INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0042311fab0a458a85c81b5a3c285120', '李实甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏连云港灌云；江苏徐州；江苏_淮安；板浦（灌云）、海属全境', '[]', '[]', '抗日战争时期', '', '伪职：伪淮海保安司令部中将司令；罪行：海州头号伪军头目，依靠青帮收编土匪散兵，伪军最多 2000 余人；配合日军扫荡海属抗日根据地，控制淮北盐场，掠夺海盐物资，镇压民众反抗。；结局：抗战胜利后被捕判刑，后获释，1979 年病死。', '[]', '2026-09-10 09:57:14.033219', '2026-09-10 09:57:14.033219', '江苏', '连云港', '灌云', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0043be9f4bfa42b08be54f3a6144d380', '赵汝扬', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西临汾；山西朔州右玉；山西朔州', '[]', '[]', '抗日战争时期', '', '管辖雁门关以北包括朔州、右玉等地，推行伪化统治，协助日军掠夺资源。；在伪山西省政权中负责教育，推行奴化教育，篡改教材，向山西包括临汾地区青少年灌输亲日思想。', '[]', '2026-09-10 09:57:14.019173', '2026-09-10 09:57:14.019173', '山西', '朔州', '右玉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('004550c960b748f6b24296c563c22e6a', '高宗武', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；安徽宣城；浙江温州乐清', '[]', '[]', '抗日战争时期', '', '浙江乐清人，参与汪伪政权初期筹建；与湖南衡阳无直接关联。；安徽宣城人，参与汪精卫投敌的“重光堂会谈”，后脱离汪伪。；浙江杭州人，参与汪日密谈，后因内部矛盾脱离，但前期为汉奸活动。', '[]', '2026-09-10 09:57:14.007939', '2026-09-10 09:57:14.007939', '安徽', '宣城', '绩溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0048f0a98ef64bd5abede9bb7b061f19', '梁少芝', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东珠海斗门；广东珠海；广东肇庆；广东珠海香洲', '[]', '[]', '抗日战争时期', '', '在珠海、斗门地区推行奴化教育，编写和散发亲日宣传材料，协助日军进行思想控制。；在香洲驻防，配合日军扫荡五桂山抗日游击队，并参与掠夺当地资源。；配合日军在高要、肇庆一带推行伪化统治，参与组织伪自卫队，搜捕抗日人员。；在高要、肇庆一带协助日军建立伪政权，参与征发民夫、物资，配合日军扫荡抗日游击队。；在高要、肇庆一带协助日军建立伪政权，参与征收苛捐杂税、诱降地方武装。', '[]', '2026-09-10 09:57:14.029996', '2026-09-10 09:57:14.029996', '广东', '珠海', '斗门', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('004b84a5c3bd41fbb5364639bae0084f', '周福海', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆北碚；象山沿海；重庆南岸', '[]', '[]', '抗日战争时期', '', '伪职：伪象山保安大队长；罪行：伪军头目，驻守石浦、丹城据点，骚扰沿海乡村，抓捕抗日爱国群众。；结局：抗战胜利后被俘处决。', '[]', '2026-09-10 09:57:14.064066', '2026-09-10 09:57:14.064066', '重庆', '北碚', NULL, NULL, NULL, NULL, NULL, '');
