INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('00717e96f46f4fbc93e41a8c66374c31', '张克俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕县', '[]', '[]', '抗日战争时期', '', '伪职：蒋军陕县县长（与日伪勾结）；罪行：国民党陕县县长。1945年从灵宝经南山潜到宫前南川，召集匪首部署向宫前解放区进攻', '[]', '2026-09-10 09:57:14.072425', '2026-09-10 09:57:14.072425', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0074316a657f458a8a099a6ff2fc89c7', '周宝臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '抚宁', '[]', '[]', '抗日战争时期', '', '伪职：伪特务系长，长城沿线密探总头目。；结局：镇反时期处决', '[]', '2026-09-10 09:57:14.067067', '2026-09-10 09:57:14.067067', '河北', '秦皇岛', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('00787e3ea3fb4328b07fe54d9576cec2', '张德良', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江林口', '[]', '[]', '抗日战争时期', '', '在林口县实施“连坐”制度，抓捕抗联家属，严刑逼供，破坏抗联地方关系网，导致数十名抗联交通员牺牲。', '[]', '2026-09-10 09:57:14.066432', '2026-09-10 09:57:14.066432', '黑龙江', '牡丹江', '林口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('007ba0dbfeb448a59807c92ae5493b97', '张伯常', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北黄石下陆；重庆沙坪坝；四川成都都江堰；湖北孝感安陆；湖北武汉；辽宁沈阳大东；湖北武汉汉南；湖北襄阳南漳；湖北孝感云梦；湖北孝感；湖北宜昌', '[]', '[]', '抗日战争时期', '', '出任伪大冶县县长，推行日伪政令，协助日军征粮、征丁，镇压抗日活动，活动范围包括下陆一带。；率伪保安团配合日军扫荡灌县周边抗日武装，镇压当地民众抗日活动。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在汉阳及武汉周边任伪职，协助日军维持占领区统治、征发民夫。；安陆与云梦接壤，张伯常在安陆组织伪维持会并任伪县长，协助日军控制鄂中北地区，与孝感、云梦伪政权联系密切。；任伪湖北省教育厅厅长，推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒化青年思想。；率伪保安大队在汉南水乡地带为日军巡逻、征粮，袭击抗日游击队。；在宜昌沦陷区担任保甲长，协助日军清查户口、征发民夫。；率伪保安队在南海、南漳一带配合日军清乡，搜捕抗日人员，勒索民众，为日军征发物资。', '[]', '2026-09-10 09:57:14.002356', '2026-09-10 09:57:14.002356', '四川', '成都', '都江堰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('007d276045344f5abbede491b21cb696', '李香亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮北濉溪；山东烟台招远；河南安阳内黄；山东济宁泗水；河南洛阳瀍河；河南洛阳', '[]', '[]', '抗日战争时期', '', '率部驻防濉溪、铁佛一带，多次进攻新四军第四师游击区，烧毁村庄，抢掠财物。；洛阳沦陷后任伪商会会长，协助日军征发物资、控制商业，为日伪经济掠夺服务。；在招远推行奴化教育，篡改教材，向学生灌输亲日思想，协助日伪文化侵略。；在伪内黄县政权中负责教育，推行奴化教育，宣传“中日亲善”，毒害当地青少年。；率伪警备队配合日军扫荡泗水南部山区，抓捕抗日人员，催缴捐税。', '[]', '2026-09-10 09:57:14.008759', '2026-09-10 09:57:14.008759', '安徽', '淮北', '濉溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('007f9d5a1c964d8481a10021c1003155', '张维玺', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林灵川；辽宁沈阳和平', '[]', '[]', '抗日战争时期', '', '原国民党军将领，1943年投敌，任伪和平建国军第三方面军副总司令等职，属山东伪军头目。', '[]', '2026-09-10 09:57:14.032415', '2026-09-10 09:57:14.032415', '广西', '桂林', '灵川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0088e8b854fd4f45b7ffe6070f67e333', '刘振汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西萍乡上栗；江西萍乡；江西萍乡安源', '[]', '[]', '抗日战争时期', '', '在日军扶植下出任伪萍乡县县长，建立伪政权机构，推行日军政令，配合日军在萍乡、上栗等地进行经济掠夺和治安强化。；日军占领安源煤矿后，出面组织维持会，强迫矿工为日军采煤，克扣矿工口粮，并向日军提供矿工中抗日嫌疑人员名单。', '[]', '2026-09-10 09:57:14.040327', '2026-09-10 09:57:14.040327', '江西', '萍乡', '上栗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('008cd046bb9543759992d03d0d7bd8f2', '阎啸风', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪翼城县县长；罪行：日军占领翼城后组建伪公署；修筑据点，征粮抓丁，配合日军扫荡翼城东部山区。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.088051', '2026-09-10 09:57:14.088051', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('008f4a52307949ceaaaf0016611acee6', '崔子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊三河；河南濮阳；山东菏泽东明', '[]', '[]', '抗日战争时期', '', '协助日军在泃河沿岸设立据点，抓捕抗日群众，严刑逼供，并参与“无人区”制造行动。', '[]', '2026-09-10 09:57:14.042365', '2026-09-10 09:57:14.042365', '河北', '廊坊', '三河', NULL, NULL, NULL, NULL, '');
