INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('00bf1008b7634693b61031292543eec4', '乐俊泉', NULL, NULL, NULL, NULL, 'exact', 'exact', '吴兴练市', '[]', '[]', '抗日战争时期', '', '伪职：练市维持会会长；罪行：沦陷初期组建练市伪维持会，懂日语，为日军征粮派夫，管控市镇商贸，搭建基层傀儡统治。；结局：抗战胜利后逮捕判刑。', '[]', '2026-09-10 09:57:14.068916', '2026-09-10 09:57:14.068916', '浙江', '湖州', NULL, NULL, NULL, NULL, NULL, '');
