INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('00c07c65e3b64027abcfa2cee04f7e41', '曲冠军', NULL, NULL, NULL, NULL, 'exact', 'exact', '临江县（今白山临江）', '[]', '[]', '抗日战争时期', '', '伪职：伪警正、山林讨伐大队长；罪行：手绘长白山详图献给日军，标注抗联密营、伤员岩洞、接济抗联群众住址；带队进山扫荡，大肆搜捕抗联人员，破坏大量密营。；结局：1946 年躲进深山岩洞，被民兵抓获，公审处决。', '[]', '2026-09-10 09:57:14.081961', '2026-09-10 09:57:14.081961', '吉林', '白山', NULL, NULL, NULL, NULL, NULL, '');
