INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('00c2dce2821a4fcc828ca057a273d740', '许志一', NULL, NULL, NULL, NULL, 'exact', 'exact', '涡阳县城', '[]', '[]', '抗日战争时期', '', '伪职：涡阳维持会会长；罪行：日军占领涡阳即出面投敌，网罗二十多名本地败类组建维持会，征夫征粮，替日军搜集乡间情报，胁迫士绅附逆。；结局：涡阳光复后公审处决。', '[]', '2026-09-10 09:57:14.081689', '2026-09-10 09:57:14.081689', '安徽', '亳州', NULL, NULL, NULL, NULL, NULL, '');
