INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('01679da514374db984e8f93b9abfbc09', '姜达权', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南商丘豫东综合物流产业聚集；河南商丘；青海黄南河南；河南开封；河南开封；河南新乡；河南开封', '[]', '[]', '抗日战争时期', '', '汪伪河南省政府官员，曾任伪豫东道尹，驻商丘，统辖豫东伪政权，推行日军政策。；任伪河南省公署省长，为日军统治河南沦陷区服务，推行伪化政策。；任伪河南省公署省长，驻开封，配合日军在河南占领区推行伪政、征粮征丁。；任伪河南省省长期间，配合日军在开封及河南占领区推行伪政权建设、治安强化运动。；伪河南省公署成立后任省长，驻开封，秉承日军意旨推行伪政，镇压抗日活动，为河南沦陷区重要附逆人物。；任伪河南省省长期间驻开封，配合日军建立伪政权体系，推行保甲连坐与物资统制。；在开封统率伪保安部队，配合日军维持治安，镇压抗日活动。；在开封主持伪河南警务，配合日军清乡、扫荡，镇压抗日群众。；掌管伪河南警务，督导包括新乡在内的各地伪警察机构镇压抗日活动。；在开封主持伪警务，推行保甲连坐，镇压河南抗日活动。；任伪开封市警察局长，配合日军搜捕抗日人员。', '[]', '2026-09-10 09:57:14.045647', '2026-09-10 09:57:14.045647', '河南', '商丘', '豫东综合物流产业聚集', NULL, NULL, NULL, NULL, '');
