INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('020817c4a0c9462ab66a6ec893efb5f0', '乌尔金', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；黑龙江大兴安岭松岭；内蒙古呼伦贝尔；北京大兴；黑龙江齐齐哈尔；蒙古族；内蒙古呼伦贝尔；天津河西；黑龙江大兴安岭呼中；北京大兴；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[\"蒙古族\"]', '[]', '抗日战争时期', '', '指挥伪兴安军配合日军“讨伐”抗日武装，在呼伦贝尔地区制造多起屠杀事件，强征牧民入伍。；在呼伦贝尔西部活动，协助日军建立军事据点，迫害牧民；伪职：伪兴安北警备军少将司令；统率伪蒙古骑兵，布防呼伦贝尔草原边境，搜缴民间武器，镇压边境牧民众反抗。；结局：1945 被苏军俘虏，后关押改造', '[]', '2026-09-10 09:57:13.988190', '2026-09-10 09:57:13.988190', '内蒙古', '呼伦贝尔', '扎兰屯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('020ab8c0a2954804b0f097d8e0db5d36', '张燕卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳新民；北京石景山；吉林长春南关；河北南皮（张之洞之子，长期在吉林任职）；吉林_永吉；吉林_长春_九台；吉林长春；吉林；辽宁_大连_长海；辽宁_沈阳_浑南；甘肃甘南合作；黑龙江_哈尔滨_松北；辽宁沈阳和平；辽宁沈阳大东；辽宁_辽阳_灯塔；河北南皮（张之洞之子）；吉林长春双阳；吉林长春；吉林船营；辽宁沈阳沈北；辽宁沈阳；吉林长春宽城；吉林长春；河北承德平泉；河北承德；吉林长春绿园；吉林长春；山东聊城；辽宁大连旅顺口；山东烟台；辽宁沈阳新民；吉林；吉林长春；吉林白山；吉林；河北秦皇岛秦皇岛经开区；河北秦皇岛；云南昆明呈贡；山东聊城；辽宁_沈阳_苏家屯；黑龙江哈尔滨松北；黑龙江齐齐哈尔；北京、吉林、河北、辽宁；天津河北；吉林长春公主岭；辽宁沈阳；吉林长春长春高；吉林长春；武汉（伪武汉市政府）；吉林；重庆永川；辽宁沈阳新民；云南普洱西', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪吉林省实业厅厅长、伪满外交部大臣，熙洽重要助手。结局：1945 年逃亡日本，滞留海外，未受审判；伪职：伪冀东防共自治政府要员（关联）；罪行：张之洞第十一子；张仁蠡之兄；日军曾邀其任伪武汉市长，其荐弟张仁蠡代之；在北平推行奴化教育，修改教科书，鼓吹“中日亲善”，压制师生抗日思想。；在北平推行奴化教育，其管辖学校包括石景山地区的小学和中学，强制推行日语教学和“中日亲善”宣传。；协助日本掠夺吉林森林、矿产等资源，组织劳工为日军服务。；推行奴化教育，强制学校教授日语，篡改历史，灌输“日满亲善”思想。；代表伪满与日本签订不平等条约，出卖东北权益，间接影响船营地区资源控制。……（共涉及31个地区的犯罪记录）；伪职：伪吉林省实业厅厅长；罪行：投靠熙洽，接管吉林工矿，配合日本掠夺矿产资源，参与伪满建国。；结局：日本投降后被捕，关押北平监狱，1951 年病死狱中。', '[]', '2026-09-10 09:57:13.982792', '2026-09-10 09:57:13.982792', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('020b563b440941b5838cc0773fd46643', '刘汉民', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；湖北襄阳谷城；湖北襄阳樊城；湖北襄阳；湖北襄阳', '[]', '[]', '抗日战争时期', '', '率伪保安大队配合日军对谷城及周边地区进行扫荡，搜捕抗日人员，强征民夫修筑据点。；抗战期间在襄阳地区投敌，组织伪维持会，后任伪襄阳县县长，协助日军维持占领区秩序、征发物资与劳工。；日军侵占襄阳后出面组织伪维持会，后任伪襄阳县县长，为日军征粮派款、维持地方伪秩序。；率伪军配合日军清乡，搜捕抗日军民，抢掠百姓。；襄阳沦陷后组织维持会，任会长，为日军筹集物资、维持地方秩序，协助建立伪政权。', '[]', '2026-09-10 09:57:14.057118', '2026-09-10 09:57:14.057118', '湖北', '襄阳', '樊城', NULL, NULL, NULL, NULL, '');
