INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('024f3b31895a4418983c41819de49e08', '陈恭澍', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京；陕西西安；天津河北；浙江宁波余姚；浙江宁波；浙江宁波；浙江舟山岱山；浙江_舟山_嵊泗；浙江_舟山_普陀；浙江金华；上海杨浦', '[]', '[]', '抗日战争时期', '', '为日军宪兵队充当翻译，参与审讯酷刑，指认抗日分子，导致多名地下党员牺牲。；投靠汪精卫政权，在浙江地区协助日伪镇压抗日活动，破坏地下组织。；投靠汪精卫政权，在浙江协助日伪镇压抗日力量，破坏地下抗日组织。；在浙江任职期间，协助日伪镇压抗日力量，破坏地下抗日组织，推行“清乡”政策。；在金华、兰溪等地协助日军清乡，镇压抗日力量，搜捕军统地下人员。；曾在宁波地区指挥特工行动，协助日军镇压抗日力量。；原军统人员叛变后，在杨浦地区协助日伪抓捕旧同事。；投敌后任伪特工总部处长，进行特务活动。；河北人，原军统人员，被捕后投敌，任汪伪特工总部杭州区负责人，活动于浙江金华、杭州等地，抗战后被捕。；负责南京特务工作，逮捕抗日地下人员', '[]', '2026-09-10 09:57:13.978290', '2026-09-10 09:57:13.978290', '上海', '杨浦', '余姚', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0250cd58855f4c92942d843aae659ee9', '陈次溥', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_杭州_余杭；安徽安庆怀宁；安徽安庆；浙江绍兴嵊州', '[]', '[]', '抗日战争时期', '', '浙江嵊县人，抗战期间投敌，日军占领嵊县后组织伪维持会并任会长，后任伪嵊县长，协助日军征粮征丁、维持地方伪化统治。；汪伪政权在安庆地区推行清乡运动时的重要执行者，负责组织伪军警配合日军扫荡抗日武装，在怀宁、桐城、潜山交界地区实施保甲连坐与物资封锁。；汪伪政权任命，任内配合日军进行物资统制，强征粮食，镇压学生和市民的抗日活动。', '[]', '2026-09-10 09:57:14.007659', '2026-09-10 09:57:14.007659', '安徽', '安庆', '怀宁', NULL, NULL, NULL, NULL, '');
