INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('038943dc63194adb9b2fae51b7dbca65', '顾祝三', NULL, NULL, NULL, NULL, 'exact', 'exact', '赣榆全县', '[]', '[]', '抗日战争时期', '', '伪职：伪赣榆县县长；罪行：执掌赣榆伪政权，执行日伪清乡、抓丁征粮，出动伪县大队配合日军扫荡滨海抗日根据地。；结局：抗战胜利后汉奸罪判刑。', '[]', '2026-09-10 09:57:14.075401', '2026-09-10 09:57:14.075401', '江苏', '连云港', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('03aae207b6b84f05bb312e09195cbc4f', '梁鸿志', '众异', NULL, 1882, 1946, 'exact', 'exact', '安徽_滁州_苏滁现代产业园；浙江杭州；广西_柳州；福建福州长乐；四川成都；四川_成都_金牛；江苏南京；安徽_宣城_郎溪；安徽滁州；山东青岛；甘肃甘南合作；云南普洱西；广西桂林；江西九江；四川南充南部；浙江舟山；湖南永州；重庆万州；重庆_合川；重庆沙坪坝；陕西_西安_长安；福建长乐；江苏南京；福建福州长乐；江苏南京；福建福州长乐；云南普洱西；福建福州长乐；安徽_淮北_杜集；安徽芜湖；广西柳州柳南；广西柳州；云南普洱西；陕西西安；江苏南京；云南昆明呈贡；江苏南京；山东聊城；山东_青岛_城阳；山东青岛；山东_青岛_莱西；四川南充南部；湖北_咸宁_通山；湖北黄冈；贵州贵阳；陕西宝鸡；陕西渭南；安徽安庆；安徽芜湖；江苏南京；浙江宁波；河北秦皇岛海港；上海杨浦', '[]', '[]', '抗日战争时期', '汪伪政权；南京伪维新政府 / 汪伪政权', '梁鸿志，字众异，福建长乐人。晚清巨儒梁章钜曾孙。1905年入京师大学堂。北洋时期任段祺瑞执政府秘书长。1938年3月在日本扶植下于南京成立「中华民国维新政府」，任行政院长。1940年并入汪伪，任监察院长、立法院长。1946年5月以汉奸罪被判死刑，11月9日在上海提篮桥监狱被执行枪决。；伪任职务：原伪维新政府行政院长；汪伪监察院院长、立法院长，伪维新政府首要头目，前期统治南京环球网。。结局：1946 年上海枪决', '[]', '2026-09-10 09:57:13.977520', '2026-09-10 09:57:13.977520', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('03aeef222f454af69349044fc341ad3c', '刘海臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '栖霞县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：亲手杀害抗日军民10人、主使杀害35人；结局：1946年1月7日被栖霞、栖东县6000余人公审', '[]', '2026-09-10 09:57:14.086939', '2026-09-10 09:57:14.086939', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
