INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('04d342388939467e853acfb1b2f90b07', '李荫南', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关；甘肃甘南合作；广东肇庆高要；广东肇庆；广东佛山；广东广州从化；广东广州天河；广东广州；广东江门恩平；广东江门；广东广州番禺；广东广州；广东广州；河南郑州中牟；广东惠州；广西桂林恭城；广西桂林；广东韶关南雄；广东清远；广东广州；河北保定雄县；广东韶关曲江；广东_云浮_郁南；广东韶关仁化；广东韶关；广东广州黄埔；广东广州', '[]', '[]', '抗日战争时期', '', '广州沦陷后出面组织伪商会，为日军筹款、摊派物资，协助经济统制。；在广州伪警察系统中任职，参与治安镇压和情报搜集，为日军统治服务。；南雄沦陷前后出面组织维持会，为日军筹粮、带路、宣传“中日亲善”，是南雄地区有记载的附逆者。；桂林沦陷期间，组织伪维持会，协助日军维持治安、征发物资。；率伪军驻防佛山、南海，多次配合日军进攻西海抗日根据地，杀害抗日军民。；广州商界附逆代表人物，协助日军实施物资统制、配给与掠夺，从中牟利。；统率伪军在西江流域包括肇庆、高要一带活动，配合日军扫荡抗日游击队，残害百姓。；广州沦陷初期协助日军组织维持会，参与经济掠夺与物资统制。；利用伪合作社系统掠夺农产品，配合日军经济封锁。；汪伪政权在南雄县的代理人，为日军征调物资，镇压当地抗日活动，与韶关地区抗日力量为敌。；曲江伪教育科科长，推行奴化教育，宣传亲日思想。；汪伪政权委任的从化县县长，在从化地区推行伪政，配合日军扫荡与清乡。；曲江（今韶关市区）伪政权头目，配合日军在韶关地区的统治，组织伪保安队，搜捕抗日分子，征收苛捐杂税。；在汪伪广东省政府任职，推行奴化教育，篡改教材，向包括清远、连州在内的广东各地学校灌输亲日思想。；惠州周边博罗地区伪维持会头目，为日军征粮派夫，协助日军控制博罗一带。；协助江门维持会会长为日军筹粮派夫，维持江门及恩平周边伪秩序。；广州沦陷初期出面组织伪广州维持会，任会长，协助日军维持占领秩序，为早期广州伪政权代表人物。；任伪广东教育厅长，推行奴化教育，篡改教材，灌输亲日思想。；汪伪时期在广州伪市政府财政系统任职，为日伪筹措经费。', '[]', '2026-09-10 09:57:14.025454', '2026-09-10 09:57:14.025454', '广东', '广州', '从化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('04d6e5b16f27478789c699014cdecf20', '陈镜波', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东清远连南；辽宁沈阳大东；广东深圳盐田；辽宁沈阳大东；广东广州荔湾；广东广州；云南普洱西；广东佛山三水；广东肇庆鼎湖；广东清远阳山；辽宁沈阳大东；广东清远；广东珠海香洲；广东珠海；广东清远；广东清远清城', '[]', '[]', '抗日战争时期', '', '管辖珠海、香洲一带伪政权，推行日军政策，征发劳工修建军事工事，镇压抗日活动。；在鼎湖坑口、沙浦一带充任伪保甲长，监视村民，举报抗日家属，协助日军征夫。；在清远推行奴化教育，篡改教材，宣传“大东亚共荣”，强迫学校师生参加亲日活动，为伪政权培养顺民。；在清远沦陷区充任伪警察头目，带领伪警察配合日军搜捕抗日人员，勒索民众，维持伪政权治安，活动范围覆盖清远南部及佛冈边缘地带。；在清城地区担任伪警察头目，配合日军搜捕抗日人士，镇压民众反抗，推行保甲连坐制度，为日伪政权维持地方治安。；在清远沦陷区充任伪警察头目，协助日军搜捕抗日人士，镇压民众反抗，维护伪政权治安。；协助李辅群组织维持会，为日军筹款筹粮，诱迫乡民归顺。；在广州荔湾及周边地区组织伪自卫团，配合日伪行动。；在清远推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青少年。；在三水、肇庆交界地区组织伪维持会，配合日军封锁西江，搜捕抗日人员。；在伪广东省教育厅任职，推行奴化教育，宣传“大东亚共荣圈”，其教育政策覆盖包括深圳、盐田在内的广东沦陷区。', '[]', '2026-09-10 09:57:14.027070', '2026-09-10 09:57:14.027070', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('04de753462f6492bb4543010d151f08e', '李福和', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南安阳滑县；河南安阳；四川南充南部；山东菏泽；河南商丘；河南安阳；河南平顶山；河南_开封_杞县；青海黄南河南；福建泉州南安；河南漯河；河南濮阳；黑龙江黑河北安；河南_许昌_许昌经开区；河南许昌；河南郑州；陕西宝鸡；安阳；河南南阳新野；河南南阳；内蒙古赤峰；山西、河北；山东菏泽菏泽经开区；山东菏泽；广西_桂林_灵川；河北石家庄井陉；河北衡水武邑；河北衡水；河北邯郸；河北邯郸涉县；河南许昌建安；河南许昌；山西晋中；河北邯郸邯郸冀南；河南；河北邯郸临漳；河北邯郸成安；河北衡水安平；河北衡水；河北邯郸复兴；河北邯郸；河北邯郸武安；河北邯郸', '[]', '[]', '抗日战争时期', '伪军', '率部在晋中、左权边缘地区骚扰，配合日军抢粮，杀害抗日群众。；原为东北军军官，后投靠日军，在冀中地区协助日军清剿抗日武装，1938年因内部矛盾被处决。；率伪军在井陉、平山一带配合日军进攻八路军，屠杀抗日群众，后因内讧被日军处决。；原国民党军官，投日后在冀东及石家庄周边组织伪军，参与对正太铁路沿线抗日游击队的围剿，后因内讧被日军处决。；组织伪剿共军，专门搜捕抗日地下党员，在安平、衡水交界处设立集中营，残害抗日志士。……（共涉及23个地区的犯罪记录）；伪任职务：皇协军第一路军军长，抗战早期投敌，驻防安阳水冶，进攻太行根据地。结局：1938 年部下起义，曲沟事变中将其就地击毙；伪职：皇协军第一路军军长；罪行：原国民党游击司令，1937年底叛变投日，是抗战初期最早投敌的国军高级将领之一；驻防安阳西部水冶一带；收拢溃散武装数千人，配合日军进攻太行山抗日根据地；结局：1938年8月7日，部下黄宇宙、徐靖远发动曲沟事变，将其当场击毙', '[]', '2026-09-10 09:57:13.990912', '2026-09-10 09:57:13.990912', '山东', '菏泽', '菏泽经开区', NULL, NULL, NULL, NULL, '');
