INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('058aa30173c14f8fb42feadb058c33ef', '陈子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾大宁；山西运城临猗；山西运城盐湖；河南郑州中牟；山西忻州原平；山西阳泉；山西运城垣曲；山西、河北；河北邢台威县；山西大同阳高', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，迫害爱国教师。；多次带队袭击抗日游击队，在崞县（今原平）一带制造“无人区”，杀害无辜百姓。；随日军宣抚班到临猗各村演讲，诱骗百姓归顺，并收集地方武装情报，导致多支抗日小分队遭伏击。；推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，并告发多名爱国教师，致其被捕或失踪。；为日军筹措军饷，控制盐业贸易，强迫商户向日军献金，从中牟利，并告发抗日商人。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018879', '2026-09-10 09:57:14.018879', '山西', '临汾', '大宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('058cb7aa8d9f424c8fa70168e7c5b85a', '林思进', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都青羊', '[]', '[]', '抗日战争时期', '', '日伪曾试图拉拢其参与维持会教育事务，但林思进拒绝，此处仅记录日伪联络名单。', '[]', '2026-09-10 09:57:14.002459', '2026-09-10 09:57:14.002459', '四川', '成都', '青羊', NULL, NULL, NULL, NULL, '');
