INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0599d730b8204f41a42d834b8c9e4519', '张天佐', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊昌乐；山东潍坊；山东潍坊寒亭；山东潍坊昌乐；山东淄博；潍县；山东潍坊；山东潍坊临朐；山东潍坊；山东_淄博_淄川；山东潍坊昌乐', '[]', '[]', '抗日战争时期', '', '伪职：国民党第八区专员（与日伪勾结）；罪行：虽非日伪任命，但1943年派二营长张震寰以五团长的身份投降日军，以“曲线救国”为由开脱。所部多为替日本人卖命的汉奸。在潍坊地区横行多年，杀害共产党人无数；结局：1948年潍县战役中被解放军击毙', '[]', '2026-09-10 09:57:14.015929', '2026-09-10 09:57:14.015929', '山东', '潍坊', '临朐', NULL, NULL, NULL, NULL, '');
