INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('05a89e1301bd4c9189feac91d2f2867e', '崔效骞', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西大同', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪晋北政厅厅长，伪蒙疆体系雁北高官，管理大同工矿掠夺。结局：抗战后被捕，公审处决', '[]', '2026-09-10 09:57:14.076697', '2026-09-10 09:57:14.076697', '山西', '大同', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('05a93372d51b4cc396e3696cb83d2355', '张庆余', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北唐山开平；江苏南通通州；河北唐山滦州；江苏南通通州；河北秦皇岛山海关；河北秦皇岛；河北唐山唐山海港经开区；江苏南通通州；河北唐山唐山芦台经开区；江苏南通通州；河北秦皇岛抚宁；河北秦皇岛；河北唐山唐山高；江苏南通通州；河北唐山迁安；江苏南通通州；河北唐山曹妃甸；江苏南通通州；安徽马鞍山含山；河北秦皇岛；江苏南通通州；河北秦皇岛昌黎；河北秦皇岛；天津河北；河北廊坊三河；江苏南通通州；北京平谷；安徽马鞍山；安徽马鞍山和县；陕西西安长安；北京、天津、河北；江苏扬州；河北唐山；江苏南通通州；北京通州；江苏南通通州；河北唐山丰润；江苏南通通州；河北沧州沧州经开区；北京密云', '[]', '[]', '抗日战争时期', '', '初期为殷汝耕效力，在密云镇压抗日活动，后反正但影响有限。；在密云地区协助日军维持治安，镇压抗日活动，参与冀东伪政权的军事行动。；1935年参与殷汝耕成立的伪冀东防共自治政府，驻防平谷、密云一带，协助日军维持治安，镇压抗日活动。1938年反正后投靠国民党，但此前已造成抗日力量损失。；原为冀东伪军头目，1937年7月通州事变中率部反正，杀死日军和汉奸，但此前曾为伪政权效力。；初期为殷汝耕效力，但1937年7月29日率部发动通州起义，杀死日军和汉奸数百人，后反正抗日，故其前期行为属被迫附逆。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.993611', '2026-09-10 09:57:13.993611', '北京', '密云', '含山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('05ba43bf4aad4ee19b677bcb9d5b8c95', '戴吾愆', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（经济汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：经济汉奸；罪行：经济汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.069255', '2026-09-10 09:57:14.069255', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('05c01ac5e8be4daba45485dd964e2750', '汪伪浙江省政府委员——周佛海', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波', '[\"兼\"]', '[]', '抗日战争时期', '', '作为汪伪核心人物，虽未常驻浙江，但通过伪省府控制浙江包括宁波的行政与财政。', '[]', '2026-09-10 09:57:14.050789', '2026-09-10 09:57:14.050789', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
