INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('05ca5b4d09284b39ac230d27e96746bd', '张德纯', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯；黑龙江佳木斯富锦；江苏南通南通经开区；黑龙江哈尔滨道外', '[]', '[]', '抗日战争时期', '', '积极宣传“日满亲善”，组织“协和义勇奉公队”，协助日军收集情报，煽动民众告发抗日分子。；为日军搜集新四军情报，导致多起抗日据点被破坏，多名地下党员被捕牺牲。；组织地方自卫团，协助日军封锁抗联交通线，在富锦北部山区多次伏击抗联小分队。；在道外区设立检查哨，搜捕抗联交通员，多次带队突袭民宅，没收抗日物资。', '[]', '2026-09-10 09:57:14.034121', '2026-09-10 09:57:14.034121', '江苏', '南通', '南通经开区', NULL, NULL, NULL, NULL, '');
