INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07b18f9baffa4b0a920d597a8134bb99', '李仲平', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '广西北海；河北；广东云浮；重庆云阳', '[]', '[]', '抗日战争时期', '', '投靠日军，任曲阳县伪政权首脑，协助日军推行‘治安强化运动’，强征民夫修筑炮楼据点，镇压抗日群众。；日军占领望都后，率先组织维持会，为日军提供粮秣、民夫情报，协助建立伪政权，并参与诱降抗日分子，破坏当地地下党组织。；投靠日军，任涞水县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。；伪职：首任伪大名县知事；主持修建五十余处碉堡，封锁卫河沿岸根据地。；结局：抗战胜利逮捕，判处无期徒刑', '[]', '2026-09-10 09:57:14.024733', '2026-09-10 09:57:14.024733', '广东', '云浮', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07b2e07140f248978ffaf3bb9b6b5d9a', '林福生', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江丽水云和', '[]', '[]', '抗日战争时期', '', '协助日军进行奴化宣传，散布“中日亲善”言论，诱骗青年参加伪军，破坏抗日宣传。', '[]', '2026-09-10 09:57:14.049364', '2026-09-10 09:57:14.049364', '浙江', '丽水', '云和', NULL, NULL, NULL, NULL, '');
