INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07dc88e575a54c94a2925b7d2d38faff', '王伯龄', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京栖霞；江苏常州溧阳；江苏南京溧水；江苏无锡江阴；江苏苏州常熟；江苏苏州昆山；江苏苏州', '[]', '[]', '抗日战争时期', '', '苏州沦陷后率先投敌，组织维持会，为日军筹粮派夫，协助稳定占领秩序。；江阴沦陷后投敌，任维持会长，为日军征粮派款，强拉壮丁，镇压抗日武装。；率领伪保安队配合日军扫荡溧水山区，杀害新四军伤员和群众。；日军占领常熟后组织维持会，为日军提供粮食和情报，协助建立伪政权。；在栖霞地区组织伪联防队，配合日军扫荡，抢劫百姓财物；率伪保安队参与对溧阳山区抗日根据地的进攻，烧毁村庄，抢劫民财。', '[]', '2026-09-10 09:57:14.033589', '2026-09-10 09:57:14.033589', '江苏', '南京', '栖霞', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07df7b74d9a7463dbf613082d9850366', '于品卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古巴彦淖尔；河北张家口；陕西_西安；河北南宫；内蒙古乌兰察布察哈尔右翼中旗；吉林高；云南普洱西；四川南充南部；广西桂林资源；河北张家口；内蒙古呼和浩特和林格尔；内蒙古呼和浩特；内蒙古呼伦贝尔牙克石；内蒙古包头达尔罕茂明安；内蒙古包头；内蒙古赤峰巴林左旗；河北张家口；内蒙古鄂尔多斯；天津河北；重庆沙坪坝；陕西榆林；河北张家口；河北；河北张家口蔚县；河北张家口；内蒙古锡林郭勒正蓝旗；四川南充南部；河北冀州；蔚县；河北张家口；河北_张家口_涿鹿', '[]', '[]', '抗日战争时期', '汪伪政权', '原张家口商会会长，日军占领后出任伪市长，为日军征粮派款，镇压抗日活动，协助维持殖民秩序。；原为张家口商会会长，日军占领后出任伪市长，积极组织维持会，为日军筹措军费，强征民夫修建军事设施，并参与伪蒙疆政府的物资掠夺政策。；原为张家口商会会长，投日后任伪张家口市长，为日军筹集物资，协助建立保甲制度，镇压抗日活动。；投靠日军，历任伪职，在张家口、下花园一带推行保甲制度，协助日军清乡，迫害抗日军民。；原为张家口商会头目，投日后任伪市长，为日军推行保甲制度，强征劳工，在下花园矿区压榨矿工，提供煤炭资源给日军。……（共涉及25个地区的犯罪记录）；伪职：伪察南自治政府主席，伪蒙疆联合自治政府副主席；张家口头号大汉奸，率士绅出城迎接日军，组建维持会，推行保甲、征粮抓丁，掠夺物资，镇压察南抗日运动。；结局：1945??12??24 晋察冀特别法庭公审，汉卿桥执行死刑今日头条；伪职：伪蒙疆联合自治政府副主席，常驻大同、张家口；罪行：统筹蒙疆下属察南、晋北，参与分裂傀儡政权，督导晋北伪政务。；结局：1945 张家口公审枪决；伪任职务：伪蒙疆联合自治政府副主席，张家口伪政权核心，主管经济搜刮物资。结局：1945 年张家口解放，晋察冀边区公审，执行死刑', '[]', '2026-09-10 09:57:13.987200', '2026-09-10 09:57:13.987200', '内蒙古', '乌兰察布', '察哈尔右翼中旗', NULL, NULL, NULL, NULL, '');
