INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07e1730768154308a04600e3c519f222', '金井章二', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西吕梁石楼；山西吕梁；山西临汾古县；山西临汾；陕西西安长安；云南普洱西', '[]', '[]', '抗日战争时期', '', '日本特务，操控伪蒙政权，其活动区域与陕西北部邻近。；日本特务，任伪山西省公署顾问，实际控制伪政权，在临汾等地督导日军政策实施，参与镇压抗日。；作为日军派驻伪山西省的最高顾问，实际控制伪政权，在吕梁地区推行殖民统治，指挥伪军伪警镇压抗日活动。', '[]', '2026-09-10 09:57:14.018750', '2026-09-10 09:57:14.018750', '山西', '临汾', '古县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07e3cf48a04944a3bbff6289f469359e', '孙兆铭', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏镇江扬中；江苏镇江', '[]', '[]', '抗日战争时期', '', '在镇江、扬中一带推行“清乡”政策，建立伪基层政权，强征捐税，参与围剿新四军游击队。', '[]', '2026-09-10 09:57:14.037029', '2026-09-10 09:57:14.037029', '江苏', '镇江', '扬中', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07ed1e7852bc43b8b73f1b486e328b51', '任凤昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖老城区；安徽芜湖', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪芜湖维持会头目、伪芜湖商会，为日军搜刮物资，残害百姓。结局：1951 年芜湖公审枪决；伪职：芜湖维持会首任会长；罪行：引狼入室，带日军从竹丝港开进芜湖，制造城内大屠杀；组建最早伪维持会，搜刮财物，强征粮草资敌。；结局：解放后公审镇压处决。', '[]', '2026-09-10 09:57:14.071359', '2026-09-10 09:57:14.071359', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('07edae52befe4d1eb664098ad8e0270c', '刘子干', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁孝义；山西吕梁；山西朔州；山西朔州平鲁；山西朔州怀仁；山西朔州平鲁；山西忻州五台山风景区；山西临汾翼城；山西忻州原平；山西大同左云；山西忻州；山西忻州五台；山西、河北', '[]', '[]', '抗日战争时期', '', '在翼城县建立伪警察体系，严查抗日嫌疑，刑讯逼供，破坏中共地下交通线。；在吕梁山区多个村镇建立维持会，为日军摊派粮款，强迫百姓领取“良民证”，并告密导致多名地下党员被捕牺牲。；日军占领左云后率先组织维持会，为日军筹粮派款，提供抗日人员名单，导致多名地下党员被捕牺牲。；在五台山地区为日军带路，搜捕抗日干部，强迫民众“归顺”日伪。；为日军征收粮食和壮丁，强迫青壮年充当伪军，并告密导致多名抗日人员被捕。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019333', '2026-09-10 09:57:14.019333', '山西', '吕梁', '孝义', NULL, NULL, NULL, NULL, '');
