INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08951474901745f993275495f676d2c8', '刘湘云', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都都江堰；辽宁沈阳大东；重庆九龙坡；四川成都双流；四川成都金堂', '[]', '[]', '抗日战争时期', '', '在双流县组织伪维持会，为日军征粮派款，协助建立伪保甲制度，迫害抗日家属。；在九龙坡地区协助日军管理码头和物资运输，参与镇压抗日活动。；金堂县人，抗战期间投靠日军，任伪金堂县维持会会长，协助日军征粮、征丁，维持地方伪秩序。；在伪政权下主持成都教育会，推行奴化教育，篡改教材，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.001920', '2026-09-10 09:57:14.001920', '四川', '成都', '双流', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08ab482685d84974b0b0feadc2048a7a', '蓝文蔚', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌伍家岗；湖北宜昌', '[]', '[]', '抗日战争时期', '', '日军占领宜昌后出面组织伪维持会，后任伪宜昌县县长，协助日军推行保甲、征发劳役、搜刮物资，维持沦陷区殖民统治。；日军侵占宜昌后出面组织伪维持会，后任伪宜昌县县长，协助日军推行殖民统治、征发民夫与物资。；日军侵占宜昌后出面组织伪宜昌县维持会，后任伪宜昌县县长，协助日军推行殖民统治、征发民夫与物资。', '[]', '2026-09-10 09:57:14.056247', '2026-09-10 09:57:14.056247', '湖北', '宜昌', '伍家岗', NULL, NULL, NULL, NULL, '');
