INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08b6bbfbdccd4e0796347416352d3995', '席子遒', NULL, NULL, NULL, NULL, 'exact', 'exact', '禹县（今禹州）', '[]', '[]', '抗日战争时期', '', '伪职：原国民党禹县县长→禹县日伪维持会长、保安团长；罪行：原国民党禹县县长，日寇侵占禹县后摇身一变投靠日本人，任维持会长、保安团长，手下有近3000匪兵，死心塌地效忠日军。盘踞禹县，纠集禹、襄、郏、临汝等县土匪，企图摧毁抗日根据地', '[]', '2026-09-10 09:57:14.075567', '2026-09-10 09:57:14.075567', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08b8de099e33446eb001b5cc7b0d5727', '赵仲英', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴诸暨', '[]', '[]', '抗日战争时期', '', '日军占领诸暨初期，组织维持会，协助日军建立统治秩序。', '[]', '2026-09-10 09:57:14.052028', '2026-09-10 09:57:14.052028', '浙江', '绍兴', '诸暨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08bc9a306ad64556a2a3fa8bf1e369e2', '周伯勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北鄂州梁子湖；湖北咸宁赤壁；辽宁沈阳大东；湖北鄂州鄂城；湖北武汉；湖北孝感；湖北黄石下陆；湖北黄石；湖北恩施鹤峰；辽宁沈阳大东；湖北武汉江岸；湖北鄂州；湖北黄石西塞山；湖北黄石黄石港；湖北随州；湖北随州随县', '[]', '[]', '抗日战争时期', '', '在恩施推行奴化教育，篡改教材，强迫学生学日语，宣传“大东亚共荣”。；在鄂东地区推行伪政，协调鄂城、大冶、武昌等县伪政权，为日军掠夺梁子湖周边资源提供行政支持。；率地方武装投敌，任伪自卫团团长，在随县北部配合日军进攻抗日游击区。；协助日军控制鄂城商业与物资流通，为日军采购军需，压榨商户。；在鄂东地区组织伪军，配合日军进攻大冶、阳新抗日根据地，活动范围覆盖黄石地区。；任伪汉口市商会会长，协助日军统制经济，强迫商民纳捐。；在咸宁推行奴化教育，编写伪教材，宣扬“大东亚共荣”，毒害青少年。；在葛店地区组织维持会，为日军提供船只、民夫，协助控制长江沿岸。；任伪孝感县维持会会长，控制孝感地区基层，为日军提供情报，抓捕抗日人员。；黄石港商会会长，抗战期间与日军合作，为日军采购军需物资，协助日军对黄石港经济进行统制，压迫当地商户。；黄石港商会头目，抗战期间附逆，协助日军征购物资、控制商业，为日军在黄石地区的经济掠夺服务。', '[]', '2026-09-10 09:57:14.055291', '2026-09-10 09:57:14.055291', '湖北', '咸宁', '赤壁', NULL, NULL, NULL, NULL, '');
