INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('08f133f150334b6bbcb254d284303967', '郭化民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸邯郸经开区；河北邯郸；邯郸贾村', '[]', '[]', '抗日战争时期', '', '伪职：伪军司令，郭采芹侄子；掌握邯郸主力伪军，盘踞邯郸城、黄粱梦、户村、河沙镇各据点，多次进山扫荡紫山、邯郸西部游击区，破坏地下交通线。；结局：邯郸城破潜逃北平，1950 抓捕押回邯郸枪决；率特务队专门刺探八路军情报，抓捕抗日积极分子，在邯郸城内实施白色恐怖，严刑拷打被捕人员。；伪职：伪军司令，郭采芹侄子；掌握邯郸主力伪军，盘踞城乡据点，扫荡紫山游击区，破坏地下交通线。；结局：潜逃北平，1950 抓捕押回邯郸枪决', '[]', '2026-09-10 09:57:14.045431', '2026-09-10 09:57:14.045431', '河北', '邯郸', '邯郸经开区', NULL, NULL, NULL, NULL, '');
