INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09181045f4944397ae9d975c92503457', '郑孝胥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '云南昆明呈贡；广西_桂林_七星；广西_桂林_永福；辽宁营口大石桥；重庆_大足；黑龙江齐齐哈尔；黑龙江_大庆_龙凤；吉林长春长春高；吉林长春；吉林四平；吉林；吉林长春绿园；吉林长春；辽宁_大连_西岗；吉林长春农安；吉林长春；吉林、辽宁；福建闽侯；吉林长春德惠；吉林长春', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪满首任国务总理大臣；罪行：起草《日满议定书》，出卖东北主权，构建伪满傀儡体制，推行殖民统治。；结局：1938 年病死于长春中国社会科...。；原清朝遗老，伪满首任总理，在四平、吉林等地推行奴化教育，协助日本殖民统治。；在长春主持伪满初期国务，签订卖国条约，承认日本在东北的特权。；在长春主持伪满政府，协助溥仪登基，推行奴化政策。；在长春（新京）任伪满首任总理，签订卖国条约，协助日本建立殖民统治体系。；原清朝遗臣，投日后任伪满首任国务总理，在长春签署多项卖国条约，协助日本建立伪满政权。……（共涉及7个地区的犯罪记录）；伪任职务：伪满国务总理大臣，伪满开国，常驻长春，管辖黑龙江在内东北全境。结局：1938 年暴病死于长春，逃脱审判', '[]', '2026-09-10 09:57:13.981814', '2026-09-10 09:57:13.981814', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('091df73dded34b759177c5a8030368ad', '陈玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北_张家口_康保；河北；河北邢台临西；江苏连云港连云港经开区', '[]', '[]', '抗日战争时期', '', '为日军搜集情报，逮捕抗日地下工作者，严刑逼供，破坏抗日组织。；为日军筹粮派款，提供抗日武装活动情报，导致多个村庄被烧杀。', '[]', '2026-09-10 09:57:14.036827', '2026-09-10 09:57:14.036827', '江苏', '连云港', '连云港经开区', NULL, NULL, NULL, NULL, '');
