INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09a2827c7d89494abd14907f7696465c', '傅春生', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州开化；浙江台州路桥', '[]', '[]', '抗日战争时期', '', '路桥沦陷期间出面组织伪维持会，任会长，为日军派粮派款、维持市面，并协助日伪建立基层伪政权，是路桥当地直接附逆的代表人物。；日军侵占开化期间出面组织伪维持会，为日军筹粮、派夫、带路，协助维持占领秩序。', '[]', '2026-09-10 09:57:14.050213', '2026-09-10 09:57:14.050213', '浙江', '台州', '路桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09b15dd03c1648d2bc663d1138ff4fb8', '徐宝田', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南通海安；安徽合肥肥东；浙江温州洞头；浙江台州黄岩；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '协助维持会长为日军征粮派款，欺压乡民。；在洞头推行伪政权统治，强征壮丁，组织伪自卫团，配合日军清剿海岛游击队。；推行奴化教育，强迫学校使用日伪教材，宣传“大东亚共荣”。；在肥东地区任伪区长，协助日军“清乡”，强征壮丁，残害抗日家属。', '[]', '2026-09-10 09:57:14.006097', '2026-09-10 09:57:14.006097', '安徽', '合肥', '肥东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09bd8602bde445f9bd284e69687e4d42', '古鼎华', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州北湖；湖南长沙宁乡；湖南长沙；湖南长沙', '[]', '[]', '抗日战争时期', '', '汪伪政权在华南的军事头目之一，其伪军活动与湘南、粤北交界地区有交叉。；广东人，汪伪政权任命其为伪湖南省主席，因日军未能完全控制湖南而未实际到任，但伪政权体系对长沙、宁乡地区有名义上的管辖。；率伪保安团配合日军扫荡长沙近郊抗日游击队。', '[]', '2026-09-10 09:57:14.059767', '2026-09-10 09:57:14.059767', '湖南', '郴州', '北湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09c53ea5087b4ed493f2ed43b7403d5f', '夏斗寅', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北黄冈麻城', '[]', '[]', '抗日战争时期', '', '湖北麻城人，原国民党将领，抗战期间投敌，任伪湖北省政府委员，为日军在湖北统治服务。', '[]', '2026-09-10 09:57:14.057444', '2026-09-10 09:57:14.057444', '湖北', '黄冈', '麻城', NULL, NULL, NULL, NULL, '');
