INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09cab2b0e2af4d17ba83e5c7d669d3dc', '王剪波', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南邵阳新宁；湖南邵阳；湖南邵阳；湖南邵阳武冈；湖南邵阳；湖南邵阳大祥；湖南邵阳；湖南衡阳衡山；湖南衡阳；湖南衡阳常宁；湖南长沙宁乡；湖南长沙；湖北咸宁通城', '[]', '[]', '抗日战争时期', '', '在邵阳一带收编土匪、游杂武装，组成伪军配合日军作战，袭击抗日游击队。；在湘南地区组织伪军，配合日军对衡阳、衡山一带进行扫荡与治安作战，收编土匪武装为伪军。；在邵阳沦陷期间担任伪警察头目，配合日军搜捕抗日人员，维持伪治安。；常宁沦陷期间组织维持会，为日军筹粮筹款，诱降当地士绅，协助日军控制常宁地区。；率伪保安队盘踞通城，为日军征粮、带路，多次配合日军袭扰周边抗日武装。；在湘中地区包括邵阳一带活动，组织伪维持会，为日军提供情报和后勤支持。；在伪长沙县政府中负责教育，推行亲日奴化教育，在长沙、宁乡等地学校进行亲日宣传。；率部投敌，改编为伪保安团，配合日军扫荡邵阳周边抗日武装。；日军占领邵阳后出任伪警察局长，镇压抗日群众，稽查抗日分子。', '[]', '2026-09-10 09:57:14.055352', '2026-09-10 09:57:14.055352', '湖北', '咸宁', '通城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09d09803cff14953841ee7461debe1dd', '唐文彬', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁', '[]', '[]', '抗日战争时期', '', '控制物资配给，盘剥农民，为日军收购粮食和战略物资。', '[]', '2026-09-10 09:57:14.064495', '2026-09-10 09:57:14.064495', '重庆', '铜梁', NULL, NULL, NULL, NULL, NULL, '');
