INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09ee9128f4fe49408e76b64921fc08e8', '孙占元', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江双鸭山宝清；黑龙江七台河桃山', '[]', '[]', '抗日战争时期', '', '组织地方汉奸武装，为日军带路，参与围剿抗联第三、第四军，抢夺百姓粮食资敌。；亲自审讯并酷刑折磨抗联被俘人员，提供情报导致抗联密营被毁，参与“三光”政策行动。', '[]', '2026-09-10 09:57:14.065161', '2026-09-10 09:57:14.065161', '黑龙江', '七台河', '桃山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('09f0b50ea6d24abdb1bf018340d9fb39', '郭子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；山西运城闻喜；山西忻州忻府；山西长治；山西、河北；山西临汾乡宁；山西临汾；河北邯郸邱县', '[]', '[]', '抗日战争时期', '', '为日军统制临汾及乡宁物资，垄断粮食、棉花贸易，向抗日根据地走私毒品，破坏抗日经济。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，破坏抗日宣传。；在辖区推行保甲制度，强派捐税，向日军报告抗日武装动向，导致多次袭击失败。；率伪军驻防屯留边境，多次参与‘清乡’行动，抢劫百姓财物，并协助日军建立情报网。；率伪剿共军驻防长治、武乡一线，多次参与对太行根据地的进攻，在武乡蟠龙镇一带制造多起惨案。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018516', '2026-09-10 09:57:14.018516', '山西', '临汾', '乡宁', NULL, NULL, NULL, NULL, '');
