INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0aa3dc0eedfa4c2b88a52807ce3d93cc', '张英华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁；河北保定；河南南阳；青海黄南河南；辽宁鞍山岫岩；青海黄南河南；河北石家庄；江苏南京鼓楼', '[]', '[]', '抗日战争时期', '', '投日后主管伪省警务，在保定设立特务机构，破坏地下抗日组织，逮捕进步学生和爱国人士，施以酷刑。；在石家庄及河北地区推行日伪政权政策，协助日军进行经济掠夺和治安维持，镇压抗日力量。；岫岩大商户，投日后任伪商会会长，为日军筹集物资，并强迫商户“献金”，资助伪军购买武器。；已列，补充其曾垄断粮食贸易。', '[]', '2026-09-10 09:57:14.033917', '2026-09-10 09:57:14.033917', '江苏', '南京', '鼓楼', NULL, NULL, NULL, NULL, '');
