INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0b0da605f8354d3bb48b6e653c389d10', '门致中', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林，曾任宁夏省主席（1927??1929）；安徽芜湖镜湖；天津河北；河北秦皇岛北戴河；河北秦皇岛；河北廊坊；安徽芜湖镜湖；安徽芜湖；天津、山西、河北；河北石家庄；山西晋中左权；山西晋中', '[]', '[]', '抗日战争时期', '华北伪临时政府', '原西北军将领，投日后在河北保定、石家庄一带驻防，多次率伪军进攻冀中根据地。；指挥华北伪军配合日军“扫荡”，其下属部队在晋中地区犯下罪行。；负责华北伪绥靖军，在廊坊各县设立“剿共”办事处，破坏地下交通站。；率伪军驻守石家庄，配合日军“铁壁合围”，在束鹿、晋县等地烧杀抢掠，并强抓民夫修建碉堡。；在冀东地区（含秦皇岛、北戴河）指挥伪军，配合日军进行“治安强化运动”，残害百姓。；伪任职务：早年做过宁夏省主席，抗战期间在华北投敌，伪华北政务委员会常务委员、华北治安军总司令，指挥伪治安军扫荡华北抗日根据地，作恶全部在华北，不在宁夏。。结局：抗战胜利被国民政府收编，之后逃往香港，客死香港', '[]', '2026-09-10 09:57:14.003256', '2026-09-10 09:57:14.003256', '安徽', '芜湖', '镜湖', NULL, NULL, NULL, NULL, '');
