INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0c44a5770d7d4f9388389932382175b1', '张鸿渐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西长治长治高；浙江绍兴上虞；山西、河北；山西晋城；山西吕梁交口；山西阳泉；河北秦皇岛山海关；河北唐山；山西吕梁；山西吕梁孝义', '[]', '[]', '抗日战争时期', '', '在孝义县配合日军修建碉堡，强拆民房，迫害百姓。；率伪保安队驻守交口川口一带，参与日军“三光”政策行动，烧毁村庄十余个，抢劫牲畜粮食。；指挥伪警察协助日军在太原、娄烦等地搜捕抗日分子，破坏地下组织。；率伪保安队多次袭击灵石东部山区抗日游击队，抓捕抗日干部及家属，并参与日军‘三光’政策行动，烧毁村庄多处。；在任期间推行“保甲连坐”，多次配合日军扫荡晋城山区，杀害抗日家属。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019696', '2026-09-10 09:57:14.019696', '山西', '吕梁', '交口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0c46352e17f647a39bd065d93279f99a', '赵守钰', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳', '[]', '[]', '抗日战争时期', '', '河南南阳人，抗战期间任伪南阳警察局局长，配合日军搜捕抗日人员，维持伪政权治安。', '[]', '2026-09-10 09:57:14.046710', '2026-09-10 09:57:14.046710', '河南', '南阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0c49b16ae96744538ceb05edff8aadeb', '赵清林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁大连；辽宁大连庄河；辽宁大连沙河口；辽宁；辽宁大连；辽宁大连西岗', '[]', '[]', '抗日战争时期', '', '大连港务汉奸，管理港口运输，为日军输送兵员和掠夺物资，参与奴役码头工人。；为日本宪兵队充当翻译，参与审讯和酷刑迫害抗日志士及无辜平民。；组织协和会宣传“日满亲善”，诱骗青年参加伪军，协助日军进行经济掠夺，监视居民言行。；辽宁大连人，曾任伪西岗区保安队队长，配合日军进行“治安肃正”，杀害多名抗日嫌疑人员。；管理大连港，为日军运输军需物资，协助日本经济掠夺。', '[]', '2026-09-10 09:57:14.062967', '2026-09-10 09:57:14.062967', '辽宁', '大连', '庄河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0c49e87bf68d42f0affc962ce468f52f', '申文魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治潞城；山西长治', '[]', '[]', '抗日战争时期', '', '在长治、潞城交界地带频繁袭击抗日游击队，杀害抗日战士，抢夺武器物资。', '[]', '2026-09-10 09:57:14.024331', '2026-09-10 09:57:14.024331', '山西', '长治', '潞城', NULL, NULL, NULL, NULL, '');
