INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0c67b29f135e432c98a472c56a02afb7', '李宝珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；北京、河北；河北唐山；北京通州；北京_顺义；梨树', '[]', '[]', '抗日战争时期', '', '执行日伪“连坐”制度，逮捕大量抗日嫌疑人员，严刑逼供，致多人死亡。；协助日军搜捕抗日分子，严刑拷打被捕人员，提供情报给日军。；指挥伪警察在唐山市区搜捕抗日分子，破坏地下组织。；统辖伪军警，在路南地区实行“连坐清乡”，破坏抗日根据地。；伪职：伪梨树县保安大队长；罪行：九一八后率保安队投降日军；指挥伪保安队围剿辽北义勇军，抓捕爱国群众。；结局：解放后镇反判处长期徒刑。', '[]', '2026-09-10 09:57:13.995179', '2026-09-10 09:57:13.995179', '北京', '通州', NULL, NULL, NULL, NULL, NULL, '');
