INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0d83f4cbd0884d12aaa8be86738f33b0', '李万春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北、辽宁；辽宁大连沙河口；辽宁_大连_长海；河北唐山遵化；河北唐山；黑龙江七台河茄子河；黑龙江七台河勃利；黑龙江鸡西密山；河北廊坊；河北廊坊三河；黑龙江伊春；天津宝坻；黑龙江佳木斯汤原；黑龙江佳木斯；河北沧州任丘；辽宁沈阳新民；黑龙江双鸭山饶河；黑龙江伊春南岔；河北秦皇岛青龙；辽宁大连；河北廊坊三河；河北沧州青县；河北保定保定高；河北保定清苑；黑龙江哈尔滨尚志', '[]', '[]', '抗日战争时期', '', '指挥伪警察逮捕抗日地下党员，严刑逼供，协助日军建立情报网络。；率伪警备队多次配合日军“扫荡”高阳、清苑等地，抓捕抗日干部，烧毁村庄。；任高阳伪县长期间，推行保甲制度，强征粮食，配合日军“治安强化运动”，抓捕抗日干部。；日军占领高碑店后率先投敌，组织维持会，为日军筹集物资，指认抗日分子，导致多名地下党员被捕牺牲。；在任期间强征粮税，配合日军“清乡”行动，抓捕抗日干部，并建立伪保甲制度，镇压群众反抗。……（共涉及17个地区的犯罪记录）；在三河县配合日军“扫荡”，杀害抗日村干部，并勒索百姓。', '[]', '2026-09-10 09:57:14.002930', '2026-09-10 09:57:14.002930', '天津', '宝坻', '保定高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0d894a327910479bac83c74b2cb05fba', '陈佩玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建泉州；福建泉州丰泽；福建泉州；福建泉州晋江；福建泉州；福建泉州德化；福建泉州石狮；福建泉州', '[]', '[]', '抗日战争时期', '', '率伪军在泉州沿海地区配合日军登陆作战，袭击抗日武装，残害百姓。；率部在泉州、南安、惠安沿海配合日军作战，袭击抗日游击队，劫掠沿海村庄。；陈国辉部属，在泉州、南安一带活动，参与割据与附敌。；协助王天赐组织伪维持会，在泉州地区为日军服务。；泉州地方士绅，日军侵入闽南沿海后附逆，参与组织伪维持会，协助日军推行保甲连坐，压制抗日活动。；德化地方史料中提及的维持会人员，协助日伪在德化山区进行统治与征敛，具体事迹记载较少。', '[]', '2026-09-10 09:57:14.061537', '2026-09-10 09:57:14.061537', '福建', '泉州', '南安', NULL, NULL, NULL, NULL, '');
