INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e094a146f874b368ac164849af556c5', '佐佐木', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山丰润', '[\"汉奸化名\"]', '[]', '抗日战争时期', '', '实际指挥伪军扫荡丰润北部山区，烧毁村庄十余个，屠杀百姓百余人。注：此人为日籍但归化汉奸，有争议，但史料列为汉奸。', '[]', '2026-09-10 09:57:14.041500', '2026-09-10 09:57:14.041500', '河北', '唐山', '丰润', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e0ffa2909254539a7da586d3594d87c', '陈斗南', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东肇庆；辽宁沈阳和平；广东肇庆高要；广东肇庆德庆；广东肇庆；广东肇庆怀集；广东广州；广东肇庆封开；广东肇庆四会；广东肇庆高要；广东肇庆广宁；广东肇庆', '[]', '[]', '抗日战争时期', '', '统率伪军配合日军在肇庆、德庆一带进行清乡扫荡，进攻抗日游击队，残害百姓。；日军侵占肇庆后出面组织维持会，为日军筹粮筹款、提供情报，维持殖民统治秩序。；主办伪报，宣传“和平反共建国”，为日军侵略张目，诋毁抗日力量。；在广州沦陷后参与伪广东治安维持会，后任伪广东省政府委员，协助日军推行保甲、征粮及奴化教育，其影响覆盖西江肇庆一带。；在封开基层推行保甲制度，监视民众，举报抗日分子，为日军征调民夫和物资。；率伪军配合日军在四会、广宁、高要一带扫荡抗日游击队，烧杀抢掠。；任伪高要县县长期间，推行保甲连坐，配合日军征粮征税，搜捕抗日分子。', '[]', '2026-09-10 09:57:14.030074', '2026-09-10 09:57:14.030074', '广东', '肇庆', '四会', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e105a538db040cda91740e81d692ed2', '农世英', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西百色田阳；广西崇左龙州', '[]', '[]', '抗日战争时期', '', '龙州本地人，任伪保甲长期间为日军收集情报，带领日伪军搜捕抗日游击队员，强征粮食和壮丁。；在田阳地区协助日军建立伪政权，负责保甲联防，镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.031555', '2026-09-10 09:57:14.031555', '广西', '崇左', '龙州', NULL, NULL, NULL, NULL, '');
