INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e34ac71debe4993ae957847c4ece3d9', '周庆云', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州南浔；浙江湖州；浙江温州', '[]', '[]', '抗日战争时期', '', '在日军扶植下控制湖州商会，垄断粮食和丝绸贸易，为日军物资供应服务。；效忠日军，指挥伪警察搜捕抗日地下党员，严刑拷打进步青年，并参与镇压1944年温州学生抗日示威。', '[]', '2026-09-10 09:57:14.051529', '2026-09-10 09:57:14.051529', '浙江', '湖州', '南浔', NULL, NULL, NULL, NULL, '');
