INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e4320802aed438db69d364815a22ace', '刘振东', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西恒山；黑龙江鸡西；辽宁朝阳；辽宁朝阳建平；宁夏_石嘴山；辽宁朝阳建平；内蒙古赤峰巴林左旗；内蒙古赤峰；辽宁朝阳喀喇沁左翼；内蒙古赤峰；河北承德兴隆；吉林长春朝阳；山东烟台蓬莱；山东烟台莱阳；山东烟台；黑龙江齐齐哈尔甘南；黑龙江齐齐哈尔；山东威海文登；内蒙古、吉林、河北、辽宁；山东淄博淄川；山东淄博周村；黑龙江双鸭山；山东日照莒县；山东日照；黑龙江绥化海伦；山东潍坊；山东潍坊临朐；辽宁朝阳龙城', '[]', '[]', '抗日战争时期', '', '伪职：伪蒙古军第一团团长，驻防包头石拐煤矿；驻守大青山北麓，镇压煤矿工人与游击活动。；结局：石拐战斗被八路军俘虏，教育后释放btdjgov.cn；率保安队配合日军“扫荡”，烧杀抢掠，多次参与围剿赤峰周边的抗日游击队。；在朝阳地区任伪警察署长，抓捕抗日群众，为日军提供情报。；投靠日军，组织维持会为日军征粮派款，提供劳役，并告密抗日分子，导致多名抗日人员被捕牺牲。；组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日军民，烧杀抢掠。；任伪建平县县长期间，强制推行“粮谷出荷”，导致百姓饿殍遍野，并告密逮捕地下抗日人员。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.990351', '2026-09-10 09:57:13.990351', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e45aeac6e7646abaf795d4723912e68', '王化月', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸特务（孙黎特务机关）；罪行：1943年7月与叛徒苏同武、汉奸郑治一带领孙黎特务机关抓捕中共朱家乡党总支等八名党员干部，致使八人被折磨致死并投入枯井；结局：解放后被人民政府处决', '[]', '2026-09-10 09:57:14.082817', '2026-09-10 09:57:14.082817', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e492bd42cc843428db14491e0d9363f', '张怀信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸广平；河北邯郸；河北；河北邯郸魏县', '[]', '[]', '抗日战争时期', '', '率伪军多次袭击冀南抗日根据地，在邯郸周边村庄烧杀抢掠，杀害抗日军属，并协助日军清乡；日军占领魏县后率先组织维持会，为日军提供粮秣、民夫情报，协助建立伪政权。', '[]', '2026-09-10 09:57:14.045216', '2026-09-10 09:57:14.045216', '河北', '邯郸', '广平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0e4a90d2c8ea487a8c1c5866bcd26c92', '左钦彝', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳湘阴；湘阴县；湖南湘阴', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪湘阴县县长兼保安司令，掌握三千伪保安武装；后期暗中掩护抗日武装。结局：抗战胜利后获宽大处理，善终岳阳市情网；伪职：湘阴县维持会会长→兴中会会长→伪湘阴县长；罪行：1885年生。1944年5月日军侵占湘阴后被地方绅士推为维持会会长；7月改为“兴中会”后任会长；年底改为伪湘阴县政府后任县长，自兼保安总队司令。以洪帮为基础组织了一支3000人的保安大队；结局：1945年4月被八路军南下支队策反，此后“人在曹营心在汉”，暗地配合抗日。1947年10月在押返湘阴途中被军统特务枪杀', '[]', '2026-09-10 09:57:14.058123', '2026-09-10 09:57:14.058123', '湖南', '岳阳', '湘阴', NULL, NULL, NULL, NULL, '');
