INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fabfe0011a44b8eaff9056a8710ecd8', '赵子丰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；天津宁河；河北；河北_邢台_邢台经开区；河北唐山；河北唐山玉田；河北承德兴隆', '[]', '[]', '抗日战争时期', '', '在唐山市区实施宵禁，镇压工人和学生抗日示威。；率伪军在玉田、遵化边界地区袭击八路军，烧毁村庄。；宁河（部分属路南）伪县长，控制蓟运河交通，盘查抗日物资。；充当日军特务，打入抗日组织内部，策反叛徒，导致兴隆地区多个地下联络站被破坏，数十名抗日人员牺牲。；效忠日军，指挥伪警察抓捕抗日志士，破坏地下党组织，参与“清乡”行动。', '[]', '2026-09-10 09:57:14.041844', '2026-09-10 09:57:14.041844', '河北', '唐山', '玉田', NULL, NULL, NULL, NULL, '');
