INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fbed8d68d8d4c2dadf5610b346feb3a', '徐树楠', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江湖口', '[]', '[]', '抗日战争时期', '', '在伪湖口县教育系统任职，推行奴化教育，篡改教材并组织师生参加亲日宣传活动。', '[]', '2026-09-10 09:57:14.039175', '2026-09-10 09:57:14.039175', '江西', '九江', '湖口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fc58a791da44f12850a8d5d27b12727', '李文光', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大庆大同；黑龙江伊春伊美；黑龙江伊春；黑龙江哈尔滨道里；黑龙江哈尔滨道外；黑龙江大庆肇州；黑龙江哈尔滨呼兰；黑龙江哈尔滨；黑龙江鸡西；黑龙江哈尔滨依兰；黑龙江牡丹江绥芬河；黑龙江伊春乌翠；黑龙江哈尔滨方正；黑龙江牡丹江穆棱；黑龙江绥化北林；黑龙江绥化；黑龙江哈尔滨平房；黑龙江哈尔滨；黑龙江哈尔滨五常；黑龙江七台河桃山；黑龙江七台河；黑龙江双鸭山；黑龙江哈尔滨通河；黑龙江牡丹江', '[]', '[]', '抗日战争时期', '', '在勃利县（含今七台河、桃山一带）推行日伪殖民统治，强征劳工，配合日军清剿抗联，残害百姓。；在穆棱县任职期间，积极推行日伪殖民政策，强征劳工，配合日军清乡，破坏抗日地下组织，迫害抗日家属。；伪满时期大同县（今大庆大同区）汉奸县长，积极为日军征粮、抓劳工，镇压当地抗日活动，具体劣迹包括强征民夫修筑警备道路。；在通河县任内积极推行日伪“归屯并户”政策，强迫民众迁入集团部落，配合日军封锁抗联，导致当地百姓大量伤亡。；原方正县地方士绅，投日后任伪县长，为日军提供粮食物资，组织伪自卫团对抗抗联，迫害当地百姓。；负责哈尔滨及周边地区警察特务系统，多次组织搜捕抗日地下组织，破坏尚志地区抗联联络站。；长期担任伪三江省警务厅厅长，负责该省（含今双鸭山岭东）的警察特务工作，组织“搜山”行动，抓捕抗日联军地下工作者，实施白色恐怖；原地方士绅，投日后任伪道里区区长，协助日伪推行保甲制度，强征捐税，出卖抗日情报，导致多名抗联战士牺牲；在牡丹江地区组织伪警察协助日军围剿抗联，逮捕杀害多名地下党员。；在东安省（今鸡西、密山等地）强化殖民统治，配合日军“归屯并户”，迫害抗日群众。；原奉系宪兵，投日后任哈尔滨宪兵队长，在平房地区设立秘密监狱，刑讯抗日志士。；在绥芬河口岸协助日本宪兵队检查出入境人员，抓捕抗日分子和苏联情报员。；在呼兰县推行保甲制度，强征劳工，协助日军建立“集团部落”，迫害抗日群众。；作为道外区汉奸头目，协助日军强征民夫修建军事设施，向宪兵队告密抗日嫌疑人员。；原哈尔滨警察，投敌后任伪警察厅长，残酷镇压地下党和抗日群众，制造多起逮捕屠杀事件。；在哈尔滨残酷镇压抗日地下组织，抓捕、刑讯抗日志士，协助日本宪兵队制造多起惨案。；指挥伪警察讨伐队，在四方台、双鸭山等地多次袭击抗联部队，逮捕杀害抗日志士。；在牡丹江地区推行日伪“治安肃正”，强征劳工，协助日军对抗联根据地实施封锁。；率伪森林警察在伊春林区为日军采伐木材，同时搜捕抗联小分队，破坏抗联密营。；投敌后任依兰县伪县长，强征民夫，配合日军建立“集团部落”。；伪满时期长期担任绥化县县长，推行日伪殖民政策，强征劳工，收缴民间武器，配合日军“治安肃正”，镇压当地抗日活动。；在五常县任伪县长期间，推行保甲制度，强征民夫修建警备道路，配合日军讨伐抗联第三军；在肇州任伪县长期间，强征民夫修建警备道路，协助日军清乡并迫害抗联家属。；积极执行日伪“治安肃正”，建立保甲制度，抓捕抗联交通员，并参与“归屯并户”强迫居民迁移。', '[]', '2026-09-10 09:57:14.065102', '2026-09-10 09:57:14.065102', '黑龙江', '七台河', '桃山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fc8cb836f074e939d98b1bf00d8886f', '陈仲衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州南沙；广东云浮郁南；广东湛江吴川；广东广州荔湾；广东广州；广东广州番禺；湖北宜昌猇亭；湖北宜昌', '[]', '[]', '抗日战争时期', '', '在南沙地区组织伪维持会，协助日军管理地方，征发劳工与物资。；在番禺沦陷区为日军筹款筹粮，协助推行伪币与物资统制。；在吴川组织伪维持会，协助日军征粮征夫。；在广州沦陷区教育界推行亲日奴化教育。；率伪保安队配合日军扫荡宜昌周边地区，包括猇亭一带，清乡并抓捕抗日军民。', '[]', '2026-09-10 09:57:14.026009', '2026-09-10 09:57:14.026009', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fda361c5c21486d9aa55fa59bbcdd09', '陶保晋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁人', '[\"陶锡三\"]', '[]', '抗日战争时期', '南京伪维新政府', '伪任职务：南京沦陷后出任南京市自治委员会会长，伪维新政府立法委员；江宁籍士绅，利用地方声望协助日军维持占领秩序。主要活动在南京城，但籍贯江宁。。结局：抗战胜利以汉奸罪逮捕，病死狱中抖音百科', '[]', '2026-09-10 09:57:14.068855', '2026-09-10 09:57:14.068855', '江苏', '南京', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fe4cc471abf447ab55a9f7a6f8a9721', '毛鸿勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州柯城；浙江衢州；浙江衢州；浙江衢州龙游；浙江衢州龙游；浙江衢州衢江', '[]', '[]', '抗日战争时期', '', '率伪保安队协助日军维持治安，搜捕抗日分子，参与镇压衢州地区抗日活动。；组织伪保安大队，配合日军扫荡龙游南部山区，烧毁抗日村庄，抓捕并杀害多名抗日军民。；日军占领龙游后投敌，任伪县长，强迫百姓领取“良民证”，为日军征粮派款，破坏抗日地下组织。；组织伪保安队，配合日军扫荡抗日武装，抓捕、杀害抗日军民，参与镇压衢江地区抗日活动。', '[]', '2026-09-10 09:57:14.052173', '2026-09-10 09:57:14.052173', '浙江', '衢州', '柯城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0fea62f4a62d42d0bd9d55fd5707fee7', '刘文甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳', '[]', '[]', '抗日战争时期', '', '河南南阳人，抗战期间投敌，任伪维持会干事，协助日军办理行政事务。', '[]', '2026-09-10 09:57:14.046984', '2026-09-10 09:57:14.046984', '河南', '南阳', '宛城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('0ff010d9a3a64602b895f2e920aaca5d', '王德舆', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西鹰潭贵溪；江西上饶万年；江西上饶；江西九江修水；江西南昌；江西吉安永丰；江西吉安；江西吉安；湖南岳阳云溪；湖南岳阳临湘；江西赣州上犹；湖北咸宁通山；湖北咸宁嘉鱼；湖南岳阳君山；湖南岳阳；江西上饶铅山；江西南昌；江西南昌安义；江西南昌；江西上饶玉山；重庆云阳；江西赣州赣县；江西赣州；江西吉安井冈山；江西吉安泰和；江西_吉安；江西九江瑞昌；江西九江；江西南昌青云谱；江西南昌；辽宁沈阳大东；江西赣州宁都；江西南昌；江西上饶婺源；辽宁沈阳大东；江西鹰潭余江；江西南昌；江西景德镇乐平；江西景德镇', '[]', '[]', '抗日战争时期', '', '在上饶县城组织伪维持会，为日军搜集情报、征调民夫，并协助推行伪化教育。；在万县地区组织维持会，为日军提供情报和物资，协助日军控制长江航运。；以商会名义为日军摊派物资、筹措军需，协助日伪对岳阳工商业进行经济统制。；任伪嘉鱼县县长，推行保甲连坐，配合日军对咸宁周边地区进行扫荡。；率伪警察配合日军搜捕抗日人员，镇压当地民众反抗。；率伪保安队配合日军扫荡景德镇周边抗日力量，捕杀抗日人员，勒索地方百姓。；在伪南昌县推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”，毒化沦陷区青少年。；在日占区推行奴化教育，篡改教材，宣传所谓大东亚共荣，毒化南昌青少年。；江西吉安人，投敌后组织伪维持会，协助日军在吉安地区的统治与物资征调。；在南昌为日军筹办军需，组织商户“献金”，协助日军控制粮食市场。；在南昌伪江西省政府任职，参与伪政权决策，协助日军在江西沦陷区推行经济掠夺和奴化教育。；九江沦陷后出任伪商会会长，为日军筹款、摊派物资，协助实行经济统制，属经济领域附逆者。；江西贵溪人，贵溪沦陷期间任伪维持会长，配合日军掠夺资源、镇压抗日活动。；临湘沦陷后投靠日军，任伪县知事，配合日军修筑粤汉铁路沿线据点，镇压抗日游击活动。；抗战时期在吉安沦陷区出任伪职，协助日军管理地方，镇压抗日活动。；在南昌沦陷区为日军统制物资、摊派捐款，属经济附逆者。；浙赣会战期间日军侵占玉山后，出面组织伪维持会，为日军征派民夫、粮食，维持占领秩序。；在沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣”。；在赣南地区协助日军推行伪化政策，组织伪政权，动员地方士绅附逆，为日军提供情报。；在南昌沦陷区任伪商会会长，为日军筹款筹物，强制商户“献纳”，并参与经济统制。；在南昌及赣东北一带参与伪政权筹备活动，为日军物色伪职人员，推动伪化教育宣传。；在日军占领吉安期间出任伪警察局长，统率伪警配合日军搜捕抗日分子、镇压民众反抗，维持占领秩序。；泰和沦陷期间组织维持会，依附日军，协助征发民夫、物资，压迫当地民众。；江西赣县人，日军侵占赣州期间，出任伪保甲长，协助日军清查户口、征发民夫、征收物资，是赣州基层附逆者。', '[]', '2026-09-10 09:57:14.037241', '2026-09-10 09:57:14.037241', '江西', '鹰潭', '贵溪', NULL, NULL, NULL, NULL, '');
