INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('10198886711d4c63ac7c628ee6426673', '李元亨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山滦州；河北唐山；河北；河北廊坊；河北廊坊安次；河北秦皇岛北戴河；河北秦皇岛；河北唐山迁安；河北唐山唐山芦台经开区；吉林经开区；河北唐山玉田；河北唐山迁西', '[]', '[]', '抗日战争时期', '', '在芦台镇（今芦台经开区一带）组织维持会，为日军提供粮食、劳力和情报，协助镇压当地抗日武装。；在迁安（今属唐山）配合日军进攻冀东抗日根据地。；指挥伪警察在玉田县内搜捕抗日地下党员，破坏抗日组织。；在迁安推行新民会奴化宣传，组织青少年接受日伪教育，收集抗日情报，协助日军“宣抚”工作。；率伪保安队常驻迁西金厂峪一带，为日军护矿，镇压矿工反抗，杀害抗日游击队员。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.041695', '2026-09-10 09:57:14.041695', '河北', '唐山', '唐山芦台经开区', NULL, NULL, NULL, NULL, '');
