INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1280ce23440e466e92e4e2667597565a', '陈明辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西抚州广昌；江西抚州；江西上饶铅山', '[]', '[]', '抗日战争时期', '', '江西铅山人，铅山沦陷期间任伪维持会长，配合日军征粮征丁，维持占领区秩序。；在金溪及抚州东北部地区为日军筹粮筹款，组织伪政权，协助日军控制交通线。', '[]', '2026-09-10 09:57:14.037185', '2026-09-10 09:57:14.037185', '江西', '上饶', '铅山', NULL, NULL, NULL, NULL, '');
