INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1294ae46ec8147bca4b2ea405df17f04', '色旺多尔济', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古兴安科尔沁右翼前旗；内蒙古通辽扎鲁特旗；内蒙古通辽；内蒙古通辽科尔沁左翼中旗；内蒙古呼伦贝尔牙克石；内蒙古呼伦贝尔；内蒙古赤峰翁牛特旗；黑龙江大庆杜尔伯特；内蒙古通辽科尔沁左翼后旗；内蒙古赤峰巴林右旗；内蒙古兴安科尔沁右翼中旗；内蒙古赤峰红山；内蒙古赤峰', '[]', '[]', '抗日战争时期', '', '在伪满洲国东蒙古地区任职，参与地方行政与治安维持，配合日军对通辽及周边蒙旗的控制。；科尔沁右翼中旗地方豪绅，日军占领后组织维持会，协助日军维持治安、征发粮草，后转入伪旗公署任职。；翁牛特旗蒙古族王公，投靠日本，任伪翁牛特旗旗长或札萨克，协助日伪统治翁牛特旗，推行伪政、征粮征畜。；在巴林右旗伪旗公署任职，执行日伪政令，推行保甲连坐，征发民夫物资，配合日军控制当地。；杜尔伯特旗蒙古贵族，投敌后任伪杜尔伯特旗旗长，后任伪满兴安局官员，协助日本在杜尔伯特及周边地区推行殖民统治。；在呼伦贝尔地区担任伪旗县职务，推行保甲、征发劳役，配合日伪统治。；在科尔沁左翼后旗充任伪旗长，推行保甲连坐，协助日军征粮、征兵，控制当地民众。；任伪科尔沁左翼中旗旗长期间，推行日本殖民教育，强征物资，组织伪警察维持治安，协助日军镇压抗日活动。；投靠日伪，在赤峰北部旗县推行伪政，配合日军清乡。；在伪兴安南省协和会任职，负责亲日宣传、组织民众训练，活动覆盖科尔沁右翼前旗，协助日伪进行思想控制。', '[]', '2026-09-10 09:57:13.987827', '2026-09-10 09:57:13.987827', '内蒙古', '兴安', '科尔沁右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('12a2c2a8919141059487f6d71cdab57f', '胡金山', NULL, NULL, NULL, NULL, 'exact', 'exact', '亳县二区（颜集）', '[]', '[]', '抗日战争时期', '', '伪职：白枪会头目，勾结日伪；罪行：地方会道门武装，勾结日伪发动暴乱，制造亳二区惨案，杀害 9 名党员干部，抓捕二十余名革命人员。；结局：暴乱被镇压，捕获后公审枪决。', '[]', '2026-09-10 09:57:14.086224', '2026-09-10 09:57:14.086224', '安徽', '亳州', NULL, NULL, NULL, NULL, NULL, '');
