INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('12dce14d78254b61b48d9815cd602e81', '张仲孚', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南信阳信阳高；河南信阳；河南新乡卫滨；河南新乡；河南信阳商城；河南信阳潢川；河北廊坊固安；天津河北；河南信阳淮滨；河南信阳', '[]', '[]', '抗日战争时期', '', '在伪河北省政权中任职，参与伪政权事务。；在潢川沦陷区组织伪政权，为日军征发物资、修筑工事，配合清乡扫荡。；继任伪豫北道尹，继续为日军控制豫北新乡等地，直至抗战结束。；在伪河南省政权中任职，负责豫南地区伪化行政，督导信阳、潢川、固始等县伪政权建设，配合日军统治豫南。；在伪豫南道任职，管辖包括信阳在内的豫南伪政权，协助日军征粮、征兵、维持治安与推行奴化教育。', '[]', '2026-09-10 09:57:14.042440', '2026-09-10 09:57:14.042440', '河北', '廊坊', '固安', NULL, NULL, NULL, NULL, '');
