INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('12f785182ce346e3a6e727bb43e6cf5e', '王凤岗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊大城；天津河北；河北保定保定高；河北保定高阳；河北保定徐水；河北廊坊三河；河北廊坊香河；河北保定阜平；河北保定涿州；河北廊坊安次；河北保定清苑；河北保定；河北沧州黄骅；辽宁沈阳新民；河北廊坊霸州；河北保定容城；河北保定高阳；河北保定定州；河北保定涞水；河北沧州河间；河北保定唐县；河北保定涞源；河北保定顺平；河北保定唐县；河北唐山唐山海港经开区；河北保定定兴；河北廊坊大厂；河北廊坊香河；河北保定高碑店；河北沧州肃宁；固安；河北廊坊文安；河北衡水冀州；河北衡水；河北衡水武邑；河北保定易县；河北廊坊永清；河北廊坊固安；北京房山；河北沧州沧州高；河北保定蠡县；河北衡水故城；河北衡水；河北保定满城；河北廊坊；河北廊坊大厂；河北保定安新；河北衡水深州；河北衡水；北京、河北；河北保定雄县；河北沧州青县；河南平顶山平顶山高；河南平顶山', '[]', '[]', '抗日战争时期', '', '伪职：原地方武装，抗战后期投敌，伪固安保安团；日降后被国民党收编，成为大清河北主要顽匪，残害冀中十分区军民。；结局：1949 年逃亡台湾，病死台湾；在房山、良乡一带为日军效力，围剿八路军游击队，抓捕抗日家属，破坏地下交通线。；原国民党地方武装头目，投日后任保定地区伪保安司令，在白沟新城、高碑店一带设立据点，残酷镇压抗日群众，制造多起惨案。；在保定地区为日军搜集情报，参与策划“治安强化运动”，迫害抗日军民。；曾任伪高阳县长，后升任伪保定道尹，推行日伪统治，强征粮税，镇压抗日活动。；在高阳、保定一带率伪警备队多次突袭村庄，杀害抗日家属，烧毁民房。……（共涉及63个地区的犯罪记录）；在大厂地区组织“反共自卫团”，袭击回民支队，破坏民族团结抗日。', '[]', '2026-09-10 09:57:13.994416', '2026-09-10 09:57:13.994416', '北京', '房山', '保定高', NULL, NULL, NULL, NULL, '');
