INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13304bd254f14df59fabaaa55c81a5cf', '黄仲庵', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西玉林陆川；广西梧州；广西贺州钟山；辽宁沈阳大东；广西北海海城；广西北海；广西柳州；广西南宁；广西南宁邕宁；广西南宁邕宁；云南普洱西；广西北海合浦；广西北海；广西南宁良庆；广西钦州钦南；广西北海', '[]', '[]', '抗日战争时期', '', '广西梧州沦陷后组织伪维持会，为日军筹粮、拉夫，并协助日军控制西江航运。；在北海、钦州沿海地区为日军提供港口情报和物资，组织伪政权协助日军控制北部湾沿岸。；以商会名义为日军征集物资，协助日军对北海商民进行经济掠夺。；在日伪控制下推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；在广东南路包括北海、合浦一带参与伪维持会，协助日军推行殖民统治。；日军侵占广西期间，参与伪教育机构，推行奴化教育。；在日军侵占邕宁（今南宁良庆区一带属当时邕宁县）期间，组织伪维持会并任会长，协助日军管理地方、征发物资、压制抗日力量。；日军侵占邕宁后出任伪县知事，负责征粮、征夫和推行保甲连坐。；日军侵占柳州期间，出任伪柳州警察局局长，协助日军维持治安、镇压抗日活动。', '[]', '2026-09-10 09:57:14.030520', '2026-09-10 09:57:14.030520', '广西', '北海', '合浦', NULL, NULL, NULL, NULL, '');
