INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13441ae8e38a42d084e223f00ea75891', '赵承绶', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼和浩特清水河；内蒙古呼和浩特和林格尔；山西太原；山西长治武乡；山西临汾尧都；山西临汾；内蒙古、山西、河北；山西太原阳曲；山西忻州原平；云南普洱西；河北张家口万全；河北张家口；黑龙江大庆大同；山西大同；黑龙江大庆大同；山西临汾乡宁；山西临汾；河北张家口；内蒙古呼和浩特土默特左旗；山西太原晋源；山西太原小店；云南普洱西；山西晋中平遥；山西晋中；山西晋中左权；内蒙古包头昆都仑；内蒙古包头；内蒙古巴彦淖尔五原；山西大同大同经开区；黑龙江大庆大同；山西朔州；内蒙古包头固阳；内蒙古包头；山西吕梁；山西吕梁孝义；江苏无锡锡山；山西忻州；山西大同新荣；黑龙江大庆大同；内蒙古巴彦淖尔临河；内蒙古呼和浩特呼和浩特经开区；山西临汾侯马；山西临汾；内蒙古乌兰察布商都；内蒙古乌兰察布；山西_临汾_曲沃；山西临汾；山西吕梁汾阳；山西吕梁；山西大同云州；山西忻州五台；山西忻州五台山风景区；山西忻州五台；内蒙古乌兰察布丰镇；内蒙古乌兰察布；山西临汾；山西晋中；内蒙古包头东河；内蒙古包头；山西临汾吉县；山西运城；内蒙古乌兰察布凉城；内蒙古包头石拐；内蒙古包头；陕西西安周至；云南普洱西；山西晋中祁县；山西晋中；山西长治上党；山西大同平城；山西朔州怀仁；内蒙古乌兰察布兴和；内蒙古乌兰察布；内蒙古呼和浩特；内蒙古包头青山；内蒙古乌兰察布；内蒙古包头包头稀土高；内蒙古包头；山西吕梁交口；江苏无锡锡山', '[\"注：早期抗日，后投敌，但主要在晋中地区，与晋源关联较少\"]', '[]', '抗日战争时期', '', '原晋绥军将领，一度与日军合作，其部队活动于绥南（含凉城），参与对八路军游击区的“围剿”。；原晋军将领，被俘后变节，在乌兰察布地区协助日伪收编散兵，参与“清乡”行动。；原晋军将领，投日后任伪职，参与对乌兰察布、兴和地区的军事“讨伐”和物资掠夺。；原国民党将领，后投靠日军，在乌兰察布东部地区协助日军建立伪政权，参与对抗日武装的围剿。；原晋军军官，投日后在乌兰察布东部组织伪保安队，配合日军封锁根据地。；原晋军将领，投日后任伪绥远省顾问，参与策划对包头、东河地区的“强化治安”运动，为日军出谋划策。……（共涉及74个地区的犯罪记录）；原晋军将领，被俘后投敌，组织伪剿共军，专门进攻八路军晋绥根据地。；原晋绥军将领，投日后任伪保安副司令，参与镇压抗日武装。；被日军俘虏后变节，协助日军劝降晋绥军，但主要活动在晋西。', '[]', '2026-09-10 09:57:13.986597', '2026-09-10 09:57:13.986597', '内蒙古', '乌兰察布', '丰镇', NULL, NULL, NULL, NULL, '');
