INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('136c667004bc44da940256bef72acac4', '丁超', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁葫芦岛；河北_承德_隆化；黑龙江黑河北安；辽宁葫芦岛建昌；黑龙江伊春乌翠；黑龙江齐齐哈尔；河北承德；辽宁_朝阳_北票；辽宁_朝阳_双塔；辽宁_朝阳_建平；吉林长春榆树；吉林长春；吉林四平铁西；吉林延边延吉；黑龙江齐齐哈尔；辽宁_朝阳；辽宁_朝阳_凌源；吉林、河北、辽宁；黑龙江绥化肇东；吉林；吉林辽源；辽宁阜新；吉林延边图们；吉林；吉林白城大安；吉林；辽宁_丹东_振安；辽宁新宾；吉林', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：先抗日后投敌，伪满通化省省长，围剿抗日武装。结局：苏军俘获，1950 年病亡抚顺战犯管理所；伪职：伪安东省省长（华人）；罪行：原东北抗日自卫军将领，兵败投敌；主持伪安东省政务，推行集团部落、保甲，强征劳工，配合东边道大讨伐围剿抗联。；结局：1945 苏军逮捕，关押抚顺战犯管理所，1951 年狱中病死。；原东北军将领，投日后在辽源、龙山一带率伪军围剿抗日游击队，制造多起惨案。；原东北军旅长，一度抗日，后投降日军，任伪吉林警备司令，参与围剿抗联。；原东北军将领，投日后组织治安军，在榆树、长春周边围剿抗联。；原东北军军官，投日后任伪热河省警务厅长，在承德、滦平一带组织伪警察，协助日军清乡、搜捕抗日人员。；原东北军将领，投日后在伪热河省任职，推行日伪奴化教育，强征粮食和民夫，为日军侵华战争服务。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.997644', '2026-09-10 09:57:13.997644', '吉林', '四平', '铁西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('136ef310fd0f4e2d95e6175ecffe3770', '张九', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳坪山；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '推行奴化教育，在宝安、深圳等地学校强制使用伪教材，宣传“大东亚共荣”。', '[]', '2026-09-10 09:57:14.029076', '2026-09-10 09:57:14.029076', '广东', '深圳', '坪山', NULL, NULL, NULL, NULL, '');
