INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('137e037aba6e4ed3b8cbcc887d1534dc', '莫福如', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东肇庆鼎湖；广东肇庆；广东云浮；广东肇庆端州；广东肇庆', '[]', '[]', '抗日战争时期', '', '率伪军在肇庆、鼎湖、四会交界地带活动，配合日军清乡，劫掠民财，杀害抗日干部。；控制云浮商会期间为日军采购物资，强制商户缴纳所谓“治安费”，协助日军经济掠夺。；率伪军在高要、肇庆地区配合日军扫荡，袭击抗日游击队，强征粮食和壮丁。', '[]', '2026-09-10 09:57:14.024799', '2026-09-10 09:57:14.024799', '广东', '云浮', '端州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13986d0cb940439383e1e920b3b5861a', '张子言', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。', '[]', '2026-09-10 09:57:14.064393', '2026-09-10 09:57:14.064393', '重庆', '沙坪坝', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13a9a31e375f49afa892f7b9f17fe010', '徐理明', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳大东；河南郑州', '[]', '[]', '抗日战争时期', '', '在河南沦陷区推行奴化教育，改编教材，强制学生学习日语，宣传“大东亚共荣圈”。；任伪郑州警察局局长，负责郑州沦陷区治安，搜捕抗日人士，协助日军维持殖民统治。', '[]', '2026-09-10 09:57:14.048964', '2026-09-10 09:57:14.048964', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13ac514893174ddeb4d9e4e58b253d82', '王德一', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东日照东港；山东日照五莲；山东日照；辽宁沈阳新民；山东日照岚山；山东日照', '[]', '[]', '抗日战争时期', '', '在日照县城及岚山一带搜捕抗日人员，推行保甲制度，配合日军进行治安强化运动。；在日伪统治下推行奴化教育，编写亲日教材，组织学生进行亲日宣传，毒化沦陷区青少年。；主持伪新民会，进行奴化宣传，组织训练伪青年，配合日军推行治安强化运动。；在五莲地区组织伪保安团，协助日军维持治安，参与扫荡抗日根据地。', '[]', '2026-09-10 09:57:14.014320', '2026-09-10 09:57:14.014320', '山东', '日照', '东港', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13b5835d1b3941bd83fb1b42ef2c5ee5', '寇松年', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁大连庄河', '[]', '[]', '抗日战争时期', '', '指挥伪警察在庄河地区搜捕抗日志士，参与制造多起屠杀事件。', '[]', '2026-09-10 09:57:14.063007', '2026-09-10 09:57:14.063007', '辽宁', '大连', '庄河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13c7199a5cc3436fa63db6e0cc137b8d', '姚作宾', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川南部；山东青岛；山东济南；山东潍坊昌邑；山东青岛；福建南平政和；山东青岛；四川南部县', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪青岛特别市市长；罪行：1943年接赵琪任伪青岛市市长，为日军征敛物资、搜捕抗日民众；来源：抗日战争纪念网（青报网转载）；备注：外省籍任职青岛；青岛解放后被审判处决；伪任职务：长期在北方沦陷区，历任伪青岛维持会总务长、伪青岛特别市市长；大肆搜刮物资献粮献金献飞机资敌。。结局：抗战胜利逮捕，判处死刑执行枪决', '[]', '2026-09-10 09:57:14.013129', '2026-09-10 09:57:14.013129', '四川', '南充', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13cfbc0bf4d04535becd96037b0bb254', '韩步洲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '交城；山西太原；山西', '[]', '[]', '抗日战争时期', '', '充当日伪经济汉奸，为日军统制平城地区物资，强征商户捐款，垄断粮食贸易，导致民不聊生。；任太原县伪知事，强征粮税，出卖抗日群众，为日军提供情报。；伪职：伪山西省保安第四师师长；罪行：原阎军军官投敌；驻扎交城、文水一带；多次率伪军配合日军扫荡交城、清太徐根据地，捕杀干部民兵。；结局：日本投降被阎锡山收编；太原解放被俘劳动改造', '[]', '2026-09-10 09:57:14.021341', '2026-09-10 09:57:14.021341', '山西', '太原', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13d79abb14bf486cb880340411bb2ee9', '张星南', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳和平；辽宁沈阳', '[]', '[]', '抗日战争时期', '', '管理伪满银行沈阳分行，发行伪币，掠夺民间财富。', '[]', '2026-09-10 09:57:14.063573', '2026-09-10 09:57:14.063573', '辽宁', '沈阳', '和平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13e8046d89dc414083bb61c095ea0815', '李端凝', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽中', '[]', '[]', '抗日战争时期', '', '伪职：伪盘山县第二任县长（1933??）；罪行：推行保甲连坐，强征劳工粮食，围剿辽西义勇军；为被打死的日伪军修建 “忠魂碑”，美化日伪统治。；结局：抗战胜利逮捕，汉奸罪判刑。', '[]', '2026-09-10 09:57:14.081492', '2026-09-10 09:57:14.081492', '辽宁', '沈阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13ea33e9b2d04596b3b4c8fedaefc616', '宋殿元', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西大同广灵；河北邢台任泽；河北衡水枣强；河北张家口张家口察北管理；河北张家口张北；河北康保；康保；山西、河北；河北_邢台_隆尧', '[]', '[]', '抗日战争时期', '', '伪职：伪讨伐队头目，长期活动包头周边；烧杀淫掠，血债极多。；结局：1951 包头人民广场公审枪决；伪职：伪讨伐队头目；结局：1951 年包头公审枪决；专门负责刺探八路军情报，带领特务队破坏抗日交通线，曾抓捕并杀害抗日村长数人，其特务队以手段残忍著称。；原为张北县劣绅，投日后任伪知事，在察北地区推行日伪“治安强化运动”，强征壮丁，搜刮民财。；率自卫团配合日军‘铁壁合围’，在枣强南部多次袭击抗日游击队，杀害多名抗日战士。；组织伪自卫团，配合日军“铁壁合围”，袭击抗日武装，残害抗日家属。；在冀县及周边地区抓捕抗日军民，提供情报给日军，参与杀害抗日干部，民愤极大。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.021071', '2026-09-10 09:57:14.021071', '山西', '大同', '广灵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('13f36cd641b4471986e98983406e7f7e', '惠锡良', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖', '[]', '[]', '抗日战争时期', '', '伪职：特工警卫队队长；罪行：特务武装头目，负责看守被捕人员，参与特务抓捕行动中国人民政...。；结局：肃奸运动镇压。', '[]', '2026-09-10 09:57:14.068535', '2026-09-10 09:57:14.068535', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
