INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('14073d265fcd4d47bd2c6fecfbc41e97', '许廷杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头南澳；广东揭阳揭东；广东揭阳；广东汕头龙湖；广东汕头澄海；广东_汕头_潮南；广东汕头金平；广东汕头；广东；广东揭阳', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪广州绥靖公署参谋长，广东伪军高级将领。结局：抗战胜利被捕，判处徒刑', '[]', '2026-09-10 09:57:14.027779', '2026-09-10 09:57:14.027779', '广东', '揭阳', '揭东', NULL, NULL, NULL, NULL, '');
