INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1435c4320b4743049cc8ecf28436c3d7', '郭培德', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城；山东聊城冠县；山东聊城东昌府', '[]', '[]', '抗日战争时期', '', '在日军扶植下出任伪冠县县知事，推行保甲连坐，配合日伪军扫荡抗日根据地。；率伪警备队在聊城及东昌府周边配合日军扫荡，抓捕抗日人员，抢掠民财，残害百姓。；配合日军清乡，强征民夫修筑公路据点，掠夺棉花粮食。', '[]', '2026-09-10 09:57:14.017512', '2026-09-10 09:57:14.017512', '山东', '聊城', '东昌府', NULL, NULL, NULL, NULL, '');
