INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1440b83f837249a8b4dfbe355d368e5f', '陈耀', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东云浮云安；广东云浮；广东佛山；广东佛山高明；广东佛山；广东珠海斗门；广东深圳南山；广东深圳；广东深圳福田；广东深圳；广东佛山三水', '[]', '[]', '抗日战争时期', '', '佛山沦陷后出面组织伪维持会，后任伪南海县县长，为日军征集物资、维持治安、推行保甲制度，协助日军统治佛山及南海地区。；日军侵占云浮期间出面组织伪维持会，协助日军征粮、拉夫、维持地方治安，镇压抗日群众。；日军侵占深圳后，出面组织伪深圳维持会，协助日军维持治安、征发民夫与物资，为日军在深圳地区的殖民统治服务。；任伪三水县警察局局长期间，配合日军搜捕抗日人员，推行保甲连坐，勒索当地百姓。；佛山沦陷后出面组织伪南海县维持会，后任伪县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。；佛山沦陷后出面组织伪南海县维持会，后任伪南海县县长，协助日军征粮、拉夫、维持治安，镇压抗日群众。；抗日战争时期投靠日军，参与组织伪宝安县维持会并任会长，后任伪宝安县县长，协助日军在宝安、深圳、南头一带推行殖民统治、征粮派款、维持治安。；在斗门地区出任伪区长，推行日军殖民统治政策，协助征收赋税、登记户口，并参与镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.024866', '2026-09-10 09:57:14.024866', '广东', '云浮', '云安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('14434345fe264543a3679b05e17ca0f1', '廖志强', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳江穿山', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：穿山乡伪维持会长，勾结日军扫荡穿山一带游击区。结局：审判后处死', '[]', '2026-09-10 09:57:14.083498', '2026-09-10 09:57:14.083498', '广西', '柳州', NULL, NULL, NULL, NULL, NULL, '');
