INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('14656822b905451c8161066a5f6e48cd', '纪作涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林通化梅河口；吉林通化东昌；吉林通化', '[]', '[]', '抗日战争时期', '', '任伪通化县县长期间，强征劳工，推行“归屯并户”，协助日军制造无人区，破坏抗联根据地。；汉奸文人，任伪满通化省协和会事务长，在梅河口、通化等地宣传“日满亲善”，组织奴化教育，协助日军征粮抓丁。', '[]', '2026-09-10 09:57:14.000724', '2026-09-10 09:57:14.000724', '吉林', '通化', '东昌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1469008a87494f73bdc8db7cc4087e5b', '杨清漳', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南湘西凤凰', '[]', '[]', '抗日战争时期', '', '湖南凤凰人，日军犯湘西时组织维持会，为日军筹粮、提供情报，协助伪政权控制凤凰地区。', '[]', '2026-09-10 09:57:14.059076', '2026-09-10 09:57:14.059076', '湖南', '湘西', '凤凰', NULL, NULL, NULL, NULL, '');
