INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1476e33bb2f74de3a3a969bcfe7353b2', '陈俄', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南东方；广西防城港港口；海南琼中；海南琼海', '[]', '[]', '抗日战争时期', '', '在崖县地区为日军筹粮筹款，协助日军管理港口与盐场，镇压抗日群众。；在琼东（今属琼海）地区组织伪维持会，为日军征粮、拉夫，配合日军清乡。', '[]', '2026-09-10 09:57:14.053642', '2026-09-10 09:57:14.053642', '海南', '东方', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('147f8548c8e04b39810ed977883d1e67', '佟衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁鞍山铁西；辽宁沈阳铁西；辽宁；吉林；辽宁_沈阳；辽宁抚顺清原；辽宁抚顺；辽宁沈阳沈北；辽宁沈阳', '[]', '[]', '抗日战争时期', '', '伪职：伪第二军管区参谋长，伪军少将；罪行：协助吉兴策划对吉林抗联的多次大讨伐。；结局：苏军逮捕，抚顺战犯管理所，后期特赦。；在抚顺、清原等地建立特务网络，搜捕抗日地下工作者，曾参与破坏中共南满地下组织。；协助日伪推行经济统制，迫害民族工商业者。；原沈阳士绅，投日后组织协和会，在沈北农村进行思想宣传，瓦解民众抗日意识。；任协和会铁西分会会长，推行奴化宣传，组织青年训练，为日军输送劳工。', '[]', '2026-09-10 09:57:14.063303', '2026-09-10 09:57:14.063303', '辽宁', '抚顺', '清原', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('148a6af2699b4699b4feb03a638ddad2', '刘汉臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江苏_淮安_清江浦；河北沧州运河；黑龙江黑河北安；江苏泰州靖江；江苏_连云港_灌云；江苏连云港灌南；江苏扬州宝应；江苏扬州；辽宁朝阳凌源；河北承德丰宁；河北承德；吉林辽源东辽；江苏_南通_南通经开区；辽宁朝阳北票；河北承德平泉；河北承德；江苏连云港连云港经开区；安徽淮北；辽宁抚顺新宾；河北承德；湖北宜昌；湖北宜昌宜都；江苏南通如东；江苏盐城建湖；内蒙古赤峰宁城；吉林通化柳河；吉林通化；辽宁本溪；内蒙古赤峰敖汉旗；内蒙古、吉林、河北、辽宁；吉林白城；云南普洱西；吉林辽源西安；吉林辽源；辽宁本溪南芬；辽宁本溪', '[]', '[]', '抗日战争时期', '', '负责协和会宣传，组织“勤劳奉仕”运动，强迫民众为日军修路筑堡，收集情报供日军使用。；将抓捕的抗联嫌疑人和无辜百姓投入矫正院，实施酷刑和劳役，致多人死亡，是日伪法西斯统治的忠实执行者。；组织地方自卫团，协助日军维持治安，多次参与袭击抗联小分队，杀害无辜群众。；在西安县（今辽源市）宪兵队任翻译，参与审讯和刑讯抗日志士，多次歪曲供词陷害无辜百姓，协助日军制造多起惨案，如“西安县大逮捕”事件。；率伪军驻防承德、丰宁，多次参与对抗日根据地的“讨伐”，烧毁村庄，掠夺牲畜，在丰宁黑山嘴一带制造多起惨案。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.990768', '2026-09-10 09:57:13.990768', '内蒙古', '赤峰', '敖汉旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('14970c1c5eed413f9dbb70e2851b86a4', '王竹亭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津河北；湖南常德津', '[]', '[]', '抗日战争时期', '', '投日后任伪津海道尹，管辖天津周边各县，推行伪政权法令，配合日军“清乡”行动。', '[]', '2026-09-10 09:57:14.003011', '2026-09-10 09:57:14.003011', '天津', '河北', NULL, NULL, NULL, NULL, NULL, '');
