INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1541d741b8d242bb9f40181f6d7b92dd', '吴金标', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华永康；辽宁沈阳和平；浙江丽水景宁；浙江丽水；福建三明清流', '[]', '[]', '抗日战争时期', '', '为日军控制金华商业，强制摊派“和平救国捐”，垄断粮食贸易，从中牟利。；在丽水沦陷期间，为日军筹措物资，强迫商户缴纳“慰劳金”，并出卖抗日商人名单。；清流县经济汉奸，为日军收购粮食、木材等物资，垄断当地贸易，配合日军经济掠夺。', '[]', '2026-09-10 09:57:14.049497', '2026-09-10 09:57:14.049497', '浙江', '丽水', '景宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1543851129794165abaa8682028c7afd', '易季猷', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（随州籍省级汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：伪湖北省政府建设厅第二科长；罪行：曾都区洛阳镇人。日本东京宏文学院毕业。抗战期间任伪湖北省政府建设厅第二科长、中日文化协会武汉分会会员', '[]', '2026-09-10 09:57:14.071524', '2026-09-10 09:57:14.071524', '湖北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1545ed353b8c45afaa24bfd354de0c57', '马骥材', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠；安徽滁州明光；安徽阜阳临泉；安徽阜阳；山西阳泉城区；安徽安庆宜秀；安徽安庆；安徽安庆；安徽安庆怀宁；安徽亳州利辛；安徽阜阳', '[]', '[]', '抗日战争时期', '', '阜阳为皖北重镇，邻近亳州、利辛，马任伪县长期间配合日军扫荡，推行保甲连坐。；蚌埠人，投敌后任伪蚌埠市市长，在皖北重镇蚌埠推行伪政，为日军提供情报与物资支持。；怀宁本地士绅，1938年安庆沦陷后出面组织伪怀宁县维持会，后任伪怀宁县知事，为日军征粮、派夫、维持治安，是怀宁地区直接附逆的地方伪政权头目。；在安庆沦陷期间担任伪警察头目，配合日军搜捕抗日人士，控制安庆城区治安。；安庆沦陷后投靠日军，任伪安庆商会会长，协助日军对安庆工商业进行控制和掠夺，为日伪筹集军需物资。；安庆商界附逆人物，参与伪维持会，协助日军控制安庆商业与物资调配，为占领军提供经济支持。；安庆商界人物，日军占领安庆后与伪政权合作，协助筹款筹粮、维持商业秩序，为占领当局服务。；嘉山县（今明光市）人，抗战期间任伪嘉山县县长，配合日军控制津浦铁路沿线，征发民夫修筑工事，镇压当地抗日活动。；在亳县、阜阳一带组织伪政权和伪军，配合日军扫荡皖北抗日根据地，残害抗日军民。', '[]', '2026-09-10 09:57:14.004440', '2026-09-10 09:57:14.004440', '安徽', '蚌埠', '利辛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('154bc31fd8e34c01b2d88b1793f0dc44', '王贤宾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳新民；辽宁抚顺新抚；辽宁', '[]', '[]', '抗日战争时期', '', '指挥伪警察抓捕抗日分子，协助日军实施“归屯并户”，制造无人区。；指挥伪警察在新民地区抓捕抗日游击队员，破坏地下组织，多次参与“讨伐”行动。', '[]', '2026-09-10 09:57:14.063267', '2026-09-10 09:57:14.063267', '辽宁', '抚顺', '新抚', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('156967f5668543118b87bd9420510ad4', '陈孝顺', NULL, NULL, NULL, NULL, 'exact', 'exact', '坝埂头水路口岸', '[]', '[]', '抗日战争时期', '', '伪职：坝埂头叛徒特务；罪行：原我方人员叛变，加入崔光汉特务武装；利用码头便利搜集来往人员情报，破坏沿江地下交通线。；结局：解放后镇反镇压。', '[]', '2026-09-10 09:57:14.077846', '2026-09-10 09:57:14.077846', '安徽', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1589a55764744356a27bd6e260959844', '道尔吉', NULL, NULL, NULL, NULL, 'exact', 'exact', '乌拉特中旗；库伦旗；杭锦旗', '[]', '[]', '抗日战争时期', '', '伪职：伪地方武装头目；配合伪蒙古军在杭锦沿黄草原劫掠，抓捕支援八路军的牧民。；结局：1944 被地方抗日武装击毙；伪职：蒙旗下层官员，受伪蒙疆拉拢；向包头伪政权报送草原情报，鼓动部分牧民附日。；结局：战后管制处理；伪职：伪警察告密分子；出卖加林台起义计划，致使多名爱国警察被捕牺牲，获伪满勋章奖励。；结局：1945 被内部人员击毙', '[]', '2026-09-10 09:57:14.071828', '2026-09-10 09:57:14.071828', '内蒙古', '通辽', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('158ceb82a5cc4b2cb4e9df4bd49f414e', '李树声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古赤峰巴林左旗；内蒙古赤峰宁城；内蒙古呼伦贝尔牙克石；山西忻州五寨；归绥；内蒙古赤峰翁牛特旗；黑龙江佳木斯；山东潍坊坊子', '[]', '[]', '抗日战争时期', '', '伪职：第二任伪厚和市市长；原旧官僚，鼓吹 “东亚圣战”，强征铜铁、粮食、劳工资敌，推行保甲、奴化教育。；结局：汉奸罪判 15 年徒刑，入狱不久患病死亡；组织伪保安队，配合日军扫荡抗日根据地，抓捕并杀害抗日军民。', '[]', '2026-09-10 09:57:13.989387', '2026-09-10 09:57:13.989387', '内蒙古', '呼伦贝尔', '牙克石', NULL, NULL, NULL, NULL, '');
