INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('161afbfce6f74151ba24648961af383b', '李希尧', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明五华；云南昆明；云南昆明；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '出任伪昆明县县长，推行日伪政令，征发民夫、粮食供给日军，协助建立伪保甲制度，镇压抗日活动。；昆明商界人士，抗战期间与日伪经济合作，为日军筹措军需物资，垄断当地贸易，从中牟利。', '[]', '2026-09-10 09:57:13.980910', '2026-09-10 09:57:13.980910', '云南', '昆明', '五华', NULL, NULL, NULL, NULL, '');
