INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('165cb3205fa243288d557a93a49fa089', '张明远', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安新干；河南南阳', '[]', '[]', '抗日战争时期', '', '河南南阳人，抗战期间投敌，任伪维持会干事，协助日军办理行政事务，推行伪化政策。；江西新干人，投敌后任伪新干县长，协助日军统治新干地区，迫害抗日群众。', '[]', '2026-09-10 09:57:14.039770', '2026-09-10 09:57:14.039770', '江西', '吉安', '新干', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1663d9c5b4c0445da9d9a8affb3e927b', '尹永祯', NULL, NULL, NULL, NULL, 'exact', 'exact', '营口', '[]', '[]', '抗日战争时期', '', '伪职：伪营口市市长（华人）；罪行：伪满设市后华人市长，实权归日本副市长；协助推行保甲、劳工征用、物资统制，执行战时经济掠夺政策。；结局：光复后逮捕，汉奸罪惩处。', '[]', '2026-09-10 09:57:14.082321', '2026-09-10 09:57:14.082321', '辽宁', '营口', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1664c1c39e9447c98956bbfffafc46dd', '黄振球', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西贺州；广西梧州', '[]', '[]', '抗日战争时期', '', '梧州地区维持会头目，为日军筹粮、筹款，协助日军控制西江航运。', '[]', '2026-09-10 09:57:14.033048', '2026-09-10 09:57:14.033048', '广西', '贺州', NULL, NULL, NULL, NULL, NULL, '');
