INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('166e7ac60c1e41bf8e2068b6dcdd7d27', '常栋彝', NULL, NULL, NULL, NULL, 'exact', 'exact', '绥化县城', '[]', '[]', '抗日战争时期', '', '伪职：伪绥化思想矫正院院长；光复后绥化维持会会长；罪行：大地主，投靠日寇掌管思想矫正院，抓捕迫害不满伪满百姓；日本投降后网罗伪警特务组建维持会、国民党党部，勾结土匪图谋暴乱，对抗民主政权绥化新闻网。；结局：1946 年除夕公审枪决绥化新闻网。', '[]', '2026-09-10 09:57:14.085169', '2026-09-10 09:57:14.085169', '黑龙江', '绥化', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1683ac1cdafa40d699692c6a361b9fa0', '霍老四', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸峰峰矿', '[\"霍振海\"]', '[]', '抗日战争时期', '', '原为会道门首领，被日军收编后，率红枪会成员为日军站岗放哨，袭击八路军武工队，残害群众。', '[]', '2026-09-10 09:57:14.045202', '2026-09-10 09:57:14.045202', '河北', '邯郸', '峰峰矿', NULL, NULL, NULL, NULL, '');
