INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('168c6758341645c38376afba5396c6aa', '陶希圣', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城；湖北黄冈', '[]', '[]', '抗日战争时期', '', '安徽宣城人，曾参与汪伪政权筹建，后脱离并揭露汪日密约。；湖北黄冈人，参与汪伪政权初期宣传；与湖南衡阳无直接关联。', '[]', '2026-09-10 09:57:14.007950', '2026-09-10 09:57:14.007950', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1691b02224cb41adb4000fd6d47f4c85', '李干臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东泰安东平；山东济南莱芜；山东济南济南高；山东济南章丘', '[]', '[]', '抗日战争时期', '', '任伪泰安道尹，管辖包括莱芜在内的地区，推行日伪政策，镇压抗日。；统领伪保安团在东平境内配合日军扫荡，捕杀抗日人员。；在章丘地区推行伪政，配合日军扫荡，残害抗日军民。', '[]', '2026-09-10 09:57:14.014836', '2026-09-10 09:57:14.014836', '山东', '泰安', '东平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1693a70c93964ea893b07dfcb2f8a78c', '张万昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽源', '[]', '[]', '抗日战争时期', '', '伪职：伪西安县总商会会长；罪行：依附日伪，摊派报国捐，为矿山、日军筹措物资，盘剥工商业。；结局：没收财产，判处徒刑。', '[]', '2026-09-10 09:57:14.078010', '2026-09-10 09:57:14.078010', '吉林', '辽源', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('169ac421e9de4be8a797a745b109e9d5', '李钟万', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边龙井；吉林_延边_汪清', '[]', '[]', '抗日战争时期', '', '以“反满抗日”罪名审判爱国志士，判处大量死刑和重刑，维护日本殖民法律秩序。；强制推行“粮谷出荷”，搜刮粮食供日军，导致延边地区严重饥荒，饿殍遍野。', '[]', '2026-09-10 09:57:13.998578', '2026-09-10 09:57:13.998578', '吉林', '延边', '龙井', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16a8c582a0bf4f0babf3ee7df2a51d68', '杨宇霆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁锦州；辽宁抚顺顺城；辽宁鞍山千山；辽宁抚顺；辽宁本溪', '[\"注：非直接汉奸，但需澄清\", \"注：非汉奸，但需澄清\", \"注：早亡，不列入\"]', '[]', '抗日战争时期', '', '虽早年是奉系，但九一八后曾与日本秘密接触，试图在辽宁地区建立傀儡政权，后因内部矛盾未果。；杨宇霆于1929年被张学良处决，不在抗战时期活动，故不列入。', '[]', '2026-09-10 09:57:14.063191', '2026-09-10 09:57:14.063191', '辽宁', '抚顺', '顺城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16adc5f304c547969228c621c3bd6a84', '孙国栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西宜春；江西南昌；广东韶关曲江；广东韶关；江西九江修水；黑龙江伊春汤旺；黑龙江伊春；黑龙江佳木斯东风；黑龙江齐齐哈尔；黑龙江伊春金林；黑龙江伊春；内蒙古赤峰巴林左旗；内蒙古赤峰宁城；江西抚州广昌；江西抚州；黑龙江佳木斯郊区；黑龙江佳木斯；湖北十堰房县；黑龙江伊春大箐山；黑龙江伊春嘉荫；江西宜春高安；江西宜春上高；江西宜春', '[]', '[]', '抗日战争时期', '', '在高安地区建立伪警察体系，配合日军搜捕抗日人员，镇压民众反抗。；在宜春与上高交界地区组织维持会，协助日军修筑据点，征发民夫。；佳木斯地方士绅，日军占领佳木斯后出面组织维持会，为日军筹粮筹款、招募劳工，协助建立伪政权。；汪伪广东绥靖军军官，率伪军配合日军在广东包括韶关周边地区进行清乡与扫荡。；在伊春地区担任伪保甲长，协助日军监控民众，举报抗日分子，推行保甲制度。；佛山县（今嘉荫县，属伊春市）维持会头目，协助日军控制黑龙江沿岸，征发劳工、物资，配合日军封锁抗日联军。；在东乡、抚州北部地区为日军筹粮筹款，组织伪政权，协助日军扫荡抗日根据地。；在汤原地区组织维持会，为日军筹粮筹款、提供情报，协助日军镇压汤原抗日游击队和当地抗日群众，其活动范围接近伊春汤旺地区。；在同江地区任伪县长，推行殖民统治政策，配合日军对黑龙江沿岸抗日武装的封锁。；伪满宁城县警务科长，在宁城地区负责警察特务系统，搜捕抗日人员，配合日军扫荡抗日根据地。；湖北房县人，抗战期间投敌，任伪房县警察局局长，协助日军维持房县治安，搜刮民财。；协助伪县长处理政务，参与征粮、派夫等伪化工作，为日军侵略提供后勤支持。；在南昌地区组织伪维持会，协助日军控制赣中交通，迫害抗日人员。', '[]', '2026-09-10 09:57:13.991352', '2026-09-10 09:57:13.991352', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16b189bf89384fe58aeae0ba5df67a7c', '胡庆林', NULL, NULL, NULL, NULL, 'exact', 'exact', '潍县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸特务（坊子宪兵队潍县分队）；罪行：坊子宪兵队潍县分队汉奸特务，将于乃武枪杀', '[]', '2026-09-10 09:57:14.076466', '2026-09-10 09:57:14.076466', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
