INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16e020cd2ccc4edd8978bc69685a1ba5', '李效民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城陵川；山西；山西吕梁；山西吕梁石楼；山西吕梁离石', '[]', '[]', '抗日战争时期', '', '率伪军在中阳、石楼一带袭击八路军游击队，杀害群众。；负责在离石推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，并收集抗日情报供日军。；投靠日军后出任晋城县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众，破坏地下抗日组织。；投靠日军，组织维持会，为日军征粮派款，协助日军建立伪政权，镇压抗日群众。；组织伪维持会，为日军征粮派款，协助日军建立伪政权，镇压抗日群众。', '[]', '2026-09-10 09:57:14.019476', '2026-09-10 09:57:14.019476', '山西', '吕梁', '离石', NULL, NULL, NULL, NULL, '');
