INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16f3068e7b0c485385610a127936e8c6', '徐文达', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波慈溪；浙江衢州常山；浙江衢州；江苏镇江句容', '[]', '[]', '抗日战争时期', '', '组织商会为日军提供粮食、布匹等物资，强迫商户缴纳“慰劳金”。；负责为伪政权征收苛捐杂税，搜刮民财，供日军军需。；衢州沦陷初期组织伪维持会，为日军提供物资和情报，协助日军建立殖民统治秩序。；任伪县长期间推行日伪政权法令，强征民夫修建碉堡，配合日军清乡扫荡，迫害抗日家属', '[]', '2026-09-10 09:57:14.036894', '2026-09-10 09:57:14.036894', '江苏', '镇江', '句容', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('16faf8dbd504457ba38e4bf9c0d24b3f', '王仲实', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽池州贵池', '[]', '[]', '抗日战争时期', '', '在贵池推行奴化教育，强制使用日伪教材，组织学生参加亲日宣传活动。', '[]', '2026-09-10 09:57:14.008627', '2026-09-10 09:57:14.008627', '安徽', '池州', '贵池', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('170535c66a0c46e0befcbdbcad738521', '陈国瑞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北承德丰宁；河北；河北_保定_定兴；辽宁葫芦岛南票；山西阳泉矿区；河北邢台；河北邢台南宫；河北承德围场；河北承德鹰手营子矿；河北承德兴隆', '[]', '[]', '抗日战争时期', '', '为日军征收苛捐杂税，强抢民间物资，导致百姓负担沉重，部分农户破产。；在丰宁推行日伪“治安肃正”政策，组织汉奸自卫团，强征粮食，配合日军“三光”政策，迫害抗日家属，破坏地下抗日组织。；在承德地区组织伪警察特务，搜捕抗日地下人员，破坏抗日组织，多次带队“清乡”残害百姓。；积极宣传‘日满亲善’，推行奴化教育，搜集抗日情报，协助日军实施‘三光政策’，在兴隆地区犯下罪行。；任伪承德县县长期间，推行保甲制度，强征粮税，协助日军建立“无人区”，迫害百姓，破坏抗日根据地。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.040881', '2026-09-10 09:57:14.040881', '河北', '承德', '丰宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('170e3989de6a4c45bc869255c9a8bc51', '黄子卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州临武；湖南永州东安；湖南永州；山西阳泉城区；湖南郴州安仁；湖南长沙；湖南株洲渌口；湖南衡阳南岳；湖南衡阳；湖南衡阳', '[]', '[]', '抗日战争时期', '', '任伪岳阳警察局长，协助日军搜捕抗日人员，勒索市民，控制岳阳城区治安。；1944年日军侵占临武期间，出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领秩序。；湖南人，日军第四次长沙会战占领长沙后，出任伪长沙县长，为日军征粮、拉夫、维持治安；活动范围在长沙一带，与郴州、安仁无直接关联。；衡阳沦陷期间，部分商会人士与日军合作，协助摊派物资、维持市场，黄子卿被地方史料提及。；日军侵占永州期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序。；汪伪湖南省政府警务处长，负责湖南沦陷区伪警察事务，其管辖范围包括衡阳地区，协助日军维持伪统治。；在湘潭、渌口地区组织伪维持会，为日军征集物资，协助日军扫荡。', '[]', '2026-09-10 09:57:14.058060', '2026-09-10 09:57:14.058060', '湖南', '株洲', '渌口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('17114b7999ec4b1bbea4b2e397cdb0d2', '赵其休', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门开平；河北唐山开平；广东江门鹤山；辽宁沈阳大东；广东江门新会；广东江门；广东江门江海；广东江门；广东江门台山；广东江门', '[]', '[]', '抗日战争时期', '', '在江门地区推行奴化教育，篡改教材，宣传“大东亚共荣圈”，协助日军进行文化侵略，影响鹤山等地学校。；开平沦陷期间组织伪维持会，协助日军统治开平及邻近地区，征粮派款，压迫民众。；江门沦陷时期与日军合作，参与伪维持会与商会事务，为日伪筹款筹粮。；江门沦陷后依附日伪，控制商会为日军筹措物资，协助推行伪化经济统治。；江门沦陷后依附日伪，以商会名义为日军筹款筹粮，协助维持伪政权经济统治。；新会沦陷后投敌，历任伪维持会会长、伪县长，配合日军在江门、新会地区推行治安强化运动，搜捕抗日人员。；新会沦陷初期参与组织伪维持会，协助日军安民、征粮、建立伪基层政权。', '[]', '2026-09-10 09:57:14.028494', '2026-09-10 09:57:14.028494', '广东', '江门', '台山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1711df44574a450fa93b1a3b67f00c97', '王四毛', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀仁', '[]', '[]', '抗日战争时期', '', '伪职：伪怀仁讨伐队头目；罪行：带队袭扰怀仁南部山区，抓捕抗日干部。；结局：被武工队锄奸击毙', '[]', '2026-09-10 09:57:14.081151', '2026-09-10 09:57:14.081151', '山西', '朔州', NULL, NULL, NULL, NULL, NULL, '');
