INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('177c6166b3464b659372d626821bf76e', '陈国桢', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆州沙市；湖北荆州江陵；浙江丽水松阳；安徽安庆；浙江温州龙港；浙江温州；浙江衢州衢江', '[]', '[]', '抗日战争时期', '', '汪伪江陵县县长，驻荆州城，推行伪政令、配合日军清乡与物资统制。；强征民工修建军用公路，虐待劳工，致多人死亡。；建立汉奸情报网，向日军提供温州地区抗日组织名单，导致多名地下党员被捕牺牲，并参与策划“清乡”行动。；在衢江地区任伪区长，推行保甲制度，强征壮丁和粮食，为日军提供情报，协助清剿抗日力量。；推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，破坏抗日宣传。', '[]', '2026-09-10 09:57:14.006717', '2026-09-10 09:57:14.006717', '安徽', '安庆', '松阳', NULL, NULL, NULL, NULL, '');
