INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('18eed37e881741fb9e12388d82a56d3b', '王梦古', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江武宁；江西九江；江西九江；江西南昌西湖；江西南昌；江西宜春袁州；辽宁沈阳大东；江西赣州信丰；江西赣州赣县；江西宜春高安；江西宜春上高；江西宜春', '[]', '[]', '抗日战争时期', '', '在赣县参与伪维持会活动，协助日军管理地方事务，为日占区基层附逆人员。；高安沦陷期间组织伪维持会，为日军征集粮食、劳工，并协助建立伪保甲制度。；在宜春推行奴化教育，篡改教材，宣扬“大东亚共荣”，组织学生参加日军宣传集会。；任伪九江县长期间，配合日军推行保甲连坐，征粮征丁，镇压抗日活动。；在宜春县城组织维持会，为日军筹集物资，协助建立伪区、乡政权，上高邻近地区亦受其影响。；日军侵占宜春期间出面组织伪维持会，协助日军征粮、拉夫、维持地方秩序，为日军侵略服务。；九江商人，抗战期间依附日军，出任伪九江商会会长，为日军筹款筹物，协助控制九江经济。；统率伪保安武装配合日军扫荡南昌近郊抗日游击队，捕杀抗日军民，勒索地方。', '[]', '2026-09-10 09:57:14.038877', '2026-09-10 09:57:14.038877', '江西', '九江', '庐山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('18f1f3f7bba940b6bd4c53cf8240f349', '涂允檀', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北黄石阳新；湖北黄石黄石港；湖北_武汉_东西湖；湖北武汉；湖北_武汉_硚口；湖北武汉黄陂；湖北_恩施；广西桂林资源；湖北鄂州鄂城；湖北黄冈；湖北黄冈蕲春；湖北黄冈；湖北武汉；湖北宜昌秭归；湖北宜昌；湖北襄阳；湖北黄冈龙感湖管理；湖北黄冈；湖北_咸宁_崇阳；湖北武汉；湖北_咸宁_嘉鱼；湖北武汉江岸；湖北武汉；湖北_武汉_洪山；湖北宜昌兴山；山西阳泉城区；湖北宜昌；湖北孝感孝昌；湖北孝感；湖北黄石黄石港', '[]', '[]', '抗日战争时期', '', '在伪汉口特别市政府任职，协助日伪管理武汉及周边地区，为日军侵略服务。；在伪湖北省政府任职，推行亲日奴化教育，控制湖北武汉地区教育文化领域。；武汉沦陷初期组织伪汉口市维持会，协助日军维持占领秩序，后任伪职。；掌管伪武汉特别市财政，为日军搜刮民财，征收苛捐杂税，支持伪政权运转与日军军需。；黄冈地区伪教育官员，推行奴化教育，篡改教材，向学生灌输亲日思想。；抗战期间任伪黄石港税务局局长，为日伪征收税款，盘剥当地商民，协助日军对黄石港经济进行控制。；在鄂城推行日语教育与奴化宣传，篡改历史教材，为日军殖民统治服务。；抗战时期在湖北伪政权中任职，参与沦陷区行政事务。；任伪汉口特别市教育局局长，推行奴化教育，篡改教材，向学生灌输亲日思想。；在黄冈地区任伪警察局长，带领伪警察配合日军搜捕抗日志士，镇压民众反抗。；宜昌沦陷后投敌，组织伪宜昌县维持会并任会长，后任伪宜昌县县长，协助日军维持宜昌城区及周边统治。；宜昌沦陷后出面组织维持会，后任伪宜昌县县长，为日军征集粮食、民夫，维持占领区基层统治。；掌管伪武汉教育，推行奴化教育，篡改教材，向学生灌输亲日思想。；列名伪湖北省政府委员，参与伪政权事务。；日军占领黄石后组织维持会，为日军筹集物资、征派民夫，协助维持黄石港地区治安。；湖北黄陂人，抗战期间投敌，任伪汉口市市长，协助日军管理汉口，镇压抗日活动。；抗战后期任伪汉口市市长，配合日军维持汉口地区统治，直至抗战胜利。；孝感沦陷后出面组织维持会，为日军筹粮筹款、拉夫，协助日军维持孝感地区治安。；继任伪汉口特别市市长，推行日伪政策，在汉口地区协助日军进行经济统制与治安强化。；抗战期间投敌，曾任伪汉口特别市市长，在武汉地区协助日军维持殖民统治。；投敌后任伪汉口特别市市长，在汉口地区协助日军维持统治，直至抗战胜利。；抗战期间附逆，任伪汉口特别市市长，在武汉地区为日伪政权服务。；抗战期间附逆，任伪汉口市市长等职，参与日伪在湖北的行政统治。；抗战后期任伪汉口市市长，配合日军维持武汉地区统治。；日军占领宜昌后，出面组织伪宜昌县维持会并任会长，协助日军维持地方秩序、征发民夫与物资。；湖北人，抗战期间任伪湖北省政府委员，并曾兼任伪黄冈县县长，在黄冈地区推行伪化教育。；在湖北伪政权中任职，负责建设事务，协助日军掠夺资源、修建军事设施。', '[]', '2026-09-10 09:57:14.054609', '2026-09-10 09:57:14.054609', '湖北', '武汉', '黄陂', NULL, NULL, NULL, NULL, '');
