INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a221dd726f44a00b97ce0d7bafecabb', '梁耀南', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东清远阳山；广东云浮新兴；广西贵港；辽宁沈阳大东；广东肇庆德庆；广东阳江；河南郑州中牟；广西南宁；广西南宁邕宁；广西贵港港北；云南普洱西；广东肇庆怀集；广东云浮', '[]', '[]', '抗日战争时期', '', '率伪军在连县、阳山交界地区活动，配合日军扫荡抗日游击队，抢掠民财。；控制物资配给，协助日军掠夺阳江农副产品，从中牟利。；出任伪德庆县县长，推行日伪政令，配合日军清乡、征粮，镇压当地抗日武装。；日军第二次入侵广西期间，参与组织伪广西省维持会，为日军在广西的统治出谋划策，并到贵县等地活动。；在占领区推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”。；在邕宁组织维持会，为日军征发粮食、民夫，并参与建立伪基层政权。；在伪新兴县政权中掌管警察事务，配合日军搜捕抗日人员，推行保甲连坐。；在云浮及周边地区为伪军招兵买马，诱降地方武装，配合日军对抗日根据地进行扫荡。；投靠日军后充任伪警察巡官，参与组建伪自卫队，配合日军扫荡怀集周边乡村，搜捕抗日游击队员及地方抗日人士。', '[]', '2026-09-10 09:57:14.024766', '2026-09-10 09:57:14.024766', '广东', '云浮', '新兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a25aefed8424b9e8c14b4b5bd5fbc52', '芜湖绥靖军军官', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽芜湖南陵；安徽芜湖', '[]', '[]', '抗日战争时期', '', '驻防芜湖及南陵部分地区，参与日军“扫荡”，抢劫民财，强征民夫。', '[]', '2026-09-10 09:57:14.009592', '2026-09-10 09:57:14.009592', '安徽', '芜湖', '南陵', NULL, NULL, NULL, NULL, '');
