INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a2abd7622da4c4eb7656fd2e271ed15', '陈其华', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州罗源；乌丘岛、莆田近海', '[]', '[]', '抗日战争时期', '', '伪职：伪和平救国军一路军司令，驻乌丘屿；罪行：驻守乌丘核心据点，岛上设立日军气象站、补给站；管控海上航运，贩运鸦片、日货，截击我方海上交通船；闽中海上游击队曾截获其巨额物资船莆田晚报。；结局：被军统特务诱杀。', '[]', '2026-09-10 09:57:14.062166', '2026-09-10 09:57:14.062166', '福建', '福州', '罗源', NULL, NULL, NULL, NULL, '');
