INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a46929a9e0b4cedb491080455e83f02', '李埏', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹤壁（淇县）', '[]', '[]', '抗日战争时期', '', '伪职：伪职（原国民党淇县县长）；罪行：原为国民党淇县县长，时局恶化后叛国投敌，出任伪职，盘踞老寨山，搜刮百姓，镇压地方抗日力量。1943年在汉奸刘月亭、王跃南策划下投降日军，被编为淇县保安团；结局：抗日武装发起进攻，将其赶出山区据点，退守淇县县城。抗战胜利后继续依附国民党，豫北解放后被抓获归案，接受人民审判', '[]', '2026-09-10 09:57:14.079449', '2026-09-10 09:57:14.079449', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
