INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a5afdb1fef9466c8ca736d640d7b0f8', '龙绳武', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山腾冲；云南保山龙陵；云南保山龙陵；云南保山隆阳；云南保山', '[]', '[]', '抗日战争时期', '', '龙云之子，抗战期间在滇西与日军有接触，其活动范围涉及保山、腾冲一带，但具体附逆行为史料记载有限。；龙云之子，抗战时期在滇西一带拥有地方武装。日军侵占腾冲、龙陵后，其部在滇西局势混乱中一度与日伪方面有接触和妥协传闻，后离开滇西。相关记载多与滇西失守后地方势力动摇、附敌嫌疑有关。；日军侵占龙陵后，出面组织龙陵县维持会，为日军征派民夫、粮秣，协助维持占领区秩序，是龙陵当地较有影响的附逆人物。', '[]', '2026-09-10 09:57:13.979940', '2026-09-10 09:57:13.979940', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a633b5eff7c46d4bc2f9d0a168c81b0', '李海秋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_连云港_连云港经开区', '[]', '[]', '抗日战争时期', '', '任伪警察局长期间，配合日军宪兵队搜捕抗日地下人员，多次参与“清乡”行动，残害无辜百姓。', '[]', '2026-09-10 09:57:14.036814', '2026-09-10 09:57:14.036814', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1a6594f3b4884b6c858d60fd24368c51', '张子英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '宁夏石嘴山；山西；山西吕梁柳林；山西吕梁；山西忻州神池', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军扫荡永和及周边地区，多次袭击抗日游击队，抓捕并杀害抗日军民，掠夺粮食资敌。；率伪军配合日军在吕梁山区多次围剿八路军，杀害抗日军民。；为日军搜集情报，破坏地下抗日组织，参与屠杀抗日志士。；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，杀害八路军伤员，抢劫百姓财物。', '[]', '2026-09-10 09:57:14.003817', '2026-09-10 09:57:14.003817', '宁夏', '石嘴山', '柳林', NULL, NULL, NULL, NULL, '');
