INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b20c69c1031482c90ccaca2b0813e62', '刘凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄元氏；延庆；河北衡水安平；河北衡水；河北邢台平乡；河北邢台；河北；黑龙江双鸭山尖山；黑龙江双鸭山饶河；河北邯郸邱县', '[]', '[]', '抗日战争时期', '', '伪职：伪延庆警备大队长；盘踞延庆城、永宁据点，下乡清乡扫荡。；结局：延庆解放被俘处死；带领伪自卫团配合日军封锁抗日根据地，抢劫百姓财物。；充当日军经济汉奸，控制衡水商会，为日军筹集物资，强迫商户“献金”，垄断粮食贸易。；在邢台东部及平乡一带活动，率伪军袭击八路军游击队，烧毁村庄。；充当日军特务，刺探抗日军情，抓捕并刑讯抗日人员，罪行累累。', '[]', '2026-09-10 09:57:14.043327', '2026-09-10 09:57:14.043327', '河北', '石家庄', '元氏', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b2c9f4a4d4f4555aa11aa961b4fc6f7', '佐藤羡次郎', NULL, NULL, NULL, NULL, 'exact', 'exact', '洛阳城区', '[]', '[]', '抗日战争时期', '', '伪职：日本间谍、特务；罪行：日本北海道人，化名“杨书祥”潜伏洛阳多年，以卖卤豆腐丝为掩护搜集情报，绘制洛阳详尽地形图，为日军轰炸和进攻提供情报；结局：洛阳沦陷后晋升少将，随日军入城', '[]', '2026-09-10 09:57:14.067979', '2026-09-10 09:57:14.067979', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b3138446ef044898761aa230222b2db', '张联第', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林长春宽城；河北承德宽城；河北承德承德高；吉林长春德惠；吉林长春双阳；吉林；吉林松原扶余；吉林松原；吉林_长春_榆树；吉林长春绿园；吉林长春长春净月高；吉林长春；吉林、河北；吉林通化；吉林长春九台；吉林四平伊通；吉林', '[]', '[]', '抗日战争时期', '', '原吉林省政府官员，投日后任伪满吉林省公署参事，参与策划对吉林、四平地区抗日武装的围剿，并协助日军建立“集团部落”。；审判抗日人士，判处大量爱国者死刑或重刑；指挥伪警察在双阳山区围剿抗联小分队，杀害多名游击队员。；在长春及宽城地区组织协和会，收集情报，破坏抗日组织。；在德惠县任伪县长，组织伪警察配合日军清乡，强征粮食和壮丁。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.997279', '2026-09-10 09:57:13.997279', '吉林', '四平', '伊通', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b3148fa9de244d383255c3bdba7eb61', '许锡清', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东潮州饶平；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '日军占领潮安后，出面组织维持会，协助日军安民、征粮、拉夫，维持沦陷区秩序。', '[]', '2026-09-10 09:57:14.029883', '2026-09-10 09:57:14.029883', '广东', '潮州', '饶平', NULL, NULL, NULL, NULL, '');
