INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b3a5cbfb58a4f84b8c05eb385bfc9fa', '杨立言', NULL, NULL, NULL, NULL, 'exact', 'exact', '潘集、凤台北部', '[]', '[]', '抗日战争时期', '', '伪职：伪绥靖六团团长（大褂队）；罪行：土匪投敌，“大褂队” 改编伪军，四处烧杀抢掠、绑票勒索，捕杀抗日干部，多次进攻凤台抗日民主政府，淮上祸害最大伪军头目之一淮南市人民...。；结局：1940 年苏涂村战斗被抗日武装击毙，部队全歼淮南日报。', '[]', '2026-09-10 09:57:14.067508', '2026-09-10 09:57:14.067508', '安徽', '淮南', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b49e185a60d4aa4958fbcfb320245e2', '张问德', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山腾冲；云南德宏梁河；云南保山腾冲；云南昆明安宁；云南保山腾冲', '[]', '[]', '抗日战争时期', '', '云南腾冲人，滇西沦陷后出任腾冲抗日县长，拒绝日伪拉拢，坚持抗日。此条为排除性说明，非汉奸。；张问德在腾冲投敌，出任伪腾冲县维持会副会长，协助日军征粮派夫，参与伪政权活动。；张问德在腾冲沦陷后坚持抗日，拒绝与日军合作，并发表《答田岛书》。其事迹常被用于对照当地附逆者，故不作为汉奸列入，仅说明腾冲伪政权相关背景。；腾冲沦陷后出任抗日县长，坚持敌后抗战，未附逆。', '[]', '2026-09-10 09:57:13.980037', '2026-09-10 09:57:13.980037', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b4d013899cb4de88608803742373f9c', '吴剑秋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西抚州临川；江西南昌', '[]', '[]', '抗日战争时期', '', '在南昌伪政权任职，曾赴抚州、临川等地督导伪化宣传与物资征调，拉拢地方头面人物附逆。', '[]', '2026-09-10 09:57:14.040030', '2026-09-10 09:57:14.040030', '江西', '抚州', '临川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b53a36965114024a0fe187fce661420', '李铭书', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林梨树；吉林_长春_长春净月高；黑龙江黑河爱辉；黑龙江黑河北安；黑龙江大庆肇源；黑龙江大庆肇州；内蒙古呼伦贝尔；吉林船营；黑龙江大兴安岭加格达奇；黑龙江牡丹江海林；黑龙江牡丹江；黑龙江_牡丹江；黑龙江齐齐哈尔讷河；黑龙江鹤岗东山；黑龙江鹤岗；黑龙江哈尔滨双城；黑龙江大兴安岭呼玛；黑龙江鸡西；吉林_长春_九台；吉林松原；吉林松原长岭；吉林高；黑龙江哈尔滨依兰；山东临沂兰山；吉林长春农安；黑龙江鹤岗；黑龙江大兴安岭塔河；北京大兴；黑龙江黑河；黑龙江佳木斯桦川；黑龙江齐齐哈尔；黑龙江鹤岗绥滨；黑龙江鹤岗；吉林四平；黑龙江鹤岗兴安；黑龙江哈尔滨宾县；黑龙江黑河五大连池；黑龙江黑河；黑龙江大兴安岭漠河；黑龙江黑河；吉林白城白城经开区；黑龙江黑河孙吴；吉林四平伊通；黑龙江鹤岗向阳；黑龙江鹤岗；黑龙江齐齐哈尔拜泉；吉林松原松原经开区；吉林松原乾安；吉林长春；吉林辽源；黑龙江_牡丹江_阳明；吉林长春双阳；吉林；吉林松原扶余；吉林丰满；黑龙江牡丹江牡丹江经开区；黑龙江牡丹江；吉林；吉林延边图们；黑龙江牡丹江；黑龙江佳木斯；黑龙江绥化明水；黑龙江绥化；吉林松原乾安；吉林永吉', '[]', '[]', '抗日战争时期', '汪伪政权', '在吉林地区组织协和会，进行反动宣传，搜集抗日情报。；组织协和会分会，为日军募集物资，监视居民言行，举报抗日嫌疑人员，协助日军强征丰满水电站劳工。；伪满四平市（今四平市）市长，配合日军建立“集团部落”，制造无人区，迫害抗日群众。；原伊通地方士绅，投日后任伪满伊通县县长，推行保甲制度，组织汉奸武装，协助日军在伊通地区“清乡”，迫害抗日群众。；协助日军进行思想控制，举报抗日群众，参与“治安肃正”行动。……（共涉及25个地区的犯罪记录）；伪职：伪吉林省秘书长、第二任伪吉林省省长；罪行：熙洽核心副手；主持吉林省伪行政，推行保甲、粮食出荷，强征国兵劳工，镇压吉林抗日武装。；结局：日本投降后被苏军逮捕，关押抚顺战犯管理所，狱中病死。；伪任职务：伪吉林省公署秘书长、伪民政厅厅长，熙洽核心副手，参与组建伪吉林政权。结局：日本投降被苏军逮捕，关押抚顺战犯管理所，狱中病亡', '[]', '2026-09-10 09:57:13.996054', '2026-09-10 09:57:13.996054', '吉林', '丰满', '伊通', NULL, NULL, NULL, NULL, '');
