INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b5984d628984506bd24c3dfe8cf74b6', '陈铁夫', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山三水；广东佛山；河南鹤壁山城', '[]', '[]', '抗日战争时期', '', '佛山沦陷后出面组织伪佛山维持会，协助日军安民、征粮、招募伪警，压迫佛山镇商民。；佛山沦陷后组织伪维持会，协助日军管理佛山镇，推行保甲、征发物资，是佛山本地早期附逆代表人物。；佛山沦陷初期组织维持会，协助日军接管市政，维持秩序并征集物资。；控制南海县伪警察，配合日军搜捕抗日分子，在佛山城区实行宵禁与户口清查。', '[]', '2026-09-10 09:57:14.026201', '2026-09-10 09:57:14.026201', '广东', '佛山', '三水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b5a9d5f6c104372bbd0fc39a0cbf914', '王昭夷', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三沙南沙；海南五指山；海南三沙西沙；海南乐东；海南东方；海南白沙；海南五指山；海南保亭；海南白沙；海南保亭', '[]', '[]', '抗日战争时期', '', '在保亭地区附逆，任伪保亭县县长，协助日军控制五指山外围和保亭一带，组织伪自卫队配合日军对黎族苗族抗日力量进行镇压。；在保亭地区为日军统治服务，组织伪保甲与自卫队。；在保亭地区组织伪维持会，协助日军统治黎族、苗族聚居区，征发劳工。；在白沙地区组织伪政权，配合日军进攻抗日根据地，抓捕抗日人员。；在乐东地区为日军服务，参与伪政权统治，协助日军镇压黎族、苗族抗日力量。；在保亭地区投敌，组织伪政权与伪自卫队，协助日军征发黎族民工、粮食，参与镇压抗日群众。', '[]', '2026-09-10 09:57:14.053556', '2026-09-10 09:57:14.053556', '海南', '三沙', '南沙', NULL, NULL, NULL, NULL, '');
