INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1b92c0fe1f62451493a35dbb0091bba5', '张治邦', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁湖熟赤山', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪镇长，多次向日军通风报信；我方多次警告仍死心塌地附敌，搬迁至湖熟依仗据点作恶。。结局：短枪队伏击，在赤山??湖熟道口被击毙南京市江宁...', '[]', '2026-09-10 09:57:14.078075', '2026-09-10 09:57:14.078075', '江苏', '南京', NULL, NULL, NULL, NULL, NULL, '');
