INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bb3711055114341bf7c051a34b88f98', '陆宗舆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北；北京东城；北京昌平；北京海淀；北京_西城；河北_廊坊；天津滨海；湖南常德津；天津河北；河北廊坊固安；河北廊坊；天津和平；湖南常德津；天津北辰；湖南常德津', '[]', '[]', '抗日战争时期', '', '曾任北洋政府官员，后投靠日伪，在北平担任顾问，参与策划经济统制政策。；原亲日外交官，投日后任伪顾问，参与对北平及昌平地区的殖民政策制定。；在北平担任日伪顾问，参与策划奴化政策，涉及海淀地区学校和文化机构；亲日派人物，参与伪政权活动，协助日本经济掠夺。；在天津组织亲日文化活动，宣传“中日亲善”，麻痹民众抗日意识。……（共涉及9个地区的犯罪记录）；参与日伪对冀中地区的经济掠夺，支持“以战养战”政策。', '[]', '2026-09-10 09:57:13.992922', '2026-09-10 09:57:13.992922', '北京', '东城', '固安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bb3f017869b4a44a6f1c7b6b6ae56e8', '吴稚晖', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏无锡锡山；江苏无锡；江苏无锡江阴；江苏无锡；江苏常州新北；江苏常州；江苏_无锡_新吴', '[\"注：此处为同名误记，实际为吴稚英\"]', '[]', '抗日战争时期', '', '推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”。；无锡沦陷初期出任维持会长，为日军筹粮，协助建立伪政权。；无锡商会头目，投靠日伪后为日军采购物资，控制商业，资助伪政权，压迫商户。；为日军筹措军饷，组织商会为伪政权捐款，强迫商户使用军票，协助日军控制常州商业命脉。', '[]', '2026-09-10 09:57:14.034837', '2026-09-10 09:57:14.034837', '江苏', '常州', '新北', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bbe52101707464fbcef46391f7cfd4e', '周燮卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南张家界桑植；云南普洱西；重庆酉阳；云南普洱西；湖南湘西古丈；湖南怀化沅陵；云南普洱西；云南普洱西；湖南湘西龙山；云南普洱西；湖南湘西泸溪；湖南湘西凤凰；云南普洱西', '[]', '[]', '抗日战争时期', '', '在渝东南、黔东北、湘西交界地区组织伪军，配合日军作战，骚扰抗日后方，残害抗日军民。；无；湘西地区土匪首领，抗战时期曾与日伪方面联系，接受伪军番号，在湘西一带活动，对抗抗日力量。；原国民党军将领，抗战时期投降日军，在湖南地区组织伪军，其活动范围涉及湘西北，曾配合日军进攻湘西抗日根据地。；原国民党地方武装将领，抗战末期在湘西投敌，任伪湘西保安司令，协助日军维持湘西占领区秩序。；湘西地区地方武装首领，抗战期间在湘西一带活动，与日伪势力有联系。；抗战末期在湘西地区组织伪军，配合日军进攻湘西抗日根据地，在古丈、沅陵交界地带活动。；湘西地区人，1944年组织伪湘西自治军，配合日军在湘西进行军事活动，维持伪政权地方秩序。', '[]', '2026-09-10 09:57:14.058348', '2026-09-10 09:57:14.058348', '湖南', '张家界', '桑植', NULL, NULL, NULL, NULL, '');
