INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1be57219ef88446ab10d27949c701381', '黄宇宙', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林灵川；河南安阳龙安；河南安阳；陕西宝鸡', '[]', '[]', '抗日战争时期', '', '在安阳一带参与伪皇协军组建与指挥，配合日军行动，后因内讧被杀。；在豫北参与伪皇协军活动，后于1938年8月与徐靖远等人在安阳水冶镇击毙李福和，率部反正。；华北伪军头目，配合日军作战，对陕西宝鸡抗日后方构成威胁。；原国民党军将领，1937年投敌，任伪皇协军第一军参谋长，后反正。', '[]', '2026-09-10 09:57:14.032405', '2026-09-10 09:57:14.032405', '广西', '桂林', '灵川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bf427956a9a4d819cfc307d42128dbf', '高文宪', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西榆林府谷；陕西榆林', '[]', '[]', '抗日战争时期', '', '在山西伪军中任职，配合日军对晋陕绥边区的袭扰，影响榆林、府谷一带。', '[]', '2026-09-10 09:57:14.064664', '2026-09-10 09:57:14.064664', '陕西', '榆林', '府谷', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bf8a9f25e624524a0a8060b039db79b', '陈允兹', NULL, NULL, NULL, NULL, 'exact', 'exact', '永修县（今属九江）', '[]', '[]', '抗日战争时期', '', '伪职：汪伪永修县县长；罪行：永修县人，1938年永修沦陷后出任伪县长，在日军刺刀下维持殖民统治、征发粮食劳役、管控当地百姓；结局：史料未明确记载其最终审判及结局（来源：永修沦陷期最高伪行政长官，有部分史料记载其任内曾有限度保护百姓，仍属于汉奸范畴）', '[]', '2026-09-10 09:57:14.082039', '2026-09-10 09:57:14.082039', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1bfaf9dd138048fea5aa6cbb63f4b584', '贾振锋', NULL, NULL, NULL, NULL, 'exact', 'exact', '东北', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：沁县伪保安大队长，铁杆汉奸，在太岳区烧杀抢掠，残害群众。结局：抗战胜利后公审枪决', '[]', '2026-09-10 09:57:14.076569', '2026-09-10 09:57:14.076569', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c03aafabaa94b07a42e277395fbf660', '李步青', NULL, NULL, NULL, NULL, 'exact', 'exact', '玉环坎门、楚门', '[]', '[]', '抗日战争时期', '', '伪职：玉环伪组织骨干；罪行：协助李蛰锵经营资敌机构，为日军搜刮渔货物资，胁迫地方百姓。；结局：清算判处有期徒刑玉环史志网。', '[]', '2026-09-10 09:57:14.072300', '2026-09-10 09:57:14.072300', '浙江', '台州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c057e40f4494a8ea47d63038eebd791', '刘雨田', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁_大连_旅顺口；辽宁大连；辽宁；辽宁大连普兰店；普兰店泡子；辽宁大连中山；辽宁大连；辽宁大连沙河口；辽宁普兰店（大连）；辽宁大连瓦房店；辽宁大连', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：关东州厅参事、大连市议员、华商公议会会长，关东都督府嘱托（高级顾问）；罪行：甲午战争主动给日军做向导，参与旅顺大屠杀引路；变卖土地房产捐献两架 “雨田号” 战机；宣扬大东亚共荣奴化思想，拉拢乡绅附逆，迫害爱国志士。；结局：1945 年隐匿潜逃，1951 年抓获公审枪决，至死毫无悔意。；大连地区汉奸，任伪民政署长，推行保甲制度，强征劳工，为日军提供物资。；在大连地区指挥伪警察抓捕抗日志士，协助日军进行特务活动。；旅顺地方士绅，投日后任伪旅顺市市长，配合日军镇压旅顺地区抗日武装。；辽宁普兰店人（原复县），九一八后组织地方维持会，协助日军控制普兰店地区，残害抗日志士。；效忠日本关东军，指挥伪警察搜捕抗日地下组织，多次参与屠杀和镇压大连沙河口地区工人罢工与抗日群众。……（共涉及6个地区的犯罪记录）；伪任职务：老牌汉奸，变卖祖产捐飞机给日军，长期充当日本情报顾问。结局：1951 年 81 岁被捕，公审枪决', '[]', '2026-09-10 09:57:14.062909', '2026-09-10 09:57:14.062909', '辽宁', '大连', '中山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c0a517d75934c4f88fc7cdeed6c4745', '顾锡九', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_南通；江苏南通启东；江苏南通；江苏盐城；江苏南通如东；江苏南通如皋；江苏南通；江苏南通南通经开区；江苏南通；江苏南通海安', '[]', '[]', '抗日战争时期', '', '率伪保安队多次袭击如东抗日根据地，杀害基层干部和群众。；原国民党地方武装头目，后投敌，任伪盐城保安司令，配合日军清乡，捕杀抗日军民，破坏地下组织。；在南通、如皋地区推行清乡，组织伪自卫团，破坏抗日根据地。；指挥伪警察协助日军搜捕抗日分子，破坏地下组织，残害百姓。；任伪南通特别区公署署长，推行日伪奴化教育，强征劳工，协助日军经济掠夺。；日军占领海安后，出任维持会长，为日军提供粮食、情报，组织汉奸武装。；任南通伪县长期间，积极为日军提供情报，组织伪保安队配合日军扫荡，破坏抗日根据地，残害抗日干部。', '[]', '2026-09-10 09:57:14.033959', '2026-09-10 09:57:14.033959', '江苏', '南通', '南通经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c1fc99bec414c31920c95eccd34d5fe', '章宗祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京昌平；北京_西城；河北廊坊；北京、天津、河北；天津河北；湖南常德津；北京东城；河北廊坊；河北廊坊固安；天津北辰；湖南常德津；天津和平；湖南常德津', '[]', '[]', '抗日战争时期', '', '北洋政府前官员，北平沦陷后出任伪职，为日伪政权提供政治咨询，协助维持殖民秩序。；原亲日官僚，投日后在北平为日伪出谋划策，涉及昌平地区资源控制。；参与伪政权，为日本侵华政策辩护。；在天津分会任职，参与处理伪政权事务，支持日军侵略政策。；为日伪政权出谋划策，参与起草奴化政策文件，影响天津伪政府决策。……（共涉及7个地区的犯罪记录）；为日伪在廊坊地区推行保甲制度出谋划策，协助镇压抗日运动。', '[]', '2026-09-10 09:57:13.992944', '2026-09-10 09:57:13.992944', '北京', '东城', '固安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c3597d761d347bbb6a72a52dfd3e010', '陈子褒', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门', '[]', '[]', '抗日战争时期', '', '在江门地区掌管伪警察力量，配合日军搜捕抗日人员，维持沦陷区秩序。', '[]', '2026-09-10 09:57:14.028768', '2026-09-10 09:57:14.028768', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c37e61e1e0144cd82e249df0d41bbb4', '郭振如', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹿邑县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸团长；罪行：1939年4月25日，率两个团的汉奸武装配合日军突袭鹿邑县城', '[]', '2026-09-10 09:57:14.068277', '2026-09-10 09:57:14.068277', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c4479824d3a4bbb85dcc3e847e8e1d8', '丁叔言', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊奎文；山西阳泉城区；山东潍坊临朐；山东潍坊潍坊滨海经开区；山东_潍坊_潍城；山东潍坊；山东_潍坊_寿光；山东潍坊高密；山东潍坊；山东济南；山东潍坊青州', '[]', '[]', '抗日战争时期', '', '任伪潍县维持会会长，协助日军建立伪政权，维持地方秩序。；在潍坊地区担任伪鲁东道尹，协助日军统治，推行奴化教育。；山东人，投靠日伪政权，在济南及山东各地推行奴化教育，编写亲日教材，为日军侵略培养顺民，其教育政策覆盖潍坊、诸城等地。；潍县商人，抗战期间与日伪合作，控制潍县商会，为日军征集物资、推行伪币，在经济领域附逆，活动于潍县城区。；在潍县推行日伪奴化教育，改编教材，组织亲日宣传活动。；在潍县推行奴化教育，协助日军控制学校。；控制潍县工商业，为日军筹集军需物资，强制商户纳捐，协助日军经济统制。；潍县商人，投靠日军后任伪商会会长，为日军征集物资，协助经济统制。；青州沦陷初期组织维持会，协助日军稳定占领秩序。', '[]', '2026-09-10 09:57:14.016549', '2026-09-10 09:57:14.016549', '山东', '潍坊', '寿光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1c4895d8081f4f35bac5a4e2090d5b54', '杨子荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏连云港东海；甘肃甘南合作', '[]', '[]', '抗日战争时期', '', '控制合作社，垄断物资配给，克扣百姓口粮，为日军搜刮战略物资。', '[]', '2026-09-10 09:57:14.036759', '2026-09-10 09:57:14.036759', '江苏', '连云港', '东海', NULL, NULL, NULL, NULL, '');
