INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1d4edde34bd64ed2917d089dc98c9b39', '汪伪政权绍兴县知事', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴柯桥；山西吕梁兴县', '[\"姓名不详\"]', '[]', '抗日战争时期', '', '在日占期间主持绍兴县伪政权，推行日伪统治政策，协助日军征粮、征税，镇压抗日活动。；在日占期间主持绍兴县伪政权，协助日军推行‘清乡’和物资统制，镇压抗日活动。具体姓名因档案缺失未详。', '[]', '2026-09-10 09:57:14.051939', '2026-09-10 09:57:14.051939', '浙江', '绍兴', '柯桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1d511d7452e5435cba7dcfc1392e8b50', '曹茂琮', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南永州零陵；湖南郴州安仁；湖南郴州；湖南郴州宜章', '[]', '[]', '抗日战争时期', '', '在日军侵占零陵期间，出面组织伪维持会，协助日军征粮、派夫、维持治安，镇压抗日民众。；1944年日军侵入宜章后，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，是宜章当地有记载的附逆者。；湖南郴县人，1944年日军侵入郴州地区后，出面组织伪郴县维持会，为日军筹粮、派夫、维持地方秩序，是郴州地区有明确记载的附逆者之一。', '[]', '2026-09-10 09:57:14.058914', '2026-09-10 09:57:14.058914', '湖南', '永州', '零陵', NULL, NULL, NULL, NULL, '');
