INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1d9220c0220e4d4fb9c0e2bd893f5832', '杨森', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；贵州六盘水六枝特；重庆涪陵；四川成都金牛；四川成都；贵州贵阳；贵州黔南荔波；四川_成都_金堂', '[]', '[]', '抗日战争时期', '', '原川军将领，后投靠日军，任伪四川省保安司令，率伪军配合日军扫荡抗日根据地。；抗日战争期间曾率部投靠日伪，任伪军头目，在四川地区进行伪化活动。；在四川、贵州交界地区与日军有秘密往来，其部队在成都附近曾与伪军配合行动。；原为川军将领，抗战期间在成都、邛崃地区与日军暗通款曲，纵容部下投敌，协助日军维持地方秩序，迫害抗日人士。；黔南事变期间在独山、荔波一带组织维持会，为日军带路、征集物资，并参与组织伪保安队。；率部在重庆、涪陵地区配合日军扫荡，镇压民众抗日活动。；协助日军对贵州地区实施经济掠夺，控制物资流通，为日军提供军需物资，压榨当地百姓。；在成都及川东地区与伪政权合作，组织伪军，参与清乡，迫害抗日家属。', '[]', '2026-09-10 09:57:14.001788', '2026-09-10 09:57:14.001788', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
