INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1e8c72edf5d64c9db10bfae188df02d8', '李以锦', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄滕州；山东枣庄；山东临沂郯城；山东枣庄市中；山西阳泉矿区；山东临沂；山东枣庄薛城；山东枣庄', '[]', '[]', '抗日战争时期', '', '郯城沦陷后组织维持会，任伪县长，为日军征粮派款、搜集情报，协助日伪军控制郯城及周边地区。；在峄县、枣庄地区组织伪保安队，协助日军维持占领区秩序，参与抓捕抗日人员，征敛物资。；在枣庄矿区组织维持会，为日军掠夺煤炭资源服务，强迫矿工劳动，迫害抗日矿工。；日军占领滕县后，出任伪滕县县长，在滕县、枣庄北部一带协助日军建立伪政权，推行保甲、征粮、抓丁等政策。；掌管伪警察武装，在临沂城乡搜捕抗日人员，推行保甲连坐，勒索民众。', '[]', '2026-09-10 09:57:14.012723', '2026-09-10 09:57:14.012723', '山东', '临沂', '兰陵', NULL, NULL, NULL, NULL, '');
