INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f09ff1352ec44c29530744698f5a874', '孙步月', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳；鹤壁（浚县）；滑县（今属安阳）', '[]', '[]', '抗日战争时期', '', '伪职：反共自卫团团长；罪行：1941年4月与杨振兰一同占领抗日根据地安化城（二安）村；伪职：豫北剿共副司令、浚滑内黄3县边区反共自卫团团长；罪行：1938年秋投靠日寇，组建浚、滑、内黄3县边区反共自卫团，被日寇封为“豫北剿共副司令”。以郭小寨为中心构建大型伪军据点，多次配合日军对沙区抗日根据地进行扫荡。先后杀害革命干部及群众420余人，烧毁房屋3000余间；结局：1945年4月，冀鲁豫军区发起讨伐战斗，经三昼夜激战，其主力被八路军彻底歼灭，孙步月本人在战斗中被俘，随后依法惩处。善堂镇烈士纪念碑前雕有双手反缚、双腿下跪、背插亡命旗石像，即孙步月', '[]', '2026-09-10 09:57:14.048699', '2026-09-10 09:57:14.048699', '河南', '濮阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f0a109d2454481ab074cba73d90e9ba', '顾玉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '颍上、阜阳交界', '[]', '[]', '抗日战争时期', '', '伪职：日伪派遣联络员；罪行：往返凤台伪政权与阜阳后方，传递情报，掩护敌特潜入，引诱部分人员投奔敌占区。；结局：武工队锄奸行动就地处决。', '[]', '2026-09-10 09:57:14.088218', '2026-09-11 02:31:17.444967', '', '阜阳', NULL, NULL, NULL, NULL, NULL, '');
