INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f1fda43b6ef4aa89c0d2fea0f6aa100', '张我东', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东潮州饶平；广东汕头；广东汕头龙湖', '[]', '[]', '抗日战争时期', '', '协助日军在汕头建立初期殖民统治机构，招募伪职人员，维持地方秩序。；主办伪报纸，为日军侵略张目，进行反共与奴化宣传。；在汕头沦陷区出任伪商会会长，为日军筹款筹粮，协助日军经济掠夺，影响潮汕各地。', '[]', '2026-09-10 09:57:14.028124', '2026-09-10 09:57:14.028124', '广东', '汕头', '龙湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f223ec5041f47fea373a5bef84b1375', '高景祚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄新华；河北；河北唐山唐山高；河北唐山', '[]', '[]', '抗日战争时期', '', '在丰润县（今属唐山市）推行伪政权，组织“自卫团”配合日军扫荡，强征民夫修筑炮楼，残害抗日家属。；主持清乡活动，建立保甲制度，强迫村民报告八路军行踪，多次带队烧杀抢掠。', '[]', '2026-09-10 09:57:14.041709', '2026-09-10 09:57:14.041709', '河北', '唐山', '唐山高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f2f0c13727f49a4b2ef25375569296c', '管翼贤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京丰台；安徽芜湖镜湖；北京大兴；浙江杭州西湖；浙江杭州；北京、河北；安徽芜湖镜湖；安徽芜湖；湖北蕲春；河北石家庄井陉矿；北京海淀；江苏南京江宁；辽宁沈阳和平；河北石家庄；江苏南京浦口；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '华北伪临时政府', '伪任职务：伪华北《新民报》总编辑，北平头号新闻文化汉奸，大肆宣传日伪理论。结局：初判无期，1951 年北京军管会判处死刑执行枪决；控制北平及丰台地区报刊舆论，查禁抗日言论，为日伪宣传服务。；在北平控制舆论，在大兴地区散发汉奸报纸，美化日军侵略，污蔑抗日军民。；在北平（含海淀）控制舆论，宣传“大东亚共荣”，为日伪张目，污蔑抗日活动；原新闻界人士，投日后任伪石家庄市市长，在井陉矿区强化治安，组织伪警察镇压矿工反抗，为日军提供煤炭资源。；继任伪石家庄市长，协助日军控制交通线，在平山地区强征民夫修筑碉堡和封锁沟。', '[]', '2026-09-10 09:57:13.993197', '2026-09-10 09:57:13.993197', '北京', '丰台', '镜湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f3944e29bcb460ca602ea4afbd85730', '谢文东', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林经开区；吉林；黑龙江佳木斯东风；黑龙江佳木斯；黑龙江佳木斯前进；黑龙江佳木斯；黑龙江双鸭山友谊；黑龙江双鸭山；黑龙江佳木斯向阳；黑龙江佳木斯；黑龙江鹤岗兴山；黑龙江鹤岗；黑龙江佳木斯桦南；黑龙江佳木斯；黑龙江哈尔滨南岗；黑龙江哈尔滨；依兰、勃利、桦南，合江全境；黑龙江佳木斯郊区；黑龙江佳木斯；辽宁宽甸（长期活动黑龙江依兰）；黑龙江伊春汤旺；黑龙江齐齐哈尔；湖北武汉东西湖；湖北武汉；黑龙江鸡西鸡冠；黑龙江鸡西；广西桂林灵川；广西柳州三江；黑龙江七台河勃利；陕西西安莲湖', '[\"注：早期抗联，后叛变\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：原为抗联第八军军长，1939 年率全军投敌，伪满三江省协和会头目，协助日军讨伐抗联。结局：日本投降后沦为北满巨匪，1946 年勃利公审枪决；伪职：原抗联第八军军长，投降后伪三江省讨伐队头目；罪行：土龙山暴动起家，1939 年率抗联八军大部投降日寇；带领伪军进山讨伐抗联，残害抗日军民；日本投降后投靠国民党，成为 “四大旗杆” 匪首，制造多起屠杀惨案佳木斯广播...。；结局：1946 年依兰公审枪决。', '[]', '2026-09-10 09:57:14.000551', '2026-09-10 09:57:14.000551', '吉林', '经开区', '灵川', NULL, NULL, NULL, NULL, '');
