INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f7933025bbd4dd78f2ed1481c6af01d', '李冠英', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀仁', '[]', '[]', '抗日战争时期', '', '伪职：伪怀仁县县长；罪行：建立怀仁伪县公署，修筑炮楼，配合日军扫荡雁北西部山区。；结局：战后汉奸罪判刑', '[]', '2026-09-10 09:57:14.078469', '2026-09-10 09:57:14.078469', '山西', '朔州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f7991a0446648128a7ca1a82c349515', '汪屺', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州；云南普洱西；广东江门开平；河北唐山开平；广东佛山；山西阳泉城区；广东江门恩平；广东江门；广东_湛江；广西桂林恭城；云南普洱西；广东_江门_江海；广东湛江赤坎；广东_韶关_武江；广东江门新会；广东广州；广东_韶关_乐昌；广东广州；广东_韶关_乳源；广东_云浮_郁南；广东_韶关_曲江；广东韶关', '[]', '[]', '抗日战争时期', '', '在伪广东省政府任职，配合日军进行经济掠夺和物资统制。；曾任汪伪广州市长，负责广州城区伪政权的行政运作，协助日军实施物资统制与治安强化。；负责伪广东财政，为日伪筹措经费，压榨沦陷区民众，包括佛山、三水一带。；在广东伪政权中负责警务，配合日军搜捕抗日人士、维持占领区治安。；掌管广东伪警察系统，参与镇压抗日活动、搜捕抗日人员。；负责日伪广东民政与基层保甲，协助日军征发劳役与物资。；掌管伪广东警察系统，镇压抗日活动，搜捕抗日人员。；汪伪广东省政府委员兼民政厅厅长，负责伪政权民政事务，配合日军实施保甲与治安控制。；汪伪广东地方政权人物，活动于广州，未见与广西柳州直接关联。；曾任汪伪广州市长，协助日伪维持广州统治秩序。；负责汪伪广东警务，协助日军镇压抗日力量，维持沦陷区治安，江门、开平一带伪警察系统受其节制。；汪伪广东省政府核心成员，负责民政事务，推行保甲制度，配合日军征粮征丁。；汪伪政权在广东的重要官员，曾任伪广州市长、伪广东省政府委员等职，参与伪政权地方行政。；掌管汪伪广东警察系统，镇压抗日活动，维护日伪在广东包括江门地区的统治秩序。；广州沦陷后出任伪广州市长，协助日军维持广州城区统治。；汪伪政权时期曾任伪广州市市长，参与广州市政与治安的附逆管理。；伪警察头目，活动于华南，对广西有影响。；长期把持伪广州警察系统，配合日军搜捕抗日人士、镇压市民反抗。；曾任汪伪广州市市长，负责广州沦陷区市政与治安，配合日军实施物资统制与保甲制度。；曾任汪伪广州市市长，参与广州伪政权运作。；在汪伪广东省、广州市政权中任职，参与伪政权行政事务，协助日军控制广州及周边地区。；在汪伪广东省、广州市政权中任职，参与伪化地方行政。；广东伪政权成员，参与伪广东省政务，活动区域与广西邻近。；曾任伪广州市市长，参与伪广东省政务，协助日军推行保甲制度与物资统制。；汪伪广东省、广州市政权官员，参与伪广州市政管理，为日军统治服务。；历任伪广州市长等职，协助日军管理广州，推行伪化政策，搜刮民财。；在汪伪广东省政府任职，参与伪政权管理，协助日军维持占领区秩序。；广东伪政权重要成员，曾任伪广州市市长，协助日军管理广州及周边地区，推行奴化教育。；负责汪伪广东警务，统辖伪警察力量，配合日军搜捕抗日人士、维持占领区治安。；长期在广东伪政权中任职，掌管伪警察系统，镇压抗日活动，维护日伪统治。', '[]', '2026-09-10 09:57:14.025409', '2026-09-10 09:57:14.025409', '广东', '江门', '开平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1f8a0f6557d641f0a2fe818b6ec1a51f', '徐学禹', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶；江西九江柴桑；辽宁沈阳大东；江西上饶信州；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '在九江推行奴化教育，改编教材，宣传“大东亚共荣圈”。；江西上饶人，伪上饶县警察局长，配合日军搜捕抗日分子、镇压民众反抗，维持上饶沦陷区治安。；协助李蓬春组织伪维持会，负责向商户摊派款项、物资，配合日军在上饶城区的统治。', '[]', '2026-09-10 09:57:14.037166', '2026-09-10 09:57:14.037166', '江西', '上饶', '信州', NULL, NULL, NULL, NULL, '');
