INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fb143aac67f4fcb9184b77c52f86cd2', '张乐山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳新民；辽宁沈阳和平；辽宁大连；辽宁沈阳辽中；黑龙江佳木斯郊区；辽宁阜新；辽宁铁岭昌图；辽宁；辽宁沈阳铁西；黑龙江鸡西梨树；黑龙江鸡西', '[]', '[]', '抗日战争时期', '', '投日后任伪大连港务局长，管理港口，为日军运输军需物资。；率领汉奸保安队配合日军扫荡沈阳郊区及辽中农村，烧杀抢掠，多次参与屠杀抗日群众。；率伪保安队协助日军“清乡”，在铁西工厂区监视工人，举报抗日言论，导致多人被捕杀害。；昌图县协和会头目，协助日军进行思想宣传，组织“勤劳奉仕”运动，强迫当地农民为日军服劳役。；管理阜新煤矿，残酷压榨矿工，实行“人肉开采”，导致大量劳工死亡。；率伪军在新民、法库等地配合日军扫荡，杀害抗日义勇军战士和平民，抢劫财物。', '[]', '2026-09-10 09:57:14.063094', '2026-09-10 09:57:14.063094', '辽宁', '沈阳', '新民', NULL, NULL, NULL, NULL, '');
