INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fc02e538f644fc586edeb4a411f53c8', '王经明', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门同安；福建厦门', '[]', '[]', '抗日战争时期', '', '组织亲日教育团体，在厦门、同安推广奴化教育。', '[]', '2026-09-10 09:57:14.061005', '2026-09-10 09:57:14.061005', '福建', '厦门', '同安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fc9d89f573543adade455aa2df5ef25', '陈静之', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济南历下；山东济宁任城；山东济宁；山东济宁泗水；辽宁沈阳大东；山东威海威海临港经开区；山东威海；山东济南历城；山东济南；山东济宁；山东济南长清；辽宁沈阳新民；内蒙古赤峰宁城；山东聊城冠县；辽宁沈阳大东；山东济宁济宁高；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '掌管伪警察系统，在济宁城乡清查户口、逮捕抗日嫌疑人员，协助日军实施保甲连坐。；在聊城推行新民会运动，宣传“大东亚共荣”，协助日军征集物资。；任伪济南道尹期间，管辖历城等县，推行日伪政令，征发民夫物资。；为日军筹款筹物，强制商户纳捐，协助日伪经济掠夺。；统领伪警察大队，配合日军在威海卫及周边地区进行治安肃正，抓捕抗日军民。；推行奴化教育，强制学校使用伪教材，宣传“大东亚共荣”，毒害泗水青少年。；在历下区一带推行保甲制度，监视居民，举报抗日人员。；在长清推行新民会活动，进行奴化宣传与情报收集。；在教育领域推行奴化教育，编写伪教材，宣扬“中日亲善”“大东亚共荣”，毒害青少年，为日伪培养顺民。；依附日伪，控制济宁商会，为日军筹款筹粮，压榨商户，协助经济掠夺。', '[]', '2026-09-10 09:57:14.013403', '2026-09-10 09:57:14.013403', '山东', '威海', '威海临港经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fcc28e4d84e44df9a80b8373c737560', '何国柱', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西北海；广东江门；广东江门新会；广东江门；云南普洱西', '[]', '[]', '抗日战争时期', '', '投靠日本，在湖北伪政权中任职，配合日军统治，对陕西有间接影响。；率领伪保安队配合日军扫荡合浦、北海抗日游击区，烧毁民房，杀害抗日群众。；负责江门伪警察系统，协助日军搜捕抗日人员、控制交通与物资，是江门地区直接附逆的警政头目。；江门沦陷后出面组织伪商会，为日军筹款、征物，协助经济统制，属经济附逆者。', '[]', '2026-09-10 09:57:14.028603', '2026-09-10 09:57:14.028603', '广东', '江门', '新会', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fce93d8521e4aa28831cb4e6638e684', '赵振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北衡水冀州；河北承德丰宁；河北石家庄鹿泉；内蒙古通辽；内蒙古、河北、辽宁；辽宁朝阳喀喇沁左翼', '[]', '[]', '抗日战争时期', '', '专门负责侦破抗日地下组织，严刑逼供，导致多名抗日志士牺牲。；为日军宣传“日满亲善”，组织汉奸青年团，刺探抗日军情，协助日军在丰宁山区进行“梳篦式”清剿，导致多支小股游击队损失。；为日军充当翻译，参与审讯和酷刑迫害抗日俘虏，提供情报导致多起抗日行动失败。；负责日伪特务工作，搜捕抗日地下党员，破坏抗日组织，残害百姓。；率伪保安队协助日军“讨伐”，杀害抗日军民，强征民夫修建军事工事。', '[]', '2026-09-10 09:57:13.991852', '2026-09-10 09:57:13.991852', '内蒙古', '通辽', '丰宁', NULL, NULL, NULL, NULL, '');
