INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fd267856f7a4d9a9f24c3fb57be9ea6', '陈伯平', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西南昌', '[]', '[]', '抗日战争时期', '', '率领伪保安队配合日军扫荡南昌周边乡村，捕杀抗日游击队员及家属，抢掠民财。', '[]', '2026-09-10 09:57:14.039375', '2026-09-10 09:57:14.039375', '江西', '南昌', NULL, NULL, NULL, NULL, NULL, '');
