INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fe35b2d67074391aba4f4fda6a313bc', '蒋文成', NULL, NULL, NULL, NULL, 'exact', 'exact', '抚顺望花', '[]', '[]', '抗日战争时期', '', '伪职：伪望花街长；罪行：强征劳工、摊派物资；日本投降后私藏武器，勾结国民党地下组织，等待国民党接收。；结局：1945 年群众公审处死。', '[]', '2026-09-10 09:57:14.080421', '2026-09-10 09:57:14.080421', '辽宁', '抚顺', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1ff33d08839743db98a5acc6ce4a1740', '孟庆文', NULL, NULL, NULL, NULL, 'exact', 'exact', '长岭新安镇', '[]', '[]', '抗日战争时期', '', '伪职：伪长岭新安镇警察署署长；罪行：日伪时期残害百姓；光复后组建维持会与 “大排队” 武装，修筑炮台，武力抗拒民主政府接收。；结局：武装失败后被清算。', '[]', '2026-09-10 09:57:14.075086', '2026-09-10 09:57:14.075086', '吉林', '松原', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1ff7aea715d641c4883c013d3d12bc9b', '金玉昆', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（政治汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：伪职；罪行：政治汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.083407', '2026-09-10 09:57:14.083407', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1ffa2b13abd14d87b1d5df4793010b08', '刘俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '代县', '[]', '[]', '抗日战争时期', '', '伪职：伪据点伪军副班长（叛徒）；罪行：背信弃义出卖我方敌工部长高凡，致使高凡被捕牺牲。；结局：被我方俘获处决', '[]', '2026-09-10 09:57:14.075341', '2026-09-10 09:57:14.075341', '山西', '忻州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1ffdb93908fc4e3f8625394e2f6ef888', '陈敬斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口鹿邑；河南周口；河南周口周口经开区；河南开封；青海黄南河南；河南商丘；河南许昌；河南开封；河南商丘豫东综合物流产业聚集；河南商丘；河南鹤壁浚县；河南安阳；河南鹤壁山城；河南安阳汤阴；河南周口；河南商丘；河南商丘梁园；河南商丘；河南周口川汇；河南周口；河南新乡；河南鹤壁；河南鹤壁鹤山；河南安阳汤阴；河南周口商水；河南周口；河南商丘民权', '[]', '[]', '抗日战争时期', '', '在开封、商丘、周口等地任职伪政权，推行日军殖民统治政策，协助掠夺豫东物资。；在河南沦陷区伪政权中任职，参与豫东地区伪政权的行政与治安管理，为日军统治提供支持。；在河南伪政权中任职，参与推行日军殖民统治政策，协助征粮征兵，镇压河南抗日力量。；在伪河南省政府任职并一度主持豫东道伪政，商丘一带为其管辖区域，协助日军推行治安强化运动。；在河南沦陷区任伪职，协助日军推行保甲制度、征发劳工，其管辖范围涉及豫中包括许昌在内的部分地区。；在太康任伪职期间，配合日军扫荡豫东抗日根据地，组织伪自卫团，强征民夫修筑据点，对周口北部地区造成较大危害。；在汤阴及邻近鹤壁地区推行伪化教育，强征劳工，为日军修筑据点、公路，协助日军控制豫北交通线。；淮阳邻近周口，其任伪县长期间为日军征粮派款，组织伪自卫团，配合日军对周口周边地区进行清乡。；伪豫东道管辖商丘、周口、淮阳等县，陈敬斋任道尹期间推行伪化教育、经济统制，为日军掠夺豫东物资，并指挥伪军配合扫荡。；在商丘推行奴化教育，改编教材，强制学校教授日语和亲日内容，毒害青少年。；开封沦陷后出任伪市长，协助日军统治河南省会。；掌管伪河南省警察系统，在豫北包括鹤壁地区建立伪警察网络，镇压抗日活动。；统率伪保安队活动于安阳、鹤壁、浚县等地，配合日军扫荡，抓捕抗日人员。；淮阳沦陷后投敌，组织维持会并任伪县长，在淮阳、鹿邑、周口一带为日军征粮征丁，配合日伪政权推行保甲连坐。；夏邑沦陷后任伪县长，为日军筹办粮秣，协助日军维持夏邑及商丘周边地区治安。；出任民权县伪知事，执行日军政令，推行保甲制度，配合日军对民权及周边地区的控制与扫荡。；在汤阴县任伪县长期间，配合日军推行保甲制度，搜捕抗日人员，为日军掠夺资源。；在河南沦陷区推行奴化教育，影响包括新乡、卫辉在内的豫北地区。', '[]', '2026-09-10 09:57:14.047310', '2026-09-10 09:57:14.047310', '河南', '周口', '周口经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1ffe22e8f4b6478fb36b54616ed1a44b', '韩希梦', NULL, NULL, NULL, NULL, 'exact', 'exact', '定县', '[]', '[]', '抗日战争时期', '', '伪职：伪定县警备大队长；铁杆汉奸，每次日军扫荡充当先锋，残害百姓。；结局：被我方武工队锄奸击毙党史学习教...', '[]', '2026-09-10 09:57:14.078667', '2026-09-10 09:57:14.078667', '河北', '保定', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('1fffc1aa925f4be8b0222802b26929b2', '张老墨', NULL, NULL, NULL, NULL, 'exact', 'exact', '武邑', '[]', '[]', '抗日战争时期', '', '伪职：伪武邑警备大队长；多次袭扰武邑、武强交界堡垒村庄。；结局：武邑解放被俘处决', '[]', '2026-09-10 09:57:14.080414', '2026-09-10 09:57:14.080414', '河北', '衡水', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2000254b2db841bca3eb20976675295f', '溥仪', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝；广西桂林七星', '[]', '[]', '抗日战争时期', '', '伪满洲国元首，主要活动于东北，与重庆沙坪坝无直接关联。；被日本扶植为伪满洲国元首，充当日本殖民统治工具，属于抗战时期有明确记载的汉奸。', '[]', '2026-09-10 09:57:14.031995', '2026-09-10 09:57:14.031995', '广西', '桂林', '七星', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('200acd2f5ab3424a9037c872c7ff7efc', '涂瀛洲', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉汉南；湖北武汉', '[]', '[]', '抗日战争时期', '', '汉口沦陷初期组织维持会，为日军筹集物资、维持秩序，后并入伪武汉特别市政权。', '[]', '2026-09-10 09:57:14.056613', '2026-09-10 09:57:14.056613', '湖北', '武汉', '汉南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('200dbb3e5beb418d808d59fa72a29708', '王瑞', NULL, NULL, NULL, NULL, 'exact', 'exact', '浠水县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：浠水县洗马镇小金山村人。1941年7月17日下午在洗马镇通往三角山土路上活动，被新四军侦察员认出；结局：被新四军锄奸', '[]', '2026-09-10 09:57:14.080701', '2026-09-10 09:57:14.080701', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('200e79756d404d2abd6240f7a4f243cd', '吴菊生', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏苏州虎丘；江苏苏州太仓；江苏苏州；浙江_嘉兴_桐乡；浙江湖州；浙江湖州长兴；江苏苏州相城；江苏苏州吴江；辽宁沈阳和平；浙江杭州上城；安徽芜湖芜湖经开区；安徽芜湖；浙江_湖州_吴兴；江苏苏州吴中；江苏苏州苏州工业园', '[]', '[]', '抗日战争时期', '', '日军初占芜湖时，协助维持会组织“良民证”发放，指认抗日分子，导致多人被捕。；在长兴县推行奴化教育，强征粮食，建立伪保甲制度，向日军提供情报，导致多处抗日据点被破坏。；指挥伪警察镇压抗日群众，抓捕地下党员，破坏抗日组织。；在苏州、太仓交界地带活动，率伪军袭击抗日游击队，杀害多名抗日群众。；在虎丘一带为日军和伪军提供抗日活动情报，协助抓捕抗日群众。；在相城一带组织汉奸武装，为日军带路“扫荡”，强征民夫和粮食。；为日军征购粮食和物资，强迫商户缴纳“和平捐”，从中牟利，资助伪军。；率伪保安队在吴中地区多次围剿抗日游击队，杀害无辜百姓。；率领伪保安队配合日军围剿抗日游击队，在苏州工业园区（原娄葑、唯亭一带）进行扫荡。；效忠日军，镇压抗日活动，逮捕并刑讯抗日志士，助纣为虐。；负责上城地区绥靖事务，组织汉奸武装，破坏抗日组织，向日军报告抗日动态。', '[]', '2026-09-10 09:57:14.009735', '2026-09-10 09:57:14.009735', '安徽', '芜湖', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2018af1d1195454d93b60e4e9e8cde03', '张余三', NULL, NULL, NULL, NULL, 'exact', 'exact', '蓬莱县', '[]', '[]', '抗日战争时期', '', '伪职：伪县知事；罪行：蓬莱大汉奸之一；结局：抗战胜利后潜逃；被通缉', '[]', '2026-09-10 09:57:14.074045', '2026-09-10 09:57:14.074045', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('201fef97e8ae47a8b0c8dd64861f4149', '宋子君', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪汾阳县县长；罪行：建立汾阳伪公署，管控太汾公路，强征粮食壮丁，多次配合日军扫荡晋绥八分区。；结局：1945 解放文水战斗中被击毙', '[]', '2026-09-10 09:57:14.067008', '2026-09-10 09:57:14.067008', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('20298500e86746afa42df7292dd9a781', '王翦波', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳汨罗；湖南岳阳；湖南岳阳临湘；湖南岳阳湘阴；湖南岳阳；湖南衡阳南岳；湖南衡阳；湖南衡阳；湖南湘潭；湖南岳阳平江；湖南岳阳；湖南怀化溆浦；湖南衡阳', '[]', '[]', '抗日战争时期', '', '岳阳沦陷后投敌，历任伪维持会会长、伪县长，为日军筹粮筹款、征发民夫，并参与组织伪保安队。；率伪保安大队配合日军在临湘、岳阳交界地区扫荡，袭击抗日游击队。；日军占领湘潭后出面组织维持会，为日军筹粮、拉夫、维持地方伪秩序。；湘阴沦陷后投敌，任伪县长，配合日军扫荡洞庭湖周边抗日武装，与汨罗、岳阳伪政权协同。；在临湘一带收编土匪武装，投靠日军，配合日军扫荡抗日根据地，残害抗日军民。；衡阳沦陷后，日军扶植伪政权，王翦波被部分地方资料列为参与伪县政筹备人员，但记载简略。；在衡阳组织伪维持会，为日军筹粮、派夫，协助日军控制衡阳地区。；湘南地区伪军头目之一，衡阳沦陷后投靠日军，参与组织伪军和维持会，在衡阳、南岳一带进行伪化活动。', '[]', '2026-09-10 09:57:14.057802', '2026-09-10 09:57:14.057802', '湖南', '岳阳', '临湘', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2029bf83b2bb4fca90a3404e62e41699', '巴金保', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江大兴安岭加格达奇；内蒙古呼伦贝尔；内蒙古呼伦贝尔鄂温克族自治旗；达斡尔族；内蒙古呼伦贝尔；内蒙古呼伦贝尔海拉尔', '[\"达斡尔族\"]', '[]', '抗日战争时期', '', '在呼伦贝尔索伦旗（今鄂温克族自治旗）任伪职，强迫牧民缴纳“出荷粮”，为日军提供畜力、皮毛等战争物资。；伪职：末任伪兴安东省省长；接续博彦满都，维持伪满末期统治。；结局：战后关押改造，特赦释放', '[]', '2026-09-10 09:57:13.988145', '2026-09-10 09:57:13.988145', '内蒙古', '呼伦贝尔', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('202b0e72b0bb4195b68919e8c07280ba', '曹梦九', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台', '[]', '[]', '抗日战争时期', '', '伪职：伪保定道道尹，伪保定道最高行政长官；统管 20 县伪政权，推行保甲连坐，配合日军反复扫荡冀中、晋察冀根据地。；结局：日本投降后逮捕，判处无期徒刑', '[]', '2026-09-10 09:57:14.017411', '2026-09-10 09:57:14.017411', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
