INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2176274361d5402da760cb3e6e157615', '李宣德', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宿州砀山；河南商丘睢阳；河南商丘；河南周口郸城；河北邢台沙河；安徽阜阳颍上', '[]', '[]', '抗日战争时期', '', '在沈丘一带组织伪维持会，为日军筹粮筹款，协助日军控制沙河沿岸地区，影响波及郸城南部。；颍上县地方士绅，日军侵占颍上期间出面组织维持会，为日军筹粮筹款、带路扫荡，协助建立伪政权。；砀山地区伪维持会负责人，协助日军管理地方，征发民夫物资，推行保甲制度。；夏邑沦陷后任伪县长，隶属豫东伪政权系统，为日军筹粮筹款，维持伪基层统治，活动范围与商丘、睢阳邻近。', '[]', '2026-09-10 09:57:14.008459', '2026-09-10 09:57:14.008459', '安徽', '宿州', '砀山', NULL, NULL, NULL, NULL, '');
