INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2284c5dd8e65401aafe779b4be53d8b3', '李相朝', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边珲春；吉林延边和龙；吉林延边延吉', '[]', '[]', '抗日战争时期', '', '在延吉地区组织警察特务，破坏抗日地下组织，多次参与围剿东北抗日联军，残害抗日志士。；组织地方自卫团协助日军“清乡”，在珲春边境地区杀害抗日群众和抗联联络员', '[]', '2026-09-10 09:57:13.997696', '2026-09-10 09:57:13.997696', '吉林', '延边', '和龙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('22854fb30a7c49b9973089097bd117d2', '王永苍', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东泰安岱岳；山东泰安；山西阳泉城区；山东泰安新泰；山东济南济阳；山东泰安宁阳；山东泰安；山东济南长清；山东济南；山东滨州邹平；山东泰安', '[]', '[]', '抗日战争时期', '', '控制济南铁路枢纽，协助日军运输军用物资、镇压铁路沿线抗日活动。；泰安沦陷后任伪县知事，为日军征粮、征夫，镇压当地抗日活动。；泰安沦陷后组织伪维持会，协助日军维持地方秩序、摊派物资，是泰安早期伪政权代表人物之一。；泰安沦陷后组织维持会，为日军筹粮、派夫、维持地方秩序，协助伪政权建立。；日军侵占泰安后出任伪泰安县知事/县长，组织维持会与伪警备队，配合日军清乡、扫荡，镇压当地抗日活动。；抗战时期在泰安地区任伪县长，协助日军维持占领区秩序，推行保甲连坐，搜捕抗日人员。；组织伪保安团，配合日军守备济阳，镇压抗日活动。；抗战时期在新泰地区任伪县知事、伪县长，组织维持会，配合日军统治新泰，搜捕抗日人员。；邹平沦陷后组织维持会，后任伪县长，为日军征发民夫、粮食，协助日军控制邹平地区。；日军侵占德州后出面组织维持会，后任伪德县县知事，为日军筹粮筹款、维持地方伪秩序，是德州城区早期附逆代表人物。', '[]', '2026-09-10 09:57:14.014071', '2026-09-10 09:57:14.014071', '山西', '阳泉', '城区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('228df2bc723346289f37e0d7b3a932cc', '李景和', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北邢台沙河；河北石家庄井陉矿', '[]', '[]', '抗日战争时期', '', '投日汉奸，任伪井陉县知事，在井陉矿区推行日伪政权，强征粮食和劳工，协助日军建立“爱护村”以隔离抗日武装。；充当日军爪牙，负责井陉煤矿的警戒，镇压矿工反抗，抓捕并杀害抗日地下工作者。；率伪警备队多次配合日军扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，抢劫财物。；率伪警备队多次袭击抗日村庄，抓捕并杀害抗日干部和群众，烧毁民房，民愤极大。', '[]', '2026-09-10 09:57:14.043307', '2026-09-10 09:57:14.043307', '河北', '石家庄', '井陉矿', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('229c3c704e2c43ce8107e82f611ff70b', '刘老黑', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台隆尧；河北石家庄栾城；河北邢台临城；河北', '[\"刘振声\"]', '[]', '抗日战争时期', '', '专门刺探八路军情报，带领特务队突袭抗日村庄，制造多起惨案。；带领伪自卫团为日军站岗放哨，封锁交通，参与“清乡”行动，抢劫抗日家属财产。；率伪自卫团驻守据点，多次袭击八路军游击队，杀害抗日家属，烧毁村庄。', '[]', '2026-09-10 09:57:14.043562', '2026-09-10 09:57:14.043562', '河北', '石家庄', '栾城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('22b2a6c58a3d4b38ba947a38f766123a', '周鸿煜', NULL, NULL, NULL, NULL, 'exact', 'exact', '金东沈宅周边', '[]', '[]', '抗日战争时期', '', '伪职：旧军官，沈锦智同党；罪行：与沈锦智串通，准备投降日军，筹划伪化地方，为日军搜集乡间情报。；结局：同沈锦智一同被抗日武装处决。', '[]', '2026-09-10 09:57:14.084382', '2026-09-10 09:57:14.084382', '浙江', '金华', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('22b8c5d0560c49b1a4e6f899b2c60c5b', '张君英', NULL, NULL, NULL, NULL, 'exact', 'exact', '渑池县', '[]', '[]', '抗日战争时期', '', '伪职：渑池县副县长（被害）；罪行：中共派往渑池县任副县长。在上官子平叛乱中被杀害；结局：1945年5月在上官子平叛乱中牺牲', '[]', '2026-09-10 09:57:14.076577', '2026-09-10 09:57:14.076577', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('22c4414d67834e8baf95d711fc1e2c93', '张子厚', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西咸阳秦都；河南开封；河南南阳；辽宁沈阳大东；河南许昌；河南开封尉氏；河南开封鼓楼；辽宁沈阳大东；山东潍坊临朐；河南洛阳涧西；河南洛阳；河南南阳新野；河南洛阳洛宁；山西晋中和顺；山西晋中；河南鹤壁；河南鹤壁淇县；河南郑州登封；河南郑州新密；河南新乡凤泉；河南新乡；河南许昌建安；辽宁沈阳大东；河南三门峡三门峡经开区；河南洛阳瀍河；辽宁沈阳大东；山东烟台；山东烟台牟平；陕西汉中汉台；河南洛阳伊川；河南洛阳；河南南阳淅川；河南新乡；河南鹤壁鹤壁经开区；河南鹤壁淇县；河南南阳社旗；河南南阳方城；河南三门峡湖滨；云南普洱西；陕西汉中勉县；陕西汉中；重庆沙坪坝；河南许昌魏都；河南许昌；河南新乡新乡高；河南新乡', '[]', '[]', '抗日战争时期', '', '在新乡沦陷区任伪警察头目，配合日军搜捕抗日人员、镇压民众。；洛阳沦陷后主持伪教育会，推行奴化教育，宣传“大东亚共荣圈”。；河南淅川人，抗战期间任伪淅川县长，协助日军维持淅川伪政权。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；1945年日军占领新野后，被任命为伪新野县公署县知事，协助日军维持地方统治、征派粮款，是新野地区直接附逆的伪政权头目。；协助伪维持会会长管理南郑县（今汉台区）地方事务，为日军筹粮筹款，动员民众服从日伪统治。；在日军支持下出任伪方城县县长，活动于南阳东北部，与社旗地区相邻，配合日军征粮、清乡。；任伪临朐县保甲长，协助日军征粮、抓丁，监视民众，迫害抗日人员。；密县本地人，日军占领密县后投敌，任伪保安团团长，配合日军清乡，镇压当地抗日力量。；投靠日本，在秦都镇维持会中任职，协助日军统治，对秦都地区有直接影响。；任伪淇县县长期间推行保甲连坐，配合日军清乡，强征民夫修筑封锁沟墙。；任伪登封县警察局长期间，协助日军搜捕抗日人员，推行保甲连坐。；在伪豫北道尹公署任职，驻新乡，负责警务，协助日军清乡、扫荡，迫害抗日群众。；日军占领豫西后设立伪豫西道，张子厚任道尹，管辖洛阳、偃师、孟津等地，包括涧西地区，推行日伪政策。；率伪保安团配合日军扫荡许昌周边抗日武装，残害百姓。；率部投敌，编为伪保安团，配合日军在洛宁南部山区搜剿抗日武装。；作为日伪在晋中地区的汉奸代表，参与策划对和顺、昔阳等地的“清剿”行动，协助日军建立伪政权。；协助伪维持会会长为日军筹粮筹款，维持陕县沦陷区秩序。；在开封控制报刊与宣传，为日军侵略辩护，鼓吹‘大东亚共荣圈’。；牟平沦陷后组织维持会，任伪县长，协助日军控制牟平地区，掠夺资源，镇压抗日军民。；率地方武装投敌，编为伪保安团，在伊川及洛阳南部配合日军进行清乡、搜捕抗日人员。；参与组织维持会，为日军筹粮筹款、拉夫修路。；河南南阳人，抗战期间任伪南阳县教育科科长，推行奴化教育，篡改教材，宣传“大东亚共荣”。；南阳教育界人士，1945年日军占领南阳后出任伪教育科科长，推行奴化教育，篡改教材，向学生灌输亲日思想。；淇县沦陷后投敌，组织维持会，协助日军控制平汉铁路沿线，镇压抗日群众。；控制新乡地区物资配给，为日军掠夺粮食和棉花等战略物资。；在基层推行保甲制度，监视居民，为日军征丁征粮。；在伪汉中道尹公署任职期间，配合日军对汉中地区进行经济掠夺，推行保甲连坐制度，镇压抗日活动。；任伪开封县县长，推行保甲制度，征粮征丁，配合日军统治。；在豫西伪道任职，负责警务，协助日军搜捕抗日人员。；在沦陷区推行奴化教育，篡改教材，宣传“中日亲善”“大东亚共荣”。', '[]', '2026-09-10 09:57:14.016728', '2026-09-10 09:57:14.016728', '山东', '潍坊', '临朐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('22c60d133896408192d5ce6572a62876', '吕伯荪', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西永修', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪永修县县长，配合日军修筑据点，强征粮食劳工。结局：抗战胜利被捕，判处死刑', '[]', '2026-09-10 09:57:14.078833', '2026-09-10 09:57:14.078833', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
