INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('23183d3a4dbd41f08609268347c7c5ec', '陈统', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江徐闻；广东广州；广东湛江吴川', '[]', '[]', '抗日战争时期', '', '在经济领域附逆，为日军筹集物资，协助日军对广州湾及雷州半岛实行经济掠夺。；吴川沦陷期间出面组织伪维持会，为日军筹粮筹款、拉夫，协助日军维持地方统治，压迫当地民众。', '[]', '2026-09-10 09:57:14.029675', '2026-09-10 09:57:14.029675', '广东', '湛江', '吴川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('23235e83cd0e4fa492fced3982afdbe3', '高凌霨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津东丽；河南开封；陕西_西安_长安；湖南常德津；天津河北；河北秦皇岛；青海黄南河南；河北张家口；天津和平；安徽_宣城_泾县；天津南开；陕西_西安_高陵；湖北武汉江岸；天津河北；河北秦皇岛；湖南常德津；重庆万州；湖南常德津；北京昌平；天津北辰；湖南常德津；天津_武清；山东济宁；天津河北；陕西宝鸡；天津河北；天津（战时属河北）；天津河西；湖南常德津；天津红桥；天津河北；广西桂林资源；天津河北；安徽_阜阳_颍东；北京、天津、河北；北京通州；江苏南通通州；云南普洱西；重庆沙坪坝；天津河北；云南普洱西', '[]', '[]', '抗日战争时期', '汪伪政权', '原北洋政客，投日后在华北伪政权任职，间接参与昌平地区伪行政协调。；作为华北伪政权高层，参与对通州地区的统治决策，支持日军经济掠夺和军事镇压。；作为华北伪政权高层，其政策直接影响天津及东丽地区，支持建立各级伪政权，协助日军经济掠夺。；曾任北洋政府总理，后投靠日伪，在天津担任顾问，为日伪政权出谋划策。；日军占领天津后率先附逆，组织伪政权，协助日军接管南开大学校园，将校舍改为日军兵营和仓库，驱逐师生。……（共涉及27个地区的犯罪记录）；伪任职务：伪河北省首任省长、天津维持会会长。结局：抗战胜利后被捕，1940 年狱中病死', '[]', '2026-09-10 09:57:13.994817', '2026-09-10 09:57:13.994817', '北京', '通州', '津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('232a54445ac143b3b581f333f46cec2b', '色丹旺楚克', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰巴林右旗；内蒙古乌海乌达', '[]', '[]', '抗日战争时期', '', '在昭乌达盟地区任伪职，组织维持会，协助日军征发物资、镇压抗日。', '[]', '2026-09-10 09:57:13.990856', '2026-09-10 09:57:13.990856', '内蒙古', '赤峰', '巴林右旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('23377c1bc7b1485da69a946c8d8527e9', '黄公略', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南邵阳新宁；湖南邵阳；湖南益阳赫山；湖南长沙；湖南邵阳武冈；湖南岳阳华容；湖北鄂州华容；湖南邵阳城步；湖南邵阳；湖南益阳；湖南长沙', '[]', '[]', '抗日战争时期', '', '日军侵占邵阳后出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。；日军侵占邵阳后，出面组织伪邵阳县维持会，协助日军征粮、派夫、维持占领区秩序。；日军侵占邵阳后，出面组织伪邵阳县维持会，协助日军征粮、派夫、维持占领秩序。；日军侵占邵阳后，出面组织伪邵阳县维持会，协助日军征粮、派夫、维持地方秩序，为日军统治服务。；在长沙、益阳等地参与日伪政权筹划，协助日军推行保甲连坐，镇压湖南抗日力量。；长沙沦陷期间组织维持会，为日军筹粮筹款，协助维持占领区秩序。；日军侵占新宁期间，出面组织伪维持会，为日军征派粮秣、民夫，协助维持占领区秩序。；在汪伪湖南省政权中任职，参与清乡计划，其活动范围涉及湘北岳阳、华容等沦陷区，协助日军推行治安强化。；日军侵占邵阳期间，出面组织伪维持会，为日军征派民夫、粮食，协助维持占领区秩序。；日军侵占武冈期间，出面组织伪维持会，为日军征派粮秣、民夫，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.057907', '2026-09-10 09:57:14.057907', '湖南', '岳阳', '华容', NULL, NULL, NULL, NULL, '');
