INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('233e3751220641a89e7be780855f9cb9', '鲁道源', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明呈贡；湖南长沙', '[]', '[]', '抗日战争时期', '', '滇军将领，抗战时期率部参加长沙会战等，无汉奸记载。；滇军将领，抗战时期参加长沙会战等，无汉奸记载。', '[]', '2026-09-10 09:57:13.985145', '2026-09-10 09:57:13.985145', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
