INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('23451e484de54146866c8cf120459f0d', '薛逢元', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南通如皋；江苏南通；江苏南通海安；江苏南通', '[]', '[]', '抗日战争时期', '', '继任伪南通县长，协助日军清乡，逮捕抗日人士，推行保甲制度。；率伪军在南通、如皋交界处扫荡，杀害抗日干部。', '[]', '2026-09-10 09:57:14.034217', '2026-09-10 09:57:14.034217', '江苏', '南通', '如皋', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2346f1113f7b4836acb08a3d7d3f9919', '孙德林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁鞍山岫岩', '[]', '[]', '抗日战争时期', '', '已列，补充其曾参与“三光”政策。；地主武装头目，投日后任保安团长，率团丁配合日军扫荡，烧毁抗日村庄，掠夺百姓财物。', '[]', '2026-09-10 09:57:14.063850', '2026-09-10 09:57:14.063850', '辽宁', '鞍山', '岫岩', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('234d580b006a4e409eaea8533aea0dfc', '陈子岐', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾陆丰；广东云浮郁南；广东肇庆；广东汕头；广东潮州饶平；广东汕尾城区；广东汕尾；广东汕尾海丰；广东汕头南澳；广东揭阳揭东；广东揭阳；广东汕尾；广东汕头龙湖；广东汕头澄海；广东潮州潮安；广东汕头濠江；广东汕头；广东揭阳；广东汕头金平；广东汕头潮阳；广东揭阳榕城；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '汪伪揭阳县县长，推行伪政令，配合日军在揭阳及周边地区的统治。；汪伪政权在潮安地区的伪县长，潮安与揭阳相邻，其活动对揭阳地区有一定影响。；在南澳伪警察机构任职，协助日军管控海岛居民。；率伪军配合日军进攻海陆丰抗日根据地，捕杀抗日军民，抢掠沿海村庄。；肇庆沦陷后组织伪维持会，任会长，为日军服务。；担任伪海丰县警察局局长，协助日军维持治安，抓捕抗日人士，推行伪化教育，其势力范围覆盖海丰、陆河交界地区。；陈子岐在潮汕地区为日军搜集情报，抓捕抗日人士，其侦缉活动涉及揭阳、惠来等县，导致多名抗日志士被捕遇害。；在汕尾推行奴化教育，篡改教材，强迫学生学日语、拜神社。；控制汕尾渔港，为日军征用渔船、渔民，协助海上封锁抗日力量。；在潮安沦陷区担任伪警察局长，配合日军清乡，逮捕抗日群众，为日军提供情报。；在饶平沿海地区组织维持会，为日军提供情报和物资，协助控制沿海交通线。；在澄海组织伪维持会，为日军征发物资、维持地方秩序。；澄海沦陷后组织伪维持会，为日军征粮征夫，协助控制地方。；在汕头推行日语教育与亲日奴化宣传，改编教材，组织学生参加日军庆祝活动。；在枫溪一带为日军征粮、征工，监视村民动向，向日军报告抗日分子行踪。；潮阳沦陷后出任伪县长，为日军征粮征税、维持伪政权。', '[]', '2026-09-10 09:57:14.025839', '2026-09-10 09:57:14.025839', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
