INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('236d5c39a6d84475b030ead346cb2328', '刘继广', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古包头土默特右旗；内蒙古、河北；山东；河北张家口宣化；内蒙古呼和浩特赛罕；内蒙古呼和浩特；内蒙古鄂尔多斯康巴什；内蒙古包头土默特右旗；内蒙古包头；内蒙古赤峰；山西朔州朔城；内蒙古呼和浩特新城；内蒙古通辽开鲁；内蒙古包头；内蒙古包头白云鄂博矿；内蒙古包头达尔罕茂明安；内蒙古包头昆都仑；内蒙古包头；内蒙古通辽科尔沁左翼中旗；内蒙古通辽；河北张家口张家口经开区；辽宁沈阳大东；内蒙古包头石拐；内蒙古包头；内蒙古乌兰察布兴和；内蒙古乌兰察布；内蒙古鄂尔多斯鄂托克前旗；内蒙古包头土默特右旗；内蒙古鄂尔多斯伊金霍洛旗；内蒙古鄂尔多斯；重庆沙坪坝', '[]', '[]', '抗日战争时期', '汪伪政权', '在乌兰察布盟伪政权中负责“宣抚”工作，为日军宣传“大东亚共荣”，协助推行奴化教育。；在包头伪政权中负责警察事务，抓捕抗日地下人员，协助日军进行特务活动，镇压民众反抗。；指挥伪警察在包头、九原地区搜捕抗日分子，破坏地下交通线，多次参与日军“治安强化运动”，杀害无辜百姓。；负责包头日伪治安，抓捕抗日嫌疑犯，刑讯逼供，协助日军特务机关破坏地下抗日组织。；任伪包头警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织，在固阳、包头一带制造多起血案。……（共涉及13个地区的犯罪记录）；伪任职务：伪蒙古军第一师师长，后任伪包头市首任市长。结局：日本投降后潜逃，后被捕判处徒刑；伪职：第一任正式伪包头市市长；原东北军，随李守信投敌，伪蒙古军第一师师长改任市长；推行保甲连坐，强征劳工修筑炮楼兵营，掠夺物资。后调任伪蒙疆最高检察厅厅长、宣化省省长。；结局：日降后逃张家口，建国后抓捕劳改', '[]', '2026-09-10 09:57:13.986734', '2026-09-10 09:57:13.986734', '内蒙古', '乌兰察布', '兴和', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('236fa4e8e67e43ffa9a1969d65478e91', '张伯伦', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江修水；浙江温州；广西贵港港北；四川成都郫都；江西上饶；江西赣州上犹；湖南怀化溆浦；湖南岳阳；江西抚州广昌；江西抚州；江西赣州石城；江西抚州宜黄；江西南昌；江西宜春奉新；湖南常德桃源；湖南常德；江西赣州；湖南湘西泸溪；湖南怀化溆浦；江西赣州赣县；江西上饶铅山；重庆沙坪坝；江西赣州全南；江西赣州', '[]', '[]', '抗日战争时期', '', '溆浦沦陷期间组织维持会，为日军征派粮草。；在宜黄基层担任伪保甲长，为日军征派粮食、民夫，监视村民言行，协助伪政权控制地方。；在赣州、全南一带活动，协助日军建立伪政权，推行奴化教育，强征劳工。；在上犹县组织伪保安队，配合日军清乡，抓捕抗日群众，勒索钱财，无恶不作。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在赣州沦陷期间任伪警察局长，带领伪警察搜捕抗日分子，镇压市民反抗，为日军提供情报，残害无辜群众。；组织伪保安团，配合日军扫荡修水周边抗日武装，残害抗日军民。；协助伪维持会会长陈炯明管理贵县伪政权事务，为日军征调民夫、粮食，镇压民众反抗。；在黎川及抚州东部地区为日军服务，征集物资、情报，协助日军维持占领区统治。；在郫县地区组织伪维持会，协助日军征粮、派款，维持地方伪秩序。；常德沦陷期间，以商会会长身份与日军合作，强制商户缴纳“治安费”，为日军筹集物资。；以商会名义为日军筹款筹粮，强制商户交纳“慰劳金”，并协助日军管制物资。；江西上饶人，上饶沦陷期间任伪商会会长，协助日军摊派捐款、征购物资，压迫工商界。；为日军征收苛捐杂税，盘剥南昌、进贤等地商民，资助伪政权运转。；传闻在奉新地区组织伪保安队，配合日军扫荡，但缺乏正式档案佐证。；在石城基层担任伪保甲长，为日军征收物资、传递情报，并协助伪政权控制乡村。；浙江温州人，抗战期间出任伪温州商会会长，协助日军经济掠夺，为日伪政权筹集物资。；在岳阳组织伪维持会，为日军筹粮、派夫，协助日军控制岳阳地区。；在赣县沦陷期间担任伪警察头目，配合日军维持占领区治安，逮捕抗日嫌疑人员，勒索商户与居民。', '[]', '2026-09-10 09:57:14.002312', '2026-09-10 09:57:14.002312', '四川', '成都', '郫都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('237a236d424344f0ba571cfca16913b4', '李德斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北天门；河南信阳商城；河南信阳；河南信阳平桥；河南信阳', '[]', '[]', '抗日战争时期', '', '配合日军经济掠夺，统制物资，强征粮棉，剥削当地民众。；在日伪扶植下出任伪信阳县知事，推行伪政令，配合日军清乡、征粮、编组保甲，镇压抗日活动。；在信阳沦陷区充任伪县长，配合日军清乡、征粮、抓丁，维持伪政权统治。；在日军扶植下出任伪信阳县政权头目，推行保甲制度，配合日军清乡、征发民夫和粮食，镇压抗日活动，是信阳地区伪政权的重要代表人物。', '[]', '2026-09-10 09:57:14.046309', '2026-09-10 09:57:14.046309', '河南', '信阳', '商城', NULL, NULL, NULL, NULL, '');
