INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('240f982c3ff8428ab4d65f6b3b6e348a', '朱耀华', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_淮安_涟水；浙江宁波镇海；江苏淮安淮阴；湖南长沙天心；湖南长沙', '[]', '[]', '抗日战争时期', '', '效忠日军，指挥伪警察搜捕抗日分子，严刑拷打被捕人员，参与制造多起屠杀事件，并协助日军掠夺民间物资。；隶属日伪特务机关，发展汉奸线人，破坏抗日组织，曾参与逮捕并杀害多名新四军交通员和地下党员。；指挥伪警察镇压镇海抗日示威，逮捕并杀害多名爱国人士。；湘阴沦陷后组织伪维持会，为日军征集物资、情报，协助日军控制湘阴及长沙北部地区。', '[]', '2026-09-10 09:57:14.036124', '2026-09-10 09:57:14.036124', '江苏', '淮安', '淮阴', NULL, NULL, NULL, NULL, '');
