INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2424e484a12d4357aaa233b72364508c', '孙秉贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽菏泽经开区；山东菏泽郓城；山东济宁任城；山东济宁；山东菏泽菏泽高；山东菏泽东明；山东济南；山东菏泽成武；山东菏泽；山东菏泽', '[]', '[]', '抗日战争时期', '', '在郓城建立伪政权，配合日军对郓城、鄄城一带抗日根据地进行扫荡，残害抗日军民。；濮县（今属菏泽鄄城一带）人，投敌后任伪濮县县长，后升任伪鲁西道尹公署道尹，管辖鲁西多县伪政权，配合日军对冀鲁豫抗日根据地进行扫荡。；东明沦陷后组织维持会，后任伪县知事，在东明、菏泽、成武一带为日军征粮派款，协助修筑据点，破坏抗日政权。；伪兖州道辖济宁附近地区，协助日军征发劳工、粮食，镇压抗日群众。；在东明地区为日军效力，组织伪军，协助日军控制黄河渡口和交通线。；在济南市区实施特务统治，逮捕抗日人员，镇压民众。', '[]', '2026-09-10 09:57:14.015299', '2026-09-10 09:57:14.015299', '山东', '济宁', '任城', NULL, NULL, NULL, NULL, '');
