INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('244bd6a097e24fe0b048f032d29963ac', '马国恩', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；河南南阳淅川；南阳市区', '[]', '[]', '抗日战争时期', '', '伪职：豫鄂边防先遣军总司令（汉奸）；罪行：原豫鄂边防司令部负责人。1945年8月15日日本宣布投降后，日伪蒋合流公开化，豫鄂边防司令部被改编为“豫鄂边防先遣军总司令部”，马国恩被任命为总司令', '[]', '2026-09-10 09:57:14.046800', '2026-09-10 09:57:14.046800', '河南', '南阳', '淅川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2455032d45fc41fe85087139d0a430b9', '王谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西大同浑源；黑龙江大庆大同；山西晋中平遥；山西晋中灵石；山西大同；河南郑州中牟；山西太原娄烦；山西；山西太原小店；山西太原示范；山西太原古交；山西太原晋源；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '为日军征收粮食和劳役，告发抗日村民，导致多名群众被杀害。；充当日军经济汉奸，组织商会为日军筹集军费，垄断煤炭贸易，压低矿工工资，从中牟利。；在伪大同省任职期间，多次到浑源督导‘治安肃正’，组织伪军配合日军进攻八路军游击队。；建立汉奸情报网，向日军报告古交抗日武装动向，导致多名游击队员被捕。；组织维持会为日军征粮派款，协助日军建立伪政权，镇压抗日群众。；推行日伪奴化教育，在太原各学校强制教授日语，篡改历史教材，迫害爱国师生。……（共涉及7个地区的犯罪记录）；负责新民会宣传，组织汉奸团体，破坏抗日群众组织。；组织商人向日军献金献物，垄断市场，打压抗日商户，为日军筹措军饷。', '[]', '2026-09-10 09:57:14.020878', '2026-09-10 09:57:14.020878', '山西', '大同', '浑源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2468d86ab2054b6bae90b84e4bd1a652', '刘钧衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江绥化', '[]', '[]', '抗日战争时期', '', '任伪绥化县警务局长期间，指挥伪警察配合日军\'讨伐\'抗日联军，在绥棱、庆城一带搜捕抗日地下工作者。', '[]', '2026-09-10 09:57:14.066534', '2026-09-10 09:57:14.066534', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
