INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('25953fdfe5c94adeab7226ed3ea6c65e', '刘佐周', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北唐山曹妃甸；河北唐山迁安；河北唐山；河北；河北唐山开平；河北唐山；河北唐山丰润；河北唐山；河北唐山玉田；河北唐山；河北唐山唐山芦台经开区；河北唐山；河北唐山滦州；河北唐山丰南；河北唐山；河北唐山滦南；河北唐山；河北唐山遵化；河北唐山；河北秦皇岛昌黎；广东云浮', '[]', '[]', '抗日战争时期', '', '参与冀东伪政权，在唐山地区建立伪保安体系，镇压抗日运动。；在唐山市区推行伪政权法令，管理治安和税收，协助日军建立情报网，镇压抗日活动。；活动于唐山、滦县、丰南交界，多次围剿抗日游击队，杀害抗日群众。；在唐山、丰润地区组织伪保安武装，协助日军镇压抗日救国会，残害进步群众。；原为冀东保安队头目，后公开投靠日军，在唐山、丰润一带协助日军清剿抗日武装，制造多起屠杀事件。……（共涉及18个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.024829', '2026-09-10 09:57:14.024829', '广东', '云浮', '丰南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2599327641e447c39dff0ca7e008a090', '陈炳坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '青阳城关、木镇', '[]', '[]', '抗日战争时期', '', '伪职：青阳伪警察局局长；罪行：执掌伪警侦缉队，盘查公路渡口，搜捕爱国人士，多次配合日伪军清剿铜青游击根据地。；结局：肃奸运动判处死刑。', '[]', '2026-09-10 09:57:14.081726', '2026-09-10 09:57:14.081726', '安徽', '池州', NULL, NULL, NULL, NULL, NULL, '');
