INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('265e9ea5a26e443991cf7e85477e2d4e', '张联魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西临汾汾西；山西临汾；山西_晋中；山西太原；山西_太原_晋源；山西_太原_清徐；山西临汾尧都；山西_太原_古交；山西临汾翼城；山西临汾；山西临汾隰县；山西晋中榆次；山西临汾；山西运城；山西；吉林延边安图；吉林；山西临汾曲沃；山西_太原_小店；山西忻州五台山风景区；山西忻州五台；山西运城稷山；山东临沂河东；山西晋城；山西_晋中_左权；山西_太原_示范；山西太原；山西_太原_阳曲', '[]', '[]', '抗日战争时期', '', '任伪晋南道尹（驻临汾），统辖临汾、运城等地伪政权，配合日军“治安强化运动”，推行保甲制度，搜刮粮食资敌。；任伪晋南道（辖临汾等地）道尹，负责推行日伪“以华制华”政策，组织伪警察和保甲制度，配合日军扫荡抗日根据地。；组织伪保安队，配合日军扫荡尧都区周边村庄，杀害抗日军民。；组织维持会，为日军提供情报，协助清乡，残害抗日群众。；在临汾县推行伪政权，强征民夫修筑公路和碉堡，向日军提供粮食和情报，镇压抗日活动。……（共涉及34个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.998051', '2026-09-10 09:57:13.998051', '吉林', '延边', '安图', NULL, NULL, NULL, NULL, '');
