INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('270b34b87a5245c7838e40ceccfbb564', '葛杰甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '温州城区、近郊', '[]', '[]', '抗日战争时期', '', '伪职：伪永嘉县县长（第三次沦陷）；罪行：日军扶持正式伪永嘉县长，搭建完整伪县公署，设立伪警察局、各镇伪镇长；推行保甲、征粮派夫，开设鸦片馆、赌场，奴化宣传，镇压民间抗日活动。；结局：抗战胜利后汉奸审判判处死刑。', '[]', '2026-09-10 09:57:14.084870', '2026-09-10 09:57:14.084870', '浙江', '温州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('270f7e749a4c4f68913b72d2d4060aca', '吴道南', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵铜官；安徽铜陵；安徽安庆潜山；安徽安庆；海南海口；安徽安庆宜秀；安徽安庆；安徽安庆太湖；安徽安庆；安徽合肥包河；安徽合肥；江西上饶鄱阳；海南五指山；海南陵水；安徽_安庆_望江；海南三沙中沙；海南海口；海南三沙西沙；安徽安庆怀宁；安徽_蚌埠；安徽合肥肥西；安徽_合肥_巢湖', '[]', '[]', '抗日战争时期', '', '组织伪保安团配合日军在安庆周边清乡，袭击抗日游击队，强征民夫与物资。；在汪伪安徽省教育厅任职，推行亲日奴化教育，篡改教材，毒害青年。；在铜陵特区推行伪化统治，建立保甲制度，为日军提供情报，破坏抗日根据地。；组织伪保安团，配合日军在安庆周边地区进行治安战，袭击抗日游击队，残害百姓。；汪伪政权时期曾任伪安徽省政府委员，并一度出任伪怀宁县长，在怀宁推行保甲、征粮、奴化教育，配合日军对安庆周边地区的控制。；在儋县地区建立伪维持会与伪保安队，配合日军扫荡，迫害抗日军民。；为日伪政权强征各种捐税，包括“治安捐”“慰劳捐”，搜刮民财，导致百姓负担沉重，部分款项直接用于日军军费。；江西鄱阳人，鄱阳沦陷期间任伪维持会长，为日军提供物资与情报，协助日军控制鄱阳湖地区。；在伪政权中负责民政事务，配合日军实施殖民统治。；安徽沦陷区伪警务负责人，在合肥等地部署伪警察力量，镇压抗日民众。；汪伪政权在安徽的地方官员，曾任伪安庆地区专员，负责督导安庆、太湖等县伪政，配合日军清乡。；在陵水地区协助日军征粮拉夫，镇压抗日活动。；为伪政权征收苛捐杂税，侵吞抗日家属财产，协助日军经济掠夺。；安徽沦陷区伪政权要员，参与伪安徽省政，协助日军推行保甲制度、征发劳役。；在海口组织维持会，为日军筹粮筹款、招募劳工，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.005833', '2026-09-10 09:57:14.005833', '安徽', '合肥', '包河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('271378e2de654c4ba14b4bb8d2d4fda5', '刘镜洲', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽菏泽高；山东菏泽单县；山东菏泽鄄城；河南濮阳清丰', '[]', '[]', '抗日战争时期', '', '在单县地区为日军效力，组织维持会，配合日军对湖西抗日根据地的扫荡。；鄄城人，投敌后历任伪鄄城县县长、伪鲁西道尹公署官员，在鄄城、菏泽一带为日军征粮抓丁，组织伪军配合日军扫荡。；清丰人，抗战期间投敌，任伪清丰县保安团团长，在清丰、濮阳交界地区配合日军扫荡，捕杀抗日干部。', '[]', '2026-09-10 09:57:14.018126', '2026-09-10 09:57:14.018126', '山东', '菏泽', '鄄城', NULL, NULL, NULL, NULL, '');
