INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2795412c796d42809d7767cefab579ac', '王德辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南昌江；江西景德镇昌江', '[]', '[]', '抗日战争时期', '', '在昌江基层推行保甲制度，为日军征发劳工、征收粮食，监视民众言行，举报抗日嫌疑人员。', '[]', '2026-09-10 09:57:14.054268', '2026-09-10 09:57:14.054268', '海南', '昌江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('279a38baf10b4fadbf7d356ac2275aa8', '马麟', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃临夏', '[]', '[]', '抗日战争时期', '', '甘肃临夏人，与马良共同组织伪甘肃省维持会，任副会长，协助日军在甘肃的渗透和情报收集。', '[]', '2026-09-10 09:57:14.060135', '2026-09-10 09:57:14.060135', '甘肃', '临夏', '秦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('279fb504b3bc45ac89c6b61f88d3fdd5', '李茂斋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西运城绛县；山西；山西运城盐湖；山西运城临猗；山西运城；山西_运城_芮城', '[]', '[]', '抗日战争时期', '', '日军侵占运城后率先投敌，组织维持会，为日军筹措物资，协助建立伪政权，并出卖抗日地下工作者名单。；在日军扶植下担任伪区长，推行保甲制度，强征壮丁，搜刮民财，迫害抗日家属。；效忠日军，负责绛县县城及周边治安，大肆搜捕抗日地下党员和进步人士，严刑逼供后移交日军，导致多名抗日志士牺牲。；效忠日军，建立伪警察体系，搜捕地下党员和抗日积极分子，严刑逼供，破坏抗日地下组织。；效忠日军，负责维持县城治安，搜捕抗日地下人员，迫害爱国群众。', '[]', '2026-09-10 09:57:14.023660', '2026-09-10 09:57:14.023660', '山西', '运城', '临猗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('27b169f835de4163829c2f4cbca8141c', '朱鼎坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州靖江；江苏泰州；江苏泰州泰兴；江苏泰州靖江', '[]', '[]', '抗日战争时期', '', '在泰州地区推行日伪统治，组织伪政权，协助日军扫荡，强征民夫。；参与策划对泰兴、靖江边境的扫荡，协助李长江整编伪军，向日军输送壮丁。', '[]', '2026-09-10 09:57:14.035966', '2026-09-10 09:57:14.035966', '江苏', '泰州', '泰兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('27b36e667a3a4607933d1381f3d974dc', '叶蕴章', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州乐清；浙江温州鹿城；河南郑州中牟；浙江_温州_永嘉；浙江温州洞头；黑龙江佳木斯郊区；浙江温州龙港；辽宁葫芦岛龙港；浙江温州；浙江温州平阳；浙江温州龙湾；浙江温州永嘉；浙江温州瑞安', '[]', '[]', '抗日战争时期', '', '乐清首次沦陷时组织维持会，为日军筹粮派款，强迫百姓领取“良民证”。；指挥伪警察搜捕抗日分子，破坏地下组织，参与日军对平民的镇压行动。；任伪永嘉县知事，为日军提供粮食、劳役，并参与组建伪警察队伍，迫害抗日志士。；管辖平阳（含龙港一带），为日军征粮派款，组织伪保安队，协助日军围剿浙南抗日武装，残害无辜百姓。；率伪保安队配合日军扫荡温州郊区及洞头海域，抓捕抗日志士，抢劫民财。；任伪保安大队长，抓捕抗日志士，破坏地下党组织，罪行累累。；组织商会为日军筹款、采购军需物资，强迫商户缴纳“慰劳金”，从中牟利。；任伪平阳县知事，协助日军推行“治安强化”运动，搜刮民间物资，逮捕抗日志士。', '[]', '2026-09-10 09:57:14.051338', '2026-09-10 09:57:14.051338', '浙江', '温州', '乐清', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('27b8124d435049caa8fe34b951b84a4f', '陈文彬', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_台州_天台；湖北十堰；江西宜春；辽宁沈阳大东；江苏_镇江_扬中', '[]', '[]', '抗日战争时期', '', '湖北郧县人，抗战期间投敌，任伪郧县经济科科长，协助日军搜刮物资，压榨民众。；在占领区学校推行奴化教育，强制使用伪政权教材，宣传“大东亚共荣”。；为日伪政权征收各种税赋，盘剥商户，截留抗日物资。；指挥伪警察协助日军搜捕抗日地下人员，多次带队袭击新四军游击队，杀害多名抗日群众。', '[]', '2026-09-10 09:57:14.037012', '2026-09-10 09:57:14.037012', '江西', '宜春', NULL, NULL, NULL, NULL, NULL, '');
