INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2843314aca71425fab0dcb64ecb7d48a', '王鸣亚', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '海南伪政权高层人物，协助日军统治全琼，包括崖县、三亚地区，参与征粮、征丁和镇压抗日活动。', '[]', '2026-09-10 09:57:14.053028', '2026-09-10 09:57:14.053028', '内蒙古', '乌海', '海南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('284bba1701e94741a3a438a832f560e8', '陈长福', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建龙岩；福建厦门；福建泉州安溪；福建厦门；福建泉州金门；福建泉州；福建泉州丰泽；福建泉州；福建厦门同安；福建厦门；福建龙岩漳平；福建龙岩；福建福州；福建三明尤溪；福建泉州惠安；福建泉州；福建厦门湖里；福建厦门；福建厦门翔安；福建厦门；福建漳州东山；福建厦门；福建泉州晋江；福建厦门；福建泉州石狮；福建厦门；福建泉州；福建漳州南靖；福建泉州；福建漳州；福建厦门；福建福州；福建福州长乐', '[]', '[]', '抗日战争时期', '', '晋江沦陷区伪县长，配合日军在泉州平原推行“治安强化运动”，捕杀抗日游击队员及其家属。；日军占领长乐期间组织伪维持会，为日军征粮拉夫。；在厦门伪政权任职期间，多次派人潜入泉州、南安等地发展伪组织，诱降地方武装，配合日军扫荡。；日军侵占厦门后，在漳州地区组织维持会，为日军提供情报、粮秣，协助维持沦陷区秩序。；漳州地区沦陷期间组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序，活动直接覆盖漳州及云霄周边。；日军侵占厦门后，在漳州地区组织维持会，为日军筹粮筹款、拉夫，协助建立伪基层政权。；漳州本地士绅，日军侵占厦门后一度试图在漳州组织维持会，为日军提供粮秣、向导，后因漳州未长期沦陷而活动受限，但仍与漳浦沿海伪组织有联系。；漳州本地士绅，日军空袭与登陆威胁期间出面组织维持会，为日军提供物资与情报，后因民众抵制而销声匿迹。；在厦门沦陷期间为日军筹款筹粮，协助日伪对闽南沿海地区进行经济控制和物资征调，其活动影响波及漳州沿海。；厦门商界人物，抗战期间附逆，协助日军控制闽南物资流通。；厦门沦陷后投敌，协助日军统制闽南物资，为伪政权筹款筹粮，其商业网络覆盖漳州、诏安等地，间接支持日军对闽南的侵略。；泉州沦陷前后组织伪维持会，为日军提供情报与物资，协助建立伪保甲制度，压迫当地民众。；泉州沦陷前后组织维持会，为日军筹粮、拉夫、搜集情报，协助建立伪基层政权。；组织伪军配合日军在厦门及周边地区进行治安肃正，镇压抗日力量。；厦门富商，日军占领后出面组织伪商会，为日军筹款、征物资，并协助向泉州、晋江一带掠夺粮食与战略物资。；掌管厦门伪警察系统，镇压抗日活动，搜捕爱国人士，配合日军维持厦门及思明一带治安。；掌管伪警察系统，搜捕抗日人士、镇压民众反抗，为日军维持厦门及海沧周边治安控制。；厦门沦陷后投敌，控制商会为日军筹款筹粮。；在伪厦门警察系统任职，参与镇压抗日分子，维护日伪在闽南沿海的统治秩序。；福州人，福州第二次沦陷期间任伪保甲长，协助日军清查户口，举报抗日人员，征发民夫物资。；泉州人，在伪政权下推行日语教育与奴化宣传，协助日军在泉州、泉港等地学校实施殖民教育。；厦门沦陷后依附日军，参与伪维持会与商会活动，为日军筹款筹粮、稳定殖民经济秩序。；协助日军搜捕抗日人士，镇压厦门及周边地区民众。；在闽南及闽中部分地区担任伪保甲长，协助日军与伪政权征粮、派夫、监视抗日人员。；在漳州、泉州沿海一带收编土匪武装，与日军勾结，进行走私、劫掠和骚扰抗日游击队。；在日军控制下的泉州地区出任伪警察局长，参与抓捕抗日人士、维持伪治安，协助日军镇压民众反抗。；福建伪政权要员，协助日军在福建各地推行伪化统治，其活动涉及泉州地区。；在同安一带组织维持会，为日军征粮派款、拉拢地方势力。；在厦门基层推行保甲制度，协助日军清查户口、征发劳工和物资。；在厦门地区为日伪维持治安，参与搜捕抗日人员、镇压民众。；在龙岩地区参与伪维持会活动，协助日军及伪政权控制地方，压迫民众。', '[]', '2026-09-10 09:57:14.060315', '2026-09-10 09:57:14.060315', '福建', '三明', '尤溪', NULL, NULL, NULL, NULL, '');
