INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28b2c1648407499b88218efa9c2653c6', '杨振兰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸；河北邯郸磁县；河北邯郸涉县；辽宁沈阳新民；河北；滑县（今属安阳）；河北_邯郸_大名；河南安阳汤阴；河南安阳；河北邯郸丛台；辽宁沈阳新民；河南商丘豫东综合物流产业聚集；河南开封；河南鹤壁鹤山；河南安阳汤阴；河北邯郸武安；河北廊坊；河北廊坊永清', '[]', '[]', '抗日战争时期', '', '率伪军多次突袭永清县抗日村庄，烧毁房屋，抢夺牲畜。；伪职：伪二十四路；罪行：1941年4月率部占领抗日根据地安化城（二安）村；率伪军多次突袭永清县抗日村庄，烧毁房屋，抢夺牲畜。；在磁县推行保甲制度，强征壮丁补充伪军，参与镇压磁县抗日游击队，制造多起惨案。；日军占领邯郸后率先组织维持会，为日军征粮派夫，协助建立伪政权，迫害爱国人士。；推行奴化教育，组织“新民会”宣传亲日思想，强迫青年参加伪军训练。；作为日伪在邯郸的顾问，参与策划“清乡”行动，协助日军建立保甲制度，强征劳工。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042333', '2026-09-10 09:57:14.042333', '河北', '廊坊', '丛台', NULL, NULL, NULL, NULL, '');
