INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28beda189ac644d69d5d7c15cee075f2', '刘文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '湖北荆州石首；湖北荆州江陵；重庆丰都；河南郑州中牟；河北唐山滦州；河北唐山；江西鹰潭；江西鹰潭贵溪；湖北天门；湖北仙桃；湖北随州随县；重庆_璧山；河南驻马店驻马店经开区；河南驻马店；安徽马鞍山含山；湖北十堰竹山；江西上饶德兴；江西上饶', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山监狱参与处决抗日志士。；在唐山监狱中秘密处决抗日志士。', '[]', '2026-09-10 09:57:14.011058', '2026-09-10 09:57:14.011058', '安徽', '马鞍山', '含山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28cb11f038ec46ee89dc32ae0e65089a', '伊来灏', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：伪博山县警备大队大队长→伪博山县警备团长、淄博警备司令；罪行：临朐人，土匪出身。1938年9月率300余人投日军，被编为伪博山县警备大队。任内捕杀抗日军民，血债累累。博山解放前夕暗藏5000余斤炸药企图炸毁我军；结局：1945年8月26日解放淄川时被俘；1945年9月5日被周村城防司令部宣判处决', '[]', '2026-09-10 09:57:14.087195', '2026-09-10 09:57:14.087195', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28cc0f67a8ec4f7ea2b0f621d83d5435', '刘万昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '漯河地区（临颍县/襄城县）；襄城县', '[]', '[]', '抗日战争时期', '', '伪职：襄城县县长（汉奸）；罪行：抗战时期任襄城县县长。向第五战区谎报“一战区投降了”，导致第五战区用机枪扫射友军，使我军腹背受敌、伤亡惨重；结局：后被两区人员在茶楼捉获，刘万昌供认不讳，当场被枪决；伪职：临颍县县长（汉奸）；罪行：抗战时期任临颍县县长。向第五战区谎报“一战区投降了”，第五战区未加核实即以机枪扫射，致使第一战区部队腹背受敌、伤亡惨重；结局：后经两区沟通核实为汉奸挑拨离间，两区人员在茶楼将其抓获，刘万昌供认不讳，当场被枪决', '[]', '2026-09-10 09:57:14.082506', '2026-09-10 09:57:14.082506', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28ce4c089a694bad813760e1c4830ff3', '张啸林', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海青浦；浙江宁波慈溪；江西九江濂溪；辽宁沈阳和平；浙江杭州；浙江宁波慈溪；贵州贵阳；浙江宁波；广西玉林兴业；广西玉林；浙江宁波余姚；浙江宁波；浙江宁波慈溪；浙江杭州；浙江宁波慈溪；广西_柳州；重庆万州；浙江杭州上城；浙江杭州；上海杨浦；浙江杭州桐庐；广西_桂林_灵川；浙江台州椒江；湖北咸宁通山；浙江杭州；陕西渭南；浙江温州瑞安；浙江湖州；浙江杭州西湖；浙江杭州；上海金山；重庆_合川；浙江湖州', '[\"注：非张啸林本人，同名汉奸\", \"原籍宁波，但主要活动上海\"]', '[]', '抗日战争时期', '', '任伪警察局长，协助日军在椒江码头搜查抗日物资，逮捕并刑讯抗日嫌疑人员。；上海青帮头目，与杜月笙、黄金荣齐名。抗战初期投靠日本，曾参与策划在浙江杭州等地建立伪政权，为日军提供情报和镇压抗日力量。1940年被暗杀。其活动范围主要在沪杭一带。；上海青帮头目，抗战初期投敌，与日伪勾结，策划组建伪浙江省政府，后遭暗杀。；上海青帮头目，抗战初期投敌，与日本特务勾结，策划成立伪浙江省政府，因未及就任即被暗杀。其势力曾渗透湖州地区。；浙江杭州人，青帮头目，抗战期间投靠日军，任伪浙江省政府委员，在浙江一带组织伪军，镇压抗日力量。；浙江慈溪人，上海青帮头目，抗战期间投靠日军，任伪浙江省政府主席，在华中地区进行伪化统治和帮会活动。；浙江慈溪人，上海青帮头目，抗战后公开投敌，为日军提供情报，组织汉奸武装，破坏抗日运动，1940年被暗杀。；上海青帮头目，投敌后任伪职，与陕西渭南地区无直接关联。；上海青帮头目，抗战期间投靠日本，组织伪‘新亚和平促进会’，为日军在华中、江西等地采购物资、诱降国民党军政人员，其势力范围涉及九江一带的长江航运与情报活动。；上海青帮头目，杭州出生，日军占领杭州后积极投靠，组织维持会，为日军征粮派款，破坏抗日活动，后被暗杀。；浙江慈溪人，青帮头目，抗战初期投敌，在杭州、上海等地为日军搜集情报，协助日伪镇压抗日力量，1940年被暗杀。；浙江慈溪人，上海青帮头目，抗战爆发后投靠日本，在杭州、滨江一带协助日军建立伪政权，贩卖鸦片、强征物资，1940年被军统刺杀。；虽主要活动于上海，但曾参与宁波余姚的帮会势力，协助日军维持秩序。；宁波籍青帮头目，与日伪勾结，准备出任伪职，1940年被暗杀。曾在宁波发展汉奸势力。；上海青帮头目，抗战期间投敌，准备出任伪浙江省长，1940年被军统刺杀。；浙江慈溪人，上海青帮头目，抗战期间投靠日军，筹建伪浙江省政府，1940年被军统刺杀。；青帮头目，投靠日本，拟出任伪浙江省长，但未及上任即被军统刺杀于上海。；浙江杭州人，上海青帮头目，抗战期间投靠日军，组织伪军，协助日军镇压抗日力量，后在浙江一带活动。；浙江慈溪人，上海青帮头目，抗战期间投靠日本，组织伪军，1940年被军统刺杀。；其帮会势力曾向贵州延伸，在贵阳、息烽一带发展成员，协助日军搜集西南情报。；与日军勾结，在青浦及周边地区从事汉奸活动，后因投敌被暗杀。；原上海青帮头目，抗战初期投靠日本，策划组织汉奸武装，协助日军控制浙江、上海地区，后因内部矛盾被暗杀。；浙江慈溪人，上海青帮头目，抗战期间投敌，出任伪浙江省政府委员，协助日军在上海及浙江地区维持统治、镇压抗日活动，1940年被军统刺杀。；投靠日伪，组织伪军，后被军统刺杀。；上海青帮头目，投敌后组织伪军，其势力范围涉及长江中下游，包括湖北部分地区。；上海青帮头目，投靠日军，活动于上海，与广西玉林无直接关联。；原上海青帮头目，抗战爆发后投靠日本，在浙江湖州一带活动，协助日军维持治安，后于1940年被暗杀。；上海青帮头目，投敌后任伪浙江省长，组织伪军，1940年被刺身亡。；浙江慈溪人，上海青帮头目，抗战期间投靠日军，组织伪军，后任伪浙江省长，协助日军镇压抗日活动。；上海青帮头目，投靠日伪，其势力未直接进入万州。；青帮头目，投靠日伪，协助日军控制上海码头，镇压抗日活动，1940年被暗杀。；青帮头目，曾与日伪勾结，在杨浦地区（原租界东区）经营赌场和烟馆，为日军提供情报，后被暗杀。', '[]', '2026-09-10 09:57:13.977312', '2026-09-10 09:57:13.977312', '上海', '杨浦', '慈溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28cfa113da834332bbc2dd35ceae8a4f', '沈金生', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州；山西吕梁兴县；上海金山', '[]', '[]', '抗日战争时期', '', '投靠日伪，任伪商会会长，为日军筹集物资，强迫商户“献金”。；任伪吴兴县知事期间，推行日伪“清乡”政策，强征壮丁，搜刮民财，配合日军扫荡抗日武装。', '[]', '2026-09-10 09:57:13.979373', '2026-09-10 09:57:13.979373', '上海', '金山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('28e72acf5099411490c1078939523fc0', '李寿山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁葫芦岛；辽宁辽阳弓长岭；吉林辽源龙山；吉林辽源；辽宁铁岭调兵山；吉林白山抚松；内蒙古赤峰松山；吉林辽源东丰；吉林辽源；吉林白城洮南；吉林白城；吉林白山；辽宁锦州凌海；辽宁铁岭银州；辽宁鞍山铁东；河南商丘；辽宁抚顺；辽宁沈阳法库；辽宁沈阳；辽宁朝阳建平；辽宁朝阳；辽宁抚顺清原；辽宁辽阳太子河；辽宁辽阳；黑龙江大庆林甸；辽宁辽阳宏伟；辽宁辽阳；辽宁盘锦双台子；辽宁盘锦盘山；辽宁锦州凌河；吉林蛟河；辽宁营口；辽宁沈阳；河南周口项城；河南商丘；吉林_辽源_东辽；吉林通化柳河；辽宁锦州义县；山东潍坊潍城；山东潍坊昌邑；辽宁抚顺望花；吉林通化辉南；辽宁葫芦岛绥中；辽宁锦州黑山；安徽宿州；辽宁本溪明山；辽宁本溪；辽宁本溪桓仁；黑龙江伊春丰林；黑龙江齐齐哈尔；宽甸；吉林辽源西安；吉林桦甸；辽宁营口盖州；辽宁丹东元宝；辽宁丹东；辽宁丹东凤城；辽宁丹东；辽宁铁岭；河南商丘；河南商丘睢县；山西阳泉矿区；辽宁鞍山海城；辽宁沈阳辽中；辽宁鞍山台安；吉林四平梨树；辽宁铁岭清河；河北邢台清河；辽宁_沈阳_和平；辽宁阜新；辽宁丹东振安；辽宁丹东；河南周口商水；河南漯河舞阳；河南驻马店；山西阳泉城区；辽宁阜新太平；辽宁阜新彰武；辽宁鞍山岫岩；辽宁营口鲅鱼圈；辽宁抚顺新宾；黑龙江鹤岗东山；吉林通化梅河口；辽宁丹东；辽宁丹东宽甸；河南信阳息县；吉林磐石；辽宁阜新海州；辽宁本溪；辽宁大连；辽宁盘锦兴隆台；辽宁盘锦；辽宁锦州；吉林松原宁江；吉林松原；吉林通化集安；吉林通化；辽宁盘锦大洼；辽宁盘锦盘山；辽宁抚顺新抚；黑龙江绥化海伦；黑龙江齐齐哈尔；辽宁营口西市；吉林白山江源；吉林白山临江；辽宁鞍山千山；辽宁鞍山；吉林四平铁西；辽宁沈阳铁西；吉林白城镇赉；辽宁辽阳；辽宁鞍山立山；吉林_通化；辽宁朝阳；吉林长春朝阳；河南周口沈丘；辽宁丹东；辽宁铁岭昌图；河南驻马店正阳；吉林白城洮北；黑龙江双鸭山宝山；黑龙江双鸭山；辽宁辽阳白塔；辽宁辽阳；辽宁本溪平山；河北石家庄平山；辽宁本溪；辽宁葫芦岛南票；安徽宿州泗县；安徽宿州；辽宁辽阳文圣；辽宁辽阳；辽宁鞍山铁西；辽宁沈阳铁西；辽宁鞍山；辽宁葫芦岛；云南普洱西；吉林、辽宁；辽宁铁岭开原；安徽淮南谢家集；辽宁盘锦；辽宁盘锦盘山；河南周口；河南周口西华', '[]', '[]', '抗日战争时期', '', '伪职：伪蠡县县长；依附伪军，推行保甲，摊派物资。；结局：战后逮捕判刑；伪职：伪宽甸县县长；罪行：宽甸伪主官，实施保甲连坐，强征国兵、劳工，围剿抗联在宽甸的游击力量。；结局：县城收复后逮捕判刑。；已列，但补充其曾下令处决抗日家属。；梨树县伪警务负责人，直接指挥警察特务搜捕地下抗日组织，多次参与屠杀抗日群众。；积极推行“归屯并户”，切断抗日武装与群众联系，多次率警察袭击磐石抗日游击队营地，并实施“连坐”政策。；充当日军走狗，带领保安队抓捕抗日军民，破坏地下组织，强征民夫修筑军事工事。；在辽源地区任伪县长，积极执行日伪“治安肃正”政策，协助日军建立“集团部落”，迫害抗日家属。；九一八后投敌，任伪警务局长，组织伪警察配合日军清乡，逮捕抗日志士，并参与“讨伐”活动。……（共涉及74个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.997459', '2026-09-10 09:57:13.997459', '吉林', '四平', '梨树', NULL, NULL, NULL, NULL, '');
