INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('29509d4f0dac4407936cf8cd97df464f', '吴鹤龄', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古；内蒙古包头九原；内蒙古包头；内蒙古呼和浩特；河北张家口；内蒙古乌兰察布；内蒙古包头；内蒙古乌海海南；内蒙古包头；内蒙古呼和浩特；内蒙古呼和浩特和林格尔；内蒙古呼和浩特；内蒙古呼伦贝尔牙克石；河北张家口万全；河北张家口；内蒙古、河北；内蒙古乌兰察布化德；内蒙古乌兰察布卓资；内蒙古乌兰察布；内蒙古鄂尔多斯；内蒙古包头；内蒙古呼和浩特；内蒙古_锡林郭勒_二连浩特；云南普洱西；河北张家口；内蒙古_呼和浩特；内蒙古赤峰喀喇沁旗；内蒙古巴彦淖尔临河；云南普洱西；河北张家口；内蒙古乌兰察布集宁；内蒙古乌兰察布；内蒙古乌海海勃湾；内蒙古锡林郭勒乌拉盖；云南普洱西；重庆沙坪坝；内蒙古赤峰翁牛特旗；内蒙古赤峰；河北张家口张家口经开区；河北张家口；内蒙古喀喇沁旗；江苏南京；内蒙古_锡林郭勒_苏尼特右旗；内蒙古呼和浩特；内蒙古包头石拐；内蒙古包头；内蒙古通辽通辽经开区；内蒙古通辽；内蒙古包头土默特右旗；内蒙古呼和浩特土默特左旗；内蒙古巴彦淖尔乌拉特中旗；内蒙古巴彦淖尔乌拉特前旗；内蒙古乌兰察布察哈尔右翼前旗；内蒙古巴彦淖尔五原；内蒙古呼和浩特；内蒙古鄂尔多斯；内蒙古乌兰察布', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪蒙疆参议府议长，伪政务院院长，德王核心幕僚，起草伪政权法令。结局：1949 年逃往台湾，客死台湾，未受审判；伪职：德王核心幕僚，伪蒙疆政务院部长；参与全套分裂政策，在厚和主持奴化宣传、教育。；结局：战后关押，特赦释放；参与伪蒙疆政权建设，在丰镇、乌兰察布等地组织伪行政机构，配合日军“治安强化”运动，迫害抗日军民。；作为伪蒙疆高层，参与制定对乌兰察布、兴和地区的“治安强化”政策，支持日军“三光”作战。；参与伪蒙政权决策，协助日军在乌兰察布、凉城等地推行保甲制度，组织伪警察镇压抗日活动。；参与策划伪蒙古军政府成立，在化德地区协助日伪政权推行殖民统治，参与“防共”和镇压抗日活动。；德王亲信，参与伪蒙疆政府行政事务，在乌兰察布地区推行日伪政策，强征劳工，压迫民众。……（共涉及62个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.986140', '2026-09-10 09:57:13.986140', '内蒙古', '乌兰察布', '丰镇', NULL, NULL, NULL, NULL, '');
