INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a80ca42db94407cbeffb7265df59713', '李庆萱', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪锦西县后期县长；罪行：执行战时粮食出荷，疯狂搜刮物资；强征劳工运往矿山与边境要塞。；结局：日本投降后被捕判刑。', '[]', '2026-09-10 09:57:14.076876', '2026-09-10 09:57:14.076876', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
