INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a88b33253f749f286d40d5c81a4174e', '郑禹', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁_沈阳_和平；辽宁；云南_昆明_呈贡；吉林；福建闽侯；辽宁沈阳；辽宁_沈阳_皇姑', '[]', '[]', '抗日战争时期', '', '伪职：伪奉天市末代市长；罪行：郑孝胥之子，伪满后期奉天市长，执行日军末期搜刮政策。；结局：1945 被苏军逮捕，关押抚顺战犯管理所，1954 年病死。；继任伪奉天市长，积极执行日本“满洲国”政策，奴役市民。；伪满总理郑孝胥之子，任伪奉天市长，协助日军搜刮战略物资，强征劳工。；伪满末期沈阳市长，协助日军实行“战时体制”，强征金属、粮食，镇压地下抗日活动。', '[]', '2026-09-10 09:57:13.982723', '2026-09-10 09:57:13.982723', '辽宁', '福州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a90ed92cb0044558bd4cf22600805f0', '吴兆麟', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁通山；湖北咸宁；湖北荆州沙市；湖北荆州', '[]', '[]', '抗日战争时期', '', '通山人，咸宁周边地区汉奸，日军侵占通山后出面组织维持会，协助日军维持地方秩序。；湖北伪政权参议，参与伪政决策，其活动涉及荆州、沙市地区的伪政推行。', '[]', '2026-09-10 09:57:14.054971', '2026-09-10 09:57:14.054971', '湖北', '咸宁', '通山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a912756295a4fd4bab88e541e612181', '唐蟒', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_衡阳；湖南长沙岳麓；湖南长沙；湖南株洲渌口；湖南长沙浏阳；湖南_益阳_益阳大通湖管理；湖南_怀化_溆浦；湖南衡阳南岳；湖南衡阳；江苏南京江宁；江苏南京；江苏南京鼓楼；湖南长沙浏阳；湖南长沙；湖南株洲茶陵；湖南长沙', '[]', '[]', '抗日战争时期', '', '湖南浏阳人，投靠汪伪，参与伪军事机构，其附逆行为对湖南籍军人投伪有影响。；湖南浏阳人，投靠汪伪，参与伪政权军事与地方事务，战后被审判。；湖南浏阳人，1944年日军占领湖南大部后，被推为伪湖南省政府主席，主持伪政权，为日军征粮、征夫，是湖南沦陷区最高伪职人物。；在湖南沦陷区组织伪保安部队，配合日军维持占领区秩序，参与伪政权军事活动。；湖南浏阳人，抗战后期在湖南沦陷区出任伪职，协助日军管理长沙及周边地区。；湖南本地人，日军占领长沙后出任伪职，协助日军征粮、拉夫，维持伪政权基层统治。；湖南浏阳人，唐生智之弟，投靠汪伪，任伪参军长，参与伪军事务。；在南京鼓楼区参与伪立法，为日本侵略提供法律依据。；湖南籍，汪伪政权参军处参军，后任伪湖南省政府顾问，参与湖南伪政权筹划，与衡阳、南岳地区有籍贯及人脉关联。；湖南籍伪官员，继任汪伪湖南省长，在湖南沦陷区维持伪政权，协助日军统治，搜刮物资。；湖南浏阳人，汪伪政权中任伪湖南省政府主席，直接参与湖南沦陷区伪化统治，与永州零陵地区有行政管辖关联。；湖南籍，汪伪政权中任伪职，曾被任命为伪湖南省长但未实际掌控湖南，仍属湖南籍附逆要员。；湖南浏阳人，原国民党元老唐才常之子，1944年长沙沦陷后投敌，任伪长沙维持会顾问，后任伪湖南省政府委员，在长沙从事汉奸活动。；湖南浏阳人，汪伪政权军事成员；与衡阳蒸湘无直接地方关联。；湖南浏阳人，汪伪军事委员会成员，参与伪军建设，其活动范围涉及华中，与湖南长沙、宁乡地区有间接联系。；汪伪政权名义高官，在南京为伪政权撑门面。；湖南浏阳人，汪伪政权军事参议，参与伪军策反与伪化宣传，与湘籍伪政权人物关系密切。；湖南籍旧军人，抗战后期投靠日军，在湘中地区组织伪军，配合日军对长沙周边抗日武装进行扫荡。；湖南浏阳人，1944年湖南大部沦陷后，被日军扶植为伪湖南省长，在长沙、岳阳等地建立伪政权。；唐生智之弟，被日方考虑为伪湖南省长人选，但未实际就任，后逃往香港。；湖南浏阳人，日军侵占湖南后出面组织伪政权，任伪湖南省政府主席。；湖南浏阳人，抗战后期出任伪湖南省政府主席，为湖南伪政权最高头目之一；其伪政权名义上统辖湖南各县伪组织，郴州、永兴地区伪维持会、伪警察所亦在其体系内。', '[]', '2026-09-10 09:57:14.033631', '2026-09-10 09:57:14.033631', '江苏', '南京', '江宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a9185f200f64d3388f0948c654caddd', '汪精卫', '季新', '精卫', 1883, 1944, 'exact', 'exact', '浙江山阴', '[\"\\u6C6A\\u5146\\u94ED\"]', '[\"\\u4F2A\\u7EF4\\u65B0\\u653F\\u5E9C\\u884C\\u653F\\u9662\\u957F\",\"\\u534E\\u4E2D\\u5934\\u53F7\\u6C49\\u5978\"]', '抗日战争时期', '汪伪政权；汪伪政权 / 中国国民党', '伪任职务：汪伪国民政府主席、行政院院长，在南京建立汪伪政权，签署卖国条约，承认伪满洲国。结局：1944 年病死于日本名古屋；战后坟墓被炸毁，挫骨扬灰；汪兆铭，笔名精卫，历史上多以「汪精卫」称呼。祖籍浙江山阴（今绍兴），出生于广东三水（今属佛山市），是民国时期的重要政治人物。早年投身革命，曾谋刺清摄政王载沣未遂，袁世凯统治时期赴法国留学。回国后于1919年在孙中山领导下，驻上海创办《建设》杂志。1921年孙文在广州就任大总统，汪精卫任广东省教育会长、广东政府顾问。1924年任中央宣传部长。后期思想明显退变，于抗日战争期间投靠日本，在南京成立伪国民政府，沦为汉奸。1944年在日本名古屋因「骨髓肿」病死。', '[]', '2026-09-10 09:57:13.981593', '2026-09-11 02:28:37.139309', '', '芜湖', '绩溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a95633e482d4263b2ddc8778273d5d4', '敖门达赖', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大兴安岭新林；北京大兴', '[]', '[]', '抗日战争时期', '', '原蒙古族军官，投日后率伪兴安军在大兴安岭北部巡逻，多次与抗联第三支队交战，杀害抗联战士。', '[]', '2026-09-10 09:57:14.066124', '2026-09-10 09:57:14.066124', '黑龙江', '大兴安岭', '新林', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2a9a85a6d3fb4bf8a6f941206ed5d7bd', '王天和', NULL, NULL, NULL, NULL, 'exact', 'exact', '金门', '[]', '[]', '抗日战争时期', '', '伪职：伪金门特别区署科长；罪行：辅佐王廷植，执行苛政，督办鸦片种植。；结局：汉奸案判刑。', '[]', '2026-09-10 09:57:14.082847', '2026-09-10 09:57:14.082847', '福建', '泉州', NULL, NULL, NULL, NULL, NULL, '');
