INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2aa57eb7f8ae40189377a254b4a96ae1', '陈樵', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建_福州_闽侯；福建莆田；福建泉州晋江', '[]', '[]', '抗日战争时期', '', '晋江人，日军占领晋江期间任伪维持会会长，协助日军征粮拉夫、推行保甲制度。；福建人，抗战时期任伪福建省政府委员兼教育厅长，推行奴化教育，篡改教材，宣传“中日亲善”。；在日伪控制莆田期间出任伪县知事，执行日伪政令，协助征收赋税、登记户口。；在日军扶植下出任伪莆田县知事，推行伪化教育，配合日军清乡，搜捕抗日人士，强征物资供给日军。', '[]', '2026-09-10 09:57:14.062019', '2026-09-10 09:57:14.062019', '福建', '泉州', '晋江', NULL, NULL, NULL, NULL, '');
