INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2aad4854b3c041c18ff6a1114efd416f', '郭金城', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东_潍坊_奎文；山东潍坊寒亭；山东潍坊安丘；山东聊城高唐；山东潍坊昌乐；山东菏泽郓城；山东德州平原；山东德州；山东潍坊青州', '[]', '[]', '抗日战争时期', '', '武城属德州地区，日军侵占后组织伪维持会，协助日军维持地方秩序、摊派物资。；控制高唐部分乡镇，建立保甲制度，强征壮丁，配合日军清剿抗日武装，勒索百姓财物。；任伪郓城县警察局长期间，带领伪警察配合日军搜捕抗日人员，在郓城、鄄城边境地区制造多起惨案。；寒亭沦陷后出任伪维持会会长，为日军征粮、派夫，协助日军控制寒亭一带。；任伪益都县长期间，配合日军统治青州地区，征粮征丁，镇压抗日活动。；在昌乐县组织伪保安团，配合日军进攻抗日根据地，抓捕抗日人员。；安丘沦陷后组织维持会，任伪县长，协助日军建立伪政权，征发民夫、粮食，破坏抗日组织。；在潍县城区及周边村镇搜捕抗日人员，镇压群众反抗，配合日军进行治安强化运动。；潍县本地人，投靠日军后任伪警察局长，镇压抗日群众，搜捕抗日人员，直接参与潍县地区的日伪统治。', '[]', '2026-09-10 09:57:14.014016', '2026-09-10 09:57:14.014016', '山东', '德州', '平原', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2ab78ae0f88645e4a79c94def9388f1e', '黄飞', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西南宁马山；广西柳州融水；广西南宁；江西吉安万安；辽宁沈阳大东；广西贵港平南；江西赣州大余；江西赣州南康；江西吉安遂川；云南普洱西；广西南宁兴宁；云南普洱西；江西吉安安福', '[]', '[]', '抗日战争时期', '', '在南宁沦陷期间投靠日军，出任伪警务头目，协助日军搜捕抗日人员、维持伪治安。；抗战后期在赣南一带收编土匪、散兵，组织伪军配合日军行动，骚扰赣县、南康、大余等地抗日后方。；抗战后期投靠日军，在广西境内收编土匪、组建伪军，配合日军扫荡抗日根据地。；参与伪南宁维持会事务，协助日军推行保甲、征粮和宣传‘中日亲善’。；日军侵占南宁期间，与田次廉等组织伪南宁维持会，任副会长，协助日军推行保甲、征发民夫物资，镇压抗日活动。；与田次廉共同组织伪南宁维持会，为日军侵占南宁提供地方协助。；在日军占领南宁期间出任伪警察局长，协助日军搜捕抗日人士、镇压民众反抗。；日军占领广西期间，出面组织伪绥靖机构，拉拢地方士绅投敌，在马山、都安一带活动，为日军筹粮筹款。；日军侵占贵县期间，出面组织维持会，为日军征粮、派夫，维持地方伪秩序。；在安福推行奴化教育，强制学校使用伪编教材，向学生灌输亲日思想，为日伪统治培养顺民。；在伪江西省政府中负责亲日宣传，推行奴化教育，为日军侵略辩护。；在吉安日伪政权中负责宣传，鼓吹“大东亚共荣”，为日军侵略辩护。', '[]', '2026-09-10 09:57:14.030690', '2026-09-10 09:57:14.030690', '广西', '南宁', '良庆', NULL, NULL, NULL, NULL, '');
