INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2b2a6bfc6fc041468a067f368411b0a5', '张群', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都；甘肃甘南合作；四川成都金堂；四川资阳；四川成都彭州；四川成都', '[]', '[]', '抗日战争时期', '', '抗战初期曾代表国民政府与日本进行秘密接触，后未公开投敌，但因其妥协倾向被时人诟病。；在任期间对日军空袭成都、彭县等地应对不力，且与日方有秘密接触，被指消极抗日。；在日军压力下与伪政权合作，维持四川地区伪秩序，镇压抗日活动，为日军提供战略物资。；原国民党官员，后投靠日军，任伪四川省政府主席，在四川地区推行日军政策，协助征粮征税。', '[]', '2026-09-10 09:57:14.001678', '2026-09-10 09:57:14.001678', '四川', '成都', '彭州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2b2df46093b249f89fe99d78d676f20c', '孙耀东', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；河南信阳罗山；河南信阳；湖北襄阳谷城；黑龙江鸡西；湖北襄阳；辽宁沈阳大东；湖北襄阳枣阳；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '组织亲日文化团体，宣传“大东亚共荣圈”，进行奴化宣传。；任伪襄阳县教育科科长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日伪培养顺民。；出面组织伪商会，为日军摊派款项、物资，协助控制襄阳城区经济。；伪东安省警察头目，辖今鸡西地区，协助日军镇压抗日力量，实施殖民统治。；控制谷城沦陷区商业，为日军采购军需物资，协助日军对粮食、棉花等实行统制，盘剥民众。；在豫南地区代表伪河南省政权协调各县伪化工作，督促信阳、罗山等地征粮征丁，配合日军经济掠夺。', '[]', '2026-09-10 09:57:14.046495', '2026-09-10 09:57:14.046495', '河南', '信阳', '罗山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2b2ef0a241a84574aa4dc0ff04cf48e9', '王永树', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江丽水庆元；浙江台州路桥；浙江台州；福建宁德福鼎；福建宁德；浙江温州', '[]', '[]', '抗日战争时期', '', '浙江人，汪伪浙江省政府官员，协助日军统治。；浙江温州人，抗战期间组织伪维持会，协助日军管理温州地区，推行日伪政策。；抗战期间投靠日军，在黄岩组织伪维持会，后任伪黄岩县县长，协助日军征粮、派款、维持占领区秩序，镇压抗日活动。黄岩与路桥地域相邻，其伪政权活动覆盖今台州路桥一带。；在宁德地区组织伪维持会，为日军筹集物资、提供情报，协助维持日伪统治。', '[]', '2026-09-10 09:57:14.049476', '2026-09-10 09:57:14.049476', '浙江', '丽水', '庆元', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2b33cb7851b74fbd95c2c9fd39504c1f', '林汝舟', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州平阳；浙江温州；浙江_温州_苍南；浙江温州永嘉；浙江温州乐清；浙江温州；浙江台州天台；浙江台州仙居；浙江温州龙港；浙江温州瑞安；浙江台州椒江；浙江温州瑞安；浙江温州', '[]', '[]', '抗日战争时期', '', '在仙居组织伪政权，配合日军“清乡”，杀害抗日群众数十人。；组织伪绥靖军，配合日军在温州、瑞安一带扫荡，残害抗日军民。；在椒江海门地区组织伪维持会，为日军征收税赋，强迫居民领取“良民证”，举报抗日活动。；原国民党官员，后投敌，任伪绥靖公署参议，为日军提供温州地区情报，策反国民党部队。；投靠日军后担任伪职，参与策划对浙南抗日根据地的清剿行动。；在瑞安沦陷期间出任伪知事，配合日军“扫荡”，强迫百姓领取“良民证”，并出卖抗日游击队情报。；为日军征调物资，强迫商户缴纳“慰劳金”，协助日伪经济掠夺。；温州沦陷期间任维持会长，为日军提供物资情报，协助建立伪政权。', '[]', '2026-09-10 09:57:14.049974', '2026-09-10 09:57:14.049974', '浙江', '台州', '天台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2b4e93ca78074c0bab97a3c996d2eba4', '王知生', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北_恩施；湖北武汉；湖北宜昌五峰；湖北宜昌；湖北_咸宁_嘉鱼；湖北武汉；湖北宜昌点军；山西阳泉城区；湖北咸宁咸安；湖北咸宁；湖北武汉东西湖；湖北武汉武昌；湖北武汉；湖北武汉汉阳；湖北孝感大悟；湖北孝感；湖北咸宁通山；湖北武汉；湖北襄阳保康；湖北襄阳；湖北黄冈；湖北孝感汉川；湖北武汉汉南；湖北武汉汉阳；湖北咸宁崇阳；湖北咸宁', '[]', '[]', '抗日战争时期', '', '孝感沦陷后组织维持会，出任伪孝感县县长，为日军征粮派款、维持地方伪秩序。；在伪汉口市政府任职期间，协助日军实施物资统制、劳工征发等政策。；抗战期间投敌，任伪湖北省政府委员、伪汉口市市长等职，在武汉地区推行日伪政策，协助经济掠夺。；抗战期间投敌，在湖北沦陷区担任伪政权职务，协助日军统治。；汪伪政权官员，曾任伪湖北省政府委员，后任伪汉口特别市市长，在武汉地区推行伪政，配合日军经济掠夺。；任伪武汉特别市警察局局长，统领伪警察配合日军搜捕抗日人员、管制市民、推行保甲连坐。；抗战期间投敌，任伪武汉警察总监，在武汉地区协助日军维持治安，镇压抗日民众。；抗战期间投敌，任伪武汉特别市社会局局长，在武汉地区推行奴化教育和社会控制。；咸宁沦陷后出面组织伪咸宁县维持会，为日军征发民夫、粮食，维持占领区秩序。；任伪汉阳县县长，在汉阳地区推行保甲制度，征发劳工与物资，配合日军清乡，镇压当地抗日活动。；抗战期间任伪襄阳县政府县长，在襄阳地区协助日军维持伪政权，推行保甲制度，搜刮民财。；日军占领武汉后组织伪汉口市维持会并任会长，为日军筹粮筹款，诱降地方士绅，协助建立伪政权。；在武汉地区任伪职，参与伪湖北省政权，负责武昌地区伪化行政事务。；湖北黄冈人，出任伪黄冈县县长，为日军征粮征税，协助殖民统治。；武昌沦陷后组织伪维持会，任会长，协助日军安民、征工征粮，维持武昌地区伪秩序。；在伪湖北省及武汉特别市政府任职，参与伪政权决策与行政。；日军占领宜昌后出面组织维持会，后任伪宜昌县县长，协助日军征发民夫、物资，维持占领区基层统治。；汉阳沦陷后组织维持会，后任伪汉阳县县长，管辖区域包括今汉南一带，为日军征发民夫、粮食，维持伪化统治。；咸宁沦陷后组织维持会，任伪咸宁县维持会会长、伪县长，为日军征粮、拉夫、维持治安。；咸宁沦陷后组织维持会，后任伪咸宁县县长，为日军征粮、拉夫、搜集情报，镇压当地抗日力量。；汉川沦陷后出面组织维持会，后任伪汉川县政府县长，为日军征粮派款、维持地方伪秩序。；宜昌沦陷后出面组织伪维持会，任会长，协助日军维持宜昌城区及周边治安，为日军征发民夫、物资。；抗战期间在武汉伪政权中主管卫生，协助日军维持占领区公共卫生秩序。', '[]', '2026-09-10 09:57:14.055035', '2026-09-10 09:57:14.055035', '湖北', '咸宁', '咸安', NULL, NULL, NULL, NULL, '');
