INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d1b63232ae445068d23d3ec7cce316f', '李树馨', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西朔州山阴', '[]', '[]', '抗日战争时期', '', '原为地方土匪头目，日军占领山阴后率部投敌，任伪保安队长，多次带队袭击八路军游击队，杀害抗日干部，并参与日军在岱岳镇、古城镇等地的烧杀抢掠。', '[]', '2026-09-10 09:57:14.023422', '2026-09-10 09:57:14.023422', '山西', '朔州', '山阴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d2a26cbce8e4b2da32d18aaecd6e697', '袁文会', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津宝坻；天津；天津东丽；天津河北；湖南常德津；河北秦皇岛山海关；河北秦皇岛；天津、河北；河北秦皇岛昌黎', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：青帮大头目，伪安清道义会首领，为日军搜集情报、抓捕劳工、残害爱国人士。结局：1950 年天津公审，判处死刑枪决；在天津东丽一带经营赌场烟馆，为日军搜集情报，参与迫害抗日群众，是地方恶霸型汉奸。；投靠日军，组织汉奸武装，为日军充当特务，绑架勒索抗日人士，控制码头和烟馆，为日军提供情报。；天津青帮头子，投靠日军，在天津开设赌场烟馆，协助日本宪兵队抓捕抗日分子，参与“治安维持会”。；在天津及滨海地区（塘沽、大沽）控制码头和烟馆，为日军充当爪牙，绑架、暗杀抗日人士。；在山海关、秦皇岛一带组织汉奸武装，协助日军维持治安，残害百姓……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.002559', '2026-09-10 09:57:14.002559', '天津', '东丽', '山海关', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d2bc2093e574d7e96cd2da359299c56', '黄宗南', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖城内', '[]', '[]', '抗日战争时期', '', '伪职：伪保安一中队中队长；罪行：伪军主力，驻守伪县政府鼓楼，维护城区伪统治，下乡参与扫荡。；结局：战后被俘惩处。', '[]', '2026-09-10 09:57:14.074263', '2026-09-10 09:57:14.074263', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d36753a70a84fc187634ce4ff676429', '李国栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江西吉安永丰；江西吉安新干；河北衡水武强；河北唐山滦州；河北唐山；福建宁德屏南；福建宁德；河北；安徽安庆大观；贵州遵义习水；辽宁沈阳大东；江西上饶；河南周口太康；河南周口；云南德宏芒市；贵州贵阳修文；贵州贵阳；甘肃天水；安徽滁州天长；江苏南京六合；安徽马鞍山含山；黑龙江_黑河_北安；福建福州闽侯；辽宁沈阳和平', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山周边制造恐怖，逼村民供出抗日分子。；在唐山周边村庄搜捕抗日干部，杀害无辜百姓。；为日军搜集抗日情报，破坏地下党组织，逮捕并刑讯抗日人士，助纣为虐。', '[]', '2026-09-10 09:57:13.980549', '2026-09-10 09:57:13.980549', '云南', '德宏', '芒市', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d3686f4917f4e41acdd295fbbb1fca6', '韩铁汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '逊克、北安交界朝阳山', '[]', '[]', '抗日战争时期', '', '伪职：原抗联三军人员，叛徒；罪行：叛变投敌，杀害抗联三军三师政治部主任常有钧；充当伪讨伐队向导，在朝阳山一带搜剿抗联西征部队，出卖山林密营信息。；结局：解放后镇压反革命公审枪决。', '[]', '2026-09-10 09:57:14.071383', '2026-09-10 09:57:14.071383', '黑龙江', '黑河', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d36cc7982c94fa8aeef3f0f05071e0b', '贺秉温', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼和浩特清水河；内蒙古；内蒙古包头达尔罕茂明安；归绥；内蒙古呼和浩特托克托；内蒙古呼和浩特和林格尔；内蒙古包头；内蒙古呼和浩特；内蒙古呼和浩特玉泉；内蒙古乌兰察布集宁', '[]', '[]', '抗日战争时期', '', '伪职：第一任伪厚和市市长；日军入城牵头组织归绥维持会，迎接日军；后任伪蒙疆土药（鸦片）公司董事长，大规模收购鸦片，毒化沦陷区，搜刮巨额资财供给日军。；结局：1945 北平被捕，1948 绥远高等法院判处无期徒刑，狱中病死；在集宁县城为日军征粮、征夫，推行奴化教育，镇压抗日活动。；在包头、东河地区充当日军鹰犬，搜捕抗日地下工作者，镇压民众反抗，参与“特别治安”行动。；投靠日军，任伪归绥（今呼和浩特）市长，推行日伪政令，强征劳工，搜刮民财。；投靠日军任伪县长，在托克托县推行日伪法令，强征苛捐杂税，出卖抗日分子，协助日军建立维持会。；任伪归绥市市长期间，管理旧城（玉泉区）行政事务，执行日伪“治安肃正”计划，强制居民领取“良民证”，并参与奴化宣传。', '[]', '2026-09-10 09:57:13.987412', '2026-09-10 09:57:13.987412', '内蒙古', '呼和浩特', '察哈尔右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d40026b4e5547c4900d61b76e4e5edc', '张荫梧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河南新乡延津；天津河北；河北沧州任丘；河北衡水深州；天津河北；河北保定定州；河北沧州南皮；河北沧州；河北_沧州_运河；天津河北；河北_沧州_青县；河北衡水；河北保定保定白沟新城；天津河北；河北保定博野；河北_保定_唐县；河北衡水武邑；天津河北；河南济源；河北邯郸涉县；河南安阳；河南鹤壁；河南_鹤壁_鹤壁经开区；河南_鹤壁_鹤山；河北保定容城；河北保定高阳；河北_沧州；河北廊坊大厂；河北_廊坊_霸州；河北_廊坊_香河；河北保定涞源；河北沧州任丘；河北沧州；河北_廊坊_廊坊经开区；河北保定定兴；河北石家庄行唐；天津河北；河北保定徐水；河北保定；河南鹤壁淇滨；河南鹤壁；河南周口扶沟；河南商丘；天津河北；河北廊坊；河南新乡；天津河北；河南濮阳清丰；天津河北；河北衡水冀州；天津河北；河南漯河临颍；青海黄南河南；河北保定蠡县；天津河北；河北保定高阳；河北_沧州_献县；河北沧州肃宁；河北衡水桃城；河北衡水；河北邢台；河北_邢台_柏乡；河北保定；河北衡水故城；天津河北；河北邢台新河；河北邢台；河北廊坊三河；北京平谷；北京、河北；河北_廊坊；河北廊坊安次；河北保定顺平；河北邯郸永年；河北邯郸；河北沧州新华；河北石家庄新华；河北沧州沧县；河北邢台；北京密云', '[\"张荫梧系\", \"注：其活动主要在冀中，但涉及顺平\"]', '[]', '抗日战争时期', '', '率伪军配合日军“铁壁合围”，在密云云蒙山区烧毁村庄数十个。；原国民党将领，后与日军勾结，在保定地区组织伪军，协助日军清剿抗日武装。；原国民党河北省民政厅长，投日后负责保定地区伪政权行政事务，协助日军强征粮食、劳工，在白沟新城一带破坏抗日地道。；原国民党将领，抗战初期在河北组织民军，后与日军勾结，在保定地区协助日伪清剿抗日武装。；原国民党将领，后与日军勾结，任伪河北省保安司令，在保定地区组织伪军袭扰抗日武装。……（共涉及70个地区的犯罪记录）；虽名义上抗日，但多次与八路军摩擦，1942年后其部属在顺平一带与日军暗中勾结，提供情报，协助清剿。；日军侵占涞源后率先组织维持会，为日军提供粮草、向导，协助建立伪政权，并煽动民众投降，后随日军行动，参与清乡。；投日后在冀中（含廊坊南部）组织“还乡团”，对抗日家属进行报复性屠杀。', '[]', '2026-09-10 09:57:13.993727', '2026-09-10 09:57:13.993727', '北京', '密云', '保定白沟新城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d4d23bd7e4c4880bb2ca6c60ffeba71', '陈命凡', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东_青岛_城阳；山东烟台海阳；山东烟台；山东青岛；山东_青岛_市南；山东青岛；山东青岛黄岛', '[]', '[]', '抗日战争时期', '', '推行奴化教育，篡改教材，向青岛学生灌输亲日思想，协助日军进行文化侵略。；推行亲日奴化教育，改编学校课程，组织师生参加日伪宣传活动，为殖民统治培养顺民。；管理青岛伪政权财政，为日军搜刮物资，支持侵略战争。；在伪警察系统中担任要职，参与逮捕抗日人士。；推行奴化教育，篡改教材，向学生灌输亲日思想。；在烟台地区为日军筹款筹物，协助经济掠夺，属于经济领域附逆者。', '[]', '2026-09-10 09:57:14.017170', '2026-09-10 09:57:14.017170', '山东', '烟台', '海阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d55c7a7526a4b2491afb5a1277d113a', '高占奎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄栾城；河北_保定_定州；河北', '[]', '[]', '抗日战争时期', '', '指挥伪警察抓捕抗日地下党员，破坏地下交通站，参与“清乡”行动。；专门搜集八路军和抗日政府情报，多次导致抗日人员被捕牺牲。', '[]', '2026-09-10 09:57:14.040895', '2026-09-10 09:57:14.040895', '河北', '石家庄', '栾城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d5afec0f09a4e40ba798aa83a936968', '蔡鑫元', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州姜堰；江苏泰州；靖江、泰兴', '[]', '[]', '抗日战争时期', '', '伪职：伪暂编第十九师师长；罪行：手握数千伪军，盘踞靖泰地区，争夺地盘，四处劫掠；配合日军清乡扫荡，大肆搜捕地下抗日人员，祸害靖西乡村中国共产党...。；结局：抗战胜利后以汉奸罪处决。', '[]', '2026-09-10 09:57:14.035930', '2026-09-10 09:57:14.035930', '江苏', '泰州', '姜堰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d5b6373561e454dbeae1ce8905318a9', '李宏锟', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都', '[]', '[]', '抗日战争时期', '', '抗战期间投敌，在伪四川省政府任职，后任伪成都市市长，推行日军政策，镇压抗日活动。；任伪成都警察局局长期间，搜捕抗日志士，镇压学生抗日运动，为日军提供情报。；在成都地区组织伪警察队伍，配合日军搜捕抗日人士，镇压民众抗日活动。；抗战期间在成都地区投敌，担任伪警察局局长，参与镇压抗日活动、维护日伪统治。；任伪成都警察局局长期间，配合日军搜捕抗日人士、维持治安，镇压民众反抗。；抗战期间在成都日占区任伪警察局局长，协助日军镇压抗日活动、搜捕抗日人士。', '[]', '2026-09-10 09:57:14.001906', '2026-09-10 09:57:14.001906', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d61f72a5bb547b791166743e68483cb', '张升臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪盘山县末代县长；罪行：伪满末期维持伪政权。；结局：八一五后被民主政府逮捕。', '[]', '2026-09-10 09:57:14.080855', '2026-09-10 09:57:14.080855', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d692ea3d80c4da7ab542d5f31f089b7', '李黑马', NULL, NULL, NULL, NULL, 'exact', 'exact', '襄垣', '[]', '[]', '抗日战争时期', '', '伪职：伪襄垣警备大队长；罪行：伪军头目，多次袭扰襄垣周边根据地村庄。；结局：被俘后处决。', '[]', '2026-09-10 09:57:14.068177', '2026-09-10 09:57:14.068177', '山西', '长治', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d7527674edc486b9b4bd8fdf1ffada3', '杨德三', NULL, NULL, NULL, NULL, 'exact', 'exact', '固阳', '[]', '[]', '抗日战争时期', '', '伪职：伪保安团团长；1937 奉日军命令攻占大佘太，洗劫商号，建立伪据点；1938 被门炳岳部击溃，化装逃跑，之后继续为日军驻守大佘太，配合日军扫荡周边中共巴彦淖...。；结局：解放后镇反公审枪决', '[]', '2026-09-10 09:57:14.083321', '2026-09-10 09:57:14.083321', '内蒙古', '包头', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d7c38768fdf439d8c76080274c0cf8d', '苏盛江', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪山西省警务厅长；罪行：掌管全省伪警察系统，指挥特务搜捕地下党，推行保甲连坐。；结局：抗战胜利被捕判刑；伪任职务：伪山西省警务厅长，掌控全省伪警察特务系统，镇压根据地。结局：抗战胜利被捕，判处徒刑，狱中死亡；伪职：第二任伪河东道道尹；罪行：接续统治晋南，强化剿共，搜刮物资，抓捕抗日人员。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.076510', '2026-09-10 09:57:14.076510', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d7edee94756466a9620a368e8c778fa', '沈九皋', NULL, NULL, NULL, NULL, 'exact', 'exact', '象山丹城、石浦', '[]', '[]', '抗日战争时期', '', '伪职：伪象山维持会会长；罪行：象山沦陷组建伪维持会，迎接日军，筹措粮草物资，胁迫乡绅附逆，搭建基层伪统治。；结局：抗战胜利后清算判刑。', '[]', '2026-09-10 09:57:14.069172', '2026-09-10 09:57:14.069172', '浙江', '宁波', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d966537ba5d46e3a3aac954d5c10691', '李芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北_宜昌；湖北咸宁通城；辽宁沈阳大东；湖北武汉黄陂；湖北武汉；湖北襄阳；湖北十堰；湖北武汉江汉；湖北武汉；陕西西安长安', '[]', '[]', '抗日战争时期', '', '在伪湖北省政府中负责教育，推行奴化教育，篡改教材。；列名伪湖北省政府委员，参与伪政权活动。；在通城推行奴化教育，强制学校使用伪教材，宣传“大东亚共荣圈”。；抗战期间投敌，任伪汉口市商会会长，在武汉地区协助日军进行经济统制和物资掠夺。；湖北十堰人，抗战期间投敌，任伪十堰地区维持会会长，协助日军维持地方治安，搜刮民财，镇压抗日活动。；武汉沦陷初期组织伪维持会，任会长，协助日军维持占领区秩序，征发民夫、物资，为日军侵略服务。；在汪伪政权中任外交要职，参与对日妥协。', '[]', '2026-09-10 09:57:14.054634', '2026-09-10 09:57:14.054634', '湖北', '十堰', '通城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d98ba8fb0a44b8981ec70f32be4244e', '李锡侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪巨鹿县县长；配合张百奎伪军，实施清乡、抓丁征粮。；结局：抗战胜利逮捕，判处无期徒刑', '[]', '2026-09-10 09:57:14.084573', '2026-09-10 09:57:14.084573', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d9be6a32da5404a92a6030995327348', '刘筱约', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；湖北宜昌宜都；湖北荆州沙市；湖北宜昌远安；湖北宜昌；湖北宜昌宜都；湖北荆州沙市；湖北荆州公安；湖北宜昌当阳；湖北宜昌', '[]', '[]', '抗日战争时期', '', '率伪保安团配合日军在宜昌、远安交界地区清乡，抓捕抗日军民。；宜都沦陷后出面组织维持会，协助日军征粮征夫，推行奴化宣传。；统率伪保安大队在宜昌地区协助日军维持治安，参与对抗日根据地的封锁与扫荡。；抗战期间在宜都地区组织伪保安团，配合日军扫荡抗日武装，维护伪政权统治。；公安县沦陷后组织伪维持会，协助日军征粮、征夫，维持占领区基层秩序。；沙市地区投敌商人，组织伪维持会，为日军提供情报和物资。', '[]', '2026-09-10 09:57:14.056024', '2026-09-10 09:57:14.056024', '湖北', '宜昌', '宜都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d9da477f4bd418691bdf4603380a46e', '胡宗璜', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城', '[]', '[]', '抗日战争时期', '', '在宣城沦陷区任伪警察头目，配合日军搜捕抗日人员，维持伪治安。', '[]', '2026-09-10 09:57:14.007879', '2026-09-10 09:57:14.007879', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2d9f077084c3498ebc721062fc539ea3', '王克明', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西汉中勉县；广东清远；陕西汉中汉台；陕西汉中；浙江_台州_玉环', '[]', '[]', '抗日战争时期', '', '日军侵占汉中期间，出面组织伪汉中维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。；在汪伪广东省政府主管经济，协助日军掠夺广东物资，推行统制经济，对清远、连州等地资源进行搜刮。；抗日战争初期，在勉县地区组织伪维持会，协助日军及伪政权维持地方治安，推行奴化教育，为日军征集粮秣。；为日军提供情报，逮捕并刑讯抗日群众，参与“清乡”行动，导致多名地下党员牺牲。', '[]', '2026-09-10 09:57:14.029402', '2026-09-10 09:57:14.029402', '陕西', '汉中', '勉县', NULL, NULL, NULL, NULL, '');
