INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2e6816fdfe694c74ad214fdcfc9b6d04', '彭勃', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_郴州_北湖；湖南常德武陵；湖南岳阳；辽宁沈阳大东；湖南衡阳雁峰；湖南衡阳；湖南邵阳大祥；湖南常德；湖南郴州资兴', '[]', '[]', '抗日战争时期', '', '衡阳沦陷后出面组织维持会，协助日军征粮、拉夫、维持治安，为日军占领衡阳提供地方支持。；在大祥镇组织维持会，为日军派粮派夫，协助维持占领区基层秩序。；汪伪政权在湖南设立伪保安武装，配合日军对沦陷区进行控制与扫荡。；汪伪湖南省警务负责人，在湖南占领区推行伪警察制度，镇压抗日活动。；日军侵占资兴期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。；在湖南沦陷区负责清乡工作，配合日军对常德、益阳等地区进行清乡扫荡，镇压抗日武装。；在长沙主办伪报纸，宣扬“大东亚共荣”，为日军占领政策进行文化宣传。', '[]', '2026-09-10 09:57:14.057764', '2026-09-10 09:57:14.057764', '湖南', '岳阳', '武陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2e6ab8d3d64e4e5d8c9da3033c74da8b', '伪永丰县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西吉安永丰', '[]', '[]', '抗日战争时期', '', '永丰沦陷区域伪维持会配合日军维持赣中占领区。', '[]', '2026-09-10 09:57:14.038631', '2026-09-10 09:57:14.038631', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2e6b814d42064f1ab82c9c7c171b5312', '达密凌苏龙', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '察哈尔右翼后旗；内蒙古呼伦贝尔牙克石；内蒙古；内蒙古_锡林郭勒_二连浩特', '[]', '[]', '抗日战争时期', '', '伪职：伪蒙古军第七师少将师长（驻商都）；原地方武装，1937 投日，指挥伪骑兵在商都、陶林一带扫荡，镇压草原抗日活动。；结局：1945 向苏蒙军投降，部队被带入外蒙古，后病死抖音百科；指挥伪蒙古军部队在锡林郭勒草原扫荡抗日游击队，并参与对苏蒙边境的侦察。', '[]', '2026-09-10 09:57:13.989219', '2026-09-10 09:57:13.989219', '内蒙古', '呼伦贝尔', '牙克石', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2e77493315f346f9a796373f1972f315', '陈漱云', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳汨罗；湖南衡阳衡山；湖南衡阳；湖南衡阳；湖南株洲茶陵；湖南湘潭；湖南湘潭湘乡', '[]', '[]', '抗日战争时期', '', '日军侵入茶陵期间，组织维持会，为日军筹粮、带路，协助日军在茶陵地区的统治。；衡阳沦陷期间，部分教育界人士参与伪教育机构，推行奴化教育，陈漱云被地方文史资料提及。；湘乡沦陷后组织维持会，为日军提供情报和后勤支持。；在衡阳沦陷区推行奴化教育，改编教材，强制学校教授日语与亲日内容，为伪政权培养顺民。；汨罗乡维持会会长，为日军征粮、带路，协助日军扫荡汨罗江两岸抗日游击队。', '[]', '2026-09-10 09:57:14.058090', '2026-09-10 09:57:14.058090', '湖南', '岳阳', '汨罗', NULL, NULL, NULL, NULL, '');
