INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2fee1b58c5164d87b74dbd9775425611', '徐景吾', NULL, NULL, NULL, NULL, 'exact', 'exact', '开封城区', '[]', '[]', '抗日战争时期', '', '伪职：伪政府财务科长（中共地下党员）；罪行：受党组织派遣打入伪政府任财务科长，实际从事抗日情报工作；结局：待考（潜伏人员）', '[]', '2026-09-10 09:57:14.082168', '2026-09-10 09:57:14.082168', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('2ff54460ce1c4e0b984b8444f85da52b', '扈全禄', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南滑县；河南鹤壁浚县；河南鹤壁；河南安阳；鹤壁（浚县/淇县/汤阴）', '[]', '[]', '抗日战争时期', '伪军', '伪职：伪河南剿匪总司令；罪行：原为豫北老牌匪首，抗战爆发后反复摇摆，最终投降日军，被委任伪河南剿匪总司令。部队活动于淇县、浚县、汤阴一带，配合日军扫荡，捕杀抗日军民，劫掠乡村。其主力多次遭八路军打击，屡次溃败又死灰复燃；结局：抗战结束后依附国民党顽军继续作恶，新乡解放时被俘，在狱中畏罪自缢；伪任职务：伪第六旅旅长，滑县浚县一带皇协军，祸害卫南地区。结局：卫南战役部队被歼灭，本人逃窜，后被捕获处决', '[]', '2026-09-10 09:57:14.047757', '2026-09-10 09:57:14.047757', '河南', '鹤壁', '浚县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3012bb5dc3b44d0ca9b889ab2803a0e2', '杨作明', NULL, NULL, NULL, NULL, 'exact', 'exact', '兴化城乡', '[]', '[]', '抗日战争时期', '', '伪职：伪 22 师主力团长；罪行：伪军骨干，带兵下乡扫荡，强拆民房木料砖石修筑碉堡，烧杀掠夺，百姓绰号 “火星菩萨”兴化日报。；结局：被新四军俘获，公审枪决兴化日报。', '[]', '2026-09-10 09:57:14.082251', '2026-09-10 09:57:14.082251', '江苏', '泰州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3014d15d92e542799ad23c0ea9fa6df5', '黄启明', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西萍乡莲花；广西桂林资源；广东汕头；福建龙岩长汀；福建龙岩连城', '[]', '[]', '抗日战争时期', '', '主办伪《潮汕日报》，为日军侵略宣传，粉饰殖民统治，诋毁抗日力量。；为日军筹款筹粮，强制商户缴纳“治安费”，协助日军掠夺地方资源。；连城县地主，投敌后组织伪维持会，为日军提供连城至长汀一带的地形情报，协助日军进攻抗日游击队。', '[]', '2026-09-10 09:57:14.028101', '2026-09-10 09:57:14.028101', '广东', '汕头', '莲花', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3015874c55ee4bd9a86d65b174befa16', '伊作衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔；黑龙江哈尔滨五常；黑龙江哈尔滨阿城', '[]', '[]', '抗日战争时期', '', '在五常、阿城等地组织“特别搜查班”，多次参与围剿抗联第十一军，残害抗日群众；齐齐哈尔人，任伪协和会齐齐哈尔本部总务部长，积极宣传“日满亲善”，组织奴化教育，煽动民众告密，破坏抗日群众组织。', '[]', '2026-09-10 09:57:14.065812', '2026-09-10 09:57:14.065812', '黑龙江', '哈尔滨', '五常', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3015f17c04fd45808ecf3aa918cda4c0', '李麟阁', NULL, NULL, NULL, NULL, 'exact', 'exact', '蒙城县城', '[]', '[]', '抗日战争时期', '', '伪职：蒙城沦陷时期伪商会会长；罪行：蒙城沦陷时出任伪商会头目，摊派商捐，搜刮物资供给日军；蒙城收复后尚未逃窜即被爱国县长马忍言抓捕处决中安在线。；结局：1939 年被就地枪毙。', '[]', '2026-09-10 09:57:14.076006', '2026-09-10 09:57:14.076006', '安徽', '亳州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('301de3c8277e4b618da24cd14d02497d', '赵晋卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '交城；山西、河北；山西运城夏县；河北唐山玉田', '[]', '[]', '抗日战争时期', '', '日军占领夏县后率先组织维持会，为日军提供情报，指认抗日家属，导致多人被捕遇害。；在玉田及冀东地区协助日军镇压抗日活动，推行保甲制度，抓捕抗日军民。；伪职：伪交城县县长；罪行：建立交城伪公署，管控交山要道，抓夫征粮，迫害抗属。；结局：光复后逮捕判刑', '[]', '2026-09-10 09:57:14.023715', '2026-09-10 09:57:14.023715', '山西', '运城', '夏县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('301f877fa0b44c69a5c214a8a97a9f61', '陈质平', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南海口；海南白沙；云南普洱西；海南三沙中沙；海南定安；海南三亚天涯；海南琼海；海南海口琼山；海南海口；海南三沙西沙；内蒙古乌海海南；海南三亚吉阳；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在定安地区附逆，建立伪行政机构，协助日军维持占领区秩序，迫害抗日群众。；推行奴化教育，在海口、琼山等地学校强制日语教学，篡改历史，为日军殖民统治培养顺民。；与日军海军特务部合作，参与海南岛资源调查与经济掠夺，为日军统治出谋划策。；在琼海地区组织维持会，为日军征派粮食、劳工，诱降抗日人员，配合日伪军扫荡乡村。；在海口商界为日军筹款筹物，协助经济掠夺，维持伪统治秩序。；在儋县组织伪维持会，协助日军控制西部沿海，征发渔盐物资，镇压抗日民众。；在崖县为日军筹款筹粮，控制物资流通，协助日军经济掠夺。；海南沦陷初期参与组织海口维持会，为日军筹粮、筹款、拉夫，协助建立日占区基层控制体系。', '[]', '2026-09-10 09:57:14.053143', '2026-09-10 09:57:14.053143', '海南', '三亚', '吉阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3021fc2f780e40c2818b5ac70bf12609', '朱阿大', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴秀洲', '[]', '[]', '抗日战争时期', '', '率自卫团协助日军修筑碉堡，封锁交通，并参与‘清乡’行动，抢劫民财，强奸妇女，民愤极大。', '[]', '2026-09-10 09:57:14.050693', '2026-09-10 09:57:14.050693', '浙江', '嘉兴', '秀洲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3027fc1b18554800a0c3e8c819894489', '朱骥', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州姜堰；江苏泰州', '[]', '[]', '抗日战争时期', '', '在苏北沿江地区为日军维持伪政权，配合日伪军对泰州、靖江一带抗日武装进行清剿。', '[]', '2026-09-10 09:57:14.035938', '2026-09-10 09:57:14.035938', '江苏', '泰州', '姜堰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('302c095061c5419a968f92869385d1e1', '林明伦', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南_三沙_中沙；海南临高', '[]', '[]', '抗日战争时期', '', '日军侵占临高后出面组织维持会，协助日军推行保甲制度、征发民夫与物资，维持地方伪秩序。；组建伪警察队伍，配合日军搜捕抗日人员，镇压民众反抗，维持占领区治安。', '[]', '2026-09-10 09:57:14.053455', '2026-09-10 09:57:14.053455', '海南', '临高', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('303635e0f55d4397989544853751e043', '王明甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南平顶山宝丰；河南平顶山；河南郑州荥阳；河南焦作沁阳；河南焦作；河南郑州；河南郑州新密；河南平顶山叶县；河南焦作；山西阳泉矿区；河南焦作焦作示范；河南焦作；河南焦作博爱；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '在郑州伪警察系统中任职，参与搜捕抗日人员、维持占领区秩序，配合日军对郑州及周边地区进行控制。；控制焦作商会，为日军筹款筹物，协助实行经济统制，压迫商户。；在焦作沦陷期间出面组织伪商会，为日军筹款、摊派物资，协助日伪对焦作工商业者进行控制与压榨。；叶县沦陷后投靠日军，组织伪保安团，配合日军清乡、扫荡，镇压抗日群众。；在平顶山矿区组织维持会，为日军掠夺煤炭资源提供劳力与情报，迫害矿工中的抗日分子。；平顶山地区煤矿区伪维持会头目，协助日军控制煤矿，强迫矿工劳动，为日军提供煤炭资源。；充任伪焦作镇镇长，推行保甲连坐，协助日军清查户口、抓捕抗日嫌疑人员。；荥阳本地士绅，1944年日军占领荥阳后投敌，组织伪维持会并任伪县长，协助日军控制荥阳及周边地区，征发民工、粮食。；在焦作矿区组织维持会，为日军掠夺煤炭资源服务，协助镇压矿工抗日活动。；在日军控制下为伪政权筹款筹粮，协助日军对矿区经济进行掠夺。；登封沦陷后组织伪政权，任伪县长，配合日军扫荡嵩山抗日根据地，活动区域与新密接壤。', '[]', '2026-09-10 09:57:14.047912', '2026-09-10 09:57:14.047912', '河南', '平顶山', '叶县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('30368f084d424b74a5089017fc83c47c', '史荷甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '蓬莱县', '[]', '[]', '抗日战争时期', '', '伪职：伪五区区长；罪行：蓬莱汉奸；结局：抗战胜利后潜逃；被通缉并没收财产', '[]', '2026-09-10 09:57:14.067038', '2026-09-10 09:57:14.067038', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3038bad151914af3908d23ec15ed6a6a', '董成高', NULL, NULL, NULL, NULL, 'exact', 'exact', '信阳县', '[]', '[]', '抗日战争时期', '', '伪职：日本特务组织“白天府”便衣队副队长；罪行：1944年夏，阴谋以谈判为名消灭公安局手枪队，发出“请柬”邀手枪队正、副队长到何家垮“赴宴”；结局：1944年被信阳公安局手枪队将计就计击毙', '[]', '2026-09-10 09:57:14.085316', '2026-09-10 09:57:14.085316', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3043c55de06b49e9be3ae2b40b77bc9f', '贾世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西_运城_平陆；山西长治武乡；山西忻州定襄；山西长治潞城；山西长治；山西；山西晋城泽州', '[]', '[]', '抗日战争时期', '', '垄断粮食和食盐配给，克扣百姓口粮，将物资优先供应日军，并低价强购农民粮食。；随日军宣抚班活动，诱降抗日人员，破坏抗日统一战线，参与建立伪乡村政权。；为日军征收各种附加税，盘剥商户和农民，将大量税款上交日军，支持侵略战争。；日军占领武乡县城后任维持会长，为日军筹集粮款，强迫村民‘欢迎皇军’，并告密导致多名抗日村长被杀。；在长治、潞城一带为日军摊派捐税，强抓壮丁补充伪军，并参与屠杀抗日俘虏。', '[]', '2026-09-10 09:57:14.021927', '2026-09-10 09:57:14.021927', '山西', '忻州', '定襄', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3044a9f8f7554b26bd9b8b3b8e68f3ed', '刘麻子', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台；河北保定清苑；广德誓节渡据点', '[\"刘振海\"]', '[]', '抗日战争时期', '', '伪职：广德誓节渡伪乡队长；罪行：伪武装爪牙，抓捕接济新四军百姓，掠夺山区竹木物资，残害乡民。；结局：抗战胜利后公审处决。；专门刺探八路军情报，带领特务抓捕抗日家属，严刑逼供，杀害多名地下党员。；为日军提供情报，导致任县多名地下党员被捕牺牲。', '[]', '2026-09-10 09:57:14.041105', '2026-09-10 09:57:14.041105', '河北', '保定', '清苑', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('304c245961344bbf87e9924625094cd4', '刘兴周', NULL, NULL, NULL, NULL, 'exact', 'exact', '平顶山周边；河南开封', '[]', '[]', '抗日战争时期', '', '伪职：伪开封警备司令；罪行：郏县人牛子龙率人潜入开封将其击毙。刘兴周疯狂残害抗日民众；结局：1939年被牛子龙击毙于河南省警备司令部门口', '[]', '2026-09-10 09:57:14.048135', '2026-09-10 09:57:14.048135', '河南', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('304f90bb8c524824b3944bdc59e901fc', '汤春耕', NULL, NULL, NULL, NULL, 'exact', 'exact', '衡阳城区', '[]', '[]', '抗日战争时期', '', '伪职：衡阳维持会成员（酒酱业）；罪行：衡阳沦陷期间充当汉奸，参加日伪维持会，为虎作伥', '[]', '2026-09-10 09:57:14.084730', '2026-09-10 09:57:14.084730', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3051c016aedc4b9ead0cd05d1b98d913', '宁春霖', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东泰安泰山；山东泰安；广西桂林灵川；辽宁沈阳和平；山东淄博临淄；山东淄博；山东泰安新泰；山东泰安；山东泰安', '[]', '[]', '抗日战争时期', '', '山东汉奸武装头目，活动于泰安、新泰地区，协助日军维持治安，进攻抗日武装。；在山东泰安、淄博一带活动，组织伪军协助日军维持统治。；协助日军在泰安地区推行殖民政策，参与伪政权决策。；原国民党军将领，1943年投敌，任伪和平建国军第三方面军参谋长等职，属山东伪军头目。；任伪泰安道尹期间，推行日伪政令，协助日军征粮、征丁，控制泰山地区。', '[]', '2026-09-10 09:57:14.014673', '2026-09-10 09:57:14.014673', '山东', '泰安', '新泰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('305b95113e0743fdab6660542f608bd5', '蔡宗熙', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北大兴', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪吴县县长，兼任保安、自卫团头目，推行奴化教育、封锁管制。。结局：抗战胜利被捕判刑苏州市地方...', '[]', '2026-09-10 09:57:14.078954', '2026-09-10 09:57:14.078954', '河北', '北京', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('30753e71e0084c458b9f4d59e7f647cb', '李宝明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权', '[]', '[]', '抗日战争时期', '', '宣传“中日亲善”，组织汉奸特务刺探八路军情报，破坏抗日群众组织。', '[]', '2026-09-10 09:57:14.022491', '2026-09-10 09:57:14.022491', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('307d9a309ab8408d8ee62d1cf30a6001', '张德全', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定易县', '[]', '[]', '抗日战争时期', '', '专门刺探八路军情报，带领特务队破坏抗日交通线，多次告密导致游击队损失。', '[]', '2026-09-10 09:57:14.040937', '2026-09-10 09:57:14.040937', '河北', '保定', '易县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3083c363b4874030be7f7184af02b0f5', '陈静波', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州乐陵；辽宁沈阳大东；山东德州德州经开区；山东德州；山东德州；河北邢台柏乡；河北邢台；安徽滁州来安；辽宁沈阳新民；广西桂林灵川；青海黄南河南；山东德州；辽宁沈阳新民；河北邢台南和；河北邢台；山东济南槐荫；山东济南', '[]', '[]', '抗日战争时期', '', '在德州地区掌管伪警察，配合日军搜捕抗日人员，维持殖民统治秩序。；控制邢台物资流通，为日军掠夺棉花、粮食等战略物资，压榨当地农民。；在德州地区组织伪保安团，配合日军对周边抗日武装进行清乡、扫荡。；组织新民会进行亲日宣传，协助日军控制民众思想与基层组织。；滁县沦陷区伪新民会头目，负责亲日宣传、组织民众团体，配合日军进行思想控制，其活动覆盖滁县、来安等地。；在伪乐陵县政权中负责教育，推行奴化教育，宣传“大东亚共荣”，毒化沦陷区青少年。；抗战期间投敌，组织伪河南自治军，任总司令，属河南伪军头目。；协助日军控制胶济铁路济南段，保障军运，镇压铁路工人抗日活动。；在邢台教育界推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动，影响包括南和在内的周边县区。', '[]', '2026-09-10 09:57:14.009342', '2026-09-10 09:57:14.009342', '安徽', '滁州', '来安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3087dd4e0f4b453cbaeee151d5ee1712', '赵锡三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北沧州南皮；河北沧州献县；河北沧州黄骅；河北；河北邢台宁晋；河北沧州东光；青海黄南河南；河北邯郸大名；河北邢台内丘', '[]', '[]', '抗日战争时期', '', '指挥伪警察抓捕地下党员，严刑逼供，破坏抗日组织。；负责在南皮推行奴化教育，组织“新民会”宣传“中日亲善”，强迫群众悬挂日伪旗，并密报抗日积极分子名单给日军宪兵队。；任伪沧县知事期间，推行保甲制度，强征壮丁，配合日军清乡，破坏中共地下组织。；在沧县东部及海兴一带设卡盘查，截断抗日物资运输，参与制造“旧城惨案”，残害抗日群众。；为日军出谋划策，参与“治安强化运动”，在献县推行奴化教育，强迫民众“归顺”。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.043022', '2026-09-10 09:57:14.043022', '河北', '沧州', '东光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('308a0c618f6348119d97e5d65f914a74', '唐玉祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：伪博山县警备大队中队长→伪警备团一营营长；罪行：1942年任伪警备大队中队长；1945年伪警备团成立后任一营营长', '[]', '2026-09-10 09:57:14.068994', '2026-09-10 09:57:14.068994', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
