INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('310abe1edca34e739ab652067598cc08', '龙云飞', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化溆浦；湖南怀化；湖南湘西凤凰；湖南湘西古丈；湖南湘西花垣；湖南湘西永顺；湖南湘西凤凰；湖南湘西泸溪；湖南湘西龙山；吉林辽源龙山', '[]', '[]', '抗日战争时期', '', '在湘西苗族地区组织伪维持会，为日军提供物资和情报，协助日军控制湘西地区，包括怀化、溆浦一带。；湘西凤凰人，苗族地方武装首领，抗战后期与日军及伪政权有接触，被指在湘西地区配合日伪行动，维持地方伪秩序。；湘西凤凰人，苗族地方武装首领，抗战期间在湘西地区活动，与日伪有间接联系，维持地方势力。；湘西苗族地方武装头目，抗战后期投靠日军，被委为伪湘西苗疆自治军总指挥，在永顺、凤凰、乾城一带活动。；无；在湘西苗区为日军组织维持会，征派粮款，协助日军统治，活动范围包括古丈、花垣一带。；湘西凤凰、龙山一带土匪首领，抗战时期曾与日伪势力有联系，接受伪军委任，在湘西地区从事劫掠和破坏抗日后方活动。', '[]', '2026-09-10 09:57:14.058560', '2026-09-10 09:57:14.058560', '湖南', '怀化', '溆浦', NULL, NULL, NULL, NULL, '');
