INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3144fec4fb374812966e58a58fc7f7bd', '段树华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西临汾霍州；山西临汾', '[]', '[]', '抗日战争时期', '', '为日军筹措物资，控制临汾商业，协助日伪经济掠夺。；在临汾县推行日伪“治安强化运动”，建立伪乡村政权，强迫民众领取“良民证”，多次向日军报告抗日活动，导致多名地下党员被捕。；率伪保安队驻防长治地区，多次配合日军对武乡砖壁、王家峪等八路军总部驻地周边进行“铁壁合围”，屠杀抗日军民。', '[]', '2026-09-10 09:57:14.019446', '2026-09-10 09:57:14.019446', '山西', '临汾', '霍州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31472529df37494e856a59f26c6dd238', '李注东', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川_成都_青羊；四川_资阳；四川成都', '[]', '[]', '抗日战争时期', '', '在成都基层推行保甲连坐，协助日军征丁征粮，举报抗日人员。；任伪警察局长期间，配合日军搜捕抗日人士，镇压学生运动。；投靠日伪，担任伪警察局长，镇压抗日群众，搜捕抗日志士，为日军提供情报。', '[]', '2026-09-10 09:57:14.001840', '2026-09-10 09:57:14.001840', '四川', '成都', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('314c2271580b4ce3bf70446b38211924', '白瑞生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北保定高阳；河北邯郸曲周', '[]', '[]', '抗日战争时期', '', '指挥伪警察特务，破坏高阳地下交通站，逮捕并严刑拷打抗日群众，向日军提供情报，致使多名游击队员牺牲。；率伪军中队驻守曲周县城，多次参与对冀南军区部队的作战，并杀害被俘的抗日战士，罪行累累。', '[]', '2026-09-10 09:57:14.041266', '2026-09-10 09:57:14.041266', '河北', '保定', '高阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('314e63b7ed0e47fd843b3dde556ca754', '唐式遵', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；重庆涪陵；四川成都锦江；四川成都；四川成都金牛', '[]', '[]', '抗日战争时期', '', '抗日战争期间曾率部投靠日伪，任伪军头目，在四川地区进行伪化活动。；川军将领，抗战期间在成都、邛崃地区与日伪势力勾结，参与伪政权活动，为日军提供情报与物资。；在重庆参与组织维持会，协助日军维持占领区秩序，后转至涪陵活动。；唐式遵本人坚持抗日，但其部分旧部在成都地区投敌，参与伪维持会活动，唐式遵本人不属汉奸。', '[]', '2026-09-10 09:57:14.002107', '2026-09-10 09:57:14.002107', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
