INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31d1565e61d0439f891e83066ddc317c', '时育德', NULL, NULL, NULL, NULL, 'exact', 'exact', '肇源', '[]', '[]', '抗日战争时期', '', '伪职：伪肇源县村长；罪行：执行日伪 “粮食出荷”，盘剥乡民；光复后秘密串联地主、伪官吏策划武装暴乱，图谋推翻民主区政府。；结局：1946 年公审枪决。', '[]', '2026-09-10 09:57:14.078034', '2026-09-10 09:57:14.078034', '黑龙江', '大庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31d24b6480124c05939bfb15a8fdbf89', '高占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定阜平；河北石家庄行唐；山西吕梁方山；河北保定安国；河北石家庄灵寿；山西忻州代县；山西、河北；河北石家庄赵县', '[]', '[]', '抗日战争时期', '', '负责方山伪新民会，推行奴化教育，宣传“中日亲善”，强迫群众参加反共集会，收集抗日情报。；组织地方自卫团，协助日军维持占领区秩序，参与“清剿”行动，杀害抗日民兵和群众。；专门刺探八路军情报，化装潜入抗日村庄，诱捕抗日干部，并参与多起屠杀事件。；驻防阜平、涞源一带，多次率部袭击八路军后方医院，杀害伤病员和医护人员，并参与“无人区”制造。；专门刺探八路军活动情报，多次向日军报告抗日武装行踪，导致数次战斗失利。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.020364', '2026-09-10 09:57:14.020364', '山西', '吕梁', '方山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31e60ad040464ad6b7b80f4510ba4f1b', '郭莘野', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东_潍坊_临朐', '[]', '[]', '抗日战争时期', '', '任伪潍县警察局局长，配合日军搜捕抗日人员，镇压群众。', '[]', '2026-09-10 09:57:14.016666', '2026-09-10 09:57:14.016666', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31e7fe52953a4eb086b3261888aa955d', '王德元', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北廊坊安次；泌阳县', '[]', '[]', '抗日战争时期', '', '伪职：企图当汉奸者；罪行：常兴联庄会揭露了常兴的王德元准备扩充力量、等日军过来当汉奸的阴谋；结局：被联庄会揭露制止', '[]', '2026-09-10 09:57:14.042497', '2026-09-10 09:57:14.042497', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31e91c9d41284e3cadf16793cabb7176', '李振西', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西咸阳秦都；陕西咸阳；河南周口；河南三门峡卢氏；河南三门峡；河南商丘；河南商丘民权；河南洛阳新安；河南洛阳；河南驻马店；河南商丘豫东综合物流产业聚集；河南商丘；陕西西安碑林；黑龙江牡丹江西安；河北衡水冀州；河北衡水；河北衡水深州；河北衡水；河南商丘柘城；陕西汉中；陕西汉中汉台；陕西汉中；陕西西安灞桥；云南普洱西；河南驻马店平舆；河南驻马店；河南三门峡义马；河南洛阳新安', '[]', '[]', '抗日战争时期', '', '宁陵沦陷后任伪县长，配合日军在宁陵、商丘一带进行殖民统治，征粮抓丁。；确山（邻近驻马店）汉奸，组织维持会，协助日军控制确山、驻马店一带，镇压抗日活动。；投靠日本，在陕西维持会中任职，协助日军维持占领区秩序，对咸阳、秦都地区有直接影响。；在陕州（今三门峡陕州区）组织伪维持会，配合日军统治，摊派钱粮、拉夫修路。；率地方武装投靠日军，编入伪保安队，协助日军清乡、搜捕抗日人员，活动于新安及洛阳西部。；在驻马店沦陷期间任伪警察局长，带领伪警察配合日军盘查行人、抓捕抗日嫌疑人员，维护日伪统治秩序。；柘城沦陷后投敌，组织维持会，为日军征集粮秣、修筑据点，协助日军对柘城及周边地区进行清乡。；新安沦陷后出任伪维持会会长，为日军征粮派款，维持伪秩序。；在陕西地区组织伪保安队，配合日军行动（注：陕西大部未沦陷，此条为传闻或未证实，需谨慎）。；在日军控制下出任伪汉中县知事，推行伪政令，配合日军清乡、征发物资，镇压抗日活动。；周口镇商人，日军占领周口期间出面组织伪维持会并任会长，为日军筹粮筹款、招募伪警察，维持沦陷区统治。；担任伪汉中县警察局长期间，搜捕抗日志士，为日军提供情报，协助伪政权征收苛捐杂税。；西安地区维持会头目，协助日军征粮征夫，镇压抗日民众。；衡水沦陷后组织维持会，为日军筹粮筹款，诱降地方武装，协助建立伪政权。；民权沦陷后组织维持会，协助日军统治，征粮派款。；在衡水地区推行伪化统治，协助日军镇压抗日军民。', '[]', '2026-09-10 09:57:14.044213', '2026-09-10 09:57:14.044213', '河北', '衡水', '冀州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('31e9c5c63e634fc0be2d42b5859f138c', '陈升', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西商洛', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：黑煞道军事头目，纠集武装准备起事接应日军商洛日报。。结局：暴乱被镇压，就地处置', '[]', '2026-09-10 09:57:14.069127', '2026-09-10 09:57:14.069127', '陕西', '商洛', NULL, NULL, NULL, NULL, NULL, '');
