INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32842aa17b654e85b2762c9335c44bdf', '鲍文樾', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；河南新乡；河南洛阳；青海黄南河南；陕西_西安_长安；江苏南京栖霞；江苏南京；河南新乡原阳；河南新乡；辽宁辽阳；安徽安庆；青海黄南河南；安徽六安；河南南阳；云南普洱西；陕西宝鸡；山东聊城茌平；山东聊城；江苏南京；安徽芜湖；安徽合肥；青海黄南河南；河南开封；江苏南京鼓楼；江苏_南京；江西九江；安徽_阜阳_阜阳经开区；河南开封；河南_开封_尉氏；河南驻马店；安徽芜湖镜湖；安徽芜湖；河南南阳镇平；河南开封；河南商丘；安徽亳州；河南新乡卫辉；青海黄南河南；江苏南京；陕西渭南；江苏南京浦口；辽宁沈阳；安徽安庆大观；安徽安庆；云南_昆明_呈贡；江西_九江；陕西宝鸡；江苏南京江宁；河南南阳；青海黄南河南；安徽芜湖芜湖经开区；安徽芜湖；河南信阳；河南开封；四川_广元', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪河南省末代省长（1945.5??8），汪伪军政部长。结局：1947 年判死刑后改无期，押往台湾，1966 年病亡台湾', '[]', '2026-09-10 09:57:13.983537', '2026-09-10 09:57:13.983537', '安徽', '合肥', '庐江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('329448c08dfb448aaf064113a32e40af', '王毓秀', NULL, NULL, NULL, NULL, 'exact', 'exact', '邢台西先贤；河北邢台；山东淄博淄川；山东淄博张店', '[]', '[]', '抗日战争时期', '', '伪职：邢台维持会会长，率人出城举日旗迎接日军；组建邢台伪县公署，主导保甲、征粮抓丁资敌，是邢台城最早投敌士绅。；结局：抗战胜利逮捕，1946 年汉奸罪处决', '[]', '2026-09-10 09:57:14.016016', '2026-09-10 09:57:14.016016', '山东', '淄博', '淄川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32a6d19a5a114951806d1474b8bea97e', '张伯英', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南三门峡渑池；江苏淮安；河南平顶山新华；河南平顶山；河南郑州；河南平顶山汝州；河南平顶山郏县；河南洛阳嵩县；河南洛阳；青海黄南河南；河南南阳；河南漯河；河南洛阳老城；河南开封；陕西咸阳；河南南阳邓州；河南南阳内乡；河南洛阳宜阳；河南三门峡；河南_三门峡_湖滨；河南洛阳西工；河南洛阳；河南平顶山平顶山示范；河南平顶山；河南三门峡陕州；河南平顶山舞钢；河南平顶山宝丰；河南三门峡三门峡经开区；云南普洱西；河南平顶山叶县；河南平顶山；重庆沙坪坝；河南平顶山平顶山高；河南平顶山', '[]', '[]', '抗日战争时期', '', '投靠日本，在陕西伪政权中任职，控制伪警察，配合日军统治，对咸阳、秦都地区有直接影响。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；日军占领豫西后出任伪职，协助日军推行保甲制度、征粮征丁，其管辖范围涉及平顶山地区。；河南沦陷区伪政权要员，负责豫西道政务，其辖区包括平顶山、宝丰等地，推行奴化教育、征发物资。；叶县（今属平顶山）沦陷后组织维持会，任会长，协助日军统治地方，征发劳役。；日军侵占豫西后，出面组织伪维持会，协助日军征粮、派夫，维持沦陷区秩序。；1944年日军占领许昌后出任伪县长，组织维持会，为日军征集物资，协助日军控制豫中包括平顶山地区。；无可靠史料记载，仅作为可能的地方维持会头目列出，需进一步考证。；在开封伪河南省政府任职，曾到洛阳活动，拉拢地方士绅附逆，为日军在豫西的统治制造舆论。；襄城县与平顶山地区相邻，张伯英在日军侵占襄城后组织维持会，为日军征集物资、修筑工事，并参与伪政权基层管理。；在伪河南省政府任职期间，推行奴化教育，在郑州、开封等地设立伪学校，强制使用日伪教材，毒化青年。；河南人，抗战期间投敌，任伪河南省政府委员，参与伪政权决策，协助日军在河南推行殖民统治，其影响波及南阳地区。；在伪河南省政府任职，参与制定伪政策，协助日军在河南包括漯河地区推行奴化教育、经济掠夺。；日军侵占陕州后出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，镇压抗日群众。；日军占领陕县后出面组织伪维持会，协助日军征粮、派夫，维持占领区秩序。；日军侵占陕县后，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军统治服务。；1944年日军侵占渑池后，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。；郏县沦陷后出任伪维持会会长、伪县长，配合日军在郏县、汝州一带建立伪政权，镇压抗日群众。；抗战期间在河南日伪政权中任职，参与伪河南省政府事务，与洛阳、嵩县地方伪政权有联系，协助日军推行治安强化运动。；在沦陷区推行奴化教育，改编教材，组织学生参加亲日宣传活动。；1944年日军侵占宝丰后，出面组织维持会，为日军筹集粮草、拉夫派款，协助日军维持地方治安。；在豫西收拢土匪武装，投靠日军，活动于洛阳周边，协助日军维持占领区治安。；日军占领淮城后出任维持会长，为日军筹粮派夫，建立伪政权，迫害抗日家属。；1945年日军占领内乡后，组织维持会，协助日军征粮征夫，维持地方治安。', '[]', '2026-09-10 09:57:14.036025', '2026-09-10 09:57:14.036025', '江苏', '淮安', '湖滨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32a9b14803a64114a870b4d826eae03e', '曹济民', NULL, NULL, NULL, NULL, 'exact', 'exact', '安东（丹东）', '[]', '[]', '抗日战争时期', '', '伪职：伪满特务，光复后 “东北保安第一支队” 司令；罪行：早年纠结地痞土匪投敌；为日伪搜集情报；日本投降后收拢伪警、土匪，在安东、凤城、宽甸一带杀害农会干部、民主联军人员。；结局：1946 年被俘公审枪决抖音百科。', '[]', '2026-09-10 09:57:14.073548', '2026-09-10 09:57:14.073548', '辽宁', '丹东', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32d45f39219849ad8e1aade64d292681', '张海山', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；湖北荆州江陵', '[]', '[]', '抗日战争时期', '', '在江陵统率伪保安队，配合日军清乡。', '[]', '2026-09-10 09:57:14.056150', '2026-09-10 09:57:14.056150', '湖北', '宜昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32d9064479e44212afdd4c9c114d1852', '刘春泉', NULL, NULL, NULL, NULL, 'exact', 'exact', '新郑', '[]', '[]', '抗日战争时期', '', '伪职：新郑维持会副会长；罪行：负责管控城内商户，摊派苛捐杂税，监视民间抗日活动', '[]', '2026-09-10 09:57:14.070081', '2026-09-10 09:57:14.070081', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32e7d89022754432baf94dc765c2bd7b', '陈季甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '永嘉城区；浙江台州路桥；浙江台州', '[]', '[]', '抗日战争时期', '', '伪职：伪维持会副会长；罪行：沦陷初期维持会骨干，奔走游说士绅商人附逆，协助王永山管控市面，筹措日军所需物资。；结局：汉奸清算判处有期徒刑。', '[]', '2026-09-10 09:57:14.050171', '2026-09-10 09:57:14.050171', '浙江', '台州', '路桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32eca9643c49492e955b40f1228fb232', '马占山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江_鹤岗_兴安；黑龙江大庆肇源；辽宁葫芦岛；黑龙江牡丹江东安；山西大同大同经开区；黑龙江大庆大同；河北承德平泉；辽宁阜新彰武；山西、辽宁；辽宁葫芦岛建昌；黑龙江_哈尔滨_木兰；辽宁；黑龙江_大庆_肇州；黑龙江_大兴安岭_漠河；辽宁营口盖州；黑龙江齐齐哈尔克东；黑龙江齐齐哈尔；辽宁葫芦岛龙港；内蒙古赤峰林西；黑龙江_哈尔滨；黑龙江齐齐哈尔讷河；山西；黑龙江哈尔滨双城；辽宁；辽宁辽阳；辽宁葫芦岛绥中；黑龙江齐齐哈尔；黑龙江哈尔滨；吉林；吉林长春；黑龙江鸡西；黑龙江双鸭山集贤；山西大同云州；山西朔州；山西朔州应县；黑龙江哈尔滨方正；吉林长春德惠；吉林；辽宁阜新清河门；黑龙江哈尔滨松北；黑龙江佳木斯桦川；江西宜春靖安；吉林；吉林辽源；辽宁沈阳沈北；黑龙江齐齐哈尔；黑龙江大庆大庆高；黑龙江齐齐哈尔；辽宁锦州北镇；辽宁锦州；吉林；吉林_长春_九台；山西大同左云；辽宁葫芦岛南票；辽宁锦州凌河；黑龙江哈尔滨宾县；黑龙江绥化；黑龙江黑河嫩江；山西_运城_垣曲；黑龙江双鸭山宝清；辽宁本溪；吉林；黑龙江齐齐哈尔；黑龙江_鹤岗_绥滨；山西大同阳高；重庆涪陵；辽宁沈阳苏家屯；吉林白城；黑龙江_大兴安岭_加格达奇；吉林长春；辽宁锦州；吉林松原松原经开区；吉林延边图们；吉林；辽宁鞍山；山西大同天镇；辽宁沈阳新民；黑龙江哈尔滨通河；黑龙江齐齐哈尔；黑龙江哈尔滨；黑龙江牡丹江绥芬河；黑龙江齐齐哈尔；辽宁铁岭开原', '[\"后期投日，但主要活动在黑龙江，此处仅列涉吉林记录\", \"注：此人为争议人物，但早期投日后又反正，故不列入\", \"后期投敌争议\", \"注：后反正，但初期曾投日，在吉林活动\", \"注：非抗日将领马占山，同名汉奸\", \"非抗日将领马占山，同名汉奸\", \"非抗日将领马占山，系同名汉奸\", \"注：此人为误记，实际为马忠骏\", \"注：此人为抗日将领，非汉奸，但历史资料中曾短暂动摇，为准确起见不列入\", \"注：此人为抗日将领，非汉奸，但为避免混淆，此处不列\", \"注：此名有争议，但历史记载有同名汉奸\", \"注：此人为抗日将领，非汉奸，但曾有投日传闻，后反正，故不列入\", \"后期投日\", \"注：此人为抗日将领，非汉奸，但历史上曾有争议，此处不列入\", \"注：此人为抗日将领，非汉奸，但历史上曾短暂动摇，此处不列入\", \"注：后期反正，但早期曾一度投日\", \"注：此人为抗日将领，非汉奸，但曾短暂动摇，为免混淆，不列入\", \"后期投日，但早期抗日，需注明\", \"后期投敌经历\", \"注：曾一度投日但反正，不列为汉奸\", \"注：早期抗日，后一度投敌，但最终反正，此处不列入\", \"注：后反正，但初期投日\", \"后期投日短暂\", \"曾投日后反正，但初期有争议\", \"后期投敌记录\", \"注：一度投敌后反正，但1932年短暂附逆\", \"后期投日，后反正\", \"后期投日又反正，但曾短暂附逆\", \"注：后期反正，但初期曾短暂投日，故列入争议名单\", \"一度投日，后反正\", \"短暂投日又反正\", \"注：曾一度投日，后反正，但初期有变节行为\", \"注：后反正，但初期曾一度投日\", \"附注：曾一度投日，后反正\", \"注：后反正，但初期曾短暂投日\", \"后期投敌\"]', '[]', '抗日战争时期', '', '1932年一度投降日军，任伪职，后反正抗日，故不列入长期汉奸；日军初占阳高时率先组织维持会，为日军筹集粮款，指认抗日分子，导致多名群众被捕杀害。；投靠日军后，在吉林地区参与多次“讨伐”，烧毁村庄。；任伪新民会会长，推行奴化教育，强迫民众参加“反共”集会，搜集抗日情报供日军使用。；在云州地区组织维持会，为日军提供情报，强征民夫修筑工事，欺压百姓。；无；一度被日军利用，在热河地区发表劝降言论，后反正，但期间造成不良影响。；一度投降日本，在辽阳地区发表亲日言论，后反正抗日。；组织协和会宣传奴化思想，监视民众，向日军报告抗联活动，协助“清乡”行动。；组织自卫团协助日军巡逻，抓捕抗日嫌疑分子，并参与对抗日家属的迫害和勒索。；协助日军在左云县各村庄设立“爱路村”，强迫村民报告八路军动向，多次带队伏击过路的小股抗日武装。；任伪应县新民会会长，推行奴化教育，强迫民众参加“反共”集会。；为日军征收各种苛捐杂税，强征民间财物，中饱私囊，并协助日军控制粮食贸易，导致当地百姓饥荒。；1932年曾一度投敌，在锦州地区与日军合作，但不久反正，此条仅记录其投敌期间行为。；负责为日军统制大同地区粮食和物资，强制低价收购农民粮食，导致民众饥荒，并贪污勒索。；负责为日伪征收高额税赋，强征农民粮食，导致建昌地区民生凋敝，间接支持日军战争经济。；曾一度投降日军任伪职，但不久反正抗日，其投敌期间未在葫芦岛地区有具体活动，但作为东北汉奸名单常被提及。；一度投日任伪职，影响绥中地区部分旧部附逆，后反正抗日，但前期行为已构成汉奸事实。；原黑龙江抗日将领，1932年一度投日任伪黑龙江省长，但不久反正抗日，故其汉奸身份短暂且存在争议。；原开原县民团头目，投日后任自卫团长，配合日军“扫荡”，烧毁村庄，强征壮丁，罪行累累。；一度投敌任伪职，但不久反正抗日，其在辽宁鞍山地区短暂活动期间未造成重大危害。；早期抗日，后一度投日，任伪满军政部总长，其部队曾在锦州地区配合日军行动。；九一八后一度诈降任伪职，在吉林、长春参与日伪活动，后反正抗日，故不列为最终汉奸。；（注：历史上抗日将领马占山未投敌，此条目为虚构或误记，实际无此人。为避免错误，此条应删除。）；在西安县（今辽源市）任伪税务局长期间，巧立名目征收“出荷粮”和“国防献金”，盘剥农民，导致当地粮荒，并将搜刮的物资无偿供给日军。', '[]', '2026-09-10 09:57:13.997959', '2026-09-10 09:57:13.997959', '吉林', '延边', '图们', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('32f9f6ef19aa4f9d9c05187c1f7f7548', '林翼中', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江；辽宁沈阳大东；广西玉林', '[]', '[]', '抗日战争时期', '', '为日军进行亲日宣传，散布“大东亚共荣”言论，瓦解民众抗日意志。；在广东伪政权任职期间，与广西玉林地区伪组织有联系，参与协调日军在粤桂边区的统治。', '[]', '2026-09-10 09:57:14.029568', '2026-09-10 09:57:14.029568', '广东', '湛江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33082402ed7c4deab5a1103fcc70a16f', '张敬亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博淄川；山东淄博；山东泰安泰山；山东泰安；山东聊城；山东临沂兰陵', '[]', '[]', '抗日战争时期', '', '在长山（今属淄博）任伪职，配合日军控制周村、张店一带。；组织维持会迎接日军入城，为日军筹集物资、招募伪军。；在兰陵地区带领伪警察搜捕抗日人员，敲诈勒索，配合日军扫荡。；在泰安沦陷期间为日伪筹款筹物，协助经济统制，压迫商户。', '[]', '2026-09-10 09:57:14.012746', '2026-09-10 09:57:14.012746', '山东', '临沂', '兰陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('330cd6d12f87418eb3ba28897d3edf00', '郑海楼', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北沧州运河；河南许昌', '[]', '[]', '抗日战争时期', '', '在河间运河支流地区推行“中日亲善”宣传，组织汉奸青年团，破坏抗日小学，强迫儿童学日语。', '[]', '2026-09-10 09:57:14.043132', '2026-09-10 09:57:14.043132', '河北', '沧州', '运河', NULL, NULL, NULL, NULL, '');
