INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('336e3b9e8fda411a85606cdd68a02b0d', '王尚志', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊昌邑；山东烟台；山东青岛平度；山东青岛即墨；山东潍坊寒亭；山东潍坊昌邑；山东烟台莱山；山东青岛平度；山东青岛；山东潍坊坊子；山东青岛即墨；山东青岛；山东滨州无棣；山东滨州；山东潍坊潍坊滨海经开区；山东潍坊昌邑；山东潍坊高密；山东潍坊昌邑；山东淄博；山东德州；山东_淄博_淄川；山东济南；山西吕梁中阳；山西吕梁离石；广西桂林灵川；辽宁沈阳和平；山东潍坊临朐；辽宁沈阳和平；山东潍坊昌邑；安徽芜湖镜湖；山东潍坊潍城；山东潍坊昌邑；山东青岛李沧；山东青岛；山东滨州惠民；山东滨州沾化；山东潍坊昌邑；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '', '在昌邑、潍县北部活动，投敌后任伪军师长，控制沿海盐场，为日军掠夺物资，镇压抗日群众。；在沾化、滨县、惠民边界地区组织伪军，配合日军清乡，镇压抗日活动。；原国民党地方武装头目，后投敌，任伪鲁东和平建国军副司令，活动于潍坊、临朐、安丘一带，配合日军扫荡。；山东昌邑人，抗战期间投靠日军，任伪军副司令，在潍县、昌邑、平度一带活动，配合日军扫荡抗日根据地。；在鲁北地区组织伪军，配合日军控制德州、平原周边交通线和乡村，参与清乡、扫荡。；统率伪保安队活动于离石、中阳、临县交界地区，配合日军进攻八路军根据地，残害抗日军民。；活动于平度、莱阳一带，投敌后配合日军进攻胶东抗日根据地。；在昌邑、平度、掖县一带活动，后投敌，配合日军进攻胶东和潍坊北部抗日武装。；投敌后任伪军旅长，活动于昌潍地区，协助日军控制潍县、坊子周边交通线。；组织地方自卫团，协助日军维持治安，抓捕抗日嫌疑犯。；在鲁北道（辖滨州、无棣）为日军出谋划策，推行奴化教育，协助经济掠夺。；在潍坊、昌邑、高密一带组织伪军，投靠日军，参与扫荡抗日根据地。；在济南以东及鲁中地区活动，协助日军维持占领区。；在胶东及青岛周边地区活动，配合日军扫荡抗日根据地。；在山东胶东地区活动，投靠日军后任伪军头目，配合日军扫荡。；在鲁东及潍坊地区活动，后投靠日伪，参与组织伪军和维持会，配合日军对昌邑、潍县、平度交界地区进行清乡和扫荡。；在胶东地区率部投敌，任伪军司令，配合日军扫荡莱阳、烟台周边抗日根据地，残害百姓。；在胶东平度、莱阳一带活动，后投敌任伪军职务，配合日军扫荡抗日根据地。；在胶东地区投敌，组织伪军配合日军扫荡，活动于莱阳、莱西、即墨一带。；山东人，抗战期间投靠日军，组织伪军，在华东地区进行伪化统治。；抓捕抗日嫌疑犯。；投靠日军后任伪军师长，在鲁中、淄博一带配合日军扫荡抗日根据地，征粮征丁。；与厉文礼共同在潍县、寒亭一带组织伪军，配合日军扫荡鲁东抗日根据地，残害百姓。；与厉文礼一同投敌，在潍县、昌邑、安丘等地活动，协助日军维持占领区秩序。；原国民党军将领，抗战期间投敌，任伪鲁东和平建国军副司令等职，属山东伪军头目。；在鲁北地区投敌，组织伪军配合日军扫荡抗日武装。；在鲁东地区活动，投靠日军后配合其对即墨、青岛一带进行扫荡和镇压。；在昌邑、潍县一带投敌，组织伪军配合日军进攻抗日武装。', '[]', '2026-09-10 09:57:14.010202', '2026-09-10 09:57:14.010202', '安徽', '芜湖', '镜湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('337fb52472a6473ca47db8df62c03675', '刘黑七', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东临沂；河北；山东临沂蒙阴；山东临沂', '[\"刘桂堂\"]', '[]', '抗日战争时期', '', '原土匪出身，投日后在石家庄、栾城一带流窜，烧杀抢掠，多次袭击抗日武装，后被抗日军民击毙。', '[]', '2026-09-10 09:57:14.012703', '2026-09-10 09:57:14.012703', '山东', '临沂', '蒙阴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33810ce84e784e4d8fbaff36378d4f65', '周光海', NULL, NULL, NULL, NULL, 'exact', 'exact', '绥芬河', '[]', '[]', '抗日战争时期', '', '伪职：伪绥芬河商务会长、维持会头目；罪行：伪满时期为日军筹措物资，监控口岸来往人员；光复后收拢伪警特务，勾结国民党势力破坏接收。；结局：被民主政府逮捕审判。', '[]', '2026-09-10 09:57:14.080357', '2026-09-10 09:57:14.080357', '黑龙江', '牡丹江', NULL, NULL, NULL, NULL, NULL, '');
