INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33859cd142ec4e79b3a06d4c467917fa', '张晓舟', NULL, NULL, NULL, NULL, 'exact', 'exact', '深泽', '[]', '[]', '抗日战争时期', '', '伪职：原安平县抗日县长，叛变投敌；熟悉根据地内情，为日军出谋划策，瓦解抗日力量，危害极大。；结局：安平解放被俘，公审死刑', '[]', '2026-09-10 09:57:14.076314', '2026-09-10 09:57:14.076314', '河北', '石家庄', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('338a0dbc1e4841c1b1364c7763f0190e', '潘元恺', NULL, NULL, NULL, NULL, 'exact', 'exact', '苏州；芜湖西内街 11 号', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪吴县警察局局长，掌控伪警察，配合 90 号特工站搜捕爱国人士。。结局：光复后公审枪决；伪职：汪伪特工芜湖站（十一号）站长；罪行：“芜湖十一号” 特务头子，皖南特务最高头目；下设情报、侦行、警卫，在湾沚、荻港、当涂广布分站，大肆抓捕、刑讯爱国军民，制造大量血案中国人民政...。；结局：抗战胜利后捕获处决。', '[]', '2026-09-10 09:57:14.083398', '2026-09-10 09:57:14.083398', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33903da4fd9f47caac6336f33656ef74', '那顺朝鲁', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在伪兴安北省警备军任职，参与呼伦贝尔地区伪军活动。', '[]', '2026-09-10 09:57:13.988879', '2026-09-10 09:57:13.988879', '内蒙古', '呼伦贝尔', '扎赉诺尔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33935e890c0d4a819be11788c9bde3eb', '张逊之', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津宝坻；天津', '[]', '[]', '抗日战争时期', '华北伪临时政府', '在宝坻县任伪职，协助日军清乡扫荡，强征民夫，掠夺粮食，迫害抗日家属。；在天津县（含塘沽、汉沽、大港一带）推行日伪统治，强征民工修建军事设施。；伪任职务：汉奸普安协会骨干，配合日本鼓吹华北自治，勾结黑帮。结局：建国后抓捕，公审处决', '[]', '2026-09-10 09:57:14.002784', '2026-09-10 09:57:14.002784', '天津', '宝坻', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('339fb43c26424840be59cb75608d59b8', '王荆山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林长春长春汽车经开区；黑龙江哈尔滨道里；辽宁大连；吉林长春；辽宁锦州；黑龙江哈尔滨依兰；黑龙江哈尔滨；辽宁辽阳弓长岭；黑龙江哈尔滨南岗；黑龙江哈尔滨；辽宁沈阳铁西；吉林、辽宁；黑龙江哈尔滨宾县；吉林；吉林长春；吉林长春长春经开区；吉林长春二道；黑龙江哈尔滨；辽宁沈阳和平；辽宁沈阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：长春实业巨头，裕昌源老板；为日军供应军粮，协助开拓团强占农民土地，兼任多个伪协会职务。结局：1951 年抓捕，1952 年以汉奸罪枪决，家产没收；伪职：伪吉林总商会会长；罪行：吉林大商人，附逆日伪；为日军筹措军需物资，摊派报国捐，盘剥工商百姓。；结局：反奸清算，没收财产，判处徒刑。；在二道河子地区（今二道区）协助日军建立“集团部落”，制造无人区；在长春汽车经开区一带为日军筹措物资，强迫商户“献金”，协助经济掠夺。；长春大商人，投日后任伪商会会长，在长春经开区一带为日军筹措物资，强迫商户捐款。；大连地方士绅，投日后任伪市公署参事，协助日伪推行“治安强化”运动。；控制沈阳商业，为日军筹集物资，强迫商户捐献“国防献金”。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.997681', '2026-09-10 09:57:13.997681', '吉林', '长春', '二道', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33a620c87a9240bd899b888ee06df8c8', '刘占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；河北石家庄新乐；山西忻州偏关', '[]', '[]', '抗日战争时期', '', '长期驻守偏关东部据点，多次突袭抗日村庄，抢劫牲畜和财物，并杀害抗日军属多人。；日军占领新乐后率先组织维持会，为日军征粮派款，协助建立伪政权。', '[]', '2026-09-10 09:57:14.021805', '2026-09-10 09:57:14.021805', '山西', '忻州', '偏关', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33bbb3f637d34faca2f4dc3d358c1d31', '周德安', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北潜江；湖南怀化沅陵；湖南怀化', '[]', '[]', '抗日战争时期', '', '率地方武装投敌，编为伪自卫团，在怀化、芷江一带配合日军行动。；在周矶地区为日军设立据点征调民夫，刺探新四军活动情报。', '[]', '2026-09-10 09:57:14.056745', '2026-09-10 09:57:14.056745', '湖北', '潜江', '沅陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33c126cfd33843f282f46ba2c03a9d5f', '张星槎', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东梅州大埔；广东梅州梅县；河南漯河召陵；河南许昌', '[]', '[]', '抗日战争时期', '', '许昌沦陷后任伪维持会会长，为日军筹粮、派夫、维持伪政权，许昌为漯河邻近地级区域，其伪化活动与漯河一带伪政权联系密切。；在梅县沦陷区协助日军建立伪政权，负责情报搜集与物资征调，迫害抗日群众。', '[]', '2026-09-10 09:57:14.027923', '2026-09-10 09:57:14.027923', '广东', '梅州', '大埔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33c30f3ac4a549a3a2c931bd34061105', '赵光第', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊；山东潍坊安丘；山东潍坊高密；山东潍坊；江苏扬州宝应；江苏南京六合', '[]', '[]', '抗日战争时期', '', '在安丘组织伪政权，推行奴化教育，协助日军掠夺矿产、粮食。；末任六合伪知事，在六合地区搜刮民财。；在山东推行奴化教育，编写亲日教材，活动范围涉及潍坊、高密等地。；原李长江部团长，投敌后任伪师长，活动于高邮、宝应地区，参与“清乡”和掠夺。', '[]', '2026-09-10 09:57:14.016572', '2026-09-10 09:57:14.016572', '山东', '潍坊', '高密', NULL, NULL, NULL, NULL, '');
