INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33d81cee50bb4e0a9c9054592cb57b92', '郭礼伯', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州于都；江西赣州；江西赣州大余；江西赣州赣县', '[]', '[]', '抗日战争时期', '', '在赣南地区参与组织反共武装和地方政权，压制抗日民主运动，迫害进步青年和中共地下党员，与地方豪绅勾结控制赣州一带基层政权。；在日军占领赣县期间，以商会名义为日军筹款、筹粮，并动员商户悬挂日伪旗帜，协助经济掠夺。', '[]', '2026-09-10 09:57:14.040461', '2026-09-10 09:57:14.040461', '江西', '赣州', '于都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33d9fe9436f54877983fac55b0673c9c', '王绪五', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏宿迁宿豫；江苏宿迁', '[]', '[]', '抗日战争时期', '', '汪伪政权委任的宿迁县县长，推行保甲制度，配合日军征粮征兵，镇压抗日活动。', '[]', '2026-09-10 09:57:14.034503', '2026-09-10 09:57:14.034503', '江苏', '宿迁', '宿豫', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33def8aed3a542479a6a76972c58879b', '朱仿文', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽六安', '[]', '[]', '抗日战争时期', '', '六安地方人物，抗战期间在六安沦陷区组织维持会，任会长，配合日军征发民夫、物资，维持伪政权基层统治。', '[]', '2026-09-10 09:57:14.005638', '2026-09-10 09:57:14.005638', '安徽', '六安', '霍邱', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33e05ae99aa44323bea60244d1a7d726', '陈汉卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北随州；湖北宜昌远安；湖北宜昌；湖南岳阳华容；湖北鄂州华容；湖北咸宁赤壁；湖北咸宁嘉鱼；湖北宜昌长阳；湖北宜昌；湖北黄石铁山；湖北黄石黄石港；湖北黄石黄石港；湖北宜昌伍家岗；湖北宜昌；湖北咸宁咸安；湖北咸宁；湖北鄂州；吉林高；湖北黄石大冶；湖北咸宁通山；湖北黄石大冶；湖北黄石；湖北黄石阳新；湖北孝感孝昌；湖北孝感；湖北咸宁崇阳；湖北宜昌西陵；湖北鄂州鄂城；湖北武汉武昌；湖北鄂州华容', '[]', '[]', '抗日战争时期', '', '嘉鱼沦陷后附逆，任伪维持会会长、伪县长，为日军征发粮食、民夫，配合伪军清乡。；当阳沦陷后投敌，历任伪维持会会长、伪县长，配合日军对宜昌、远安一带进行扫荡。；协助日军建立维持会，筹款筹粮，动员商户向日军供应物资。；任伪咸宁县县长期间，配合日军在咸宁地区推行保甲连坐，搜捕抗日人员，征敛物资。；担任伪黄石港警察局局长，协助日军维持治安，搜捕抗日人员，控制黄石港码头与交通。；在黄石港地区担任伪警察头目，配合日军镇压抗日活动、搜捕抗日人员。；黄石港人，投靠日军后出任伪警察局局长，负责黄石港及西塞山周边治安，抓捕抗日人士，协助日军推行保甲连坐。；在鄂城与武昌交界地区组织伪维持会，为日军提供情报与物资。；崇阳沦陷后投敌，组织伪维持会并任伪崇阳县县长，协助日军统治崇阳地区。；在西陵镇一带组织维持会，为日军带路、征夫、征粮，协助日军控制西陵地区。；控制食盐专卖，为日军筹措经费，高价售盐盘剥百姓，严禁食盐流入抗日根据地。；为日军筹款筹粮，强制商户交纳物资，协助日军实行经济统制。；任伪宜昌县保安团团长，率伪军配合日军扫荡抗日根据地，抓捕抗日军民，在宜昌地区为虎作伥。；统率伪保安大队配合日军扫荡孝感、孝昌一带抗日根据地，捕杀抗日人员。；大冶地区伪军头目，组织伪保安团配合日军清乡、扫荡，镇压抗日力量，活动范围包括大冶、黄石港、铁山一带。；出面组织伪商会，为日军筹款筹物，协助控制宜昌商业，配合经济封锁。；统率伪保安队配合日军在岳阳、华容、南县一带进行扫荡，搜捕抗日人员，强征民夫与物资。；任伪华容乡乡长期间，推行保甲连坐，协助日军征丁征粮，压制当地抗日活动。；抗战期间任伪大冶县警察局局长，配合日军搜捕抗日人员，镇压地方抗日活动，维护日伪在大冶地区的统治。；大冶沦陷后投敌，组织维持会并任伪县长，在鄂东南地区协助日军掠夺矿产、镇压抗日。；率伪军配合日军扫荡大冶、阳新一带抗日根据地，捕杀抗日人员，强征民夫。', '[]', '2026-09-10 09:57:14.055077', '2026-09-10 09:57:14.055077', '湖北', '咸宁', '咸安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33eb2fdf23d24bec939b933ba1ddd92f', '黄子信', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头南澳', '[]', '[]', '抗日战争时期', '', '在南澳伪政权中任县长，执行日军指令，镇压抗日活动。', '[]', '2026-09-10 09:57:14.028156', '2026-09-10 09:57:14.028156', '广东', '汕头', '南澳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33f663f00fe5480693470afb234ca347', '林文庆', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州永泰；辽宁沈阳和平；福建宁德福安；福建厦门；福建厦门同安；福建厦门；福建三明尤溪；福建厦门；福建莆田；福建厦门；福建福州', '[]', '[]', '抗日战争时期', '', '在伪政权中负责卫生行政，配合日军防疫与人口管控措施。；在厦门沦陷区参与伪维持会与伪教育文化机构，协助日军推行奴化宣传与伪化教育。；厦门沦陷期间参与伪教育维持组织，协助日军控制厦门大学校产与师生。；福建附逆文人，在伪省政府挂职，为日伪撰写宣传文章，鼓吹“和平建国”。；福建籍汉奸，任伪厦门特别市市长，协助日军在闽南及莆田沿海地区的殖民统治，推行奴化教育，为日军筹集物资。；福州人，福州沦陷期间出任伪福州教育会会长，协助日伪推行奴化教育，篡改教材，向学生灌输亲日思想。；厦门沦陷后参与伪教育文化机构，推行日语教育及奴化宣传，影响闽南及闽东部分学校。', '[]', '2026-09-10 09:57:14.060249', '2026-09-10 09:57:14.060249', '福建', '三明', '尤溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('33f73b2b3e6f40ccba89f08d7f18d552', '周子涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕县', '[]', '[]', '抗日战争时期', '', '伪职：陕县警卫中队中队长（已投敌）；罪行：原陕县抗日民主政府警卫中队中队长。1945年5月26日在柳沟村召开秘密会议，勾结日伪、军统策划叛乱；5月28日率部发动“王彦事变”；结局：待考（豫西事变参与者）', '[]', '2026-09-10 09:57:14.069367', '2026-09-10 09:57:14.069367', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34026461feec4bd593fb80b95adfd7a4', '段绳武', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西临汾洪洞；山西临汾', '[]', '[]', '抗日战争时期', '', '日军占领临汾后首任维持会长，负责为日军筹集粮食、征集苦力，并建立情报网，向日军报告抗日武装动向。', '[]', '2026-09-10 09:57:14.019208', '2026-09-10 09:57:14.019208', '山西', '临汾', '洪洞', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('340ad0df843b4c5eae0af195aa28446d', '王福民', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德福安；福建莆田仙游；福建莆田；福建南平；福建莆田；福建三明尤溪；福建三明；福建福州；福建泉州石狮；福建泉州', '[]', '[]', '抗日战争时期', '', '南平地区人，抗战期间在南平组织伪维持会并任会长，协助日军及伪政权维持地方秩序，征发民夫、物资，推行保甲连坐。；任伪莆田县警察局局长期间，带领伪警察配合日军搜查抗日分子，镇压民众反抗，维护日伪统治秩序。；在三明及周边地区组织伪维持会，协助日军与伪政权征派粮款、登记户口、维持地方伪秩序。；率伪军在泉州、石狮沿海配合日军扫荡。；福安沦陷或受日军威胁期间，出面组织伪维持会，为日军筹粮、派夫，协助维持地方伪秩序。；福州沦陷期间出任伪警察局局长，协助日军搜捕抗日人员、管制交通与物资。；与张逸舟共同组织伪军，在闽中沿海包括莆田、仙游一带活动，协助日军维持伪化区。', '[]', '2026-09-10 09:57:14.060228', '2026-09-10 09:57:14.060228', '福建', '三明', '尤溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('340f34cc928b40648d6f1ac6fccc47a5', '柳世平', NULL, NULL, NULL, NULL, 'exact', 'exact', '天津武清；武清', '[\"柳小五\"]', '[]', '抗日战争时期', '伪军', '伪任职务：武清伪警备副大队长，郊县伪军头目，多次扫荡冀中根据地。结局：1945 年日本投降前夕被日军处决；伪职：伪武清保安第一总队司令，势力覆盖安次、胜芳一带；廊坊头号铁杆汉奸，盘踞胜芳、葛渔城，多次扫荡大清河北，屠杀干部群众。；结局：1945 年天津被国民党逮捕，1946 公审枪决北方网；伪职：伪武清保安第一总队司令，见安次部分。；结局：公审枪决', '[]', '2026-09-10 09:57:14.079141', '2026-09-10 09:57:14.079141', '天津', '天津', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('341d7fdc8e31493fb19e7716b5c99a48', '王仲哲', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城茌平；山东聊城；安徽安庆太湖；安徽安庆；河南开封；安徽宣城；山西吕梁石楼；山西吕梁；安徽安庆；浙江宁波江北；安徽安庆怀宁；安徽安庆宿松；安徽安庆太湖', '[]', '[]', '抗日战争时期', '', '在开封主持伪司法，迫害抗日人士和爱国群众。；任伪安庆警察局局长期间，配合日军搜捕抗日人员，镇压民众反抗，维持日伪治安。；太湖县沦陷后出面组织维持会，为日军筹粮派款，配合伪政权在安庆西部山区进行伪化活动。；安庆沦陷后任伪县知事，执行日军政令，推行保甲制度，协助征发劳工与物资。；任伪宣城县警察局长，协助日军维持治安，搜捕抗日人士，迫害当地百姓。；望江沦陷期间任伪县长，协助日军控制长江北岸，搜捕抗日人员。；抗战期间在怀宁附逆，主持伪教育行政，推行日语教学与亲日奴化教育，组织学生参加日军宣传活动，属教育文化领域汉奸。；伪山东省委员，参与聊城地区伪化政策。；伪山东省委员，参与聊城地区伪政权事务。；发行伪币，掠夺山西包括吕梁地区民众财富，为日军殖民统治提供经济支持。', '[]', '2026-09-10 09:57:14.007354', '2026-09-10 09:57:14.007354', '安徽', '安庆', '太湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('341df2b8e50449a291ced76dfe1f6558', '朱崇汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '四甲坝一带', '[]', '[]', '抗日战争时期', '', '伪职：伪南通特别区第九区区长；罪行：伪清乡区长，构建基层伪政权，抓捕抗日干部，残害群众南通史志网。；结局：武工队潜入据点抓捕处决。', '[]', '2026-09-10 09:57:14.082999', '2026-09-10 09:57:14.082999', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34307abb191c427fa7bc138d4d27c54a', '黄某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东阳江江城；广东阳江；广东江门恩平；河北唐山开平；广西百色田东；广西百色；湖南衡阳衡阳松木经开区；山西阳泉城区；广西梧州苍梧；广西南宁上林；广东茂名电白；福建莆田城厢；福建莆田；江西赣州信丰；广西百色田东；广西柳州三江；广西柳州；广西百色靖西；广西南宁宾阳', '[\"黄公侠\", \"黄伯衡\", \"黄老六\", \"黄老八\", \"名不详\", \"黄老七\", \"黄仲庵\", \"待考\", \"佚名\"]', '[]', '抗日战争时期', '', '作为桂西地区维持会代表，参与汪伪政权在广西的筹组活动，协助日军在百色、田东等地建立伪基层政权。；组织伪保安队配合日军扫荡苍梧乡村，抓捕抗日游击队员。；开平沦陷期间出面组织维持会，协助日军控制开平、恩平一带交通与物资。；率领伪保安队配合日军扫荡电白沿海抗日游击队，残害抗日群众，勒索民财。；日军占领柳州期间，充任伪保甲长，为日军派捐、指认抗日人员，属柳州基层汉奸。；城厢本地商人，日军短暂占据莆田城厢期间组织维持会，为日军提供情报、向导及物资，协助建立伪保甲组织。；在宾阳沦陷期间协助日军征派民夫、粮食，维持地方秩序，具体姓名地方志记载模糊。；在信丰县担任伪保甲长，协助日军和伪政权征粮、派夫，属基层附逆人员。；1944年日军侵入田东时，纠集地方劣绅成立伪维持会，为日军筹粮、带路，并协助日军搜捕抗日游击队员，迫害当地群众。；日军侵占上林期间，出面组织伪维持会，为日军带路、征粮，并诱降地方武装。；组织伪保安队，协助日军在阳江及江城地区清乡、扫荡，迫害抗日群众。；衡阳沦陷后，日军利用部分旧警察维持城区治安，协助搜捕抗日人员，具体姓名多不可考，仅见于零星口述。；靖西地处中越边境，抗战后期日军曾短暂侵入桂南、桂西，地方维持会记载零散，具体姓名与事迹缺乏可靠档案。', '[]', '2026-09-10 09:57:14.028669', '2026-09-10 09:57:14.028669', '广东', '江门', '恩平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('343301f6feec4b318cfe21c58469d763', '奇子祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古鄂尔多斯准格尔旗；内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯康巴什；内蒙古鄂尔多斯；内蒙古呼伦贝尔牙克石；云南普洱西；内蒙古鄂尔多斯杭锦旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯达拉特旗；内蒙古鄂尔多斯伊金霍洛旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯', '[]', '[]', '抗日战争时期', '', '蒙古族贵族，投靠日本后任伪伊克昭盟盟长，在鄂尔多斯地区推行日伪统治，强迫牧民缴粮纳税，协助日军清剿抗日力量。；投靠日伪，任伪达拉特旗西协理，配合日军“扫荡”抗日根据地，向日军提供情报并征收粮草。', '[]', '2026-09-10 09:57:13.989324', '2026-09-10 09:57:13.989324', '内蒙古', '呼伦贝尔', '牙克石', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('343c1d55212f41fcb051fbd00e272ed1', '张继武', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔甘南；黑龙江齐齐哈尔；虎林小木河、独木河', '[]', '[]', '抗日战争时期', '', '伪职：日军特务（虎林事件告密者）；罪行：出卖虎林爱国抗日组织，制造 “虎林事件”，致使 64 名爱国人士被捕，24 人惨遭杀害；被日军委任为地方常驻特务继续搜集情报。；结局：抗战胜利后潜逃，混入队伍，清队时被揪出，畏罪自杀。', '[]', '2026-09-10 09:57:14.066984', '2026-09-10 09:57:14.066984', '黑龙江', '齐齐哈尔', '甘南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('344b4750e97949df966297e18984edc1', '张振汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京；江苏徐州邳州；江苏徐州；江苏徐州徐州经开区；江苏徐州沛县', '[]', '[]', '抗日战争时期', '', '原国民党将领，投敌后任伪徐州绥靖公署主任，指挥伪军配合日军“扫荡”苏北抗日根据地。；利用伪司法机构迫害抗日人士，判处多人死刑或重刑，为日伪统治提供法律工具。；日军初占沛县时，组织维持会，为日军提供粮秣、民夫，并协助建立伪政权。；参与伪江苏省政府决策', '[]', '2026-09-10 09:57:14.033247', '2026-09-10 09:57:14.033247', '江苏', '南京', '徐州经开区', NULL, NULL, NULL, NULL, '');
