INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('345dc5d9c63d44559d94ae48f5c8554f', '芦孝', NULL, NULL, NULL, NULL, 'exact', 'exact', '开封城区', '[]', '[]', '抗日战争时期', '', '伪职：伪区队长→伪大队长；罪行：西郊乡王府砦村人，恶霸、汉奸、地主。1938年开封沦陷后投靠日军，曾杀人11名，奸淫妇女十多人；结局：1950年12月23日被处决', '[]', '2026-09-10 09:57:14.085945', '2026-09-10 09:57:14.085945', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('345f251b72654887917f5b4853928d18', '陈洛绪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄藁城', '[]', '[]', '抗日战争时期', '', '为日军筹集物资，强迫商户“献金”，从中贪污，资敌卖国。', '[]', '2026-09-10 09:57:14.043819', '2026-09-10 09:57:14.043819', '河北', '石家庄', '藁城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('346551b910994a2f8f8283beaaf2077f', '韩则信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北秦皇岛山海关；河北秦皇岛昌黎；河北唐山唐山高；河北唐山；河北唐山迁西；云南昆明西山；北京、天津、河北；河北秦皇岛；河北_廊坊_大厂；河北唐山唐山芦台经开区；河北唐山；河北唐山滦州；天津河北；河北邯郸；河北唐山迁安；北京_通州；河北唐山唐山海港经开区；河北唐山遵化', '[]', '[]', '抗日战争时期', '', '指挥伪警察协助日军搜捕抗日分子，参与“治安强化”行动，欺压百姓。；投日后任伪冀南道尹，管辖邢台、邯郸等地，推行“治安强化”运动，配合日军对冀南根据地的“囚笼政策”。；组织地方自卫团，配合日军袭击抗日村庄，杀害村干部和群众。；在唐山开滦矿区组织伪保安队，镇压矿工罢工，为日军控制煤炭资源效力。；在唐山地区推行伪政府法令，组织汉奸团体，协助日军收集情报，镇压当地抗日活动。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995082', '2026-09-10 09:57:13.995082', '天津', '河北', '唐山海港经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34707bcb1bc542ccb0515dd5a2c61955', '孙振邦', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州德城；山东德州；河北衡水桃城；河北衡水', '[]', '[]', '抗日战争时期', '', '在伪鲁北道任职，管辖包括德州在内的鲁北地区，为日军推行治安强化运动、征粮征丁，镇压抗日力量。；在衡水、桃城等地开展亲日宣传，组织伪化教育，诱骗青年参加伪军。', '[]', '2026-09-10 09:57:14.014083', '2026-09-10 09:57:14.014083', '山东', '德州', '德城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3479538a331241c2ada4369943614089', '万墨林', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦', '[]', '[]', '抗日战争时期', '', '在杨浦地区负责粮食配给，克扣口粮，导致平民饥荒。', '[]', '2026-09-10 09:57:13.977359', '2026-09-10 09:57:13.977359', '上海', '杨浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('347b72e3336f49a8895bbe0a940e55e2', '钦家谋', NULL, NULL, NULL, NULL, 'exact', 'exact', '蓬莱县', '[]', '[]', '抗日战争时期', '', '伪职：伪二区区长；罪行：蓬莱汉奸；结局：抗战胜利后潜逃；被通缉并没收财产', '[]', '2026-09-10 09:57:14.085552', '2026-09-10 09:57:14.085552', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34876a3891354e00bfef52a220b5fab7', '周大文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京门头沟；河北；河北廊坊；北京石景山；北京丰台；北京延庆；辽宁葫芦岛兴城；北京_东城；河北廊坊；北京、河北、辽宁', '[]', '[]', '抗日战争时期', '', '负责北平市政工程，为日军修建军事设施，强征民夫，破坏城市基础设施。；在丰台地区推行日伪社会控制，组织“新民会”分会，进行奴化宣传。；继任伪北平市长，在延庆等地区继续推行日伪“粮食统制”，强征农民粮食，配合日军“扫荡”。；在石景山地区强征民夫修建军事道路和碉堡，服务于日军对平西根据地的“扫荡”。；在门头沟矿区推行日军防疫政策，限制民众流动，间接协助日军控制疫情和人口。……（共涉及7个地区的犯罪记录）；其管辖范围涉及廊坊北郊，配合日军在潮白河沿岸“清乡”。', '[]', '2026-09-10 09:57:13.993109', '2026-09-10 09:57:13.993109', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3489110bcd4e4c00b2b6d093f0b6cf77', '张锡珩', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州郑州经开区；河南郑州；河南漯河郾城；河南许昌；河南新乡牧野；河南新乡；河南商丘梁园；青海黄南河南；河南安阳', '[]', '[]', '抗日战争时期', '', '郑州沦陷后依附日伪，以商会名义为日军筹款、筹粮，协助经济统制，是郑州工商界附逆代表人物。；抗战时期在新乡任伪县知事，协助日军统治新乡及周边地区。；河南沦陷区伪政权官员，负责许昌及周边包括漯河、郾城一带的伪行政事务，推行保甲、征粮、奴化宣传。；汤阴沦陷后任伪县长，为日军征粮征丁，修筑封锁沟墙，配合扫荡安阳、汤阴一带抗日武装。；在汪伪河南省政府任职，参与管理豫东伪政权，推行日军政策，镇压抗日活动。', '[]', '2026-09-10 09:57:14.047643', '2026-09-10 09:57:14.047643', '河南', '商丘', '梁园', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('349002018fd247c792ceffab47cb19fd', '孙荣久', NULL, NULL, NULL, NULL, 'exact', 'exact', '勃利（七台河全境）；桦南、勃利', '[]', '[]', '抗日战争时期', '', '伪职：抗联八军师长，投敌伪山林队头目；罪行：投降日军，充当伪山林讨伐队；日本投降后接受国民党委任，大肆劫掠、杀害基层干部，合江四大匪首之一。；结局：1947 年剿匪被俘处决。；伪职：原抗联八军师长，投敌伪山林讨伐队长；罪行：投降日寇，带队扫荡抗联根据地；光复后发动勃利 “双??十二暴乱”，杀害二十余名革命干部，北满四大匪首之一。；结局：1947 年被俘公审枪决。', '[]', '2026-09-10 09:57:14.076801', '2026-09-10 09:57:14.076801', '黑龙江', '佳木斯', NULL, NULL, NULL, NULL, NULL, '');
