INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34b66ac422dd407ba76fb4353255e442', '陈炯明旧部某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东梅州五华；江苏连云港东海', '[\"陈演生\"]', '[]', '抗日战争时期', '', '广东海丰籍，活动于东江、韩江流域，参与伪军组织与情报活动，与梅州地区抗日力量为敌。', '[]', '2026-09-10 09:57:14.027901', '2026-09-10 09:57:14.027901', '广东', '梅州', '五华', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34db30908c034a7aac7d7d616f9d665d', '黄子安', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳老河口；广西南宁；广西南宁西乡塘；广西南宁；湖南衡阳祁东；湖南衡阳；河南信阳新县；河南信阳；湖北孝感安陆；湖北孝感；河南信阳潢川；河南信阳；广西南宁江南；广西南宁；湖北孝感大悟；湖北宜昌当阳；广西南宁隆安；湖北孝感云梦；湖北孝感；湖北襄阳枣阳', '[]', '[]', '抗日战争时期', '', '在罗山组织伪政权，为日军征粮派款，协助日军封锁信阳、潢川之间的交通线。；大悟地区伪军头目，率保安团配合日军扫荡大悟山抗日根据地。；统率伪保安队配合日军在孝感、云梦一带进行扫荡，捕杀抗日人员，是当地伪军头目之一。；在基层推行保甲连坐，监视民众，向日军和伪政权报告抗日人员行踪，协助征粮拉夫。；在枣阳双沟镇组织维持会，为日军据点供应粮草、情报，欺压当地百姓。；衡阳沦陷期间，黄子安以商会会长身份出面组织伪商团，为日军筹集物资、摊派款项，协助日军控制衡阳经济。；1944年冬日军侵入隆安，黄子安出面组织伪隆安维持会，为日军征粮派夫，维持地方伪秩序。；日军占领南宁后，受日伪指派出任伪南宁县县长，负责伪政权行政事务，配合日军征粮征夫。；控制当阳沦陷区物资流通，为日军统制粮食、棉花等物资，盘剥民众。；在应山任伪县长，配合日军在鄂北、孝感北部地区清乡。；在日军占领南宁期间出任伪警察局局长，统辖伪警察协助日军搜捕抗日人士、维持占领区治安。；在罗山地区建立伪政权，配合日军对罗山、信阳、新县交界地带进行清乡，强征民夫修筑据点，镇压当地抗日武装。；日军入侵广西后投敌，任伪职，在南宁、梧州等地为日军进行宣传和招降活动。', '[]', '2026-09-10 09:57:14.031264', '2026-09-10 09:57:14.031264', '广西', '南宁', '江南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('34f68339f25a47f3ad6df5c3265c5570', '苏锡文', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海虹口；上海青浦；广西_桂林_灵川；广西桂林资源；湖南_怀化_怀化洪江管理；广西玉林；重庆_合川；陕西_西安_长安；上海静安；上海黄浦；云南_昆明_呈贡；广西_柳州；广西_桂林_永福；重庆_万州；云南普洱西；福建厦门；浙江绍兴；云南普洱西；上海浦东；浙江舟山普陀', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪上海大道市政府市长，上海最早傀儡政权首脑，后任伪市府秘书长。结局：1945 年病死，逃脱审判', '[]', '2026-09-10 09:57:13.977015', '2026-09-10 09:57:13.977015', '上海', '浦东', NULL, NULL, NULL, NULL, NULL, '');
