INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('35d3c77da1db42db985ebb4f40ab3f39', '卢英', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海徐汇；上海虹口；上海静安；上海_松江；上海黄浦；上海青浦；浙江舟山普陀；上海长宁；浙江宁波余姚；上海闵行；湖北；上海杨浦', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪上海特别市警察局长，掌控上海伪警察系统，配合 76 号抓捕爱国人士。结局：抗战胜利被捕，判处死刑执行枪决', '[]', '2026-09-10 09:57:13.976387', '2026-09-10 09:57:13.976387', '上海', '青浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('35dc6335aeb0413b9b1f9e17dc22b944', '陈干', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊；山东潍坊青州', '[]', '[]', '抗日战争时期', '', '在益都（今青州）组织维持会，后任伪县长，为日军征集粮食、劳工，镇压抗日活动。', '[]', '2026-09-10 09:57:14.016559', '2026-09-10 09:57:14.016559', '山东', '潍坊', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('35de91b9820e43a0a617388789b1cf37', '石太山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉平定', '[]', '[]', '抗日战争时期', '', '率自卫团协助日军封锁抗日根据地，杀害过路商旅，并参与‘清乡’行动。', '[]', '2026-09-10 09:57:14.024639', '2026-09-10 09:57:14.024639', '山西', '阳泉', '平定', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('35f17d6c6a91466a93d42d4f101f202b', '高玉森', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹿邑县', '[]', '[]', '抗日战争时期', '', '伪职：鹿邑县城铁杆汉奸；罪行：鹿邑县城的铁杆汉奸，原为教书先生。日军在鹿邑修炮楼后，常给日军送烧鸡、羊腿等食物；为讨好日军学唱曲、酿酒；妻子因耻于与其为伍而离去；结局：曾借送酒之机用高度酒灌醉14名日本兵（具体结局史料未详载）', '[]', '2026-09-10 09:57:14.085835', '2026-09-10 09:57:14.085835', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('35f611f83e6b43d1bbba3222b73b04e0', '殷同', NULL, NULL, NULL, NULL, 'exact', 'exact', '南京，江阴原籍', '[]', '[]', '抗日战争时期', '', '伪职：伪维新政府建设部总长（江阴人）；罪行：伪维新政府高层，主管华北、华中交通，为日军掠夺资源服务，汪伪政权重要人物。；结局：1942 年病亡，未及战后清算。', '[]', '2026-09-10 09:57:14.079320', '2026-09-10 09:57:14.079320', '江苏', '无锡', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('360327236c944043974564f1be41941d', '兰子彬', NULL, NULL, NULL, NULL, 'exact', 'exact', '定兴', '[]', '[]', '抗日战争时期', '', '伪职：伪定兴县县长；受赵玉昆伪军支持，推行日伪政令。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.077638', '2026-09-10 09:57:14.077638', '河北', '保定', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('360a668b7abe4c5c94cb351c355e2710', '莫雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东清远连山；辽宁葫芦岛连山', '[]', '[]', '抗日战争时期', '', '连山地区沦陷后参与组织伪维持会，协助日军征粮派款，维持占领区基层统治。', '[]', '2026-09-10 09:57:14.029346', '2026-09-10 09:57:14.029346', '广东', '清远', '连山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('36159100962b4aedb39c02200f373adc', '陈统元', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江麻章；广东广州；广东广州；广东湛江坡头；广东广州；广东湛江遂溪', '[]', '[]', '抗日战争时期', '', '为日军筹款征粮，管理伪政权财政，协助日军掠夺广州湾及周边地区经济资源。；在广东南路日伪政权中任职，配合日军对雷州半岛及广州湾周边地区进行政治诱降与物资掠夺。；充当日伪警察头目，搜捕抗日人士，镇压民众反抗，维护日伪统治秩序。；在广州湾伪警察系统任职，协助日军镇压抗日活动、管理户籍与检查行人。', '[]', '2026-09-10 09:57:14.029715', '2026-09-10 09:57:14.029715', '广东', '湛江', '坡头', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('361ae3819ac947888ad3b3687a168a3e', '李正之', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西萍乡莲花；江西萍乡；江西新余分宜', '[]', '[]', '抗日战争时期', '', '抗日战争后期，日军侵入赣西分宜一带时，出面组织伪分宜县维持会，充任会长，为日军征派民夫、粮秣，协助维持沦陷区秩序。；日军侵占萍乡期间，出面组织萍乡县维持会，协助日军征派民夫、粮食，维持沦陷区秩序。', '[]', '2026-09-10 09:57:14.040152', '2026-09-10 09:57:14.040152', '江西', '新余', '分宜', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('36223333dfdd4b238760e16a57178d14', '沈鸿烈', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳新民；天津；广西_桂林_灵川；天津北辰；广西桂林资源；江苏_无锡_江阴；山东青岛', '[]', '[]', '抗日战争时期', '', '在伪市府任职期间，参与经济统制，协助日军掠夺天津资源。；控制社会团体，组织“新民会”天津分会，进行反共宣传和特务活动。', '[]', '2026-09-10 09:57:14.002631', '2026-09-10 09:57:14.002631', '天津', '北辰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('362b00ff184e4f5ab12a9c696dfd656d', '张亚庸', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海长宁', '[]', '[]', '抗日战争时期', '', '在长宁区推行保甲制度，组织汉奸联防队，监视居民，举报抗日活动。', '[]', '2026-09-10 09:57:13.979661', '2026-09-10 09:57:13.979661', '上海', '长宁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('36300a2f4cd44cc8b08928123018badc', '刘国钧', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林资源；湖北武汉东西湖；湖北宜昌；湖北襄阳；广东肇庆；云南普洱西；湖北咸宁咸安；湖北武汉武昌；江西抚州广昌；江西抚州；湖北孝感大悟；湖北武汉武昌；湖北_咸宁_崇阳；湖北_咸宁_通山；湖北武汉新洲；湖北武汉；湖北武汉黄陂；湖北武汉蔡甸；湖北武汉武昌；湖北咸宁；浙江舟山；湖北襄阳南漳；辽宁沈阳大东；湖北鄂州鄂城；安徽合肥肥东；安徽合肥；湖北武汉；江西宜春宜丰；江西宜春铜鼓；湖北黄冈；湖北黄石西塞山；湖北黄石黄石港；湖北荆州公安；湖北武汉洪山；湖北武汉；湖北荆州沙市；湖北_孝感；湖北鄂州；湖北鄂州梁子湖；湖北_十堰；湖北_武汉_汉阳；湖北武汉；广东韶关曲江；湖北荆州江陵；湖北荆州沙市；湖北荆州；湖北孝感孝昌', '[]', '[]', '抗日战争时期', '', '率伪军配合日军在鄂城梁子湖一带扫荡，袭击抗日游击队。；黄冈本地人，日军占领黄冈后组织维持会，任伪县长，为日军征粮拉夫，出卖抗日人员。；黄冈地区伪政权头目，组织维持会迎接日军，任伪黄冈县县长期间，为日军征粮、拉夫、搜集情报，镇压当地抗日群众。；黄冈本地人，抗战期间组织维持会，任伪黄冈县县长，协助日军征粮、拉夫，镇压当地抗日力量。；黄冈本地人，1938年黄冈沦陷后出面组织维持会，后任伪黄冈县县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。；抗战期间在武昌地区附逆，任伪武昌市政处处长、伪武昌县县长，协助日军推行保甲、征粮等伪政。；任伪警察局长，配合日军搜捕抗日人员，维持占领区治安，欺压百姓。；武汉沦陷后组织伪武昌维持会，任会长，协助日军维持武昌地区秩序，征发物资、拉夫，为日军侵略服务。；任伪合肥县知事，在肥东地区推行保甲制度，强征壮丁，为日军提供粮食和情报。；投敌后长期在武汉担任伪警察头目，在汉口、硚口等地镇压抗日活动，抓捕爱国人士，协助日军维持治安。；沙市沦陷后任伪商会会长，为日军筹款、摊派物资，协助维持伪经济秩序。；在湖北沦陷区为日军修建军事设施、掠夺资源，协助经济侵略。；在舟山建立伪警察系统，抓捕抗日群众，实施白色恐怖。；汉口商界附逆代表人物，组织伪维持会，为日军筹款筹粮，协助经济掠夺。；汉口沦陷后出任伪商会会长，协助日军统制物资、摊派捐款，为日伪经济掠夺服务。；在抚州地区统筹各伪维持会，为日军征集物资、情报，协助日军维持占领区统治，迫害抗日人员。；在铜鼓地区为日军征集物资，组织伪政权，协助日军镇压当地抗日活动。；指挥伪保安部队在鄂东包括鄂城地区配合日军作战，镇压抗日民众。；抗战期间投敌，任伪武昌县县长、伪湖北省政府委员，参与日伪在湖北的统治。；曲江伪警察所所长，协助日军搜捕抗日分子，维持曲江地区治安。；投敌后任伪武汉特别市社会局局长，后任伪汉口特别市市长，负责伪政权社会管控，协助日军征发劳工、物资。；抗战期间在汉口商会任职，为日军筹款筹物，协助经济统制。；武汉沦陷后参与伪维持会及伪商会活动，协助日军筹措物资、摊派款项，在经济领域附逆，为日伪统治服务。；咸宁本地人，日军侵占咸宁后出面组织维持会，为日军征粮、拉夫、维持地方殖民统治。；黄石港本地士绅，日军占领黄石后出面组织维持会，为日军筹集物资、维持地方秩序，协助日军控制黄石港及西塞山一带。；黄石港地区维持会头目，日军占领黄石后出面组织维持会，为日军征集物资、拉夫、维持地方秩序，协助日军控制黄石港、石灰窑一带，铁山矿区亦受其影响。；在公安县组织维持会，为日军征粮征税，协助日军扫荡抗日武装，残害当地百姓。；湖北人，抗战期间投敌，任伪汉口市市长，配合日军推行治安强化运动，搜刮物资。；汉口沦陷初期任伪汉口市市长，组织伪政权，维持殖民秩序，为日军筹集物资。；武汉沦陷后任伪汉口市市长，推行伪政，为日军征发劳役、物资。；沙市沦陷后组织维持会，任会长，协助日军管理沙市及江陵一带民政、经济，为日军筹集物资。；沙市沦陷后出任伪维持会会长，协助日军控制沙市及周边荆州地区，为日军筹集物资。；湖北黄冈人，抗战期间组织伪维持会，为日军征粮、派夫，协助维持占领区秩序。；湖北黄冈人，抗战期间在黄冈地区组织伪维持会，协助日军征粮、征夫，维持地方伪秩序，镇压抗日群众。；黄冈地区人，抗战期间组织伪维持会，为日军征粮、派夫，协助日军控制黄冈一带。；黄冈地区伪维持会头目，协助日军在黄冈县及周边地区建立伪政权、征发劳役、搜刮物资。；以参议身份游说地方士绅附逆，为日军搜集西江两岸抗日武装情报。；襄阳沦陷期间组织伪政权，为日军提供情报，协助维持占领区治安。；襄阳沦陷后组织维持会，出任伪襄阳县县长，为日军征粮派款、维持地方伪秩序。；抗战期间投敌，任伪武汉特别市警察局局长，在武汉地区镇压抗日活动，搜捕抗日人员。；抗战期间出任伪武汉特别市警察局局长，利用伪警察力量镇压抗日活动，维护日军占领秩序。；在襄阳沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣”，毒化青少年思想，协助日军进行文化侵略。；在伪湖北省政府任职，为日军搜刮湖北沦陷区财政资源。；抗战时期投靠日军，在伪汉口市和伪湖北省政权中任职。；汪伪政权在湖北的官员，曾任伪汉口市市长，协助日军推行经济掠夺和治安强化。；在湖北沦陷区任职伪湖北省政府委员、伪武昌市政处处长，协助日军管理武昌地区，推行保甲制度。；抗战期间投敌，任伪黄陂县县长，在黄陂地区为日军推行伪化统治，组织维持会、保甲，协助日军征粮征夫。', '[]', '2026-09-10 09:57:14.006027', '2026-09-10 09:57:14.006027', '安徽', '合肥', '肥东', NULL, NULL, NULL, NULL, '');
