INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('36ceae7b71354ebcbb541d66e6c41416', '张亚东', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵；辽宁沈阳新民；安徽芜湖无为；山东德州临邑；山西阳泉城区；安徽铜陵枞阳；山东德州陵城；山东德州；山东德州德城；山东德州；山东聊城茌平；辽宁沈阳大东；山东德州齐河；山东德州；山东济南；山东潍坊临朐；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '率部配合日军扫荡枞阳沿江地区，捕杀抗日军民，强征民夫修筑碉堡；德州沦陷后任伪德县县知事/县长，组织维持会，协助日军维持德州城区及周边治安，征发民夫、粮食。；任伪山东省新民会会长，进行奴化宣传，协助日军推行保甲制度，涉及潍坊、临朐地区。；在济南推行奴化宣传，组织新民会训练汉奸骨干。；组织伪保安队配合日军扫荡新四军游击队，杀害多名抗日军民，掠夺物资。；组织伪保安团配合日军在德州及周边地区扫荡，进攻抗日武装，维护日伪基层统治。；德州沦陷后组织维持会，投靠日军，出任伪德县县知事，协助日军征粮、派夫、镇压抗日人员。；指挥伪警察搜捕抗日人员，实施保甲连坐，镇压济南市民反抗。；投靠日军，任铜陵县维持会会长及伪县长，协助日军征收粮税、强征民夫，镇压抗日活动。；日军侵占德州后，在德县一带出任伪职，协助日军维持占领秩序、征粮派款。；负责伪山东宣传，在聊城等地推行奴化教育，宣传“大东亚共荣”。', '[]', '2026-09-10 09:57:14.009625', '2026-09-10 09:57:14.009625', '安徽', '芜湖', '无为', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('36e6d54b3fa0430985fd1303a00bcc7a', '大桥忠一', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边延吉；吉林', '[]', '[]', '抗日战争时期', '', '在伪间岛省和伪吉林省担任次长，掌握实权，推行日本殖民政策，镇压延边抗日活动。', '[]', '2026-09-10 09:57:13.998072', '2026-09-10 09:57:13.998072', '吉林', '延边', '延吉', NULL, NULL, NULL, NULL, '');
