INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('37ae1b91a1504c9ebbde6c46b407bc44', '刘万海', NULL, NULL, NULL, NULL, 'exact', 'exact', '香河', '[]', '[]', '抗日战争时期', '', '伪职：伪特务队长。；结局：武工队锄奸击毙', '[]', '2026-09-10 09:57:14.072055', '2026-09-10 09:57:14.072055', '河北', '廊坊', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('37b96941b0764d6793f245e60e525c51', '马德山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西运城夏县；山西运城；河北沧州任丘；北京、山西、河北；山西吕梁；山西吕梁文水；河北廊坊安次；河北廊坊；河北廊坊固安；河北廊坊大厂；河北廊坊；山西朔州应县；河北邯郸邯郸经开区；河北邯郸；河北保定定州；河北邢台信都；河北_邢台_襄都；河北邯郸邯山；河北邯郸丛台；河北邯郸广平；山西大同广灵；河北邯郸；北京平谷；山西忻州代县；河北邯郸复兴；河北邯郸武安；河北邯郸魏县；河北秦皇岛青龙；河北邯郸成安；山西大同灵丘', '[]', '[]', '抗日战争时期', '', '日军占领平谷初期，组织维持会为日军筹粮筹款，提供向导，并劝降当地武装力量。；在文水县配合日军“扫荡”，烧毁村庄，抢掠财物。；为日军控制广灵商业，强迫商户向日军“献金”，并垄断食盐、布匹等物资供应，从中牟利，同时为日军收购军需物资。；专门抓捕抗日嫌疑人员，严刑逼供，杀害多名地下党员和进步群众。；专门搜集八路军和游击队活动情报，向日军报告，导致多次抗日行动失败，多名抗日人员被捕牺牲。……（共涉及23个地区的犯罪记录）；在固安南部设立据点，切断抗日交通线，并杀害多名交通员。', '[]', '2026-09-10 09:57:13.993880', '2026-09-10 09:57:13.993880', '北京', '平谷', '广灵', NULL, NULL, NULL, NULL, '');
