INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('387c748c4a9d42dd90a15111ac0da0d8', '李炎汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉武昌；湖北武汉洪山；湖北武汉；湖北武汉青山；湖北武汉武昌；湖北武汉东西湖；湖北武汉；湖北武汉汉阳；湖北武汉江夏', '[]', '[]', '抗日战争时期', '', '抗战期间在江夏地区组织伪维持会，为日军征粮、征丁，协助维持伪政权统治。；任伪汉阳县维持会会长及伪县长，控制汉阳地区基层政权，为日军征集粮食、劳工，镇压抗日活动。；武汉沦陷后在汉阳地区参与伪维持会并任伪汉阳县政府县长，协助日军在汉阳及周边地区推行伪化统治，征粮征工。；日军占领汉口后，参与组织伪汉口维持会并任会长，协助日军安民、筹粮。；抗战期间在武昌组织伪维持会，任会长，为日军占领当局服务。；武汉沦陷后在洪山地区组织伪维持会，任会长，协助日军控制洪山及周边地区，征粮征夫，压迫当地民众。；在汉阳及武汉近郊任伪县长、伪保安团头目，配合日军清乡，镇压当地抗日活动，东西湖一带亦在其伪统治影响范围内。', '[]', '2026-09-10 09:57:14.056518', '2026-09-10 09:57:14.056518', '湖北', '武汉', '新洲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3881878ea3fc44ca89886ce41217f816', '张老五', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '蒙城板桥集周边；河北邢台；河北；河北邯郸涉县', '[]', '[]', '抗日战争时期', '', '为日军强征民夫，修建炮楼，虐待劳工。；组织维持会为日军征粮派款，强迫百姓领取‘良民证’，告密抗日积极分子。；伪职：蒙城伪乡维持头目；罪行：日军过境蒙城期间出任临时伪乡长，迎接日军，抓夫抢粮，带路烧杀周边村庄。；结局：地方抗日武装捕获正法。', '[]', '2026-09-10 09:57:14.044574', '2026-09-10 09:57:14.044574', '河北', '邢台', '涉县', NULL, NULL, NULL, NULL, '');
