INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3919ef78f9424f32a23551aab3821f7d', '周化人', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠；广东_广州_天河；山西阳泉城区；陕西_西安_长安；安徽芜湖；安徽合肥；广东广州；湖南_湘西_泸溪；浙江丽水庆元；江苏镇江京口；江苏镇江', '[]', '[]', '抗日战争时期', '', '在芜湖推行“保甲制度”，强化殖民统治，镇压反日运动。；浙江人，汪伪浙江省政府官员，协助日军在浙江的统治。；负责伪安徽全省警察系统，在合肥设立伪警察分局，镇压抗日活动，抓捕地下党员。；在广东沦陷区推行亲日奴化教育，控制学校与宣传机构。；汪伪政权广州市行政负责人之一，推行伪政府政令，配合日军对广州民众的管控。；在汪伪政权中负责教育，推行奴化教育。；在蚌埠推行奴化教育，改编教材，强制学生学日语，宣扬“中日亲善”，迫害爱国师生。；汪伪政权时期曾任伪广州市市长，协助日伪控制广州城区。；在镇江京口地区实施粮食统制，强征农民粮食，镇压抗日宣传，逮捕进步人士。；曾任汪伪广州市市长，协助日军维持广州占领区秩序，推行伪化行政。；汪伪政权官员，曾任伪广州市市长，参与广东沦陷区行政与宣传事务。；汪伪政权在广东的地方官员，曾任伪广州市市长，协助日军管理广州。；推行奴化教育，在合肥、庐江等地学校强制教授日语，篡改历史教材。；推行奴化教育，在合肥、肥东学校强制教授日语，灌输“中日亲善”思想。；其亲日宣传体系覆盖湖南沦陷区，进行奴化宣传。', '[]', '2026-09-10 09:57:14.005741', '2026-09-10 09:57:14.005741', '安徽', '合肥', '京口', NULL, NULL, NULL, NULL, '');
