INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3a0898b4840443219638f669c0047b41', '王孝忱', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽亳州涡阳', '[]', '[]', '抗日战争时期', '', '安徽涡阳人，抗战期间投敌，组织伪维持会，后任伪涡阳县县长，为日军征粮、派夫，镇压抗日活动。', '[]', '2026-09-10 09:57:14.005035', '2026-09-10 09:57:14.005035', '安徽', '亳州', '涡阳', NULL, NULL, NULL, NULL, '');
