INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3a2c736819934669bfb7228992e46a69', '赵廷选', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北承德；河北承德承德高；河北承德', '[]', '[]', '抗日战争时期', '', '率伪军配合日军扫荡，屠杀承德周边村庄百姓，烧毁民房。；在承德地区推行日伪治安肃正，镇压抗日民众，协助日军建立保甲制度，抓捕抗日志士。；在承德地区（含鹰手营子矿区）组织特务网，抓捕抗日地下工作者，破坏抗日组织，多次参与“讨伐”行动，罪行累累。', '[]', '2026-09-10 09:57:14.042902', '2026-09-10 09:57:14.042902', '河北', '承德', '承德高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3a2e82b73c5f4d3990c1e234907f6ae3', '陈瑞祯', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊潍坊滨海经开区；山东潍坊昌乐；山东潍坊安丘；山东潍坊昌乐；山东潍坊青州；山东潍坊；山东潍坊昌邑；山东潍坊坊子', '[]', '[]', '抗日战争时期', '', '任伪潍县教育科科长，推行奴化教育，在潍县、坊子学校强制日语教学与亲日宣传。；山东益都（今青州）人，投敌后任伪县长，在益都、临朐一带推行伪政，配合日军征粮抓丁，活动区域邻近潍坊。；昌乐沦陷后组织维持会，任伪县长，为日军征粮征夫，推行伪化教育，配合日军扫荡。；伪山东省昌潍道行政长官，管辖潍县、昌乐、益都等地，推行日军殖民统治政策，征发劳工、物资。；抗战时期在昌邑伪政权中任职，执行日伪政令，组织伪军警和保甲，协助日军对昌邑抗日根据地进行扫荡和清乡。', '[]', '2026-09-10 09:57:14.016857', '2026-09-10 09:57:14.016857', '山东', '潍坊', '坊子', NULL, NULL, NULL, NULL, '');
