INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3a750373e9b648e595501bb70bcdf406', '吴正荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '无锡城区', '[]', '[]', '抗日战争时期', '', '伪职：伪侦缉队队长；罪行：老牌流氓汉奸，手上残害大量共产党、爱国志士，滥施酷刑，为日军大肆抓捕群众无锡市档案...。；结局：1939 年被尤国桢锄奸团击毙。', '[]', '2026-09-10 09:57:14.087902', '2026-09-10 09:57:14.087902', '江苏', '无锡', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3a76e162981a47a88327de623b1fca0e', '王开基', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山腾冲；云南保山龙陵；云南昆明', '[]', '[]', '抗日战争时期', '', '在腾冲、龙陵沦陷区，维持会负责为日军筹措物资。王开基被部分文史资料列为参与维持会、协助日军统治的地方人员。；王开基为昆明地方人士，曾被汪伪方面接触，拟任昆明维持会职务，因昆明未沦陷，未实际成立。', '[]', '2026-09-10 09:57:13.980123', '2026-09-10 09:57:13.980123', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
