INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3aa9fcdd4f744b9981d3b5fbc905b194', '姜明远', NULL, NULL, NULL, NULL, 'exact', 'exact', '开鲁', '[]', '[]', '抗日战争时期', '', '伪职：开鲁第一任伪县长，商会会长；1933 从中撮合促成李守信投敌，迎接日军占领开鲁，组建伪政权，搜刮资财。；结局：战后汉奸罪重刑关押', '[]', '2026-09-10 09:57:14.084863', '2026-09-10 09:57:14.084863', '内蒙古', '通辽', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3aaf47c5a0a546789ec683888d621420', '吉尔格朗', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古锡林郭勒苏尼特右旗；内蒙古鄂尔多斯杭锦旗；内蒙古锡林郭勒锡林浩特', '[]', '[]', '抗日战争时期', '', '率杭锦旗地方武装投靠日伪，配合伪蒙疆政权维持当地统治，镇压抗日群众。；在苏尼特右旗任伪警察署长，直接负责地方治安，搜捕抗日人员，配合日军和伪蒙军行动。；在锡林郭勒盟某旗任伪旗长，协助日伪征收牲畜、物资，控制牧民。', '[]', '2026-09-10 09:57:13.992260', '2026-09-10 09:57:13.992260', '内蒙古', '鄂尔多斯', '杭锦旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ab292b5ee774a5dbaee06dc5d175a71', '陈玉铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口阳原；河北；山西_朔州_右玉；内蒙古锡林郭勒乌拉盖；黑龙江哈尔滨尚志', '[]', '[]', '抗日战争时期', '', '日军占领阳原后率先组织维持会，为日军筹粮派款，出卖抗日积极分子。；在承德县推行伪满“街村制”，强征劳工，搜刮粮食，协助日军建立“无人区”，迫害抗日群众。；在承德地区任伪警务科长，组织特务情报网，多次抓捕抗日地下工作者，参与制造多起屠杀事件。', '[]', '2026-09-10 09:57:13.992419', '2026-09-10 09:57:13.992419', '内蒙古', '锡林郭勒', '乌拉盖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3abb6e27cd7348edbcd3177f2b0c83c6', '谢锡珍', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东梅州大埔', '[]', '[]', '抗日战争时期', '', '强制商户向日军缴纳“军需捐”，并协助日军统制大埔陶瓷、茶叶等物资。', '[]', '2026-09-10 09:57:14.027951', '2026-09-10 09:57:14.027951', '广东', '梅州', '大埔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ac5c6ba1ab94d079d9a133523afc26c', '刘汉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '大同', '[]', '[]', '抗日战争时期', '', '伪职：伪保安团团长；罪行：驻守大同城郊，强征壮丁扩充伪军，袭扰根据地边缘村庄。；结局：1945 光复被俘，判处重刑', '[]', '2026-09-10 09:57:14.083351', '2026-09-10 09:57:14.083351', '山西', '大同', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ae1c7e0b1f349c9a1f542d06ba52f1b', '张万才', NULL, NULL, NULL, NULL, 'exact', 'exact', '瑷珲、呼玛边境山林', '[]', '[]', '抗日战争时期', '', '伪职：伪瑷珲县山林警察小队长；罪行：熟悉黑龙江沿岸山林，带队搜捕抗联三支队，盘查采金工人，抓捕秘密支援抗联的边民。；结局：抗战胜利后被反奸清算镇压。', '[]', '2026-09-10 09:57:14.079494', '2026-09-10 09:57:14.079494', '黑龙江', '黑河', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ae82fd978234143838c4b9f9f38d657', '陈耀东', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳南漳；湖北襄阳；河南南阳；福建漳州诏安；福建漳州；重庆北碚', '[]', '[]', '抗日战争时期', '', '投敌后组建伪保安团，配合日军在襄阳、南漳一带进行清乡、扫荡，袭击抗日游击队，残害抗日军民。；漳浦沦陷后组织伪维持会，协助日军在漳州沿海地区推行伪化统治，为日军提供情报与物资。；抗战初期在北碚地区组织伪维持会，协助日军维持地方秩序、征派粮秣，后因日军未长期占领北碚而活动受限。；河南南阳人，抗战期间任伪南阳教育局长，推行奴化教育。', '[]', '2026-09-10 09:57:14.047165', '2026-09-10 09:57:14.047165', '河南', '南阳', '南漳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3af8f45aebe448b58d32823d3c112ff3', '于惠卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '勃利县城、茄子河矿区', '[]', '[]', '抗日战争时期', '', '伪职：伪勃利县警务科特务股特务；罪行：专门搜捕矿区与农村地下抗日人员，抓捕抗联交通员，主持刑讯逼供，制造多起冤狱。；结局：解放后被逮捕审判。；伪职：伪怀来县县长；依托沙城、新保安据点，抓捕地下交通人员，强征壮丁粮草。；结局：战后判处长期徒刑', '[]', '2026-09-10 09:57:14.071853', '2026-09-10 09:57:14.071853', '黑龙江', '七台河', NULL, NULL, NULL, NULL, NULL, '');
