INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3b243d29cb2a4f439d9bb307ca7b9651', '陈鸿猷', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大兴安岭漠河；黑龙江大兴安岭新林；北京大兴；黑龙江佳木斯桦川；吉林白城洮北；吉林白城；黑龙江大兴安岭呼中；北京大兴', '[]', '[]', '抗日战争时期', '', '协助日伪审判抗日人士，判处多名抗联情报员死刑或重刑。；负责黑河及大兴安岭北部特务工作，组织密探潜入呼中林区，破坏抗联地下交通线，逮捕多名抗联联络员。；为日本关东军特务机关效力，在白城、洮北建立情报网，破坏抗日地下组织，逮捕并杀害多名抗日志士。；原黑龙江教育界汉奸，投日后在协和会任职，在大兴安岭地区推行奴化宣传，诱降抗联意志薄弱者。；在漠河县（今漠河市）推行日伪统治，强征当地鄂伦春族和汉族百姓为日军修路、伐木，虐待劳工。', '[]', '2026-09-10 09:57:13.999407', '2026-09-10 09:57:13.999407', '吉林', '白城', '洮北', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3b2906c2d2f445c18109d6a55662a0c3', '张克顺', NULL, NULL, NULL, NULL, 'exact', 'exact', '淄川县', '[]', '[]', '抗日战争时期', '', '伪职：淄川县维持会成员/粮差；罪行：1937年12月底受淄川县维持会会长高福斋派遣，到河东村招抚“铁板会”，企图诱使其投降日军；结局：被“铁板会”成员扣押', '[]', '2026-09-10 09:57:14.074271', '2026-09-10 09:57:14.074271', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
