INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3bee808e02354fe283cbaa21f8164bb9', '张世安', NULL, NULL, NULL, NULL, 'exact', 'exact', '湾沚（今芜湖湾沚区）；湾沚（旧属芜湖县）', '[]', '[]', '抗日战争时期', '', '伪职：湾沚自治会会长（当时属宣城）；罪行：日军占领湾沚成立自治会，胁迫商户出钱出物资敌，配合芮义发往来宣城敌占区开展伪化活动。；结局：抗战胜利汉奸审判伏法。；伪职：湾沚伪自治会会长；罪行：湾沚沦陷组建维持自治会，征粮派夫，协助日军控制宣芜交通要道。；结局：抗战胜利后公审处决。', '[]', '2026-09-10 09:57:14.079303', '2026-09-10 09:57:14.079303', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3bf0d44294d54192ae33680f9f963078', '陈璧君', '冰如', NULL, 1891, 1959, 'exact', 'exact', '浙江宁波象山；吉林高；广东广州南沙；广东广州；广东_广州_天河；广东_江门_台山；重庆大足；云南昆明呈贡；广西桂林兴安；云南普洱西；江苏南京；辽宁沈阳和平；广东阳江阳西；广西桂林阳朔；云南普洱西；安徽芜湖鸠江；安徽芜湖；江苏南京；广西柳州；广西桂林；云南普洱西；广东广州黄埔；广东新会；广西桂林七星；云南普洱西；云南普洱西；江苏南京；广东佛山；广东阳江江城；广东阳江；广西桂林恭城；云南普洱西；广东佛山三水；广东_广州；广东_广州_白云；辽宁大连中山；广东广州增城；广东_广州_海珠；广东_广州_番禺；广东_广州_越秀；广东_江门；河北唐山开平；广东_江门_新会；广东_江门_江海；广东_江门_蓬江；广东_深圳_龙岗；云南普洱西；江苏南京；吉林高；广西桂林；广西贺州昭平；云南普洱西；广西柳州城中；云南普洱西；广东惠州龙门；广东惠州', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪精卫妻子，参与汪伪政权决策，在上海活动。结局：无期徒刑，1959 年上海监狱病亡红色文化网；陈璧君，字冰如，原籍广东新会，生于马来亚槟榔屿。南洋富商陈耕基之女。1908年在槟城听汪精卫演说后倾心，资助其革命事业。1912年与汪在上海结婚。抗战爆发后极力怂恿汪精卫投敌，是汪集团投敌的核心推手。汪伪政权成立后任伪中央监察委员会常委、政治委员会委员。1945年9月在广州被捕，1946年4月以汉奸罪被判处无期徒刑，1949年后由苏州监狱移送上海提篮桥监狱。1959年6月17日病死于狱中，年68岁。', '[]', '2026-09-10 09:57:13.982384', '2026-09-10 09:57:13.982384', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3bf4bd8bd52b4163a7b8bd6e18c34918', '朱怀冰', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌宜都；湖北宜昌；湖南长沙；天津河北；湖南长沙芙蓉；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '率部在河北南部、衡水一带进攻八路军，与日军夹击抗日根据地。；抗战期间投敌，出任伪宜昌县商会会长，为日军筹款筹粮，协助经济掠夺。；任伪宜昌县商会会长，为日军筹办军需物资，协助日伪经济统制。；参与伪湖南省政，在长沙、岳阳等地协助日军“清乡”。；负责日伪在湖南的舆论宣传，创办伪报，散布“大东亚共荣”言论，为日军侵略辩护。；湖南长沙人，沦陷后任伪长沙自治会会长，后任伪湖南省政府参议，在长沙及周边地区进行亲日宣传，组织伪自治机构。', '[]', '2026-09-10 09:57:14.044444', '2026-09-10 09:57:14.044444', '湖北', '宜昌', '宜都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3bf63766146c4f2a9f8d0d5bf2ea0e47', '毛光翔', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州贵阳', '[]', '[]', '抗日战争时期', '', '组织商界向日军献金献物，协助日伪发行军票、强征物资。', '[]', '2026-09-10 09:57:14.062591', '2026-09-10 09:57:14.062591', '贵州', '贵阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3bfa196c524b4ce59788df613c989291', '陈仲明', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东河源；广东韶关仁化；广东韶关；浙江温州永嘉；浙江温州洞头', '[]', '[]', '抗日战争时期', '', '组织维持会，为日军提供粮食和情报，协助建立伪政权，迫害抗日民众。；在广东沦陷区推行奴化教育，包括河源周边地区，编写伪教材，培训亲日师资。；参与伪军军事策划，协助日军进攻瓯江口及洞头沿海据点，破坏抗日游击队活动。；负责韶关地区物资统制，为日军掠夺粮食、矿产等战略物资，压榨当地民众，协助日军经济封锁抗日根据地。', '[]', '2026-09-10 09:57:14.028880', '2026-09-10 09:57:14.028880', '广东', '河源', '仁化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c0562d5d01c48de920f3e0385436121', '吴乾甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌海海南；海南澄迈；海南万宁；海南三沙西沙；海南白沙；内蒙古乌海海南；海南屯昌；海南三沙中沙；内蒙古乌海海南；海南三亚崖州；内蒙古乌海海南；海南海口美兰', '[]', '[]', '抗日战争时期', '', '协助日军掠夺海南橡胶、铁矿、盐等资源，推行物资统制，压榨当地民众。；以地方士绅身份投靠日军，参与伪政权咨询与劝降活动，协助日军推行‘治安强化’。；组织伪保安队，配合日军进攻抗日根据地，参与清乡、烧杀抢掠。；海南岛沦陷后投靠日军，参与伪琼崖临时政府，协助日军在海南推行殖民统治，影响波及崖县等地。；在海南日伪政权中任职，参与推行日军殖民统治政策，活动范围涉及海南南部地区。；率伪保安团随日军下乡扫荡，烧毁民房、抢掠粮食，并在万宁至陵水公路沿线设置关卡盘查抗日人员。；在日军侵占西沙群岛后，参与组织伪维持会，协助日军管理岛屿、掠夺磷矿资源并监视渔民。；在美兰一带执行保甲制度，监视居民，举报抗日人员，协助日军抓丁征粮。；海南岛伪政权高层之一，参与组建伪自治会，为日军统治海南制造舆论，协助推行经济掠夺与奴化教育。', '[]', '2026-09-10 09:57:14.052843', '2026-09-10 09:57:14.052843', '海南', '万宁', '崖州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c085015d5574ea1b33af0f2cd292f9c', '孟昭华', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南商丘睢县；河南商丘', '[]', '[]', '抗日战争时期', '', '商丘沦陷后在伪政权中任职，参与推行保甲连坐、征发劳工和粮秣，协助日军维持豫东占领区统治。', '[]', '2026-09-10 09:57:14.047660', '2026-09-10 09:57:14.047660', '河南', '商丘', '睢县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c0863e27e9e4efba2c8ae11b9b05aa9', '周贯虹', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安新干；江西九江武宁；广西桂林资源；江西南昌；江西宜春奉新；江西吉安永新；云南普洱西；江西吉安；山西阳泉城区；江西南昌；江西九江湖口；江西九江；江西赣州宁都；江西九江；江西吉安万安；云南普洱西', '[]', '[]', '抗日战争时期', '', '参与伪江西省政权事务，为日军在江西的统治提供协助。；据地方文史资料传闻，日军侵占奉新期间曾组织维持会，周氏被指为负责人之一，但确凿档案记载有限。；任伪南昌市市长期间配合日军统治，推行奴化教育、经济统制。；南昌沦陷后出任伪市长，主持伪市政，配合日军统治，为江西地区主要附逆者之一。；九江沦陷后组织维持会，为日军提供情报，协助建立伪政权。；在江西日伪政权中负责警务，协助日军维持占领区治安，镇压抗日活动。；吉安地方商人，日军侵占吉安期间出面组织维持会，为日军筹款筹粮，协助推行伪化教育。；控制南昌日占区商业，为日军采购军需物资，压榨商户，协助日军经济掠夺。；投靠日伪，在江西伪政权中负责财政事务，为日军搜刮沦陷区资源、维持伪政权运转效力。；九江沦陷后出面组织伪商会，为日军摊派款项、物资，协助控制粮食与日用品流通。；江西新干人，投敌后任伪保安队长，带领伪军协助日军清乡，镇压抗日力量。；统领伪保安大队，配合日军进攻武宁山区抗日游击队，捕杀抗日人员及其家属。；掌控伪南昌警察系统，搜捕抗日人员与嫌疑民众，协助日军维持城区治安与封锁。；掌控伪南昌市警察机构，搜捕抗日人员，协助日军维持占领区治安，参与镇压市民反抗。', '[]', '2026-09-10 09:57:14.039084', '2026-09-10 09:57:14.039084', '江西', '九江', '武宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c1a21bdcc5d4c81952d7a9409088784', '宋鼎铭', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁岫岩', '[]', '[]', '抗日战争时期', '', '伪职：伪满工兵上校，岫岩伪驻军头目；罪行：原奉系，投敌，驻守岫岩，拥兵千余；日本投降后固守岫岩，拒绝向八路军投降，等待国民党接收。；结局：被八路军先遣支队攻破岫岩俘获，公审处决。', '[]', '2026-09-10 09:57:14.070996', '2026-09-10 09:57:14.070996', '辽宁', '鞍山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c210b466f38426f959c5a374e215f02', '申宪武', NULL, NULL, NULL, NULL, 'exact', 'exact', '滕县', '[]', '[]', '抗日战争时期', '', '伪职：伪保安二师师长；罪行：滕县地区危害最大的伪军头目。以滕县西后闫村为巢穴，配合日军镇压抗日力量。1939年八路军一一五师挺进鲁南后，其主力刘广田、王振东、朱石英、刘宇华等部被先后消灭', '[]', '2026-09-10 09:57:14.080317', '2026-09-10 09:57:14.080317', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c23613dd15e4c489b607967b9b6fc51', '庄洪业', NULL, NULL, NULL, NULL, 'exact', 'exact', '抚顺', '[]', '[]', '抗日战争时期', '', '伪职：伪警察署翻译特务；罪行：充当日军翻译，告密、指认抗日群众，参与抓捕迫害。；结局：抗战时期被我方锄奸处决。', '[]', '2026-09-10 09:57:14.078200', '2026-09-10 09:57:14.078200', '辽宁', '抚顺', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c2b278077ef47f093af4be01382e068', '张福臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪宁津县县长；疯狂扫荡冀鲁边根据地，抓捕抗日干部。；结局：战后公审枪决', '[]', '2026-09-10 09:57:14.069486', '2026-09-10 09:57:14.069486', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c315c492dc54becae6a0e291a1e3899', '朱深', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京石景山；北京大兴；北京_东城；四川_广元；天津河北；重庆_永川；河北秦皇岛；山东聊城；北京延庆；江西九江；河南商丘；陕西渭南；陕西_西安；云南普洱西；北京西城；河北廊坊；江苏南京鼓楼；北京门头沟；河北秦皇岛秦皇岛经开区；河北秦皇岛；北京昌平；河北_秦皇岛；天津河北；河北廊坊；北京海淀；河北永清；北京丰台；北京、河北', '[]', '[]', '抗日战争时期', '华北伪临时政府', '参与决策对冀中抗日根据地的“毁灭性扫荡”，包括廊坊地区。；曾任伪中华民国临时政府司法委员会委员长，后任伪华北政务委员会常务委员，并一度兼任伪北京市长，推行日伪法令。；在任期间强化丰台地区日伪统治，推行“治安强化运动”，镇压抗日力量。；继余晋龢后任伪北平市长，强化对大兴等郊区的控制，增设伪警察分驻所，搜捕八路军地下工作人员。；参与北平伪政权司法系统，在延庆等地设立伪法院，迫害抗日群众，判处抗日志士死刑或劳役。；原北洋司法总长，投日后在北平任职，参与“治安强化运动”，对昌平抗日根据地实施封锁。……（共涉及14个地区的犯罪记录）；伪任职务：伪华北政务委员会司法总署督办，北平伪政权核心。结局：1943 年病死于北平，逃脱审判中国社会科...', '[]', '2026-09-10 09:57:13.992704', '2026-09-10 09:57:13.992704', '北京', '延庆', '秦皇岛经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c3648a7afaf4f09883d9534507a29b4', '单德贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '茶陵县', '[]', '[]', '抗日战争时期', '', '伪职：八路军第十三团副团长→伪京北剿匪少将支队长\"、代理平谷县伪县长\"；罪行：茶陵县虎踞山乡三芫村人。参加过长征、平型关战役的老红军。1944年5月因对组织不满，携妻女及两名警卫投靠河北三河县日伪；结局：抗战胜利后被北平国民党政府抓捕，以汉奸罪判处有期徒刑12年；1949年春在转运途中自杀身亡', '[]', '2026-09-10 09:57:14.083367', '2026-09-10 09:57:14.083367', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c3f47df1515435eae5c49acb1cd41aa', '周昆贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '望江杨湾', '[]', '[]', '抗日战争时期', '', '伪职：望江县杨湾汉奸向导；罪行：带领日军汽艇扫荡杨湾，直接酿成杨湾惨案，52 名平民惨遭杀害，村庄焚毁，为日军打探乡间抗日武装踪迹望江新闻网。；结局：抗战胜利公审处决。', '[]', '2026-09-10 09:57:14.081223', '2026-09-10 09:57:14.081223', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c491046a05a4ed3963973663b2efeea', '李中襄', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西南昌；辽宁沈阳大东；江西鹰潭余江；江西九江；江西宜春高安；江西南昌；江西宜春袁州；江西宜春；江西南昌；江西宜春；江西南昌西湖；江西南昌；江西景德镇乐平；江西景德镇；江西赣州会昌；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '南昌沦陷后参与伪政权筹备活动，与宜春、高安一带的伪维持会有联系。；九江沦陷后投敌，任伪县长，推行保甲连坐，为日军征工征粮，镇压抗日活动。；在日占江西期间掌管伪警察系统，在宜春、袁州等地搜捕抗日分子，实施白色恐怖。；在日伪控制的南昌及周边地区建立伪警察体系，配合日军搜捕抗日人士，向赣南、赣东渗透伪警力量，维持日伪治安。；在日占区推行奴化教育，篡改教材，宣扬“大东亚共荣圈”，毒害青年学生。；在赣州城区组织伪维持会，为日军征派物资、搜集情报，协助日军控制赣州及周边会昌等地。；汪伪政权在江西地区的重要附逆者，参与伪江西省政，活动范围覆盖赣西、宜春一带。；在伪江西省政权中任职，参与南昌周边伪化行政，为日军征粮、征兵与情报搜集服务。；在景德镇为日军统制陶瓷生产与销售，强迫瓷工为日军生产军用物资，压榨地方经济。', '[]', '2026-09-10 09:57:14.039410', '2026-09-10 09:57:14.039410', '江西', '南昌', '西湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c4dbc9ea9f34876afc9cee097b45beb', '丁训斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '益都（今青州）', '[]', '[]', '抗日战争时期', '', '伪职：伪益都县知事；罪行：1938年日军侵占益都后成立的伪益都县公署知县', '[]', '2026-09-10 09:57:14.067389', '2026-09-10 09:57:14.067389', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c4ed15556f94dc3b5eacd693a8152bf', '李阿才', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江台州玉环', '[]', '[]', '抗日战争时期', '', '控制坎门渔港，为日军提供渔船和渔民情报，强迫渔民为日军运输物资，克扣渔民口粮。', '[]', '2026-09-10 09:57:14.050146', '2026-09-10 09:57:14.050146', '浙江', '台州', '玉环', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c52f539fd254d66a67978572492e05a', '赵全功', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中榆次；山西晋中左权；山西晋中灵石；河北_张家口_蔚县；山西长治潞州；辽宁沈阳新民；山西吕梁文水；辽宁沈阳新民；山西太原小店；山西_晋中_昔阳；山西晋中太谷；山西朔州山阴；山西太原万柏林；山西太原古交；山西、河北', '[]', '[]', '抗日战争时期', '', '宣传奴化思想，组织“新民会”为日军服务，强迫群众参加反共集会，告密抗日积极分子。；率伪警协助日军“扫荡”，在万柏林一带抓捕抗日军民，实施酷刑，强征劳工。；率伪警察抓捕抗日地下党员，破坏古交地下交通站。；抓捕抗日地下交通员，破坏小店地区地下联络站。；推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，搜集抗日情报。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.020261', '2026-09-10 09:57:14.020261', '山西', '吕梁', '文水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c57fa1df92e4635b3cd5a088839ab82', '黄启良', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门开平；河北唐山开平；广东汕头；广东韶关曲江；广东韶关；山西阳泉城区；广东汕头潮阳；广东阳江阳春；广东清远连南；广东清远阳山；广东梅州五华；广东_肇庆_四会；广东清远连州；广东清远阳山；广东韶关始兴；广东清远；广东梅州梅县；广东清远清新；广东清远英德；广东清远；广东韶关南雄；广东韶关；广东广州荔湾；广东广州；广东清远佛冈；广东佛山；广东梅州蕉岭；广东广州；广东云浮新兴；广东揭阳惠来', '[]', '[]', '抗日战争时期', '', '佛山商界附逆代表，为日军筹款、摊派物资，协助日伪控制佛山粮食与日用品贸易。；掌管伪警察系统，搜捕抗日人士，协助日军维持汕头市区治安。；在阳山县协助日军建立伪政权，组织维持会，为日军征粮派款，监视当地民众。；黄启良统率伪保安大队在惠来及周边地区配合日军作战，参与围剿抗日武装，强征民夫修筑工事，残害当地百姓。；在清新地区组织伪维持会，为日军征粮派款，诱降地方武装，配合日军对抗日根据地的封锁与扫荡。；在肇庆城区及高要县境推行伪警察统治，搜捕抗日分子，勒索商民，为日军提供情报。；在肇庆城区及鼎湖一带搜捕抗日分子，推行保甲连坐，协助日军维持殖民统治。；连州地区沦陷或受日军威胁期间，出面组织伪维持会，为日军筹粮、派夫，协助维持伪政权统治。；阳春地区沦陷或受日军威胁期间，组织伪维持会，为日军筹粮、派款、拉夫，协助维持日伪统治。；台山沦陷期间组织伪维持会，配合日军在台山、开平一带的统治与经济掠夺。；在潮汕沦陷区任伪警察头目，配合日军镇压抗日群众，搜捕抗日人员，其活动范围覆盖潮梅地区。；在潮阳及潮南一带组建伪警察力量，搜捕抗日人员，推行治安强化。；担任伪保甲长期间，为日军搜集梅县抗日游击队情报，带领日伪军搜山，迫害抗日家属。；统率伪保安部队在潮梅各县配合日军扫荡，强征民夫、掠夺物资，对丰顺、梅县等地抗日力量进行清剿。；韶关始兴沦陷区伪维持会头目，为日军征集物资、维持治安，与南雄、曲江伪政权有联系。；担任伪保甲长期间为日军搜集抗日游击队情报，带领日伪军搜村，导致多名抗日群众被捕。；在广州沦陷后受伪广东治安维持会指派，回梅县组织分会，拉拢地方劣绅，为日军南侵张目，后因日军未占梅县而活动受限。；任伪清远县警察局长，配合日军搜捕抗日人员，镇压当地民众反抗。；英德沦陷后组织伪英德县维持会，任会长，协助日军控制英德地区，镇压抗日活动。；在清远组织伪维持会，配合日军对北江流域的扫荡。；广州沦陷期间在伪商会任职，协助日伪进行经济统制与物资征集。；韶关地区伪维持会副会长，配合日军在韶关一带进行统治与物资征集。；掌控伪警察武装，搜捕抗日志士，协助日军维持占领区秩序，勒索民众。；在佛冈县协助日军建立伪政权，负责摊派捐税、登记户口、诱降抗日人员，为日军提供佛冈至清远一带的情报。；在阳山（邻近连南）组织伪维持会，配合日军对粤北山区的扫荡，为日军征发民夫、粮食，协助建立伪保甲制度。', '[]', '2026-09-10 09:57:14.025209', '2026-09-10 09:57:14.025209', '广东', '云浮', '新兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3c5cb6ad8e1a485c9999e00e3f1e47a4', '卢满喜', NULL, NULL, NULL, NULL, 'exact', 'exact', '孝感县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：1942年5月在孝感县小河镇尾追新四军战士陶林，为其通风报信', '[]', '2026-09-10 09:57:14.068986', '2026-09-10 09:57:14.068986', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
