INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cb1ba70d8ac4d2f8774b8999eaade71', '毕春茂', NULL, NULL, NULL, NULL, 'exact', 'exact', '外地流窜', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪自卫团团长，部队盘踞邵伯湖西岸戚墅庙；配合邵伯据点日伪军下乡扫荡，抢劫湖沿各圩农户，扣押勒索湖上商船渔民。。结局：新四军奔袭戚墅庙据点，部队被歼灭，毕春茂被俘后处决邗江史志网', '[]', '2026-09-10 09:57:14.072048', '2026-09-10 09:57:14.072048', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cb5a4f13f394b8d89d48e77a8ac8047', '陈阿兴', NULL, NULL, NULL, NULL, 'exact', 'exact', '邵武、和顺一带', '[]', '[]', '抗日战争时期', '', '伪职：日特眼线；罪行：外来潜入分子，混迹集镇，收买当地地痞，搜集后方仓储、兵源情报，鼓动走私资敌。；结局：邵武地方自卫队抓获，判处有期徒刑。', '[]', '2026-09-10 09:57:14.079271', '2026-09-10 09:57:14.079271', '福建', '南平', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cb76da6a4cf4ee487a636fcab92c341', '关庆禄', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江穆棱；黑龙江牡丹江；黑龙江黑河逊克；黑龙江双鸭山宝山', '[]', '[]', '抗日战争时期', '', '直接指挥伪警察和特务队，多次袭击抗联小分队，抓捕并杀害抗日群众，在逊克宝山乡制造“血洗”事件。；在牡丹江宪兵队担任翻译，参与审讯和拷打被捕抗联人员，直接导致多名抗联干部被处决，并协助日军进行“特别移送”。', '[]', '2026-09-10 09:57:14.066492', '2026-09-10 09:57:14.066492', '黑龙江', '牡丹江', '穆棱', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cb771469089460290ef2864b2505b5f', '陈长捷', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼和浩特武川；内蒙古乌海；山西太原阳曲；内蒙古包头；内蒙古乌兰察布；山西吕梁；内蒙古呼和浩特新城；内蒙古、山西', '[]', '[]', '抗日战争时期', '', '原国民党军官，1940年投日，在乌兰察布东部（兴和、丰镇）组织伪保安队，配合日军“蚕食”抗日根据地。；原国民党军官，被俘后投敌，任伪包头市长，推行日伪法令，组织汉奸商会，为日军筹集物资，迫害爱国人士。；原国民党将领，被俘后变节，在归绥新城为日军出谋划策，参与策划对抗日武装的围剿行动。；负责日伪军后勤，贪污军需物资，间接导致伪军战斗力低下，但助纣为虐。', '[]', '2026-09-10 09:57:13.986335', '2026-09-10 09:57:13.986335', '内蒙古', '乌兰察布', '新城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cb9bc3072004d339c52536e6fc728fc', '郭连生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西晋中左权；山西晋中榆次', '[]', '[]', '抗日战争时期', '', '在榆次、太谷一带为日军效力，强征壮丁，搜刮粮食，破坏地下交通线。；在长治城组织维持会，为日军提供情报，协助建立伪政权，强迫百姓领取“良民证”，迫害抗日家属。', '[]', '2026-09-10 09:57:14.022465', '2026-09-10 09:57:14.022465', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cc0e9bcd25742968387cfd225c34972', '沈文奎', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州长兴', '[]', '[]', '抗日战争时期', '', '作为汪伪政权在长兴的行政代理人，负责征收田赋和杂税，为日军提供军粮，并参与诱降国民党地方武装。', '[]', '2026-09-10 09:57:14.051744', '2026-09-10 09:57:14.051744', '浙江', '湖州', '长兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cc41101cab8413ca9ba5ae999b7f18d', '王金声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；河北沧州东光；河北沧州沧县；河南南阳新野；河南南阳西峡；河北；河北沧州吴桥；河北衡水；河南商丘；河南南阳南阳示范；河南南阳；河南信阳；河南南阳；河北邢台清河；河北衡水枣强', '[]', '[]', '抗日战争时期', '', '在沧县及东光交界地区协助日军清乡，残害抗日家属，抢劫民财。；效忠日军，负责伪警察系统，搜捕抗日地下人员，破坏中共地下组织，参与“清乡”行动。；在深县地区协助日军建立据点，围剿抗日武装，强征民夫修筑炮楼。；在衡水推行日伪统治，设立伪警察所，强征劳工，协助日军修建碉堡和封锁沟。；为日军搜集情报，抓捕抗日地下人员，参与‘清乡’行动，迫害抗日家属。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042999', '2026-09-10 09:57:14.042999', '河北', '沧州', '东光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cc54c5dcfac454fb0a88959bb05fb97', '马元祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳南召；河南南阳；河南南阳方城；河南南阳', '[]', '[]', '抗日战争时期', '', '1944年投敌，任伪豫南特别区行政公署专员，管辖包括南阳在内的豫南地区，为日军筹粮、派夫、推行伪化教育。；在豫南、南阳一带活动，率伪军配合日军进攻抗日武装，掠夺民众财物，残害抗日家属。', '[]', '2026-09-10 09:57:14.046688', '2026-09-10 09:57:14.046688', '河南', '南阳', '南召', NULL, NULL, NULL, NULL, '');
