INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cd3fc386add44bc8f2b7570c53469ef', '包善一', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古通辽库伦旗；内蒙古通辽；内蒙古通辽开鲁；内蒙古通辽；内蒙古通辽科尔沁左翼中旗；内蒙古通辽科尔沁左翼后旗；科尔沁左翼后旗；内蒙古赤峰巴林右旗；内蒙古乌海乌达；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '原为地方士绅，后投靠日军，任伪通辽县县长，协助日军建立保甲制度，搜捕抗日地下人员，强征军粮。；伪职：伪兴安军骑兵统领，原博王旗统领；九一八后投靠日军，组建伪武装，盘踞科左后旗，为日军征调粮草、马匹，镇压草原反抗力量。；结局：日本投降被国民党收编，解放后镇压处决', '[]', '2026-09-10 09:57:13.988211', '2026-09-10 09:57:13.988211', '内蒙古', '呼伦贝尔', '扎兰屯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cda09b50313429b86ad68750d0b9dd6', '刘玉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西临汾汾西；山东枣庄；河北张家口怀来；山西临汾；安徽滁州全椒；河北张家口赤城；峄县；山东枣庄山亭；山西、河北；山西吕梁石楼；贵池梅街', '[]', '[]', '抗日战争时期', '', '伪职：枣庄维持会会长；罪行：青帮小头目。1938年日军侵占枣庄后，第一个打起欢迎旗，出任枣庄维持会会长。利用其鑫大面粉厂为日军收购粮食，解决日军军粮问题；伪职：叛变游击队员；罪行：原我方人员被俘投敌，潜伏南山搜集游击队情报，策动基层人员叛变。；结局：武工队捕获就地镇压。；主持伪新民会临汾分会，推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，刺探抗日情报。；配合日军“清乡”，在怀来山区搜捕八路军伤员，抢劫百姓财物，杀害抗日家属。；在赤城县城及乡镇建立伪警察网络，搜捕八路军侦察员和抗日家属，实施酷刑。', '[]', '2026-09-10 09:57:14.009133', '2026-09-10 09:57:14.009133', '安徽', '滁州', '全椒', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3cda2a49c2494ff6957dccaca8e75147', '陈伯达', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建漳州平和', '[]', '[]', '抗日战争时期', '', '福建附逆文人，在汪伪政权中任职，为日军在福建的统治进行宣传。', '[]', '2026-09-10 09:57:14.061900', '2026-09-10 09:57:14.061900', '福建', '漳州', '平和', NULL, NULL, NULL, NULL, '');
