INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ce3e40ae86f4d74998688c7c1218c12', '金昌洙', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边龙井；吉林延边汪清；吉林延边和龙', '[]', '[]', '抗日战争时期', '', '亲自审讯和拷打被捕的抗联战士及地下党员，提供情报导致多处秘密联络点被破坏。；在龙井设立秘密监狱，严刑拷打抗日嫌疑犯，协助日本宪兵队破获多处地下联络站。；率保安队多次袭击抗联小分队，捕获后残忍处决，并参与“归屯并户”烧毁民房。', '[]', '2026-09-10 09:57:13.997735', '2026-09-10 09:57:13.997735', '吉林', '延边', '和龙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ce6cf61bc1e4e36aca3629b9bf041e7', '李杏村', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南漯河临颍；河南漯河', '[]', '[]', '抗日战争时期', '', '1944年日军占领郾城后，组织维持会并出任伪县长，为日军征集物资、维持地方秩序，其活动范围覆盖漯河及周边地区。', '[]', '2026-09-10 09:57:14.048653', '2026-09-10 09:57:14.048653', '河南', '漯河', '临颍', NULL, NULL, NULL, NULL, '');
