INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3d39daa2ce9e4784beb84e6f32fda3ef', '张梦熊', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安遂川；江西南昌', '[]', '[]', '抗日战争时期', '', '在南昌沦陷区为日军筹措物资，协助经济掠夺，属经济领域附逆者。', '[]', '2026-09-10 09:57:14.039947', '2026-09-10 09:57:14.039947', '江西', '吉安', '遂川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3d3d67cd86fc4fcabb5e7730c758c536', '陈少安', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆袍哥头目', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：暗中和上海汪伪特务机关通信，在重庆散布 “抗战必败” 投降谣言，发展下线情报眼线。。结局：抗战期间被逮捕判刑', '[]', '2026-09-10 09:57:14.068009', '2026-09-10 09:57:14.068009', '重庆', '重庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3d3ec102cc6a40a2b0188cf71e09a082', '株洲地区维持会相关人物', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南株洲石峰', '[\"待考\"]', '[]', '抗日战争时期', '', '1944年日军发动豫湘桂战役，占领株洲（当时为湘潭县株洲镇，今株洲市石峰区一带属之）。当地曾出现维持会组织，协助日军征粮、拉夫、维持治安。具体姓名因地方档案散失，难以确证。', '[]', '2026-09-10 09:57:14.058731', '2026-09-10 09:57:14.058731', '湖南', '株洲', '石峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3d55eabd1b4d49e096a1ea97000530f7', '郭象升', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城阳城；山西太原；山西晋城高平；山西太原；山西临汾洪洞；山西临汾；山西太原示范；辽宁沈阳大东；山西；山西临汾襄汾；山西临汾；山西晋城；山西晋城阳城', '[]', '[]', '抗日战争时期', '', '在临汾地区宣传“中日亲善”，为日军粉饰侵略，参与审查和销毁抗日书刊，破坏文化抗日活动。；组织汉奸文人鼓吹“大东亚共荣”，为日伪统治制造舆论，污蔑抗日运动。；在阳城县推行日伪法令，破坏抗日组织，曾亲自带路引导日军包围抗日村庄。；作为晋城籍士绅投敌，在太原伪省府任职，为日军“以华制华”出谋划策，并回乡劝降抗日武装。；在太原为日伪文化宣传服务，撰写美化侵华文章，并回乡策反知识分子。', '[]', '2026-09-10 09:57:14.019239', '2026-09-10 09:57:14.019239', '山西', '临汾', '洪洞', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3d5d718de9594a3c9ca2ec193f1a31fd', '郭继昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中太谷', '[]', '[]', '抗日战争时期', '', '日军占领太谷初期，协助建立维持会，为日军提供当地情报，并组织“宣抚班”诱降抗日人员。', '[]', '2026-09-10 09:57:14.022333', '2026-09-10 09:57:14.022333', '山西', '晋中', '太谷', NULL, NULL, NULL, NULL, '');
