INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3dba8f43a78c429d8d2f1d88a9467d75', '李老财', NULL, NULL, NULL, NULL, 'exact', 'exact', '永定、永靖边境', '[]', '[]', '抗日战争时期', '', '伪职：日伪情报联络员；罪行：原沿海商人，厦门沦陷后附逆，受指派潜入永定山区，打探闽粤交界防务，试图联络地方土匪接应日伪势力。；结局：闽西地方自卫队捕获，判处死刑。', '[]', '2026-09-10 09:57:14.072086', '2026-09-10 09:57:14.072086', '福建', '龙岩', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3dce81ca7f4e4a0ba58c8857ca5c4277', '金壁东', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林_长春_德惠；河北承德平泉；辽宁鞍山岫岩；辽宁鞍山岫岩；辽宁鞍山；辽宁_大连_长海；辽宁铁岭（满族）；吉林长春；黑龙江哈尔滨；河北承德；辽宁_沈阳_大东；辽宁铁岭西丰；辽宁铁岭；黑龙江佳木斯富锦；黑龙江佳木斯；黑龙江哈尔滨松北；黑龙江齐齐哈尔；吉林、河北、辽宁；河北承德双滦；河北承德；辽宁锦州古塔；吉林长春；吉林；吉林；黑龙江牡丹江', '[]', '[]', '抗日战争时期', '', '清肃亲王善耆之子，投日后在四平、长春一带协助日军管理铁路与城市，镇压反满抗日活动。；熙洽之后继任伪吉林省长，推行日本移民政策，强征劳工，镇压反满抗日活动。；在任期间配合日本“决战体制”，强征物资和兵员，迫害抗日志士。；清皇室后裔，投日后任伪新京（长春）市长，管理伪都，镇压抗日活动。；清肃亲王善耆之子，投靠日本后历任伪满要职，在吉林龙潭地区推行殖民政策，协助日军镇压抗联。……（共涉及13个地区的犯罪记录）；伪职：伪新京特别市第一任市长；罪行：伪满早期新京主官，参与城市殖民规划，强征土地、劳工，镇压城内爱国运动。；结局：抗战胜利前病死。；已列，补充其曾协助日军运输军火。', '[]', '2026-09-10 09:57:13.996553', '2026-09-10 09:57:13.996553', '河北', '承德', '双滦', NULL, NULL, NULL, NULL, '');
