INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ddc4c5b203d4d4abc576c111150bd0e', '夏恭', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔牙克石；重庆沙坪坝；内蒙古_赤峰_松山；内蒙古锡林郭勒正蓝旗；内蒙古呼和浩特和林格尔；黑龙江大庆大同；黑龙江大庆大同；山西大同；黑龙江大庆大同；陕西榆林府谷；陕西榆林；内蒙古巴彦淖尔；山西；山西大同新荣；黑龙江大庆大同；山西朔州朔城；山西朔州；山西大同；山西大同平城；黑龙江大庆大同；山西大同浑源；黑龙江大庆大同；陕西西安；大同；内蒙古乌兰察布察哈尔右翼中旗；吉林高；黑龙江大庆大同；内蒙古鄂尔多斯；内蒙古_锡林郭勒_多伦；内蒙古鄂尔多斯；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪晋北自治政府最高委员；伪蒙疆联合自治政府副主席、大同炭矿理事长（1937??1941）；罪行：清末举人，日军占领大同牵头组建维持会，建立伪晋北自治政府；推行 “铲共防共”，编闾保甲，协助日军掠夺大同煤炭、粮食，推行奴化教育，配合日军扫荡雁北各抗日根据地。；结局：1941 年病死，逃脱战后审判，钉在历史耻辱柱上；日军占领大同后，出任伪晋北自治政府最高委员，组织维持会，为日军征粮派款，协助建立伪政权。；日军侵占大同后，出任伪晋北自治政府主席，推行奴化教育，组织伪警察协助日军维持秩序，强征民夫修建军事设施。；日军扶植的伪晋北自治政府首脑，驻大同，主持伪政权日常事务，为日军提供粮秣、情报，协助镇压抗日力量。；日军占领大同后出任伪县知事，组织维持会，协助日军建立伪政权，并参与对天镇地区抗日武装的围剿。；1937年日军占领大同后，出任伪晋北自治政府主席，后任伪大同省省长，积极为日军征粮、抓夫，组织伪警察镇压左云等地抗日活动。……（共涉及9个地区的犯罪记录）；伪任职务：伪晋北自治政府主席（雁北十三县），大同伪政权首脑，前清举人。结局：1941 年病亡，逃脱战后审判', '[]', '2026-09-10 09:57:13.987238', '2026-09-10 09:57:13.987238', '内蒙古', '乌兰察布', '察哈尔右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3de2d896b29e43d8b05a493467365308', '陈炳康', NULL, NULL, NULL, NULL, 'exact', 'exact', '瑞安城郊', '[]', '[]', '抗日战争时期', '', '伪职：伪瑞安便衣特务头目；罪行：网罗流氓充当爪牙，刺探地下党组织情报，搜捕抗日人员。；结局：根据地武工队锄奸处决。', '[]', '2026-09-10 09:57:14.067259', '2026-09-10 09:57:14.067259', '浙江', '温州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e000381d5cf46e8ad2ded023f8881c3', '赵金标', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城射阳；江西宜春；江西萍乡；浙江衢州常山；安徽马鞍山博望；浙江绍兴柯桥；江苏镇江句容', '[]', '[]', '抗日战争时期', '', '指挥伪警察协助日军巡逻，抓捕抗日嫌疑犯，严刑逼供，并勒索百姓财物。；组织伪自卫团，协助日军修建碉堡和封锁线，强征民夫，克扣口粮，致多人饿死。；驻防句容边境，参与“围剿”新四军，杀害多名游击队员。；专门侦缉抗日地下人员，多次破获情报站，严刑拷打被捕者，致死多人；率湖匪投靠日军，在射阳湖区域抢劫商船，袭击新四军运输队，为日军提供水路情报。；率伪军配合日军进攻萍乡、宜春交界抗日根据地，烧毁民房、抢掠财物。', '[]', '2026-09-10 09:57:14.011017', '2026-09-10 09:57:14.011017', '安徽', '马鞍山', '博望', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e0cf3c0665f472d895172f501f05824', '王连璧', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北沧州南皮；河北；昌黎；河北沧州献县', '[]', '[]', '抗日战争时期', '', '率伪保安队驻守南皮各据点，多次随日军“清乡”，抓捕抗日干部，抢掠百姓财物，并参与杀害八路军侦察员。；率伪保安队多次袭击孟村、盐山交界处的抗日武装，杀害抗日战士，抢劫百姓财物，充当日军鹰犬。；组织汉奸武装，多次袭击县抗日政府，杀害抗日干部，参与制造多起惨案。；伪职：伪昌黎县县长、新民会头目；推行奴化教育，掠夺粮食矿产，管控滦河沿线据点。；结局：日本投降后逮捕判刑；伪职：伪昌黎县长，新民会头目，奴化教育、物资掠夺。；结局：日本投降后逮捕判刑', '[]', '2026-09-10 09:57:14.043047', '2026-09-10 09:57:14.043047', '河北', '沧州', '南皮', NULL, NULL, NULL, NULL, '');
