INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e50cbb5527641d283dfc0474c669c22', '成逸庵', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；山东德州宁津；山东德州；山东济宁金乡；山东济宁；山东菏泽；山东潍坊潍坊滨海经开区；辽宁沈阳新民；山东德州德城；山东德州；山东德州庆云；山东德州；山东德州齐河；山东德州；山东济南；山东济宁；山东淄博博山；山东淄博；山东潍坊寒亭；山东_潍坊_潍城；山东_潍坊_青州；山东济宁梁山；山东济宁；山东德州武城；辽宁沈阳新民；山东济南钢城；山东济南；山东德州陵城；山东_济宁_鱼台；山东聊城茌平；山东聊城；山东德州；山东潍坊高密；山东东营；山东东营广饶；山东济南；山东_青岛；山东潍坊；山东潍坊坊子；山东_潍坊_昌乐；山东_潍坊_诸城；山东淄博淄川；山西阳泉矿区；山东淄博周村；辽宁沈阳新民；山东聊城东昌府；山东潍坊昌邑；山东德州临邑；山东德州', '[]', '[]', '抗日战争时期', '', '负责山东沦陷区民政，协助日军征粮、派夫，推行奴化教育。；在济南推行奴化教育，改编教材，灌输亲日思想。；在济南推行奴化教育，篡改教材，为日军殖民统治服务。；广饶县（今属东营市）人，抗战初期组织维持会迎降日军，后任伪县知事，协助日军征粮、抓丁、推行保甲，镇压抗日群众。；在鲁北道任职期间，协助日军控制德州、临邑等地，参与治安强化运动。；在淄川、博山一带组织维持会，协助日军控制淄博矿区，压榨矿工，镇压抗日活动。；在伪山东省政府任职，参与日伪政权对山东各地的行政管理，其辖区涉及淄博周边地区。；在鲁北地区任伪职，协助日军维持占领区统治，参与征粮、抓丁等事务，活动范围覆盖德州一带。；在山东推行新民会亲日宣传与殖民教育，协助日军进行思想控制，活动范围覆盖淄博地区。；负责日伪宣传与奴化教育，在潍坊等地设立新民会分会，推行亲日文化教育。；高密沦陷后组织维持会，出任伪县长，为日军征粮征夫，镇压抗日活动。；任伪鲁北道道尹，管辖包括德州在内的鲁北地区，协助日军推行伪化统治。；在潍县组织维持会，协助日军维持地方伪秩序，征粮派款，压迫民众，其活动直接影响昌邑、潍县周边地区。；驻济南，掌管伪山东警察系统，镇压抗日人员，推行治安强化运动。；掌管伪山东警察系统，在济南及周边地区镇压抗日人员。；在济南主持伪山东警务，配合日军扫荡、清乡，镇压抗日根据地。；在济南主持伪警务，镇压抗日活动，推行治安强化运动。；驻济南，掌管伪警察系统，配合日军搜捕抗日人员，实施治安强化运动。；在伪山东省政权中主管警务，建立伪警察网络，配合日军在山东包括济宁地区镇压抗日活动。；在山东包括泰安、东平地区推行奴化教育，组织新民会协助日军控制民众。；在山东伪政权中任职，参与鲁北地区日伪行政与治安事务。；在鲁北道（辖德州、宁津等）推行伪化行政，组织伪自卫团，协助日军掠夺棉花、粮食等物资。；德州沦陷后组织维持会，任伪德县县长，为日军筹粮筹款、维持地方伪秩序。；在山东包括德州地区推行新民会奴化教育，组织宣传亲日思想。；主持山东伪新民会，在济宁等地推行亲日宣传和奴化教育。；率伪军在济南周边及鲁中地区配合日军扫荡抗日根据地。；潍县本地士绅，日军占领潍县后出面组织维持会，后任伪县长，为日军征粮、征夫，推行奴化教育。；潍县沦陷后出面组织维持会，后任伪潍县县长，协助日军管理潍县及坊子地区，推行保甲连坐、征粮征工。；在潍县组织维持会，投靠日军，协助建立伪政权，推行保甲制度，镇压抗日群众。；日军侵占潍县后组织维持会，后任伪县长，为日军征粮征夫，推行奴化教育，协助日军镇压抗日活动。；在伪山东省公署任职，配合日军掠夺山东资源，在聊城、东昌府一带修筑公路、据点，服务于日军军事控制。；伪山东省委员，参与聊城地区伪政权事务。；抗战期间任伪鲁西道尹，管辖鲁西地区，包括济宁部分县区，推行日伪政策，征发民夫物资。；伪鲁西道行政长官，管辖包括菏泽在内的鲁西地区，推行伪化教育、征粮征丁。；潍县沦陷后组织维持会，为日军筹粮筹款、征发劳工，协助日军统治潍县及寒亭地区。；潍县沦陷后组织维持会，为日军筹粮筹款，协助建立伪政权。；潍县沦陷后组织维持会，为日军筹粮筹款，维持地方伪秩序。；在伪鲁北道及伪山东省政权中任职，参与日伪对鲁北包括德州地区的统治，协助日军维持占领秩序。；在鲁西道推行奴化教育，影响济宁、梁山地区教育系统。；负责山东伪政权民政事务，推行保甲制度，协助日军控制基层。', '[]', '2026-09-10 09:57:14.011882', '2026-09-10 09:57:14.011882', '山东', '东营', '东营经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e576333f39a45fb95363490b286ddbf', '张英武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄元氏；河北石家庄栾城；河北保定高碑店；河北；河北_邯郸_成安；河北石家庄行唐；河北石家庄高邑；河北石家庄深泽；河北石家庄鹿泉；河北石家庄；河北石家庄藁城；河北石家庄；河北_邯郸_武安；河北保定竞秀；河北保定', '[]', '[]', '抗日战争时期', '', '任伪清苑县长期间，推行保甲制度，强征粮款，协助日军建立伪政权，镇压抗日活动。；任伪保定县知事期间，为日军提供情报，组织伪警察抓捕抗日地下党员，强征劳工送往东北。；任伪保定市长期间，推行日伪统治政策，强征民夫，搜刮物资供日军使用。；日军占领高碑店后率先组织维持会，为日军征粮派款，提供情报，帮助日军建立伪政权。；投靠日军，任元氏县伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.041177', '2026-09-10 09:57:14.041177', '河北', '保定', '竞秀', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e5a8a41c66f40d58be465c8f20770b9', '金钩胡子', NULL, NULL, NULL, NULL, 'exact', 'exact', '岳阳', '[]', '[]', '抗日战争时期', '', '伪职：伪秘稽队长；罪行：水匪出身，手下百十号人枪。投靠费竹如后与日军接上头；费竹如任维持会长后，其任秘稽队长', '[]', '2026-09-10 09:57:14.072393', '2026-09-10 09:57:14.072393', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
