INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3e68e527db5e46e2ba218842e23306be', '思鸿升', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南德宏芒市；云南德宏盈江；云南德宏陇川；云南昆明安宁；云南德宏陇川；云南德宏梁河；云南德宏芒市', '[]', '[]', '抗日战争时期', '', '在德宏地区组织伪军，配合日军扫荡抗日武装，参与维持会活动，为日军统治服务。；陇川土司思氏家族成员，日军占领期间曾参与维持会活动。；日军占领潞西（今芒市）后，思鸿升投敌，出任伪芒市安抚使，组织维持会，协助日军统治潞西地区，征派粮秣民夫。；日军侵入盈江后，思鸿升投敌，组织维持会，为日军征粮派款、修筑道路，并协助日军搜捕抗日志士。', '[]', '2026-09-10 09:57:13.980393', '2026-09-10 09:57:13.980393', '云南', '德宏', '梁河', NULL, NULL, NULL, NULL, '');
