INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ed14d54b30c4640b729fb37ebd21303', '郑绍玄', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头濠江；河南郑州中牟；广东汕头澄海；广东汕头潮阳；广东揭阳', '[]', '[]', '抗日战争时期', '', '协助日军实施经济统制，强制商户缴纳物资与款项，为日军采购军需，从中牟利。；在基层推行保甲制度，监视居民，举报抗日嫌疑，协助日军维持治安。；在普宁组织伪维持会，配合日军对揭阳、普宁交界地区的控制，征粮派款。；潮阳沦陷后组织维持会，为日军提供情报与物资，协助维持占领区秩序。；潮阳沦陷后组织伪维持会，协助日军建立基层伪政权。', '[]', '2026-09-10 09:57:14.027730', '2026-09-10 09:57:14.027730', '广东', '揭阳', '潮阳', NULL, NULL, NULL, NULL, '');
