INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ee99a4e95344757b9866966bc3c11a6', '张致和', NULL, NULL, NULL, NULL, 'exact', 'exact', '磁县', '[]', '[]', '抗日战争时期', '', '伪职：伪磁县警备大队长；伪军主力，驻守磁县城、观台、彭城，多次扫荡西部山区。；结局：磁县解放被俘，公审枪决；伪职：伪磁县警备大队长；伪军主力头目，驻守磁县城、观台、彭城，多次配合日军扫荡磁县西部山区。；结局：磁县解放被俘，公审枪决', '[]', '2026-09-10 09:57:14.073014', '2026-09-10 09:57:14.073014', '河北', '邯郸', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3ef3952a37444621ad8cfe2b401f4fa4', '赵全璧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西大同云冈；黑龙江大庆大同；山西_大同_浑源；山西临汾大宁；山西朔州平鲁；山西大同阳高；黑龙江大庆大同；山西；山西朔州朔州经开区；山西忻州宁武', '[]', '[]', '抗日战争时期', '', '任伪大同警务处处长，指挥伪警察协助日军搜捕抗日分子，实施“清乡”行动，残害百姓。；主管伪警宪特，在左云、大同地区建立情报网，多次组织搜捕地下党员，破坏抗日组织，执行日军“三光”政策。；任伪警察局长，协助日军搜捕地下党员和抗日群众，破坏抗日组织，参与‘清乡’行动。；在日军扶植下管理大同及周边县政，强迫农民种植鸦片，为日军提供军费，并组织汉奸武装协助“扫荡”。；日军占领初期组织维持会，为日军筹集物资，强拉民夫，协助建立伪政权。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018858', '2026-09-10 09:57:14.018858', '山西', '临汾', '大宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3efc2c24bdda41b8bfc5bd1dd5ad37f2', '张善琨', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江吴兴', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪中华电影联合公司总经理，炮制亲日宣传影片。结局：抗战胜利逃往香港，未受审判', '[]', '2026-09-10 09:57:14.070438', '2026-09-10 09:57:14.070438', '浙江', '湖州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f086e5abf6d4b609d4308c195500476', '张宪云', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁邹城', '[]', '[]', '抗日战争时期', '', '率伪警备队配合日军扫荡邹东抗日根据地，抓捕抗日人员，勒索百姓。', '[]', '2026-09-10 09:57:14.015735', '2026-09-10 09:57:14.015735', '山东', '济宁', '邹城', NULL, NULL, NULL, NULL, '');
