INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f1c6f6b5a66479e8902a39b1f2ae171', '刘佩臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊霸州；河北廊坊；河北沧州任丘；河北沧州黄骅；河北；河北沧州河间；河北廊坊大厂', '[]', '[]', '抗日战争时期', '', '任伪县知事期间，推行日伪保甲制度，强征粮食，抓捕抗日群众，为日军提供情报。；率伪军多次袭击文安、大城交界抗日武装，烧毁村庄，掠夺财物，制造多起惨案。；率伪治安军在廊坊、霸州一带驻防，参与日军“清剿”行动，烧杀抢掠，制造多起惨案。；在任丘县推行日伪统治，强征粮食，镇压抗日群众，协助日军建立保甲制度，抓捕抗日军民送交日军宪兵队。；任伪任丘县知事期间，积极推行日伪政权，协助日军清乡、征粮、抓捕抗日人员，破坏抗日组织。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042458', '2026-09-10 09:57:14.042458', '河北', '廊坊', '大厂', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f1ce938bce2466f86ebaa024a4b5341', '陈省三', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博桓台；山东淄博周村；山东淄博淄川；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '周村沦陷后任伪商会会长，为日军筹款筹粮，协助控制周村商业，配合日军经济掠夺，周村紧邻桓台。；组织新民会，进行亲日宣传，协助日军推行治安强化运动。', '[]', '2026-09-10 09:57:14.015957', '2026-09-10 09:57:14.015957', '山东', '淄博', '桓台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f24cecb127f46dfb79a49ab9874c68b', '周景颐', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州铜山', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校教授日语和“中日亲善”内容，篡改历史教材，为日军培养顺民。', '[]', '2026-09-10 09:57:14.035328', '2026-09-10 09:57:14.035328', '江苏', '徐州', '铜山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f29c4b783e44341b17aff963d154c10', '王疤眼', NULL, NULL, NULL, NULL, 'exact', 'exact', '蔡里（今淮北杜集）淮北文明网', '[]', '[]', '抗日战争时期', '', '伪职：伪伪军大队长；罪行：原旧军官，投敌任伪军大队长；其子充当日军翻译，父子作恶，抓捕残害爱国人士，鱼肉乡里。；结局：1944 年中秋，被地下锄奸小组在婚宴上击毙淮北文明网。', '[]', '2026-09-10 09:57:14.087709', '2026-09-10 09:57:14.087709', '安徽', '淮北', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f2ca26ddb6d4fd3a76993fdb59136a7', '聂光耀', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南常德', '[]', '[]', '抗日战争时期', '', '在日军占领常德期间出任伪警察局长，带领伪警察配合日军搜捕抗日人员、维持治安。', '[]', '2026-09-10 09:57:14.058190', '2026-09-10 09:57:14.058190', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f2eaca855c247f1bb542a6166a4ca93', '李振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东德州平原；山东济南商河；河北保定满城；河北邯郸邯郸经开区；河北；河北保定望都；河北保定涞源；河北保定安国；河北保定易县；内蒙古锡林郭勒多伦', '[]', '[]', '抗日战争时期', '', '组织伪保安队，配合日军扫荡安国抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众。；率伪警察配合日军“清乡”，逮捕抗日群众，严刑逼供，并参与屠杀狼牙山地区村民。；在望都县城内建立特务情报网，侦捕抗日地下党员，严刑逼供，导致多名抗日人员牺牲或被捕。；任伪警察所长期间，指挥伪警搜捕抗日家属，破坏交通线，多次带队突袭村庄，抢劫财物，并参与杀害被俘的八路军伤员。；负责在满城推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.992467', '2026-09-10 09:57:13.992467', '山东', '德州', '平原', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f3c955150af4774b3178839349f339d', '姜荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '江都黄珏桥', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪黄珏镇镇长，我方争取对象，后期出卖区长戴锡九情报。。结局：被我方控制改造，从宽处理', '[]', '2026-09-10 09:57:14.069424', '2026-09-10 09:57:14.069424', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f4c5cbbf0a94b45a9fa6d9c3f9a6974', '李景明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北；北京延庆；河北唐山；河北秦皇岛', '[]', '[]', '抗日战争时期', '', '在延庆县任伪县长期间，强征民夫修筑炮楼和公路，组织伪自卫团，配合日军对南山（平北根据地）进行“蚕食”。；在丰润县任伪职期间，积极推行日伪“治安强化运动”，组织伪警察和保甲武装，配合日军扫荡抗日根据地，残害抗日军民。；推行奴化教育，在唐山、汉沽等地学校强制教授日语，删改历史教材，灌输“中日亲善”思想。；推行奴化教育，在唐山等地学校强制灌输亲日思想。；推行奴化教育，在秦皇岛、北戴河等地学校强制灌输亲日思想，破坏中国教育体系。', '[]', '2026-09-10 09:57:13.993952', '2026-09-10 09:57:13.993952', '北京', '延庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3f4d9a3704554629828fafa7b3250e75', '方金土', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州柯城', '[]', '[]', '抗日战争时期', '', '充当日军密探，多次告密导致抗日游击队员被捕牺牲，民愤极大。', '[]', '2026-09-10 09:57:14.052326', '2026-09-10 09:57:14.052326', '浙江', '衢州', '柯城', NULL, NULL, NULL, NULL, '');
