INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3fa0b9096c3a426fad259e420d3ee254', '张浩', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西鹰潭余江；江西鹰潭', '[]', '[]', '抗日战争时期', '', '鹰潭沦陷后参与组织维持会，为日军筹集物资、拉夫，并协助日军宣抚队进行奴化宣传。', '[]', '2026-09-10 09:57:14.040637', '2026-09-10 09:57:14.040637', '江西', '鹰潭', '余江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('3fa2408bb56a422ca31ffa4f52824896', '张君嵩', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州；广西贵港平南；广西贵港；广西柳州柳江；云南普洱西；广西梧州苍梧；广西梧州；广西北海；广西北海合浦；广西崇左龙州；广西崇左；广西桂林恭城；广西桂林；广西柳州城中；广西柳州；广西柳州柳城；广西柳州', '[]', '[]', '抗日战争时期', '', '日军侵占梧州后出面组织维持会，协助日军征粮、拉夫、维持治安。；1944年日军侵占梧州后，出面组织伪梧州维持会，协助日军维持地方秩序、征发物资。；1944年日军侵占梧州后，出面组织伪维持会，协助日军征粮、拉夫、维持治安。；据部分地方文史资料提及，1944年日军入侵柳州期间，有地方士绅组织伪维持会，张君嵩可能为其中之一，但可靠记载有限。；投靠日伪后负责广西伪警察系统，在崇左、龙州等地建立伪警察所和保甲联防，镇压抗日群众，搜捕抗日志士。；日军侵占北海期间出面组织伪维持会，协助日军征粮、拉夫、维持治安，镇压抗日群众。；在汪伪广西省政权中任职，负责警务与治安，配合日军镇压抗日力量。；日军侵占合浦期间出面组织伪维持会，协助日军征粮、拉夫、维持地方秩序，为日军侵略服务。；1944年日军侵占柳州后，出面组织伪柳州维持会，协助日军维持地方秩序、征派物资。；在广东附逆，活动范围与广西东南部接近，但与贵港、平南无直接关联。；1944年日军发动豫湘桂战役占领桂林后，出面组织伪桂林维持会，协助日军维持占领秩序、征发民夫与物资。；1944年日军侵占桂林期间，出面组织伪维持会，协助日军维持地方秩序、征发物资。', '[]', '2026-09-10 09:57:14.030416', '2026-09-10 09:57:14.030416', '广西', '北海', '合浦', NULL, NULL, NULL, NULL, '');
