INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('424a701ed5e149d0a6fcf9228cb07328', '何绍周', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；云南昆明呈贡；贵州贵阳修文', '[]', '[]', '抗日战争时期', '', '国民党军将领，抗战时期参加远征军入缅作战，无汉奸记载。；在日军占领区参与奴化宣传，编写亲日教材，协助日军推行日语教育。；在酉阳组织伪新民会，进行亲日宣传，发展伪会员，配合日伪进行思想控制。', '[]', '2026-09-10 09:57:13.985255', '2026-09-10 09:57:13.985255', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42526f7422df46619b2aaee1c9fd7eb9', '于振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北沧州黄骅；河北；河北唐山滦州；河北唐山', '[]', '[]', '抗日战争时期', '', '在唐山丰润一带活动，协助日军抓捕抗日志士，破坏地下党组织。；建立情报网，多次侦破抗日地下组织，导致数十名抗日志士被捕牺牲。', '[]', '2026-09-10 09:57:14.041761', '2026-09-10 09:57:14.041761', '河北', '唐山', '滦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('425fb75e219442b49bd01be6cbc61823', '额勒春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；吉林松原前郭尔罗斯；内蒙古通辽；北京大兴；内蒙古_通辽；达斡尔族；内蒙古兴安扎赉特旗；内蒙古呼伦贝尔陈巴尔虎旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[\"达斡尔族\"]', '[]', '抗日战争时期', '', '伪职：第一任伪兴安东省省长（扎兰屯）；接受伪满任命，组建兴安东省公署，推行保甲、奴化教育，配合日本开拓团进入布特哈地区。；结局：1941 离职，战后关押判刑抖音百科；伪满洲国兴安东省（部分辖区与兴安盟接壤）省长，虽主要活动于扎兰屯一带，但曾参与协调兴安、阿尔山地区的日伪军事行动。；在呼伦贝尔地区主持伪警务，协助日军搜捕抗日分子，参与“清乡”行动，迫害达斡尔、鄂温克等各族群众。；作为蒙古族上层投靠日本，任伪兴安北省省长，配合日军在呼伦贝尔地区实施“治安肃正”，迫害抗日志士，强制推行奴化教育。；在呼伦贝尔东部地区推行伪满统治，协助日军清剿抗联部队，征收粮草；曾任伪满洲国兴安北省省长，在呼伦贝尔地区推行日伪殖民统治，协助日本关东军镇压当地抗日力量。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.987667', '2026-09-10 09:57:13.987667', '吉林', '松原', '前郭尔罗斯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('426d73fb9a294e7faa99b35c386a9875', '刘郁文', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波象山；安徽芜湖；浙江杭州西湖；浙江杭州；江苏南京浦口；江苏镇江', '[]', '[]', '抗日战争时期', '', '利用司法权力迫害抗日群众，判处抗日志士重刑，为日伪统治提供法律镇压工具。；为日军征收各种附加税，强征“慰劳金”，中饱私囊，导致芜湖商户破产。；在杭州各中学推行“中日共荣”教育，强迫学生参拜日本神社。；协助日军在象山强征劳工，修建军事工事，虐待劳工致死。；在浦口地区组织伪保安团，协助日军巡逻和清乡。', '[]', '2026-09-10 09:57:14.009756', '2026-09-10 09:57:14.009756', '江苏', '南京', '浦口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42762c542e8d419e831334bdc9a328ea', '高云龙', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州铜山；安徽淮南潘集；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '负责淮南煤矿（含潘集矿区）的劳工管理，克扣矿工口粮，向日军举报抗日工人，导致多名矿工被处决。；任伪第一区区长，协助日军建立区乡伪政权，强征民夫修筑公路和碉堡，报告抗日武装动向。', '[]', '2026-09-10 09:57:14.009061', '2026-09-10 09:57:14.009061', '安徽', '淮南', '潘集', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('427db381eaf24009a08fbcf8d5119198', '于惠风', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪隆化县县长；推行保甲制度，强征劳工粮草，配合讨伐队扫荡。；结局：战后判处徒刑', '[]', '2026-09-10 09:57:14.081749', '2026-09-10 09:57:14.081749', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4282a6b885e64ac98c1f5553a793cb59', '王锡符', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京门头沟；河南三门峡；青海黄南河南；河南平顶山；青海黄南河南；河南南阳方城；河南南阳；北京；青海黄南河南；北京顺义', '[]', '[]', '抗日战争时期', '', '率伪军配合日军扫荡抗日根据地，抓捕抗日军民，参与制造多起惨案。；率伪警在门头沟斋堂、清水一带搜捕抗日干部，破坏地下党组织。；配合日军“治安强化运动”，在顺义各乡建立伪自卫团，抓捕抗日干部。；率伪军多次配合日军围剿八路军游击队，在顺义西部村庄烧杀抢掠，抓捕并杀害抗日干部。', '[]', '2026-09-10 09:57:13.995255', '2026-09-10 09:57:13.995255', '北京', '门头沟', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42927c1439564887ab7296ca57a26a0d', '尹宝山', NULL, NULL, NULL, NULL, 'exact', 'exact', '热河林西（今内蒙古赤峰）', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪蒙古军第二师师长，随李守信投敌，驻防商都。结局：1937 年作战失利被解职，抗战后被捕判刑', '[]', '2026-09-10 09:57:14.083053', '2026-09-10 09:57:14.083053', '内蒙古', '赤峰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42aa1a85fe404607a247d40b44cc0676', '吴海清', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳枣阳；辽宁阜新太平', '[]', '[]', '抗日战争时期', '', '在襄阳太平店一带为日军征粮拉夫，协助建立伪保甲制度。', '[]', '2026-09-10 09:57:14.057234', '2026-09-10 09:57:14.057234', '湖北', '襄阳', '枣阳', NULL, NULL, NULL, NULL, '');
