INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42d65e1ae7f74a27b1a90f1855091a30', '吴赞臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '遂平县；确山县', '[]', '[]', '抗日战争时期', '', '伪职：国民党遂平县党部书记长（投敌）；罪行：见上（确山县吴赞臣）；结局：见上；伪职：国民党确山县党部代理书记长（投敌）；罪行：原为国民党遂平县党部书记长、确山县党部代理书记长。直接参与血洗竹沟的行动（“确山惨案”），致使我党数百名伤病员及家属惨遭杀害。豫南沦陷后投靠日伪；结局：1944年日军占领遂平后，被嵖岈山抗日第四中队秘密处死', '[]', '2026-09-10 09:57:14.069223', '2026-09-10 09:57:14.069223', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42eaf4f2456d4bd8bc8f12bc49c4051c', '刘兴', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江黑河逊克；三肇全域', '[]', '[]', '抗日战争时期', '', '伪职：伪满刘兴讨伐队头目；罪行：伪军讨伐队司令，配合日军围剿抗联十二支队，参与三肇肃正，四处搜捕、屠杀抗日军民。；结局：伪满后期病死。', '[]', '2026-09-10 09:57:14.066853', '2026-09-10 09:57:14.066853', '黑龙江', '黑河', '逊克', NULL, NULL, NULL, NULL, '');
