INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('42fbed6a38cf4092996b6c6d993fff64', '伪吉水县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西吉安吉水', '[]', '[]', '抗日战争时期', '', '吉水沦陷区域伪维持会配合日军控制赣江航道。', '[]', '2026-09-10 09:57:14.038608', '2026-09-10 09:57:14.038608', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
