INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4336296a80e94c5baed879257a552dbe', '吴友三', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西宜春袁州；江西宜春；江西九江武宁；江西南昌；福建泉州金门；福建泉州；江西南昌红谷滩；江西南昌；江西宜春高安；福建南平建瓯；江西鹰潭余江；福建_宁德_屏南；江西抚州南城；江西宜春上高；辽宁沈阳大东；江西吉安万安；江西南昌青山湖；江西南昌；江西抚州资溪；江西抚州金溪；江西南昌安义；江西南昌；江西上饶玉山；江西上饶鄱阳；江西南昌；江西抚州金溪；江西吉安遂川；江西吉安；江西九江彭泽；福建泉州鲤城；福建泉州晋江；福建漳州东山；黑龙江鹤岗东山；福建南平政和；江西九江修水；江西九江；福建漳州芗城；辽宁沈阳大东；云南普洱西；江西南昌东湖；江西南昌；江西上饶万年；辽宁沈阳大东；福建漳州云霄', '[]', '[]', '抗日战争时期', '', '在九江沦陷期间，以商会会长身份为日军筹款筹物，协助日军控制当地经济。；在金溪县（邻近资溪）组织维持会，为日军提供粮草，并参与清乡活动。；在日占区推行奴化教育，强制学校使用日伪教材，组织师生参加“庆祝日军胜利”等活动。；晋江沦陷区附逆，出任伪维持会会长，为日军搜集情报、征粮派款，压迫当地民众。；在高安推行日语教育，篡改历史教材，协助日军进行文化侵略。；据地方史料零星记载，东山沦陷期间曾有维持会组织，吴友三可能为负责人之一，协助日军征调民夫、物资，但具体事迹记载较少。；在万安推行奴化教育，协助日伪控制学校，灌输亲日思想。；在宜春日占区主办伪报纸和广播，散布亲日言论，诋毁抗日力量，为日军粉饰侵略。；在余江沦陷期间投靠日军，充任伪警察头目，带领伪警配合日军搜捕抗日人员、催征捐税。；在伪江西省政府任职期间，推行日军殖民统治政策，协助征收赋税、征集劳工，宣传“中日亲善”。；南昌沦陷后组织伪维持会，为日军征粮、派款、拉夫，协助日军维持南昌及周边地区治安。；率伪军配合日军扫荡南昌周边抗日武装，捕杀抗日群众。；率伪保安队配合日军在南昌、进贤交界地区清乡，抓捕抗日军民，抢掠民财。；在上饶推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”。；在沦陷区推行奴化教育，篡改教材，强迫学生学日语，宣传“大东亚共荣”。；在新建县及南昌近郊组织维持会，为日军提供情报、向导，征发民夫修筑工事，参与搜捕抗日游击队员。；在南城乡村推行保甲制度，监视村民言行，向日军密报抗日分子及游击队活动。；在南昌地区组织维持会，为日军征粮、拉夫，协助建立伪政权基层组织。；在伪福建省政府中负责财政，为日军筹集军费，推行伪币，掠夺福建物资，配合日军经济封锁。；惠安沿海附逆头目，组织伪自卫团协助日军封锁海岸，阻止抗日物资进入泉州内陆。；云霄沦陷期间出任伪维持会会长，为日军筹粮、派款，维持地方伪政权，直接活动于云霄地区。；福建建瓯人，建瓯沦陷期间任伪维持会会长，为日军征粮征夫，协助镇压抗日分子，推行亲日教育。；在南昌近郊新建县组织伪维持会，为日军征夫征粮。；在南昌西郊新建地区组织维持会，为日军带路、征夫、征粮，协助建立伪基层政权。；在吉安沦陷区推行奴化教育，篡改教材，向学生灌输亲日思想。；在宜春推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，影响上高部分学校。；在漳州芗城一带协助日军宣传“大东亚共荣圈”，拉拢地方商户为日军筹款。；日军侵占玉山后投敌，率地方武装改编为伪保安队，配合日军下乡扫荡、搜捕抗日游击人员。；率伪保安队配合日军扫荡彭泽及周边抗日根据地，捕杀抗日军民。；在江西日占区参与伪政权运作，协助日军推行治安强化运动，督导南昌一带伪行政与征敛事务。；政和人，抗战期间在政和组织伪维持会并任会长，协助日军及伪政权维持地方统治，征发物资、劳工，推行奴化教育。', '[]', '2026-09-10 09:57:14.037519', '2026-09-10 09:57:14.037519', '江西', '上饶', '万年', NULL, NULL, NULL, NULL, '');
