INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43699d09ebd24a25a1eb905c054c005d', '王允卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城茌平；山东聊城；黑龙江大庆让胡路；黑龙江齐齐哈尔；河北承德；吉林通化；吉林_延边_延吉', '[]', '[]', '抗日战争时期', '', '在承德任伪热河省长期间，推行经济统制与奴化教育，协助日军围剿抗日武装，镇压民众反抗。；伪满驻华北代表，与山东聊城地区伪政权有联系。；在通化、白山地区推行奴化教育，篡改历史教材，培养亲日伪职人员。；在伪间岛省省长任内，执行日本指令，征发劳工、粮食，镇压延边抗日群众。；伪满黑龙江省实业厅官员，参与对黑龙江地区包括大庆一带的经济掠夺和物资统制。', '[]', '2026-09-10 09:57:13.998373', '2026-09-10 09:57:13.998373', '山东', '聊城', '茌平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('437c33b133344236bf425a52fbac4818', '金日成', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边延吉', '[]', '[]', '抗日战争时期', '', '伪满档案中记载的同名亲日分子，在延边地区协和会任职，协助日军进行民众动员。', '[]', '2026-09-10 09:57:13.998494', '2026-09-10 09:57:13.998494', '吉林', '延边', '延吉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('437d27dc2a394f588ed586ca8ac10bb9', '赵筱三', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南洛阳；河南许昌鄢陵；河南许昌；河南焦作武陟；河南洛阳栾川；河南洛阳；河南郑州；河南驻马店平舆；河南驻马店；河南周口太康；河北邢台沙河；河南洛阳涧西；河南洛阳；河南南阳；河南郑州新郑；山西阳泉城区；河南郑州；河南商丘；陕西西安灞桥；黑龙江牡丹江西安；河南驻马店确山；河南三门峡三门峡经开区；河南平顶山平顶山示范；河南平顶山；河南平顶山汝州；河南焦作山阳；山西阳泉矿区；河南三门峡；河南开封；河南周口西华；河南漯河；河南平顶山；河南南阳；山西阳泉城区；河南焦作孟州；河南焦作；河南安阳', '[]', '[]', '抗日战争时期', '', '1944年日军占领平顶山地区后，出面组织维持会，为日军征粮征夫，维持伪秩序，协助日军控制当地煤矿与交通线。；1944年日军侵占平顶山地区后，出面组织维持会，为日军筹集粮草、拉夫派款，协助日军维持地方治安，压迫当地民众。；郑州本地商人，日军占领郑州后出面组织维持会，任伪郑县县长，协助日军征粮、征夫，镇压抗日活动，势力范围包括荥阳周边。；在洛阳沦陷期间掌管伪警察，配合日军搜捕抗日人员、管制居民，活动涉及洛阳及新安交界地区。；1944年日军侵占临汝（今汝州）后，出面组织维持会并任伪县长，协助日军建立伪政权、征发物资、镇压抗日活动，是汝州本地直接附逆的代表人物。；在开封组织维持会，为日军筹办物资、招募劳工，协助建立伪政权。；1944年日军占领平顶山地区后，出面组织维持会，为日军筹集物资、招募劳工，协助日军控制当地煤矿和交通线。；漯河本地商人，1944年日军占领漯河后出面组织维持会，为日军筹集物资、招募劳工，协助维持占领区秩序。；抗战期间投敌，任伪河南省教育厅厅长，推行奴化教育，在南阳、方城等地设立伪学校，灌输亲日思想。；1944年日军占领许昌后，出面组织维持会，后任伪许昌县县长，为日军筹粮筹款、搜集情报，镇压抗日群众。；在郑州沦陷期间担任伪警察头目，协助日军搜捕抗日人员、管控户籍、镇压民众反抗，是郑州本地伪警系统的代表人物。；控制安阳商业，为日军采购军需物资，强制商户“献金献物”，配合经济封锁。；掌管商丘伪警察系统，搜捕抗日人士，监控民众，配合日军维持占领区治安。；在伪豫北道任职期间，参与组建伪警察队伍，配合日军在焦作、孟县等地清乡、搜捕抗日人员，是豫北伪警系统的重要人物。；在伪河南省会开封及郑州等地掌管伪警察系统，镇压抗日活动，搜捕抗日人员，推行特务统治。；商丘地方商人，抗战后投敌，任伪商丘县维持会会长，后任伪豫东道尹公署顾问，协助日军在豫东各县包括周口、扶沟一带推行伪政。；南阳本地士绅，日军占领南阳期间出面组织维持会，为日军筹粮、派夫、维持治安，协助伪政权控制南阳城区。；1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮筹款、维持地方秩序，协助日军统治南阳地区。；南阳本地人，日军侵占南阳期间组织维持会，为日军筹粮、派夫、搜集情报，协助日军控制南阳城区。；1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮筹款、维持秩序，协助日军控制南阳城区。；南阳本地人，日军侵占南阳后组织维持会，为日军筹粮筹款，协助建立伪基层政权，镇压抗日群众。；河南南阳人，抗战期间组织伪南阳维持会，任会长，协助日军维持南阳地区治安，推行伪化统治。；南阳本地人，日军侵占南阳后出面组织维持会，为日军筹粮、派夫、搜集情报，协助建立伪政权。；1945年日军侵占南阳期间，出面组织维持会，为日军筹粮筹款，维持地方秩序，协助日军统治南阳城区。；南阳地区维持会头目，1945年日军侵占南阳时出面组织维持会，为日军筹粮、派夫，协助维持地方治安。；1944年5月洛阳沦陷后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征发物资、镇压抗日活动。；确山本地人，日军侵占确山期间出面组织维持会，为日军征粮、派夫、搜集情报，协助日军控制确山及周边地区。；在洛阳沦陷期间出面组织伪商会，为日军筹款、摊派物资，协助日军控制洛阳商业与经济命脉。；驻马店本地汉奸，日军占领驻马店后组织维持会，为日军筹粮筹款、搜集情报，协助日军控制驻马店及周边平舆等县。；在焦作煤矿区组织维持会，为日军强征矿工、催缴捐税，压迫当地民众。；在陕县组织伪保安团，配合日军扫荡抗日武装，残害当地民众。；在西安地区组织维持会，协助日军维持占领区秩序（注：西安未沦陷，此条为传闻或未证实，需谨慎）。；郑州沦陷后组织伪维持会，协助日军维持郑州城区治安，征派粮款、劳工，为日军提供情报，是郑州本地直接附逆的代表人物之一。；日军侵占郑州后，出面组织伪维持会，协助日军维持地方秩序、征发物资。；郑州沦陷后出面组织伪维持会，协助日军维持郑州城区秩序，为日军筹粮、派夫、征收物资，是郑州本地直接附逆的伪政权头目之一。；郑州沦陷后出面组织伪维持会，协助日军维持郑州城区秩序、征发物资、登记户口，是郑州本地直接附逆的伪政权头目之一。；西华县地方士绅，日军侵占西华后出面组织伪维持会，任会长，协助日军维持地方秩序、征派粮款，后伪维持会改组为伪县公署。；在武陟县为日军维持治安，搜捕抗日人员，协助日军控制地方。；周口沦陷后组织维持会，为日军筹粮筹款、维持地方秩序，协助日伪控制周口及沙河沿线。', '[]', '2026-09-10 09:57:14.045539', '2026-09-10 09:57:14.045539', '河南', '三门峡', '三门峡经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4380c9e9859f4154a7162ffdf6ce6aa7', '黄标', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；湖北潜江；洪湖峰口镇；湖北荆州', '[]', '[]', '抗日战争时期', '', '伪职：伪峰口镇维持会长、伪自警团长、伪清剿大队长；罪行：洪湖峰口镇人。表面为日伪服务，实际系中共特别党员，受李先念指派打入日寇内部做情报工作；结局：抗战胜利后被误解为汉奸，后获平反', '[]', '2026-09-10 09:57:14.056056', '2026-09-10 09:57:14.056056', '湖北', '宜昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4384f0d7bf054358afe74dad7ed91e8b', '张治公', NULL, NULL, NULL, NULL, 'exact', 'exact', '伊川县；河南洛阳', '[]', '[]', '抗日战争时期', '', '伪职：伪自由县（今伊川县）县长、伪白沙县政府县长；罪行：伊川人，出身绿林。1941年任伪自由县县长；1944年洛阳沦陷后在白沙建立日伪县政府任伪县长，任期约5-8天。任内为日军派款派粮；结局：1951年3月18日经洛阳专署批准，以反革命罪在偃师县处决', '[]', '2026-09-10 09:57:14.048432', '2026-09-10 09:57:14.048432', '河南', '洛阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('439cc9f21569448f9cef5efb77269717', '林文龙', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建三明；福建南平建瓯；福建南平', '[]', '[]', '抗日战争时期', '', '福建籍汉奸，在伪福建省政府中主管警务，建立伪警察体系，配合日军在福建各地搜捕抗日人士，其警务网络覆盖南平、建瓯等闽北地区。；三明本地人，抗战期间投靠日军，组织伪三明维持会，为日军搜集情报、征调民夫、协助伪化统治。；在三明地区担任伪警察局长，协助日军维持治安，镇压抗日分子，推行保甲连坐制度。', '[]', '2026-09-10 09:57:14.060335', '2026-09-10 09:57:14.060335', '福建', '三明', '永安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('439d101b86fb43d9845748a8a27063c5', '罗绍基', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州', '[]', '[]', '抗日战争时期', '', '投敌后任伪梧州警察局长，协助日军搜捕抗日分子，镇压民众反抗。', '[]', '2026-09-10 09:57:14.033055', '2026-09-10 09:57:14.033055', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43a1d7d2fe7943cb81081eda33561820', '周玉堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城大丰；江苏盐城；江苏盐城盐城经开区；江苏盐城；江苏盐城亭湖', '[]', '[]', '抗日战争时期', '', '率伪军配合日军在亭湖地区“扫荡”，烧毁村庄，抢劫民财，杀害抗日军属。；日军占领盐城初期组织维持会，协助日军建立统治秩序，强征民夫修筑工事。；充当日军特务，在大丰、盐城一带刺探新四军情报，抓捕抗日志士，手段残忍。', '[]', '2026-09-10 09:57:14.036400', '2026-09-10 09:57:14.036400', '江苏', '盐城', '亭湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43a7a21c99c2451a9e09f543d2b74f97', '孙文远', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北十堰郧西', '[]', '[]', '抗日战争时期', '', '湖北郧西人，抗战期间投敌，任伪郧西经济科科长，协助日军搜刮物资，压榨民众。', '[]', '2026-09-10 09:57:14.054839', '2026-09-10 09:57:14.054839', '湖北', '十堰', '郧西', NULL, NULL, NULL, NULL, '');
