INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43ab6d2107764eefa9b73fcbd17b7532', '梁朝杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东云浮云安；广东云浮；广东茂名；广东韶关始兴；广东惠州；辽宁大连中山', '[]', '[]', '抗日战争时期', '', '参与伪广东军事与绥靖事务，指挥伪军配合日军在广东各地包括东江惠州地区进行清乡与扫荡。；在广东沦陷区进行亲日宣传，为日军殖民统治制造舆论。；汪伪广东省府民政负责人，主管伪政权基层保甲与维持会，直接推动茂名、电白等地伪基层组织建设。；主持修建日伪据点、公路，为日军掠夺云浮矿产资源提供便利。；在中山县及邻近的珠海地区组织伪警察与伪军，配合日军清乡、扫荡抗日力量，镇压当地民众抗日活动。', '[]', '2026-09-10 09:57:14.025151', '2026-09-10 09:57:14.025151', '广东', '云浮', '云安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43b3adbf8b2e45b9ace078ab157ee0cd', '赵廷珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北秦皇岛海港；河北唐山滦州；河北唐山；黑龙江黑河北安', '[]', '[]', '抗日战争时期', '', '在玉田（邻近唐山）为日军提供情报，协助围剿抗日游击队。；在海港区抓捕抗日志士，为日军提供情报，参与镇压码头工人罢工。', '[]', '2026-09-10 09:57:14.041811', '2026-09-10 09:57:14.041811', '河北', '唐山', '滦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43b9488a926643cebbdd398dca922037', '阿齐兹医生', NULL, NULL, NULL, NULL, 'exact', 'exact', '新疆', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：跟随和加尼牙孜流亡上海，与日本陆军特务机关密切合作，为日方做新疆情报翻译，联络流亡的新疆分裂分子，策划渗透新疆。未返回新疆本土活动环球网。。结局：抗战胜利在上海被捕判刑', '[]', '2026-09-10 09:57:14.085222', '2026-09-10 09:57:14.085222', '新疆', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43be0746a08844b98dd19a08df1df454', '赵广礼', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北；吉林舒兰；吉林', '[]', '[]', '抗日战争时期', '', '在吉林、舒兰地区协助日军宪兵队审讯、拷打抗日军民，提供情报。；任伪兴隆县县长期间，积极推行日伪“治安肃正”政策，组织保甲制度，协助日军镇压抗日武装，强征劳工，掠夺资源。', '[]', '2026-09-10 09:57:14.000606', '2026-09-10 09:57:14.000606', '吉林', '舒兰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43c7be2800854985a240e3bea60b9aaa', '周海清', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆涪陵；辽宁沈阳大东；重庆忠县；重庆巫山；重庆长寿', '[]', '[]', '抗日战争时期', '', '主办伪报纸和广播，散布“大东亚共荣”言论，诋毁抗日力量。；统领巫山伪保安团，配合日军对三峡地区抗日武装进行围剿。；在忠县任职期间，为日军提供情报，镇压抗日活动。；担任保甲长期间，举报抗日家属，协助日军征发劳工，参与搜捕地下党员。', '[]', '2026-09-10 09:57:14.064001', '2026-09-10 09:57:14.064001', '重庆', '巫山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43cbe058b6914084ad3bc2f6b8aa53a9', '秦松亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽凤阳；蚌埠、临淮关', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪凤阳县县长，皖北伪地方核心人物。结局：1951 年蚌埠公审枪决；伪职：维持会骨干、伪凤阳县县长（蚌埠当时属凤阳县）；罪行：参与蚌埠早期维持会，后出任伪凤阳县长，推行保甲良民证，强征民夫修工事，迫害抗日群众。；结局：1951 年公审枪决。', '[]', '2026-09-10 09:57:14.078802', '2026-09-10 09:57:14.078802', '安徽', '滁州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e262875987435db7ecc6d5420ecdf8', '商震', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中', '[]', '[]', '抗日战争时期', '', '虽名义居北平，但参与策划晋中伪政权运作，协助日军推行“治安肃正”。', '[]', '2026-09-10 09:57:14.022175', '2026-09-10 09:57:14.022175', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e4988766624842996631e6ca5ca440', '史泽波', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西西安周至；云南普洱西', '[]', '[]', '抗日战争时期', '', '在山西伪军中任职，配合日军扫荡，其活动与陕西有间接关联。', '[]', '2026-09-10 09:57:14.064938', '2026-09-10 09:57:14.064938', '陕西', '西安', '周至', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e4cb7d173e490a86a21e8ca38541aa', '刘建义', NULL, NULL, NULL, NULL, 'exact', 'exact', '清丰县', '[]', '[]', '抗日战争时期', '', '伪职：清丰维持会会长；罪行：青帮头子，1938年2月日军二次占领清丰后出任维持会会长，专为日寇效力；结局：待考（四支队打击汉奸组织后下场）', '[]', '2026-09-10 09:57:14.075842', '2026-09-10 09:57:14.075842', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e5711a2cda41939c0307f9ab2915d4', '崔光汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '顺安镇及铜官山周边', '[]', '[]', '抗日战争时期', '', '伪职：顺安特务大队长（双料特务）；罪行：伪装进步骗取皖南行署参议员身份，公开叛变投敌；出卖地下党组织，抓捕杀害督导处主任陈益卿；勾结中统，组建特务武装；向日军告密直接酿成范家湾惨案，致使巫希权等 28 位新四军指战员牺牲。；结局：抗战胜利后肃奸捕获，判处死刑处决。', '[]', '2026-09-10 09:57:14.082802', '2026-09-10 09:57:14.082802', '安徽', '铜陵', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e59714abab4f969ff1ad747ce568a2', '刘文辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；陕西宝鸡凤县；云南普洱西；重庆江津；辽宁沈阳大东；四川成都彭州；四川成都；四川成都；重庆涪陵；河南郑州中牟；四川_成都_金牛；重庆巫溪', '[]', '[]', '抗日战争时期', '', '为日军采购军需物资，垄断当地盐、粮贸易，从中牟利并资助伪政权。；抗日战争期间曾率部投靠日伪，任伪军头目，在四川地区进行伪化活动。；在成都与伪政权保持联系，允许伪军过境，为日军提供西康物资，镇压抗日活动。；在重庆伪政权中任职，参与推行日伪政策，协助经济统制与物资征调。；川军将领，抗战期间在成都、邛崃地区与日伪势力合作，纵容部下投敌，协助日军维持地方治安。；虽名义上为西康省主席，但曾与日军暗中联络，允许日军特务在成都、彭县一带活动，未积极抗日。；在教育领域推行奴化教育，篡改教材，宣传所谓‘大东亚共荣圈’。；汪伪政权任命的陕西省伪职，试图在陕西建立伪政权，进行亲日宣传。', '[]', '2026-09-10 09:57:14.001810', '2026-09-10 09:57:14.001810', '四川', '成都', '彭州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43e6b729efd34a97a4a7720acea73bee', '李际春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊霸州；河北廊坊；重庆永川；湖南常德津；河北唐山乐亭；河北唐山滦南；河北承德承德高；河北秦皇岛山海关；河北秦皇岛；河北秦皇岛昌黎；河北秦皇岛抚宁；河北廊坊安次；河北廊坊大厂；河北廊坊；河北廊坊廊坊经开区；河北廊坊；河北秦皇岛；天津籍；北京顺义；辽宁_大连_旅顺口；河北唐山唐山高；河北唐山；辽宁朝阳北票；辽宁营口大石桥；河北唐山丰润；河北沧州沧州渤海；河北唐山唐山海港经开区；河北唐山；河北承德；河北沧州；天津武清；辽宁朝阳龙城；辽宁朝阳；辽宁葫芦岛兴城；辽宁葫芦岛；山东德州禹城；山东德州；天津宝坻；河北秦皇岛秦皇岛经开区；河北秦皇岛；河北唐山迁安；河北唐山；河北；吉林长春朝阳；天津河北；河北唐山迁西；河北唐山；河北唐山滦州；天津_蓟州；北京、天津、河北、辽宁；河北唐山玉田；河北唐山；河北廊坊；河北承德；河北唐山；河北唐山路北；辽宁鞍山海城；辽宁营口；陕西西安长安；辽宁沈阳；河北保定蠡县；北京通州；河北唐山；河北秦皇岛；河北唐山路南；河北唐山乐亭；天津宁河；河北唐山滦南；河北唐山；北京怀柔；河北廊坊三河；陕西榆林神木；湖南常德津；河北唐山丰南；河北唐山；河北唐山曹妃甸；河北唐山；河北廊坊；天津北辰；天津滨海；江苏盐城滨海；北京密云', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪宝坻维持会总头目，老牌汉奸；冀东事变时期勾结日军，组织伪军祸害京东各县。；结局：抗战胜利后逮捕，狱中病死；在密云一带强征壮丁，配合日军建立“无人区”，制造多起惨案。；在密云县推行日伪统治，强征粮税，协助日军建立保甲制度，迫害抗日军民。；参与殷汝耕伪冀东政权，在怀柔地区组织伪保安队，配合日军清乡，抓捕抗日军民。；日本顾问的帮凶，参与策划冀东独立，为日军提供情报，协助镇压反日运动。；在顺义及周边地区协助日军清乡、镇压抗日力量，组建伪军参与扫荡，残害百姓。……（共涉及78个地区的犯罪记录）；伪任职务：九一八后天津便衣队暴乱主谋，日本雇佣汉奸武装头目。结局：抗战胜利后逮捕，病死狱中', '[]', '2026-09-10 09:57:13.993552', '2026-09-10 09:57:13.993552', '北京', '密云', '开平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('43f0d2163ae645ec963e2d05a0dd2cb5', '刘子仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店遂平；河南驻马店；河南周口淮阳；河南周口；河南驻马店汝南；河南驻马店西平；河南开封兰考；安徽亳州涡阳；安徽亳州；河南周口西华；河南周口；安徽亳州蒙城；河南周口；河南商丘；山东聊城高唐；山东聊城；河南驻马店平舆；河南周口沈丘；山西阳泉城区；河南商丘虞城；河南商丘；安徽宿州萧县；安徽宿州泗县；河南商丘宁陵；河南商丘；山东聊城；河南商丘永城；河南商丘；河南商丘永城；河南商丘夏邑；安徽阜阳；河南商丘；河南驻马店确山；河南商丘柘城；河南商丘；山东聊城茌平；山东聊城；河南驻马店；永城；辽宁锦州太和；河南周口川汇；河南周口；河南商丘；安徽阜阳阜南；安徽阜阳；安徽阜阳颍上；安徽阜阳；安徽亳州；安徽宿州；安徽宿州萧县；河南商丘商丘经开区；河南商丘；河南开封；安徽宿州埇桥；安徽宿州砀山；河南周口周口经开区；河南周口；河南周口郸城；河南商丘', '[]', '[]', '抗日战争时期', '', '伪职：永城县伪县长；罪行：永城人，原名刘德良，后改刘俊良。1939年加入中国共产党，年末投降国民党，次年又叛变投日，任永城县伪县长。发行永城县流通券，面额五角至二十五元，发行总额达5000余万元，使百姓深受其害。勾结夏邑土顽祁炎勋、商丘土顽蒋心亮、蒋心纯及顽军骑三师，围剿八路军；结局：1951年以历史罪被判处死刑', '[]', '2026-09-10 09:57:14.004403', '2026-09-10 09:57:14.004403', '安徽', '亳州', '蒙城', NULL, NULL, NULL, NULL, '');
