INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4540077ca12f4e43a96633f3a696b506', '杨介轩', NULL, NULL, NULL, NULL, 'exact', 'exact', '宜昌城区/宜都', '[]', '[]', '抗日战争时期', '', '伪职：宜都江北维持总会会长、宜昌第四区公署区长；罪行：宜都白洋区小冲口人（今属枝江市），以烧窑为生。1940年日军侵占宜都江北后，先在石宝山设维持总会任会长，下辖顾家店、张家店等多个分会；后在小冲口设维持总会仍任会长，统辖云池、古老背等地分会。1941年1月任紫荆岭维持会联合会会长，同年8月任宜昌第四区公署区长。以通国军等借口抓捕敲诈民众；强行侵占郑旭轩等人田地，强买张刘氏等人土地79亩；参与紫荆岭酒精厂设立，低价强收粮食1.82万石提炼酒精；为日军强征物资并强征民夫4220名；1944年8月杀害国民党第六战区情报人员叶子明，指使章元干暗杀区长吴家修；结局：抗战胜利后被移交高等法院审判，后越狱潜逃；1951年被宜都县人民政府缉拿归案并处决', '[]', '2026-09-10 09:57:14.075192', '2026-09-10 09:57:14.075192', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4543314658e14d2cac65cce1310b6e72', '刘洛进', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '效忠日军，负责伪警察事务，搜捕抗日地下人员，严刑逼供，破坏中共地下交通线，为日军提供情报。', '[]', '2026-09-10 09:57:14.086459', '2026-09-10 09:57:14.086459', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('45463343914b4a64ad0452e4090afecb', '陈友云', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东潮州；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '在汕头基层推行保甲制度，监视居民，向日军举报抗日嫌疑人员，协助征发劳役。；日军侵占潮安后出面组织伪维持会，后任伪潮安县政府县长，协助日军征粮、征夫、推行伪化统治。；日军侵占潮安后出面组织伪维持会，后任伪潮安县政府县长，协助日军征粮、派款、维持治安，镇压抗日民众。；日军侵占潮安后出面组织伪维持会，后任伪潮安县政府县长，协助日军征粮、派款、维持治安，镇压抗日活动。', '[]', '2026-09-10 09:57:14.028112', '2026-09-10 09:57:14.028112', '广东', '汕头', '湘桥', NULL, NULL, NULL, NULL, '');
