INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('457c3dff7804485e998cadb1285c761c', '林文忠', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州长乐；福建宁德柘荣；福建福州马尾；福建福州闽侯；福建福州；福建南平光泽；福建福州闽侯；福建福州；福建南平；福建福州罗源；福建福州福清；福建福州', '[]', '[]', '抗日战争时期', '', '为日军筹款、摊派物资，协助经济掠夺。；闽侯沦陷期间组织维持会，为日军征粮征夫，压制抗日活动。；在闽侯组织维持会，配合日军在福州周边地区征粮征夫，协助建立伪保甲制度。；福清沦陷期间组织伪维持会，为日军征粮、拉夫、搜集情报，协助日军镇压当地抗日活动。；在福建沦陷区参与伪化教育，推行日语教学和亲日宣传，毒化青年思想。；长乐人，日军占领长乐期间组织伪维持会并任会长，为日军征集物资、维持地方秩序，配合伪政权统治。；马尾本地人，马尾沦陷期间任伪维持会会长，协助日军控制马尾港及闽江航运，为日军搜集情报、征发民夫。；福州台江人，日军占领福州期间任伪台江维持会会长，协助日军在台江地区征发物资、登记户口、推行伪化教育。；罗源人，1944年日军窜扰罗源时出面组织伪维持会，协助日军征粮拉夫，维持占领区秩序。；福州沦陷期间任伪福州维持会副会长，协助日军进行地方控制、物资征调和宣传安抚活动。；福建南平人，南平沦陷期间任伪维持会副会长，协助日军管理地方，征发民夫物资，参与奴化宣传。', '[]', '2026-09-10 09:57:14.060476', '2026-09-10 09:57:14.060476', '福建', '南平', '光泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4581ee6e514e4a58b312291b24a66b2c', '李德詅', NULL, NULL, NULL, NULL, 'exact', 'exact', '淄川县', '[]', '[]', '抗日战争时期', '', '伪职：王村“爱路青年团”情报搜集班侦察班长；罪行：1942年12月8日在淄川县第六区古城乡万家庄发现20名八路军便衣后向王村警务分所报告。随后带路对八路军进行三面包围，致3名八路军牺牲；结局：被八路军击中三枪当场毙命', '[]', '2026-09-10 09:57:14.068208', '2026-09-10 09:57:14.068208', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
