INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('466d42db601d4809a0cc63b4ff337d27', '郭宗汾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾隰县；山西临汾；山西晋城高平；山西；山西临汾；山西晋中；山西临汾吉县；山西临汾洪洞；山西临汾侯马；山西临汾', '[]', '[]', '抗日战争时期', '', '投日后任伪山西保安副司令，在临汾地区扩充伪军，配合日军“扫荡”，杀害抗日军民。；为日军出谋划策，参与策划对临汾抗日武装的围剿，并劝降部分国民党游击队。；率伪军驻防吉县一带，参与日军“铁滚扫荡”，烧毁村庄，掠夺物资，杀害抗日群众。；负责在临汾、隰县农村进行“宣抚”活动，诱骗民众领取“良民证”，并告发抗日分子，导致多人被捕。；率伪军在霍州、洪洞一带与日军协同作战，袭击八路军游击队。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018473', '2026-09-10 09:57:14.018473', '山西', '临汾', '侯马', NULL, NULL, NULL, NULL, '');
