INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('469120d0a6de463a9c29b093308540f9', '吴世昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_湖州_南浔；江苏无锡；江苏无锡宜兴', '[]', '[]', '抗日战争时期', '', '无锡人，指挥伪警协助日军巡逻、抓捕抗日嫌疑犯，参与镇压罢工和学生运动，充当日军耳目。；任伪警察局长期间，镇压抗日活动，抓捕地下党员并移交日军宪兵队。；日军占领宜兴初期，组织维持会，为日军带路、征粮，协助建立伪政权。', '[]', '2026-09-10 09:57:14.035569', '2026-09-10 09:57:14.035569', '江苏', '无锡', '宜兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46962ead09824622afd5a56d10594702', '龙希贞', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄峄城；峄县（涧头集）；山东台儿庄', '[\"龙瓜屋子\"]', '[]', '抗日战争时期', '伪军', '伪职：涧头集伪区长、台儿庄伪军头目；罪行：投敌后充当日军耳目，迫害原运河支队人员及抗属；来源：项目数据库；备注：运河支队叛徒，抗战后被处决；伪任职务：涧头集伪区长，运河支队叛徒，运河南岸伪军头目。结局：抗战胜利后公审处决；伪职：运河支队第三大队大队长（叛变前）→伪军头目；罪行：1903年生，台儿庄区马兰屯乡龙口村人。1940年春率部参加八路军，被编入运河支队第三大队任大队长。同年10月叛变投敌，充当汉奸。配合日军镇压抗日军民；结局：1945年9月7日被八路军生俘，10月15日被枪决', '[]', '2026-09-10 09:57:14.014566', '2026-09-10 09:57:14.014566', '山东', '枣庄', '峄城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46a163fd5b16419aad75de07c2c0430d', '朴仁洙', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边龙井', '[]', '[]', '抗日战争时期', '', '为日本宪兵队充当翻译，参与审讯和酷刑，直接导致多名抗联战士被杀害。', '[]', '2026-09-10 09:57:13.998789', '2026-09-10 09:57:13.998789', '吉林', '延边', '龙井', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46a7b324f65f4eee8f941dbbf3d5e152', '刘汝明', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州郑州航空港经开区；河南郑州；河南信阳；河南南阳；河南平顶山；河南开封；河南开封龙亭；河南开封；河南南阳桐柏；河南南阳；河南南阳南召；河南南阳；河南南阳；河南南阳西峡；河南南阳；河南驻马店上蔡；河南驻马店；河南南阳新野；河南南阳；河南南阳社旗；河南南阳；河南郑州二七；河南郑州；河南开封鼓楼；辽宁沈阳新民；河南南阳方城；河南南阳；河南驻马店；河南驻马店确山；河南驻马店；河南南阳镇平；河南南阳；河南驻马店驿城；河南驻马店；河南郑州上街；河南郑州；河南南阳南阳示范；河南南阳', '[]', '[]', '抗日战争时期', '', '抗战期间投靠日军，在豫东、郑州周边地区组织伪军，配合日军扫荡抗日武装，残害抗日群众。；在南阳地区组织伪清乡队，配合日军进行清乡，搜捕抗日人员，焚烧村庄，勒索民众。；1945年日军侵占南阳后，联络南阳各县维持会，成立伪联合会，为日军筹办粮秣、夫役，协助日军统治南阳地区。；原国民党军军官，1943年在河南投敌，所部伪军在南阳、方城、社旗一带活动，配合日军进攻抗日根据地。；原国民党将领，1943年前后在河南投敌，所部被编为伪军，在郑州、许昌一带配合日军行动。；统率伪军驻开封及周边地区，配合日军扫荡、清乡，镇压抗日武装。；原国民党军将领，1943年在河南投敌，任伪军师长，在南阳、内乡一带配合日军行动，后于1945年率部反正。；河南南阳人，抗战期间投靠日军，组织伪保安团，配合日军扫荡南阳周边抗日武装。；利用新民会组织训练亲日团体，配合日军进行思想控制与情报收集。；抗战后期在豫西投敌，组织伪军配合日军扫荡抗日根据地，其活动范围包括南阳西部及西峡周边地区。；抗战后期在豫南地区投敌，组织伪军配合日军在南阳、新野一带进行清乡、扫荡，是当地伪军头目之一。；投靠日军后组织伪军，在郑州及周边地区配合日军扫荡抗日武装，残害百姓。；原国民党军将领，1944年投敌，在豫南组织伪军，配合日军进攻南阳、方城一带的抗日武装。；在豫南地区组织伪军，配合日军进攻抗日根据地，活动范围包括南阳东部及驻马店一带。；抗战后期在豫南投敌，组织伪军配合日军扫荡确山、泌阳、新蔡一带抗日武装，残害抗日军民。；抗战后期在豫南投敌，组建伪军配合日军清乡，活动于驻马店、确山、西平一带，袭击抗日武装。；抗战后期在豫南收编地方武装，投靠日军，活动于驻马店、上蔡、汝南一带，配合日军进攻抗日武装。；原为国民党军下级军官，投敌后在南阳地区组建伪军，配合日军扫荡南阳、南召一带抗日根据地。；河南信阳人，抗战期间投敌，任伪豫南道尹，管辖信阳、南阳部分区域，组织维持会，为日军征粮征丁，配合日军扫荡豫南抗日根据地。；在豫南信阳一带组织伪政权，活动范围接近平顶山南部，配合日军扫荡豫南抗日武装。；在上蔡、驻马店一带率伪军配合日军行动，参与扫荡，镇压抗日群众。；河南南阳人，抗战期间任伪南阳商会会长，为日军筹集物资、资金，协助经济掠夺。；在豫南地区任伪道尹，管辖包括南阳部分区域，协助日军进行经济掠夺和治安维持。；原国民党军将领，投敌后任伪职，在豫鄂边区包括南阳一带活动，协助日军维持占领区。；张岚峰部伪军头目，率部驻防豫南驻马店、泌阳一带，配合日军扫荡抗日武装，抢掠民财。；组织伪自卫团协助日军守备开封，盘查行人，抓捕抗日嫌疑人员。；河南南阳人，抗战期间投敌，任伪南阳保安团团长，协助日军维持南阳地区治安，镇压抗日活动。；河南南阳人，抗战期间组织伪军，配合日军在南阳地区扫荡抗日武装。', '[]', '2026-09-10 09:57:14.046594', '2026-09-10 09:57:14.046594', '河南', '南阳', '南召', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46a850e460824bdf9ef2540f17e1aa93', '任水生', NULL, NULL, NULL, NULL, 'exact', 'exact', '郎溪钟桥', '[]', '[]', '抗日战争时期', '', '伪职：内奸惯匪；罪行：勾结伪军，密谋里应外合偷袭游击武装，企图暗杀乡干部，出卖游击区情报。；结局：游击连抓获就地枪毙。', '[]', '2026-09-10 09:57:14.075062', '2026-09-10 09:57:14.075062', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46b2dc5bb6b648c6bfd0e2963a444435', '韩姓汉奸', NULL, NULL, NULL, NULL, 'exact', 'exact', '监利县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（后反正）；罪行：监利周老嘴一带汉奸，被新四军巡逻战士抓获；结局：经政工部门思想改造后主动投诚，深夜操日语骗开日军据点大门，协助34团全歼日军四百余人', '[]', '2026-09-10 09:57:14.075039', '2026-09-10 09:57:14.075039', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46bd2d86291b42ef877aa42267420b98', '刘文岛', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌秭归；湖北_武汉_江岸；湖北_黄冈_罗田；广西桂林资源；湖北_黄冈_麻城；安徽_芜湖_镜湖；湖北黄冈；河南郑州中牟；湖北黄冈团风；湖北黄冈；湖北黄冈英山；湖北黄冈；湖北黄冈黄梅；郧县/均县一带；湖北武汉；湖北荆州；湖北武汉汉南；湖北孝感云梦；湖北孝感；湖北黄石黄石港；湖北恩施；湖北黄冈；湖北黄石下陆；山西阳泉矿区；湖北黄石阳新', '[]', '[]', '抗日战争时期', '', '伪职：（被郧县民众声讨）；罪行：湖北广济人，曾任国民党汉口特别市市长。抗战时期其言论被郧县民众视为“认贼作父”，郧县街头曾张贴“刘文岛认贼作父”“郧县民众坚决驱逐汉奸卖国贼刘文岛”等标语', '[]', '2026-09-10 09:57:14.010080', '2026-09-10 09:57:14.010080', '湖北', '孝感', '云梦', NULL, NULL, NULL, NULL, '');
