INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46e2d577d4a847af99593cecf3139456', '张德成', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆合川；重庆巫溪；重庆璧山', '[]', '[]', '抗日战争时期', '', '日军空袭重庆期间，在璧山组织维持会，协助日军搜集情报、征发民夫，为日机指示轰炸目标。；在重庆商界为日伪势力筹款筹粮，协助控制物资流通，压制商人抗日活动。；传闻在合川沦陷期间任伪警察局长，镇压抗日分子，但无正式档案。', '[]', '2026-09-10 09:57:14.064109', '2026-09-10 09:57:14.064109', '重庆', '巫溪', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('46fa4d548ae84879b752326ddde96016', '孙咸熙', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江', '[]', '[]', '抗日战争时期', '', '伪职：伪盘山县第一任县长（1932??1933）；罪行：组建盘山县伪公署，配合日本参事官，推行保甲，强征粮饷，对抗义勇军进攻县城，向伪省求援调兵镇压抗日武装。；结局：抗战胜利后以汉奸罪逮捕判刑。', '[]', '2026-09-10 09:57:14.078728', '2026-09-10 09:57:14.078728', '浙江', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4700e6fe1e7444e7be9c7f5bec6beb26', '张惠民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古包头', '[]', '[]', '抗日战争时期', '', '投靠日军后控制包头商会，为日军筹集军饷和物资，强迫商户缴纳各种捐税，从中牟利。', '[]', '2026-09-10 09:57:13.987952', '2026-09-10 09:57:13.987952', '内蒙古', '包头', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4705848a8fc243308999c37cc0cb7859', '续范亭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾隰县；山西忻州', '[\"注：此人为抗日将领，非汉奸，但历史资料中曾误传，故不列入\", \"叛变后\"]', '[]', '抗日战争时期', '', '无', '[]', '2026-09-10 09:57:14.019432', '2026-09-10 09:57:14.019432', '山西', '临汾', '隰县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('470c904de1bc4857a3a2422805a44d8a', '熊遂', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安遂川；江西南昌；江西南昌；江西上饶余干；云南普洱西', '[]', '[]', '抗日战争时期', '', '江西沦陷区伪政权头目之一，组织维持会为日军筹粮筹款，诱降地方士绅。；南昌沦陷后投敌，任伪南昌市市长，协助日军推行伪化统治。；南昌沦陷初期组织维持会，为日军筹粮筹款、维持地方秩序，协助日军控制南昌周边地区。', '[]', '2026-09-10 09:57:14.037590', '2026-09-10 09:57:14.037590', '江西', '上饶', '余干', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('470d48dade974284a6ea14114d2c73c0', '赵玉昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定徐水；河北保定涿州；黑龙江黑河北安；河北保定保定高；河北保定；河北保定竞秀；天津河北；河北保定涞水；河北保定望都；内蒙古赤峰喀喇沁旗；内蒙古赤峰；河北保定涞源；河北保定安新；河北保定容城；河北保定徐水；河北；内蒙古赤峰松山；内蒙古赤峰；河北保定易县；易县；河北保定蠡县；河北衡水故城；河北衡水；五寨；河北保定满城；河北廊坊文安；河北廊坊大城；内蒙古赤峰翁牛特旗；易县东邵村；河北保定雄县；河北保定曲阳；河北保定保定白沟新城；河北保定；河北保定阜平；河北保定满城', '[]', '[]', '抗日战争时期', '', '原为八路军冀中军区第10军分区司令员，1939年叛变投敌，在保定地区组建伪军，多次配合日军扫荡白沟新城及周边抗日根据地，杀害抗日军民数百人。；原为土匪，后投靠日军，任保定伪保安队队长，协助日军扫荡抗日根据地，残害抗日军民。；原为地方武装头目，投日后任伪军司令，在保定高阳一带协助日军扫荡，残害抗日军民。；原为土匪，后投日，在安新、容城一带袭击县区游击队，杀害多名抗日烈士。；原为抗日武装首领，后投敌叛变，任伪安新县保安联队队长，多次率部袭击抗日根据地，捕杀抗日干部和群众，制造多起惨案。……（共涉及31个地区的犯罪记录）；伪职：原八路军支队司令员，叛变投敌，伪易县警备团长兼特务部长；狼牙山五壮士事件主要祸首，熟悉根据地内情，带领日军反复扫荡晋察冀一分区，残害大批干部群众；势力延伸定兴、易县、涞水一带。；结局：日本投降后潜逃，1952 年抓捕归案公审枪决；伪职：伪五寨警备大队长；罪行：祸害五寨周边乡村，搜捕晋绥根据地人员。；结局：解放后公审枪决；伪职：伪易县警备团长兼特务部长，见上。；结局：公审枪决抖音百科', '[]', '2026-09-10 09:57:13.990511', '2026-09-10 09:57:13.990511', '内蒙古', '赤峰', '喀喇沁旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4718b8ce28154c7ebda3a7e9d2fa5024', '赵德山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊永清；辽宁沈阳新民；采石矶（马鞍山雨山）；湖北荆门东宝；林口、穆棱交界山林；重庆长寿；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '推行奴化教育，组织“新民会”宣传亲日思想，搜集抗日情报，协助日军进行经济封锁。；伪职：伪特务，原抗联人员；罪行：叛变后充当伪讨伐队向导，熟悉吉东山林，出卖多处抗联密营位置，多次参与进山扫荡。；结局：解放后被逮捕惩处。；伪职：采石伪警察所长；罪行：采石据点伪警头目，管控江边码头，抓捕、关押抗日人士，敲诈过往船商渔民。；结局：建国后镇反处决。', '[]', '2026-09-10 09:57:14.042576', '2026-09-10 09:57:14.042576', '河北', '廊坊', '永清', NULL, NULL, NULL, NULL, '');
