INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('472d44d64bfa4c4db116509e1767d9a6', '张淦', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽六安裕安；安徽六安；广西桂林恭城；广西南宁；吉林高', '[]', '[]', '抗日战争时期', '', '桂系将领，抗战期间在安徽六安、立煌一带活动，后期与日伪有秘密接触，参与反共摩擦。；原桂系将领，后投靠汪伪政权，任伪军高级头目，在华中地区配合日军作战。；桂系将领，坚持抗战，未附逆。', '[]', '2026-09-10 09:57:14.005445', '2026-09-10 09:57:14.005445', '安徽', '六安', '裕安', NULL, NULL, NULL, NULL, '');
