INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4793bdbdb6d94deb95371ca24a233744', '巴图济尔噶勒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古阿拉善阿拉善右旗', '[]', '[]', '抗日战争时期', '', '协助达理札雅处理旗务，与日本特务及伪蒙疆政权有暗中往来，曾为日军搜集阿拉善地区情报，并协助日伪人员渗透旗境。', '[]', '2026-09-10 09:57:13.992583', '2026-09-10 09:57:13.992583', '内蒙古', '阿拉善', '阿拉善右旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4794697c2a744d798eb416b18e51bd7e', '张天寿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '效忠日军，指挥伪警察搜捕抗日分子，破坏地下交通站，勒索百姓，协助日军建立保甲制度，强化殖民统治。', '[]', '2026-09-10 09:57:14.080532', '2026-09-10 09:57:14.080532', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('479871ffa6344bcc83be50a38479e99e', '张子修', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店上蔡；河南周口淮阳；河南周口；河南商丘；河南周口鹿邑；河南周口；河南许昌鄢陵；河南商丘睢阳；河南商丘；河南南阳镇平；河南周口项城；河北邢台沙河；河南商丘；河南商丘民权；河南商丘；河南南阳邓州；河南周口鹿邑；河南商丘；河南周口商水；河南周口；河南新乡封丘', '[]', '[]', '抗日战争时期', '', '河南沦陷区伪政权要员，参与伪河南省政，协助日军在豫东包括商丘、民权一带推行殖民统治。；鹿邑沦陷后组织维持会，后任伪县长，为日军征粮征丁，配合扫荡。；在封丘推行奴化教育，编写亲日教材，组织师生参加日伪宣传活动，为日军殖民统治服务。；沈丘沦陷后组织维持会并任伪县知事，协助日军控制沙河沿岸，征发物资劳工，是周口地区有记载的附逆者。；在商丘沦陷区任伪警察局长，指挥伪警察配合日军清查户口、抓捕抗日嫌疑人员，维持日伪统治秩序。；淮阳人，抗战期间投敌，任伪淮阳县公署知事，管辖区域邻近西华、周口，配合日军推行保甲制、征粮征丁，镇压抗日群众。；在淮阳一带为日军推行伪政，组织伪保安团，配合日军对周口、商水、淮阳交界地区进行治安强化，镇压抗日活动。；镇平人，抗战末期投靠日军，组织伪保安团，配合日军扫荡当地抗日武装。；商丘本地伪武装头目，率伪保安团配合日军守备队扫荡商丘、睢阳周边乡村，强征民夫、修筑据点。；任伪上蔡县警察局长，协助日军搜捕抗日人员、维持伪治安，参与地方清乡与保甲推行。；扶沟伪政权头目，推行经济统制，强征小麦、棉花供给日军，配合日军对扶沟、鄢陵一带抗日根据地进行扫荡。；抗战末期投靠日军，组建伪保安团，配合日军扫荡邓县周边抗日武装，维护日伪统治。；商丘沦陷后组织维持会，后任伪豫东道尹，管辖商丘、周口、鹿邑等豫东地区，为日军推行治安强化运动、掠夺物资。', '[]', '2026-09-10 09:57:14.047231', '2026-09-10 09:57:14.047231', '河南', '南阳', '邓州', NULL, NULL, NULL, NULL, '');
