INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('47be08266e0d45c2a52a53c5ab86dc1e', '李道轩', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山；广东广州黄埔；广东汕尾陆丰；广东汕尾海丰；广东佛山高明；广东佛山；广东广州荔湾；广东广州', '[]', '[]', '抗日战争时期', '', '日军占领佛山后，纠集地方劣绅成立伪维持会，为日军筹款、派夫、搜集情报，迫害抗日家属。；日军占领佛山后，纠集地方劣绅成立伪佛山镇维持会，为日军筹粮筹款、登记户口、诱降抗日人员。；广州沦陷初期伪维持会成员，参与地方附逆事务。；佛山沦陷初期参与组织伪维持会，协助日军维持地方秩序、征发民夫物资。；海丰沦陷后组织伪维持会，为日军提供情报、粮秣，并参与诱降地方抗日武装。；汪伪广东司法官员，利用伪法院镇压抗日人士，维护日伪统治秩序。', '[]', '2026-09-10 09:57:14.026106', '2026-09-10 09:57:14.026106', '广东', '佛山', '禅城', NULL, NULL, NULL, NULL, '');
