INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('482347028d7d4129a7da732c7d4c4f44', '汪时璟', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；安徽蚌埠淮上；安徽蚌埠；河北秦皇岛秦皇岛经开区；河北秦皇岛；安徽旌德；江苏南京鼓楼；河北廊坊；天津河北；湖南_怀化_怀化洪江管理；云南普洱西；陕西_西安_长安；北京昌平；河北张家口尚义；河北张家口；北京大兴；北京门头沟；安徽芜湖；北京海淀；广西_柳州；云南普洱西；北京、河北；安徽芜湖镜湖；安徽芜湖；北京东城；北京丰台；北京延庆；北京石景山；北京_西城；安徽安庆；山东聊城；河北唐山', '[]', '[]', '抗日战争时期', '华北伪临时政府', '在廊坊各县强征苛捐杂税，为伪军和日军提供经费，加重百姓负担。；在北平东城设立伪中国联合准备银行总部，发行伪币，掠夺中国资财，为日军侵华战争提供经济支持。；在北平设立伪银行，发行伪币，在丰台地区强制兑换，掠夺经济资源。；在北平发行伪币，掠夺大兴等县物资，导致当地经济崩溃，间接支持日军战争机器。；在北平发行伪币，在延庆等县强制兑换法币，掠夺民间财富，造成通货膨胀，破坏抗日经济基础。；在北平设立伪银行，发行联银券，掠夺昌平等地民间财富，造成经济混乱。……（共涉及12个地区的犯罪记录）；伪任职务：伪华北政务委员会经济总署督办，伪中国联合准备银行总裁（北平）。结局：1945 年鸿门宴被捕，判处无期徒刑，1952 年狱中死亡', '[]', '2026-09-10 09:57:13.992872', '2026-09-10 09:57:13.992872', '北京', '东城', '茌平', NULL, NULL, NULL, NULL, '');
