INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('49c3c672a7584f17bc5e0c8d7eebdd1f', '刘佩水', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸“二五子”通信大队大队长；罪行：1941年1月，淄博矿区工会特务队副队长翟干臣等转移途中恰遇刘佩水等20余人，双方交火；结局：刘佩水等6人被击毙', '[]', '2026-09-10 09:57:14.077691', '2026-09-10 09:57:14.077691', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('49c450e7364f49fdb01406a8d3147213', '刘子英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄新华；内蒙古、山西、河北；山西吕梁中阳；山西忻州静乐；河南焦作沁阳；河南焦作；湖南湘西泸溪；云南普洱西；山西朔州朔城；山西朔州；山西临汾乡宁；河南焦作焦作示范；河南焦作修武；山西大同新荣；山西吕梁石楼；山西吕梁交城；内蒙古_巴彦淖尔_五原', '[]', '[]', '抗日战争时期', '', '为日军效忠，搜捕抗日地下人员，破坏地下交通线，并参与镇压当地民众的反抗。；日军占领乡宁期间，组织维持会为日军筹粮派款，提供抗日武装活动情报，导致多名地下党员被捕牺牲。；为日军宪兵队效命，在新荣地区发展特务网络，破坏地下抗日组织，逮捕并杀害多名共产党员和进步人士。；在忻县任伪职期间，为日军提供情报，组织伪政权征税派捐，协助日军建立“无人区”，迫害抗日家属。；效忠日伪政权，搜捕地下抗日人员，破坏抗日组织，勒索百姓财物。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.990291', '2026-09-10 09:57:13.990291', '山西', '临汾', '乡宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('49db651ac0b143dc92ef7e896f587ac6', '李振之', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：原中共博山县委经建科长（叛变）；罪行：1941年10月被捕叛变。其后又撺掇其子李奉奎叛变投敌。父子叛变给博山四区党组织带来毁灭性破坏', '[]', '2026-09-10 09:57:14.080384', '2026-09-10 09:57:14.080384', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
