INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4ab5cde3fc2c49dbb395ce2ec1c75f3c', '谢介石', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林长春宽城；吉林长春；台湾新竹；云南昆明呈贡；黑龙江_双鸭山_友谊；黑龙江_大庆_龙凤；黑龙江_绥化_绥棱；黑龙江哈尔滨松北；吉林长春；吉林；吉林；黑龙江伊春丰林；黑龙江哈尔滨松北；黑龙江哈尔滨；吉林长春绿园；吉林；吉林长春长春高；吉林长春', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪满洲国首任外交部总长，主导伪满外交，大量引荐台湾人赴东北出任伪职，为日本分裂中国效力。。结局：抗战胜利被捕，关押于抚顺战犯管理所，1954 年狱中去世；早年投靠日本，在吉林地区参与对日交涉，后任伪满驻日大使，积极为日本侵华辩护。；在长春制定伪法律，镇压抗日活动，迫害爱国人士，维护日本殖民秩序。；在吉林任职期间协助日军稳定统治，后调任伪满外交系统，为日本服务。；原台湾籍官僚，投日后任伪满驻日大使，在长春和东京间活动，为日本侵略政策辩护。；伪职：伪吉林省交涉署署长、伪满外交部大臣；罪行：台湾籍，早期投靠熙洽，参与伪满外交，出卖国家利益。；结局：1946 年被捕，病死狱中。', '[]', '2026-09-10 09:57:13.982678', '2026-09-10 09:57:13.982678', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
