INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b2b182750974b469aa61c3cf44a1351', '崔培德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北廊坊霸州；山西、河北；河北石家庄鹿泉；河北衡水武邑；河北衡水；山西长治潞城；辽宁沈阳新民；河南南阳新野；河南南阳；山西长治长子；山西长治；河北保定高碑店；辽宁沈阳新民；河南安阳文峰；河南安阳', '[]', '[]', '抗日战争时期', '', '推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，破坏抗日宣传。；在长治、长子交界地区推行“连坐法”，强迫百姓报告八路军行踪，导致多名抗日群众被日军杀害。；负责在占领区推行奴化教育，组织“新民会”宣传“中日亲善”，刺探抗日情报，协助日军抓壮丁。；率警备队多次突袭抗日村庄，活埋抗日军属，并强迫青年加入伪军。；日军占领获鹿初期，组织维持会，为日军带路搜捕抗日分子，强征民夫修炮楼。', '[]', '2026-09-10 09:57:14.024352', '2026-09-10 09:57:14.024352', '山西', '长治', '潞城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b353b56618e409ab31e6aa95c7ddbe7', '李伯洲', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾海丰；江苏徐州丰县', '[]', '[]', '抗日战争时期', '', '任伪陆丰县县长，隶属汕尾地区，配合日军扫荡抗日游击队，推行奴化教育。', '[]', '2026-09-10 09:57:14.028414', '2026-09-10 09:57:14.028414', '广东', '汕尾', '海丰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b3b7f40692048979028be7487760792', '额尔钦巴图', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰阿鲁科尔沁旗；内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔；内蒙古呼伦贝尔新巴尔虎右旗；内蒙古兴安科尔沁右翼中旗', '[]', '[]', '抗日战争时期', '', '继凌升后任伪兴安北省省长，继续在海拉尔及呼伦贝尔地区为伪满洲国和日本统治服务。；科尔沁右翼中旗蒙古族上层，投日后任该旗伪旗长，协助日军征发物资、推行保甲制度，镇压当地抗日活动。；在伪满洲国时期任阿鲁科尔沁旗旗长，执行日伪政令，征派劳工、物资，配合日军对当地抗日力量进行压制。；呼伦贝尔地区蒙古族上层，投靠日本，在伪兴安北分省任职，参与伪政权对呼伦贝尔各旗包括新巴尔虎右旗的统治。；凌升之后任伪兴安北省省长，继续在海拉尔及呼伦贝尔地区为伪满洲国和日本统治服务。；继凌升后任伪兴安北省省长，继续为伪满洲国和日本关东军服务，控制呼伦贝尔地区。；在伪兴安北省任职，参与日本对呼伦贝尔地区的殖民统治和基层控制。；凌升被处决后接任伪兴安北省省长，继续为伪满洲国统治呼伦贝尔地区服务，直至1945年日本投降。；继凌升之后任伪兴安北省省长，继续为日本侵略者服务，在呼伦贝尔地区推行伪满政令，协助日本掠夺当地资源。', '[]', '2026-09-10 09:57:13.987801', '2026-09-10 09:57:13.987801', '内蒙古', '兴安', '科尔沁右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b3cfe84e31b49af9f54d347c9f4012b', '何介夫', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关始兴；广东韶关；江西抚州临川；广东韶关新丰；广东韶关；江西鹰潭；湖南岳阳岳阳屈原管理；湖南岳阳湘阴；湖南岳阳；湖南长沙', '[]', '[]', '抗日战争时期', '', '为日军筹款筹物，控制粮食与食盐配给，协助经济封锁，压制商户支持抗日。；统领伪保安团在湘阴、汨罗一带协助日军清乡，抓捕抗日群众。；在曲江一带组织维持会，协助日军维持韶关周边占领区统治。；以商会名义为日军筹集瓷业物资，强迫商户缴纳“治安费”。；汪伪政权在乐昌县的县长，配合日军在韶关北部地区的殖民统治，镇压抗日民众。；长沙沦陷后出任伪长沙县知事，协助日军维持占领区秩序，征调物资。', '[]', '2026-09-10 09:57:14.030351', '2026-09-10 09:57:14.030351', '广东', '韶关', '始兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b46923590a84989bab11dea38d09028', '汪笃斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '安庆老城区', '[]', '[]', '抗日战争时期', '', '伪职：安庆维持会首任会长、自治委员会委员长；罪行：安庆沦陷头号汉奸，日军进城举太阳旗出城迎接；组建维持会，发放盐商执照收受贿赂，胁迫商户复业，办理良民证，协助日军搜捕爱国人士，其子在天津出任伪警察分局长。；结局：抗战胜利后肃奸逮捕，判处死刑处决。', '[]', '2026-09-10 09:57:14.077567', '2026-09-10 09:57:14.077567', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
