INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4b85d94c798c4352862e7a4a325cb1bf', '李荫堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口蔚县；河北张家口宣化；河北唐山滦州；河北唐山；河北保定涞水；河北唐山；山西、河北；山西阳泉平定', '[\"同名\"]', '[]', '抗日战争时期', '', '为日军统制煤炭物资，强迫商户‘献金’，资助伪军，并出卖抗日情报。；日军占领涞水初期，组织维持会，为日军筹粮筹款，强征民夫修路筑堡，协助建立伪政权。；在唐山各学校删除历史课中的爱国内容，灌输奴化思想。；在宣化、蔚县一带督导伪政权，强征粮食，组织“自卫团”，配合日军“治安强化运动”，破坏抗日根据地。；率保安队多次袭击八路军游击队，杀害抗日干部，烧毁村庄，为日军充当鹰犬。；在唐山学校开除进步教师，推行奴化课程。', '[]', '2026-09-10 09:57:14.024617', '2026-09-10 09:57:14.024617', '山西', '阳泉', '平定', NULL, NULL, NULL, NULL, '');
