INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4ba41880b71845aba5327b2761f1f6bf', '盛某', NULL, NULL, NULL, NULL, 'exact', 'exact', '金东澧浦', '[]', '[]', '抗日战争时期', '', '伪职：澧浦伪乡长；罪行：澧浦伪乡政权头目，为日军催粮派差，向炮台据点日军递送情报，欺压乡间百姓金华市人民...。；结局：八大队夜袭澧浦，抓捕处决金华市人民...。', '[]', '2026-09-10 09:57:14.087717', '2026-09-10 09:57:14.087717', '浙江', '金华', NULL, NULL, NULL, NULL, NULL, '');
