INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4bbf57ba4a85420fafe76cfc91da8137', '李守维', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏宿迁宿豫；江苏宿迁；江苏盐城响水', '[]', '[]', '抗日战争时期', '', '参与策划清乡行动，协助日军推行保甲制度，搜捕抗日分子。；宿迁沦陷后出面组织维持会，为日军筹粮筹款、拉夫修路，协助日军建立伪政权，维持地方治安。', '[]', '2026-09-10 09:57:14.034495', '2026-09-10 09:57:14.034495', '江苏', '宿迁', '宿豫', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4bc1fdf2dc3e4c0790cbca515335e7f4', '陈雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西梧州岑溪；广西梧州；广西梧州藤县；广西梧州苍梧；广西玉林；广西桂林；广西桂林秀峰；广西南宁；广西梧州万秀；广西梧州；广西桂林临桂；广西桂林；广西崇左；广西南宁；广西柳州鹿寨；云南普洱西；云南普洱西；广西桂林叠彩；广西桂林；广西河池南丹；广西河池', '[]', '[]', '抗日战争时期', '', '抗战后期在广西境内组织伪军，配合日军扫荡抗日游击区，活动范围涉及桂林周边。；在伪广西省政府中主管教育，推行日语教学与奴化教育，篡改历史教材，为日军殖民统治服务。；在日军侵占桂南、粤西期间，组织伪维持会，活动范围涉及崇左、南宁一带，协助日军征粮、拉夫。；在日军占领梧州期间，以商会名义协助日军强制摊派物资、控制经济，属经济领域附逆者。；在日军占领梧州期间，以商会名义为日军筹款、征物，协助经济掠夺。；日军侵占苍梧期间，出面组织伪维持会，为日军筹粮、派夫、维持地方秩序。；桂林沦陷期间任维持会会长，为日军提供情报、粮食和劳力，协助维持占领秩序。；在汪伪广西省政权中任职，负责警务与情报，协助日军在桂林、南宁等地建立伪警察网络，镇压抗日活动。；在梧州万秀一带担任伪保甲长，为日军征派壮丁、粮食，监视居民言行，协助维持伪统治。；控制南宁码头工人，为日军装卸军用物资，协助镇压工人反抗。；藤县沦陷期间，组织伪维持会，为日军征粮、派夫，协助控制地方。；日军入侵广西期间，参与伪广西维持会活动，协助日军征调物资、维持治安。；日军占领桂林后，出面组织伪商会，强制商户向日军缴纳物资，配合日军经济掠夺。；在广西沦陷区参与伪警察系统，配合日军维持治安、搜捕抗日分子，其系统延伸至河池地区。', '[]', '2026-09-10 09:57:14.030875', '2026-09-10 09:57:14.030875', '广西', '南宁', '鹿寨', NULL, NULL, NULL, NULL, '');
