INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4bd91964634b496ab25c4e1c7bc05b6c', '王舟平', NULL, NULL, NULL, NULL, 'exact', 'exact', '渑池县', '[]', '[]', '抗日战争时期', '', '伪职：八路军独立第七旅政委（被害）；罪行：中共派往上官子平部任政委兼渑池县委书记。在上官子平叛乱中被杀害；结局：1945年5月在上官子平叛乱中牺牲', '[]', '2026-09-10 09:57:14.074438', '2026-09-10 09:57:14.074438', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4bf78476d5b942499735eed6d0963a80', '刘明德', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口；河南鹤壁淇县；云南昆明西山；云南保山龙陵；河南许昌鄢陵；河南许昌；河南焦作武陟；山西阳泉矿区；河南焦作解放；河南焦作；修武；河南许昌许昌经开区；河南许昌；河南商丘柘城；河南焦作温县；河南焦作武陟；山西吕梁石楼；河南焦作修武；河南鹤壁淇滨；河南鹤壁；河南许昌禹州；云南普洱西；云南保山腾冲；云南普洱西；河南漯河；河南焦作中站；河南焦作；云南保山龙陵；河南周口商水；河南周口；河南新乡新乡平原示范；河南新乡；河南焦作山阳；河南焦作沁阳；河南新乡；河南焦作博爱；河南焦作；河南焦作武陟；河南信阳息县；河南信阳；河南漯河临颍；河南新乡封丘；河南新乡新乡高；河南新乡', '[]', '[]', '抗日战争时期', '', '伪职：伪军头目（汉奸）；罪行：1943年日伪顽匪合流，刘明德率匪部公开投降日寇当了汉奸', '[]', '2026-09-10 09:57:13.980174', '2026-09-10 09:57:13.980174', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c0bb80f68bb4bd797a5e2042ad4f025', '孙仁轩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林经开区；吉林；长春；吉林辽源东丰；黑龙江绥化庆安；黑龙江绥化；吉林松原长岭；吉林松原乾安；吉林白山抚松', '[]', '[]', '抗日战争时期', '', '在东丰县从事特务活动，发展汉奸情报网，破坏抗日地下组织，直接参与刑讯逼供抗日人员。；伪职：伪新京总商会会长；罪行：为日伪摊派各类报国捐，筹措军需物资，压榨长春商民。；结局：反奸清算，没收财产，判处徒刑。', '[]', '2026-09-10 09:57:13.999038', '2026-09-10 09:57:13.999038', '吉林', '松原', '长岭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c14ecbb8d424d8984183fe967cfbd59', '黄耀庭', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西鹰潭；江西南昌；湖南郴州苏仙；湖南郴州宜章', '[]', '[]', '抗日战争时期', '', '日军占领郴县后出任伪警察头目，负责搜捕抗日人员、维持伪治安，其活动区域包括郴县至宜章一线。；组织伪保安队配合日军行动，在郴县及周边地区参与清乡、征粮和镇压抗日活动。；参与南昌伪政权筹备，为日军宣传“东亚共荣”，推行奴化教育。', '[]', '2026-09-10 09:57:14.040618', '2026-09-10 09:57:14.040618', '江西', '鹰潭', '苏仙', NULL, NULL, NULL, NULL, '');
