INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c3bc3f8fceb44cda17070357493d975', '赵文远', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北十堰竹溪', '[]', '[]', '抗日战争时期', '', '湖北竹溪人，抗战期间投敌，任伪竹溪经济科科长，协助日军搜刮物资，压榨民众。', '[]', '2026-09-10 09:57:14.054831', '2026-09-10 09:57:14.054831', '湖北', '十堰', '竹溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c3e56cf7b9f429691a9a5e9469bcb1d', '张文铸', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯东风；黑龙江佳木斯；黑龙江大兴安岭加格达奇；黑龙江大兴安岭松岭；黑龙江齐齐哈尔；黑龙江伊春金林；黑龙江齐齐哈尔；内蒙古呼伦贝尔；黑龙江齐齐哈尔；黑龙江鹤岗兴安；黑龙江齐齐哈尔；黑龙江鹤岗绥滨；黑龙江佳木斯；黑龙江大庆大庆高；黑龙江齐齐哈尔；黑龙江黑河嫩江；黑龙江齐齐哈尔；黑龙江佳木斯汤原；黑龙江哈尔滨延寿；黑龙江齐齐哈尔；黑龙江哈尔滨松北；黑龙江哈尔滨；吉林白城大安；吉林白城；黑龙江佳木斯；黑龙江佳木斯桦南；黑龙江哈尔滨；黑龙江大庆龙凤；黑龙江齐齐哈尔；黑龙江大庆杜尔伯特；黑龙江齐齐哈尔', '[]', '[]', '抗日战争时期', '', '原东北军旅长，投日后负责黑龙江中西部“讨伐”，在嫩江流域多次袭击抗联部队；在伪黑龙江省政权中任职，协助日本推行省政殖民化，参与治安肃正与物资统制。；原东北军军官，九一八事变后投敌，曾任伪黑龙江省长，参与伪满地方政权建设，其统治区域包括齐齐哈尔及龙沙地区。；原东北军团长，投日后在黑龙江地区多次“讨伐”抗联，烧毁村屯。；原哈尔滨地方保安队长，投日后任伪警备司令，协助日军清乡。；在汤原县建立庞大特务网络，收买叛徒破坏抗联地下交通站，逮捕并杀害汤原县委书记及多名区委干部。；负责嫩江、加格达奇一带防务，配合日军“治安肃正”，杀害抗联战士。；管理呼伦贝尔及大兴安岭西麓地区，协助日本对鄂伦春等少数民族进行控制，并参与对抗联的军事行动。；原东北军军官，投日后在黑龙江地区协助日军策划“讨伐”抗联，多次参与松岭、嫩江一带的扫荡行动。；投敌后任伪满军将领，在黑龙江地区参与镇压东北抗日联军，推行日伪军事统治。；在哈尔滨及北满地区指挥伪军对抗联进行多次围剿，其部队在桦南、勃利等地烧杀抢掠。；原东北军军官，投日后任伪满第三军管区司令，驻齐齐哈尔，多次率伪军进攻抗联，屠杀抗日军民。；原东北军军官，投日后驻守齐齐哈尔，指挥伪军多次“讨伐”抗联部队，在富裕县等地烧杀抢掠；在佳木斯、绥滨、鹤岗一带指挥伪军多次围剿抗联，杀害抗联战士及平民。；在佳木斯地区实施殖民统治，强征劳工，配合日军‘讨伐’抗联，推行经济掠夺政策。；在黑龙江西部及兴安地区围剿抗联，实施“三光”政策。；原东北军团长，投敌后任伪满军职，其辖区包括白城、大安，多次派伪军配合日军扫荡抗联。；原东北军军官，投敌后历任伪黑龙江省长、伪满参议府参议，参与伪满在黑龙江的殖民统治，推行保甲连坐、粮谷出荷等政策，其辖区涵盖大庆、杜尔伯特地区。；原东北军军官，投敌后任伪黑龙江省长，参与伪满在黑龙江地区的行政统治，后任伪满参议府参议。；在佳木斯地区负责特务活动，搜捕抗日人员，破坏抗日地下组织。；投敌后任伪满军管区司令，参与镇压黑龙江地区抗日武装。；长期任伪黑龙江省（省会齐齐哈尔）省长，推行日伪法令，强征劳工，配合日本经济掠夺。', '[]', '2026-09-10 09:57:13.999317', '2026-09-10 09:57:13.999317', '吉林', '白城', '大安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c4023066f4e4b0ebb5ecd0a2a170b77', '江朝宗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东济宁微山；山东济宁；青海黄南河南；广西_桂林_灵川；安徽旌德；安徽宣城旌德；北京西城；北京昌平；江西九江；重庆永川；安徽宣城旌德；安徽_黄山；云南普洱西；陕西_西安_长安；北京朝阳；吉林长春朝阳；天津河北；河北廊坊；北京、河北；北京海淀；山西太原示范；云南普洱西；四川_广元；云南普洱西；陕西_西安_灞桥；陕西_西安_蓝田；重庆沙坪坝；陕西_西安；北京东城；重庆_万州；重庆_大足；云南普洱西', '[]', '[]', '抗日战争时期', '汪伪政权', '初期在北平及周边（含廊坊北）组织维持会，为日军建立秩序。；伪任职务：伪北平特别市首任市长，北平治安维持会会长。结局：1943 年病亡，未受审判中国社会科...；1937年北平沦陷后率先组织伪北平维持会，迎接日军进城，后任伪临时政府顾问，是东城地区早期汉奸头目。；原北洋将领，北平沦陷后任伪维持会副会长，协助日军接管昌平。；北洋遗老，北平沦陷初期出任伪维持会会长，为日军在朝阳地区建立秩序提供协助。；七七事变后出任伪北平维持会会长，后任伪北平市长，协助日军维持北平（含海淀）秩序，镇压抗日民众；七七事变后率先投敌，组织北平维持会，为日军提供后勤支持，协助建立伪政权。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.992980', '2026-09-10 09:57:13.992980', '北京', '东城', '莲湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c4beda1fd5a4539b45d68077c22a709', '陈伯谦', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西南昌红谷滩；江西南昌；江西上饶玉山；江西上饶；江西宜春', '[]', '[]', '抗日战争时期', '', '统领伪保安大队配合日军对南昌周边乡村进行扫荡，强征粮食、抓捕抗日人员，镇压当地民众反抗。；组建伪警察队伍，配合日军清乡，在高安、宜春交界地带镇压抗日活动。；在伪江西省政府任职期间，参与推行日军在赣东北的保甲连坐与物资统制政策，影响范围包括上饶、玉山。', '[]', '2026-09-10 09:57:14.038027', '2026-09-10 09:57:14.038027', '江西', '上饶', '玉山', NULL, NULL, NULL, NULL, '');
