INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4c5c1c8d671f481e87c311e38bed507a', '王伯勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州六盘水六枝特；湖南益阳赫山；山西阳泉城区；湖南益阳桃江；湖南益阳；湖南益阳沅江', '[]', '[]', '抗日战争时期', '', '在沅江地区组织维持会，为日军筹集物资、提供情报，协助日军控制洞庭湖周边。；桃江沦陷后组织伪维持会，为日军筹粮、派款，并协助建立伪基层保甲。；受日军指使控制益阳城区商业，强制商户交纳“治安费”，并为日军采购军需物资。；在六盘水地区组织伪维持会，为日军征集物资、情报，协助管理地方，压迫当地民众。', '[]', '2026-09-10 09:57:14.059266', '2026-09-10 09:57:14.059266', '湖南', '益阳', '桃江', NULL, NULL, NULL, NULL, '');
