INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4ce43202095e449d9a45d448ce759380', '周文焕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁鞍山岫岩；辽宁鞍山岫岩；辽宁鞍山；河北保定涞水；山西吕梁；山西吕梁石楼；山西忻州忻府；山西朔州朔州经开区；江苏连云港东海；山西_忻州_代县；山西大同广灵；山西忻州定襄；山西忻州五寨；河北_衡水_景县；河北沧州东光；山西运城平陆；辽宁沈阳新民；黑龙江双鸭山宝清；山西大同阳高；山西忻州保德；黑龙江鸡西滴道；黑龙江鸡西；山西_朔州_应县；山西、河北、辽宁；河北衡水衡水高；河北衡水景县', '[]', '[]', '抗日战争时期', '', '已列，补充其曾组织“献机”活动。；在石楼县为日军提供民夫，并参与迫害抗日家属。；为日军驻广灵部队担任翻译，多次参与审讯抗日志士，并利用翻译身份敲诈勒索百姓，曾向日军告密导致多名地下党员被捕牺牲。；垄断阳高粮食、棉花等物资，低价强购后供给日军，导致百姓饥荒，并从中贪污中饱。；在日军控制区任伪区长，协助日军建立保甲制度，强迫村民‘自首’抗日分子。；为日军征收各种苛捐杂税，强征粮食和物资，导致百姓负担沉重，部分收入用于资助伪军。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019763', '2026-09-10 09:57:14.019763', '山西', '吕梁', '广灵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4ce5608be3514a7cafa28b61ea0d514c', '李春浓', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南澄迈；海南陵水；海南文昌；海南海口美兰', '[]', '[]', '抗日战争时期', '', '在陵水地区推行伪政，配合日军扫荡抗日根据地，强征民夫与物资。；在文昌北部铺前、罗豆一带为日军筹办物资，指引日军袭击抗日村庄。；充任伪警察头目，带领伪警配合日军下乡扫荡，抓捕抗日人员及嫌疑群众。；协助赵士桓组织维持会，为日军提供情报与后勤支持。', '[]', '2026-09-10 09:57:14.054221', '2026-09-10 09:57:14.054221', '海南', '文昌', '美兰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4ce703fe7678424a8a32deba6e1a2885', '周某某', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁谷里；湖南永州零陵；湖南永州江华；湖南株洲', '[\"佚名\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：谷里密探，在游击区搜集情报，向秣陵关日军告密，危害地下组织。。结局：“红小鬼班” 武工队抓捕，送横山县抗日民主政府公审处置南京雨花台...', '[]', '2026-09-10 09:57:14.058806', '2026-09-10 09:57:14.058806', '湖南', '永州', '零陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4cef63a4459f49f9b4e6ad3b3084ddaa', '王振亚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河南南阳；河南三门峡义马；河南三门峡；河北；河南漯河；河南漯河临颍；河南三门峡灵宝；河南平顶山平顶山高；河南平顶山', '[]', '[]', '抗日战争时期', '', '任伪迁安县长期间，推行日伪“治安强化”运动，强征民夫修筑炮楼、封锁沟，配合日军清乡，逮捕抗日人员。', '[]', '2026-09-10 09:57:14.045708', '2026-09-10 09:57:14.045708', '河南', '三门峡', '义马', NULL, NULL, NULL, NULL, '');
