INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d4f34628e7a437c8d7077e5dc3c384a', '阎俊贤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁离石', '[]', '[]', '抗日战争时期', '', '日军初占离石时组织维持会，为日军筹粮派款，提供妇女慰劳队，并出卖抗日积极分子名单。', '[]', '2026-09-10 09:57:14.020805', '2026-09-10 09:57:14.020805', '山西', '吕梁', '离石', NULL, NULL, NULL, NULL, '');
