INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d5da6800edd43e0a0c2138e5e9ecaac', '潘树勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博淄川；山东淄博；山东淄博临淄；山东济南章丘；山东潍坊；山东潍坊昌乐', '[]', '[]', '抗日战争时期', '', '在山东淄博、章丘一带活动，投敌后任伪军头目，参与镇压抗日军民。；在益都（今青州）任伪职，协助日军控制胶济铁路中段，与淄博地区日伪联系密切。；在昌乐为日军征粮征丁，组织伪自卫团，配合日军对潍县、昌乐边境抗日武装进行清剿。', '[]', '2026-09-10 09:57:14.015890', '2026-09-10 09:57:14.015890', '山东', '淄博', '临淄', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d5e57327a2345e98793a15bc0550bf6', '王定华', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南五指山；海南临高；海南三沙中沙；海南万宁；海南海口；海南万宁；海南三沙西沙；海南白沙；广西北海；海南屯昌；海南琼中；海南三亚', '[]', '[]', '抗日战争时期', '', '在临高地区为日军征收物资，组织伪警察。；在乐会地区组织伪政权，协助日军控制地方，迫害抗日家属。；在海口周边推行保甲制度，监视民众，协助日军征粮征丁。；控制北海商业，为日军采购军需物资，强制商户缴纳“治安费”，协助日军经济掠夺。；在万宁地区附逆，协助日军推行伪化教育、征发劳役，镇压抗日群众。；任伪崖县县长，协助日军控制三亚、榆林等地，为日军提供情报和物资。；在白沙地区为日军推行伪政令，参与对黎族抗日武装的镇压与诱降活动。；在龙滚地区组织伪维持会，为日军收集情报、征发民工修筑公路，参与破坏中共地方组织。', '[]', '2026-09-10 09:57:14.030458', '2026-09-10 09:57:14.030458', '广西', '北海', '中沙', NULL, NULL, NULL, NULL, '');
