INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d8147d6fb7d45a19a55d4a9bd38bb22', '张锡田', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州金水；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '在郑州组织伪新民会，进行亲日宣传、训练伪职人员、协助日军推行保甲与物资统制，是郑州本地文化宣传领域的附逆者。', '[]', '2026-09-10 09:57:14.049032', '2026-09-10 09:57:14.049032', '河南', '郑州', '金水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d875d291cbc4beea9df6cfe179a18d4', '宝音乌勒吉', NULL, NULL, NULL, NULL, 'exact', 'exact', '外蒙古；朝阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：逃亡伪蒙疆的外蒙古分裂分子，在张家口伪蒙疆政权任职，策划渗透外蒙古。结局：日本战败后被外蒙古逮捕处决；伪职：伪吐默特右旗旗长（蒙奸）；罪行：朝阳本地蒙旗最高长官；执行日伪蒙汉分治，搜刮牲畜粮食，配合讨伐山区抗日武装；八一五后出任朝阳治安维持会会长，企图维持伪政权等待国民党接收。；结局：解放后逮捕，汉奸罪重判。', '[]', '2026-09-10 09:57:14.070289', '2026-09-10 09:57:14.070289', '辽宁', '朝阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4d9399d3e01d4b3dbd23a90bf5e91efe', '张鸿惠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城高平；山西；山西晋城沁水；山西晋城城区；山西晋城；山西晋城阳城', '[]', '[]', '抗日战争时期', '', '日军首次侵占晋城时组织维持会，为日军带路清乡，指认抗日家属，勒索商民钱财，后随日军撤退而逃亡。；组建伪保安队，配合日军扫荡晋城周边抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众，掠夺物资。；率伪军配合日军进攻抗日根据地，抓捕并杀害抗日干部和群众。；投靠日军，任伪沁水县知事，推行保甲制度，组织伪警备队，配合日军扫荡抗日根据地，杀害多名抗日干部和群众。；率伪军多次配合日军扫荡抗日根据地，捕杀抗日干部和群众，制造多起惨案。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.023133', '2026-09-10 09:57:14.023133', '山西', '晋城', '城区', NULL, NULL, NULL, NULL, '');
