INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4e85df189a3e4101a24576f9130ce02b', '赵德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治沁源；河北沧州海兴；河北沧州运河；山西临汾浮山；江苏徐州丰县；河北_沧州_新华；河北_沧州_沧州经开区；江苏淮安金湖；山西晋中左权；河北沧州吴桥；山西晋城泽州；山西、河北；河北石家庄新乐；河北邯郸峰峰矿；山西晋中和顺；安徽_马鞍山_含山；山西阳泉城区；山西阳泉；河北沧州青县；辽宁沈阳新民；河北廊坊；河北廊坊香河；河北沧州孟村；江苏_宿迁_泗洪；河北_沧州_盐山', '[]', '[]', '抗日战争时期', '', '在香河县北部山区搜捕抗日武装，并强征民夫修建炮楼。；日军占领浮山后率先投敌，组织维持会，为日军筹集粮饷，强征民夫修筑碉堡公路，并劝降抗日人员。；参与“扫荡”左权县麻田镇，杀害八路军伤病员及群众20余人。；协助日军在泽州地区建立伪警备体系，参与“清乡”行动，抓捕抗日分子，烧毁村庄。；参与“三光”政策，烧杀抢掠，无恶不作。；在阳泉煤矿为日军效力，镇压矿工反抗，克扣矿工口粮，并协助日军强征劳工送往东北或日本。……（共涉及21个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.011101', '2026-09-10 09:57:14.011101', '山西', '临汾', '浮山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4e9e24895db9419cb283db7b5891c452', '李希才', NULL, NULL, NULL, NULL, 'exact', 'exact', '临湘县', '[]', '[]', '抗日战争时期', '', '伪职：日伪维持会会长；罪行：临湘县日伪维持会会长，罪大恶极；结局：1941年2月被临湘游击队在大岭口处决', '[]', '2026-09-10 09:57:14.076409', '2026-09-10 09:57:14.076409', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
