INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4f4d361d43ec4529912ff6be909ee960', '齐燮元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '安徽蚌埠；河北宁河（今属天津）；河北保定徐水；天津西青；天津河北；北京丰台；北京大兴；北京_延庆；北京_昌平；北京海淀；北京石景山；北京门头沟；山东德州；山东聊城；河南商丘；河南濮阳；青海黄南河南；云南普洱西；陕西宝鸡；陕西榆林；河南开封禹王台；四川南充南部；云南_昆明_呈贡；江苏徐州；天津武清；天津津南；河北张家口；陕西西安高陵；云南普洱西；河北唐山玉田；河北唐山；河北秦皇岛；山西晋中左权；江苏南京；河北石家庄辛集；河北石家庄；安徽芜湖；河北保定博野；河北廊坊；河北沧州；河北保定涞源；河北沧州河间；天津南开；河北石家庄井陉；河北石家庄；湖南常德津；河北秦皇岛昌黎；河北秦皇岛；河北秦皇岛秦皇岛经开区；河北秦皇岛；河北保定竞秀；北京东城；北京_西城；北京顺义；天津东丽；安徽安庆；河北保定；天津河北；河北唐山路南；河北唐山；河北廊坊；河北石家庄；河北秦皇岛；河北秦皇岛抚宁；四川南充南部；天津南开；河南新乡；青海黄南河南；陕西渭南；云南普洱西；安徽芜湖镜湖；安徽芜湖；河北唐山唐山芦台经开区；河北唐山；河北沧州沧县；河北唐山路北；河北唐山；河北唐山；陕西_西安；江苏南京浦口；吉林长春朝阳；四川_广元；天津河北；河北石家庄；河南信阳；河南商丘；云南普洱西；陕西榆林；陕西_西安_长安；安徽安庆；江苏南京鼓楼；云南普洱西；重庆_永川；北京、天津、河北；安徽芜湖镜湖；北京通州；江苏南通通州；天津静海；河北石家庄；河北邢台；天津北辰；天津滨海；江苏盐城滨海；北京密云', '[]', '[]', '抗日战争时期', '华北伪临时政府', '北平沦陷后投敌，任伪华北治安军总司令，组织伪军协助日军清剿抗日武装，在北平及周边地区实施“扫荡”。；原直系军阀，投日后负责华北伪军，在丰台及北平周边配合日军“扫荡”，镇压抗日武装。；在北平及丰台地区组织伪军，协助日军清剿抗日武装，镇压民众反抗。；北洋直系军阀，投日后在北平组建伪治安军（绥靖军），配合日军“扫荡”冀中、平郊抗日根据地，在大兴一带多次清剿抗日武装。；在北平及华北地区组织伪治安军，配合日军扫荡抗日根据地，捕杀抗日军民，破坏地下组织。……（共涉及85个地区的犯罪记录）；伪任职务：伪华北治安总署督办、华北治安军总司令，河北伪军总头目。结局：1946 年南京枪决', '[]', '2026-09-10 09:57:13.982943', '2026-09-10 09:57:13.982943', '北京', '东城', '大观', NULL, NULL, NULL, NULL, '');
