INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('4fd9540f58784bed934abc0745dfa6b4', '王楚卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '丽水城关（莲都）', '[]', '[]', '抗日战争时期', '', '伪职：丽水县（莲都）临时维持会会长；罪行：1942 年 6 月日军占领丽水，胁迫出任维持会会长；召集商户回城开市，为日军强征粮食、民夫、物资，办理良民证，协助日军管控城区治安。；结局：日军撤退后被第三战区逮捕，汉奸公审判处死刑执行枪决。', '[]', '2026-09-10 09:57:14.083755', '2026-09-10 09:57:14.083755', '浙江', '丽水', NULL, NULL, NULL, NULL, NULL, '');
