INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('50008bb221724c888e8ecb37a12e58bb', '贺佑民', NULL, NULL, NULL, NULL, 'exact', 'exact', '蚌埠', '[]', '[]', '抗日战争时期', '', '伪职：伪安徽省建设厅厅长；罪行：强征皖北各地民夫，为日军修筑铁路、公路、碉堡、军事工事，掠夺矿产资源资敌。；结局：汉奸清算判处有期徒刑。', '[]', '2026-09-10 09:57:14.086891', '2026-09-10 09:57:14.086891', '安徽', '蚌埠', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('500158b1d32a411597c9bce54f3b067b', '郭怀义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_长治_屯留', '[]', '[]', '抗日战争时期', '', '为日军征收苛捐杂税，强征田赋，逼死多名农民，资助日军军费。', '[]', '2026-09-10 09:57:14.024110', '2026-09-10 09:57:14.024110', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('500909c4a04d43c4b5f93ded5f29a324', '傅式说', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；浙江丽水青田；浙江丽水；湖南_娄底_新化；浙江温州乐清；浙江乐清；浙江_舟山_岱山；广西桂林资源；吉林高；浙江金华；江苏南京；浙江温州瑞安；浙江温州乐清；浙江衢州；安徽安庆；江苏南京溧水；浙江台州椒江；云南普洱西；浙江台州；浙江杭州；浙江温州乐清；浙江杭州；浙江温州乐清；云南_昆明_呈贡；浙江绍兴；浙江舟山；四川_广元；浙江_台州_临海；浙江绍兴；浙江金华；浙江_金华_东阳；浙江杭州；陕西_西安；浙江_杭州_建德', '[\"傅式悦\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪铁道部长、伪浙江省长，驻杭州，掌控浙江伪军政，掠夺工矿、粮食资源。。结局：1947 年上海高等法院判处死刑枪决；伪任职务：伪浙江省省长、杭州绥靖主任，推行清乡，搜刮浙西物资。结局：1947 年上海高等法院判处死刑枪决', '[]', '2026-09-10 09:57:13.983857', '2026-09-10 09:57:13.983857', '浙江', '温州', '乐清', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('500e4a32b5b84df1a4683c8f10a83890', '赵洛刚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '在无极推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会。', '[]', '2026-09-10 09:57:14.087631', '2026-09-10 09:57:14.087631', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('502095042e4f4a03a9db4ab1a351078e', '裴昌会', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西运城芮城；山西太原', '[]', '[]', '抗日战争时期', '', '原国民党军官，后投敌任晋南伪军顾问，参与策划对绛县、垣曲等地的‘扫荡’，为日军提供情报。；在太原伪省府任职，参与制定针对晋南地区的“治安强化”措施，协助日军清乡。；投敌后任伪河东道尹，管辖运城、临晋、猗氏等县，推行日伪“新民会”奴化教育，强征劳工送往东北和日本，并组织伪军配合日军“扫荡”中条山抗日武装。', '[]', '2026-09-10 09:57:14.023924', '2026-09-10 09:57:14.023924', '山西', '运城', '芮城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('50217330a7a4435c9ac1cdb3109179cc', '湖南伪省政府筹备人员', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南湘潭湘潭九华示范；四川南充南部', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '日军侵占湖南部分地区后，曾试图建立伪省政府，部分附逆人员参与筹备，但未能正式成立，姓名记载零散。', '[]', '2026-09-10 09:57:14.059040', '2026-09-10 09:57:14.059040', '湖南', '湘潭', '湘潭九华示范', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('502a36a4085644858cf1f7d2ffbaf27c', '黄旭初', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林平乐；云南普洱西；广西百色靖西；云南普洱西；广西梧州岑溪；广西梧州；广西南宁武鸣；云南普洱西；广西柳州城中；广西梧州万秀；广西梧州；云南普洱西；广西柳州；广西桂林兴安；云南普洱西；广西南宁江南；云南普洱西；广西百色；广西河池南丹；广西桂林；广西梧州蒙山；云南普洱西；广西南宁邕宁；广西南宁马山；广西桂林；云南普洱西；广西南宁青秀；广西桂林；广西贺州钟山；湖南郴州桂东；甘肃甘南合作；广西南宁兴宁；云南普洱西；广西_贺州；广西桂林阳朔；广西桂林；广西梧州龙圩；广西梧州；广西柳州柳南；云南普洱西；广西柳州鹿寨；云南普洱西；广西桂林叠彩；广西桂林；广西南宁良庆；广西南宁；广西桂林秀峰；广西柳州；广西梧州；广西桂林恭城；云南普洱西；广西桂林临桂；广西桂林；广西南宁上林；云南普洱西；广西贺州昭平；云南普洱西；广西桂林灌阳；云南普洱西；云南普洱西；广西玉林；云南普洱西；广西桂林资源；云南普洱西；吉林高；辽宁沈阳和平；广西梧州长洲；广西梧州；广西玉林兴业；云南普洱西', '[]', '[]', '抗日战争时期', '', '广西省主席，抗战期间广西部分沦陷区出现伪政权，参与者多与桂系旧部有关，与梧州地区有间接关联。；长期主政广西，抗战后期在日军入侵广西时，省政府撤退，部分地方政权瓦解，其下属有投敌行为，黄本人对日伪渗透应对不力，但未直接投敌。；作为桂系要员，在抗战后期广西沦陷前后有与日方接触的传闻，但历史记载存在争议，未被广泛认定为汉奸。；广西沦陷期间部分县级维持会成立，黄旭初作为省主席是否直接附逆无确证，地方档案仅见零星传闻。；桂系核心人物，抗战期间坚持抗日，未任伪职，此处仅作排除说明，非汉奸。；在广西沦陷区参与伪维持会活动，协助日军推行保甲制度与物资统制，波及梧州地区。；黄旭初为桂系核心人物，抗战期间主政广西，坚持抗日，非汉奸。；广西省政府主席，抗战期间与日方有秘密接触传闻，但未公开投敌，历史评价存在争议，非典型汉奸。；抗战期间长期主政广西，虽与蒋系有矛盾，但坚持抗日立场，未附逆；日伪曾试图拉拢其出任伪职，遭拒绝。；日军入侵广西时曾试图拉拢其出任伪职，但其未就任，相关记载多见于日方档案，实际未附逆。；部分资料称其在桂林沦陷前后与日方有接触，但主流记载其随桂系撤退，未附逆；此条存疑，不宜作为确定汉奸。；日军入侵广西期间，一度参与伪广西省政府活动，协助日军维持地方统治。；抗战后期桂系与日方有秘密接触，黄旭初作为桂系核心人物之一，曾参与相关谈判，但最终未公开附逆。；抗战后期日军入侵广西时，黄旭初作为桂系要员曾一度与日方有接触，但最终未公开投敌，其行为在战后受到调查。；抗战后期，日军入侵广西，黄旭初作为桂系要员曾一度与日方有接触，但最终未公开投敌，其行为在战后受到调查。；桂系要员，抗战后期曾与日军暗中接触，谋求保存实力，但未公开投敌，故严格意义上不属汉奸，仅列作相关人物。；桂林沦陷后，部分桂系人员被日军胁迫或利用参与维持会活动；黄旭初相关附逆情形在部分史料中有争议记载，常被列入广西沦陷区伪组织关联人物。；抗战后期曾与日军方面接触，商讨所谓“广西自治”事宜，后因形势变化未公开附逆，但留有通敌嫌疑。；桂林、柳州沦陷后，广西部分地方政权人物与日军合作传闻，黄旭初被部分资料提及，但缺乏确证。；日军曾试图拉拢其合作，但其拒绝，坚持抗日立场。；日军侵占广西期间，日方曾试图拉拢其出面组织伪省政府，黄旭初未附逆，但日伪档案中列为其拟任伪省主席人选。；日军侵占南宁期间，与日伪合作，参与伪经济机构，为日军掠夺广西物资、控制占领区经济提供协助。；广西沦陷时期与日伪有联系，被指参与维持会活动，协助日军维持地方秩序，但史料记载有限。；新桂系主要人物，抗战时期主政广西，属国民政府地方实力派，并非汉奸；此处列出以说明广西伪政权史料中常被混淆的背景人物。；有传闻称日军曾诱其出任伪职，但黄旭初实际未附逆；此条为争议性记录，需进一步考证。；抗战后期广西部分沦陷时，被日军利用名义上参与伪政权维持活动，相关记载多见于广西沦陷区伪组织材料。；抗战后期桂林沦陷后，日军曾试图拉拢其出面组织伪政权，黄旭初虽未公开投敌，但曾与日方进行过接触和谈判，在广西伪政权筹建过程中态度暧昧。；抗战期间长期主政广西，与日方有秘密接触，但未公开投敌，战后被列为附逆嫌疑人物。；抗战后期曾与日军方面接触，商讨“和平”条件，虽未正式就任伪职，但被视为广西高层附逆倾向人物。；汪精卫伪政权曾任命其为伪广西省政府主席，试图在广西建立伪政权，但黄旭初并未实际赴任，其任命更多具有象征性。；桂林沦陷后留在广西，与日伪有经济合作往来，被指为日伪筹措物资，战后受到调查。；广西省主席，抗战期间长期主政广西，与日伪有接触传闻，但未正式投敌，史料存争议。；桂系主政广西，梧州属其辖区，但未任伪职，此处仅作背景排除。；黄旭初主政广西期间坚持抗日，但梧州沦陷后地方维持会多由当地士绅出面组织。；在广西沦陷区参与伪维持会活动，协助日军推行殖民统治，活动范围涉及梧州地区。；汪伪政权曾试图拉拢其出任伪广西省主席，黄旭初未就任，但日伪在广西沦陷区曾以其名义进行宣传。；抗战后期汪伪政权为渗透广西，曾委任其为伪广西省政府主席，试图在桂西、百色一带建立伪政权，因日军未能长期控制广西全境而未实际履职，但其名义上的附逆行为被记录。；桂系核心人物之一，抗战后期在广西沦陷期间曾与日军有妥协接触，其部下在桂林、柳州等地组织维持会，虽未正式投敌，但相关附逆行为有记载。；无可靠史料证明其附逆，不应列为汉奸。；广西部分沦陷期间，被指参与伪维持会活动，协助日军在梧州一带推行伪化统治。；抗战后期日军入侵广西时，黄旭初曾一度动摇，后虽未公开投敌，但其部属在桂东地区与日伪有接触。需注意：黄旭初并非严格意义上的汉奸，此条存疑，建议核实。；投靠汪伪，任伪广西省财政厅厅长，为伪政权筹措经费，剥削民众。；广西省政府主席，抗战后期在日军入侵广西、桂林沦陷前后，曾出现与日方接触、谋求地方自保的传闻与记载，但未公开投敌，历史评价复杂，常被列入广西沦陷时期附逆嫌疑人物讨论。；有史料称其在日军第二次侵桂期间一度与日方接触、参与维持地方秩序，但此说争议较大，主流记载其仍属桂系抗日阵营，需谨慎对待。；抗战期间任广西省政府主席，未附逆，不属于汉奸。；新桂系成员，在日军入侵广西期间动摇投敌，参与伪政权活动，协助日军维持地方秩序，具体职务记载不一，但被列为广西附逆人员。', '[]', '2026-09-10 09:57:14.030941', '2026-09-10 09:57:14.030941', '广西', '南宁', '上林', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5038b9b8d6894d758cd2fb6659378505', '徐绍南', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京雨花台；江苏泰州姜堰；江苏泰州', '[]', '[]', '抗日战争时期', '', '在泰州、姜堰地区为日军搜集新四军及抗日武装情报，参与破坏抗日地下组织。；在江苏任伪警务头目，协助日军维持治安。', '[]', '2026-09-10 09:57:14.033808', '2026-09-10 09:57:14.033808', '江苏', '南京', '雨花台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('505211ec13be423aa69c0a8f01fdaaee', '桑文海', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山靖宇', '[]', '[]', '抗日战争时期', '', '长期参与对靖宇地区抗联部队的“围剿”，多次率伪警察搜山、烧毁密营，逮捕抗联交通员，并参与对杨靖宇牺牲后遗体的辨认和处置。', '[]', '2026-09-10 09:57:14.000043', '2026-09-10 09:57:14.000043', '吉林', '白山', '靖宇', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('505374ca88f5442aa37dbb1c8941fed4', '陈国钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；湖北宜昌；湖北天门；重庆酉阳；浙江湖州德清；黑龙江黑河北安；湖南_益阳_安化；湖南益阳；吉林长春农安；黑龙江佳木斯郊区；湖南益阳桃江；湖南益阳；湖南岳阳岳阳楼；湖南岳阳；湖北咸宁通山；湖北荆州洪湖；湖北荆门', '[]', '[]', '抗日战争时期', '', '在长春县（今长春郊区）强征壮丁，推行“连坐”制度，镇压农民反抗。', '[]', '2026-09-10 09:57:14.000870', '2026-09-10 09:57:14.000870', '吉林', '长春', '农安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5057c0c129074aad97a22fceac7a45d5', '刘子玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城；山东济宁；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '主持伪新民会，进行亲日宣传，推行奴化教育，协助日军控制民众思想。；在聊城伪警察局任职，带领伪警察配合日军搜捕抗日人员，镇压群众反抗。', '[]', '2026-09-10 09:57:14.015377', '2026-09-10 09:57:14.015377', '山东', '济宁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('50593f9d0cb24a5384ae1517aa500aa6', '齐默特色木丕勒', NULL, NULL, NULL, NULL, 'exact', 'exact', '郭尔罗斯前旗；前郭尔罗斯前旗（哈拉毛都王府）', '[]', '[]', '抗日战争时期', '', '伪职：郭尔罗斯前旗札萨克亲王，伪满蒙政部大臣、兴安总署总长；罪行：参与炮制伪满洲国，签署伪东北行政委员会独立宣言；带头将蒙地献给伪满，配合日本推行蒙地掠夺，庇护日本特务，协助日本对蒙东地区殖民统治抖音百科。；结局：1942 年病死于王府，未等到抗战审判。；伪职：伪满蒙政部大臣，哲里木盟盟长；投靠伪满，协助日军控制哲里木各旗，强征牲畜粮草，推行殖民统治。；结局：1942 病死长春', '[]', '2026-09-10 09:57:14.079700', '2026-09-10 09:57:14.079700', '吉林', '松原', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('505f56efa1774270b4a974937e45b84e', '薛玉衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪西安县第三任县长；罪行：强化治安肃正，执行粮食出荷，为煤矿强征劳工。；结局：战后汉奸罪判刑。', '[]', '2026-09-10 09:57:14.073606', '2026-09-10 09:57:14.073606', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5065df30b3d047fc9968bd2885bbada3', '郭清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；河北邯郸临漳；河北邯郸；河南安阳滑县；河南安阳；河南濮阳南乐；福建泉州南安；河北邯郸广平；河北邯郸；陕西咸阳彬州；青海黄南河南；河北邯郸肥乡；河南安阳安阳高；河南安阳；河南鹤壁鹤壁经开区；河南安阳；河北邢台威县；河北邢台信都；河南安阳汤阴；河北邯郸馆陶；河北邯郸；山西、河北；河北邯郸鸡泽；河北邯郸大名；河南安阳北关；河南安阳；山西吕梁汾阳；临漳；河南鹤壁鹤山；河南安阳汤阴；河南安阳殷都；河南安阳；河北邯郸武安；河北邯郸魏县；河北邯郸大名；河南安阳内黄；河北邯郸临漳；河北邯郸永年；河北邯郸临漳；河南鹤壁浚县；河南安阳', '[]', '[]', '抗日战争时期', '', '负责在汾阳推行奴化教育，宣传‘中日亲善’，强迫民众参加反共集会，收集抗日情报。；在信都区西部组织地主武装，配合日军封锁山区，杀害抗日村干部。；充当日军特务，专门刺探八路军情报，破坏抗日组织，诱捕并杀害多名地下党员，手段残忍，民愤极大。；长期盘踞邯郸、永年一带，勾结日军，袭击抗日武装，残害百姓，强征壮丁。；在邯郸、临漳一带活动，为日军搜集情报，参与围剿八路军游击队，残害抗日家属。……（共涉及17个地区的犯罪记录）；伪职：土匪投敌，伪冀南剿共独立旅旅长；贾河口为大本营，烧杀掳掠，制造多起村庄惨案，大肆捕杀抗日军民，设立剿共委员会迫害群众。；结局：1949 年被俘，公审枪决', '[]', '2026-09-10 09:57:14.020514', '2026-09-10 09:57:14.020514', '山西', '吕梁', '汾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5074b4487834457f896d5ca767db713b', '王世杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽池州；河南驻马店；湖北黄石下陆；山西阳泉矿区；安徽池州；山西阳泉城区；河南驻马店；河南驻马店确山；重庆_涪陵；湖北咸宁嘉鱼；湖北咸宁；安徽池州东至；安徽池州；安徽池州青阳；安徽池州石台；江西上饶；安徽铜陵铜官；安徽铜陵；湖北黄石黄石港', '[]', '[]', '抗日战争时期', '', '黄石港本地人，抗战期间担任伪保甲长，为日军征收粮食、税款，登记户口，协助日军控制黄石港居民，举报抗日嫌疑人员。；池州沦陷后出面组织伪维持会，任会长，协助日军建立伪政权，征发民夫、物资，推行保甲制度，为日军统治池州地区服务。；组建伪警察队，配合日军搜捕抗日分子，镇压当地民众反抗。；贵池（今池州市区）人，日军占领贵池后投敌，先后任伪维持会会长、伪县长，管理伪政权，为日军征粮征税、推行保甲，其辖区与青阳相邻，对青阳地区伪政权有影响。；确山沦陷后出面组织维持会，替日军征粮派款，镇压抗日群众。；驻马店镇本地商人，日军占领驻马店后组织维持会，协助日军管理车站、码头及物资转运，为日军提供情报和后勤支持。；率伪保安大队配合日军对铜陵、铜官山一带进行扫荡，搜捕抗日人员，强征民夫为日军采矿、修路。；汪伪政权委任的贵池县县长，在池州城区及周边推行保甲制度，征发民夫、物资供给日军，镇压抗日群众。；在黄石港伪警察局任职，配合日军搜捕抗日人员，镇压当地民众反抗。；青阳人，日军占领青阳后投敌，历任伪维持会长、伪县知事，在青阳、石台交界地区推行伪化统治，配合日军清乡，搜捕抗日人员。；嘉鱼人，咸宁周边地区汉奸，日军侵占嘉鱼后组织维持会，协助日军控制长江沿岸。；江西上饶人，上饶沦陷期间任伪保安队长，率伪军配合日军“扫荡”抗日武装。；石灰窑（今黄石市区）沦陷后组织维持会，为日军服务，协助管理石灰窑工矿区。', '[]', '2026-09-10 09:57:14.008506', '2026-09-10 09:57:14.008506', '安徽', '池州', '东至', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('507bc0cd526c4cd796b68b16cef886b8', '魏乐道', NULL, NULL, NULL, NULL, 'exact', 'exact', '伊川县', '[]', '[]', '抗日战争时期', '', '伪职：日伪白沙警察局大队长；罪行：韦子斌下属，与韦子斌面和心不和；结局：被抗日武装争取为内线', '[]', '2026-09-10 09:57:14.086114', '2026-09-10 09:57:14.086114', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
