INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('50f309aab0a540e28dccf68d8b93d233', '方瑞麟', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东潮州；广东揭阳', '[]', '[]', '抗日战争时期', '', '在惠来组织伪政权，与揭阳伪政权协同，协助日军封锁沿海，阻断抗日物资运输。；掌管伪警察系统，搜捕抗日人士，配合日军维持汕头市区治安。；在潮汕沦陷区联络各地伪维持会，为日军筹款筹粮，协助经济掠夺。', '[]', '2026-09-10 09:57:14.027743', '2026-09-10 09:57:14.027743', '广东', '揭阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('50f5927f25394e9a83bcb3ec7a94f9a9', '王五', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴海盐；浙江嘉兴平湖；浙江嘉兴；山西吕梁兴县；浙江嘉兴嘉善', '[]', '[]', '抗日战争时期', '', '投靠日军，任海盐县维持会会长及伪县长，协助日军征粮、拉夫，镇压抗日民众，曾指使汉奸队袭击新四军游击队。；任伪嘉兴县知事期间，协助日军推行‘清乡’政策，强征粮食，镇压抗日民众。；在日军占领期间出任伪平湖县知事，协助日伪推行‘清乡’政策，强征民夫，搜刮粮食，镇压抗日活动。；日军占领嘉善后出任维持会长，协助日军征粮、拉夫，镇压抗日民众，提供情报。', '[]', '2026-09-10 09:57:14.050272', '2026-09-10 09:57:14.050272', '浙江', '嘉兴', '嘉善', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5109f21c3e9a4158b726a598d36b555e', '陈渠珍', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化溆浦；湖南怀化；湖南湘西凤凰；湖南常德津；云南普洱西；湖南湘西永顺；云南普洱西；湖南益阳；云南普洱西；湖南湘西泸溪；湖南湘西龙山；云南普洱西；湖南张家界桑植；湖南张家界；甘肃甘南合作', '[]', '[]', '抗日战争时期', '', '湘西地方实力派，抗战后期与日伪方面有秘密接触，但未公开投敌，历史评价复杂。；在湘西地区组织伪自治委员会，协调各县伪维持会为日军服务，包括怀化、溆浦等地的伪维持会活动。；无；湘西凤凰人，长期统治湘西地区，抗战期间虽名义上抗日，但与日伪方面有暧昧接触，保持地方割据，未积极抗日。；湘西地方实力派，抗战时期曾与日伪方面有联系，在湘西地区保持独立势力，对抗中央政府抗日政策。；湖南凤凰人，湘西地方实力派，抗战后期在日军诱降下曾与日方接触，一度接受伪湘西自治军总司令名义，后因形势变化未完全公开附逆。；湘西地区投靠日军的头面人物，组织维持会，协助日军控制湘西部分区域。；湘西地方实力派，抗战期间曾与日伪方面有秘密接触，其部属在湘西部分地区与伪军合作，但本人是否正式投敌存在争议。；湘西地方实力派，抗战时期曾与日军及伪政权有暧昧关系，其势力范围覆盖湘西包括张家界、桑植地区，在日军进攻湘西时未积极抵抗，部分部下投敌。；湘西凤凰人，长期统治湘西，抗战期间与日伪方面有暗中联系，其部属在湘西地区有附逆行为，本人被指态度暧昧。；湘西地方实力派，抗战期间曾与日伪方面有秘密接触，日方拟委其为伪湘西绥靖公署主任，后因形势变化未公开就任。', '[]', '2026-09-10 09:57:14.058234', '2026-09-10 09:57:14.058234', '湖南', '常德', '津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('511506a2b0954762b1bccdad809607aa', '耿梦梅', NULL, NULL, NULL, NULL, 'exact', 'exact', '平遥', '[]', '[]', '抗日战争时期', '', '伪职：伪平遥县县长；罪行：建立平遥伪县公署，管控同蒲铁路，推行保甲十家连坐，压榨城乡百姓。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.070886', '2026-09-10 09:57:14.070886', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5118243cccc24d62a7fb302c9773d6c2', '马步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄石家庄高；河北石家庄平山', '[]', '[]', '抗日战争时期', '', '在平山协助日军封锁抗日根据地，组织伪军袭击八路军后方，破坏生产。', '[]', '2026-09-10 09:57:14.043678', '2026-09-10 09:57:14.043678', '河北', '石家庄', '石家庄高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('511bbe176cd843cbbb70dd9fa6150d34', '赵维周', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州静乐', '[]', '[]', '抗日战争时期', '', '充当日军爪牙，主持伪警察所，负责清查抗日分子，破坏地下交通线，曾亲自带队逮捕多名抗日群众并施以酷刑。', '[]', '2026-09-10 09:57:14.022134', '2026-09-10 09:57:14.022134', '山西', '忻州', '静乐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5126547998e24f1c8cc6195b4044d824', '汪翱', NULL, NULL, NULL, NULL, 'exact', 'exact', '长兴、太湖西南沿岸', '[]', '[]', '抗日战争时期', '', '伪职：伪苏浙皖三省边区剿匪指挥官；罪行：原我方人员叛变投敌，手握伪军武装，四处游说抗日武装投降，扫荡长兴山区抗日根据地，残害爱国军民。；结局：1939 年被长超抗日义勇军诱捕处决。', '[]', '2026-09-10 09:57:14.086286', '2026-09-10 09:57:14.086286', '浙江', '湖州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('512696c540144fd9bd4fb702716c9d62', '王庆璋', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州滨江；辽宁_沈阳；辽宁大连瓦房店；辽宁大连；山西大同平城；辽宁丹东凤城；辽宁丹东；辽宁抚顺东洲；辽宁抚顺；黑龙江哈尔滨；吉林长春长春净月高；辽宁_沈阳_大东；黑龙江哈尔滨松北；辽宁沈阳；辽宁_沈阳_和平；辽宁大连；吉林长春；辽宁_沈阳_铁西；吉林松原扶余；吉林、辽宁；辽宁新宾；吉林；吉林通化；辽宁阜新细河；辽宁阜新', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪奉天市（沈阳）市长、伪满邮政总局局长。结局：1950 年逮捕，1958 年病亡抚顺狱中；在长春市区残酷镇压抗日活动，逮捕爱国人士。；参与净月地区“归屯并户”，制造无人区，切断抗日联军与群众联系。；原安东商人，投日后任伪满安东省经济警察，在丹东、凤城地区协助日军统制粮食、棉花等物资，欺压百姓。；曾任大连商会会长，投日后任伪大连市市长，协助日本控制大连港及殖民经济。；辽宁大连人，投靠日本殖民当局，任伪大连市长，管理港口及殖民事务。……（共涉及14个地区的犯罪记录）；伪职：伪怀德县（公主岭）县长；罪行：怀德是产粮大县，执行高压粮食出荷，强征国兵劳工。；结局：战后逮捕判刑。', '[]', '2026-09-10 09:57:13.997558', '2026-09-10 09:57:13.997558', '吉林', '长春', '长春净月高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('51290498a98c44399c3a5af1adcae566', '高凤阁', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江双鸭山宝清；黑龙江佳木斯桦川；黑龙江佳木斯；黑龙江鸡西密山', '[]', '[]', '抗日战争时期', '', '负责佳木斯地区特务工作，建立情报网，破坏抗联地下联络站，导致多名抗联干部被捕牺牲。；组织“协和会”宣传奴化思想，搜集抗日情报，告密抗联活动，协助日军逮捕地下党员和爱国群众。；为日军掠夺粮食和农产品，强迫农民“出荷”，对反抗者进行报复，勾结日伪军围剿抗联小分队。', '[]', '2026-09-10 09:57:14.065591', '2026-09-10 09:57:14.065591', '黑龙江', '佳木斯', '桦川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('512bef9e2d844de0b8da712a86a99863', '罗亚杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '潍县', '[]', '[]', '抗日战争时期', '', '伪职：伪宣抚班成员；罪行：东北人，阴险毒辣。每逢大集就换上便衣到集上搜寻游击队，认为谁有嫌疑就带到宣抚班拷打审问', '[]', '2026-09-10 09:57:14.087661', '2026-09-10 09:57:14.087661', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('51360159126a4d78bc6af68f1a184ccb', '罗活', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州；广西_玉林；广西梧州万秀；广西梧州；广西桂林临桂；云南普洱西；广西桂林；广西梧州藤县；广西梧州', '[]', '[]', '抗日战争时期', '', '广西沦陷期间，率伪保安队协助日军维持占领区，参与清乡与搜捕抗日人员。；日军占领梧州后，以商会名义为日军筹款筹粮，组织商户附逆，支持日伪经济掠夺。；抗战后期率部投敌，被日军委任为伪保安司令，配合日军进攻抗日根据地。；梧州沦陷期间，参与伪警察组织，协助日军搜捕抗日人员、维持治安。；在桂林沦陷期间担任伪警察局长，指挥伪警察配合日军搜查、逮捕抗日分子，实施保甲连坐。；梧州沦陷期间出任伪警察局长，协助日军搜捕抗日人士、维持治安。；梧州沦陷时期出任伪警察局长，配合日军搜捕抗日人员、镇压民众反抗。', '[]', '2026-09-10 09:57:14.031965', '2026-09-10 09:57:14.031965', '广西', '桂林', '临桂', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('51381c4017964d97b5efaae5ddedb75c', '石友信', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北衡水；濮阳全县', '[]', '[]', '抗日战争时期', '', '伪职：伪六十九军师长（石友三之弟）；罪行：1940年3月代表石友三到开封会见日本驻军司令官佐佐木，签订投降协定；结局：与石友三同时死亡', '[]', '2026-09-10 09:57:14.044456', '2026-09-10 09:57:14.044456', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('513831903b02474b85a3df006e98eacd', '张凤阁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北秦皇岛青龙；河北承德鹰手营子矿；河北；河北沧州；河北沧州海兴', '[]', '[]', '抗日战争时期', '', '在鹰手营子矿区一带设卡盘查，抓捕抗日交通员，参与多次突袭抗日根据地的行动。；在海兴县为日军效命，组织伪军封锁沿海，破坏抗日交通线。；指挥伪警察队配合日军“扫荡”抗日根据地，抓捕并杀害抗日干部和群众，破坏中共地下组织，参与制造多起惨案。', '[]', '2026-09-10 09:57:14.042933', '2026-09-10 09:57:14.042933', '河北', '承德', '鹰手营子矿', NULL, NULL, NULL, NULL, '');
