INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('51e2da7e25b1458a8a3c6e8e05e6a742', '朱坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉新洲；湖北武汉；湖北孝感孝昌；湖北孝感应城；湖北孝感安陆；湖北孝感；湖北孝感', '[]', '[]', '抗日战争时期', '', '应城沦陷后投敌，任伪县长，控制应城膏盐资源为日军服务，镇压抗日群众。；任伪孝感县县长期间推行保甲连坐，配合日军清乡，镇压抗日群众。；在伪政权中负责教育，推行奴化教育，篡改教材，向学生灌输亲日思想。；在黄冈地区参与伪维持会活动，协助日军维持地方秩序、摊派物资，为日伪在武汉东部地区的统治提供地方支持。', '[]', '2026-09-10 09:57:14.055751', '2026-09-10 09:57:14.055751', '湖北', '孝感', '孝昌', NULL, NULL, NULL, NULL, '');
