INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('52268bfeb6f947308dfe47e03b6a92cf', '金铭世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁辽阳文圣；辽宁朝阳北票；吉林、辽宁；辽宁朝阳建平；辽宁朝阳；吉林通化；吉林白山抚松；吉林桦甸', '[]', '[]', '抗日战争时期', '', '在任期间强征劳工修建警备道路和碉堡，为日军提供粮食和物资，并组织汉奸情报网，破坏抗日地下组织。；协助日军管理北票煤矿，强迫中国矿工劳动，虐待致死无数，提供煤炭支持侵华战争。；在朝阳县推行“治安肃正”，组织汉奸特务队，残害抗日群众。；在辽阳文圣区组织维持会，协助日军建立秩序，强征民夫修筑军事工事，并告密抗日活动。', '[]', '2026-09-10 09:57:13.999183', '2026-09-10 09:57:13.999183', '吉林', '桦甸', '抚松', NULL, NULL, NULL, NULL, '');
