INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5271b39ed9ed4cbb965c9d052a8f6bcc', '贺遐昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '竹溪县；湖北_武汉_武昌；湖北武汉；武汉（伪湖北省）；湖北孝感', '[]', '[]', '抗日战争时期', '', '伪职：伪汉口市政府秘书长、伪湖北省政府委员、秘书长；罪行：湖北竹溪人。汪伪政府时期历任汉口市政府秘书长、湖北省政府委员、秘书长。何佩瑢死后曾代理湖北省政府主席数月，是十堰地区在汪伪政权中任职级别最高的汉奸；结局：抗战胜利后被捕，具体结局待考；伪职：伪省市府秘书长、伪武汉参议府参议；罪行：湖北竹溪人。何佩瑢死后代理湖北省政府主席数月；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.055797', '2026-09-10 09:57:14.055797', '湖北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5272c8aac3ef4d8480d16c6f223ba150', '殷汝耕', '亦农', NULL, 1885, 1947, 'exact', 'exact', '安徽蚌埠淮上；安徽蚌埠；北京石景山；北京门头沟；北京大兴；北京_东城；北京丰台；北京_西城；天津河北；河北廊坊；河北秦皇岛；云南昆明呈贡；内蒙古_呼伦贝尔_牙克石；天津宝坻；安徽安庆；山东济南；山东济宁；云南普洱西；江苏南京鼓楼；河北唐山；天津河北；河北廊坊；河北张家口；河北承德；重庆_大足；重庆_永川；重庆沙坪坝；山西太原示范；陕西_西安；陕西_西安_长安；河北秦皇岛；河北唐山曹妃甸；河北唐山；北京朝阳；吉林长春朝阳；天津北辰；湖南常德津；天津武清；北京昌平；河北石家庄石家庄高；河北石家庄；北京平谷；北京顺义；天津宁河；天津_蓟州；江苏南通通州；河北秦皇岛；河北廊坊；河北廊坊香河；天津和平；湖南常德津；河北唐山；江苏南京浦口；北京延庆；北京海淀；江苏南京浦口；江苏南京；北京、天津、河北；北京通州；江苏南通通州；天津静海；浙江平阳；天津滨海；江苏盐城滨海；北京密云', '[]', '[]', '抗日战争时期', '伪冀东防共自治政府 / 汪伪政权；华北伪临时政府', '伪任职务：冀东防共自治政府主席，割据冀东 22 县，华北最早傀儡政权头目抖音百科。结局：1947 年南京被执行死刑；伪职：伪冀东防共自治政府行政长官，冀东头号大汉奸，伪政权后期机关迁唐山交大，分割冀东 22 县，推行殖民统治，镇压抗日运动唐山党史网。；结局：1947 南京判处死刑枪决；1935年成立伪冀东防共自治政府，管辖包括北平东部地区，后并入伪中华民国临时政府，长期为日本侵略服务。；早年在冀东成立伪政权，其势力范围曾涉及北平近郊及丰台一带，为日军提供情报和后勤支持。；在冀东（含丰台周边）成立伪政权，脱离国民政府，为日军提供后勤与情报支持。；早年在冀东成立伪政权，后活动于北平，协助日军控制平津地区，参与对大兴等县的伪化统治，推行保甲制度。；在冀东及北平周边地区建立伪政权，为日军提供情报和后勤支持，协助日军控制平津地区。……（共涉及83个地区的犯罪记录）；殷汝耕，字亦农，浙江平阳人。早年留学日本，毕业于早稻田大学，娶日本女子为妻。北洋时期服务于各系军阀。1935年11月25日在河北通县成立「冀东防共自治委员会」，后改称「冀东防共自治政府」，任主席，是抗战前第一个公开独立的汉奸政权。1947年12月1日在南京老虎桥监狱被执行枪决。', '[]', '2026-09-10 09:57:13.981454', '2026-09-10 09:57:13.981454', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('527635e4603a432e85c4d16a5236b361', '林康侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海浦东；上海杨浦', '[]', '[]', '抗日战争时期', '', '为日伪在杨浦地区工厂提供金融支持，协助发行军用票，掠夺资源。；协助日伪在浦东推行金融统制，发行伪币，掠夺民间财富。', '[]', '2026-09-10 09:57:13.977229', '2026-09-10 09:57:13.977229', '上海', '杨浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('527939c932bc4c2c8afc4d2f210c6bce', '袁金铠', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林经开区；吉林；广西桂林资源；辽宁沈阳法库；辽宁鞍山；吉林四平；黑龙江_齐齐哈尔_泰来；辽宁沈阳沈河；辽宁辽阳；辽宁大连中山；甘肃甘南合作；辽宁_大连_长海；辽宁沈阳；辽宁_沈阳_和平；辽宁盘锦双台子；辽宁盘锦；辽宁_营口_大石桥；黑龙江_哈尔滨_松北；吉林长春朝阳；吉林_高；辽宁辽阳；辽宁沈阳；辽宁_沈阳_浑南；吉林长春德惠；吉林长春；吉林长春；辽宁大连；辽宁辽阳；辽宁_大连_金州；辽宁铁岭开原；辽宁铁岭；辽宁大连庄河；吉林长春宽城；辽宁辽阳灯塔；河北承德；辽宁_辽阳；辽宁鞍山；吉林高；辽宁_沈阳_大东；辽宁铁岭；吉林长春农安；辽宁铁岭西丰；辽宁铁岭；吉林长春南关；吉林长春；辽宁_沈阳_苏家屯；吉林长春长春汽车经开区；吉林长春；辽宁辽阳；辽宁鞍山；吉林、河北、辽宁；辽宁锦州凌河；辽宁锦州；辽宁锦州北镇；辽宁锦州；辽宁大连；辽宁沈阳；辽宁沈阳；辽宁辽阳白塔；辽宁_鞍山_千山；吉林长春；辽宁锦州；辽宁阜新；辽宁_大连_瓦房店；辽宁_抚顺；广西桂林资源；辽宁_抚顺_望花；辽宁_抚顺_顺城；辽宁阜新太平；辽宁阜新；辽宁沈阳铁西；吉林四平伊通；吉林；辽宁_丹东_凤城；辽宁_丹东_振安；辽宁_葫芦岛；山西阳泉矿区；黑龙江齐齐哈尔；吉林；辽宁沈阳；辽宁_辽阳_宏伟；辽宁_葫芦岛_龙港；辽阳山岳铺；吉林长春双阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪奉天维持会委员长、伪满尚书府大臣、参议府参议；罪行：九一八牵头组建奉天维持会，协助日军接管辽沈，参与策划伪满洲国，推行保甲，镇压东北反日力量，辽阳本地广置田产。主要任职沈阳、长春，非辽阳本地履职抖音百科。；结局：1945 年被列为大汉奸，家产抄没，1947 年病死辽阳，逃脱审判人民网文化...。；伪职：奉天地方治安维持会委员长；伪满尚书府大臣、参议府参议；罪行：九一八事变后立刻牵头组建奉天维持会，协助日军接管沈阳，恢复伪政权，参与策划伪满洲国建立，推行保甲，镇压反日活动。；结局：1945 年被捕，保外就医，1947 年病死，逃脱审判。；伪任职务：奉天治安维持会委员长、伪满尚书府大臣，沈阳最早附逆高层，协助日军接收沈阳政权。结局：1945 年被捕，保外就医，1947 年病死；原奉系官僚，在四平地区参与伪政权建设，协助日军推行“治安肃正”计划。；原奉系政客，投日后任伪满参议府议长，在吉林、四平一带鼓吹“日满亲善”，协助日军稳定殖民秩序。；原奉系官僚，投日后在伪满中枢任职，参与起草和推行奴化政策，活跃于长春政治圈。；虽主要任奉天职务，但多次在长春参与伪满中央政务，积极推动东北傀儡化；在伪满中央任职，参与起草诏书和礼仪制度，为傀儡政权服务。……（共涉及67个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.996746', '2026-09-10 09:57:13.996746', '吉林', '四平', '泰来', NULL, NULL, NULL, NULL, '');
