INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5297ef25a0df4f5599ae79ed8755a120', '夏孝义', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁陆郎花塘', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：陆郎独立警备队头目，原游击队员叛变投敌；盘踞陆郎据点，招募散兵，多次扫荡横山根据地，残害抗日军民，谈判劝降拒不悔改。。结局：1944??08??21 新四军四十六团攻坚，击毙于据点内南京雨花台...', '[]', '2026-09-10 09:57:14.077600', '2026-09-10 09:57:14.077600', '江苏', '南京', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('529e9a70cc4f4545933d328654dd0198', '陈子兴', NULL, NULL, NULL, NULL, 'exact', 'exact', '亳县三区', '[]', '[]', '抗日战争时期', '', '伪职：叛变区队长；罪行：原我方人员叛变，出卖地下党员纵食力、王金铎等人，投靠日伪充当帮凶。；结局：被抗日民主政府锄奸处决。', '[]', '2026-09-10 09:57:14.081856', '2026-09-10 09:57:14.081856', '安徽', '亳州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('529f2e25e3394e52a9beb91f60d7e492', '赵晋三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城高平；山西；山西运城新绛；山西运城河津；山西临汾安泽；江苏徐州沛县', '[]', '[]', '抗日战争时期', '', '日军初占安泽时，率先组织维持会，为日军筹集粮款，并劝诱乡绅投敌，破坏抗日统一战线。；任伪安泽县保安队队长，率伪军多次“清乡”，在安泽山区搜捕抗日军民，杀害多名八路军伤员和村干部。；主持伪警察局，协助日军进行“治安强化运动”，搜捕抗日军民，实施“连坐”制度，残害无辜百姓。；强制学校改用日伪教材，强迫学生参加日军庆典，检举抗日教师。；为日军征收苛捐杂税，贪污抗日物资，逼迫农民交出粮食支援日军。', '[]', '2026-09-10 09:57:14.018936', '2026-09-10 09:57:14.018936', '山西', '临汾', '安泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('52af860be77048e68ddbfef554e283f7', '周文卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州；湖北十堰；湖北恩施；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '湖北十堰人，抗战期间投敌，任伪十堰地区经济科科长，协助日军搜刮物资，压榨民众。；率伪保安队多次袭击新四军交通站，抓捕并杀害抗日志士，抢劫百姓财物，罪行累累。；宜昌地区投敌分子，组织伪维持会，协助日军管理宜昌城区及周边乡镇。', '[]', '2026-09-10 09:57:14.051589', '2026-09-10 09:57:14.051589', '浙江', '湖州', NULL, NULL, NULL, NULL, NULL, '');
