INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53b5885e3b004a9f8207113511eb0d0a', '王起模', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门思明；辽宁沈阳大东；辽宁沈阳大东；福建_厦门_海沧；福建厦门翔安；福建龙岩；福建泉州安溪；福建泉州', '[]', '[]', '抗日战争时期', '', '日军侵扰龙岩时出面组织维持会，为日军带路、征夫征粮。；在伪政权中负责社会团体与民众控制，配合日军宣传与奴化教育。；在福建沦陷区依附日伪，参与伪政权行政事务，协助日军统治。；在厦门推行奴化教育，协助日军控制学校、篡改教材、宣传所谓‘大东亚共荣圈’。；泉州沿海地区沦陷期间，出面组织伪维持会，为日军筹粮筹款，协助维持地方治安，属泉州地区直接附逆者。；在厦门推行奴化教育，篡改教材，宣传所谓‘大东亚共荣圈’，毒化厦门及思明地区青年。', '[]', '2026-09-10 09:57:14.061020', '2026-09-10 09:57:14.061020', '福建', '厦门', '思明', NULL, NULL, NULL, NULL, '');
