INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53ea77957714417bb56aac220236b1cf', '陈鸿文', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建莆田涵江；福建莆田', '[]', '[]', '抗日战争时期', '', '在日军扶植下出任伪莆田县知事，推行伪化教育，配合日军清乡、征粮，镇压抗日群众，是莆田地区伪政权主要头目之一。；在日军扶植下出任伪莆田县知事，推行伪化教育，征发民夫物资供应日军，配合日军清乡扫荡，镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.062403', '2026-09-10 09:57:14.062403', '福建', '莆田', '涵江', NULL, NULL, NULL, NULL, '');
