INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53ee151ed5b44f04acd30ba830fd0a88', '陈继善', NULL, NULL, NULL, NULL, 'exact', 'exact', '化德', '[]', '[]', '抗日战争时期', '', '伪职：伪化德县县长；此地为早期伪蒙古军政府驻地，执行日伪政令，为德王、李守信征集物资兵源。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.072878', '2026-09-10 09:57:14.072878', '内蒙古', '乌兰察布', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53ee1d20be74485bb5070049097530d0', '萧叔萱', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西宝鸡；江苏南京；江苏南京江宁；安徽芜湖；安徽芜湖镜湖；安徽芜湖；江苏南京鼓楼；江苏南京浦口；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '在芜湖设立警察训练所，培养汉奸警察，镇压民众。；参与策划伪军对抗日根据地的进攻，涉及江宁地区。；汪伪政权军事要员，协助日军作战，其活动与陕西宝鸡抗日后方有间接关联。；在南京协助管理伪军，参与清剿新四军等抗日武装。；在南京鼓楼区参与伪军事务，为日军提供军事咨询。；汪伪军事要员，参与伪军整编；负责安徽伪警察系统，在芜湖设立特务据点，逮捕抗日人士，实施白色恐怖。；在芜湖强拆民房修建日军兵营，征用土地建机场，导致大量居民流离失所。', '[]', '2026-09-10 09:57:14.009964', '2026-09-10 09:57:14.009964', '安徽', '芜湖', '镜湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53f34e42c0a24873ad5a549b4c5238e4', '李德懋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治平顺；山西晋城高平；河南郑州中牟；山西吕梁交口；山西', '[]', '[]', '抗日战争时期', '', '在交口、孝义等地推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众悬挂日伪旗，破坏抗日群众组织。；作为伪晋中道最高行政长官，督导灵石等县伪政权推行保甲制度，强征粮食棉花供日军军需，并协助日军建立情报网，破坏抗日地下组织。；为日军统制物资，强迫商户捐献，为伪军代购军粮，从中牟利。；1938年日军侵占平顺后出任伪县知事，协助日军建立维持会，强征民夫修筑碉堡公路，搜刮粮食供给日军，并组织伪警备队镇压抗日群众。；日军首次侵占平顺时组织维持会，为日军带路清乡，指认抗日家属，强迫百姓领取“良民证”，并参与诱降抗日干部。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019925', '2026-09-10 09:57:14.019925', '山西', '吕梁', '交口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('53f4bd197b254b669e4faca2b546d34e', '田玉峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽鄄城；山东菏泽', '[]', '[]', '抗日战争时期', '', '在巨野、菏泽一带任伪职，协助日军推行治安强化运动，其活动范围与鄄城、郓城相邻。', '[]', '2026-09-10 09:57:14.018205', '2026-09-10 09:57:14.018205', '山东', '菏泽', '鄄城', NULL, NULL, NULL, NULL, '');
