INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54b2ee169b3642f3848f148932f6e071', '王则鼎', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古包头达尔罕茂明安', '[]', '[]', '抗日战争时期', '', '在包头推行亲日奴化教育，编写伪教材，向包括达尔罕茂明安在内的周边地区传播亲日思想。', '[]', '2026-09-10 09:57:13.988115', '2026-09-10 09:57:13.988115', '内蒙古', '包头', '达尔罕茂明安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54b751cb2a6a4c3983396cb5cb1ebd0b', '王殿玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江穆棱；黑龙江牡丹江阳明；黑龙江哈尔滨松北；黑龙江黑河；黑龙江牡丹江牡丹江经开区；黑龙江牡丹江；黑龙江七台河桃山；黑龙江七台河；黑龙江哈尔滨松北；黑龙江哈尔滨；黑龙江绥化肇东；黑龙江绥化', '[]', '[]', '抗日战争时期', '', '地方汉奸武装头目，配合日军“讨伐”抗联，在牡丹江周边村庄烧杀抢掠，强迫村民“归屯并户”。；在桃山、七台河地区组织伪警察队，抓捕抗日地下工作者，参与制造多起屠杀事件。；在穆棱地区组织伪警察，多次参与搜捕抗联交通员，刑讯逼供，导致多名抗日志士牺牲，并协助日军建立“集团部落”。；原黑河警察头目，投日后任伪满黑河省警务厅厅长，组织伪警察和特务，搜捕抗联地下工作者。；原哈尔滨地方士绅，投日后协助日本宪兵队逮捕抗日人士。；原绥化地方士绅，日军占领绥化后出任伪县长，协助日军建立伪政权，组织“自卫团”对抗联进行清剿，强征民夫修筑公路和碉堡。；指挥伪警察在阳明地区抓捕抗联交通员，严刑逼供，破坏抗日组织。', '[]', '2026-09-10 09:57:14.065131', '2026-09-10 09:57:14.065131', '黑龙江', '七台河', '桃山', NULL, NULL, NULL, NULL, '');
