INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54d081b8838c40848b92fc22512c4512', '蔡培', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽六安；江苏无锡；江苏南京；江苏南京江宁；安徽滁州苏滁现代产业园；福建泉州；浙江_杭州_西湖；安徽安庆；江苏南京溧水；福建厦门；江苏南京；云南普洱西；福建泉州鲤城；福建厦门；江苏南京鼓楼；江苏南京浦口', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪南京特别市第一任市长，改组南京伪市府，推行保甲、良民证制度抖音百科。。结局：汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.005398', '2026-09-10 09:57:14.005398', '安徽', '滁州', '苏滁现代产业园', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54d23927e3c64dc1b6d341a725b05629', '李景春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台临城；河北邯郸成安；河北邢台平乡；山西大同阳高；黑龙江大庆大同；河北衡水阜城；河北邢台邢台经开区；辽宁沈阳新民；河北邢台任泽；辽宁沈阳新民；河北邢台内丘；辽宁沈阳新民；河北邢台隆尧；黑龙江鸡西梨树；山西、河北；河北邯郸邱县', '[]', '[]', '抗日战争时期', '', '原为晋系地方官员，投日后任伪大同省参事，参与策划对阳高、大同地区的经济掠夺和奴化教育。；作为伪忻州道顾问，参与策划对宁武抗日根据地的经济封锁，指使伪军抢掠百姓财物，并参与诱降抗日人员，破坏地下抗日组织。；在日军扶植下担任伪区长，推行保甲制度，强征劳工，搜刮民财，为日军提供情报，协助日军扫荡抗日根据地。；组织伪自卫团协助日军驻守据点，袭击八路军游击队，抢劫百姓财物。；日军占领临城后率先组织维持会，为日军征粮派款，充当汉奸走狗。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.021202', '2026-09-10 09:57:14.021202', '山西', '大同', '阳高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54d8cd1c244040f5b44634eb710f71e8', '孙方晤', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（特务汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：特务汉奸；罪行：特务汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.079548', '2026-09-10 09:57:14.079548', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54d8cd6f7c7b4eeb9000b67748916f0c', '傅炳宽', NULL, NULL, NULL, NULL, 'exact', 'exact', '厦门伪警察系统', '[]', '[]', '抗日战争时期', '', '伪职：伪警长；罪行：指挥伪警搜捕爱国人士，城门关卡盘查迫害市民。；结局：逮捕判刑。', '[]', '2026-09-10 09:57:14.082069', '2026-09-10 09:57:14.082069', '福建', '厦门', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54dcaf87a08b4fd48eb703dd8f42cd14', '王怀仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '祁县', '[]', '[]', '抗日战争时期', '', '伪职：伪祁县维持会会长；罪行：商人，1937 祁县沦陷主动投敌；组建侦缉队，建立保甲，出卖情报，致使八路军子洪口作战受挫。；结局：1938 八路军锄奸处决', '[]', '2026-09-10 09:57:14.077496', '2026-09-10 09:57:14.077496', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54e1e4087aca4f9c99cdd5bd346a3dcb', '柳衍斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '镇江', '[\"柳肇庆\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：镇江治安维持会会长、伪镇江自治委员会委员长，沦陷初期头号傀儡；受日军宣抚班操纵，召集士绅，胁迫市民回城，筹措物资夫役金山网。。结局：抗战胜利后逮捕，判处徒刑', '[]', '2026-09-10 09:57:14.081532', '2026-09-10 09:57:14.081532', '江苏', '镇江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('54e50d1c44e9433fbe649118457e679d', '赵如海', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京溧水；浙江_绍兴_上虞；江苏镇江句容；浙江宁波余姚；浙江宁波', '[]', '[]', '抗日战争时期', '', '日军占领溧水后组织维持会，为日军提供粮食、向导，协助建立伪政权。；率伪保安队配合日军扫荡，捕杀抗日军民，抢夺物资，破坏地下组织。；率伪军驻守宁波，参与多次“扫荡”，杀害抗日军民。；协助日军维持治安，严查抗日物资，多次带队突袭村庄。', '[]', '2026-09-10 09:57:14.033752', '2026-09-10 09:57:14.033752', '江苏', '南京', '溧水', NULL, NULL, NULL, NULL, '');
