INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('55201e248f854ca0bc83aa63159c4775', '王季章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北石家庄；冀东', '[]', '[]', '抗日战争时期', '', '首任伪石家庄市长，建立伪市公署，配合日军对市区进行军事管制和人口清查。；伪职：伪冀南道后期道尹、伪顺德道道尹，任职四年；推行治安强化运动，统筹 15 县清乡、修筑炮楼封锁沟，奴化教育。；结局：1943 调走，抗战胜利后判处无期徒刑', '[]', '2026-09-10 09:57:14.043162', '2026-09-10 09:57:14.043162', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
