INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('552c2e958acd4aefb87339d90385503a', '韩森', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古包头青山；内蒙古包头；内蒙古呼和浩特土默特左旗；内蒙古包头青山', '[]', '[]', '抗日战争时期', '', '负责包头及九原地区治安，为日军提供情报，逮捕抗日志士，参与镇压1942年包头工人罢工。；协助王英指挥伪军，参与制定针对大青山抗日游击根据地的军事行动，多次率部袭击抗日武装。；亲自带队搜捕抗日分子，严刑拷打嫌疑人员，向日军提供大青山游击队活动情报。', '[]', '2026-09-10 09:57:13.987984', '2026-09-10 09:57:13.987984', '内蒙古', '包头', '九原', NULL, NULL, NULL, NULL, '');
