INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5537b68a89ec43a292aca91111df47b5', '常玉清', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西渭南；广西柳州；江苏南京；广西桂林灵川；湖北咸宁通山；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '', '上海青帮头目，抗战期间投敌，组织伪安清同盟会，协助日军维持统治。；华中伪军头目，与陕西渭南地区无直接关联。；江苏人，抗战期间投靠日军，组织伪安清同盟会，在华中地区包括湖南进行帮会伪化活动。；青帮头目，投敌后组织伪军，在长江中下游地区包括湖北配合日军行动。；江苏南京人，青帮头目，抗战期间投敌，历任伪上海特别市警察局长、伪军将领等职，在上海及周边地区协助日军维持治安、镇压抗日力量。；上海青帮头目，组织伪黄道会等汉奸组织，进行暗杀、破坏活动。', '[]', '2026-09-10 09:57:14.031574', '2026-09-10 09:57:14.031574', '广西', '柳州', '灵川', NULL, NULL, NULL, NULL, '');
