INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5600c91bd9224985b8ad4063cf2dbba5', '郭玉堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽单县；山东菏泽；河南洛阳；山东菏泽曹县；河北邢台柏乡', '[]', '[]', '抗日战争时期', '', '统领曹县伪保安团，配合日军扫荡曹县、单县交界地区，捕杀抗日干部和群众。；日军占领洛阳后出任伪县知事，协助日军推行保甲制度、征发民夫。；在巨野及菏泽周边地区任伪职，强征民夫修筑封锁沟，配合日军对抗日根据地进行经济封锁。；在柏乡推行保甲连坐，搜捕抗日人员，迫害无辜群众。', '[]', '2026-09-10 09:57:14.018013', '2026-09-10 09:57:14.018013', '山东', '菏泽', '单县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('560fbf64b0774032a0520fa7d1d688ef', '伪武宁县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西九江武宁', '[]', '[]', '抗日战争时期', '', '武宁部分沦陷时期，伪维持会为日军征粮派款，配合扫荡抗日根据地。', '[]', '2026-09-10 09:57:14.038262', '2026-09-10 09:57:14.038262', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5628b61d11b049e0ae0ca30ded42385e', '和梦九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '威县；河北；河北邢台威县；威县出身，后期任伪平乡县长；河北邢台内丘', '[]', '[]', '抗日战争时期', '', '组织伪保安队，配合日军扫荡抗日根据地，多次袭击抗日武装，杀害抗日干部和群众。；投靠日军，任威县伪县长，组织伪政权，协助日军推行“治安强化运动”，镇压抗日民众，征收苛捐杂税，为日军提供粮食物资。；伪职：先威县大汉奸，后任伪平乡县长；日降后被国民党收编为保安第三旅长；收拢伪军顽抗。；结局：1945 被冀南西支队活捉，公审枪决威县发布；伪职：威县维持会头目，最早迎接日军入城，后转任伪平乡县长（见平乡）。；结局：公审枪决威县发布', '[]', '2026-09-10 09:57:14.044777', '2026-09-10 09:57:14.044777', '河北', '邢台', '内丘', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('563afce217054925b692edc0e67dc6f1', '王幼侨', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；河南新乡；河南濮阳；青海黄南河南；河南南阳；福建泉州南安；河南新乡牧野；河南新乡；河南平顶山汝州；河南平顶山；河南洛阳；青海黄南河南；河南鹤壁；河南鹤壁浚县', '[]', '[]', '抗日战争时期', '', '在伪河南省政府任职，推行奴化教育，改编教材，宣传“中日亲善”。；河南安阳人，投日后在伪河南省政府任职，并任伪豫北道尹，管辖安阳、汤阴等豫北各县，推行伪化政策。；日伪在豫北设立伪道尹公署，王幼侨等附逆者参与豫北伪政权，新乡属豫北道范围。；在浚县、淇县一带协助日军建立维持会与保甲制度，征发民夫、粮食，镇压当地抗日武装。；在河南沦陷区任伪豫西道尹等职，负责豫西地区伪化行政，其辖区包括临汝（今汝州）、郏县、宝丰等平顶山地区，协助日军征粮、拉夫、维持治安。；在伪河南省政府中任职，负责豫西道事务，管辖洛阳及嵩县等地，协助日军推行伪化政策。；1944年日军占领豫西后，出任伪豫西道尹，管辖包括洛阳在内的豫西地区，协助日军维持统治。；在伪河南省政府任教育厅厅长，在河南沦陷区推行奴化教育，篡改教材、宣传亲日思想，其教育政策覆盖南阳、新野等县，对当地教育领域造成附逆影响。；河南人，抗战期间投敌，任伪豫南道尹，在豫南地区包括南阳一带协助日军维持伪政权，推行殖民统治。；在伪河南省政府中主管教育，推行奴化教育，新乡等地学校亦受其管辖。；抗战期间在伪河南省政府任教育厅厅长，在河南沦陷区包括濮阳地区推行奴化教育，篡改教材，宣传“中日亲善”。', '[]', '2026-09-10 09:57:14.046786', '2026-09-10 09:57:14.046786', '青海', '黄南', '河南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('563fd1cac03b4f028022d2b216061ac8', '陈则敏', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州福清；福建福州闽侯', '[]', '[]', '抗日战争时期', '', '在日军扶植下出任伪福清县县长，推行伪政令、征派捐税、配合日军扫荡福清沿海抗日力量。；闽侯沦陷时期任伪维持会副会长，参与日伪在闽侯地区的基层统治与物资征集。', '[]', '2026-09-10 09:57:14.062099', '2026-09-10 09:57:14.062099', '福建', '福州', '福清', NULL, NULL, NULL, NULL, '');
