INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5654bc83730c4462b5573852795c6dbc', '赵子青', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸临漳；河北_邯郸_复兴；黑龙江牡丹江东安；河北；河北邯郸；黑龙江黑河北安；山西临汾古县；山西临汾；河北邯郸邯郸冀南；河北邯郸；河北_邯郸_武安', '[]', '[]', '抗日战争时期', '', '协助日军在邯郸、磁县、成安等地建立伪军据点，参与‘清乡’行动，掠夺物资。；日军占领临漳后率先组织维持会，为日军征粮派款，提供劳役，并出卖抗日积极分子。；协助日军搜捕抗日志士，破坏地下组织，实施白色恐怖。；推行保甲制度，强征民夫修筑炮楼，配合日军“清乡”，在峰峰地区强征粮食。；效忠日军，建立伪警察体系，抓捕抗日地下工作者，破坏抗日组织。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018667', '2026-09-10 09:57:14.018667', '山西', '临汾', '古县', NULL, NULL, NULL, NULL, '');
