INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('56bd94bdd98a4f75bde07854557399d4', '周老黑', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄藁城；颍上沙河沿岸', '[]', '[]', '抗日战争时期', '', '率马队追击抗日游击队，在无极、藁城交界处多次交战，杀害伤员。；伪职：日伪密探，怀远籍潜入人员；罪行：经常往返凤台沦陷区??颍上，伪装船工，侦查沙河航运、守军布防，散布日军谣言，拉拢沿江乡民资敌走私。；结局：颍上保安大队抓获，判处死刑。', '[]', '2026-09-10 09:57:14.043810', '2026-09-10 09:57:14.043810', '河北', '石家庄', '藁城', NULL, NULL, NULL, NULL, '');
