INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('56c5aefd50aa4362bd6179111f596c76', '李居平', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东潮州饶平', '[]', '[]', '抗日战争时期', '', '饶平沦陷期间，出面组织伪维持会，为日军征粮、派夫、搜集情报，协助日军控制饶平沿海地区。', '[]', '2026-09-10 09:57:14.029891', '2026-09-10 09:57:14.029891', '广东', '潮州', '饶平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('56caefd247b843b4af118d9258957358', '杜锡钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河南开封；河北唐山滦南；河北唐山丰南；河北河间；云南普洱西；陕西_西安_长安；河北廊坊；河北石家庄；天津河北；北京、山西、河北；河南开封禹王台；山西阳泉城区；江苏徐州；河北保定；河北廊坊；青海黄南河南；北京顺义；河北张家口；河北唐山遵化；河北唐山；江苏南通通州；河北唐山；安徽芜湖；河北沧州河间；河北秦皇岛昌黎；云南_昆明_呈贡；云南普洱西；河北秦皇岛秦皇岛经开区；河北秦皇岛；河南信阳信阳高；河南信阳；河北唐山迁安；河北唐山；河北唐山开平；河北唐山；天津河北；山西晋中左权；山西阳泉盂县；河北秦皇岛抚宁；河北唐山；河南商丘民权；河南商丘；河北石家庄石家庄循环化工园；河北石家庄；河北唐山路南；河北唐山；河北秦皇岛；天津河北；河北_邢台；河北秦皇岛海港；河北秦皇岛；陕西宝鸡；安徽_芜湖_镜湖；河北廊坊固安；天津河北；云南普洱西；河北石家庄', '[]', '[]', '抗日战争时期', '华北伪临时政府', '驻通州指挥伪军，配合日军“铁壁合围”，破坏抗日根据地，犯下累累罪行。；在顺义任职期间，强征民夫修筑炮楼公路，搜刮民财，逮捕抗日家属。；派部队配合日军进攻晋中根据地，在寿阳、盂县一带制造惨案。；在保定一带组织伪保安队，协助日军抓捕抗日志士，破坏地下组织。；原北洋军官，投日后在保定组织伪军，参与围剿八路军冀中根据地，残害抗日军民。……（共涉及41个地区的犯罪记录）；伪任职务：伪华北治安总署督办，接替齐燮元，伪军高官，常驻北平。结局：1945 年北平被捕，判处徒刑，狱中死亡', '[]', '2026-09-10 09:57:13.983035', '2026-09-10 09:57:13.983035', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('56dc9c37688c46078749ec703b834b6e', '金馥庄', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门；福建宁德柘荣；福建厦门', '[]', '[]', '抗日战争时期', '', '在厦门任伪警察头目，镇压抗日民众，其警务活动影响闽南地区。；在伪厦门政权中任职，协助日军推行伪化教育与社会控制，属于福建沿海占领区附逆人员。；在伪厦门政权中任职，参与协助日军管理闽南占领区事务，为日伪统治服务。；在日伪厦门政权中任职，参与伪政权的行政与宣传事务，属于福建沦陷区附逆人员。；在厦门协助日军建立伪警察系统，搜捕抗日人士，迫害无辜民众。；在厦门任伪警察头目，配合日军搜捕抗日人士，推行保甲连坐，控制厦门市区治安。；在厦门及闽南沿海地区组织伪警察力量，配合日军搜捕抗日人士，镇压民众抗日活动。；在厦门及闽南地区组建伪警察队伍，镇压抗日活动，配合日军搜捕抗日人士。', '[]', '2026-09-10 09:57:14.060415', '2026-09-10 09:57:14.060415', '福建', '宁德', '柘荣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('56e00957bf3847d5a720fb5e8bceef2e', '张卓', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州六盘水六枝特；辽宁沈阳大东；贵州贵阳', '[]', '[]', '抗日战争时期', '', '日军侵入黔南时投敌，收编溃兵与地方武装组成伪军，配合日军扫荡抗日游击队。；在伪贵州省教育部门任职，推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青年思想。', '[]', '2026-09-10 09:57:14.062543', '2026-09-10 09:57:14.062543', '贵州', '六盘水', '六枝特', NULL, NULL, NULL, NULL, '');
