INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5747741486d94ed8b1c6ff14092a28dc', '何炳贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；陕西_西安_长安；陕西_西安；云南普洱西', '[]', '[]', '抗日战争时期', '', '投敌后任伪安徽省省长，配合日军。；汪伪粮食头目，参与对广西的粮食征发与掠夺。；在汪伪政权中任要职，配合日军征粮。；浙江杭州人，1938年任伪杭州市长，推行日伪统治，强征物资，镇压抗日活动，后调任伪浙江省政府委员。', '[]', '2026-09-10 09:57:14.032127', '2026-09-10 09:57:14.032127', '浙江', '杭州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('576faea3394d4857a29ef7f5bf2a0293', '刘士魁', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹿邑县', '[]', '[]', '抗日战争时期', '', '伪职：日伪汉奸；罪行：与陈家寅一同为日军效力的汉奸；结局：1938年8月与陈家寅一同被处决', '[]', '2026-09-10 09:57:14.081786', '2026-09-10 09:57:14.081786', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('577578495e7041eabf8b988ae10d2270', '吴友梅', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西抚州广昌；江西抚州；福建泉州永春；福建泉州；江西上饶信州；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '泉州沦陷后组织伪晋江县维持会，协助日军维持治安，迫害抗日人士。；在沦陷区推行奴化教育，强制学校使用日伪教材，向学生灌输“大东亚共荣”思想。；在宜黄、抚州南部地区组织维持会，配合日军和伪军进行地方控制，迫害抗日群众。', '[]', '2026-09-10 09:57:14.037752', '2026-09-10 09:57:14.037752', '江西', '上饶', '信州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('577886d186ee4d8bba4769aeafb4ff09', '赵汝梅', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江大庆林甸；吉林长春；黑龙江牡丹江阳明；黑龙江_佳木斯；吉林长春榆树；吉林长春农安；吉林；吉林长春长春经开区；吉林经开区；吉林；吉林长春长春净月高；吉林长春；吉林长春九台；吉林永吉', '[]', '[]', '抗日战争时期', '', '协助日军搜捕抗日分子，破坏地下组织，参与制造多起屠杀事件。；组织协和会，宣传“日满亲善”，瓦解民众抗日意志；在吉林省政府内参与制定“治安维持”政策，协助日军清乡。；在长春推行日伪市政管理，强拆民房，建立“新京”规划。；在榆树地区设立情报点，多次出卖抗联交通员。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.999233', '2026-09-10 09:57:13.999233', '吉林', '永吉', '九台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('577935b61ee24c17b6d48d36648e8f56', '王赞斌', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林恭城', '[]', '[]', '抗日战争时期', '', '桂系将领，坚持抗战，未附逆。', '[]', '2026-09-10 09:57:14.032227', '2026-09-10 09:57:14.032227', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('577c764a85b24a2889c4b48b92125aa6', '张新斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '新蔡县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（叛徒）；罪行：新蔡县小李庄烈士惨案中，因叛徒告密，汉奸张新斋带领数百名国民党士兵包围小李庄，拘捕李渭滨等人并于次日集体杀害', '[]', '2026-09-10 09:57:14.073818', '2026-09-10 09:57:14.073818', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('577f651634af460597f0e644ded8cf92', '李润生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山滦州；河北唐山；山西晋中左权；山西晋中太谷；山西大同新荣；山西太原古交；山西、河北；山西_晋中_寿阳', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山为日军洗钱，资助侵华战争。；在新荣地区（今新荣区）组织维持会，为日军征收粮税，提供情报，强迫村民修炮楼、修公路，多次带领日军袭击八路军小分队。；率伪军参与对古交抗日根据地的“铁壁合围”，烧毁村庄，屠杀民众。；组建伪保安队，多次配合日军袭击寿阳抗日游击队，抓捕抗日干部，并参与“清乡”行动，残害百姓。；向日军报告八路军动向，导致太谷南山根据地多次遭袭，多名民兵被杀。；在唐山操纵金融，为日军侵华战争提供资金。', '[]', '2026-09-10 09:57:14.021106', '2026-09-10 09:57:14.021106', '山西', '大同', '新荣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('578dc121925141fdb7cb0ede8aed40f7', '王绍文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '[]', '[]', '抗日战争时期', '', '投靠日军，任寿阳县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '[]', '2026-09-10 09:57:14.070701', '2026-09-10 09:57:14.070701', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('578f1578e0ec4ad99927b61b880c75b3', '张盛林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西晋中左权', '[]', '[]', '抗日战争时期', '', '任伪大同警察局长期间，积极搜捕抗日地下人员，破坏中共平城地下组织，协助日军推行“三光政策”。；在左权县城组织维持会，为日军征粮派款，提供情报，导致多名抗日干部被捕牺牲。', '[]', '2026-09-10 09:57:14.022446', '2026-09-10 09:57:14.022446', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('57930c6f8fd046b1960f683335315b71', '于治堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台莱阳；江苏南京栖霞', '[]', '[]', '抗日战争时期', '', '栖霞沦陷后组织伪政权，任伪县长，配合日军对胶东抗日根据地实行经济封锁和扫荡。', '[]', '2026-09-10 09:57:14.017387', '2026-09-10 09:57:14.017387', '山东', '烟台', '莱阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('57a0376f2aec4702aa64e5a9ac134206', '李端章', NULL, NULL, NULL, NULL, 'exact', 'exact', '沁阳', '[]', '[]', '抗日战争时期', '', '伪职：皇协军团长→伪河南省保安第1师第2旅旅长→伪第二师少将参议→中央清化先遣军司令兼21师师长；罪行：1938年日军侵占沁阳后以抗日之名组建自卫团，后与日军勾结组成皇协军；用金钱贿赂日本翻译官、四姨太引诱讨好日军侵沁队长吉岗并拜为义父；队伍发展到数百人；盘踞沁阳8年，全县死于日伪祸害群众4万多人；掘开沁河大堤企图阻止八路军，致多村遭受水灾；温县、孟县、济源、焦作、博爱等县汉奸、恶霸相继逃入沁阳；结局：1945年日本投降后拒绝向八路军投诚，杀害谈判人员；被蒋介石改编为“中央清化先遣军”；1945年11月8日沁阳攻城战中被击毙', '[]', '2026-09-10 09:57:14.067721', '2026-09-10 09:57:14.067721', '河南', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('57aa5cd7d33246c3baf690ee3fd25d69', '陈世文、卜贤举、梁呆子', NULL, NULL, NULL, NULL, 'exact', 'exact', '江都三里乡', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：密探，向日伪告密，引导敌人偷袭我方干部驻地。。结局：1944 年武工队抓获，连夜处决邗江史志网', '[]', '2026-09-10 09:57:14.083423', '2026-09-10 09:57:14.083423', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
