INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('57deaebd136b488a9509275e2b100cfe', '刘启明', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建南平延平；河北邢台平乡；福建三明永安；福建三明；福建福州平潭；福建龙岩漳平；福建龙岩；福建龙岩武平；福建龙岩；福建南平浦城；福建龙岩上杭；福建三明清流', '[]', '[]', '抗日战争时期', '', '浦城人，抗战期间在浦城组织伪维持会并任会长，为日军筹粮、征夫，协助伪政权控制闽浙赣边区部分乡镇。；清流县伪保安队头目，带领伪军配合日军清乡，搜捕抗日游击队员，残害当地百姓。；福建人，在伪福建省政府任职，负责伪警察系统，协助日军在福建各地包括三明地区实施保甲连坐、搜捕抗日人士。；在日伪占领或渗透期间，负责推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动，地方史料中有附逆记录。；在伪政权教育系统任职，推行奴化教育，篡改教材以配合日军宣传。；在闽西龙岩、武平、上杭一带活动，组织伪自治会，配合日军与伪军进行清乡、招降抗日人员，破坏当地抗日组织。；在龙岩伪警察系统任职，协助日军和伪政权镇压抗日群众、搜捕抗日人员。；南平乡村保甲长，附逆日军，负责摊派捐税、监视村民，举报抗日人员，协助日军维持基层统治。', '[]', '2026-09-10 09:57:14.060355', '2026-09-10 09:57:14.060355', '福建', '三明', '永安', NULL, NULL, NULL, NULL, '');
