INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5953bc2289a843258395d8bd3d2540d7', '许良臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南焦作解放；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '在焦作矿区及周边村镇搜捕抗日人员，勒索商户居民，配合日军扫荡，迫害无辜群众。', '[]', '2026-09-10 09:57:14.048871', '2026-09-10 09:57:14.048871', '河南', '焦作', '解放', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5957d0f1e6fa43bc8217fc2375563229', '白堃', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；广西桂林资源；广西桂林象山；山西阳泉城区；广西桂林临桂；广西桂林；广西玉林容县；广西桂林；广西桂林平乐；广西桂林；广西桂林恭城；广西桂林；广西桂林；广西柳州柳城；广西柳州；广西崇左；广西柳州', '[]', '[]', '抗日战争时期', '', '桂林沦陷后投敌，任伪警察局局长，协助日军搜捕抗日人士、镇压民众反抗，维持日伪在桂林城区的秩序。；桂林沦陷期间任伪警察局长，配合日军镇压抗日活动，抓捕抗日志士。；桂林沦陷后任伪警察头目，协助日军搜捕抗日人员、管控户口、镇压民众反抗。；抗战后期附逆，参与伪广西政权，在桂林沦陷期间为日军占领当局效力。；协助伪柳州维持会会长张君嵩，为日军征派物资、维持地方秩序，参与伪化统治。；桂林沦陷期间，参与组建伪警察机构，协助日军搜捕抗日人员、管控户籍与物资。；1944年日军侵入资源县后，出面组织维持会，为日军征粮、派夫，协助维持占领秩序。；在桂林地区组织伪维持会，协助日军维持占领秩序，属于广西范围内有明确记载的伪维持会头目。；桂林沦陷期间，依附日军，参与伪维持会与商会活动，为日军筹款筹粮，协助控制桂林商业与物资流通。；桂林沦陷后，参与组织伪桂林市维持会并任会长，协助日军推行殖民统治，征调物资与人力。；日军侵占柳州期间，出面组织伪维持会，协助日军征发物资、维持治安。；原桂系军官，桂林沦陷后率部投敌，被日军委为伪广西省保安司令，收编散兵游勇组成伪军，配合日军扫荡桂北抗日武装。；桂林沦陷期间任伪维持会副会长，协助日军管理桂林城区，参与征粮、征夫等附逆活动。；桂林沦陷后出任伪桂林市市长，主持伪市政，配合日军实施保甲连坐、物资统制与宣传奴化政策。；桂林沦陷期间出任伪桂林市市长，主持伪市政，配合日军统治，推行保甲连坐，为日军筹粮筹款。', '[]', '2026-09-10 09:57:14.031497', '2026-09-10 09:57:14.031497', '广西', '崇左', '柳城', NULL, NULL, NULL, NULL, '');
