INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5a2557080a6e442db0203b0cb45a0a32', '陈命新', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台芝罘；山东烟台；山东烟台福山；山东烟台', '[]', '[]', '抗日战争时期', '', '抗战初期在烟台组织伪维持会，迎接日军进城，协助日军维持地方秩序，直接涉及烟台、福山地区。；在蓬莱地区任伪县长，属烟台辖区，配合日军维持会与保甲制，镇压抗日军民。', '[]', '2026-09-10 09:57:14.017245', '2026-09-10 09:57:14.017245', '山东', '烟台', '福山', NULL, NULL, NULL, NULL, '');
