INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5a3f4302ea0d496592412bac725fe2c4', '黄公健', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西南宁宾阳；甘肃甘南合作；广西桂林阳朔；广西桂林；广西桂林临桂；广西桂林；广西桂林全州；云南普洱西；广西_南宁', '[]', '[]', '抗日战争时期', '', '日军发动桂柳会战后，在广西沦陷区参与伪政权活动，担任伪省府要职。；日军侵占南宁期间，出任伪警察局局长，协助日军维持治安、镇压抗日活动。；日军占领桂林期间，参与伪教育机构，推行奴化教育，篡改教材，宣传亲日思想。；为日军征收苛捐杂税，盘剥占领区民众，支持日军‘以战养战’。；抗战后期在广西沦陷区与日伪合作，参与伪政权活动，为日军提供情报。；在日军占领南宁期间出任伪财政头目，为伪政权筹款、征收捐税，支持日军占领。；桂林沦陷期间，协助日军控制商会、摊派款项、征调物资，为伪政权经济掠夺服务。', '[]', '2026-09-10 09:57:14.030847', '2026-09-10 09:57:14.030847', '广西', '南宁', '宾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5a414e9a27594482b75630d72c297c8d', '李正谊', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西萍乡上栗；江西萍乡；江西吉安吉州；江西吉安；江西吉安井冈山；江西吉安；江西吉安永新；江西吉安万安；江西吉安；江西赣州信丰；江西赣州；江西宜春上高；江西南昌；云南普洱西；江西吉安遂川；云南普洱西；江西吉安安福', '[]', '[]', '抗日战争时期', '', '吉安地区沦陷或接近沦陷期间，组织维持会，为日军筹粮、派夫、搜集情报，协助日伪维持地方秩序。；抗战后期日军侵占吉安期间，出面组织伪吉安县政府筹备处，充当日伪维持地方统治的代理人。；日军侵占永新期间出面组织维持会，为日军征派民夫、粮食，协助维持占领秩序。；在伪江西省政府中负责警务，协助日军维持沦陷区治安，镇压抗日活动。；在伪江西省政权中负责警务，协助日军在赣中、赣南地区搜捕抗日人士，镇压民众反抗，推行保甲连坐制度。；日军侵占萍乡期间，出面组织萍乡县维持会，协助日军征粮、派夫、维持地方秩序，为日军侵萍提供后勤与情报支持。；抗战后期日军侵占吉安期间，出面组织伪政权，任伪吉安县政府筹备处主任、伪吉安县长，协助日军维持占领区秩序、征派物资。；抗战后期日军侵占吉安期间，出面组织伪政权，充任伪吉安县政府筹备处主任并任伪县长，协助日军维持占领区统治、征派物资与民夫。；抗战期间在江西伪政权任职，参与日伪在江西的经济掠夺与建设控制。；抗战后期在赣南地区参与伪维持会活动，协助日军在赣州及周边地区的占领统治。；在南昌及周边地区组织伪维持会，协助日军推行保甲制度，其势力范围延伸至宜春、上高一带，为日军征粮、征夫。；安福县地方士绅，日军侵占赣中期间出面组织伪安福县维持会，协助日军征粮、派夫、维持地方秩序，为日军在安福地区的统治服务。', '[]', '2026-09-10 09:57:14.039572', '2026-09-10 09:57:14.039572', '江西', '吉安', '万安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5a4b635857a14dc6b06fbabee95616a7', '周镐', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西西安', '[]', '[]', '抗日战争时期', '', '投敌后任伪军事委员会调查统计部次长，进行特务活动。', '[]', '2026-09-10 09:57:14.064842', '2026-09-10 09:57:14.064842', '陕西', '西安', NULL, NULL, NULL, NULL, NULL, '');
