INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5aa711291ad74bdda031679b269a377e', '朱桂山', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽牡丹；山东菏泽；山东淄博；山东泰安宁阳；山东泰安；山东威海；山东_济宁_金乡；山东潍坊；山东_青岛；山东烟台；山东潍坊昌邑；安徽滁州滁州经开区；安徽滁州来安；山东青岛；山东单县；山西阳泉城区；山东济南；江苏南京栖霞；山东烟台', '[]', '[]', '抗日战争时期', '', '伪职：伪济南市市长；罪行：济南首任伪市长，组建伪济南市公署，管理城区，搜刮民财，推行奴化统治；来源：济南市志、济南党史资料；备注：济南伪市政首任长官', '[]', '2026-09-10 09:57:14.009413', '2026-09-10 09:57:14.009413', '安徽', '滁州', '滁州经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5aad98b200e541e79ec16bf92961ebf2', '翟振书', NULL, NULL, NULL, NULL, 'exact', 'exact', '襄阳（襄北）', '[]', '[]', '抗日战争时期', '', '伪职：原朱集乡乡长→伪宛南纵队头目；罪行：投靠日军后被委任为伪宛南纵队头目，多次引导日伪军下乡扫荡，搜捕抗日人员，给襄北地区带来很大危害；结局：抗战胜利后被抓捕审判', '[]', '2026-09-10 09:57:14.086107', '2026-09-10 09:57:14.086107', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5aadf4b80e0f4e58aca051b79223642c', '帅景略', NULL, NULL, NULL, NULL, 'exact', 'exact', '潍县', '[]', '[]', '抗日战争时期', '', '伪职：伪潍县县知事（第二任）；罪行：接替毛寄尘任伪县知事，系“大烟鬼”，仅干了半年多', '[]', '2026-09-10 09:57:14.078784', '2026-09-10 09:57:14.078784', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ab26fed8b1c47038b07d7f9c5c861e3', '凌启鸿', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪上海特别市社会局局长，管控上海工商社团，搜刮物资。结局：汉奸罪判处死刑执行枪决', '[]', '2026-09-10 09:57:14.078652', '2026-09-10 09:57:14.078652', '上海', '上海', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ab48144f9c34161a2f0b30b17f8b02d', '张德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；辽宁沈阳和平；安徽安庆；山东潍坊；山东潍坊寿光；安徽_铜陵_义安；安徽马鞍山当涂；山西_长治_沁源；山西；山东枣庄山亭；山西吕梁石楼；重庆江北；江西上饶信州；江西上饶；山东枣庄；江苏_镇江_扬中；重庆北碚；江苏镇江句容；河北保定容城；江西宜春宜丰；山西运城稷山；重庆涪陵；江苏盐城射阳；山西长治黎城；山西太原小店；湖南岳阳临湘；湖南岳阳', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军袭击小店周边抗日游击队，杀害抗日军属。；严酷镇压抗日运动，设立集中营，关押审讯抗日群众。；控制物资配给，强征粮食，为日军经济掠夺服务。', '[]', '2026-09-10 09:57:14.006670', '2026-09-10 09:57:14.006670', '安徽', '安庆', '当涂', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ab6c48f192d4553baf70738d9fbb446', '张良臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西运城盐湖；山西运城；山西运城平陆；山西运城夏县；山西运城绛县；山西；山西运城闻喜；山西运城万荣；山西运城垣曲；山西运城永济', '[]', '[]', '抗日战争时期', '', '协助日军维持运城治安，参与清乡扫荡，捕杀抗日军民，强征民夫修建碉堡工事。；投靠日军，任万泉县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。；投靠日军后出任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡，搜刮粮食供给日军，并参与诱捕抗日军民。；投靠日军后任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡公路，并组织伪警备队配合日军扫荡抗日根据地，残害抗日军民。；投靠日军，任夏县伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.023587', '2026-09-10 09:57:14.023587', '山西', '运城', '万荣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ab6fd134001478c8941061a86bfc938', '姚文初', NULL, NULL, NULL, NULL, 'exact', 'exact', '岳阳', '[]', '[]', '抗日战争时期', '', '伪职：地主汉奸；罪行：岳阳县地主，投靠日军充当汉奸；结局：被汤赐珊活捉', '[]', '2026-09-10 09:57:14.074674', '2026-09-10 09:57:14.074674', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
