INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ac03719047240e4826da3a9adce4299', '卢焘', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州贵阳；辽宁沈阳大东；广西河池南丹；广西柳州', '[]', '[]', '抗日战争时期', '', '在柳州及桂中地区参与伪维持会活动，协助日军控制交通线与物资流通，影响波及河池一带。；推行奴化教育，改编教材，强迫学校开设日语课并宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.032729', '2026-09-10 09:57:14.032729', '广西', '河池', '南丹', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ac644f86d934612a9dab63033b7c503', '刘东岩', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌五峰', '[]', '[]', '抗日战争时期', '', '五峰地区沦陷或半沦陷期间出面组织维持会，为日军筹粮、派夫，协助维持地方秩序。', '[]', '2026-09-10 09:57:14.056179', '2026-09-10 09:57:14.056179', '湖北', '宜昌', '五峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ac73f37e4144ced9611d7c354bf5deb', '胡宗南', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴诸暨；浙江绍兴', '[\"注：此为误记，实际为胡宗南同名者，非国民党将领\"]', '[]', '抗日战争时期', '', '在浙江伪党部工作，参与对绍兴、诸暨的伪化宣传。', '[]', '2026-09-10 09:57:14.052037', '2026-09-10 09:57:14.052037', '浙江', '绍兴', '诸暨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ac9b163901544cc9a622844c9913260', '林伯衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州；广东江门蓬江；辽宁沈阳大东；广东_肇庆；广东江门；河南鹤壁鹤山；广东_阳江', '[]', '[]', '抗日战争时期', '', '为日军征收田赋、苛捐杂税，搜刮民财，资助伪政权和伪军。；在日军控制下担任伪警察局长，参与搜捕抗日人士、镇压民众反抗。；鹤山沦陷期间组织维持会，为日军征粮征夫，协助伪政权维持地方统治。；主办伪江门日报，为日伪宣传“大东亚共荣圈”，粉饰侵略。；为日军征收苛捐杂税，盘剥梧州商民。', '[]', '2026-09-10 09:57:14.028545', '2026-09-10 09:57:14.028545', '广东', '江门', '蓬江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ad4695bab0e44ddb44caf00b9666d45', '侯殿元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中介休；山西；山西晋中平遥；山西晋中太谷', '[]', '[]', '抗日战争时期', '', '管辖太谷多个伪区，强迫青壮年充当伪军，配合日军修筑炮楼和封锁沟，破坏抗日根据地。；率伪保安队多次袭击平遥县抗日游击队，杀害抗日干部，参与日军‘三光’政策行动，烧毁村庄数十个。；率伪军多次配合日军扫荡平遥抗日根据地，杀害抗日干部和群众，制造多起惨案。', '[]', '2026-09-10 09:57:14.022250', '2026-09-10 09:57:14.022250', '山西', '晋中', '介休', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5aee9cb597cc48d1904a9c2b27e8f8ad', '祖光勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪四平省劳工大队长（驻西安煤矿）；罪行：掌管辽源一带劳工抓捕，强抓大量劳工押入西安煤矿；八一五后组织西安煤矿自治委员会反革命组织，网罗伪旧人员企图接管矿山，对抗民主政权辽源市人民...。；结局：1945 年被民主政府镇压。', '[]', '2026-09-10 09:57:14.078675', '2026-09-10 09:57:14.078675', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
