INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5b8ba993282c4f64aac691e8cec123a6', '刘春圃', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东阳江江城；安徽合肥；安徽合肥合肥高；安徽合肥；江苏镇江丹徒', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强迫学校使用伪满教材，检举抗日师生。；组织伪保安队，配合日军扫荡合肥周边地区，杀害新四军游击队员及无辜百姓，抢劫物资。；在镇江城区（京口）建立伪警察机构，协助日军搜捕抗日分子，严刑逼供，制造白色恐怖。；继林启生后任伪合肥县长，推行汪伪“新国民运动”，强征壮丁，为日军修建碉堡和公路。', '[]', '2026-09-10 09:57:14.005708', '2026-09-10 09:57:14.005708', '安徽', '合肥', '合肥高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5b8beb4450c84f41b812ddbdc0dadd70', '田次廉', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西南宁邕宁；广西南宁', '[]', '[]', '抗日战争时期', '', '日军第一次侵占南宁期间，出面组织伪南宁维持会并任会长，后任伪南宁市市长，为日军筹粮筹款、维持殖民统治秩序；1944年日军第二次侵占南宁时再次附逆，参与伪政权活动。；日军第一次侵占南宁时出面组织伪南宁维持会并任会长，后任伪南宁市市长，为日军筹粮筹款、维持殖民统治秩序；1944年日军第二次侵占南宁时再次附逆，参与伪政权活动。；日军首次侵占南宁期间，出面组织伪南宁维持会，协助日军维持占领秩序、征发民夫与物资。', '[]', '2026-09-10 09:57:14.031339', '2026-09-10 09:57:14.031339', '广西', '南宁', '邕宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5b92efcda8b24c99afde18ca8504a63c', '杨玉昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北秦皇岛青龙；河北沧州献县；河北沧州沧州渤海；天津河北；湖南常德津；河北秦皇岛北戴河；河北秦皇岛；河北承德宽城；河北保定保定高；天津、河北；河北秦皇岛山海关；黑龙江牡丹江绥芬河', '[]', '[]', '抗日战争时期', '', '天津地痞头目，投日后组织便衣队，在天津市区及郊县搜捕抗日人士，敲诈勒索百姓。；率特务队刺探八路军情报，抓捕地下党员，破坏抗日组织。；组织汉奸自卫团，配合日军“扫荡”，在宽城山区烧毁村庄，抢夺粮食，并参与屠杀抗日群众。；为日军宪兵队充当翻译和密探，指认抗日人员，导致数十名地下党员被捕牺牲。；带领自卫团为日军站岗放哨，参与“清乡”，杀害抗日家属，抢夺财物。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.003327', '2026-09-10 09:57:14.003327', '天津', '河北', '保定高', NULL, NULL, NULL, NULL, '');
