INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5c039af585bb46cd9299def5fd635ee8', '刘宗纪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京门头沟；河北秦皇岛海港；河北_秦皇岛；河北唐山乐亭；河北唐山；河北唐山唐山海港经开区；河北唐山；河北秦皇岛山海关；河北秦皇岛；北京、河北；河北唐山路北；河北唐山；北京密云', '[]', '[]', '抗日战争时期', '', '推行日伪“粮食统制”，强征密云农民粮食，导致大量饥荒。；带领伪保安队配合日军“扫荡”门头沟山区，烧毁村庄，杀害无辜百姓。；在日军占领唐山期间任伪市长，协助日军管理城市，镇压工人罢工，控制煤炭钢铁等战略物资。；指挥伪警察镇压唐山、乐亭抗日民众，抓捕地下党员。；负责为日军修建公路、碉堡和军事设施，在唐山沿海地区强征土地，破坏抗日根据地交通。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.993638', '2026-09-10 09:57:13.993638', '北京', '密云', '乐亭', NULL, NULL, NULL, NULL, '');
