INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5c2bccb3da9643628f11795b08df9402', '李春芳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江苏徐州鼓楼；海南昌江；江西景德镇昌江；云南昆明西山；云南保山；山西吕梁；山西吕梁临县；辽宁葫芦岛建昌；云南保山龙陵；辽宁沈阳大东；黑龙江佳木斯汤原；黑龙江大庆；黑龙江大庆萨尔图；江苏徐州云龙；吉林辽源龙山；山西、河北、辽宁；浙江_金华_武义；黑龙江鹤岗萝北；山西_长治_沁源；山西临汾翼城；黑龙江齐齐哈尔克山；安徽马鞍山博望；黑龙江齐齐哈尔甘南；黑龙江大庆林甸；河北石家庄鹿泉；辽宁阜新新邱；辽宁阜新；河北唐山滦州；黑龙江鸡西梨树；黑龙江鸡西；海南临高；辽宁沈阳大东；河北唐山；江苏淮安淮阴；黑龙江双鸭山；海南定安；辽宁沈阳大东；山西晋中左权；山西晋中昔阳；江苏盐城射阳；黑龙江绥化海伦；江苏连云港连云港高；浙江嘉兴海盐；河北邢台；黑龙江绥化青冈', '[\"同名\"]', '[]', '抗日战争时期', '', '专门收集八路军和游击队活动情报，多次引导日军突袭翼城抗日村庄。；在临县率伪军袭击八路军后方医院，杀害伤员。；出卖昔阳抗日村长名单，导致7名村长被日军杀害。；指挥伪警察搜捕抗日分子，严刑逼供，破坏抗日地下交通线。；在唐山地区横征暴敛，导致商户破产，民怨沸腾。……（共涉及8个地区的犯罪记录）；在滦州组织汉奸团体，破坏抗日群众运动。', '[]', '2026-09-10 09:57:13.980299', '2026-09-10 09:57:13.980299', '云南', '保山', '龙陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5c2ed4a03cca42358a96574b0bf2d226', '陈庚新', NULL, NULL, NULL, NULL, 'exact', 'exact', '宿县夹沟五柳', '[]', '[]', '抗日战争时期', '', '伪职：夹沟伪据点头目；罪行：铁杆伪军，驻守五柳据点，吸食毒品，勒索民财，坚决反共，抓捕抗日家属作为人质。；结局：被萧宿铜总队武工队锄奸击毙。', '[]', '2026-09-10 09:57:14.087025', '2026-09-10 09:57:14.087025', '安徽', '宿州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5c34ea01d67d4ca28b905fc6f94e0178', '李用民', NULL, NULL, NULL, NULL, 'exact', 'exact', '荆门县；荆门/钟祥', '[]', '[]', '抗日战争时期', '', '伪职：反共军\"司令（土顽汉奸）\"；罪行：盘踞荆钟北山抗日根据地的土顽、汉奸头目。公开打着反共军\"旗号甘当日寇走狗，对抗日武装、共产党员和根据地进步群众实行血腥镇压\"；结局：1942年8月被北山游击队攻其老巢，当场活捉；伪职：“反共军”司令；罪行：盘踞荆钟北山抗日根据地的土顽、汉奸头目。1940年襄西沦陷后公开打着“反共军”旗号甘当日寇走狗，自称司令，对抗日武装、共产党员和根据地进步群众实行血腥镇压，杀人不眨眼；结局：1942年8月，北山坚委组织游击队攻其老巢，李用民被当场活捉，受到应有惩罚', '[]', '2026-09-10 09:57:14.068027', '2026-09-10 09:57:14.068027', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
