INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ca44f6e3d4c4920ad70fc2b48f5bfa3', '马金标', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '上海金山；河南焦作山阳；河北沧州运河', '[]', '[]', '抗日战争时期', '', '在青县运河段推行奴化教育，组织汉奸情报网，破坏抗日群众组织，协助日军强征劳工。', '[]', '2026-09-10 09:57:13.979496', '2026-09-10 09:57:13.979496', '上海', '金山', '运河', NULL, NULL, NULL, NULL, '');
