INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5caf68c099674ab29157c12dd48d74d8', '潘毓桂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京石景山；湖南常德津；云南普洱西；陕西_西安_长安；北京大兴；四川_广元；湖南常德津；山东聊城；河北秦皇岛；青海黄南河南；陕西宝鸡；云南普洱西；江苏徐州；河北秦皇岛；天津_宁河；山东聊城；北京延庆；天津_北辰；河北邢台清河；湖南常德津；北京门头沟；天津河北；江西九江；湖南常德津；北京昌平；吉林长春朝阳；天津河北；北京_西城；湖南常德津；江苏南京鼓楼；河北；河北邢台清河；北京丰台；北京、天津、河北；天津_西青；天津_和平；天津_武清；湖南常德津；山东德州；青海黄南河南；云南普洱西；河北石家庄；重庆沙坪坝；河北盐山', '[]', '[]', '抗日战争时期', '汪伪政权', '虽主要任伪天津市长，但曾参与北平及丰台地区的日伪协调，协助日军镇压抗日活动。；七七事变后投敌，协助日军维持北平治安，镇压抗日活动，参与伪华北政权组建。；原宋哲元部幕僚，投日后在北平、天津活动，参与制定对大兴等县的“治安强化”计划，提供抗日武装情报。；在北平任职期间出卖抗日情报，参与镇压学生运动，协助日军清剿大兴等郊县抗日武装。；参与北平维持会，后主管伪教育，在延庆等县推行奴化教育，强制学习日语，篡改历史教材。……（共涉及36个地区的犯罪记录）；天津伪政权管辖廊坊南部（如霸州、文安部分），配合日军对大清河沿岸的封锁。；伪任职务：伪天津特别市市长。结局：上海提篮桥监狱服刑，1961 年病死狱中光明数字报', '[]', '2026-09-10 09:57:13.983112', '2026-09-10 09:57:13.983112', '天津', '河北', '怀化洪江管理', NULL, NULL, NULL, NULL, '');
