INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5cf2fc773ce8410381579f379eb3476a', '陈慎言', NULL, NULL, NULL, NULL, 'exact', 'exact', '东阳县城', '[]', '[]', '抗日战争时期', '', '伪职：伪东阳县维持会会长；罪行：东阳沦陷初期伪维持会头目，拉拢乡绅附逆，筹措粮草物资供给日军，推行良民证管控城乡。；结局：战后汉奸清算判刑。', '[]', '2026-09-10 09:57:14.072094', '2026-09-10 09:57:14.072094', '浙江', '金华', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5cf577cbe2254ab5843dc612820ddec5', '罗子云', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化溆浦；湖南衡阳衡南；湖南衡阳衡东；湖南怀化沅陵；湖南郴州北湖；湖南湘西古丈；湖南湘西永顺', '[]', '[]', '抗日战争时期', '', '日军侵占沅陵期间，出面组织沅陵县维持会，协助日军征派民夫、粮食，维持日占区秩序。；抗日战争后期，日军进犯湘西期间，罗子云在永顺地区出面组织伪维持会，协助日军征派民夫、粮食，并参与诱降地方武装。；湖南沅陵人，日军犯湘西时组织维持会，为日军筹粮、派夫，协助伪政权控制沅陵地区。；衡东地区沦陷后组织伪维持会，为日军带路、征粮、拉夫，协助日军控制衡东乡村。；协助会长处理维持会事务，为日军征派物资、维持地方伪秩序。；1945年日军入侵溆浦期间，出面组织伪维持会，为日军筹粮、派夫、带路，维持日占区秩序。；衡南地区投敌武装头目，率部配合日军扫荡，袭击抗日游击队。；日军侵占古丈期间，出面组织古丈县维持会，为日军征集粮食、民夫，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.058439', '2026-09-10 09:57:14.058439', '湖南', '怀化', '沅陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5cf7b990f7f64d2a94963e2a777f4683', '胡常瑛', NULL, NULL, NULL, NULL, 'exact', 'exact', '三门南田岛、石浦一带', '[]', '[]', '抗日战争时期', '', '伪职：伪南田（三门湾）县长、伪三门湾水陆保安总队总队长；罪行：受汪伪浙东行政公署委任，海岛伪军政头目；拥伪军数百，盘踞南田岛，强征巨额开办费，袭扰三门沿海，企图向大陆扩张，多次与我方地方武装交战浙江省地方...。；结局：南田被我方攻克，率残部逃至石浦；抗战胜利后逮捕审判。', '[]', '2026-09-10 09:57:14.076810', '2026-09-10 09:57:14.076810', '浙江', '舟山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5cf8b933f5784155b148855ae5abf0d3', '王文明', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉黄陂；辽宁沈阳大东；湖北武汉洪山；湖北武汉武昌；湖北十堰房县', '[]', '[]', '抗日战争时期', '', '抗战期间投敌，任伪黄陂县保安大队大队长，在黄陂地区组织伪军，配合日军扫荡抗日根据地。；在湖北推行奴化教育，编写伪教材，宣传“大东亚共荣圈”。；湖北房县人，抗战期间投敌，任伪房县教育科科长，推行伪化教育，奴化民众。；任伪武昌县县长，在武昌及洪山周边地区推行保甲制度，征发劳役，协助日军维持统治。', '[]', '2026-09-10 09:57:14.054790', '2026-09-10 09:57:14.054790', '湖北', '十堰', '房县', NULL, NULL, NULL, NULL, '');
