INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5d541c2ef3b043bd9e0208c1a2c7a256', '邢幼杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；河南开封；河南_开封_龙亭；河南郑州；辽宁沈阳大东；河南新乡卫辉；河南新乡；河南商丘；河南_洛阳；河南郑州金水；河南郑州；河南开封杞县；河南开封', '[]', '[]', '抗日战争时期', '', '在豫北推行奴化教育，新乡、卫辉等地学校受其控制。；汪伪河南省政府官员，推行奴化教育，在包括商丘在内的河南沦陷区学校强制日语教学和亲日宣传。；推行奴化教育，篡改教材，向学生灌输亲日思想。；在开封主持伪警务，统辖全省伪警察，配合日军清乡与治安强化。；负责伪河南省宣传事务，配合日军进行舆论控制与奴化宣传，在开封、郑州等地发行伪报刊，粉饰日军侵略。；在开封主办伪报刊，进行亲日宣传，为日军侵略辩护。；在开封主办伪报刊、广播，进行亲日宣传。；组织商界附逆，为日军筹款筹物，协助经济掠夺。；任伪开封市商会会长，为日军筹款筹物，协助经济统制。；以商会名义为日军筹款筹物，协助推行经济统制，压迫商户。；在伪河南省政府中负责教育，推行亲日奴化教育，其教育政策覆盖郑州等地学校。；在开封推行奴化教育，篡改教材，宣传“中日亲善”“大东亚共荣”，毒化沦陷区青年。', '[]', '2026-09-10 09:57:14.047716', '2026-09-10 09:57:14.047716', '河南', '开封', '顺河', NULL, NULL, NULL, NULL, '');
