INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5df8897f568747aa95405d86137f62b0', '王怀义', NULL, NULL, NULL, NULL, 'exact', 'exact', '山阴；齐齐哈尔；灵璧县城', '[]', '[]', '抗日战争时期', '', '伪职：伪龙江省协和会本部部长；罪行：主持协和会奴化宣传，推行 “日满一体”，管控学校、社会团体，监视爱国思想，为战争动员搜刮人力物力。；结局：解放后关押改造。；伪职：伪灵璧县县长；罪行：伪淮海省委任，主持灵璧伪政权，扩充伪保安队，配合日军扫荡灵北抗日根据地，强征粮饷劳工。；结局：抗战胜利后肃奸公审死刑。；伪职：伪山阴县县长；罪行：建立岱岳伪县公署，管控同蒲铁路，强征劳工粮食，配合治安强化运动。；结局：光复后逮捕判刑', '[]', '2026-09-10 09:57:14.068115', '2026-09-10 09:57:14.068115', '安徽', '宿州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5e0622c188684c33aa7377f5ef2d4397', '郝步青', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西忻州五台山风景区；山西忻州五台；山西；山西晋中榆次；山西晋中；山西晋中祁县；山西太原古交', '[]', '[]', '抗日战争时期', '', '充当日军间谍，搜集古交山区抗日武装情报，导致多次袭击失败。；负责在太原及周边推行奴化教育，组织新民会活动，宣传“中日亲善”，破坏抗日民众组织。；任伪晋中道尹期间，管辖榆次等县，推行“治安强化运动”，强征劳工，协助日军建立情报网。；管辖榆次等晋中各县，推行日军“治安强化”运动，组织伪自卫团，配合日军扫荡抗日根据地。；推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，告发抗日家属。', '[]', '2026-09-10 09:57:14.021415', '2026-09-10 09:57:14.021415', '山西', '太原', '古交', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5e084710b0ec428c8c7850f62db1ee58', '冯启民', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州番禺；广东江门；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '利用广播为日伪宣传，鼓吹“大东亚共荣圈”，配合日军思想控制。；负责汪伪在广东的新闻宣传与广播，为日军侵略辩护，进行奴化宣传。', '[]', '2026-09-10 09:57:14.026859', '2026-09-10 09:57:14.026859', '广东', '广州', '番禺', NULL, NULL, NULL, NULL, '');
