INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5e3f2c5e89854abf98974808b34dffa1', '刘昌毅', NULL, NULL, NULL, NULL, 'exact', 'exact', '清苑', '[]', '[]', '抗日战争时期', '', '伪职：保定维持会会长，首任伪清苑县长；迎接日军入城，组建伪公署、新民会，在保定城乡摊派粮款抓丁。；结局：抗战胜利逮捕，汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.079533', '2026-09-10 09:57:14.079533', '河北', '保定', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5e3f7d995f9e4a32ac6d9e18aecb841c', '周庆元', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东历城', '[]', '[]', '抗日战争时期', '', '伪职：伪历城县县长；罪行：伪历城县政府县长，在济南郊区推行伪保甲，抓捕抗日群众；来源：历城县志；备注：济南县域伪政权头目', '[]', '2026-09-10 09:57:14.071188', '2026-09-10 09:57:14.071188', '山东', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5e4a466fe2f34c75b967f1711d07890e', '陈光中', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南邵阳新宁；湖南邵阳；湖南_永州_道县；江苏南京；湖南邵阳隆回；江苏常州；江苏常州武进；江苏常州新北；湖南_邵阳_大祥；湖南邵阳北塔；湖南邵阳；湖南邵阳双清；湖南邵阳；上海长宁；湖南怀化沅陵；云南普洱西；湖南衡阳祁东；江苏无锡江阴；江苏无锡；江苏南京浦口；黑龙江佳木斯郊区；江苏无锡滨湖；江苏无锡；江苏南京浦口；江苏镇江', '[]', '[]', '抗日战争时期', '', '在南京郊区巡逻，袭击抗日游击队。；组织伪保安队，配合日军清乡扫荡，搜捕抗日志士，杀害新四军交通员及群众，抢劫民财。；负责无锡地区日伪特务工作，抓捕、刑讯抗日人士，破坏中共地下组织。；任伪警察头目，带领伪警配合日军搜捕抗日人员、镇压民众反抗。；任伪武进县知事期间，推行保甲制度，强征壮丁，配合日军清乡扫荡。；率部投敌，编入伪军，配合日军在邵阳周边乡镇清乡、搜捕抗日人员。；在长宁区驻有伪保安部队，参与镇压罢工和抗日示威，协助日军“清乡”。；协助日军在宝庆地区建立维持会，负责宣传“中日亲善”、征集物资和劳工。；在苏中地区进攻新四军；在湘南沦陷区组织伪保安部队，协助日军维持治安，镇压抗日力量。；祁东地区沦陷期间，陈光中担任伪保甲长，积极为日军催征粮草、搜集情报，并带领日军搜捕抗日人员。；投靠日军，任无锡县维持会会长及伪县长，协助日军推行“清乡”政策，强征粮食，镇压抗日民众。；率部投靠日军，改编为伪保安团，在邵阳周边地区配合日军扫荡抗日游击队。；在隆回地区组织维持会，协助日军征粮、抓夫，镇压抗日群众，维护日伪统治。；日军占领邵阳后，参与筹组伪政权，为日军提供地方情报与物资支持。；日军占领邵阳后，受命筹组伪县政府，网罗地方劣绅，为日军提供情报与后勤支持。；在湘西地区串联各县维持会，为日军筹粮筹款，协助推行伪化统治。；在镇江京口地区指挥伪保安队，参与日军“扫荡”，烧毁村庄，屠杀无辜百姓。', '[]', '2026-09-10 09:57:13.979638', '2026-09-10 09:57:13.979638', '江苏', '南京', '浦口', NULL, NULL, NULL, NULL, '');
