INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5eaed2dc7dc440f7a3b913bba76a7b22', '施仁心', NULL, NULL, NULL, NULL, 'exact', 'exact', '启东；海门', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：继任伪启东自治会会长；罪行：依附日寇，为日军征粮派差，拉拢地方士绅归顺日伪。；结局：战后汉奸审判判刑。；伪任职务：伪海门县自治会会长、伪海门县知事，海门沦陷头号傀儡，组建海门伪政权、伪警察局，推行良民证、保甲制度。。结局：战后汉奸罪审判，判处死刑', '[]', '2026-09-10 09:57:14.076927', '2026-09-10 09:57:14.076927', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5eb9ebad90cf4a0b80805f7c8fd613b3', '陈瑞亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东东营利津；山东淄博淄川；山东东营；山东东营垦利；山东东营垦利；山东东营广饶；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在鲁中地区组织伪军，协助日军维持占领区治安。；在利津、垦利交界地区推行伪政，配合日军对垦区抗日根据地实行经济封锁和军事扫荡。；在垦利一带组织维持会，为日军提供情报，协助扫荡抗日根据地。；在益都城区及铁路沿线搜捕抗日人员，镇压群众，配合日军治安强化运动。；滨县与利津同属武定道，其伪政权与利津伪县府联合行动，在黄河两岸进行清乡，捕杀抗日军民，掠夺物资。；在广饶推行日伪奴化教育，参与新民会宣传，协助日军控制学校和社会团体，向民众灌输“大东亚共荣”思想。', '[]', '2026-09-10 09:57:14.011758', '2026-09-10 09:57:14.011758', '山东', '东营', '利津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ebd9d6ce5c94a86bd62d94b649a398d', '曹克明', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊高密；山东烟台莱州；山东烟台；山东青岛即墨；山东青岛', '[]', '[]', '抗日战争时期', '', '在胶东地区组织伪军，配合日军对即墨、青岛周边抗日武装进行清剿。；组织伪保安团，配合日军在高密地区扫荡，残害抗日群众。；在胶东地区组织伪军，活动于烟台、莱州一带，配合日军进攻抗日根据地。', '[]', '2026-09-10 09:57:14.017070', '2026-09-10 09:57:14.017070', '山东', '潍坊', '高密', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('5ebe8ac490e6470c8169055659f2edf5', '赵玉堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸邯郸经开区；河北邯郸；河北；山东德州平原；黑龙江黑河北安；黑龙江黑河；山东德州宁津；吉林松原长岭；内蒙古赤峰巴林左旗；河北唐山滦州；山东德州乐陵', '[\"同名\"]', '[]', '抗日战争时期', '', '在滦州组织自卫团，协助日军维持治安。；率伪保安队多次袭击滦州抗日游击队，杀害多名游击队员。；负责统制粮食，强制低价收购农民粮食，供应日军军粮，造成邯郸地区严重饥荒。', '[]', '2026-09-10 09:57:13.991142', '2026-09-10 09:57:13.991142', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
