INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('60ebdd01eb514ac69f7a03216ba0934d', '刘三柱、要三寿、李荣桂、阎祥云', NULL, NULL, NULL, NULL, 'exact', 'exact', '左权', '[]', '[]', '抗日战争时期', '', '伪职：日伪特务团伙；罪行：秘密潜入根据地，密谋刺杀彭德怀，企图建立地下伪政权。；结局：1943 麻田军民公审，全部枪决晋中长安网', '[]', '2026-09-10 09:57:14.077203', '2026-09-10 09:57:14.077203', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('610891135786407baedf70c0106fc9a3', '陈日葵', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；四川南充南部；广西南宁青秀；广西南宁；广西南宁隆安；辽宁沈阳大东；广西南宁宾阳；广西南宁；广西河池南丹；云南普洱西；广西南宁邕宁；云南普洱西', '[]', '[]', '抗日战争时期', '', '在日军扶植下，陈日葵负责伪宣传机构，鼓吹“大东亚共荣圈”，为日军侵略张目。；日军第一次侵占南宁后，出面组织伪南宁维持会并任会长，后改任伪南宁县县长，为日军征派民夫、物资，维持沦陷区秩序。；桂南会战期间依附日军，参与组织广西南部伪维持会网络，为日军提供情报与后勤支持。；抗战期间投靠日军，参与组织伪广西政权，协助日军维持占领区统治，推行奴化宣传与征发物资。；日军侵占广西部分地区期间，参与组织伪广西省维持会，为日军统治广西占领区服务。；日军侵占广西南部期间，在南宁一带参与组织伪广西维持会并任会长，为日军推行殖民统治、征发民夫物资。', '[]', '2026-09-10 09:57:14.030709', '2026-09-10 09:57:14.030709', '广西', '南宁', '宾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6110b71c3d9d40d4a5678c31ae3dc9a4', '苏体仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；山西太原；北京大兴；北京、山西、河北；河北张家口；云南普洱西；山东聊城；山西临汾；江苏无锡锡山；山西太原；山西吕梁；广西桂林资源；吉林高；山西朔州；山西运城；山西阳泉；陕西渭南；青海黄南河南；云南普洱西；北京延庆；北京门头沟；吉林高；山西长治长子；北京海淀；北京石景山；天津河北；河北廊坊；北京丰台；北京_西城；山西晋城；陕西宝鸡；山西五台；朔州；云南普洱西', '[]', '[]', '抗日战争时期', '汪伪政权', '在北平及丰台推行奴化教育，控制学校，强迫学生参加日伪活动。；虽主政山西，但后期在北平参与伪华北政务，曾到大兴视察“治安强化”成果，支持日军建立“模范村”。；虽主政山西，但曾参与北平伪政权高层会议，其势力范围涉及延庆西部山区，协助日军封锁抗日根据地。；在北平及海淀地区掠夺工农业资源，强征劳工，服务于日军战争需求；负责华北工矿资源统制，直接管理石景山制铁所的生产计划，强迫中国工人劳动，为日军提供军工原料。……（共涉及71个地区的犯罪记录）；伪职：第一任伪山西省省长（1938??1942）；罪行：组建伪山西省公署，搭建全省伪政权体系；推行保甲、治安强化运动；协助日军掠夺粮食矿产；组建伪警备队，配合扫荡各抗日根据地，推行新民会奴化教育，充当日阎之间联络人。；结局：1942 调北平伪华北政务委员会；抗战胜利隐匿北平，未受审判，1948 病死北平；伪任职务：伪山西省首任省长，搭建山西全套伪政权，推行治安强化运动，与阎锡山暗地联络。结局：抗战胜利隐匿北平，1948 年病亡，逃脱审判；参与华北伪政权高层会议，制定针对冀中（含廊坊）的“肃正”计划。', '[]', '2026-09-10 09:57:13.993152', '2026-09-10 09:57:13.993152', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6123154f83e145bd87b4cda3a9a947a4', '张鸣岗', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建厦门；福建_厦门_海沧', '[]', '[]', '抗日战争时期', '', '在伪政权中负责卫生行政，协助日军维持占领区秩序与防疫控制。；在福建日伪政权中任职，参与伪省政与地方控制，活动范围涉及厦门周边。；汪伪政权在福建地区的重要附逆官员，参与伪福建省与厦门市政务，配合日军统治。', '[]', '2026-09-10 09:57:14.061083', '2026-09-10 09:57:14.061083', '福建', '厦门', '集美', NULL, NULL, NULL, NULL, '');
