INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6186ad90759a4471a85c296f94d3ec39', '陈伯衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关曲江；广东韶关；广西南宁邕宁；广西南宁；安徽宿州；安徽宿州埇桥；安徽宿州灵璧；福建宁德古田；福建福州连江；广西贺州钟山；贵州六盘水钟山；福建宁德蕉城；黑龙江牡丹江东宁；安徽阜阳；山东菏泽巨野；安徽滁州明光；山东菏泽巨野；山东菏泽；广东广州荔湾；广东广州；山东菏泽曹县；山东菏泽郓城；安徽合肥包河；辽宁沈阳大东；陕西汉中汉台；安徽宿州砀山；安徽宿州萧县；山东菏泽定陶；山东菏泽；广西柳州融水；广西南宁；广西玉林容县；广西柳州鹿寨；山东菏泽单县', '[]', '[]', '抗日战争时期', '', '在合肥推行奴化教育，改编教材，宣传“大东亚共荣圈”。；在伪福建省政权中负责教育事务，推行日语教学与奴化教育，影响包括闽东宁德地区。；巨野人，日军侵占巨野后出任伪县长，建立伪政权和伪警察队伍，推行保甲制度，协助日军掠夺物资、镇压抗日群众。；在伪陕西省政权中任职，负责汉中道（含今汉台区）的伪行政事务，推行日军侵略政策，征发民夫物资。；南宁沦陷期间投敌，负责伪宣传机构，为日军侵略张目，进行奴化宣传。；日军侵占容县期间，出面组织伪维持会，为日军筹粮、派夫，协助维持占领区秩序。；日军侵占鹿寨期间，出任伪鹿寨维持会会长，协助日军维持地方秩序、征调民夫物资。；在郓城一带为日军筹粮、征丁，组织伪自卫团，配合日伪军进攻抗日根据地。；在闽东沿海地区纠集武装投靠日军，任伪军头目，配合日军对宁德、罗源、连江一带进行扫荡和征粮。；韶关伪商会会长，为日军征集物资、筹措经费，协助经济掠夺。；宿州周边伪政权头目，任伪灵璧县县长，协助日军维持统治，推行伪化教育与经济掠夺。；在成武及单县邻近地区推行伪化统治，建立伪小学灌输亲日思想，协助日军抓捕抗日干部。；汪伪政权安徽教育负责人，在安徽沦陷区推行亲日奴化教育，宿州、萧县等地学校被迫使用伪教材。；汪伪广州政权参事，协助日伪市政管理。；郓城沦陷后出任伪知事，在菏泽东北部地区推行伪化统治，协助日军征发粮食、劳工，镇压抗日群众。；阜阳地方人物，抗战期间投敌，组织阜阳维持会，协助日军维持占领秩序，征收捐税，迫害抗日家属。；任伪鲁西道尹期间，统辖菏泽、巨野等县伪政权，推行治安强化运动，配合日军清乡。；在日军侵占南宁期间，组织伪文化协会，进行亲日宣传。；萧县地区伪维持会头目，协助日军建立伪政权，维持地方治安，搜刮民财。；钟山沦陷后，与日军合作组建维持会，负责向各乡摊派物资，并诱迫乡绅附逆。；汪伪政权委任的嘉山县县长，在明光及周边地区推行保甲制度，配合日军清乡，征敛粮食与物资，镇压抗日活动。', '[]', '2026-09-10 09:57:14.005797', '2026-09-10 09:57:14.005797', '安徽', '合肥', '包河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6186ef54d26e423da7c73035321ebdee', '孙立人', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆涪陵', '[]', '[]', '抗日战争时期', '', '组织亲日青年团体，协助日军宣传和劳役征集。', '[]', '2026-09-10 09:57:14.064409', '2026-09-10 09:57:14.064409', '重庆', '涪陵', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('618d97574f374265a98b14def393cd96', '王骥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治武乡', '[]', '[]', '抗日战争时期', '', '1939年出任伪武乡县知事，组织伪县署，强征民夫修筑公路和碉堡，配合日军多次清乡，抓捕抗日干部和群众。', '[]', '2026-09-10 09:57:14.024156', '2026-09-10 09:57:14.024156', '山西', '长治', '武乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61953d966f434e96918bfd385786d2a6', '江亢虎', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽_蚌埠_固镇；安徽安庆；云南昆明呈贡；安徽宣城旌德；安徽黄山；广西桂林永福；江西上饶；江西九江浔阳；辽宁沈阳和平；江苏南京雨花台；江苏南京；江苏泰州泰州医药高；陕西渭南；江苏南京；江西上饶弋阳；江西赣州；江西上饶弋阳；重庆合川；安徽_宣城_泾县；安徽_阜阳_颍泉；安徽_安庆_潜山；安徽_宣城_广德；安徽_滁州_全椒；安徽_阜阳_阜阳经开区；安徽_安庆_怀宁；辽宁沈阳和平；江苏南京浦口；江苏南京；江苏南京鼓楼；江西弋阳；江苏南京江宁；江苏南京；江苏南京浦口；安徽宣城旌德；安徽宣城；安徽黄山；陕西西安；江苏南京六合；辽宁沈阳大东；云南普洱西；安徽_滁州_苏滁现代产业园；安徽_阜阳_颍东；安徽_宣城；安徽宣城旌德；安徽黄山徽州', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪文人汉奸；罪行：抗战期间投靠日伪，发表文章为南京大屠杀日军暴行辩解，1945年被捕审判；来源：文史资料、近代汉奸史料；备注：籍贯上饶，长期在外活动，不在上饶本地作恶；伪任职务：汪伪考试院院长，鼓吹投降理论，推行奴化教育中国社会科...。。结局：被捕关押，病死狱中', '[]', '2026-09-10 09:57:13.982447', '2026-09-10 09:57:13.982447', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61991116537a4740891ba6af2b75440d', '谭英多', NULL, NULL, NULL, NULL, 'exact', 'exact', '清原', '[]', '[]', '抗日战争时期', '', '伪职：伪清原县末代县长；罪行：建立清原伪政权，推行集团部落，围剿东边道抗联；投降后勾结国民党继续作恶。；结局：公审枪决。', '[]', '2026-09-10 09:57:14.073983', '2026-09-10 09:57:14.073983', '辽宁', '抚顺', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61aa84d1a7b947b5967747708584c367', '范绍增', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都金牛；四川成都；重庆大足；重庆合川；重庆万州；重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '抗日战争期间曾率部投靠日伪，任伪军头目，在四川地区进行伪化活动。；抗战期间在四川、重庆一带活动，曾与日伪有接触，但主要身份为地方武装首领，未被列为正式汉奸。；率部出川抗战，无附逆行为；但万州、重庆一带袍哥势力复杂，部分下层头目与日伪有勾结。；利用帮会势力在成都组织伪军，为日军搜集情报，贩卖鸦片，镇压抗日群众。；抗战中率部出川，但所部与日伪有暧昧关系，本人未直接附逆。；川军将领，抗战期间在重庆及四川活动，曾参加抗战。未任伪职，无附逆行为，不应列入汉奸名录。', '[]', '2026-09-10 09:57:14.001724', '2026-09-10 09:57:14.001724', '四川', '成都', '金牛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61d14ffb44b24a629f55a88bba9b9c74', '许敬参', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封', '[]', '[]', '抗日战争时期', '', '在开封任伪市长，为日军搜刮物资，维持伪统治，直至抗战胜利。；在开封推行日伪经济统制，强征粮食与劳工。', '[]', '2026-09-10 09:57:14.048125', '2026-09-10 09:57:14.048125', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
