INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61d26795fd534cad996149441f9d20ee', '黄建中', NULL, NULL, NULL, NULL, 'exact', 'exact', '郸城县', '[]', '[]', '抗日战争时期', '', '伪职：郸城西北大地主（勾结日寇）；罪行：郸城西北黄楼村大地主，家资雄厚。不但不支持抗战，反而勾结淮阳日寇，为非作歹，破坏抗战', '[]', '2026-09-10 09:57:14.081198', '2026-09-10 09:57:14.081198', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61d94a9bb9664188a1cc4b3686bcbe56', '陆伯鸿', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_湖州_安吉；浙江嘉兴桐乡', '[]', '[]', '抗日战争时期', '', '为伪政权强征各种苛捐杂税，盘剥百姓，并将大量税款上交日军作为军费。；充当汉奸商人，为日军统制物资，强迫商户捐款，协助经济掠夺。', '[]', '2026-09-10 09:57:14.050516', '2026-09-10 09:57:14.050516', '浙江', '嘉兴', '桐乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61eac8d087d14dcd9e7e7910157879ba', '宋寿山', NULL, NULL, NULL, NULL, 'exact', 'exact', '沙河', '[]', '[]', '抗日战争时期', '', '伪职：伪沙河县维持会会长、首任伪县长；迎接日军入城，组建伪警备队，管控平汉铁路沙河沿线据点。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.087977', '2026-09-10 09:57:14.087977', '河北', '邢台', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('61f8293efe4a44e99a782272333e80a7', '张子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西运城临猗；山西_忻州_五寨；山西吕梁临县；山西晋中左权；山西晋中祁县', '[]', '[]', '抗日战争时期', '', '组织维持会为日军筹集粮款，强迫村民领取“良民证”，告密抗日活动，导致多名群众被捕。；任伪警察局长，为日军搜集情报，破坏抗日地下组织，参与‘清乡’行动。；原为忻州士绅，后投敌任伪公署顾问，为日军出谋划策，推行“治安强化”运动，破坏抗日地下组织。；率警备队袭击祁县抗日区公所，抓捕抗日家属，勒索钱财，民愤极大。；任伪猗氏县知事期间，为日军提供粮秣情报，参与‘清乡’行动，抓捕抗日干部及家属，并强迫百姓领取‘良民证’。', '[]', '2026-09-10 09:57:14.019891', '2026-09-10 09:57:14.019891', '山西', '吕梁', '临县', NULL, NULL, NULL, NULL, '');
