INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('62e56d4bd646437f9eb9280affb639b7', '何九', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳南山；辽宁沈阳大东；广东深圳坪山', '[]', '[]', '抗日战争时期', '', '为日军筹款筹粮，垄断当地贸易，配合经济掠夺。；组织亲日宣传队，在宝安、深圳、南头等地散布“大东亚共荣”言论，为日军侵略辩护。', '[]', '2026-09-10 09:57:14.029042', '2026-09-10 09:57:14.029042', '广东', '深圳', '南山', NULL, NULL, NULL, NULL, '');
