INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('62f6f314c9c846a594d55e33aacb5c9e', '王善夫', NULL, NULL, NULL, NULL, 'exact', 'exact', '宜昌城区', '[]', '[]', '抗日战争时期', '', '伪职：伪组织人员；罪行：宜昌未沦陷前任市区讼棍、记者及公务员，性阴险。宜昌沦陷后曾赴三斗坪避难，不到一月即返回投敌。伪组织人员被王善夫报告由特务机关抓捕处死者有雷鸣等人；结局：1945年9月18日，宜昌在县府广场召开庆祝抗日战争胜利大会，会后处决了王善夫等日伪汉奸', '[]', '2026-09-10 09:57:14.077622', '2026-09-10 09:57:14.077622', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('62fba00f52104f2f990a7cfd0b688648', '林岳', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三沙西沙；海南三沙中沙；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在乐东地区投敌，建立伪行政机构，配合日军控制海南南部山区与沿海。；在琼东地区组织伪维持会与伪保安队，配合日军扫荡抗日根据地，征发粮食劳工。', '[]', '2026-09-10 09:57:14.053396', '2026-09-10 09:57:14.053396', '海南', '三沙', '中沙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('62fbd8dbd5064ebda17c68bbba7e5580', '蔡晋康', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海乳山；江苏南京栖霞；山东青岛莱西；江苏南京栖霞；山东烟台海阳；山东烟台；山东青岛；高密', '[]', '[]', '抗日战争时期', '', '伪职：伪军头目（“曲线救国”）；罪行：带200余人残兵逃回高密后投降日军，当“曲线救国”的汉奸队，驻守城东北乡，残害群众', '[]', '2026-09-10 09:57:14.013361', '2026-09-10 09:57:14.013361', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('630195130314466d892bd0784c2245ee', '关锡廉', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪永吉县（吉林市）县长；罪行：伪吉林县主官，推行保甲，强征劳工，镇压城郊抗日活动。；结局：抗战胜利逮捕，汉奸罪判刑。', '[]', '2026-09-10 09:57:14.071861', '2026-09-10 09:57:14.071861', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63098457956446c1b0cda1d99c0f47b3', '李意诚', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（随州籍省级汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：伪汉口特别市政府工务局技士；罪行：广水人。抗战期间任伪汉口特别市政府工务局技士；结局：1955年去世；新中国成立后被聘为湖北省人民政府文史研究馆馆员', '[]', '2026-09-10 09:57:14.067231', '2026-09-10 09:57:14.067231', '湖北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('630989503cdd45f2b2ff3dcbe3ef116f', '李阿福', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江舟山定海；安溪县城、湖头', '[]', '[]', '抗日战争时期', '', '伪职：安溪潜伏谍报联络员；罪行：伪装逃难商人，受土桥大郎 “生命保险株式会社” 间谍机关指使，在安溪、永春联络地方败类，搜集闽西、闽中军政情报。；结局：被保安团抓捕，军法处置。', '[]', '2026-09-10 09:57:14.052124', '2026-09-10 09:57:14.052124', '浙江', '舟山', '定海', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('630fdad599254dbab0e78ba8a8e6461a', '李朗鸡', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门开平；河北唐山开平；广东佛山南海；广东广州；广东深圳宝安；广东广州增城；广东广州；广东云浮郁南；广东深圳宝安；广东广州；广西柳州鹿寨；广东广州番禺；广东深圳罗湖；广东深圳；广东清远阳山；广东清远；广东深圳盐田；广东深圳；广东佛山顺德；广东韶关；广东清远佛冈；广东珠海斗门；广东江门；广东韶关乳源；广东广州增城；广东深圳光明；广东深圳；广东珠海香洲；广东珠海；广东江门鹤山；河南鹤壁鹤山；广东河源紫金；广东河源；广东阳江江城；广东阳江；广东深圳；广东深圳南山；广东深圳；广东江门江海；广东江门；广东佛山三水；广东广州海珠；辽宁大连中山；广东韶关武江', '[]', '[]', '抗日战争时期', '', '抗战期间在斗门地区组织伪维持会，协助日军维持地方治安、征粮派款，并率伪自卫队配合日军扫荡抗日游击队。；伪军头目，率部驻防珠江三角洲及江门、台山外围，配合日军扫荡抗日游击队，强征粮食、劳工，罪行累累。；佛冈地区伪维持会头目，协助日军征发物资、维持治安。；在东莞、宝安一带组织伪军，为日军效力，镇压抗日活动。；在珠江三角洲包括江门、开平邻近地区组织伪军，参与日军对抗日根据地的清乡与扫荡。；广东地方伪维持会头目，配合日军在番禺、市桥一带活动，其势力与广西东南部邻近。；广州基层伪政权人员，协助日军推行保甲制度与人口控制。；抗战期间投靠日军，在三水组织伪维持会，后任伪三水县政府县长，协助日军征粮、拉夫、清乡，镇压抗日民众。；在广州日占区充当伪特务和警察爪牙，参与侦捕抗日人员、勒索市民。；在广东部分地区率部投敌，配合日军维持地方秩序并参与对抗日武装的作战。；在番禺、顺德、中山及广州周边活动，率伪军协助日军清乡、扫荡，残害抗日军民。；原名李辅群，广东东莞人，抗战期间投靠日军，组织伪军盘踞东莞、惠州、宝安一带，配合日军扫荡东江抗日根据地，在惠州及东江下游地区征收苛捐杂税、残害抗日军民。；在深圳、东莞一带组织伪军，配合日军扫荡抗日游击队，抢劫民财，其势力范围包括深圳、盐田周边地区。；组织伪保安大队，配合日军在宝安、深圳、南头地区进行扫荡，袭击抗日游击队，残害抗日群众。；广东著名汉奸，率伪军在广州、佛山、清远等地配合日军作战，参与扫荡抗日游击队，对清远地区抗日力量造成较大破坏。；顺德沦陷后出面组织维持会，后任伪顺德县县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。；广州及珠江三角洲沦陷区投敌武装头目之一，率部配合日军扫荡抗日游击队，活动范围包括南海、佛山周边。；在江门、新会一带收编土匪武装，组织伪军配合日军扫荡抗日游击队，残害当地民众。；在珠江三角洲及清远一带组织伪军，为日军效力，参与扫荡抗日游击队。；活跃于珠江三角洲及江门、新会、鹤山一带，组织伪军配合日军扫荡，控制水陆交通，勒索商民，参与维持会与伪政权活动。；在广东东江地区组织伪军，协助日军进攻抗日游击队，活动范围包括河源、紫金周边，参与镇压当地抗日活动。；在东莞、深圳交界地区组织伪保安队，协助日军控制广九铁路及深圳、罗湖一带，参与镇压抗日游击队。；广东著名汉奸武装头目，在广东多地包括阳江周边地区活动，组织伪军配合日军作战，残害抗日军民。；日占江门时期任伪警察头目，率伪警配合日军扫荡，镇压江门、新会一带抗日活动。；掌控江门伪警察力量，配合日军搜捕抗日人员、镇压民众。；深圳镇沦陷后组织维持会，为日军提供情报、物资，压迫当地民众。；担任伪宝安县警察局长期间，带领伪警察配合日军扫荡深圳、福田周边乡村，搜捕抗日游击队员及其家属。；投靠日军后任伪增城县县长，组织伪军协助日军在广东北部地区清乡。；广东伪军头目，活动于广州周边及珠江三角洲，参与日伪清乡与扫荡。；广东地方伪军头目，率部配合日军在珠江三角洲及广州周边地区扫荡抗日武装。；在江门及周边为日军搜集情报，协助抓捕抗日分子，属基层附逆人员。；在珠海及香洲一带收编土匪、组织伪军，配合日军对抗日游击队进行扫荡，并控制当地走私与鸦片贸易。', '[]', '2026-09-10 09:57:14.025699', '2026-09-10 09:57:14.025699', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('631222c0e0904885b99f3624b4b66f1d', '刘耀庭', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；湖北荆门；山东菏泽菏泽经开区；山东菏泽成武；山东菏泽单县；山东菏泽；山东菏泽曹县', '[]', '[]', '抗日战争时期', '', '为日军筹办军需物资，强制商户摊派捐款，协助日伪控制物资流通。；率伪军在郓城、菏泽一带活动，多次配合日军扫荡，烧毁民房，杀害抗日人员。；曹县人，抗战初期组织维持会迎接日军，协助日军建立伪政权，征粮抓丁，镇压抗日群众。；河南南阳人，抗战期间投敌，任伪保安团副官，协助日军指挥伪军，镇压抗日活动。；统领伪保安大队，在成武及周边地区配合日军清乡，抓捕抗日人员，勒索民众。', '[]', '2026-09-10 09:57:14.018029', '2026-09-10 09:57:14.018029', '山东', '菏泽', '单县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6312ef74737343f1a343fb5ebb06993e', '李启明', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德福鼎；福建宁德霞浦；海南五指山；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '任伪霞浦县县长期间，推行日伪政令，征敛粮款，配合日军扫荡抗日根据地。；参与伪军指挥，协助日军扫荡海南抗日游击队。', '[]', '2026-09-10 09:57:14.054042', '2026-09-10 09:57:14.054042', '海南', '五指山', '福鼎', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('631b2af1e09a4b5aa20b8d8227311d4b', '侯俊明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西运城河津；山西吕梁；山西吕梁离石', '[]', '[]', '抗日战争时期', '', '在离石区多次率伪军袭击八路军运输队，抢夺物资。；宣传中日亲善，组织奴化教育，搜集抗日情报，破坏地下党组织。', '[]', '2026-09-10 09:57:14.019649', '2026-09-10 09:57:14.019649', '山西', '吕梁', '河津', NULL, NULL, NULL, NULL, '');
