INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6361ef2245e641fe931b6b5f4f1cec9d', '安廷庚', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海威海火炬高；河北秦皇岛海港', '[]', '[]', '抗日战争时期', '', '在荣成及威海沿海地区组织伪政权，协助日军控制沿海港口、征用民船、封锁抗日根据地，参与镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.013422', '2026-09-10 09:57:14.013422', '山东', '威海', '威海火炬高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63694d620b194f6fb275ff705c293b9f', '何庭流', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；浙江杭州西湖；江苏南京；安徽安庆迎江；浙江宁波鄞州；安徽安庆；安徽芜湖芜湖经开区；安徽芜湖；江苏南京六合；江苏南京；安徽_芜湖；江苏南京浦口；江西九江濂溪；江西九江', '[]', '[]', '抗日战争时期', '', '在六合县（今属南京）任伪知事，推行日伪统治，强征粮食。；为日伪搜刮南京市民钱财；协助市长管理伪政权，参与组织“清乡”和物资统制。；垄断芜湖粮食购销，强制低价收购农民稻米，导致饥荒，饿殍遍野。；伪维新政府要员，参与华中沦陷区伪化统治，与江西九江伪政权有联系。；在安庆县境强征粮食，强迫百姓为日军服役。；参与设计西湖边日军军事设施，破坏岳庙、灵隐寺等文物建筑。；任伪杭州市长期间，为日军提供粮食和劳役，建立伪警察机构，镇压杭州城内抗日活动。；组织伪保安队，配合日军清乡扫荡，在迎江地区抓捕抗日分子。；原为鄞州地方士绅，投靠日伪，任伪鄞县县长期间，协助日军清乡，强征粮食，迫害抗日家属。；在江苏组织伪警察，参与镇压抗日示威和地下活动。', '[]', '2026-09-10 09:57:14.006351', '2026-09-10 09:57:14.006351', '安徽', '安庆', '芜湖经开区', NULL, NULL, NULL, NULL, '');
