INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63cbaf30964841e69f73b7247852d82a', '拉旺', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰巴林左旗', '[]', '[]', '抗日战争时期', '', '蒙古族，伪满兴安西省翁牛特左翼旗旗长，在翁牛特旗（邻近巴林左旗）推行伪满政策，征粮征兵，镇压抗日活动。', '[]', '2026-09-10 09:57:13.991382', '2026-09-10 09:57:13.991382', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63dc09a9b4d54e0a83139501b4128bd3', '王少陵', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏连云港赣榆', '[]', '[]', '抗日战争时期', '', '为日伪政权审判抗日人士，以“反满抗日”罪名判处无辜百姓，协助镇压抗日运动。', '[]', '2026-09-10 09:57:14.036806', '2026-09-10 09:57:14.036806', '江苏', '连云港', '赣榆', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63de641a0b384b13922625ebda9244d8', '林贤察', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东湛江；广东汕头澄海；广东汕头濠江；广东汕头龙湖；广东潮州潮安；广东汕头潮南；辽宁沈阳大东；广东潮州饶平；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '在潮安沦陷区任伪县长，配合日军清乡、征粮，镇压当地抗日力量。；率伪保安队配合日军扫荡潮阳、濠江一带乡村，抓捕抗日游击队员及其家属。；在汕头沦陷区为日军筹款筹物，控制商会为伪政权服务，压迫商户。；统率伪军配合日军扫荡潮汕抗日根据地，进攻抗日游击队，残害百姓。；推行奴化教育，强制使用日伪教材，灌输亲日思想。；在潮汕沦陷区推行奴化教育，改编教材，宣传“大东亚共荣圈”。；组织伪保安队配合日军扫荡潮安、饶平一带抗日武装，残害百姓。', '[]', '2026-09-10 09:57:14.028088', '2026-09-10 09:57:14.028088', '广东', '汕头', '潮南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('63f98b58b6b64e8987eca107ea60700a', '杨为桢', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西_西安_长安', '[]', '[]', '抗日战争时期', '', '在汪伪政权中负责教育，推行奴化教育。', '[]', '2026-09-10 09:57:14.065033', '2026-09-10 09:57:14.065033', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('64119c2f7e8f44d39204e5ea7e91e3a8', '李道南', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁；广东汕尾；广东汕尾海丰；江苏_南京_雨花台', '[]', '[]', '抗日战争时期', '', '任伪海丰县县长期间推行日军殖民统治，征发粮食劳工，配合清乡。；咸宁伪警察头目，协助日军维持治安，搜捕抗日分子，迫害无辜群众。；曾任伪江苏省长，在江苏地区推行伪政令，配合日军清乡。', '[]', '2026-09-10 09:57:14.028294', '2026-09-10 09:57:14.028294', '广东', '汕尾', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('641ab8f467aa46f3bb10e19854df13e4', '张守义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治武乡；山西长治；内蒙古巴彦淖尔；内蒙古巴彦淖尔乌拉特前旗；山西_临汾_曲沃；山西临汾翼城；山西临汾；山西运城芮城；山西；山西长治平顺；江苏徐州贾汪；山西_长治_壶关；山西忻州河曲；山西长治潞城；山西长治潞州；山西_大同_阳高', '[]', '[]', '抗日战争时期', '', '指挥伪警察，搜捕地下党员，严刑逼供，杀害抗日志士。；负责为日军征收粮食，在翼城、临汾交界地区强征暴敛，导致百姓饥荒。；效忠日军，指挥伪警察抓捕抗日军民，参与多次“清乡”行动，残害无辜百姓。；率伪军配合日军扫荡抗日根据地，抓捕并杀害抗日军民，抢劫百姓财物。；效忠日伪政权，负责搜捕抗日地下党员，严刑逼供，破坏抗日组织，并参与“清乡”行动。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.990157', '2026-09-10 09:57:13.990157', '内蒙古', '巴彦淖尔', '翼城', NULL, NULL, NULL, NULL, '');
