INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6423224e474249a3a9bc6b9b238aca4d', '林作桢', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠；安徽蚌埠蚌埠经开区；安徽蚌埠', '[]', '[]', '抗日战争时期', '', '日军占领蚌埠后率先组织维持会，任会长，后任伪市长，协助日军建立殖民秩序，强征民夫，掠夺粮食资源。；日军占领蚌埠后出任维持会会长，为日军提供粮食、劳役，组织伪政权初期机构。', '[]', '2026-09-10 09:57:14.010325', '2026-09-10 09:57:14.010325', '安徽', '蚌埠', '蚌埠经开区', NULL, NULL, NULL, NULL, '');
