INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6443af5f379f4b518dae399ba1567715', '李振江', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西临汾汾西；山西临汾古县；山西临汾', '[]', '[]', '抗日战争时期', '', '汾西县地方人物，日军侵占汾西后出面组织维持会并出任伪职，协助日军在汾西地区征粮、派款、维持治安，配合日伪军对汾西抗日根据地的清剿。；在临汾任伪警察头目，带领伪警察配合日军搜捕抗日人员，镇压民众反抗，维持日伪统治秩序。', '[]', '2026-09-10 09:57:14.018625', '2026-09-10 09:57:14.018625', '山西', '临汾', '古县', NULL, NULL, NULL, NULL, '');
