INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6450f4bab93a4aaca983a18dba139be5', '刘伯骧', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳台前；河南濮阳清丰；河南濮阳范县；河南濮阳清丰；河南新乡；河南濮阳濮阳工业园；河南濮阳；河南濮阳南乐；河南濮阳', '[]', '[]', '抗日战争时期', '', '清丰县士绅，日军占领清丰后组织维持会，任会长，后任伪县长，在清丰、濮阳交界地区推行伪化统治，为日军筹集物资。；在清丰县任伪县长期间，配合日军推行保甲制度，征发民夫、粮食，支援日军对冀鲁豫根据地的扫荡。；在伪河南省政府任职，管辖豫北道，包括濮阳地区，推行日军殖民统治政策，征发民力物力，镇压抗日运动。；抗战期间投敌，曾任伪冀南道道尹，管辖包括濮阳、南乐、清丰在内的冀南豫北地区，推行日军殖民统治政策，组织伪军伪警，配合日军扫荡抗日根据地。；在新乡周边汲县组织伪政权，为日军提供粮秣、劳工。', '[]', '2026-09-10 09:57:14.048208', '2026-09-10 09:57:14.048208', '河南', '新乡', '南乐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('645fad46a88c4846bd97e449aba2fd07', '万金山', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东泰安宁阳；山东泰安', '[]', '[]', '抗日战争时期', '', '活动于泰安、宁阳周边，投敌后率部配合日军作战，参与扫荡和镇压抗日群众。', '[]', '2026-09-10 09:57:14.014853', '2026-09-10 09:57:14.014853', '山东', '泰安', '宁阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('646fb8106685475795b6c7af37ab219b', '李义芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '穆棱八面通、绥芬河', '[]', '[]', '抗日战争时期', '', '伪职：八面通宪兵队密探汉奸；罪行：出卖地下交通员赵兴东，致使其被捕牺牲，破坏绥芬河国际地下交通线绥芬河市人...。；结局：1960 年群众检举，牡丹江法院判处反革命罪惩处。', '[]', '2026-09-10 09:57:14.086985', '2026-09-10 09:57:14.086985', '黑龙江', '牡丹江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('647a27e54b1b4f36a277732a025174a1', '刘志忠', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西南宁邕宁；广西南宁武鸣；广西南宁邕宁；广西梧州苍梧；广西梧州；广西玉林；广西玉林博白；广西南宁；广西南宁邕宁；广西北海；广西南宁江南；广西南宁；广西南宁马山；广西南宁；广西柳州融水；广西柳州；广西贵港港南；广西南宁良庆；广西南宁；广西南宁隆安；广西南宁', '[]', '[]', '抗日战争时期', '', '日军占领南宁后，刘志忠出面组织伪商会，为日军筹款筹粮，压迫商户。；博白沦陷后出面组织维持会，为日军筹集粮食和劳工，协助日军维持地方治安。；组织伪青年团，配合日军进行反共宣传，诱骗青年加入伪军。；在邕宁地区配合日军搜捕抗日分子，实施白色恐怖。；参与伪邕宁县维持会，协助日军征粮征夫。；南宁沦陷后组建伪保安队，配合日军清乡，在马山、武鸣一带参与对抗日游击队的围剿。；担任伪保甲长，协助日军清查户口、征收捐税、抓捕抗日人员，欺压百姓。；日军占领南宁后，出任伪南宁县县长，推行伪政令，为日军征粮征夫，协助维持占领区基层统治。；1944年日军侵占柳州后，出面组织伪柳州维持会，为日军征集物资、协助维持占领区统治。；日军侵占柳州期间，出任伪柳州维持会会长，协助日军维持地方治安、征调物资。；协助苏德燊组织伪南宁维持会，负责征发民夫、物资，配合日军统治。；日军占领南宁期间，出任伪警察局长，镇压抗日活动，抓捕爱国人士。；梧州沦陷后投靠日军，担任伪警察巡官，协助日军搜捕抗日人员。；邕宁沦陷期间参与维持会，协助日军管理地方，征派壮丁与物资。', '[]', '2026-09-10 09:57:14.030496', '2026-09-10 09:57:14.030496', '广西', '北海', '武鸣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('647bfaab055e4e00898c7a44b5d042b0', '何绍先', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁', '[]', '[]', '抗日战争时期', '', '编写散发亲日宣传品，污蔑抗日军队，鼓吹投降主义。', '[]', '2026-09-10 09:57:14.064488', '2026-09-10 09:57:14.064488', '重庆', '铜梁', NULL, NULL, NULL, NULL, NULL, '');
