INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('64cf9caddb1b42f3b309273225fedd43', '李香谷', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_宿迁', '[]', '[]', '抗日战争时期', '', '负责为日伪征收各种苛捐杂税，包括田赋、营业税、烟酒税等，加重百姓负担，并将税款直接供给日军军费。', '[]', '2026-09-10 09:57:14.034392', '2026-09-10 09:57:14.034392', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
