INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('64f953f858be4ed395ba1684ab0e65a0', '赖世璜', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州定南；江西赣州；江西赣州瑞金；江西赣州南康；江西赣州石城；江西赣州；江西赣州会昌；江西赣州', '[]', '[]', '抗日战争时期', '', '在赣州、会昌交界地区组织地方武装，抗战期间投靠日伪，参与维持会活动，为日军搜集情报、征派粮款。；日军侵占赣北、赣中期间，在赣县、南康一带组织伪维持会，为日军筹粮筹款、搜集情报，协助日军维持占领区秩序，压迫当地民众。；在赣州及周边县区活动，抗战时期依附日伪势力，参与组织维持会，为日军搜集情报、征派粮款，协助日伪维持地方统治。；在赣州推行亲日奴化教育，编写伪教材，组织学生参加亲日集会，为伪政权培养顺民。', '[]', '2026-09-10 09:57:14.040491', '2026-09-10 09:57:14.040491', '江西', '赣州', '会昌', NULL, NULL, NULL, NULL, '');
