INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('65614da258dd494483e0ecff7d340ca7', '杨杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南大理；江苏南京溧水；云南昆明呈贡；江苏镇江丹徒；上海杨浦；江苏镇江', '[]', '[]', '抗日战争时期', '', '杨杰系云南大理人，民国时期军事理论家，抗日战争期间主张抗日，曾任驻苏联大使，并非汉奸。不应列入。；统领伪保安队，配合日军扫荡镇江周边乡村，烧杀抢掠，破坏新四军根据地。；在溧水推行伪政权，征收苛捐杂税，向日军提供粮食和情报，破坏地下抗日组织。；为日军宪兵队充当翻译，在杨浦地区刑讯逼供抗日人士。；率伪保安队配合日军“扫荡”，烧毁村庄，抢劫财物，杀害抗日干部。；云南籍军事理论家，抗战时期任驻苏大使等职，无汉奸记载。', '[]', '2026-09-10 09:57:13.978242', '2026-09-10 09:57:13.978242', '上海', '杨浦', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('656d0127d3774ca58e97ec149a482325', '韩世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治黎城', '[]', '[]', '抗日战争时期', '', '为日军强征壮丁，并协助日军建立“爱护村”监控抗日活动。', '[]', '2026-09-10 09:57:14.024466', '2026-09-10 09:57:14.024466', '山西', '长治', '黎城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6572bfab67f14cee82c7620c53b00917', '刘健羽', NULL, NULL, NULL, NULL, 'exact', 'exact', '运城安邑', '[]', '[]', '抗日战争时期', '', '伪职：伪河东盐务局长；罪行：本地盐商世家出身，投降日军，掌控河东盐池，为日军掠夺食盐资源，盘剥盐工畦户，是晋南经济大汉奸。；结局：抗战胜利后逮捕审判', '[]', '2026-09-10 09:57:14.080975', '2026-09-10 09:57:14.080975', '山西', '运城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('657a4090a1ee4c7593719abcc3be8674', '刘国栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台任泽；黑龙江绥化海伦；河北；河北石家庄无极；黑龙江鸡西梨树；黑龙江鸡西；江西萍乡莲花；江西萍乡；辽宁本溪', '[]', '[]', '抗日战争时期', '', '效忠日军，建立伪警察网络，搜捕抗日地下党员和进步群众，严刑逼供，破坏中共地下组织，向日军提供情报。；率部充当日军爪牙，多次参与“扫荡”，抓捕抗日干部和家属，烧毁村庄，抢劫财物，民愤极大。；率伪军多次配合日军扫荡任县抗日根据地，杀害抗日干部和群众，烧毁村庄，抢夺物资。', '[]', '2026-09-10 09:57:14.040346', '2026-09-10 09:57:14.040346', '江西', '萍乡', '莲花', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('65820aa796a24464bd1b28d4b2f170e2', '徐柏如', NULL, NULL, NULL, NULL, 'exact', 'exact', '衢州城区（衢县）', '[]', '[]', '抗日战争时期', '', '伪职：衢县临时维持会会长；罪行：1942 年日军攻占衢州后出面组建临时维持会，召集城内商绅，为日军征集粮草民夫，维持占领区市面。日军撤退后解散。；结局：抗战胜利后以附逆罪逮捕判刑。', '[]', '2026-09-10 09:57:14.085276', '2026-09-10 09:57:14.085276', '浙江', '衢州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6587402314164079867ff52c219f5dd8', '雷沛鸿', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁良庆；云南普洱西；广西南宁；广西南宁邕宁；广西南宁青秀；广西南宁；广西南宁江南；广西南宁宾阳；广西南宁；广西南宁西乡塘；甘肃甘南合作；云南普洱西；广西_崇左；广西南宁马山；云南普洱西；广西南宁武鸣；广西南宁', '[]', '[]', '抗日战争时期', '', '据部分地方史料记载，其在日军侵占南宁期间与伪政权合作，参与推行奴化教育宣传；此说存在争议，需谨慎对待。；日军第二次侵桂时，日方曾试图拉拢其出任伪教育厅长，雷沛鸿未附逆，但日伪档案中列为其拟任人选。；日方曾企图拉拢其出面组织伪政权，其未实际附逆，但日伪曾盗用其名义进行宣传。；日军占领广西期间，曾将其列入伪政权拟任名单，雷沛鸿虽未实际就任，但在日方拉拢过程中未明确拒绝，态度动摇。；1944年日军入侵广西时，雷沛鸿曾一度被日方胁迫，但最终拒绝合作，未实际附逆。；日军侵占南宁后曾试图拉拢其出面组织伪政权，其一度与日方接触，后未正式就任，但此事在广西有明确记载。；广西沦陷期间，日伪在南宁、武鸣等地推行奴化教育，雷沛鸿被列名于相关伪教育组织材料中。；无可靠史料证明其附逆，不应列为汉奸。；若严格按汉奸名录不应列入）；日军入侵广西期间，任伪广西教育厅厅长，推行奴化教育。；在日军占领广西部分地区期间，接受伪职，参与伪教育机构活动，推行奴化教育，为日军殖民统治培养顺民。；日伪曾试图拉拢其参与伪教育机构，雷沛鸿拒绝附逆，未担任伪职。', '[]', '2026-09-10 09:57:14.030751', '2026-09-10 09:57:14.030751', '广西', '南宁', '宾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6587937e36444831a862995ccbde046d', '张喜成', NULL, NULL, NULL, NULL, 'exact', 'exact', '新乡县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（原国民党区长）；罪行：原新乡县国民党区长，日军入侵后叛变投靠日军，成为当地臭名昭著的汉奸败类', '[]', '2026-09-10 09:57:14.074841', '2026-09-10 09:57:14.074841', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('658d6e8408ec403aadaf1a817e567275', '高振东', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州鼓楼；河南商丘永城', '[]', '[]', '抗日战争时期', '', '为日军宪兵队担任翻译，并充当密探，利用语言优势刺探民间抗日言论，直接导致多名抗日志士被捕牺牲。；在永城任伪警察所所长，带领伪警配合日军下乡扫荡，抓捕抗日家属，勒索民众。', '[]', '2026-09-10 09:57:14.035372', '2026-09-10 09:57:14.035372', '江苏', '徐州', '鼓楼', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('658e10d2415b45099754645b5a4362f2', '王连仲', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东临沂蒙阴；山东临沂；山东临沂临沭；山东济南章丘；山东淄博淄川；山东淄博；山东济南莱芜；山东泰安新泰；辽宁沈阳新民；山东临沂莒南；山东临沂', '[]', '[]', '抗日战争时期', '', '在临沂、蒙阴交界地区活动，率伪军配合日军扫荡，袭击八路军和地方抗日武装。；在章丘一带组织伪警备队，协助日军扫荡抗日根据地。；在鲁中地区投敌，配合日军扫荡，活动范围涉及淄博周边。；组织伪保安团，协助日军控制莱芜乡村，参与清乡活动。；组织伪保安团，协助日军守备临沂据点，参与对莒南抗日根据地的蚕食和扫荡。；任伪泰安道新民会会长，进行奴化宣传，组织亲日活动，协助日军推行文化侵略。；率伪警备队在临沭及沭河沿岸配合日军扫荡，袭击抗日武装，掠夺物资，迫害抗日家属。', '[]', '2026-09-10 09:57:14.012667', '2026-09-10 09:57:14.012667', '山东', '临沂', '临沭', NULL, NULL, NULL, NULL, '');
