INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('663273df418a4f79a86d1a2d82994386', '周文瑞', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；浙江舟山；浙江舟山岱山；浙江舟山；江苏苏州苏州工业园；浙江杭州建德；浙江宁波镇海；浙江绍兴；辽宁沈阳大东；辽宁葫芦岛兴城；浙江台州临海；江苏无锡江阴；浙江宁波；浙江宁波奉化；浙江宁波余姚；辽宁本溪明山；河南郑州中牟；上海杨浦', '[]', '[]', '抗日战争时期', '', '垄断浙江食盐贸易，高价配给，从中牟利，同时为日军提供军需盐。；参与日伪在舟山的殖民统治，协助日军控制渔业资源，向渔民征收重税。；组织伪保安队，配合日军在镇海沿海巡逻，抓捕抗日游击队员。；管理伪警察，在绍兴城内搜捕抗日地下党，破坏情报网络。；协助伪县长镇压抗日活动，指挥伪军下乡扫荡，烧杀抢掠，无恶不作。；日军占领临海期间组织维持会，为日军提供粮食物资，强迫民众悬挂伪旗。；在苏州工业园区及周边农村实施清乡，设立封锁线，杀害抗日群众。；率伪军协助日军扫荡余姚四明山地区，杀害抗日游击队员。；为日军在杨浦地区修建军事设施和道路，强拆民房。；浙江杭州人，为日伪筹集军费，垄断杭州丝绸贸易，从中牟取暴利。；率伪保安队配合日军扫荡，杀害抗日军民。；推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”。；组织伪保安队，配合日军巡逻舟山海域，搜捕抗日游击队和盟军飞行员。；在镇海（今属宁波）组织维持会，为日军征粮拉夫，破坏镇海抗日游击队活动。；奉化人，任伪区长，强征壮丁，为日军修建工事。；组织地方汉奸维持会，为日军提供粮食和情报。', '[]', '2026-09-10 09:57:13.977457', '2026-09-10 09:57:13.977457', '江苏', '无锡', '江阴', NULL, NULL, NULL, NULL, '');
