INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('67f6b78335204226820ff48af0b97851', '白太冲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁兴县；山西临汾汾西；山西临汾；山西吕梁中阳；山西晋中太谷', '[]', '[]', '抗日战争时期', '', '投靠日军，任太谷县维持会会长及伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。；日军占领太谷后出任伪县长，协助日军推行“治安强化”运动，强征粮税，镇压抗日群众。', '[]', '2026-09-10 09:57:14.019139', '2026-09-10 09:57:14.019139', '山西', '临汾', '汾西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('67ff7963a1224e46acdf7bca3c29121c', '刘映元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼和浩特玉泉；内蒙古呼和浩特', '[]', '[]', '抗日战争时期', '', '投日后任伪巴彦塔拉盟盟长，管辖今呼和浩特及周边旗县，在玉泉区设立伪盟公署分支机构，配合日军推行“蒙地奉上”和鸦片专卖政策。', '[]', '2026-09-10 09:57:13.990121', '2026-09-10 09:57:13.990121', '内蒙古', '呼和浩特', '玉泉', NULL, NULL, NULL, NULL, '');
