INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('682ac1505bd544b98745dec4f0bbaeec', '阎先恕', NULL, NULL, NULL, NULL, 'exact', 'exact', '嘉祥县', '[]', '[]', '抗日战争时期', '', '伪职：嘉祥县伪三区区长→嘉祥县自卫团团长；罪行：嘉祥县纸坊镇阎村人。1938年3月任嘉祥县伪三区区长。1940年成立新民会三区分会，推行“强化治安政策”。1942年组建百余人的自卫团自任团长。1943年被国民党改编为鲁西专署保安第十旅任旅长，近2000人。率部屠杀抗日军民和群众，抢劫抗日政府粮食物资。自1939年至1947年共杀害308人；结局：1947年3月9日被冀鲁豫七分区参谋长杨昆部击毙', '[]', '2026-09-10 09:57:14.087817', '2026-09-10 09:57:14.087817', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('682ed643d67e4e1680d9d551359ee5b4', '王静修', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古赤峰阿鲁科尔沁旗；辽宁沈阳和平；黑龙江绥化绥棱；北京大兴；黑龙江哈尔滨延寿；黑龙江哈尔滨；黑龙江大庆；黑龙江鸡西城子河；黑龙江牡丹江西安；黑龙江牡丹江；吉林_延边_安图；吉林船营；黑龙江绥化望奎；黑龙江绥化；黑龙江牡丹江爱民；黑龙江牡丹江宁安；黑龙江_牡丹江；辽宁大连旅顺口；黑龙江齐齐哈尔克山；黑龙江哈尔滨；黑龙江_伊春_伊美；吉林长春榆树；吉林长春；黑龙江齐齐哈尔富裕；黑龙江伊春；黑龙江黑河；黑龙江黑河逊克；黑龙江鹤岗；山西阳泉矿区；黑龙江哈尔滨依兰；黑龙江哈尔滨；黑龙江黑河；黑龙江黑河五大连池；黑龙江齐齐哈尔；黑龙江哈尔滨宾县；黑龙江绥化；黑龙江牡丹江宁安；黑龙江大庆林甸；黑龙江齐齐哈尔；辽宁沈阳；黑龙江哈尔滨呼兰；黑龙江哈尔滨尚志；黑龙江哈尔滨巴彦；黑龙江哈尔滨；吉林白城镇赉；吉林白城；黑龙江双鸭山；吉林长春；吉林辽源东丰；吉林_长春_南关；吉林长春；吉林；黑龙江佳木斯桦南；吉林、辽宁；黑龙江大兴安岭漠河；黑龙江佳木斯向阳；吉林；辽宁铁岭昌图；辽宁铁岭；黑龙江齐齐哈尔；黑龙江_大兴安岭_加格达奇；黑龙江_齐齐哈尔_碾子山；黑龙江牡丹江；重庆沙坪坝；黑龙江_黑河_孙吴', '[]', '[]', '抗日战争时期', '', '投日后任伪吉林市长，推行奴化教育，强征物资。；指挥警察在船营地区搜捕地下抗日分子，破坏抗日组织，协助日军进行“思想矫正”。；在东丰县任伪县长期间，推行日伪“保甲制度”，组织自卫团，配合日军清乡，抓捕抗日群众，强征壮丁。；在长春（新京）担任伪市长，协助日本进行城市规划和殖民管理，强制推行保甲制度。；负责伪吉林警察机构，搜捕抗日分子，破坏地下组织，协助日军讨伐……（共涉及22个地区的犯罪记录）；伪职：伪奉天警备司令，伪陆军上将；罪行：奉军出身，投敌掌管奉天伪军，维持沈阳及周边治安，围剿抗日武装，配合日军清乡。；结局：1945 被苏军俘获，关押抚顺战犯管理所，病死狱中。', '[]', '2026-09-10 09:57:13.991806', '2026-09-10 09:57:13.991806', '吉林', '白城', '镇赉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('682efad2ac704b99b268b8ed45d8da97', '曾广仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东梅州梅县；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '控制梅县商会，为日军采购粮食、药品等物资，协助日伪对梅县实行经济统制，从中牟利。', '[]', '2026-09-10 09:57:14.027967', '2026-09-10 09:57:14.027967', '广东', '梅州', '梅县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6830a5ccfbf545fdbe8a39127ea2017b', '宋海亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '开封城区', '[]', '[]', '抗日战争时期', '', '伪职：伪开封市商务会会长；罪行：原开封商会执委、梁园春饭庄经理，开封沦陷后出面维持，继而组成伪开封市商务会并出任会长', '[]', '2026-09-10 09:57:14.078019', '2026-09-10 09:57:14.078019', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('683637bfb807466f87d3b8efbaee6ec5', '赵芙亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州德州经开区；山东德州；山东德州德城；山东德州；山东德州庆云；山东德州；山东德州陵城；山东滨州邹平', '[]', '[]', '抗日战争时期', '', '陵城沦陷后出任伪县政负责人，为日军征粮、派夫、维持伪政权。；在日军占领德州期间把持伪商会，为日军筹措物资、摊派款项，协助日伪对德州工商业进行控制与掠夺。；任伪鲁北道尹，管辖包括德州在内的鲁北地区，推行日伪统治，为日军掠夺物资、征发劳工。；齐东（今邹平境内）沦陷后组织维持会，后任伪县长，协助日军统治当地。；在德州沦陷期间任伪商会会长，为日军筹款筹物，协助经济掠夺，属经济领域附逆者。', '[]', '2026-09-10 09:57:14.014043', '2026-09-10 09:57:14.014043', '山东', '德州', '庆云', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6841d36bdf504f52b5f2343ba0ca9637', '张启黄', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北鄂州梁子湖；湖北鄂州；湖北鄂州鄂城；湖北随州广水；湖北孝感安陆；湖北_襄阳_保康；湖北黄冈团风；湖北黄冈；湖北恩施；湖北荆门；湖北天门；湖北荆门京山；河南南阳方城；山西阳泉城区；湖北襄阳；湖北孝感大悟；湖北孝感；湖北武汉蔡甸；湖北武汉武昌；湖北武汉江汉；河南驻马店新蔡；河南驻马店上蔡；湖北_襄阳_宜城', '[]', '[]', '抗日战争时期', '', '日军侵占鄂城后出面组织伪维持会，协助日军维持城区及梁子湖沿岸治安，征发民夫、物资，参与建立伪基层保甲体系。；团风镇本地商人，日军占领团风后组织维持会并任会长，为日军筹集粮草、提供情报，协助管理码头和过往人员。；负责伪武昌市政，协助日军管理城市、征发物资，推行奴化宣传。；抗战期间投敌，在湖北地区担任伪职，协助日军推行经济统制、物资掠夺。；在鄂北地区充任伪职，参与伪政权对随县、应山、安陆一带的统治，协助日军推行治安强化运动。；在鄂北伪政权中任职，活动范围涉及随州、安陆、曾都周边，协助日军推行保甲、征粮和治安强化运动。；任伪汉口特别市地方法院院长，利用司法权迫害抗日人员，维护日伪统治秩序。；上蔡县附逆士绅，任伪维持会会长及伪县长，管辖上蔡及邻近新蔡部分地区，为日军征粮征丁、维持伪政权。；黄冈人，协助雷寿荣组织维持会，为日军带路、指认抗日家属，参与迫害抗日人员。；在京山、天门交界地区协助日军清乡，组织伪保安队，残害百姓。；在襄阳推行奴化教育，篡改教材，向学生灌输亲日思想。；日军侵占鄂城后出面组织维持会，后任伪县长，协助日军征粮、拉夫、推行保甲，维持伪政权统治。；日军侵占鄂城后出面组织伪维持会，后任伪鄂城县政府县长，为日军征粮派款、维持殖民统治，是鄂州地区有明确记载的主要附逆者。；日军侵占鄂城后出面组织伪维持会，后任伪鄂城县政府县长，为日军征粮、拉夫、维持殖民统治秩序。；1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮、派夫、维持治安，协助日军统治南阳城区。；荆门地区投敌分子，组织伪维持会，协助日军控制荆门及周边地区。；安陆地区伪政权头目，配合日军在安陆、孝感边界地区进行统治和扫荡。；在襄阳沦陷区充任伪警察头目，配合日军搜捕抗日人员、镇压民众。；在湖北推行奴化教育，编写伪教科书，宣传“中日亲善”，毒害青少年。', '[]', '2026-09-10 09:57:14.047057', '2026-09-10 09:57:14.047057', '河南', '南阳', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6841f79f156b4df8838f26108b7156f1', '黄士俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波', '[]', '[]', '抗日战争时期', '', '在宁波推行伪化政策，组织汉奸团体，协助日军控制港口和物资。', '[]', '2026-09-10 09:57:14.050849', '2026-09-10 09:57:14.050849', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
