INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6848b29bc63944b488881610cc51560e', '张桐轩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台南宫；河北邢台邢台经开区；河北邢台；河北邢台信都；河北衡水阜城；河北衡水武邑；河北承德隆化；河北承德；河北邯郸；河北；内蒙古赤峰宁城；内蒙古赤峰；河北承德丰宁；河北承德隆化；河北_邯郸_丛台；河北邯郸邯郸冀南；河北邯郸复兴；河北邯郸邯山；河北邯郸；河北邢台沙河', '[]', '[]', '抗日战争时期', '', '组织汉奸保安队，配合日军在丰宁、隆化一带进行“大扫荡”，实行“连坐法”，强迫村民报告抗日活动，杀害无辜群众数十人。；在承德、隆化组织协和会，宣传“日满亲善”，刺探抗日情报，协助日军进行经济掠夺。；率伪军参与对阜城、武邑等地的军事‘讨伐’，杀害抗日军民多人。；任伪顺德道（邢台地区）道尹，积极推行日伪政权统治，协助日军征粮、抓夫、建立保甲制度，镇压抗日力量。；任伪临清县知事期间，积极推行日伪政权各项政策，协助日军征粮派款，镇压抗日民众，破坏中共地下组织。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.990587', '2026-09-10 09:57:13.990587', '内蒙古', '赤峰', '宁城', NULL, NULL, NULL, NULL, '');
