INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('686c7b98a3db4c8e935a3f7580cea199', '杨寿山', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台莱阳；山东烟台海阳；河南安阳文峰；辽宁沈阳新民；河南鹤壁浚县；内蒙古赤峰喀喇沁旗；内蒙古赤峰；山东德州德城；山东德州；山东德州禹城；湖北_天门；河南安阳殷都；河南安阳；内蒙古赤峰红山；内蒙古赤峰', '[]', '[]', '抗日战争时期', '', '在赤峰南部宁城地区组织维持会，投靠日伪，为日军服务。；海阳沦陷后附逆，任伪县长，为日军征粮征夫，协助封锁抗日根据地。；为伪政权筹措经费，横征暴敛，支持日军“以战养战”。；在德州德城基层担任伪保甲长，为日军摊派粮款、监视居民、举报抗日人员，属于基层维持会与保甲系统附逆者。；在安阳推行奴化教育，篡改教材，宣传“中日亲善”，毒害青少年。；任伪浚县警察局长期间，带领伪警察配合日军清乡，抓捕抗日群众，勒索百姓。；在禹城沦陷期间任伪商会会长，配合伪县公署和日军征敛物资，压榨当地商民。；日军侵占赤峰后任伪县长，协助日军建立殖民秩序，推行保甲连坐，镇压抗日群众。；在安阳教育文化领域附逆，通过新民会推行奴化教育，宣传“中日亲善”，协助日军控制安阳学校和文化机构。', '[]', '2026-09-10 09:57:13.990459', '2026-09-10 09:57:13.990459', '内蒙古', '赤峰', '喀喇沁旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('686d52f9f48949eb89a282d7521bbdac', '赵明久', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西梨树；黑龙江鸡西恒山；黑龙江鸡西', '[]', '[]', '抗日战争时期', '', '伪协和会鸡宁分会会长，在鸡西地区推行奴化教育，宣传“日满亲善”，协助日军进行思想控制。；梨树镇伪警察头目，协助日军镇压抗日群众，抓捕抗日人员，推行殖民统治。', '[]', '2026-09-10 09:57:14.066603', '2026-09-10 09:57:14.066603', '黑龙江', '鸡西', '恒山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('686e2ad60a07429fb5c8780cc815e1f8', '王振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山曹妃甸；江西抚州金溪；江西南昌；黑龙江黑河北安；河北衡水；山西晋城城区；河北沧州沧州渤海；山西晋城沁水；河北廊坊广阳；河北廊坊；山东烟台；山东烟台福山；山西晋城阳城；山西、河北；河北沧州沧州经开区；河北沧州沧县；江西抚州临川；河北沧州新华；山西晋城高平；山西晋城；河北唐山滦州；山西晋城泽州；山西晋城；山东滨州滨城；山西长治襄垣；河北沧州盐山；山东滨州；河北邢台清河', '[\"同名\"]', '[]', '抗日战争时期', '', '控制全县粮食及食盐配给，强制低价收购农民粮食供应日军，从中贪污牟利，导致民众饥荒。；日军占领晋城初期出任维持会长，为日军筹粮派款、拉夫修路，强迫商户“欢迎皇军”，并告密导致多名抗日积极分子被捕牺牲。；推行日伪政权法令，强征民夫修筑碉堡公路，搜刮民财。；充当日军爪牙，率伪保安队多次袭击抗日游击队，抓捕并刑讯抗日人员，参与制造多起惨案。；日军占领晋城后组织维持会，为日军提供情报，强征粮款，迫害抗日家属。……（共涉及17个地区的犯罪记录）；在滦州为伪政权兑换军票，剥削百姓。', '[]', '2026-09-10 09:57:14.016218', '2026-09-10 09:57:14.016218', '山东', '滨州', '滨城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6870f0eb2f2b460eb6a8a24596471beb', '方克光', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明安宁；云南德宏芒市；云南德宏芒市；云南德宏梁河', '[]', '[]', '抗日战争时期', '', '方克光在遮放地区投靠日军，组织维持会，协助日军控制遮放、畹町一带，为日军提供情报和后勤支持。；在芒市地区协助龚绶组织伪维持会，负责摊派粮款、登记民户，为日军提供劳工，并参与镇压当地抗日民众。；芒市土司方氏家族成员，日军占领期间曾参与维持会活动。', '[]', '2026-09-10 09:57:13.980406', '2026-09-10 09:57:13.980406', '云南', '德宏', '梁河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('687b7b6e559d4547a24a559600581394', '孙耀庭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西_晋中_太谷；辽宁_营口_盖州；重庆北碚；河南郑州中牟；河南信阳浉河；山西晋城阳城；湖北咸宁赤壁；安徽安庆；江苏_宿迁_宿迁经开区；河北沧州运河；山东临沂河东；山西运城垣曲；河北石家庄桥西；湖北襄阳南漳；辽宁丹东凤城；重庆丰都；江苏淮安洪泽；河南郑州中牟；安徽马鞍山当涂；山西运城绛县；山西运城闻喜；浙江衢州常山；山西_运城；山西_运城_盐湖；重庆璧山；江西吉安峡江；重庆巫溪；重庆云阳；河南信阳信阳高；陕西汉中勉县；陕西汉中汉台；山西运城夏县；四川成都武侯；黑龙江鸡西麻山；江苏连云港连云港高；湖北荆门京山；甘肃甘南合作；山西忻州代县；山西大同天镇；安徽马鞍山；山西吕梁；山西吕梁交城；安徽铜陵铜官；安徽铜陵；河南信阳平桥；山西大同阳高；湖北潜江；辽宁丹东宽甸；内蒙古赤峰巴林左旗；内蒙古赤峰宁城；重庆巫山；上海金山；山西、河北、辽宁；辽宁铁岭开原', '[]', '[]', '抗日战争时期', '', '在交城县率伪军参与“清剿”，杀害抗日村长。；率警备队多次袭击八路军游击队，杀害抗日干部，并参与日军“三光”政策，烧杀抢掠。；充当日军宪兵队密探，多次告密破坏地下抗日组织，致使数十名抗日志士被捕牺牲。；参与日军“三光”政策行动，在代县山区烧毁村庄，屠杀无辜百姓，多次带队突袭抗日根据地。；为日军征收各种苛捐杂税，强征粮食和棉花，导致百姓负担沉重，部分物资被转运至日军军需。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.979464', '2026-09-10 09:57:13.979464', '上海', '金山', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('687ef24913e94ee681c1ec5e3bd81349', '张范民', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉；湖北_武汉_江汉；湖北宜昌远安；湖北宜昌', '[]', '[]', '抗日战争时期', '', '在伪汉口特别市警察局任职，协助日军镇压武汉地区抗日活动，维持伪治安。；任伪汉口特别市警察局局长，统率伪警察配合日军搜捕抗日人员，镇压市民反抗，维持日伪统治秩序。；宜昌沦陷后组织维持会，后任伪宜昌县县长，为日军征发民夫、物资，推行保甲连坐。', '[]', '2026-09-10 09:57:14.056436', '2026-09-10 09:57:14.056436', '湖北', '宜昌', '远安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68800f0921794842a2fdc293827629a9', '马文波', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定高阳；江苏南通通州；河北保定安新；河南郑州；北京、河北；河北保定雄县；河北石家庄；河北保定定兴；河北秦皇岛卢龙', '[]', '[]', '抗日战争时期', '', '在通州推行奴化教育，强制学校教授日语，篡改历史教材，灌输“中日亲善”思想。；率伪警备队多次围剿白洋淀雁翎队，烧毁水村，逮捕抗日家属。；日军占领定兴后率先组织维持会，为日军筹粮派夫，指认抗日积极分子，导致多人被捕。；为日伪政权征收苛捐杂税，强抢粮食，供应日军军需，压榨百姓。；率伪军驻扎高阳、蠡县交界，多次进攻八路军游击队，烧毁抗日村庄，抢掠物资，并杀害地方抗日干部。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995106', '2026-09-10 09:57:13.995106', '河北', '保定', '安新', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('688155d8668a40db973b864712d382e2', '王英部属', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西榆林神木；陕西榆林府谷', '[]', '[]', '抗日战争时期', '', '伪绥西联军所部在绥远、伊克昭盟、陕北北部边缘活动，配合日军进攻绥西和陕北抗日根据地，曾窜扰神木、府谷黄河沿岸。', '[]', '2026-09-10 09:57:14.064700', '2026-09-10 09:57:14.064700', '陕西', '榆林', '神木', NULL, NULL, NULL, NULL, '');
