INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68979011c8c7475a9b62d7c55089e45f', '马兴连', NULL, NULL, NULL, NULL, 'exact', 'exact', '铜山北部', '[]', '[]', '抗日战争时期', '', '伪职：伪铜山伪军司令，土匪出身；罪行：投靠日军，自立武装，劫掠乡村，残害百姓，多次袭扰抗日地方武装。；结局：被新四军武装剿灭击毙。', '[]', '2026-09-10 09:57:14.082619', '2026-09-10 09:57:14.082619', '江苏', '徐州', NULL, NULL, NULL, NULL, NULL, '');
