INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68af5573182f49e1911ed4cefb0f9388', '瞿伯阶', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林辽源龙山；湖南湘西泸溪；湖南张家界桑植；吉林辽源龙山；湖南怀化溆浦；吉林辽源龙山', '[]', '[]', '抗日战争时期', '', '湘西地方武装头目，抗战后期与日军及伪政权勾连，接受伪职，在湘西永顺、龙山等地活动，袭击抗日游击队。；无；湘西龙山人，长期在湘西地区为匪，抗战期间与日伪及地方势力有复杂关系，未积极抗日。；在龙山组织伪维持会，为日军提供物资和情报，协助日军维持占领区秩序，活动范围接近怀化、溆浦。；湘西龙山、桑植一带土匪，抗战时期曾与日军勾结，在湘西北地区活动，其势力范围覆盖桑植周边，配合日军进行地方控制。；湘西龙山、永顺一带土匪首领，抗战时期曾与日伪方面有联系，接受伪军委任，在湘西地区扩张势力，对抗地方政府和抗日力量。；湘西龙山人来凤一带活动，土匪武装，抗战后期与日伪有联系，在湘西边境配合日军行动。', '[]', '2026-09-10 09:57:14.058319', '2026-09-10 09:57:14.058319', '湖南', '张家界', '桑植', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68cb05cbcd4e4f4d82b399cc11eb0890', '陈传礼', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄；河北邢台临城', '[]', '[]', '抗日战争时期', '', '在临城（今枣庄薛城）充任伪警察头目，控制铁路沿线，迫害抗日群众。', '[]', '2026-09-10 09:57:14.014490', '2026-09-10 09:57:14.014490', '山东', '枣庄', NULL, NULL, NULL, NULL, NULL, '');
