INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68cb19e636e74a0cb1946d57301b18e9', '王振远', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南鹤壁淇县；河南鹤壁浚县；河南鹤壁鹤山；河南鹤壁淇县；河南鹤壁浚县', '[]', '[]', '抗日战争时期', '', '在浚县任伪县长期间，推行日军政令，征发民夫修筑据点与公路，配合日伪军扫荡抗日根据地。；淇县沦陷后带头组织维持会，协助日军建立伪政权，强征民夫、物资，镇压当地抗日活动。；率伪保安团配合日军进攻抗日根据地，在浚县、淇县一带抓捕抗日人员，残害百姓。', '[]', '2026-09-10 09:57:14.049131', '2026-09-10 09:57:14.049131', '河南', '鹤壁', '浚县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('68d1ad99b00343a09f5d072559f1f7af', '蔡羹舜', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖', '[]', '[]', '抗日战争时期', '', '伪职：汪伪芜湖县长、清乡督察专员；罪行：主持芜湖清乡，设立清乡机构，清查户口、物资封锁，围剿皖南抗日力量。；结局：战后汉奸审判重刑。', '[]', '2026-09-10 09:57:14.081114', '2026-09-10 09:57:14.081114', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6903f1091afc439e8aa25372c05ee234', '杨筱泉', NULL, NULL, NULL, NULL, 'exact', 'exact', '随县环潭镇', '[]', '[]', '抗日战争时期', '', '伪职：环潭维持会会长；罪行：1939年5月随县城沦陷后，纠集流氓地痞于南门口摆香案、打“太阳旗”、放鞭炮欢迎日军进街，致使日军烧了半条街的房屋，杀害十多名无辜百姓，强奸数十名妇女。后与浙河汉奸头子王楚逸勾结，暗地充当环潭维持会长，搜集情报、贩卖敌货、发国难财；结局：1939年6月被中共随县常备第五中队地下党设计获取委任状后押送县政府，经县参议会联席会议决定立即处决', '[]', '2026-09-10 09:57:14.080775', '2026-09-10 09:57:14.080775', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
