INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('69bbe17333d2448b89d9c6120d498116', '王冠英', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江哈尔滨五常；河北邯郸丛台；河北邯郸邯山；河北邯郸；河北；河北邢台南宫；河北邢台巨鹿', '[]', '[]', '抗日战争时期', '', '伪职：后期伪冀南道道尹；日本投降后勾结郭采芹、郭化民死守邯郸城，改换国民党番号顽抗；全盘继承日伪统治体系，继续反共清乡邯郸党史网。；结局：1945 邯郸解放被俘，公审处决；伪职：后期伪冀南道道尹，冀南道最高伪行政长官；日降后勾结郭采芹固守邯郸，改换国民党番号继续反共。；结局：1945 邯郸解放被俘，公审处决；为日军充当顾问，参与策划对南宫、巨鹿等地的‘铁壁合围’，提供抗日武装情报。；组织伪保安队，配合日军扫荡丛台周边村庄，杀害抗日干部和群众，抢劫物资。；日军占领邯郸后率先组织维持会，为日军筹粮派款，提供情报，并参与建立伪县政权，迫害抗日家属，破坏地下抗日组织。；率伪军多次扫荡邯山周边村庄，制造多起惨案，抢劫物资并配合日军清剿游击队。；率伪军多次袭击冀南抗日游击队，杀害抗日军民，抢劫物资，破坏地下交通线。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.044846', '2026-09-10 09:57:14.044846', '河北', '邢台', '南宫', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('69bdfd60dc57415588b5cd98b7b8fb54', '马云涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '博山县', '[]', '[]', '抗日战争时期', '', '伪职：伪博山县长（末任）；罪行：1944年冬接替曲化儒，成为博山最后一任伪县长，至1945年8月日本投降', '[]', '2026-09-10 09:57:14.069966', '2026-09-10 09:57:14.069966', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
