INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6a384f9fbbd2437fb64a7e301b0e770a', '米子祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西忻县；忻县', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：首任伪忻县县长；罪行：日军入城牵头组建维持会；推行保甲十家连坐，设立粮谷公会掠夺粮食，抓捕城内地下抗日人员。；结局：1945 被俘，汉奸罪判处 8 年徒刑；伪任职务：伪忻县首任县长，组建维持会，推行保甲连坐，搜捕地下人员。结局：判处 8 年徒刑，服刑后释放', '[]', '2026-09-10 09:57:14.076594', '2026-09-10 09:57:14.076594', '山西', '忻州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6a3f9c5a3e61405aab24466dd14db66a', '简学美', NULL, NULL, NULL, NULL, 'exact', 'exact', '江陵岑河口', '[]', '[]', '抗日战争时期', '', '伪职：叛徒（原三区武工队分队长）；罪行：原根据地三区武工队分队长，被简化轩拉拢收买后带枪叛变投敌。随简化轩逃进岑河口日军据点，为日军提供情报，公然为敌人外出劫掠当向导\"\"；结局：被江陵县公安局手枪队活捉，经公审后处决', '[]', '2026-09-10 09:57:14.078108', '2026-09-10 09:57:14.078108', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6a4ffca051a04b8b90998d43d3e34bdb', '吴振铎', NULL, NULL, NULL, NULL, 'exact', 'exact', '东宁、老黑山要塞周边', '[]', '[]', '抗日战争时期', '', '伪职：伪东宁县警务科特务股长；罪行：专门针对边境地下党组织，破坏东宁老黑山党支部，抓捕抗日人员，配合要塞警备。；结局：日本投降后潜逃，后被捕获审判。', '[]', '2026-09-10 09:57:14.077480', '2026-09-10 09:57:14.077480', '黑龙江', '牡丹江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6a55787d6be94594a1206648e5e80103', '赵连升', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯富锦；黑龙江佳木斯汤原；黑龙江佳木斯同江；黑龙江佳木斯；黑龙江七台河桃山；黑龙江七台河；黑龙江牡丹江；黑龙江绥化肇东；黑龙江绥化', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军在七台河、桃山一带“扫荡”，烧毁村屯，杀害抗联伤员和群众。；率保安队参与‘三江大讨伐’，在佳木斯周边山区搜捕抗联战士，烧毁抗联密营，杀害伤员。；亲自带队抓捕抗联联络员，严刑逼供后处决，并参与“汤原大搜捕”行动，破坏多处秘密据点。；原绥化富商，投敌后任伪协和会会长，协助日军进行奴化宣传，组织“勤劳奉仕队”为日军服劳役，强征青年充当伪军。；在牡丹江地区主持伪警务，指挥特务警察破坏抗联地下联络站，诱降抗联叛徒，参与制造多起屠杀事件。；日本籍参事官，实际控制富锦县政，推行“粮谷出荷”政策，强征农民粮食，导致大量饿殍。', '[]', '2026-09-10 09:57:14.065149', '2026-09-10 09:57:14.065149', '黑龙江', '七台河', '桃山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6a56d77a88fb40178384bc28598809dd', '康达多尔济', NULL, NULL, NULL, NULL, 'exact', 'exact', '达拉特旗', '[]', '[]', '抗日战争时期', '', '伪职：达拉特旗札萨克；一度摇摆，与包头日伪往来，接受伪伊盟公署委任，暗中给日伪输送物资，后迫于压力回归国民政府阵营。；结局：抗战胜利后居家，管制处理', '[]', '2026-09-10 09:57:14.082771', '2026-09-10 09:57:14.082771', '内蒙古', '鄂尔多斯', NULL, NULL, NULL, NULL, NULL, '');
