INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ac5ea4223e4455ba5275e0d5a1b4ac0', '王荫槐', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉青山；湖北武汉武昌；江苏徐州邳州；江西萍乡安源；江西萍乡', '[]', '[]', '抗日战争时期', '', '为日军征收苛捐杂税，强抢粮食，导致邳州百姓饥荒，民怨极大。；抗战期间在武昌伪政权中任职，协助日军管理武昌地区。；组织伪保安团，配合日军对萍乡周边乡村进行扫荡，强征粮食、抓丁拉夫，并参与镇压当地抗日游击队。', '[]', '2026-09-10 09:57:14.035278', '2026-09-10 09:57:14.035278', '江西', '萍乡', '安源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6acf2d1ebf9440898baa2aefe268f592', '曹俊峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '稷山', '[]', '[]', '抗日战争时期', '', '伪职：伪稷山警备大队长；罪行：驻守稷山、翟店据点，多次袭扰稷麓抗日根据地。；结局：解放后镇压处决', '[]', '2026-09-10 09:57:14.074231', '2026-09-10 09:57:14.074231', '山西', '运城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ad02578c7fc43a9bca885ccbdfeb94c', '陈桐', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴上虞；浙江杭州建德；浙江金华东阳；浙江湖州南浔；浙江绍兴；浙江杭州临安；浙江绍兴诸暨；浙江绍兴；浙江金华永康；浙江金华；浙江台州；浙江台州临海；浙江湖州', '[]', '[]', '抗日战争时期', '', '日军占领东阳初期任维持会长，组织汉奸团体为日军提供情报，协助建立伪政权。；南浔沦陷后组织伪维持会，为日军提供情报并强迫商户缴纳“慰劳金”。；建德沦陷后组织维持会，为日军提供向导和情报。；日军初占金华时出任维持会长，负责为日军筹集物资、维持治安，协助日军建立伪政权。；协助日军在临海建立据点，镇压抗日群众。；负责湖州地区伪军整编，协助日军围剿新四军和游击队，多次率伪军下乡“清剿”，杀害抗日群众。；浙江绍兴人，继任伪临安县长，在临安实施“清乡”，配合日军烧毁山区抗日据点，杀害多名抗日游击队员。；指挥伪保安队，配合日军在梁湖、丰惠等地扫荡，逮捕抗日群众。；负责绍兴地区“清乡”行动，设立封锁线，搜捕抗日武装。', '[]', '2026-09-10 09:57:14.049797', '2026-09-10 09:57:14.049797', '浙江', '台州', '临安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ad38528a98f4c6780c5ce422751bd55', '陈耀平', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东肇庆四会；广东肇庆；广东肇庆广宁；广东肇庆封开；广东肇庆德庆；广东珠海；广东肇庆怀集；广东珠海香洲；广东珠海', '[]', '[]', '抗日战争时期', '', '日军侵占肇庆后出面组织伪维持会，协助日军征粮、拉夫、维持治安，镇压抗日群众。；日军侵占怀集期间出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军搜集情报并诱迫乡民归顺。；抗日战争期间在珠海地区组织伪维持会，协助日军维持地方治安、征粮征税，并参与搜捕抗日人士。；抗日战争期间在德庆县组织伪维持会，协助日军维持地方统治，征派粮秣、劳工，参与镇压抗日活动。；日军侵占四会后出面组织伪维持会，协助日军征粮、拉夫、维持治安，镇压抗日群众。；日军侵占珠海地区后，出面组织伪维持会，协助日军征粮、拉夫、维持治安，镇压抗日群众。；抗日战争时期在广宁地区组织伪维持会，协助日军维持地方治安、征粮派款，镇压抗日群众。；抗日战争期间在封开地区组织伪维持会，协助日军维持地方治安、征粮派款，镇压抗日群众。', '[]', '2026-09-10 09:57:14.029930', '2026-09-10 09:57:14.029930', '广东', '珠海', '香洲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ad9fe7890284791863f48b2f6ca8c1f', '刘云亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '杞县', '[]', '[]', '抗日战争时期', '', '伪职：杞县县长；罪行：河北人，1943年12月县公署改为县政府后担任县长', '[]', '2026-09-10 09:57:14.077754', '2026-09-10 09:57:14.077754', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6adf4ffdc12945edacf92cfe03b8b5b0', '李仲三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口崇礼；河北张家口涿鹿；河南南阳；河北保定定州；河北保定徐水；河北保定涿州；辽宁沈阳新民；北京、河北；河北保定定兴；辽宁沈阳新民；河北保定阜平；辽宁本溪平山；北京房山', '[]', '[]', '抗日战争时期', '', '投靠日军，任房山县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。；负责日伪宣传和奴化教育，组织‘新民会’搜集抗日情报，强迫民众参加反共集会。；日军占领定县后，出任维持会长，为日军筹集物资，强征民夫，协助建立伪县署。；指挥伪警察搜捕抗日地下党员，破坏中共地下组织，多次带队袭击徐水周边村庄。；主持新民会涿县分会，推行奴化教育，组织“反共救国会”，搜集抗日情报，协助日军抓捕进步青年。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.994334', '2026-09-10 09:57:13.994334', '北京', '房山', '定兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ae50cafb73a48b2af1a4dfce330ec2e', '刘子亮', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南洛阳', '[]', '[]', '抗日战争时期', '', '洛阳周边偃师县沦陷后出任伪知事，协助日军征粮征丁。', '[]', '2026-09-10 09:57:14.048451', '2026-09-10 09:57:14.048451', '河南', '洛阳', NULL, NULL, NULL, NULL, NULL, '');
