INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b1f9a931e1e44bd82512ca0426278aa', '王仁堪', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州闽侯', '[]', '[]', '抗日战争时期', '', '闽侯地区沦陷期间，组织伪闽侯县维持会并任会长，为日军征派粮食、民夫，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.062213', '2026-09-10 09:57:14.062213', '福建', '福州', '闽侯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b27b68a841e4cf6b6df14afacb64afc', '王兴仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海文登；山东威海；山东烟台莱山；山东威海；山东威海威海临港经开区；山东威海；山东威海荣成；山东烟台牟平；辽宁沈阳大东；山东烟台', '[]', '[]', '抗日战争时期', '', '威海卫伪警察头目，协助日军维持威海卫治安，抓捕抗日人员。；投敌后任伪威海卫专员，管理威海地区伪政权，配合日军海上封锁和陆上扫荡，镇压文登、荣成一带抗日武装。；日军侵占荣成后，出面组织伪维持会，协助日军征粮、征夫，维持伪政权统治，镇压当地抗日群众。；在烟台伪政权任职，其辖区与威海相邻，协助日军控制胶东沿海，征发物资劳工。；在烟台推行奴化教育，改编教材，宣传“大东亚共荣圈”，毒害青年学生。；任伪荣成县长期间，协助日军控制威海东部沿海地区，征发民夫、物资。；莱阳维持会头目，为日军筹粮筹款，协助建立伪政权，活动范围覆盖莱山。', '[]', '2026-09-10 09:57:14.013058', '2026-09-10 09:57:14.013058', '山东', '威海', '威海临港经开区', NULL, NULL, NULL, NULL, '');
