INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b81baece16b414aa8065e3ef91b2c53', '孙伯文', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_连云港_东海；安徽宿州；安徽宿州泗县；江苏徐州鼓楼；江苏徐州云龙', '[]', '[]', '抗日战争时期', '', '任伪泗县县长期间，配合日军修筑据点，封锁抗日根据地。；主持伪警察局，协助日军维持占领区秩序，搜捕抗日地下人员，迫害爱国群众。；利用商会身份，为日军强制征收商业税，垄断物资，强迫商户捐献钱财，并暗中向日军提供经济情报。；长期担任云龙区伪区长，强征壮丁，配合日军“治安强化运动”，迫害当地百姓。', '[]', '2026-09-10 09:57:14.008035', '2026-09-10 09:57:14.008035', '安徽', '宿州', '云龙', NULL, NULL, NULL, NULL, '');
