INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b89a110489648748a4c2c1e53ca1f15', '王继能', NULL, NULL, NULL, NULL, 'exact', 'exact', '岱山、登步、普陀沿海', '[]', '[]', '抗日战争时期', '', '伪职：伪军舟山保安总队主力司令；罪行：原地方武装头目投敌，手握大批海岛伪军；大鱼山战斗主力伪军，配合日军围剿东海游击武装，海岛烧杀劫掠岱山新闻网。；结局：抗战胜利后被国民党收编，后清算伏法。', '[]', '2026-09-10 09:57:14.084512', '2026-09-10 09:57:14.084512', '浙江', '舟山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b8c4ef48ca3463aba9d45c8875739dd', '野元甚藏', NULL, NULL, NULL, NULL, 'exact', 'exact', '日本，关东军特务', '[\"野本甚藏\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：受关东军派遣，跟随安钦活佛入藏；潜伏日喀则，搜集西藏军政、寺院、交通情报，是第一位成功潜入后藏的日本特工。。结局：日本战败后从印度遣返回日本', '[]', '2026-09-10 09:57:14.085087', '2026-09-10 09:57:14.085087', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b8c744ecffd4dd8b35d572903db7cd1', '周训德', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉', '[]', '[]', '抗日战争时期', '', '伪职：文化汉奸；罪行：伪《大楚报》文化汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.076610', '2026-09-10 09:57:14.076610', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b9043e9720b4d819489123ff19a3b67', '陈裔', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德福安；福建福州；山西阳泉城区；福建福州长乐；福建南平光泽；福建福州；福建福州闽侯；福建福州；福建莆田城厢；福建莆田；福建福州连江；福建泉州永春；福建宁德古田；福建福州；山西阳泉城区；福建厦门；福建龙岩长汀；福建龙岩；福建福州；福建南平武夷山', '[]', '[]', '抗日战争时期', '', '福州仓山人，1941年日军占领福州期间在仓山地区充任伪维持会委员及保甲长，协助日军登记户口、征派劳役、催缴物资，直接参与仓山地区的日伪基层统治。；福州商界人物，日军占领福州期间加入伪维持会，利用商会关系为日军筹款筹粮，协助控制福州经济。；长乐伪保安大队头目，率伪军配合日军清剿长乐抗日游击队，残害当地抗日军民。；闽侯地区附逆人物，日军侵占福州及闽侯期间，出面组织维持会，为日军征派物资、协助伪化统治。；福州及闽侯地区伪维持会头目，为日军筹粮、维持秩序，影响波及莆田、仙游一带。；莆田本地士绅，日军侵占莆田沿海期间出面组织维持会，为日军筹粮、派夫、维持地方秩序，协助伪政权在城厢及周边地区建立保甲体系。；连江人，日军侵占连江期间组织伪维持会，为日军征粮征夫，协助日军镇压当地抗日活动，残害连江民众。；在厦门及闽南地区推行奴化教育，组织伪民众团体，协助日军进行思想控制。；厦门沦陷后长期任伪市长，配合日军统治厦门及闽南沿海地区。；福州沦陷时组织伪维持会，维持日军占领秩序，征发民夫、物资，影响包括闽东在内的福建沿海。；福州第一次沦陷期间出面组织伪维持会，为日军筹粮、派夫、维持治安，协助日军控制福州城区。；福建人，抗战后期投敌，任伪闽北绥靖军司令，在南平、建阳、武夷山一带配合日军扫荡抗日根据地。；长汀本地劣绅，日军侵扰闽西期间组织伪维持会，为日军带路、筹粮，协助建立伪保甲，迫害抗日群众。长汀为龙岩地区重要县份，其伪维持会直接服务于当地日军。；福州沦陷时出任伪职，协助日军管理福州事务，推行保甲制度。；在永春推行保甲连坐，协助日军抓捕抗日志士，镇压当地抗日活动。；在日军占领福州期间任伪福州警察局局长，协助日军搜捕抗日人士、维持伪治安、推行保甲连坐。；福州沦陷期间在伪维持会任职，协助日军推行伪化管理和物资征集。；福州人，福州第一次沦陷时参与组织伪维持会，协助日军镇压抗日活动，为日军筹粮筹款。；福州人，福州两次沦陷期间任伪维持会副会长，协助日军筹粮、拉夫，镇压抗日民众。；福州人，参与伪福州维持会活动，协助日军在福州城区推行保甲与物资征调。', '[]', '2026-09-10 09:57:14.060446', '2026-09-10 09:57:14.060446', '福建', '南平', '光泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6b9355b7af2348ea8dcb40af53b55aad', '刘冠儒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原阳曲；山西晋城；山西晋城陵川；山西；山西太原示范；山西晋城阳城；山西晋城高平；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '利用司法机构迫害抗日群众，以“反满抗日”罪名判处爱国人士死刑或劳役。；率伪保安队多次袭击抗日游击队，烧毁村庄，杀害无辜群众。；在陵川县实施“三光政策”配合，纵容伪军烧杀抢掠，残害抗日干部数十人。；指挥伪警察搜捕抗日地下党员，严刑逼供，破坏中共阳城地下组织。；主持新民会，推行奴化教育，组织“青少年团”为日军服务，告密抗日活动。', '[]', '2026-09-10 09:57:14.021563', '2026-09-10 09:57:14.021563', '山西', '太原', '示范', NULL, NULL, NULL, NULL, '');
