INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6c49ee81202447f3813a744d43b7141d', '王敬斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；河南商丘豫东综合物流产业聚集；河南商丘；河南商丘；河南商丘柘城；河南开封顺河；河南开封；河南开封通许；河南开封；河南信阳息县；河南信阳；河南信阳；河南南阳桐柏；河南驻马店确山；青海黄南河南', '[]', '[]', '抗日战争时期', '', '虞城沦陷后组织维持会，为日军筹集物资，协助日军控制虞城及商丘东部地区。；开封沦陷后参与组织维持会，为日军筹粮筹款、安抚地方。；柘城沦陷后组织维持会，协助日军建立伪政权，征发物资。；在开封任伪职期间推行日军殖民政策，协助征发劳工、粮食，镇压抗日活动。；在河南沦陷区推行奴化教育，编写亲日教材，组织学生参加亲日活动，为日伪培养顺民。；在日军扶植下出任伪市长，推行伪政令，配合日军统治开封。；在伪河南绥靖军任职，驻开封地区，配合日军扫荡抗日武装。；统领伪绥靖军配合日军在河南南部包括信阳、息县一带进行扫荡，镇压抗日武装。；在信阳西部桐柏地区组织维持会，协助日军控制山区交通，征发民夫。', '[]', '2026-09-10 09:57:14.046174', '2026-09-10 09:57:14.046174', '河南', '信阳', '息县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6c6dcfe92dcb4adcb7c5bae2e6a81a6f', '赵金科', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台信都；河北', '[]', '[]', '抗日战争时期', '', '利用新民会宣传奴化思想，组织汉奸情报网，向日军提供抗日活动情报，协助抓捕进步群众。；率剿共队多次深入信都山区“清剿”，实行烧光、杀光、抢光政策。', '[]', '2026-09-10 09:57:14.044753', '2026-09-10 09:57:14.044753', '河北', '邢台', '信都', NULL, NULL, NULL, NULL, '');
