INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d0d813551884a9792c5b8a8898c7d88', '仁钦道尔吉', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在伪兴安北省警备军任职，配合日军在呼伦贝尔地区行动。', '[]', '2026-09-10 09:57:13.988542', '2026-09-10 09:57:13.988542', '内蒙古', '呼伦贝尔', '扎赉诺尔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d0d9f9193984fe6aef9ee8bf21e4ec3', '梁朝玑', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西桂林荔浦；广西柳州；广西梧州岑溪；广西梧州；广西桂林七星；云南普洱西；广西桂林阳朔；云南普洱西；广西梧州万秀；广西梧州；广西玉林容县；广西贵港桂平；广西桂林灌阳；湖南郴州桂东；广西玉林；广西南宁上林；广西南宁；广西桂林象山；广西桂林；云南普洱西；广西桂林；广西梧州藤县；云南普洱西；广西梧州长洲；广西梧州；云南普洱西；广西桂林；广西玉林兴业；广西玉林', '[]', '[]', '抗日战争时期', '', '抗战后期投靠日军，组织伪保安部队，在南宁周边地区配合日军扫荡抗日游击队。；日军第二次入侵广西期间，在南宁组织伪维持会，协助日军征粮、拉夫，并参与搜捕抗日人士。；在广西沦陷区担任伪保甲长，协助日军征派物资、监视民众。；广西籍汉奸，抗战期间投靠日伪，在广西日占区参与伪政权与伪警察事务。；在玉林地区组织伪保安大队，配合日军扫荡抗日游击队，捕杀抗日群众。；广西籍人，投靠汪伪政权，任伪广西省政府主席，协助日军在广西推行伪化统治。；梧州沦陷后出面组织伪商会，为日军筹款筹粮，压迫商户。；抗战时期在广西沦陷区附近参与伪政权维持活动，协助日军推行殖民统治，具体任职于桂南一带伪组织。；日军曾策动其出任伪广西保安司令，但其未就任，后撤往后方。；广西籍人，投靠汪伪政权，任伪广西省省长，协助日军在广西推行伪化统治，在桂林等地进行诱降与维持会组织活动。；广西籍旧军人，抗战期间投靠汪伪政权，被任命为汪伪广西省政府主席，虽因广西大部分地区未沦陷而未实际主政，但参与伪政权对广西的策反与渗透活动。；广西籍旧军人，抗战期间投靠汪伪，被任命为汪伪广西省政府主席，虽因广西大部未沦陷而未实际主政，但其附逆行为与广西、桂林地区有直接政治关联。；广西籍人，抗战期间投靠汪伪政权，参与在华南及广西边境的伪军招抚与联络活动，协助日军对广西进行政治诱降。；在广西南部及桂东南一带为日军搜集情报、策动地方势力投敌，配合日军对桂林、柳州等地的进攻。；桂林沦陷后参与伪广西省军事组织，统率伪保安部队配合日军扫荡抗日游击队、维护占领区治安。；1944年日军发动豫湘桂战役占领桂林后，出面组织伪桂林维持会，协助日军维持地方秩序、征发物资。；桂系出身，抗战后期在日军侵占广西期间出面组织伪维持会，协助日军维持桂林、柳州等地治安，为日军征发民夫物资。；广西籍人，投靠汪伪政权，被任命为汪伪广西省政府主席，负责在广西沦陷区推行伪化统治，配合日军对广西的侵略与控制。；抗战后期日军侵入广西时，出面组织伪维持会，后任汪伪广西省政府主席，协助日军维持占领区秩序、征发物资。；在岑溪及梧州周边担任伪保甲长，为日军征粮、派夫，协助维持占领区基层统治。；部分地方史料提及广西沦陷区有维持会组织，但具体姓名与玉林、兴业关联缺乏可靠记载。；在桂平地区组织伪维持会，协助日军征粮派夫，活动范围与玉林地区相邻。；在广西沦陷区从事亲日宣传，为日军侵略辩护，影响波及梧州文化教育界。', '[]', '2026-09-10 09:57:14.031007', '2026-09-10 09:57:14.031007', '广西', '南宁', '上林', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d1aba45183342338d0bbc7d16c5e0f8', '胡朝珍', NULL, NULL, NULL, NULL, 'exact', 'exact', '犁桥', '[]', '[]', '抗日战争时期', '', '伪职：犁桥伪地方骨干；罪行：追随叶茂华、郜德恩，刺探游击武装动向，告密抓捕地下工作人员，敲诈乡间百姓。；结局：锄奸行动就地镇压。', '[]', '2026-09-10 09:57:14.088173', '2026-09-10 09:57:14.088173', '安徽', '铜陵', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d201136eb34400188658366edf1f7b5', '刘勤', NULL, NULL, NULL, NULL, 'exact', 'exact', '庆安、绥棱宋万金屯', '[]', '[]', '抗日战争时期', '', '伪职：伪庆安警务科特务；罪行：潜伏监视于天放等抗联地下人员，刺探抗联小分队行踪，搜集救国会情报，多次参与搜捕行动绥化新闻网。；结局：解放后被清算镇压。', '[]', '2026-09-10 09:57:14.087623', '2026-09-10 09:57:14.087623', '黑龙江', '绥化', NULL, NULL, NULL, NULL, NULL, '');
