INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d2ffdeb5fdf4dbc94646e203d8d947e', '刘星台', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城茌平；山东聊城；山东_青岛；山东潍坊；山东潍坊昌邑；河北衡水深州；河北衡水', '[]', '[]', '抗日战争时期', '', '伪山东省委员，参与聊城地区伪政权事务。；在衡水地区组织新民会，进行奴化宣传，协助日军统治。；推行奴化教育，篡改教材，向学生灌输亲日思想。；在昌邑为日军筹集物资，协助日军控制沿海地区。', '[]', '2026-09-10 09:57:14.016612', '2026-09-10 09:57:14.016612', '山东', '潍坊', '茌平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d35ebc27eb0421cbef1552830254cc2', '张仲鲁', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；河南南阳邓州；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '1945年日军侵入邓县期间，组织新民会，进行亲日宣传，协助日军维持地方统治。；在伪河南省政府任职，推行奴化教育，篡改教材，宣传“中日亲善”，其教育政策覆盖河南沦陷区包括南阳。', '[]', '2026-09-10 09:57:14.046648', '2026-09-10 09:57:14.046648', '河南', '南阳', '邓州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d39823894ba4532aeb91cbc32fcc8f4', '许友超', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建厦门；福建泉州惠安；福建厦门；福建三明尤溪；福建厦门；福建厦门湖里；福建厦门', '[]', '[]', '抗日战争时期', '', '厦门沦陷后与日军合作，控制商会与物资配给，为伪政权筹款筹物，属经济领域附逆者。；在厦门与日伪合作，参与经济统制与地方事务。；厦门地方人物，参与维持会活动，协助日军管理厦门及闽南地区。；厦门沦陷后组织伪维持会，后任伪厦门特别市商会会长，为日军筹款筹粮，配合经济掠夺，与泉州、惠安商界有联系。；厦门侨商出身，沦陷后参与伪维持会，为日军筹款并协助控制侨汇与物资。；厦门沦陷后投敌，任伪职，协助日军经济掠夺，与泉州商界有联系。', '[]', '2026-09-10 09:57:14.060269', '2026-09-10 09:57:14.060269', '福建', '三明', '尤溪', NULL, NULL, NULL, NULL, '');
