INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d70e8b8835f45cfbca5646ff75ad409', '张效良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州静乐；山西；山西吕梁文水', '[]', '[]', '抗日战争时期', '', '率伪保安队多次配合日军扫荡文水山区抗日根据地，抓捕抗日干部，烧毁村庄，杀害无辜百姓。；在日军占领五台期间，组织维持会，协助日军推行“治安强化”运动，强征民夫修筑炮楼和公路，并配合日军扫荡抗日根据地，残害抗日军民。；负责在宁武推行奴化教育，宣传‘中日亲善’，组织汉奸团体刺探抗日情报，并协助日军建立保甲制度，强化殖民统治。；在静乐推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众参加反共集会，收集抗日情报提供给日军特务机关。；任伪警察局长期间，协助日军建立情报网，侦捕地下党员，参与制造多起屠杀事件，强征劳工送往东北。', '[]', '2026-09-10 09:57:14.020236', '2026-09-10 09:57:14.020236', '山西', '吕梁', '文水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d712f99abd54f5787abe29e62e25792', '李春荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山滦州；河北唐山；河北；黑龙江齐齐哈尔克东；河北唐山；河北承德宽城；河北承德', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山郊区掠夺土地，导致农民流离失所。；在承德、宽城交界地区指挥伪警察队，多次袭击抗日根据地，杀害抗日干部和群众，并参与制造“无人区”行动。；在唐山郊区为日军提供粮食，欺压佃农。', '[]', '2026-09-10 09:57:14.042073', '2026-09-10 09:57:14.042073', '河北', '唐山', '滦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d73c4164bc84998bcb8948901a5d6a8', '王之佑', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江伊春乌翠；黑龙江伊春；黑龙江黑河北安；吉林白城大安；吉林；黑龙江牡丹江；黑龙江佳木斯；吉林白城白城经开区；吉林', '[]', '[]', '抗日战争时期', '', '作为佳木斯市最高伪职，推行奴化教育，强制市民学习日语，配合日军“治安肃正”，多次组织搜查抗日分子。；原吉林省警务处长，投日后任牡丹江省省长，配合日军“讨伐”抗联，强征劳工。；协助于琛澂指挥伪军，在伊春、乌翠一带的山区多次组织“搜山”行动，杀害抗联伤员和支援群众。；原吉林省防军军官，投日后任伪吉林警备军司令，多次率伪军在白城、洮南、开通等地清剿抗日力量。；原东北军军官，投敌后任伪满吉林警备军参谋长，参与策划对白城、大安地区抗日游击队的围剿。；指挥伪军配合日军“讨伐”抗联第三路军，制造多起惨案。', '[]', '2026-09-10 09:57:13.999279', '2026-09-10 09:57:13.999279', '吉林', '白城', '大安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d75ad9e7e844687bd189313ce4d986a', '蒋辉若', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃临夏，早年在宁夏马福祥部任职', '[\"蒋文焕\"]', '[]', '抗日战争时期', '伪军', '伪任职务：原马家军旧部，包头沦陷后投日，出任伪回军总司令、西北保商督办公署督办；日军计划利用他向西渗透宁夏，策反马鸿逵，在绥远组建伪军武装，威胁宁夏边境。。结局：抗战胜利后被捕，以汉奸罪处决', '[]', '2026-09-10 09:57:14.080175', '2026-09-10 09:57:14.080175', '甘肃', '临夏', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6d7aaffd6e0c4770aece8a1fe9eec1a2', '李慧民', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁嘉鱼；湖北咸宁赤壁', '[]', '[]', '抗日战争时期', '', '嘉鱼沦陷后组织维持会，协助日军维持地方秩序、征派物资与人员。；蒲圻（今赤壁）沦陷后投敌，任伪维持会会长、伪县长，协助日军统治，搜刮民财，破坏抗日组织。', '[]', '2026-09-10 09:57:14.055186', '2026-09-10 09:57:14.055186', '湖北', '咸宁', '嘉鱼', NULL, NULL, NULL, NULL, '');
