INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6dafc05deb0c47679bcdab866da1f228', '宝音扎布', NULL, NULL, NULL, NULL, 'exact', 'exact', '察哈尔右翼后旗', '[]', '[]', '抗日战争时期', '', '伪职：蒙奸，伪察哈尔盟旗参事；协助日伪管控察哈尔各旗，征调壮丁编入伪蒙古军，搜集草原情报。；结局：战后判处徒刑', '[]', '2026-09-10 09:57:14.077504', '2026-09-10 09:57:14.077504', '内蒙古', '乌兰察布', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6dba077f474a4d358f83ed6f4ad9c316', '五河县伪警察所所长', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠五河', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '五河沦陷期间，伪警察所负责地方治安，配合日军搜捕抗日人员，压迫民众，具体姓名在现存史料中多不完整。', '[]', '2026-09-10 09:57:14.010372', '2026-09-10 09:57:14.010372', '安徽', '蚌埠', '五河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6dce60569f7d4789bf5ee54f7f5a014d', '朱方隅', NULL, NULL, NULL, NULL, 'exact', 'exact', '南昌县', '[]', '[]', '抗日战争时期', '', '伪职：伪南昌县县长；罪行：汪伪南昌县首任伪县长，组建伪县府，推行保甲，为日军征缴粮谷；来源：江西网、南昌县文史资料；备注：南昌县伪政权一把手', '[]', '2026-09-10 09:57:14.068822', '2026-09-10 09:57:14.068822', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6dd4109c247246c1a4506c5c7c93a5ce', '吴伯', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌海海南；海南_五指山；海南_琼海；海南东方；内蒙古乌海海南；海南定安；海南文昌；海南三沙中沙；内蒙古乌海海南；海南琼中；海南万宁', '[]', '[]', '抗日战争时期', '', '在万宁组织伪维持会，为日军征粮、带路，协助日军控制万宁沿海地区。；参与组织伪琼崖临时政府，协助日军推行殖民统治，在海南地区进行诱降、征粮和维持治安等附逆活动。；参与伪琼崖临时政府筹建与运作，协助日军推行殖民统治，镇压抗日民众。；协助詹松年维持伪政权，推行日军殖民统治政策，参与征粮、征夫和镇压抗日群众。；负责伪警察系统，配合日军清乡，在海南北部包括琼山、文昌、定安等地镇压抗日群众。；在海南伪政权中掌管警务，配合日军搜捕抗日人员，推行治安强化，迫害民众。；海南伪政权警务头目，参与组建伪警察队伍，配合日军镇压抗日群众，搜捕抗日人员。；文昌本地士绅，日军登陆文昌后出面组织维持会，为日军筹粮、派夫、带路，协助建立伪基层政权。；海南沦陷后附逆，担任伪琼崖临时政府主席，为日军在海南的统治提供所谓行政支持，推行伪化政策。；日军侵占定安后出面组织维持会，协助日军征粮、派夫、维持地方秩序，为日伪基层政权服务。', '[]', '2026-09-10 09:57:14.053306', '2026-09-10 09:57:14.053306', '海南', '三沙', '中沙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6de8c80697c94730afc87dbd3da4e05a', '沈维周', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京通州', '[]', '[]', '抗日战争时期', '', '在日军占领通县后出任伪县长，推行日伪政策，强征粮食和壮丁，协助日军维持治安。', '[]', '2026-09-10 09:57:13.995038', '2026-09-10 09:57:13.995038', '北京', '通州', NULL, NULL, NULL, NULL, NULL, '');
