INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6dff9688d5f243c598ee65f9e9abd6d4', '吴建中', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳汨罗；湖南岳阳；湖南岳阳岳阳屈原管理；江西南昌；湖南长沙天心；湖南长沙；江西抚州；湖南岳阳；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '在伪江西省政府任职期间兼任伪南昌市市长，推行日军殖民统治政策，配合经济统制与物资掠夺。；在洞庭湖区协助日军控制水路，为日军征集船只与粮秣。；控制岳阳商会为日军筹集物资，协助实行经济统制，从中牟利并压制商户。；率伪保安大队配合日军守备岳阳、汨罗铁路线，多次参与对抗日根据地的扫荡。；担任伪警察头目，在抚州地区搜捕抗日人员，配合日军实施治安强化运动。；宁乡沦陷期间投敌，组织伪维持会，配合日军扫荡长沙西部乡村。', '[]', '2026-09-10 09:57:14.039502', '2026-09-10 09:57:14.039502', '江西', '抚州', '岳阳屈原管理', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e01f6b43a384422ab44428e473a182d', '姜姓汉奸', NULL, NULL, NULL, NULL, 'exact', 'exact', '鄂城华容镇', '[]', '[]', '抗日战争时期', '', '伪职：华容街汉奸（侦缉队）；罪行：华容街上的汉奸侦缉队成员，欺压百姓，为日军搜集情报；结局：1939年10月被秦俊明率领游击队员除掉', '[]', '2026-09-10 09:57:14.085522', '2026-09-10 09:57:14.085522', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
