INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e171c69549c4b9e93694584bdfc5de1', '王守信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西大同灵丘；山西晋中和顺；山西晋中寿阳', '[]', '[]', '抗日战争时期', '', '投靠日军，任灵丘县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '[]', '2026-09-10 09:57:14.021138', '2026-09-10 09:57:14.021138', '山西', '大同', '灵丘', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e2dd8b8ff504079b743e472bbf8f98b', '郑孝先', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆北碚', '[]', '[]', '抗日战争时期', '', '在文化领域附逆，组织亲日文艺演出，撰写文章美化日军侵略。', '[]', '2026-09-10 09:57:14.064075', '2026-09-10 09:57:14.064075', '重庆', '北碚', NULL, NULL, NULL, NULL, NULL, '');
