INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e447565ddf3453184053b6169b13f16', '吴竹林', NULL, NULL, NULL, NULL, 'exact', 'exact', '通城县', '[]', '[]', '抗日战争时期', '', '伪职：通城自治会（维持会）会长；罪行：通城水口乡人，读过书，做过裁缝。死心塌地的汉奸，为报答日军扶植，四处宣扬日军“安民”政策，强迫百姓交银洋领“良民证”，向百姓摊派各种物资作为日军军事供给，组织巡逻队四处打探，帮助日军提防抗日武装袭扰；结局：待考（当地百姓对其深恶痛绝，编有顺口溜：“会长吴竹林，做过裁缝淘过金，办出事来拐煞人”）', '[]', '2026-09-10 09:57:14.074540', '2026-09-10 09:57:14.074540', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e612199ec014d65917fcf3b5880bde8', '赵阿荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_嘉兴_平湖', '[]', '[]', '抗日战争时期', '', '为日伪政权征收苛捐杂税，强征百姓财物，导致民不聊生，并贪污部分税款中饱私囊。', '[]', '2026-09-10 09:57:14.050424', '2026-09-10 09:57:14.050424', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e6191b586174be4bd225d88f8656fe9', '孙庆余', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山滦州；河北唐山', '[]', '[]', '抗日战争时期', '', '在滦南地区（今属唐山）组织伪自卫团，残害抗日军民。', '[]', '2026-09-10 09:57:14.041819', '2026-09-10 09:57:14.041819', '河北', '唐山', '滦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e658aa128fc44e39e1cfeefbd66ee31', '李德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治沁源；山西太原娄烦；山西长治壶关；山西长治屯留；山西长治沁县；山西；山西吕梁交城；山西_运城_垣曲；山西晋城；山西晋城沁水；山西晋中榆社', '[]', '[]', '抗日战争时期', '', '日军占领交城后率先组织维持会，为日军筹粮派款，强迫百姓领取“良民证”。；率保安队配合日军扫荡抗日根据地，抓捕抗日干部和群众，抢掠物资。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，破坏抗日统一战线。；在沁水组织“青年训练班”，灌输亲日思想，为日军输送伪军人员。；在日军占领期间任伪警察局长，负责侦缉抗日地下人员，严刑拷打被捕者，并协助日军推行“治安强化运动”。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019967', '2026-09-10 09:57:14.019967', '山西', '吕梁', '交城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e661f94dba04f9a9a755d6158a5346b', '徐铁珊', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；安徽安庆宿松；浙江宁波江北；河南信阳', '[]', '[]', '抗日战争时期', '', '控制信阳火车站搬运与物资，为日军转运掠夺物资，协助稽查抗日人员。；安庆沦陷后任伪警察局长，统领伪警察配合日军搜捕抗日人员、镇压市民反抗、管制交通与物资，是安庆城区伪警特系统的主要负责人。；望江沦陷后组织维持会，协助日军控制长江北岸交通线，征发民夫物资，活动范围邻近宿松。', '[]', '2026-09-10 09:57:14.007597', '2026-09-10 09:57:14.007597', '安徽', '安庆', '宿松', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e66ab77775244a2b251609e2e576992', '董福亭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁朝阳龙城；吉林长春朝阳', '[]', '[]', '抗日战争时期', '', '原土匪头目，投日后在朝阳、龙城一带驻防，多次率伪军袭击抗日武装，烧毁村庄，屠杀平民。', '[]', '2026-09-10 09:57:14.063336', '2026-09-10 09:57:14.063336', '辽宁', '朝阳', '龙城', NULL, NULL, NULL, NULL, '');
