INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e71f225812d43b3acb8d1bb7e42da12', '陶明德', NULL, NULL, NULL, NULL, 'exact', 'exact', '靖江县城', '[]', '[]', '抗日战争时期', '', '伪职：伪靖江县警察局局长；罪行：掌控伪警察武装，割据靖江县城；既与蔡鑫元互相火并，又效忠日伪，盘剥港口商运，抓捕爱国人员泰州市党史...。；结局：抗战胜利后被俘惩处。', '[]', '2026-09-10 09:57:14.084442', '2026-09-10 09:57:14.084442', '江苏', '泰州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e799370c32a4284872fec1a8fa83934', '李凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东聊城冠县；山西阳泉城区；河北唐山滦州；河北唐山；山西吕梁石楼；山西吕梁离石；河北沧州运河；河北衡水；山东潍坊；江苏徐州贾汪；河北承德滦平；河北承德；河北石家庄深泽；辽宁沈阳新民；河北石家庄辛集；河北邢台威县；河北邢台新河；河北石家庄灵寿；河北邢台清河；江苏连云港海州；江苏连云港东海；河北石家庄新乐；山东滨州无棣；山东滨州沾化；河北石家庄栾城；辽宁沈阳新民；河北；河北衡水饶阳；山东淄博博山；河北石家庄赵县；江苏_连云港_赣榆；河北邢台广宗；辽宁沈阳新民；河北_沧州_献县；河北保定曲阳；河北邢台巨鹿；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '为日军宣传奴化思想，组织汉奸情报网，刺探抗日军情，协助日军搜捕抗日分子。；在唐山市区维持伪秩序，协助日军宪兵队镇压反抗。；日军占领宽城后出任维持会长，为日军征粮派夫，协助建立伪政权，镇压抗日活动，民愤极大。；投靠日伪，任承德县保安队长，率伪军配合日军扫荡滦平、承德山区，杀害抗日军民。；效忠日寇，负责情报搜集，破坏地下党组织，逮捕并刑讯抗日志士。……（共涉及32个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.016077', '2026-09-10 09:57:14.016077', '山东', '滨州', '无棣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e8a1371393340cdad527e23cd0f3fa9', '李福林', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆；云南普洱西；广东惠州惠城；广东广州番禺；广东广州；广东江门；湖南怀化怀化洪江管理；河北邢台南和；广东惠州惠东；广东惠州；海南三沙西沙；广西北海；广东广州', '[]', '[]', '抗日战争时期', '', '协助日军搜查西门住户，没收抗日书籍，抓捕青年。；在惠城周边乡村推行保甲连坐，举报抗日家属，协助日军征丁征粮。；在西沙群岛为日军招募伪军，协助日军巡逻岛屿、控制渔民和掠夺资源。；广东番禺人，原国民党将领，广州沦陷后投敌，组织伪军配合日军。；广东地方实力派投敌，所部伪军在珠江三角洲包括江门、新会地区配合日军维持治安。；统管广东南路伪军警，推行“清乡”政策，在北海及周边地区镇压抗日力量，强征劳工。；广州地区地方势力人物，广州沦陷后参与伪维持会活动。；广东人，抗战期间投靠日军，组织伪军，在华南和华中地区进行伪化活动。；参与组织惠州伪维持会，协助日军征发物资、登记户口与推行伪化教育。', '[]', '2026-09-10 09:57:14.006751', '2026-09-10 09:57:14.006751', '安徽', '安庆', '番禺', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e8bb8e3fefd4a1596e6aa51af98288f', '阎振海', NULL, NULL, NULL, NULL, 'exact', 'exact', '柳林大武', '[]', '[]', '抗日战争时期', '', '伪职：伪据点伪军头目；罪行：盘踞大武，随同贺焕之作恶，多次进山袭扰。；结局：1945 大武战斗被俘处决', '[]', '2026-09-10 09:57:14.079425', '2026-09-10 09:57:14.079425', '山西', '吕梁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e8f07317f3445b686825318b56e95a8', '特木尔巴根', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰阿鲁科尔沁旗；内蒙古兴安科尔沁右翼前旗；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '任伪旗警务科长，指挥伪警察配合日军搜捕抗日人员，维持当地殖民治安。；蒙古族，曾在伪兴安北省公署任职，参与伪满地方政权事务，其活动范围包括呼伦贝尔地区。；在科尔沁右翼前旗担任伪警务科长，负责伪警察队伍，配合日军搜捕抗日人员，推行保甲连坐，直接镇压当地民众。', '[]', '2026-09-10 09:57:13.987865', '2026-09-10 09:57:13.987865', '内蒙古', '兴安', '科尔沁右翼前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6e9319df059049f890d88720ace4426a', '徐荫堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '固镇、新马桥', '[]', '[]', '抗日战争时期', '', '伪职：伪固镇维持会会长、伪区长；罪行：固镇投敌劣绅，迎接日军进驻固镇，建立基层伪组织，管控津浦铁路固镇段，盘查抓捕爱国人士。；结局：抗战胜利后汉奸审判伏法。', '[]', '2026-09-10 09:57:14.081986', '2026-09-10 09:57:14.081986', '安徽', '蚌埠', NULL, NULL, NULL, NULL, NULL, '');
