INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ea755c9899d4db4824f6bfe4c50c748', '姜颂平', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏；南通城、通如海启', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪特工总部苏北分区区长（朱公馆特务头子）；罪行：建立南通最大特务机关 “朱公馆”，网罗大批地痞流氓充当特务；搜捕地下党组织，策反抗日人员，为清乡提供情报支持。；结局：抗战胜利后被逮捕，以汉奸罪判刑。；伪任职务：汪伪特工总部苏北分区区长，南通特工总站头目，南通地区特务最高负责人；抓捕、刑讯地下抗日人员，策反我方人员，汤景延团谈判对手。。结局：抗战胜利捕获，汉奸罪判处死刑执行枪决', '[]', '2026-09-10 09:57:14.067305', '2026-09-10 09:57:14.067305', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
