INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ef30ebe46484e4ab99918471476574e', '高练武', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西湖口；彭泽县（今属九江）', '[]', '[]', '抗日战争时期', '', '伪职：伪财政科长；罪行：伪湖口县政府财政科长，为日军筹措粮款物资；来源：抗日战争纪念网；备注：湖口伪政权文职人员；伪职：伪彭泽县政府财政科科长；罪行：流芳袁门口人，为日军管理伪政府财政，征收捐税、搜刮物资、为日军提供经费；结局：史料未明确记载其最终结局（来源：彭泽伪政府核心官员，彭泽为汪伪江西省政府辖县）', '[]', '2026-09-10 09:57:14.069164', '2026-09-10 09:57:14.069164', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
