INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f3e26536db74923994a76881d109d87', '倪道烺', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠；蚌埠（伪省府）；安徽池州贵池；安徽池州；安徽蚌埠；安徽蚌埠龙子湖；安徽滁州凤阳；安徽_合肥_庐江；安徽_合肥_庐阳；安徽_合肥_肥东；安徽_合肥_长丰；安徽安庆；安徽_淮南_凤台；安徽_滁州_天长；安徽蚌埠；安徽阜阳；安徽马鞍山；安徽芜湖；安徽合肥；安徽阜阳；重庆_大足；安徽合肥；安徽_宿州_泗县；安徽_宿州_灵璧；安徽淮南寿县；蚌埠伪省府，籍贯今阜南抖音百科；安徽阜阳；安徽黄山；安徽阜阳；安徽合肥；安徽安庆；安徽_宣城；安徽蚌埠；安徽_淮南_谢家集；安徽滁州；安徽淮南谢家集；安徽蚌埠；安徽合肥；安徽阜阳；安徽宣城；安徽淮南；安徽阜阳；安徽蚌埠；山西阳泉矿区；安徽淮南田家庵；安徽阜阳；安徽淮北；安徽合肥；安徽_淮北；安徽淮南八公山', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪安徽省维新政府省长、汪伪安徽省政府主席（首任），省府蚌埠，搜刮物资、贩毒、强征劳工抖音百科。结局：1951 年蚌埠公审枪决；伪职：伪维新政府安徽省省长、汪伪安徽省首任省主席；罪行：北洋旧官僚，伪安徽政权奠基人，完整搭建省级伪行政、警务、教育体系；推行清乡、奴化统治，镇压皖北抗日力量抖音百科。；结局：抗战胜利被捕，1951 年押回蚌埠公审枪决抖音百科。；伪职：汪伪安徽省首任省主席（阜南县倪新寨人，驻蚌埠）；罪行：阜阳籍最大汉奸，主持安徽沦陷区伪政权；推行清乡、抓捕抗日军民，强征劳工，开设鸦片馆，设立慰安所，搜刮安徽沦陷区物资供给日军。；结局：抗战胜利被捕，1951 年蚌埠公审枪决抖音百科。', '[]', '2026-09-10 09:57:14.004209', '2026-09-10 09:57:14.004209', '安徽', '阜阳', '凤阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f4c1aea298f42bf9f02a4a0ebb98865', '张光第', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州宁津；山东德州；山东滨州阳信；辽宁沈阳大东；山东德州夏津；山东德州武城；山东德州平原；山东德州', '[]', '[]', '抗日战争时期', '', '在武城县（今属德州）任伪县知事，为日军筹集军粮，组织伪自卫团，对抗抗日武装。；在滨县推行奴化教育，编写亲日教材，组织学生参拜神社，宣传“大东亚共荣”。；德州沦陷后组织维持会，迎接日军入城，为日军筹办粮秣、夫役，维持伪秩序。；齐河邻近德州、平原，任伪县长期间协助日军征粮征丁，推行治安强化，镇压抗日活动。', '[]', '2026-09-10 09:57:14.013887', '2026-09-10 09:57:14.013887', '山东', '德州', '夏津', NULL, NULL, NULL, NULL, '');
