INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f5708ed2c58459ea9e008b4a59238a3', '徐朴诚', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波；安徽安庆；安徽六安金寨；安徽六安；安徽芜湖；浙江绍兴上虞；山西吕梁兴县；江苏常州天宁；山西阳泉城区；浙江湖州吴兴；江苏常州新北；浙江台州；浙江宁波北仑；浙江宁波镇海；陕西_西安；浙江杭州；陕西渭南；安徽芜湖芜湖经开区；上海金山；江苏无锡江阴；江苏无锡宜兴；江苏镇江丹徒；浙江绍兴诸暨；浙江绍兴；江苏吴江', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪和平军第一师师长，盘踞浙北嘉兴、嘉善，祸害杭嘉湖根据地。结局：抗战胜利被国民党收编，后被俘处决', '[]', '2026-09-10 09:57:13.979338', '2026-09-10 09:57:13.979338', '上海', '金山', '金寨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f5a65c793ad495087fe4aa39825d88b', '姚法普', NULL, NULL, NULL, NULL, 'exact', 'exact', '安阳（国民党投敌）', '[]', '[]', '抗日战争时期', '', '伪职：国民党安阳县县长；罪行：原国民党安阳县政府驻西部山区岭头村；1943年5月率众投降日军，充当日伪汉奸，仍盘踞岭头一带统治群众；结局：1943年5月，抗日武装向投降日军的姚法普政府发起进攻，消灭汉奸武装保安队五百多人', '[]', '2026-09-10 09:57:14.076330', '2026-09-10 09:57:14.076330', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f6c32c2ef0e46b5accadc21dbf43274', '王槐山', NULL, NULL, NULL, NULL, 'exact', 'exact', '海城', '[]', '[]', '抗日战争时期', '', '伪职：凌印清伪部副手汉奸；罪行：协助凌印清招匪、策反义勇军，充当日军爪牙。；结局：同案被义勇军公审枪决中国·鞍山。', '[]', '2026-09-10 09:57:14.076782', '2026-09-10 09:57:14.076782', '辽宁', '鞍山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f702bc177bb4c5c86372db072d62213', '徐良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津；云南普洱西；天津南开；天津北辰；湖南常德津；重庆_大足；陕西西安长安；天津红桥', '[]', '[]', '抗日战争时期', '', '在天津地区执行伪华北政务委员会指令，参与推行治安强化运动。；负责协调日伪在津政务，参与奴化教育和资源统制。；组织“新民会”天津分会，在南开各学校、街道建立情报网，检举抗日分子，强迫居民参加“反共救国”游行。；协助伪市长温世珍处理政务，参与制定奴化政策，管理伪政府行政事务，压制反日言论。；负责伪政权在天津的行政协调，参与推行“中日亲善”宣传，协助日军控制天津港。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.002614', '2026-09-10 09:57:14.002614', '天津', '北辰', '长安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f7193f0fce549f3bc14f74fe5e1d097', '张宗昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城高唐；山东聊城', '[]', '[]', '抗日战争时期', '', '原山东军阀，九一八事变后寓居天津，与日本特务机关往来，企图借日军势力重返山东，其旧部在鲁西北包括聊城、高唐一带活动，对地方伪化有间接影响。', '[]', '2026-09-10 09:57:14.017857', '2026-09-10 09:57:14.017857', '山东', '聊城', '高唐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f77294f5b014d98ab53eb7b6d1913db', '图布升吉尔格勒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯；云南普洱西', '[]', '[]', '抗日战争时期', '', '公开投日，在郡王旗悬挂日本旗，强迫旗民向日军献马献粮，并阻挠成吉思汗陵西迁中的抗日宣传。', '[]', '2026-09-10 09:57:13.992039', '2026-09-10 09:57:13.992039', '内蒙古', '鄂尔多斯', '鄂托克前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f7b74ae36774d2a8c86e14b016797f3', '刘二狗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；河北衡水武邑；山西晋中左权；河北邯郸涉县', '[]', '[]', '抗日战争时期', '', '化装成农民混入村庄，指认抗日积极分子，导致多人被捕杀。；充当日军特务，跟踪暗杀抗日人员，多次带路突袭涉县村庄，制造多起血案。', '[]', '2026-09-10 09:57:14.022546', '2026-09-10 09:57:14.022546', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f7bafba593941e48896767c884401c3', '孔繁蔚', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁邹城', '[]', '[]', '抗日战争时期', '', '在邹县推行奴化教育，改编教材宣扬“中日亲善”，毒害青少年。', '[]', '2026-09-10 09:57:14.015763', '2026-09-10 09:57:14.015763', '山东', '济宁', '邹城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f7fbe9ef3b7469693237d6adc8f89c0', '李仙洲', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁；山东菏泽成武；山东菏泽；山东济宁汶上；山东菏泽单县；山东菏泽；河南焦作博爱；河南焦作；山东菏泽牡丹；广西桂林资源；山东菏泽；山东菏泽', '[]', '[]', '抗日战争时期', '', '后投日任伪职，在山东包括济宁地区配合日军维持治安，进攻抗日武装。；推行奴化教育，篡改教材，强迫学生学日语，为日军殖民统治培养顺民。；菏泽沦陷后投敌，主持伪县政，推行奴化教育，强征民夫修筑菏泽至成武、单县公路及据点，配合日军对鲁西南抗日根据地扫荡。；在菏泽沦陷期间任伪县知事，推行伪化教育，强征民夫修筑据点，配合日军对菏泽周边抗日武装进行扫荡。；山东人，抗战期间投靠日军，任伪山东省政府委员、伪鲁西道尹等职，在鲁西地区推行伪化统治，协助日军掠夺资源、镇压抗日力量。；在伪山东省政府任职期间，参与鲁西地区伪政权建设，协助日军推行治安强化运动，其辖区包括菏泽、鄄城一带。；率伪警备队驻守焦作，配合日军清乡，抓捕抗日军民。；在菏泽地区参与伪政权活动，协助日军推行保甲与征粮，镇压抗日群众。', '[]', '2026-09-10 09:57:14.015682', '2026-09-10 09:57:14.015682', '山东', '济宁', '汶上', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f829ee194b54dc9b0d477fecc3798bc', '杨文会', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定安新', '[]', '[]', '抗日战争时期', '', '亲自带队搜捕雁翎队交通员，严刑拷打抗日群众，罪行累累。', '[]', '2026-09-10 09:57:14.040851', '2026-09-10 09:57:14.040851', '河北', '保定', '安新', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f8775b9b594472ab515abd792c3e381', '王景岳', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北石家庄井陉；河北石家庄石家庄循环化工园；河北；井陉长岗村；河北石家庄井陉矿；河北石家庄；河北唐山玉田', '[]', '[]', '抗日战争时期', '', '伪职：维持会会长，唯一一任伪井陉县长，兼新民会会长；全县修筑 60 余座炮楼、200 余里封锁沟，捕杀大批抗日干部，掠夺矿产土地；日本投降后摇身投靠国民党，任先遣第八旅旅长。；结局：潜逃甘肃天水，1951 年抓捕押回井陉，公审处决；在玉田推行奴化教育，强制学校使用伪满教材，迫害爱国教师。；日军占领初期组织维持会，为日军筹集粮款，提供情报，协助建立伪政权。；投日矿务官员，继任伪井陉矿务局局长，扩大煤炭生产供日军军需，组织矿工“勤劳奉仕”，镇压矿工罢工和抗日活动。；任伪石家庄市长期间，推行日伪经济统制政策，强征粮食和物资供应日军，并协助建立“新民会”等汉奸组织。；在获鹿县推行保甲制度，强征民夫修建炮楼，协助日军清乡。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042166', '2026-09-10 09:57:14.042166', '河北', '唐山', '玉田', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6f91b8a9dad54aaa8a05ae337e90216b', '李用宾', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆宜秀；安徽安庆；安徽安庆安庆经开区；安徽安庆怀宁；安徽合肥长丰；安徽合肥；安徽安庆潜山；安徽安庆；安徽安庆宿松；安徽安庆', '[]', '[]', '抗日战争时期', '', '安庆周边怀宁县伪政权头目，协助日军在安庆近郊推行保甲制度、征粮征丁。；在长丰地区（今属合肥）组织伪维持会，为日军带路，强征粮食，杀害抗日游击队家属。；安庆及怀宁沦陷后，出面组织伪维持会，为日军筹粮筹款，协助建立伪基层政权。；桐城沦陷后组织维持会并任伪县长，活动于桐城、安庆一带，协助日军维持占领区秩序。；安庆商界人物，抗战期间与日军合作，主持伪商会，为日军筹款筹粮、控制物资流通，并参与伪维持会活动，属经济领域附逆者。；潜山沦陷期间出面组织伪维持会，为日军征派粮秣、夫役，协助维持潜山地区伪统治。', '[]', '2026-09-10 09:57:14.006224', '2026-09-10 09:57:14.006224', '安徽', '合肥', '长丰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fa19094b16a4d8b9d321bac9c030c0a', '胡锡侯', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '蔚县；北京延庆', '[]', '[]', '抗日战争时期', '', '伪职：伪蔚县县长；蔚县是晋察冀根据地前沿，修筑大量碉堡，疯狂抓捕抗日军民，制造多起惨案中共张家口...。；结局：蔚县解放群众公审死刑；在延庆县城及各乡镇设立警察分所，抓捕中共地下党员，刑讯逼供，破坏平北地委在延庆的交通站。', '[]', '2026-09-10 09:57:13.994016', '2026-09-10 09:57:13.994016', '北京', '延庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fa42397ea054ecca113ef55182933ae', '何介青', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州北湖', '[]', '[]', '抗日战争时期', '', '为日军筹款筹物，控制沦陷区商业，协助日军经济掠夺。', '[]', '2026-09-10 09:57:14.059775', '2026-09-10 09:57:14.059775', '湖南', '郴州', '北湖', NULL, NULL, NULL, NULL, '');
