INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fad4ce1867e427bb6e8a38b7f803185', '郭英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北张家口', '[]', '[]', '抗日战争时期', '', '在张家口地区建立伪警察体系，指挥特务抓捕抗日分子，沽源县亦在其控制下。', '[]', '2026-09-10 09:57:14.042711', '2026-09-10 09:57:14.042711', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fc949a25fe141c9a328c8cfdb6d84a2', '张亚南', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济南历城；山东济南历下；山东济南；山东济宁济宁高；辽宁沈阳新民；山东济南章丘；山东济南长清；山东济南；山东济南；山东_济南；山东济南莱芜', '[]', '[]', '抗日战争时期', '', '掌管伪警察系统，参与搜捕抗日人员、推行保甲连坐。；掌管济南伪警察系统，参与搜捕抗日人员、推行保甲连坐。；掌管伪济南警察系统，搜捕抗日人员，维持日伪治安。；在历城地区任伪县长，推行保甲制、征粮征夫，配合日军对历城周边抗日根据地进行扫荡。；济南商界附逆代表人物，协助日军摊派捐款、物资，控制商会为伪政权服务。；莱芜沦陷后任伪县知事，建立伪政权，配合日军扫荡莱芜抗日根据地。；组织伪新民会，进行亲日宣传，协助日军推行保甲、征粮、抓丁，监视民众思想，镇压抗日言论。；在济南工商界为日伪筹款筹物，协助经济统制与宣传奴化。；章丘伪政权头目，配合日军清乡、征粮，镇压当地抗日武装。；组织商界附逆，为日军筹款筹物。；控制济南商会，为日军征购物资、摊派捐款，协助经济统制。', '[]', '2026-09-10 09:57:14.015004', '2026-09-10 09:57:14.015004', '山东', '济南', '历下', NULL, NULL, NULL, NULL, '');
