INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fceb58de3e64a55be03e80719fc0df0', '张永德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京延庆', '[]', '[]', '抗日战争时期', '', '负责为日军征收田赋和苛捐杂税，在延庆地区强征“治安费”，中饱私囊，导致农民破产。', '[]', '2026-09-10 09:57:13.994104', '2026-09-10 09:57:13.994104', '北京', '延庆', NULL, NULL, NULL, NULL, NULL, '');
