INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6fe9074e48704f5594defa8db592d88f', '陈光寒', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城滨海；江苏盐城阜宁；江苏盐城响水', '[]', '[]', '抗日战争时期', '', '伪职：伪阜宁县县长；罪行：原地方游击武装副司令，率部投敌；执掌阜宁伪县公署，出动伪武装下乡扫荡盐阜根据地，抓捕迫害抗日军民。；结局：1945 年被俘，公审处决。', '[]', '2026-09-10 09:57:14.036420', '2026-09-10 09:57:14.036420', '江苏', '盐城', '响水', NULL, NULL, NULL, NULL, '');
