INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('6ffa4422a0e54aee902242b8f7115a73', '李春润', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林经开区；吉林；吉林通化东昌；吉林松原前郭尔罗斯；黑龙江黑河北安；黑龙江牡丹江东安；黑龙江鸡西虎林；吉林舒兰；吉林白山；吉林白山临江；吉林通化二道江；黑龙江绥化安达；黑龙江绥化；黑龙江绥化肇东；河北承德平泉；河北承德；黑龙江哈尔滨；黑龙江哈尔滨延寿；辽宁本溪南芬；黑龙江牡丹江绥芬河；黑龙江哈尔滨木兰；黑龙江齐齐哈尔富裕；黑龙江齐齐哈尔；黑龙江齐齐哈尔；黑龙江齐齐哈尔碾子山；吉林、河北、辽宁；黑龙江哈尔滨五常；黑龙江绥化；吉林长春宽城；吉林；黑龙江佳木斯富锦；黑龙江鹤岗绥滨；河北唐山；吉林桦甸；吉林白城；辽宁锦州；辽宁阜新；黑龙江大庆大庆高；黑龙江绥化兰西；黑龙江绥化；黑龙江佳木斯同江；黑龙江鹤岗绥滨；黑龙江鹤岗萝北', '[\"投敌后改名李春荣\", \"注：同名抗日烈士，此处为延寿汉奸\", \"投敌后\"]', '[]', '抗日战争时期', '', '原为抗日武装成员，后叛变投敌，熟悉抗联活动规律，带领日伪军多次突袭南芬山区抗联营地。；积极宣传“日满亲善”，协助日伪当局推行“保甲连坐”制度，检举抗日分子，导致多名抗联联络员被捕牺牲。；在舒兰地区组织伪警察队，多次参与搜捕抗联地下组织。；在吉林市抓捕抗日志士，参与“思想矫正”运动，迫害平民。；强抓唐山青壮年送往东北或日本做苦工，造成大量死亡。；为日本特务机关搜集平泉、承德抗日武装活动情报，导致多支游击队被破坏。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.998918', '2026-09-10 09:57:13.998918', '吉林', '松原', '前郭尔罗斯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7003c4aee82b4a9182705dd13fd367d0', '王明宇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '利用协和会组织，在南芬矿区进行奴化宣传，诱骗青年加入伪军，收集抗日情报。', '[]', '2026-09-10 09:57:14.063413', '2026-09-10 09:57:14.063413', '辽宁', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7015c856a25c432387efce92498d26fc', '赵戴文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁柳林；陕西西安周至；云南普洱西；陕西宝鸡；山西太原杏花岭；山西太原；山西晋中左权；云南普洱西；陕西宝鸡；山西吕梁兴县；山西吕梁；云南普洱西；山西；山西太原小店；山西晋城；江苏无锡锡山；山西太原示范；云南普洱西；山西；山西太原；山西太原古交；山西太原；陕西西安蓝田；云南普洱西；山西太原晋源', '[\"投敌争议，但据史料有附逆行为\", \"注：此为历史争议人物，但未投敌，故不列入\", \"注：此处为误传，实际未投敌，但历史资料中曾出现其名被冒用，故不列入\", \"附逆争议\", \"注：此人为历史人物，但未投敌，此处不列\", \"注：此人为阎锡山幕僚，但未投日，故不列入\"]', '[]', '抗日战争时期', '', '虽未实际掌权，但曾接受日伪名义职务，为伪政权提供象征性支持。；无；注：此人为阎锡山幕僚，未投日，不应列入。故不收录。；太原沦陷初期参与组织维持会，为日军提供物资和情报，后因内部矛盾被日军弃用。；太原沦陷后参与组织维持会，为日军提供粮食和劳役，协助建立伪政权。；太原沦陷后一度出任伪维持会会长，为日军占领太原提供行政支持，后因内部矛盾被撤换。；太原沦陷后投敌，组织维持会，为日军征粮派款，协助建立伪政权，后因内部矛盾被撤换。；太原沦陷初期，曾参与组织维持会，为日军提供地方秩序管理支持，后因内部矛盾被撤换。……（共涉及8个地区的犯罪记录）；虽曾为国民党元老，太原失守后接受伪职，为日军出谋划策，协助组建伪保安队。', '[]', '2026-09-10 09:57:14.020081', '2026-09-10 09:57:14.020081', '山西', '吕梁', '兴县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7019250186be4dc29e660edfc6eb2b8a', '郑德明', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建龙岩长汀；辽宁沈阳大东；福建宁德屏南；福建宁德霞浦；福建宁德；福建宁德柘荣；福建宁德；福建福州平潭；福建南平建瓯；福建南平；福建宁德古田；福建宁德', '[]', '[]', '抗日战争时期', '', '福建籍新闻汉奸，在沦陷区创办伪报，宣扬“大东亚共荣”，为日军侵略福建各地（包括龙岩、长汀）制造舆论。；在福宁府（今宁德一带）参与伪维持会活动，协助日军征粮征工，压迫当地百姓。；组织伪保安团在闽北地区活动，配合日军对南平、建瓯一带的抗日根据地进行扫荡，烧杀抢掠，残害百姓。；率伪军在霞浦、福鼎、宁德沿海劫掠商船、渔船，配合日军封锁抗日根据地。；组织伪文化团体，为日军进行宣传、粉饰侵略，拉拢文化界人士附逆。；宁德沦陷期间，参与组织伪宁德县维持会并任会长，协助日军在三都澳及宁德沿海地区维持占领统治。；在福建伪政权中负责教育事务，推行日语教学和奴化教育，篡改历史教材，为日军殖民统治服务。', '[]', '2026-09-10 09:57:14.060539', '2026-09-10 09:57:14.060539', '福建', '南平', '建瓯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70236efce1d0438cb9d4db165377476e', '吴某', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南曲靖；广东江门恩平；广东江门；江苏_苏州；湖北咸宁崇阳；湖北咸宁通城', '[\"佚名\", \"吴镜如\", \"吴菊生\", \"吴耀南\"]', '[]', '抗日战争时期', '', '指挥伪警察协助日军搜捕抗日人士，破坏地下组织，参与“清乡”行动，镇压民众反抗。；新会沦陷后组织维持会，协助日军控制新会、江门一带，为日军筹粮派夫。；率部投敌，配合日军维持治安，镇压抗日民众。；通城沦陷后任伪维持会会长，配合日军在鄂南地区的统治。', '[]', '2026-09-10 09:57:13.986049', '2026-09-10 09:57:13.986049', '云南', '曲靖', '恩平', NULL, NULL, NULL, NULL, '');
