INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70526452d67c4824b0ba2227d31807c1', '佟老万', NULL, NULL, NULL, NULL, 'exact', 'exact', '肃宁', '[]', '[]', '抗日战争时期', '', '伪职：伪肃宁警备大队长；出城扫荡，破坏地道村庄。；结局：肃宁解放被俘处决', '[]', '2026-09-10 09:57:14.082968', '2026-09-10 09:57:14.082968', '河北', '沧州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70658398d52e4ebb8cb377445d312d03', '阿拉坦瓦齐尔', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰松山；内蒙古乌海乌达；内蒙古赤峰巴林右旗', '[]', '[]', '抗日战争时期', '', '在昭乌达盟、赤峰一带伪政权任职，推行日伪政策，控制巴林右旗等旗县。；在伪兴安西省（辖赤峰北部）任职，参与日伪对昭乌达盟地区的行政与警务控制。', '[]', '2026-09-10 09:57:13.990822', '2026-09-10 09:57:13.990822', '内蒙古', '赤峰', '巴林右旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('706eb544520143af9fbc0f203970a881', '顾宜我', NULL, NULL, NULL, NULL, 'exact', 'exact', '南通刘桥段桥乡；南通', '[\"顾尚义\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：清乡时期伪段桥乡乡长，姜颂平爪牙，作恶多端。。结局：被新四军短枪队锄奸镇压；伪职：汪伪伪乡长，特务骨干；罪行：与姜颂平勾结，充当清乡爪牙，告密抗日武装情报，欺压当地百姓。；结局：被新四军短枪队锄奸处决。', '[]', '2026-09-10 09:57:14.079687', '2026-09-10 09:57:14.079687', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('707339ab7a484548839e47fbe4608540', '沈阿源', NULL, NULL, NULL, NULL, 'exact', 'exact', '龙溪港尾、白沙滩', '[]', '[]', '抗日战争时期', '', '伪职：资敌奸商；罪行：勾结浯屿伪政权，持续向浯屿日军输送粮食、副食品，换回日货走私牟利，是岛上日军重要物资来源。；结局：战后肃奸，没收全部财产，判处有期徒刑。', '[]', '2026-09-10 09:57:14.085567', '2026-09-10 09:57:14.085567', '福建', '漳州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('707fa2fa055b4a0aa440c60c0711e03e', '解宝田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '[]', '[]', '抗日战争时期', '', '统领运城伪军，配合日军对中条山抗日根据地多次‘清剿’，杀害抗日军民，烧毁村庄。', '[]', '2026-09-10 09:57:14.083060', '2026-09-10 09:57:14.083060', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7086f758b73d40229bf8c3e452cbf012', '范争波', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南普洱西；广西桂林资源', '[]', '[]', '抗日战争时期', '', '江西人，汪伪政权在江西的经济官员，配合日军统制江西物资，掠夺粮食、矿产等资源。', '[]', '2026-09-10 09:57:14.037275', '2026-09-10 09:57:14.037275', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70874dc304c84616ba694251665c4a27', '段克昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山龙陵；云南保山；四川南充南部；云南_昆明_嵩明；云南昆明石林；云南昆明', '[]', '[]', '抗日战争时期', '', '云南经济界个别人员与日伪贸易往来，涉及昆明物资资敌，但具体身份存疑。；主持伪财政，为日伪政权搜刮民财，滥发伪币，导致云南部分地区经济混乱，民众生活困苦。；原云南财政官员，投敌后出任伪职，为日伪政权筹措经费，加重云南民众税负，支持日军侵略战争。；串联保山、龙陵、腾冲等地伪维持会，协助日军建立和巩固滇西占领区伪政权。', '[]', '2026-09-10 09:57:13.980333', '2026-09-10 09:57:13.980333', '云南', '保山', '龙陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70882b0926b6476ab49e70be9ad7f40b', '周学昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南长沙；湖南长沙；江苏南京；安徽_芜湖_镜湖；江苏南京；河北安新；山东青岛；湖南_湘西_泸溪；江苏南京；云南普洱西；江苏南京江宁；江苏南京；安徽芜湖芜湖经开区；辽宁沈阳新民；江苏南京鼓楼；江苏南京浦口', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪南京特别市末代市长，主持南京地方行政，配合日军物资征调央视网。。结局：1946 年南京判处死刑执行枪决', '[]', '2026-09-10 09:57:14.009786', '2026-09-10 09:57:14.009786', '安徽', '芜湖', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7089a0e8384b44d9b81f4f78d6e586bd', '张季春', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。', '[]', '2026-09-10 09:57:14.064307', '2026-09-10 09:57:14.064307', '重庆', '沙坪坝', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('708efe61af23433b9773f38d4f41d3f3', '金永禄', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边汪清', '[]', '[]', '抗日战争时期', '', '多次化装成商人潜入抗联活动区，诱捕抗联联络员，并参与集体屠杀抗日群众。', '[]', '2026-09-10 09:57:13.998568', '2026-09-10 09:57:13.998568', '吉林', '延边', '汪清', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70972fb12397487395d8a0b765b2cc71', '孙秀岩', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山抚松；吉林白山；吉林通化辉南；吉林；吉林通化；黑龙江鹤岗南山', '[]', '[]', '抗日战争时期', '', '率山林警察在白山、抚松林区设卡，截断抗联补给线，参与诱降和暗杀抗联干部。；吉林宪兵队汉奸头目，在通化、辉南等地残酷审讯抗日志士，参与制造“通化惨案”等血腥事件；为日本宪兵队担任翻译，参与审讯和刑讯抗日志士，在南山地区多次指认抗联联络员，导致多名地下党员被捕牺牲。；管理通化地区矫正院，关押迫害抗日嫌疑犯及无辜百姓，实施非人虐待，致多人死亡。；在通化地区设立矫正辅导院，关押和虐待抗日嫌疑人员及普通百姓，强迫劳役，致多人死亡。', '[]', '2026-09-10 09:57:13.999888', '2026-09-10 09:57:13.999888', '吉林', '白山', '抚松', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70a69e4091544036a477f111756d3242', '苏新民', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南普洱西；广西百色；广西梧州岑溪；广西桂林阳朔；广西桂林；广西玉林；广西梧州；广西梧州万秀；广西梧州；广西桂林临桂；广西桂林；广西南宁隆安；辽宁沈阳新民；广西南宁马山；广西南宁；云南普洱西；广西桂林叠彩；广西桂林；广西桂林平乐；辽宁沈阳大东；广西桂林；广西桂林秀峰；广西桂林；广西梧州藤县；广西梧州；广西百色靖西；广西百色；广西河池南丹；广西河池；广西桂林资源；广西桂林', '[]', '[]', '抗日战争时期', '', '1944年日军攻占桂林后，出面组织伪桂林维持会，为日军征集民夫、粮食，维持占领区基层统治。；在伪广西省政府中主管财政，为日军筹款、征粮，推行伪币与物资统制，支持日伪统治。；协助日军在广西占领区征收赋税，为伪政权筹措经费，涉及百色地区。；桂林沦陷后投敌，出任伪警察局长，率伪警察配合日军清查户口、抓捕抗日分子，镇压市民反抗。；被汪伪政权任命为伪广西省警务负责人，负责在广西沦陷区及周边建立伪警察力量，配合日军维持治安、搜捕抗日人员。；组织亲日青年团体，协助日军进行奴化教育宣传，拉拢当地青年为日伪服务。；在梧州沦陷期间组织维持会，为日军筹集物资、招募劳工，并参与伪政权活动。；日军入侵广西期间，任伪广西警察局局长，协助日军维持治安、镇压抗日活动。；桂林沦陷后出任伪桂林县县长，协助日军建立基层伪政权，推行保甲制度，征发劳役。；桂林沦陷期间，投靠日军，担任伪警察职务，协助日军搜捕抗日人员。；参与梧州伪维持会活动，协助日军管理地方事务。；日军侵入河池地区后，出面组织伪维持会，为日军征粮、派夫、维持地方秩序，协助推行占领政策。；部分地方史料提及广西沦陷区有维持会组织，但具体姓名与百色、靖西关联的可靠记载极少。；在梧州推行日伪奴化教育，组织教师附逆，篡改教材，毒害青少年。；1944年日军占领桂林后，出面组织桂林维持会，协助日军维持地方秩序、征发物资、推行伪化统治。；在日军占领广西期间，参与伪宣传机构，为日军“大东亚共荣”宣传造势，撰写附逆文章。；桂林沦陷后与张君度共同组织维持会，负责联络地方保甲长，为日军征粮征夫，协助推行伪化教育。；1944年11月南宁沦陷后，出面组织南宁维持会，协助日军维持地方秩序、征调民夫和物资，为日军占领南宁提供后勤支持。；1944年日军第二次入侵广西并占领南宁后，苏新民出面组织伪南宁维持会，协助日军维持治安、征发物资。', '[]', '2026-09-10 09:57:14.031413', '2026-09-10 09:57:14.031413', '广西', '南宁', '隆安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('70ad34b0cc89465cb8bf9b8eb15d0dee', '马兰亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封顺河；河南开封', '[]', '[]', '抗日战争时期', '', '任伪开封县县长，管辖开封周边及顺河一带，配合日军征粮征丁、维持治安。', '[]', '2026-09-10 09:57:14.048184', '2026-09-10 09:57:14.048184', '河南', '开封', '顺河', NULL, NULL, NULL, NULL, '');
