INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('714e4402d8f7422b9e711922bfeff1fe', '彭国钧', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南长沙；湖南益阳安化；湖南益阳益阳大通湖管理；湖南益阳；湖南长沙望城；湖南长沙；湖南益阳桃江；湖南益阳', '[]', '[]', '抗日战争时期', '', '长沙沦陷期间参与伪维持会活动，协助日军维持地方秩序、征派物资，为日军在长沙的统治提供经济与后勤支持。；湖南长沙人，沦陷后任伪长沙维持会委员，后任伪湖南省政府参议，在长沙及雨花地区从事汉奸活动。；在汪伪湖南省政府中负责教育，推行奴化教育，在长沙、宁乡等地学校强制使用伪教材，毒化青年。；日军侵占安化期间，出面组织伪维持会，为日军征派粮秣、民夫，协助维持占领秩序。；日军侵占益阳期间，出面组织伪维持会，协助日军征粮、派夫、维持占领秩序。；益阳沦陷期间组织伪维持会，为日军筹粮筹款，维持地方伪秩序，协助日军统治益阳地区。', '[]', '2026-09-10 09:57:14.059304', '2026-09-10 09:57:14.059304', '湖南', '益阳', '安化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7159d217f928476d8dfd208b24e97e5d', '张伯言', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城亭湖；江苏盐城；重庆沙坪坝；安徽合肥肥西；安徽合肥；安徽蚌埠龙子湖', '[]', '[]', '抗日战争时期', '', '指挥伪保安队协助日军在龙子湖及周边村庄扫荡，抓捕抗日军民，强征民夫修筑工事。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；日军占领盐城后出任维持会长，为日军筹集物资，组织汉奸情报网，出卖抗日志士，导致多名地下党员被捕。；日军占领盐城初期任维持会长，为日军筹粮派夫，提供情报。；日军占领合肥后出任伪县长，为日军征夫派款，破坏抗日组织，迫害爱国人士。', '[]', '2026-09-10 09:57:14.006126', '2026-09-10 09:57:14.006126', '安徽', '合肥', '肥西', NULL, NULL, NULL, NULL, '');
