INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('717de99113bb4b918163246577f3cc18', '韦子斌', NULL, NULL, NULL, NULL, 'exact', 'exact', '伊川县', '[]', '[]', '抗日战争时期', '', '伪职：日伪白沙警察局局长；罪行：铁杆汉奸，带领汉奸武装出没洛阳、偃师、宜阳一带刺探情报、破坏抗日斗争。警察局有100多人；结局：1944年12月14日，伊川县独立团奇袭白沙警察局，韦子斌被击毙', '[]', '2026-09-10 09:57:14.081543', '2026-09-10 09:57:14.081543', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('71866b04dfd5472287eba362c3f741fd', '张维周', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江绥化海伦；黑龙江绥化；江西景德镇浮梁；黑龙江黑河北安；黑龙江大庆萨尔图；黑龙江大庆肇州', '[]', '[]', '抗日战争时期', '', '投敌后任伪肇州县公署参事官，参与伪县政，协助日军在肇州地区实施保甲制度与物资统制。；指挥伪保安队参与“讨伐”抗联，烧毁村庄，屠杀平民。；在浮梁乡村担任伪保甲长，为日军征丁征粮，监视村民言行，举报抗日人员。；伪满时期任绥化县县长，执行日伪殖民统治政策，组织维持会、保甲自卫团，协助日军搜捕抗日人员。', '[]', '2026-09-10 09:57:14.040274', '2026-09-10 09:57:14.040274', '江西', '景德镇', '浮梁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('718e4d6f717c4ac5ba9b26bbd1cff70f', '吕子英', NULL, NULL, NULL, NULL, 'exact', 'exact', '祁县', '[]', '[]', '抗日战争时期', '', '伪职：伪祁县警备大队长；罪行：驻守祁县城、子洪据点，残害抗日军民。；结局：解放后公审枪决', '[]', '2026-09-10 09:57:14.069408', '2026-09-10 09:57:14.069408', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('719830617ade4815a68acb68e3860a3a', '林文彬', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建南平；福建福州闽侯；福建龙岩长汀；福建龙岩；福建宁德蕉城；福建宁德', '[]', '[]', '抗日战争时期', '', '南平人，任伪南平县警察局局长，带领伪警察配合日军搜捕抗日分子，勒索百姓，维持伪政权治安。；南平人，抗战期间投靠日军，任伪南平县维持会副会长，协助日军管理地方、搜捕抗日分子。；在宁德一带依附日军，率伪保安队配合日军扫荡抗日游击队，镇压当地民众抗日活动。；闽侯沦陷期间任伪维持会委员，参与日伪基层统治、征粮派夫和治安维持。；漳平县劣绅，组织伪维持会，配合日军在漳平、龙岩、长汀交界地区进行清乡，迫害抗日家属。', '[]', '2026-09-10 09:57:14.060520', '2026-09-10 09:57:14.060520', '福建', '南平', '武夷山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('71a8070436234c9da219024ae3ef3ef4', '张景唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '夏县', '[]', '[]', '抗日战争时期', '', '伪职：伪夏县县长；罪行：建立夏县伪政权，配合日军反复扫荡中条山北部，搜捕中条地委干部。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.085253', '2026-09-10 09:57:14.085253', '山西', '运城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('71ade58f18d6419cbc0ebaea1f06cf6f', '薛德顺', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西华县', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：和尚，黑煞道核心骨干，传播日伪宣传，发展会众，筹备暴乱商洛日报。。结局：暴乱失败后捕获处决', '[]', '2026-09-10 09:57:14.077916', '2026-09-10 09:57:14.077916', '陕西', '渭南', NULL, NULL, NULL, NULL, NULL, '');
