INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('72add8321fdb46a39b484bc89190e5a2', '刘绍琨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津_和平；天津_宝坻；天津、河北；河北秦皇岛山海关；湖南常德津；天津红桥', '[]', '[]', '抗日战争时期', '', '长期担任伪天津警察机构负责人，协助日军搜捕抗日分子，镇压民众反抗。；七七事变后投敌，任伪天津市治安维持会委员，后代理伪市长，配合日军建立殖民统治，推行奴化教育。；指挥伪警察镇压抗日学生和地下党，搜捕爱国人士，配合日军“清乡”。；指挥伪警察协助日军搜捕抗日志士，破坏地下组织，参与镇压学生运动。；任伪武清县知事，组织伪县署，为日军征粮派夫，镇压当地抗日武装。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.002594', '2026-09-10 09:57:14.002594', '湖南', '常德', '津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('72ae4890e2664f489af40b1c8167710e', '周仕安', NULL, NULL, NULL, NULL, 'exact', 'exact', '博望铜山??谢村', '[]', '[]', '抗日战争时期', '', '伪职：铜山伪军头目；罪行：勾结刀会势力，递送情报，抓捕游击队员，打压横山地区抗日活动；抗战胜利后潜逃芜湖潜伏。；结局：1947 年落网，判处死刑。', '[]', '2026-09-10 09:57:14.088095', '2026-09-10 09:57:14.088095', '安徽', '马鞍山', NULL, NULL, NULL, NULL, NULL, '');
