INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7348c1d4ec5d4d2bb9e58843f7e88191', '王德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾蒲县；河北唐山滦州；河北唐山；山西阳泉矿区；江苏连云港赣榆；安徽安庆大观；山东滨州；山东滨州惠民；江苏连云港灌南；代县；安徽安庆；山西临汾古县；山西吕梁方山；安徽马鞍山博望；山西阳泉矿区；山东潍坊；江苏盐城滨海；江苏_徐州_贾汪；浙江丽水缙云；江西南昌新建；山西、河北；山西运城平陆；河南郑州中牟', '[\"同名\"]', '[]', '抗日战争时期', '', '伪职：伪代县警备大队长；罪行：驻守代县城、峨口据点，残害抗日军民。；结局：解放后公审枪决；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，抢劫财物，烧毁村庄。；在方山县城设立伪警察局，抓捕抗日地下工作者，严刑逼供，破坏抗日组织，向日军提供情报。；为日军统制物资，强迫商户缴纳“慰劳金”，向日伪军提供粮食、布匹等军需品，从中牟利。；在矿区设立情报网，专门刺探抗日活动，多次带队搜查矿工宿舍，逮捕并酷刑审讯抗日嫌疑分子，致多人伤残。；在唐山地区垄断粮食，高价出售，牟取暴利。……（共涉及6个地区的犯罪记录）；在唐山垄断物资，导致百姓生活困难。', '[]', '2026-09-10 09:57:14.006789', '2026-09-10 09:57:14.006789', '安徽', '安庆', '大观', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('734f7aa97aa843eda7a996360c75d898', '何学凤', NULL, NULL, NULL, NULL, 'exact', 'exact', '临湘县', '[]', '[]', '抗日战争时期', '', '伪职：伪县政府出纳；罪行：伪临湘县政府出纳', '[]', '2026-09-10 09:57:14.077653', '2026-09-10 09:57:14.077653', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7350c4ca65ab4d53bb894529fa68ab26', '王少峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳淅川；河南南阳南召；河南南阳；河南南阳桐柏', '[]', '[]', '抗日战争时期', '', '河南淅川人，抗战期间在淅川组织伪维持会，任会长，协助日军控制淅川地区。；桐柏县人，日军侵入桐柏后出面组织维持会，充当日军耳目，协助征发民夫、粮食，破坏当地抗日组织。；在南阳沦陷期间任伪南阳县知事，推行保甲制度，配合日军扫荡南阳周边抗日武装，镇压民众抗日活动。', '[]', '2026-09-10 09:57:14.046676', '2026-09-10 09:57:14.046676', '河南', '南阳', '南召', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7355aeddbbab4faf8e0af94e05ae41ef', '保云孙', NULL, NULL, NULL, NULL, 'exact', 'exact', '南通', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：第三任伪南通县知事，汪伪伪南通县长，管理城区及城郊伪行政。。结局：战后捕获，判处重刑监禁', '[]', '2026-09-10 09:57:14.069143', '2026-09-10 09:57:14.069143', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('737c431b5acd432aac0119f604db71ce', '汪伪政权浙江省绍兴县知事', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴；山西吕梁兴县', '[\"姓名不详\"]', '[]', '抗日战争时期', '', '在汪伪政权下主持绍兴县政，推行日伪统治政策，协助日军征粮、征税、镇压抗日活动。具体姓名因档案缺失未详。', '[]', '2026-09-10 09:57:14.051768', '2026-09-10 09:57:14.051768', '浙江', '绍兴', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7381df74848a40e2ad97cf3bbae44803', '张兆铭', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江舟山定海；浙江舟山；浙江金华武义', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校教授日语和“中日亲善”课程，取缔抗日宣传，迫害爱国教师。；负责浙江沿海及舟山海域的水上治安，协助日军封锁海上交通，截击抗日物资运输。；协助日军建立伪政权，组织汉奸团体，强迫商户“欢迎”日军，并参与搜刮民间财物。', '[]', '2026-09-10 09:57:14.052106', '2026-09-10 09:57:14.052106', '浙江', '舟山', '定海', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('738aa5f8173c483ab31a88e43c33e735', '色楞那木济勒', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古锡林郭勒太仆寺旗；内蒙古锡林郭勒多伦；内蒙古锡林郭勒苏尼特右旗；内蒙古乌兰察布察哈尔右翼中旗；内蒙古锡林郭勒镶黄旗；内蒙古锡林郭勒正镶白旗；内蒙古乌兰察布察哈尔右翼后旗；内蒙古乌兰察布；内蒙古锡林郭勒苏尼特右旗；内蒙古锡林郭勒乌拉盖', '[]', '[]', '抗日战争时期', '', '苏尼特右旗本地王公，投靠日伪，任伪苏尼特右旗札萨克并兼任伪锡林郭勒盟副盟长，协助德王政权在本地征丁征粮、推行奴化教育。；在太仆寺旗担任伪旗长，直接为日军和伪蒙政权服务，负责当地行政、税收与治安。；在锡林郭勒盟苏尼特右旗任伪旗长，配合日军与伪蒙疆政权，在本地推行伪政、征发牧民。；锡林郭勒盟浩齐特旗人，投靠日伪，在伪锡林郭勒盟任职，协助日军在锡林郭勒盟推行殖民政策。；察哈尔右翼正黄旗蒙古贵族，任伪旗总管，在察哈尔右翼中旗邻近地区推行伪蒙疆政权政策，征粮征兵。；率伪保安队协助日军围剿八路军游击队，在乌兰察布南部地区抓捕抗日群众，实施酷刑逼供；在伪锡林郭勒盟公署及所属旗任职，协助日伪征收牲畜、物资，维持地方伪秩序，活动范围覆盖锡林郭勒盟东部。；在日伪统治时期出任伪正白旗（今正镶白旗部分地区）旗长，执行日伪政令，征派牲畜、劳工，协助日军控制当地。', '[]', '2026-09-10 09:57:13.987335', '2026-09-10 09:57:13.987335', '内蒙古', '乌兰察布', '察哈尔右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('738e08e130ac49b3bebb53226259cfc5', '朱瑞', NULL, NULL, NULL, NULL, 'exact', 'exact', '洮南', '[]', '[]', '抗日战争时期', '', '伪职：伪国高教员，光复后 “光复军” 头目；罪行：伪满时期从事奴化教育；日本投降后网罗土匪、伪军警组建国民党东北先遣军第十一师，多次攻打洮南县城，屠杀革命干部群众吉林省地方...。；结局：武装叛乱失败被捕获处决。', '[]', '2026-09-10 09:57:14.081484', '2026-09-10 09:57:14.081484', '吉林', '白城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73921a80030949b698eb174a5e8cade0', '陈福生', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴秀洲；江苏苏州太仓；上海宝山；上海嘉定；江苏苏州常熟；江苏苏州', '[]', '[]', '抗日战争时期', '', '担任伪嘉定警察局长，搜捕抗日分子，协助日军进行治安肃正，欺压百姓。；专门侦缉抗日分子，在秀洲区设立密探网，多次带队抓捕进步学生和游击队员，酷刑逼供。；为日军充当耳目，侦缉抗日地下人员，多次带队搜查民宅，逮捕进步人士。；在苏州、常熟地区发展特务网络，逮捕并刑讯抗日人士，制造多起血案。；为日军征收苛捐杂税，强抢粮食，导致太仓百姓饥荒，并侵吞税款中饱私囊。', '[]', '2026-09-10 09:57:13.975523', '2026-09-10 09:57:13.975523', '上海', '宝山', '常熟', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7396f8bfe73d4c7e9bebb834fcfddcc6', '刘本功', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽鄄城；山东菏泽郓城；汶上县（原济宁县）；山东济宁梁山；山东济宁；山东济宁微山；山东济宁；山东济宁任城；山东济宁；山东聊城；山东聊城；山东菏泽定陶；山东菏泽郓城；山东济宁；山东菏泽巨野；山东菏泽东明；山东临沂费县；云南普洱西；山东菏泽曹县；山东菏泽；山东菏泽菏泽高；山东菏泽郓城', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪郓城县长、伪警备司令，外号活阎王，鲁西重要伪军，制造多起惨案。结局：1946 年济南被处决；伪职：伪郓城县长、伪警备司令；罪行：外号活阎王，鲁西著名伪军头目，配合日军扫荡、制造多起屠杀惨案；来源：项目数据库；备注：1946年在济南被处决；伪职：伪郓城县维持会会长→伪郓城县县长（1939—1945）→国民党鲁西南剿匪总司令；罪行：汶上县康驿东刘庄人。韩复榘旧部特务连长。1939年1月投靠日军，任伪郓城县长，统治郓城长达七年。兵力2000余人。配合日军九二七大扫荡，屠杀抗日军民两千人以上；强征数万百姓修筑金堤封锁沟；焚烧村庄、劫掠湖区。1942年以私通八路罪名活埋潘渡村皮行经理李殿阁；1943—1944年强征1437名青壮年赴日本北海道挖煤，仅131人生还；结局：日军投降后投靠国民党，驻守济宁。1946年济宁解放逃至济南，被国民党山东省长王耀武以恶贯郓城、失守济宁等罪处决', '[]', '2026-09-10 09:57:14.012869', '2026-09-10 09:57:14.012869', '山东', '临沂', '费县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('739a57de690d4368b6a03bbe0f4cce4e', '于镜涛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江哈尔滨巴彦；黑龙江哈尔滨；黑龙江黑河；黑龙江黑河逊克；吉林长春九台；吉林长春；黑龙江哈尔滨；黑龙江齐齐哈尔；吉林长春；黑龙江黑河；辽宁大连；黑龙江齐齐哈尔；吉林；黑龙江哈尔滨；黑龙江佳木斯；哈尔滨、滨江省全境；黑龙江哈尔滨尚志', '[]', '[]', '抗日战争时期', '', '在长春地区指挥伪警察，参与多次大搜捕，迫害抗日地下工作者和普通民众。；率伪宪兵协助日军，在长春及周边地区屠杀抗联伤员和群众；在长春及绿园一带指挥伪警特，大肆搜捕抗日分子，制造多起血腥事件。；伪长春市政核心汉奸，协助日本殖民管理，参与“勤劳奉仕”等奴役劳工计划。；伪职：伪哈尔滨警察厅厅长，后伪滨江省省长；罪行：执掌哈尔滨伪警察体系，推行粮食出荷、国兵征集，主导镇压北满抗日力量，兼任协和会头目。；结局：解放后被关押改造。；伪职：伪勤劳奉仕部大臣、伪新京特别市末代市长；罪行：主持强征劳工；八一五后自封长春特别市市长，全盘留用 80 多名伪官吏、伪警察，通电重庆等待国民党接收。；结局：苏军逮捕押苏联，引渡抚顺战犯管理所，后特赦释放。', '[]', '2026-09-10 09:57:13.998293', '2026-09-10 09:57:13.998293', '吉林', '长春', '九台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73a87fc70c064dacb1b2457d28057e2c', '哈斯瓦齐尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古乌兰察布察哈尔右翼前旗；内蒙古乌兰察布；内蒙古', '[]', '[]', '抗日战争时期', '', '在乌兰察布地区参与“铁壁合围”行动，围剿抗日武装。；指挥伪警察在旗内搜捕抗日地下工作者，严刑逼供，并配合日军进行“治安强化运动”，残害无辜百姓。', '[]', '2026-09-10 09:57:13.987069', '2026-09-10 09:57:13.987069', '内蒙古', '乌兰察布', '察哈尔右翼前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73a8f603b86f43f99bb9e6f15687ae6f', '赵仲达', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪抚顺县后期县长；罪行：推行集家归屯（集团部落），拆毁村庄，逼迫百姓入部落，制造大量难民，配合围剿抗联。；结局：战后逮捕判刑。', '[]', '2026-09-10 09:57:14.068673', '2026-09-10 09:57:14.068673', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73adb838167d4a34b798b4c3e199bae6', '孙百魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁葫芦岛连山；辽宁锦州；辽宁葫芦岛；辽宁大连瓦房店；辽宁锦州凌海；辽宁阜新；辽宁；辽宁盘锦盘山；辽宁盘锦大洼', '[]', '[]', '抗日战争时期', '', '九一八后组织瓦房店维持会，协助日军建立地方伪政权，镇压当地抗日民众。；盘山土匪出身，被日伪收编后任保安队队长，在盘山、大洼一带袭击抗日游击队，烧毁村庄。；指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员，破坏抗日组织。；在锦州省（含绥中）推行奴化教育，篡改历史，强迫学生学日语。；原地方警察，投日后任连山地区伪警察署长，直接执行日伪“治安肃正”，逮捕、刑讯抗日嫌疑人员，参与“大检举”行动。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.063140', '2026-09-10 09:57:14.063140', '辽宁', '大连', '瓦房店', NULL, NULL, NULL, NULL, '');
