INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73bf7ce9397a47d0b1786ba41ea01c53', '曹乃庚', NULL, NULL, NULL, NULL, 'exact', 'exact', '东北', '[]', '[]', '抗日战争时期', '', '伪职：伪邢台警备第一大队大队长，驻防城西山区炮楼，多次进山扫荡。；结局：邢台解放被俘，判处死刑', '[]', '2026-09-10 09:57:14.083281', '2026-09-10 09:57:14.083281', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73c19603ebec4889a68c24c337b314b0', '王骧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西临汾尧都；山西临汾；河南开封；山西吕梁；山西_太原；山西_太原_晋源；山西_晋中_左权；云南普洱西；陕西榆林府谷；陕西榆林；山西长治；青海黄南河南；山西_太原_古交；山西长治上党；山西长治；山西晋中榆次；山西太原娄烦；云南普洱西；陕西宝鸡；山西；山西临汾洪洞；山西朔州朔城；广西桂林资源；山西临汾侯马；山西临汾；云南普洱西；山西临汾；山西运城；山西太原万柏林；山西太原；山西临汾；山西晋城；山西寿阳；陕西宝鸡；陕西渭南；陕西西安莲湖；云南普洱西；山西阳泉；河北廊坊固安；天津河北；云南普洱西；山西临汾吉县；山西临汾；山西_临汾_曲沃；云南普洱西；江苏无锡锡山；西藏日喀则定日；山西_太原_清徐；山西_太原_阳曲；山西运城；寿阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪末代山西省省长，兼伪保安司令、新民会会长、剿共委员会主任晋中市人民...。结局：被捕入狱，1953 年狱中病死；伪职：第三任（末代）伪山西省省长，兼伪山西保安司令、新民会会长、剿共委员会主任（1944??1945）晋中市人民...；罪行：扩充伪军，强征粮食、鸦片；封锁晋绥、晋察冀根据地；继续和阎锡山秘密联络。；结局：日本投降后先被阎锡山短期留用，后国民政府肃奸逮捕判刑；日军占领临汾后出任伪维持会会长，后任伪临汾县知事，为日军提供情报，强征民夫修筑工事，迫害抗日家属。；日军占领临汾后出任伪县长，组织维持会，为日军征粮派夫，镇压抗日活动，协助建立伪政权基层机构。；在临汾组织维持会，为日军征粮派夫，破坏抗日组织，协助建立伪政权。；在临汾地区组织伪维持会，为日军征粮派夫，破坏抗日组织，协助日军扫荡。；日军占领临汾后出任伪县长，组织维持会，为日军提供情报，强迫民众修路筑堡，参与清乡扫荡，残害抗日军民。……（共涉及60个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.001264', '2026-09-10 09:57:14.001264', '山西', '临汾', '侯马', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73c21f0d19d641c9bc329f63ef7366a9', '张世浦', NULL, NULL, NULL, NULL, 'exact', 'exact', '濮阳县', '[]', '[]', '抗日战争时期', '', '伪职：濮阳县庆祖集伪军队副队长；罪行：张世宽之弟，与张世宽一同投敌作恶；结局：与张世宽一同被击毙', '[]', '2026-09-10 09:57:14.071312', '2026-09-10 09:57:14.071312', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
