INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73ce1e84a314449a8b73cd5d94b4b0d0', '赵永胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古乌兰察布卓资；内蒙古乌兰察布；内蒙古包头土默特右旗', '[]', '[]', '抗日战争时期', '', '投靠日伪，任乌兰察布盟警察署长，参与镇压抗日活动，逮捕并杀害多名抗日志士，强征民夫修筑工事。；土默特右旗人，率伪骑兵团驻防包头地区，多次配合日军突袭大青山抗日游击队，杀害多名八路军战士。', '[]', '2026-09-10 09:57:13.987120', '2026-09-10 09:57:13.987120', '内蒙古', '乌兰察布', '卓资', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73d104c931a04132adf711bf28801a3d', '叶步青', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州泰兴', '[]', '[]', '抗日战争时期', '', '率伪自卫团在古溪、分界一带活动，为日军提供情报，参与“清剿”行动，烧毁村庄。', '[]', '2026-09-10 09:57:14.035956', '2026-09-10 09:57:14.035956', '江苏', '泰州', '泰兴', NULL, NULL, NULL, NULL, '');
