INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73d5a12cedf446e89ea8be3ced792357', '旺丹', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔；内蒙古兴安科尔沁右翼前旗；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在伪兴安北省警备军任职，参与呼伦贝尔地区殖民统治。；蒙古族，曾在伪兴安北省公署任职，参与伪满地方政权事务，其活动范围包括呼伦贝尔地区。；在科尔沁右翼前旗担任保甲长并兼任协和会分会会长，推行保甲制度、宣传亲日思想，协助日伪征粮征兵，监控当地民众。', '[]', '2026-09-10 09:57:13.987887', '2026-09-10 09:57:13.987887', '内蒙古', '兴安', '科尔沁右翼前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73d938a103d746a1b2e57b5bfdaf8f4e', '陈那乐', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三沙西沙；广东广州南沙', '[]', '[]', '抗日战争时期', '', '在日军侵占南沙部分岛礁后，参与伪维持会活动，协助日军进行岛屿管理和资源调查。', '[]', '2026-09-10 09:57:14.053614', '2026-09-10 09:57:14.053614', '海南', '三沙', '西沙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73dbe8f5781847e88c8903bbe266a7e4', '丁强', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北承德', '[]', '[]', '抗日战争时期', '', '负责热河地区伪警察体系，配合日军进行“讨伐”，抓捕抗日地下工作者，实施“连坐”政策。；在承德、丰宁地区建立特务情报网，多次指挥围剿抗日游击队，逮捕并杀害抗日军民，参与“集家并村”行动，制造无人区。；负责伪满警察系统，在承德及双桥地区大肆搜捕抗日分子，实施“治安肃正”，制造多起屠杀事件。；任伪围场县县长期间，推行保甲制度，强征民夫修建警备道路和碉堡，为日军提供粮秣情报，多次配合日伪军“扫荡”围场抗日游击区。；原热河省警察头目，投日后任伪警务厅长，在宽城、承德等地推行保甲制度，抓捕抗日军民，提供情报给日军。', '[]', '2026-09-10 09:57:14.042765', '2026-09-10 09:57:14.042765', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73e02fc3986c468ea594407ea3986df8', '拉希色楞', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰翁牛特旗；内蒙古赤峰巴林左旗；黑龙江鹤岗兴安；内蒙古赤峰巴林右旗', '[]', '[]', '抗日战争时期', '', '在伪翁牛特旗公署任职，协助日军推行保甲制度、控制农牧民，直接参与翁牛特旗地区伪政。；蒙古族，伪满兴安西省巴林右翼旗旗长，配合日军在巴林地区推行殖民统治，征粮征兵，镇压抗日活动。；在巴林右旗伪政权中任职，协助日军和伪兴安省控制地方，参与征发与镇压。', '[]', '2026-09-10 09:57:13.990811', '2026-09-10 09:57:13.990811', '内蒙古', '赤峰', '巴林右旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('73e8279c244a461aa1527facb240defe', '王兆祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西吕梁兴县；山西吕梁；山东菏泽东明；山东菏泽；山东菏泽定陶；山东菏泽菏泽经开区；山东菏泽', '[]', '[]', '抗日战争时期', '', '率伪军配合日军在東明、菏泽交界地区进行清乡扫荡，抓捕抗日人员，抢掠民财，欺压当地群众。；率伪保安团配合日军对菏泽周边抗日根据地进行扫荡，抢掠民财，抓捕抗日干部和群众。；在离石县城组织维持会，为日军筹粮筹款、拉夫修路，协助日军控制吕梁山区交通线，活动范围覆盖离石、临县、兴县一带。；统率伪保安团配合日军对定陶及周边抗日根据地进行扫荡，捕杀抗日干部和群众，强征壮丁扩充伪军。', '[]', '2026-09-10 09:57:14.017915', '2026-09-10 09:57:14.017915', '山东', '菏泽', '东明', NULL, NULL, NULL, NULL, '');
