INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('744f134362444df08298571604d5398d', '赵瑞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '陕西渭南；山西临汾汾西；山西临汾；山西晋中左权；河北沧州沧州渤海；山西；广西玉林；陕西西安莲湖；云南普洱西；山西晋中；山西吕梁石楼；山西吕梁；云南普洱西；云南普洱西；山西临汾；江苏扬州江都；云南普洱西；陕西榆林府谷；陕西榆林；江苏扬州仪征；山西吕梁中阳；山西吕梁；山西、河北；山西沁县', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：原阎锡山部队，投敌任伪山西保安第二师师长，晋东南伪军头目。结局：1945 年被俘，公审枪决；在晋中地区配合日军作战，破坏抗日政权，强征民夫修筑碉堡公路。；建立特务网络，暗杀抗日干部，策反动摇分子，破坏地下组织。；率伪军驻扎邯郸地区，多次进攻八路军和抗日游击队，烧杀抢掠，破坏抗日组织。；伪职：伪山西省保安副司令、剿共军第一师师长；罪行：原阎军军官，1942 投敌，驻扎太原；多次率伪军配合日军扫荡清太徐、交城根据地，屠杀干部民兵。；结局：抗战胜利被阎收编；太原解放被俘，劳动改造', '[]', '2026-09-10 09:57:14.018611', '2026-09-10 09:57:14.018611', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('746d135e703d4145867d6982269e1c08', '阎效曾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁汾阳', '[]', '[]', '抗日战争时期', '', '组织伪自卫团，配合日军封锁山区，袭击抗日武装，杀害多名八路军伤员和村干部。', '[]', '2026-09-10 09:57:14.020528', '2026-09-10 09:57:14.020528', '山西', '吕梁', '汾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('748c2c42e0d64cffb863017445e185a3', '孙建言', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城大丰；江苏南通通州；江苏盐城盐都；江苏盐城东台；江苏盐城盐城经开区；江苏盐城阜宁；江苏盐城滨海；江苏盐城亭湖', '[]', '[]', '抗日战争时期', '', '带领伪保安队在东台各乡镇搜捕抗日人员，烧毁村庄，抢夺财物。；在亭湖地区强征壮丁，为日军修建据点，向日军报告新四军活动，导致多次突袭失败。；在滨海地区组织伪保安队，为日军带路“扫荡”，抢劫粮食，杀害地方抗日积极分子。；管理南通城及通州地区伪行政，推行奴化教育，协助日军封锁抗日根据地。；任伪盐都区区长，强征壮丁，勒索百姓，为日军提供粮食和劳役。；在现盐城经开区南洋、便仓等地设立伪政权，为日军提供情报，抓捕抗日群众。；率伪保安队多次袭击阜宁抗日民兵，杀害群众，抢劫物资。；在日占期间任大丰伪县长，推行保甲制度，强征民夫修筑据点，搜刮民财，镇压抗日活动。', '[]', '2026-09-10 09:57:14.034318', '2026-09-10 09:57:14.034318', '江苏', '南通', '通州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('749d3cc224434b5e99620b18e8d6dad1', '陶德坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '乍浦', '[]', '[]', '抗日战争时期', '', '伪职：伪平湖乍浦商会会长；罪行：商界汉奸，为日军筹措物资，胁迫商户出钱出物资敌，盘剥沿海商贸。；结局：抗日武装攻克乍浦，当场捕获枪决。', '[]', '2026-09-10 09:57:14.069344', '2026-09-10 09:57:14.069344', '浙江', '嘉兴', NULL, NULL, NULL, NULL, NULL, '');
