INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('752b7853e7894208869c021de7e0c32d', '顾宝衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；陕西_西安_长安；广西桂林恭城；云南普洱西', '[]', '[]', '抗日战争时期', '', '垄断粮食收购，将杭州及周边大米大量运往日本，导致民众饥荒。；在汪伪政权中任要职，配合日军征粮。；参与汪伪对广西的粮食统制。', '[]', '2026-09-10 09:57:14.032139', '2026-09-10 09:57:14.032139', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('752e8ac5c410442e879b0c83b9b9fd03', '陈学谈', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江麻章；广东广州；广东湛江；广东广州；广东湛江吴川；广东广州；广东湛江廉江；广东广州；广东湛江雷州；广东广州；广东茂名化州；广东广州；广东湛江霞山；广东广州；广东云浮郁南；广东湛江赤坎；广东广州；广东湛江坡头；广东广州', '[]', '[]', '抗日战争时期', '', '在广州湾及雷州一带与日军合作，参与伪维持会活动，影响粤西沿海与茂名、化州周边地区。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，协助日军维持殖民统治，推行伪化教育，为日军征发物资与劳工。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，协助日军推行殖民统治，征发物资、劳工，镇压抗日活动。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，后任伪广州湾自治区行政专员，协助日军征粮、征夫、推行奴化教育，控制当地烟赌等行业，为日军统治服务。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，后任伪广州湾自治区行政专员，协助日军征粮、征夫、推行奴化教育，镇压抗日民众。；广州湾沦陷后与日军及伪政权合作，参与维持地方秩序和经济摊派，被视为当地附逆代表人物之一。；日军占领广州湾后出面组织维持会，协助日军推行殖民统治，征发民夫、物资，配合日伪清乡与治安强化运动。；广州湾（今湛江）沦陷后投靠日军，出面组织伪维持会，协助日军推行殖民统治、征发物资与劳工。；在海康组织伪维持会，为日军服务。；广州湾沦陷后与日军及伪政权合作，参与筹组伪维持会、协助摊派捐税与物资，为日军统治广州湾提供地方势力支持。；广州湾及雷州地区沦陷前后，与日军及伪政权合作，参与筹款、物资供应和地方‘维持’事务，是湛江地区较有影响的附逆人物。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，协助日军维持殖民统治，推行伪化教育，为日军征发劳役、物资。', '[]', '2026-09-10 09:57:14.026077', '2026-09-10 09:57:14.026077', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
