INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('75bbfa14a28f43ca84607670dc239cae', '李治平', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南屯昌；海南万宁；海南五指山；海南琼中；广西桂林资源；海南万宁；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在儋县地区协助日军统治，参与扫荡抗日根据地。；任伪陵水县县长，配合日军在陵水、保亭一带进行扫荡，掠夺资源。；在海南岛伪政权中任职，参与制定对琼崖抗日根据地的封锁与清乡计划，并到万宁等地督导伪政权的征粮征丁工作。；在万宁地区投敌，组织维持会，为日军筹粮筹款，协助日军镇压抗日力量。', '[]', '2026-09-10 09:57:14.052883', '2026-09-10 09:57:14.052883', '海南', '万宁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('75c0bd5ab8a94eebaeb4bac6c957024e', '黄庆澜', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦；浙江温州', '[]', '[]', '抗日战争时期', '', '配合日军在杨浦地区进行防疫“扫荡”，掩盖细菌战罪行。；浙江温州人，汪伪政权官员，曾任伪浙江省政府委员，参与日伪统治浙江地区。', '[]', '2026-09-10 09:57:13.977473', '2026-09-10 09:57:13.977473', '浙江', '温州', '瓯海', NULL, NULL, NULL, NULL, '');
