INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('75c7cc9999404b81a5c3c71e796e99ac', '姜全我', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '凤城；辽宁锦州；辽宁丹东；辽宁丹东振兴；湖北荆州公安；吉林、辽宁；吉林白山；吉林通化；吉林通化；吉林磐石；吉林通化；吉林通化梅河口', '[]', '[]', '抗日战争时期', '', '伪职：伪凤城县警务科长、伪满少将；罪行：原东北军投敌；长期在凤城、安东一带讨伐义勇军，制造多起惨案。；结局：1934 年被义勇军击毙。；协助日军镇压磐石抗日游击队，多次参与“讨伐”杨靖宇领导的南满抗日武装，抓捕抗日群众并刑讯逼供。；任伪安东省协和会会长，宣传“日满亲善”，组织汉奸团体，配合日军进行思想奴化，收集抗日情报。；原安东县公安局长，投日后任伪县长，协助日军掠夺资源，镇压当地抗日民众。', '[]', '2026-09-10 09:57:13.999602', '2026-09-10 09:57:13.999602', '吉林', '白山', '振兴', NULL, NULL, NULL, NULL, '');
