INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('76541ee53f56475d9de2d50febc221ab', '王调勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德古田', '[]', '[]', '抗日战争时期', '', '在伪福建省政府中任职，参与伪警察系统管理，协助日军在福建占领区维持治安与镇压抗日活动。', '[]', '2026-09-10 09:57:14.061302', '2026-09-10 09:57:14.061302', '福建', '宁德', '古田', NULL, NULL, NULL, NULL, '');
