INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('769dd997ea6848f1a544c0cea9bcf5e0', '王义山', NULL, NULL, NULL, NULL, 'exact', 'exact', '宣化', '[]', '[]', '抗日战争时期', '', '伪职：伪宣化警备大队长；伪军主力，驻守宣化城、沙岭子据点，多次扫荡南山抗日根据地。；结局：宣化解放被俘，公审枪决', '[]', '2026-09-10 09:57:14.077305', '2026-09-10 09:57:14.077305', '河北', '张家口', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('76a8fd0c13d9415e96550120ac3caeef', '王振纲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄石家庄高；河北石家庄正定；河北唐山唐山高；河北唐山；河北沧州运河；河北唐山丰润；山西忻州五寨；河北唐山路南；河北唐山玉田；北京、山西、河北；河北邢台隆尧；河北张家口赤城；山西长治长子；河北邯郸复兴；河北唐山唐山海港经开区；山西临汾翼城；山西临汾；河北唐山玉田；河北邢台襄都；河北邢台', '[]', '[]', '抗日战争时期', '', '率保安团配合日军扫荡密云山区，围捕八路军游击队，杀害抗日干部及群众。；在临汾推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军。；率领伪军多次袭击八路军游击队，抓捕并杀害抗日干部和群众，参与日军“三光”政策行动，烧毁村庄，掠夺粮食。；投靠日军，任五寨县伪县长，协助日军推行‘治安强化运动’，强征粮税，镇压抗日群众。；率伪保安队配合日军在长子县丹朱镇、色头镇等地扫荡，杀害抗日民兵，烧毁民房，民愤极大。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019363', '2026-09-10 09:57:14.019363', '山西', '临汾', '翼城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('76afc7c6c53d414aa428b33158cbb0eb', '王劲闻', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴', '[]', '[]', '抗日战争时期', '', '浙江绍兴人，任伪浙江省警务处长，指挥伪警察协助日军搜捕抗日分子，残害百姓，战后被镇压。', '[]', '2026-09-10 09:57:14.051052', '2026-09-10 09:57:14.051052', '浙江', '绍兴', NULL, NULL, NULL, NULL, NULL, '');
