INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('76cb785b52b2455bb51683d9732ec910', '陈老八', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '合肥城郊、二十埠、磨店；河北邢台内丘', '[]', '[]', '抗日战争时期', '', '带领便衣队化装潜入抗日村庄，刺探情报，抓捕抗日家属，勒索钱财，民愤极大。；伪职：合肥宪兵队便衣密探；罪行：地痞投靠日军宪兵队，四处刺探情报，敲诈商户，告密抓捕进步群众，民愤极大。；结局：抗战后期被地下锄奸队击毙。', '[]', '2026-09-10 09:57:14.044805', '2026-09-10 09:57:14.044805', '河北', '邢台', '内丘', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('76dfa5c5da194dc0b181146ab55dea4a', '洪福僧格', NULL, NULL, NULL, NULL, 'exact', 'exact', '扎鲁特旗', '[]', '[]', '抗日战争时期', '', '伪职：伪扎鲁特旗警务科长；假意参加起义，出卖加林台等人，直接制造起义警察惨案，双手沾满鲜血。；结局：1945 年光复后公审枪决', '[]', '2026-09-10 09:57:14.081462', '2026-09-10 09:57:14.081462', '内蒙古', '通辽', NULL, NULL, NULL, NULL, NULL, '');
