INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7795186371104c89947ffef0b4f811d4', '马仲英', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃平凉静宁；甘肃平凉', '[]', '[]', '抗日战争时期', '', '在甘肃地区活动，曾与日伪势力勾结，其部属在平凉一带参与伪军活动，协助日伪维持地方。', '[]', '2026-09-10 09:57:14.060151', '2026-09-10 09:57:14.060151', '甘肃', '平凉', '静宁', NULL, NULL, NULL, NULL, '');
