INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('77a46b0806364a5794d72077f5f097a2', '高志远', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；江苏常州金坛；江苏镇江句容', '[]', '[]', '抗日战争时期', '', '审判抗日志士，以“反满抗日”罪名判处重刑，维护日伪统治。；负责伪新民会在汉中地区的奴化宣传，组织亲日团体，培训伪政权人员，推行日语教育。；审判抗日人士，以“反日罪”判处多人死刑或重刑，充当日伪司法帮凶。', '[]', '2026-09-10 09:57:14.035048', '2026-09-10 09:57:14.035048', '江苏', '常州', '金坛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('77b38fe8f47a4c0b825ea3ad111fac7f', '张逸舟', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建漳州南靖；福建福州；乌丘、湄洲、南日岛，闽海沿海；福建三明尤溪；湖南怀化通道；云南普洱西；福建宁德柘荣；福建泉州安溪；福建厦门；福建泉州惠安；福建莆田；福建泉州；嵛山??三都澳外海，闽东全部海岸线；福建厦门；闽江口、平潭、长乐海面；福建福州鼓楼；福建福州；福建闽侯；福建三明永安；辽宁沈阳和平；福建_南平_光泽；福建南平武夷山；福建厦门；福建宁德霞浦；福建宁德；福建泉州；福建福州；福建_福州_连江；福建_福州_马尾；福建莆田；福建龙岩；福建宁德古田；福建福州；福建宁德；广东江门蓬江；广东江门；金门、围头、深沪、崇武外海，泉州整个海岸线；福建三明清流；福建三明；广西桂林资源；福建莆田；福建泉州石狮；福建泉州', '[]', '[]', '抗日战争时期', '伪军', '伪职：伪福建和平救国军第二集团军总司令（仙游籍，频繁袭扰泉州沿海）；罪行：闽海最大海上伪军头目，司令部驻马祖；以乌丘、金门为基地，劫掠泉州海面商船渔船，武装袭扰晋江永宁、深沪，惠安崇武，南安石井沿海村镇，抓捕渔民，贩运鸦片日货，封锁泉州海上交通线。；结局：抗战胜利被军统收编，后逃亡海外。；伪职：伪福建和平救国军第二集团军总司令（仙游籍）；罪行：闽海头号海上伪军头目，原土匪，投靠厦门日军；司令部驻马祖南竿塘，总兵力三千余人；以乌丘、湄洲为前进基地，劫掠渔船商船，走私鸦片，袭扰莆田忠门、东埔沿海村庄，进攻闽中海上抗日游击武装，为日军封锁闽中海岸线秀屿新闻网。；结局：抗战胜利被国民党军统收编；后被清算，逃亡海外。；伪职：伪福建和平救国军第二集团军总司令；罪行：闽海总伪军头目，司令部驻南竿塘；舰船经常出没于霞浦三沙、福鼎沙埕、蕉城三都澳海面，劫掠闽东渔船，贩运鸦片、日货，抓捕海上抗日人员。；结局：抗战胜利被军统收编，后逃亡海外。；伪职：伪 “福建和平救国军” 第二集团军司令；罪行：闽海最大伪军头目，受日军庇护，盘踞海岛，劫掠商船，进攻沿海抗日游击根据地，残害沿海渔民百姓党史学习教...。；结局：抗战胜利后被国民党收编，后被清算。；伪任职务：闽东海上海军伪军总司令，盘踞马祖、平潭海面，劫掠商船，为日军充当海上武装。结局：日本投降后被国民党收编，后解体，本人潜逃', '[]', '2026-09-10 09:57:14.028828', '2026-09-10 09:57:14.028828', '广东', '江门', '蓬江', NULL, NULL, NULL, NULL, '');
