INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('77beee290c5941f0a4a8219d86d7a607', '李万发', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯富锦；黑龙江佳木斯同江；黑龙江鸡西滴道；黑龙江哈尔滨方正', '[]', '[]', '抗日战争时期', '', '投日后任伪警备队长，在方正、通河一带多次袭击抗联小分队，杀害抗日伤员，抢夺百姓财物。；效忠日本关东军，在滴道地区大肆搜捕抗日联军地下工作者，多次带队‘讨伐’抗联小分队，杀害无辜百姓，并强征劳工送往煤矿。；充当日军特务，伪装成商人潜入富锦、同江等地，刺探抗联情报，导致多处密营被毁。', '[]', '2026-09-10 09:57:14.065512', '2026-09-10 09:57:14.065512', '黑龙江', '佳木斯', '富锦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('77ceab9013a2442dbe82c63a6ac44626', '郭馨坡', NULL, NULL, NULL, NULL, 'exact', 'exact', '太康县', '[]', '[]', '抗日战争时期', '', '伪职：太康县长（勾结汉奸）；罪行：1944年被委任为太康县长。收编土匪流氓扩充武装，盘踞扶太西边区，控制交通要道；勾结汉奸，经常袭击中共地方武装', '[]', '2026-09-10 09:57:14.073709', '2026-09-10 09:57:14.073709', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
