INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7849dc951e264f45bc8bedb28208bc44', '黄召贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '启东', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪启东自治会首任会长，启东沦陷初期傀儡。。结局：战后逮捕判处徒刑；伪职：启东早期伪自治会会长；罪行：启东沦陷初期牵头组建伪自治会，迎接日军，搭建傀儡统治。；结局：抗战胜利后清算惩处。', '[]', '2026-09-10 09:57:14.067574', '2026-09-10 09:57:14.067574', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78502920def3402fb3e8c51a39061402', '吴伯寿', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾陆丰；广东汕尾；广东汕尾城区', '[]', '[]', '抗日战争时期', '', '在汕尾镇推行保甲制度，为日军征发劳工，协助搜捕抗日地下工作人员。；为日军搜集抗日游击队情报，导致多名抗日人员被捕遇害。', '[]', '2026-09-10 09:57:14.028363', '2026-09-10 09:57:14.028363', '广东', '汕尾', '城区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7850f07434c04259b4c64a216e38ad69', '陈炳炎', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江坡头；甘肃陇南康县；广东湛江雷州', '[]', '[]', '抗日战争时期', '', '在海康县为日军组织伪政权，推行保甲连坐，协助日军清乡与搜捕抗日游击队员。；在海康（今雷州）组织伪维持会，配合日军统治，强征民夫修筑工事，迫害抗日家属。', '[]', '2026-09-10 09:57:14.029724', '2026-09-10 09:57:14.029724', '广东', '湛江', '坡头', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('785921c2c22f47659c1a45d073025db7', '张宝琛', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州吴兴；山西吕梁兴县；浙江温州乐清；浙江温州文成；浙江温州；浙江温州永嘉；浙江温州平阳；浙江丽水云和；浙江丽水；浙江温州；浙江温州苍南；浙江温州；浙江湖州安吉；浙江温州泰顺；浙江衢州；浙江衢州常山；浙江金华磐安；浙江衢州龙游；浙江温州龙港；浙江温州；浙江湖州长兴', '[]', '[]', '抗日战争时期', '', '任伪乐清县县长期间，推行日伪统治政策，强征民夫，协助日军清乡，镇压抗日活动。；投靠日军后任伪温州区行政督察专员，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；投靠日伪，任伪温州区行政督察专员，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；投靠日军，任伪温州绥靖公署主任，协助日军维持占领区秩序，镇压抗日活动，征收苛捐杂税，迫害爱国人士。；日军占领长兴后出任伪县知事，协助日军推行“治安肃正”，强征民夫修筑公路和碉堡，并组织伪保安队镇压抗日活动。；1938年日军占领龙游后，出任伪龙游县知事，协助日军维持占领区秩序，强迫民众领取“良民证”，并组织伪保安队镇压抗日活动。；日军占领衢县期间出任伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食支援日军，并参与镇压抗日活动。；任伪永嘉县长期间，推行日伪统治，强征捐税，镇压抗日活动，协助日军维持占领秩序。；1938年出任伪吴兴县知事，推行日伪统治，协助日军征粮、征税，镇压抗日活动。；投靠日伪，任伪温州区行政督察专员，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；投靠日军，任伪温州区行政督察专员，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；1941年投敌，任伪泰顺县县长，协助日军推行“治安强化”运动，强征民夫修筑工事，搜刮粮食资敌，迫害抗日军民。；日军占领磐安期间出任伪县长，协助日伪推行“治安强化”运动，强征民夫修筑碉堡，并组织伪保安队镇压抗日活动。；投靠日军，出任伪平阳县知事，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；投靠日军，出任安吉县伪政权首脑，协助日军维持占领区秩序，征收粮税，镇压抗日活动。；日军占领温州期间出任伪维持会会长，协助日军征粮、征税，镇压抗日活动。；在丽水、云和一带协助日军清乡，搜捕抗日志士，破坏地下抗日组织。；日军占领常山期间组织维持会，协助日军征粮派款，镇压抗日民众，提供情报给日军', '[]', '2026-09-10 09:57:14.049286', '2026-09-10 09:57:14.049286', '浙江', '丽水', '云和', NULL, NULL, NULL, NULL, '');
