INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78b38391a3504f9b9ab2d84e96e34eda', '周德胜', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；湖北荆州；湖北宜昌伍家岗；河南信阳平桥；河南信阳；湖北宜昌点军；山西阳泉城区；湖北宜昌猇亭；浙江宁波江北；湖北宜昌宜都；湖北宜昌；湖北宜昌远安；湖北黄冈；湖北宜昌；湖北宜昌远安；湖北荆州江陵；湖北黄石黄石港；湖北宜昌当阳；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '协助伪维持会会长王知生管理宜昌城区事务，为日军筹粮筹款，征发民夫。；在猇亭地区组织伪维持会，为日军提供情报、粮草，协助日军控制长江北岸渡口。；在宜昌地区统领伪保安大队，配合日军进行清乡、扫荡，残害抗日群众。；任伪远安县保安队队长，协助日军维持远安及周边地区治安，参与镇压抗日活动。；黄冈本地人，带领伪军配合日军扫荡，烧毁民房，杀害抗日群众。；任伪襄阳县商会会长，协助日军统制物资，强征商民财物，为日军经济掠夺服务。；率伪军在沔阳、监利一带配合日军清乡，烧杀抢掠，残害抗日军民。；率伪军在信阳、罗山、确山一带配合日军扫荡，袭击抗日根据地，抢掠粮食牲畜。；江陵本地伪军头目，率伪保安大队配合日军清乡，搜捕抗日人员，控制江陵部分乡镇。；黄石港码头工人出身，投靠日军后组织伪工会，控制码头工人，为日军装卸掠夺物资，协助日军镇压工人反抗。；在宜昌沦陷区推行奴化教育，改编教材、宣传“大东亚共荣”，毒害青少年。；带领伪自卫团配合日军守备队，在伍家岗及宜昌城区周边巡逻、抓捕抗日嫌疑人员。；远安沦陷期间组织维持会，为日军带路、征发民夫，协助建立伪保甲制度。', '[]', '2026-09-10 09:57:14.046432', '2026-09-10 09:57:14.046432', '河南', '信阳', '平桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78c218d77d0c404d8c35e0f0c668db74', '王维屏', NULL, NULL, NULL, NULL, 'exact', 'exact', '新安县；山西；山西_运城_闻喜；山西临汾安泽；河南洛阳洛宁；河南洛阳', '[]', '[]', '抗日战争时期', '', '伪职：伪新安县长；罪行：1944年5月新安县沦陷后任伪县长；率领伪保安队配合日军多次扫荡安泽抗日根据地，杀害抗日干部和群众数十人，并参与抢劫粮食和物资。；任伪警察局长期间，大肆搜捕抗日地下党员和进步人士，严刑逼供，破坏地下抗日组织。', '[]', '2026-09-10 09:57:14.018895', '2026-09-10 09:57:14.018895', '山西', '临汾', '安泽', NULL, NULL, NULL, NULL, '');
