INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78c639f7032946ffac3ea78f9f8f66e5', '范俊文', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封人（安义籍）；原籍河南开封，长期在安义、南昌一带活动；河南开封', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪安义特务队长；罪行：1942年杀害战友携枪投日，任伪安义特务队长，多次带队扫荡安义、靖安、新建乡村，残害百姓；抗战胜利后潜伏南昌璇宫饭店被捕，后审判处决；来源：抗日战争纪念网；备注：活动范围含南昌周边，在南昌落网；伪职：汪伪安义县特务队队长；罪行：盘踞新建乐化、樵舍，带领日军靖安队扫荡新建、安义、靖安乡村，制造多起烧杀抢掠惨案，残害抗日军民；结局：战后被依法处决；伪任职务：伪安义县特务队长，手段残暴，多次纵火屠村，残害大量群众。结局：抗战胜利后江西公审，执行死刑', '[]', '2026-09-10 09:57:14.069006', '2026-09-10 09:57:14.069006', '河南', '开封', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78c76feed32a48efb1fae741bcb0ac02', '赵锡田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北沧州肃宁；河北沧州；河北秦皇岛卢龙；河北廊坊大城；天津河北；河北秦皇岛青龙；河北廊坊霸州；河北廊坊；河北；河北廊坊；河北廊坊安次；辽宁沈阳新民；河北沧州；河北秦皇岛抚宁；河北秦皇岛；河北承德兴隆', '[]', '[]', '抗日战争时期', '', '在唐山市区为日军服务，管理伪市政，强制推行经济统制，掠夺唐山煤炭等资源，镇压工人罢工和抗日地下活动。；在丰润路南地区烧毁村庄，抢掠百姓，配合日军“剔抉”战术。；负责廊坊及周边地区治安，镇压抗日活动，多次率伪军袭击抗日武装，杀害抗日人员。；日军占领廊坊后出任维持会会长，为日军筹集物资，提供情报，协助建立伪政权，后调任伪河北省参事。；推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，并举报抗日积极分子。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042233', '2026-09-10 09:57:14.042233', '河北', '唐山', '路南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78d3885813454b76a7979b8b590592e6', '朱学曾', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴桐乡；山西吕梁兴县', '[]', '[]', '抗日战争时期', '', '任伪嘉兴县知事期间，推行保甲制度，强征壮丁，配合日军清乡扫荡。', '[]', '2026-09-10 09:57:14.050468', '2026-09-10 09:57:14.050468', '浙江', '嘉兴', '桐乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78dde461f58f4837ad5c125f44ec0a1e', '王慈博', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口太康；河南开封；河南南阳；河南驻马店', '[]', '[]', '抗日战争时期', '', '南阳方城人，组织维持会，为日军筹集物资，协助日军维持地方秩序。；任伪警察局长，协助日军管理驻马店城区，登记户口、发放良民证，镇压抗日活动。；在开封、商丘、周口一带参与伪政权事务，协助日军推行治安强化运动，督导豫东各县伪政权建立与征粮。', '[]', '2026-09-10 09:57:14.046629', '2026-09-10 09:57:14.046629', '河南', '南阳', '太康', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78e0f314188340ca96f64a87666435b3', '王诚斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '顺安??梁家垄一带', '[]', '[]', '抗日战争时期', '', '伪职：顺安特务骨干；罪行：铁杆告密汉奸，探得铜陵大队驻地情报，连夜引路日伪军包围梁家垄，是范家湾战斗直接告密人；常年搜集根据地情报，指认抗日干部群众安青网。；结局：抗战胜利后公审处决。', '[]', '2026-09-10 09:57:14.079356', '2026-09-10 09:57:14.079356', '安徽', '铜陵', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78e2c40649e14ffe8ee3977c5e9b265d', '木村肥佐生', NULL, NULL, NULL, NULL, 'exact', 'exact', '日本外务省特务', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：化名达瓦桑波，伪装蒙古喇嘛，经青海潜入拉萨，搜集西南国际援华通道情报，调查西藏社会民情；日本投降后经亚东逃往印度噶伦堡光明网。。结局：在印度被英军逮捕，遣送回日本，著有《潜伏西藏十年》', '[]', '2026-09-10 09:57:14.072957', '2026-09-10 09:57:14.072957', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('78f45312289344139ca72f45fcf964cd', '李国良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京延庆', '[]', '[]', '抗日战争时期', '', '组织地方自卫团，在延庆各要道设卡盘查，截获八路军物资，并配合日军对海坨山根据地进行封锁。', '[]', '2026-09-10 09:57:13.994095', '2026-09-10 09:57:13.994095', '北京', '延庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7903e2238ffb47529e8b2513c0b2981e', '张叔平', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州贵阳修文；贵州贵阳', '[]', '[]', '抗日战争时期', '', '在日军短暂占领贵阳期间，代表商界与日军合作，强制商户缴纳“慰劳金”与物资。', '[]', '2026-09-10 09:57:14.062632', '2026-09-10 09:57:14.062632', '贵州', '贵阳', '修文', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7905a74aa9554f15b59b101fe1f82a5f', '马占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北承德丰宁；内蒙古赤峰巴林左旗；内蒙古赤峰；河北保定望都；内蒙古赤峰翁牛特旗；山西、河北；山西忻州五寨；辽宁沈阳新民；山西长治潞城', '[]', '[]', '抗日战争时期', '', '负责伪新民会宣传，推行奴化教育，煽动民众反对抗日政权。；带领便衣队混入集市和村庄，刺探八路军情报，多次引导日军突袭抗日村庄。；率伪军驻守望都西关，多次突袭周边村庄，抢劫牲畜和粮食，并参与杀害冀中军区第十分区交通员。；训练汉奸青年，灌输奴化思想，组织青年团协助日军巡逻，曾带领特务抓捕丰宁地区的地下党员，并参与破坏抗日交通线。', '[]', '2026-09-10 09:57:13.991224', '2026-09-10 09:57:13.991224', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('790e5ea5cb1148499187e7770e88004d', '顾宝珊', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏苏州苏州工业园；江苏苏州', '[]', '[]', '抗日战争时期', '', '协助日军在苏州东部（今工业园区区域）建立据点，参与“扫荡”新四军游击队。', '[]', '2026-09-10 09:57:14.036742', '2026-09-10 09:57:14.036742', '江苏', '苏州', '苏州工业园', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7915accd469a422bbfaa4d13463aa48d', '李凤鸣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁；河北沧州；河北沧州东光；山西阳泉城区；山东临沂临沭；山西忻州保德；山东枣庄台儿庄；河北石家庄晋州；辽宁丹东；河北石家庄行唐；山东枣庄；山西阳泉矿区；山西忻州忻府；河北沧州东光；河北邯郸邯郸冀南；河北石家庄；山东济宁济宁高；山东济宁；河北沧州吴桥；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '组织维持会为日军征粮派款，提供情报，并强迫百姓悬挂日伪旗帜，破坏抗日组织地下活动。；充当日军走狗，负责为日军筹粮派款，强迫百姓领取“良民证”，并告密导致多名地下党员被捕牺牲。；为日军筹粮派款，强迫百姓“欢迎皇军”，提供情报，协助日军建立伪政权。；任伪警察局长，执行日伪法令，搜捕抗日地下党员，参与“治安强化运动”。；为日军搜集抗日情报，抓捕地下党员和进步群众，严刑逼供，并参与“清乡”行动，破坏抗日组织。……（共涉及18个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.012647', '2026-09-10 09:57:14.012647', '山东', '临沂', '临沭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('792304968b34419d81d51c819cdf5f98', '孙国桢', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江瑞昌；江西九江；江西南昌进贤', '[]', '[]', '抗日战争时期', '', '在进贤县境内搜捕抗日分子，为日军提供情报，迫害无辜百姓。；在伪九江县政府主管教育，推行奴化教育，改编教材、组织亲日宣传，属教育文化领域附逆者。', '[]', '2026-09-10 09:57:14.039342', '2026-09-10 09:57:14.039342', '江西', '九江', '瑞昌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('79289e1f7fbf400f847bb1d411a58381', '林匡', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江台州路桥；浙江台州', '[]', '[]', '抗日战争时期', '', '日军侵占温岭后出面组织伪维持会，任伪县长，为日军筹粮筹款、拉夫，配合日伪清乡，镇压当地抗日力量。温岭属台州，与路桥同处台州湾南岸。', '[]', '2026-09-10 09:57:14.050161', '2026-09-10 09:57:14.050161', '浙江', '台州', '路桥', NULL, NULL, NULL, NULL, '');
