INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('793059edec0c4d15a1fb2b0e073ac7d0', '陈楷贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀宁洪镇', '[]', '[]', '抗日战争时期', '', '伪职：安庆特务机关大特务、伪洪镇区区长；罪行：鸦片烟鬼出身，铁杆特务；带队充当日军向导夜袭江镇，纵火焚烧民房；拦劫根据地紧缺盐、布、医药物资；随意罗织 “私通新四军” 罪名抓捕百姓，敲诈勒索，血债累累。；结局：1942 冬被游击锄奸队就地击毙。', '[]', '2026-09-10 09:57:14.083770', '2026-09-10 09:57:14.083770', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('794354863bc8419ba5e9f2184844080a', '易国栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（随州籍省级汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：伪武汉司法部第一科主事；罪行：曾都区洛阳镇人。抗战期间任伪武汉司法部第一科主事、伪中日文化协会武汉分会法学研究会研究委员', '[]', '2026-09-10 09:57:14.083228', '2026-09-10 09:57:14.083228', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('794c6dbcfc6d446dbbacf841cd4de972', '赵云椿', NULL, NULL, NULL, NULL, 'exact', 'exact', '抚宁', '[]', '[]', '抗日战争时期', '', '伪职：第一任伪抚宁县县长，组建伪县公署、警备队、新民会；冀东大暴动期间调集伪军围剿七家寨抗日暴动队伍，制造重大伤亡，推行清乡、抓丁征粮。；结局：日本投降后潜逃，1946 年抓捕归案镇压；伪职：第一任伪抚宁县县长，组建伪县公署、警备队、新民会；1938 年调集伪军围剿七家寨抗日暴动队伍，制造重大伤亡，推行清乡抓丁征粮。；结局：日本投降后潜逃，1946 抓捕归案镇压', '[]', '2026-09-10 09:57:14.080759', '2026-09-10 09:57:14.080759', '河北', '秦皇岛', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('795078542a2f46589236c8413c236a7e', '刘叔模', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆云阳', '[]', '[]', '抗日战争时期', '', '组织伪文化协会，为日军进行文化宣传，鼓吹中日亲善。', '[]', '2026-09-10 09:57:14.064025', '2026-09-10 09:57:14.064025', '重庆', '云阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('795853039e334792ac23efe1882cd764', '乔日成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权；山西朔州平鲁；山西；山西朔州；山西运城永济；山西晋中左权；山西晋中；山西晋中榆社', '[]', '[]', '抗日战争时期', '', '原为土匪，后投靠日军，在清徐、太原一带活动，袭击抗日武装，残害百姓，后反正但历史评价复杂。；投靠日军后任神池县伪保安队长，多次带路袭击八路军游击队，杀害抗日群众，强征粮饷。；原土匪出身，投日后任和顺县伪保安队长，多次带队袭击抗日游击队，杀害抗日干部，强征百姓财物；盘踞雁北，多次配合日军进攻晋中根据地，残杀抗日干部和群众，制造多起惨案。；投靠日军后任榆社县保安队队长，多次配合日军扫荡抗日根据地，抓捕抗日军民，抢劫粮食物资，残害百姓。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.022416', '2026-09-10 09:57:14.022416', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('79589dcb8c844631bcb49ec56407d8e7', '叶景福', NULL, NULL, NULL, NULL, 'exact', 'exact', '莲都县城', '[]', '[]', '抗日战争时期', '', '伪职：丽水县维持会副会长；罪行：协助王楚卿，联络城内商绅附逆，下乡催缴粮草，盘查往来行人，迫害拒绝合作百姓。；结局：抗战胜利后判处有期徒刑。', '[]', '2026-09-10 09:57:14.078682', '2026-09-10 09:57:14.078682', '浙江', '丽水', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('795a36a356d442aca2d8c640f966b96a', '李老黑', NULL, NULL, NULL, NULL, 'exact', 'exact', '阜城', '[]', '[]', '抗日战争时期', '', '伪职：伪阜城警备大队长；驻防阜城、漫河据点，残害抗日军民。；结局：阜城解放被俘枪决', '[]', '2026-09-10 09:57:14.084251', '2026-09-10 09:57:14.084251', '河北', '衡水', NULL, NULL, NULL, NULL, NULL, '');
