INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('795e1a5fc0cc45ad9fe002261421604d', '周安国', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_郴州_桂东；湖南株洲茶陵；湖南湘潭；湖南长沙开福；湖南长沙天心；云南普洱西', '[]', '[]', '抗日战争时期', '', '湖南人，在长沙沦陷区主持伪宣传，散布亲日言论、诋毁抗日力量，活动涉及开福区文化教育界。；日军占领湘潭后，组织维持会，为日军筹粮、派夫，协助日军控制湘潭地区。；在湘北、鄂南、赣西一带活动，收编散兵游勇组成伪军，配合日军对湖南抗日根据地进攻。；湖南籍人物，在日军占领湖南期间出任伪财政职务，为伪政权筹措经费。', '[]', '2026-09-10 09:57:14.058822', '2026-09-10 09:57:14.058822', '湖南', '株洲', '茶陵', NULL, NULL, NULL, NULL, '');
