INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7993a9dae8084d7f9032332a83a8f92d', '韩光太', NULL, NULL, NULL, NULL, 'exact', 'exact', '密山西大林子（兴凯镇）', '[]', '[]', '抗日战争时期', '', '伪职：地方汉奸密探；罪行：向伪满军警告密，出卖地下党支部，多名党员牺牲，破坏密山地下党组织。；结局：解放后反奸清算被惩处。', '[]', '2026-09-10 09:57:14.074350', '2026-09-10 09:57:14.074350', '黑龙江', '鸡西', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7995ad240d4c48c784991a968e371879', '石星川', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁咸安；湖北武汉；鄂东地区（黄冈籍省级汉奸）；江西九江；湖北黄石阳新；湖北武汉；湖北_咸宁_嘉鱼；湖北_咸宁_赤壁；湖北_咸宁_通山；湖北孝感；湖北_宜昌_兴山；湖北荆州；湖北襄阳；湖北鄂州鄂城；湖北荆州江陵；湖北武汉；湖北阳新；湖北宜昌；江西九江濂溪；江西九江；湖北_十堰_房县；湖北武汉；重庆万州；云南普洱西；湖北黄石阳新；湖北黄石；安徽_阜阳_颍泉；湖北黄冈；湖北武汉；湖北黄冈；湖北黄石阳新；湖北武汉；湖南_怀化_怀化洪江管理；湖北孝感孝昌；湖北武汉；辽宁阜新太平；湖北武汉；湖北黄石阳新；湖北黄石阳新；湖北武汉；湖北黄石；武汉（伪武汉市政府）；湖北鄂州梁子湖；湖北黄石阳新；湖北_黄石_大冶；湖北黄石；阳新县；湖北武汉黄陂；湖北武汉；重庆沙坪坝；湖北武汉黄陂；湖北咸宁；湖北武汉；湖北鄂州华容；湖北黄石阳新', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪汉口市市长、伪湖北参议府议长、湘鄂赣财务委员会主任。结局：初判死刑，改无期徒刑，1948 年病死于武昌狱中抖音百科；伪职：伪武汉参议府副议长→伪汉口市市长；罪行：湖北阳新人。1939年4月任伪武汉特别市政府参议府副议长；1940年10月出任伪汉口市市长；与何佩瑢、张仁蠡、雷寿荣并称湖北“四大汉奸”；结局：1946年4月7日被判处死刑，后减为无期徒刑；1948年7月死于狱中；伪职：伪武汉特别市政府参议府副议长→伪汉口市市长；罪行：湖北阳新人。早年留学日本，加入同盟会。1939年4月应日本驻汉军特务部长邀请出任伪职；1940年10月出任伪汉口市市长；与何佩瑢、张仁蠡、雷寿荣并称湖北“四大汉奸”；结局：1946年4月7日被湖北省高等法院判处死刑，后减为无期徒刑；1948年7月卒于狱中；伪职：伪汉口市市长、伪湖北参议府副参议长；罪行：黄州府兴国军（今阳新县，旧属黄州府）人。抗战期间投敌，与何佩瑢、张仁蠡、雷寿荣并称湖北四大汉奸\"\"；结局：1945年日本投降后以汉奸罪被捕，1948年死于狱中', '[]', '2026-09-10 09:57:14.010951', '2026-09-10 09:57:14.010951', '江西', '九江', '濂溪', NULL, NULL, NULL, NULL, '');
