INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('79b9f87d7dd842a4994407000eafcb26', '陈明栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南五指山；海南澄迈；海南三沙南沙；内蒙古乌海海南；海南澄迈；海南海口美兰；海南海口；海南东方', '[]', '[]', '抗日战争时期', '', '在三亚、崖县地区投靠日军，任伪崖县县长，协助日军控制榆林、三亚港等要地，组织伪维持会和伪警察，参与掠夺海南南部资源。；在感恩地区推行伪化统治，协助日军控制沿海地区。；在澄迈南部山区组织伪自卫团，配合日军对抗日根据地进行封锁与清剿。；在澄迈地区协助日军清乡，迫害抗日家属。；在海口主办伪报刊与广播，为日军侵略辩护，诋毁抗日力量。', '[]', '2026-09-10 09:57:14.053525', '2026-09-10 09:57:14.053525', '海南', '三沙', '南沙', NULL, NULL, NULL, NULL, '');
