INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('79d539a9781a432593924e569f24363c', '吕焯', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东清远；广东广州', '[]', '[]', '抗日战争时期', '', '广东沦陷后投敌，历任伪番禺县县长等职，协助日军统治广州周边，清远邻近地区亦受其伪政权影响。', '[]', '2026-09-10 09:57:14.029263', '2026-09-10 09:57:14.029263', '广东', '清远', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('79e0974cfb5f498596c63d6b31488d34', '赵琪', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城茌平；山东聊城；河南郑州郑州航空港经开区；山东青岛；山东济南；山东_济南_钢城；山东_聊城_临清；山东掖县（莱州）；北京昌平；山东德州；北京；江苏徐州；山东掖县（今莱州）；山东潍坊昌邑；山东济南；四川南充南部；北京大兴；安徽合肥肥东；山东青岛', '[]', '[]', '抗日战争时期', '汪伪政权', '在任期间配合日军“五次治安强化运动”，在大兴南部地区制造无人区，杀害抗日群众。；在北平（含昌平）管理伪社会事务，推行保甲连坐，监控民众活动。；伪任职务：青岛维持会会长、伪青岛特别市市长。结局：建国后入狱，1957 年病死于狱中；伪职：伪青岛治安维持会会长、伪青岛特别市市长；罪行：1938年1月起任伪青岛维持会会长、伪青岛市长，辅佐日军统治青岛，推行奴化政策，压制抗日活动，1943年3月卸任；来源：抗日战争纪念网（青报网转载）；备注：1947年被国民政府以汉奸罪判处死刑', '[]', '2026-09-10 09:57:13.993272', '2026-09-10 09:57:13.993272', '四川', '南充', '南部', NULL, NULL, NULL, NULL, '');
