INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a1eddd4114a4bbbb1c0079c2c99ed71', '张耀东', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城响水；江苏盐城；河南南阳；河南开封；河南三门峡陕州；河南三门峡卢氏；河南漯河；河南三门峡湖滨；河南安阳北关；河南安阳', '[]', '[]', '抗日战争时期', '', '在安阳推行奴化教育，组织亲日宣传，协助日军控制学校和文化机构。；河南南阳人，抗战期间投敌，任伪警察局巡官，协助日军维持治安，迫害百姓。；协助会长为日军征集粮草、劳工，参与维持会日常事务，镇压抗日活动。；控制物资配给，协助日军掠夺农产品和工业原料。；出任伪县长，配合日军统治，镇压抗日活动。；日军侵占卢氏后组织维持会，为日军带路、征粮，破坏抗日组织。；率伪军多次扫荡盐城、响水地区，杀害抗日干部和群众，烧毁村庄。', '[]', '2026-09-10 09:57:14.036449', '2026-09-10 09:57:14.036449', '江苏', '盐城', '响水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a20c52227404ffb9dbbd869c681b694', '李树棠', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆岳西；云南昆明西山；安徽滁州明光；安徽滁州；安徽滁州南谯；安徽_滁州_苏滁现代产业园；山东德州德州经开区；辽宁沈阳大东；安徽_黄山_黟县；湖北恩施；山东东营利津；河北邢台清河；安徽宣城郎溪；安徽铜陵铜官；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '组建伪滁县保安团，配合日军扫荡周边抗日根据地，袭击新四军及地方抗日武装。；滁县本地人，组织伪保安团配合日军扫荡抗日根据地，参与清乡与情报搜集，活动范围包括滁县及南谯一带。；组织伪保安团，配合日军对滁县周边抗日游击区进行扫荡，强征民夫、修筑据点，协助日军控制滁县交通线。；岳西地区投敌分子，组织伪维持会，为日军提供情报、粮秣，配合日伪军对岳西山区抗日武装的扫荡。；在皖南地区任伪保安司令，配合日军清乡，镇压抗日力量。；在德州推行奴化教育，宣传“中日亲善”“大东亚共荣”，属教育文化领域附逆者。；广饶与利津相邻，其伪政权与利津伪政权协同行动，多次配合日军扫荡小清河以北地区，抓捕抗日人员，强征劳工。；恩施本地投敌武装头目，率部配合日军扫荡，镇压当地抗日游击队。；在铜官山矿区为日军管理矿工，强迫开采铜矿资源，虐待矿工，并协助日军抓捕抗日分子。；明光本地人，日军侵占明光后组织维持会，为日军筹集物资、招募劳工，协助建立伪基层政权，直接活动于明光地区。；郎溪人，组织伪保安团，配合日军对郎溪及周边地区进行清乡扫荡，残害抗日军民。', '[]', '2026-09-10 09:57:14.007629', '2026-09-10 09:57:14.007629', '安徽', '安庆', '岳西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a232aef70ff40488d569a23fb30d152', '曾宪成', NULL, NULL, NULL, NULL, 'exact', 'exact', '钟祥县', '[]', '[]', '抗日战争时期', '', '伪职：民族败类（汉奸）；罪行：钟祥县民族败类，通过自己的情报网将刘辅珩哗变的时间故意泄漏给汉奸，妄想借刀杀人，利用日军消灭新四军', '[]', '2026-09-10 09:57:14.082024', '2026-09-10 09:57:14.082024', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
