INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a82ace3b3b4470c9056ef84c4469ec6', '徐臣焰', NULL, NULL, NULL, NULL, 'exact', 'exact', '咸宁县（今咸安区）', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（混入革命队伍）；罪行：混入革命队伍内的汉奸。1942年8月暗害中共咸宁县委书记徐宏义', '[]', '2026-09-10 09:57:14.067524', '2026-09-10 09:57:14.067524', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a877b362a504e379504f5895d2d6b16', '赵郁卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西麻山；黑龙江鸡西；黑龙江绥化安达；黑龙江齐齐哈尔；黑龙江双鸭山岭东；黑龙江鸡西虎林；黑龙江牡丹江；黑龙江齐齐哈尔；黑龙江牡丹江；黑龙江鸡西密山；黑龙江绥化青冈', '[]', '[]', '抗日战争时期', '', '任伪安达县县长期间，积极推行日伪殖民政策，强征民夫，搜刮粮食，镇压抗日活动。；任伪青冈县县长期间，强征民夫修建警备道路，配合日军“讨伐”抗日游击队，搜刮民财。；原黑龙江省警察系统人员，投日后任牡丹江省警务厅厅长，负责指挥伪警察和特务，破坏抗联地下组织，逮捕杀害多名抗日志士。；在牡丹江市区建立特务网，多次破坏地下抗日组织，逮捕并刑讯爱国人士。；在齐齐哈尔、讷河推行奴化教育，强制学校教授日语，篡改历史教材。；任伪鸡宁县（今鸡西地区）县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，掠夺当地煤炭资源。；任伪虎林县县长期间，积极推行日伪殖民政策，强征劳工修建军事工程，镇压抗日民众，为日军提供粮食物资支持。；任伪密山县县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，搜刮民财，为日本侵略者提供物资和情报。；在伪富锦县县长任内，积极推行日伪“归屯并户”政策，强征民夫修筑警备道路，配合日军封锁抗日游击区，导致岭东一带民众流离失所；在牡丹江地区组织特务警察网，破坏抗联地下组织，逮捕并杀害多名抗联联络员和爱国群众。', '[]', '2026-09-10 09:57:14.065703', '2026-09-10 09:57:14.065703', '黑龙江', '双鸭山', '岭东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a8cc59ed6894d6ea8ea0e859f61e2a7', '余晋龢', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；广西桂林资源；四川南充南部；安徽安庆；浙江绍兴；河北秦皇岛；河北张家口；山西大同平城；云南普洱西；浙江绍兴；江苏南京鼓楼；江西九江；山东聊城；北京延庆；河北石家庄辛集；河北石家庄；安徽_阜阳_阜阳经开区；天津河北；河北廊坊；北京大兴；北京昌平；吉林长春朝阳；北京石景山；北京海淀；河北唐山；北京丰台；北京、河北；云南普洱西；北京_西城；北京门头沟；天津河北；云南普洱西', '[\"余晋和\"]', '[]', '抗日战争时期', '华北伪临时政府', '伪任职务：伪华北政务委员会建设总署督办，曾任伪北平警察局长。结局：被捕入狱，1964 年病死于狱中；1938年出任伪北京市市长，在任期间配合日军实施保甲制度、粮食统制，镇压北平城内抗日地下活动。；继任伪北平市长，在丰台地区设立伪警察机构，配合日军“清乡”和粮食统制。；原国民党官员，投日后任伪北平市长，管辖包括大兴在内的郊区，推行日伪法令，镇压抗日活动，组织“献铜献铁”等物资搜刮。；在北平推行保甲制度，配合日军搜捕抗日人士，强制推行粮食统制，导致民不聊生。；原国民党官员，投日后任伪北平市长，在延庆等辖区推行日伪法令，组织“献铜献铁”，协助日军强化治安。……（共涉及18个地区的犯罪记录）；其伪政权势力延伸至廊坊北郊，支持日军在通县、香河一带建立“非武装区”。', '[]', '2026-09-10 09:57:13.992753', '2026-09-10 09:57:13.992753', '浙江', '绍兴', '辛集', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7a9ba54445274c7096ea0bcd2ba4b0cd', '神尾贰郎', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边延吉', '[]', '[]', '抗日战争时期', '', '作为伪间岛省实际控制者之一，主导延边地区行政、警察与经济掠夺，配合关东军围剿抗日联军。', '[]', '2026-09-10 09:57:13.998064', '2026-09-10 09:57:13.998064', '吉林', '延边', '延吉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7aa23b49ca334637a284a98d81c8d6be', '陈玉科', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明；云南昆明五华；云南昆明；云南昆明东川', '[]', '[]', '抗日战争时期', '', '负责日伪宣传工作，创办亲日报刊，散布投降言论，为日军侵略辩护。；在经济领域与日伪合作，强制商户缴纳‘献金’，为日军采购军需物资，垄断昆明部分商业，牟取暴利并资助伪政权。；投靠日伪后出任伪昆明县警察局长，协助日军镇压抗日活动，逮捕爱国人士，维护伪政权统治秩序。', '[]', '2026-09-10 09:57:13.980877', '2026-09-10 09:57:13.980877', '云南', '昆明', '东川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7aa315af58b347438f356ecaabe4c5e5', '马凌云', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南洛阳老城；河南洛阳；河南洛阳洛宁；河南洛阳；河南洛阳伊川；河南洛阳；河南三门峡陕州', '[]', '[]', '抗日战争时期', '', '收编土匪武装组成伪军，在陕州、灵宝一带配合日军作战，袭击抗日游击队。；在孟津组织维持会，配合日军封锁黄河渡口，搜捕抗日人员，其活动范围覆盖洛阳北部及老城周边。；统辖豫西伪政权，驻洛阳，负责协调各县维持会与伪军，为日军掠夺物资。；在洛阳教育文化界附逆，主持伪教育会，推行奴化教育，为日军占领宣传服务。', '[]', '2026-09-10 09:57:14.045918', '2026-09-10 09:57:14.045918', '河南', '三门峡', '陕州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7ab16296258b471fa99d2345530bedba', '周维纲', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安青原；江西萍乡上栗；江西萍乡；湖北黄冈麻城', '[]', '[]', '抗日战争时期', '', '麻城人，任伪麻城县警察局局长，配合日军和伪县政府镇压抗日活动，迫害抗日家属。；在萍乡县东桥、上栗一带担任伪保甲长，负责为日军征丁征粮、监视村民言行，多次向日军密报抗日人员行踪。；在青原一带协助日军建立基层维持会，任副会长，负责征粮、派夫、传递情报，压迫当地民众。', '[]', '2026-09-10 09:57:14.039971', '2026-09-10 09:57:14.039971', '江西', '吉安', '青原', NULL, NULL, NULL, NULL, '');
