INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7ae930dc4cde42a1a8f565fd2b0d03bd', '郑大章', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京；天津河北', '[]', '[]', '抗日战争时期', '', '在南京任伪警察厅长，协助日军维持殖民秩序；河北人，汪伪军事参议院副院长，协助日军整编伪军。', '[]', '2026-09-10 09:57:14.033165', '2026-09-10 09:57:14.033165', '天津', '河北', NULL, NULL, NULL, NULL, NULL, '');
