INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7af6c2f84cac4b40a3b1093a5370be91', '赵金宝', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏无锡惠山', '[]', '[]', '抗日战争时期', '', '为日军搜集新四军及游击队情报，多次导致抗日据点被破坏。', '[]', '2026-09-10 09:57:14.035691', '2026-09-10 09:57:14.035691', '江苏', '无锡', '惠山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7b076e4d1b9b4a119d55189c00c29e95', '周文山', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽池州东至；江西九江瑞昌；江西九江；江西抚州临川；江西九江都昌；江西景德镇；江西上饶广丰；江西南昌；浙江衢州龙游；湖北宜昌；湖北宜昌远安；江西抚州金溪；安徽铜陵铜官；安徽铜陵', '[]', '[]', '抗日战争时期', '', '组织伪自卫团配合日军清乡，在铜陵、铜官一带搜捕新四军和抗日群众，烧杀抢掠。；率伪保安队配合日军对金溪及周边乡村进行扫荡，搜捕抗日人员，强征民夫修筑据点。；至德（今属东至县）本地武装头目，率部投敌后被编为伪至德县保安团，任团长，配合日军对东至山区进行扫荡，杀害抗日军民。；在日军扶植下参与筹建伪临川县政府，负责联络地方士绅附逆，推行保甲连坐与物资统制。；在九江沦陷区担任保甲长、伪乡长，执行日军征粮、派夫、编查户口等命令，协助控制基层。；在远安统率伪保安队，协助日军征发民夫、物资。；南昌沦陷后长期任伪南昌县维持会会长，为日军征粮、拉夫、搜集情报。；在都昌乡村推行保甲连坐，监视村民，向日军告密抗日人员行踪。；日军首次侵占龙游时，率先组织维持会，为日军筹粮派款，提供民夫和情报，并劝诱乡绅投敌。；在乐平县组织维持会，协助日军控制乐平至景德镇交通线，镇压抗日民众。', '[]', '2026-09-10 09:57:14.008575', '2026-09-10 09:57:14.008575', '安徽', '池州', '东至', NULL, NULL, NULL, NULL, '');
