INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7b99649e4ec4419998c7884e9bf36a94', '徐季敦', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江舟山岱山；浙江舟山；浙江金华兰溪；浙江金华；浙江舟山普陀；浙江舟山；浙江台州临海；浙江台州；浙江_舟山_嵊泗；浙江丽水庆元；浙江舟山；浙江金华东阳；浙江金华', '[]', '[]', '抗日战争时期', '', '指挥伪保安部队配合日军“扫荡”，围剿浙东抗日游击队。；在台州地区设立伪政权机构，配合日军扫荡，强征民夫和粮食。；浙江人，汪伪浙江省政府官员，参与伪化统治。；在舟山定海县为日军效力，组织伪警察和维持会，协助日军控制港口。；在金华县城内为日军征粮、派夫，镇压抗日活动，破坏地下党组织。；在舟山地区为日军征粮派款，强征民夫，协助日军控制海岛，镇压渔民抗日活动。；在舟山定海县任伪职，为日军征粮派夫，协助维持占领区秩序，镇压抗日游击队。；任伪金华县知事期间，为日军征粮派夫，镇压抗日活动，协助建立日伪基层政权。', '[]', '2026-09-10 09:57:14.049428', '2026-09-10 09:57:14.049428', '浙江', '丽水', '庆元', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7baa867073064a19adb64c8be27f7972', '林景仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德蕉城；福建厦门；台湾板桥', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：板桥林家，赴伪满洲国任职，伪满外交部政务司欧美科科长，服务伪满傀儡政权。。结局：抗战胜利后被捕，后释放返回台湾', '[]', '2026-09-10 09:57:14.061413', '2026-09-10 09:57:14.061413', '福建', '宁德', '蕉城', NULL, NULL, NULL, NULL, '');
