INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7bec83eedddd445fa22b26922c7d8999', '龚绶', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山腾冲；云南保山龙陵；云南昆明安宁；云南普洱西；云南昆明晋宁；云南德宏梁河；云南德宏陇川；云南德宏梁河；云南德宏芒市；云南德宏梁河；云南昆明西山；云南德宏陇川；云南保山隆阳；云南保山', '[]', '[]', '抗日战争时期', '', '日军侵占滇西后，腾冲、龙陵及周边边地出现维持会组织。龚绶作为地方土司势力人物，被部分史料列为与日伪合作、参与维持地方治安者。；日军占领梁河、盈江一带后，龚绶出任南甸维持会会长，协助日军维持地方秩序、征派物资，并参与伪政权组织。；日军占领梁河后，龚绶投靠日军，在南甸（今梁河）组织维持会，出任伪南甸宣抚使，协助日军征派粮秣、民夫，并参与镇压当地抗日活动。；滇西沦陷期间，南甸土司区被日军控制，龚绶曾被迫与日军接触，但未积极附逆。；龚绶在陇川沦陷后组织伪维持会，协助日军统治当地。；云南梁河一带土司，日军侵占滇西后曾出任伪维持会会长，协助日军征粮、派夫，后抗日武装反攻时被俘。；在滇西沦陷区与日军合作，参与维持会活动，活动范围接近保山地区。；日军占领潞西（今芒市）后，龚绶率先投敌，出任伪芒市安抚使，主持伪维持会，为日军搜集情报、征粮派款，并诱降当地土司头人，协助日军控制芒市、遮放一带。', '[]', '2026-09-10 09:57:13.980009', '2026-09-10 09:57:13.980009', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7bf8cdde306e4694bd5e366099838083', '扎奇斯钦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古乌海；内蒙古乌兰察布化德；内蒙古巴彦淖尔乌拉特中旗；内蒙古乌兰察布兴和', '[\"札奇斯钦\"]', '[]', '抗日战争时期', '', '参与伪蒙疆政权在乌拉特中旗的行政建设，协助推行奴化教育，宣传“日蒙亲善”。；在兴和县任伪县长期间，为日军征粮派款，组织伪警察镇压抗日群众，协助日军建立情报网。；在化德参与伪政权行政事务，协助推行日伪奴化教育。', '[]', '2026-09-10 09:57:13.986671', '2026-09-10 09:57:13.986671', '内蒙古', '乌兰察布', '兴和', NULL, NULL, NULL, NULL, '');
