INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7c43b68388f44742a727b7a16a20a1f3', '李永平', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊诸城；江苏盐城滨海；河北唐山丰润；河北；山东诸城；山东日照东港；江苏盐城滨海；山东日照；山东潍坊潍坊滨海经开区；江苏盐城滨海；河北唐山迁安；山东日照；江苏盐城滨海；山东日照莒县；山东日照；山东青岛；山东日照日照经开区；山东潍坊诸城；高密；山东日照岚山；山东日照', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汉奸头目（伪滨海警备军司令）；罪行：高密人。原为土匪，“九一八”后拉起队伍占山为王。1943年率6000余人投靠日军，任伪滨海警备军少将司令，盘踞胶南、诸城沿海。1944年制造“泊里惨案”，杀害共产党员和群众120多人；结局：1944年11月1日病死在青岛；专门抓捕抗日家属，刑讯逼供，破坏地下交通站，罪行累累。；在迁安县城及乡镇建立伪警察网络，严查抗日地下交通线，多次带队搜捕八路军游击队和地下党员。；伪任职务：伪滨海警备军司令，盘踞泊里，制造泊里大屠杀惨案。结局：1944 年病死于青岛；伪职：伪滨海警备军司令；罪行：盘踞胶南泊里镇一带，配合日军扫荡滨海区，制造泊里惨案祸害民众；来源：项目数据库；备注：1944年病死于青岛', '[]', '2026-09-10 09:57:14.014364', '2026-09-10 09:57:14.014364', '山东', '日照', '高密', NULL, NULL, NULL, NULL, '');
