INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7cde2be5cf4541e791abde8eab0cd810', '桂柳地区伪军头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林全州', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '在桂柳会战后的沦陷区，部分投敌武装被编为伪军，配合日军扫荡抗日游击区。', '[]', '2026-09-10 09:57:14.032036', '2026-09-10 09:57:14.032036', '广西', '桂林', '全州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7ceefa22e31c413db3b54c638e72c265', '胡国臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '抚松、濛江', '[]', '[]', '抗日战争时期', '', '伪职：抗联一军军需部长，叛徒特务；罪行：叛变投敌，献计抓捕程斌母亲胁迫程斌投降，出卖抗联大量机密情报党史学习教...。；结局：解放后被镇压。', '[]', '2026-09-10 09:57:14.086538', '2026-09-10 09:57:14.086538', '吉林', '白山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7cf9061268324b1a9bcb1b6b8a3d2758', '陈耀汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽东明；山东菏泽；山西阳泉城区；山东聊城莘县；山东聊城；山东聊城；湖北武汉；山东聊城东昌府；吉林通化东昌；山东聊城阳谷；山东聊城；湖北十堰；云南普洱西；湖北孝感', '[]', '[]', '抗日战争时期', '', '掌管聊城伪警察，搜捕抗日人员，破坏中共地下组织，在聊城城区及周边推行“良民证”制度。；伪武汉警备司令，指挥伪警察与伪军警备武汉市区，搜捕抗日人员，配合日军维持殖民统治。；在菏泽推行日军奴化教育，编写亲日教材，组织师生参加亲日活动，为日军殖民统治培养顺民。；在伪湖北省政府中任职，参与制定沦陷区民政政策，其管辖范围包括孝感、云梦等县。；任伪鲁西道尹期间，辖聊城、阳谷等县，推行伪化行政，征粮抓丁，协助日军建立据点。；统辖鲁西伪军，多次配合日军对聊城周边抗日根据地进行扫荡。；湖北人，抗战期间投敌，任伪鄂西自治军总司令，组织伪军配合日军在鄂西地区作战，镇压抗日武装。；抗战期间投敌，任伪汉口特别市市长，在武汉地区协助日军维持占领统治。；在东昌道伪政权中统领伪保安队，配合日军在聊城及周边各县扫荡，残害抗日军民。；伪鲁西道管辖聊城、莘县等县，主持道级伪政权，推行日军政令、征粮征夫、镇压抗日活动。', '[]', '2026-09-10 09:57:14.017447', '2026-09-10 09:57:14.017447', '山东', '聊城', '东昌府', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7d0233d4dc66400f84933db04d4de740', '孙殿臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆大观；黑龙江双鸭山饶河', '[]', '[]', '抗日战争时期', '', '日军占领初期任维持会长，组织汉奸团体，协助日军建立统治。；带领自卫团为日军带路，破坏抗联密营，抢夺粮食物资，并参与制造多起屠杀事件。', '[]', '2026-09-10 09:57:14.007272', '2026-09-10 09:57:14.007272', '安徽', '安庆', '大观', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7d10f4e82b70492f94c5ba7799c5917b', '杨某', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化靖州；湖南怀化；广东茂名电白；云南曲靖；安徽六安金安；安徽六安；广西贵港平南；云南昆明官渡；云南昆明', '[\"佚名\", \"名不详\"]', '[]', '抗日战争时期', '', '抗战后期昆明周边曾出现日伪渗透与维持会活动传闻，但云南地处大后方，未沦陷，故无成体系伪政权；相关人物多无明确档案记载。；日军侵占平南期间，组织维持会，为日军筹粮、拉夫，维持伪政权。；在电白县组织伪维持会，为日军征集物资、情报，配合伪政权推行保甲制度，压迫当地民众。；怀化地区在1944-1945年日军进攻湘西时，部分县曾出现维持会，但地方志记载简略，具体负责人姓名多不可考。此条为示意，无确证。；地方志中提及曲靖沦陷区有伪警察头目为日军搜集情报、抓捕抗日人员，但具体姓名缺失。；六安本地伪军头目，率保安团配合日军扫荡六安周边抗日根据地，抓捕抗日人员。', '[]', '2026-09-10 09:57:13.985580', '2026-09-10 09:57:13.985580', '云南', '昆明', '官渡', NULL, NULL, NULL, NULL, '');
