INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7e8b46dc220e4fac920668c0df8a55d1', '陈志康', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴新昌；浙江绍兴', '[]', '[]', '抗日战争时期', '', '在绍兴伪政府任职期间，多次派员到新昌催收捐税，协助日军清乡，破坏地下抗日组织。', '[]', '2026-09-10 09:57:14.051907', '2026-09-10 09:57:14.051907', '浙江', '绍兴', '新昌', NULL, NULL, NULL, NULL, '');
