INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7ebe26e72eb14874a35618e165775465', '林寄凡', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建漳州漳浦；福建漳州南靖；福建厦门；福建泉州；福建漳州', '[]', '[]', '抗日战争时期', '', '漳浦县旧文人，在日军舰艇骚扰漳浦沿海时出面组织维持会，协助日军登陆侦察、征发民夫，后随日军撤退而逃往厦门。；在厦门沦陷区推行日语教育和奴化教育，篡改历史教材，毒化青少年思想，为日军殖民统治服务。；在伪福建政权中推行奴化教育，在漳州等地强制使用日语教材，篡改历史，毒害青少年。；协助陈国辉办理伪维持会事务，为日军征集粮食、劳工，诱降地方士绅。', '[]', '2026-09-10 09:57:14.061502', '2026-09-10 09:57:14.061502', '福建', '泉州', '南靖', NULL, NULL, NULL, NULL, '');
