INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f225b4cfbdd4dc68280daff0a2294cf', '郑海山', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁；湖北黄石', '[]', '[]', '抗日战争时期', '', '控制码头工人，强迫为日军装卸物资，克扣工资，协助日军镇压工人反抗。；为日军征集物资，强拉民夫，破坏抗日地下组织。', '[]', '2026-09-10 09:57:14.057478', '2026-09-10 09:57:14.057478', '湖北', '黄石', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f2691a38704460499d0ccc90434ff9a', '李耀林', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西玉林陆川；广西玉林兴业；山西阳泉城区；广西南宁；广西南宁邕宁；广西北海海城；广西北海；广西南宁青秀；广西南宁；广西贺州钟山；贵州六盘水钟山；广西南宁兴宁；广西南宁；广东肇庆广宁；广西柳州融水；广西南宁；广东湛江；广东湛江霞山；广东云浮郁南；广西钦州浦北；广西北海合浦；广西钦州钦南；广西防城港；广西_贵港；广西_贵港_桂平；广西_贵港_港北；广西_贵港_港南；广西北海合浦；广西北海；广西柳州柳城；广西柳州', '[]', '[]', '抗日战争时期', '', '在北海沦陷期间充任伪警察头目，带领伪警配合日军搜捕抗日人员、勒索商民。；率伪保安队配合日军扫荡钦县、防城一带抗日游击区，为日军带路、侦察，残害抗日群众。；在合浦、浦北一带协助日军建立维持会组织，为日军征集物资、情报。；日军侵占南宁期间任伪南宁维持会副会长，协助田次廉组织伪政权，动员商户开门营业、为日军提供物资和劳务。；兴业县沦陷期间出任伪维持会会长，为日军筹粮、派夫，协助维持伪统治。；在日军占领柳州期间，以商会名义为日军筹款、摊派物资，协助日军控制柳州经济。；日军侵占柳州期间，任伪柳州商会会长，协助日军掠夺物资、控制商业。；在日军占领南宁期间出任伪警察头目，配合日军搜捕抗日人员、维持城区治安。；在日军占领南宁期间出任伪警察局长，协助日军维持治安、搜捕抗日人员。；在日军占领南宁期间出任伪警察局局长，统率伪警察配合日军搜捕抗日人员、维持占领区治安，迫害民众。；日军占领南宁期间出任伪警察局长，配合日军搜捕抗日人士、镇压民众反抗。；在日军占领南宁期间，李耀林出任伪警察局长，配合日军搜捕抗日人士、镇压民众。；在日军第一次侵占南宁时组织伪维持会，为日军筹粮、拉夫，协助建立伪基层保甲。；日军占领南宁后，出任伪南宁县县长，为日军征粮派款、拉夫修路。；日军侵占邕宁期间，组织伪邕宁县维持会，协助日军推行保甲、征粮征夫。；在日军占领贵县期间充任伪警察头目，带领伪警配合日军搜捕抗日人员、镇压民众。；在日军占领贵县期间担任伪警察头目，协助日军搜捕抗日人员、镇压民众。；在日军占领贵县期间担任伪警察头目，带领伪警察配合日军搜捕抗日人员、镇压民众反抗。；在日军占领贵县期间出任伪警察头目，带领伪警配合日军搜捕抗日人员，镇压民众反抗。；北海沦陷后参与组织伪维持会，为日军筹款筹粮，协助日军管理港口与码头。；郁南沦陷后组织伪维持会，任会长，协助日军维持地方统治。；率部投靠日军，改编为伪保安队，配合日军扫荡贺县、钟山一带抗日游击队。；统领伪警察武装，配合日军在广宁及周边地区进行治安强化运动，迫害抗日军民。；在西营（今霞山）地区组织伪维持会，配合日军进行物资征调和人口登记。', '[]', '2026-09-10 09:57:14.025907', '2026-09-10 09:57:14.025907', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
