INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f5fc48cca42471cbb0b1b5c2074c132', '张子良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '湖北荆州；湖北荆门；河北沧州海兴；山东滨州滨城；山东滨州；广东惠州；河北衡水；山东东营河口；河北沧州河间；山东德州武城；山西、河北；湖南常德武陵；山东东营东营港经开区；山东东营利津；山东滨州阳信；浙江嘉兴海盐；山东菏泽鄄城；山东滨州惠民；山东东营；山东淄博高青；山东德州宁津；山东淄博淄川；宁夏银川贺兰；内蒙古包头；山东烟台；山东烟台海阳；湖北随州随县；辽宁沈阳大东；山东滨州邹平；山东济宁嘉祥；河北沧州运河；辽宁沈阳大东；湖北宜昌点军；湖北宜昌；山东济宁兖州；山东济宁；山东济南商河；湖南常德石门；湖南常德；湖南常德常德西洞庭管理；湖南常德；山东德州夏津；山东德州；河北沧州沧州高；山东菏泽定陶；山东菏泽；山东济宁任城；山东济宁；河北沧州；河北沧州盐山；山西吕梁方山；湖南常德鼎城；河北沧州青县；山东烟台莱阳；山东青岛平度；山东东营东营经开区；吉林经开区；山东济南济阳；山东济南；山东烟台烟台经开区；山东烟台；湖南常德；山东滨州沾化；湖北宜昌伍家岗；湖北宜昌；山东滨州；山东滨州邹平；山东聊城；河北沧州吴桥；山东德州乐陵；山东德州；湖北宜昌猇亭；辽宁沈阳大东；山东烟台蓬莱；河北沧州沧州渤海；浙江嘉兴海盐；湖南益阳安化；湖南益阳；河北唐山滦州；山东烟台烟台高；山东烟台；河北廊坊；河北廊坊文安；重庆沙坪坝；湖南益阳桃江；辽宁沈阳大东；湖南益阳资阳；湖南长沙宁乡；山东德州齐河；山东德州；山东菏泽菏泽高；山东菏泽巨野；福建宁德屏南；黑龙江鹤岗南山；山东菏泽巨野；山东烟台蓬莱；山东威海荣成；湖北十堰；山东潍坊临朐；山东潍坊；湖南益阳；湖南益阳南县；山东德州德城；山西阳泉城区；山东聊城茌平；山东聊城；湖北宜昌；湖北武汉；广东惠州惠东；山东德州庆云；湖南益阳赫山；浙江金华兰溪；山东滨州博兴；山东滨州沾化；江西赣州赣县；山东德州平原；湖南益阳益阳大通湖管理；湖南岳阳；山东德州临邑；湖北宜昌五峰；湖北宜昌远安', '[\"同名\"]', '[]', '抗日战争时期', '', '率伪保安队多次配合日军扫荡方山抗日根据地，杀害抗日干部和群众，烧毁村庄，抢夺粮食牲畜。；配合日军在滦州进行细菌实验，掩盖日军暴行。；在文安洼地区配合日军水陆扫荡，破坏抗日苇塘根据地，杀害多名区干部。；在盐山地区积极效忠日军，组织伪警察队，参与“清乡”行动，掠夺民间财物。；日军占领盐山后率先组织维持会，为日军筹粮派款，强拉壮丁充实伪军，并指使汉奸特务破坏抗日地下组织。……（共涉及15个地区的犯罪记录）；在滦州医院为日军提供伤员治疗，拒绝救治抗日伤员。', '[]', '2026-09-10 09:57:14.004008', '2026-09-10 09:57:14.004008', '宁夏', '银川', '贺兰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f68b271eb8e4b2ab8d58fe2ad789dde', '马昆山', NULL, NULL, NULL, NULL, 'exact', 'exact', '锦州', '[]', '[]', '抗日战争时期', '', '伪职：伪锦州总商会会长；罪行：为日军筹措粮食、被服、军需物资；摊派各种 “报国捐”，压榨辽西商民。；结局：反奸清算，没收财产，判处徒刑。', '[]', '2026-09-10 09:57:14.067622', '2026-09-10 09:57:14.067622', '辽宁', '锦州', NULL, NULL, NULL, NULL, NULL, '');
