INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f827c63890b4755bfa18cbefd27f2b4', '严和尚', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西临川（文昌桥外）', '[]', '[]', '抗日战争时期', '', '伪职：附日汉奸；罪行：1942年日军占领临川县城，主动投靠日军，协助日军在城内搜刮物资、欺压百姓；日军撤退后被国民政府肃奸处决；来源：抚州新闻网、临川抗战史料；备注：外号，无记载正式本名，原为市井无赖、杀猪帮工', '[]', '2026-09-10 09:57:14.072204', '2026-09-10 09:57:14.072204', '江西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f82ed684dd84e5e8c72b89fa23320f5', '刘湘图', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城大丰；山西阳泉城区；江苏泰州泰兴；江苏泰州高港；江苏南京；江苏泰州兴化；江苏扬州江都；江苏扬州；江苏淮安；江苏盐城；江苏连云港；广西防城港港口；江苏泰州；江苏泰州海陵；兴化全县；江苏扬州仪征；江苏盐城滨海；江苏扬州邗江', '[]', '[]', '抗日战争时期', '', '伪职：伪第 22 师中将师长；罪行：原国军军官投敌，七千伪军盘踞兴化城；大修碉堡 170 余座，频繁下乡扫荡，抓捕残害抗日干部群众；日本投降后拒不向新四军投降，固守兴化负隅顽抗泰州市党史...。；结局：1945 年兴化攻城战斗被俘，公审枪决兴化日报。', '[]', '2026-09-10 09:57:14.033360', '2026-09-10 09:57:14.033360', '江苏', '南京', '仪征', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('7f8d3d21e8cf4743bd16b8ded020f6f7', '王豫民', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊寒亭；山东潍坊青州；山东潍坊昌邑；山东潍坊昌邑；山东烟台；山东潍坊寿光；山东潍坊昌乐；山东潍坊昌邑', '[]', '[]', '抗日战争时期', '', '原国民党地方武装头目，1943年随厉文礼投敌，在潍县、安丘、昌邑一带活动，配合日军扫荡，残害百姓。；协助厉文礼在潍县、寒亭一带组织伪军，参与扫荡抗日根据地，残害百姓。；在昌邑、平度、掖县一带活动，后投靠日伪，参与伪军组织，配合日军扫荡胶东和潍坊东部地区。；在胶东地区投敌，任伪军职务，配合日军扫荡烟台、海阳一带抗日力量。；在潍县、昌邑一带活动，协助日军维持占领区，残害抗日群众。；厉文礼部副司令，在潍县、安丘、寿光一带配合日军扫荡八路军根据地。；随厉文礼投敌，在潍县、安丘、昌乐一带活动，配合日军进攻八路军。；山东昌邑人，投敌后任伪县长兼伪军头目，在昌邑、潍县北部活动，配合日军扫荡抗日根据地。；在昌邑、高密一带组织伪政权和伪军，配合日军进攻抗日根据地。', '[]', '2026-09-10 09:57:14.016884', '2026-09-10 09:57:14.016884', '山东', '潍坊', '昌邑', NULL, NULL, NULL, NULL, '');
