INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8067a98701044f4990df16534520ea94', '白江绪', NULL, NULL, NULL, NULL, 'exact', 'exact', '汤原、伊春全境小兴安岭山区', '[]', '[]', '抗日战争时期', '', '伪职：原抗联六军政治部主任，叛徒特务；罪行：被俘投降日伪，出卖下江地区抗联全部情报、密营位置、地下救国会组织；策反抗联干部，给日伪讨伐队充当向导，抗联六军遭受重大损失。；结局：抗战胜利后被民主政府逮捕处决。', '[]', '2026-09-10 09:57:14.084495', '2026-09-10 09:57:14.084495', '黑龙江', '佳木斯', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('806974cc49a54c56ab145fd248230e46', '刀京版', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明西山；云南德宏瑞丽；云南德宏芒市；云南德宏瑞丽；云南保山腾冲；甘肃甘南合作；云南昆明晋宁；云南普洱西；云南昆明安宁；云南德宏陇川；云南德宏瑞丽；云南保山隆阳；云南保山', '[]', '[]', '抗日战争时期', '', '日军侵占滇西后，刀京版在瑞丽、陇川一带组织维持会，协助日军征粮、派夫、维持治安，并出任伪瑞丽设治局局长，为日军在德宏地区的统治提供地方行政支持。；南甸土司刀氏家族成员，日军占领期间曾参与维持会活动。；日军占领滇西后，被迫与日军合作，后率部反正参加抗日，其活动范围涉及保山地区。；日军侵占滇西后，刀京版在陇川地区组织维持会，协助日军征粮、派夫，并参与伪政权活动，为日军在陇川的统治提供支持。；日军侵占滇西后，刀京版在瑞丽、畹町一带组织维持会，协助日军推行‘以华制华’政策，为日军征派粮秣、民夫，并参与组建伪地方武装，配合日军对滇西抗日游击区进行扫荡。；滇西沦陷期间，部分土司在日军压力下与日伪有接触，但刀京版等后来组织抗日武装。相关附逆情节史料记载不一，需谨慎对待。；滇西边地土司势力代表之一。日军侵入滇西后，部分边地土司在威逼利诱下与日军合作，参与维持会或伪政权活动。刀京版常被列入滇西边地附日势力相关记载中。；刀京版在瑞丽沦陷后出任伪维持会会长，为日军征粮、派款。', '[]', '2026-09-10 09:57:13.979963', '2026-09-10 09:57:13.979963', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('806c551313d0482894f4fcad6f98e855', '刘乙久', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：儋县治安维持会秘书，儋州伪政权核心，协助日军掠夺盐矿物资。结局：抗战胜利后审判处死', '[]', '2026-09-10 09:57:14.075157', '2026-09-10 09:57:14.075157', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
