INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('808082ca7a324ad595309f25abda79e7', '黄光斗', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安永丰；江西抚州临川；江西抚州；江西宜春袁州；江西南昌；江西鹰潭余江；江西抚州临川；江西上饶玉山；江西上饶；江西宜春上高；江西宜春', '[]', '[]', '抗日战争时期', '', '临川沦陷期间任伪县长，组织维持会，协助日军清乡，搜捕抗日志士。；率伪保安队配合日军扫荡宜春、上高交界地区，搜捕抗日人员，镇压民众。；在江西日占区出任伪职，协助日军推行保甲连坐，镇压南昌及赣中一带抗日活动，其势力范围一度覆盖宜春部分区域。；在永丰沦陷区担任伪警察局长，协助日军维持治安，逮捕抗日志士，迫害民众。；串联抚州各县维持会，为日军搜集情报、劝诱地方武装投降，并参与组织伪自卫团。；浙赣会战期间在江西沦陷区参与筹组伪政权，联络上饶、玉山等地维持会，为日军提供情报与物资。', '[]', '2026-09-10 09:57:14.038007', '2026-09-10 09:57:14.038007', '江西', '上饶', '玉山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8080e56903da495cba968d147cfa4363', '梁永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '率伪军多次配合日军扫荡矿区周边村庄，抓捕抗日军民，烧毁民房，抢夺物资，并参与杀害八路军侦察员3名。', '[]', '2026-09-10 09:57:14.024679', '2026-09-10 09:57:14.024679', '山西', '阳泉', '矿区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8081b6d10a7245998ece748a6de95ac1', '杨茂林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古鄂尔多斯东胜；内蒙古、山西；山西_忻州_忻府；河南南阳方城；山西吕梁岚县；辽宁沈阳新民；山西阳泉盂县；山西忻州原平；河南郑州中牟；河南商丘宁陵；河南商丘；山西忻州繁峙；山西运城；山西太原古交；山西临汾安泽；河南商丘民权；河南周口鹿邑；河南周口淮阳', '[]', '[]', '抗日战争时期', '', '参与策划对东胜地区抗日游击队的围剿，协助日军建立情报网，破坏抗日组织。；率警备队驻守安泽县城，多次参与“清乡”行动，杀害抗日军属，并抢劫民间财物。；宣传奴化思想，组织“新民会”胁迫群众参加日军庆典，破坏抗日宣传，提供情报给日军。；垄断古交粮食和食盐配给，克扣民食，逼使百姓饿死。；组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日干部，杀害无辜百姓，抢劫财物。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.992092', '2026-09-10 09:57:13.992092', '山西', '临汾', '安泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80928aac3b1e48dfac669891ef10b689', '郝梦龄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州五台；河北石家庄；河北；河北_邢台_邢台经开区', '[\"注：此人为抗日烈士，非汉奸，但历史资料中同名者需区分，此处不列入\", \"非抗日将领，同名汉奸\"]', '[]', '抗日战争时期', '', '在石家庄东部地区组织伪军“剿共”队，专门搜捕八路军交通员。；为日军征收苛捐杂税，强征商业税和土地税，中饱私囊，导致民不聊生。', '[]', '2026-09-10 09:57:14.021691', '2026-09-10 09:57:14.021691', '山西', '忻州', '五台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8093f8a361624737a54b71fe20ab85d5', '方大垓', NULL, NULL, NULL, NULL, 'exact', 'exact', '岳阳县', '[]', '[]', '抗日战争时期', '', '伪职：伪岳阳县政府筹备处处长→伪岳阳县长；罪行：前岳阳县中学校长。1939年9月任日伪岳阳县政府筹备处处长；1941年1月筹备处改组为日伪岳阳县政府后任县长', '[]', '2026-09-10 09:57:14.071722', '2026-09-10 09:57:14.071722', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80987c66b489495d80cb73b6a9957896', '陈伯诚', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建厦门湖里；福建厦门；福建宁德柘荣；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在闽东地区为日伪进行文化宣传，散布“大东亚共荣”言论，协助日军进行思想控制。；在厦门基层推行保甲制度，协助日军清查户口、监视居民、抓捕抗日嫌疑人员。；在厦门伪警察系统任职，参与镇压抗日活动与管控民众。', '[]', '2026-09-10 09:57:14.061155', '2026-09-10 09:57:14.061155', '福建', '厦门', '湖里', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80a1c335e7284fe7b025cbc2fb374d5c', '林阿发', NULL, NULL, NULL, NULL, 'exact', 'exact', '乌丘屿', '[]', '[]', '抗日战争时期', '', '伪职：日伪翻译汉奸；罪行：为岛上日军当翻译，协助审讯被俘渔民、海上游击人员，给伪军出谋划策，引导伪军登岸骚扰莆田沿海村庄。；结局：光复后抓捕判刑。', '[]', '2026-09-10 09:57:14.083599', '2026-09-10 09:57:14.083599', '福建', '莆田', NULL, NULL, NULL, NULL, NULL, '');
