INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80ae16c618724055b6988bb2556a043b', '王宁道', NULL, NULL, NULL, NULL, 'exact', 'exact', '来安水口', '[]', '[]', '抗日战争时期', '', '伪职：伪来安县水口区区长；罪行：把持水口区伪政权，收纳投敌溃兵，出卖抗日人员，向伪县长侯堂生告密设圈套杀害起义人员袁明举滁州市博物...。；结局：1946 年肃奸枪决。', '[]', '2026-09-10 09:57:14.082954', '2026-09-10 09:57:14.082954', '安徽', '滁州', NULL, NULL, NULL, NULL, NULL, '');
