INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80ce3494e70e4741bbb98c544305f791', '陈子英', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮北烈山；浙江湖州长兴', '[]', '[]', '抗日战争时期', '', '负责为日军管理烈山煤矿劳工，克扣工资，虐待矿工，多次向日军举报矿内抗日地下活动，导致多名矿工被捕牺牲。；负责伪警察系统，搜捕抗日地下党员，破坏中共长兴地下组织，并协助日军推行保甲制度。', '[]', '2026-09-10 09:57:14.008771', '2026-09-10 09:57:14.008771', '安徽', '淮北', '烈山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80cfcb51ed634b1093d4c0e2649687be', '戴东藩', NULL, NULL, NULL, NULL, 'exact', 'exact', '西安（辽源）', '[]', '[]', '抗日战争时期', '', '伪职：九一八后代理县长，伪西安县第一任县长；罪行：九一八原县长逃跑，戴东藩代理县长，主张出城迎接日军；组建伪西安县公署，依靠日军武力维持统治，协助日军接收西安煤矿，推行保甲，镇压地方抗日武装辽源市人民...。；结局：抗战胜利后逮捕，汉奸罪判处徒刑。', '[]', '2026-09-10 09:57:14.087178', '2026-09-10 09:57:14.087178', '吉林', '辽源', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80e1396a8fcb49e5b8e4057ea9fde0f6', '赵梓亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东东营垦利；山东东营河口；山东东营东营经开区；山东东营；山东滨州惠民', '[]', '[]', '抗日战争时期', '', '在滨县、东营一带为日军效劳，组织伪政权，搜捕抗日人员。；蒲台县（今东营区、东营经开区大部及博兴一带）伪政权头目，协助日军维持占领秩序，征发民夫、物资。；在阳信、惠民边界地区组织维持会，为日军筹粮筹款，配合日军清乡。；在利津及黄河口附近组织维持会，迎接日军，筹粮筹款，协助建立伪政权，压迫当地民众。', '[]', '2026-09-10 09:57:14.011705', '2026-09-10 09:57:14.011705', '山东', '东营', '东营经开区', NULL, NULL, NULL, NULL, '');
