INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('80f1a421c12140648e4cdd60ea92a33c', '张金铭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台莱州；山东青岛平度；山东烟台莱山；山东烟台芝罘；山东青岛平度', '[]', '[]', '抗日战争时期', '', '在山东平度、莱州一带组织伪军，配合日军扫荡，残害抗日军民。；海阳伪县长，协助日军控制海阳、莱山沿海地区。；平度邻近烟台，张任伪县长，配合日军扫荡胶东，推行保甲连坐。；任伪平度县县长，配合日军统治，镇压抗日活动，活动范围邻近莱西。', '[]', '2026-09-10 09:57:14.017281', '2026-09-10 09:57:14.017281', '山东', '烟台', '芝罘', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('81010b671ea341b48dbb3a0f6d8a9eb2', '叶永年', NULL, NULL, NULL, NULL, 'exact', 'exact', '哈尔滨全市，参与三肇地区扫荡；山东', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪哈尔滨警察厅特务科，北满大特务，抓捕残害大量地下党、爱国群众。结局：1951 年哈尔滨公审枪决；伪职：伪哈尔滨警察厅外勤警佐，特务头目（“白菜叶” 之一）；罪行：手下 “四大扒皮”“八大打手”，大肆抓捕杀害抗联、爱国群众；制造三肇血案，敲诈商户，制造多起冤狱抖音百科。；结局：1951 年被处决。', '[]', '2026-09-10 09:57:14.078843', '2026-09-10 09:57:14.078843', '山东', '哈尔滨', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('810a8d8d78814243be656f4732cb5ac3', '王逸轩', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三沙南沙；海南定安', '[]', '[]', '抗日战争时期', '', '在定安地区投靠日军，任伪定安县县长，组织伪维持会、伪保安队，配合日军对定安及南渡江流域抗日力量进行扫荡和清剿。', '[]', '2026-09-10 09:57:14.053480', '2026-09-10 09:57:14.053480', '海南', '三沙', '南沙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('810e2a651346473f83619b07e0a8f571', '陈宝荃', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪万全县县长；管控万全、孔家庄一带，推行集家并村，抓捕堡垒户。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.086961', '2026-09-10 09:57:14.086961', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8113b82e26914d40a5db185f2367496d', '韦贽唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州；广西南宁；辽宁沈阳大东；云南普洱西；江苏南京；广西桂林荔浦；广西桂林平乐', '[]', '[]', '抗日战争时期', '', '荔浦沦陷期间投敌，任伪警察所所长，率伪警配合日军搜捕抗日人员，勒索当地民众。；日军侵占柳州后出任伪警察局长，带领伪警察配合日军搜捕抗日人员、维持占领区治安。；广西籍文人，投靠汪伪政权，在南京、广州等地从事亲日宣传，与广西沦陷区伪化宣传有联系。；平乐沦陷后率地方武装投靠日军，编为伪保安队，配合日军扫荡抗日游击队，征缴民间枪支。；在日伪占领区从事亲日宣传，编辑发行伪报纸，鼓吹‘大东亚共荣圈’。', '[]', '2026-09-10 09:57:14.030828', '2026-09-10 09:57:14.030828', '广西', '南宁', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('81193ac68c8847b08b9a6381d6540127', '马骧', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明富民；云南昆明；云南昆明；云南昆明盘龙；云南昆明；云南昆明官渡；云南昆明；云南昆明西山', '[]', '[]', '抗日战争时期', '', '地方史料中偶见昆明附近维持会、伪保甲组织活动记载，但具体姓名、职务多不可考；马骧之名见于部分口述传闻，缺乏可靠档案佐证。；马骧为云南籍，曾参与汪伪政权对云南的策反活动，被列入拟任云南伪政府人员名单，未实际到任。；马骧系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。；云南昆明地区在抗战后期面临日军从滇西入侵威胁，但昆明市区始终未被日军占领，未建立正式伪政权。地方史料中未见昆明市区有明确记载的汉奸名录。；地方志中偶见昆明附近维持会人员记载，但姓名、事迹残缺，难以确认其确切汉奸身份。', '[]', '2026-09-10 09:57:13.985552', '2026-09-10 09:57:13.985552', '云南', '昆明', '官渡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('812aec16289c484bac74f9ffcc6f9410', '张存礼', NULL, NULL, NULL, NULL, 'exact', 'exact', '潢川县', '[]', '[]', '抗日战争时期', '', '伪职：伪乡长；罪行：张作和之父，名义上担任伪乡长，实际由张作和在伪乡公所当权派款要伕', '[]', '2026-09-10 09:57:14.068488', '2026-09-10 09:57:14.068488', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
