INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8170f77fd2f54d91b191b6bc1179fe0b', '王蔚波', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南湘潭湘乡', '[]', '[]', '抗日战争时期', '', '日军占领湘乡期间任伪县长，推行伪政，协助日军控制湘乡地区。', '[]', '2026-09-10 09:57:14.058986', '2026-09-10 09:57:14.058986', '湖南', '湘潭', '湘乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8175ba4e744148fc8f9bc8d290f13baf', '陈多儒', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三亚；海南三亚吉阳；广西防城港港口；海南三亚崖州；海南三亚海棠', '[]', '[]', '抗日战争时期', '', '在崖县地区为日军搜集情报、抓捕抗日人员，配合日伪军警镇压当地民众。；在三亚榆林地区组织维持会，协助日军管理港口和劳工，为日军军事工程征调民夫，配合殖民统治。；参与组织伪崖县维持会，为日军筹粮筹款、搜集情报，协助维持日占区秩序。；在崖县（今三亚一带）充任伪警察头目，配合日军搜捕抗日人员，勒索百姓，维持日伪统治秩序。；在崖县（今三亚一带）充任伪警察头目，配合日军搜捕抗日人员，勒索民众，维持日伪统治秩序。', '[]', '2026-09-10 09:57:14.052977', '2026-09-10 09:57:14.052977', '海南', '三亚', '吉阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('81862c1b13bf4701b40c52aae2823f4f', '吴国栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江七台河勃利；黑龙江七台河；江苏宿迁泗洪；浙江温州龙港；辽宁葫芦岛龙港；辽宁本溪明山；辽宁本溪；黑龙江佳木斯汤原；山西朔州应县；安徽铜陵；广西钦州浦北；广西钦州；安徽马鞍山当涂；江苏南京高淳；浙江台州仙居；重庆江北；黑龙江绥化安达；重庆北碚；黑龙江佳木斯郊区；黑龙江佳木斯；黑龙江齐齐哈尔；黑龙江大庆；黑龙江大庆杜尔伯特；广西钦州钦南；广西北海合浦；重庆铜梁；浙江温州苍南；浙江温州；江苏淮安金湖；江苏镇江句容', '[]', '[]', '抗日战争时期', '', '在东坝地区为日军征粮派夫，镇压抗日活动，报告新四军行踪。；率部参与“三光”行动，烧毁银集周边民房，抢走耕牛和财物。；直接负责佳木斯市区及郊区治安，抓捕抗日嫌疑人员，镇压地下抗日组织。；组织自卫团协助日军“清乡”，在七台河矿区抓捕劳工，迫害矿工中的抗日分子。；在下蜀镇一带为日军运输物资，协助伪军进攻新四军游击队。；为日军搜集新四军和地方抗日武装的情报，导致多次抗日行动失败，多名地下党员被捕牺牲。；为日军控制温州经济，强制商户缴纳“慰劳金”，并垄断物资供应。；组织“宣抚班”到各村劝降抗联人员，诱骗多名意志薄弱者叛变，并参与建立“思想矫正院”关押爱国群众。；直接参与镇压安达地区的抗日救国会，逮捕并杀害多名爱国人士。；建立汉奸情报网，多次向日军报告新四军活动，导致多处抗日联络点被破坏；率伪军在钦州、浦北边境配合日军扫荡，烧毁抗日村庄，杀害抗日群众。；率领伪保安团配合日军扫荡北碚周边抗日根据地，烧毁民房、抢掠粮食。；任伪黑龙江省民生厅长，在齐齐哈尔推行粮谷出荷、劳工征发等政策。；在龙港地区（原鳌江镇）组织维持会，为日军提供船只和向导，协助日军封锁瓯江口，劫掠商旅财物。；参与维持会，为日军带路、提供情报，协助建立伪政权。；联络重庆周边维持会，协助日军建立伪政权，参与诱降活动。；搜捕抗日志士，刑讯逼供，敲诈勒索百姓。；在杜尔伯特旗警察系统任职，协助日本控制当地蒙古族民众，镇压抗日活动。；为伪政权征收苛捐杂税，强征粮食供应日军，导致民众负担加重。；参与抓捕抗日人员，破坏本溪地区中共地下组织。；在合浦、钦州一带为日军征粮征夫，组织伪自卫队配合日军行动，迫害抗日家属。；率警备队多次袭击抗日游击队，杀害抗日干部，烧毁村庄，罪行累累。', '[]', '2026-09-10 09:57:14.010474', '2026-09-10 09:57:14.010474', '安徽', '铜陵', '当涂', NULL, NULL, NULL, NULL, '');
