INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('820389b48a3d4facb4b45ed04ab4a78b', '李允声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北；河北唐山开平；河北唐山；河北遵化；河北唐山', '[]', '[]', '抗日战争时期', '汪伪政权', '镇压矿工罢工，为日军护矿，迫害进步工人。；驻防唐山地区，协助日军收缴民间武器，强征壮丁，破坏抗日组织。；驻防唐山地区，协助日军“治安肃正”，抓捕抗日地下工作者。；率伪治安军驻冀东，参与1942年“五一大扫荡”在路南地区的行动，烧杀抢掠。；伪任职务：伪冀东保安队头目，盘踞冀东唐山一带。结局：抗战胜利后公审处决', '[]', '2026-09-10 09:57:14.041364', '2026-09-10 09:57:14.041364', '河北', '唐山', '开平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('82114400933648d783093d04d94c85d5', '梁翰嵩', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁马山；广西南宁；广西崇左龙州；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '负责汪伪在广西的宣传工作，在崇左、龙州等地发行伪报刊，宣扬“大东亚共荣”，进行奴化教育。；南宁沦陷后出任伪商会会长，协助日军控制南宁经济、征调物资，并动员商界与日方合作。', '[]', '2026-09-10 09:57:14.031440', '2026-09-10 09:57:14.031440', '广西', '南宁', '马山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8216c64ffe3f4a318b1f43e5a14296c9', '樊仲云', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川广元；广西桂林恭城；云南普洱西；重庆_大足；江苏南京；陕西西安；陕西_西安_长安；江西九江；江苏南京江宁；江苏南京；江苏南京鼓楼；江苏南京浦口；上海杨浦；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '浙江人，汪伪政权教育部次长，从事奴化教育宣传。；在南京伪中央大学推行奴化教育；在汪伪政权中负责教育，推行奴化教育。；在南京伪中央大学推行亲日教育，毒害青年。；参与汪伪奴化教育，影响广西部分学校。；参与奴化教育，为日伪培养亲日人员。；投敌后任伪教育部次长，参与奴化教育。；在杨浦地区（原沪江大学校址）主持伪教育机构，培养汉奸人才。；在南京协助林柏生控制新闻媒体，打压抗日舆论。；在鼓楼区管理伪交通系统，为日军运输物资提供便利。；负责汪伪教育事务，推行奴化教育，对四川等后方进行文化渗透。', '[]', '2026-09-10 09:57:13.977835', '2026-09-10 09:57:13.977835', '上海', '杨浦', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('821dadd25d784e98841628a086ed05d3', '何举之', NULL, NULL, NULL, NULL, 'exact', 'exact', '南乐县', '[]', '[]', '抗日战争时期', '', '伪职：伪清丰县县长；依附日军，掠夺粮棉物资，制造多起抓捕惨案。；结局：战后逮捕判刑；伪职：南乐维持会会长（首任伪县长）；罪行：南乐本地大地主。1937年底日军侵占南乐后出面组建维持会，出任第一任伪县长。加固城门，严查出入人员，设立水牢关押嫌疑群众，逼迫各村上交粮款；结局：1938年四支队进攻南乐城时弃城逃亡，之后下落不明', '[]', '2026-09-10 09:57:14.075551', '2026-09-10 09:57:14.075551', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('821fc8707b914852879f6ef95ec9d88e', '吴天保', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌夷陵；湖北宜昌', '[]', '[]', '抗日战争时期', '', '率伪保安队驻守宜昌近郊，配合日军扫荡抗日游击队，强征民夫修筑工事。', '[]', '2026-09-10 09:57:14.056289', '2026-09-10 09:57:14.056289', '湖北', '宜昌', '夷陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8223f9270e14491ba0e5c5cb9ce22fdd', '于文成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北唐山；河北_唐山_唐山汉沽管理；河北；河北_秦皇岛；河北唐山唐山海港经开区；河北唐山；河北唐山迁安；河北唐山丰南；河北唐山；河北唐山迁西', '[]', '[]', '抗日战争时期', '', '为日伪筹集军费，强迫商户捐献，协助日军经济掠夺。；指挥伪警察搜捕抗日地下党员，破坏地下交通线，参与“大检举”行动，逮捕杀害多名爱国人士。；在丰润、丰南一带任伪县长，推行保甲连坐，强征粮食，配合日军“治安强化运动”，多次带队清乡。；在丰润、丰南一带推行日伪法令，强征民夫修筑据点，协助日军“治安强化运动”。；在唐山、丰润交界处设立检查站，搜捕抗日人员，严刑逼供，杀害多名地下党员。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.041313', '2026-09-10 09:57:14.041313', '河北', '唐山', '丰南', NULL, NULL, NULL, NULL, '');
