INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('825855338f444dcfb31d859a4adbd893', '何德辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶余干；江西抚州广昌；江西抚州南丰', '[]', '[]', '抗日战争时期', '', '在南丰、广昌周边地区率伪保安队配合日军行动，搜捕抗日人员，征派粮款。；担任伪保甲长期间，为日军提供情报，带领日军搜捕抗日人员，强征壮丁。', '[]', '2026-09-10 09:57:14.037620', '2026-09-10 09:57:14.037620', '江西', '上饶', '余干', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('825b3e91dae145d4b3995922a14390fa', '王化南', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东德州宁津；山东德州；河南_三门峡_三门峡经开区；河南_三门峡_湖滨；河北石家庄赞皇；黑龙江大庆；黑龙江大庆林甸；山东济宁兖州；山东济宁；内蒙古赤峰林西；河北石家庄高邑；河北秦皇岛卢龙；河北衡水武强；辽宁沈阳新民；河北；山东德州陵城；山东德州；黑龙江齐齐哈尔甘南；黑龙江齐齐哈尔；河北唐山滦州；河南三门峡卢氏；河南三门峡灵宝；山东济宁汶上；辽宁沈阳新民；山东淄博淄川；山西阳泉矿区；黑龙江绥化海伦；河南三门峡渑池；河南三门峡陕州；河北石家庄行唐；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '在滦州强征各种苛捐杂税，加重百姓负担，供日军军费。；为日军进行奴化宣传，组织‘新民会’活动，诱骗青年参加伪军，协助日军建立保甲制度。；在赞皇推行奴化教育，组织“新民会”宣传亲日思想，诱骗青年参加伪军。；负责高邑县城治安，大肆搜捕抗日地下党员和进步青年，严刑逼供，破坏抗日地下组织，为日军提供情报。；作为日本顾问的帮凶，参与改编伪保安队，推行奴化教育，强迫学校使用伪满教材，破坏抗日地下组织。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.991261', '2026-09-10 09:57:13.991261', '内蒙古', '赤峰', '林西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('825c80d5174541a6b36c9aaf78a3ec61', '邢诒壮', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南三亚崖州；海南三亚海棠', '[]', '[]', '抗日战争时期', '', '日军侵占崖县后出面组织维持会，协助日军推行保甲、征粮、拉夫，维持日伪统治秩序。；日军侵占崖县后出面组织伪维持会，后任伪崖县县长，协助日军推行保甲、征粮、拉夫，镇压抗日群众。', '[]', '2026-09-10 09:57:14.053271', '2026-09-10 09:57:14.053271', '海南', '三亚', '崖州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('825d5662889c48d28b9e89698c602c05', '郭振华', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南平顶山舞钢；河南平顶山鲁山；河南平顶山', '[]', '[]', '抗日战争时期', '', '襄城县（今属许昌市，邻近平顶山）人，日军占领期间任维持会副会长，协助日军征粮、派款，并参与组织伪自卫团。；1944年日军侵占鲁山后，组织维持会，为日军征粮征丁、提供情报，协助日军镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.047990', '2026-09-10 09:57:14.047990', '河南', '平顶山', '石龙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8260bbfca56f4019909e1c0bca17d921', '李金标', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴；河南郑州中牟；浙江_嘉兴_嘉善；浙江嘉兴平湖；浙江嘉兴', '[]', '[]', '抗日战争时期', '', '日军占领嘉兴后率先投敌，组织维持会，为日军提供情报，协助建立伪政权，并参与掠夺当地丝绸和粮食资源。；为日军筹措军需物资，强迫商户捐款，从中牟利，并充当日军经济情报员。；效忠日伪政权，搜捕地下党员，破坏抗日组织，勒索商民。', '[]', '2026-09-10 09:57:14.050284', '2026-09-10 09:57:14.050284', '浙江', '嘉兴', '平湖', NULL, NULL, NULL, NULL, '');
