INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('826a3032208345dd847b4a94b5bbf352', '周养浩', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安；江西南昌', '[]', '[]', '抗日战争时期', '', '在南昌及吉安一带活动，参与伪政权宣传，鼓吹“中日亲善”。', '[]', '2026-09-10 09:57:14.039549', '2026-09-10 09:57:14.039549', '江西', '吉安', NULL, NULL, NULL, NULL, NULL, '');
