INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('827c466b49be4d08b856ef16d30525b1', '叶寅亮', NULL, NULL, NULL, NULL, 'exact', 'exact', '长沙', '[]', '[]', '抗日战争时期', '', '伪职：伪湖南洪兴血义会会长、伪湖南省设计委员会常务委员；罪行：长沙八大汉奸之一。洪帮头目，纠集帮伙成立伪湖南洪兴血义会\"，为日伪军政人员提供场所，并开设赌场。\"；结局：抗战胜利后被捕入狱，1949年越狱，后被人民政府逮捕镇压。', '[]', '2026-09-10 09:57:14.079479', '2026-09-10 09:57:14.079479', '湖南', NULL, NULL, NULL, NULL, NULL, NULL, '');
