INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('833879c90ff84a3eba963d7d4a589efe', '李萼', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_邵阳；湖南邵阳新宁；湖南邵阳；湖南益阳；湖南邵阳大祥；湖南邵阳；湖南邵阳北塔；湖南邵阳；湖南_邵阳_双清；湖南郴州资兴；湖南娄底双峰；湖南娄底；湖南湘潭湘乡', '[]', '[]', '抗日战争时期', '', '充任伪警察头目，协助日军搜捕抗日人员，镇压地方反抗。；湖南沦陷期间附逆，参与伪湖南省政权，其活动范围覆盖湘中、益阳一带。；日军窜扰娄底时组织维持会，为日军筹粮、带路，并诱迫乡民归顺。；邵阳沦陷后投靠日军，组织伪维持会，替日军筹粮、拉夫、搜集情报，镇压抗日群众。；在湖南日占区参与伪政权活动，协助日军推行治安强化，其活动范围涉及邵阳一带。；抗战后期在湖南日占区参与伪政权，为日军在湖南的统治提供行政支持。；湘乡沦陷后组织维持会，替日军筹粮筹款、拉夫，并协助建立伪基层政权。；在郴县沦陷期间参与伪维持会，协助日军推行伪化统治，镇压抗日群众。；率伪保安团协助日军扫荡邵阳周边乡村，强征民夫、勒索粮款。', '[]', '2026-09-10 09:57:14.057523', '2026-09-10 09:57:14.057523', '湖南', '娄底', '双峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('833b4176eef642bb8c868d68e5d89522', '朱少甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州嘉禾；湖南郴州', '[]', '[]', '抗日战争时期', '', '湖南嘉禾人，日军占领嘉禾期间出任伪维持会会长，协助日军征粮、派款、维持治安；嘉禾与郴州、安仁同属郴州地区。', '[]', '2026-09-10 09:57:14.059822', '2026-09-10 09:57:14.059822', '湖南', '郴州', '嘉禾', NULL, NULL, NULL, NULL, '');
