INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8349f2777d6c44348307fa81b42a5ca7', '张殿九', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江绥化', '[]', '[]', '抗日战争时期', '', '组织地主武装协助日军，在绥化农村搜捕抗联联络员，并强征壮丁补充伪军。', '[]', '2026-09-10 09:57:14.066508', '2026-09-10 09:57:14.066508', '黑龙江', '绥化', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('834d554812564ebdb2d05748b5e89dea', '陈耀枢', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东云浮新兴；黑龙江七台河新兴；广东茂名化州；广东茂名；广东阳江阳东；广东阳江；广东茂名茂南；广东茂名；广东阳江阳西；广东阳江；广东云浮', '[]', '[]', '抗日战争时期', '', '抗日战争后期投靠日军，出任伪茂名县维持会会长，后改任伪茂名县县长，协助日军征粮、拉夫，维持沦陷区秩序，镇压抗日群众。；日军侵占新兴期间出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。；抗日战争期间投靠日伪，出任伪阳江县政府县长，协助日军维持阳江地区伪政权统治。；抗战期间在阳江地区附逆，参与组织伪维持会，后任伪阳江县政府县长，协助日军维持占领区秩序、征粮派款。；抗日战争期间在化县一带附敌，参与组织伪维持会，为日军征粮、派夫、维持地方伪秩序。；日军侵占茂名期间出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，并诱迫地方士绅附逆。；日军侵占云浮期间出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.024716', '2026-09-10 09:57:14.024716', '广东', '云浮', '新兴', NULL, NULL, NULL, NULL, '');
