INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83b6c8a634354cc0b43afb01a9f272c2', '韩祥符', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口阳原；内蒙古鄂尔多斯东胜；山西阳泉城区；内蒙古、河北；河北张家口怀来；内蒙古包头；内蒙古乌兰察布；内蒙古包头包头稀土高；内蒙古包头；河北张家口怀安；河北张家口；内蒙古包头石拐；内蒙古包头', '[]', '[]', '抗日战争时期', '', '率伪蒙古军驻防乌兰察布南部，多次参与对八路军大青山支队的围剿，在卓资地区烧杀抢掠。；负责发行伪蒙疆货币，搜刮包头地区财富，配合日军经济掠夺，导致当地通货膨胀，民生凋敝。；日军占领包头初期，组织维持会，为日军征粮派款，提供劳役，协助建立伪政权。；投靠日军任伪包头市长，管理日伪行政，协助日军建立殖民秩序，镇压包头及固阳地区抗日活动，强制推行奴化教育。；在包头、石拐地区从事特务活动，搜集情报，破坏抗日组织。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.987167', '2026-09-10 09:57:13.987167', '内蒙古', '包头', '包头稀土高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83b9db57e98b48eab9496d489a25b329', '札奇斯钦', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌兰察布', '[]', '[]', '抗日战争时期', '', '负责在乌兰察布地区推行奴化教育，强令学校使用日语和蒙奸教材，煽动民族分裂，为日军征兵征粮。', '[]', '2026-09-10 09:57:13.986313', '2026-09-10 09:57:13.986313', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83bd7bd8e6884e36aa27f3fd503e11d1', '金璧东', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林；吉林_延边_延吉；吉林长春', '[]', '[]', '抗日战争时期', '', '曾任伪间岛省省长，在延边地区推行殖民统治，配合日军围剿抗日武装。；清室后裔，投靠日本，曾任伪吉林省长，参与殖民统治，其管辖范围包括四平地区。；清皇室后裔，投靠日本，在吉林、长春等地推行奴化统治，镇压反满抗日活动。', '[]', '2026-09-10 09:57:13.997586', '2026-09-10 09:57:13.997586', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
