INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83d112d926304cf391aa5145efd2589b', '李桂芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '平山县城', '[]', '[]', '抗日战争时期', '', '伪职：青帮头子，新民会骨干；多次向日军告密，致使我方夜袭平山县城计划泄露，造成重大损失河北省老区...。；结局：抗战胜利后镇压处决', '[]', '2026-09-10 09:57:14.068123', '2026-09-10 09:57:14.068123', '河北', '石家庄', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83d21dc6c15b427591026f16705e10e7', '王同安', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南济源；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '推行日语教育和奴化教材，组织教师培训宣扬“大东亚共荣”，毒化沦陷区青年。', '[]', '2026-09-10 09:57:14.048627', '2026-09-10 09:57:14.048627', '河南', '济源', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83d469860b0d4e2a9aabf2aa3a5e1c32', '郭巩', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州章贡；江西赣州赣县', '[]', '[]', '抗日战争时期', '', '日军侵占赣南期间出面组织伪维持会，任伪赣县县长，为日军征粮、征夫、搜集情报，协助日军维持占领区秩序，镇压抗日群众。', '[]', '2026-09-10 09:57:14.040569', '2026-09-10 09:57:14.040569', '江西', '赣州', '章贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83dbc92ee59149afb64947367155a7c7', '马振华', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽东明；山东菏泽；山东菏泽成武；山东济宁嘉祥；山东菏泽定陶；山东菏泽单县；山东菏泽东明；山东菏泽鄄城；山东菏泽；山东菏泽曹县；山东菏泽；山东菏泽菏泽经开区；山东菏泽巨野', '[]', '[]', '抗日战争时期', '', '任伪鲁西道尹，管辖菏泽、东明等县伪政权，推行日军殖民统治政策，督征粮款，配合日军扫荡鲁西抗日根据地。；率伪军在巨野、定陶交界地区活动，配合日军袭击抗日武装，抢掠民财，残害百姓。；与刘本功共同组建伪鲁西剿共军，在郓城、鄄城、菏泽三角地带配合日军扫荡，残害抗日群众。；巨野沦陷后投敌任伪知事，推行伪化教育，为日军征发民夫、物资，镇压抗日群众。；巨野沦陷后投敌，任伪职期间在巨野、成武、嘉祥一带配合日军扫荡，强征民夫修筑碉堡，镇压抗日群众。；东明人，抗战初期组织维持会迎接日军，后任伪东明县县长，协助日军控制黄河渡口，封锁抗日根据地，迫害抗日人员家属。；组织维持会迎接日军，为日军筹集物资，登记户口，协助建立伪保甲制度，镇压抗日活动。；在定陶及菏泽周边地区组织伪军，配合日军扫荡，镇压抗日武装，搜刮民财。', '[]', '2026-09-10 09:57:14.017936', '2026-09-10 09:57:14.017936', '山东', '菏泽', '东明', NULL, NULL, NULL, NULL, '');
