INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83f14750f47e4aa783ec0108f094954d', '郭维周', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪宣化县县长；宣化省核心伪政权，修筑大量炮楼封锁平绥铁路，掠夺粮食矿产。；结局：抗战胜利逮捕，判处长期徒刑', '[]', '2026-09-10 09:57:14.084811', '2026-09-10 09:57:14.084811', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83fb149dca65450d847a69d8756abdfb', '张砚田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '陕西西安长安；河北唐山迁安；江苏南通通州；河北唐山路南；河北唐山；北京通州；江苏南通通州；河北秦皇岛山海关；河北秦皇岛；北京、河北；河北唐山玉田；河北唐山；河北唐山唐山芦台经开区；河北唐山；河北唐山滦州；河北廊坊大厂；河北廊坊；河北唐山滦南；江苏南通通州；河北唐山唐山高；江苏南通通州', '[]', '[]', '抗日战争时期', '', '与张庆余共同参与通州事变，但事变前长期担任伪军职务，参与镇压抗日活动。；与张庆余一同参与通州起义，但起义前曾执行伪政权命令，参与镇压抗日民众。；驻防唐山、丰润一带，执行伪政府命令，协助日军强征民夫、粮食，破坏抗日组织。；与张庆余类似，投日期间在唐山、芦台地区参与伪政权军事活动，后反正。；伪冀东保安队军官，驻防冀东地区，参与维持伪政权统治，后随通州事变反正。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995025', '2026-09-10 09:57:13.995025', '北京', '通州', '唐山芦台经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('83fcba23a08d4ae69309f35b0c8b8072', '汪子明', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_衢州；安徽黄山黟县；安徽黄山祁门', '[]', '[]', '抗日战争时期', '', '投靠日军后任伪警察局长，协助日军搜捕抗日分子，镇压民众反抗，勒索商贩。；汪伪政权委任的黟县县长，在黟县推行保甲制度，配合日军清乡。；祁门本地士绅，日军侵入皖南后出面组织维持会，为日军筹粮、带路、招募民夫，协助维持沦陷区秩序，是祁门县伪政权初期代表人物。', '[]', '2026-09-10 09:57:14.011498', '2026-09-10 09:57:14.011498', '安徽', '黄山', '祁门', NULL, NULL, NULL, NULL, '');
