INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('84e74870302c4a9ea2de9c4d39409f89', '杨祖诒', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶；江西上饶玉山；江西上饶', '[]', '[]', '抗日战争时期', '', '江西上饶人，上饶沦陷期间任伪建设科长，配合日军修建军事设施、掠夺当地资源。；1942年浙赣会战日军攻陷上饶期间，组织伪维持会，协助日军搜刮物资、登记户口、诱迫民众返城。；上饶沦陷期间受日军指使筹组伪维持会，负责摊派捐款、物资和民夫，配合日军对赣东北地区的控制。', '[]', '2026-09-10 09:57:14.037411', '2026-09-10 09:57:14.037411', '江西', '上饶', '玉山', NULL, NULL, NULL, NULL, '');
