INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('84f072fcb44d490689b8331a72d833c0', '马金良', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；山西阳泉城区；河南郑州巩义；河南郑州；河南南阳；河南开封兰考；河南开封', '[]', '[]', '抗日战争时期', '', '在开封县组织维持会，为日军筹粮筹款，协助建立伪基层政权。；组织伪保安团，配合日军守备南阳，参与对抗日游击队的围剿。；在伪南阳县政权下掌管警察，搜捕抗日人员，镇压民众反抗，为日军维持治安。；1945年日军占领南阳后，出任伪警察局局长，负责城区治安，抓捕抗日嫌疑人员。；郑州沦陷期间任伪商会会长，为日军筹措军需物资，协助日军对郑州工商业的控制和掠夺。', '[]', '2026-09-10 09:57:14.046617', '2026-09-10 09:57:14.046617', '河南', '南阳', '兰考', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('84f2043a5af6463395cf84b93a6bc316', '周绍武', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁；四川遂宁安居', '[]', '[]', '抗日战争时期', '', '在安居镇组织维持会，为日军带路、征粮，迫害抗日家属。', '[]', '2026-09-10 09:57:14.064472', '2026-09-10 09:57:14.064472', '重庆', '铜梁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('84f867470f0c4acf87050c25a54e43e5', '王兆麟', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；广西桂林资源；福建厦门同安；福建厦门；福建漳州华安；福建泉州；福建漳州；福建泉州南安；福建泉州；福建漳州南靖；福建漳州；福建泉州石狮；福建泉州', '[]', '[]', '抗日战争时期', '', '在闽南沿海一带收编土匪、组织伪军，配合日军对漳州、泉州沿海进行骚扰和扫荡。；在闽南沿海收编土匪，组织伪军，配合日军在漳州、诏安一带进行骚扰与破坏，后因内部矛盾被日军处决。；抗战期间投敌，在福建日占区任职，参与伪政权对闽南沿海地区的统治和资源掠夺。；1938年日军进犯漳州沿海时，出面组织维持会筹备活动，为日军登陆提供情报和物资，后因日军撤退而未正式成立。；推行奴化教育，在厦门及同安等地学校强制日语教学、篡改历史教材。；晋江（今泉州辖区）沦陷期间组织维持会，协助日军征粮征夫。；在伪厦门特别市机构任职，协助日军进行地方行政与宣传。；在晋江（今泉州辖区）组织维持会，为日军登陆泉州沿海提供向导与补给，迫害抗日群众。', '[]', '2026-09-10 09:57:14.060893', '2026-09-10 09:57:14.060893', '福建', '厦门', '同安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('84fa18cec3154c3a8398f273074a59f1', '寇永和', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山靖宇', '[]', '[]', '抗日战争时期', '', '在濛江（今靖宇）地区积极推行日伪“保甲连坐”制度，组织伪警察配合日军“大讨伐”，多次抓捕抗联地下工作者和爱国群众，是当地有名的汉奸头目。', '[]', '2026-09-10 09:57:14.000052', '2026-09-10 09:57:14.000052', '吉林', '白山', '靖宇', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8505bf1554924fb59fdf942293ff6f57', '杨高伯', NULL, NULL, NULL, NULL, 'exact', 'exact', '无锡；无锡县城', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：维持会委员，第二任伪无锡县长，对日态度强硬，残酷对待抗日人员。。结局：1940 年被抗日锄奸人员刺杀；日军为此闭城大搜捕一周；伪职：第一任伪无锡县县长；罪行：首任伪县长，全面执行日伪政令，压榨民众，迫害抗日力量无锡市档案...。；结局：1938 年被抗日游击队潜入城内处决，日军为此全城大搜捕。', '[]', '2026-09-10 09:57:14.071213', '2026-09-10 09:57:14.071213', '江苏', '无锡', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('850f8afa699a40878e78068397a2e870', '于占鳌', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西滴道', '[]', '[]', '抗日战争时期', '', '组织地方自卫团协助日军扫荡，在滴道周边村庄烧杀抢掠，曾一次抓捕12名疑似抗联联络员的农民，全部移交日军处死。', '[]', '2026-09-10 09:57:14.066649', '2026-09-10 09:57:14.066649', '黑龙江', '鸡西', '滴道', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8510e505a49f42c2a0bf386b208b7f37', '熊文辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西_南昌；江西南昌；江西上饶信州；江西南昌；江西南昌新建；山西阳泉城区；江西南昌；江西抚州临川；江西抚州', '[]', '[]', '抗日战争时期', '', '南昌沦陷后出面组织伪南昌市维持会，为日军筹粮筹款、维持城区秩序，协助日军搜捕抗日人员。；南昌沦陷后受日军指使筹组伪南昌市维持会，协助日军安民、征发物资、诱迫商民复业以粉饰占领。；统率伪警察配合日军搜捕抗日人员，清查户口，勒索市民，镇压地下抵抗活动。；收编地方土匪与散兵组成伪军，配合日军扫荡抚州周边乡村，袭击抗日游击队。；日军占领南昌期间出任伪南昌市市长，协助日军推行保甲、配给与宣传，镇压抗日活动。；在南昌沦陷期间出任伪南昌市市长，配合日军实施经济统制、物资配给，参与奴化教育宣传，维护日伪统治秩序。；南昌沦陷后出任伪南昌市市长，协助日军推行保甲制度、配给制度，镇压抗日活动。；江西伪政权高层之一，参与制定沦陷区统治政策，其活动范围覆盖南昌、上饶等赣东北地区。', '[]', '2026-09-10 09:57:14.037799', '2026-09-10 09:57:14.037799', '江西', '上饶', '信州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8513027d6a4243a994fe236bda739ba7', '方茂山', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆潜山；安徽安庆；安徽安庆安庆经开区；安徽安庆；安徽安庆宜秀；安徽安庆；安徽安庆怀宁；山西阳泉城区；安徽安庆岳西；安徽安庆；安徽安庆望江；安徽安庆宿松；安徽安庆；安徽安庆桐城', '[]', '[]', '抗日战争时期', '', '桐城沦陷期间组织伪维持会，为日军筹粮筹款，维持地方伪秩序，协助日军控制桐城地区。；原地方武装头目，投敌后任伪军团长，盘踞安庆周边，配合日军清乡，残害百姓。；在安庆周边收编土匪、游杂武装组成伪保安队，配合日军扫荡抗日根据地，活动范围涉及怀宁、桐城、宿松一带。；望江沦陷期间出面组织伪维持会，为日军征粮征夫、搜集情报，协助日军控制望江地区。；安庆沦陷初期出面组织伪安庆维持会，协助日军维持城区秩序、征发物资、登记户口，是安庆城区早期汉奸组织负责人之一。；率部投敌，任伪安庆自卫团团长，在安庆及宜秀周边地区为日军效力，搜捕抗日人员。；桐城沦陷期间任伪县长，在桐城、安庆一带配合日军行动，推行保甲连坐，镇压抗日群众。；安庆沦陷后依附日伪，控制安庆商会，为日军筹款筹粮，协助经济掠夺。', '[]', '2026-09-10 09:57:14.007398', '2026-09-10 09:57:14.007398', '安徽', '安庆', '安庆经开区', NULL, NULL, NULL, NULL, '');
