INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('853df4d783f64e2caa6e490bf829249c', '朱伯华', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏淮安清江浦', '[]', '[]', '抗日战争时期', '', '充当日军特务，刺探抗日情报，抓捕并酷刑审讯抗日志士。', '[]', '2026-09-10 09:57:14.036288', '2026-09-10 09:57:14.036288', '江苏', '淮安', '清江浦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85478cce1e6f4e1298621ac895b53f83', '傅胜蓝', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；江苏南京；安徽芜湖镜湖；湖南株洲渌口；上海静安；湖南郴州桂东；安徽芜湖芜湖经开区；四川南充南部；湖南长沙开福；江苏南京；江苏南京浦口；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '镇压南京市民抗议活动；在南京负责反间谍，严刑拷打抗日嫌疑犯。；虐待关押的抗日志士，克扣囚粮，导致多人病死狱中。；长沙沦陷后任伪警察局长，协助日军维持城区治安、搜捕抗日人员、管理户籍与物资配给。；湖南人，汪伪特务骨干，在沦陷区进行特务活动，涉及湖南部分区域情报网络。；湖南人，汪伪特工骨干，在南京及华中地区从事特务活动，其活动范围覆盖湖南部分沦陷区，与长沙有间接关联。；湖南籍相关人物常被提及，汪伪特工系统骨干，在浙江地区从事特务活动。；虐待囚犯。；被日方列入伪湖南省政府名单，但未实际赴任，历史记载有限。；诱骗青年加入伪组织，进行军事训练，充当日军炮灰，破坏学生运动。；在静安地区强占民房土地，为日军修建军事设施，迫害原住民。', '[]', '2026-09-10 09:57:13.979741', '2026-09-10 09:57:13.979741', '安徽', '芜湖', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85481457f78e4b8a9f96586546d224df', '王继美', NULL, NULL, NULL, NULL, 'exact', 'exact', '峄县（税郭）；山东枣庄；山西阳泉矿区；山东枣庄市中；山东枣庄', '[]', '[]', '抗日战争时期', '', '伪职：税郭乡伪乡长；罪行：兼任税郭乡伪乡长，驻防税郭，成为日军枣庄据点东部的屏障。1942年7月与当地汉奸、伪乡长联手为日军立“功德碑”；结局：见上；伪职：伪宪兵队特务大队队长→峄东剿共司令→国民党32纵队司令；罪行：枣庄一带最知名的大汉奸。1919年生，郭里集前小湾人。1941年1月带全排28人携枪投降日军，被编入杨贵岭部，任峄县第三警备大队第三中队长兼税郭乡伪乡长。后任伪宪兵队特务大队队长、“峄东剿共司令”。残害抗日干部、战士及无辜百姓数百人。1944年制造“官地惨案”，偷袭鲁南军区警九旅十七团，致70余人牺牲、70余人被捕。日本投降后拒绝向八路军缴械，被国民党收编为“山东挺进军三十二纵队少将司令”。1946年6月枣庄首次解放时被击毙；结局：1946年6月9日在枣庄被山东野战军击毙', '[]', '2026-09-10 09:57:14.014471', '2026-09-10 09:57:14.014471', '山东', '枣庄', '山亭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('854ae5e79ddb40f59fab71cae33c01ea', '陈良烈', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州；广东云浮郁南；广东_广州_黄埔', '[]', '[]', '抗日战争时期', '', '负责伪广东宣传事务，为日军进行舆论欺骗和奴化宣传。；汪伪广东教育官员，推行奴化教育，篡改教材，向学生灌输亲日思想。；汪伪政权在广东的文化宣传附逆者，负责伪宣传与广播，进行亲日媚日宣传。', '[]', '2026-09-10 09:57:14.025472', '2026-09-10 09:57:14.025472', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
