INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8591fafcb7a04d479a6dc0a9d3100283', '陈孝强', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东_揭阳_揭东；广东广州；广东江门江海；广东江门；广东梅州大埔；广东梅州；广东广州增城', '[]', '[]', '抗日战争时期', '', '负责联络梅州、大埔地方伪维持会，推行保甲连坐，协助日军掠夺钨矿等战略物资。；广东伪军系统人物，协助日军维持沦陷区治安，活动涉及江门地区。；广东人，投敌后任伪军师长，活动于惠州、增城、龙门一带，协助日军维持占领区治安，参与对东江抗日根据地的清乡扫荡。；广东伪军头目之一，活动于广州及附近地区，协助日军维持占领区。；负责潮汕地区伪警备，协助日军维持治安、镇压抗日力量。', '[]', '2026-09-10 09:57:14.026934', '2026-09-10 09:57:14.026934', '广东', '梅州', '大埔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('859375485aff41a68026eadce84abd50', '王靖国', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾隰县；山西晋中左权；山西太原阳曲；山西忻州五台；山西；山西忻州；云南普洱西；山西晋中；山西临汾吉县；山西吕梁；山西忻州岢岚；山西忻州；山西临汾霍州；山西临汾', '[]', '[]', '抗日战争时期', '', '在吉县、蒲县等地组织伪保安团，协助日军镇压民众反抗，参与“三光”政策下的破坏行动。；原阎锡山部将领，后投靠日军，在汾西、临汾一带组建伪军，参与对抗日根据地的进攻，杀害抗日军民。；原阎锡山部将领，后投靠日军，在晋西地区参与围剿八路军和抗日游击队，制造多起惨案。；原阎锡山部军长，投日后任伪军总司令，在临汾地区驻防，参与“扫荡”太岳根据地。；在交口、隰县一带活动，与日军达成局部停战协议，默许日军通过其防区进攻八路军，并向日军提供情报。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018792', '2026-09-10 09:57:14.018792', '山西', '临汾', '吉县', NULL, NULL, NULL, NULL, '');
