INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85c839121e814676852ab06327749e68', '王光临', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店驿城；河南驻马店；河南驻马店新蔡；河南驻马店；河南_信阳_淮滨；河南驻马店上蔡；河南驻马店；河南驻马店驻马店经开区；河南驻马店遂平；河南漯河临颍；辽宁沈阳大东；河南信阳；河南许昌；河南许昌鄢陵；河南许昌长葛；河南驻马店遂平；河南驻马店西平；河南信阳光山；河南信阳；河南驻马店汝南；河南驻马店；河南驻马店正阳；河南驻马店汝南', '[]', '[]', '抗日战争时期', '', '掌管伪警察力量，协助日军搜捕抗日人员，维持日伪统治秩序，参与对信阳周边乡村的扫荡与情报搜集。；长葛沦陷后出面维持，为日军征发民夫、粮食，协助日军控制平汉铁路沿线。；驻马店沦陷后组织维持会，协助日军管理车站、物资与地方治安，为日军提供情报与后勤支持。；在遂平县城组织伪维持会，配合日军维持地方统治，征派粮款，其活动区域与汝南同属驻马店地区。；驻马店商会头目，日军占领期间协助日军统制物资、征购军粮，为日军经济掠夺服务，属经济领域附逆者。；任伪汝南县县长，汝南与正阳接壤，其伪政权参与日军对豫南地区的统治，推行保甲连坐，镇压抗日活动。；任伪豫南道尹期间管辖信阳、光山等县伪政权，推行奴化教育，组织伪保安队配合日军扫荡，搜刮民财供给日军。；遂平沦陷后投敌，组织维持会并出任伪县长，为日军征发物资、修筑据点，镇压地方抗日力量。；西平与遂平相邻，任维持会会长，协助日军控制平汉铁路沿线，征发物资与劳工。；率伪军在驻马店、确山、遂平一带配合日军清乡，袭击抗日武装，残害抗日军民。；掌控伪警察力量，搜捕抗日人员及嫌疑民众，协助日军维持占领区治安，参与破坏中共地下组织和抗日群众团体。；在日军占领许昌期间，担任伪警察头目，配合日军搜捕抗日人员，镇压地方抗日活动。；在伪河南省政府中负责宣传事务，为日军殖民统治进行文化宣传和奴化教育，鼓吹“中日亲善”“大东亚共荣”，是河南文化教育领域附逆的代表人物。', '[]', '2026-09-10 09:57:14.046204', '2026-09-10 09:57:14.046204', '河南', '信阳', '光山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85c8511090cc4528b6ac346eb5d8c5b8', '肖德贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '长沙', '[]', '[]', '抗日战争时期', '', '伪职：汉奸赌徒；罪行：湖北籍汉奸赌徒。在长沙为祸。；结局：被伪市长唐令欧捕获，并枪毙于南门口。', '[]', '2026-09-10 09:57:14.084061', '2026-09-10 09:57:14.084061', '湖北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85cfb98d8ca94dfd848328648c67c848', '王明斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊临朐；山东烟台蓬莱；河南平顶山湛河；河南平顶山；山东潍坊；辽宁沈阳新民；山东烟台烟台经开区；山东威海', '[]', '[]', '抗日战争时期', '', '在威海卫地区组织维持会，协助日军统治，征发物资。；在宝丰县及邻近平顶山地区组织维持会，为日军筹集物资、情报，协助日军控制地方。；组织新民会，进行反共宣传，配合日军进行思想控制，拉拢腐蚀抗日意志薄弱者。；在日军扶植下出任伪蓬莱县知事，推行伪化教育、征发物资，配合日军对蓬莱抗日根据地进行经济封锁和扫荡。；任伪潍县保甲长，协助日军征粮、抓丁，监视民众，迫害抗日人员。', '[]', '2026-09-10 09:57:14.016589', '2026-09-10 09:57:14.016589', '山东', '潍坊', '临朐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85d024db29114d80a5e0267c824fa707', '韩维屏', NULL, NULL, NULL, NULL, 'exact', 'exact', '陵川万章村', '[]', '[]', '抗日战争时期', '', '伪职：原国民党二区区长，日伪咨议员；罪行：被峰头据点抓捕随即叛变；出卖万章村民兵情报，直接酿成万章惨案，多名民兵牺牲。；结局：万章村公审就地枪决', '[]', '2026-09-10 09:57:14.077386', '2026-09-10 09:57:14.077386', '山西', '晋城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85dc504c45d2426d97b56e30bc88b4df', '梁鸿楷', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山；广东肇庆；广东韶关新丰；广东韶关；广东江门新会；广东江门；广西柳州鹿寨；四川南充南部；广西柳州城中；广西柳州；广东广州越秀；广东广州；广东江门鹤山；河南鹤壁鹤山', '[]', '[]', '抗日战争时期', '', '广州沦陷初期附逆，参与组织伪治安维持会，收编散兵游勇为日军所用。；广东籍附逆者，参与伪民众组织，在江门、新会等地协助日军宣传与动员。；广东地区伪维持会头目，配合日军在华南维持治安，其活动区域与广西东南部邻近，属华南伪政权附逆者。；广东人，日军侵占广州后出面组织伪维持会，协助日军维持治安、征发物资，其势力范围涉及珠江三角洲包括江门、鹤山周边。；广东人，抗战期间投敌，任伪广东绥靖军第一师师长，在佛山、南海、顺德一带配合日军扫荡抗日游击队。；统辖广东伪军，配合日军在包括肇庆、德庆在内的西江地区进行扫荡和治安强化运动。；汪伪政权在广东的军事头目之一，统率伪军配合日军在广东各地包括韶关周边进行扫荡和清乡。；广东伪政权头目之一，其维持会体系与广西梧州、柳州等地伪维持会有横向联系，间接影响柳州地区。', '[]', '2026-09-10 09:57:14.026583', '2026-09-10 09:57:14.026583', '广东', '广州', '越秀', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85e167853f174a7183a2fa187bdab690', '刘峙', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮北濉溪；安徽亳州涡阳；安徽淮北；江西吉安泰和；辽宁沈阳大东；江西吉安吉州；甘肃甘南合作；安徽淮北；安徽淮北烈山；江西吉安井冈山；江西吉安永新', '[\"误记，实为刘瑞岐\", \"非本人，疑为误记，此处按历史资料列“刘子举”\", \"误，应为刘启雄\", \"误记，实为刘子良\", \"附逆传闻\"]', '[]', '抗日战争时期', '', '部分野史称其在江西沦陷区与日伪合作，但正史无明确记载，仅列备考。；刘子良，安徽涡阳人，投日后任伪安徽省长，在淮北地区推行保甲制度，强征粮税，镇压抗日活动。；烈山本地劣绅，日军占领烈山后出任维持会长，为日军提供矿工名单，抓捕抗日嫌疑分子，克扣矿工口粮中饱私囊。；在宿县（今属淮北市）任伪县长，强征粮食，出卖抗日志士，协助日军建立维持会。；任伪濉溪县知事期间，推行保甲制度，向日军提供抗日分子情报，强征粮食，迫害抗日家属。；在吉安地区推行奴化教育，协助日军宣传“大东亚共荣圈”，毒害青年学生，为日伪统治培养顺民。；永新沦陷期间组织维持会，为日军服务，协助征粮征夫，维持日伪地方统治。', '[]', '2026-09-10 09:57:14.008664', '2026-09-10 09:57:14.008664', '安徽', '淮北', '濉溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85e41af98dde42edb58305f41b596fe6', '霍老贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '新河', '[]', '[]', '抗日战争时期', '', '伪职：伪新河警备大队长；下乡抢掠，抓捕抗日干部。；结局：新河解放被俘枪决', '[]', '2026-09-10 09:57:14.080562', '2026-09-10 09:57:14.080562', '河北', '邢台', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('85e5a3567a0e45bc8bc4209700894622', '夏文运', NULL, NULL, NULL, NULL, 'exact', 'exact', '台儿庄', '[]', '[]', '抗日战争时期', '', '伪职：日军翻译官（潜伏人员）；罪行：台儿庄战役时为日军翻译官，表面是“汉奸”，实际系李宗仁安插的情报员。在台儿庄战役关键时刻送出“日军北动南不动”八字密报，助中国军队取得大捷；结局：抗战胜利后恢复身份（非汉奸，系潜伏人员）', '[]', '2026-09-10 09:57:14.069286', '2026-09-10 09:57:14.069286', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
