INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('861fa7c530914567b9af983eb6336baa', '黄道', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶德兴；江西上饶横峰；江西上饶广信；江西上饶弋阳；江西上饶广丰；江苏徐州丰县', '[]', '[]', '抗日战争时期', '', '经核查，黄道为中共闽浙赣省委领导人，非汉奸，故不列入。；此处不列入汉奸；浙赣会战期间日军侵占广丰后，出面组织伪广丰县维持会，为日军征派粮秣、拉夫，维持占领区秩序。；黄道为中共闽浙赣根据地领导人之一，并非汉奸；此处列出仅为提示德兴地区相关人物易混淆，不应归入汉奸名录。；抗战后期在弋阳县城组织维持会，为日军征粮派夫，协助日伪政权维持地方秩序。', '[]', '2026-09-10 09:57:14.037874', '2026-09-10 09:57:14.037874', '江西', '上饶', '广丰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('862412f9abfb4874b1ef2b2f493d2556', '黄公柱', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林荔浦；广西桂林；广西柳州；湖南常德常德西洞庭管理；湖南常德；湖南常德桃源；湖南常德；广西桂林；云南普洱西；广西桂林秀峰；广西桂林；湖南益阳益阳高；湖南益阳；湖南常德石门；广西桂林灌阳；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '常德会战期间，日军占领常德后组织维持会，协助日军维持治安、征发民夫、搜刮物资。；日军占领柳州后，出任伪警察局长，协助日军维持治安，抓捕抗日分子。；湖南人，在汪伪湖南省政府中任职，参与推行伪化教育、经济掠夺政策，其影响覆盖常德地区。；率部投敌，改编为伪保安部队，配合日军扫荡广西抗日游击区。；石门沦陷前后，地方维持会人员协助日军征粮、拉夫、维持治安，具体姓名与事迹在《石门县志》等地方史料中有零星记载。；桂林沦陷后出面组织伪商会，为日军筹款筹粮，协助日伪控制桂林经济，压迫商户。；益阳沦陷期间出面组织维持会，协助日军征粮、派夫、维持地方秩序，为日军在益阳地区的统治提供基层支持。；1944年日军攻陷桂林后，出面组织伪桂林市维持会，协助日军搜捕抗日人士、征发粮食民夫，维持日占区秩序。；桂林沦陷期间，任伪警察局长，配合日军搜捕抗日人员。；桂林沦陷期间主办伪报，为日军宣传“大东亚共荣圈”，进行文化附逆。', '[]', '2026-09-10 09:57:14.031657', '2026-09-10 09:57:14.031657', '广西', '桂林', '灌阳', NULL, NULL, NULL, NULL, '');
