INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86b0cf9766594358b4c1f240562d4400', '贵福', NULL, NULL, NULL, NULL, 'exact', 'exact', '达斡尔族', '[]', '[]', '抗日战争时期', '', '伪职：伪满参议府参议；九一八后参与伪满 “建国” 活动，支持其子凌升出任伪兴安北省省长；凌升事件之后被日本软禁。；结局：1941 抑郁病死长春抖音百科', '[]', '2026-09-10 09:57:14.082611', '2026-09-10 09:57:14.082611', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86c945d2d0934ae49873a061dd2db746', '吴朗之', NULL, NULL, NULL, NULL, 'exact', 'exact', '宿城', '[]', '[]', '抗日战争时期', '', '伪职：伪宿迁县商会副会长；罪行：协助胡杰生管控商业，借伪合作社敛财，搜刮金银物资供应日伪，迫害爱国工商业者中共宿迁市...。；结局：汉奸清算判刑。', '[]', '2026-09-10 09:57:14.070988', '2026-09-10 09:57:14.070988', '江苏', '宿迁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86c9ebfa18a541ad9a366c8e9a91c9a4', '王绪高', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '湖南常德津；辽宁；河北唐山乐亭；河北唐山；河北廊坊；天津蓟州；天津、河北；湖南常德津；天津_西青；天津_静海；天津南开；天津_滨海；天津北辰；天津_河西；天津红桥', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪天津特别市市长（1943）。结局：抗战胜利被捕，判处徒刑，狱中病逝；在廊坊东部（三河、大厂）指挥伪军多次袭击八路军小分队。；作为伪天津县行政长官，管辖北辰一带，强征粮税，协助日军建立保甲制度。；利用司法权力迫害抗日人士，判处多名南开区地下党员及爱国师生重刑，为日军“军法会审”提供法律掩护。；掌管伪天津警察机构，配合日军搜捕抗日地下人员，破坏抗日组织，实施白色恐怖统治。；任伪天津警察局长，协助日军搜捕抗日分子，镇压民众反抗，参与制造多起血腥事件。；推行奴化教育，强制学校教授日语和“中日亲善”课程，压制抗日思想传播。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.002660', '2026-09-10 09:57:14.002660', '天津', '北辰', '乐亭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86ccb1596bb947b4bef129f243e1dc58', '江国璋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西景德镇浮梁；江西景德镇', '[]', '[]', '抗日战争时期', '', '在景德镇地区参与组织伪维持会，协助日军控制瓷业生产与运输，为日军筹集物资。', '[]', '2026-09-10 09:57:14.040244', '2026-09-10 09:57:14.040244', '江西', '景德镇', '浮梁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86d863ee0f5648738d908ac75c427cb5', '杨怀英', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西吕梁兴县；山西吕梁临县', '[]', '[]', '抗日战争时期', '', '在临县担任伪保甲长，监视村民行动，向日军报告抗日人员行踪，导致多名抗日群众被捕。', '[]', '2026-09-10 09:57:14.020111', '2026-09-10 09:57:14.020111', '山西', '吕梁', '兴县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('86d930bfd3c344a08e9e93664830fede', '李维业', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯康巴什；内蒙古鄂尔多斯；天津河北；内蒙古包头；内蒙古_锡林郭勒_锡林浩特；陕西西安长安；云南普洱西；内蒙古鄂尔多斯伊金霍洛旗；内蒙古鄂尔多斯；内蒙古呼和浩特', '[]', '[]', '抗日战争时期', '', '在东胜县（今鄂尔多斯市东胜区）组织维持会，为日军征粮征夫，协助日军控制鄂尔多斯中部地区。；在包头及周边旗县建立伪警察网络，搜捕抗日人员，协助日军维持殖民统治。；在固阳地区组织维持会，为日军服务，其活动区域与鄂尔多斯北部抗日根据地相邻，参与封锁与情报搜集。；在山西沦陷区任伪职，配合日军统治，其活动区域与陕西东部邻近。；河北人，抗战期间投靠日军，组织伪军，在华北地区进行伪化统治。；在日军占领包头期间，受命筹建伪宁夏警察机构，在银川、贺兰等地招募伪警，镇压抗日分子，推行保甲连坐。；绥远人，曾任伪厚和浩特（今呼和浩特）市市长，后任伪乌兰察布盟公署参事，参与伪政权对乌兰察布地区的管理。；李守信部伪蒙古军将领，率部驻防察哈尔、锡林郭勒一带，配合日军围剿抗日武装。；在伪蒙古军中任职，率部驻防绥远地区，参与对呼和浩特周边及和林格尔等地的控制与扫荡，配合日军维持伪蒙疆政权统治。；在固阳地区投靠日伪，担任伪县长，配合日军在绥西及鄂尔多斯北部进行统治和扫荡。', '[]', '2026-09-10 09:57:13.987388', '2026-09-10 09:57:13.987388', '内蒙古', '鄂尔多斯', '伊金霍洛旗', NULL, NULL, NULL, NULL, '');
