INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8750ef5e9e9b4d4d9b16d9e2ea2a420d', '周志远', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_衢州_衢江；浙江_金华_武义；浙江_丽水；浙江湖州长兴', '[]', '[]', '抗日战争时期', '', '为日军征收苛捐杂税，强征物资，导致当地民生凋敝。；指挥伪警察搜捕抗日地下人员，破坏抗日组织，参与对民众的勒索。；推行奴化教育，在全县中小学强制教授日语和“中日亲善”课程，删改历史教材，迫害爱国教师。；为日伪政权征收各种苛捐杂税，横征暴敛，搜刮民财，供应日军军需。', '[]', '2026-09-10 09:57:14.049229', '2026-09-10 09:57:14.049229', '浙江', '湖州', '长兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('875670138c86483aac74300f0f0198bf', '赵子云', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮北濉溪；河南洛阳；湖南常德桃源；山东德州德城；安徽宿州泗县；安徽宿州灵璧；重庆丰都；河南信阳淮滨；湖北襄阳；安徽宿州埇桥；安徽宿州；河南信阳浉河；辽宁沈阳大东；安徽宿州宿州马鞍山现代产业园；安徽宿州；河北衡水武邑；河北衡水；安徽亳州蒙城；安徽亳州涡阳；安徽安庆大观；河南三门峡义马；河南洛阳宜阳；安徽亳州；湖北十堰竹山；湖北宜昌；湖北宜昌枝江；重庆涪陵；山东菏泽定陶；山东菏泽；湖北鄂州；湖北鄂州鄂城；重庆铜梁；安徽宿州；安徽宿州泗县；河北邢台', '[]', '[]', '抗日战争时期', '', '统率伪军配合日军对邢台、柏乡一带进行扫荡，烧杀抢掠，破坏抗日根据地。；单县沦陷后投敌，任伪单县县知事，在菏泽南部地区协助日军建立伪政权，征粮征夫，配合扫荡。；宜阳沦陷后组织伪维持会，协助日军统治，迫害抗日群众。；湖北竹山人，抗战期间投敌，任伪竹山警察局局长，协助日军管理竹山，镇压抗日武装。；担任伪保长期间，强征壮丁、粮食，监视村民，向日军告密抗日分子。；指挥伪警察搜捕地下党员，破坏抗日交通站，参与制造“濉溪惨案”，杀害无辜群众数十人。；担任常德城区保甲长，为日军清查户口、举报抗日分子，协助日军征发劳工。；协助伪政权登记户口、征收捐税，举报抗日分子及家属。；在衡水地区协助日军维持治安，参与清乡、抢粮，迫害抗日人员。；泗县沦陷后组织维持会，为日军筹集物资、招募伪军。；泗县地区伪维持会负责人，协助日军维持占领区秩序，参与经济掠夺。；宿州萧县地区伪政权头目，配合日军清乡、扫荡，镇压抗日群众，为日军提供情报与物资。；负责为日军强征粮食，导致大观区民众饥荒。；在枝江统率伪保安队，配合日军控制长江航运。；控制鄂城商业，为日军采购军需物资，协助经济统制，压榨商户。；日军侵占息县期间附逆出任伪县长，管辖范围涉及今淮滨部分地区，推行伪化教育、征粮征夫，配合日军统治。；在灵璧伪政权任职，执行日伪经济统制，强征粮食棉花，迫害抗日家属。；宿州地区伪军头目，率部配合日军扫荡抗日根据地，征粮派款，欺压百姓。；在信阳推行奴化教育，改编教材宣扬“大东亚共荣”，组织教师参加亲日培训，毒化沦陷区青少年。；在襄阳基层推行保甲制度，为日军摊派捐税、清查户口。；在基层推行保甲制度，监视居民言行，向日军举报抗日人员。；亳县本地武装头目，投靠日军后任伪保安团长，配合日军扫荡涡河沿岸抗日武装，残害百姓。；汪伪政权任命的亳县伪知事，在亳县推行伪化行政，配合日军征粮、拉夫，参与对涡阳、蒙城一带抗日力量的清剿。；在洛阳周边收编土匪、溃兵，组织伪军配合日军扫荡豫西抗日根据地。', '[]', '2026-09-10 09:57:14.004328', '2026-09-10 09:57:14.004328', '安徽', '亳州', '蒙城', NULL, NULL, NULL, NULL, '');
