INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8800d5735a1f4e6c894bdaeb77a26c5e', '张守业', NULL, NULL, NULL, NULL, 'exact', 'exact', '乌衣（津浦铁路重镇）；阳高；内蒙古呼和浩特和林格尔；茄子河矿区', '[]', '[]', '抗日战争时期', '', '伪职：乌衣镇伪维持会长；罪行：乌衣头号汉奸，迎接日军进驻，办理良民证，征夫征粮，充当向导，配合铁路沿线扫荡。；结局：抗战胜利后判处死刑。；伪职：伪阳高讨伐队队长；罪行：祸害阳高、天镇一带，抓捕抗日干部，敲诈百姓。；结局：1945 年被民兵击毙；伪职：伪茄子河煤矿劳务系把头、特务；罪行：为日军骗招劳工，监视矿工，检举有反日倾向工人，配合日军镇压矿工反抗。；结局：解放后管制改造。', '[]', '2026-09-10 09:57:13.989774', '2026-09-10 09:57:13.989774', '内蒙古', '呼和浩特', '和林格尔', NULL, NULL, NULL, NULL, '');
