INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8837470c02744a7685067f162de081c2', '韩鹏九', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东青岛李沧；山东青岛；山东_青岛_城阳；山东青岛黄岛；山东青岛崂山', '[]', '[]', '抗日战争时期', '', '在青岛伪警察系统中任职，参与搜捕抗日志士，维持日伪统治秩序。；为日军筹款征粮，在崂山地区征收苛捐杂税，支持伪政权运转。；掌控伪警察系统，配合日军搜捕抗日人员，实施保甲连坐。；作为经济界附逆者，为日军筹措物资，配合经济掠夺。', '[]', '2026-09-10 09:57:14.018286', '2026-09-10 09:57:14.018286', '山东', '青岛', '李沧', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('883b1797868e402ab22fe7463ca4e626', '袁庆濂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁营口西市；辽宁营口；辽宁锦州；辽宁丹东；黑龙江齐齐哈尔；黑龙江哈尔滨；黑龙江鸡西城子河；吉林、辽宁；黑龙江哈尔滨双城；黑龙江哈尔滨；黑龙江哈尔滨平房；黑龙江哈尔滨；辽宁丹东东港；广西桂林资源；辽宁营口；辽宁本溪；辽宁葫芦岛；辽宁锦州；吉林龙潭', '[]', '[]', '抗日战争时期', '', '原吉林警察厅官员，投日后任伪省警务厅长，在龙潭区设立多个警察分所，残酷镇压抗日群众。；在东港地区强占土地，掠夺矿产和农产品，为日军提供战争物资。；直接指挥本溪地区伪警察，搜捕地下党员和抗联交通员，参与“集团部落”建设，迫害百姓。；充当日本经济侵略代理人，强制商户为日军提供物资，协助日伪掠夺营口港资源，迫害爱国商人。；在营口西市地区为日军筹集军饷，强迫商户捐献物资，向日伪当局举报抗日商人，协助经济统制。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.001052', '2026-09-10 09:57:14.001052', '辽宁', '本溪', '资源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('883d491dedbb4bd1a14b27fe647abce7', '伪星子县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城', '[]', '[]', '抗日战争时期', '', '星子县邻近共青城地区，沦陷后组织伪维持会，配合日军控制鄱阳湖西岸交通与乡村。', '[]', '2026-09-10 09:57:14.038206', '2026-09-10 09:57:14.038206', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
