INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('88ac13ab5fc047e881e25d6ea30afdfe', '方礼高', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀宁石牌周边', '[]', '[]', '抗日战争时期', '', '伪职：怀宁地方劣绅、伪乡情报联络员；罪行：暗地为日伪搜集游击武装情报，通风报信，勾结敌伪势力欺压乡里，阻挠根据地开展工作。；结局：游击区公判大会宣布九大罪状，就地处决中安在线。', '[]', '2026-09-10 09:57:14.077288', '2026-09-10 09:57:14.077288', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('88acca375efa4a8990d2ca7d7e89c3b6', '刘文清', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯郊区；黑龙江佳木斯；黑龙江双鸭山友谊；黑龙江鹤岗萝北；黑龙江鹤岗；黑龙江鸡西鸡冠；黑龙江鸡西；黑龙江佳木斯抚远；黑龙江齐齐哈尔', '[]', '[]', '抗日战争时期', '', '汤原县与佳木斯郊区接壤，任伪县长期间配合日军对汤原、佳木斯一带抗日游击区进行经济封锁和军事扫荡。；九一八事变后组织鹤岗街维持会，迎接日军占领，协助日军筹粮、征夫，维持地方秩序，为伪政权建立铺路。；伪鸡宁县（今鸡西）县长，执行日伪统治政策，推行保甲连坐，征劳工、征粮，配合日军围剿抗日武装。；在友谊地区任伪协和会会长，进行亲日宣传，协助日伪政权控制民众思想。；同江县邻近抚远，任伪县长期间推行日伪政令，协助日军控制黑龙江沿岸。', '[]', '2026-09-10 09:57:14.065545', '2026-09-10 09:57:14.065545', '黑龙江', '佳木斯', '抚远', NULL, NULL, NULL, NULL, '');
