INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('88ec05534edd4e66a44e033a1fff51f5', '张璧', NULL, NULL, NULL, NULL, 'exact', 'exact', '北京东城；陕西_西安_长安；北京西城；北京石景山；北京门头沟；河北；北京延庆；河北廊坊固安；天津河北；天津北辰；湖南常德津；北京海淀；云南普洱西；北京、天津；四川_广元；北京大兴；北京昌平；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '', '曾任伪华北治安军高级将领，参与指挥伪军在北平东城及周边地区镇压抗日力量。；七七事变后率先组织北平地方维持会，迎接日军进城，协助维持治安，后因权力斗争失势，但前期对大兴地区伪政权建立有直接影响。；七七事变后率先组织维持会，迎接日军入城，协助建立伪政权，为日军征粮派款。；七七事变后率先投敌，组织北平维持会，为日军提供粮食、劳力和情报，协助建立伪政权。；原北洋将领，北平沦陷初期组织伪维持会，为日军稳定昌平等郊区秩序服务。……（共涉及10个地区的犯罪记录）；伪职：伪冀东保安队司令，通州事变主要人物。；结局：抗战胜利被捕，病死狱中', '[]', '2026-09-10 09:57:13.992841', '2026-09-10 09:57:13.992841', '北京', '大兴', '固安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('88f6ef7fc5a041b48d0e07bbc864be9f', '邓平', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳坪山；广东深圳', '[]', '[]', '抗日战争时期', '', '管理深圳镇伪政权，为日军提供劳工和情报，镇压抗日活动。', '[]', '2026-09-10 09:57:14.029145', '2026-09-10 09:57:14.029145', '广东', '深圳', '坪山', NULL, NULL, NULL, NULL, '');
