INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('89059599f2514c4f8c7f70b0365ff622', '于尔贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔甘南', '[]', '[]', '抗日战争时期', '', '投敌后任伪甘南县警务局长，率伪警察镇压当地抗日群众，配合日军清乡。', '[]', '2026-09-10 09:57:14.066974', '2026-09-10 09:57:14.066974', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8905ba422bae4165adde58837b0456b8', '赵文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '四川成都金堂；四川成都；河北沧州任丘；重庆北碚；辽宁沈阳大东；河北衡水；安徽安庆；河北邯郸曲周；江西吉安峡江；江西吉安；重庆九龙坡；辽宁沈阳大东；四川成都邛崃；四川成都；河北邢台临西；河北邯郸广平；山东潍坊；山东潍坊昌乐；河北唐山滦州；江西萍乡莲花；江西南昌；安徽马鞍山当涂；河南郑州中牟；重庆巫山；北京、河北；内蒙古赤峰巴林左旗；河北沧州泊头', '[\"同名\"]', '[]', '抗日战争时期', '', '推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，搜集抗日情报。；在滦州训练汉奸青年，灌输亲日思想，为日军输送走狗。；率伪军配合日军对任丘、河间交界地区进行反复扫荡，制造多起惨案，杀害抗日军属。；在交河县（含泊头）推行保甲制度，组织伪警察协助日军清乡，残害抗日家属。；推行日伪“治安强化运动”，镇压抗日活动，逮捕进步学生和地下党员。……（共涉及10个地区的犯罪记录）；在滦州诱骗青年加入伪青年团，进行军事训练。', '[]', '2026-09-10 09:57:13.991315', '2026-09-10 09:57:13.991315', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8907ba8a4647486391f532302a59b1c6', '刘汉川', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州铜山；江苏徐州睢宁；江苏徐州鼓楼；江苏徐州邳州', '[]', '[]', '抗日战争时期', '', '在睢宁县城设立伪政权，协助日军征收粮税，组织伪警察镇压抗日活动，多次带队袭击抗日游击队。；在伪徐海道尹公署任职，参与策划清乡运动，协助日军搜捕抗日志士，并参与奴化教育宣传。；投靠日军，任邳县伪政权首脑，协助日军推行“治安肃正”，强征民夫修筑据点，镇压抗日民众。；曾任伪徐海道尹，管辖包括铜山在内的多个县，积极推行日伪政权政策，组织伪警察和保安队，配合日军扫荡，抓捕抗日人士。', '[]', '2026-09-10 09:57:14.035201', '2026-09-10 09:57:14.035201', '江苏', '徐州', '睢宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8908bf349b96418a94d39bcb29890d02', '刘锡三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山丰润；河北；河北唐山路南；河北唐山遵化；河北_廊坊_三河；河北廊坊；河北廊坊文安；河北唐山', '[]', '[]', '抗日战争时期', '', '在文安洼地区围剿抗日游击队，并参与“水淹”根据地行动。；发行伪币，扰乱金融，为日军掠夺唐山资源服务。；率伪军驻防丰润、玉田，多次围剿八路军冀东军区部队，杀害抗日战士和群众。；遵化伪县长，参与镇压冀东暴动余部，为日军提供情报。；在文安洼地区围剿抗日游击队，并参与“水淹”根据地行动。；指挥伪警察协助日军搜捕抗日分子，破坏中共地下交通站，参与“大检举”行动，杀害无辜百姓。', '[]', '2026-09-10 09:57:14.041334', '2026-09-10 09:57:14.041334', '河北', '唐山', '丰润', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('89106bc3a74348afaae0415e485c933e', '周阿虎', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海金山；浙江温州平阳', '[]', '[]', '抗日战争时期', '', '为日军搜集抗日情报，多次导致游击队联络点被破坏。；充当日军鹰犬，带领便衣队搜捕地下党员和抗日群众，多次参与屠杀事件。', '[]', '2026-09-10 09:57:13.979484', '2026-09-10 09:57:13.979484', '上海', '金山', '平阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('891ff7c5f49c4a7fbbe50881a825299e', '张体乾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '推行新民会奴化宣传，组织“青少年团”洗脑，破坏抗日群众组织。', '[]', '2026-09-10 09:57:14.021591', '2026-09-10 09:57:14.021591', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('89236564360849508e646c9cb89b21d4', '李德旺', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶余干；江西上饶德兴；江西上饶鄱阳；山西晋城阳城', '[]', '[]', '抗日战争时期', '', '日军侵占鄱阳期间出面组织伪维持会，为日军征粮派款、维持地方秩序，协助日军控制鄱阳城乡。；日军侵占余干期间出面组织维持会，为日军征粮派款、维持地方秩序，协助日军搜捕抗日人员。；地方史料中偶见提及德兴沦陷时期有维持会组织，但具体人名、事迹缺乏可靠公开记载，需进一步查证。', '[]', '2026-09-10 09:57:14.037546', '2026-09-10 09:57:14.037546', '江西', '上饶', '余干', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('89265f86a3eb4f8aa5edf53e748dbc6d', '孙发祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南漯河；河南漯河舞阳；湖北恩施鹤峰', '[]', '[]', '抗日战争时期', '', '率伪保安团在鹤峰及周边地区清乡，烧毁抗日群众房屋，捕杀抗日干部及家属。；舞阳沦陷后投敌，组织维持会，为日军提供情报，协助日军进攻舞阳南部抗日根据地。', '[]', '2026-09-10 09:57:14.048645', '2026-09-10 09:57:14.048645', '河南', '漯河', '鹤峰', NULL, NULL, NULL, NULL, '');
