INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8949a938493041a5a84707a1b0c60caa', '陈铁生', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州石城；江西赣州；河南开封；湖北咸宁嘉鱼；江西赣州信丰；江西赣州；江西赣州章贡；江西赣州南康；湖北宜昌；湖北孝感；江西赣州定南；河南开封兰考；辽宁沈阳大东；湖北_襄阳_枣阳；山西阳泉城区；河南开封龙亭；湖北咸宁；湖北襄阳；湖北襄阳老河口；湖北咸宁咸安；辽宁沈阳大东；江西赣州；湖北咸宁通山；湖北潜江；河南郑州管城；河南郑州；湖北黄石下陆；山西阳泉矿区；河南新乡；河南郑州郑州航空港经开区；辽宁沈阳新民；河南郑州惠济；河南郑州；河南信阳商城', '[]', '[]', '抗日战争时期', '', '在赣州日占区伪警察系统任职，参与维持占领区治安，协助日军管控民众。；在赣州沦陷期间任伪警察局长，配合日军清查抗日分子，逮捕爱国人士，维持伪政权治安。；组织伪新民会，进行亲日宣传，协助日军控制民众思想，配合治安强化运动。；在开封主持伪宣传，为日军侵略辩护，鼓吹“大东亚共荣圈”，麻痹民众抗日意志。；在郑州及管城地区协助日军推行奴化教育，组织亲日宣传，培训伪教员。；率部投靠日军，编为伪保安团，在赣县、南康、信丰一带配合日军扫荡抗日游击队，捕杀抗日人员，勒索百姓。；抗日战争后期在定南县组织伪维持会，为日军和伪政权征派粮款、民夫，协助维持地方治安，迫害抗日群众。；孝感沦陷后投敌，任伪维持会会长、县长，配合日军扫荡周边抗日根据地。；任伪新乡县警察局长，搜捕抗日人员，镇压民众反抗。；在开封推行奴化教育，篡改教材，强迫学生学习日语，培养亲日思想。；任伪通山县县长，推行保甲制度，配合日军对通山及周边山区抗日武装进行清乡。；在咸宁地区组建伪警察队伍，配合日军清乡、搜捕抗日人员，镇压当地民众。；协助王旭初组织维持会，为日军筹办粮草、向导。；下陆地区沦陷后组织维持会，为日军征集物资、拉夫，协助日军控制下陆铁路与矿区。；控制报刊与广播，进行亲日反共宣传，粉饰日军占领政策。；光化（今老河口）沦陷后组织维持会，任伪县长，配合日军统治。；抗战期间在伪河南省教育系统任职，后任伪郑州中学校长，推行奴化教育，篡改教材，向学生灌输亲日思想。；在咸宁推行奴化教育，强制学校使用伪教材，宣传“大东亚共荣圈”，毒化青少年。；抗战期间在嘉鱼任伪县长，执行日军指令，管理沦陷区基层事务。；在监利、潜江交界地区配合日军“清乡”，捕杀抗日人员。；在开封各校推行日语教育与亲日宣传，组织学生参加日伪活动。；在豫南沦陷区负责伪警务，配合日军进行户口清查、逮捕抗日嫌疑人员。；充任伪警察头目，配合日军清查户口、抓捕抗日嫌疑人员，镇压民众反抗。；掌控伪警察力量，在襄阳城区及近郊搜捕抗日分子，配合日军实施保甲连坐，镇压民众反抗。；在赣州伪警察系统中任职，参与搜捕抗日分子、监控民众，配合日军及伪政权维持治安。', '[]', '2026-09-10 09:57:14.040434', '2026-09-10 09:57:14.040434', '江西', '赣州', '信丰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('894e92526fa9444da834c7d4efe557af', '王炳宸', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪梨树县县长；罪行：梨树为四平省核心县；强力推行粮食出荷，武力征粮，推行集团部落。；结局：战后汉奸罪判刑。', '[]', '2026-09-10 09:57:14.078164', '2026-09-10 09:57:14.078164', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
