INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('898064a2370940ef8f257d451fc3342e', '郭寿山', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州定南；河南许昌长葛；山东潍坊昌邑；河南开封', '[]', '[]', '抗日战争时期', '', '在定南一带率领伪保安队配合日伪军行动，搜捕抗日人员，征派粮款，欺压百姓。；为日军征收苛捐杂税，掠夺开封经济资源。；在昌邑地区组织维持会，配合日军建立伪基层政权，推行保甲制度，征调民夫和物资，镇压抗日群众。；为日军筹办军需物资，强制商户摊派，协助日军控制长葛经济。', '[]', '2026-09-10 09:57:14.017015', '2026-09-10 09:57:14.017015', '山东', '潍坊', '昌邑', NULL, NULL, NULL, NULL, '');
