INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8a5bb3df896542e983ba20519ff298cb', '刘允升', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔克山；齐齐哈尔', '[]', '[]', '抗日战争时期', '', '伪职：伪黑龙江省会公安局长；罪行：掌管齐齐哈尔伪公安系统，抓捕爱国人士，镇压民间抗日活动，搭建城市伪警体系。；结局：解放后镇压反革命时期被惩处。', '[]', '2026-09-10 09:57:14.066931', '2026-09-10 09:57:14.066931', '黑龙江', '齐齐哈尔', '克山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8a5f0eb3109a400fbf77a2e749ad1086', '林剑魂', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西景德镇昌江', '[]', '[]', '抗日战争时期', '', '推行保甲制度和奴化政策，在昌江等地强化日伪基层统治，镇压民众反抗。', '[]', '2026-09-10 09:57:14.054292', '2026-09-10 09:57:14.054292', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8a6082f397e64f1e9eb9b3ceeb18bdaf', '陈特向', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东潮州饶平；广东_汕头_濠江；广东汕头潮阳；广东汕头澄海；广东潮州潮安；广东汕头；广东汕头南澳；广东_汕头_龙湖；广东湛江徐闻；广东湛江遂溪；广东潮州；辽宁沈阳大东；广东汕头潮南；广东汕头潮阳', '[]', '[]', '抗日战争时期', '', '掌管伪警察系统，搜捕抗日人士，协助日军实施物资统制与人口登记，镇压市民反抗。；统率伪军配合日军扫荡潮汕抗日游击区。；统率伪军配合日军扫荡潮汕抗日根据地，参与清乡与封锁。；协调潮汕各地伪维持会，为日军筹粮筹款，推行奴化教育，协助日军巩固沦陷区统治。；在遂溪组织伪维持会，协助日军维持治安，搜捕抗日游击队员。；潮安沦陷后任伪县长，协助日军统治潮汕腹地，参与经济掠夺和治安强化。；潮安沦陷后出任伪县长，隶属汕头伪政权体系，推行日伪政令。；在潮阳沦陷区出任伪县长，配合日军清乡、征粮，镇压当地抗日游击队。；在潮汕地区组织伪自治武装，配合日军对潮汕抗日根据地和游击区进行扫荡。；任伪潮阳县县长期间，在潮阳及邻近潮南地区推行保甲制、征粮征夫，协助日军控制地方。；在潮安沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.028006', '2026-09-10 09:57:14.028006', '广东', '汕头', '南澳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8a7533a082434b9ba10b58c6187540d9', '王景阳', NULL, NULL, NULL, NULL, 'exact', 'exact', '兴城', '[]', '[]', '抗日战争时期', '', '伪职：伪兴城县警务科长；罪行：指挥伪警察、密探，搜捕郑桂林义勇军地下关系，迫害义勇军家属。；结局：解放后惩处。', '[]', '2026-09-10 09:57:14.072277', '2026-09-10 09:57:14.072277', '辽宁', '葫芦岛', NULL, NULL, NULL, NULL, NULL, '');
