INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8b24c8273dca4990927901ff29d4d333', '韦耀祖', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁马山；广西南宁武鸣；广西南宁邕宁；广西南宁；广西梧州龙圩；广西梧州；广西南宁隆安；广西南宁武鸣；广西河池南丹；广西南宁武鸣；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '南丹沦陷期间担任伪保甲长，替日军摊派粮款、监视村民，协助维持日伪基层统治。；参与伪南宁维持会活动，协助日军维持占领区秩序。；南宁沦陷期间充任伪警察头目，协助日军维持城区秩序，抓捕抗日嫌疑人员。；武鸣沦陷后，韦耀祖组织伪维持会，为日军提供情报和物资，协助管理地方。；武鸣沦陷后任伪维持会副会长，协助日军管理武鸣及周边地区，包括马山部分区域，为日军提供情报和物资。；率伪保安队在梧州、龙圩周边配合日军扫荡抗日游击队，残害百姓。', '[]', '2026-09-10 09:57:14.031222', '2026-09-10 09:57:14.031222', '广西', '南宁', '武鸣', NULL, NULL, NULL, NULL, '');
