INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8b45856a824546ef9c29c2b096d3f3d7', '李春秀', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古_包头_包头稀土高；内蒙古呼和浩特托克托；内蒙古_呼和浩特_和林格尔；内蒙古、河北；内蒙古呼和浩特；河北张家口', '[]', '[]', '抗日战争时期', '', '为日伪征收苛捐杂税，盘剥百姓，将税款直接供给日军军需。；投日任伪归绥县知事，协助日军实施保甲制度，迫害抗日家属。；率伪保安队多次袭击托克托县境内的抗日游击队，杀害抗日家属，抢劫村庄，罪行累累。；推行奴化教育，强制学校教授日语，宣扬“中日亲善”，毒害青少年。', '[]', '2026-09-10 09:57:13.988021', '2026-09-10 09:57:13.988021', '内蒙古', '呼和浩特', '托克托', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8b476b167c9440dfbce22404e1a944d3', '陈耀南', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾海丰；广东梅州梅县；广东广州；广东湛江遂溪；广东云浮郁南；湖南益阳；广东清远连南；广东清远；广东韶关翁源；广东韶关；广东潮州；广东惠州惠城；广东惠州', '[]', '[]', '抗日战争时期', '', '在惠州沦陷期间任职伪警察机构，参与搜捕抗日人员、镇压民众抗日活动。；在伪海丰县推行日语教育，篡改历史教材，宣传“大东亚共荣圈”，奴化青少年。；在雷州、遂溪一带为日军效力，组织伪政权，协助日军扫荡抗日游击区。；日军侵占益阳期间出面组织维持会，协助日军征粮、拉夫、维持占领秩序，并参与筹建伪政权。；在广州参与伪广东治安维持会，后受日军指派到粤东梅县一带活动，拉拢地方士绅附逆，为日军筹粮。；抗战期间投靠日军，参与组织伪广东维持会，后任伪广东省政府委员，协助日军推行殖民统治。；在清远地区担任伪警察头目，配合日军搜捕抗日人员，推行保甲连坐，压制民众抗日。；在连县（今连州，毗邻连南）组织伪维持会，协助日军及伪政权控制粤北山区，为日军提供物资和情报，压迫当地民众。；韶关地区汉奸，参与组织伪韶关维持会，协助日军管理地方事务，为日军提供物资和情报支持。；统率伪绥靖军配合日军在潮汕地区进行清乡、扫荡，残害抗日军民。', '[]', '2026-09-10 09:57:14.025269', '2026-09-10 09:57:14.025269', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
