INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8bf7522722c242b79fb32bc83b2bc75d', '白化安', NULL, NULL, NULL, NULL, 'exact', 'exact', '铁岭第七区', '[]', '[]', '抗日战争时期', '', '伪职：伪地方保安大队副，恶霸汉奸；罪行：伪满依附日伪；光复后勾结国民党，杀害农会干部 8 人，反攻倒算，祸害辽北乡村。；结局：1951 年镇反公审枪决。', '[]', '2026-09-10 09:57:14.079037', '2026-09-10 09:57:14.079037', '辽宁', '铁岭', NULL, NULL, NULL, NULL, NULL, '');
