INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8c00aa12c1854c769820ebf6b625f432', '刘茂恩', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口；河南洛阳涧西；河南洛阳；河南南阳；河南三门峡陕州；云南普洱西；河南洛阳新安；河南洛阳；河南洛阳西工；河南洛阳；河南洛阳洛阳高；河南洛阳；河南开封龙亭；河南开封；河南洛阳老城；河南洛阳；河南周口淮阳；河南洛阳栾川；河南洛阳；河南商丘；河南洛阳嵩县；河南洛阳；河南洛阳汝阳；河南洛阳；河南驻马店平舆；青海黄南河南；河南三门峡三门峡经开区；云南普洱西；河南南阳；河南平顶山；河南洛阳；河南平顶山平顶山高；河南平顶山；河南洛阳伊川；河南洛阳', '[]', '[]', '抗日战争时期', '', '豫西沦陷后投靠日军，拼凑伪自治军，活动于洛阳、伊川、嵩县一带，协助日军维持占领区秩序并对抗抗日武装。；在洛阳、宜阳、洛宁交界地区组织伪自治军，协助日军维持占领区治安。；洛阳沦陷后附逆，参与伪豫西政权，协助日军推行保甲、征发劳役。；1944年降日，组织伪军配合日军扫荡豫西，进攻八路军及地方抗日武装。；原为地方武装首领，1944年日军侵占豫西后一度投敌，被编为伪保安团，活动于洛阳、嵩县交界地区，后率部反正。；淮阳地方商人，抗战期间与日军合作，任伪淮阳县维持会副会长及商会会长，为日军采购军粮、棉布等物资，并协助推行伪币。；在豫东伪政权中负责警务，配合日军搜捕抗日人员，镇压民众。；投敌后驻开封，协助日军策划对抗日根据地的扫荡与清乡。；在豫西地区组织伪军，配合日军进攻抗日根据地，搜捕抗日人员。；原国民党军将领，后投靠日军，任伪豫西剿共军司令，在豫西配合日军进攻八路军。；河南人，抗战期间投敌，在豫西组织伪军，配合日军进攻豫西抗日根据地，其活动范围接近南阳北部。；1944年豫西沦陷后投敌，组织伪军配合日军扫荡豫西抗日根据地，活动范围包括平顶山周边山区。；在洛阳、宜阳一带收编土匪与溃兵，组织伪军配合日军进攻抗日根据地。；在豫东道伪保安系统任职，参与制定扫荡计划，协调周口、淮阳等地伪军行动。；1944年日军发动豫湘桂战役后，河南大部沦陷，刘茂恩被汪伪政权任命为伪河南省政府省长，但未实际就任，其任命反映了当时河南伪政权对南阳、新野等地的名义管辖意图。；在河南沦陷区组织伪自治军，活动于洛阳、汝阳一带，协助日军维持占领区，对抗抗日力量。；原国民党将领，抗战后期在河南率部投敌，所部被编为伪军，活动范围包括洛阳、新安周边地区。；洛阳及豫西沦陷后率部投敌，所部被编为伪保安团，在洛阳、宜阳、嵩县、栾川交界地区配合日军行动。；洛阳沦陷后率部投敌，被日军委为伪保安总队长，在洛阳老城及周边地区协助日军征粮、清乡。；原国民党河南省主席，1944年投敌，任伪河南省政府委员，协助日军维持河南伪统治。；原国民党将领，后率部投日，在洛阳及豫西地区配合日军进攻抗日根据地。；原国民党地方武装首领，1944年豫西沦陷后投敌，被日军委任为伪豫西剿共军司令，配合日军进攻抗日根据地，活动于洛阳周边。；豫西沦陷后投敌，组织伪自治军，在平顶山、宝丰、鲁山一带配合日军行动，骚扰抗日根据地。', '[]', '2026-09-10 09:57:14.045687', '2026-09-10 09:57:14.045687', '河南', '三门峡', '三门峡经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8c0692a70c9a47c4b50b664ef8c58d8c', '徐志澄', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州柯城', '[]', '[]', '抗日战争时期', '', '任伪衢县县长期间，推行日伪统治，强征民夫修筑工事，配合日军清乡扫荡。', '[]', '2026-09-10 09:57:14.052300', '2026-09-10 09:57:14.052300', '浙江', '衢州', '柯城', NULL, NULL, NULL, NULL, '');
