INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8c1aa20e5fb845499097e78014b9a858', '张占魁', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口沈丘；河南周口；河南周口郸城；河南周口周口经开区；河南商丘；河南周口太康；河南周口', '[]', '[]', '抗日战争时期', '', '在商丘、周口、鹿邑一带收编土匪武装，组织伪军配合日军进攻睢杞太抗日根据地，残害抗日军民。；在鹿邑、郸城交界地区活动，率伪军配合日军扫荡，袭击抗日游击队，残害百姓。；在豫东周口、太康、鹿邑一带活动，率伪军配合日军进攻抗日游击区，抢掠民财，杀害抗日军民。；在淮阳、周口一带充任伪职，推行日伪政令，征发民夫物资，配合日军对豫东抗日力量进行镇压。', '[]', '2026-09-10 09:57:14.047373', '2026-09-10 09:57:14.047373', '河南', '周口', '周口经开区', NULL, NULL, NULL, NULL, '');
