INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8cca0c4d9b1046be81d7adb34f29fe71', '任光宇', NULL, NULL, NULL, NULL, 'exact', 'exact', '武康（今德清）上柏', '[]', '[]', '抗日战争时期', '', '伪职：伪武康上柏区伪区长；罪行：地方恶少投敌，手上杀害多名武康县中队游击队员，残害莫干山区抗日群众，气焰嚣张。；结局：莫干区中队抓捕，公审处决。', '[]', '2026-09-10 09:57:14.072024', '2026-09-10 09:57:14.072024', '浙江', '湖州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8cd0e84b64e94d508a281161f8fc788e', '张惕勤', NULL, NULL, NULL, NULL, 'exact', 'exact', '不在合肥本地活动', '[]', '[]', '抗日战争时期', '', '伪职：汪伪空军，合肥籍；罪行：原国军飞行员，1941 驾机投敌，加入汪伪空军，参与轰炸大后方，合肥籍贯的知名投敌人员。；结局：1948 年上海判处死刑枪决。', '[]', '2026-09-10 09:57:14.070613', '2026-09-10 09:57:14.070613', '安徽', '合肥', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8cdff9597880411f96d9edbea5a14dc4', '李德新', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西玉林；广西玉林北流', '[]', '[]', '抗日战争时期', '', '北流沦陷后组织维持会，为日军征粮派夫，协助日军控制北流地区。', '[]', '2026-09-10 09:57:14.032763', '2026-09-10 09:57:14.032763', '广西', '玉林', NULL, NULL, NULL, NULL, NULL, '');
