INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8cf1870944444378b5af2f62cdf43fb8', '张国栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔富拉尔基；锦西（江家屯）', '[]', '[]', '抗日战争时期', '', '伪职：九一八初期锦西县县长；罪行：日军将至，亲自制作日本国旗，率士绅出城迎接古贺联队入城；向日军密报城外联庄会义勇军计划，出卖抗日武装，直接促成日军占领锦西县城葫芦岛市南...。；结局：抗战胜利后被逮捕，以汉奸罪判处徒刑。', '[]', '2026-09-10 09:57:14.066949', '2026-09-10 09:57:14.066949', '黑龙江', '齐齐哈尔', '富拉尔基', NULL, NULL, NULL, NULL, '');
