INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8cf8cccac2cb4f08a5cb584d3650865f', '翟学文', NULL, NULL, NULL, NULL, 'exact', 'exact', '长垣县', '[]', '[]', '抗日战争时期', '', '伪职：长垣伪维持会成员；罪行：1938年2月日军侵占长垣后，纠集本地地痞流氓，手持太阳旗列队欢迎日军入城；日军扶持其成立伪维持会，保管日军辎重物资；结局：后被抗日武装活捉', '[]', '2026-09-10 09:57:14.075982', '2026-09-10 09:57:14.075982', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
