INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d249bd3e68f4f1496042b480cacd859', '陈楚楠', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江彭泽；江西九江；湖北黄冈', '[]', '[]', '抗日战争时期', '', '在江西沦陷区依附汪伪政权，参与伪江西省政，督导九江一带伪政权与伪军。；黄冈人，抗战期间任伪黄冈县保安大队大队长，率伪军配合日军扫荡黄冈、蕲春一带抗日根据地。', '[]', '2026-09-10 09:57:14.038929', '2026-09-10 09:57:14.038929', '江西', '九江', '彭泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d2ce6ece663482da3c3c3f34a93f9ef', '崔步武', NULL, NULL, NULL, NULL, 'exact', 'exact', '泰州城区（姜堰）', '[]', '[]', '抗日战争时期', '', '伪职：伪泰县（泰州）县长；罪行：汪伪清乡专员，主政泰县伪政权，推行清乡保甲，征粮抓丁，配合日伪围剿苏中三分区抗日武装南通市档案...。；结局：抗战胜利后被捕判刑。', '[]', '2026-09-10 09:57:14.087405', '2026-09-10 09:57:14.087405', '江苏', '泰州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d2e2a4d990a4b7f8635fb51689094ac', '张凤鸣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；山西长治沁县；山西晋中榆社', '[]', '[]', '抗日战争时期', '', '充当日军走狗，参与多次清乡行动，杀害抗日干部和群众，抢劫民财。；日军初占沁县时出任维持会长，为日军筹集粮款，强迫百姓‘欢迎皇军’，并告密抗日活动。；率伪军多次配合日军袭击无极县抗日武装，杀害抗日干部和群众，参与制造多起惨案。；率伪军多次扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，为日军提供情报，是当地罪大恶极的汉奸武装头目。', '[]', '2026-09-10 09:57:14.022947', '2026-09-10 09:57:14.022947', '山西', '晋中', '榆社', NULL, NULL, NULL, NULL, '');
