INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d40f12c271a41c2a836b7b59e1ea0b5', '金永昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '广西桂林资源；河北_张家口_宣化；内蒙古锡林郭勒正蓝旗；云南普洱西；重庆沙坪坝；内蒙古呼伦贝尔牙克石；河北张家口尚义；河北张家口；内蒙古、河北；内蒙古呼伦贝尔满洲里；内蒙古赤峰喀喇沁旗；内蒙古赤峰；内蒙古_呼和浩特；内蒙古乌海乌达；内蒙古锡林郭勒多伦；内蒙古赤峰松山；内蒙古赤峰；内蒙古通辽；内蒙古鄂尔多斯', '[]', '[]', '抗日战争时期', '', '在满洲里地区协助日军管理边境事务，参与对苏谍报活动；投靠日本，负责伪蒙疆交通建设，为日军军事运输提供便利。；参与制定伪蒙疆法律，在万全地区设立伪法院，迫害抗日军民，协助日军“清乡”行动。；负责为日军征收苛捐杂税，搜刮民财，支持伪政权运作。；在张家口、怀安地区组织伪警察和特务，搜捕抗日地下人员，实施“连坐”制度，制造多起屠杀事件。', '[]', '2026-09-10 09:57:13.989062', '2026-09-10 09:57:13.989062', '内蒙古', '呼伦贝尔', '满洲里', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d4b10a0136b417b9b0a9f50c91edb41', '郑海清', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北潜江；安徽马鞍山当涂；江西宜春；湖北荆门京山；湖北襄阳谷城；重庆江津；湖北十堰；浙江温州苍南；重庆巫溪', '[]', '[]', '抗日战争时期', '', '协助日军强征劳工修建军事设施，克扣劳工工资，参与镇压工人罢工；湖北均县人，抗战期间投敌，任伪均县保安团团长，组织伪军配合日军作战，镇压抗日活动。；在熊口为日军筹粮筹款，引导日军搜捕抗日游击队员。；在永漋河一带组织伪维持会，为日军提供情报、向导，协助建立伪政权基层组织。；在铜鼓、宜春交界山区组织伪政权，为日军搜集情报，破坏抗日交通线。；带领伪自卫队配合日军行动，参与搜捕抗日游击队员。；率伪保安团配合日军扫荡，袭击抗日游击队，残害抗日群众。；组织伪自卫团配合日军守备队防守谷城据点，多次参与对周边抗日根据地的袭扰和物资掠夺。；协助日军在灵溪建立情报网，多次告密导致抗日人员被捕。', '[]', '2026-09-10 09:57:14.011203', '2026-09-10 09:57:14.011203', '安徽', '马鞍山', '当涂', NULL, NULL, NULL, NULL, '');
