INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d4e16557cba4fa598a1bbb19fc65ff5', '王永贵', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京；北京_密云；黑龙江佳木斯汤原；黑龙江佳木斯；江苏盐城；陕西西安', '[]', '[]', '抗日战争时期', '', '协助日军抓捕抗日家属，破坏地下交通线，残害进步群众。', '[]', '2026-09-10 09:57:13.993654', '2026-09-10 09:57:13.993654', '北京', '西安', '汤原', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d503e3416b3454bafb98cbc90ee7e60', '王锡良', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；河南周口沈丘；河南平顶山新华；河南平顶山；河南平顶山舞钢；青海黄南河南；河南郑州；河南郑州上街；河南郑州；山西阳泉城区；河南开封通许；河南开封尉氏；河南新乡新乡平原示范；河南新乡；河南许昌襄城；河南许昌；河南漯河召陵；河南漯河', '[]', '[]', '抗日战争时期', '', '任伪河南省警务厅厅长，驻开封，指挥伪警察配合日军“扫荡”，镇压抗日力量。；带领伪保安队在通许境内搜捕抗日人员，配合日军扫荡。；在河南伪政权中担任要职，协助日军推行保甲制度、征粮征丁，镇压豫东地区抗日力量。；项城沦陷后组织维持会，为日军征粮派款，协助日伪控制项城及邻近沈丘地区。；平顶山地区沦陷后，出面组织维持会，为日军征集物资、情报，协助日军管理煤矿及地方治安。；郑州沦陷后组织伪维持会，后任伪郑州市市长，为日军征集物资、维持治安，直接参与郑州地区的伪政权活动。；日军侵占新乡后，出面组织伪维持会，后任伪新乡县县长，为日军征粮、派夫、维持地方伪秩序。；日军侵占许昌后，出面组织维持会，后任伪许昌县县长，为日军征粮派款、维持治安，镇压抗日活动。；1944年日军占领漯河后，出面组织伪维持会，协助日军维持占领秩序、征派物资、登记户口，是漯河当地直接附逆的伪政权头目。；郑州沦陷后组织伪维持会，任会长，协助日军征粮、派夫，维持地方伪秩序。；郑州沦陷后出面组织维持会，为日军筹粮筹款、招募劳工，协助日军管理城市秩序。；郑州沦陷后组织维持会，为日军筹集物资、维持地方秩序，协助日军控制郑州城区。；日军侵占郑州后，出面组织伪郑州维持会，任会长，协助日军维持地方秩序、征发物资、安抚民众，是郑州沦陷初期主要的附逆人物之一。；推行奴化教育，强制学校使用伪教材，宣传“中日亲善”。', '[]', '2026-09-10 09:57:14.047509', '2026-09-10 09:57:14.047509', '河南', '周口', '沈丘', NULL, NULL, NULL, NULL, '');
