INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8d95247327e74eb0926b2928324c6803', '熙洽', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁葫芦岛绥中；辽宁阜新；吉林；辽宁葫芦岛；山东聊城茌平；山东聊城；吉林；河北承德平泉；辽宁沈阳；吉林；辽宁鞍山岫岩；辽宁鞍山；黑龙江伊春大箐山；吉林；吉林；广西_桂林_永福；重庆_大足；辽宁鞍山千山；吉林；黑龙江佳木斯；黑龙江牡丹江绥芬河；辽宁丹东凤城；吉林；辽宁辽阳灯塔；吉林；吉林四平双辽；吉林；河北秦皇岛山海关；辽宁沈阳；吉林；黑龙江双鸭山集贤；黑龙江齐齐哈尔；辽宁阜新彰武；辽宁阜新；辽宁朝阳双塔；吉林长春朝阳；黑龙江鸡西城子河；吉林；吉林、河北、辽宁；吉林四平；吉林；辽宁铁岭；辽宁葫芦岛南票；辽宁营口大石桥；吉林；辽宁沈阳；吉林白城白城经开区；吉林；黑龙江绥化肇东；吉林；吉林白城洮北；吉林；辽宁沈阳；辽宁盘锦；沈阳（满族）；辽宁锦州；辽宁沈阳苏家屯；吉林；辽宁阜新；黑龙江鹤岗兴安；吉林；辽宁阜新太平；辽宁阜新；辽宁鞍山；黑龙江牡丹江牡丹江经开区；黑龙江牡丹江；吉林；黑龙江牡丹江；辽宁鞍山铁西；辽宁鞍山；重庆沙坪坝；辽宁锦州古塔；辽宁锦州', '[]', '[]', '抗日战争时期', '', '伪职：伪满宫内府大臣；罪行：九一八主动引日军入吉林，策动伪满建国，搜刮东北资源，镇压吉林抗日力量。；结局：苏军逮捕，引渡回国，1952 年哈尔滨战犯管理所病逝。；伪职：伪吉林省首任长官、伪财政部大臣；罪行：九一八主动放弃吉林防务，开城投降日军；组建伪吉林省长官公署，宣布脱离国民政府；参与伪满建国；指挥伪军围剿吉林各地义勇军、抗联，推行集团部落，疯狂掠夺资源抖音百科。；结局：苏军逮捕，关押，1952 年哈尔滨战犯管理所病死。；九一八事变后投靠日本，协助建立伪满洲国，任吉林省伪省长，镇压抗日力量，推行殖民政策。；原吉林省政府委员，1931年叛国投敌，迎接日军占领吉林，后任伪吉林省长，积极推行伪满政权各项政策，镇压抗日力量。；原吉林副司令长官公署参谋长，1931年投降日军，打开吉林城门，并协助日军占领四平、吉林等要地，后任伪满高官。；原吉林副都统，九一八事变时在吉林投降日军，建立伪吉林省政权，后任伪满高官，推行殖民政策，协助日本掠夺东北资源。；原吉林副都统，九一八事变时在吉林开城迎敌，组织伪吉林省政权，为日军侵占吉林、四平地区提供便利。……（共涉及56个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.981899', '2026-09-10 09:57:13.981899', '吉林', '四平', '伊通', NULL, NULL, NULL, NULL, '');
