INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8df255f8a1a7434a84b6e66fafe4c67a', '吴坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南保亭；辽宁沈阳大东；海南乐东；江西景德镇昌江', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校使用日语和伪满教材，宣传“大东亚共荣圈”。；在昌江、乐东交界地区活动，配合日军扫荡，残害抗日群众。', '[]', '2026-09-10 09:57:14.054008', '2026-09-10 09:57:14.054008', '海南', '乐东', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8df5480d2e094f60bd56143155b54235', '王绍武', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北唐山路南；山东菏泽菏泽高；山东菏泽定陶；山东泰安东平；山东泰安；香河；山东济宁汶上；河北邢台；山东济宁兖州；山东济宁；河北邯郸邯郸冀南；辽宁沈阳新民；山东济宁曲阜；山东济宁；山东聊城；山东泰安泰山；辽宁沈阳新民；山东济宁济宁高；山东济宁；河北石家庄石家庄高；山东济宁微山；河北沧州运河；山东菏泽巨野；山东菏泽；河北；山东泰安肥城；辽宁沈阳大东；平遥；山东济宁泗水；山东济宁嘉祥；山东济宁；山东菏泽曹县；山东菏泽；山东济宁鱼台；山东济宁；山东宁阳；山东济宁；济宁（兖州）；山东济宁邹城；山东泰安', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪香河县县长。；结局：战后判刑；伪职：伪宁阳县长、伪兖济道道尹；罪行：掌鲁西南十数县伪政权，推行保甲连坐，残害抗日人员；来源：项目数据库；备注：镇反中被处决；伪任职务：伪宁阳县长、兖济道道尹，掌控鲁西南十余县伪政权，推行保甲连坐。结局：镇反时期被处决；伪职：伪东光县县长；配合李文成伪军推行日伪政令，强征粮秣。；结局：战后逮捕判刑；伪职：伪宁阳县知事（1939）→伪兖济道道尹（1942—1945）；罪行：滋阳（今兖州）人。原为土匪武装头目，1938年率部投降日军。任宁阳伪县长期间祸害宁阳四年；1942年升任兖济道道尹，管辖济宁、宁阳、曲阜、滋阳等十余县伪政权。推行保甲连坐，强征粮食壮丁；配合日军扫荡泰西、尼山抗日根据地；大肆抓捕地下党员与抗日干部。打死打伤我军民数百人；结局：1945年日本投降后投靠国民党；解放战争后期被俘，镇反运动中被判处死刑执行枪决；伪职：伪平遥警备大队长；罪行：率伪军下乡清乡，抓捕抗日干部群众。；结局：解放后镇压处决；滦县（路南核心）伪县长，强征粮食、劳工，为日军修建碉堡，镇压滦河两岸抗日武装。；专门搜集抗日情报，抓捕地下党员，酷刑审讯，导致多个抗日组织被破坏。；协助日军宪兵队刑讯逼供，残害抗日志士。；充当日军傀儡，在邯郸县城及周边乡村建立伪保甲制度，强征民夫修筑碉堡公路，配合日军‘扫荡’，残害抗日军民。；组织新民会，开展‘宣抚’活动，诱骗青年参加伪军，收集抗日情报，破坏群众抗日团体。', '[]', '2026-09-10 09:57:14.014762', '2026-09-10 09:57:14.014762', '山东', '泰安', '东平', NULL, NULL, NULL, NULL, '');
