INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8e653e2b30a94497b8e6f80ba871b440', '罗锦章', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江；九江县（今浔阳区）', '[]', '[]', '抗日战争时期', '', '伪职：伪九江商会会长；罪行：鸦片烟商出身，投敌后任伪商会会长，为日军搜刮商业物资、管控市场、掠夺瓷业等资源；结局：史料未明确记载其最终结局（来源：九江伪政权“三巨头”之一，代表日伪控制下的商界）；伪职：伪商会会长；罪行：鸦片商人，出任伪商会会长，管控商贸，为日军征敛物资；来源：九江市史志办；备注：九江伪政权三巨头之一', '[]', '2026-09-10 09:57:14.071603', '2026-09-10 09:57:14.071603', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8e7c02cb9b2d401195623ee09eda70ce', '崔永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_晋城_城区', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，强征“慰劳金”，盘剥商户，致使多家商铺倒闭，民怨极大。', '[]', '2026-09-10 09:57:14.023150', '2026-09-10 09:57:14.023150', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8e8c5d1978c84e5b9c8cee40a92510fa', '石孝先', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆合川；重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '据地方志片段，曾在合川组织维持会，协助日军征粮，但史料零散。；重庆袍哥组织“孝义会”首领，在沙坪坝及重庆周边活动。抗战期间与军统、地方势力关系复杂，但无确凿证据表明其任伪职或附逆。', '[]', '2026-09-10 09:57:14.064097', '2026-09-10 09:57:14.064097', '重庆', '合川', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8e99e64432c54a238a2705186bbbda2d', '刘显世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁；辽宁本溪；辽宁本溪', '[]', '[]', '抗日战争时期', '', '负责本溪湖煤铁公司（溪湖地区）的劳工管理，残酷压榨中国矿工，大量劳工因虐待致死，并协助日军将矿工充当劳役修筑军事工事。', '[]', '2026-09-10 09:57:14.063432', '2026-09-10 09:57:14.063432', '辽宁', NULL, NULL, NULL, NULL, NULL, NULL, '');
