INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8ea44161ac794490a269a1fe7f198af0', '张万禄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；山西', '[]', '[]', '抗日战争时期', '', '率领伪保安队多次袭击抗日游击队，抓捕抗日军民，并参与日军对周边村庄的扫荡，烧杀抢掠。；充当日军帮凶，率领矿警队监视矿工，抓捕抗日分子，多次参与镇压矿工罢工，并强迫矿工为日军生产军需煤炭。', '[]', '2026-09-10 09:57:14.024572', '2026-09-10 09:57:14.024572', '山西', '阳泉', '城区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8ea4b5ee003b48bbbbd2507edf7e8360', '惠纹章', NULL, NULL, NULL, NULL, 'exact', 'exact', '唐河县', '[]', '[]', '抗日战争时期', '', '伪职：皇协军成员；罪行：申中祥部属，唐河县皇协军成员；结局：与申中祥一同被围歼，被抓捕后枪决', '[]', '2026-09-10 09:57:14.070328', '2026-09-10 09:57:14.070328', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
