INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8eaa7a17ef8b442582febc5a2c353ec2', '王金发', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴秀洲；浙江丽水松阳；上海金山；上海闵行；上海宝山', '[]', '[]', '抗日战争时期', '', '在新农乡为日军征收粮食，殴打抗捐农民，致多人伤残。；为日伪征收各种苛捐杂税，强征粮食，导致闵行地区民生凋敝，并贪污中饱私囊。；组织维持会为日军提供粮秣情报，强迫商户悬挂伪旗，并举报抗日积极分子，致多人被捕。；投靠日军，组织维持会，为日军筹款、提供物资，镇压抗日活动，强征民夫修筑工事。；组织伪自卫团，协助日军驻守据点，参与“扫荡”周边村庄，烧毁民房，抢劫财物。', '[]', '2026-09-10 09:57:13.975958', '2026-09-10 09:57:13.975958', '上海', '宝山', '松阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8eac5a96ae4b4928988027bf378fda81', '周阿桂', NULL, NULL, NULL, NULL, 'exact', 'exact', '海门、葭沚、路桥一带', '[]', '[]', '抗日战争时期', '', '伪职：海门（椒江）日军便衣密探；罪行：地痞投敌，刺探我方自卫队情报，引导日军登陆扫荡，告密抓捕爱国青年。；结局：被地方抗日自卫队锄奸处决。', '[]', '2026-09-10 09:57:14.088157', '2026-09-11 02:44:59.378911', '', '台州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8eb267d2263b4e1c88b66e4f37bd7f94', '赵振华', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江伊春丰林；黑龙江伊春；山东聊城；山东聊城东阿；山东聊城；山东聊城阳谷；山东聊城；黑龙江双鸭山；广西柳州三江', '[]', '[]', '抗日战争时期', '', '统领伪军配合日军对聊城、阳谷、莘县一带进行清乡扫荡，杀害抗日干部和群众。；在伪三江省推行协和会运动，进行奴化宣传，协助日军控制民众思想。；管辖包括聊城、东阿在内的鲁西伪政权，推行治安强化运动，镇压抗日活动。；伪满时期任佛山（今嘉荫）县伪县长，管辖范围与伊春北部接壤，协助日军推行殖民统治。；任伪县知事期间推行保甲制度，协助日军搜捕抗日人员。', '[]', '2026-09-10 09:57:14.017528', '2026-09-10 09:57:14.017528', '山东', '聊城', '东阿', NULL, NULL, NULL, NULL, '');
