INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8f1d6c2898ad4c37be5a9e77248b96a7', '王旭初', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州中原；河南郑州；河南郑州郑州经开区；山西阳泉城区；河南三门峡；河南开封祥符；河南开封；河南开封兰考；河南开封；河南开封通许；河南开封杞县；河南开封尉氏', '[]', '[]', '抗日战争时期', '', '日军侵占通许后出面组织维持会，后任伪县知事，为日军征粮派款、维持伪政权统治。；日军占领开封后出面组织维持会，后任伪开封市市长，协助日军推行殖民统治、征粮征丁。；日军占领开封后出面组织伪维持会，后任伪开封市市长，协助日军推行殖民统治、征发物资与劳工。；日军侵占开封后出面组织伪维持会，后任伪开封市市长，协助日军推行殖民统治、征发物资与劳工。；任伪豫北道尹，管辖豫北地区，推行日伪法令，配合日军扫荡。；日军侵占尉氏后出面组织维持会，后任伪县知事，为日军征粮派款、维持伪秩序。；日军占领开封后出面组织伪维持会，协助日军维持地方秩序、征发物资，并参与伪河南省政权的筹建与运作。；开封沦陷后出面组织伪维持会，协助日军维持地方秩序、征发物资，并参与伪河南省政权筹备。；郑州沦陷后组织伪维持会，后任伪郑县县长，为日军在郑州地区的统治提供地方行政支持，协助征发民夫、物资。；郑州沦陷后出面组织伪郑州维持会，后任伪郑县县长，为日军征集物资、维持地方秩序，是郑州地区伪政权代表人物。；日军侵占兰封后出面组织维持会，后任伪县知事，为日军征粮、派夫、维持伪统治秩序。；郑州沦陷后出面组织伪维持会，协助日军维持郑州城区及近郊治安，为日军征集物资、劳工，是郑州本地直接附逆的伪政权头目之一。；日军侵占开封后出面组织伪维持会，后任伪开封市市长，协助日军推行殖民统治、征发物资与劳工。；日军侵占杞县后出面组织维持会，后任伪杞县县长，协助日军征粮、派款、维持治安，镇压抗日群众。', '[]', '2026-09-10 09:57:14.045572', '2026-09-10 09:57:14.045572', '河南', '三门峡', '兰考', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8f20bb988eac4fc0b86d52e9271603a1', '张财旺', NULL, NULL, NULL, NULL, 'exact', 'exact', '郴县山川塘（今郴州市苏仙区）', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：为日军效力，日军投降后仍帮日军抓“花姑娘”，坏事做绝；结局：被郴州抗日武装押解回郴州，公审后枪决', '[]', '2026-09-10 09:57:14.073967', '2026-09-10 09:57:14.073967', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8f43046d3d674ee39c8e38108933ab92', '李某', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南永州零陵；湖南永州；广东江门；云南曲靖；安徽黄山；安徽黄山祁门；广西百色靖西；广西百色；湖北咸宁崇阳；湖北咸宁', '[\"佚名\", \"李少卿\", \"李朗鸡\", \"待考\", \"李少白\"]', '[]', '抗日战争时期', '', '百色地区抗战期间并非日军长期占领区，维持会记载极少，缺乏可靠姓名与事迹。；祁门沦陷期间任维持会会长，为日军服务。；在永州地区为日军充当翻译，协助日军与地方伪组织沟通，参与征敛与情报收集。；部分保甲长在日军占领期间被迫或主动为日伪征粮、派款、带路，战后多被追究。；在新会、江门地区掌管伪警察，配合日军清乡，镇压抗日群众。；在咸宁基层担任伪保甲长，为日军征粮、派夫、搜集情报。', '[]', '2026-09-10 09:57:13.985900', '2026-09-10 09:57:13.985900', '云南', '曲靖', '靖西', NULL, NULL, NULL, NULL, '');
