INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('8ffee5f63a4244479c512a0f521a0216', '刘发', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳坪山；广东深圳；广东深圳宝安；广东深圳南山；黑龙江鹤岗南山；广东清远；广东深圳福田；广东深圳；广东清远连州；广东清远；广东佛山三水', '[]', '[]', '抗日战争时期', '', '在宝安县（含今深圳、福田一带）组织伪维持会，配合日军推行保甲制度，征收粮税，镇压抗日群众。；在日军扶植下出任伪清远县县长，推行保甲制度，协助日军征粮、清乡，镇压抗日群众。；组织伪自卫队，配合日军在三水清乡，搜捕抗日游击队员及其家属。；在源潭一带为日军搜集情报、征发民夫，协助日军控制粤汉铁路沿线。；在宝安地区组建伪警察队伍，配合日军扫荡抗日游击队，逮捕和审讯抗日人员。；深圳沦陷后组织维持会，为日军提供情报、粮秣，并协助设立伪政权机构。；南头沦陷后出面组织维持会，为日军筹粮、拉夫、搜集情报，协助日军控制南头及南山一带。', '[]', '2026-09-10 09:57:14.026307', '2026-09-10 09:57:14.026307', '广东', '佛山', '三水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9006a1083c5040929786c4b29544c14d', '白志沂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西大同左云；黑龙江大庆大同；山西忻州五台山风景区；山西忻州；山西太原娄烦；山西阳泉矿区；山西阳泉；山西；山西忻州；山西忻州宁武；黑龙江大庆大同；山西阳泉；山西吕梁；山西_太原_阳曲；山西晋中左权；山西晋中；山西阳泉城区；山西阳泉', '[]', '[]', '抗日战争时期', '', '原阎锡山部军官，投日后在吕梁山区组织伪军，专门袭击八路军后方。；任伪晋北政厅厅长，管理大同、云州等县，推行日伪法令，强征粮税，协助日军建立维持会。；任伪晋北自治政府要职，后任伪晋北政厅厅长，管理大同及周边县份，配合日军“治安强化运动”，奴化教育民众。；在左云、大同地区组织伪警察队，配合日军“清乡”，杀害抗日家属，强征苛捐杂税，破坏地下党组织。；指挥伪保安队在娄烦山区“清剿”，杀害抗日村长和民兵数十人。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019568', '2026-09-10 09:57:14.019568', '山西', '吕梁', '左云', NULL, NULL, NULL, NULL, '');
