INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('91e0e17503e04891ad1c9b5d3caeed08', '王国英', NULL, NULL, NULL, NULL, 'exact', 'exact', '邵阳县', '[]', '[]', '抗日战争时期', '', '伪职：邵阳县维持会会长；罪行：老邵阳县北乡小水庙人，中央政校毕业，曾任国军第16师政治部主任等职。邵阳沦陷后被日寇任命为邵阳县维持会会长，协同日寇强迫城内未逃出的居民开“军民联欢会”，举行维持会正、副会长就职典礼。组织无赖之徒十余人充当维持会职员，下设宣传、民生、复兴、民政、建设、财务六科及警察局。借筹措办公费之名，派人深入城内各大商店和殷实人家掘地三尺挖掘金银财宝，抢夺粮食、猪、牛、羊等送给日寇；结局：1945年8月16日，国民革命军74军副师长杨明率部进入邵阳城，当晚即逮捕王国英及其同伙。王国英不久被判处死刑，执行枪决', '[]', '2026-09-10 09:57:14.087691', '2026-09-10 09:57:14.087691', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('91e71cbaaf59402fabd5fba52c991b72', '陈子惠', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄城；湖北十堰竹山；湖北十堰郧西', '[]', '[]', '抗日战争时期', '', '为日军筹款筹物，强制商户缴纳‘治安费’，协助日军经济掠夺。；在郧西地区组织伪维持会，配合日伪军警活动，协助征发民夫、粮食，维持日伪在鄂陕边界一带的基层统治。', '[]', '2026-09-10 09:57:14.054865', '2026-09-10 09:57:14.054865', '湖北', '十堰', '竹山', NULL, NULL, NULL, NULL, '');
