INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('91ec09b2997344d98d5cadc859402eb0', '宋文郁', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州三江；黑龙江哈尔滨道外', '[]', '[]', '抗日战争时期', '', '在三江地区推行“集团部落”，切断抗联与群众联系，导致大量平民死亡。；在道外区指挥特务活动，破坏抗联地下联络站，导致多名地下党员被捕牺牲。', '[]', '2026-09-10 09:57:14.066032', '2026-09-10 09:57:14.066032', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
