INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('926f438f92b548cdbb63afd14b007c46', '郭采芹', NULL, NULL, NULL, NULL, 'exact', 'exact', '邯郸贾村；河北_邯郸；河北邯郸丛台；河北邯郸；河北；河北邯郸邯郸冀南；河北邯郸复兴；河北邯郸', '[]', '[]', '抗日战争时期', '', '伪职：伪邯郸商会会长、冀南剿共军教导司令；搜刮粮棉资敌，训练伪军，指挥扫荡，杀害大量县区干部。；结局：邯郸解放被俘，公审枪决；伪职：伪邯郸商会会长、冀南剿共军教导司令；冀南头号大汉奸，为日军大量搜刮棉花粮食；训练伪军，参与指挥扫荡，在插箭岭杀害我方多名县区干部，纵容烟馆妓院毒害百姓。；结局：邯郸解放被俘，公审枪决；指挥伪警察搜捕抗日地下党员，破坏地下交通线，刑讯逼供抗日志士。；长期担任伪邯郸县知事，推行保甲制度，强征劳工，为日军提供情报，参与“治安强化运动”。；在丛台地区推行奴化教育，强制学校使用日伪教材，组织学生参加“中日亲善”活动，并检举有抗日思想的师生。；充当日军傀儡，征收苛捐杂税，强征民夫，配合日军扫荡。；组建伪警备队，配合日军扫荡抗日根据地，多次带队抓捕抗日干部和家属，烧毁村庄，抢劫民财，民愤极大。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.045062', '2026-09-10 09:57:14.045062', '河北', '邯郸', '丛台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9273ce85147e427f874cd620df275168', '尚振华', NULL, NULL, NULL, NULL, 'exact', 'exact', '舞阳县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：1945年2月新四军围歼史聘侯部后，调集舞阳北舞渡皇协军2000余人，驻扎到尹集镇周围10个村，企图围困新四军', '[]', '2026-09-10 09:57:14.083022', '2026-09-10 09:57:14.083022', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
