INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('927e98e4723945fc9bff678aece8e4cf', '郑梅轩', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州常山', '[]', '[]', '抗日战争时期', '', '任伪县长期间推行保甲制度，强征壮丁，配合日军经济掠夺，破坏抗日组织', '[]', '2026-09-10 09:57:14.052196', '2026-09-10 09:57:14.052196', '浙江', '衢州', '常山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('928110bf850144e3a12bc40a3c04692e', '周文达', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江舟山定海；浙江宁波慈溪；浙江温州乐清；浙江温州洞头；浙江_丽水_缙云；浙江台州椒江；浙江台州；浙江宁波象山；浙江宁波；浙江温州泰顺；浙江舟山嵊泗；浙江宁波北仑；浙江丽水青田；浙江丽水；浙江_金华_永康；浙江_台州_仙居', '[]', '[]', '抗日战争时期', '', '为日军提供丽水、青田一带抗日武装的部署情报，参与策划“清乡”行动。；指挥伪警察搜捕抗日分子，刑讯逼供，破坏地下交通站。；在日军占领期间任伪警察局长，负责清查抗日分子，实施保甲制度，协助日军强征物资。；为伪政权征收苛捐杂税，搜刮民财，将大量钱粮上缴日军，并贪污抗日物资，导致地方经济凋敝。；在北仑柴桥一带为日军效力，提供情报，组织汉奸武装，欺压百姓。；为日伪效忠，抓捕抗日志士，破坏地下抗日组织，参与“清乡”行动。；指挥伪警察搜捕抗日地下党员，破坏情报网络，协助日军在洞头设立检查站。；在嵊泗列岛组织伪维持会，为日军提供情报，协助日军封锁海面，抓捕抗日志士。；为日军统制宁波商业，强迫商户捐献物资，中饱私囊。；为日军筹措军饷，控制定海商业贸易，强制商户缴纳“慰劳金”，从中牟利，并协助日军掠夺战略物资。；为伪政府征收苛捐杂税，侵吞抗日家属财产，逼死多名抗属。；率伪保安队多次袭击台州沿海抗日游击队，在椒江口设卡盘查，逮捕抗日交通员。；率伪保安队协助日军扫荡，捕杀抗日军民，破坏中共地下组织。', '[]', '2026-09-10 09:57:14.049601', '2026-09-10 09:57:14.049601', '浙江', '丽水', '青田', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92828687923141b78c47222c890ddaee', '黄自强', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京栖霞；广西南宁；江西_上饶_余干；江西宜春；江西九江；湖南_益阳_益阳大通湖管理；安徽安庆；江西吉安；湖南常德；湖南株洲醴陵；江西萍乡湘东；江苏南京；湖南衡阳；湖南衡阳衡南；江西九江庐山；江西九江；湖南长沙；江西九江彭泽；江西九江；江西南昌；江西南昌东湖；湖南衡阳耒阳；湖南衡阳；湖南_湘西_泸溪；湖南_永州_零陵；江苏南京浦口；湖南邵阳武冈；辽宁沈阳大东；湖南郴州；湖北荆州沙市；湖南邵阳新宁；江西上饶广丰；云南普洱西；福建漳州东山；黑龙江鹤岗东山；江西南昌青云谱；江西宜春；云南普洱西；汪伪江西省政府（省治九江）；云南普洱西；江西南昌；广西贺州；云南普洱西；福建晋江；云南普洱西；江西九江', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪江西省省长兼驻九江绥靖主任；罪行：1945年3月出任江西省长，为日军在赣北沦陷区做最后阶段的殖民统治；结局：1945年8月日本投降后随汪伪政权覆灭，最终结局史料未明确记载（来源：曾任汪伪军事委员会政治部部长、政治保卫总署总监，为汪伪政权特务系统头目）；伪任职务：汪伪末代伪江西省省长、九江绥靖主任。结局：抗战胜利逃往台湾，后被枪击身亡', '[]', '2026-09-10 09:57:14.006313', '2026-09-10 09:57:14.006313', '广西', '南宁', '栖霞', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('928737cfc1d94e019d24af67a5f1de18', '赵文斌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治沁源', '[]', '[]', '抗日战争时期', '', '编写反共宣传材料，强迫村民参加“庆祝会”，破坏抗日舆论。', '[]', '2026-09-10 09:57:14.024243', '2026-09-10 09:57:14.024243', '山西', '长治', '沁源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92a9a26837b54e1f9351579adbb8313d', '陆少家', NULL, NULL, NULL, NULL, 'exact', 'exact', '余姚盐区', '[]', '[]', '抗日战争时期', '', '伪职：伪余姚福寿乡事务员；罪行：基层伪爪牙，告密抗日人员，协助日伪清乡，压榨盐民百姓。；结局：根据地抗日武装抓捕，教育释放后仍继续通敌，后被镇压。', '[]', '2026-09-10 09:57:14.084000', '2026-09-10 09:57:14.084000', '浙江', '宁波', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92abafb1dd5f476188100f0ea764d6c9', '常建邦', NULL, NULL, NULL, NULL, 'exact', 'exact', '潞城', '[]', '[]', '抗日战争时期', '', '伪职：伪潞城县参议员，原我方参议员叛变；罪行：公开投敌，出卖根据地情报，破坏潞城地下组织。；结局：被抗日政府逮捕处决。', '[]', '2026-09-10 09:57:14.073471', '2026-09-10 09:57:14.073471', '山西', '长治', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92b0a0baf1694696bca8633ea4f9b5b5', '杨泽普', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪三河县县长；管控冀东与平北通道，修筑炮楼，搜捕抗日人员。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.070193', '2026-09-10 09:57:14.070193', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92d70c17d1ca445a952b699828277a6e', '陈志远', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；江苏南通海安；云南玉溪通海；河北唐山曹妃甸；浙江丽水青田；河南郑州中牟；浙江宁波象山；浙江温州；浙江_衢州_江山；浙江台州黄岩；浙江温州永嘉；浙江温州；浙江温州瑞安；浙江温州文成；浙江温州平阳；河北；浙江温州洞头；辽宁沈阳大东；河北秦皇岛北戴河；浙江_丽水_龙泉；河北_唐山_唐山高；浙江金华浦江；浙江金华；浙江温州乐清；浙江金华永康；辽宁沈阳大东；河北唐山唐山汉沽管理；广东深圳盐田；浙江温州泰顺；浙江温州龙港；浙江温州；江苏镇江句容', '[]', '[]', '抗日战争时期', '', '在汉沽管理地区（今汉沽管理区）设立伪政权，管理盐田和农场，为日军提供食盐和粮食，镇压当地反抗。；推行奴化教育，强制学校教授日语，删改历史教材，迫害爱国教师，组织学生参拜神社。；管辖包括曹妃甸周边区域，为日军提供情报，强征劳工，迫害抗日家属。；组织新民会分会，在路南各村推行“中日满亲善”宣传，收集抗日情报。；在抚宁县及北戴河周边地区为日军征粮派款，组织伪自卫团，协助日军扫荡抗日根据地。', '[]', '2026-09-10 09:57:14.034273', '2026-09-10 09:57:14.034273', '江苏', '南通', '海安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92e9c361b07445f8987bbefcd785bcaa', '章宝琛', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_绍兴_越城', '[]', '[]', '抗日战争时期', '', '指挥伪警配合宪兵队搜捕地下党员和抗日志士，参与‘清乡’行动，刑讯逼供，制造多起血案。', '[]', '2026-09-10 09:57:14.052062', '2026-09-10 09:57:14.052062', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
