INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('92ff2e15b7af45dc8ef394ef02613602', '孟光恒', NULL, NULL, NULL, NULL, 'exact', 'exact', '阳城', '[]', '[]', '抗日战争时期', '', '伪职：原国民党党部书记长，日伪大特务；罪行：十二月事变后率人马集体投日；组建特务网络，渗透太岳根据地，刺探情报、策反我方人员，破坏地下组织。；结局：抗战胜利后逮捕审判', '[]', '2026-09-10 09:57:14.072918', '2026-09-10 09:57:14.072918', '山西', '晋城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('930e6ddd86f6480a876b00fec1d0fb6a', '陈维伦', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_南京', '[]', '[]', '抗日战争时期', '', '推行保甲制度，控制民众', '[]', '2026-09-10 09:57:14.033483', '2026-09-10 09:57:14.033483', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('930ed18f8c034a78a42644086ff1e188', '宋占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治屯留；河北邯郸曲周；山西、河北', '[]', '[]', '抗日战争时期', '', '专门刺探八路军情报，带领特务队突袭抗日村庄，逮捕并杀害抗日积极分子。；在曲周县第二区（今河南疃一带）为日军效力，强抓壮丁补充伪军，并强迫村民报告八路军行踪，致使多名游击队员牺牲。', '[]', '2026-09-10 09:57:14.024122', '2026-09-10 09:57:14.024122', '山西', '长治', '屯留', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9316bf1319854ad7b843b70ff1f1d9ef', '关成山', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯向阳；黑龙江佳木斯；黑龙江伊春金林；黑龙江伊春；黑龙江齐齐哈尔；黑龙江哈尔滨宾县；黑龙江哈尔滨；吉林松原前郭尔罗斯；吉林松原；黑龙江大兴安岭呼玛；黑龙江哈尔滨依兰；黑龙江齐齐哈尔富裕', '[]', '[]', '抗日战争时期', '', '伪满时期在勃利、佳木斯一带任保甲长及伪自卫团团长，推行保甲连坐，配合日军搜捕抗日人员，欺压当地百姓。；原地方警察，投敌后任依兰警务科长，抓捕抗日志士，迫害百姓。；原富裕县地主，投日后任协和会会长，组织汉奸宣传队，煽动民众告发抗联活动；率伪保安队多次袭击抗日联军小分队，在松原、扶余一带杀害抗日军民。；在伊春地区担任伪警察头目，配合日军维持治安，镇压当地抗日民众，推行保甲连坐制度。；率保安队配合日军“讨伐”抗联，在呼玛县金山镇等地杀害抗联伤员，抢夺群众粮食。；投敌后任伪龙江省长，管辖今齐齐哈尔及大庆部分地区，参与伪满地方统治。；原哈尔滨警察，投日后任特务科长，专门侦破抗联地下联络站，在宾县、哈尔滨逮捕并处决多名共产党员。', '[]', '2026-09-10 09:57:13.998952', '2026-09-10 09:57:13.998952', '吉林', '松原', '前郭尔罗斯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('931f313b5cd34dc587052b7a13fc3ad9', '赵安国', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶广丰', '[]', '[]', '抗日战争时期', '', '日军侵占广丰期间组织伪保安队，配合日军扫荡、搜捕抗日人员。', '[]', '2026-09-10 09:57:14.037928', '2026-09-10 09:57:14.037928', '江西', '上饶', '广丰', NULL, NULL, NULL, NULL, '');
