INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('932b01337e7c4520b3be90ce25183617', '魏禄荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '汝南县/平舆县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（唆策者）；罪行：1944年河南战役中，驻扎在汝南县城的日寇在汉奸魏禄荣的唆策之下，纠集其他各处据点的日寇上千人，大举东犯，扫荡平舆杨埠庙湾一带，打响了白龙王庙之战', '[]', '2026-09-10 09:57:14.068907', '2026-09-10 09:57:14.068907', '河南', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('932b1f8b2cea41bbbf3ef59c707a61a4', '杨振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北沧州；河北沧州青县；河北沧州运河；北京延庆；北京、山西、河北；山西大同平城；黑龙江大庆大同；云南昆明盘龙；云南昆明；北京房山；北京顺义；河北张家口；河北秦皇岛卢龙', '[]', '[]', '抗日战争时期', '', '专门收集平北八路军情报，多次带领日军偷袭延庆北部村庄，造成抗日干部牺牲。；为日军征收各种苛捐杂税，贪污抗日家属财产，协助日伪经济封锁。；日军占领顺义后率先投敌，组织维持会，为日军筹集粮款，引导日军清乡。；任伪大同宣抚班班长，随日军进行“宣抚”活动，诱骗民众归顺，收集抗日情报，破坏群众抗日团体。；为日伪法庭审判抗日志士，判处多人死刑或长期监禁。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.985774', '2026-09-10 09:57:13.985774', '云南', '昆明', '盘龙', NULL, NULL, NULL, NULL, '');
