INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('94168dfa4fa744019f889dc724f62d31', '王性初', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台海阳；辽宁沈阳大东；山东烟台莱阳；山东烟台；山东烟台烟台经开区；山东烟台；山东烟台烟台高；江苏南京栖霞；山东烟台；山东烟台招远', '[]', '[]', '抗日战争时期', '', '在烟台莱阳地区投敌，出任伪县长，配合日军进攻抗日根据地。；在烟台栖霞地区任职伪县长，配合日军扫荡抗日根据地。；在海阳地区推行奴化教育，宣传“大东亚共荣”，协助日伪进行文化侵略。；招远沦陷后组织维持会，任伪县长，协助日军掠夺招远金矿资源，镇压抗日军民。；烟台沦陷后依附日军，控制商会为日军筹措物资、资金，协助推行伪币和配给制度，属经济领域附逆者。', '[]', '2026-09-10 09:57:14.017143', '2026-09-10 09:57:14.017143', '山东', '烟台', '海阳', NULL, NULL, NULL, NULL, '');
