INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('947805612bb84ff187189d6654b42c98', '吴金彪', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州', '[]', '[]', '抗日战争时期', '', '浙江杭州人，任伪杭州市商会会长，为日军统购物资，垄断粮食、丝绸贸易，从中牟利，资助伪政权。', '[]', '2026-09-10 09:57:14.051141', '2026-09-10 09:57:14.051141', '浙江', '杭州', '临安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('947a8c1887e9491abda2020314b9c797', '张鸣岐', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建漳州漳浦；福建漳州；福建_福州_晋安；福建_莆田；福建漳州云霄；福建漳州；山东滨州无棣；山东滨州；福建厦门思明；福建厦门；黑龙江鹤岗东山；福建泉州惠安；福建福州；福建漳州', '[]', '[]', '抗日战争时期', '', '在福建伪政权中任职，参与厦门地区伪行政事务，协助日军推行殖民统治。；在伪福建省政权中主管财政，为日伪筹措军费、推行伪币。；汕头沦陷后任伪市长，其伪政权与闽南伪政权勾结，在闽粤沿海包括漳州、东山附近海域进行走私和情报活动。；原北洋政客，抗战期间在福建沦陷区出任伪职，协助日军推行保甲制度，其指令涉及漳州、漳浦等地的伪政权组建与物资征调。；福建地方人物，参与伪福建省政府，协助日军在福建推行伪化行政。；抗战期间投靠日军，在鲁北道（辖滨州、无棣等地）推行伪政，协助日军征粮、抓丁、维持治安，镇压抗日力量。；北洋旧官僚，抗战初期投靠日军，出任伪福建省主席，在福州、厦门等地推行伪化，其政令影响泉州、惠安。；原北洋旧官僚，抗战期间投靠日军，出任伪福建省主席，统辖包括漳州在内的福建沦陷区伪政权。；在闽南地区组织伪军，配合日军扫荡抗日力量，活动于漳州、云霄、诏安一带。', '[]', '2026-09-10 09:57:14.016485', '2026-09-10 09:57:14.016485', '山东', '滨州', '无棣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('94868afe8dfc4765938655eabe7a5706', '陈子云', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东阳江；广东湛江遂溪；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在阳江任伪警察局长，配合日军搜捕抗日人士，镇压阳江、江城一带民众抗日活动。；在遂溪推行奴化教育，协助日军控制学校，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.029784', '2026-09-10 09:57:14.029784', '广东', '湛江', '遂溪', NULL, NULL, NULL, NULL, '');
