INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('950c739710844848842b3888b9bc0feb', '郭登瀛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西_大同_云州；山西晋中平遥；黑龙江鹤岗南山；山西；山西忻州岢岚；山西吕梁交口；山西吕梁；山西_忻州_原平；山西忻州；山西忻州代县；山西太原古交；山西吕梁孝义；山西太原清徐；山西太原', '[]', '[]', '抗日战争时期', '', '在临县（今吕梁临县）为日军收集八路军情报，破坏抗日组织。；带领警备队协助日军在交口双池、桃红坡等地设卡盘查，逮捕抗日军民，并参与对八路军小股部队的伏击。；收编散兵游勇组成伪军支队，在孝义、汾阳交界处设卡收税，抢劫商旅，多次袭击八路军运输队。；负责伪警察事务，协助日军搜捕抗日分子，实施“连坐”制度，迫害无辜民众。；推行日伪“治安强化”运动，在古交各村设立伪村公所，强征捐税。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019516', '2026-09-10 09:57:14.019516', '山西', '吕梁', '交口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('950df6474089490593567a699ca2afd2', '魏新民', NULL, NULL, NULL, NULL, 'exact', 'exact', '岳阳洪山', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（告密者）；罪行：与李永寿一同向日军谎报军情，诬控洪山、昆山、三旗港等地是“游匪”聚集区，怂恿日军制造“洪山血案”', '[]', '2026-09-10 09:57:14.071959', '2026-09-10 09:57:14.071959', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
