INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9546388348c844cbb0c60152c60f840a', '李永祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山滦州；河北唐山；吉林白山靖宇', '[]', '[]', '抗日战争时期', '', '在唐山地区参与“三光”政策，烧毁村庄。', '[]', '2026-09-10 09:57:14.000063', '2026-09-10 09:57:14.000063', '吉林', '白山', '靖宇', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('954a55f2963842e29fdcf9452f8eeba4', '徐绍卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林长春农安；吉林长春长春汽车经开区；吉林长春二道；黑龙江佳木斯郊区；辽宁_抚顺；辽宁_沈阳_和平；吉林长春；辽宁锦州；吉林_长春_朝阳；辽宁辽阳弓长岭；辽宁抚顺东洲；辽宁抚顺；吉林、辽宁；辽宁_沈阳_大东；吉林；辽宁本溪南芬；辽宁抚顺新宾；河南平顶山；辽宁沈阳；吉林长春双阳', '[]', '[]', '抗日战争时期', '', '伪职：伪锦州省首任省长（华人）；罪行：伪满早期封疆大吏；主持锦州省全套殖民统治，推行保甲、集团部落，强征粮食、壮丁，残酷镇压辽西抗日义勇军。；结局：1945 被苏军逮捕，关押抚顺战犯管理所，后病死狱中。；在长春县（今长春郊区）强征土地，组织“自卫团”对抗抗日游击队；在农安地区强制推行“粮谷出荷”，搜刮农民粮食，抓捕抗日群众。；在双阳地区推行日伪政权，组织伪自卫团，镇压当地抗日武装。；在长春推行“市街整理”，强征土地，迫害中国居民。；继任伪新京市长，执行日伪市政管理，压制市民抗日情绪。……（共涉及16个地区的犯罪记录）；伪职：伪新京特别市市长、伪锦州省省长；罪行：先后主政新京、锦州，推行保甲、集团部落，强征粮饷，镇压义勇军。；结局：苏军逮捕，关押抚顺战犯管理所，狱中病死吉林省地方...。', '[]', '2026-09-10 09:57:14.000833', '2026-09-10 09:57:14.000833', '吉林', '长春', '二道', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('955dbf212e8c4d949570cc8a29c5be1e', '吴则虞', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城', '[]', '[]', '抗日战争时期', '', '安徽宣城人，在伪安徽省教育系统任职，推行奴化教育。', '[]', '2026-09-10 09:57:14.007982', '2026-09-10 09:57:14.007982', '安徽', '宣城', '绩溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('955e7022cd8143c9a35268ce56c4ab92', '张资平', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北黄冈红安；湖北武汉；广西柳州；陕西_西安_长安；广东梅州梅县；安徽阜阳阜阳经开区；广东梅州梅县；江苏南京；云南普洱西；江西宜春万载；江西宜春；广东梅县', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：上海文化汉奸，日伪刊物撰稿，鼓吹大东亚理论。结局：抗战胜利被捕判刑，刑满释放后病逝', '[]', '2026-09-10 09:57:14.010883', '2026-09-10 09:57:14.010883', '安徽', '阜阳', '阜阳经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('955eb93849d64045a3d3f4db6ee66e70', '公茂文', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东临沂蒙阴', '[]', '[]', '抗日战争时期', '', '任伪蒙阴县知事期间，配合日军清乡、扫荡，强征民夫，修筑据点，镇压抗日活动。', '[]', '2026-09-10 09:57:14.012830', '2026-09-10 09:57:14.012830', '山东', '临沂', '蒙阴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('956c013bf44a4478907efde9f94ea733', '张邦翰', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明石林；云南昆明；云南昆明官渡；云南_昆明_寻甸；云南保山；云南昆明；云南昆明；江苏南京；云南_昆明_西山；云南昆明五华；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '原为云南地方官员，抗战期间投靠日伪，出任伪昆明市市长，协助日军维持昆明地区治安，推行伪化教育。；抗战期间投靠日伪，参与组织伪云南省维持会，协助日军在云南推行殖民统治，后任伪云南省政府委员，为日伪政权筹措物资、宣传‘大东亚共荣圈’。；部分地方史料提及昆明地区曾有维持会活动，但具体人名、职务多不可考，张邦翰是否确为汉奸存在争议。；张邦翰系云南昆明人，早年追随汪精卫，抗战期间在南京汪伪政权中活动，曾参与策划在云南建立伪政权的图谋，但因云南抗日力量强大未能得逞。其活动范围涉及昆明及周边地区。；张邦翰为云南籍，曾与汪伪政权有联系，被列入汪伪拟任云南伪政府人员名单，但因云南未沦陷，未实际赴任。；云南籍人士，抗战期间曾被汪伪方面接触拉拢，但未见可靠史料证明其出任伪职。此条为排除性说明，非汉奸。；云南籍人士，曾为国民政府官员。抗战期间有日伪接触传闻，但无确凿附逆任职记载，不宜列为汉奸。；云南籍人士，未见可靠汉奸记录；此条仅作排除性说明，非汉奸。', '[]', '2026-09-10 09:57:13.979863', '2026-09-10 09:57:13.979863', '云南', '保山', '五华', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('956c3945a80745c08411e7e2daa2b02a', '钱光祖', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵枞阳', '[]', '[]', '抗日战争时期', '', '协助日军建立枞阳伪政权，强迫百姓领取“良民证”，为日军提供情报', '[]', '2026-09-10 09:57:14.010662', '2026-09-10 09:57:14.010662', '安徽', '铜陵', '枞阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('956f18f411df41fb89632810e951b051', '曹荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州海珠；广东广州；广西柳州鹿寨；广东佛山顺德；广东广州荔湾；广东广州；广东佛山南海；广东佛山；广东广州增城；广东广州；广东广州；广东广州白云；广东广州；广东广州越秀；广东广州；广东广州番禺；广东广州增城', '[]', '[]', '抗日战争时期', '', '日军侵占增城后出面组织维持会，为日军筹粮、派夫、维持地方伪秩序。；在增城地区建立伪政权，协助日军控制广州东部，镇压当地抗日力量。；汪伪广东伪军头目之一，参与指挥伪军配合日军在广州及珠江三角洲地区扫荡抗日武装。；广东伪军头目之一，在广州外围及珠三角地区配合日军行动。；东莞地区伪政权头目，曾任伪东莞县长，协助日军维持东莞占领区统治。；组织伪自卫武装，协助日军清乡，在南海、佛山地区搜捕抗日分子，强征粮食劳工。；在珠江口及广州外围地区组织伪军，配合日军封锁、扫荡东江抗日根据地。；在番禺沦陷区担任伪警察头目，协助日军维持地方治安、搜捕抗日人员。；广东增城附逆人物，任伪县长并组织伪军，配合日军在增城、广州东北部地区活动。；广东地方伪维持会头目，协助日军控制顺德地区，活动区域与广西邻近。', '[]', '2026-09-10 09:57:14.026424', '2026-09-10 09:57:14.026424', '广东', '佛山', '南海', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9574f1a6d4d54c3dbac991368229f044', '张锡禄', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大庆杜尔伯特', '[]', '[]', '抗日战争时期', '', '投敌后任伪安达县县长，安达邻近大庆、杜尔伯特，其配合日军征粮、征劳工，推行保甲制度。', '[]', '2026-09-10 09:57:14.066205', '2026-09-10 09:57:14.066205', '黑龙江', '大庆', '杜尔伯特', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9575012b5b8f4c66bbc21e69c0d21dfe', '黄希文', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪磁县县长（知事）；精通日语，推行奴化教育，掠夺彭城陶瓷资源，组织伪警备队扫荡磁西山区。；结局：抗战胜利逮捕，判处长期监禁；伪职：伪磁县县长（知事），精通日语；编纂伪磁县县志，推行奴化教育，管控彭城陶瓷产业为日军掠夺资源，组织伪警备队扫荡磁西山区根据地邯郸日报社。；结局：抗战胜利逮捕，判处长期监禁', '[]', '2026-09-10 09:57:14.083608', '2026-09-10 09:57:14.083608', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
