INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95a4b09eaf7147daa13477c40c43b347', '农某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西百色田东', '[\"农福廷\"]', '[]', '抗日战争时期', '', '投靠日军后组建伪保安队，配合日军扫荡田东及周边乡村，镇压抗日力量，强征粮食和劳工，残害百姓。', '[]', '2026-09-10 09:57:14.032894', '2026-09-10 09:57:14.032894', '广西', '百色', '田东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95ad37dc84f2491b8f674c5b2a909f60', '曹承宗', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁辽阳文圣；辽宁_丹东_振兴；辽宁鞍山海城；辽宁鞍山；黑龙江鸡西城子河；黑龙江鸡西；辽宁丹东宽甸；辽宁丹东元宝；辽宁丹东振安；辽宁丹东；辽宁；辽宁辽阳太子河；辽宁大连普兰店；辽宁铁岭；辽宁丹东东港；辽宁沈阳；辽宁鞍山台安；辽宁丹东凤城', '[]', '[]', '抗日战争时期', '', '任伪安东市（今丹东）市长，推行日伪经济统制，强征劳工，协助日军建立治安维持会，镇压市民反抗。；活动于东港、凤城一带，率伪军配合日军围剿抗日义勇军，烧毁村庄，残害百姓。；原凤城县地方士绅，投日后任伪满凤城县县长，在凤城地区推行保甲制度，强征劳工，镇压抗日义勇军。；首任伪宽甸县长，协助日军建立伪政权，强征民夫修建警备道路和碉堡，镇压当地抗日义勇军。；任伪安东市长期间，推行日伪经济统制，强征劳工，镇压市区抗日活动。……（共涉及14个地区的犯罪记录）；伪职：伪安东省末代省长；罪行：伪满后期安东省华人最高长官；执行战时物资搜刮，强征劳工、粮食；日本投降后牵头组织安东维持会，企图等待国民党接收。；结局：被俘，以汉奸罪判处重刑。', '[]', '2026-09-10 09:57:14.062690', '2026-09-10 09:57:14.062690', '辽宁', '丹东', '元宝', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95aee73dca924ad881c679dbb4591d07', '杨呆子', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西玉山', '[]', '[]', '抗日战争时期', '', '伪职：附日密探；罪行：私通日军，身上搜出日本银币，头发标记“大日本”字样，被游击队抓获枪决；来源：玉山之窗党史资料；备注：浙赣战役时期，为外号，无完整正式姓名记载', '[]', '2026-09-10 09:57:14.071342', '2026-09-10 09:57:14.071342', '江西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95b0c69830974dda9655c0072af39dd5', '高松坡', NULL, NULL, NULL, NULL, 'exact', 'exact', '章丘/淄博；山东淄博桓台；山西阳泉矿区；山东济南济南高；山东济南；山东济南章丘；山东济南；山东泰安；辽宁沈阳新民；山东淄博张店；山东淄博；山东泰安宁阳；山东泰安；山东济南莱芜；山东济南钢城；山东济南；山东济南莱芜；山东济南', '[]', '[]', '抗日战争时期', '', '伪职：山东“剿共”军司令；罪行：1941年春率部投靠日军，被编为山东“剿共”军任司令。随日军不断窜扰章丘、淄博、莱芜抗日根据地，组成暗杀团专门杀害地下党员、八路军伤病员和抗日群众', '[]', '2026-09-10 09:57:14.014787', '2026-09-10 09:57:14.014787', '山东', '泰安', '宁阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95b38059f81e420d956ab92b0475c099', '柴九思', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾襄汾；山西临汾洪洞；山西；山西运城河津', '[]', '[]', '抗日战争时期', '', '率伪警备队多次配合日军“扫荡”汾城、襄陵一带，杀害抗日军民，抢劫物资，烧毁村庄。；组织维持会迎接日军，协助建立伪政权，摊派粮款，为日军带路袭击村庄。', '[]', '2026-09-10 09:57:14.019220', '2026-09-10 09:57:14.019220', '山西', '临汾', '洪洞', NULL, NULL, NULL, NULL, '');
