INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95b9d1fba7bd4b0d9645d041ebaae1d7', '刘起时', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关新丰；广东韶关始兴', '[]', '[]', '抗日战争时期', '', '始兴县汉奸，组织维持会为日军服务，协助日军在韶关南部地区的统治。', '[]', '2026-09-10 09:57:14.030361', '2026-09-10 09:57:14.030361', '广东', '韶关', '新丰', NULL, NULL, NULL, NULL, '');
