INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95e48df115aa49878b16aa6b210a6570', '孙志英', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城建湖；江苏盐城', '[]', '[]', '抗日战争时期', '', '率伪军多次袭击新四军游击队，杀害地方干部和群众，烧毁村庄，抢夺粮食，是日伪在盐城地区的主要帮凶。', '[]', '2026-09-10 09:57:14.036508', '2026-09-10 09:57:14.036508', '江苏', '盐城', '建湖', NULL, NULL, NULL, NULL, '');
