INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('95feb1b084ef4d4cb56f84f8114e2b85', '唐绍武', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '重庆袍哥组织首领之一，在沙坪坝及重庆地区活动。抗战期间与地方军政势力有联系，但无可靠证据表明其任伪职或附逆。', '[]', '2026-09-10 09:57:14.064259', '2026-09-10 09:57:14.064259', '重庆', '沙坪坝', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('96027c0771ee47f58078e6599e2207f5', '苏成德', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州；贵州贵阳息烽；浙江丽水庆元；浙江宁波；浙江宁波；安徽安庆；广西桂林兴安；云南普洱西；江苏南京；陕西渭南华州；陕西渭南；上海_松江；安徽芜湖；上海长宁；安徽合肥；安徽_阜阳_界首；江苏南京鼓楼；上海杨浦；上海徐汇；安徽滁州天长；江苏南京；安徽宣城宣城经开区；江苏南京浦口；陕西_西安；江苏南京浦口；江苏南京；浙江杭州；安徽马鞍山雨山；安徽马鞍山；湖南长沙；黑龙江佳木斯郊区；浙江_杭州_余杭；湖南湘西泸溪', '[]', '[]', '抗日战争时期', '', '汪伪特务头目，其活动范围涉及安徽东部，镇压抗日组织。；山东人，汪伪特工头目，在南京及周边地区镇压抗日力量，势力涉及江西部分沦陷区。；在贵州安插伪警察人员，息烽一带曾有其训练的伪警活动。；山东人，抗战期间投敌，任伪特工总部南京区区长、伪首都警察厅长，其特务与警察活动涉及江西沦陷区。；汪伪特务与警察头目，在南京负责伪警察与特务活动，迫害抗日人士。；原国民党军官投敌，任伪浙江省保安副司令，组织伪军配合日军“清剿”抗日武装，制造多起惨案。；汪伪特工骨干，在南京及周边包括马鞍山、当涂一带进行特务活动，迫害抗日人士。；湖南人，汪伪特工成员，参与华中地区伪特工活动，与长沙有间接关联。；汪伪特务头目，在安徽沦陷区进行特务活动，镇压抗日力量。；在南京、浦口地区领导特工暗杀和情报活动，残害抗日志士。；继续领导伪警察，镇压南京地区抗日活动。；汪伪政权安徽警务头目，负责安徽沦陷区警察系统，配合日军镇压抗日力量。；山东人，但长期在浙江任职，投日后任伪浙江省警察厅长，在杭州、滨江地区设立关卡，搜捕抗日分子，勒索商民。；参与76号特工在南京的行动，暗杀抗日志士。；投敌后任伪首都警察总监，协助日军。；汪伪特工头目，在安徽合肥等地建立特务组织，搜捕抗日人士。；在安庆推行伪警察统治，设立关卡，盘查抗日人员，参与“清乡”行动。；76号特工出身，后任南京伪警察厅长，镇压抗日活动；在鼓楼区推行“新国民运动”，强制民众效忠汪伪。；在广西地方协助日军维持占领区秩序，参与组织维持会，为日军提供物资与情报支持。；在宁波、象山等地建立伪警察体系，搜捕抗日地下党员。；其特工活动涉及湖南沦陷区部分城市。；指挥伪保安队在杨浦地区巡逻、镇压罢工和抗日活动。；汪伪特工要员，与陕西渭南地区无直接关联。；浙江人，汪伪政权警务官员，在浙江负责伪警察系统，协助日军维持治安、镇压抗日。；在宁波余姚建立伪警察系统，协助日军抓捕抗日分子，实施白色恐怖。；在长宁区（如中山公园一带）指挥特务活动，搜捕地下抗日人员，破坏抗日组织。；湖南籍相关人物常被提及，汪伪特工与警察系统头目，在南京地区镇压抗日活动。；在芜湖建立秘密监狱，严刑拷打抗日志士，杀害新四军联络员。；在南京指挥伪警察，搜捕抗日分子，镇压学生和工人运动；指挥伪保安部队协助日军扫荡，破坏抗日地下组织。；汪伪政权特工要员，任伪特工总部南京区区长、伪首都警察厅长等职，镇压抗日力量。；汪伪政权特工要员，任伪特工总部南京区区长、伪首都警察厅长等职。；在杭州实施白色恐怖，设立特务据点，严刑拷打抗日嫌疑犯，制造“杭州监狱惨案”。；在徐汇区指挥警察镇压罢工和抗日活动，抓捕进步人士。；在南京市区及江宁郊区实施特务统治，残害百姓。；浙江杭州人，曾任伪浙江省保安司令部参谋长，在临安、余杭等地指挥伪军“扫荡”，烧毁村庄，屠杀抗日群众。；浙江温州人，汪伪政权警务官员，曾任伪浙江省警务处处长，协助日军维持治安，镇压抗日活动。', '[]', '2026-09-10 09:57:13.976493', '2026-09-10 09:57:13.976493', '上海', '长宁', '宣城经开区', NULL, NULL, NULL, NULL, '')