INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9686bce3a10c4dfc96f43c15f4dd2eab', '邢士廉', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林松原宁江；吉林舒兰；辽宁_大连_旅顺口；河北承德隆化；黑龙江哈尔滨；吉林白城大安；内蒙古赤峰林西；吉林；辽宁沈阳铁西；黑龙江哈尔滨松北；吉林长春榆树；吉林；黑龙江齐齐哈尔昂昂溪；黑龙江齐齐哈尔；吉林、河北、辽宁；黑龙江牡丹江西安；黑龙江齐齐哈尔；辽宁沈阳；吉林白城白城经开区；吉林白城；黑龙江哈尔滨松北；黑龙江齐齐哈尔；黑龙江黑河北安；黑龙江齐齐哈尔；吉林白城镇赉；吉林白城；吉林长春；辽宁阜新；吉林延边图们；吉林；吉林；吉林；内蒙古赤峰林西', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪满军事部大臣，伪满上将；罪行：原东北军投敌；掌管伪满军事，指挥伪军讨伐抗联，推行集家归屯。；结局：苏军逮捕，抚顺战犯管理所，1954 年狱中病死吉林省地方...。；曾任伪吉林省长，推行日伪统治政策，参与经济掠夺和奴化教育。；原东北军将领，投日后任伪满吉林省省长，在吉林地区推行日伪统治，强征劳工，镇压抗日活动。；原东北军旅长，投日后任伪吉林省长，在昌邑及周边推行保甲制度，协助日军清乡。；在吉林地区推行“治安肃正”，指挥伪军配合日军对桦甸山区进行反复“扫荡”，杀害抗联战士及无辜百姓。；原东北军将领，投日后负责伪满治安，参与围剿抗联。……（共涉及18个地区的犯罪记录）；伪任职务：伪满治安部大臣、第 4 军管区司令官，伪满上将，镇压东北抗联。结局：苏军俘获，抚顺战犯管理所，1954 年病亡狱中', '[]', '2026-09-10 09:57:13.995418', '2026-09-10 09:57:13.995418', '吉林', '延边', '图们', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9686db6437d349cb8ec3b87f60ae16bf', '王佐才', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江苏连云港灌云；山西运城夏县；河南郑州中牟；山西临汾浮山；辽宁盘锦盘山；山西临汾乡宁；山西临汾；黑龙江_黑河_北安；浙江舟山岱山；江苏连云港连云港经开区；江苏连云港海州；黑龙江大庆大庆高；黑龙江大庆肇州；河北_唐山；黑龙江齐齐哈尔克东；山西大同云州；河北石家庄元氏；浙江杭州余杭；山西晋城；山西晋城沁水；黑龙江佳木斯；黑龙江哈尔滨松北；黑龙江哈尔滨宾县；山西吕梁临县；山西运城新绛；山西运城；内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；浙江宁波宁海；浙江宁波象山；山西、河北、辽宁；浙江舟山；山西_运城_芮城', '[]', '[]', '抗日战争时期', '', '原阎锡山部军官，投日后任临汾伪道尹公署顾问，参与策划对临汾、乡宁地区的“清剿”行动，诱降抗日干部。；在浮山二区推行保甲制度，清查抗日家属，向日军报告八路军活动情报，导致多次袭击事件。；在临汾县城任伪职期间，为日军提供情报，组织伪警察所，抓捕抗日分子，强征粮税，破坏地下抗日组织。；原为地方民团头目，投日后任伪保安队副队长，在临汾、蒲县交界地带多次袭击八路军游击队，杀害抗日家属，抢劫物资。；组织伪自卫团，配合日军巡逻和清乡，杀害抗日军属，抢劫民财。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.992320', '2026-09-10 09:57:13.992320', '内蒙古', '鄂尔多斯', '鄂托克前旗', NULL, NULL, NULL, NULL, '');
