INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97041ac313044435a2bf1f5b5e646381', '郭世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治壶关；山西；山西吕梁交城；山西吕梁离石', '[]', '[]', '抗日战争时期', '', '率伪军驻守交城至离石公路沿线，袭击抗日运输队，抢劫物资，杀害护送人员。；在日军占领区设立伪区公所，摊派苛捐杂税，强抓壮丁，为日军提供粮食和劳役，迫害抗日家属。', '[]', '2026-09-10 09:57:14.020021', '2026-09-10 09:57:14.020021', '山西', '吕梁', '交城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9704b33c2558433fae23cef5a2db390c', '杜运宇', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝；内蒙古_锡林郭勒_多伦；内蒙古呼伦贝尔牙克石；山东', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪蒙疆交通部长，主管平绥铁路，为日军转运兵员物资。结局：关押改造期间病亡，未等到特赦', '[]', '2026-09-10 09:57:13.989410', '2026-09-10 09:57:13.989410', '内蒙古', '呼伦贝尔', '牙克石', NULL, NULL, NULL, NULL, '');
