INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97057f1a95614719970d2fc615f4e92b', '陈敦和', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南长沙天心；湖南长沙；湖南长沙宁乡；湖南长沙；湖南怀化溆浦；湖南湘潭；湖南长沙；湖南长沙开福', '[]', '[]', '抗日战争时期', '', '在湘潭组织伪维持会，为日军提供物资和情报，协助日军维持占领区秩序。；长沙沦陷期间，以商会名义为日军筹款筹粮，协助日伪维持长沙城内经济秩序。；在汪伪湖南省政府中负责警务，参与组建伪警察队伍，镇压长沙、宁乡一带抗日分子，维护日占区秩序。；长沙商人，沦陷后出面组织伪商会，为日军筹款筹物，协助经济掠夺，活动于开福区商业地带。', '[]', '2026-09-10 09:57:14.058517', '2026-09-10 09:57:14.058517', '湖南', '怀化', '溆浦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97159a4a8ce142d186502672cdb2792f', '隋明福', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北', '[]', '[]', '抗日战争时期', '', '伪职：伪玉田县县长；配合日军铃木启久，推行第四次治安强化运动；组建反共自卫团、棍儿团，炮制八大杀禁律，一周抓捕三千余抗日人员，制造玉田大抓捕惨案唐山党史网。；结局：冀东民主政府公审死刑；伪职：伪玉田县县长，配合铃木启久日军部队推行第四次治安强化运动；组建反共自卫团、棍儿团，炮制 “八大杀禁律”，全县抓捕三千余抗日人员，制造玉田大抓捕惨案唐山党史网。；结局：冀东民主政府公审死刑', '[]', '2026-09-10 09:57:14.069295', '2026-09-10 09:57:14.069295', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('972562e1c1574c5bac5c5f47a64950d8', '奇子义', NULL, NULL, NULL, NULL, 'exact', 'exact', '准格尔旗', '[]', '[]', '抗日战争时期', '', '伪职：旗内台吉，勾结包头日伪；秘密接受伪委任，为日伪刺探准格尔、府谷一带河防情报。；结局：抗战胜利后逮捕判刑', '[]', '2026-09-10 09:57:14.079022', '2026-09-10 09:57:14.079022', '内蒙古', '鄂尔多斯', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9734c86f10fe4434813e8e8c061d0216', '陈秉义', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古；内蒙古乌海海南；内蒙古乌海；内蒙古巴彦淖尔临河；内蒙古巴彦淖尔五原；内蒙古巴彦淖尔杭锦后旗；内蒙古乌兰察布化德；内蒙古乌兰察布卓资；内蒙古包头；内蒙古包头东河；内蒙古包头；内蒙古包头九原；内蒙古呼和浩特玉泉；内蒙古呼和浩特；绥远；内蒙古乌兰察布凉城；内蒙古呼和浩特；内蒙古乌兰察布丰镇；内蒙古包头固阳', '[]', '[]', '抗日战争时期', '', '伪职：伪绥西自治联军第一师师长；原国民党军官，1940 投日，率部进入河套，驻守五原外围，祸害河套百姓。；结局：解放后逮捕处决；率部驻防丰镇周边，多次袭击抗日游击队，杀害抗日干部，强征民夫修筑日军工事。；任伪凉城县长期间，为日军征粮派款，组织伪警察抓捕抗日地下人员，破坏中共凉城抗日根据地。；原为地方民团头目，投日后任伪绥东保安队队长，在卓资、旗下营一带为日军搜集情报，抓捕抗日人员，欺压乡民。；率伪军驻扎商都、化德地区，参与日军“治安强化”运动，屠杀抗日群众。；协助王英统领伪军，在乌海、海南周边地区设卡收税，强征民夫，为日军修筑工事。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.986473', '2026-09-10 09:57:13.986473', '内蒙古', '乌兰察布', '凉城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97493a2c0b424825bb842fff5134290a', '刘坤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '日军占领大名后率先组织维持会，为日军提供情报，协助建立伪政权，强迫百姓领取“良民证”。', '[]', '2026-09-10 09:57:14.081916', '2026-09-10 09:57:14.081916', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
