INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('979025ae29c8444eb529236bda618b70', '王毅', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南文昌；辽宁沈阳大东；海南三亚天涯；内蒙古乌海海南；内蒙古乌海海南；海南白沙；海南海口；海南东方；内蒙古乌海海南；海南三沙西沙；海南海口琼山；海南三沙中沙；海南文昌；海南澄迈；海南五指山；内蒙古乌海海南；海南琼中；海南保亭；海南海口琼山；海南海口；海南陵水；海南三亚崖州；内蒙古乌海海南；江西景德镇昌江；海南临高；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '伪职：首任伪河东道道尹（1939??1941）；罪行：搭建伪河东道整套行政体系；推行保甲、治安强化运动，强征粮食、盐池资源、劳工；指挥各县伪政权配合日军扫荡中条山、太岳南部根据地，推行奴化教育抖音百科。；结局：抗战胜利逮捕，汉奸罪重判', '[]', '2026-09-10 09:57:14.053122', '2026-09-10 09:57:14.053122', '海南', '三亚', '天涯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('979115b641ee460a8bad2c85c9f38ba8', '陈天恩', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州；福建福州闽侯；辽宁沈阳大东；福建福州；福建福州台江；福建福州', '[]', '[]', '抗日战争时期', '', '福州人，福州沦陷期间任伪福州商会会长，协助日军征调物资、摊派捐款，控制福州商业为日伪服务。；福州沦陷期间主持伪商会，为日军摊派款项、征调物资，协助日伪经济掠夺。；福州沦陷期间任伪教育会会长，推行奴化教育，组织教师参加日伪培训，宣传“大东亚共荣圈”。；福州教育界附逆者，任伪教育会会长，推行日语教学和奴化教育，为日军培养亲日分子。；福州人，日军占领福州期间任伪保安队队长，配合日军清乡、搜捕抗日人员。；福州台江地区保甲长，协助日军登记户口、征发壮丁、监视居民，推行保甲连坐。', '[]', '2026-09-10 09:57:14.061989', '2026-09-10 09:57:14.061989', '福建', '福州', '仓山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9792044ecd1948098902e65aa5bdaff8', '美崎丈平', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西恒山；黑龙江鸡西', '[]', '[]', '抗日战争时期', '', '日本籍伪满官员，任伪东安省次长，实际掌控东安省（含今鸡西地区）行政，推行殖民统治与治安肃正。', '[]', '2026-09-10 09:57:14.066584', '2026-09-10 09:57:14.066584', '黑龙江', '鸡西', '恒山', NULL, NULL, NULL, NULL, '');
