INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9793e3a20bd74323974198c0d4d4e76f', '赵欣余', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁大连旅顺口', '[]', '[]', '抗日战争时期', '', '投日后任伪协和会奉天省会长，协助日本进行思想宣传和特务活动。', '[]', '2026-09-10 09:57:14.063075', '2026-09-10 09:57:14.063075', '辽宁', '大连', '旅顺口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9793f6590c8b4a689e057be8d5ef5504', '陈锡三', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州；江苏徐州沛县；江苏_徐州_丰县；江苏徐州鼓楼；江苏徐州铜山；江苏淮安清江浦；江苏_连云港_东海；山东东营河口；山东东营广饶；江苏淮安金湖；江苏淮安；江苏_宿迁；江苏_宿迁_宿迁经开区', '[]', '[]', '抗日战争时期', '', '协助日军建立特务情报网，搜捕共产党员和进步人士，刑讯逼供，制造多起惨案。；为日军征收苛捐杂税，强征粮食和物资，加重百姓负担，支持日军战争经济。；推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”。；在沛县强征军粮，破坏中共地下组织，协助日军建立碉堡封锁线，镇压湖西抗日根据地。；在淮安南部（含今金湖区域）推行保甲制度，强征壮丁，为日军提供情报。；掌管伪警察机构，镇压抗日活动，抓捕并刑讯抗日军民，曾参与制造多起屠杀事件，并协助日军强征劳工。；效忠日军，镇压抗日活动，逮捕并刑讯抗日志士，向日军提供情报。；推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，迫害有爱国倾向的教师和学生。；在广饶县任伪维持会会长，协助日军维持地方统治、征粮征夫，其活动区域涉及今东营市广饶县及周边地区。；负责为日伪政权征收苛捐杂税，搜刮民财，贪污公款，为日军军费提供地方财政支持。', '[]', '2026-09-10 09:57:14.012046', '2026-09-10 09:57:14.012046', '山东', '东营', '河口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97957adf0f0145ee8817c602bc9396d2', '郭仲隗', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南平顶山鲁山；河南平顶山宝丰；河南洛阳西工；辽宁沈阳大东；河南新乡牧野；河南新乡；河南平顶山；河南许昌襄城；河南新乡原阳；河南新乡；河南洛阳栾川；河南洛阳；河南新乡卫辉；河南新乡；河南洛阳宜阳；河南洛阳；河南洛阳嵩县；河南洛阳；河南洛阳新安；山西阳泉城区；山西晋城阳城；河南新乡获嘉', '[]', '[]', '抗日战争时期', '', '在获嘉县任伪警察所所长，配合日军维持治安，迫害抗日家属。；在洛阳沦陷期间出任伪县知事，配合日军推行保甲、征发劳役，活动范围覆盖洛阳城区及新安一带。；洛阳沦陷后出任伪洛阳县知事，配合日军在洛阳城乡推行保甲、征粮、拉夫等政策。；在日军占领洛阳期间出任伪县知事，管理洛阳城区及老城民政，配合日军推行保甲连坐与物资统制。；在洛阳及豫西地区推行伪政令，配合日军清乡、征粮，镇压抗日活动。；在洛阳及豫西地区为伪政权奔走，拉拢地方士绅附逆，协助日军宣传“大东亚共荣”。；在豫北道伪政权中负责教育，推行奴化教育，新乡为其辖区。；宝丰县与鲁山接壤，日军占领宝丰后出面组织伪维持会，为日军筹集物资、情报。；洛阳沦陷后投靠日军，收编地方武装组成伪军，配合日军在洛阳、偃师、孟津一带清乡、扫荡。；襄城沦陷后任维持会会长，为日军筹粮筹款，协助日军维持襄城地区统治。；在河南沦陷区参与伪教育机构，推行奴化教育，其活动涉及豫北新乡等地。；组织伪保安团，配合日军扫荡新乡、卫辉周边抗日武装。；洛阳沦陷后投靠日伪，参与组织嵩县维持会，为日军提供情报、协助征粮，是嵩县当地较有影响的附逆者。', '[]', '2026-09-10 09:57:14.047874', '2026-09-10 09:57:14.047874', '河南', '平顶山', '鲁山', NULL, NULL, NULL, NULL, '');
