INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97b6780b05114281b4340795aa127b83', '李景文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄元氏；河北邢台南宫；河北邯郸武安；辽宁沈阳新民；山西、河北；河北邯郸永年；河北邯郸邯郸经开区；河北沧州孟村；河北邢台宁晋；河北石家庄高邑；河北邯郸；河北邯郸武安；山西阳泉；河北石家庄赞皇', '[]', '[]', '抗日战争时期', '', '日军占领阳泉后首任维持会长，组织矿工为日军无偿劳动，克扣矿工口粮，协助日军掠夺煤炭资源，迫害反抗矿工。；在孟村成立伪维持会，为日军征集粮饷、抓派民夫，破坏抗日组织，曾指认并抓捕多名抗日地下工作人员。；长期盘踞沧县东部及黄骅沿海地区，为日军运输物资、封锁港口，抓捕抗日志士，并强征民夫修建炮楼和封锁沟。；率伪军多次扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。；率伪军配合日军“扫荡”抗日根据地，杀害抗日干部和群众，破坏抗日组织，烧毁村庄。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.024517', '2026-09-10 09:57:14.024517', '山西', '阳泉', '孟村', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97bfef6f3a3f4950a59fb6e2044d87bf', '何某某', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南永州零陵；湖南永州宁远', '[]', '[]', '抗日战争时期', '', '宁远沦陷期间投敌，组织伪维持会，协助日军征粮、派款、维持地方秩序。', '[]', '2026-09-10 09:57:14.058923', '2026-09-10 09:57:14.058923', '湖南', '永州', '零陵', NULL, NULL, NULL, NULL, '');
