INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97f90aee0f7149a0b73dcf224df28721', '沈鸿英', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴南湖；山西吕梁兴县；浙江湖州南浔；浙江湖州；广西梧州', '[]', '[]', '抗日战争时期', '', '投靠日军，任伪嘉兴县知事，协助日伪推行“清乡”政策，强征民夫，搜刮粮食，镇压抗日民众。；湖州沦陷后出任伪维持会会长，为日军征粮派款，协助建立伪政权。；与梧州有历史关联，但抗战期间未任伪职，此处仅作背景排除。', '[]', '2026-09-10 09:57:14.032581', '2026-09-10 09:57:14.032581', '广西', '梧州', '南湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97fc524d49a5401e89a2d1ec223eb761', '赵梦周', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林长春二道；吉林长春；吉林长春宽城；河北承德宽城；吉林松原乾安；吉林；吉林；辽宁本溪', '[]', '[]', '抗日战争时期', '', '在长春、二道地区组织协和会，宣传“日满亲善”，瓦解抗日意志；在宽城地区推行日伪保甲制，强征壮丁，协助日军建立“治安区”。', '[]', '2026-09-10 09:57:13.998827', '2026-09-10 09:57:13.998827', '吉林', '松原', '乾安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97fd7c1f9233452fab89b24304322522', '王佐华', NULL, NULL, NULL, NULL, 'exact', 'exact', '濛江（靖宇县）', '[]', '[]', '抗日战争时期', '', '伪职：原抗联弹药手，伪讨伐队队员；罪行：叛变，跟随伪讨伐队进山清剿抗联，参与围捕杨靖宇战斗新华网。；结局：建国后被管制。', '[]', '2026-09-10 09:57:14.077195', '2026-09-10 09:57:14.077195', '吉林', '白山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('97ffb43bc3d94dfb853b66433f50c2c0', '王慎修', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪汾城县县长；罪行：建立汾城伪政权，修筑炮楼，疯狂摊派粮款，制造多起村庄惨案。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.077355', '2026-09-10 09:57:14.077355', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('980389c5c5b049318baf6e06ed260d5b', '周德先', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏扬州仪征', '[]', '[]', '抗日战争时期', '', '率伪保安队在仪征各地设卡盘查，杀害新四军交通员，参与“清乡”行动，掠夺百姓财物。', '[]', '2026-09-10 09:57:14.035505', '2026-09-10 09:57:14.035505', '江苏', '扬州', '仪征', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('980d0fb5c3a7433bbec243a2b42df937', '黄国栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江濂溪；广东汕尾城区；辽宁沈阳大东；江西宜春靖安；江西宜春；广东广州荔湾；广东广州；海南五指山；海南白沙', '[]', '[]', '抗日战争时期', '', '张贴亲日标语，散布“大东亚共荣”言论，瓦解民众抗日意志。；汪伪政权委任的伪濂溪乡长，推行保甲连坐，协助日军清乡与物资统制。；率伪保安大队配合日军驻宜春部队清乡，搜捕抗日人员，强征粮食，并在宜春、万载交界地区设置关卡盘剥民众。；广州沦陷区伪自卫团头目，协助日军维持地方秩序。；在白沙地区统辖伪军，配合日军进攻抗日根据地。', '[]', '2026-09-10 09:57:14.027049', '2026-09-10 09:57:14.027049', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
