INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9819606ca8af4c2bb53dc5643448ea76', '周渭清', NULL, NULL, NULL, NULL, 'exact', 'exact', '江山县城', '[]', '[]', '抗日战争时期', '', '伪职：江山临时维持会会长；罪行：浙赣战役江山沦陷，组建临时维持会，为日军筹措给养，胁迫地方士绅合作。日军撤退维持会瓦解。；结局：抗战胜利后附逆案审判，判处徒刑。', '[]', '2026-09-10 09:57:14.083462', '2026-09-10 09:57:14.083462', '浙江', '衢州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('982f131297134fbb9d07b9f7063c1005', '陈德', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林恭城；云南普洱西', '[]', '[]', '抗日战争时期', '', '广西沦陷期间，任伪保安大队长，配合日军搜捕抗日人员。；广西沦陷期间，任伪保安大队长，配合日军。', '[]', '2026-09-10 09:57:14.032354', '2026-09-10 09:57:14.032354', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('983b6e2f11664f79ba0df5f53783b92a', '刘伯谦', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡阳保税；湖南衡阳；山西阳泉城区；湖南怀化沅陵；湖南怀化；湖南娄底双峰；湖南湘潭湘乡；湖南株洲茶陵；湖南株洲；湖南衡阳南岳；湖南衡阳；湖南衡阳祁东；湖南衡阳衡东；湖南衡阳；湖南衡阳；湖南郴州嘉禾；湖南衡阳耒阳；山西晋城阳城；湖南_湘潭', '[]', '[]', '抗日战争时期', '', '在衡阳沦陷期间担任伪警察局长，协助日军搜捕抗日分子、维持城区治安。；日军占领郴县后出任伪警察局长，负责侦缉抗日分子、维持城区治安，配合日军统治。；嘉禾县沦陷后组织伪维持会，为日军征粮派款，协助日军建立伪政权。；衡阳沦陷后任伪警察头目，配合日军搜捕抗日人员、维持伪治安，地方志中有简略记载。；在日军占领衡阳期间出任伪警察局长，负责维持城区秩序、搜捕抗日人员。；抗战后期在湘乡沦陷区出任伪县长，秉承日军意旨推行伪化统治，征粮拉夫。；日军占领株洲后，出面组织维持会，为日军提供物资、情报，协助维持株洲地区伪秩序。；日军侵入怀化后组织维持会，负责登记户口、征发劳役，协助日军建立伪基层政权。；祁阳沦陷后，刘伯谦出面组织伪维持会，为日军征粮、派款、拉夫，并协助日军镇压抗日活动。；日军占领衡阳期间，以商会名义为日军筹款筹粮，协助日军控制衡阳工商业。；耒阳沦陷期间组织伪维持会，为日军征集粮食、民夫，并参与伪保甲组织，协助日军控制耒阳城乡。；衡阳沦陷后组建伪保安团，任团长，配合日军清乡、扫荡，活动于衡阳及南岳周边地区。；日军占领衡阳后，出任伪衡阳县县长，协助日军推行保甲制度、征粮征夫，镇压抗日活动。；日军占领衡阳后出任伪衡阳县县长，主持伪县政，配合日军清乡、征发民夫与物资，推行奴化教育。；在日军控制下组建伪警察队伍，配合日军搜捕抗日人员、镇压民众。', '[]', '2026-09-10 09:57:14.057571', '2026-09-10 09:57:14.057571', '湖南', '娄底', '双峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('983e76d3874545ed906a5a3312c2e574', '赵子恒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北衡水景县；河北；河北_石家庄', '[]', '[]', '抗日战争时期', '', '管理伪警察，协助日军进行户口清查，抓捕地下党员。；日军占领景县初期任维持会长，为日军筹粮筹款，组织伪政权，强迫百姓领取“良民证”，告密抗日活动。；日军占领深县后出任维持会长，为日军筹粮派款，提供抗日武装活动情报，导致多处秘密联络点被破坏。', '[]', '2026-09-10 09:57:14.043241', '2026-09-10 09:57:14.043241', '河北', '衡水', '景县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9840f48dc7434d219f4b8a2d3d8132f8', '萨镇冰', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门；福建福州', '[]', '[]', '抗日战争时期', '', '日军占领福州后曾试图拉拢其出任伪职，但其拒绝附逆；此条仅作辨析，非实际汉奸。', '[]', '2026-09-10 09:57:14.060827', '2026-09-10 09:57:14.060827', '福建', '厦门', NULL, NULL, NULL, NULL, NULL, '');
