INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('984a653398ac448ca3ea33aadff1ed74', '李馨斋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北邢台信都；河北邢台', '[]', '[]', '抗日战争时期', '', '任伪顺德道尹，管辖邢台、沙河、内丘等县，为日军提供情报，组织伪警备队，配合日军扫荡抗日根据地。；原为地方民团头目，后投降日军，任伪保安联队队长，多次率部袭击八路军后方机关，杀害抗日干部和群众，并参与日军对冀南根据地的“铁壁合围”行动。', '[]', '2026-09-10 09:57:14.044720', '2026-09-10 09:57:14.044720', '河北', '邢台', '信都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9853a0d96a6841aa88bf626bea1e7931', '邓世增', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西北海合浦；广西钦州钦南', '[]', '[]', '抗日战争时期', '', '在钦县基层充任伪保甲长，执行日伪政令，登记户口、征收捐税、监视民众，举报抗日人员。；在日伪控制下推行奴化教育，修改教材，向学生灌输亲日思想。', '[]', '2026-09-10 09:57:14.030560', '2026-09-10 09:57:14.030560', '广西', '北海', '合浦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9853df1834394e87951ca9d59f27a20a', '区芳浦', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州；广东广州海珠；广东广州；广东_广州', '[]', '[]', '抗日战争时期', '', '掌管广州沦陷区财政税收，为伪政权与日军筹措经费，推行苛捐杂税。；参与汪伪广东省及广州市政，协助日伪推行各项统治措施。；汪伪政权在广东的财政官员，曾任伪广东财政厅长，为伪政权筹措经费，配合日军经济统制。', '[]', '2026-09-10 09:57:14.026667', '2026-09-10 09:57:14.026667', '广东', '广州', '海珠', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('985e7ad7bc73411ca06b255ace23f2ab', '宾阳维持会某负责人', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁宾阳', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '日军短暂侵入宾阳期间，当地曾出现维持会组织，为日军提供情报、粮秣，但具体姓名在地方志中记载不全。', '[]', '2026-09-10 09:57:14.031162', '2026-09-10 09:57:14.031162', '广西', '南宁', '宾阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('98630018a3b3413ca688cf1a8eae66b3', '周文才', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴平湖', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校教授日语和‘中日亲善’课程，迫害坚持爱国教育的教师。', '[]', '2026-09-10 09:57:14.050448', '2026-09-10 09:57:14.050448', '浙江', '嘉兴', '平湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('986ad093a39e4408b52c28a3b628e3a0', '林荟材', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌海海南；海南海口；海南东方；海南文昌；海南海口琼山；海南三沙南沙；海南海口；海南海口琼山；海南琼中；内蒙古乌海海南；海南海口龙华；福建南平政和；海南白沙；海南文昌；海南三沙中沙；海南临高；海南三亚吉阳；内蒙古乌海海南；海南屯昌；海南澄迈；海南临高；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '参与海口伪市政和伪政权事务，为日军统治海口、龙华及周边地区提供行政协助。；在澄迈地区投敌，组织维持会，为日军提供情报和物资，协助日军统治。；参与伪军组织，协助日军扫荡抗日根据地，镇压民众抗日活动。；投敌后主持文昌伪政权，配合日军扫荡文昌抗日根据地，强征物资，推行奴化教育。；投靠日军后在海南任伪职，参与伪军武装活动，配合日军对琼崖抗日独立纵队活动区域进行围剿。；在琼山地区投敌，任伪琼山县县长，组织伪维持会和伪保安队，配合日军对琼山、海口一带抗日游击区进行清乡、扫荡，强征粮食和劳工。；在琼山地区组织维持会，协助日军扫荡抗日游击队。；在临高地区附逆，协助日军征粮、征丁，推行保甲制度，压制抗日活动。；推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害海南青年。；在海南海口等地为日军服务，参与伪政权行政事务，协助日军控制城镇与港口，压迫当地民众。；海南伪政权核心人物之一，参与伪琼崖临时政府决策，其势力范围覆盖澄迈等琼北地区。；在琼山地区出任伪县长，配合日军清乡、征粮，建立伪保甲制度，诱降抗日分子。；在文昌地区组织伪维持会，配合日军扫荡，抓捕抗日志士，强征粮食。；在海南包括临高地区进行亲日宣传，散布投降言论，瓦解民众抗日意志。', '[]', '2026-09-10 09:57:14.053168', '2026-09-10 09:57:14.053168', '海南', '三亚', '吉阳', NULL, NULL, NULL, NULL, '');
