INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('99b04e40c379474690ede35d5285461b', '马步芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃天水；甘肃兰州；甘肃兰州永登；甘肃平凉静宁；甘肃平凉', '[]', '[]', '抗日战争时期', '', '虽未直接投日，但在甘肃地区与日伪有暗中往来，其部属在平凉、静宁一带与伪军有合作，镇压抗日力量。；虽为国民党地方军阀，但抗战期间在甘肃、青海地区与日伪方面有秘密接触和妥协行为，其部属在兰州、皋兰一带曾与伪军有往来，被指对日伪态度暧昧。；虽未公开投敌，但抗战期间与日伪有秘密接触和交易，其势力范围覆盖甘肃、青海，对天水地区有影响，历史记载中其部分行为被视为附逆倾向。；虽未公开投敌，但曾与日军有秘密接触，在甘肃、青海一带维持割据，对抗战有消极影响。', '[]', '2026-09-10 09:57:14.060070', '2026-09-10 09:57:14.060070', '甘肃', '兰州', '永登', NULL, NULL, NULL, NULL, '');
