INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('99bd5da223de4e5e8c86b44ad7d0b667', '刘伯群', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州柳城；云南普洱西；广西玉林容县；湖南郴州桂东；广东惠州；广西桂林平乐；广西桂林；广西贵港桂平；云南普洱西；广西玉林陆川；广西玉林北流；广西贵港', '[]', '[]', '抗日战争时期', '', '桂林沦陷期间出面组织伪商会，为日军筹款筹物，强制商户“献纳”，协助日军经济掠夺。；在伪广西政权中负责宣传，为日军侵略张目，进行亲日、奴化宣传。；抗战后期在广西伪政权中任职，参与伪警察系统的组建与运作，协助日军镇压抗日活动。；日军占领梧州期间组织伪维持会，协助日军统治，梧州为玉林邻近地区，其活动范围覆盖桂东南。；以商会名义为日军摊派捐款、物资，协助日伪对惠州工商业者进行控制与掠夺。；在贵县乡村推行保甲制度，为日军征丁征粮，监视村民行动，举报抗日人员。；北流沦陷后组织伪维持会，为日军征粮、带路，并协助日军扫荡附近乡村。', '[]', '2026-09-10 09:57:14.027254', '2026-09-10 09:57:14.027254', '广东', '惠州', '柳城', NULL, NULL, NULL, NULL, '');
