INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9a7089337455408191b73a5eb2450653', '赵文灿', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城；山东聊城高唐；山东聊城；山东聊城莘县；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '率伪警察配合日军搜捕抗日人员，刑讯逼供，勒索商户居民。；在聊城组织新民会，开展亲日宣传、奴化教育，协助日军控制民众思想。；统领伪保安团，驻守聊城及周边据点，配合日军进攻抗日根据地，抓捕壮丁，征发民夫。', '[]', '2026-09-10 09:57:14.017423', '2026-09-10 09:57:14.017423', '山东', '聊城', '莘县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9a7db88124ba4ee38de0d185d89ed5a7', '杨秀峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南平顶山鲁山；河南平顶山宝丰；河南南阳；河南南阳唐河；河南南阳；山东聊城高唐；河南南阳；辽宁沈阳大东；山东聊城', '[]', '[]', '抗日战争时期', '', '南阳人，任伪新民会会长，组织亲日团体，宣传“大东亚共荣”，协助日军进行思想控制。；组织维持会迎接日军，为日军筹集粮草，招募伪军。；以合作社为名，强行低价收购高唐棉花、粮食，供给日军，剥削农民，配合经济封锁。；南阳唐河人，日军侵占唐河后组织维持会，为日军征粮派款，协助伪政权统治。；唐河县劣绅，组织维持会为日军服务，其活动范围与社旗南部接壤，协助日军控制南阳东部。；1945年日军侵入唐河期间，组织维持会，为日军筹办粮草，协助日军维持地方统治。；郏县与鲁山、宝丰相邻，日军占领后任伪维持会会长，配合日军征粮征丁。；在南阳沦陷期间任伪教育局长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军培养顺民。', '[]', '2026-09-10 09:57:14.017499', '2026-09-10 09:57:14.017499', '山东', '聊城', '高唐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9a86289abab745a5b449e0dd6a80cfd9', '王玉珂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东德州夏津；山东德州庆云；河北；山东聊城；山东聊城东昌府；山东聊城高唐', '[]', '[]', '抗日战争时期', '', '率部充当日军帮凶，多次袭击黄骅抗日县大队，杀害抗日干部和群众，参与“五一大扫荡”期间在沧州地区的清剿行动。', '[]', '2026-09-10 09:57:14.013910', '2026-09-10 09:57:14.013910', '山东', '德州', '夏津', NULL, NULL, NULL, NULL, '');
