INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9af9689c0d8249c18a1cf188ced708a6', '张性初', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波；浙江宁波江北；浙江宁波宁海；浙江宁波海曙；浙江宁波', '[]', '[]', '抗日战争时期', '', '宁海本地人，日军扶植下出任伪宁海县知事，推行保甲制度，强征壮丁，为日军提供物资，镇压抗日武装。；负责伪浙东地区警察事务，在宁波、海曙一带搜捕抗日志士，协助日军维持治安，实施“清乡”行动。；为日伪政权强征苛捐杂税，盘剥江北商户与百姓，资助日军军费，民愤极大。；为日军征收苛捐杂税，强征田赋，导致宁波百姓负担沉重，部分款项用于伪军军费。', '[]', '2026-09-10 09:57:14.050770', '2026-09-10 09:57:14.050770', '浙江', '宁波', '宁海', NULL, NULL, NULL, NULL, '');
