INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9b53e5ce956a44e5a426f009761f1c71', '孙永昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东泰安岱岳；山东泰安；山东临沂费县；山东临沂；山东济宁梁山；山东济宁；山东临沂罗庄；山东临沂平邑；山东泰安宁阳；山东泰安；山东泰安新泰；山东泰安；山东泰安肥城；山东临沂沂南；山东济宁微山；山东临沂', '[]', '[]', '抗日战争时期', '', '任伪付庄乡乡长，配合日军在付庄、罗庄一带清乡，强迫村民修筑据点，提供情报。；临沂商界附逆代表，为日军筹集物资，协助推行伪币，控制当地经济。；在泰安岱岳一带担任伪保甲长，协助日军清查户口、监视抗日人员、催缴粮款。；出任伪沂南县知事，在沂南地区建立伪政权，推行保甲连坐，为日军征粮、征夫，配合日军对抗日根据地进行经济封锁和军事扫荡。；滕县沦陷后任伪知事，配合日军在滕县、微山湖东岸地区清乡，镇压抗日武装。；抗战时期任伪泰安县商会会长，为日军筹集物资，协助经济掠夺，压迫商户。；平邑地区沦陷后出面组织维持会，协助日军建立伪政权，摊派粮款，压迫当地民众。；泰安沦陷后投靠日军，任伪商会会长，为日军筹款筹物，协助经济掠夺。；在临沂苍山地区组织维持会，为日军征粮、带路，镇压抗日群众。；在肥城地区统领伪保安团，配合日军扫荡抗日根据地，抢粮抓丁，迫害抗日家属。；任伪邹县知事，协助日军扫荡济宁东部抗日力量。', '[]', '2026-09-10 09:57:14.012527', '2026-09-10 09:57:14.012527', '山东', '临沂', '平邑', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9b5400beece64517a62e687674145dd5', '林曜李', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪琼崖民众自卫军秘书长，詹松年主要副手，伪军文官头目。结局：战后捕获，判处死刑枪决', '[]', '2026-09-10 09:57:14.080540', '2026-09-10 09:57:14.080540', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
