INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9b6f65e677cc47e1b165d20fc70bd9cf', '刘德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治沁源；江苏连云港东海；河北唐山滦州；河北唐山；黑龙江牡丹江林口；河北邢台沙河；山西忻州神池；河北沧州；河北沧州吴桥；黑龙江黑河北安；江苏南京高淳；浙江衢州常山；河北_石家庄_灵寿；山西太原古交；山西、河北；江苏常州金坛；榆次；山西大同阳高', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山组织青年为日军服务，充当劳役。；率领伪保安队配合日军进攻抗日根据地，在阳高南山一带烧毁村庄，屠杀抗日家属。；在古交河口、镇城底等地设卡盘查，抢劫百姓财物，杀害抗日家属。；多次带队突袭抗日村庄，烧毁民房，抢掠牲畜，杀害抗日军属，并参与“清乡”行动。；率队袭击八路军运输队，抢夺物资，杀害押运战士。；在唐山诱骗青年加入伪军，充当日军炮灰。……（共涉及8个地区的犯罪记录）；伪职：宪兵队便衣特务头目；罪行：发展密探网络，破获地下交通站，抓捕地下党员。；结局：解放后镇反处决', '[]', '2026-09-10 09:57:14.021237', '2026-09-10 09:57:14.021237', '山西', '大同', '阳高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9b6f68ea424b4c7a93bc6a3339927954', '何明', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳宝安', '[]', '[]', '抗日战争时期', '', '在沙井一带为日军征收蚝田税，协助日军控制沿海地区，迫害抗日渔民。', '[]', '2026-09-10 09:57:14.029168', '2026-09-10 09:57:14.029168', '广东', '深圳', '宝安', NULL, NULL, NULL, NULL, '');
