INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bc86d505bae41248d9c53a86e606d54', '陈子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；河南三门峡湖滨；河南三门峡灵宝；河南洛阳新安；河南洛阳；河南信阳罗山；河南三门峡卢氏；河南商丘；河南商丘宁陵；河南焦作解放；河南焦作；广东广州；河南信阳淮滨；河南信阳固始；河南洛阳；河南_洛阳_洛宁；河南焦作沁阳；湖北十堰房县；湖北十堰；河南新乡卫滨；河南新乡；河南南阳；河南焦作马村；河南焦作；宁夏银川贺兰；辽宁沈阳新民；河南信阳新县；河南信阳；广东江门蓬江；广东江门；山东潍坊临朐；山东潍坊；山西、河北；河南洛阳宜阳；河南信阳信阳高；河南信阳；广东湛江；陕西汉中勉县；陕西汉中城固；河北衡水武邑；河北衡水；山西长治屯留；河北邯郸；湖北十堰竹溪；湖北十堰房县；山西运城芮城；河南洛阳嵩县；河南焦作焦作示范；河南焦作；河南焦作修武；河南三门峡三门峡经开区；河南三门峡渑池；河南焦作博爱；河南焦作；广东江门鹤山；河南鹤壁鹤山；河南三门峡；河南三门峡渑池；河南洛阳栾川；辽宁沈阳大东；河南焦作温县；河南焦作；河南商丘睢县；河南商丘；河南漯河；辽宁沈阳大东；河南平顶山湛河；河南平顶山；河南商丘夏邑；辽宁沈阳大东；河南焦作山阳；青海黄南河南', '[]', '[]', '抗日战争时期', '', '专门刺探抗日军情，抓捕地下党员，刑讯逼供，制造多起惨案。；组织维持会为日军筹粮派款，提供情报，协助日军建立伪政权。；推行奴化教育，在邯郸各学校强制教授日语，灌输‘中日亲善’思想，压制师生抗日情绪。', '[]', '2026-09-10 09:57:14.004153', '2026-09-10 09:57:14.004153', '宁夏', '银川', '贺兰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bcf010326f440afb0a938e66ba7c84d', '陈绍武', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰翁牛特旗；重庆沙坪坝；广东湛江', '[]', '[]', '抗日战争时期', '', '伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；参与维持会决策，协助日军维护南路治安，镇压抗日活动。；赤峰沦陷后投敌，在伪赤峰县公署任职，协助日军推行保甲、征粮、抓丁等殖民统治措施，直接涉及赤峰及翁牛特旗周边地区。', '[]', '2026-09-10 09:57:13.991632', '2026-09-10 09:57:13.991632', '内蒙古', '赤峰', '翁牛特旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bd8d93ea0184a779e2b53dcc65a8089', '王效文', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州姜堰；上海崇明', '[]', '[]', '抗日战争时期', '', '在姜堰镇组织维持会，为日军提供情报、粮秣和民夫，协助日军控制姜堰及周边地区。；以“通匪”罪名滥捕无辜，刑讯逼供，判处抗日志士死刑，协助日军镇压反抗。', '[]', '2026-09-10 09:57:13.976366', '2026-09-10 09:57:13.976366', '上海', '崇明', '姜堰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bdde151c0f347809c87078a5d19924d', '张钫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南洛阳宜阳；河南洛阳；河南洛阳嵩县；河南洛阳；河南洛阳汝阳；河南洛阳；河南洛阳伊川；河南洛阳', '[]', '[]', '抗日战争时期', '', '日军占领洛阳后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征派粮款、拉夫修路，为日军侵略服务。；日军占领洛阳后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征派粮款。；抗战初期被日军拉拢，曾列入伪河南省政府名单，但未实际就任；后在洛阳、嵩县一带从事地方活动，与日伪有接触，历史评价复杂。；抗战后期在豫西沦陷区参与伪政权，协助日军维持洛阳及豫西一带的治安与征发。；抗战后期在豫西沦陷区参与伪政权，协助日军维持豫西占领区秩序，活动范围涉及洛阳及新安周边。；抗战后期在豫西沦陷区附逆，参与伪政权维持会与地方治安活动，活动范围覆盖洛阳及豫西各县。；抗战后期洛阳沦陷后，参与伪河南省政权，在豫西地区协助日军推行伪化统治，活动范围覆盖洛阳及周边。；日军发动豫湘桂战役占领洛阳后，出面组织伪豫西行政公署，协助日军维持豫西占领区治安，推行伪化统治。；1944年豫西沦陷后投靠日军，参与组织伪河南省政权，在洛阳、伊川一带协助日军推行保甲、征粮和维持会体系。；抗战后期洛阳沦陷后，参与日伪在豫西的行政维持活动，协助日军推行保甲与征粮，活动范围覆盖洛阳及豫西各县。', '[]', '2026-09-10 09:57:14.048464', '2026-09-10 09:57:14.048464', '河南', '洛阳', '伊川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bdf87c8bc60444a9d1c87084353a53a', '丁鉴修', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁沈阳大东；辽宁辽阳；辽宁_辽阳_灯塔；辽宁铁岭；辽宁阜新海州；辽宁阜新；吉林长春双阳；吉林长春；吉林长春绿园；吉林长春；吉林长春宽城；辽宁大连旅顺口；河北承德；吉林经开区；吉林白山；吉林；辽宁沈阳新民；河北秦皇岛山海关；黑龙江哈尔滨松北；辽宁阜新彰武；辽宁阜新；吉林、河北、辽宁；吉林长春公主岭；吉林四平；辽宁沈阳；吉林长春长春高；吉林长春；辽宁鞍山；辽宁沈阳浑南；广西桂林资源；吉林；河北承德滦平；河北_承德；吉林白城通榆；吉林；吉林长春；吉林_高；山东聊城；辽宁_大连；辽宁_大连_庄河；辽宁盘锦双台子；辽宁营口大石桥；辽宁葫芦岛绥中；辽宁葫芦岛；黑龙江齐齐哈尔', '[]', '[]', '抗日战争时期', '', '原东北交通官员，投日后管理四平铁路枢纽，为日军运输兵员物资，并参与镇压铁路沿线抗日游击队。；负责伪满交通建设，在长春（新京）及吉林地区修建军用铁路和公路，服务于日军侵略。；组织汉奸特务，在公主岭、长春等地搜捕抗联地下工作者。；协助日本掠夺吉林矿产、森林资源，强征中国劳工。；管理伪满交通，为日军运输军需物资，协助军事占领。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.996797', '2026-09-10 09:57:13.996797', '吉林', '白城', '通榆', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9bf6a555fb974f2ab5eb7e68189a369d', '王凤山', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南鹤壁淇滨；河南鹤壁浚县；河南焦作中站；山西阳泉矿区；河南焦作山阳；河南焦作修武；河南焦作解放；河南焦作；河南新乡；河南新乡获嘉；河南焦作焦作示范；河南焦作', '[]', '[]', '抗日战争时期', '', '在浚县组织伪保安团，为日军维持治安，镇压抗日活动。；控制焦作矿区，为日军掠夺煤炭资源提供武装保护，迫害矿工和抗日人员。；在博爱及焦作西部组织维持会，为日军筹集物资、情报，诱迫群众服从伪政权。；日伪占领修武期间任伪县知事，推行保甲连坐，协助日军掠夺煤炭和粮食资源。；控制焦作煤矿矿警，协助日军掠夺煤炭资源，镇压矿工。；在新乡周边获嘉县为日军筹粮、派夫，镇压抗日活动。', '[]', '2026-09-10 09:57:14.048233', '2026-09-10 09:57:14.048233', '河南', '新乡', '中站', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c04012011e541adb47886ac5bc50e3d', '王仲三', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北廊坊广阳；河北廊坊香河；云南昆明西山；云南保山龙陵；云南昆明东川；云南昆明；安徽滁州天长', '[]', '[]', '抗日战争时期', '', '组织伪昆明市维持会，为日军筹集物资、拉拢地方士绅，协助日军在昆明地区的统治。；昆明沦陷期间（注：昆明实际未被日军长期占领，此处指日伪渗透时期或周边地区），组织伪维持会，为日军提供情报、物资，协助推行保甲连坐，压迫昆明市民。；王仲三在滇西沦陷区组织伪军，配合日军对腾冲、龙陵等地的控制，参与征粮、抓丁等行动。；香河县伪政权头目，香河属廊坊地区，为日军服务。；滁县沦陷后组织维持会，为日军筹粮筹款、拉夫，协助建立伪政权。', '[]', '2026-09-10 09:57:13.980609', '2026-09-10 09:57:13.980609', '云南', '昆明', '东川', NULL, NULL, NULL, NULL, '');
