INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c14666150ab46eb865a3775d997370d', '刘世润', NULL, NULL, NULL, NULL, 'exact', 'exact', '桃江县（栗埠乡）', '[]', '[]', '抗日战争时期', '', '伪职：栗埠乡乡长；罪行：1944年9月，将从益阳运回的三千多斤配购食盐企图私分；结局：待考（属于利用职权谋私，是否与日伪勾结有待考证）', '[]', '2026-09-10 09:57:14.070453', '2026-09-10 09:57:14.070453', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c162fb30cc84c3a863410a04ad538ee', '任援道下属', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦', '[\"具体姓名不详\"]', '[]', '抗日战争时期', '', '在杨浦区驻防，镇压工人。', '[]', '2026-09-10 09:57:13.978765', '2026-09-10 09:57:13.978765', '上海', '杨浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c1884c08c094e8281ff9098b1ce7c06', '张慕良', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶余干；江西抚州临川；江西上饶广丰；江西上饶；江西_景德镇；湖南邵阳；辽宁沈阳大东；江西吉安永丰；江西吉安；江西景德镇乐平；江西上饶玉山；辽宁沈阳大东；江西上饶鄱阳；江西上饶', '[]', '[]', '抗日战争时期', '', '在日军扶植下出任伪县知事，推行伪化教育，配合日军清乡，强征民夫修筑据点。；在沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；主持日占区学校，推行奴化教育，篡改教材，组织学生参加亲日集会与宣传。；日军占领上饶期间出任伪县知事，配合日军建立伪政权、推行奴化教育。；在伪政权中负责教育事务，推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”。；在吉安地区收编土匪、地痞组成伪军，配合日军进攻抗日根据地，抢掠民财。；在乐平地区建立伪警察体系，协助日军搜捕抗日分子，镇压民众反抗，推行保甲连坐。；浙赣会战期间上饶沦陷后，出面组织伪维持会，为日军筹粮、派夫、搜集情报，协助日军维持占领区统治。；掌管伪警察局，协助日军清查户口、逮捕抗日嫌疑分子，勒索商户。', '[]', '2026-09-10 09:57:14.037568', '2026-09-10 09:57:14.037568', '江西', '上饶', '余干', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c1e1d9de5a54de6b3ce67b1c0705fab', '张济民', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安万安；江西南昌青云谱；江西南昌', '[]', '[]', '抗日战争时期', '', '出面组织伪南昌商会，为日军筹款、摊派物资，协助经济统制，压迫商户配合日伪掠夺。；在万安日伪占领期间担任伪警察头目，协助日军抓捕抗日人员，维持占领区秩序。', '[]', '2026-09-10 09:57:14.039513', '2026-09-10 09:57:14.039513', '江西', '南昌', '青云谱', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c28eae9c62d43698d7334c9bb647d3f', '张兴汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_连云港_灌云', '[]', '[]', '抗日战争时期', '', '任伪警察局长期间，负责侦缉抗日地下活动，多次带队搜捕中共地下党员和抗日积极分子。', '[]', '2026-09-10 09:57:14.036767', '2026-09-10 09:57:14.036767', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c30ccc9a0524c4b89a5658b91efa92e', '符永茂', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江吴川；广东广州；广东茂名化州；广东湛江雷州；广东湛江雷州；广东湛江霞山；广东广州；广东湛江遂溪；广东湛江徐闻；广东广州；广东湛江赤坎；广东广州；广东广州', '[]', '[]', '抗日战争时期', '', '日军占领广州湾后出面组织维持会，充任伪政权头目，协助日军推行殖民统治、征粮征税、维持治安。；日军侵占遂溪后出面组织伪维持会，为日军征粮派款、搜集情报，协助维持沦陷区秩序。；日军占领广州湾后任伪区长，配合日军维持治安、摊派捐税、搜捕抗日人员。；在广州湾协助日军镇压抗日活动，搜捕抗日人士，管理伪警察队伍，配合日军维持治安。；雷州沦陷后出面组织伪维持会，协助日军征粮、派夫、维持地方治安，为日军统治雷州半岛提供地方支持。；日军占领广州湾后出面组织伪维持会，后任伪广州湾特别市市长，协助日军推行殖民统治、征发物资与劳工，维持沦陷区秩序。；在雷州半岛及邻近粤西地区附敌，组织伪维持会，为日军征集粮食、劳工，配合日军对茂名、化州方向的扫荡与封锁。；广州湾沦陷后率部投敌，任伪保安队队长，配合日军清乡、扫荡，镇压抗日群众，在湛江及吴川一带活动。；充任伪警察头目，协助日军搜捕抗日人士，镇压民众反抗，维护日伪在广州湾的统治秩序。；在广州湾协助日军镇压抗日活动，搜捕抗日人士，配合日军推行保甲连坐制度。；在广州湾及周边地区（含徐闻方向）为日军搜集情报、搜捕抗日人员，配合日军扫荡雷州半岛抗日游击区。', '[]', '2026-09-10 09:57:14.029437', '2026-09-10 09:57:14.029437', '广东', '湛江', '吴川', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c31aac6d23840a49fbaa69c2a2bc314', '萨尔图伪保长', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大庆萨尔图', '[]', '[]', '抗日战争时期', '', '萨尔图（今大庆市萨尔图区）投敌者，任伪保长，协助日军在萨尔图一带推行保甲制度，征粮、抓劳工、监视抗日人员。', '[]', '2026-09-10 09:57:14.066259', '2026-09-10 09:57:14.066259', '黑龙江', '大庆', '萨尔图', NULL, NULL, NULL, NULL, '');
