INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c367f7309a2458b9891983377e34c76', '李品仙系统附逆人员', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林全州；云南普洱西', '[]', '[]', '抗日战争时期', '', '桂柳沦陷期间，广西部分地方武装和警察在日军诱降下改编为伪军伪警，协助日军控制交通线和乡镇。', '[]', '2026-09-10 09:57:14.032004', '2026-09-10 09:57:14.032004', '广西', '桂林', '全州', NULL, NULL, NULL, NULL, '');
