INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c4218bf82b847f096ed17ffc217bfde', '吴少华', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南信阳淮滨；河南信阳潢川；河南信阳光山；河南信阳固始；河南信阳', '[]', '[]', '抗日战争时期', '', '率伪军在光山、信阳交界地区配合日军扫荡，捕杀抗日干部与群众。；在光山县城及周边乡镇建立伪警察网络，为日军搜集情报，抓捕抗日军民，勒索商民财物。；在潢川沦陷期间组织维持会，为日军提供情报和物资，协助日军控制豫东南交通线，镇压民众反抗。；率部投靠日军，编成伪保安团，配合日军在固始及周边地区清乡、扫荡。', '[]', '2026-09-10 09:57:14.046070', '2026-09-10 09:57:14.046070', '河南', '信阳', '光山', NULL, NULL, NULL, NULL, '');
