INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c4752df1778450097cf166f0c610ab3', '李金山', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；湖北荆州沙市；河南南阳；湖北十堰房县', '[]', '[]', '抗日战争时期', '', '在沙市统率伪保安队，协助日军控制码头、商会。；湖北房县人，抗战期间投敌，任伪房县保安团团长，协助日军维持房县治安，镇压抗日武装。；河南南阳人，抗战期间投敌，为日军充当特务，搜集情报，抓捕抗日人员。', '[]', '2026-09-10 09:57:14.046910', '2026-09-10 09:57:14.046910', '河南', '南阳', '宛城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c477b118f014fb6b0c86452ef2c5b21', '杨清泉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北邢台襄都；河北邯郸邯郸经开区；河北邢台邢台经开区', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强迫学校使用日伪教材，宣传“中日亲善”，迫害爱国师生。；为日军搜集八路军和抗日武装情报，多次导致抗日人员被捕，破坏地下交通线。；组织商会为日军筹集物资，强迫商户捐款，垄断粮食布匹贸易，为日军提供情报。', '[]', '2026-09-10 09:57:14.045008', '2026-09-10 09:57:14.045008', '河北', '邢台', '襄都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c4e92ce9b6b4ed4be9e934594008c5b', '魏时珍', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都青羊；四川成都', '[]', '[]', '抗日战争时期', '', '在成都为日军进行宣传，散布亲日言论，瓦解抗日士气。', '[]', '2026-09-10 09:57:14.002497', '2026-09-10 09:57:14.002497', '四川', '成都', '青羊', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c56349ce67e49ea90f6044bcaa956da', '宝贵廷', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古乌兰察布；内蒙古包头；内蒙古呼和浩特；内蒙古包头土默特右旗；内蒙古乌兰察布四子王旗；云南普洱西；内蒙古呼和浩特武川；内蒙古巴彦淖尔临河；内蒙古鄂尔多斯；河北张家口；内蒙古呼和浩特土默特左旗；内蒙古乌兰察布；内蒙古包头青山；内蒙古乌海海勃湾；内蒙古巴彦淖尔五原；内蒙古乌兰察布；内蒙古包头白云鄂博矿；内蒙古呼和浩特玉泉；河北张家口万全；内蒙古呼伦贝尔牙克石；内蒙古锡林郭勒镶黄旗；云南普洱西；内蒙古、河北；内蒙古包头青山；内蒙古呼和浩特；河北张家口；内蒙古巴彦淖尔乌拉特前旗；内蒙古乌兰察布；河北张家口桥东；内蒙古锡林郭勒锡林浩特；吉林高；内蒙古呼和浩特；湖南怀化通道；内蒙古乌海；内蒙古包头；云南普洱西；内蒙古巴彦淖尔乌拉特中旗', '[]', '[]', '抗日战争时期', '汪伪政权', '率伪蒙古军在乌兰察布、丰镇一带驻防，多次参与对八路军和游击队的“围剿”，烧杀抢掠，残害百姓。；伪蒙古军将领，在乌兰察布地区驻防，协助日军维持殖民秩序，抓捕抗日地下工作者，参与经济掠夺。；在乌兰察布及化德地区指挥伪军参与多次进攻八路军和国民党抗日部队的行动。；在乌兰察布、卓资一带驻防，配合日军“铁壁合围”战术，袭击抗日游击队，强征马匹和粮食。；率伪蒙古军在乌兰察布、商都地区驻防，参与围剿八路军大青山支队，残害抗日军民。……（共涉及31个地区的犯罪记录）；伪任职务：伪蒙古军第四师师长，伪蒙古军司令部少将，长期驻防绥远。结局：关押改造，1966 年特赦释放', '[]', '2026-09-10 09:57:13.986181', '2026-09-10 09:57:13.986181', '内蒙古', '呼和浩特', '土默特左旗', NULL, NULL, NULL, NULL, '');
