INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c80eb7fac8c4a969bebcd1e78b6f395', '陈亚东', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄峄城；山东济南济南高；山东济南历城；山东济宁兖州；辽宁沈阳新民；山东泰安泰山；辽宁沈阳大东；山东菏泽成武；山东菏泽', '[]', '[]', '抗日战争时期', '', '在兖州主持伪新民会，开展亲日宣传和奴化教育，协助日伪统治。；在峄县推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动。；郓城沦陷后组织维持会，后任伪县知事，在郓城、菏泽、成武一带为日军征粮派款，协助清乡，破坏抗日根据地。；日军侵占历城后组织维持会，为日军带路、筹粮，维持地方伪秩序。；在泰安推行亲日奴化教育，修改教材，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.014617', '2026-09-10 09:57:14.014617', '山东', '枣庄', '峄城', NULL, NULL, NULL, NULL, '');
