INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9c9ead992e8946b29e0895b3979d9702', '徐振中', NULL, NULL, NULL, NULL, 'exact', 'exact', '广饶；寿光', '[]', '[]', '抗日战争时期', '', '伪职：国民党投降派保安团团长（汉奸）；罪行：益都县国民党投降派保安团团长。1941年1月5日带领朱良据点日伪军300余人包围东朱鹿村，杀害中共清东地委组织部长李寿岭、益寿县委组织部长刘旭东等12名干部群众，制造“东朱鹿惨案”。将刘旭东绑在树上挖掉双眼；伪职：“剿共联军”头目；罪行：参与何思源组织的“剿共联军”，配合日伪进攻抗日根据地', '[]', '2026-09-10 09:57:14.083816', '2026-09-10 09:57:14.083816', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9ca039b2d7fe41b199d5f15952a68c16', '陈铁头', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州中原；河南郑州；河南新乡延津；河南南阳；河南漯河郾城；河南漯河；河南许昌许昌经开区；河南驻马店新蔡；河南驻马店驿城；河南驻马店；河南开封顺河；河南平顶山宝丰；河南郑州；河南许昌长葛；河南许昌；河南漯河；河南南阳桐柏；河南平顶山；河南周口项城；河南商丘；河南漯河召陵；河南漯河；河南新乡新乡高；河南新乡', '[]', '[]', '抗日战争时期', '', '组织伪保安团，配合日军下乡扫荡，抓捕抗日群众，勒索财物。；叶县（今属平顶山市）人，抗战后期投靠日军，组织伪保安团，在叶县及周边地区配合日军清乡，残害抗日群众。；河南南阳宛城人，抗战期间投敌，组织伪自卫团，配合日军清乡，残害抗日群众。；在豫北道包括新乡地区率领伪保安队，配合日军扫荡抗日武装。；组织伪保安团配合日军守备郑州及周边据点，参与清乡、扫荡，镇压抗日群众。；在顺河区组织伪维持会，为日军筹粮筹款，协助维持殖民秩序。；漯河沦陷期间任伪警察局长，带领伪警察配合日军搜捕抗日人员，勒索商户，欺压百姓。；郑州地区伪保甲长，协助日军推行保甲制度，监视居民，征发劳役，迫害抗日家属。；在遂平及驻马店周边地区为日军效力，搜捕抗日人员，强征粮食，欺压百姓。；漯河沦陷期间任伪商会会长，为日军筹款、摊派物资，协助维持经济掠夺体系，属经济领域附逆者。；新蔡本地武装头目，投靠日军后任伪保安团团长，配合日军清乡、扫荡，抓捕抗日人员，残害百姓。；率伪保安大队配合日军对许昌、长葛交界地区进行扫荡，抢粮抓丁。；在豫东周口、项城、商丘一带率部投敌，任伪军团长，配合日军扫荡抗日根据地，残害百姓。；郏县沦陷后率部投敌，配合日军扫荡郏县、宝丰交界地区，残害抗日军民。；组织伪保安团，配合日军扫荡延津及周边抗日根据地，参与抓捕抗日军民、抢粮拉夫等附逆活动。；漯河沦陷期间任伪警察头目，为日军维持治安，参与抓捕和迫害抗日群众。；桐柏人，任伪警察局长，带领伪警察配合日军搜查抗日分子，刑讯逼供，残害百姓。', '[]', '2026-09-10 09:57:14.046834', '2026-09-10 09:57:14.046834', '河南', '南阳', '宛城', NULL, NULL, NULL, NULL, '');
