INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9cb7e5f25bd54ac6a882cb3cf7cd4532', '李儒林', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北十堰竹溪', '[]', '[]', '抗日战争时期', '', '在郧县一带依附日伪势力，参与组织维持会与伪基层政权，为日军搜集情报、征发民夫粮秣，压制抗日活动。', '[]', '2026-09-10 09:57:14.054918', '2026-09-10 09:57:14.054918', '湖北', '十堰', '竹溪', NULL, NULL, NULL, NULL, '');
