INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9d14b5e5c6784dc294c159e7a4f69af3', '张子淦', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古包头达尔罕茂明安；内蒙古鄂尔多斯康巴什；内蒙古鄂尔多斯；内蒙古鄂尔多斯杭锦旗；内蒙古鄂尔多斯；山西朔州朔城；重庆沙坪坝', '[]', '[]', '抗日战争时期', '', '参与伪晋北自治政府事务，为日军在雁北地区建立伪政权、推行殖民统治效力。；在包头地区组织维持会，包头为鄂尔多斯北部重要门户，其活动直接影响鄂尔多斯地区，为日军征粮征款，协助建立伪政权。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在伪绥远省政权中任职，参与对鄂尔多斯及杭锦旗等地的行政控制，推行日伪法令，协助经济掠夺。；在萨拉齐及包头周边地区为日军征粮、征税，维持伪政权，间接控制达尔罕茂明安南部一带。', '[]', '2026-09-10 09:57:13.988076', '2026-09-10 09:57:13.988076', '内蒙古', '包头', '达尔罕茂明安', NULL, NULL, NULL, NULL, '');
