INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9d5bd599b740467fab1e04b3fce81baa', '陈耀庭', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城广德；江西南昌新建；江西南昌安义；湖北襄阳保康', '[]', '[]', '抗日战争时期', '', '新建县沦陷后投敌，组织伪维持会，为日军征粮、征丁，协助日军在新建西山、生米一带清乡。；掌管伪安义县警察武装，配合日军搜捕抗日人员、镇压民众。；广德沦陷期间出面组织伪维持会，协助日军维持地方秩序、摊派粮款，是当地伪政权代表人物之一。；在保康地区组织维持会，协助日军征粮派款，维持伪化统治。', '[]', '2026-09-10 09:57:14.007856', '2026-09-10 09:57:14.007856', '安徽', '宣城', '广德', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9d6d68ee2302447c8f4bd73d01c4f5df', '王天祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸成安；河北邯郸邯郸冀南；山东菏泽巨野；山西、河北；山西大同浑源；河北邯郸大名；河北邯郸邱县', '[]', '[]', '抗日战争时期', '', '投靠日军，任伪浑源县县长，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。；组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日干部和群众，参与制造多起惨案。；为日军出谋划策，参与建立伪政权，协助日军掠夺大名地区粮食和物资。；在大名、邯郸地区统率伪军，参与日军“治安强化运动”，破坏抗日根据地，抓捕抗日干部。；率伪保安队多次进入成安境内扫荡，杀害抗日干部，抢劫民财。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018094', '2026-09-10 09:57:14.018094', '山东', '菏泽', '巨野', NULL, NULL, NULL, NULL, '');
