INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da4735e5b9f4edaab7bc8d2633c7938', '贡锡九', NULL, NULL, NULL, NULL, 'exact', 'exact', '扬州公道桥', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪公道乡乡长，为日伪征集粮款，泄露我方情报，屡劝不改。。结局：甘泉抗日民主政府公审枪决', '[]', '2026-09-10 09:57:14.071474', '2026-09-10 09:57:14.071474', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da5c3ea818c4e7a896bb72d1c599bb5', '马全良', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏银川；甘肃平凉静宁；甘肃平凉；宁夏吴忠；内蒙古呼和浩特回民', '[]', '[]', '抗日战争时期', '', '抗战期间被日军特务机关拉拢，参与策划在宁夏吴忠、灵武一带煽动回民脱离中国，配合日军建立伪回教政权的图谋，后因事泄未果。；日军侵占绥远部分地区后，曾试图在宁夏建立伪政权，马全良被日方拉拢，参与策划在银川地区组织维持会，后因马鸿逵控制严密未能公开就任，但曾向日军提供宁夏军政情报。；在平凉县组织维持会，协助日军维持地方秩序，征粮征夫，镇压抗日活动。', '[]', '2026-09-10 09:57:14.003718', '2026-09-10 09:57:14.003718', '宁夏', '吴忠', '静宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da62740dd0f4191936540e6844c1830', '张辉瓒', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州临武；湖南长沙；江西吉安泰和；江西吉安吉州；江西吉安；湖南常德津；湖南常德；湖南株洲天元；湖南株洲；江西赣州瑞金；江西抚州临川；湖南湘潭岳塘；湖南长沙浏阳；湖南岳阳湘阴；湖南衡阳衡南；湖南衡阳；湖南怀化靖州；湖南郴州；湖南湘潭；湖南湘西泸溪；湖南怀化怀化洪江管理', '[\"附逆传闻\", \"注：此处为误列，实际为国民党将领，非汉奸\"]', '[]', '抗日战争时期', '', '湖南长沙人，早年参与围剿红军，1931年被俘处决，其部属部分在湘中地区活动，与日伪有间接关联，但本人主要活动于抗战前。；湘潭沦陷期间任伪警察局长，协助日军维持治安，抓捕抗日人员，推行保甲连坐。；协助日军在湖南推行清乡运动，在郴州、嘉禾一带组织伪保甲，搜捕抗日分子。；湖南长沙人，国民党将领，1930年率部参加对中央苏区的第一次“围剿”，在江西龙冈被红军俘虏，1931年被处决。其活动主要在江西，与湖南有籍贯关联，但并非严格意义上的汉奸。；湖南长沙人，1931年在江西被红军俘虏处决，非汉奸，但常被误列，此处不属汉奸名录。；湖南长沙人，1930年率部进攻中央苏区被俘，1931年被处决，与衡阳地区关联较弱。；湖南长沙人，早年参与围剿红军，1931年被俘，并非严格意义汉奸，但因其在湖南地区活动且与日军有接触传闻，部分史料将其列入附逆嫌疑。；无。张辉瓒为国民党军将领，1931年已死，与抗日战争汉奸无关。此条仅为避免误列。；无；湖南长沙人，沦陷后任伪长沙县某保保长，后任伪长沙县自卫团团长，配合日军清乡，搜捕抗日分子，活动于长沙雨花地区。；湖南长沙人，1931年在对中央苏区“围剿”中被俘处决，非汉奸。此处不适用。；衡阳沦陷期间出面组织地方维持会，为日军征派粮秣、民夫，协助维持占领秩序。；地方史料提及其在吉安沦陷期间参与伪教育机构，推行奴化教育，但记载简略，仅列备考。；组织伪清乡队，配合日军在长沙县、宁乡、浏阳等地“扫荡”。；湖南长沙人，早期参与围剿红军，虽非严格意义汉奸，但在抗战前的地方军事活动中与湘西地区有交集。；常德会战期间投靠日军，组织伪清乡队，在常德、桃源、汉寿交界地区搜捕抗日人员，勒索百姓。；湘阴沦陷后组织维持会，为日军征集粮食、劳工。；株洲沦陷期间，出面组织伪维持会，为日军征集物资、拉夫，协助日军维持占领区秩序。；1944年日军发动豫湘桂战役后，在湖南沦陷区出面组织伪自治会，为日军筹粮筹款、维持地方。；湖南长沙人，1931年在江西被红军俘虏处决，此前有资料指其与日方有秘密接触，但主要历史定位为国民党将领，非典型汉奸。；日军占领泰和期间，出任伪警察局长，协助日军维持治安，抓捕抗日分子，镇压民众反抗。；在赣东临川、南城一带组织伪维持会，为日军提供物资和情报，协助日军控制赣东与赣南之间的交通线，迫害抗日群众。', '[]', '2026-09-10 09:57:14.039707', '2026-09-10 09:57:14.039707', '江西', '吉安', '吉州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da6a871c6d64c9c917c810de7ab2731', '施文卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海崇明', '[]', '[]', '抗日战争时期', '', '为日军和汪伪政权筹款，强制商户捐献，垄断粮食贸易，向日军提供军需物资。', '[]', '2026-09-10 09:57:13.976317', '2026-09-10 09:57:13.976317', '上海', '崇明', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da6eed65771424f8d9358c753e7ba7d', '唐慎之', NULL, NULL, NULL, NULL, 'exact', 'exact', '当涂县城', '[]', '[]', '抗日战争时期', '', '伪职：伪当涂县财政科长；罪行：经济汉奸，征收苛捐杂税，为日军筹集粮食、铜铁，统筹铁矿劳工摊派，搜刮资敌物资。；结局：战后判处有期徒刑。', '[]', '2026-09-10 09:57:14.069135', '2026-09-10 09:57:14.069135', '安徽', '马鞍山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9da91ad4da3148d089a9132f10ea3d0c', '张仁蠡', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '安徽蚌埠；河北唐山曹妃甸；广西桂林资源；重庆_万州；陕西_西安_长安；北京大兴；河北南皮（张之洞之子）；安徽安庆；安徽芜湖鸠江；安徽芜湖；河北秦皇岛；河北唐山；河北_唐山_路南；北京顺义；天津和平；河北唐山迁西；江苏南京；河北石家庄辛集；河北石家庄；安徽芜湖；浙江_杭州_西湖；河北唐山唐山高；天津河北；安徽淮北；天津南开；湖南常德津；江苏南京鼓楼；安徽合肥肥东；安徽合肥；安徽安庆；河北秦皇岛昌黎；天津红桥；北京门头沟；湖北鄂州鄂城；河北_秦皇岛；河北衡水冀州；河北衡水；天津河北；江苏_南京_浦口；江西九江；湖北武汉；安徽芜湖镜湖；安徽芜湖；河北唐山；河北秦皇岛；河北唐山唐山芦台经开区；河北唐山；河北廊坊；河北秦皇岛抚宁；湖北武汉；湖南_湘西_泸溪；北京_通州；河北唐山；江苏南京浦口；江苏_南京；武汉（伪武汉市政府）；安徽安庆；安徽蚌埠；北京昌平；吉林长春朝阳；安徽_合肥_庐江；天津河北；湖北武汉；云南普洱西；陕西_西安_长安；山西阳泉矿区；河北秦皇岛；北京丰台；北京、天津、河北；天津河北；湖北武汉；北京怀柔；安徽芜湖芜湖经开区；安徽芜湖；江苏镇江丹阳；江苏镇江；江苏_镇江_润州；天津河北；湖北武汉；湖南常德津；陕西渭南；云南普洱西；陕西_西安_灞桥；陕西_西安_蓝田；江苏徐州铜山；江苏徐州；云南普洱西；河北石家庄；重庆沙坪坝；天津河西；江苏扬州邗江；河北石家庄裕华；河北唐山路北', '[]', '[]', '抗日战争时期', '汪伪政权', '投日后任伪北平市长，管辖包括丰台在内的北平地区，推行日伪法令，强征物资。；专门负责大兴、宛平等郊县“剿共”，指挥伪军警突袭村庄，逮捕抗日家属。；投靠日伪政权，任怀柔县知事，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。；在任期间推行日伪统治政策，协助日军征粮、强征劳工，镇压抗日活动。；原北洋官僚，投日后任伪北平市长，管辖包括昌平在内的北平郊区，配合日军征粮、抓夫和“治安强化”运动。……（共涉及75个地区的犯罪记录）；伪任职务：伪武汉特别市首任市长，后调伪天津特别市市长。结局：抗战胜利被捕，判处无期徒刑，1951 年狱中去世湖北省人民...；参与策划廊坊地区“治安强化”具体措施，并督导各县伪政权执行。；伪职：伪武汉特别市政府市长；罪行：张之洞第十三子。1935年任伪冀东防共自治政府民政厅长；1939年4月任伪武汉特别市政府首任市长；结局：1951年以汉奸罪在北京被判处死刑', '[]', '2026-09-10 09:57:13.983291', '2026-09-10 09:57:13.983291', '天津', '河北', '矿区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9db1c3a78d2240029f235bb05a3d61ea', '王定国', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南五指山；海南澄迈；海南保亭；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '为日军强征橡胶、粮食等物资，压榨当地百姓，从中牟利。；在澄迈地区组织伪军，协助日军征粮征税。', '[]', '2026-09-10 09:57:14.054121', '2026-09-10 09:57:14.054121', '海南', '五指山', NULL, NULL, NULL, NULL, NULL, '');
