INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9dbde5bd4f374ec093dee443cdece88f', '赵福林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北_邯郸_魏县', '[]', '[]', '抗日战争时期', '', '指挥伪警察搜捕抗日分子，严刑拷打被捕人员，多次带路突袭抗日村庄。', '[]', '2026-09-10 09:57:14.045457', '2026-09-10 09:57:14.045457', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9dc3d6857c8f4267891b67c0ba941336', '宋子贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封祥符；河南开封；河南商丘豫东综合物流产业聚集；河南商丘；河南商丘柘城；河南周口淮阳；河南商丘；河南郑州新密；河南商丘虞城；河南郑州巩义', '[]', '[]', '抗日战争时期', '', '在鹿邑、淮阳邻近地区任伪职，协助日军推行治安强化运动，组织伪自卫团，镇压抗日力量。；日军占领开封后组织伪维持会，协助日军维持地方秩序，征发物资。；鹿邑沦陷后任伪县长，依附日军，在鹿邑及邻近商丘地区推行伪化统治，为日军征粮征夫。；商丘沦陷后投靠日军，控制商会为日军筹款筹粮，协助经济掠夺。；在虞城组织伪警备队，协助日军维持地方治安，参与搜捕抗日人员、镇压民众反抗。；在柘城地区组建伪保安团，配合日军扫荡，袭击地方抗日武装，残害抗日群众。；巩县沦陷后附逆，在伪政权中负责教育事务，推行奴化教育，篡改教材以配合日军宣传。；新郑沦陷后投敌，任伪维持会会长及伪县长，为日军提供情报与物资，活动范围紧邻新密。；在商丘县城及周边地区协助日军维持治安，搜捕抗日人员，推行保甲连坐，镇压民众抗日活动。', '[]', '2026-09-10 09:57:14.047540', '2026-09-10 09:57:14.047540', '河南', '周口', '淮阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9dd0b00a236d449e989cdb9660ed0eee', '乐秀华', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖北乡', '[]', '[]', '抗日战争时期', '', '伪职：伪保安三中队中队长；罪行：盘踞万春圩北乡，骚扰乡间百姓，配合日军清剿。；结局：抗战胜利后清算。', '[]', '2026-09-10 09:57:14.077535', '2026-09-10 09:57:14.077535', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
