INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9ddb69e79672431cac59c3a04bfd5074', '翟书田', NULL, NULL, NULL, NULL, 'exact', 'exact', '梨树十家堡', '[]', '[]', '抗日战争时期', '', '伪职：九一八四平街维持会会长、伪四平街市政公所市长（早期），绰号 “翟小鬼”；罪行：九一八迅速投靠日军，组建维持会，协助日军接管四平；放高利贷，勾结日伪压榨百姓；八一五后仍依附国民党势力敛财吉林省地方...。；结局：四平解放后逮捕，没收全部家产，后病死狱中吉林省地方...。', '[]', '2026-09-10 09:57:14.073742', '2026-09-10 09:57:14.073742', '吉林', '四平', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9ddc3b3d95bb4fdbb175feb72ea0e13c', '王跃南', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹤壁（淇县）', '[]', '[]', '抗日战争时期', '', '伪职：大汉奸；罪行：1938年2月13日，日军占领淇县城时，打开城门迎接日军进驻县城。1943年参与策划李埏投降日军', '[]', '2026-09-10 09:57:14.076266', '2026-09-10 09:57:14.076266', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
