INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9dfd9ea68ce1449ebe781702373dbc89', '刘锡田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊永清', '[]', '[]', '抗日战争时期', '', '为日军推行奴化教育，组织汉奸宣传队，强迫民众参加“反共”集会，搜集抗日情报供日军使用。；指挥伪警察抓捕抗日地下党员，破坏抗日交通站，参与“治安强化运动”中的清乡行动。', '[]', '2026-09-10 09:57:14.042560', '2026-09-10 09:57:14.042560', '河北', '廊坊', '永清', NULL, NULL, NULL, NULL, '');
