INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9e6f403d8b774bbe9ca510e8819983cd', '刘翰如', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉黄陂；湖北武汉汉阳；湖北武汉', '[]', '[]', '抗日战争时期', '', '投敌后任伪武汉行营主任、伪军师长，在武汉及周边地区配合日军作战。；在伪武汉政权中任职，控制社会团体与舆论，协助日军征发劳工、物资，推行奴化教育。；在伪武汉政权中任职，负责社会控制与物资统制，协助日军征发劳工、配给物资，推行奴化宣传。；在伪武汉政权中任职，负责社会控制与物资统制，协助日军征发物资、管制民众。；抗战期间在武汉伪政权中任职，参与鸦片专卖等毒化政策。；任伪汉口特别市商会会长，为日军统制经济服务，强制商户纳捐，协助掠夺战略物资。；抗战期间投敌，任伪汉阳县县长，在汉阳地区为日军维持伪政权。', '[]', '2026-09-10 09:57:14.056533', '2026-09-10 09:57:14.056533', '湖北', '武汉', '黄陂', NULL, NULL, NULL, NULL, '');
