INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9f4f7e40cf224c89bafeac76f2f21efa', '于冲汉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '广西桂林资源；辽宁鞍山岫岩；吉林长春农安；吉林长春；辽宁营口鲅鱼圈；吉林长春南关；吉林；吉林长春；辽宁辽阳；本溪草河口；辽宁_沈阳；吉林四平伊通；吉林；辽宁葫芦岛；辽宁_辽阳_灯塔；辽宁铁岭；辽宁鞍山岫岩；辽宁鞍山；吉林长春德惠；吉林长春；吉林长春宽城；吉林长春；辽阳；辽宁朝阳双塔；河北承德；辽宁_辽阳_白塔；辽宁_鞍山_千山；辽宁_沈阳_大东；辽宁铁岭西丰；辽宁铁岭；吉林长春；吉林_长春_朝阳；辽宁_大连；辽宁_大连_中山；辽宁_大连_旅顺口；辽宁辽阳；辽宁_大连_长海；辽宁沈阳；辽宁_沈阳_和平；辽宁_沈阳_沈北；辽宁_沈阳_浑南；辽宁盘锦；黑龙江_哈尔滨_松北；辽宁阜新彰武；辽宁阜新；吉林、河北、辽宁；辽宁锦州凌河；辽宁锦州；辽宁大连沙河口；辽宁大连；辽宁_沈阳_沈河；辽宁_沈阳_皇姑；辽宁锦州北镇；辽宁锦州；辽宁阜新海州；山西阳泉矿区；辽宁沈阳新民；辽宁沈阳；辽宁沈阳辽中；辽宁本溪；辽宁_大连_瓦房店；辽宁_抚顺；辽宁_抚顺_新抚；辽宁_抚顺_望花；辽宁_抚顺_顺城；辽宁沈阳；辽宁辽阳；辽宁铁岭清河；河北邢台清河；辽宁锦州；辽宁阜新；广西桂林资源；辽宁_葫芦岛_龙港；辽宁阜新太平；辽宁阜新；辽宁鞍山；辽宁鞍山立山；辽宁鞍山；辽宁营口老边；辽宁盘锦双台子；广西桂林资源；辽宁辽阳；辽宁_大连_金州；辽宁营口；辽宁营口站前', '[]', '[]', '抗日战争时期', '', '伪职：伪奉天自治指导部部长；罪行：伪满早期核心人物，建立自治指导部，在奉天全省网罗汉奸，培训伪官吏，推行奴化统治。；结局：1932 年病死，逃脱审判。；伪职：伪奉天自治指导部部长、伪满监察院院长；罪行：九一八投敌，建立自治指导部，培训东北各地伪官吏；与日本合办弓长岭等铁矿，掠夺矿山资源；炮制伪满建国理论。主要任职沈阳抖音百科。；结局：1932 年病死大连，逃脱审判抖音百科。；原奉系官员，投日后任伪满监察院院长，参与伪满政权建设，在吉林地区推行“协和会”活动，麻痹民众抗日意识。；在吉林地区协助日军建立情报网，迫害抗日爱国人士。；曾任伪满要职，在长春（新京）参与伪满政权建设，协助日本控制东北金融与行政。；在长春任伪监察院长，为日本殖民机构效力，参与镇压抗日力量；参与伪满政权建设，在长春担任监察院长，监督推行殖民法令。……（共涉及61个地区的犯罪记录）；伪职：伪满参议府参议，伪奉天自治指导部部长（本溪籍）；罪行：伪满开国核心汉奸，策划伪满洲国建立，在东北全境培训伪官吏，推行殖民统治。主要任职在奉天，非本溪本地履职。；结局：1932 年病死，逃脱审判。；已列，补充其曾克扣劳工口粮。', '[]', '2026-09-10 09:57:13.997225', '2026-09-10 09:57:13.997225', '吉林', '四平', '伊通', NULL, NULL, NULL, NULL, '');
