INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9f8e4c55220040fdaf8d7bae9891153e', '郭映淮', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西朔州山阴；山西吕梁岚县；山西；山西忻州静乐', '[]', '[]', '抗日战争时期', '', '在岚县东村一带设立伪区公所，为日军征收粮款，告密抗日活动，导致多名群众被捕。；强制推行日伪教材，删除中国历史内容，强迫学校悬挂日本国旗，并检举有爱国言论的教师，导致多名教师被捕。', '[]', '2026-09-10 09:57:14.020184', '2026-09-10 09:57:14.020184', '山西', '吕梁', '岚县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9f93929af0b8484a8ace12c730c628a8', '于静远', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯富锦；吉林长春；辽宁沈阳和平；吉林_长春_南关；吉林_经开区；吉林_长春_双阳；辽阳，于冲汉之子；辽宁抚顺东洲；辽宁抚顺；吉林白山；吉林；吉林长春公主岭；辽宁沈阳；辽宁沈阳铁西；黑龙江牡丹江西安；黑龙江齐齐哈尔；辽阳，于冲汉长子；吉林、辽宁；吉林_延边_延吉；吉林永吉', '[]', '[]', '抗日战争时期', '', '伪职：伪满自治指导部训练处长、伪满经济部大臣；罪行：继承其父亲日立场，培训伪官吏，主持伪满经济掠夺，管控工矿粮食。；结局：苏军逮捕，抚顺战犯管理所关押，后特赦释放。；伪职：伪新京特别市市长、伪经济部大臣；罪行：主持新京市政，推行奴化宣传；主管伪满经济掠夺，管控工矿资源。；结局：苏军逮捕，抚顺战犯管理所，后期特赦释放。；组织协和会，宣传“王道乐土”，煽动民众支持伪满政权，监视抗日言行。；在长春推行粮食配给制，强征民夫，协助日军建立防空体系；参与修建军事铁路和公路，便利日军运输，强征劳工。；指挥伪警察配合日本宪兵，逮捕抗日地下工作者，制造多起惨案。；管理伪都“新京”，配合日本殖民统治，实施粮食配给制。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.998232', '2026-09-10 09:57:13.998232', '吉林', '永吉', '公主岭', NULL, NULL, NULL, NULL, '');
