INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9fd6d44692ac444e94425b861c31b4ba', '马兴元', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄市中；山东枣庄台儿庄；山西阳泉矿区；山东临沂罗庄；山东临沂；山东临沂河东；山西阳泉城区；山东枣庄薛城；山东枣庄', '[]', '[]', '抗日战争时期', '', '在峄县乡村充任保甲长，为日军征粮、派夫、搜集情报，迫害抗日群众。；日军占领枣庄煤矿后，马兴元组织矿区维持会，协助日军管理煤矿，强迫矿工劳动，为日军掠夺煤炭资源服务。；在枣庄、薛城地区担任伪保长、维持会成员，为日军征粮派款、搜集情报，协助日伪维持基层统治。；在伪沂州道警务系统任职，负责临沂及周边县伪警察调度，参与对罗庄地区抗日群众的镇压。；控制临沂城区商业，为日军筹集物资，配合经济封锁，压榨商户和百姓。', '[]', '2026-09-10 09:57:14.012804', '2026-09-10 09:57:14.012804', '山东', '临沂', '河东', NULL, NULL, NULL, NULL, '');
