INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('9fe991eed5864f64bd83a71348c233a1', '王泽民', NULL, NULL, NULL, NULL, 'exact', 'exact', '永年；河北；河北邯郸邯郸经开区；河北邯郸；河北邯郸永年', '[]', '[]', '抗日战争时期', '', '伪职：伪永年保安司令；与许铁英盘踞广府，抓捕迫害抗日家属；日降后改编国民党保安纵队。；结局：城破逃窜，后抓获处决；率伪警备队驻守永年城，协助日军封锁抗日武装，参与“清乡”行动，勒索百姓，强征捐税。；组织地方自卫团协助日军巡逻，在邯郸县西部山区多次参与“清剿”八路军游击队，杀害抗日村长。；伪职：伪永年保安司令；与许铁英合伙盘踞广府，抓捕迫害抗日家属，出城抢粮杀人；日降后改编为国民党保安纵队。；结局：永年城破逃窜，后被抓获处决', '[]', '2026-09-10 09:57:14.045282', '2026-09-10 09:57:14.045282', '河北', '邯郸', '永年', NULL, NULL, NULL, NULL, '');
