INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a0c696b0f959471f8b4ce660696a7fd3', '刘玉书', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；河北唐山滦州；河北唐山乐亭；天津滨海；安徽安庆；河北秦皇岛山海关；安徽阜阳颍州；安徽阜阳颍上；山西大同平城；北京延庆；北京、天津、山西、河北；安徽阜阳阜阳经开区；安徽阜阳；安徽滁州来安；安徽滁州明光；安徽滁州凤阳；安徽滁州；天津河北；河北廊坊；四川；北京丰台；北京大兴；北京昌平；吉林长春朝阳；北京海淀；北京石景山；北京_西城；北京门头沟；四川_广元；云南普洱西；河北唐山；天津_武清；湖南常德津；天津宁河；天津_河西；天津_津南；天津河东；山东临沂河东；云南普洱西', '[]', '[]', '抗日战争时期', '汪伪政权', '任伪北京市警察局局长，负责北平城内的治安监控，大肆搜捕抗日志士，协助日军进行“思想战”。；长期任伪北平警察头目，在丰台地区抓捕抗日地下人员，执行日伪保甲制度。；在任期间指挥伪警察在大兴等地抓捕抗日志士，破坏地下组织，协助日军设立“爱护村”和封锁沟。；在北平及大兴地区指挥伪警察，协助日军逮捕抗日志士，破坏地下交通线，参与“治安强化”运动。；在北平及延庆地区指挥伪警察，搜捕抗日地下人员，破坏中共地下组织，参与“治安强化运动”。……（共涉及30个地区的犯罪记录）；伪任职务：伪北平特别市后期市长。结局：抗战胜利 “鸿门宴” 被捕，判处徒刑，狱中病逝；在廊坊各县组织伪保安团，协助日军“扫荡”，并参与屠杀抗日群众。', '[]', '2026-09-10 09:57:13.992808', '2026-09-10 09:57:13.992808', '天津', '宁河', '南谯', NULL, NULL, NULL, NULL, '');
