INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a1023b510b1f4af6a1175107d3a56da6', '张子超', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口淮阳；河南周口；河南开封兰考；河南商丘豫东综合物流产业聚集；河南商丘；河南驻马店平舆；河南濮阳濮阳经开区；河南濮阳清丰；河北衡水故城；河南郑州上街；河南郑州巩义；河南驻马店驻马店经开区；河南驻马店新蔡；河南郑州新郑；河南郑州；河南驻马店；河南郑州；山西阳泉城区；河南平顶山汝州；河北衡水冀州；河北衡水；河南漯河源汇；河南濮阳；河南漯河舞阳；河南平顶山；河南商丘夏邑；河南商丘；河南安阳滑县；河南郑州惠济；河南郑州', '[]', '[]', '抗日战争时期', '', '统率伪保安团盘踞滑县，配合日军进攻冀鲁豫边区，捕杀抗日干部和群众。；新蔡沦陷后投敌，组织维持会，为日军征发粮食、牲畜，协助伪军扩编。；在兰封地区协助日军建立伪警察体系，搜捕抗日人员，镇压地方抗日活动。；日军侵占郑州北部惠济一带后，出面组织伪惠济维持会并任会长，协助日军征发粮食、劳工，维持地方伪秩序。；掌管郑州伪警察系统，搜捕抗日分子，镇压民众反抗，协助日军维持治安。；控制郑州伪警察系统，配合日军搜捕抗日人员，镇压市民反抗，管理良民证与通行证。；在郑州沦陷期间担任伪警察头目，协助日军搜捕抗日人员，维持城区治安，参与镇压民众抗日活动。；任伪舞阳县警察局长，协助日军镇压抗日活动，搜捕抗日人员，维持伪政权治安。；驻马店镇商人，日军侵占驻马店后组织维持会，任会长，为日军筹集物资、情报，协助建立伪政权。；驻马店镇人，日军占领驻马店后组织维持会，为日军筹集物资、招募伪职人员，协助日军管理驻马店城区。；故城沦陷后出面组织维持会，后任伪县长，为日军征粮征夫，镇压当地抗日活动。；汝南（邻近平舆）汉奸，组织维持会，协助日军在汝南、平舆一带建立伪政权，搜捕抗日人员。；临汝沦陷后任伪警察局局长，率伪警察配合日军搜捕抗日人员，维护汝州地区伪统治秩序。；在漯河镇（今源汇区）任伪警察所所长，带领伪警察配合日军巡查、抓捕抗日嫌疑人员，勒索商户。；睢县沦陷后组织维持会，后任伪县长，配合日军在睢县、商丘一带进行统治和扫荡。；为日军筹集军需物资，控制濮阳商业，配合日军经济封锁抗日根据地。；清丰县紧邻濮阳，张子超在日军占领后组织维持会，后任伪县长，为日军统治服务，影响波及濮阳地区。；汜水县（今属荥阳，与上街地区接壤）沦陷后任伪维持会会长，协助日军统治地方。；在深县、衡水交界地区活动，率伪军袭击抗日游击队，杀害村干部，抢掠民财。；巩县沦陷后投敌，组织伪保安团配合日军扫荡，镇压抗日群众，活动于巩县及周边地区。；郑州沦陷后投靠日军，任伪商会会长，协助日军征敛物资、控制经济，为占领军提供后勤支持，是郑州经济领域附逆者。；郑州沦陷后依附日军，以商会名义为日军筹款、筹粮、摊派物资，协助日军控制郑州经济与物资流通。；周口沦陷期间任维持会会长，配合日军建立伪基层政权，推行保甲连坐，协助征发劳工和物资。；日军占领平顶山煤矿后，出任伪煤矿株式会社理事长，强迫矿工劳动，掠夺煤炭资源，配合日军经济侵略。；控制商丘物资流通，为日军采购军粮和战略物资，协助经济掠夺，是商丘地区经济附逆的代表人物。；协助日军控制商丘物资流通，为日军采购军需，压榨商户，配合经济掠夺。', '[]', '2026-09-10 09:57:14.044273', '2026-09-10 09:57:14.044273', '河北', '衡水', '冀州', NULL, NULL, NULL, NULL, '');
