INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a2a9dbdff73f468790526170e7cbb0f3', '李成五', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮北杜集；安徽滁州来安；安徽阜阳临泉；安徽亳州涡阳', '[]', '[]', '抗日战争时期', '', '临泉本地人，抗战期间组织伪维持会，为日军征粮、派夫，协助日军在临泉及周边地区的占领统治。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，其活动范围涉及滁县与来安交界地区。；涡阳沦陷期间组织伪维持会，任会长，为日军筹粮、派夫、维持地方伪秩序，协助日军控制涡阳地区。；在濉溪、杜集一带充当日伪基层爪牙，催粮逼款、监视民众，协助日军维持占领秩序。', '[]', '2026-09-10 09:57:14.004960', '2026-09-10 09:57:14.004960', '安徽', '亳州', '涡阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a2adc68ced4f489b9dff3b43330b3dc8', '陈维周', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建_龙岩；湖北_宜昌；福建福州平潭；福建福州；福建福州闽侯；福建福州；湖北_武汉；福建莆田城厢；福建莆田；河北衡水深州；河北衡水；广东江门新会；广西北海；福建厦门；福建福州福清；福建福州连江；广东阳江阳春；广东阳江；福建莆田秀屿；福建莆田；福建莆田；福建福州台江；福建福州；福建福州鼓楼；江苏南京鼓楼；福建福州福清；江苏_南京', '[]', '[]', '抗日战争时期', '', '福州商界附逆者，在日军占领期间组织商会为日伪筹款、摊派物资。；新会伪警察头目，率伪警配合日军搜捕抗日人员，控制新会城及周边乡镇。；任伪湖北省教育厅厅长，推行奴化教育，篡改教材，强制学校教授日语和亲日内容，毒害青少年。；在衡水、深州一带为日军出谋划策，协助推行伪化政策。；在伪福州警察局任职期间，参与日伪治安管制、情报搜集和逮捕抗日嫌疑人员等活动。；在伪湖北省政府中负责财政，为日军搜刮民财，推行伪币。；福建伪政权高层之一，参与制定伪化政策，协助日军在福建各地包括莆田地区推行保甲制度和物资统制，镇压抗日运动。；在日军控制阳江期间出任伪县长，推行伪政令，协助日军对阳江及周边阳春等地的控制与掠夺。；管理伪保安部队后勤；在钦州、廉州（合浦）、北海等地推行伪政权统治，协助日军掠夺物资，镇压抗日活动。；福建厦门人，1938年厦门沦陷后出任伪厦门特别市市长，在厦门及闽南地区推行日伪统治，协助日军维持占领秩序。；在日军占领福州期间任伪福州维持会教育科科长，推行奴化教育，篡改教材，强迫学校悬挂日伪旗帜。；连江沦陷期间组织伪维持会，配合日军征粮、派款、修筑工事，协助日伪控制连江沿海。；福州鼓楼一带保甲长，协助日军登记户口、征发民夫，并监视居民动向。；福清人，投靠日军后组织伪维持会，为日军筹粮筹款，协助日军搜捕抗日人士，压迫福清民众。；在莆田伪警察系统中任职，带领伪警配合日军扫荡沿海抗日据点。；汪伪时期在莆田、仙游一带活动，协助伪省府推行‘清乡’与保甲连坐，参与镇压抗日民众，为日军搜集地方情报。；为日伪政权筹措经费，发行伪币，掠夺福建物资。', '[]', '2026-09-10 09:57:14.028755', '2026-09-10 09:57:14.028755', '广东', '阳江', '阳春', NULL, NULL, NULL, NULL, '');
