INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a481ad30c1f8419381444c680ec845da', '黄梦年', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林平乐；云南普洱西；广西柳州柳北；广西柳州；广西桂林；云南普洱西；广西梧州岑溪；广西梧州；广西柳州柳城；广西南宁西乡塘；广西崇左；广西梧州；广西柳州鹿寨；广西南宁江南；广西南宁；云南普洱西；广西桂林象山；广西柳州；广西玉林容县；广西玉林；广西梧州长洲；广西梧州；广西百色田阳；广西百色', '[]', '[]', '抗日战争时期', '', '日军侵占梧州期间，组织伪维持会，协助日军推行伪化统治、征调民力。；率领伪保安队配合日军扫荡抗日游击队，镇压梧州、岑溪一带的抗日活动。；在日军占领广西期间，参与伪广西省政权，负责警务与治安，协助日军搜捕抗日人士、镇压民众反抗。；在日军占领广西期间依附日伪，担任伪警务头目，参与搜捕抗日人士、镇压民众反抗。；日军占领广西部分地区后，参与伪政权筹备，协助日军在桂林、柳州一带推行伪化统治。；梧州长洲一带保甲长，协助日军征发民夫、物资，监视居民。；日军侵占柳城期间，组织伪维持会，为日军征派粮食、民夫，协助推行伪化统治。；协助张君度组织伪维持会，负责联络日军与地方士绅，为日军提供情报。；日军侵入百色地区时，组织伪维持会，为日军征集粮食、劳工，并参与搜捕抗日人员。；日军侵占鹿寨期间，任伪鹿寨维持会财政科科长，协助日军控制财政、掠夺资源。；在南宁沦陷区担任伪保甲长，协助日军清查户口、征发劳役、监视居民。；在兴业地区组织伪维持会，为日军服务，兴业与玉林、容县相邻。；在伪广西政权中负责财政，为日军搜刮民财、筹措军费。；日军第二次入侵广西期间，出面组织伪广西省维持会，任会长，为日军筹粮筹款、招募伪职人员。；与张君度共同组织伪柳州维持会，负责联络地方士绅，为日军筹粮筹款。', '[]', '2026-09-10 09:57:14.031326', '2026-09-10 09:57:14.031326', '广西', '南宁', '江南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a482681bd34e4187a0c078c9b9833eb6', '刘荫卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南新乡原阳；河南新乡', '[]', '[]', '抗日战争时期', '', '在豫北伪政权中任职，协助日军控制新乡一带，推行治安强化运动。', '[]', '2026-09-10 09:57:14.048312', '2026-09-10 09:57:14.048312', '河南', '新乡', '原阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4851790a5e44f7b8610ba8b9fb9268c', '周瑞卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆门京山；湖北黄石；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在宋河镇为日军设立据点筹粮派款，诱逼商户附逆，协助日军维持地方治安。；推行奴化教育，篡改教材，强迫学生学习日语，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.057005', '2026-09-10 09:57:14.057005', '湖北', '荆门', '京山', NULL, NULL, NULL, NULL, '');
