INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4ad813b912f4e77808c02bdba60aee4', '赵锡章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北衡水衡水滨湖；河北；河北沧州沧州高；河北沧州', '[]', '[]', '抗日战争时期', '', '日军占领沧州后出任维持会长，为日军筹粮筹款，强迫商户‘献金’，协助建立伪政权。；充当日军爪牙，负责河间县城及周边据点防务，参与‘清乡’行动，杀害抗日家属，强征民夫修筑炮楼。；日军占领深县后率先组织维持会，为日军筹粮筹款，强迫民众欢迎日军，协助建立伪政权。；任伪深县知事，协助日军建立伪政权，多次带路“清乡”，残害抗日军属。', '[]', '2026-09-10 09:57:14.043094', '2026-09-10 09:57:14.043094', '河北', '沧州', '沧州高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4b23fa1f50e4dc3b258b01e6c9b11b5', '张百熙', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南永州双牌；湖南郴州北湖；辽宁沈阳大东；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '双牌本地人，日军侵占期间出任伪保甲长，协助日军征粮、派夫、搜集情报，压迫当地民众。；衡阳沦陷后出任伪警察局长，协助日军维持城区秩序，抓捕抗日人员，镇压民众。；在日军占领郴县期间出面组织伪教育会，推行奴化教育，协助日军宣传“大东亚共荣”。', '[]', '2026-09-10 09:57:14.058883', '2026-09-10 09:57:14.058883', '湖南', '永州', '双牌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4c2596fa0af4ad9bdb9632e15bf5d68', '区大庆', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；广东广州从化；广东广州荔湾；山西阳泉城区；广东清远连山；广东清远；云南普洱西；广东深圳罗湖；广东深圳', '[]', '[]', '抗日战争时期', '', '清远沦陷期间组织伪维持会，为日军征派粮秣、夫役，协助维持占领区治安。；从化沦陷期间出任伪维持会会长，为日军征粮、派夫、维持地方伪秩序。；曾任伪广州市警察局局长，协助日军控制广州城区，镇压抗日活动。；负责伪广东宣传事务，在深圳、罗湖等地进行亲日宣传，配合日军进行思想控制。；广东教育文化领域附逆者，推行奴化教育，活动区域与广西邻近。；参与广州沦陷初期的伪维持会活动，协助日军控制广州城区。', '[]', '2026-09-10 09:57:14.026802', '2026-09-10 09:57:14.026802', '广东', '广州', '从化', NULL, NULL, NULL, NULL, '');
