INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4df9eafdb954e2ca2aeccd52b59e95e', '王河', NULL, NULL, NULL, NULL, 'exact', 'exact', '长治南关', '[]', '[]', '抗日战争时期', '', '伪职：潞安宪兵队便衣特务头目（上党四大汉奸之一）；罪行：叛变投敌，带领宪兵抓捕抗日军民；协助日军拿平民做活体解剖，制造多起惨案。；结局：长治解放公审枪决', '[]', '2026-09-10 09:57:14.078315', '2026-09-10 09:57:14.078315', '山西', '长治', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4dfc16acc5e46b3ae1c10d17b393a10', '王臣盛', NULL, NULL, NULL, NULL, 'exact', 'exact', '郎溪钟桥', '[]', '[]', '抗日战争时期', '', '伪职：内奸匪徒；罪行：与任水生合伙通敌，传递情报，策划抢劫游击队武器物资。；结局：被游击连捕获处决。', '[]', '2026-09-10 09:57:14.072102', '2026-09-10 09:57:14.072102', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4eb4281102d468f95038dceb264bca7', '张耀南', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南安阳龙安；河南安阳汤阴；湖北荆门沙洋；河南新乡辉县；河南新乡；山东淄博沂源；河南安阳汤阴；河南安阳；河南驻马店驻马店经开区；河南驻马店；河南信阳息县；河南信阳；河南安阳内黄；河南安阳；湖北荆门掇刀；河南信阳商城', '[]', '[]', '抗日战争时期', '', '在沙洋镇组织伪维持会，为日军筹集物资、拉夫派工，协助日军控制汉水航运。；在掇刀石地区组织维持会，为日军筹集物资、情报，带领日伪军搜捕抗日干部和群众。；在安阳伪政权中任职，执行日军征粮、派夫、保甲连坐等政策，波及内黄等周边县。；推行奴化教育，在新乡、辉县各学校强制开设日语课，篡改历史教材，组织学生参拜神社，毒化青少年思想。；在安阳沦陷后任伪县长，配合日军统治，推行保甲制度，搜捕抗日人员。；在汤阴县推行日伪政策，与安阳日伪政权协同行动，征粮派夫、镇压抗日活动。；沂水与沂源相邻，其伪政权活动覆盖沂源部分地区，组织维持会、保甲，配合日军对沂蒙山区的扫荡。；在伪河南省政府任职，参与制定亲日政策，协助日军在河南各地推行伪化统治，涉及信阳地区。；率伪军在豫南地区配合日军清乡，袭击抗日游击队，抢掠民众。；率伪军在遂平及驻马店西北地区为日军护路、征粮，袭击抗日武装。', '[]', '2026-09-10 09:57:14.015982', '2026-09-10 09:57:14.015982', '山东', '淄博', '沂源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a4f4e75f8b2847189ff3a45544b13c96', '秦庆霖', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏淮安；江苏扬州；广西桂林临桂；广西桂林；安徽滁州天长；江苏泰州；不详；东台、丁溪、草堰', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪 25 师师长，如皋地区主力伪军，参与多次清乡扫荡。。结局：国民政府收编后，因汉奸罪行审判处决；伪职：伪 25 师师长；罪行：伪军将领，控制东台运河沿线据点，盘剥沿河百姓，协助日军运输掠夺物资。；结局：抗战胜利后被逮捕惩处。', '[]', '2026-09-10 09:57:14.009177', '2026-09-10 09:57:14.009177', '安徽', '滁州', '天长', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a508adc50ac0400697cd47535f8d5230', '刘志强', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州柳北；广西柳州；广西钦州浦北；广西北海合浦；广西贵港港北；广西崇左龙州；广西北海合浦；广西北海；广西贺州；辽宁沈阳大东；广西梧州龙圩；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '收编地方土匪组建伪军，在钦州、合浦、浦北交界地区配合日军扫荡抗日游击队。；在梧州推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青少年。；在北海伪警察机构任职，带领伪警巡查街道，逮捕可疑抗日人员并交日军处理。；在日占期间推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；在龙州担任伪警察局长期间，建立特务网络，逮捕抗日人员，强征劳工为日军修筑工事，民愤极大。；日军占领柳州后，出面组织伪商会，为日军筹款筹粮，协助物资统制。；组织伪保安队，配合日军下乡扫荡，抓捕抗日游击队员和无辜群众，烧杀抢掠。', '[]', '2026-09-10 09:57:14.030541', '2026-09-10 09:57:14.030541', '广西', '北海', '合浦', NULL, NULL, NULL, NULL, '');
