INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a5c4f8829a52468ba5363612f7047d93', '李兴甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳内乡；河南南阳南阳示范；河南南阳；河南南阳社旗；河南南阳；河南南阳镇平', '[]', '[]', '抗日战争时期', '', '镇平县人，1945年日军入侵镇平期间组织维持会，为日军服务，协助征粮、派款，维持伪秩序。；在日军控制下出任伪南阳县县长，推行保甲制度，征发民夫、粮食，配合日军扫荡抗日武装。；1945年日军进犯内乡时，出面组织伪维持会，为日军提供物资、情报，协助日军控制内乡地区。；1945年日军占领南阳时，组织伪南阳县维持会，配合日军征发民夫、物资，维持日占区统治。', '[]', '2026-09-10 09:57:14.046663', '2026-09-10 09:57:14.046663', '河南', '南阳', '内乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a5e42d1eec2d412a8b7e8e6f89bc02bb', '李先教', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州北湖；湖南_郴州_苏仙；湖南岳阳平江；湖北鄂州华容', '[]', '[]', '抗日战争时期', '', '日军侵占华容后组织伪维持会，为日军筹办粮草、情报，协助建立伪基层政权。；日军侵占郴县期间出面组织维持会，为日军征派民夫、物资，协助维持占领区秩序。；日军侵占郴县期间，出面组织郴县维持会，为日军征派粮秣、夫役，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.058008', '2026-09-10 09:57:14.058008', '湖南', '岳阳', '平江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a5edb13e37c444bfbf0f0c018b38cf03', '张焕相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁葫芦岛；辽宁鞍山岫岩；辽宁本溪明山；辽宁本溪；辽宁辽阳；辽宁锦州凌海；辽宁锦州；黑龙江牡丹江阳明；抚顺；黑龙江黑河北安；黑龙江黑河；黑龙江哈尔滨；吉林经开区；黑龙江哈尔滨松北；辽宁锦州凌河；辽宁锦州；吉林长春公主岭；吉林_长春_榆树；辽宁沈阳新民；辽宁沈阳；辽宁盘锦双台子；黑龙江_哈尔滨_松北；辽宁沈阳苏家屯；辽宁_沈阳_和平；辽宁锦州义县；辽宁锦州；辽宁沈阳法库；吉林、辽宁；辽宁抚顺新抚；黑龙江牡丹江', '[]', '[]', '抗日战争时期', '', '审判抗日志士，判处死刑或重刑，维护日伪统治。；组织保安队配合日军“讨伐”，烧毁村庄。；率伪保安队配合日军扫荡新抚地区抗日游击队，杀害多名抗日群众。；负责伪奉天省警务，残酷镇压抗日军民，多次参与“讨伐”行动。；原东北军将领，投日后为伪满出谋划策，在沈阳地区动员地方士绅支持日军统治。……（共涉及14个地区的犯罪记录）；伪职：伪满司法部大臣、参议府参议；罪行：抚顺籍，原奉系将领，投敌出任伪满高官，协助镇压东北反日力量。；结局：1945 被捕，关押抚顺战犯管理所，后病死。', '[]', '2026-09-10 09:57:14.000260', '2026-09-10 09:57:14.000260', '吉林', '经开区', '公主岭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a5f326ebe1d841db862712e76339de6f', '顾馨一', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海浦东', '[]', '[]', '抗日战争时期', '', '在川沙（今浦东新区）推行日伪统治，镇压当地抗日武装。', '[]', '2026-09-10 09:57:13.979227', '2026-09-10 09:57:13.979227', '上海', '浦东', NULL, NULL, NULL, NULL, NULL, '');
