INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a60aabd76115481a8ce363ffa3bea5e3', '李朗星', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北随州；河南南阳；湖北襄阳宜城；湖北襄阳枣阳；湖北襄阳；湖北襄阳樊城；湖北襄阳；山西阳泉城区；湖北襄阳谷城；湖北襄阳；河南南阳方城；河南南阳；湖北襄阳；湖北十堰竹山；湖北十堰房县；湖北襄阳襄城；辽宁沈阳大东；河南南阳桐柏；河南南阳；湖北襄阳保康；湖北襄阳；湖北襄阳老河口；湖北襄阳；湖北襄阳南漳；湖北襄阳', '[]', '[]', '抗日战争时期', '', '组织伪保安团配合日军对襄阳周边抗日根据地进行袭扰，抓捕、审讯抗日军民。；在湖北伪政权中任职，并曾出任伪襄阳县县长，推行日军殖民统治政策，参与清乡与物资统制。；在南阳沦陷区参与伪政权筹建，协助日军推行保甲制度，登记户口，压制抗日活动。；在房县地区充当日伪基层爪牙，担任伪保长并参与维持会活动，负责摊派捐税、监视抗日群众、传递日伪政令。；1945年日军占领南阳期间，出任伪南阳县政府县长，为日军征粮、派款、推行奴化教育。；在鄂北包括随州地区推行清乡，组织伪军和伪警察封锁抗日根据地，编查保甲，镇压民众抗日活动。；任伪襄阳县政府警察局局长，协助日军搜捕抗日人员，推行保甲连坐，控制襄阳城区及近郊。；在豫南信阳、南阳一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民。；在沦陷区推行奴化教育，篡改教材，宣传所谓‘大东亚共荣圈’。；河南南阳人，抗战期间任伪南阳县长，配合日军统治南阳地区。；投敌后任伪襄阳地区保安团团长，配合日军扫荡抗日根据地，残害抗日军民。；在伪湖北省政府任职期间，负责襄阳地区伪行政事务，推行日军指令，征发物资、编组伪保甲，协助日军控制鄂西北。；抗战期间在宜城地区出任伪县长，协助日军推行殖民统治，征发民夫、物资。；襄阳沦陷后投敌，参与组织伪襄阳县政府，为日军维持地方统治、征发物资。；在襄阳地区协助日军组建伪保安团，参与清乡、搜捕抗日人员。；襄阳沦陷初期组织维持会，为日军筹集物资、招募伪职人员，协助建立伪基层政权。', '[]', '2026-09-10 09:57:14.046543', '2026-09-10 09:57:14.046543', '河南', '南阳', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a60e9261190e4a4eaf5776ba417dda09', '李尚贤等九人', NULL, NULL, NULL, NULL, 'exact', 'exact', '辉县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸；罪行：1944年辉县抗日政府对李尚贤等九名汉奸处以极刑；结局：1944年被辉县抗日政府处决', '[]', '2026-09-10 09:57:14.087070', '2026-09-10 09:57:14.087070', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
