INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a615c8474d394f93b99af88d9c1784f4', '王一凡', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪江宁县伪县长，伪县府驻秣陵关；推行保甲、良民证，征粮拉夫，配合日伪对横山根据地扫荡清剿。。结局：战后汉奸罪判处徒刑关押', '[]', '2026-09-10 09:57:14.072308', '2026-09-10 09:57:14.072308', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
