INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a65d90fca6344d54873c4667d71d0e1c', '赵筱亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城旌德；安徽宣城；安徽安庆怀宁；安徽滁州滁州经开区；安徽滁州；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '怀宁本地人，投敌后任伪保安大队长，率伪军配合日军在怀宁石牌、高河、月山等地清剿抗日游击队，强征民夫与粮食，民愤较大。；在宣城邻近的郎溪地区组织伪维持会，为日军征发物资、维持治安。；滁县商人，日军占领滁县后出任伪商会会长，协助日军统制物资、征收商税，为日军采购军需品，压制商户抗日活动。；负责滁县新民会，进行亲日宣传，组织民众参加日军组织的集会与劳役，推行奴化思想。', '[]', '2026-09-10 09:57:14.007673', '2026-09-10 09:57:14.007673', '安徽', '安庆', '怀宁', NULL, NULL, NULL, NULL, '');
