INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6bc034808724ceaa85f2e5ed0358bb5', '胡泽吾', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林资源；安徽安庆太湖；安徽安庆；安徽宿州；安徽阜阳阜南；安徽阜阳；安徽安庆；安徽安庆望江；安徽安庆；安徽六安金安；安徽六安；安徽六安；安徽合肥；安徽池州；江苏_南京', '[]', '[]', '抗日战争时期', '', '六安本地士绅，日军占领六安期间出面组织维持会，为日军筹粮筹款，维持地方伪秩序。；汪伪安徽省警务负责人，指挥伪警察配合日军镇压抗日活动，搜捕抗日人员。；汪伪安徽省警务负责人，在合肥及安徽占领区实施特务警察统治，镇压抗日活动。；汪伪安徽省警务负责人，统辖伪警察力量，在池州等沦陷区搜捕抗日人士，维持殖民秩序。；汪伪安徽省警务负责人，统辖伪警察力量，在安庆等地实施特务统治，镇压抗日活动。；在安庆沦陷区推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动。；阜阳沦陷期间任伪县长，为日军征粮派款，组织伪警察和保甲，迫害抗日群众。；推行奴化教育，控制学校宣传亲日思想；安庆沦陷区伪警察头目，协助日军搜捕抗日人员，镇压市民反抗，维护日伪统治秩序。；在伪安徽省政权中负责建设事务，为日军修建军事设施、掠夺资源提供便利。；汪伪安徽财政官员，在安徽沦陷区推行伪币、征粮征税，为日军提供经济支持，涉及宿州地区。', '[]', '2026-09-10 09:57:14.005307', '2026-09-10 09:57:14.005307', '安徽', '六安', '巢湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6be21b9831c49688c9d8c83fc25e3d2', '纪大作', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山长白；吉林通化；吉林通化二道江；吉林通化；吉林白山临江', '[]', '[]', '抗日战争时期', '', '伪满临江县（今临江市）县长，积极推行日伪殖民政策，强征劳工修建警备道路和碉堡，协助日军“讨伐”抗联，并参与镇压当地民众反日运动。；任伪通化县长期间，强征民夫修建警备道路和碉堡，配合日军“归屯并户”，制造无人区，迫害抗日群众。；在长白县任伪县长，强制推行“归屯并户”，烧毁民房，切断抗联与群众联系。；积极为日军征粮派夫，强征民夫修筑警备道路和碉堡，镇压当地抗日民众，曾亲自带队烧毁抗联联络点村庄。', '[]', '2026-09-10 09:57:13.999814', '2026-09-10 09:57:13.999814', '吉林', '白山', '临江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6c1cea6dac447b0960d6d8347bcbf00', '谢振华', NULL, NULL, NULL, NULL, 'exact', 'exact', '华容县', '[]', '[]', '抗日战争时期', '', '伪职：华容县维持会会长→伪华容县长；罪行：1943年3月日军侵占华容后出任华容县维持会会长；1944年春伪华容县政府成立后任县长', '[]', '2026-09-10 09:57:14.081408', '2026-09-10 09:57:14.081408', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
