INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6d7c75edaf64ef1b31ce13d4d1c0ff6', '李焕章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '不详；山西', '[]', '[]', '抗日战争时期', '汪伪政权', '率伪保安队多次配合日军扫荡夏县抗日根据地，抓捕并杀害抗日干部和群众，烧毁村庄，民愤极大。；伪任职务：同善社高层，负责联络汪伪周佛海，往返湖南、贵州，布置贵州地下阴谋活动，传递日伪指令给黔东各道首。。结局：抗战胜利抓捕判刑', '[]', '2026-09-10 09:57:14.077239', '2026-09-10 09:57:14.077239', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6db331ec50d4325951bbe9694995203', '谢叶生', NULL, NULL, NULL, NULL, 'exact', 'exact', '江都公道镇', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：伪地方情报头目，与伪军高层结拜，大开香堂收徒近百人，给日伪提供情报。。结局：抗战胜利公审镇压邗江史志网', '[]', '2026-09-10 09:57:14.088029', '2026-09-10 09:57:14.088029', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a6df687f02a347e1894a6aac94b0c26c', '高福斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博淄川；淄川县', '[]', '[]', '抗日战争时期', '', '伪职：淄川县维持会会长（首任）；罪行：1937年12月日军占领淄川后，高福斋出面建立汉奸组织——地方治安维持会。依仗日军势力向群众要粮、要款。1937年12月底，受日军指使以“宣抚安民”为由派汉奸张克顺等到河东村招抚“铁板会”。1938年2月2日（正月初三），高福斋持扩音筒在杨家寨村口喊话诱骗村民打开寨门，致使日军入村屠杀', '[]', '2026-09-10 09:57:14.015995', '2026-09-10 09:57:14.015995', '山东', '淄博', '淄川', NULL, NULL, NULL, NULL, '');
