INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a706c93e692a45d0b2144964c4c29fa6', '赵雪门', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏_宿迁_宿城；浙江绍兴诸暨', '[]', '[]', '抗日战争时期', '', '为日伪政权筹措经费，加重地方捐税，支持日军侵略战争。；在诸暨推行“清乡”，组织伪自卫团，配合日军对诸暨山区进行扫荡。', '[]', '2026-09-10 09:57:14.034440', '2026-09-10 09:57:14.034440', '浙江', '绍兴', '诸暨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a71413744256416cacedd6bcba455c50', '常尧臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：原东北军骑兵旅长，随熙洽投敌，伪吉林警备军将领。结局：苏军逮捕，抚顺战犯管理所，病亡狱中', '[]', '2026-09-10 09:57:14.068146', '2026-09-10 09:57:14.068146', '吉林', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a720a1792c5b478b99d2d336e38757be', '高步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁汾阳；山西_朔州；山西吕梁中阳；山西忻州保德；山西_阳泉_盂县；山西忻州；山西忻州原平；山西吕梁石楼；山西吕梁；河北保定涞源；山西忻州忻府；山西_忻州_偏关；山西大同新荣；山西、河北；山西吕梁岚县；山西吕梁孝义；山西阳泉平定；山西大同阳高；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '率保安团配合日军对孝义西部山区进行“铁壁合围”，烧毁村庄十余个，抢掠牲畜粮食，并参与活埋抗日军属。；率伪军驻防岚县普明镇，多次袭击八路军游击队，抢劫百姓财物，杀害抗日军属。；日军占领汾阳后出任维持会长，为日军筹集粮款，强征劳役，并告密导致多名抗日群众被捕牺牲。；负责为日军搜刮民财，强征各种苛捐杂税，在新荣地区逼死多名交不起税的农民，并参与鸦片专卖毒害百姓。；组织新民会宣传“大东亚共荣”，诱骗青年参加伪军，并协助日军征集慰安妇。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019830', '2026-09-10 09:57:14.019830', '山西', '吕梁', '中阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a72a612045be4a0199e2356dba0eecc8', '黄鳌', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃', '[]', '[]', '抗日战争时期', '', '任伪邛崃县维持会委员，协助日军维持地方秩序，推行奴化教育，为日军征集物资。', '[]', '2026-09-10 09:57:14.002273', '2026-09-10 09:57:14.002273', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a733e546f5024a4ab500561c5e3ae0e2', '郭全忠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_晋城_泽州', '[]', '[]', '抗日战争时期', '', '任伪警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织。', '[]', '2026-09-10 09:57:14.023243', '2026-09-10 09:57:14.023243', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a7340072a0284be386f0d4519d053eb2', '王静轩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江伊春；辽宁沈阳苏家屯；辽宁葫芦岛绥中；辽宁大连；吉林长春长春经开区；吉林；吉林松原前郭尔罗斯；辽宁沈阳康平；辽宁沈阳沈北；黑龙江黑河北安；黑龙江黑河；辽宁鞍山岫岩；吉林长春公主岭；吉林、辽宁；吉林；辽宁铁岭开原；辽宁辽阳灯塔；辽宁辽阳；吉林白城白城经开区；吉林白城；辽宁_沈阳_大东', '[]', '[]', '抗日战争时期', '', '已列，补充其曾参与“大讨伐”。；任伪吉林市市长期间，配合日军修建丰满水电站，强征劳工，造成大量劳工死亡，并协助日军推行“治安肃正”政策。；为日军宪兵队充当翻译，参与刑讯逼供抗日人士，罪行累累。；原吉林省官员，投日后在吉林市伪省公署任职，参与推行保甲制度。；辽宁大连人，任伪副市长，协助日本市长管理市政，推行粮食配给制，导致大连民众饥荒。；协助日伪警察镇压抗日活动，参与抓捕地下党员。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.996484', '2026-09-10 09:57:13.996484', '吉林', '松原', '前郭尔罗斯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a735fa59ce5744d68fbf6c766c722c1b', '张德能', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡阳保税；湖南衡阳；湖南衡阳雁峰；湖南衡阳；湖南衡阳常宁；湖南衡阳', '[]', '[]', '抗日战争时期', '', '衡阳沦陷后主持伪教育会，推行奴化教育，篡改教材，向学生灌输亲日思想。；控制衡阳商业，为日军采购军需物资，强制商户缴纳“献金”，协助日军经济掠夺。；参与衡阳伪维持会具体事务，负责与日军联络、传达命令、摊派物资。', '[]', '2026-09-10 09:57:14.059489', '2026-09-10 09:57:14.059489', '湖南', '衡阳', '常宁', NULL, NULL, NULL, NULL, '');
