INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a7a09b93204946bb8d8c95a31531b447', '李子清', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南鹤壁鹤山；河南鹤壁', '[]', '[]', '抗日战争时期', '', '在鹤壁集地区组织维持会，为日军筹集粮草、提供情报，协助日军控制当地煤矿资源。', '[]', '2026-09-10 09:57:14.049171', '2026-09-10 09:57:14.049171', '河南', '鹤壁', '鹤山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a7a96fedb4dd4179ac8df49557d17834', '陈国辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德蕉城；福建厦门海沧；福建厦门；福建泉州德化；福建泉州；福建漳州芗城；福建泉州；福建龙岩武平；福建漳州；福建泉州金门；福建泉州；福建泉州；福建莆田；福建龙岩；福建龙岩长汀；福建龙岩；福建漳州云霄；福建漳州；福建泉州南安；福建莆田；福建厦门同安；福建泉州惠安；福建泉州；福建泉州安溪；福建泉州；福建漳州华安；福建龙岩；福建泉州南安；福建厦门；福建泉州；福建_厦门；福建漳州；福建漳州平和；福建泉州', '[]', '[]', '抗日战争时期', '', '原为闽南土匪武装首领，1931年前后接受日本特务机关拉拢，在泉州、惠安一带组织伪军，配合日军侵扰闽南沿海，后被十九路军击败处决。；在闽南包括同安一带收编土匪、组织伪军，配合日军骚扰抗日根据地。；原福建地方军阀，抗战初期投靠日军，在闽南组织伪军，配合日军对闽西南抗日武装进行清剿，活动范围接近龙岩地区。；原为闽南地方军阀，九一八事变后与日本特务机关接触，企图借助日军势力割据闽南，后在漳州一带被十九路军击溃。；长期盘踞泉州、南安、安溪一带，为非作歹，后虽被国民党收编，但其部属在抗战初期有投敌附逆行为，对闽南地方造成严重危害。；长期盘踞闽南、闽西一带，曾与国民党地方势力及日伪方面有勾连，在龙岩、漳平、华安等地活动，对地方民众横征暴敛，后被国民党方面处决。；长期盘踞闽南、闽西一带，曾控制漳平、龙岩部分区域，勾结地方豪绅与日伪势力，扰害地方，后被国民党当局处决。；原为地方武装头目，后投敌任伪保安队头目，在漳州、云霄一带协助日军维持治安、镇压抗日活动。；长期盘踞泉州、德化、永春一带，割据地方，与日伪势力有勾连，后被国民党当局处决；其部属在闽南地区活动，对地方社会造成严重破坏。；福建南安人，长期盘踞泉州、莆田一带，1930年代初期接受国民党收编后仍割据地方，后与日军及伪政权暗中联络，其部属在泉州沿海地区配合日军行动，1937年被捕处决。；在福建沿海及闽西南地区收编武装，投靠日军，任伪军支队司令，参与对龙岩、漳州一带抗日游击队的扫荡与封锁。；长期盘踞闽南、龙岩一带，勾结日本势力，组织伪军，扰乱地方，后被十九路军擒获处决。；福建地方武装头目，曾与日军勾结，在闽南及闽东部分地区进行伪化活动，后为抗日武装所制。；闽南地方武装头目，曾与日伪势力勾连，在厦门、海沧周边扩张势力，扰害地方。；盘踞泉州、永春、德化一带，割据闽南，后接受国民党收编，但其势力长期控制泉州地区，横征暴敛，与日伪势力有勾连。；盘踞泉州、南安一带，接受国民党收编后仍割据地方，后与日军及伪政权暗中勾连，其部属在泉州、南安地区横征暴敛、残害民众。；盘踞泉州、永春、安溪一带，割据闽南，后接受国民党收编，但其部属在地方横征暴敛，与日伪势力有暗中勾连，1932年被十九路军处决。；早年盘踞泉州、永春、德化一带，1931年后接受国民党收编前后与日方有勾连，在泉州及洛江周边扩张武装势力，横征暴敛，后被十九路军处决。；盘踞泉州、南安、永春、德化、安溪、惠安、莆田、仙游等地，割据闽南，横征暴敛，与日本势力暗中勾连，后被十九路军以汉奸罪名处决。；原为福建地方军阀，抗战后投靠日军，在闽南漳州、泉州一带收编土匪武装，为日军提供情报与后勤支持。；福建地方武装头目，抗战初期一度投靠日军，在闽南漳州、泉州一带活动，后被国民政府处决。；在闽南一带收编土匪武装，投靠日军，配合日军扫荡抗日游击队，残害百姓。；福建南安人，早年盘踞泉州、晋江一带。抗战爆发后投靠日军，在厦门、泉州沿海收编土匪武装，组织伪军配合日军登陆与扫荡，并诱降地方武装，为日军搜集晋江、泉州一带情报。；泉州沦陷后出面组织维持会，协助日军推行保甲制度，征发民夫物资，镇压抗日活动。；泉州沦陷前后投靠日军，组织伪维持会，协助日军维持地方秩序、征粮拉夫，并出任伪晋江县县长，为日军在泉州地区的统治服务。；泉州本地武装头目，抗战初期投靠日军，组织伪自治军配合日军登陆福建沿海，在泉州、金门一带推行伪化统治，搜捕抗日人士。', '[]', '2026-09-10 09:57:14.060794', '2026-09-10 09:57:14.060794', '福建', '厦门', '同安', NULL, NULL, NULL, NULL, '');
