INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a8097c65765a4ee39c8439db160e0bdd', '仲养斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '沭阳及周边', '[]', '[]', '抗日战争时期', '', '伪职：伪沭阳县伪军旅长；罪行：率伪军配合日军反复扫荡淮海区根据地，直接间接残害六十余名抗日志士与平民；日本投降后投靠国民党继续反共作恶。；结局：1945 年 11 月抓捕归案，公审枪决。', '[]', '2026-09-10 09:57:14.072335', '2026-09-10 09:57:14.072335', '江苏', '宿迁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a814f7c51d7a4bac886e7d42bf971852', '李映棠', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西吕梁中阳；山西吕梁离石', '[]', '[]', '抗日战争时期', '', '日军占领离石后率先投敌，组织维持会，协助日军建立伪政权，向中阳、离石一带村庄派款征夫。', '[]', '2026-09-10 09:57:14.019802', '2026-09-10 09:57:14.019802', '山西', '吕梁', '中阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a81549f88b624af98b396a92f4c6ae37', '姚金陵', NULL, NULL, NULL, NULL, 'exact', 'exact', '荆门县', '[]', '[]', '抗日战争时期', '', '伪职：土顽头目（汉奸）；罪行：1942年10月，派一个连到杨家集投靠日军，企图与日军合伙对荆南抗日游击队实行大“清剿”；结局：投日计划被荆南工委利用日伪顽矛盾粉碎', '[]', '2026-09-10 09:57:14.070097', '2026-09-10 09:57:14.070097', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a81756acfe4745d49dfe9df47d8a3071', '刘培绪', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西宝鸡；湖北武汉；安徽芜湖；天津河北；湖北_咸宁_通山；湖南_湘西_泸溪；陕西_西安', '[]', '[]', '抗日战争时期', '', '控制长江芜湖段水上交通，为日军运输军需，盘查过往船只，勒索商旅。；湖南人，早年在湘军任职，后投汪伪，任伪军长，参与对湖南沦陷区的伪化控制与清乡。；汪伪政权军事要员，协助日军作战，其活动与陕西宝鸡抗日后方有间接关联。；在武汉地区率伪军配合日军扫荡，镇压抗日力量。；华北伪军头目，配合日军作战，对陕西宝鸡抗日后方构成威胁。；河北人，汪伪政权陆军部长，参与伪军整编与训练，配合日军作战。；投敌后任伪第三集团军总司令，配合日军。；汪伪伪军将领，在湖北地区指挥伪军配合日军进攻抗日根据地。', '[]', '2026-09-10 09:57:14.009519', '2026-09-10 09:57:14.009519', '天津', '河北', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a82d0c28414d487788a0e93eaddb14b7', '李树桂', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海文登；辽宁沈阳新民；山东烟台海阳；黑龙江伊春大箐山；黑龙江大庆；山西阳泉城区；山东_潍坊_寿光；山东潍坊潍坊滨海经开区；山东潍坊安丘；山东威海威海经开区', '[]', '[]', '抗日战争时期', '', '任伪潍县警察局长期间，配合日军搜捕抗日人员，镇压民众，活动范围包括潍县城区及寒亭周边。；任伪潍县警察局长期间，配合日军抓捕抗日人员，推行保甲连坐，镇压民众反抗。；任伪文登县新民会会长，配合日军进行宣传、奴化教育，组织亲日团体，协助推行治安强化运动。；日伪时期任伪文登县知事，文登与威海相邻，其伪政权活动覆盖威海经开区一带，推行保甲连坐，征发劳工。；伊春本地士绅，日军侵占伊春后出面组织维持会，协助日军征发劳工、物资，维持地方伪秩序，直接服务于大箐山、伊春一带的殖民统治。；在大庆地区肇州一带任伪县长，执行日本殖民政令，征粮征工，配合日伪军警镇压抗日活动。；率伪保安团配合日军扫荡海阳抗日根据地，抓捕抗日军民，破坏抗日组织。；在安丘地区组织伪政权，配合日军征粮征夫，镇压抗日活动。', '[]', '2026-09-10 09:57:14.013488', '2026-09-10 09:57:14.013488', '山东', '威海', '威海经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a836028d65cd40ad9de4a6522a1be614', '崔南善', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林_延边_龙井；吉林延边延吉；吉林延边汪清；吉林；吉林延边图们；吉林延边安图', '[]', '[]', '抗日战争时期', '', '组织亲日朝鲜人团体，协助日军进行“思想战”和情报活动。', '[]', '2026-09-10 09:57:13.996355', '2026-09-10 09:57:13.996355', '吉林', '延边', '图们', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a83b697818424fb58ffc0dc816b97d0c', '刘文光', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北鄂州华容；湖北鄂州；湖北咸宁通山；湖北咸宁崇阳；山西阳泉城区；重庆_铜梁；湖北咸宁咸安；湖北咸宁；湖北孝感；湖北武汉汉阳；湖北随州曾都；湖北孝感大悟；湖北荆门钟祥；湖北荆门；湖北荆门京山；湖北鄂州梁子湖；湖北鄂州鄂城', '[]', '[]', '抗日战争时期', '', '在鄂城及梁子湖周边地区组建伪警察队，配合日军清乡、搜捕抗日人员，推行良民证与保甲连坐。；在鄂城地区组建伪警察力量，配合日军搜捕抗日人员、镇压民众反抗。；担任伪警察局长期间，配合日伪政权搜捕抗日人士，勒索民众，为日军提供情报。；在荆门城关组织伪维持会，为日军筹办粮秣、夫役，诱迫商户复业以粉饰占领区秩序。；在鄂城地区组建伪保安武装，配合日军清乡、扫荡，镇压抗日群众，活动范围覆盖今鄂州华容一带。；在随北、应山交界地区依附日军，组织维持会与伪自卫团，为日军搜集情报、征发物资，迫害抗日人员。；大悟地区沦陷后组织维持会，协助日军建立伪政权，镇压当地抗日群众。；在汉阳地区附逆，任伪县长，协助日军控制汉阳及周边地区，推行奴化教育，搜刮民财。；率伪保安团配合日军对京山及周边抗日根据地进行扫荡，搜捕抗日人员，强征民夫和粮食。；在随县城区及淅河、安居等地建立伪警察网络，登记户口、发放良民证，协助日军抓捕抗日人员。；在孝感城区及孝南乡镇建立伪警察网络，搜捕抗日志士，镇压民众抗日活动。；负责伪湖北省政府在鄂南地区的政务，协调咸宁、蒲圻等县伪政权，推行日军殖民政策。；崇阳沦陷后组织维持会，为日军征集粮食、劳工，协助伪化基层。', '[]', '2026-09-10 09:57:14.055140', '2026-09-10 09:57:14.055140', '湖北', '咸宁', '咸安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a83e531706964a6d9a62cd8df2efbd32', '王仲孚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口蔚县', '[]', '[]', '抗日战争时期', '', '投靠日伪，任蔚县伪县长，推行保甲制度，建立伪警察队，配合日军扫荡，抓捕抗日人员，强征劳工。', '[]', '2026-09-10 09:57:14.042721', '2026-09-10 09:57:14.042721', '河北', '张家口', '蔚县', NULL, NULL, NULL, NULL, '');
