INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a862ab12cecb45f1a676d3351fc7fc1c', '景蔚文', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西运城新绛；山西运城', '[]', '[]', '抗日战争时期', '', '统管运城各县伪政权，推行奴化教育，强征劳工送往东北和日本，协助日军实施“三光”政策。', '[]', '2026-09-10 09:57:14.023759', '2026-09-10 09:57:14.023759', '山西', '运城', '新绛', NULL, NULL, NULL, NULL, '');
