INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a869704231d04e5b816e53bf0e940c0d', '李敬斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店上蔡；河南开封祥符；河南开封；河南南阳方城；辽宁沈阳新民；河南驻马店泌阳；河南开封；河南驻马店西平；河南商丘；河南漯河舞阳；河南驻马店驻马店经开区；河南驻马店；河南商丘虞城；河南商丘', '[]', '[]', '抗日战争时期', '', '在开封为日军筹款筹粮，协助经济掠夺，压榨商户和民众。；上蔡沦陷后出面组织维持会，后任伪县长，为日军征粮、派夫、维持地方伪秩序，是上蔡本地有记载的附逆者。；在豫东商丘一带任职伪政权，协助日军推行保甲连坐、征发劳工，参与镇压抗日活动。；负责沦陷区警察系统，搜捕抗日人员，配合日军维持开封及周边地区治安。；控制开封伪警察系统，搜捕抗日人员，配合日军维持占领区治安。；任伪开封市警察局长，协助日军搜捕抗日人员、管控户籍与物资。；掌控伪开封警察系统，搜捕抗日人员，配合日军实施戒严与清查。；泌阳本地士绅，日军占领泌阳后出面组织维持会，任伪县知事，协助日军征粮、征夫、建立伪保甲，镇压抗日群众。；西平沦陷期间出面组织维持会，为日军征集粮秣、民夫，协助建立伪基层政权，维持日军在西平的占领统治。；在豫东伪政权中负责教育事务，推行奴化教育，篡改教材，向商丘、虞城等地学生灌输亲日思想。；1944年日军侵占舞阳后，出面组织伪维持会，为日军筹粮、派夫、维持地方秩序，协助日军统治舞阳地区。；在确山及驻马店一带依附日军，参与伪县政筹备与保甲编组，配合日伪清乡。；在确山及驻马店一带依附日军，参与组建伪政权，配合日军扫荡抗日根据地，征发民夫物资。；1945年日军侵占南阳后，组织伪南阳新民会，进行亲日宣传，协助日军推行奴化教育。', '[]', '2026-09-10 09:57:14.047134', '2026-09-10 09:57:14.047134', '河南', '南阳', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a86ea20e3efe43a4b2134db4417773d4', '马冠三', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州宁津；山东德州；山东菏泽', '[]', '[]', '抗日战争时期', '', '统领伪警备队在德州及邻近宁津地区进行清乡、扫荡，捕杀抗日军民，勒索民财。；在菏泽地区为日军控制经济资源，协助征粮、征棉，支持日军战时经济。', '[]', '2026-09-10 09:57:14.013937', '2026-09-10 09:57:14.013937', '山东', '德州', '宁津', NULL, NULL, NULL, NULL, '');
