INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a8b780ba830940668846feff54758415', '卓特巴扎普', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古乌兰察布化德；内蒙古乌兰察布；内蒙古乌兰察布察哈尔右翼前旗；内蒙古乌兰察布集宁；内蒙古乌兰察布；河北张家口张家口察北管理；河北张家口沽源；内蒙古锡林郭勒正镶白旗；内蒙古_锡林郭勒_锡林浩特；内蒙古察哈尔；内蒙古、河北；内蒙古锡林郭勒正蓝旗；四川南充南部；内蒙古_锡林郭勒_苏尼特左旗；内蒙古锡林郭勒苏尼特右旗；内蒙古乌兰察布察哈尔右翼中旗；四川南充南部；内蒙古锡林郭勒太仆寺旗；河北张家口；内蒙古锡林郭勒东乌珠穆沁旗', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪蒙疆政务院院长，察盟伪高官，协助德王组建伪政权。结局：苏军俘虏押往蒙古，病死于乌兰巴托狱中；协助日军在乌兰察布北部地区建立伪警察机构，参与“大东亚圣战”宣传。；在乌兰察布东部及察哈尔右翼前旗地区率伪军参与“扫荡”，烧毁村庄，杀害抗日干部，并协助日军建立特务情报网。；参与蒙疆政权核心决策，在乌兰察布地区推行日伪法令，组织伪警察和保甲制度。；原锡林郭勒盟副盟长，投日后任伪司法部长，参与制定镇压抗日民众的法令，迫害蒙汉进步人士。；在张家口管理伪蒙疆内政，推行户籍管制和物资配给，协助日军经济掠夺。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.987018', '2026-09-10 09:57:13.987018', '内蒙古', '乌兰察布', '化德', NULL, NULL, NULL, NULL, '');
