INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a93f485fd904425eadcef06d42c5458f', '李鼎安', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉硚口；湖北武汉武昌；湖北武汉', '[]', '[]', '抗日战争时期', '', '任伪武汉特别市社会局局长，控制民众团体，推行奴化教育与社会控制。；抗战期间在武汉伪政权中主管土地事务，协助日军征用土地。；日军占领武昌后组织伪维持会，任会长，协助日军维持武昌及周边地区秩序。', '[]', '2026-09-10 09:57:14.056652', '2026-09-10 09:57:14.056652', '湖北', '武汉', '硚口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a94b01f13de245aca4a778274584bfa2', '张星五', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁兖州；安徽宿州；辽宁；山东烟台福山；山东济南钢城；天津南开；山东淄博淄川；山东淄博；山东烟台；浙江嘉兴海盐；山东淄博桓台；辽宁沈阳新民；山东德州德州经开区；山东德州；山东历城；山东潍坊昌乐；内蒙古赤峰巴林左旗；内蒙古赤峰；山东济南历下；辽宁沈阳新民；山东济宁微山；山东德州禹城；山东德州；山东烟台芝罘；山东烟台；山东聊城茌平；山东聊城；山东泰安岱岳；山东泰安；辽宁大连瓦房店；山东济南历城；山东济南；山东菏泽郓城；山东德州；山东济南；山东泰安东平；山东泰安泰山；山东泰安；山东烟台招远；山东烟台烟台高；山东烟台；山东济宁；山东聊城东昌府；江苏徐州；江苏徐州铜山；山东济南市中；山西阳泉城区；辽宁大连中山；山东泰安', '[]', '[]', '抗日战争时期', '', '伪职：汉奸向导密探；罪行：长期为日军搜集济南周边抗日游击队情报，多次带路扫荡历城乡村，战后被肃奸处决；来源：济南党史文史；备注：本地基层铁杆汉奸；在中山区协助日军推行粮食统制，强征居民粮食，导致民众饥荒。；在瓦房店地区为日军效力，抓捕抗日地下党员，破坏抗日组织。', '[]', '2026-09-10 09:57:13.991444', '2026-09-10 09:57:13.991444', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9564013337b4ce18405774ca4daacec', '彭佐熙', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南株洲醴陵；湖南株洲渌口；湖南株洲；山西阳泉城区；湖南长沙；广东汕尾陆河；湖南衡阳祁东；山西阳泉城区；湖南衡阳衡阳松木经开区；湖南衡阳；湖南衡阳南岳；湖南衡阳；湖南衡阳', '[]', '[]', '抗日战争时期', '', '1944年醴陵沦陷后，出面组织地方维持会，为日军征派粮食、民夫，协助维持占领区秩序，是醴陵本地附逆代表人物。；在日军占领长沙期间，出任伪职，协助日军维持长沙地区治安与伪化统治。；日军占领株洲期间，出面组织维持会，为日军征粮、拉夫，协助维持占领秩序。；湖南人，抗战后期在日军占领长沙后出任伪职，组织伪保安部队，协助日军维持占领区秩序；其活动主要在长沙地区，与郴州、安仁有一定地域邻近性但无直接任职记载。；出任伪陆丰县县长，配合日军推行保甲制度，征派壮丁、粮食，镇压抗日活动，其辖区包括今陆河县一带。；衡阳沦陷后，参与组织地方维持会，协助日军征粮、拉夫、维持治安，具体事迹散见于衡阳地方文史资料。；据衡阳地方文史资料零星记载，1944年衡阳沦陷期间，当地有维持会组织协助日军维持秩序、征派民夫，但具体负责人姓名多已散佚，彭佐熙之名见于部分口述史料，可靠性有限。；衡阳沦陷后出面组织维持会，任会长，协助日军维持地方秩序、征派物资、诱降民众，直接活动于衡阳地区，与南岳邻近。；衡阳沦陷期间，出面组织伪维持会，为日军筹粮、派夫、维持地方秩序，协助日军统治衡阳城区。；长沙沦陷后出面组织伪维持会，协助日军维持长沙城区秩序、征派物资与劳工，为日军占领长沙提供地方伪政权支持。', '[]', '2026-09-10 09:57:14.028454', '2026-09-10 09:57:14.028454', '广东', '汕尾', '陆河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a956b03d63c34a96a2fba0fa7c85f19f', '罗志强', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山；广西柳州融水；广西柳州柳城', '[]', '[]', '抗日战争时期', '', '日军侵占柳城期间组织伪维持会，协助日军控制柳城及邻近融水方向的水陆交通与物资。；在南海、佛山一带配合日军维持治安，逮捕抗日嫌疑人员，勒索商户。', '[]', '2026-09-10 09:57:14.026327', '2026-09-10 09:57:14.026327', '广西', '柳州', '融水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a95a61fa232548afb7543e7779346d3a', '高首三', NULL, NULL, NULL, NULL, 'exact', 'exact', '迁西罗家屯', '[]', '[]', '抗日战争时期', '', '伪职：伪治安军独立二十团团长，兵力千余；迁安??迁西北部最强伪军；反复清乡扫荡迁青平根据地，制造多起村庄惨案，扶持乡村特务眼线；日降后投靠国民党潜伏。；结局：1952 罗家屯万人公审枪决', '[]', '2026-09-10 09:57:14.079053', '2026-09-10 09:57:14.079053', '河北', '唐山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a967129c3b3d4faaaa2ee9073ab36cc4', '胡兰生', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉汉南；湖北武汉汉阳；湖北武汉', '[]', '[]', '抗日战争时期', '', '控制报刊、广播，为日军进行欺骗宣传，粉饰侵略，压制抗日言论。；负责伪湖北省宣传事务，为日军侵略辩护，散布亲日言论，压制抗日舆论。；抗战期间投敌，任伪湖北省政府财政厅厅长，在湖北武汉地区为日伪政权搜刮民财。；任伪武汉特别市社会局局长，控制社会团体，监视民众动向，协助日军征用劳工。', '[]', '2026-09-10 09:57:14.056547', '2026-09-10 09:57:14.056547', '湖北', '武汉', '汉南', NULL, NULL, NULL, NULL, '');
