INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a989becfe844404aa6cb811b1b8972e1', '马文甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳南阳示范；辽宁沈阳大东；河南周口周口经开区；河南周口；河南周口商水；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '1945年南阳沦陷期间，在伪政权中负责教育事务，推行奴化教育，宣传“大东亚共荣圈”，毒害青年学生。；在淮阳、周口地区协助日军建立伪政权，推行奴化教育，为日军提供情报。；在商水推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”，组织师生参加日伪集会，是文化教育领域附逆者。', '[]', '2026-09-10 09:57:14.046700', '2026-09-10 09:57:14.046700', '河南', '南阳', '南阳示范', NULL, NULL, NULL, NULL, '');
