INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9c62623684f46d4bcf7f0baa50033a8', '林水来', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门海沧', '[]', '[]', '抗日战争时期', '', '海沧沦陷后组织伪维持会，为日军征调民夫、物资，维持海沧地区殖民统治。', '[]', '2026-09-10 09:57:14.061124', '2026-09-10 09:57:14.061124', '福建', '厦门', '海沧', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9ded98a2c6d4bdfbea1dd6ddda13cee', '刘子久', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南漯河；河南漯河郾城；河南三门峡三门峡经开区；河南三门峡灵宝；河南三门峡湖滨；河南三门峡灵宝；河南洛阳洛宁；河南平顶山宝丰；河南新乡辉县；辽宁沈阳大东；河南平顶山新华；河北石家庄新华；河南许昌长葛；河南三门峡卢氏；河南三门峡陕州；河南三门峡灵宝；河南开封尉氏；河南开封；河南三门峡义马；河南三门峡卢氏；河南平顶山舞钢；河南漯河舞阳；安徽宿州灵璧；河南信阳新县；河南信阳光山；河南平顶山汝州；河南平顶山宝丰；河南平顶山', '[]', '[]', '抗日战争时期', '', '主办伪《豫北日报》，宣扬“大东亚共荣”，为日军侵略辩护，诋毁抗日力量，在新乡、辉县等地散发反动宣传品。；在光山及邻近新县地区组织伪维持会，为日军筹粮筹款、提供情报，协助日军对光山、新县一带抗日根据地进行封锁和扫荡。；临汝沦陷后投敌，组织维持会，协助日军控制临汝及邻近的宝丰、郏县一带。；协助会长组织维持会，负责摊派粮款、登记户口，为日军提供情报。；在郾城推行奴化教育，组织教师参加伪培训，强迫学校使用伪教材，为日军培养顺民。；1944年日军侵占宝丰后，组织维持会并任会长，协助日军在宝丰、汝州交界地区推行伪化统治，征粮派款。；鲁山县靠近平顶山新华区，刘子久在日军占领期间出任伪维持会副会长，协助日军征粮、派款，维持地方伪秩序。；卢氏沦陷期间出面组织伪政权，为日军征发粮食、民夫，并参与搜捕抗日分子。；灵宝沦陷期间参与伪维持会，协助日军维持地方治安、征发物资。；组织亲日宣传，拉拢地方士绅附逆，配合日军进行思想控制。；率伪保安团在开封、尉氏交界地区配合日军行动，镇压抗日武装。；1944年日军侵占舞阳后，组织维持会，为日军征粮派款、提供情报，协助日军控制舞阳及周边地区。；鲁山县（今属平顶山市）人，日军占领期间任伪警察局长，带领伪警察配合日军扫荡抗日武装，镇压当地民众反抗。；灵宝沦陷期间组织伪维持会，为日军筹粮筹款，压迫当地民众。；带领伪保安队配合日军下乡扫荡，抢粮抓丁，破坏抗日根据地。；日军在豫西设立伪道尹公署，统辖陕州、卢氏、灵宝等县伪政权，推行保甲、征粮拉夫。；日军在豫西扶植伪政权，刘子久任伪道尹，统辖包括陕县、灵宝在内的豫西伪政，配合日军统治。', '[]', '2026-09-10 09:57:14.008433', '2026-09-10 09:57:14.008433', '安徽', '宿州', '灵璧', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9e12730cf744355b686c3f5a9728d1a', '于化南', NULL, NULL, NULL, NULL, 'exact', 'exact', '长岭新安镇', '[]', '[]', '抗日战争时期', '', '伪职：伪长岭新安镇商务会长、维持会骨干；罪行：依附日伪，为日军筹措物资；光复后出钱出枪资助反动地方武装对抗民主政府。；结局：解放后被惩处。', '[]', '2026-09-10 09:57:14.080749', '2026-09-10 09:57:14.080749', '吉林', '松原', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9e153ecbf2a43b2ad32760b50ee2e34', '窦光殿', NULL, NULL, NULL, NULL, 'exact', 'exact', '濉溪百善、南坪、孙疃一带中共淮北市...；安徽濉溪', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪暂编第十五师师长；罪行：皖北实力最强本地伪军头目，兵力五千余；盘踞宿西南，强拆民房、抓丁拉夫，设立侦缉队，杀害抗日军民六十余人，多次进攻豫皖苏抗日根据地，劫掠乡村。宿南战役核心伪军。；结局：1945 年宿南战役被新四军四师击毙，部队大部被歼灭中共淮北市...。；伪任职务：汪伪暂编第十五师师长，皖北重要伪军，兵力五千余人，扫荡淮北抗日根据地。结局：抗战胜利后被捕，公审处决', '[]', '2026-09-10 09:57:14.075264', '2026-09-10 09:57:14.075264', '安徽', '淮北', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('a9e15c6d45b34da6ab9eec761d57905a', '郑德铭', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建福州；福建莆田荔城；福建莆田；福建福州；福建福州福清', '[]', '[]', '抗日战争时期', '', '在伪莆田县教育科任职，推行奴化教育，篡改教材，向学生灌输亲日思想，协助日军进行文化侵略。；福州人，投靠日军后任伪警察局督察长，带领伪警察在福州城内搜捕抗日分子，敲诈勒索市民，为日军提供情报。；福清沦陷期间任伪维持会会长，为日军筹粮、维持治安。', '[]', '2026-09-10 09:57:14.061950', '2026-09-10 09:57:14.061950', '福建', '福州', '连江', NULL, NULL, NULL, NULL, '');
