INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ab486cce639242279de1858c1f30349f', '金雄白', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西_柳州；重庆大足；江苏南京浦口；辽宁沈阳和平；安徽安庆；江苏南京；浙江_杭州_西湖；江苏南京鼓楼；浙江绍兴；山西吕梁兴县；上海杨浦；江西赣州；云南普洱西；浙江杭州桐庐；辽宁沈阳大东；陕西西安长安；江苏南京浦口；浙江杭州；广西桂林恭城；云南普洱西；安徽芜湖镜湖；江苏南京江宁；安徽芜湖芜湖经开区；浙江_杭州_建德', '[]', '[]', '抗日战争时期', '', '汪伪在浙江的行政骨干，协助省长处理日常事务，参与制定迫害抗日民众的政策。；控制伪新闻机构，为日伪宣传。；在汪伪政权中负责宣传，为日军侵略辩护。；汪伪金融头目，其金融体系渗透广西，掠夺物资。；在鼓楼区参与制定伪法律，为日本侵略合法化服务。；汪伪政权新闻宣传骨干，主办伪报，进行亲日宣传。；协助伪市长处理政务，参与策划“清乡”和物资统制。；浙江杭州人，投日后任伪警察局长，协助日军维持治安，多次围捕抗日地下组织。；提供情报导致游击队遭袭。；在安庆设立伪法院，迫害抗日人士，判刑关押无辜百姓。；江苏人，抗战期间投敌，任伪《平报》社长，后任伪中央储备银行调查处长，为伪政权进行经济与舆论服务，其活动涉及华中包括江西。；浙江杭州人，负责发行伪币“中储券”，搜刮民财，造成通货膨胀。；为日军收集新四军活动情报，导致多次游击队遭袭，造成重大伤亡。；利用报纸为日伪张目，攻击抗日力量。；在杨浦地区发行汉奸报纸，散布投降言论。；在南京任伪职，控制伪新闻宣传机构。；撰写亲日报道，美化日军暴行，污蔑抗日军民为“匪”，为汉奸政权造势。；浙江绍兴人，原报人，抗战期间投敌，历任汪伪政权中央宣传部次长、伪绍兴县长等职，在绍兴地区协助日军进行文化宣传与伪化统治。；负责南京地区亲日宣传，控制舆论；在南京办报鼓吹“和平救国”，为日伪统治造势。；原报人，投日后负责伪浙江省宣传，在桐庐等地张贴反共标语，鼓吹“大东亚共荣”，欺骗民众。', '[]', '2026-09-10 09:57:13.977907', '2026-09-10 09:57:13.977907', '上海', '杨浦', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ab4bd7b59be74097b062927d40aff31d', '王仁棠', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建_福州_仓山；福建福州闽侯；福建福州', '[]', '[]', '抗日战争时期', '', '闽侯人，日军占领福州及闽侯期间任伪闽侯县维持会会长，协助日军在闽侯、晋安一带征粮拉夫，推行保甲伪化。；闽侯人，日军侵占福州及闽侯期间，组织伪维持会，为日军征派民夫、物资，推行保甲连坐。；闽侯人，日军侵占福州及闽侯期间，组织伪维持会，为日军征粮、征工，配合日伪清乡。；福建人，在伪福建省政权中任财政厅厅长，负责为日伪筹措经费、征收捐税，支持日军在福建的占领统治。', '[]', '2026-09-10 09:57:14.061976', '2026-09-10 09:57:14.061976', '福建', '福州', '闽侯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ab4c1140ac4d4a48ab658e3cf9467399', '郭受天', NULL, NULL, NULL, NULL, 'exact', 'exact', '扶沟县；辽宁沈阳和平', '[]', '[]', '抗日战争时期', '', '伪职：伪三十二军军长兼鄢、扶、西、尉四县伪行政公署长官；罪行：大汉奸。任伪三十二军军长兼鄢陵、扶沟、西华、尉氏四县伪行政公署长官。日军和汉奸队四处抢劫，无恶不作。1945年8月扶沟解放后，指使伪军配合日军反扑', '[]', '2026-09-10 09:57:14.032425', '2026-09-10 09:57:14.032425', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ab4ceafce82e4b35948c75bd86e5c8be', '陈桐生', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州吴兴；浙江嘉兴桐乡；浙江嘉兴海宁；浙江嘉兴', '[]', '[]', '抗日战争时期', '', '率伪军参与“清乡”行动，在嘉兴、海宁交界处多次袭击抗日游击队，杀害多名抗日群众。；负责为日伪征收田赋、捐税，搜刮民财，供日军军需。；率伪军配合日军扫荡，多次袭击抗日游击队，杀害无辜群众。', '[]', '2026-09-10 09:57:14.050497', '2026-09-10 09:57:14.050497', '浙江', '嘉兴', '桐乡', NULL, NULL, NULL, NULL, '');
