INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ace2110369254a11b61596b98c02eeda', '陈秉渊', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古鄂尔多斯伊金霍洛旗；内蒙古鄂尔多斯；内蒙古鄂尔多斯；内蒙古鄂尔多斯杭锦旗；内蒙古鄂尔多斯康巴什；内蒙古鄂尔多斯', '[]', '[]', '抗日战争时期', '', '在包头地区投靠日伪，担任伪职，协助日军在绥西及鄂尔多斯北部进行统治和经济掠夺。；在鄂尔多斯部分地区组织维持会，为日军征粮征夫，协助建立伪保甲制度，镇压当地抗日群众。；在日军侵占杭锦旗部分地区后出面组织维持会，为日军征粮派款、搜集情报，协助伪政权控制当地基层。；在日军扶植下出任伪伊克昭盟公署盟长，协助日伪在鄂尔多斯地区推行保甲、征粮、征兵，镇压抗日力量。', '[]', '2026-09-10 09:57:13.992129', '2026-09-10 09:57:13.992129', '内蒙古', '鄂尔多斯', '伊金霍洛旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ace6b378d91c4c8c953a1da080e87dff', '雷筱圃', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆州石首；湖北宜昌；洪湖（原沔南）；湖北荆州洪湖', '[]', '[]', '抗日战争时期', '', '伪职：伪沔南县政府筹备处处长；罪行：新堤码头黑帮八大柱头\"帮主。1940年被日本军特务部派来的妹尾义邦委任为\"沔南县政府筹备处\"处长\"', '[]', '2026-09-10 09:57:14.056872', '2026-09-10 09:57:14.056872', '湖北', '荆州', '洪湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ace922b9bc3b44a5869ffca51820c437', '薛兴甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北石家庄高邑；河北；冀南道（辖濮阳）；河北石家庄石家庄高；河北石家庄高邑', '[]', '[]', '抗日战争时期', '', '伪职：伪冀南道道尹（前期），冀南道最高伪行政长官；统辖 14 县伪政权，推行治安强化运动，组织各县伪军扫荡冀南根据地，掠夺粮棉物资。；结局：1944 清丰战斗被俘，公审枪决；在高邑县为日军强征军粮，建立伪警察所，多次带队突袭抗日村庄，杀害无辜百姓。；强制学校使用日伪教材，推行奴化教育，解散抗日小学，迫害爱国教师，组织学生为日军“祝捷”活动。；任伪石门市市长，协助日军建立殖民统治，推行奴化教育，强征劳工，为日军提供后勤支持。；任伪邯郸县知事期间，为日军提供情报，组织伪警察抓捕抗日干部，参与‘治安强化运动’。；伪职：伪冀南道尹；罪行：河北籍，日伪高级文官，投降日军后任伪冀南道尹，管辖冀南、豫北十余县伪政权。统筹各县横征暴敛，指挥各县伪政权配合日军扫荡冀鲁豫根据地。1944年亲自到清丰县城召集13县伪县长开会；结局：1944年清丰战役中被八路军生擒，公审镇压', '[]', '2026-09-10 09:57:14.043702', '2026-09-10 09:57:14.043702', '河北', '石家庄', '石家庄高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('acec185b614345638f375d765131e5d7', '刘宗和', NULL, NULL, NULL, NULL, 'exact', 'exact', '鸡西城子河晓城煤矿', '[]', '[]', '抗日战争时期', '', '伪职：煤矿翻译、特务；罪行：充当翻译，协助日军审讯矿工，传递情报，迫害爱国工人城子河区人...。；结局：解放后管制改造。', '[]', '2026-09-10 09:57:14.072126', '2026-09-10 09:57:14.072126', '黑龙江', '鸡西', NULL, NULL, NULL, NULL, NULL, '');
