INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ae8df6fbf21445ecbc6ab187c5e0c6f7', '申从周', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东枣庄市中；山东枣庄滕州；山东济宁曲阜；山东济宁', '[]', '[]', '抗日战争时期', '', '在滕县（今枣庄市滕州市）充任伪县长，协助日军推行保甲制，征粮抓丁，镇压抗日活动。；济宁地区伪军头目，组织伪保安团协助日军维持济宁治安，参与清乡与扫荡。', '[]', '2026-09-10 09:57:14.014628', '2026-09-10 09:57:14.014628', '山东', '枣庄', '市中', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ae902b17f4c34b0bba00108d7b07188e', '邵尚俭', NULL, NULL, NULL, NULL, 'exact', 'exact', '金州；辽宁大连庄河；辽宁；辽宁大连；辽宁大连西岗；辽宁大连长海；辽宁大连甘井子', '[]', '[]', '抗日战争时期', '', '伪职：关东州厅参事、大连市商会副会长，身兼 30 余个伪职，粮油大亨；罪行：垄断大连粮油行业，执行日军物资配给，摊派报国公债，把粮食油料供给日军；商民抗捐罢市时私自赴东京欺骗日本当局；日本投降后任治安维持会副会长，勾结日伪残余与国民党。；结局：1946 逮捕，没收绝大部分财产，保外就医，后病逝北京。；在庄河地区任伪县长，协助日军清乡，镇压庄河抗日义勇军和民众反抗。；辽宁大连甘井子人，在日本殖民统治下任甘井子区长，协助日本推行保甲制度，强征劳工，镇压当地反抗。；辽宁大连人，曾任伪大连宪兵队队长，残酷镇压西岗区及周边抗日地下组织。；在长海县（今属大连）推行日伪统治，强征渔民劳役，镇压渔民反抗。', '[]', '2026-09-10 09:57:14.062997', '2026-09-10 09:57:14.062997', '辽宁', '大连', '庄河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ae92a4cb438b4a57af67a3eaf86e9712', '陈坤', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州海珠；广东广州；广东揭阳榕城；广东揭阳', '[]', '[]', '抗日战争时期', '', '在汪伪广东政权下参与伪警察系统，协助日伪维持广州治安。；伪揭阳县保安大队长，率领伪军配合日军在揭阳地区进行治安强化运动，镇压抗日活动。', '[]', '2026-09-10 09:57:14.026848', '2026-09-10 09:57:14.026848', '广东', '广州', '海珠', NULL, NULL, NULL, NULL, '');
