INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aeba5432d84140febdce3e6a7d79fef0', '李荫棠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北石家庄正定；内蒙古赤峰巴林左旗；河北秦皇岛山海关；河北石家庄；河北秦皇岛卢龙', '[]', '[]', '抗日战争时期', '', '日军占领固安后率先组织维持会，为日军筹粮派夫，协助建立伪政权，镇压抗日活动。；在晋县任伪知事，组织“清乡队”，杀害抗日村长数十人。；率伪保安队配合日军扫荡，抓捕抗日军民，参与制造多起惨案。；率伪军多次配合日军扫荡正定、灵寿一带抗日根据地，抓捕抗日干部和群众，并参与制造多起惨案。；组织伪警察队，多次配合日军“扫荡”卢龙北部山区，抓捕抗日干部和群众，参与制造多起惨案，勒索百姓财物。……（共涉及6个地区的犯罪记录）；伪职：伪平泉县县长；平泉是日伪扫荡承平宁根据地指挥中心，强修炮楼人圈，大检举抓捕抗日人员。；结局：战后汉奸罪判处长期徒刑', '[]', '2026-09-10 09:57:13.991505', '2026-09-10 09:57:13.991505', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aebb2f39fa044124bef126981d2482b4', '赵老步', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北邢台威县', '[\"赵步云\"]', '[]', '抗日战争时期', '', '组织伪自卫团，协助日军封锁抗日根据地，盘查过往行人，抢夺群众财物，多次带路袭击八路军游击队。；组织伪自卫团，配合日军封锁抗日根据地，参与“清乡”行动，杀害抗日军属，抢夺民财，民愤极大。', '[]', '2026-09-10 09:57:14.044891', '2026-09-10 09:57:14.044891', '河北', '邢台', '威县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aec77b8d5ab64e8291e3a4e2ba9de4a8', '荣厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁辽阳；吉林船营；辽宁沈阳大东；吉林高；辽宁葫芦岛龙港；辽宁沈阳；辽宁_沈阳_和平；辽宁盘锦双台子；辽宁辽阳灯塔；黑龙江哈尔滨；辽宁_大连_庄河；吉林；吉林长春；辽宁_大连_旅顺口；辽宁沈阳；黑龙江齐齐哈尔；吉林长春公主岭；辽宁锦州凌河；辽宁沈阳新民；辽宁沈阳；辽宁沈阳辽中；辽宁_大连_瓦房店；辽宁营口；辽宁葫芦岛绥中；辽宁锦州；辽宁沈阳；辽宁沈阳苏家屯；吉林长春；辽宁锦州；辽宁阜新；辽宁鞍山；辽宁铁岭西丰；辽宁沈阳铁西；吉林、辽宁；吉林；吉林经开区；辽宁_沈阳_浑南；吉林；吉林_长春_南关；吉林_长春_九台；吉林', '[]', '[]', '抗日战争时期', '', '推行保甲制度，强化殖民统治，协助日军建立“集团部落”以隔离抗联。；原吉林地方官员，投日后任伪满吉林省财政厅厅长，负责为日军搜刮吉林、四平、伊通地区的粮食和物资，支持侵略战争。；投靠日本，任伪吉林省财政厅长及省长，协助日军搜刮资源，推行奴化教育。；协助日本财阀在船营地区开采矿产、掠夺森林资源，强征当地农民为矿工。；原吉林官银号总办，投日后负责伪满在吉林、辽源地区的财政搜刮，发行伪币，掠夺粮食和物资，支持日军战争。……（共涉及47个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995790', '2026-09-10 09:57:13.995790', '吉林', '经开区', '浑南', NULL, NULL, NULL, NULL, '');
