INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aeec75f44ae24ba29c5522155e82716e', '王伯元', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海松江；广西桂林资源；江苏无锡梁溪；浙江宁波镇海；浙江宁波；江苏苏州太仓；浙江宁波；浙江宁波鄞州；辽宁沈阳和平；上海奉贤；浙江杭州西湖；上海杨浦', '[]', '[]', '抗日战争时期', '', '发行伪币，套购法币，扰乱浙江金融，导致物价飞涨。；在杨浦区强占民房供日军居住，驱逐原住户。；控制江苏经济，为日军掠夺资源；为伪政权征收苛捐杂税，侵吞抗日物资，资助日军军费。；利用伪法庭迫害抗日群众，以“通匪”罪名判处多人死刑或长期监禁。；率伪保安队配合日军“清乡”，在太仓各乡镇搜捕抗日分子，烧毁村庄，抢劫民财。；协助日军控制宁波金融，发行军用票，套取法币，扰乱经济，并资助伪军。；为日军在宁波、镇海地区筹措军费，强迫商户捐献，并垄断粮食贸易。；原为宁波士绅，投日后协助维持会工作，参与组织“和平救国”宣传，瓦解抗日意志。；日军占领松江后率先组织维持会，为日军筹粮派款，协助维持占领秩序。', '[]', '2026-09-10 09:57:13.975667', '2026-09-10 09:57:13.975667', '上海', '奉贤', '梁溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aef2ab11a8744f8fa80f6c16a0414011', '赵冠英', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳；河南安阳滑县；吉林白城；吉林白城镇赉', '[]', '[]', '抗日战争时期', '', '在豫北濮阳、滑县、长垣一带率伪军配合日军作战，袭击抗日武装，抢掠民财。；率保安队配合日军“讨伐”抗日联军，在洮南、镇赉一带烧毁民房，屠杀抗日群众，曾参与制造多起惨案。', '[]', '2026-09-10 09:57:13.999260', '2026-09-10 09:57:13.999260', '吉林', '白城', NULL, NULL, NULL, NULL, NULL, '');
