INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('af6a325c4ecf4631abe32454fbe6f861', '罗树甲', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳雁峰；湖南衡阳；湖南张家界桑植；湖南张家界；湖南衡阳祁东；湖南衡阳；湖南衡阳', '[]', '[]', '抗日战争时期', '', '衡阳保卫战后期，日军占领衡阳后，罗树甲参与组织伪自治会，协助日军管理城市、征调民夫。；衡阳沦陷期间参与伪维持会，协助日军管理地方事务，征集物资与劳工。；湖南地方士绅，抗战时期在湘西北地区组织维持会，协助日军管理地方，其活动范围涉及张家界、桑植周边地区。；衡阳沦陷期间，部分地方士绅出面组织维持会，罗树甲被地方史料提及为参与维持会活动者之一。', '[]', '2026-09-10 09:57:14.058363', '2026-09-10 09:57:14.058363', '湖南', '张家界', '桑植', NULL, NULL, NULL, NULL, '');
