INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('af8c31de95704655832a04326d000e0c', '烟台伪新民会会长孙传芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台莱山；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '组织伪新民会，进行亲日宣传，协助日军控制舆论，在烟台、莱山一带活动。', '[]', '2026-09-10 09:57:14.017365', '2026-09-10 09:57:14.017365', '山东', '烟台', '莱山', NULL, NULL, NULL, NULL, '');
