INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('aff5e78a39554a64b1f6567e248a5639', '何定之', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南东方；海南澄迈；海南海口龙华；内蒙古乌海海南；海南三亚崖州；海南三亚；海南澄迈；海南万宁；海南三沙中沙；海南三沙西沙；海南三沙南沙；海南海口；海南琼中；海南澄迈；海南白沙；海南定安；海南五指山；海南文昌；海南屯昌；内蒙古乌海海南；海南三亚吉阳；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在文昌地区协助日军统治，镇压抗日群众。；在澄迈地区为日军征粮、征丁，组织伪自卫军，配合日军进攻抗日游击队。；在伪政权民政部门任职，参与制定澄迈等地保甲连坐与人口登记政策。；在定安地区推行保甲，协助日军修筑据点、公路，搜捕抗日人员。；海口沦陷后组织伪维持会并任会长，协助日军维持海口市区秩序，征发民夫、物资，推行伪化宣传和保甲制度。；在澄迈地区为日军征粮征工，组织伪自卫军，配合日军进攻抗日根据地。；海南伪政权高层之一，参与制定伪化政策，协助日军统治海南。；在琼东地区投敌，建立伪行政机构，协助日军征粮征夫，压制抗日力量。；在乐会地区为日军征发粮食和劳工，维持伪政权统治，镇压当地抗日活动。；在崖县、三亚一带为日军筹款筹物，协助日伪经济掠夺和物资统制。；组织万宁商户为日军筹款筹物，协助日军统制粮食与食盐，打压不愿合作的商贩。；在海南儋县等地任伪县长，推行日伪政令，组织伪自卫队和维持会，协助日军控制西部沿海地区。；在海南沦陷区推行奴化教育，协助日军控制学校和文化宣传，影响海口及周边地区。', '[]', '2026-09-10 09:57:14.052933', '2026-09-10 09:57:14.052933', '海南', '万宁', '吉阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('affb08f428d84d6cb24f18b3121b3480', '唐惠民', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海徐汇；上海青浦；江苏苏州太仓；江苏苏州；江苏苏州吴中；江苏苏州；江苏苏州吴江；江苏南京；江苏苏州张家港；江苏苏州；江苏_南京_浦口；上海长宁；江苏；安徽安庆；江苏镇江丹徒；江苏无锡；江苏南京浦口', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：76 号特工总部副主任，早期特务头目，后与李士群内讧被排挤。结局：抗战胜利被捕，病死狱中', '[]', '2026-09-10 09:57:13.976950', '2026-09-10 09:57:13.976950', '上海', '长宁', '浦口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('affbd8bf62c942f69659c21bb77c7827', '张显荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '泗水县；滕县', '[]', '[]', '抗日战争时期', '', '伪职：汉奸（泗水）；罪行：泗水县汉奸，曾偷袭孔昭同自卫军；伪职：泗水皇协军司令；罪行：泗水张庄人。原本拉起武装号称抗日，1942年经受日伪威逼利诱，率千余人队伍投降日军，出任皇协军司令，盘踞泗南山区。调转枪口攻打尼山根据地；出卖地下交通站；在山区设立据点，勒索周边村庄；结局：1944年八路军攻克张庄据点，张显荣被击毙', '[]', '2026-09-10 09:57:14.069766', '2026-09-10 09:57:14.069766', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('affc2634a2c547569a4f71e207e18eb9', '张本政', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁旅顺（大连）；辽宁大连；辽宁大连长海；辽宁大连；辽宁；辽宁大连沙河口；辽宁大连；大连/烟台；旅顺；辽宁大连庄河；辽宁大连；辽宁大连旅顺口；辽宁大连', '[]', '[]', '抗日战争时期', '汪伪政权', '大连巨商，投靠日本，任伪商会会长，为日军筹集军费，垄断港口贸易。；在大连地区为日军提供物资和资金，协助日本控制港口和航运，迫害抗日人士。；大连巨商，长期为日本殖民当局服务，资助日军侵略，参与经济掠夺。；大连巨商，长期为日本关东军提供物资和情报，任伪商会会长，协助日本掠夺大连资源。；辽宁大连人，日本殖民时期大连最大买办，为日军提供物资和情报，协助镇压抗日活动。……（共涉及10个地区的犯罪记录）；伪职：关东州厅参事、大连市商会会长，身兼 49 项伪职，政记轮船公司老板；罪行：甲午即投敌；全部轮船供日军运输军火兵员；捐献飞机 40 架，受日本天皇接见；日本投降后组建大连治安维持会，勾结残留日军与国民党势力，迫害爱国人士。；结局：1947 初判 12 年，保外就医潜逃；1951 年公审枪决，家产全部没收抖音百科。；伪任职务：大连大商人，关东厅参事，捐献巨资、飞机支援日军侵华，为日军提供航运运力抖音百科。结局：1951 年大连公审，判处死刑枪决；伪职：日本特务/大奸商；罪行：甲午战争时为日军带路攻占旅顺；在烟台经营海上运输、工厂、银行等；为日军捐40架战机；做汉奸长达50余年；结局：抗战胜利后被国民政府逮捕判刑12年；1951年被人民政府公审处决', '[]', '2026-09-10 09:57:14.062935', '2026-09-10 09:57:14.062935', '辽宁', '大连', '中山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b0023e336f4f4aafb95018f733ff0664', '田杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '崞县', '[]', '[]', '抗日战争时期', '', '伪职：首任伪安泽县县长；罪行：建立安泽伪政权，设立宪兵、剿共对策委员会，迫害根据地军民，杀害百姓五百余人临汾新闻网。；结局：战后逮捕判刑；伪职：首任伪崞县县长兼维持会长；罪行：日军占领崞阳，组建维持会，搭建伪政权体系。；结局：调走，战后逮捕判刑', '[]', '2026-09-10 09:57:14.068427', '2026-09-10 09:57:14.068427', '山西', '忻州', NULL, NULL, NULL, NULL, NULL, '');
