INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b024c957c31e4068ae77e561cfd9a867', '杨老俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口商水', '[]', '[]', '抗日战争时期', '', '担任伪保甲长期间，为日军搜集抗日武装情报，带领日伪军抓捕抗日家属，强征粮食和壮丁，直接危害商水乡村。', '[]', '2026-09-10 09:57:14.047398', '2026-09-10 09:57:14.047398', '河南', '周口', '商水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b028591c94874521a9dd2087377fac39', '汤卓然', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪第一任伪武进县县长，推行保甲联保切结、良民证制度，配合第一期清乡，编纂伪地方刊物为日伪宣传常州市档案...。。结局：战后汉奸罪判处死刑', '[]', '2026-09-10 09:57:14.084288', '2026-09-10 09:57:14.084288', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b0288d00128c491498bac1e33310557c', '王光夏', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏宿迁泗阳；江苏宿迁宿城；江苏宿迁；江苏宿迁宿豫；辽宁阜新太平', '[]', '[]', '抗日战争时期', '', '为伪政权粉饰太平，拉拢地方士绅附逆，协助日军推行治安强化运动。；汪伪政权委任的泗阳县县长，组织维持会、保甲制，为日军征粮征夫，镇压当地抗日群众。；抗战期间投靠日伪，出任宿迁县伪县长，协助日军维持地方伪政权，征粮派款，镇压抗日群众。', '[]', '2026-09-10 09:57:14.034404', '2026-09-10 09:57:14.034404', '江苏', '宿迁', '宿城', NULL, NULL, NULL, NULL, '');
