INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b044456b8d174a9ea4944ed9d75116d1', '杜葆田', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪石门警察署长、特务系长，外号 “杜阎王”；掌管宪兵特务，私设多处地牢，酷刑残害数百抗日军民。；结局：1951 年公审，三万人大会枪决', '[]', '2026-09-10 09:57:14.072111', '2026-09-10 09:57:14.072111', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b048d9e23c1942ce94dc175f9f6830c3', '李四娃', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权', '[]', '[]', '抗日战争时期', '', '参与“清乡”时强奸妇女，并杀害反抗者1人。', '[]', '2026-09-10 09:57:14.022766', '2026-09-10 09:57:14.022766', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b04b3879fbad457ea32ecfdb3f72b25a', '李兴唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博淄川；山西阳泉矿区；山东淄博沂源；山东淄博博山；山东淄博博山；山东淄博', '[]', '[]', '抗日战争时期', '', '组织伪矿警，配合日军守备淄博矿区，镇压矿工反抗。；任伪博山县知事，在博山及周边地区推行保甲制，征粮征夫，协助日军扫荡鲁中抗日根据地，涉及沂源边缘地区。；日伪时期任伪博山县知事，配合日军在博山地区的统治，参与征发劳工、物资，支持日军对淄博煤矿的掠夺。', '[]', '2026-09-10 09:57:14.015901', '2026-09-10 09:57:14.015901', '山东', '淄博', '博山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b04d87de5b62471bb2b2eeca8e71268a', '胡某', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁咸安；安徽黄山；安徽黄山黟县；江西九江永修；安徽黄山黟县；湖北咸宁崇阳；湖北咸宁', '[\"胡元恺\", \"胡仲文\"]', '[]', '抗日战争时期', '', '在咸安地区组织伪维持会，为日军据点供应物资，协助日军清乡。；在咸宁沦陷区推行奴化教育，协助日军进行文化侵略。；在永修日占区负责伪警察事务，协助日军盘查、抓捕抗日人员。；黟县沦陷期间任维持会会长，配合日军统治。；黟县本地人物，抗战期间投敌，任伪黟县维持会会长，协助日军控制黟县地区。', '[]', '2026-09-10 09:57:14.011261', '2026-09-10 09:57:14.011261', '安徽', '黄山', '黟县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b04e3819ffee4aa084a8bf8415b48d0e', '陈小毛下属', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦', '[\"具体姓名不详\"]', '[]', '抗日战争时期', '', '在杨浦区抓人。', '[]', '2026-09-10 09:57:13.979031', '2026-09-10 09:57:13.979031', '上海', '杨浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b0521b7590844889beba96f2891aee90', '万兆芝', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西南昌', '[]', '[]', '抗日战争时期', '', '伪职：汪伪中央高级汉奸；罪行：南昌籍，留学美国，投靠汪伪，历任汪伪实业总署劳工局局长、合作局局长等，在南京汪伪中央任职，推行奴化经济政策；来源：近代汪伪人物史料；备注：籍贯南昌，主要活动不在南昌本地', '[]', '2026-09-10 09:57:14.082008', '2026-09-10 09:57:14.082008', '江西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b05243349cb141d4831910aec247e71d', '刘伯刚', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州柳江；广西柳州柳北；广西柳州', '[]', '[]', '抗日战争时期', '', '在柳江地区协助日军建立伪政权，征集物资，压迫民众。；日军占领柳州期间，出任伪柳江县知事，推行日军政令，协助清乡与物资统制。', '[]', '2026-09-10 09:57:14.031617', '2026-09-10 09:57:14.031617', '广西', '柳州', '柳北', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b0552c41074c404d96b0950fa0b519b4', '尹祚乾', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鹤岗；吉林松原长岭；吉林；黑龙江伊春金林；黑龙江齐齐哈尔；黑龙江牡丹江', '[]', '[]', '抗日战争时期', '', '在伪吉林省政权及协和会中任职，推行殖民思想宣传和地方控制，活动范围包括今松原地区。；长期在伪三江省任职，负责警务和治安，伪三江省辖境包括今鹤岗、萝北等地，其指挥伪警察配合日军围剿抗日联军，镇压当地民众抗日活动。；曾任伪满江防舰队司令，在黑龙江水域配合日军行动，参与封锁和围剿抗日力量。；任伪牡丹江省省长期间，积极推行日伪殖民政策，镇压抗日力量，强征劳工，为日军提供物资支持。', '[]', '2026-09-10 09:57:13.999105', '2026-09-10 09:57:13.999105', '吉林', '松原', '长岭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b055c1fb4a224a7da67ca52cc6a78b01', '张治中', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南永州东安；湖南长沙；湖南衡阳衡南；湖南邵阳；湖南邵阳双清；山西阳泉城区；湖南衡阳衡东；湖南邵阳城步；湖南张家界永定；湖南永州蓝山；湖南永州；辽宁沈阳大东；湖南永州道县；湖南永州零陵', '[]', '[]', '抗日战争时期', '', '在城步地区担任伪保甲长，为日军征收物资、传递情报，协助维持地方伪秩序。；湖南籍，原国民党湖南省主席，抗战期间与日方有接触，其部分旧部在湖南沦陷区有附逆行为。；日军占领邵阳期间，出任伪警察局局长，协助日军搜捕抗日人员、维持治安，镇压民众反抗。；无；长沙沦陷期间，参与伪维持会，为日军筹款筹粮，协助维持殖民统治。；在零陵（今永州零陵区）组织维持会，配合日军统治，征发民夫。；日军第四次长沙会战占领长沙后，出面组织伪维持会，协助日军维持城区秩序、征调物资。；在汪伪政权下负责湖南沦陷区教育，推行奴化教育，篡改教材，宣传“大东亚共荣”。；经检索，张治中为抗日爱国将领，非汉奸，不应列入。；湖南籍要人，日伪曾试图拉拢其出任伪职，未成，但相关接触被记录。', '[]', '2026-09-10 09:57:14.058385', '2026-09-10 09:57:14.058385', '湖南', '张家界', '永定', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b05c776cbe154161aaed89ad45056d38', '不详', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明盘龙；内蒙古呼伦贝尔根河', '[]', '[]', '抗日战争时期', '', '在根河地区（时属伪兴安北省）参与镇压抗日联军和当地民众，协助日军搜集情报，迫害抗联地下工作者。具体姓名因档案缺失未能确认。；在伪满统治下，参与推行殖民政策，强征劳工，配合日军“讨伐”抗联小部队，并参与对鄂温克、鄂伦春等民族的监控。具体姓名未见于公开史料。；经检索，昆明市盘龙区在抗战期间始终未被日军占领，未建立伪政权、维持会或伪警察机构。云南省内明确记载的汉奸主要集中在滇西沦陷区（腾冲、龙陵等地），但与昆明盘龙地区无直接关联。因此，针对云南、昆明、盘龙地区的汉奸名录，公开可靠史料中无具体可列人员。', '[]', '2026-09-10 09:57:13.985801', '2026-09-10 09:57:13.985801', '云南', '昆明', '盘龙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b06148aa3ce04d078d1ff871c471f369', '杜月笙', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波；上海杨浦', '[]', '[]', '抗日战争时期', '', '本人流亡香港，但其门徒如万墨林等在上海杨浦地区为日伪传递情报，参与经济投机。；宁波人，但实际未投敌，反而支持抗日，故不列入汉奸。此条为排除项。', '[]', '2026-09-10 09:57:13.977349', '2026-09-10 09:57:13.977349', '上海', '杨浦', '奉化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b06257fac2f643d18dfb68906bf89e8d', '鲍贵廷', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼和浩特和林格尔', '[]', '[]', '抗日战争时期', '', '和林格尔本地士绅，日军占领和林格尔后组织维持会，任会长，协助日军征粮、征夫，维持地方伪秩序，镇压抗日群众。', '[]', '2026-09-10 09:57:13.989761', '2026-09-10 09:57:13.989761', '内蒙古', '呼和浩特', '和林格尔', NULL, NULL, NULL, NULL, '');
