INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b06ca18266cd47a189f07b8f909104b3', '许铁英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '永年；河北邯郸鸡泽；河北邯郸永年', '[]', '[]', '抗日战争时期', '', '伪职：土匪投敌，伪铁血团司令；残害抗日军民数百；日降后被国民党收编固守广府城。；结局：1947 永年突围战斗被击毙；依附日军，在鸡泽、永年等地烧杀抢掠，抓捕壮丁，配合日军“铁壁合围”。；伪职：土匪投敌，伪铁血团司令；残害抗日军民数百人；日降后被国民党收编，固守广府城，四处烧杀抢掠，制造多起惨案抖音百科。；结局：1947 永年解放突围时被击毙', '[]', '2026-09-10 09:57:14.045468', '2026-09-10 09:57:14.045468', '河北', '邯郸', '鸡泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b06d8fa583844a3c93834370e87f66c7', '李义生', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉汉阳', '[]', '[]', '抗日战争时期', '', '汉阳沦陷后组织伪维持会，任会长，为日军带路、筹粮、招募苦力，协助建立伪基层政权。', '[]', '2026-09-10 09:57:14.056621', '2026-09-10 09:57:14.056621', '湖北', '武汉', '汉阳', NULL, NULL, NULL, NULL, '');
