INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b0881a4c6cc1452a989cd9d8d316c780', '刘化溥', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州德城；山东德州；山东德州陵城；山东德州；山东德州平原；山东德州', '[]', '[]', '抗日战争时期', '', '伪鲁北道管辖包括德州一带，任内推行日伪政令，配合日军统治鲁北。；在德州沦陷区推行日伪奴化教育，协助日伪控制学校、审查教材，向学生灌输亲日思想。；在鲁北道伪政权中任职，管辖包括德州、平原在内的鲁北地区，协助日军推行治安强化运动和地方伪政。', '[]', '2026-09-10 09:57:14.013964', '2026-09-10 09:57:14.013964', '山东', '德州', '平原', NULL, NULL, NULL, NULL, '');
