INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b1d2a1f70b644c6b968b387180921810', '善吉密都布', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔新巴尔虎右旗', '[]', '[]', '抗日战争时期', '', '在新巴尔虎右旗担任伪旗长，听命于伪满洲国兴安北分省，协助日军和伪政权在当地推行保甲制度、征收物资、控制牧民。', '[]', '2026-09-10 09:57:13.988942', '2026-09-10 09:57:13.988942', '内蒙古', '呼伦贝尔', '新巴尔虎右旗', NULL, NULL, NULL, NULL, '');
