INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2630c6866cb4e8fb8ebffd56c96af83', '蓝祯白', NULL, NULL, NULL, NULL, 'exact', 'exact', '宜昌城区', '[]', '[]', '抗日战争时期', '', '伪职：伪宜昌县中央治安维持会会长；罪行：宜昌沦陷后，日寇随军特务机关长崛川芳雄胁迫引诱一些奸佞之徒，在中书街设伪宜昌县中央治安维持会，蓝祯白任会长。1941年2月伪维持会撤销后，改任合作社社长；结局：抗战胜利后经国民党审查无劣迹释放；解放后被公安局传唤调查，经多方查证认为其在日伪时期“抱定不坑人不害人的宗旨”，予以释放', '[]', '2026-09-10 09:57:14.069588', '2026-09-10 09:57:14.069588', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b26c93537ee84715831b539991ceea5a', '李宪文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原晋源', '[]', '[]', '抗日战争时期', '', '在晋源地区推行日伪政权，征收苛捐杂税，强迫民众劳役。', '[]', '2026-09-10 09:57:14.021456', '2026-09-10 09:57:14.021456', '山西', '太原', '晋源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b26f176c5f76434599d8f0f78007bc28', '汪少山', NULL, NULL, NULL, NULL, 'exact', 'exact', '休宁屯溪商界', '[]', '[]', '抗日战争时期', '', '伪职：休宁资敌奸商；罪行：商人，私下通过边境通道，向芜湖日伪走私茶叶、桐油等战略物资，换取日伪鸦片，属于重大资敌分子，没有出任伪职。；结局：抗战胜利后肃奸立案，没收全部资产，判处有期徒刑。', '[]', '2026-09-10 09:57:14.087132', '2026-09-10 09:57:14.087132', '安徽', '黄山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b28926d70f4d47e18ba6695441bd85fc', '郴州维持会会长', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州桂东；湖南郴州', '[\"佚名\"]', '[]', '抗日战争时期', '', '日军侵占郴州期间，当地维持会负责人，姓名记载不详，协助日军维持地方秩序、征发物资。', '[]', '2026-09-10 09:57:14.059899', '2026-09-10 09:57:14.059899', '湖南', '郴州', '桂东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b29f9c2f92b4406cb24c2a059ad449b9', '王楚材', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北随州随县；湖北随州曾都；湖北随州广水；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '随县沦陷后组织伪维持会，为日军筹粮筹款、维持地方伪秩序，协助日军控制随县城区。；在随县、曾都一带收编地方武装，组织伪保安团配合日军扫荡，参与清乡、封锁抗日根据地，镇压抗日群众。；在随县沦陷区组建伪警察队伍，配合日军搜捕抗日人员，镇压民众反抗。；率伪保安队配合日军扫荡随县南部山区，搜捕抗日游击队员，强征民夫修筑据点。', '[]', '2026-09-10 09:57:14.057308', '2026-09-10 09:57:14.057308', '湖北', '随州', '广水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2a2ba0e267143109c50ff0e23aa393b', '林瑞云', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南东方', '[]', '[]', '抗日战争时期', '', '在崖县地区主办伪报刊与广播，为日军侵略辩护，诋毁抗日力量。', '[]', '2026-09-10 09:57:14.053710', '2026-09-10 09:57:14.053710', '海南', '东方', NULL, NULL, NULL, NULL, NULL, '');
