INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2b49ff7fc06445d9f3769a1c77dc627', '黄曦', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉；辽宁沈阳大东；湖南_湘西_泸溪；湖北武汉青山；湖北武汉', '[]', '[]', '抗日战争时期', '', '湖南籍伪军将领，率部在湘北配合日军清乡。；抗战期间在武汉伪政权中负责宣传，为日军占领进行粉饰宣传。；任伪湖北省政府宣传处处长，主办亲日报刊和广播，散布“大东亚共荣”谬论，诋毁抗日力量。', '[]', '2026-09-10 09:57:14.056559', '2026-09-10 09:57:14.056559', '湖北', '武汉', '青山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2b6138f5c1c40e29751373a86d04373', '刘兴汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江_黑河_北安', '[]', '[]', '抗日战争时期', '', '组织青年进行奴化教育，为日军招募“义勇队”。', '[]', '2026-09-10 09:57:14.066789', '2026-09-10 09:57:14.066789', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2bd96647fbc45e5ae9efa55cc1dd53f', '陈友仁', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东深圳；陕西_西安_长安；福建福州平潭；福建福州；浙江_台州_临海；广东深圳盐田；广东韶关南雄；福建南平延平；福建福州；福建莆田；浙江金华磐安；福建南平松溪；广东惠州；山西阳泉城区；福建三明尤溪；广东河源紫金；广东河源', '[]', '[]', '抗日战争时期', '', '组织伪民众团体，在深圳等地进行亲日宣传，配合日军殖民统治。；在汕头沦陷后出任伪市长，协助日军在潮汕地区推行伪化统治。；在广东沦陷区推行奴化教育，编写亲日教材，其教育政策影响包括河源、紫金在内的广东多地，毒害青年思想。；莆田沦陷时出面组织伪维持会，协助日军统治。；松溪县人，抗战期间在松溪组织伪维持会并任会长，为日军及伪政权筹粮筹款，协助登记户口、推行奴化宣传，镇压当地抗日活动。；指挥伪警察协助日军搜捕抗日分子，破坏地下交通站，抄没抗日家属财产。；抗战初期日本方面曾试图拉拢其参加华南伪政权，陈友仁未正式附逆，但曾与日方接触，被列入当时舆论关注的附逆嫌疑名单；其活动涉及广东及香港。；充任伪警察头目，协助日军搜捕抗日人员，镇压民众抗日活动，维护日伪在惠州城区的统治秩序。；尤溪地区附逆人物，组织伪维持会，为日军及伪政权筹粮、派夫、维持地方伪统治。；广东沦陷区伪商会头目，为日军筹款筹物，协助经济掠夺，与粤北物资流通及伪政权有直接关联。；延平本地士绅，抗战期间附逆，任伪延平县维持会副会长，协助日军征发民夫、物资，宣传“中日亲善”。；日军首次侵入磐安时出任维持会会长，为日军筹集粮饷，指认抗日分子，导致多名群众被捕遇害。；福州沦陷时期在伪警察系统任职，参与搜捕抗日人员、维持日伪治安。；在汪伪政权中任外交要职，参与对日妥协。', '[]', '2026-09-10 09:57:14.027232', '2026-09-10 09:57:14.027232', '广东', '惠州', '紫金', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2bead37adc247ac89f9af23cdcd78cd', '汪瑞闿', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_杭州_余杭；浙江舟山；江苏淮安盱眙；江西', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪浙江省首任省主席（1938??1940），杭州伪政权开创者，组建全套伪省厅机构。结局：1940 年病亡杭州，逃脱审判', '[]', '2026-09-10 09:57:14.051131', '2026-09-10 09:57:14.051131', '江苏', '淮安', '盱眙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2d12dca2ed8480a8aa248e6c914e36e', '刘湘', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；重庆涪陵；四川成都；重庆合川；重庆_大足；四川_成都_金牛；重庆万州；四川成都青羊；重庆沙坪坝；四川_成都_郫都；重庆渝中', '[]', '[]', '抗日战争时期', '', '抗战初期率川军出川，但与日方有过试探性接触，后病逝，未构成汉奸罪。；全面抗战爆发后率川军出川抗战，但此前曾与日本方面有联络，后在抗战中病逝，未被定性为汉奸。；在重庆及涪陵一带指挥伪警察搜捕抗日人士，破坏地下组织。；刘湘本人坚持抗日，但其死后部分部属如冷开泰等投敌，在成都地区组织伪政权，刘湘本人不属汉奸。；原为川军领袖，抗战初期曾率部出川，但后与日军秘密接触，意图投敌，其活动范围覆盖成都、邛崃，对当地抗日力量造成破坏。；刘湘本人坚持抗日，未附逆，但其部下中有人投敌，如王缵绪等，需注意区分。；日伪曾单方面宣布其任伪职，但刘湘实际坚持抗日，此处仅记录日伪宣传名单。；其部分旧部在成都地区组织伪保安队，协助日军维持治安，征收苛捐杂税。；四川军阀，抗战初期任第七战区司令长官，1938年病逝于汉口。未在重庆沙坪坝地区任伪职，亦无附逆行为，故不应列入汉奸名录。；作为川军领袖，抗战初期率部出川，病逝于汉口；日方曾试图拉拢四川地方势力，但刘湘未附逆。；原为四川军阀，抗战初期曾与日伪秘密接触，后因病去世，但其部分部下投敌，影响四川地区伪化活动。', '[]', '2026-09-10 09:57:14.001705', '2026-09-10 09:57:14.001705', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b2d26dcdf8dc484d8e2197143570463c', '吴常安', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江牡丹江经开区；黑龙江牡丹江东宁', '[]', '[]', '抗日战争时期', '', '在东宁边境地区协助日军封锁抗联国际交通线，抓捕越境抗联战士及苏联情报人员。', '[]', '2026-09-10 09:57:14.066481', '2026-09-10 09:57:14.066481', '黑龙江', '牡丹江', '牡丹江经开区', NULL, NULL, NULL, NULL, '');
