INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b387e0e062794dfdb78654119ce6846c', '谭启秀', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门开平；河北唐山开平；广东肇庆；广东佛山高明；辽宁沈阳和平；广东云浮', '[]', '[]', '抗日战争时期', '', '广东人，抗战期间投靠日军，组织伪和平救国军，在广东各地配合日军作战，其势力曾活动于珠江三角洲及佛山周边地区。；在粤西包括云浮地区参与伪维持会联合活动，协调各伪组织为日军服务，推行保甲连坐。；在江门、新会、开平一带活动，率伪军配合日军扫荡抗日游击队，控制水陆交通。；在肇庆、云浮、罗定一带收编土匪伪军，配合日军封锁西江，进攻抗日游击队。', '[]', '2026-09-10 09:57:14.024846', '2026-09-10 09:57:14.024846', '广东', '云浮', '高明', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3970b4518e74cbba41a9c34b2a40312', '孙小毛', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江嘉兴海盐', '[]', '[]', '抗日战争时期', '', '建立汉奸情报网，向日军报告新四军和国民党游击队活动地点，导致多次袭击和村民伤亡。', '[]', '2026-09-10 09:57:14.050638', '2026-09-10 09:57:14.050638', '浙江', '嘉兴', '海盐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b39ead5c7d974feea91c0ba87f676b61', '马永魁', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西大同浑源；黑龙江大庆大同；山西；大同；黑龙江大庆大同；山西大同；黑龙江大庆大同；山西朔州朔城', '[]', '[]', '抗日战争时期', '', '任伪大同县知事期间，推行保甲制度，强征壮丁，配合日军“治安强化运动”，迫害抗日家属。；任伪大同县知事期间，为日军征收粮款，抓捕抗日军民，并参与“清乡”行动，破坏地下抗日组织。；历任伪大同县知事、伪大同省民政厅长，推行保甲制度，强征壮丁，配合日军“三光政策”，在新荣地区多次组织伪军扫荡抗日根据地。；投靠日军，历任伪大同县知事，在浑源等地推行保甲制度，抓捕抗日分子，强征劳工。；伪职：伪晋北自治政府最高委员，后任伪蒙疆财政部长；罪行：大同商会会长，主动迎日军入城；参与搭建晋北伪政权，掌管财政，搜刮物资供给日军，管控商贸与煤炭资源。；结局：日本投降后被捕，以汉奸罪判处重刑', '[]', '2026-09-10 09:57:14.020821', '2026-09-10 09:57:14.020821', '山西', '大同', '浑源', NULL, NULL, NULL, NULL, '');
