INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3e614d06c204a348ba0e8a4a35c92e7', '李瑞山', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州章贡；辽宁沈阳大东；江西赣州上犹；江西赣州赣县', '[]', '[]', '抗日战争时期', '', '在赣州推行奴化教育，编写亲日教材，组织新民会宣传“大东亚共荣圈”，强迫师生参加日伪集会，毒化青年思想。；率伪保安团配合日军扫荡赣县、上犹一带抗日游击队，烧毁民房，抢掠百姓财物。', '[]', '2026-09-10 09:57:14.040450', '2026-09-10 09:57:14.040450', '江西', '赣州', '上犹', NULL, NULL, NULL, NULL, '');
