INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3f28a585c204e35b301d90815475772', '河野悦次郎', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西吕梁石楼；山西吕梁', '[]', '[]', '抗日战争时期', '', '协助金井章二控制伪山西省政权，在吕梁地区推行日军殖民政策，参与对抗日根据地的扫荡。', '[]', '2026-09-10 09:57:14.020624', '2026-09-10 09:57:14.020624', '山西', '吕梁', '石楼', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3f3b9afa7744849bab74f2330e1e6af', '李春农', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南白沙；海南海口；海南东方；内蒙古乌海海南；海南海口龙华；海南海口；海南三亚吉阳；内蒙古乌海海南；广西桂林资源；海南文昌；广西防城港港口；海南琼中；海南定安；海南海口秀英；海南海口；海南三沙中沙；内蒙古乌海海南；海南三亚崖州；内蒙古乌海海南；海南三亚海棠；内蒙古乌海海南；海南海口；内蒙古乌海海南；海南三亚；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在海口沦陷后与日军合作，控制商会和物资配给，为日军筹措军需、粮食和劳工，压迫商民。；在海南文昌等琼北地区任伪县长，组织伪维持会和伪保安队，配合日军扫荡抗日乡村，镇压民众抗日活动。；在海南充任伪职，协助日军征粮、拉夫、清乡，其伪政权体系延伸至海南南部包括崖县地区。；文昌沦陷后附逆，任伪文昌县县长，建立伪区乡政权和伪自卫队，协助日军控制文昌沿海及清澜港一带，参与封锁抗日根据地和掠夺渔盐资源。；在文昌一带组织伪政权和伪维持会，配合日军扫荡抗日游击区，征发民夫与物资。；在海口地区为日军维持治安、征收物资，参与伪政权决策。；在海口及琼山、琼海一带协助日军实施保甲连坐，搜捕抗日人员，强征物资。；在海口地区组织伪民众自治会，配合日军进行宣传、劳军、物资征集，拉拢地方士绅附逆。；担任伪海口市长期间，协助日军管理港口、物资统制，搜刮民财，镇压海口抗日活动。；统辖海南伪警察力量，配合日军在包括崖县、三亚在内的海南各地镇压抗日活动。；参与海南伪政权事务，协助日军推行殖民统治和反共宣传。；统管海南伪警察系统，崖县、三亚伪警察受其节制，参与搜捕抗日人士、镇压民众。；投靠日军，任伪定安县县长，组织伪维持会，协助日军对琼山、定安一带抗日根据地进行扫荡。；参与伪琼崖临时政府事务，协助日军在海南推行伪化行政，动员地方资源支持日军。；在海南伪政权中任职，协助日军进行地方控制、征发物资和宣传奴化教育。；为日军筹款征粮，推行伪币与物资管制，剥削海南民众，支持日军侵略经济体系。；为日军筹款征粮，控制海南沦陷区经济，压榨民众，支持日伪统治。；负责伪政权财政搜刮，为日军和伪政权筹措经费，加重海南民众负担。；主持伪宣传机构，为日军侵略辩护，散布亲日言论，配合文化渗透。', '[]', '2026-09-10 09:57:14.053054', '2026-09-10 09:57:14.053054', '海南', '三亚', '吉阳', NULL, NULL, NULL, NULL, '');
