INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3fcb5e38c8c48939d2277403503b39f', '汪锦元', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州开化', '[]', '[]', '抗日战争时期', '', '协助傅春生组织伪维持会，向日军提供地方情报并摊派物资。', '[]', '2026-09-10 09:57:14.052278', '2026-09-10 09:57:14.052278', '浙江', '衢州', '开化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b3ff2314af544c6790bdf86c431c90ef', '成建基', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东滨州邹平；辽宁铁岭清河；山东潍坊临朐；山东东营广饶；广饶县（今东营区）；山东东营河口；辽宁铁岭清河；山东淄博桓台；辽宁铁岭清河；山东滨州惠民；山东滨州沾化；辽宁铁岭清河；山东滨州无棣；山东滨州；山东淄博；山东东营广饶；山东淄博桓台；山东聊城；山东潍坊安丘；山东东营广饶；山东东营东营港经开区；辽宁铁岭清河；辽宁铁岭清河；河北邢台清河；山东东营垦利；辽宁铁岭清河；山东东营；山东东营利津；辽宁铁岭清河', '[]', '[]', '抗日战争时期', '', '伪职：伪山东省保安十六旅三团团长、垦利县保安大队长；罪行：字立堂，绰号野马。1941年6月投靠日军，盘踞三里庄据点。先后杀害党员干部、八路军及群众300余人。1943年公然与日伪合流。1945年制造博兴“五二一”惨案，致180余人牺牲；结局：1948年5月在昌乐解放时重伤自杀', '[]', '2026-09-10 09:57:14.011545', '2026-09-10 09:57:14.011545', '山东', '东营', '东营港经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b403be07806b40e89d5bbfad3648b040', '黄绍雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华义乌；浙江丽水云和；河南郑州中牟；浙江衢州常山；浙江温州泰顺', '[]', '[]', '抗日战争时期', '', '组织商会为日军采购军需物资，从中牟利，并强迫商户向日军献金献粮。；专门收集抗日武装情报，多次带领日军偷袭游击队驻地，造成重大伤亡，并参与诱捕中共干部。；主持清乡工作，组织“自首”运动，诱捕抗日群众，烧毁村庄多处；专门为日军收集金义浦地区抗日武装情报，多次带日军突袭游击队驻地，导致多名抗日战士牺牲。', '[]', '2026-09-10 09:57:14.049377', '2026-09-10 09:57:14.049377', '浙江', '丽水', '云和', NULL, NULL, NULL, NULL, '');
