INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b4889e19eb634b40a47a6674fb3ac5d8', '张允中', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江海林', '[]', '[]', '抗日战争时期', '', '指挥伪警察多次突袭海林地区抗联密营，逮捕并刑讯逼供抗日军民，直接参与杀害抗联战士的行动。', '[]', '2026-09-10 09:57:14.066447', '2026-09-10 09:57:14.066447', '黑龙江', '牡丹江', '海林', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b4894224ae6d4c47ba45af1d7267bebd', '颜秀五', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州；江苏扬州；陕西_西安；江苏泰州靖江', '[]', '[]', '抗日战争时期', '', '原国民党鲁苏皖边区游击部队将领，随李长江投敌，在泰州、姜堰地区驻防，参与伪化政权建设与对抗日根据地的封锁扫荡。；投敌后任伪第四军军长，配合日军。；随李长江投敌，任伪军师长，在泰州及周边地区活动，参与日军对苏中地区的清乡与扫荡，搜捕抗日人员。；原李长江部旅长，随李投敌后任伪师长，驻防扬州地区，参与清乡和“扫荡”，劫掠百姓，捕杀抗日人员。；协助李长江管理伪军，参与策划对苏中根据地的“扫荡”，残害抗日军民。；原李明扬部游击司令，投敌后驻防扬州西郊及江都部分地区，为日军提供情报，参与“治安强化”运动。', '[]', '2026-09-10 09:57:14.035388', '2026-09-10 09:57:14.035388', '江苏', '泰州', '靖江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b48c1510cce54979bbf363930d89067b', '旺丹尼玛', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔牙克石；内蒙古乌兰察布察哈尔右翼中旗；内蒙古通辽科尔沁左翼后旗；内蒙古赤峰巴林右旗；内蒙古兴安科尔沁右翼中旗', '[]', '[]', '抗日战争时期', '', '在内蒙古地方伪政权中任职，配合日本殖民统治。；察哈尔右翼镶红旗蒙古贵族，任伪旗总管，与察哈尔右翼中旗同属察哈尔右翼，协助日军统治。；在科尔沁右翼中旗任伪警务科长，指挥伪警察配合日军‘讨伐’抗日游击队，迫害抗日群众。；在科尔沁左翼后旗基层推行保甲制度，监视民众，向日军举报抗日人员，配合伪警察抓捕抗日群众。；在巴林右旗或邻近旗县任伪保甲长，协助日军征发粮食、民夫，监视抗日群众。', '[]', '2026-09-10 09:57:13.987353', '2026-09-10 09:57:13.987353', '内蒙古', '乌兰察布', '察哈尔右翼中旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b48c9f2c1a254ccabee2bdf5267e69a6', '李景友', NULL, NULL, NULL, NULL, 'exact', 'exact', '盂县', '[]', '[]', '抗日战争时期', '', '伪职：伪先锋队队长；罪行：带队下乡清乡扫荡，抓捕地方干部，掠夺粮食牲畜。；结局：抗战结束后清算处决', '[]', '2026-09-10 09:57:14.078416', '2026-09-10 09:57:14.078416', '山西', '阳泉', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b4a4c50eb0ad4c9f9b268f38780940f4', '金汤侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴；广西桂林资源', '[]', '[]', '抗日战争时期', '', '为日军修建军用码头和公路，强拆民房，征用劳力，并参与掠夺当地石料资源。；组织商会为日军提供物资，强迫商户缴纳“慰劳金”，协助日伪经济统制。', '[]', '2026-09-10 09:57:14.051819', '2026-09-10 09:57:14.051819', '浙江', '绍兴', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b4a6807aea4645799a7e5b00dcc2568e', '郝梦九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台任泽', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，贪污中饱，逼迫百姓缴纳“治安费”“慰劳金”，导致民不聊生。', '[]', '2026-09-10 09:57:14.044670', '2026-09-10 09:57:14.044670', '河北', '邢台', '任泽', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b4b252723f1a4700af3e3a905f765b5d', '吴直夫', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古乌海海南；海南', '[]', '[]', '抗日战争时期', '华北伪临时政府', '伪任职务：伪琼崖临时政府副主席，伪政务委员会副委员长，伪政权二号文官，主管财税民政。结局：战后捕获，公审死刑枪决', '[]', '2026-09-10 09:57:14.053281', '2026-09-10 09:57:14.053281', '海南', NULL, NULL, NULL, NULL, NULL, NULL, '');
