INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b51fca47b7844e1cb64c03d101ceceec', '孙柏青', NULL, NULL, NULL, NULL, 'exact', 'exact', '兴隆', '[]', '[]', '抗日战争时期', '', '伪职：伪青龙县县长；强力推行集家并村、修建人圈，疯狂清剿长城沿线抗日武装，制造多起惨案。；结局：1945 被俘，公审判处死刑；伪职：伪兴隆县长，重点推行长城 “无人区” 政策，疯狂清剿。；结局：1945 年被俘，公审死刑；伪职：伪兴隆县县长；强力推行集家并村，强修人圈，疯狂清剿雾灵山抗日根据地，制造多起惨案。；结局：1945 被俘，公审判处死刑；伪职：伪青龙县县长；执行长城无人区政策，强修 “人圈”，疯狂清剿长城沿线抗日武装，抓捕迫害大量群众。；结局：1945 年被俘，公审判处死刑', '[]', '2026-09-10 09:57:14.067587', '2026-09-10 09:57:14.067587', '河北', '承德', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b5200e74065645f4a20dc0312590923a', '黄功灼等5人', NULL, NULL, NULL, NULL, 'exact', 'exact', '赣北（九江及周边）', '[]', '[]', '抗日战争时期', '', '伪职：地方汉奸、地主土劣；罪行：卖国求荣，为日军提供情报、带路扫荡、祸害当地百姓；结局：被赣北抗日游击队依法镇压处决（来源：赣北地区基层汉奸代表，史料仅记载姓名及被处决事实）', '[]', '2026-09-10 09:57:14.078515', '2026-09-10 09:57:14.078515', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b523f62efae64c18bcb40e90c681475d', '林梦飞', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建泉州晋江；福建泉州；福建泉州石狮；福建泉州安溪；福建莆田', '[]', '[]', '抗日战争时期', '', '安溪沦陷期间组织维持会，协助日军统治。；莆田人，日军占领莆田期间组织伪维持会并任会长，为日军征集物资、维持地方伪秩序。；福建晋江人，在泉州、石狮、泉港沿海为日军收编海盗与地方武装，组织伪军配合日军扫荡抗日根据地。', '[]', '2026-09-10 09:57:14.061719', '2026-09-10 09:57:14.061719', '福建', '泉州', '晋江', NULL, NULL, NULL, NULL, '');
