INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b5f640c1d7e34ebfbc78891fb6ac94de', '李廷栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安泰和；江西南昌', '[]', '[]', '抗日战争时期', '', '日军侵占南昌后，组织伪南昌县维持会，协助日军维持占领区秩序，征发民夫、粮食，为日军侵华提供支持。', '[]', '2026-09-10 09:57:14.039872', '2026-09-10 09:57:14.039872', '江西', '吉安', '泰和', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b5f921d84d36444592c07235fe35df51', '阿旺根敦', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古赤峰巴林左旗；内蒙古赤峰阿鲁科尔沁旗', '[]', '[]', '抗日战争时期', '', '蒙古族，伪满兴安西省阿鲁科尔沁旗旗长，在阿鲁科尔沁旗（邻近巴林左旗）推行保甲制度，征粮征畜，协助日军维持殖民统治。', '[]', '2026-09-10 09:57:13.991373', '2026-09-10 09:57:13.991373', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b602f041b36e4cbb918c382326963b98', '曹伯闻', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡南；湖南长沙；湖南长沙；湖南衡阳雁峰；湖南衡阳；湖南长沙浏阳；湖南永州蓝山；湖南长沙天心；湖南长沙；湖南_郴州_桂东；浙江金华磐安；浙江金华', '[]', '[]', '抗日战争时期', '', '参与日军策划的伪湖南省政府筹备，协助推行伪化行政。；作为伪省府参议，多次到金华、磐安督导“剿共”工作，建议强化伪警察机构，并参与策划对抗日根据地的经济封锁。；率部投敌，改编为伪保安团，配合日军在长沙近郊进行清乡与搜捕。；湖南籍人物，日军占领湖南期间参与伪教育行政，推行奴化教育。；湖南籍，在日军占领湖南期间参与伪湖南省政府，协助日军推行伪化政策。；长沙商人，日军占领后出面组织伪商会，为日军筹款筹物，协助经济掠夺，与宁乡商界有联系。；在衡阳沦陷区负责伪宣传，散布亲日言论，配合日军进行思想控制。；长沙沦陷期间组织维持会，为日军服务，影响波及衡阳地区伪政权运作。', '[]', '2026-09-10 09:57:14.052689', '2026-09-10 09:57:14.052689', '浙江', '金华', '磐安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b60b5f5ea6c1404cbb8aa939434ccca7', '李士群下属', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦', '[\"具体姓名不详\"]', '[]', '抗日战争时期', '', '在杨浦区监视工厂工人，报告抗日活动。', '[]', '2026-09-10 09:57:13.978556', '2026-09-10 09:57:13.978556', '上海', '杨浦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b60b9962dc7c43cc8c9c16a2c463c295', '王剑斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林经开区；江苏扬州；江苏扬州；江苏泰州兴化；江苏扬州仪征；江苏扬州；江苏盐城东台', '[]', '[]', '抗日战争时期', '', '主持东台地区“清乡”，设立封锁线，屠杀抗日家属，推行连坐制。；日军初占兴化时组织维持会，为日军筹粮派夫，协助建立伪政权。；原李长江部旅长，投敌后任伪师长，驻防扬州西郊，协助日军封锁抗日游击区。；在扬州推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，迫害爱国教师和学生。；任伪江都县警察局长期间，在扬州城区及近郊（含今经开区部分区域）设立特务据点，逮捕抗日地下工作者，刑讯逼供。；管理伪警察机构，在扬州城内设立特务据点，侦捕地下党员和进步学生，破坏抗日组织。', '[]', '2026-09-10 09:57:14.035455', '2026-09-10 09:57:14.035455', '江苏', '扬州', '仪征', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b60f5a83bbcd40c5b3e961eaf7e948d4', '李青云', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆南岸', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：日伪外围情报员，搜集兵工厂、码头、川湘公路运输情报，秘密转交日特机关。。结局：军统破获逮捕，判处有期徒刑', '[]', '2026-09-10 09:57:14.071919', '2026-09-10 09:57:14.071919', '重庆', '重庆', NULL, NULL, NULL, NULL, NULL, '');
