INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b641f9f3f3c04f62bb57514bfae7324b', '穆子厚', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽东明', '[]', '[]', '抗日战争时期', '', '日军侵占东明后出面组织维持会，为日军筹粮筹款、拉夫派丁，协助日军维持占领秩序，是东明地区较早投敌的汉奸头目之一。', '[]', '2026-09-10 09:57:14.017901', '2026-09-10 09:57:14.017901', '山东', '菏泽', '东明', NULL, NULL, NULL, NULL, '');
