INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b668161f6c604a4d9c3aeb67a31a64aa', '马选三', NULL, NULL, NULL, NULL, 'exact', 'exact', '绥远（归绥，今内蒙古）', '[\"马朝选\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：包头日本特务机关松井恒白派遣间谍，潜入西宁东关，拉拢地方人员，散布分裂谣言，搜集青海军政情报，策动西北分裂活动。。结局：1938 年在西宁被捕，押解兰州第八战区处置，判处重刑关押', '[]', '2026-09-10 09:57:14.084423', '2026-09-10 09:57:14.084423', '内蒙古', '呼和浩特', NULL, NULL, NULL, NULL, NULL, '');
