INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b66a2587f2f84adc87d8234f7a0bf206', '张启璜', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南信阳固始；湖北仙桃；湖北十堰竹溪；湖北孝感孝南；湖北孝感；河南信阳潢川；河南信阳浉河；山西阳泉城区；湖北襄阳老河口；湖北荆州石首；河南南阳；河南信阳；山西阳泉城区；河南信阳息县；湖北襄阳；湖北孝感安陆；河南平顶山鲁山；湖北襄阳谷城；河南信阳平桥；山西阳泉城区；湖北十堰竹山；河南信阳光山；湖北恩施鹤峰；湖北潜江；湖北荆州沙市；武汉（伪军）；湖北孝感；湖北孝感应城；湖北十堰房县；湖北襄阳枣阳', '[]', '[]', '抗日战争时期', '', '伪职：伪军师长；罪行：汪伪军头目', '[]', '2026-09-10 09:57:14.045961', '2026-09-10 09:57:14.045961', '河南', '信阳', '信阳高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b66ccfeefa6b440bb8af1e88fcd0442b', '牛荫鹰', NULL, NULL, NULL, NULL, 'exact', 'exact', '无锡县城', '[]', '[]', '抗日战争时期', '', '伪职：第五任伪无锡县县长；罪行：官僚出身，应付日伪，听闻抗日武装要锄奸，主动辞职逃离无锡。；结局：战后被逮捕审判。', '[]', '2026-09-10 09:57:14.082420', '2026-09-10 09:57:14.082420', '江苏', '无锡', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b674ad98c774490c8c172f0357426149', '陈海清', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁；湖南郴州临武；湖南娄底双峰；重庆璧山；重庆江北；湖北宜昌；湖北宜昌当阳；湖南郴州永兴', '[]', '[]', '抗日战争时期', '', '日军侵占双峰期间，出面组织维持会，为日军征派粮秣、夫役，协助维持占领区秩序。；利用保甲长身份为日军刺探军事情报，带领日伪军搜捕抗日人员，勒索当地百姓。；临武沦陷后投靠日军，充任伪保安队头目，率部配合日军下乡扫荡、搜捕抗日人员。；统领伪保安队协助日军扫荡周边乡村，捕杀抗日军民，抢掠民财。；在当阳统率伪保安队，配合日军扫荡抗日游击队。；率伪保安团协助日军扫荡周边抗日武装，强征民夫，掠夺物资。；郴县沦陷后收编地方武装，任伪保安团长，配合日军“清乡”与扫荡，活动范围覆盖郴县、永兴交界地区。', '[]', '2026-09-10 09:57:14.056139', '2026-09-10 09:57:14.056139', '湖北', '宜昌', '双峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b67c09d3c1c14d7d86cb1f2e9fcc52ad', '岑德广', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海虹口；广西西林；江苏南京；浙江宁波鄞州；浙江宁波；上海静安；安徽芜湖；江苏南京建邺；江苏南京溧水；上海浦东', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪中央政治委员、赈务委员会委员长，桂籍最高级别汪伪大员，参与汪伪政权顶层策划。结局：抗战胜利被捕，后潜逃香港，逃脱审判', '[]', '2026-09-10 09:57:13.979208', '2026-09-10 09:57:13.979208', '上海', '虹口', '建邺', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b686c24535bc4dd2ad7e557e61e9ba12', '龙辑五', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南湘西花垣', '[]', '[]', '抗日战争时期', '', '湖南花垣人，日军侵入湘西时组织维持会，协助日军维持地方秩序，征调物资与民夫。', '[]', '2026-09-10 09:57:14.059084', '2026-09-10 09:57:14.059084', '湖南', '湘西', '花垣', NULL, NULL, NULL, NULL, '');
