INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b6a12b6425064dcbad262e0768d0509a', '陈志明', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江丽水；浙江台州仙居；浙江丽水缙云；浙江丽水景宁；浙江丽水莲都；浙江温州苍南', '[]', '[]', '抗日战争时期', '', '日军占领景宁期间，组织维持会，协助日军征粮派款，迫害抗日民众，提供情报给日军。；组织伪保安队配合日军扫荡，捕杀抗日军民，破坏地下交通线。；率伪军配合日军扫荡丽水周边乡村，杀害抗日军民，烧毁民房。；组织伪保安队，配合日军扫荡抗日武装，抓捕抗日军民并移交日军。；在苍南地区为日军提供情报，组织伪保安队协助日军扫荡抗日武装。；任伪仙居县县长期间，推行日伪政权，强征民夫，搜刮粮食资敌，镇压抗日活动。', '[]', '2026-09-10 09:57:14.049195', '2026-09-10 09:57:14.049195', '浙江', '丽水', '景宁', NULL, NULL, NULL, NULL, '');
