INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b6dd67b40c494a96970bf7c5fe2b72a7', '覃某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西百色田东；广西百色；广西贵港平南', '[\"覃寿彭\", \"名不详\"]', '[]', '抗日战争时期', '', '日军占领期间，以商会名义为日军筹集物资、军饷，协助日军控制百色商业，压榨商户和百姓。；在平南沦陷期间率伪保安队配合日军扫荡抗日游击队。', '[]', '2026-09-10 09:57:14.032918', '2026-09-10 09:57:14.032918', '广西', '百色', '田东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b71c2dae24e4437e8f81259de33a538c', '黄强', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳坪山；广东深圳龙岗；广东深圳；广东湛江麻章；广东湛江雷州；海南三沙中沙；海南澄迈；海南海口；广西桂林恭城；云南普洱西；广东湛江；海南三沙西沙；海南澄迈；广东惠州惠东；广东惠州；海南东方；内蒙古乌海海南；海南_五指山；广东深圳南山；广东深圳；广东深圳福田；广东深圳；广东湛江赤坎；广东广州；海南屯昌；海南海口琼山；海南海口；海南海口秀英；海南海口；海南三亚崖州；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '参与伪政权宣传和情报工作，协助日军镇压抗日力量。；深圳墟沦陷后任维持会会长，协助日军管理深圳墟及附近乡村，征发民夫、物资，配合日军清乡。；广西沦陷期间，任伪宣传处长，进行亲日宣传。；率领伪军驻守深圳、福田一带，配合日军对东江抗日游击区进行扫荡，抢掠民财，杀害抗日人员。；率伪军配合日军对坪山、龙岗一带进行扫荡，捕杀抗日游击队员及家属。；率伪军配合日军对宝安、深圳一带进行清乡，烧毁抗日村庄，勒索民众财物。；在海南日占区参与推行奴化教育，宣传所谓“大东亚共荣圈”，活动范围涉及海南南部。；在澄迈地区投敌，组织伪政权和伪武装，配合日军对抗日根据地进行经济封锁与军事扫荡。；在广东日伪政权中任职，参与推行日军殖民政策，协助维持会系统在广东各地的建立。；在澄迈地区组织伪政权，配合日军征粮、修路和清乡，压制当地抗日力量。；推行奴化教育，篡改教材，强迫惠州、惠东学校师生接受亲日宣传。；协调雷州半岛各伪维持会，配合日军统治，为日军提供情报，镇压抗日群众。；为日军筹款征粮，发行伪币，控制海口、琼山地区经济，压榨民众。；日军侵占广州后参与伪广东治安维持会，协助日军稳定广东占领区统治。；以商会会长身份与日军合作，为海口、秀英港的日军提供物资和情报，并协助管理码头劳工。；参与伪政权决策，协助日军征用劳工、修建军事设施，在海南多地活动。；在伪政权中负责民政事务，配合日军征粮征税。；负责伪政权宣传，散布亲日言论，为日军侵略辩护，麻痹民众抗日意志。', '[]', '2026-09-10 09:57:14.027476', '2026-09-10 09:57:14.027476', '广东', '惠州', '惠东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b725047b58554a28aa617dad4a9488ad', '杜子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_运城_万荣', '[]', '[]', '抗日战争时期', '', '为日军强征各种苛捐杂税，逼死多名交不起税的农民，并贪污部分税款，助纣为虐。', '[]', '2026-09-10 09:57:14.023637', '2026-09-10 09:57:14.023637', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
