INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b7673bdc6b944859990b3d00187bb432', '陈志坚', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_温州_鹿城', '[]', '[]', '抗日战争时期', '', '充当日军爪牙，指挥伪警察搜捕抗日志士，破坏地下抗日组织，参与“清乡”行动。', '[]', '2026-09-10 09:57:14.051506', '2026-09-10 09:57:14.051506', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b76c91dfa9c0425693218afa4ab7c270', '胡蕙', NULL, NULL, NULL, NULL, 'exact', 'exact', '南昌本地人；江西新建', '[]', '[]', '抗日战争时期', '', '伪职：南昌沦陷首任维持会会长；罪行：最早投靠日军，负责城区治安，为日军搜刮物资；结局：暂无明确结局记载；伪职：伪维持会会长；罪行：南昌沦陷初期，出任新建伪维持会会长，协助日军管控城区、搜刮物资，后因与日军指挥官矛盾辞职；来源：江西网、南昌抗战文史；备注：南昌最早一批伪组织头目', '[]', '2026-09-10 09:57:14.084317', '2026-09-10 09:57:14.084317', '江西', '南昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b772c76b844b4bd3be04640390dfd940', '李华', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江瑞昌；江西南昌新建；江西南昌；江西南昌进贤；江西_南昌_东湖；江西南昌；广西桂林恭城；云南普洱西；广西桂林恭城；云南昆明富民；江西九江修水；江西九江；江西南昌；江西赣州大余；江西赣州南康；江西上饶', '[]', '[]', '抗日战争时期', '', '日军占领上饶期间任伪警察局局长，带领伪警为日军维持治安、抓捕抗日群众。；九江沦陷初期组织维持会，为日军筹集粮秣、招募劳工，协助日军建立殖民秩序。；任伪警察头目，配合日军搜捕抗日人员，勒索市民，维持沦陷区治安。；在南昌县及进贤一带搜捕抗日人员，配合日军清乡，勒索民众。；江西新建人，投敌后任伪新建县长，协助日军控制南昌周边地区。；广西沦陷期间，任伪商会会长，为日军筹款筹粮。；日军进犯南康时，组织维持会迎接日军，协助征发粮食、民夫，并参与清查抗日人员。；在南昌沦陷区担任伪警察头目，配合日军抓捕抗日人员，镇压市民反抗，维持日伪殖民秩序。；广西沦陷期间，任伪保安大队长，配合日军。；南昌沦陷初期组织伪维持会，为日军筹粮筹款、招募伪警察，维持日占区秩序。；南昌沦陷初期组织伪维持会，为日军筹粮筹款、招募伪警。；南昌沦陷初期受日军指使筹组伪南昌市维持会，为日军筹办粮秣、夫役，诱迫商户复业以粉饰占领区秩序。；据部分地方史料记载，富民县在抗战期间曾有维持会组织，但具体负责人姓名及事迹记载不详。李华一名见于部分口述史料，称其曾担任富民县维持会会长，协助日军征粮派款，但缺乏确凿档案证据。；恭城沦陷期间，任伪保安大队长，配合日军。；率伪保安大队配合日军对南昌、新建周边乡村进行扫荡，捕杀抗日游击队员及家属，强征民夫修筑工事。；任伪瑞昌县警察局局长，统领伪警察配合日军搜捕抗日人员、镇压民众反抗、维护沦陷区治安。', '[]', '2026-09-10 09:57:13.985638', '2026-09-10 09:57:13.985638', '云南', '昆明', '富民', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b77fd920b0e84d7b8dd3b790e86c4527', '杨敬修', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津河东；山东临沂河东', '[]', '[]', '抗日战争时期', '', '率领伪保安队配合日军扫荡河东地区，抓捕抗日军民，抢劫财物，犯下多起罪行。', '[]', '2026-09-10 09:57:14.002977', '2026-09-10 09:57:14.002977', '天津', '河东', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b781e4a55b884761888b5b39581229c7', '宋澈', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾；山西运城；山西阳泉郊区；山西阳泉；山西；山西_太原；广西桂林资源', '[]', '[]', '抗日战争时期', '', '负责伪省财政，为日军搜刮民财，发行伪币，控制经济命脉。', '[]', '2026-09-10 09:57:14.019161', '2026-09-10 09:57:14.019161', '山西', '阳泉', '郊区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b785c83a1d5a4573ba2484cc9b2543a8', '李奎安', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆九龙坡；重庆巫山；重庆南岸；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '日军轰炸重庆期间，在南岸地区组织维持会，协助日军宣传‘大东亚共荣圈’，为日军提供本地情报与物资征集。；抗战期间滞留重庆，与日伪方面保持联系，参与组织伪商会，为日军经济掠夺提供协助。；抗战期间在巫山组织维持会，协助日军与伪政权维持地方秩序，征派民夫与物资。', '[]', '2026-09-10 09:57:14.063943', '2026-09-10 09:57:14.063943', '重庆', '九龙坡', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b7899659396d4fb8b56334730f8a4387', '王洪九', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博张店；山东淄博；山东淄博沂源；山东淄博；山东淄博博山；山东淄博；山东临沂莒南；山东临沂；山东济宁汶上；山东济宁；山东泰安宁阳；山东泰安；山东枣庄薛城；山东枣庄；山东临沂；山西阳泉城区；山东泰安岱岳；山东泰安；山东枣庄台儿庄；山东济宁邹城；山东济宁；山东日照日照经开区；江苏盐城滨海；山东枣庄山亭；山东枣庄；山东枣庄滕州；山东枣庄；山东济宁；山东淄博淄川；江苏徐州新沂；山东日照莒县；山东日照；山东临沂沂南；山东临沂；山东临沂沂水', '[]', '[]', '抗日战争时期', '', '在鲁南临沂、枣庄、费县一带活动，后与日伪合作，进攻抗日根据地，残害抗日群众，其武装在抗战后期具有明显附逆性质。；在鲁南地区投敌，组织伪军配合日军扫荡，其活动范围与泰安、宁阳周边日伪势力有联系。；投靠日军后任伪军旅长，在济宁、临沂一带袭击抗日武装，残害民众。；在鲁南地区组织伪军，配合日军扫荡，其活动范围涉及淄博南部边缘地区。；任伪临沂保安队头目，配合日军在鲁南、泰安南部地区进行扫荡和镇压抗日活动。；在鲁南地区组织伪军，配合日军扫荡，活动范围涉及济宁东部、邹县周边。；日军侵占临沂后出面组织维持会，后任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；抗战期间投靠日军，在临沂县城组织维持会，后任伪临沂县知事，协助日军征粮、征夫、清乡，镇压抗日群众。；日军侵占临沂后投敌，组织伪维持会，后任伪临沂县知事，协助日军推行保甲连坐、征粮抓丁，镇压抗日群众。；抗战期间投靠日军，在临沂县城组织维持会，后任伪临沂县知事，协助日军征粮、派夫、清乡，镇压抗日群众。；日军侵占临沂后出面组织维持会，充任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；日军侵占临沂后出面组织维持会，后任伪临沂县知事，协助日军推行保甲连坐、征粮派夫，镇压抗日群众，其势力范围覆盖临沂城区及罗庄一带。；抗战期间投靠日军，在临沂地区组织伪维持会，后任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；临沂沦陷后投靠日军，组织伪维持会，后任伪临沂县知事，协助日军征粮、派夫、清乡，镇压抗日群众。；抗战期间投靠日军，出任伪沂州道道尹兼伪临沂县知事，在临沂及沂南一带推行伪化统治，组织维持会、保甲制，配合日军清乡、扫荡，镇压抗日群众。；在鲁南地区投敌，组织伪军配合日军扫荡，活动范围覆盖枣庄、临沂一带，对当地抗日力量造成较大破坏。；抗战期间投靠日军，在临沂地区组织维持会，协助日军维持占领区秩序，推行伪化统治，搜捕抗日人员，为日军征发劳役和物资。；日军侵占临沂后出面组织维持会，后任伪临沂县县长，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；在鲁南地区为日军效力，管理伪政权，镇压抗日民众。；在鲁南地区包括枣庄东部一带充当伪军头目，袭击抗日武装，残害百姓。；在鲁中地区组织武装，后投靠日军，活动于淄博、沂源周边，参与反共扫荡，镇压抗日军民。；投日后任伪临沂县长，配合日军扫荡莒县、日照南部抗日根据地，屠杀抗日军民。；在临沂、日照交界地区组织伪政权和伪军，配合日军扫荡滨海根据地，残害抗日军民。；投日后控制临沂南部及新沂西部边界，设立伪据点，阻断抗日交通，残害群众。；抗战期间投靠日军，在沂水地区组织伪政权和伪军，配合日军扫荡抗日根据地，镇压抗日群众。；原国民党鲁南游击区司令，1943年投敌，任伪临沂道尹，其势力范围覆盖枣庄东部及台儿庄周边，配合日军扫荡。；在鲁南、鲁中地区组织伪政权和伪军，其势力范围一度延伸至淄博南部，参与日军扫荡。；在济宁、汶上、临沂一带组织伪军，配合日军清乡，捕杀抗日军民。', '[]', '2026-09-10 09:57:14.012088', '2026-09-10 09:57:14.012088', '山东', '临沂', '临沂高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b78a5f48b33a4355b90ac63617f368cd', '李德甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北仙桃', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校使用日伪教材，组织学生参加亲日集会。', '[]', '2026-09-10 09:57:14.054499', '2026-09-10 09:57:14.054499', '湖北', '仙桃', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b78a977954d642afba9718aeaa254dc1', '张从龙', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西临汾蒲县；山西；山西临汾翼城；山西临汾；山西临汾浮山；山西晋城泽州；山西临汾乡宁；山西长治；山西长治上党；山西长治壶关', '[]', '[]', '抗日战争时期', '', '伪职：末代伪安泽县县长；罪行：维持日伪末期统治，强征物资壮丁。；结局：光复后逮捕判刑；协助日军建立伪政权，为日军筹集粮款，强迫百姓领取“良民证”，举报抗日群众。；任日伪乡宁县县长期间，协助日军推行“治安强化”运动，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。；在古县地区组织维持会，协助日军征粮派款，出卖抗日积极分子，破坏地下抗日组织，导致多名群众被捕遇害。；任浮山县伪县长期间，积极推行日伪政权各项政策，组织维持会，协助日军征粮派款，镇压抗日民众，破坏地下抗日组织。；任浮山县伪县长期间，积极推行日伪政权，组织维持会，协助日军扫荡抗日根据地，强征民夫粮食，镇压抗日群众。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018453', '2026-09-10 09:57:14.018453', '山西', '临汾', '乡宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b78f396dc75841e28fa5bca4d651b8da', '潘某', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏苏州', '[\"潘子欣\"]', '[]', '抗日战争时期', '', '充当日伪经济工具，组织商会为日军筹措军费，控制苏州粮食与棉纱贸易，从中牟利，间接支持侵略战争。', '[]', '2026-09-10 09:57:14.036559', '2026-09-10 09:57:14.036559', '江苏', '苏州', NULL, NULL, NULL, NULL, NULL, '');
