INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b7a5d24333944b5eafb4faede496bc15', '陈式锐', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建厦门同安；福建厦门；福建漳州平和；福建漳州；福建漳州漳浦；福建漳州', '[]', '[]', '抗日战争时期', '', '负责伪厦门财政税收，为日军搜刮民财、维持伪政权运转。；负责伪厦门财政税收，为日军筹措军费，推行苛捐杂税。；为伪厦门政权搜刮民财，征收苛捐杂税，供应日军军需，属经济领域附逆者。；管理社会团体与户籍，协助日军实施保甲连坐、监控民众。；在漳州沦陷区或半沦陷区组织伪青年团，进行亲日宣传，诱骗青年加入伪军，活动范围包括漳浦、云霄等县。；漳州附逆分子，协助维持会征发民夫、物资供给日军。；推行奴化教育，篡改教材，向厦门及海沧等地学生灌输亲日思想。；在厦门沦陷区参与伪化教育、宣传亲日思想，协助日伪文化统制。', '[]', '2026-09-10 09:57:14.060705', '2026-09-10 09:57:14.060705', '福建', '厦门', '同安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b7a9a2c0d7af469e82c0d09ae97f23bb', '金名世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁兴京；吉林辽源龙山；吉林_长春_德惠；河北承德承德高；黑龙江伊春大箐山；北京大兴；辽宁朝阳凌源；吉林船营；吉林通化梅河口；吉林_延边_延吉；黑龙江鹤岗向阳；黑龙江佳木斯向阳；黑龙江黑河北安；黑龙江黑河；黑龙江哈尔滨双城；吉林延边敦化；黑龙江哈尔滨；吉林；吉林长春；河北承德；黑龙江鸡西；黑龙江双鸭山四方台；黑龙江牡丹江绥芬河；黑龙江双鸭山宝山；黑龙江双鸭山；黑龙江黑河爱辉；黑龙江黑河；黑龙江鹤岗；黑龙江齐齐哈尔；吉林、河北、辽宁；黑龙江佳木斯；黑龙江鹤岗兴安；黑龙江绥化；黑龙江牡丹江宁安；黑龙江黑河孙吴；黑龙江双鸭山；吉林长春；吉林松原松原经开区；吉林；吉林；吉林长春公主岭；吉林长春；吉林；辽宁鞍山；吉林昌邑；吉林；辽宁沈阳铁西；吉林；黑龙江牡丹江；黑龙江绥化兰西；吉林通化', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪新京特别市市长、伪民生部大臣；罪行：执行战时物资统制，强征国兵劳工，迫害爱国人士。；结局：苏军逮捕，抚顺战犯管理所关押，后特赦。；负责吉林地区伪警察系统，搜捕抗日分子，协助日军实施“治安肃正”。；原吉林警察机构官员，投日后任伪吉林省警务厅长，组织警察特务搜捕抗日分子，破坏地下组织，在丰满地区实施高压统治。；原吉林警察头目，投日后任伪满吉林省警务厅厅长，组织警察特务，在四平、伊通等地搜捕抗日志士，破坏地下组织。；原吉林省政府官员，投日后任伪吉林省长，管辖四平、梨树等地，推行“粮谷出荷”和“勤劳奉仕”制度。；满族亲日分子，在吉林市及昌邑区实施奴化教育，强征劳工，镇压反满抗日活动。……（共涉及30个地区的犯罪记录）；伪任职务：伪吉林省公署机要秘书，后任伪三江省省长，伪满核心官僚。结局：苏军逮捕，抚顺关押，1964 年特赦', '[]', '2026-09-10 09:57:13.995532', '2026-09-10 09:57:13.995532', '吉林', '延边', '敦化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b7a9c722f434423aa0fc2763036670cc', '罗俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江台州路桥；浙江台州', '[]', '[]', '抗日战争时期', '', '控制台州湾沿海航运，为日军运输物资、搜集沿海情报，协助日伪封锁抗日根据地海上通道，活动涉及海门、路桥、温岭沿海。', '[]', '2026-09-10 09:57:14.050222', '2026-09-10 09:57:14.050222', '浙江', '台州', '路桥', NULL, NULL, NULL, NULL, '');
