INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b80e4eba8f1947cbbe6dfe3303b590a1', '陈小汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '孝感花园镇', '[]', '[]', '抗日战争时期', '', '伪职：铁杆汉奸；罪行：深得日本驻军宠爱，为虎作伥。1943年正月十三日在松林湾毒打一名老大娘，逼问其子是否参加新四军；结局：1943年被新四军五师锄奸队副队长丁庆江活捉', '[]', '2026-09-10 09:57:14.067501', '2026-09-10 09:57:14.067501', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8191a8ac6b4470b9db70675f3687121', '冯小黑子', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀宁月山、凉亭乡', '[]', '[]', '抗日战争时期', '', '伪职：月山据点便衣特务；罪行：先投靠日军当情报特务，后又摇摆向国民党；日军为抓捕他扑空叶家享堂，迁怒无辜平民，酿成民间惨案中安在线。；结局：被我方武工队追踪击毙。', '[]', '2026-09-10 09:57:14.086006', '2026-09-10 09:57:14.086006', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8304b9f86b04c96807fcd765ebc1f70', '苏云英', NULL, NULL, NULL, NULL, 'exact', 'exact', '台湾高雄', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：勾结日军，诱杀抗日义军领袖林少猫及其部众五百余人；把持地方税收，协助殖民当局管控高雄，压榨地方百姓。。结局：1919 年病死，未经历战后审判', '[]', '2026-09-10 09:57:14.081439', '2026-09-10 09:57:14.081439', '台湾', '高雄', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b830dd8128b34c10a48f60e40811ec42', '王明远', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大庆让胡路；内蒙古呼和浩特；黑龙江鹤岗萝北；黑龙江鹤岗；黑龙江齐齐哈尔甘南；河南平顶山新华；河北石家庄新华；河南平顶山舞钢；河南新乡延津；河南新乡；河南郑州登封；河南三门峡义马；黑龙江鸡西恒山；黑龙江鸡西；黑龙江齐齐哈尔依安；河南开封尉氏；河南平顶山；河南平顶山叶县；内蒙古锡林郭勒多伦；河南三门峡陕州；甘肃甘南合作；重庆沙坪坝；黑龙江鸡西鸡冠；黑龙江鸡西；吉林经开区；河南郑州惠济', '[]', '[]', '抗日战争时期', '', '叶县沦陷后出任维持会会长，替日军征发民夫、粮食，维持地方伪秩序。；任伪依安县协和会会长，协助日军进行思想宣传与地方控制，推行奴化教育。；1944年日军侵占临汝后，出面组织维持会，为日军筹集物资、拉夫派款，协助日军维持占领区秩序。；郏县紧邻平顶山新华区，王明远在日军占领郏县后出任伪维持会会长，协助日军推行保甲、征粮抓丁，镇压抗日群众。；鸡西恒山地区伪保长，协助日军管理煤矿劳工，监视居民，举报抗日嫌疑人员。；1944年日军攻占登封后，出面组织伪维持会，为日军征粮征夫，协助维持占领区秩序。；伪满时期任安达县县长，安达为今大庆市辖区之一，其伪政权统治覆盖让胡路周边地区，协助日军征粮、征兵、镇压抗日活动。；协助日军强征劳工，送往东北各地工矿与军事工程。；在鹤岗煤矿负责劳工征发和管理，配合日军强征中国劳工，实施残酷压榨，导致大量劳工死亡，是经济领域附逆者的典型。；在伪新乡县政权中负责教育，推行奴化教育，篡改教材，向学生灌输亲日思想，属文化教育领域附逆者。；在新乡推行奴化教育，修改教材，灌输亲日思想，培训伪师资。；伪鸡西县警察头目，率伪警察配合日军搜捕抗日人员，镇压当地抗日活动，残害民众。；在惠济地区任伪乡长、保甲长，协助日军推行保甲连坐、征粮征丁，监控当地民众，是基层附逆人员的代表。；在多伦组建伪保安团，配合日军守备多伦，参与对抗日武装的围剿。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在甘南县任保长并兼伪协和会分会会长，推行保甲制度，协助日军征粮、抓劳工，进行奴化宣传。；投敌后任伪保安队队长，配合日军扫荡嵩山抗日根据地，残害百姓。；控制伪合作社，为日军统制物资、掠夺农产品，盘剥百姓。；负责伪宣传，散布亲日言论，为日军侵略辩护。', '[]', '2026-09-10 09:57:13.992507', '2026-09-10 09:57:13.992507', '内蒙古', '锡林郭勒', '多伦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b837bd12e81b4f64a05c7ee3e837c99f', '彭松龄', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南娄底双峰；湖南长沙；湖南益阳赫山；湖南益阳；湖南邵阳北塔；湖南邵阳；湖南_邵阳_新宁', '[]', '[]', '抗日战争时期', '', '在日军扶植下组建伪保安部队，配合日军在湖南沦陷区进行治安肃正、搜捕抗日人员。；在长沙沦陷区参与维持会，协助日军征发物资，其活动范围涉及湘中地区。；率伪军盘踞益阳、沅江一带，为日军搜集情报、征发民夫，并参与对洞庭湖区的控制。；在湘中地区组织伪维持会网络，为日军在邵阳、新化等地征调物资、拉夫。', '[]', '2026-09-10 09:57:14.057639', '2026-09-10 09:57:14.057639', '湖南', '娄底', '双峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8422af2d5634bdb8a4c390dfad879a5', '李德盛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治武乡', '[]', '[]', '抗日战争时期', '', '任伪保安队长，率伪军协助日军袭击八路军后方机关，在武乡东部地区烧杀抢掠，杀害抗日军属多名。', '[]', '2026-09-10 09:57:14.024164', '2026-09-10 09:57:14.024164', '山西', '长治', '武乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b84295224c35408fb5771fe6884b4e9a', '李国杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林资源；福建厦门海沧；福建厦门；福建_龙岩；福建_福州_闽侯；福建福州永泰；福建福州；福建福州福清；福建福州；福建福州', '[]', '[]', '抗日战争时期', '', '厦门商界附逆代表，协助日军征购物资、摊派款项，控制厦门及海沧周边经济。；在福州沦陷期间依附日伪，推行奴化教育，协助日军控制学校与宣传机构。；抗战期间附逆，任伪福建省政府委员兼建设厅长，参与日伪在福建的经济掠夺与基础设施控制。；福州地方士绅附逆，组织伪自治会，协助日军推行保甲与物资统制。；福建人，在伪福建省政权中任建设厅厅长，协助日伪进行所谓建设与资源掠夺，为日军在福建的军事与经济控制服务。；福州沦陷期间任伪警察局长，指挥伪警协助日军搜查、逮捕抗日分子，维持日伪统治秩序。；协助日军修建军事设施、公路，为侵略提供后勤支持。；福州商人，日军占领期间任伪福州商会副会长，为日军筹款筹粮，协助经济统制。；福州商人，投靠日军后任伪商会会长，为日军筹集物资，强制商户缴纳捐款，协助日军控制福州经济命脉。；福州商人，福州沦陷期间任伪商会会长，为日军筹款、摊派物资，协助日伪控制福州经济。', '[]', '2026-09-10 09:57:14.061103', '2026-09-10 09:57:14.061103', '福建', '厦门', '海沧', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8439475ad374840936c7db1c2c90477', '陈子昭', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头澄海；广东汕头潮南；广东汕头；广东汕头潮阳；辽宁沈阳大东；广东潮州湘桥', '[]', '[]', '抗日战争时期', '', '在汕头沦陷后出面组织伪商会，为日军筹款筹物，协助经济统制。；推行奴化教育，篡改教材，宣传亲日思想，毒害潮汕青少年。；在潮阳推行日语教育，篡改教材，宣传“大东亚共荣圈”，毒化青少年思想。；在潮汕沦陷区参与伪政权活动，协助日军推行伪化统治，联络地方士绅为日伪服务。', '[]', '2026-09-10 09:57:14.028227', '2026-09-10 09:57:14.028227', '广东', '汕头', '潮南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8508decd7fc4a1b8f7aecb95f0a3d94', '牛文灿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治', '[]', '[]', '抗日战争时期', '', '随日军进行“宣抚”活动，诱骗群众归顺日伪，破坏抗日政权，多次带领日军突袭村庄。', '[]', '2026-09-10 09:57:14.024014', '2026-09-10 09:57:14.024014', '山西', '长治', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8584170ead6437b8605ee0d710b4fcf', '朱经古', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁兖州；广西桂林资源；山东济宁邹城；山东济宁兖州；山东德州；山东潍坊；山东德州；山东济宁；山东聊城；山东枣庄滕州；辽宁沈阳大东；山东济宁金乡；甘肃甘南合作；山东济宁梁山；山东济宁；山东菏泽东明；云南普洱西；山东济宁曲阜；山东济宁；山东聊城；山东菏泽巨野；辽宁沈阳大东；河南商丘；山东临沂河东；山东临沂；山东临沂；山东济宁济宁高；山东济宁；山东菏泽成武；山东济宁泗水；山西阳泉城区；山东聊城茌平；山东聊城；山东菏泽菏泽经开区；山东菏泽；山东济宁微山；山东济宁；山东聊城冠县；辽宁沈阳新民；山东德州陵城；山东德州；山东济宁嘉祥；山东济宁；山东泰安；湖南永州道县；山东济宁鱼台；山东济宁；山东聊城临清；山东聊城；山东菏泽曹县；山东菏泽定陶；山东菏泽；山东济宁任城；山东济宁；山东菏泽牡丹；山东菏泽；山东菏泽单县；山东菏泽郓城；山东菏泽；山东泰安', '[]', '[]', '抗日战争时期', '', '统管山东伪警察，在德州、宁津等地部署伪警力，配合日军扫荡，搜捕抗日人员，实施恐怖统治。；统管山东伪警察，指挥济宁等地伪警搜捕抗日人员，推行保甲连坐。；掌管山东伪警察系统，在聊城、莘县等地建立伪警察所与保甲自卫团，配合日军清乡、搜捕抗日人员。；掌管伪山东警察系统，在聊城、高唐等地建立伪警察所、训练伪警，参与搜捕抗日人员、维持伪统治秩序。；在伪山东省政权中任职，负责鲁西道事务，督导菏泽、郓城等县伪政权建设，推行治安强化运动，配合日军清乡扫荡。；日军侵占曹县后出面组织维持会，后任伪县长，为日军筹粮筹款、维持殖民统治，协助日伪镇压抗日活动。；在伪山东省政权中负责建设事务，为日军掠夺资源、修筑军事设施服务。；菏泽沦陷后出面组织维持会，后任伪菏泽县县长，协助日军建立伪政权、维持治安，推行奴化教育，为日军征发粮食、劳工，镇压当地抗日活动。；旧官僚出身，投敌后任伪鲁西道尹，负责聊城、临清一带的伪政权事务，配合日军统治。；在山东伪政权中任职，参与济宁地区伪化统治，协助日军掠夺物资、镇压抗日力量。；在德州沦陷期间依附日伪，协助摊派物资、控制商民。；成武沦陷后出面组织维持会，后任伪县知事，为日军征粮派款、修筑据点，协助日伪军清乡，镇压当地抗日活动。；日军侵占菏泽后出面组织维持会，出任伪县知事，为日军征粮派款、维持伪秩序，协助日伪统治菏泽地区。；在临沂推行奴化教育，编写亲日教材，组织师生参加日伪宣传活动，毒害青少年。；任伪济宁县知事期间推行保甲连坐，协助日军掠夺物资，镇压济宁城区抗日活动。；日军侵占兖州后出任伪兖州道尹，参与组建伪政权，维持日伪在兖州及周边地区的统治秩序。；山东人，抗战期间任伪山东省合作社联合会会长，协助日军掠夺物资，推行经济统制。；济宁沦陷后出任伪济宁县知事，协助日军建立维持会与伪警察体系，镇压抗日群众，摊派捐税。；济宁沦陷后出面组织维持会，任伪济宁县知事，协助日军维持治安、征粮征丁，镇压当地抗日活动。；组织新民会进行奴化宣传，拉拢青年参加伪军，配合日军经济统制。；日军侵占济宁后任伪济宁道尹，管辖济宁及周边县区，协助日军维持占领秩序、征发民夫与物资。；任伪泰安道尹期间，协助日军维持泰安及周边地区治安，推行保甲连坐。；抗战时期任伪泰安道尹，驻泰安，管辖包括泰安、岱岳一带的伪政权事务，协助日军维持占领区秩序、征发物资。；抗战时期任伪泰安道尹，管辖泰安、新泰等地区，推行伪政，为日军征集物资、劳工，镇压当地抗日活动。；日伪在泰安设立伪道尹公署，朱经古等伪道尹负责泰安及周边地区的伪政权事务，配合日军扫荡、征粮和治安强化运动。；任伪山东省长，推行日军‘治安强化运动’，统辖全省伪政权，包括泰安、东平地区。；作为山东伪政权最高头目，推行日军殖民政策，督令各道县征粮、征兵、清乡，镇压山东抗日军民。；管辖鲁西包括济宁部分地区，为日军筹粮筹款，诱降地方武装，镇压抗日力量。；在伪河南省政府中主管警务，建立和指挥伪警察系统，在商丘、虞城等沦陷县推行保甲连坐、清查抗日人员。；在枣庄、峄县地区推行奴化教育，担任伪中学校长，宣传“大东亚共荣”，毒害青年学生。；在临沂县城及周边地区组织伪警察，配合日军搜查、逮捕抗日分子，维持伪治安。；伪东临道尹，管辖聊城一带，建立伪县政权，征粮征丁。；管辖包括邹县在内的伪兖州道，推行保甲连坐，征发劳工，支援日军军事行动。；在山东伪政权中任职，参与推行日军殖民统治政策，涉及济宁地区伪政事务。；在伪山东省政权中掌管教育，推行奴化教育，在包括德州、禹城在内的山东各地学校中灌输亲日思想。；推行奴化教育，在山东包括潍坊地区宣传亲日思想，毒害青年。；在山东推行奴化教育，编写亲日教材，培训伪教员，为日军侵略培养顺民，影响包括聊城、阳谷在内的山东各地。；日军侵占单县后出面组织维持会，后任伪县知事，为日军征粮派款、拉夫修路，协助日军清乡，迫害抗日人员家属。；日军侵占菏泽后出任伪菏泽县知事，协助日军建立维持会与保甲制度，推行奴化教育，为日军征发民夫、粮食，参与清乡活动。；日军侵占菏泽后出任伪县知事，主持伪政权，推行保甲制度，征粮征夫，协助日军统治。；在巨野推行奴化教育，篡改教材，宣传“大东亚共荣”，毒化青少年。；推行奴化教育，强制学校使用日伪教材，宣扬东亚共荣。；任伪临沂道尹，管辖临沂及周边县伪政权，配合日军进行治安强化运动，镇压抗日活动。；日伪时期在济宁地区任职，负责伪政权地方行政，协助日军维持济宁及周边地区统治。；投靠日军，历任伪山东省政府要职及伪鲁西道尹，负责鲁西地区伪政权建设，为日军筹措军需、推行奴化教育，镇压抗日活动。', '[]', '2026-09-10 09:57:14.012368', '2026-09-10 09:57:14.012368', '山东', '临沂', '河东', NULL, NULL, NULL, NULL, '');
