INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8af3b361c124955b912f97b7c17b660', '王永江', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；广西桂林资源；辽宁_大连_普兰店；辽宁葫芦岛绥中；黑龙江绥化北林；辽宁葫芦岛；辽宁锦州北镇；吉林松原松原经开区；吉林松原扶余；辽宁阜新海州；江苏连云港海州；辽宁大连沙河口；辽宁盘锦兴隆台；辽宁鞍山岫岩；河北秦皇岛山海关；河北秦皇岛；辽宁营口鲅鱼圈；辽宁辽阳；辽宁鞍山铁东；辽宁鞍山；辽宁盘锦盘山；辽宁；吉林舒兰；吉林；辽宁_沈阳_浑南；河北承德鹰手营子矿；黑龙江_黑河_北安；辽宁大连瓦房店；辽宁大连；山西太原清徐；辽宁大连金州；吉林、山西、河北、辽宁；辽宁铁岭开原；辽宁铁岭；河北承德隆化；辽宁丹东；辽宁朝阳双塔；辽宁；辽宁_鞍山_岫岩；辽宁鞍山千山；辽宁铁岭；辽宁_大连_庄河；黑龙江哈尔滨；河北承德；吉林高；辽宁辽阳白塔；辽宁辽阳；吉林长春德惠；吉林；辽宁辽阳宏伟；辽宁辽阳；辽宁阜新彰武；辽宁阜新；黑龙江佳木斯；吉林四平；辽宁营口；辽宁本溪；辽宁沈阳；辽宁_大连；辽宁大连；吉林辽源；辽宁锦州；辽宁阜新；黑龙江佳木斯富锦；吉林长春朝阳；辽宁朝阳；辽宁_沈阳_苏家屯；辽宁沈阳辽中；辽宁辽阳太子河；辽宁盘锦双台子；吉林；辽宁大连长海；辽宁大连甘井子；辽宁朝阳；吉林通化；黑龙江佳木斯同江', '[\"注：实际未投敌，但需核实\", \"重名，非汉奸，已排除\", \"注：此为历史人物，非汉奸，故不列入\", \"注：实际未投敌，但被误传，此处不列\", \"子\"]', '[]', '抗日战争时期', '', '伪满四平省（辖今四平、梨树、双辽等地）首任省长，推行粮食“出荷”政策，强征劳工，协助日军“讨伐”抗联。；原地方官僚，投日后任伪满四平街市（今四平市）市长，推行日伪奴化教育，协助日军征粮征税，镇压当地反抗。；在吉林地区宣传“日满亲善”，组织汉奸团体，破坏抗日统一战线。；原土匪武装头目，投日后被委任为东边道（含今辽源、东辽一带）保安司令，多次率伪军袭击抗日游击队，残害百姓。；在吉林、辽源地区组织伪警察，协助日军搜捕抗日志士，镇压民众反抗。……（共涉及58个地区的犯罪记录）；无；在丹东市区推行保甲制度，强制居民领取“良民证”，协助日军镇压抗日活动。；原营口港职员，投日后管理鲅鱼圈港区，为日军运输军需物资，强迫中国工人无偿劳动，克扣口粮。；九一八后参与组织营口地方维持会，迎接日军占领，协助建立伪政权，为日军征粮派款。；在吉林审判抗日志士，判处多起“反满抗日”案件死刑。；已列，但需注意其还负责为日军征收“出荷粮”，导致当地饥荒。；已列，补充其曾贪污抗日捐款。', '[]', '2026-09-10 09:57:13.996916', '2026-09-10 09:57:13.996916', '吉林', '松原', '松原经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8b21067b3924462a47b7ce2ac6829dc', '陈炯明', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东揭阳普宁；广西柳州柳北；广东广州；云南普洱西；广西贵港；广西_贵港_港北；广西_贵港_港南；广西柳州三江；湖南郴州桂东；广东揭阳；广东广州；广东揭阳惠来；广东揭阳；广东_揭阳_榕城；广东汕尾；广东深圳；广东汕尾城区；广东汕尾海丰；广东惠州惠东；山西阳泉城区；广东潮州饶平；广西南宁宾阳；云南普洱西', '[]', '[]', '抗日战争时期', '', '九一八事变后，日本侵略者企图拉拢其出面组织伪政权，陈炯明曾与日方接触，但未正式就任伪职便于1933年病死，其与日方暧昧关系在潮汕地区有历史记载。；无；九一八事变后，日本方面曾拉拢陈炯明，试图让其出面组织伪政权。陈炯明虽未公开就任伪职，但曾与日方接触，其旧部在广东沿海地区活动，与揭阳、惠来一带地方势力有联系。；九一八事变后，日本方面曾试图拉拢陈炯明合作，陈炯明一度与日方接触，但最终未公开就任伪职。其活动范围主要在广东及香港，与揭阳地区有间接关联。；抗日战争初期，日本侵略者曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未正式就任即于1938年病逝，但其与日方接触的传闻在广东地区流传。；九一八事变后，日本方面曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未公开就任，但其旧部与日方有接触。陈炯明为海丰人，海丰与陆河相邻，其活动范围覆盖汕尾地区。；九一八事变后，日本方面曾拉拢其出面组织华南伪政权，陈炯明虽未正式就任伪职，但与其旧部保持联系，被时人视为潜在附逆对象；其活动范围涉及广东及香港，与深圳、盐田一带的旧部有联络。；九一八事变后，日本方面曾试图拉拢其出面组织伪政权，陈炯明虽未公开就任伪职，但与其旧部在广东沿海及深圳、罗湖一带的势力被日军利用，间接为日方渗透提供便利。；在日军支持下组织伪自治会，鼓吹“中日亲善”，协助日军控制惠州城区。；日军侵占贵县期间出面组织维持会，为日军征派粮秣、拉夫，协助维持占领秩序。；日军侵占贵县期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。；日军侵占贵县期间，出面组织伪维持会，协助日军征派粮食、民夫，维持沦陷区秩序。；日军侵占广州后曾试图拉拢其出任伪维持会会长，陈炯明未接受，但日方仍将其列入拟用名单，此事在揭阳及粤东地区有传闻。；日军侵占广州后曾试图拉拢其出任伪职，陈炯明未接受，但因其旧部多附逆，常被列入相关人物讨论。；日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1933年已去世，此说系误传，实际未参与。；日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1938年病逝，未实际附逆。；抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑，仅作为广西伪政权筹组背景提及。；抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑。；日军侵占广州后，曾试图拉拢陈炯明出任伪广西省维持会会长，但陈炯明未就任，此事与广西伪政权筹建有关。；在日军第二次侵占广西期间，组织伪保安队协助日军维持占领区治安，搜捕抗日分子。；虽主要活动于广东，但其伪维持会网络曾向桂东、桂南渗透，与广西邻近地区伪化有关。；海丰籍旧军阀，九一八后拒绝日军拉拢但保持暧昧，1933年病逝，未直接附逆。', '[]', '2026-09-10 09:57:14.027435', '2026-09-10 09:57:14.027435', '广东', '惠州', '惠东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8b881e508e048beaf21b2dc80e7bfc1', '王乾元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '陕西西安周至；云南普洱西；山西吕梁文水；山西忻州静乐；山西忻州五台山风景区；山西忻州五台；山西忻州神池；山西；山西忻州繁峙；山西忻州原平；山西忻州忻府；山西忻州宁武', '[]', '[]', '抗日战争时期', '', '投靠日军，任文水县伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众，破坏中共地下组织。；投靠日军，任伪五台县知事，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。；投靠日军，任保德县维持会会长及伪县长，协助日军建立伪政权，强征民夫，搜刮粮食，镇压抗日群众。；日军侵占原平后出任维持会长，为日军征粮派款，协助建立伪政权，迫害抗日群众。；投靠日军，任宁武县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.020222', '2026-09-10 09:57:14.020222', '山西', '吕梁', '文水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b8bdc6cb8d3e4bed8b821da256b99429', '王在之', NULL, NULL, NULL, NULL, 'exact', 'exact', '中牟', '[]', '[]', '抗日战争时期', '', '伪职：八岗维持会会长（1944年）；罪行：设立伪警察大队，管控渡口，盘查往来人员，堵截抗日人员南北交通', '[]', '2026-09-10 09:57:14.069263', '2026-09-10 09:57:14.069263', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
