INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b910ea83cc474305a2a16f24fed73dd4', '张秀山', NULL, NULL, NULL, NULL, 'exact', 'exact', '沧县', '[]', '[]', '抗日战争时期', '', '伪职：伪沧县警察局长；配合日本宪兵抓捕地下党员、交通员，酷刑迫害被捕人员。；结局：镇反时期公审处决', '[]', '2026-09-10 09:57:14.086569', '2026-09-10 09:57:14.086569', '河北', '沧州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b9148678e78842c6958d0d69f3a8dcb1', '杨澄源', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁离石；山西太原阳曲；云南普洱西；山西；山西忻州岢岚；山西临汾隰县；江苏无锡锡山；山西_太原_晋源；山西临汾；山西临汾曲沃；山西晋中；山西临汾尧都；山西临汾吉县；山西吕梁；山西长治；山西忻州；山西临汾翼城；山西临汾；山西吕梁孝义；山西临汾霍州；山西临汾；山西临汾侯马；山西阳泉矿区；山西运城永济；山西运城', '[]', '[]', '抗日战争时期', '', '任伪临汾警备司令，负责临汾城防及治安，残酷镇压抗日活动，多次组织搜捕地下党员，破坏抗日组织。；在侯马矿区为日军看管煤矿，镇压矿工反抗，强抓劳工送往东北。；任伪晋南道（辖临汾、侯马等县）道尹，推行保甲制度，为日军筹集粮饷，镇压当地抗日武装。；组织维持会为日军筹集粮饷，强征劳役，并告密导致多名地下党员被捕牺牲。；原晋军旅长，投敌后为日军出谋划策，参与策划对尧都区的扫荡。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018427', '2026-09-10 09:57:14.018427', '山西', '临汾', '侯马', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b91fe5a6ec3c438d88ff09446f717468', '高景岳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄正定；河北石家庄；河北石家庄桥西；河北；河北石家庄辛集；河北石家庄正定', '[]', '[]', '抗日战争时期', '', '日军占领初期在桥西组织维持会，为日军带路、指认抗日家属，强征民夫修建工事。；在石家庄为日军搜集情报，策动汉奸活动，协助日军控制华北。；率伪保安团多次参与对正定、获鹿等地的“清剿”，烧毁村庄，杀害抗日武装人员及平民。', '[]', '2026-09-10 09:57:14.043604', '2026-09-10 09:57:14.043604', '河北', '石家庄', '桥西', NULL, NULL, NULL, NULL, '');
