INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b97ee4f2fb7e469b944a822919f82d3b', '林之江', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海虹口；上海黄浦；上海静安；上海长宁；浙江舟山', '[]', '[]', '抗日战争时期', '', '在虹口及周边推行“清乡”，设立封锁线，搜捕抗日游击队和地下党。；指挥伪水警在舟山、嵊泗海域巡逻，协助日军打击海上抗日武装，搜捕地下党员。；在长宁区设有据点，参与绑架和刑讯抗日人士，罪行累累。；指挥伪保安队参与“清乡”，在黄浦区及周边扫荡抗日游击队，屠杀无辜百姓。；负责76号在静安一带的武装行动，参与镇压学生运动和工人罢工。', '[]', '2026-09-10 09:57:13.979296', '2026-09-10 09:57:13.979296', '上海', '长宁', NULL, NULL, NULL, NULL, NULL, '');
