INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('b9d4d278d9084587b56f3b59c7897266', '史贤臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '平定', '[]', '[]', '抗日战争时期', '', '伪职：原我方公安人员，叛变后任阳泉宪兵队特务阳泉日报数...；罪行：1941 大扫荡中投敌；带领日伪军搜捕村干部、地下人员，破坏抗日基层组织，劫掠群众财物。；结局：武工队潜入家中处决阳泉日报数...', '[]', '2026-09-10 09:57:14.071045', '2026-09-10 09:57:14.071045', '山西', '阳泉', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba01ac4b11534b21af98503a6fa558f1', '李伯球', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东肇庆四会；广东肇庆；广东肇庆怀集；广东肇庆；广东梅州五华；广东梅州梅县；广东梅州大埔；广东广州；广东茂名；广东茂名电白；广东梅州梅县；广东肇庆德庆；广东肇庆；广东阳江阳西；广东茂名电白；广东肇庆封开；广东肇庆；广西玉林；广东梅州丰顺；广东汕头；广东茂名茂南；广东茂名；广东云浮新兴；广东云浮；广东_云浮_云安；广东梅州蕉岭；广东汕头；广东肇庆端州；广东肇庆', '[]', '[]', '抗日战争时期', '', '在潮梅地区活动，曾任伪汕头市警察局督察长，后任伪潮梅绥靖公署参议，配合日军清乡，抓捕抗日人士，其活动范围覆盖梅州、蕉岭一带。；统率伪军配合日军在肇庆、高要、四会等地清乡，进攻抗日武装，捕杀抗日人员。；统率伪军配合日军扫荡西江抗日游击队，在肇庆、鼎湖、高要等地设卡征税、抓捕抗日人员。；在汕头及潮梅地区充任伪警察头目，参与搜捕抗日人员，镇压民众抗日活动，其势力范围覆盖梅州丰顺一带。；在伪梅县政权中掌管警察武装，配合日军和伪政权搜捕抗日人士，勒索商户，维持日伪统治秩序。；充任伪警察头目，带领伪警配合日军扫荡肇庆周边乡村，勒索民众，迫害抗日家属。；在云浮县城组织伪维持会，协助日军征粮、派款，并诱迫乡绅附逆。；在日伪控制下出任伪四会县县长，推行伪政令，配合日军清乡、征粮，迫害抗日人员。；日军侵占肇庆期间组织伪维持会，为日军筹粮、派夫，协助建立伪基层政权。；在电白沿海地区组织伪维持会，配合日军登陆与物资掠夺，强迫渔民为日军服务。；组织伪保安大队，配合日军对茂南、茂名地区进行扫荡，烧杀抢掠，残害抗日军民。；在日军占领玉林期间充任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗。；日军第一次侵占肇庆期间，参与组织伪肇庆维持会，为日军筹粮筹款、拉夫修路，并协助日军宣传‘东亚共荣’。；在广东伪军中任职，活动范围涉及阳江、阳春、电白一带，配合日军扫荡抗日游击区。；在伪政权中掌管警察武装，配合日军清乡，搜捕抗日游击队员及爱国人士。；在广州伪政权中任职，参与制定对粤东地区的“治安肃正”计划，配合日军扫荡梅州、大埔一带抗日武装。；在肇庆地区参与伪政权活动，协助日军管理地方事务，推行奴化教育，为日军搜集情报。；在梅县沦陷前后参与组织伪维持会，协助日军维持地方秩序、征发民夫与物资，并诱迫地方士绅附逆。', '[]', '2026-09-10 09:57:14.024903', '2026-09-10 09:57:14.024903', '广东', '云浮', '新兴', NULL, NULL, NULL, NULL, '');
