INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba17739ca60e420dad3c9f4699b986cc', '杨惺华', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西西安长安；江西九江湖口；江西九江；云南普洱西；广西桂林资源；云南普洱西', '[]', '[]', '抗日战争时期', '', '在伪江西省政府掌管财政，为日军筹措军费、推行伪币、掠夺物资，支撑沦陷区殖民经济体系。；江西人，汪伪政权在江西的警务头目，掌管伪警察力量，参与搜捕抗日人员、推行保甲连坐。；任伪江西省警务处长，统管包括九江、湖口在内的伪警察力量，参与清乡与抗日人员搜捕。；江西人，投敌后任伪江西省财政厅长等职，为日军搜刮江西资源。；在汪伪政权中负责宣传，为日军侵略辩护。', '[]', '2026-09-10 09:57:14.037144', '2026-09-10 09:57:14.037144', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba1e755666ce47ffa501bb4722a0174a', '王清翰', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏扬州', '[]', '[]', '抗日战争时期', '', '原孙良诚部师长，投敌后任伪军长，活动于扬州、高邮一带，协助日军推行伪化。', '[]', '2026-09-10 09:57:14.035464', '2026-09-10 09:57:14.035464', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
