INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba21fb835e6b4d69b887b9f2f90e41e5', '陈振', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宣城', '[]', '[]', '抗日战争时期', '', '在宣城沦陷区任伪警察局长，协助日军维持治安、抓捕抗日人员。', '[]', '2026-09-10 09:57:14.007818', '2026-09-10 09:57:14.007818', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba223ea1dee24ad7b0cec530effed843', '陈耀先', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南平顶山舞钢；河南平顶山叶县；河南周口；河南周口沈丘；河南周口鹿邑；河南平顶山平顶山高；河南平顶山；河南南阳方城；河南驻马店；河南驻马店西平；河南驻马店汝南；河南驻马店正阳；河南驻马店泌阳；河南驻马店遂平；河南驻马店驻马店经开区；河南驻马店上蔡；河南郑州；河南周口淮阳；河南商丘永城；河南商丘夏邑；河南漯河舞阳；河南漯河；河南周口；河南周口沈丘；河南平顶山鲁山；河南平顶山；河南平顶山；河南平顶山汝州', '[]', '[]', '抗日战争时期', '', '鹿邑沦陷期间投靠日军，组织维持会并任伪县长，为日军征集粮食、修筑据点，镇压地方抗日活动。；在伪河南省政府中负责教育，推行奴化教育，在郑州、开封等地学校强制使用日伪教材，毒化青年。；任伪郾城县保安大队长，协助日军维持郾城、漯河一带治安，参与抓捕抗日人员。；襄城邻近平顶山地区，日军占领后任伪维持会会长，协助日军维持统治。；在正阳县城组织伪维持会，为日军提供粮秣、情报，协助日军维持豫南占领区秩序。；正阳县人，日军侵占正阳后组织维持会，为日军征发民夫、粮食，协助日军在正阳、确山一带建立据点。；周口商人，抗战期间任伪周口商会会长，为日军筹集物资、摊派款项，协助日军控制周口经济。；宝丰（今属平顶山）沦陷后任维持会会长，为日军筹粮筹款，协助建立伪基层政权。；临汝（今汝州）沦陷后组织维持会，为日军提供情报和物资，协助日军控制临汝地区。；上蔡沦陷后投靠日军，历任维持会会长、伪县长，推行奴化教育，为日军搜刮民财。；在夏邑、永城一带附逆，任伪夏邑县知事，后任伪豫东道尹公署参事，协助日军推行伪化教育、征粮征丁。；1944年日军侵占叶县后，出面组织维持会，为日军筹集物资、拉夫派款，协助日军维持占领区秩序。；郸城地区维持会头目，为日军筹粮筹款，协助日军在郸城、鹿邑、沈丘交界地区建立伪化政权，镇压抗日群众。；1945年日军侵占方城后投敌，任伪方城县警察所所长，带领伪警察配合日军搜查、抓捕抗日人员。；西平沦陷后任维持会长，为日军征粮征丁，协助建立伪政权。；抗战期间投敌，任伪遂平县知事，后任伪豫南道参事，管辖范围邻近泌阳，协助日军征粮征夫。；控制淮阳沦陷区商业，为日军采购军需物资，协助经济封锁，压榨商户和民众。', '[]', '2026-09-10 09:57:14.047104', '2026-09-10 09:57:14.047104', '河南', '南阳', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba226f60c71f4852ae1bd9d7cbbae89c', '李子安', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店驻马店经开区；河南驻马店', '[]', '[]', '抗日战争时期', '', '在西平及驻马店周边地区建立伪警察网络，镇压抗日活动，勒索民众。', '[]', '2026-09-10 09:57:14.049108', '2026-09-10 09:57:14.049108', '河南', '驻马店', '驻马店经开区', NULL, NULL, NULL, NULL, '');
