INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba75458df6444a1cb3e296c291dfb9d2', '吴四宝', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南通；陕西渭南华州；陕西渭南；上海奉贤；广西桂林灵川；上海普陀；浙江舟山普陀；上海长宁；安徽安庆桐城；安徽安庆；浙江宁波；重庆万州；上海嘉定；浙江衢州开化；浙江衢州；重庆_合川；江苏南通；江苏南京江宁；江苏南京浦口；上海杨浦；江苏南京浦口；江苏南京', '[\"吴世宝\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：76 号警卫总队长，头号行动打手，大肆绑架暗杀。结局：1942 年被日本宪兵毒杀狱中', '[]', '2026-09-10 09:57:13.975320', '2026-09-10 09:57:13.975320', '上海', '嘉定', '桐城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba766430a4124087b030c3a91eaf8438', '张十斤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权', '[]', '[]', '抗日战争时期', '', '报告八路军开会地点，导致会议被袭，3名干部牺牲。', '[]', '2026-09-10 09:57:14.022812', '2026-09-10 09:57:14.022812', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba829acd6da34d8d9b7ce79cb073c06d', '张遐民', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；山西吕梁石楼；山西吕梁；内蒙古鄂尔多斯；重庆沙坪坝；山西朔州朔城；山西朔州', '[]', '[]', '抗日战争时期', '', '在吕梁地区担任伪职，协助日军建立维持会、保甲制度，征发粮食和劳工，配合日军对石楼、中阳、离石一带的扫荡。；在包头及绥西地区为日伪政权服务，参与经济掠夺与物资统制，其管辖范围与鄂尔多斯北部相邻并产生影响。；在东胜（今鄂尔多斯市东胜区）地区组织维持会，投靠日军，协助日伪在鄂尔多斯中部地区推行统治，维持地方治安。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；任伪雁北道尹，管辖包括朔州在内的雁北地区，为日军征粮、派夫、清乡。', '[]', '2026-09-10 09:57:13.992176', '2026-09-10 09:57:13.992176', '内蒙古', '鄂尔多斯', '鄂托克前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba8ab553fd1943e6a2b27f99c94a0d8d', '成宅西', NULL, NULL, NULL, NULL, 'exact', 'exact', '海宁硖石', '[]', '[]', '抗日战争时期', '', '伪职：继任伪海宁县署长；罪行：接替章学海执掌海宁伪政权，继续推行清乡保甲，强征蚕丝、粮食供给日军。；结局：抗战胜利后逮捕惩处。', '[]', '2026-09-10 09:57:14.086378', '2026-09-10 09:57:14.086378', '浙江', '嘉兴', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba8b61da0aae4923abc536974edf38be', '刘伯勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南益阳', '[]', '[]', '抗日战争时期', '', '益阳资阳地区人，日军侵占期间协助组织维持会，负责摊派粮款、招募伪职人员，为日军提供情报。', '[]', '2026-09-10 09:57:14.059362', '2026-09-10 09:57:14.059362', '湖南', '益阳', '资阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ba8f63077d10410abf32b86bda7a1cba', '高振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北石家庄高邑；云南普洱西；河北保定涞水', '[]', '[]', '抗日战争时期', '', '专门从事特务活动，跟踪、绑架抗日干部，破坏地下交通线，多次带队突袭村庄抓捕“嫌疑分子”。；在西南岩、北渎一带配合日军清乡，烧毁抗日村庄房屋，抢夺牲畜和粮食，抓捕抗日民兵。', '[]', '2026-09-10 09:57:14.041070', '2026-09-10 09:57:14.041070', '河北', '保定', '涞水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('baa3e2cdf9c84ed6aca54ba541347c68', '周赞廷', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆门钟祥；湖北荆门', '[]', '[]', '抗日战争时期', '', '任伪县长期间推行保甲连坐，配合日军清乡，强征民夫修筑荆门至钟祥一带公路据点。', '[]', '2026-09-10 09:57:14.057051', '2026-09-10 09:57:14.057051', '湖北', '荆门', '钟祥', NULL, NULL, NULL, NULL, '');
