INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('baaa90f20fb74dcd98d1b48302ec6b5c', '刘廷栋', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏银川', '[]', '[]', '抗日战争时期', '', '受日伪宣传机构指使，在银川及周边地区组织亲日青年团体，进行奴化宣传，拉拢青年学生赴沦陷区接受训练，为日伪培养后备人员。', '[]', '2026-09-10 09:57:14.003874', '2026-09-10 09:57:14.003874', '宁夏', '银川', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('baaef68669e148e5a19479cb235ed242', '李竹庵', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆垫江', '[]', '[]', '抗日战争时期', '', '日军空袭垫江后，出面组织维持会，协助日军安抚民众、征集物资，并诱使部分士绅附逆。', '[]', '2026-09-10 09:57:14.064136', '2026-09-10 09:57:14.064136', '重庆', '垫江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bab09b55557d466683003b12945fbb6a', '王毓民', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京栖霞；山东临沂临沂高；辽宁沈阳大东；山东临沂平邑；山东日照莒县；山东聊城阳谷；辽宁沈阳新民；山东枣庄滕州；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '推行奴化教育，在临沂各学校强制使用伪教科书，宣传“大东亚共荣”。；在烟台任伪警察局局长，协助日军维持治安，搜捕抗日人士，镇压烟台及栖霞周边地区的抗日活动。；莒县沦陷后充任伪知事，协助日军控制鲁东南，与临沂、平邑周边日伪势力相呼应。；组织新民会进行亲日宣传，拉拢腐蚀民众，搜集抗日情报，协助日军推行保甲连坐。；在枣庄煤矿区为日军管理矿工，组织维持会，协助日军掠夺煤炭资源，压迫矿工。', '[]', '2026-09-10 09:57:14.012567', '2026-09-10 09:57:14.012567', '山东', '临沂', '临沂高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bab73efc80fc4bd4b626053ec813d801', '周法乾', NULL, NULL, NULL, NULL, 'exact', 'exact', '灌云龙苴、新坝一带', '[]', '[]', '抗日战争时期', '', '伪职：伪灌云县保安大队长；罪行：土匪出身投敌；诱杀八路军陇海南进支队团长汤曙红；修筑十余处碉堡，酷刑残害抗日军民；横征暴敛；日本投降后摇身变为国民党边防指挥官继续作恶。；结局：1948 年苏北兵团攻克据点，被击毙抖音百科。', '[]', '2026-09-10 09:57:14.075409', '2026-09-10 09:57:14.075409', '江苏', '连云港', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bab75507ad77483aabb42ed3d2e91d7e', '刘仲虎', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳宜城；湖北襄阳；湖北襄阳南漳；湖北襄阳', '[]', '[]', '抗日战争时期', '', '在襄阳地区附逆，参与伪政权事务，协助日军推行保甲、征粮等殖民统治措施。；襄阳沦陷后组织伪维持会，为日军筹粮筹款、维持地方秩序，协助日军推行保甲连坐，镇压抗日群众。', '[]', '2026-09-10 09:57:14.057165', '2026-09-10 09:57:14.057165', '湖北', '襄阳', '南漳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('babd78a9573146a8b4a0dd860f3ebd67', '王银海', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁武', '[]', '[]', '抗日战争时期', '', '伪职：伪宁武警备大队长；罪行：盘踞宁武城、东寨据点，下乡清乡扫荡。；结局：解放后公审枪决', '[]', '2026-09-10 09:57:14.069849', '2026-09-10 09:57:14.069849', '山西', '忻州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bac7f6e92ed24122b1f5eab0a23a64bf', '马文焕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治武乡；河北石家庄栾城；河北邢台邢台经开区；辽宁沈阳大东；山西长治黎城；河北邢台平乡；北京延庆；河北衡水桃城；河北衡水；北京、山西、河北；山西运城盐湖；河北石家庄晋州；辽宁沈阳新民；河北石家庄行唐；河北保定安国；河北邢台隆尧', '[]', '[]', '抗日战争时期', '', '在延庆各小学推行日语教育，强迫学生唱日本国歌，检举有抗日思想的教师，导致多名教师被捕。；为日军进行奴化宣传，强迫民众参加“中日亲善”集会，破坏抗日舆论，诱骗青年为日军效力。；负责新民会在武乡的宣传活动，鼓吹‘中日亲善’，诱骗青年参加伪军，并收集抗日情报供日军。；强迫村民修建碉堡，向日军献粮，并告密杀害地下党员。；继任伪县长后，继续推行日军‘三光政策’，组织伪军配合日军扫荡，并强迫青年加入伪军。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.994129', '2026-09-10 09:57:13.994129', '北京', '延庆', '盐湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('baca3e65afda4787ba0f41551fb5dc3d', '业喜海顺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古兴安阿尔山；内蒙古赤峰翁牛特旗；内蒙古乌海乌达；内蒙古兴安扎赉特旗；内蒙古赤峰巴林右旗；内蒙古乌海乌达', '[]', '[]', '抗日战争时期', '', '投靠日伪，在兴安南省（阿尔山一带）任参事官，协助日军推行“治安肃正”，迫害当地抗日群众。', '[]', '2026-09-10 09:57:13.987614', '2026-09-10 09:57:13.987614', '内蒙古', '兴安', '扎赉特旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bad51a2bd3534d8f88744d6ae69faa05', '严明', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪南通特别区公署署长（清乡时期，相当于伪县长），执行张北生清乡政令，编组伪区乡政权。。结局：抗战胜利判处死刑', '[]', '2026-09-10 09:57:14.075366', '2026-09-10 09:57:14.075366', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
