INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb0c5fea9d4e4ea2ba57543a6814b0b4', '贡布扎布', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古；鄂托克旗；内蒙古鄂尔多斯乌审旗；内蒙古呼伦贝尔新巴尔虎左旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔；内蒙古鄂尔多斯；四川南充南部', '[]', '[]', '抗日战争时期', '', '伪职：伪旗协理，受伪伊盟公署遥控；秘密和包头特务机关联络，企图煽动旗内王公投日，因旗内上层抵制，未能建立正式伪政权。；结局：战后管制判刑；率伪保安队配合日军“扫荡”札萨克旗南部，抓捕并杀害抗日地下交通员。；为日军及伪蒙疆政府担任翻译，刺探中共伊克昭盟工委及陕北根据地的军事动向，多次引导日军袭击乌审旗边境的抗日武装。', '[]', '2026-09-10 09:57:13.988459', '2026-09-10 09:57:13.988459', '内蒙古', '呼伦贝尔', '扎赉诺尔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb1116e1ffe94a7cb8618bfc62f78f29', '张敬斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪威县县长；推行保甲连坐，制造多起抓捕惨案。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.085475', '2026-09-10 09:57:14.085475', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb15f70154174e92bc13b372717109c1', '甘珠尔扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古赤峰阿鲁科尔沁旗；内蒙古兴安科尔沁右翼前旗；内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔；内蒙古锡林郭勒正镶白旗；黑龙江鹤岗兴安；吉林白城通榆；内蒙古赤峰林西；内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔；内蒙古兴安阿尔山；内蒙古呼伦贝尔鄂伦春自治旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔；内蒙古呼伦贝尔新巴尔虎左旗；内蒙古通辽扎鲁特旗；内蒙古通辽；内蒙古通辽开鲁；内蒙古通辽；内蒙古赤峰喀喇沁旗；内蒙古赤峰；内蒙古乌海乌达；内蒙古锡林郭勒锡林浩特；云南红河蒙自；内蒙古通辽；黑龙江鹤岗兴安；内蒙古通辽奈曼旗；辽宁彰武；内蒙古科尔沁；内蒙古通辽科尔沁左翼中旗；内蒙古呼伦贝尔牙克石；内蒙古呼伦贝尔；内蒙古通辽科尔沁左翼中旗；内蒙古通辽科尔沁左翼后旗；内蒙古赤峰巴林右旗；内蒙古兴安科尔沁右翼中旗；内蒙古赤峰巴林左旗；内蒙古乌海乌达；内蒙古兴安突泉；内蒙古呼伦贝尔新巴尔虎右旗；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '汪伪政权', '日本关东军扶植的蒙古族汉奸，参与组建伪兴安军，在兴安、阿尔山一带协助日军维持治安，围剿抗日武装。；蒙古族投日分子，参与组建伪兴安军，镇压抗日力量，协助日军统治通辽地区。；蒙古族贵族出身，投靠日本关东军，参与组建伪兴安军，在通辽、奈曼旗一带镇压抗日武装，协助日军推行“治安肃正”计划。；科尔沁左翼中旗人，蒙古族。九一八事变后投靠日本关东军，参与组建伪兴安军，任伪兴安南省省长，协助日军镇压蒙古族抗日武装，推行奴化教育，强征劳工，为日军提供物资和情报。；伪职：伪兴安南警备军司令官、伪第九军管区中将司令官，司令部驻通辽；指挥兴安骑兵多次赴热河、冀东讨伐抗日武装，制造大量惨案，推行奴化教育，为日军搜集粮草马匹抖音百科。；结局：1945 被俘，关押改造，1966 年特赦释放；伪任职务：伪满第九军管区中将司令，东蒙伪满高级将领，镇压抗日武装。结局：抚顺战犯管理所关押，1966 年特赦释放', '[]', '2026-09-10 09:57:13.987731', '2026-09-10 09:57:13.987731', '内蒙古', '兴安', '突泉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb23120569844cedac5ccc8a1b24cf43', '艾贵海', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（特务汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：特务汉奸；罪行：特务汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.075835', '2026-09-10 09:57:14.075835', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb2321e8e7104fcbaaa8b49b65fb87a3', '张亮宏', NULL, NULL, NULL, NULL, 'exact', 'exact', '淮阳县', '[]', '[]', '抗日战争时期', '', '伪职：淮阳西北大地主、汉奸头目；罪行：淮阳西北有名的大地主，把女儿嫁给日本人。手下有汉奸100多人，盘踞双楼寨据点。群众编顺口溜：“张老亮，张亮宏，投靠日寇罪无穷，他是鬼子的老丈人，专门欺压老百姓”。经常出来抓人、抢东西；结局：1939年农历正月初九，薛朴若、王其梅率游击队夜袭双楼寨，张亮宏钻红薯窖逃脱；1939年农历正月廿三，率残部100余人配合日军扫荡薛孟庄，烧毁400多间房屋', '[]', '2026-09-10 09:57:14.074896', '2026-09-10 09:57:14.074896', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb2395524b1c40e6a5300a31413fc976', '宁国才', NULL, NULL, NULL, NULL, 'exact', 'exact', '安达宋站（今大庆管辖）', '[]', '[]', '抗日战争时期', '', '伪职：伪保长，大地主；罪行：效忠日伪，向日军通风报信抗联行踪；抗联经过时扣押群众，因 “效忠” 被日军公开表彰发奖章，迫害接济抗联百姓。；结局：解放后反奸清算被惩处。', '[]', '2026-09-10 09:57:14.067640', '2026-09-10 09:57:14.067640', '黑龙江', '大庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb23f07893a7419196d9faa1a768a2c5', '袁履登', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波；上海杨浦；河南郑州中牟；上海浦东', '[]', '[]', '抗日战争时期', '', '控制杨浦地区工商界，为日军征用工厂物资，强迫工人为日军生产。；强迫商户向日军缴纳“慰劳金”，组织商人向日军提供粮食、棉布等战略物资，从中牟利。；宁波沦陷后出任伪维持会会长，协助日军推行“治安强化”运动，强征粮食和劳工，迫害抗日家属。；宁波沦陷后出任伪维持会会长，后任伪鄞县县长，为日军征粮派款，协助推行保甲制度。；宁波沦陷后出任伪维持会会长，后任伪鄞县县长，为日军征收粮饷、推行保甲制度，镇压抗日活动。；宁波商人，投靠日军，任伪商会会长，为日军筹集军饷，垄断粮食贸易。；为日伪在浦东征粮、筹款，控制商业，为日军提供物资。', '[]', '2026-09-10 09:57:13.977204', '2026-09-10 09:57:13.977204', '上海', '杨浦', '慈溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb273245460b4bbf937d658f7a3a1c35', '李盛唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州铜山；江苏徐州；江苏徐州睢宁', '[]', '[]', '抗日战争时期', '', '任伪铜山县保安大队长，率伪军配合日军清乡、扫荡，杀害抗日军民，强征壮丁，为日军提供情报。；在睢宁地区建立伪政权，强征壮丁补充伪军，多次向日军报告新四军活动情报，导致抗日武装遭受损失。', '[]', '2026-09-10 09:57:14.035076', '2026-09-10 09:57:14.035076', '江苏', '徐州', '铜山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb3197a052aa403f83ada9316ad6245d', '王仲槐', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆垫江', '[]', '[]', '抗日战争时期', '', '在垫江及邻县边界地区建立伪警察网络，登记户口、发放良民证，镇压抗日宣传活动。', '[]', '2026-09-10 09:57:14.064152', '2026-09-10 09:57:14.064152', '重庆', '垫江', NULL, NULL, NULL, NULL, NULL, '');
