INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb53cc42c6a242e7b9777859ccd535c6', '王云五', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳雁峰；湖南衡阳；湖南衡阳', '[]', '[]', '抗日战争时期', '', '衡阳沦陷后出面组织伪商会，为日军筹款筹粮，协助经济控制。；衡阳商界人物，沦陷后参加伪维持会，为日军筹款筹粮，协助控制衡阳商业与物资。；衡阳沦陷期间以商会名义为日军筹款筹粮，参与维持会活动。', '[]', '2026-09-10 09:57:14.059565', '2026-09-10 09:57:14.059565', '湖南', '衡阳', '衡东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb53e737265146d3b02c277ec692ed24', '张若柏', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆州松滋；湖北荆门；湖北武汉；吉林高；湖北武汉；湖北宜昌宜都；湖北宜昌；湖北襄阳；武汉（伪湖北省）；湖北武汉江夏；湖北孝感；湖北武汉江岸；湖北宜昌', '[]', '[]', '抗日战争时期', '', '伪职：伪湖北省政府秘书长；罪行：何佩瑢任伪省长时的秘书长', '[]', '2026-09-10 09:57:14.055910', '2026-09-10 09:57:14.055910', '湖北', '宜昌', '宜都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb54edf761674ca1a777b5f0390275aa', '彭泰荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川（同善社总道首，势力渗透贵州）', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：同善社总头目，接受汪伪暗中资助，布置黔湘川地下暴动，派遣骨干潜入黔东发展组织，计划响应日军西进，在贵州发展大量道徒。。结局：抗战胜利后被捕，判处徒刑', '[]', '2026-09-10 09:57:14.081083', '2026-09-10 09:57:14.081083', '四川', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb6165266372466d843e39d635166e1e', '池宗墨', NULL, NULL, NULL, NULL, 'exact', 'exact', '北京石景山；广西桂林资源；河北唐山；河北_唐山_唐山高；北京大兴；天津北辰；北京_东城；北京平谷；北京_西城；天津宝坻；天津_蓟州；河北唐山玉田；河北唐山；河北廊坊香河；河北秦皇岛抚宁；重庆_大足；陕西_西安_长安；河北秦皇岛；河北唐山；河北_唐山_路南；北京顺义；河北唐山；河北_唐山_唐山海港经开区；河北_唐山_迁西；北京延庆；河北张家口尚义；天津河北；青海黄南河南；河南开封；天津武清；河北秦皇岛昌黎；北京昌平；吉林长春朝阳；天津河北；河北唐山；河北秦皇岛；河北廊坊；河北唐山；河北廊坊大厂；江苏南通通州；重庆_永川；天津宁河；北京丰台；北京门头沟；陕西西安莲湖；陕西_西安_高陵；北京、天津、河北；天津_和平；浙江平阳；云南普洱西；天津_河北；河北_秦皇岛；河北_秦皇岛_海港；北京_通州；河北唐山；北京密云', '[]', '[]', '抗日战争时期', '', '协助殷汝耕管理伪冀东政权，参与对北平东部地区的殖民统治和物资掠夺。；殷汝耕亲信，后任伪北平警察局长，在丰台地区协助日军维持治安，镇压抗日民众。；协助殷汝耕建立伪冀东政权，后在北平参与伪市政管理，迫害抗日人士。；殷汝耕心腹，参与冀东伪政权，后转任北平伪职，协助日军管理大兴等县行政，强征民夫和粮食。；任伪北平市长期间，推行日伪法令，强征民夫物资，协助日军维持占领秩序，镇压抗日活动。……（共涉及74个地区的犯罪记录）；伪职：伪冀东防共自治政府秘书长、行政长官（通州事变后），驻唐山，对日屈膝认罪赔款，修建日军慰灵塔，主导冀东伪政务。；结局：抗战胜利南京判处死刑执行', '[]', '2026-09-10 09:57:13.992660', '2026-09-10 09:57:13.992660', '天津', '宁河', '大厂', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb65957cf5d64b07a33c89171de47c73', '陆翥双', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪吴县县长，配合清乡运动，下乡摊派苛捐。。结局：战后逮捕，判处重刑关押苏州市地方...', '[]', '2026-09-10 09:57:14.087608', '2026-09-10 09:57:14.087608', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
