INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb72bbb9be664960973da149d3f3ecde', '王孝英', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建三明清流；福建三明；福建福州闽清；福建宁德蕉城；福建福州；福建厦门；福建南平；福建莆田；福建龙岩漳平；福建厦门；福建泉州惠安；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '出任伪莆田县警察局长，统领伪警察配合日军维持治安，搜捕抗日人士，勒索百姓，为日军提供情报。；泉州本地妇女界附逆者，组织伪妇女会，为日军宣传“大东亚共荣”，动员妇女参与伪后勤，活动涉及惠安。；厦门沦陷后参与维持会及伪政权活动，为日军在闽南地区的统治服务。；南平本地人，日军侵扰南平期间组织伪维持会，为日军筹粮、带路，协助维持伪秩序，压迫当地民众。；在厦门沦陷区掌管伪警察，镇压抗日分子，其情报网络覆盖漳州、漳浦沿海，多次配合日军搜捕抗日志士。；福州沦陷期间参与伪维持会活动，负责妇女宣传与慰劳日军，协助推行奴化教育。；闽清县附逆人物，日军侵扰闽清期间组织维持会，为日军派款派粮、维持伪秩序。；三明地区沦陷期间组织伪维持会，为日军提供情报、粮食和劳工，协助日军控制三明一带，镇压当地抗日活动。', '[]', '2026-09-10 09:57:14.060377', '2026-09-10 09:57:14.060377', '福建', '三明', '清流', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bb794262711e436fb33c87680a1a3968', '曹汝霖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北；北京昌平；天津滨海；湖南常德津；北京东城；北京_西城；山东_济宁_微山；河北廊坊；天津河北；河北廊坊固安；河北廊坊；天津和平；湖南常德津；天津北辰；湖南常德津；北京海淀', '[]', '[]', '抗日战争时期', '', '北洋时期政客，北平沦陷后接受伪职，虽未直接掌权，但利用旧关系为日伪政权笼络人心。；原亲日政客，虽未任实职，但为日伪在北平及昌平的活动提供政治支持。；虽未任实职，但在北平与日伪高层往来，为日伪政权提供政治咨询，影响海淀地区亲日势力；北洋政客，投靠日伪，为伪政权出谋划策。；虽为咨询委员，但多次在天津活动，利用旧关系为日伪拉拢社会人士。……（共涉及10个地区的犯罪记录）；虽无实权，但作为汉奸头面人物，为日伪在华北（含廊坊）统治提供政治支持。', '[]', '2026-09-10 09:57:13.992902', '2026-09-10 09:57:13.992902', '北京', '东城', '微山', NULL, NULL, NULL, NULL, '');
