INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bbed8567d48449c3907b3ea9b41073af', '余传忠', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西瑞昌；瑞昌县（今瑞昌市）', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪瑞昌县县长、伪保安总队长，多次带路扫荡，屠杀抗日军民。结局：1945 年日本投降后被诱捕捕杀；伪职：伪瑞昌保安总队长兼伪瑞昌县长；罪行：瑞昌南义东升村七里冲人，1940年8月带特务队投靠日军，从伪保安队长逐步升至伪保安总队长兼县长，配合日军扫荡、杀害赣北游击队分队长夏明和等抗日人员，祸害瑞昌及周边地区，日军九江司令官奉调回国时专程向其辞别；结局：1945年农历十一月十二日在横港被其妹夫设计诱捕杀死，时年35岁（来源：瑞昌臭名昭著的铁杆汉奸，是赣北地区级别最高的县级汉奸之一）；伪职：伪保安总队长、伪瑞昌县长；罪行：1940年投敌，任伪保安总队长、伪瑞昌县长，多次带领伪军扫荡赣北，屠杀大量抗日军民和平民；来源：瑞昌地方抗战史料；备注：赣北臭名昭著铁杆汉奸', '[]', '2026-09-10 09:57:14.075947', '2026-09-10 09:57:14.075947', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bbf5b1cc997e4df9a5b82360e506a353', '吕老贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '蔚县', '[]', '[]', '抗日战争时期', '', '伪职：伪蔚县警备大队长；伪军铁杆，充当日军扫荡向导，残害山区百姓。；结局：镇反公审枪决', '[]', '2026-09-10 09:57:14.080038', '2026-09-10 09:57:14.080038', '河北', '张家口', NULL, NULL, NULL, NULL, NULL, '');
