INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc57bb0ce31a4ca980ca348d672fb7ec', '董九吉', NULL, NULL, NULL, NULL, 'exact', 'exact', '怀来桑园', '[]', '[]', '抗日战争时期', '', '伪职：联庄会头目，后投敌；制造桑矾救国会惨案，杀害我方干部，逮捕大批救国会人员送交日军，严重破坏宣涿怀根据地。；结局：怀来解放后公审枪决', '[]', '2026-09-10 09:57:14.067971', '2026-09-10 09:57:14.067971', '河北', '张家口', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc5e088b6b494876b9e2db43a7453ff2', '林树森', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南陵水；内蒙古乌海海南；海南昌江；江西景德镇昌江；海南三亚崖州；海南三亚；海南海口美兰；海南海口；海南万宁；海南琼海；海南保亭；海南屯昌；海南定安；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在文昌、琼海交界地区推行伪化统治，组织伪军协助日军扫荡。；充任伪警察头目，带领伪警配合日军下乡扫荡，抓捕抗日群众和游击队员。；组织伪军武装，配合日军对昌江及周边抗日根据地进行扫荡，抓捕抗日军民，抢掠物资。；统率伪警察配合日军搜捕抗日人员，审讯、拷打被捕群众，参与万宁县城及周边据点的治安强化运动。；海南岛伪政权高层成员，参与制定日伪在琼崖地区的统治政策，协助日军镇压抗日力量。；率伪军配合日军扫荡保亭抗日根据地，多次参与屠杀和逮捕抗日群众。；率伪军配合日军对海口、美兰周边乡村进行扫荡，烧杀抢掠。；在崖县及三亚一带协助日军征派粮食、民夫，参与维持日伪基层统治。；海南伪政权要员，参与制定伪政策，协助日军在海南各县包括陵水推行殖民统治。', '[]', '2026-09-10 09:57:14.052820', '2026-09-10 09:57:14.052820', '海南', '万宁', '崖州', NULL, NULL, NULL, NULL, '');
