INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc75af50634c46d6821a1d54fd916739', '黄子英', NULL, NULL, NULL, NULL, 'exact', 'exact', '咸宁县（今咸安区）', '[]', '[]', '抗日战争时期', '', '伪职：柏墩维持会会长；罪行：担任具有汉奸性质的维持会长，但具有强烈的爱国思想，暗中参与抗日。1942年9月，曾秘密将患病的咸崇蒲中心县委书记罗通接到自己家中养病，请当地中医为其治疗；结局：待考（因暗中抗日，与一般铁杆汉奸有区别）', '[]', '2026-09-10 09:57:14.070731', '2026-09-10 09:57:14.070731', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc77a0d0d976400e8a975751eca9638d', '周伯衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽宿州灵璧', '[]', '[]', '抗日战争时期', '', '任伪宿县知事期间推行保甲连坐，配合日军清乡，镇压抗日群众。', '[]', '2026-09-10 09:57:14.008392', '2026-09-10 09:57:14.008392', '安徽', '宿州', '灵璧', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc7812ea66f841e297d2a7163c168bbc', '杨继业', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州宁武；山西太原', '[]', '[]', '抗日战争时期', '', '在太原伪省公署任职，参与策划对晋北抗日根据地的经济封锁，为日军筹集军需物资。', '[]', '2026-09-10 09:57:14.021881', '2026-09-10 09:57:14.021881', '山西', '忻州', '宁武', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc78d36cf37b400dbfe0c84f20f3a6d0', '王璧', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西长子；长子', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪长子县知事、维持会会长，征粮抓夫，修筑据点炮楼。结局：镇反期间公审枪决；伪职：伪长子县首任知事、维持会会长；罪行：地方士绅主动迎敌，组建维持会，建立保甲，征粮抓夫，协助修筑炮楼据点。；结局：镇反期间处决', '[]', '2026-09-10 09:57:14.071172', '2026-09-10 09:57:14.071172', '山西', '长治', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc7ba0e8b4db4bf497f6081bd24a972b', '旺楚克拉布丹', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古鄂尔多斯；内蒙古鄂尔多斯准格尔旗', '[]', '[]', '抗日战争时期', '', '为准格尔旗日军据点提供情报，协助伪军强征民夫修筑工事，迫害倾向抗日的蒙古族青年。', '[]', '2026-09-10 09:57:13.992029', '2026-09-10 09:57:13.992029', '内蒙古', '鄂尔多斯', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc7e262057d34549af8b201f8e9b2c6a', '潘干臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽阜阳；湖北_咸宁_通山；江苏连云港灌云；江苏淮安；安徽淮北相山；江苏连云港；江苏泰州；安徽安庆；江苏徐州；江苏扬州宝应；海南澄迈；广东广州；江苏徐州邳州；安徽六安金寨；安徽六安；海南海口；江苏泰州高港；江苏泰州；安徽安庆；江苏_南京_雨花台；江苏南京；江苏泰州兴化；江苏盐城；广西玉林；海南万宁；内蒙古乌海海南；江苏宿迁宿豫；江苏宿迁；江苏徐州睢宁；江苏徐州；江苏扬州广陵；江苏扬州；安徽淮北；江苏淮安涟水；江苏连云港东海；安徽滁州来安；安徽滁州；广西_桂林_灵川；安徽滁州；江苏徐州新沂；江苏徐州；江苏南京六合；江苏淮安淮阴；江苏徐州丰县；江苏徐州；江苏淮安洪泽；海南三沙南沙；江苏淮安淮阴；江苏宿迁；江苏扬州；江苏盐城东台；江苏盐城；江苏扬州高邮；江苏扬州；江苏南通如皋', '[]', '[]', '抗日战争时期', '', '负责伪安徽省内治安，在安庆、大观地区镇压抗日民众。；负责盐城及盐都地区警备，镇压抗日活动，逮捕并杀害多名地下党员。；原李长江部旅长，投敌后任伪师长，驻防扬州东乡，配合日军破坏抗日组织。；在洪泽湖周边地区推行日伪统治，组织伪军配合日军扫荡，镇压抗日军民，征收苛捐杂税，掠夺粮食资源供给日军。；原地方土匪头目，投日后任伪保安大队长，在邗江、扬州近郊设卡勒索，捕杀抗日游击队家属，多次配合日军“清乡”。；率伪保安队驻防扬州城，多次配合日军突袭新四军游击队，杀害地下党员，强征民夫修筑工事。；汪伪政权在安徽北部的重要爪牙，负责伪保安系统，协助日军征粮、清乡，其伪政令波及皖西六安一带。；在广州伪政权指导下赴琼组建伪维持会，澄迈等地伪维持会多受其节制。；在海口及琼山、澄迈一带协助日军管理城市，推行配给制，搜刮物资，参与迫害抗日家属。；在泰州地区指挥伪军多次进攻新四军游击队，在口岸、刁铺等地烧杀抢掠，强抓壮丁补充伪军。；原国民党军将领，投敌后任伪淮海省保安司令等职，属华中伪军头目。；投敌后任伪军师长，在苏皖边界地区配合日军作战，其活动范围接近安庆、桐城。；在江苏北部任伪军头目，配合日军扫荡抗日根据地。；任伪东海县县长期间，积极推行日伪政权，协助日军征粮征税，镇压抗日民众，破坏抗日组织。；任伪灌云县县长期间，积极推行日伪政权，协助日军征粮征税，镇压抗日民众，破坏抗日组织。；任伪灌云县县长期间，积极推行日伪政权，协助日军清乡、征粮、抓捕抗日军民，镇压抗日活动。；在伪淮海省任职，负责保安与警察事务，参与对安徽北部沦陷区的控制与镇压。；在苏北泰州、兴化地区活动，率伪军配合日军进攻新四军，参与伪化政权维持。；在兴化地区组织伪保安队，配合日军扫荡，破坏抗日组织，征收苛捐杂税。；在徐州、睢宁地区推行“清乡”政策，建立伪保甲制度，搜捕抗日地下人员，强征民夫修筑工事。；1939年日军占领淮阴后出任伪县长，协助日军推行“治安强化”运动，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。；投靠日军，任伪淮阴县县长，协助日军推行“治安肃正”，强征粮税，镇压抗日民众，破坏抗日组织。；相山本地劣绅，日军占领后出任维持会长，为日军提供情报，强征民夫修筑工事，霸占民产。；在如皋地区组织伪保安队，抓捕抗日军民，为日军提供情报。；在苏北地区为日军效力；伪军头目，活动于苏皖边区，包括滁州、明光一带，配合日军扫荡抗日根据地，镇压民众反抗。；活动于苏北，与广西玉林无关。；长期盘踞淮阴（今淮安市区），推行保甲制度，强征粮税，协助日军建立据点，镇压抗日游击队。；在连云港地区推行日伪统治，强征劳工，协助日军掠夺盐业和港口资源。；投靠日军，任涟水县伪县长，组织伪政权，协助日军推行“清乡”和“治安强化”运动，镇压抗日民众，征收苛捐杂税，残害抗日家属。；长期盘踞盐城，协助日军建立据点，镇压抗日活动，杀害新四军伤员和进步人士。；原国民党淮阴区保安司令，投敌后盘踞淮阴、淮安，多次进攻新四军根据地，杀害抗日干部。；扬州沦陷后组织维持会，为日军征粮派款，协助建立伪政权；在苏北淮海地区任伪军头目，活动范围包括宿迁、泗阳，参与日军对抗日根据地的扫荡和蚕食。；统管海南伪警察系统，在万宁、陵水等地设立警察分所，指挥搜捕抗日人员，推行治安强化运动。；驻防宿迁、泗阳一带，配合日军扫荡，残害百姓。；在徐州地区（含新沂）主持伪警察系统，镇压抗日地下活动，逮捕并杀害多名抗日志士，协助日军推行保甲制度。；徐州沦陷初期出任维持会会长，后任伪市长，为日军征粮派款，建立伪政权基层机构。；任伪徐州市长期间，推行日伪“治安强化”运动，在泉山地区实施保甲制度，协助日军搜捕抗日分子。；任伪宝应县知事，推行日伪统治，强征粮税，镇压抗日民众，配合日军清乡扫荡。；在扬州地区组织伪保安队，配合日军扫荡，镇压抗日活动，参与屠杀和逮捕抗日群众。；在琼东地区附逆，任伪琼东县县长，建立伪区乡政权，协助日军控制琼东沿海和嘉积一带，参与对抗日根据地的经济封锁和军事扫荡。；在苏皖北部活动，任伪淮海省省长兼伪军师长，其势力范围接近阜阳地区，配合日军统治。；伪军头目，在华中地区配合日军作战，其势力范围涉及湖北周边。；日军占领邳县后率先组织维持会，为日军提供情报，强征劳役，搜刮民财。；驻守淮北地区，多次率伪军袭击抗日根据地，制造“潘圩惨案”等屠杀事件。；任伪淮阴保安司令，率伪军驻守淮阴城，多次参与对淮安、淮阴抗日根据地的“扫荡”，杀害抗日军民。；协助日军管理徐州地区伪政权，参与策划对丰县、沛县等地的军事围剿，迫害抗日家属。；参与策划对盐城、东台地区的军事清剿，协助日军建立伪政权，强征壮丁。；汪伪淮海省伪军头目，其保安部队在安徽北部及滁州、来安一带配合日军进行清乡与扫荡。', '[]', '2026-09-10 09:57:14.005593', '2026-09-10 09:57:14.005593', '安徽', '六安', '金寨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc88bbd322654975ad75a536055d2bd5', '阚维雍', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林恭城', '[]', '[]', '抗日战争时期', '', '桂系将领，坚持抗战，未附逆。', '[]', '2026-09-10 09:57:14.032162', '2026-09-10 09:57:14.032162', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bc97f4faf9ef42b6944d579ca6ec9ff8', '张髯农', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊临朐', '[]', '[]', '抗日战争时期', '', '抗战时期任伪临朐县知事，主持伪县政，配合日军征粮、抓丁、扫荡，镇压抗日群众。', '[]', '2026-09-10 09:57:14.016621', '2026-09-10 09:57:14.016621', '山东', '潍坊', '临朐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bca68d893d304813bad0d72d278068a5', '陈明枢', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南五指山；海南屯昌；海南文昌；海南东方；海南乐东；海南海口秀英；海南海口；海南三沙西沙；海南陵水；海南陵水；海南临高；河南郑州中牟；海南三沙中沙；海南保亭', '[]', '[]', '抗日战争时期', '', '在文昌地区组织维持会，为日军提供物资和情报，协助日军扫荡抗日游击队。；在陵水地区协助日军控制黎族、苗族聚居区，征发物资，参与镇压抗日群众。；统领伪警察协助日军搜捕抗日人员，镇压陵水及周边地区民众抗日活动。；在乐东地区为日军征粮征工，协助日军控制山区，镇压黎族苗族抗日群众。；在崖县地区协助日军统治，参与清乡与物资统制。；控制临高物资流通，为日军采购粮食、橡胶等战略物资，从中牟利并协助经济掠夺。；作为伪政权在海口的办事机构负责人，协调海口、秀英地区伪保甲与日军之间的联络，推行配给与征工。；在保亭地区组织伪政权，协助日军推行殖民统治，征发当地民众。', '[]', '2026-09-10 09:57:14.053383', '2026-09-10 09:57:14.053383', '海南', '三沙', '中沙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcab669a54204b3991d3e0a3fad1c952', '黄克明', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江；广东广州；广东广州从化；广东深圳；广东广州黄埔；吉林高；河南鹤壁鹤山；广东佛山禅城；广东佛山；广东揭阳揭东；广东汕头潮阳；广东江门台山；广东惠州；广东珠海金湾；辽宁沈阳大东；广东江门；广东茂名化州；广东茂名；广东广州；广东广州白云；广东广州；广东惠州龙门；广东惠州；广东_广州_南沙；广东_广州_番禺；广东深圳龙岗；广东深圳；广东河源紫金；广东河源', '[]', '[]', '抗日战争时期', '', '日军占领深圳后组织维持会，为日军征集物资、情报，协助管理地方。；江门沦陷后任伪警察局长，协助日军维持治安，逮捕抗日人士，推行保甲连坐，压迫江门及鹤山周边民众。；从化伪保安大队头目，协助日军清乡、搜捕抗日游击队员。；在河源县城组织伪维持会，协助日军控制河源地区，镇压抗日群众，为日军提供粮食和劳工，直接关联紫金等周边地区。；抗战期间在粤西地区率部投敌，编入伪军，配合日军进攻抗日游击区，活动范围接近茂名、化州。；协助郭卫民指挥伪军，在广州白云山周边及珠江三角洲地区参与对抗日武装的作战。；在宝安（含深圳）地区建立伪警察网络，搜捕东江纵队情报人员。；在潮汕地区参与伪维持会活动，协助日军控制揭阳、潮阳一带。；在日军占领博罗期间任伪县长，与龙门、惠州伪政权配合，推行保甲连坐，协助日军清乡。；在台山教育界附逆，协助日军推行奴化教育，篡改教材，组织师生参加伪政权宣传活动。；伪广东绥靖军头目之一，率部配合日军在广东各地进行扫荡和清乡。；汪伪广东绥靖军高级头目，参与指挥伪军配合日军在广东的军事行动。；在新会、江门地区负责伪警察事务，协助日军维持治安、迫害抗日群众。；在惠州基层推行保甲制度，监视居民言行，向日军举报抗日人员，协助征发劳役。；在佛山、南海一带率领伪保安队随日军下乡清乡，烧杀抢掠，破坏抗日根据地。；在新会、江门一带掌管伪警察，配合日军镇压抗日活动。；为日军搜集广州湾及南路抗日情报，协助抓捕抗日人士。；任伪广东保安司令，指挥伪保安队协助日军控制广东占领区。；统率汪伪广东保安部队，配合日军在广东各地“清乡”、扫荡抗日游击队。；在中山、珠海地区推行奴化教育，协助日伪宣传“大东亚共荣圈”，控制学校与文化机构，属教育文化领域附逆者。', '[]', '2026-09-10 09:57:14.026475', '2026-09-10 09:57:14.026475', '广东', '佛山', '禅城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcb09a6252a740a78476d69981573dbf', '赵子俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南许昌鄢陵；河南许昌；河南信阳；河南许昌；河南漯河临颍；河南漯河；河南南阳；河南驻马店上蔡；河南驻马店；河南焦作马村；辽宁沈阳大东；河南洛阳汝阳；河南驻马店；河南平顶山宝丰；河南漯河郾城；河南漯河舞阳；河南漯河；河南漯河；河南漯河漯河经开区；河南漯河；河南信阳信阳高；辽宁沈阳新民；河南驻马店驿城；河南驻马店；河南信阳罗山；河南信阳；河南焦作；河南许昌魏都；山西阳泉城区；河南驻马店西平；河南驻马店；河南平顶山叶县；河南平顶山；河南信阳新县；河南信阳光山；河南信阳潢川；青海黄南河南', '[]', '[]', '抗日战争时期', '', '宝丰沦陷后投敌，率部配合日军清乡，镇压抗日群众，控制宝丰及周边乡镇。；代表伪河南省府在豫南地区协调各县伪政权，督促向日军供应物资，参与对抗日根据地的经济封锁。；临颍沦陷后任维持会长，为日军征集物资，组织伪自卫团，协助日军控制临颍至漯河交通线。；组织伪保安团，配合日军在郾城及周边地区“清乡”，镇压抗日活动。；在郾城沦陷期间任伪警察局长，配合日军搜捕抗日人员、镇压民众，维持伪治安体系，活动范围覆盖漯河、召陵一带。；在平顶山地区组织伪维持会，为日军搜集情报、征发物资，协助日军控制当地煤矿和交通线。；为日军筹款筹物，强制商户摊派，协助日伪实行经济统制与物资掠夺。；在沁阳（今焦作辖境）任伪职期间，配合日军清乡、征发物资，压迫民众。；驻马店沦陷后组织维持会，投靠日军，负责地方治安、物资征调，协助日军控制驻马店及周边地区。；率部投敌，编为伪保安团，在遂平、驻马店一带配合日军扫荡抗日武装。；在确山、驻马店一带任伪职，配合日军征粮、清乡，参与维持伪政权在豫南的基层统治。；日军侵占郾城后出任伪县知事，在漯河、郾城一带推行伪政，征发物资、登记户口，配合日军统治。；在焦作沦陷区推行奴化教育，组织学校使用伪教材，宣传“中日亲善”“大东亚共荣”，毒害青少年。；在西平及驻马店北部地区组织维持会，协助日军统治，征粮派款，迫害抗日家属。；在伪许昌县政府任职期间，推行奴化教育，强制学校使用日伪教材，向学生灌输亲日思想。；河南南阳宛城人，抗战期间投敌，任伪保甲长，协助日军征粮征丁，监视当地民众，迫害抗日家属。；在许昌城区魏都镇组织维持会，为日军提供情报、粮秣，协助管理居民。；利用新民会进行亲日宣传，拉拢地方士绅附逆，配合日军推行奴化教育与思想控制。；郾城沦陷后任伪维持会会长，配合日军在郾城、漯河一带推行伪化统治，征发民夫、粮食。；日军占领许昌期间任伪警察局局长，协助日军搜捕抗日人员、镇压民众反抗。；任伪信阳道最高行政长官，统辖信阳、罗山等县伪政权，推行日军殖民统治政策，征发劳工、粮食支持日军作战。；1944年日军侵占漯河后，出面组织漯河镇维持会，协助日军管理地方事务、征发物资，是漯河当地直接为日军服务的汉奸头目。；日军侵占汝阳后，带头组织维持会，为日军筹粮筹款、带路扫荡，压迫当地民众。；在潢川组织伪维持会，协助日军控制豫东南交通线，为日军提供情报和物资，参与对邻近光山、新县抗日力量的封锁。', '[]', '2026-09-10 09:57:14.046033', '2026-09-10 09:57:14.046033', '河南', '信阳', '信阳高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcb2fd24f24d4aed96a7aba11c07ae98', '张子廉', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳盐田', '[]', '[]', '抗日战争时期', '', '盐田地区沦陷后出面组织伪盐田维持会，协助日军控制盐田港及周边村落，征粮征工，为日军提供情报，直接涉及盐田地区。', '[]', '2026-09-10 09:57:14.029177', '2026-09-10 09:57:14.029177', '广东', '深圳', '盐田', NULL, NULL, NULL, NULL, '');
