INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcc73e76ce794f7c8984ed77f79059a5', '徐子荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江丽水云和；浙江金华武义；浙江衢州龙游；浙江衢州', '[]', '[]', '抗日战争时期', '', '原国民党地方官员，投敌后任伪衢州绥靖公署参议，参与策划对衢州、龙游地区的“清乡”行动，协助日军搜捕抗日地下人员。；任伪县长期间，推行日伪保甲制度，强征民夫修筑工事，并配合日军“清乡”行动。；为日军征收各种苛捐杂税，强征粮食和铜铁等战略物资，导致当地民生凋敝。', '[]', '2026-09-10 09:57:14.049355', '2026-09-10 09:57:14.049355', '浙江', '丽水', '云和', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcd9841ddc3f4555b2e4c1c6d436ed08', '朱斗文', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海杨浦', '[]', '[]', '抗日战争时期', '', '在杨浦地区开设烟馆，毒害民众，为日伪敛财。', '[]', '2026-09-10 09:57:13.978496', '2026-09-10 09:57:13.978496', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
