INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bceef92797274606b96a6bda8d6b09da', '王锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '高阳；湖北恩施鹤峰；湖北恩施；山西临汾大宁；黑龙江齐齐哈尔；黑龙江黑河北安；河北；河北唐山滦州；河北唐山滦州；内蒙古赤峰巴林左旗；内蒙古赤峰林西', '[\"同名\"]', '[]', '抗日战争时期', '', '在滦州电报局为日军发送密电。；伪职：伪怀安县县长；强征粮秣，管控柴沟堡交通要道，配合日军清乡。；结局：战后逮捕判刑；伪职：伪高阳县县长；管控潴龙河沿线，掠夺棉花粮食资敌。；结局：战后判处长期徒刑；在滦州控制电报通讯，为日军提供情报。', '[]', '2026-09-10 09:57:13.991481', '2026-09-10 09:57:13.991481', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bcf5f927898b4727a055e255b00f5fc9', '陈淡如', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆安庆经开区；安徽安庆；安徽安庆宜秀；安徽安庆；安徽宣城；安徽安庆；安徽安庆潜山；安徽安庆怀宁；安徽安庆宿松；安徽安庆怀宁', '[]', '[]', '抗日战争时期', '', '在安庆沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，维护日伪统治秩序。；安庆沦陷后任伪怀宁县县长，管辖区域包括安庆城区及周边，协助日军征粮、拉夫、维持伪治安。；在汪伪安徽省政府任职，负责安庆地区伪政权事务，推行日伪政策，镇压抗日活动。；汪伪政权委任的宣城县县长，在宣城推行保甲制度，配合日军清乡，镇压抗日群众。；汪伪安徽省政权教育官员，在安庆等沦陷区推行亲日奴化教育，篡改教材，毒害青少年。；安庆沦陷后任伪怀宁县县长，管辖区域包括安庆城区及周边，配合日军推行保甲、征粮与奴化教育。；在汪伪安徽省政权中任职，曾任伪安庆道尹，负责安庆地区日伪行政事务，推行奴化教育。', '[]', '2026-09-10 09:57:14.007418', '2026-09-10 09:57:14.007418', '安徽', '安庆', '安庆经开区', NULL, NULL, NULL, NULL, '');
