INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd1715e1901e40848f816112fc47a3f8', '陈守方', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；湖北宜昌五峰；湖北宜昌；湖北孝感云梦；湖北孝感大悟；湖北孝感；湖北孝感；湖北武汉黄陂；湖北襄阳樊城；湖北咸宁通山；湖北咸宁；湖北武汉青山；湖北武汉汉阳；湖北随州广水；湖北随州随县；湖北孝感孝南；湖北孝感；湖北黄冈团风；湖北黄冈；湖北武汉江夏；山西运城夏县；湖北襄阳；湖北荆州荆州经开区；湖北黄冈龙感湖管理；湖北黄冈；湖北武汉汉南；湖北武汉武昌；湖北武汉汉阳；湖北武汉武昌；湖北_武汉_江汉；湖北武汉武昌；湖北襄阳宜城；湖北襄阳；湖北恩施；湖北武汉黄陂；湖北黄冈英山；湖北武汉新洲；湖北孝感；湖北黄冈红安；湖北黄冈；湖北宜昌；湖北宜昌当阳；湖北黄冈麻城；湖北荆州公安；湖北孝感汉川；湖北孝感应城；湖北武汉硚口；湖北随州随县；湖北黄冈武穴；湖北宜昌秭归；湖北孝感安陆；湖北咸宁嘉鱼；湖北随州曾都；辽宁沈阳大东；湖北宜昌；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '统率伪保安团配合日军在宜昌及周边地区清乡、扫荡，袭击抗日武装，残害民众。；在嘉鱼任伪县长，配合日军在鄂南地区征粮、清乡。；黄冈地区伪军头目，率伪保安大队配合日军对黄冈及龙感湖周边抗日根据地进行扫荡。；麻城人，任伪麻城县保安大队大队长，协助日军维持麻城沦陷区治安，参与清乡与搜捕抗日分子。；宜昌沦陷后投敌，任伪宜昌县警察局局长，协助日军镇压抗日群众，搜捕抗日人员。；宜昌沦陷期间任伪警察局局长，协助日军镇压抗日活动，搜捕抗日人员。；任伪宜昌县警察局局长，协助日军镇压抗日群众、搜捕抗日人员。；任伪宜昌县警察局局长，协助日军维持宜昌城区治安，搜捕抗日人员，镇压民众反抗。；黄冈本地人，任伪警察局长期间，协助日军抓捕抗日志士，推行保甲连坐。；黄冈地区伪警察头目，在黄冈及浠水周边地区搜捕抗日志士，推行保甲连坐，协助日军维持殖民统治。；抗战期间任伪黄冈县警察局局长，协助日军维持治安，镇压抗日活动。；应城与云梦相邻，陈守方任伪应城县县长，配合日军在鄂中地区征粮、清乡，与云梦伪政权有协同行动。；湖北武穴人，抗战期间出任伪武穴维持会会长，协助日军管理地方事务，征敛物资。；任伪枣阳县政府县长，枣阳毗邻襄阳，其伪政权配合日军对襄阳、枣阳地区进行清乡，征发民夫。；在伪武昌市政处警察局任职，协助日军维持武昌地区治安，搜捕抗日人员。；出任伪公安县县长，推行日伪政令，为日军搜刮物资，协助日军清乡，镇压抗日活动。；在孝感、应城一带投敌，任伪县长并掌握伪军，配合日军对鄂中抗日根据地扫荡。；湖北黄安（今红安）人，抗战期间投敌，出任伪黄安县县长，在黄安地区推行伪化统治，协助日军镇压抗日力量。；英山地区投敌分子，组织伪维持会，配合日军对英山及周边地区的控制与扫荡。；控制孝感地区物资配给，为日军收购军粮、棉花等战略物资，盘剥民众。；在应城推行奴化教育，强制学校使用日伪教材，组织青少年参加亲日宣传。；在襄阳地区组织伪保安团，配合日军清乡、扫荡抗日武装。；黄冈本地士绅，日军占领黄冈后出面组织维持会，任会长，协助日军维持地方秩序、征集物资，是黄冈沦陷初期重要附逆者。；武昌沦陷后任维持会会长，后任伪武昌县县长，协助日军控制武昌及周边地区，推行保甲制度。；武昌沦陷后投敌，任伪维持会会长、伪县长，配合日军控制武昌及周边地区。；充任伪保甲长，按日军指令摊派捐税、抓捕壮丁，迫害抗日家属。；日军侵占秭归部分地区后，出面组织伪维持会并任会长，为日军筹粮筹款、提供情报。；投敌后任伪汉阳县维持会会长、伪汉阳县政府县长，在汉阳及硚口邻近地区协助日军征粮征工。；组织伪保安团协助日军守备随县及周边据点，参与对抗日根据地的封锁与扫荡。；樊城沦陷后组织伪维持会，为日军筹粮筹款、拉夫，协助建立伪基层保甲体系。；抗战期间在汉阳组织伪维持会，任会长，协助日军维持占领区秩序。；黄冈人，在伪政权中负责教育，推行日语教学和奴化教育，篡改历史教材，为日军侵略辩护。；在当阳沦陷区组织伪政权，为日军提供情报、物资，协助维持占领。；任伪武昌县县长，在武昌地区推行伪化统治，征粮征丁，配合日军扫荡抗日游击队。；抗战期间投敌，任伪湖北省警务处处长，协助日军维持沦陷区治安、镇压抗日活动。；抗战期间在孝感地区任伪县长，协助日军推行伪化统治，征粮征工，维持地方治安，配合日军对周边抗日力量进行压制。；协助会长刘国钧组织维持会，为日军筹集物资、拉夫派工。；湖北黄冈人，伪黄冈县宣传科科长，主办伪报纸和广播，散布亲日言论，为日军侵略张目。；任伪湖北省政府教育厅厅长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军文化侵略服务。；咸宁沦陷后组织维持会，后任伪咸宁县政府县长，协助日军征粮、征夫，镇压当地抗日活动。；抗战期间出任伪江陵县县长，管辖范围包括今荆州经开区一带，协助日军推行保甲制度、征发劳役。；在随县推行奴化教育，组织学校使用伪教材，宣传“中日亲善”“大东亚共荣”，为日伪培养顺民。；黄陂地区投敌分子，任伪县长，配合日军推行治安强化运动。；黄陂沦陷后组织维持会，为日军带路、征夫、筹粮，协助日军建立伪政权。；抗战期间任伪江夏县县长，在江夏地区推行日伪政策，协助日军征粮、征工，镇压抗日活动。', '[]', '2026-09-10 09:57:14.055450', '2026-09-10 09:57:14.055450', '湖北', '咸宁', '通山', NULL, NULL, NULL, NULL, '');
