INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd69103499be45d38d8b39b36e216e64', '李仲猷', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东广州；广东汕头南澳；广东汕头', '[]', '[]', '抗日战争时期', '', '汪伪广州政权秘书人员，参与伪政令文书工作。；汕头沦陷初期组织伪维持会，为日军筹粮筹款、维持地方秩序，协助建立伪政权。；汕头沦陷后参与组织伪维持会，后任伪汕头市市长，为日军筹粮筹款、推行伪化统治。；汕头沦陷初期组织伪维持会，后任伪市长，为日军筹粮筹款、维持治安，镇压抗日活动。', '[]', '2026-09-10 09:57:14.027105', '2026-09-10 09:57:14.027105', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd72cba6cd2448ddae7cf0b707fd2838', '伪玉山县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西上饶玉山', '[]', '[]', '抗日战争时期', '', '玉山沦陷后伪维持会配合日军维持浙赣边界治安。', '[]', '2026-09-10 09:57:14.038464', '2026-09-10 09:57:14.038464', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd74bb726f4f49159125af662f1bf126', '赵秉钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉；山西；山西阳泉盂县；山西阳泉平定；山西阳泉', '[]', '[]', '抗日战争时期', '', '在阳泉地区设立多处伪警察所，严查抗日物资流通，多次带队突袭抗日秘密联络点，逮捕并刑讯抗日志士。；在阳泉煤矿为日军镇压矿工罢工，抓捕抗日工人，并协助日军掠夺煤炭资源。；日军占领盂县后出任维持会长，为日军征粮派款，提供情报，迫害抗日家属。', '[]', '2026-09-10 09:57:14.024533', '2026-09-10 09:57:14.024533', '山西', '阳泉', '平定', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd752974ce5940adabf0a1c67290acd3', '刘锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东潍坊临朐；河北廊坊文安；河北沧州沧州渤海；河北邢台信都；河北；河北_唐山_唐山汉沽管理；河北秦皇岛；河北唐山唐山海港经开区；河北廊坊大城', '[]', '[]', '抗日战争时期', '', '管理汉沽盐场，将大量食盐低价供给日军，禁止民间私盐，导致当地百姓食盐困难，并镇压盐工反抗。；为日军宪兵队充当翻译，参与刑讯逼供抗日志士，罪行累累。；任伪大城县警备队队长，长期在县境及周边（含廊坊南部）执行日军命令，参与多次“扫荡”，杀害抗日军民数十人。；率伪警备队多次袭击文安抗日游击队，杀害多名抗日群众。；推行日伪“治安强化”运动，组织汉奸团体，迫害进步人士。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.016758', '2026-09-10 09:57:14.016758', '山东', '潍坊', '临朐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd77cee2a11a4c66af25939149d41905', '安厚斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '香河岭子村', '[]', '[]', '抗日战争时期', '', '伪职：香河事变伪代理县长；依附日寇，参与香河自治闹剧。；结局：战后判刑管制香河方志', '[]', '2026-09-10 09:57:14.077488', '2026-09-10 09:57:14.077488', '河北', '廊坊', NULL, NULL, NULL, NULL, NULL, '');
