INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bd853dc9a6af462ebcaa6223d98e805a', '冯静安', NULL, NULL, NULL, NULL, 'exact', 'exact', '原籍黄梅，活动湖口；彭泽县（今属九江）', '[]', '[]', '抗日战争时期', '', '伪职：伪建设科长；罪行：伪湖口县政府建设科长，负责日伪地方工程事务；来源：抗日战争纪念网；备注：湖口伪政权文职人员；伪职：伪彭泽县政府建设科科长；罪行：黄梅人，为日军征发劳役、修建军事设施、维护日占区交通工事；结局：史料未明确记载其最终结局（来源：彭泽伪政府核心官员）', '[]', '2026-09-10 09:57:14.073616', '2026-09-10 09:57:14.073616', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
