INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('be7ce2651d08474c9dd0e873c452b654', '吉兴', NULL, NULL, NULL, NULL, 'exact', 'exact', '北京大兴；黑龙江哈尔滨尚志；黑龙江哈尔滨；辽宁鞍山岫岩；辽宁鞍山；河北承德滦平；河北承德；吉林（满族）；吉林；黑龙江哈尔滨；黑龙江哈尔滨；吉林；吉林长春；吉林长春榆树；吉林长春；吉林长春公主岭；吉林长春；黑龙江齐齐哈尔；吉林、河北、辽宁；辽宁沈阳；吉林长春；吉林延边敦化；吉林；吉林长春；吉林；吉林白城大安；吉林；吉林；黑龙江牡丹江；重庆沙坪坝；黑龙江佳木斯；河北秦皇岛山海关；吉林；吉林四平伊通；吉林', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪第二军管区司令官（吉林），伪满上将；罪行：原东北军，投敌；统领吉林全省伪军，在磐石、桦甸、蛟河、舒兰大规模讨伐抗联，制造集团部落，双手沾满抗联鲜血；后升任伪满尚书府大臣抖音百科。；结局：苏军逮捕，抚顺战犯管理所，1961 年特赦。；伪任职务：伪满第二军管区司令官（驻吉林）、伪尚书府大臣，上将，多次进山讨伐东北抗联抖音百科。结局：苏军俘获，1964 年特赦释放，1969 年去世；原吉林陆军军官，投日后任伪吉林警备司令，协助日军镇压吉林抗日义勇军和抗联。；原吉林陆军军官，投日后任伪满吉林警备军司令，协助日军围剿东北抗日联军，在吉林、四平、伊通一带多次参与“讨伐”行动。；原吉林陆军军官，投日后任伪吉林警备司令，在四平、梨树一带围剿抗日义勇军和抗联部队。；原吉林驻军团长，投敌后任伪警备司令，在舒兰、五常一带多次进攻抗联部队。；在吉林地区指挥伪满军队，配合日军围剿抗日联军，制造多起惨案。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995347', '2026-09-10 09:57:13.995347', '吉林', '延边', '安图', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('be7fb627184c410ba5a5c8a7c1e89d0d', '张铁生', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西宜春袁州；江西萍乡；江西南昌西湖；江西宜春高安；江西宜春；江西吉安安福；江西吉安', '[]', '[]', '抗日战争时期', '', '主办伪报刊与广播，进行亲日宣传，诋毁抗日力量，配合日军思想统制。；受汪伪江西省政府委派，在吉安地区推行“清乡”运动，配合日军封锁抗日根据地，抓捕抗日群众。；率伪保安团在宜春、萍乡、袁州一带配合日军扫荡，烧毁民房，杀害抗日军民。；担任伪保甲长，为日军提供宜春、高安一带抗日武装情报，参与征粮拉夫。', '[]', '2026-09-10 09:57:14.039467', '2026-09-10 09:57:14.039467', '江西', '南昌', '西湖', NULL, NULL, NULL, NULL, '');
