INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bedd30b361904d41a975516c120ddb89', '赵全胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；山西吕梁；山西吕梁岚县；河北邯郸邯郸冀南；河北邯郸肥乡；河北邯郸涉县；河北邯郸武安', '[]', '[]', '抗日战争时期', '', '在岚县组织汉奸情报组，向日军报告八路军动向。；充当日军特务，专门刺探抗日情报，抓捕地下党员，多次破坏抗日交通线。；率伪军多次配合日军‘扫荡’涉县抗日根据地，抓捕抗日干部，抢劫百姓粮食，烧毁村庄。；率皇协军多次进攻冀南抗日根据地，在肥乡、广平一带烧杀抢掠，杀害八路军伤员。', '[]', '2026-09-10 09:57:14.019725', '2026-09-10 09:57:14.019725', '山西', '吕梁', '武安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('beddc19df1d64aecae2e5c9193d14e75', '石连丰', NULL, NULL, NULL, NULL, 'exact', 'exact', '固安', '[]', '[]', '抗日战争时期', '', '伪职：伪后备队队长；配合王凤岗搜捕我方干部，抓捕杀害革命人员。；结局：固安解放被俘处决廊坊市人民...', '[]', '2026-09-10 09:57:14.077830', '2026-09-10 09:57:14.077830', '河北', '廊坊', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bee2b8958f6c404d95da4c9a1ec29449', '周子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北_衡水_枣强；河北；河北邢台邢台经开区', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，强征棉花、粮食，导致百姓负担沉重，并贪污勒索中饱私囊。；勾结日军，控制商业贸易，为日军采购军需物资，强迫商户缴纳“慰劳金”，剥削商民。', '[]', '2026-09-10 09:57:14.044383', '2026-09-10 09:57:14.044383', '河北', '邢台', '邢台经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bef625c4bc014011a56090f6dbea9ca6', '王仲廉', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽黄山祁门；安徽芜湖；湖北襄阳；湖北襄阳南漳；安徽宿州灵璧；重庆南岸；安徽黄山歙县；安徽宣城宁国；安徽宣城；安徽宿州泗县；浙江台州路桥；浙江台州；安徽亳州利辛；安徽亳州蒙城；安徽阜阳太和；辽宁锦州太和；安徽宿州宿州经开区；安徽宿州埇桥；安徽宿州；安徽阜阳；江苏徐州睢宁；安徽滁州凤阳；山西阳泉城区；安徽滁州来安；安徽_滁州；安徽_滁州_全椒；安徽_滁州_南谯；山西阳泉城区；安徽_滁州_苏滁现代产业园；安徽_滁州_滁州经开区；浙江金华永康；重庆北碚；重庆酉阳；安徽阜阳阜南；安徽阜阳；安徽安庆桐城；安徽安庆；江苏宿迁宿城；辽宁沈阳大东；安徽淮北相山；安徽淮北濉溪；江苏宿迁泗洪；安徽宿州泗县；安徽黄山；安徽宣城；安徽宣城泾县；安徽宣城；安徽亳州蒙城；山西阳泉城区', '[\"误记，实为王仲华\"]', '[]', '抗日战争时期', '', '在经济领域附逆，为日军采购军需物资，强制南岸商户缴纳‘治安费’，配合日军经济封锁。；负责日伪宣传，散布“大东亚共荣”谬论，诋毁抗日力量。；组织伪保安团，协助日军清乡，在宿县及周边地区参与镇压抗日武装。；王仲华，投日后任伪濉溪县知事，在相山地区推行‘连坐法’，强征粮食，迫害抗日家属。；担任伪宣城警察局长，协助日军镇压抗日活动、维持占领区治安。；汪伪政权任命为伪皖南道尹，管辖芜湖、宣城、徽州（今黄山）等地，推行伪化教育、经济统制，配合日军对黄山周边抗日根据地的清乡。；凤阳本地人，日军占领凤阳后组织维持会，替日军筹措粮秣、招募伪警，协助日军维持凤阳城区及临淮关一带的统治秩序。；率部投敌后编为伪保安团，配合日军在灵璧、泗县一带扫荡抗日武装，捕杀抗日人员。；蒙城邻近利辛，组织维持会迎接日军，后任伪职，为日军提供情报与物资。；投靠日军，任伪泗县县长，协助日军推行“治安强化运动”，镇压抗日民众，征收苛捐杂税，强征民夫修筑据点。；浙江永康人，抗战期间任伪永康县维持会会长，配合日军统治，搜捕抗日人士。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员，管理户籍与保甲，镇压民众反抗。；在滁县伪警察系统任职，配合日军搜捕抗日人员，维持沦陷区治安，压迫当地民众。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员、控制户籍与物资，维持伪统治秩序。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗，其活动范围覆盖滁州城区及周边明光等地。；在滁县伪政权中担任警察头目，带领伪警察配合日军搜查、逮捕抗日人员，镇压当地民众反抗，维护日伪在滁县的治安统治。；在阜阳沦陷区担任伪警察局长，协助日军维持治安，抓捕抗日人士，推行保甲连坐制度。；在渝东南边区协助日伪建立基层伪组织，拉拢地方士绅附逆，为日军搜集情报、筹办粮秣。；在泗县伪政权中任职，推行日伪政令，配合日军清乡、征粮和登记户口。；在皖南包括黄山、黟县地区推行清乡，协助日军扫荡抗日根据地。；宿州周边伪政权头目，任伪萧县县长，协助日军维持占领区统治，推行保甲与征粮。；在皖北阜阳一带活动，后率部投靠日伪，被编为伪军，配合日军进攻抗日根据地。；受伪政权委派在台州沿海乡镇推行保甲制度，训练伪保甲长，为日军征粮、征夫、搜集情报，活动范围包括黄岩、路桥、温岭一带。；抗战后期在皖南投敌，率伪军活动于宣城、泾县、宁国一带，配合日军扫荡抗日武装、残害地方民众。；率伪保安队配合日军“扫荡”睢宁农村，烧毁村庄，杀害抗日军属，掠夺物资。；亳县沦陷后组织伪维持会，为日军提供物资与情报，协助维持亳县城区及周边伪化统治。；南漳地区投敌分子，组织维持会，协助日军控制南漳。；滁县本地人物，抗战期间投敌，组织伪滁县维持会并任伪县长，协助日军控制滁县及周边来安等县，推行保甲、征发劳役。；歙县地方人物，抗战期间组织伪维持会，协助日军控制歙县及周边地区，参与伪化统治。；滁县本地人，抗战期间投靠日军，任伪滁县警察局局长，负责搜捕抗日人员、控制户籍与物资流通，配合日军对滁县周边乡村的扫荡。；参与伪重庆市政府筹备活动，在北碚一带进行亲日宣传，拉拢地方士绅附逆。；原国民党军将领，投敌后任伪皖北剿共军司令，在阜阳周边地区配合日军进攻新四军。；在皖北阜阳一带组织伪军，配合日军进攻抗日武装，参与伪化地方行政。；抗战后期投靠日伪，在皖北阜阳、亳州一带组织伪军，配合日军进攻抗日根据地，抗战后所部被国民党收编。；抗战期间在皖北阜阳一带投敌，组织伪军配合日军进攻抗日武装，残害百姓。；汪伪政权委任的广德县长，活动于宣城地区广德一带。；原国民党军军官，投敌后任伪军旅长，在皖北阜阳、太和周边地区活动，配合日军扫荡抗日根据地。；安庆沦陷后出面组织伪商会，为日军筹款筹物，协助经济掠夺，是安庆经济界附逆代表。', '[]', '2026-09-10 09:57:14.004926', '2026-09-10 09:57:14.004926', '安徽', '亳州', '利辛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bef6f79a0dfa448ca902701c794606ab', '吴铁民', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城响水；江苏盐城', '[]', '[]', '抗日战争时期', '', '负责盐城、响水地区清乡，设立集中营，杀害抗日志士数十人。', '[]', '2026-09-10 09:57:14.036467', '2026-09-10 09:57:14.036467', '江苏', '盐城', '响水', NULL, NULL, NULL, NULL, '');
