INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf1682c4cdbb4b74ba37fe8c6022cb0d', '赵毓英', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳卧龙；山西阳泉城区；河南信阳商城；青海黄南河南；河南开封', '[]', '[]', '抗日战争时期', '', '任伪开封市市长，协助日军管理城市，推行奴化政策。；在河南沦陷区推行亲日奴化宣传，控制报刊与教育，为日军侵略辩护。；南阳本地士绅，1945年日军侵占南阳时出面组织维持会，任伪南阳县县长，协助日军维持城区秩序、征粮征夫，是南阳地区直接附逆的代表人物。', '[]', '2026-09-10 09:57:14.045739', '2026-09-10 09:57:14.045739', '河南', '信阳', '商城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf1c99d199184cb39083484c5ac46175', '周锡侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁咸安；湖北咸宁；湖北咸宁嘉鱼；湖北咸宁', '[]', '[]', '抗日战争时期', '', '咸宁邻县蒲圻（今赤壁）伪县长，配合日军在鄂南地区推行伪化，与咸宁伪政权协同行动。；咸宁邻近地区蒲圻沦陷后任维持会会长，协助日军征粮、派夫与维持治安。', '[]', '2026-09-10 09:57:14.055100', '2026-09-10 09:57:14.055100', '湖北', '咸宁', '咸安', NULL, NULL, NULL, NULL, '');
