INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf212b32c6b34a3e8966918732668c96', '张华', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳福田；黑龙江鹤岗南山；广东深圳南山；广东深圳；江西赣州宁都；江西赣州赣县；广东深圳宝安；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '控制宝安、深圳地区物资流通，为日军采购军需，配合经济封锁，压榨民众。；推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，压制抗日思想。；在南头（今深圳南山区，毗邻福田）组织伪维持会，为日军提供情报、向导，协助日军控制深圳湾沿岸地区。；在赣县沦陷区担任保甲长，执行日军指令，登记户口、征发劳役，监视抗日家属。', '[]', '2026-09-10 09:57:14.029020', '2026-09-10 09:57:14.029020', '广东', '深圳', '南山', NULL, NULL, NULL, NULL, '');
