INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf699e1038084a218db4c992ecad6970', '姜封远', NULL, NULL, NULL, NULL, 'exact', 'exact', '鄂城华南乡', '[]', '[]', '抗日战争时期', '', '伪职：华南乡汉奸；罪行：向日军出卖情报，酿成“血战鸭儿湖”一案，致使新四军独立五团三营遭日伪伏击受重创；结局：1941年8月被樊湖抗日民主政府判处死刑，绑上石头沉入毛湖', '[]', '2026-09-10 09:57:14.070305', '2026-09-10 09:57:14.070305', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf6d7dc8e61c4d348354a09171646f35', '常之英', NULL, NULL, NULL, NULL, 'exact', 'exact', '潍县；江苏南京鼓楼；济宁', '[]', '[]', '抗日战争时期', '', '伪职：伪山东省公署总务厅长→伪潍县知事→伪莱潍道尹→伪登州道尹→伪济南道道尹→伪青州特别区行政长官；罪行：济宁人。1915年北京政府陆军参谋本部测量学校毕业。1938年5月投降日军。先后任伪山东省公署总务厅长、伪潍县知事、伪莱潍道尹、伪登州道尹、伪济南道道尹等职；结局：1946年被国民党山东省高等法院以汉奸罪逮捕，判处有期徒刑7年；伪职：伪潍县县知事；罪行：接替帅景略任伪县知事', '[]', '2026-09-10 09:57:14.033931', '2026-09-10 09:57:14.033931', '北京', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf7212e6bc4540c19d8dcde66ce54570', '崔华山', NULL, NULL, NULL, NULL, 'exact', 'exact', '亳县东北芦家庙', '[]', '[]', '抗日战争时期', '', '伪职：伪军司令；罪行：率伪军进犯亳县，芦家庙战斗遭新四军游击支队重创，残部逃窜亳州新闻网。；结局：率残部退回商丘，抗战胜利后被国民党收编。', '[]', '2026-09-10 09:57:14.073420', '2026-09-10 09:57:14.073420', '安徽', '亳州', NULL, NULL, NULL, NULL, NULL, '');
