INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf7f480eef4f4c6499736073edea73bd', '陈绍虞', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南保山龙陵；云南保山', '[]', '[]', '抗日战争时期', '', '在保山、龙陵一带收编地痞流氓组成伪军，配合日军守备据点、修筑工事，参与对抗日根据地的封锁。', '[]', '2026-09-10 09:57:13.980362', '2026-09-10 09:57:13.980362', '云南', '保山', '龙陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf81d1c02a264df091dc1d406807de68', '王殿臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北秦皇岛青龙；河北邯郸武安；辽宁沈阳新民；长垣；河北承德平泉；河北；河北承德滦平；吉林白山靖宇；吉林白山长白；河北衡水阜城；黑龙江鹤岗南山；黑龙江鹤岗；黑龙江哈尔滨；河北唐山滦州；河北唐山；河北唐山路南；河北秦皇岛昌黎；黑龙江牡丹江绥芬河；河北沧州；河北沧州肃宁', '[\"同名\"]', '[]', '抗日战争时期', '', '在唐山推行“清乡”政策，建立保甲连坐，屠杀抗日干部。；为日军宪兵队充当翻译，参与审讯和酷刑迫害抗日人士。；参与昌黎沿海“封锁沟”修建，阻止八路军海上交通。；在宽城、承德交界地带活动，率伪保安队配合日军“扫荡”，烧毁村庄，杀害抗日群众，罪行累累。；组织汉奸宣传队，诱骗青年加入伪军，协助日军“治安强化”运动。……（共涉及11个地区的犯罪记录）；伪职：伪警备大队长；盘踞长垣县城，下乡烧杀抢掠。；结局：解放后镇反处决；在滦州日军部队担任翻译，参与审讯。', '[]', '2026-09-10 09:57:14.000114', '2026-09-10 09:57:14.000114', '吉林', '白山', '靖宇', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf8413ba7def4801b14929ee7b018740', '郑海澄', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆；安徽安庆大观；安徽安庆', '[]', '[]', '抗日战争时期', '', '推行奴化教育，在安庆大观地区学校强制教授日语。；推行奴化教育，强迫学生参加“中日亲善”活动，举报抗日师生。', '[]', '2026-09-10 09:57:14.006452', '2026-09-10 09:57:14.006452', '安徽', '安庆', '大观', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf846dba84b34d90891a6b85c1a00454', '杜耀卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '满城', '[]', '[]', '抗日战争时期', '', '伪职：伪满城县县长；依托平汉铁路，修筑大量炮楼，扫荡满城西部山区根据地。；结局：战后汉奸罪判处长期徒刑', '[]', '2026-09-10 09:57:14.075857', '2026-09-10 09:57:14.075857', '河北', '保定', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf8980ce1a5847eeabb79e947a9b88f5', '王缵绪', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；四川西充；四川成都金堂；四川成都；四川成都；重庆大足；四川_成都_金牛；四川成都双流；四川成都；四川_成都_郫都；重庆合川；重庆万州；四川南充；四川_资阳；重庆沙坪坝；四川_成都_青羊', '[\"王瓒绪\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：原四川省主席、29 集团军总司令；1944 年潜离重庆赴南京投靠汪伪，任伪军事委员会常务委员、伪武汉绥靖公署主任，广播劝降川军旧部。。结局：抗战胜利捕获，关押，后病死狱中；伪职：伪五寨县县长；罪行：管控晋西北据点，摊派粮款，修筑炮楼。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.001116', '2026-09-10 09:57:14.001116', '四川', '南充', '双流', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf8dd1b7e4c04e0495057a7f2c26e169', '熊式辉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西宜春袁州；江西宜春；江西九江都昌；江西南昌；江西九江浔阳；云南普洱西；江西九江修水；江西_萍乡_安源；江西赣州；江西赣州章贡；江西赣州；江西九江柴桑；江西九江；江西鹰潭余江；江西赣州宁都；江西赣州；江西吉安吉州；云南普洱西；江西宜春宜丰；云南普洱西；江西南昌；江西宜春高安；江西宜春；江西九江德安；云南普洱西；江西宜春靖安；江西南昌；江西抚州宜黄；云南普洱西；江西吉安泰和；云南普洱西；江西赣州会昌；江西赣州；江西新余分宜；云南普洱西；江西吉安青原；江西吉安；江西宜春奉新；江西南昌；江西南昌青云谱；云南普洱西；江西景德镇乐平；江西景德镇；江西宜春万载；江西宜春', '[\"附逆人员\", \"附逆相关记载存疑，不列入\", \"附逆传闻\"]', '[]', '抗日战争时期', '', '江西沦陷区部分附逆人员之一，在伪省政府中挂名参议，为日军统治江西提供地方联络与舆论配合。；虽非典型汉奸，但其主赣期间对日妥协倾向及部分地方维持会失控常被地方史料提及；高安、宜春一带在其治下出现基层维持会组织。；江西籍国民党官员，抗战后期在赣州地区与日军进行过试探性接触，但未正式投敌，历史评价存在争议。；抗战期间任国民党江西省主席，日伪曾试图诱降，但其未公开投敌；此处仅作背景说明，非汉奸。；有资料称其在江西沦陷后与日伪有接触，但主要历史记载仍以其战前主赣及后方任职为主，附逆情节存疑，仅列备考。；抗战后期投靠日伪，任伪赣南专员，在赣州、吉安一带为日军征集粮食和劳工，配合日军对抗日根据地进行经济封锁。；抗战后期在江西沦陷区与日伪有接触并被指附逆，参与伪政权咨询事务，后随局势变化脱离，其活动范围涉及吉安周边。；南昌沦陷后投敌，出任伪南昌市长，协助日军管理城市，征发物资和劳工。；抗战期间在江西主政，后期与汪伪政权有联系，其部下在宜春、万载一带推行妥协政策，被指为附逆行为。；原国民党江西省主席，抗战后期与日伪方面有联系，其部分旧部在江西沦陷区参与维持会活动，对宜春、上高一带的伪政权建立有间接影响。；原国民党江西省政府官员，后投靠日军，在江西沦陷区参与伪政权活动，为日军提供情报和物资支持。；原国民党江西省官员，后投靠日伪，在南昌伪省政府中任职，参与推行日军‘以华制华’政策，对宜春、靖安等地伪政权有督导之责。；熊式辉为江西籍国民党官员，非汉奸；此处仅说明江西范围内有明确记载的汉奸较少，需避免误列。；该人物为国民党江西省主席，非汉奸，此处仅作排除说明。；长期主政江西，南昌沦陷前后对日妥协传闻较多，但无确凿伪职记录，奉新一带亦有相关传闻，需谨慎对待。；部分地方史料提及其在江西沦陷区与日伪有联系，但可靠证据不足，仅列为待考线索。；历史记载其曾与日方有接触，但未实际就任伪职，此处仅作存疑记录。；历史记载其曾与日方有接触，但未实际就任伪职；此条仅作存疑记录，因缺乏确凿附逆行为证据，不宜列为汉奸。；原国民党江西省主席，抗战期间曾与日军暗中接触，其旧部在赣州地区部分投敌，组织伪维持会。；抗战后期在江西日占区出任伪省政府主席，为日军筹粮筹款，推行奴化教育，配合日军对赣西包括宜春地区的控制。；江西人，原国民党政要，抗战期间曾与日方秘密接触，虽未正式就任伪职，但其妥协倾向对江西抗战产生负面影响。；原国民党官员，后附逆投敌，在江西伪政权中任职，协助日军推行经济掠夺与治安强化，涉及景德镇瓷业管制。；主政江西期间，对日伪势力采取妥协政策，纵容赣州、会昌等地伪政权活动，迫害抗日进步人士。；抗战后期在江西伪政权中任职，参与推行日军政策，协助维持占领区统治。；在南昌、九江等地为日军出谋划策，参与伪政权经济掠夺与奴化宣传。；虽未实际到任，但被汪伪政权任命为伪江西省主席，名义上统辖包括九江在内的伪政权。；曾与日方接触，拟出任伪职，后因各方压力未正式就任，但参与过伪政权筹备活动。；抗战期间曾与日伪方面有接触，虽未正式就任伪职，但其行为在江西地区产生附逆影响，被时人视为亲日分子。', '[]', '2026-09-10 09:57:14.037364', '2026-09-10 09:57:14.037364', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
