INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bf96182351a749faaabdfa2301cb0891', '黄大麻子', NULL, NULL, NULL, NULL, 'exact', 'exact', '长葛县', '[]', '[]', '抗日战争时期', '', '伪职：日伪汉奸组织头目；罪行：与田金锡、金老六一同组建日伪汉奸组织；结局：1938年11月被摧毁', '[]', '2026-09-10 09:57:14.077025', '2026-09-10 09:57:14.077025', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bfa2e6a2a11446b29b0a13ac63a7122e', '汤良礼', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西桂林恭城；云南普洱西；江西九江；浙江杭州西湖；浙江杭州；重庆_大足；陕西西安长安', '[]', '[]', '抗日战争时期', '', '福建人，汪伪政权宣传部次长，为日军进行舆论宣传。；代表汪伪与日本交涉，签署卖国条约。；负责汪伪对外宣传，对广西进行亲日宣传。；控制杭州报纸、广播，发布亲日言论，污蔑抗日军民为“匪徒”。；在汪伪政权中任外交要职，参与对日妥协。', '[]', '2026-09-10 09:57:14.032088', '2026-09-10 09:57:14.032088', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bfa40595129942e79346bd6cc2d596ec', '陈希曾', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏镇江丹阳', '[]', '[]', '抗日战争时期', '', '日军占领丹阳后率先组织维持会，为日军提供情报，协助建立伪政权，搜刮民财。', '[]', '2026-09-10 09:57:14.036844', '2026-09-10 09:57:14.036844', '江苏', '镇江', '丹阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bfb03f247af0441888ba08ac217d83d9', '张连三', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳；河南濮阳范县', '[]', '[]', '抗日战争时期', '', '范县本地人，日军侵占范县后组织维持会，协助日军建立伪政权，维持地方治安，迫害抗日人员家属。；濮阳县人，日军侵占濮阳后出面组织维持会，后任伪濮阳县知事，协助日军建立伪政权、伪保甲，征粮派款，配合日军对冀鲁豫边区进行经济封锁和军事扫荡。；率部配合日军扫荡濮阳周边抗日根据地，捕杀抗日军民，强征民夫修筑据点与封锁沟。；濮阳人，抗战期间投靠日军，任伪濮阳县保安团团长，率部配合日军扫荡濮阳、台前一带抗日武装，捕杀抗日干部和群众。；率部投降日军，编为伪濮阳县保安团，配合日军扫荡濮阳周边抗日根据地，袭击抗日武装，残害群众。', '[]', '2026-09-10 09:57:14.048672', '2026-09-10 09:57:14.048672', '河南', '濮阳', '台前', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('bfbca9127751468ab466340235b3ba57', '柯老五', NULL, NULL, NULL, NULL, 'exact', 'exact', '咸宁地区', '[]', '[]', '抗日战争时期', '', '伪职：贺胜桥维持会会长；罪行：土匪出身。1939年5月贺胜桥日伪政权建立后任维持会会长，无恶不作', '[]', '2026-09-10 09:57:14.073580', '2026-09-10 09:57:14.073580', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
