INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c03d0c5c8c3b496b98986d39b768e815', '孙耀先', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南许昌建安；河南信阳；辽宁沈阳大东；河南许昌；河南信阳淮滨；河南信阳固始；河南驻马店驻马店经开区；河南驻马店', '[]', '[]', '抗日战争时期', '', '推行奴化教育，篡改教材，组织师生参加日伪庆祝活动，宣传“大东亚共荣”。；在建安镇充任伪镇长，执行日伪保甲连坐制度，强征民夫、粮食供给日军。；在固始及邻近淮滨地区协助日军建立伪政权，组织伪自卫团，参与对抗日武装的封锁和清剿。；控制驻马店商业，为日军采购军需物资，协助经济掠夺，压迫商户。；率伪自卫团配合日军下乡扫荡，抢粮抓丁，残害百姓。', '[]', '2026-09-10 09:57:14.046055', '2026-09-10 09:57:14.046055', '河南', '信阳', '淮滨', NULL, NULL, NULL, NULL, '');
