INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c0ced85f626c4bb189a736799b5bb344', '刘锡彤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津东丽；天津西青；天津静海；河北唐山滦州；天津、河北', '[]', '[]', '抗日战争时期', '', '率伪保安队在东丽地区（如大毕庄、金钟河沿岸）巡逻，协助日军封锁交通，抓捕抗日人员。；负责在天津及西青地区推行“中日亲善”宣传，查禁抗日书刊，控制舆论。；率伪保安队协助日军围剿八路军游击队，多次袭击村庄，杀害抗日干部。；在滦州城内搜捕抗日学生和进步人士，严刑逼供。；指挥伪警察抓捕抗日军民，提供情报给日军，参与“治安强化运动”中的清乡行动。', '[]', '2026-09-10 09:57:14.002577', '2026-09-10 09:57:14.002577', '天津', '东丽', NULL, NULL, NULL, NULL, NULL, '');
