INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c1920f931ab8494eaeece015d0e081e1', '刘汉屏', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳保康；湖北襄阳；湖北襄阳', '[]', '[]', '抗日战争时期', '', '在襄阳沦陷区组织维持会，为日军提供情报、粮秣，协助日军镇压抗日活动。；在伪襄阳县政权中掌管警察武装，搜捕抗日人员，镇压民众反抗，协助日军维持占领区治安。', '[]', '2026-09-10 09:57:14.057155', '2026-09-10 09:57:14.057155', '湖北', '襄阳', '保康', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c193e2576182418cabd75650f9b6c62f', '安钦呼图克图', NULL, NULL, NULL, NULL, 'exact', 'exact', '后藏扎什伦布寺', '[\"安钦活佛\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：九世班禅麾下重要活佛。抗战期间赴伪满洲国拜见溥仪，出任北平伪 “佛教同愿会” 会长；1939 年掩护日本特务野元甚藏进入西藏，试图为日本打通西藏工作渠道。后态度发生转变，脱离日伪。没有在西藏本地出任伪职，活动主要发生北平、东北西藏文化博...。。结局：国民政府对其警告，后期幡然悔悟，返回西藏，未按汉奸审判', '[]', '2026-09-10 09:57:14.074495', '2026-09-10 09:57:14.074495', '西藏', '日喀则', NULL, NULL, NULL, NULL, NULL, '');
