INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2291d6c36614252bcf2ef5ffcddd195', '李固', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌宜都；湖北宜昌', '[]', '[]', '抗日战争时期', '', '抗战期间出任伪宜昌县县长，在宜昌地区推行伪政，配合日军清乡、征粮。；宜昌沦陷后出任伪宜昌县县长，在日军控制下管理宜昌县政，推行伪化教育、征粮征夫等。', '[]', '2026-09-10 09:57:14.056307', '2026-09-10 09:57:14.056307', '湖北', '宜昌', '宜都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c23b9ff3dc3c4e0492850d159aeab63f', '王占一', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁城', '[]', '[]', '抗日战争时期', '', '伪职：伪协和会会长；奴化宣传，检举抓捕爱国群众，为讨伐队搜集情报。；结局：土改时期镇压处决中国人民政...', '[]', '2026-09-10 09:57:14.077900', '2026-09-10 09:57:14.077900', '内蒙古', '赤峰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c25277e3d78a47acb45880af19a8b2b7', '汪翰章', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽黄山歙县；广西桂林资源；江苏南京；安徽宣城；江苏南京浦口；辽宁沈阳大东；安徽_宿州_宿州马鞍山现代产业园；安徽滁州', '[]', '[]', '抗日战争时期', '', '歙县本地士绅，抗战期间出面组织伪维持会，为日军筹粮筹款、维持地方伪秩序，协助日军控制歙县城乡。；协助日军掠夺安徽资源，修建军事设施，征用民工。；在南京学校中灌输亲日思想，压制师生抗日言论。；汪伪安徽省政权核心幕僚，协助伪省长推行对安徽沦陷区包括宣城一带的统治。；安徽沦陷区伪政权教育头目，推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；在安徽推行奴化教育，编写亲日教材，组织学生参加亲日活动，为日军占领区培养顺民。；在安徽沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。；在安徽沦陷区推行奴化教育，篡改教材、宣传亲日思想，滁州地区学校亦受其伪教育政策影响。', '[]', '2026-09-10 09:57:14.007914', '2026-09-10 09:57:14.007914', '安徽', '黄山', '歙县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c255437de4684a39bd44b8c721b49190', '李锡三', NULL, NULL, NULL, NULL, 'exact', 'exact', '曲周；板浦、灌云全县', '[]', '[]', '抗日战争时期', '', '伪职：伪曲周县县长；执行治安强化运动，抓丁征粮，搜捕地下交通人员。；结局：战后判处长期徒刑；伪职：伪灌云县警察局长；罪行：执掌伪警察，搜捕地下抗日人员，刑讯爱国群众，配合伪军下乡清剿。；结局：战后被捕法办。', '[]', '2026-09-10 09:57:14.069336', '2026-09-10 09:57:14.069336', '河北', '邯郸', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c25cfa78420049e381ac8b22777df6ae', '齐知政', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江黑河北安；黑龙江齐齐哈尔；吉林白城镇赉；吉林白城；吉林长春；辽宁锦州凌海；吉林长春长春经开区；吉林松原前郭尔罗斯；吉林、辽宁；吉林松原松原经开区；吉林松原长岭', '[]', '[]', '抗日战争时期', '', '伪职：伪吉林省警备司令；罪行：指挥吉林伪警备武装，配合日军镇压吉林城乡抗日运动。；结局：苏军逮捕，抚顺战犯管理所，后期特赦。；协助市长管理长春，参与“新京”城市规划，驱逐原住民。；在长春、净月地区组织协和会，宣传“日满一体”，监视民众思想，告密迫害反满人士。；原长春县地方士绅，投日后任伪长春县长，在长春经开区（原属长春县）一带推行日伪统治。；在凌海地区强制推行“归屯并户”，制造无人区，配合日军围剿义勇军，征收苛捐杂税。', '[]', '2026-09-10 09:57:13.998850', '2026-09-10 09:57:13.998850', '吉林', '松原', '前郭尔罗斯', NULL, NULL, NULL, NULL, '');
