INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2a88199e51f43a3b192458e1a8ae182', '陈见园', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详；伪特别市政府', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪厦门特别市政府秘书长，伪市府核心幕僚。结局：战后逮捕判处徒刑，狱中病亡；伪职：伪市府秘书长；罪行：伪市府核心幕僚，协助李思贤处理政务，草拟伪政令。；结局：战后审讯定罪。', '[]', '2026-09-10 09:57:14.076146', '2026-09-10 09:57:14.076146', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2aca0fd96aa4ca893a9543b0605771f', '黄植楠', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东惠州；广东惠州惠阳；广西南宁邕宁；广西南宁', '[]', '[]', '抗日战争时期', '', '在日军扶植下参与组织伪惠阳县政权，推行伪化统治，征发民夫物资供应日军，配合日军对东江地区的控制。；日军侵占南宁期间，以商会会长身份协助日军征发物资、摊派款项。', '[]', '2026-09-10 09:57:14.027201', '2026-09-10 09:57:14.027201', '广东', '惠州', '邕宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2ade37fd1474989beaedd14a62e6111', '刘梦庚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津东丽；天津西青；锦州；北京通州；天津_静海；北京顺义；吉林白山；内蒙古赤峰喀喇沁旗；内蒙古赤峰；河北承德；山东聊城茌平；山东聊城；天津河北；北京、天津、河北、辽宁；河北秦皇岛山海关；河北秦皇岛；河北秦皇岛抚宁；辽宁营口；河北唐山；河北承德双滦；河北承德承德高；河北承德；辽宁锦州；河北_秦皇岛_秦皇岛经开区；辽宁葫芦岛；辽宁葫芦岛绥中；天津北辰；河北廊坊广阳；天津河北', '[]', '[]', '抗日战争时期', '', '长期担任通县伪政权负责人，配合日军“清乡”和“治安强化运动”，迫害抗日军民。；在顺义县内积极推行日伪政策，强征粮食，破坏抗日组织，残害抗日群众。；在任期间协助日军推行“治安强化运动”，在东丽地区（如军粮城、赤土一带）设立据点，搜捕抗日分子。；继任伪天津县知事，在北辰地区推行日伪法令，抓捕抗日群众。；为日军筹措军费，强制摊派商业捐税，协助日伪经济掠夺。……（共涉及14个地区的犯罪记录）；伪职：伪锦州市维持会会长（八一五后）；罪行：日本投降后拼凑锦州治安维持会，留用全部伪警察，勾结残留日军等待国民党接收。；结局：1945 年被民主政府逮捕，汉奸罪判刑。', '[]', '2026-09-10 09:57:13.990554', '2026-09-10 09:57:13.990554', '内蒙古', '赤峰', '喀喇沁旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2b00f877f834ada852e281ce3cbb958', '王德金', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶德兴；江西上饶', '[]', '[]', '抗日战争时期', '', '上饶地区抗战时期部分伪警察人员名录散见于地方志，但德兴、上饶具体汉奸个案公开可靠记载极少。', '[]', '2026-09-10 09:57:14.037991', '2026-09-10 09:57:14.037991', '江西', '上饶', '德兴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2b1f12770ba49688ffed17acdcf0205', '贾式平', NULL, NULL, NULL, NULL, 'exact', 'exact', '洛阳城区', '[]', '[]', '抗日战争时期', '', '伪职：伪洛阳县政府县长；罪行：深得日本间谍佐藤羡次郎赏识，洛阳沦陷后被推荐任命为伪县长，为虎作伥，干了很多坏事；结局：日本投降后靠内亲庇护暂逃一劫，洛阳二次解放后被逮捕法办', '[]', '2026-09-10 09:57:14.085396', '2026-09-10 09:57:14.085396', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2b3fe6d3b754fd5a304ebff74c92185', '谭子钦', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌五峰；湖北宜昌长阳；湖南衡阳耒阳', '[]', '[]', '抗日战争时期', '', '统率伪保安团在长阳、五峰交界地区配合日军清乡，袭击抗日游击队。；湖南耒阳人，日军侵入耒阳后组织伪维持会，为日军筹粮、派夫，协助日军维持占领区秩序；耒阳与安仁相邻，同属郴州地区。', '[]', '2026-09-10 09:57:14.056215', '2026-09-10 09:57:14.056215', '湖北', '宜昌', '五峰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2b897c25bf7442ba35fbee5d94888e2', '刘从云', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川', '[\"刘神仙\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：四川著名相士、袍哥、会道门大佬；曾私下与汪伪暗通书信，散布抗战悲观投降言论，煽动地方势力动摇。。结局：被国民政府驱逐出川，解放后被镇压', '[]', '2026-09-10 09:57:14.083108', '2026-09-10 09:57:14.083108', '四川', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2b905836c654c8689a675399a311b46', '丁其达', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古赤峰林西；内蒙古乌兰察布；内蒙古包头九原；内蒙古兴安乌兰浩特；内蒙古乌兰察布商都', '[]', '[]', '抗日战争时期', '', '投靠日军，任商都县伪县长，推行日伪法令，强征民夫，搜刮粮食，镇压当地抗日力量。；作为伪满兴安总省（辖今兴安盟、乌兰浩特）最高行政长官，推行日本殖民政策，强征劳工，镇压反满抗日活动。；任伪包头市长期间，为日军征集物资、强征劳工，在九原区推行保甲制度，镇压抗日地下活动，协助日军建立特务组织。', '[]', '2026-09-10 09:57:13.986202', '2026-09-10 09:57:13.986202', '内蒙古', '乌兰察布', '商都', NULL, NULL, NULL, NULL, '');
