INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2deb0602eaf44dabefcff72d6909086', '吴铁城', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关仁化；广东韶关；广东韶关曲江；广东湛江', '[]', '[]', '抗日战争时期', '', '统率伪军在粤北包括韶关、仁化一带配合日军扫荡抗日游击队，烧杀抢掠，残害百姓，罪行累累。；为日军筹款筹粮，协助经济统制，压迫商户。；在广东占领区训练伪保甲长，协助日军推行保甲制度，加强基层控制。', '[]', '2026-09-10 09:57:14.029542', '2026-09-10 09:57:14.029542', '广东', '湛江', '仁化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2e6c4c778dd4a3d86afc954cfc1f8fc', '萧叔宣', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西南昌；江西九江；山东聊城；南京汪伪，谋划接管福建沦陷区，战时曾谋划对永安省府诱降抖音百科；江西宜春；云南_昆明_呈贡；福建闽侯；云南普洱西；四川_广元；江西宜春万载；江西宜春', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪陆军部长、伪福建省政府主席；罪行：汪伪高级将领，主持伪福建政务规划，参与诱降国民政府，筹划接收福州厦门伪政权。；结局：1945 年 8 月南京逮捕汉奸冲突中中弹身亡抖音百科。；伪任职务：汪伪陆军部部长、军训部部长，曾拟出任伪福建省省长，训练伪军，东南伪军事核心。结局：1945 年抗战胜利前夕被军统击毙，未受审判', '[]', '2026-09-10 09:57:13.983467', '2026-09-10 09:57:13.983467', '江西', '九江', '万载', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2ecb7584f554f4f8e903e3ab5de6c03', '刘子芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏淮安盱眙；江苏淮安', '[]', '[]', '抗日战争时期', '', '率部投敌，任伪淮安保安队大队长，多次参与日军对淮安、盱眙交界地区的“清剿”，杀害抗日军民。', '[]', '2026-09-10 09:57:14.036303', '2026-09-10 09:57:14.036303', '江苏', '淮安', '盱眙', NULL, NULL, NULL, NULL, '');
