INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2f4ea156b0342b7ad8635f0b0f015c3', '赵仁泉', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城高唐；山东德州临邑；山东德州；山东聊城茌平；山东聊城；山东聊城临清；山东聊城', '[]', '[]', '抗日战争时期', '', '伪鲁西道尹，管辖聊城、茌平等县，推行治安强化，配合日军扫荡鲁西北抗日根据地。；抗战期间任伪鲁西道尹，管辖聊城、临清等鲁西各县，推行日伪统治，协助日军征粮、清乡。；统领伪高唐警备队，配合日军对高唐及周边地区进行“扫荡”，捕杀抗日干部和群众，强征民夫修筑据点。；任伪鲁北道尹，管辖包括德州、临邑在内的鲁北地区，推行日军殖民政策，组织伪军、伪警。', '[]', '2026-09-10 09:57:14.013624', '2026-09-10 09:57:14.013624', '山东', '德州', '临邑', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c2fdf0c07c7b4c9589b81b11c6a15057', '张万镒', NULL, NULL, NULL, NULL, 'exact', 'exact', '平鲁', '[]', '[]', '抗日战争时期', '', '伪职：伪平鲁县县长；罪行：建立平鲁伪政权，修筑炮楼，配合讨伐队扫荡平鲁山区。；结局：战后汉奸罪判刑', '[]', '2026-09-10 09:57:14.072778', '2026-09-10 09:57:14.072778', '山西', '朔州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c31450c24bd84a78bcaf55086aec6a55', '巴嘎雅苏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古呼伦贝尔额尔古纳；内蒙古呼伦贝尔陈巴尔虎旗', '[]', '[]', '抗日战争时期', '', '在陈巴尔虎旗地区组织伪警察力量，协助日军清剿抗日武装，抓捕抗日志士。；额尔古纳本地蒙古族头人，投靠日伪后任旗长，强制推行“粮谷出荷”，为日军提供物资，并举报抗日民众。', '[]', '2026-09-10 09:57:13.989680', '2026-09-10 09:57:13.989680', '内蒙古', '呼伦贝尔', '额尔古纳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c314c5ef164d40599826a9603c4814d0', '王永山', NULL, NULL, NULL, NULL, 'exact', 'exact', '永嘉（今鹿城）城区', '[]', '[]', '抗日战争时期', '', '伪职：伪温州临时商会会长；罪行：1941 年温州第一次沦陷即投靠日军，组建伪临时商会，强征物资，协助日军抢运粮食、布匹等战略物资，威逼商户资敌，城区臭名昭著的商界汉奸温州新闻网...。；结局：抗战胜利后以汉奸罪逮捕判刑。', '[]', '2026-09-10 09:57:14.075749', '2026-09-10 09:57:14.075749', '浙江', '温州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3186cc1677f46c99a11bc6e4ed120c6', '刘继武', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古通辽扎鲁特旗；内蒙古通辽；内蒙古赤峰林西；内蒙古赤峰；吉林松原长岭', '[]', '[]', '抗日战争时期', '', '日军占领赤峰后，率先组织维持会，为日军筹粮筹款，协助建立伪县公署，后任伪赤峰县协和会会长，推行奴化宣传。；在伪满洲国通辽县任职，参与伪政权地方行政与警察事务，协助日军维持统治、镇压抗日活动。；伪满时期任长岭县伪县长或维持会头目，直接参与长岭地区的伪政权统治，为日军征粮、派夫、镇压抗日活动。', '[]', '2026-09-10 09:57:13.991597', '2026-09-10 09:57:13.991597', '内蒙古', '赤峰', '林西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c318dfb03a4146678c2272b2ede941e8', '周馥', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽池州；安徽池州贵池；安徽池州', '[]', '[]', '抗日战争时期', '', '贵池地方商人，投敌后任伪秋浦县维持会副会长，协助日军管理码头与物资转运，在池州沿江一带为日军服务。；安徽人，汪伪政权财政官员，负责安徽沦陷区税收与物资统制，为日军搜刮战略物资，其财政网络覆盖池州、青阳等皖南地区。', '[]', '2026-09-10 09:57:14.008597', '2026-09-10 09:57:14.008597', '安徽', '池州', '贵池', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c31a521c4c8e4afb982ebe015eb7fac5', '崔中英', NULL, NULL, NULL, NULL, 'exact', 'exact', '叶县', '[]', '[]', '抗日战争时期', '', '伪职：日军谍报队参谋、中校军统特务；罪行：原供职于豫西警备司令部中校参谋。日军占领叶县后摇身一变成为日军谍报队参谋，专事破坏叶县党组织，危害乡里，无恶不作；结局：1944年，叶县地下党组织决定由陈继尧、王文卿将其除掉。陈继尧假托其岳母病重写信诱其回乡，途中在邵奉店村头将其击毙', '[]', '2026-09-10 09:57:14.087147', '2026-09-10 09:57:14.087147', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
