INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c395c340a7c846e3bd349a1b5d72565f', '曹瑞麟', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江鹤岗绥滨；黑龙江鹤岗；吉林辽源东辽；黑龙江牡丹江西安', '[]', '[]', '抗日战争时期', '', '任伪西安县县长期间，强制推行“保甲制度”，强征劳工，为日军提供煤炭资源，镇压当地反满抗日活动。', '[]', '2026-09-10 09:57:14.000618', '2026-09-10 09:57:14.000618', '吉林', '辽源', '东辽', NULL, NULL, NULL, NULL, '');
