INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3b096328fef4a60a7c4b66bea949eaf', '张学成', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁海城（张作霖侄）；辽宁海城', '[]', '[]', '抗日战争时期', '伪军', '伪任职务：张学良堂弟，伪辽西保安司令，收拢土匪伪军袭扰盘山一带。结局：1931 年被东北军部队击毙；伪职：九一八后伪 “东北自卫军总司令”，司令部驻黑山县高山子；罪行：受日军委任，收拢土匪、溃兵，在辽西黑山、北镇一带进攻义勇军，残害百姓。；结局：1931 年被黄显声部义勇军击毙。', '[]', '2026-09-10 09:57:14.082208', '2026-09-10 09:57:14.082208', '辽宁', '鞍山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3ba8433395a4b01b7791190a9334234', '王廷翰', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃天水；甘肃兰州永登；甘肃兰州皋兰', '[]', '[]', '抗日战争时期', '', '天水人，任伪天水县警察局局长，配合日军镇压抗日活动，抓捕抗日志士，维护日伪统治。；在皋兰县组织维持会，为日军征发粮食、劳工，协助伪政权维持地方秩序，镇压当地抗日活动。；在永登地区组织维持会，为日军征集物资、情报，协助日军控制地方。', '[]', '2026-09-10 09:57:14.060095', '2026-09-10 09:57:14.060095', '甘肃', '兰州', '永登', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3c585c3a79d4768b37f28858866a674', '马占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西_忻州_定襄；山西；山西运城平陆；山西晋中灵石', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，横征暴敛，逼死多名交不起税的农民，并贪污部分税款。；率自卫团为日军站岗放哨，截击抗日游击队，杀害多名抗日军属。；率伪警备队多次围剿抗日游击队，烧毁村庄，抢夺牲畜，杀害无辜百姓，罪行累累。', '[]', '2026-09-10 09:57:14.021910', '2026-09-10 09:57:14.021910', '山西', '晋中', '灵石', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3c83eb3110a48f989c07547e34e2705', '李长江', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳南岳；陕西宝鸡凤县；云南普洱西；江苏泰州；安徽滁州；湖南_娄底_新化；陕西_西安；云南普洱西；安徽滁州；安徽马鞍山；江苏扬州；湖南常德；江苏泰州；云南_昆明_呈贡；安徽六安；安徽安庆；安徽_宣城_宁国；安徽_宣城_泾县；安徽阜阳；安徽黄山；江苏扬州；江苏宿迁；湖北_咸宁_通山；湖南_怀化_怀化洪江管理；湖南_怀化_溆浦；云南普洱西；江苏盐城；安徽芜湖；吉林高；山东聊城茌平；山东聊城；广西_桂林_灵川；江苏泰州；江苏扬州；湖南_湘西_泸溪；河北；河北唐山路南；南京；江苏_南京；江苏扬州；安徽宣城；江苏徐州邳州；江苏徐州；江苏扬州；江苏扬州高邮；江苏泰州；江苏泰州；江苏盐城；安徽六安；安徽安庆；安徽阜阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪第一集团军总司令；罪行：原鲁苏皖边区游击副总指挥，1941 年 2 月率万余部队公开投敌，盘踞泰州；配合日军扫荡苏中根据地，掠夺物资，残害抗日军民；讨逆战役遭新四军重创西逃，后被日军下毒致瘫痪抖音百科。；结局：抗战胜利后被捕，病死狱中。；投敌后所部曾北犯冀东，在路南地区与八路军作战。；伪任职务：汪伪第一集团军总司令，总部前期驻泰州，部队经常进出扬州辖区，投敌之后多次进攻苏中根据地。1943 年赴扬州赴宴被日军下毒致终身瘫痪。。结局：建国后病逝江西抖音百科', '[]', '2026-09-10 09:57:13.983703', '2026-09-10 09:57:13.983703', '江苏', '泰州', '茌平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c3dac8e296694e699da8f10b2e99196a', '姚慕陶', NULL, NULL, NULL, NULL, 'exact', 'exact', '安庆', '[]', '[]', '抗日战争时期', '', '伪职：伪怀宁县财政科长；罪行：经济汉奸，征收各类苛捐杂税，统筹粮食、铜铁、油料为日军搜刮战略物资，摊派商户巨额捐款。；结局：战后判处有期徒刑。', '[]', '2026-09-10 09:57:14.086201', '2026-09-10 09:57:14.086201', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
