INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c424e0fff3954dd59b60ca090d5912d7', '陈继德', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南东方；海南陵水；海南东方；海南乐东', '[]', '[]', '抗日战争时期', '', '在乐东地区为日军征粮征工，协助日军控制山区，镇压黎族苗族抗日群众。；在陵水地区推行奴化教育，强制日语教学，宣传亲日思想。', '[]', '2026-09-10 09:57:14.053908', '2026-09-10 09:57:14.053908', '海南', '东方', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c425e45a8d314a6aa0954cc4f0bebc1d', '赵文甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北十堰竹山；湖北十堰丹江口；湖北随州曾都；湖北黄冈红安；河南驻马店驻马店经开区；河南驻马店；湖北黄冈罗田；湖北黄冈浠水；湖北黄冈；河南洛阳瀍河；河南洛阳；湖北黄石；河南新乡新乡高；河南新乡', '[]', '[]', '抗日战争时期', '', '在汝南及驻马店周边配合日军行动，强征民夫，修筑封锁沟墙。；洛阳沦陷后任伪保甲长，协助日军清查户口、征粮征夫，监控居民。；在随县厉山、曾都北部一带组织维持会，为日军带路、征粮，协助建立伪基层保甲。；统率鄂东伪军，配合日军对黄石、大冶、阳新等地进行扫荡，残害百姓。；湖北红安人，抗战期间在红安地区组织伪维持会，协助日军统治，参与征粮、征丁，破坏抗日基层组织。；在均县（今丹江口市一带）组织伪维持会，替日军办理地方事务，强征粮食、物资和民夫，协助日伪控制汉水沿线交通。；控制新乡商业，为日军筹款筹物，协助经济掠夺。；罗田地区人，抗战期间组织伪维持会，为日军服务，协助征发物资、维持地方伪秩序。；浠水地区伪军头目，组织伪保安团配合日军清乡，在浠水及邻近黄冈地区镇压抗日活动，残害百姓。', '[]', '2026-09-10 09:57:14.048388', '2026-09-10 09:57:14.048388', '河南', '新乡', '新乡高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c426989d63ad4715938d5a01164c3c75', '林汝澄', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州鹿城', '[]', '[]', '抗日战争时期', '', '为日军和伪政权出谋划策，协助建立情报网，向日军提供抗日武装活动情报。', '[]', '2026-09-10 09:57:14.051513', '2026-09-10 09:57:14.051513', '浙江', '温州', '鹿城', NULL, NULL, NULL, NULL, '');
