INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c4a134e30f8d45088a8d968126622bd7', '刘仙洲', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城莘县；山东聊城；山东泰安肥城；山东泰安；山东聊城阳谷；山东聊城；山东济南平阴；山东济南；山东济宁兖州；山东济宁；山东济宁梁山；山东济宁；河南郑州管城；山西阳泉城区；山东泰安；辽宁沈阳新民；山东聊城；山东菏泽东明；山东临沂；山东济宁济宁高；山东济宁；山东聊城临清；山东德州禹城；山东德州；山东菏泽巨野；山东菏泽；山东枣庄台儿庄；山东聊城冠县；山东聊城；山东菏泽郓城；山东济宁金乡；山东济宁；山东济南；河南商丘民权；河南商丘；山东济宁鱼台；山东济宁；山东济南槐荫；山东济南；山东菏泽曹县；山东菏泽定陶；山东菏泽；山东泰安泰山；山东泰安；山东聊城东昌府；山东聊城；山东济南济南高；山东济南历城；山东济南历下；山东济南', '[]', '[]', '抗日战争时期', '', '管辖聊城等鲁西各县伪政权，推行治安强化运动，为日军掠夺物资。；在滕县及济宁南部边缘地区协助日军清乡，残害抗日军民。；在伪济宁道尹公署任职，掌管伪警察力量，配合日军搜捕抗日人员，推行保甲连坐，压制民众抗日。；任伪东临道（辖聊城、阳谷等县）道尹，推行日军政令，督征粮秣，组织伪保安队，协助日军维持鲁西占领区。；在经济领域附逆，为日军筹款筹粮，协助控制济宁物资。；在山东伪政权中任职，活动范围覆盖鲁西包括菏泽、定陶一带，参与制定伪化政策，协助日军掠夺资源、镇压抗日力量。；历城沦陷后任伪县知事，为日军征粮派夫，镇压当地抗日群众。；作为东明县商会会长，为日军筹款筹物，协助日军控制当地经济，压榨商户和百姓，是经济领域附逆的代表人物。；参与组织济南维持会，协助日军接管城市。；在德州沦陷期间任伪商会会长，为日军筹措物资、摊派款项，协助日军对德州及禹城周边进行经济掠夺。；聊城沦陷后组织维持会，后任伪县长，协助日军征粮征夫、建立保甲，镇压当地抗日活动。；作为日军顾问控制曹县伪政权，推行治安强化运动，策划清乡与保甲连坐。；协助申振纲组织郑州维持会，为日军筹集物资、招募劳工，维持城区秩序。；任伪泰安县警察头目，配合日军搜捕抗日人员，镇压地方抗日活动。；在济南槐荫地区组织维持会，为日军征粮征夫，协助建立伪保甲制度。；在山东包括泰安地区推行新民会运动，进行奴化宣传。；在商丘伪政权中负责教育，推行日军奴化教育，篡改教材，向学生灌输亲日思想，活动范围覆盖商丘及民权等地。；在泰安地区统领伪保安队，配合日军清乡、扫荡，镇压抗日群众，抓捕抗日干部和家属。；日军侵占聊城后出面组织维持会，维持地方秩序并替日军筹粮筹款，诱降地方武装，是聊城早期伪政权代表人物之一。；山东伪政权要员，参与制定伪化政策，曾到菏泽、巨野等地视察督导伪政，协助日军掠夺物资。；在郓城伪警察系统任职，搜捕抗日人员，配合日军维持治安，参与对郓城周边抗日根据地的封锁与清剿。；驻济南，协助日军控制山东盐业资源，掠夺物资，为伪政权筹款。；抗战期间任伪兖济道尹，管辖兖州、济宁一带，协助日军控制鲁南鲁西南交通线。；主持伪县政，强征田赋，抓捕壮丁送日军做劳工，镇压抗日群众。；伪聊城县知事，在聊城本地推行保甲制度，征粮征丁，协助日军维持治安。；临清商界人物，抗战期间附逆，参与维持会，为日军筹款筹粮，协助控制临清经济。；驻济南，统管山东伪警察系统，镇压抗日群众，推行治安强化运动。；任伪济南道尹，管辖包括平阴在内的鲁中地区，推行日伪政令，镇压抗日活动。；抗战期间在济宁地区附逆，历任伪济宁县知事、伪济宁县长，为日军筹粮筹款，推行保甲连坐，配合日伪清乡。；在峄县及台儿庄地区组建伪警察队伍，搜捕抗日人员，推行保甲连坐，协助日军维持占领区治安。；任伪临沂县警察局长，协助日军维持治安，搜捕抗日人员，镇压群众抗日活动。', '[]', '2026-09-10 09:57:14.012934', '2026-09-10 09:57:14.012934', '山东', '德州', '禹城', NULL, NULL, NULL, NULL, '');
