INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c4b9ff1100ee41ca9c07aa1583f1890f', '马振东', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊寿光；山东济宁汶上；山东济宁；山西阳泉城区；山东滨州；山东滨州无棣；山东滨州沾化；山东滨州滨城；辽宁铁岭清河；山东潍坊安丘；山东潍坊临朐；内蒙古赤峰宁城；山东滨州阳信；山东泰安', '[]', '[]', '抗日战争时期', '', '临朐沦陷后组织维持会，任伪县长，配合日军扫荡，征粮征夫，残害百姓。；在沾化（邻近无棣）率伪军配合日军扫荡，袭击抗日根据地，残害百姓。；在兖州、济宁一带推行伪化教育，组织伪自卫团，配合日军对鲁南、鲁西南抗日根据地的扫荡。；在寿光抓捕抗日干部和群众，刑讯逼供，配合日军扫荡。；蒲台沦陷后投敌，组织维持会并任伪县长，为日军征集物资、修筑据点，协助日军对清河区进行治安强化运动。；率伪警察搜捕抗日人士，破坏中共地下组织，在济宁城乡推行保甲连坐。；控制济宁城区伪警察，参与抓捕、刑讯抗日嫌疑人员，协助日军管制物资。；在滨县及阳信边界地区搜捕抗日人员，实施保甲连坐，镇压民众反抗。；为日军筹款筹物，协助经济统制，压榨泰安商民。；在齐东县组织维持会，后任伪县长，为日军征集粮食、棉花，抓捕抗日人员，破坏抗日组织。', '[]', '2026-09-10 09:57:14.014715', '2026-09-10 09:57:14.014715', '山东', '泰安', '汶上', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c4c23d3db17b4f0e995117935e5a136d', '冯启明', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东广州南沙；广东广州；广东韶关；广东广州；广东广州番禺；广东广州海珠；广东广州', '[]', '[]', '抗日战争时期', '', '汪伪政权在广州教育领域的附逆者，推行奴化教育，曾任伪广州市教育局长。；在广州沦陷区参与伪教育文化机构，推行奴化教育，为日伪宣传服务。；负责伪广东宣传，在广州主办亲日报刊与广播，为日军占领制造舆论。；负责汪伪广东宣传机构，为日军侵略辩护，进行反共亲日宣传，影响范围包括韶关周边沦陷区。；番禺地区附逆人物，组织伪维持会，协助日军征粮、拉夫、维持地方伪秩序。', '[]', '2026-09-10 09:57:14.026682', '2026-09-10 09:57:14.026682', '广东', '广州', '南沙', NULL, NULL, NULL, NULL, '');
