INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c5655ebf4c994c3ba460c28d26b2fd4f', '李景林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北衡水衡水滨湖；河北衡水；天津、河北、辽宁；黑龙江牡丹江东安；河北沧州黄骅；河北廊坊永清；辽宁盘锦盘山；河北邯郸邯郸冀南；河北邯郸；河北邢台信都；河北沧州沧州渤海；河北沧州；河北沧州任丘；河北沧州；河北承德兴隆；河北沧州新华；河北石家庄新华；河北_沧州_沧州高；河北沧州沧县；河北石家庄井陉；河北保定高碑店；河北沧州肃宁；黑龙江齐齐哈尔；河北衡水安平；河北邯郸复兴；河北石家庄石家庄高；河北石家庄赞皇；河北沧州沧县；河北沧州；河北保定莲池；河北衡水故城；河北衡水；河北沧州海兴；河北沧州沧县；河北沧州盐山；天津静海；河北沧州沧州经开区；河北沧州河间；河北沧州沧县；河北廊坊固安；天津河北；河北石家庄；河北邢台；河北邢台襄都', '[]', '[]', '抗日战争时期', '', '统率伪军多次对静海、大港等地区进行“清乡”，烧杀抢掠，制造无人区。；原地方军阀余部，投日后负责清乡，在莲池周边多次组织“扫荡”，杀害抗日干部，抢劫民财，纵容部下奸淫妇女。；率伪军驻防保定及高碑店一带，多次参与对八路军冀中根据地的进攻，烧杀抢掠，民愤极大。；组织地方自卫团，配合日军“扫荡”，在永清西部村庄烧杀抢掠，杀害多名八路军伤员。；组织自卫团协助日军封锁山区，切断抗日武装补给线，并亲自带队搜捕抗日游击队员，杀害多名伤员。……（共涉及42个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.003674', '2026-09-10 09:57:14.003674', '天津', '静海', '莲池', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c576e2ddc91641f8bacc90d0cef81ddf', '伪石城县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西赣州石城', '[]', '[]', '抗日战争时期', '', '石城沦陷时期伪维持会为日军控制赣闽交通线。', '[]', '2026-09-10 09:57:14.038857', '2026-09-10 09:57:14.038857', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
