INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c5d1c90280984dd69191d98d0619198d', '冷寅东', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川资阳；湖南益阳资阳；四川成都', '[]', '[]', '抗日战争时期', '', '抗战期间投靠日伪，参与组织成都维持会，后任伪成都市市长，协助日军维持占领区秩序，推行奴化教育。；资阳本地士绅，日军侵扰四川期间组织维持会，为日军征集粮秣、劳工，协助伪政权维持地方秩序。；抗战初期在成都组织维持会，后出任伪成都市长，协助日军及伪政权维持地方统治，推行奴化教育，为日军搜集物资。；抗日战争期间投靠日军，在成都组织伪维持会，后任伪成都市长，协助日军维持占领区秩序，推行奴化教育，为日军征集物资。；抗日战争期间投靠日伪，参与组织伪成都市维持会，后任伪成都市长，协助日军维持占领区秩序，推行伪化统治。', '[]', '2026-09-10 09:57:14.001651', '2026-09-10 09:57:14.001651', '四川', '资阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c5d1fc65cd0f4740847890dfc3c42615', '刘山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁柳林；山西吕梁方山；山西；山西吕梁', '[]', '[]', '抗日战争时期', '', '在岚县（今吕梁岚县）率伪军围攻抗日根据地，杀害干部。；投靠日军，任方山县伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡，搜捕抗日军民，勒索百姓财物。；在柳林镇为日军摊派粮款，强迫民众劳役，告密抗日分子。', '[]', '2026-09-10 09:57:14.019543', '2026-09-10 09:57:14.019543', '山西', '吕梁', '方山', NULL, NULL, NULL, NULL, '');
