INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c7961f31a4504d34a3454618214a3a3a', '潘子明', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁；山东济宁鱼台；山东济宁邹城；山东济宁；山东济宁嘉祥；山东济宁；山东济宁梁山；山东济宁泗水；山东济宁', '[]', '[]', '抗日战争时期', '', '在济宁及嘉祥周边充任伪军头目，协助日军维持治安、清乡与封锁抗日根据地。；掌管济宁道伪警察系统，在济宁、泗水等地搜捕抗日人员，实施经济封锁。；伪兖州道辖济宁周边，配合日军进行治安强化运动，摧残抗日力量。；在梁山地区组织维持会，为日军征粮、派夫、搜集情报，协助日军控制梁山一带。；率伪保安团配合日军进攻鱼台抗日根据地，烧杀抢掠，残害百姓。；管辖鲁南地区，包括济宁东部、邹县一带，组织伪军警配合日军扫荡。', '[]', '2026-09-10 09:57:14.015393', '2026-09-10 09:57:14.015393', '山东', '济宁', '嘉祥', NULL, NULL, NULL, NULL, '');
