INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c7b5347f0e8946b3a5c1f842a94e7bdb', '方少云', NULL, NULL, NULL, NULL, 'exact', 'exact', '青阳县城、蓉城；广东潮州湘桥；广东潮州潮安；广东汕头；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '伪职：青阳维持会会长；罪行：青阳沦陷牵头组建维持会，网罗地痞，征粮抓夫，协助日军对九华山周边扫荡，推行伪化。；结局：抗战胜利后军法审判处死。', '[]', '2026-09-10 09:57:14.028020', '2026-09-10 09:57:14.028020', '广东', '汕头', '湘桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c7ce2b4df8694554994226c39e3bc7d6', '何丽生', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾；辽宁沈阳大东；广东肇庆端州；广东深圳盐田；广东深圳；广东清远阳山；广东梅州丰顺；广东梅州梅县；广东清远连南；广东清远；广东佛山三水；广东佛山；广东肇庆；广东肇庆广宁；广东佛山顺德；广东佛山；广东清远清城；广东广州；广东湛江；广东韶关南雄；广东韶关；广东肇庆封开；广东肇庆；广东清远佛冈；广东清远；广东河源紫金；广东河源；广东深圳；广东肇庆怀集；广东肇庆；广东韶关翁源；广东广州白云；广东清远英德；广东清远；广东珠海', '[]', '[]', '抗日战争时期', '', '深圳沦陷后组织伪商会，为日军筹款筹粮，协助经济统制。；佛山南海沦陷后任伪县长，配合日军推行伪化统治，征粮征税，镇压抗日群众。；在连南本地组织伪维持会，协助日军管理瑶汉民众，征发物资，为日军带路扫荡山区抗日力量。；翁源基层汉奸，担任伪保甲长，负责为日军摊派捐税、征发民夫，监视村民动向，举报抗日分子。；推行奴化教育，篡改教材，强迫师生参加日军庆祝活动，宣传所谓大东亚共荣。；组织伪妇女会，为日军慰劳、宣传“共存共荣”，动员妇女参加日伪活动，协助奴化教育。；在伪广东省政府教育部门任职，推行日语及奴化教育，编写亲日教材，其教育政策覆盖肇庆、怀集等西江地区学校。；控制珠海地区商业，为日军统制物资、征购军粮，协助经济掠夺。；深圳沦陷后组织伪深圳维持会，协助日军管理深圳墟及周边地区，征调物资、劳工，为日军提供情报，直接涉及深圳、盐田地区。；佛山南海沦陷后投敌，组织伪维持会，后任伪南海县县长，为日军筹粮筹款，维持伪秩序。；在潮梅地区主办伪报，进行亲日宣传，诋毁抗日力量，其发行范围覆盖丰顺、梅县等地。；在广东沦陷区为日军掠夺物资，控制粮食配给，其经济掠夺活动波及河源、紫金地区，导致当地民众生活困苦。；在广东伪政权中负责肇庆、封开一带的行政督导，推行日军政策，镇压抗日活动。；在广宁组织伪政权，强征民夫为日军修筑工事，征收“治安费”中饱私囊。；在阳山县担任伪警察头目，带领伪警配合日军清乡，抓捕抗日群众。；在广东沦陷区从事亲日宣传，为日军粉饰侵略，活动范围包括清远、英德周边。；为日军筹款筹物，协助统制物资，压榨商民。；广东伪政权早期头目之一，参与组织伪维持会，其活动范围覆盖广州及北江地区，包括清远一带，为日军稳定占领区秩序。；组织妇女为日军服务，协助日伪宣传与后勤，动员妇女参加亲日活动。；韶关沦陷期间组织伪维持会，协助日军维持地方秩序、征调物资，是韶关本地直接投敌的汉奸头目。；在白云区推行保甲制度，监视居民，向日军举报抗日分子，协助征粮征税。；在清远沦陷区推行日语教育和奴化宣传，编写亲日教材，组织学生参加日军庆祝活动，影响范围包括佛冈部分学校。', '[]', '2026-09-10 09:57:14.026259', '2026-09-10 09:57:14.026259', '广东', '佛山', '三水', NULL, NULL, NULL, NULL, '');
