INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c84fb52c3b484f96912077bab12c1a1c', '石友三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北邢台宁晋；河北邢台；河北邢台新河；河北邢台；河北保定；安徽芜湖镜湖；吉林长春；陕西渭南；云南普洱西；天津河北；河北邢台信都；河北邢台；山东东营垦利；山东东营；安徽芜湖镜湖；安徽芜湖；河北衡水；陕西西安莲湖；云南普洱西；许昌地区；天津、河北；陕西榆林神木；云南普洱西；河北邢台；河北；河北邢台；河北石家庄赵县', '[]', '[]', '抗日战争时期', '', '原国民党将领，在邢台、巨鹿一带与日军勾结，后公开投敌，率部配合日军进攻抗日武装。；原西北军将领，在河北南部与日军秘密勾结，企图投敌，被高树勋处决，未及正式投日。；反复无常，最终投日，其部队在保定、满城一带参与“治安强化运动”，围剿八路军。；1940年投敌，其部队在冀东地区活动，虽未长期驻留，但曾参与反共摩擦。；在赵县一带反复无常，最终投靠日军，其部队曾协助日军袭击抗日游击队。；反复无常，最终投敌，在邢台东部地区袭击八路军，残害百姓。……（共涉及9个地区的犯罪记录）；伪职：伪三十九集团军总司令（原国民党冀察战区第十军团）；罪行：盘踞豫北、冀南一带，1940年投靠日本当汉奸，与日军签订“共同防共协定”。百姓流传歌谣：“石友三，大汉奸，给日本，把事办”；结局：1940年12月1日，被部下高树勋诱捕后活埋', '[]', '2026-09-10 09:57:14.003088', '2026-09-10 09:57:14.003088', '天津', '河北', '镜湖', NULL, NULL, NULL, NULL, '');
