INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c8c701d1a4ee44abbcfd7887f0150c23', '陈泰初', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳光明；广东深圳；广东_广州_黄埔；广东广州；辽宁沈阳大东；广东云浮郁南；广东汕头；广东广州增城', '[]', '[]', '抗日战争时期', '', '汪伪广东财政官员，负责伪政权财政税收，协助日军对广东经济进行统制和掠夺。；汪伪政权委任的宝安县县长，管辖今深圳、光明一带，推行伪化教育、征丁征粮。；任伪宝安县县长期间，推行日军政令，协助清乡、征粮，镇压抗日活动，其管辖范围包括今深圳、盐田地区。；汕头沦陷后组织伪维持会，任会长，协助日军统治潮汕地区。；在增城伪政府中任职，协助日军推行保甲、征粮等伪化措施。；任伪广东教育厅长，在广州推行奴化教育，篡改教材，灌输亲日思想。；任伪广东教育厅厅长期间，在广东包括深圳、罗湖地区推行奴化教育，篡改教材，宣传“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.025754', '2026-09-10 09:57:14.025754', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c8c8b856561a43ac905879fc4cc3398f', '马宝山', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏吴忠', '[]', '[]', '抗日战争时期', '', '在吴忠堡担任伪保甲长期间，为日伪特务提供落脚点，协助其进行策反和情报搜集，并向当地商户摊派‘抗日捐’中饱私囊。', '[]', '2026-09-10 09:57:14.003785', '2026-09-10 09:57:14.003785', '宁夏', '吴忠', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c8cb06d7e1e549fea6e181466e5e53ad', '张光璧', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济阳（今属济南）；山东', '[\"一贯道总道首\"]', '[]', '抗日战争时期', '汪伪政权', '伪职：一贯道总道首；罪行：抗战期间投靠日军、勾结汪伪政权，以传道为名散布媚日言论，扩大组织配合敌伪统治；济阳、济南为其传道基地之一；来源：澎湃新闻、济阳文史资料；备注：一贯道总道首；附逆会道门头目；伪任职务：一贯道总头目，投靠日伪；重庆设立分坛，借传道散布媚日言论，蛊惑民众，接受汪伪经费资助，在大后方制造消极舆论。。结局：抗战胜利后被国民政府通缉，潜逃', '[]', '2026-09-10 09:57:14.069243', '2026-09-10 09:57:14.069243', '山东', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c8d1a030e712405292e61eb831d58a7f', '李亚东', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东菏泽菏泽高；山东菏泽鄄城；山东菏泽巨野；江苏宿迁宿城；江苏宿迁；山东菏泽曹县；山东菏泽；山东菏泽曹县', '[]', '[]', '抗日战争时期', '', '日军侵占巨野后出面组织维持会，为日军筹粮筹款、维持地方伪秩序，协助建立伪政权。；组织伪保安团，协同日军扫荡宿迁周边抗日根据地，残害百姓。；在鄄城地区建立伪政权，配合日军对濮范观抗日根据地的扫荡。；在菏泽城区及周边村镇搜捕抗日人员，镇压民众抗日活动，配合日军进行治安强化运动。；曹县人，抗战期间投敌，任伪曹县县长并掌握伪军，配合日军扫荡鲁西南抗日根据地，在曹县、菏泽交界地区强征粮款、抓捕抗日人员。；在曹县地区统领伪警备队，配合日军清乡、扫荡，抓捕抗日人员，残害当地百姓。', '[]', '2026-09-10 09:57:14.018075', '2026-09-10 09:57:14.018075', '山东', '菏泽', '巨野', NULL, NULL, NULL, NULL, '');
