INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c93d0d9cf2db4bef8877f637adf864a8', '萧家璧', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西萍乡上栗；江西萍乡；江西宜春袁州；江西宜春；江西赣州会昌；云南普洱西；江西赣州于都；江西吉安井冈山；江西赣州章贡；江西赣州；江西吉安井冈山；江西赣州大余；江西赣州瑞金；江西吉安井冈山；江西赣州赣县；江西吉安井冈山；江西萍乡安源；江西吉安遂川；江西赣州定南；江西赣州上犹', '[]', '[]', '抗日战争时期', '', '抗战期间在宜春袁州一带投靠日军，组织伪维持会，协助日军征粮、拉夫、搜集情报，并参与镇压当地抗日民众。；长期在赣西南遂川、井冈山一带组织靖卫团和反共武装，配合国民党军及日军清剿抗日根据地，屠杀民众与游击队员；抗战时期在赣州周边地区维持日伪统治秩序，1949年后继续组织土匪武装抵抗解放军。；长期在井冈山周边地区进行反共活动，抗战期间与日伪勾结，组织地方武装，残害抗日军民，是井冈山地区著名的反动武装头目。；长期在赣西南遂川、上犹、崇义一带组织靖卫团和保安团队，配合国民党军清剿红军游击队；抗日战争时期继续把持地方武装，横征暴敛、迫害抗日进步人士和群众，是赣南地区有明确记载的反动地方武装头目。；长期在江西西部包括萍乡、上栗周边地区进行反共活动，抗战期间与日军暗中勾结，保存实力，袭击抗日游击队，迫害进步群众。；长期在赣西南遂川、井冈山、于都周边地区组织地主武装，镇压红军和革命群众；抗日战争时期破坏抗日民族统一战线，迫害抗日进步人士，袭击中共地方组织，是赣西南地区著名的反共顽固势力代表。；长期在赣西南遂川、上犹、大余一带组织地方武装，抗战期间与日伪势力暗通款曲，进攻抗日游击队，残害民众。；在江西遂川组织维持会并任伪县长，配合日军在赣西南地区的占领活动，为日军提供情报和物资，镇压当地抗日力量。；长期在赣西南遂川、井冈山、瑞金周边地区组织地主武装，配合国民党军及日军清剿红军游击队和抗日力量，残害革命群众，抗战期间继续坚持反共立场，破坏当地抗日民族统一战线。；长期在赣西南地区从事反共活动，抗战时期继续把持地方武装，与日伪势力及国民党顽固派相勾结，镇压抗日民众和进步力量，残害革命群众。；长期在赣西南遂川、上犹、赣州一带镇压红军和抗日力量，抗战期间与日军及伪政权勾结，组织地方武装配合国民党顽固派反共，残害民众，破坏抗日民族统一战线。', '[]', '2026-09-10 09:57:14.039642', '2026-09-10 09:57:14.039642', '江西', '吉安', '井冈山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c95bda0ebe384b19ad2cc06831c2fb26', '戚仁亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台芝罘；山东烟台；山东威海环翠；山东威海；山东威海乳山；山东威海；山东威海；山东威海威海临港经开区；山东威海；山东威海威海火炬高；山东威海', '[]', '[]', '抗日战争时期', '', '威海卫商界附逆者，协助日军控制威海卫经济，为日军采购物资，参与伪政权活动。；协助日军组织维持会，负责摊派粮款、招募伪职人员，为日军占领威海卫提供后勤支持。；组建伪警察队伍，协助日军搜查、逮捕抗日志士，镇压威海周边抗日活动。；在威海卫组织维持会，协助日军控制港口，与烟台芝罘地区伪政权有联系。；在威海卫推行奴化教育，编写和采用亲日教材，组织师生参加日伪宣传活动，为日军殖民统治培养顺民。；在威海卫沦陷期间依附日伪，控制商会为日军筹措物资，配合经济统制政策。', '[]', '2026-09-10 09:57:14.012998', '2026-09-10 09:57:14.012998', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
