INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c9b661ad9a384cedb40802383238a870', '陈明', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江德安；江西赣州大余；江西南昌；江西赣州宁都；江西赣州赣县；山西阳泉城区；广东深圳坪山；广东深圳宝安；广东深圳光明；广东深圳福田；海南乐东；福建漳州平和；福建漳州诏安；江苏南京；广东深圳南山；江西南昌西湖；江西南昌；江西赣州；山西阳泉城区；江西上饶德兴；江西上饶；海南保亭；江西上饶弋阳；云南普洱西；广西桂林恭城；云南普洱西；江西九江修水；江西九江；江西南昌青云谱；湖南衡阳常宁；江西宜春宜丰；江西九江', '[]', '[]', '抗日战争时期', '', '在九江地区组织伪维持会，协助日军控制长江航运和物资运输，迫害抗日志士。；参与伪江西省政府事务，协助日军在江西沦陷区推行奴化教育 and 经济掠夺。；在青云谱地区组织伪维持会，为日军带路、征粮、派夫，协助日军控制青云谱及周边乡村。；日军侵入赣州期间，协助伪赣县维持会组织伪政权，为日军筹集物资、招募劳工，参与对赣州城区居民的管控。；在南昌伪政权任职期间，受命联络赣南各县伪组织，推动建立伪基层政权，为日军搜集赣南情报。；担任伪福田乡乡长，执行日军征粮、征夫命令，协助日军在福田地区建立保甲连坐制度，迫害抗日群众。；光明墟（今光明区）伪保甲长，协助日军征粮、抓丁，监视抗日活动。；1945年日军窜扰宁都时，出面组织维持会，张贴安民告示，为日军带路、征夫。；任伪德安县警察局局长期间，带领伪警察配合日军搜捕抗日人员，勒索民众，维持德安日占区治安。；带领伪警察在保亭及周边山区搜剿抗日游击队，迫害抗日家属。；感恩县与乐东接壤，其维持会为日军在乐东周边征粮拉夫，协助日军行动。；日军侵占宝安后出面组织维持会，为日军征粮派款、维持治安，协助推行伪化统治。；日军侵占宝安后，出面组织伪维持会，协助日军征粮、拉夫、维持治安，镇压抗日群众。；诏安沦陷期间组织维持会，协助日军控制闽粤边界地区。；在南头地区推行保甲制度，协助日军登记户口、征收捐税、监视民众，举报抗日人员。；广西沦陷期间，任伪教育会长，推行奴化教育。；日军占领九江后，出任伪九江县政府县长，推行伪化统治，协助日军征发物资、镇压抗日活动。；协助日军控制南京人口流动；在日军占领下主持伪商会，强制摊派物资与款项，协助日军对南昌工商业进行统制与掠夺。；江西赣州人，1944年日军侵占赣州期间，与张一清共同组织伪赣州维持会，任副会长，协助日军统治赣州城区。；在湖南沦陷区推行奴化教育，编写亲日教材，组织学生参加日军宣传活动。；上饶沦陷期间维持会系统有少数附逆人员，但姓名与事迹多未系统整理，难以确证。', '[]', '2026-09-10 09:57:14.028991', '2026-09-10 09:57:14.028991', '广东', '深圳', '光明', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('c9cdb7103cbb40daa123400bfe8e7bb2', '彭德怀', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南常德汉寿；湖南益阳南县；湖南常德；湖南_怀化_怀化洪江管理；湖南_湘潭_湘潭高；湖南_湘潭_韶山；湖南湘潭；湖南_邵阳；湖南_郴州_宜章；湖南_郴州_桂阳；湖南_郴州_汝城；湖南岳阳华容；湖北鄂州华容；湖南湘潭；湖南株洲石峰；湖南益阳沅江；湖南岳阳汨罗；湖南岳阳君山；湖南岳阳湘阴；湖南怀化靖州；湖南岳阳云溪；湖南邵阳新邵；湖南常德石门；湖南常德；湖南怀化溆浦；云南普洱西；湖南湘西吉首；湖南湘潭岳塘；湖南娄底新化；湖南娄底；湖南岳阳临湘；湖南岳阳；湖南湘西泸溪', '[\"注：此名为误传，实无此人附逆\", \"注：此条为误收，已删除\", \"注：非汉奸，此处不列\", \"注：此处为误列，实际无汉奸记录\", \"注：此条为误传，实际无汉奸记录，已剔除\", \"注：非汉奸，此处不应列入\"]', '[]', '抗日战争时期', '', '在湖南伪维持会系统中任职，协助日军在岳阳等地推行保甲连坐，镇压抗日活动。；无；湖南湘潭人，八路军副总司令，抗战期间在华北领导抗日斗争，与湖南有籍贯关联，但为抗日将领，非汉奸。；在湘西地区组织伪维持会联合会，协调各县伪维持会为日军服务，参与伪政权活动。；以商会名义为日军筹措物资，协助日伪经济统制，压迫商户，属经济领域附逆者。；常德地区沦陷期间，有地方维持会人员协助日军维持秩序、征发物资，但具体姓名与事迹记载零散，常德本地汉奸名录多散见于地方志。；在湘阴地区协助日军推行伪化，组织伪自卫团，配合日军对洞庭湖抗日游击区进行扫荡。；在湘阴县协助日军建立伪维持会，参与征发民夫、物资，支持日军军事行动。；经查，新化、娄底地区在抗战时期有明确记载的汉奸名录极少，地方志中多记载抗日志士而非附逆者。；岳阳华容交界地区伪保长，为日军征粮派款，监视村民，协助日军维持基层统治。；无。彭德怀为八路军副总司令，抗日将领，与汉奸无关。此条仅为避免混淆而设，实际不应列入汉奸名录。；无可靠汉奸记录，此条为误置占位，不应视为汉奸；无；湖南湘潭人，八路军副总司令，抗日将领，非汉奸。；经检索，彭德怀为抗日将领，非汉奸，此处仅作排除说明，不列入汉奸名录。', '[]', '2026-09-10 09:57:14.057686', '2026-09-10 09:57:14.057686', '湖南', '娄底', '新化', NULL, NULL, NULL, NULL, '');
