INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ca13f4684de64c20ab0453abbcb55563', '卢万寿', NULL, NULL, NULL, NULL, 'exact', 'exact', '邯郸', '[]', '[]', '抗日战争时期', '', '伪职：伪邯郸警察所长；配合特务李积玉抓捕抗日人员，参与插箭岭屠杀干部事件。；结局：镇反时期公审处决；伪职：伪邯郸警察所长；配合特务抓捕抗日人员，参与插箭岭屠杀干部事件。；结局：镇反公审处决', '[]', '2026-09-10 09:57:14.067366', '2026-09-10 09:57:14.067366', '河北', '邯郸', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ca3039d50ee947dc8a305c23cf44f892', '王益三', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏盐城滨海；江苏盐城射阳；江苏盐城响水', '[]', '[]', '抗日战争时期', '', '任伪区长期间，为日军提供情报，抓捕抗日人员，强征民夫修筑工事。；率伪保安队多次袭击新四军游击队，抓捕抗日群众，参与“清乡”行动，烧毁村庄，掠夺财物。；充当日军特务，在盐城、滨海一带发展汉奸情报网，多次告密导致抗日干部被捕牺牲。', '[]', '2026-09-10 09:57:14.036431', '2026-09-10 09:57:14.036431', '江苏', '盐城', '响水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ca3e6cda8ab64939ae57513f901a13e5', '赵荫棠', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南商丘民权；河南商丘；河南驻马店确山；辽宁沈阳大东；河南郑州惠济；辽宁沈阳新民；山东_济宁_金乡', '[]', '[]', '抗日战争时期', '', '山东人，抗战期间任伪山东省教育厅厅长，推行奴化教育，篡改教材，向学生灌输亲日思想。；在伪河南省政府中负责宣传，主办亲日报刊，散布“中日亲善”“大东亚共荣”言论，为日军侵略张目。；负责河南沦陷区伪宣传，为日军侵略辩护，推行奴化宣传，其宣传网络覆盖商丘、民权等豫东地区。；在伪河南省宣传系统及郑州新民会任职，参与亲日宣传、奴化教育，协助日军控制舆论。', '[]', '2026-09-10 09:57:14.015813', '2026-09-10 09:57:14.015813', '河南', '商丘', '民权', NULL, NULL, NULL, NULL, '');
