INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('caa16dd928e54a3f977534fc16fb2967', '张哲生', NULL, NULL, NULL, NULL, 'exact', 'exact', '睢宁全境', '[]', '[]', '抗日战争时期', '', '伪职：伪睢宁县县长；罪行：伪县长任期三年，执行日军清乡政策，出动伪县大队配合日军围剿抗日武装，迫害爱国群众。；结局：抗战胜利后逮捕法办。', '[]', '2026-09-10 09:57:14.080117', '2026-09-10 09:57:14.080117', '江苏', '徐州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('caa9b65e1bf542e6ac88f5c362d3a20e', '黄德', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南乐东；广西桂林恭城；云南普洱西', '[]', '[]', '抗日战争时期', '', '广西沦陷期间，任伪维持会会长，协助日军维持治安。；广西沦陷期间，任伪保安大队长，配合日军。；崖县与乐东相邻，其伪政权配合日军对乐东地区进行经济封锁和军事扫荡。', '[]', '2026-09-10 09:57:14.032327', '2026-09-10 09:57:14.032327', '广西', '桂林', '恭城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cac7b43503b4410195d98c3b16a95c47', '白俊卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北沧州；河北沧州运河', '[]', '[]', '抗日战争时期', '', '在泊镇（今泊头）为日军服务，提供情报，协助日军控制运河交通线。；任伪沧州道尹期间，管辖包括河间在内的各县伪政权，积极推行日伪‘保甲制度’，搜刮民财，支持日军经济掠夺。', '[]', '2026-09-10 09:57:14.042966', '2026-09-10 09:57:14.042966', '河北', '沧州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cac9f5a880024927a772bfb36704df51', '张培植', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '作为日伪政权在邯郸的华人顾问，协助日军推行“治安强化运动”，在丛台区设立情报点，策反抗日人员，并参与经济统制，掠夺当地物资。', '[]', '2026-09-10 09:57:14.075586', '2026-09-10 09:57:14.075586', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cacd3e61d4ba4e9d8a624c445978d6a3', '周鸿俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉武昌；湖北武汉江夏；湖北武汉武昌；湖北武汉；湖北武汉黄陂；湖北武汉；辽宁沈阳大东；湖北武汉江汉；湖北武汉；湖北_武汉_蔡甸；湖北武汉洪山；湖北武汉武昌', '[]', '[]', '抗日战争时期', '', '抗战期间任伪武昌县县长，在武昌及江夏周边地区为日军服务，推行伪政。；抗战期间在武汉伪政权中任职，负责社会事务，协助日军控制民众团体和物资分配。；统辖湖北伪保安部队，配合日军对抗日根据地和游击区进行扫荡、清乡。；任伪武汉特别市总工会理事长，协助日军控制工人，镇压工运，征发劳工为日军服务。；组织伪保安大队，配合日军在武昌地区清乡、扫荡抗日武装。；推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害湖北及武汉青少年。；投敌后任伪湖北省教育厅厅长，在武汉及湖北地区推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；抗战期间投敌，任伪湖北省政府警务处处长，在武汉及湖北地区协助日军维持治安，镇压抗日活动。；任伪武昌市政处处长，协助日军管理武昌市政，征发民工，为日军军事工程服务。', '[]', '2026-09-10 09:57:14.056603', '2026-09-10 09:57:14.056603', '湖北', '武汉', '武昌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cad3e07eb7ee4081bb229d405ee33a54', '董玉卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（经济汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：经济汉奸；罪行：经济汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.079816', '2026-09-10 09:57:14.079816', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cae69dc12c3d4bcf98374da39aa87220', '王聘三', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州贵阳修文；陕西汉中勉县', '[]', '[]', '抗日战争时期', '', '在沔县担任保甲长期间，为日军征派劳役、粮草，监视当地民众言行，举报抗日嫌疑人员。；日军窜扰修文期间，组织维持会为日军带路、筹粮，并协助建立伪保甲组织。', '[]', '2026-09-10 09:57:14.062624', '2026-09-10 09:57:14.062624', '贵州', '贵阳', '修文', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('caec93be85494fc5add5941bc3d65678', '滕松柏', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江佳木斯前进；黑龙江佳木斯；黑龙江伊春汤旺；黑龙江佳木斯汤原；黑龙江佳木斯；黑龙江双鸭山', '[]', '[]', '抗日战争时期', '', '伪满时期任三江省协和会会长，驻佳木斯，配合日伪推行殖民思想宣传、劳工征集和物资统制，为日本侵略政策服务。；在汤原县任伪警察署长，直接参与对汤旺河抗日游击根据地的围剿，逮捕和杀害抗日群众，是当地伪警系统的重要汉奸。；在伪三江省（佳木斯）任职期间，负责警务与治安，配合日军镇压抗日活动，推行保甲连坐制度。；伪满时期任三江省警务厅厅长，驻佳木斯，统管三江地区伪警察系统，积极推行保甲连坐制度，配合日军镇压抗日力量，抓捕抗日志士。；任伪三江省警务厅厅长期间，指挥伪警察配合日军在双鸭山、友谊一带镇压抗日活动。', '[]', '2026-09-10 09:57:14.065372', '2026-09-10 09:57:14.065372', '黑龙江', '伊春', '汤旺', NULL, NULL, NULL, NULL, '');
