INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb7311e48a2b48c7871c4643cd3daee9', '阮振铎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江大庆让胡路；黑龙江齐齐哈尔；辽宁葫芦岛；辽宁抚顺望花；辽宁抚顺；辽宁辽阳弓长岭；辽宁辽阳；辽宁抚顺；辽宁_沈阳；辽宁辽阳；辽宁鞍山；吉林长春双阳；吉林长春；吉林；辽宁营口大石桥；黑龙江_哈尔滨_松北；辽宁_沈阳_浑南；吉林白山；吉林长春德惠；吉林长春；辽宁_抚顺_新宾；吉林长春宽城；吉林长春；辽宁_大连_旅顺口；辽宁辽阳灯塔；辽宁抚顺；辽宁铁岭；辽宁_沈阳_大东；辽宁盘锦；山东聊城茌平；山东聊城；辽宁_沈阳_苏家屯；黑龙江哈尔滨松北；辽宁阜新彰武；辽宁阜新；吉林经开区；黑龙江鹤岗兴安；吉林长春公主岭；辽宁阜新海州；山西阳泉矿区；辽宁本溪；辽宁沈阳；吉林长春长春高；吉林长春；辽宁_沈阳_和平；吉林长春；吉林白城通榆；吉林；辽宁鞍山；吉林、辽宁', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪奉天省省长、伪满外交部大臣，伪满后期高官。结局：抚顺战犯管理所关押，1973 年特赦释放；推行日语教育和“王道乐土”宣传，抹杀东北人民民族意识。；在长春推行奴化教育，强制学习日语，抹杀中国民族意识。；推行奴化教育，篡改历史，在长春及吉林各地学校强制灌输“王道乐土”思想。；在长春负责伪满交通建设，为日军运输军需，协助“讨伐”抗联。；在吉林、长春推行文化专制，查禁抗日书刊，强制推行“王道乐土”宣传。……（共涉及36个地区的犯罪记录）；伪职：伪满外交部大臣、文教部大臣；罪行：办理对日外交，推行奴化教育，美化伪满统治。；结局：苏军逮捕，抚顺战犯管理所，后期特赦释放。', '[]', '2026-09-10 09:57:13.999472', '2026-09-10 09:57:13.999472', '吉林', '白城', '通榆', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb748d75468544dc958cbc9c4cdc303e', '林旭', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建泉州金门', '[]', '[]', '抗日战争时期', '', '金门沦陷后出面组织维持会，为日军征调民夫、粮食，协助建立伪基层保甲，压制金门民众抗日活动。', '[]', '2026-09-10 09:57:14.061844', '2026-09-10 09:57:14.061844', '福建', '泉州', '金门', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb85cb8c5ec34ece870d4f3e3c5ec4c5', '马玉堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台南宫；江苏徐州铜山；河北石家庄石家庄循环化工园；河北_邢台_清河；河北；河北石家庄藁城；河北衡水枣强；江苏淮安淮阴；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '在现循环化工园区一带强征壮丁，为日军修建军事设施，迫害抗日家属。；专门刺探抗日情报，抓捕地下党员，刑讯逼供，罪大恶极。；专门搜集八路军和抗日政府情报，多次导致抗日人员被捕牺牲，民愤极大。；率伪团配合日军对饶阳、武强交界处的抗日游击区进行反复“清剿”，杀害多名抗日村干部。；率警备队多次袭击抗日村庄，烧杀抢掠，杀害抗日军属，罪大恶极。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.035347', '2026-09-10 09:57:14.035347', '江苏', '徐州', '铜山', NULL, NULL, NULL, NULL, '');
