INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb99d9ca635e47e3b21171557bed5da7', '王砚农', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊坊子；山西阳泉矿区；山东东营东营经开区；山东东营利津；山东东营利津；辽宁沈阳新民；山东淄博淄川；山东潍坊诸城；山东潍坊安丘；山东潍坊高密', '[]', '[]', '抗日战争时期', '', '利用新民会进行奴化宣传，组织训练伪青年团、伪合作社，为日军搜集情报并推行配给制度，控制利津城乡经济。；坊子沦陷后组织伪维持会，为日军维持坊子矿区与铁路沿线秩序，征发劳工、摊派粮款。；日军侵占淄川后率先组织维持会，为日军筹粮筹款，诱降地方士绅。；利津县（今属东营市）伪政权头目，推行日军殖民统治，强征劳工、粮食，配合日伪对黄河三角洲地区的控制。；日军侵占诸城后出面组织维持会，为日军筹粮筹款、维持地方伪秩序，协助日军推行保甲连坐。；高密沦陷后组织维持会，任伪县长，为日军征粮征夫，推行伪化教育，配合日军扫荡。', '[]', '2026-09-10 09:57:14.011914', '2026-09-10 09:57:14.011914', '山东', '东营', '东营经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb9c9097e2e94341a0de290726a49051', '梁某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州三江；广西柳州；广西贵港平南；广西贵港桂平；广东江门恩平；广西百色', '[\"梁耀南\", \"名不详\"]', '[]', '抗日战争时期', '', '在桂平沦陷期间协助日军维持地方伪秩序，为日军征调物资。；在恩平伪政权中掌管警察，配合日军搜捕抗日人员，镇压民众反抗。；柳州沦陷期间充任伪警察便衣，协助日军搜捕抗日分子和地下工作者。；日军占领百色期间出任伪警察局长，协助日军维持殖民统治，登记户口、发放良民证，并参与抓捕抗日人士。', '[]', '2026-09-10 09:57:14.028623', '2026-09-10 09:57:14.028623', '广西', '柳州', '三江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb9e251b5d274d5090aca8e7303d5c08', '周文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原尖草坪；江苏连云港灌云；陕西咸阳秦都；浙江丽水云和；浙江丽水；江西抚州南城；辽宁沈阳大东；河北保定涿州；浙江_丽水_松阳；湖北十堰竹溪；广东肇庆；辽宁沈阳大东；辽宁沈阳大东；江苏连云港连云港经开区；安徽_马鞍山；浙江金华；江苏常州金坛；安徽铜陵；山西、河北、辽宁；广西贺州；广西贺州钟山；江苏盐城；河北_保定_定兴；河北保定望都；河北_廊坊_安次；黑龙江鸡西；黑龙江七台河勃利；浙江_湖州_安吉；黑龙江绥化安达；安徽安庆大观；贵州贵阳修文；山西朔州怀仁；山西朔州；黑龙江伊春；黑龙江伊春汤旺；山西朔州；山西朔州山阴；河北沧州运河；天津河西；辽宁营口；江苏宿迁泗洪；河南郑州中牟；河北_廊坊_香河；浙江_丽水_莲都；河南许昌建安；河南许昌；辽宁沈阳大东；河北保定；黑龙江伊春南岔；黑龙江伊春；四川成都武侯；四川成都；江西宜春宜丰；江西宜春樟树；江苏镇江句容；江苏南通海安；黑龙江七台河茄子河；黑龙江七台河；江苏_盐城_响水', '[\"投敌后\"]', '[]', '抗日战争时期', '', '任伪太原县知事，管辖包括尖草坪在内的乡村地区，推行保甲制度，强征壮丁。；日军占领山阴后出任维持会长，为日军筹集粮款，出卖抗日情报。；在朔州、怀仁一带为日军推行“以华制华”政策，组织汉奸宣传队，破坏抗日统一战线，并参与策划对抗日根据地的经济封锁。；原为保定商人，投日后充当日军翻译，组建密探网，在白沟新城、容城、雄县等地诱捕抗日志士，直接参与刑讯逼供。；效忠日军，指挥伪警察抓捕抗日地下党员，破坏交通线，协助日军建立保甲制度。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.002068', '2026-09-10 09:57:14.002068', '四川', '成都', '武侯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cb9f264ef376415e94bef22ea9723db2', '乌云达赉', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古兴安科尔沁右翼前旗；内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在伪兴安北省警察系统任职，协助日军镇压呼伦贝尔地区抗日活动。；蒙古族亲日官僚，在伪兴安南省任职期间负责行政、财政事务，协助日本掠夺兴安地区资源，推行保甲制度，涉及科尔沁右翼前旗。', '[]', '2026-09-10 09:57:13.987841', '2026-09-10 09:57:13.987841', '内蒙古', '呼伦贝尔', '阿荣旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cba1017a78504e88812fd5f5eea19b74', '武述之', NULL, NULL, NULL, NULL, 'exact', 'exact', '太谷', '[]', '[]', '抗日战争时期', '', '伪职：伪太谷县县长；罪行：组建太谷伪政权，修筑炮楼，盘剥百姓，配合日军扫荡太谷山区。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.072487', '2026-09-10 09:57:14.072487', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cba319413f5648d686d63efd51080819', '提乾元', NULL, NULL, NULL, NULL, 'exact', 'exact', '诏安县城（1939 年短期沦陷）', '[]', '[]', '抗日战争时期', '', '伪职：诏安临时维持会民政委员长；罪行：黄大伟伪军占领诏安期间出面投敌，组建临时维持会，征粮派款，胁迫商户纳贡，为日伪军搜罗物资，迫害爱国群众。；结局：国军收复诏安后捕获公审处决。', '[]', '2026-09-10 09:57:14.076649', '2026-09-10 09:57:14.076649', '福建', '漳州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cba5ffe36f5c45649531d8e26257dd79', '汪叔度', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆岳西；安徽铜陵枞阳；安徽安庆潜山；安徽安庆怀宁；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '汪伪政权委任的潜山县伪县长，在潜山及周边地区推行伪化行政，配合日军清乡与物资掠夺。；汪伪政权在安庆的文化宣传负责人，主办伪《安庆日报》，为日军侵略张目，宣传“大东亚共荣圈”，属文化宣传领域附逆者。；桐城沦陷区伪政权头目，任伪桐城县知事，协助日军统治桐城、枞阳一带，推行奴化教育。', '[]', '2026-09-10 09:57:14.007645', '2026-09-10 09:57:14.007645', '安徽', '安庆', '岳西', NULL, NULL, NULL, NULL, '');
