INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbc005aa7a1d4b2d9482c27ab32355ba', '沈广训', NULL, NULL, NULL, NULL, 'exact', 'exact', '台前县（原寿张县）', '[]', '[]', '抗日战争时期', '', '伪职：伪寿张县维持会长→伪警备大队副队长→伪县长；罪行：1898年生。1939年日军占领寿张城后投敌，历任伪维持会长、警备大队副队长和伪县长。效忠日军，网罗兵痞、土匪和社会流氓，扩充汉奸武装，组建警备大队，多时辖17个中队；结局：1945年被冀鲁豫军区八分区主力部队在阳谷县城活捉，同年8月处决', '[]', '2026-09-10 09:57:14.087000', '2026-09-10 09:57:14.087000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
