INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbc600b870464e238e522aad48f776fe', '朱亦飞', NULL, NULL, NULL, NULL, 'exact', 'exact', '瑞安县城', '[]', '[]', '抗日战争时期', '', '伪职：伪瑞安维持会委员；罪行：瑞安沦陷时期伪维持会骨干，协助日军勒索商户，征集粮草物资。；结局：抗战胜利后逮捕判刑。', '[]', '2026-09-10 09:57:14.080110', '2026-09-10 09:57:14.080110', '浙江', '温州', NULL, NULL, NULL, NULL, NULL, '');
