INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbdb2b4acd8e45019f8c244a20b6ece6', '程仲勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳大东；山东淄博；山东济南', '[]', '[]', '抗日战争时期', '', '在济南推行奴化教育，篡改教材，组织师生参加日伪宣传活动。；协助日军控制淄博工商业，为日伪筹集物资、资金，配合经济统制。；推行奴化教育，在济南及山东各地学校强制日语教学，宣传“大东亚共荣”。', '[]', '2026-09-10 09:57:14.015195', '2026-09-10 09:57:14.015195', '山东', '淄博', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbe33b9190654909b777f29bef9a71e3', '萧瑞臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南_新乡；河南新乡原阳；河南安阳；青海黄南河南；青海黄南河南；河南郑州；河北；河南新乡延津；河南新乡；河南新乡；青海黄南河南；河南南阳；河南新乡；河南开封；安阳（伪彰德县）；青海黄南河南；河南开封；河南焦作；河南安阳林州；河南安阳；河南新乡封丘；河南新乡；河南安阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪河南省首任省长（伪河南省自治政府），伪政权初创。结局：抗战胜利后被捕，病死狱中；伪职：伪彰德县治安维持会会长→伪河南省自治政府主席→伪河南省公署省长兼首任伪彰德县知事；罪行：1937年11月率先出城迎敌，组建彰德治安维持会；当月成立伪河南省自治政府任主席；强征粮食、棉花、民夫供给日军；推行保甲制度，配合日军扫荡；结局：抗战胜利后被国民政府逮捕，以汉奸罪判刑', '[]', '2026-09-10 09:57:14.047192', '2026-09-10 09:57:14.047192', '青海', '黄南', '河南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbe50b1e3fa940239a9ad0fa8bfede3d', '陈子实', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东江门台山；广东江门', '[]', '[]', '抗日战争时期', '', '江门沦陷后组织伪维持会，为日军提供情报、物资，协助建立伪基层政权，压迫江门及新会一带民众。', '[]', '2026-09-10 09:57:14.028587', '2026-09-10 09:57:14.028587', '广东', '江门', '台山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbf17496f1ee471d985dcf1ca71d2bad', '黄志远', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州苍南；浙江温州；江苏南通海安；江苏南通；江苏南通南通经开区；江苏南通', '[]', '[]', '抗日战争时期', '', '主持南通地区“清乡”工作，设立封锁线，搜捕抗日分子，屠杀无辜百姓。；领导特工在南通、海安地区刺探情报，绑架暗杀抗日人士。；率伪军配合日军在温州、苍南等地进行“清乡”，杀害多名抗日游击队员。', '[]', '2026-09-10 09:57:14.034133', '2026-09-10 09:57:14.034133', '江苏', '南通', '南通经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbf406fabd7a467090b4c7d82f03e40f', '张凤岐', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵郊区；安徽铜陵；汤原、佛山（嘉荫）；内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '伪职：伪特务，原抗联人员；罪行：随同王秀峰伪装山货商人潜入山林，刺探赵尚志小队行踪，传递情报给日伪警察机关。；结局：解放后被管制惩处。', '[]', '2026-09-10 09:57:13.989668', '2026-09-10 09:57:13.989668', '内蒙古', '呼伦贝尔', '阿荣旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cbff2f1d4f134df7bec069e39d8a285c', '曹明阵', NULL, NULL, NULL, NULL, 'exact', 'exact', '益阳县；湖南益阳赫山；湖南益阳', '[]', '[]', '抗日战争时期', '', '伪职：益阳县团防局局长、益阳保安团长、常德桃源益阳联防主任；罪行：益阳县沧水铺四方山人。1926年起镇压革命，马日事变后卷土重来重掌县团防局。1930年率保安团队恭迎湖南省政府主席何键。抗战爆发后寻机投靠日本人，退隐沧水铺一带，耍阴谋放暗枪，与抗日组织作对。1938年率部拦路抢劫国军43师武器弹药；结局：1939年被国军43师诱捕押送长沙；同年4月湖南省高等法院以抢劫国军枪支、破坏抗战等罪名判处死刑；4月16日在长沙小吴门外被枪决', '[]', '2026-09-10 09:57:14.059373', '2026-09-10 09:57:14.059373', '湖南', '益阳', '赫山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc0674a3fa8444028a25172f164b7420', '矮子黄麻子', NULL, NULL, NULL, NULL, 'exact', 'exact', '武阳本地人', '[]', '[]', '抗日战争时期', '', '伪职：伪保长；罪行：为日军引路围剿抚河沿岸村庄；结局：暂无明确结局记载', '[]', '2026-09-10 09:57:14.088119', '2026-09-10 09:57:14.088119', '江西', '南昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc0cf5906ada4d4fbcee35aa9350c96b', '魏运衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪本溪县县长；罪行：主持本溪县伪公署，推行集团部落，配合日伪对赛马集、草河掌抗联根据地讨伐，强征劳工粮食本溪纪检监...。；结局：抗战胜利逮捕，汉奸罪判刑。', '[]', '2026-09-10 09:57:14.088080', '2026-09-10 09:57:14.088080', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc1121d2ad574d2baae4a024f0b37376', '王伯恭', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆迎江；安徽安庆；安徽马鞍山；安徽马鞍山当涂；江苏南通；江苏苏州苏州工业园；江苏南京六合；安徽安庆；安徽芜湖镜湖；安徽芜湖；安徽芜湖芜湖经开区；安徽芜湖；安徽_芜湖；江苏常州金坛；江苏镇江丹阳；江苏镇江', '[]', '[]', '抗日战争时期', '', '指挥伪军在南通、海安一带“扫荡”，杀害抗日军民，烧毁村庄。；协助刘迈维持治安，向日军提供抗日分子名单。；指挥伪警察协助日军搜捕抗日分子，破坏地下交通线，参与镇压镇江地区群众反抗。；投靠日军，任丹阳伪县长，组织伪保安队，协助日军‘清剿’新四军游击队，强征粮食和劳役。；率伪保安队配合日军扫荡，捕杀抗日军民，抢劫财物，民愤极大。；在安庆迎江地区任伪县知事，推行日伪政策，强征劳役，迫害抗日家属。；继张仁蠡后任伪芜湖县长，推行保甲制度，协助日军进行经济封锁和物资搜刮。；投靠日军，任当涂县伪县长，协助日军推行“治安强化”运动，强征粮税，镇压抗日民众。；巧立名目征收各种捐税，搜刮民财，供日军和伪政权挥霍。；利用司法权力迫害抗日人士，判处抗日分子刑罚，维护日伪统治。；在芜湖推行保甲制度，强化汉奸统治，参与日军“扫荡”行动，抓捕并杀害抗日分子。；继任六合伪知事，协助日军扫荡新四军游击队。', '[]', '2026-09-10 09:57:14.006383', '2026-09-10 09:57:14.006383', '安徽', '安庆', '迎江', NULL, NULL, NULL, NULL, '');
