INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc594efb0f7b49edb1bf4c43d952ab23', '韩一峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪献县县长；五一大扫荡后重建伪政权，疯狂搜捕冀中八分区干部。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.086825', '2026-09-10 09:57:14.086825', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc63a5396b0143418a08b546f3e1049e', '刘文卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北潜江；辽宁沈阳大东；山西阳泉城区；湖北黄石；湖北黄石黄石港；湖北荆门东宝；河南信阳；湖北襄阳；陕西汉中；湖北黄石大冶；山西阳泉矿区；湖北荆州；湖北荆州沙市；湖北十堰房县；湖北随州；湖北随州随县', '[]', '[]', '抗日战争时期', '', '收编地方武装投靠日军，任伪保安团团长，配合日军扫荡随县周边抗日根据地。；在信阳北部确山组织维持会，为日军提供情报、粮草，协助建立伪政权。；在郧县一带依附日军，组织伪维持会，为日军筹粮、派款、拉夫，并协助推行伪化统治。；在沦陷区推行奴化教育，改编教材，向学生灌输亲日思想。；在荆门城区及掇刀石等地搜捕抗日志士，勒索商户，推行“良民证”制度，协助日军维持占领秩序。；充任伪警察头目，配合日军搜捕抗日人员，镇压民众，控制鄂城城区及周边治安。；依附日军，控制黄石港商业物资，为日军采购军需，协助经济封锁，压迫商户。；担任伪警察局长期间，配合日军搜捕抗日人士，镇压民众反抗，维护日伪在汉中的统治秩序。；沙市沦陷后组织伪维持会，为日军筹款、征粮、招募劳工，并协助设立慰安所。；大冶沦陷后投敌，组织伪维持会并任伪大冶县县长，协助日军控制大冶矿区及地方事务。；推行奴化教育，强制学校使用伪教材，宣传“大东亚共荣圈”。；在襄阳基层推行保甲制度，为日军摊派捐税、清查户口。', '[]', '2026-09-10 09:57:14.046148', '2026-09-10 09:57:14.046148', '河南', '信阳', '房县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc6e4fd6d4b8477aab9acbce33438b84', '孙耀武', NULL, NULL, NULL, NULL, 'exact', 'exact', '临晋', '[]', '[]', '抗日战争时期', '', '伪职：伪临晋县县长；罪行：维持临晋伪统治，压榨百姓。；结局：光复后判刑', '[]', '2026-09-10 09:57:14.070263', '2026-09-10 09:57:14.070263', '山西', '运城', NULL, NULL, NULL, NULL, NULL, '');
