INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cc9011192f894d8fb91a74900e21dfef', '包永伦', NULL, NULL, NULL, NULL, 'exact', 'exact', '七台河大四站、岚棒山一带', '[]', '[]', '抗日战争时期', '', '伪职：伪勃利县大四站警察讨伐队警尉、特务头目；罪行：带领伪讨伐队进山清剿二路军，包围杀害抗联五军副官长冯丕让；长期搜捕岚棒山根据地地下救国会群众，捣毁多处密营。；结局：解放后镇压反革命公审处决。', '[]', '2026-09-10 09:57:14.085898', '2026-09-10 09:57:14.085898', '黑龙江', '七台河', NULL, NULL, NULL, NULL, NULL, '');
