INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cca049b64b4f46649003cdd624f5f82d', '郑海涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；湖北荆门；重庆南岸；湖北黄石铁山；湖北黄石；江苏淮安金湖；湖北恩施鹤峰', '[]', '[]', '抗日战争时期', '', '建立密探网，多次向日军报告新四军行踪，导致数次战斗失利。；统领南岸伪自卫团，配合日军清乡，搜捕抗日分子，维护日伪在南岸的统治秩序。；大冶县伪教育科头目，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军在黄石、铁山地区的文化侵略服务。；组织商户为日军及伪政权筹集物资，垄断市场，配合经济封锁，牟取暴利。；任伪襄阳县保安大队大队长，率部配合日军在襄州、樊城一带进行扫荡，捕杀抗日军民。；在十里铺为日军搜集情报，带领伪军搜捕抗日干部和家属。', '[]', '2026-09-10 09:57:14.036368', '2026-09-10 09:57:14.036368', '江苏', '淮安', '金湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cca30734a867489f8ed046506c3c87b3', '无记录', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽马鞍山花山；安徽马鞍山', '[]', '[]', '抗日战争时期', '', '经查现存公开历史档案及地方志，马鞍山市花山区（含原当涂县部分区域）在抗日战争时期无明确记载的、经司法审判或党史部门认定的汉奸个人名录。该地区当时主要为游击区与日占区交错地带，日伪基层政权人员多为外地调任或临时委派，且战后档案散佚，未形成系统名单。', '[]', '2026-09-10 09:57:14.011214', '2026-09-10 09:57:14.011214', '安徽', '马鞍山', '花山', NULL, NULL, NULL, NULL, '');
