INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccb3f326e480459eb0f49cdbdbf3a53c', '曲焕文', NULL, NULL, NULL, NULL, 'exact', 'exact', '赤峰', '[]', '[]', '抗日战争时期', '', '伪职：伪赤峰警察署署长；随同讨伐队下乡，勒索、抓捕抗日家属。；结局：1945 被俘处决', '[]', '2026-09-10 09:57:14.087940', '2026-09-10 09:57:14.087940', '内蒙古', '赤峰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccb5bdcf858d4eb0b90e6c50a0477f2f', '王明五', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区', '[]', '[]', '抗日战争时期', '', '在郑州沦陷期间任伪警察头目，协助日军镇压抗日活动、搜捕抗日人员、维持城区治安，直接服务于日军在郑州的殖民统治。', '[]', '2026-09-10 09:57:14.049016', '2026-09-10 09:57:14.049016', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccbb2c226a024cf7b4b3f8ec29797d0f', '张华南', NULL, NULL, NULL, NULL, 'exact', 'exact', '烟台市', '[]', '[]', '抗日战争时期', '', '伪职：伪烟台道尹；罪行：伪烟台道尹（一说张化南）', '[]', '2026-09-10 09:57:14.071115', '2026-09-10 09:57:14.071115', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccbbcdbc6f644b408060e60245c28a3f', '张一鹏', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽蚌埠；广西桂林资源；浙江杭州建德；上海静安；江苏苏州吴江；江苏苏州；安徽合肥庐江；安徽合肥；江苏南京；安徽芜湖；江苏苏州昆山；河南郑州中牟；上海杨浦；安徽滁州；安徽芜湖镜湖；安徽芜湖；江苏苏州姑苏；江苏苏州；安徽_黄山_黟县；浙江杭州富阳；安徽_阜阳_颍东；江苏南京浦口；陕西_西安；浙江杭州；浙江宁波鄞州；浙江宁波；安徽芜湖镜湖；浙江丽水庆元；安徽_阜阳_颍州', '[]', '[]', '抗日战争时期', '', '为日军统制物资，强迫商户捐献，帮助日军收购粮食和金属，从中牟利。；浙江人，汪伪浙江省政府官员，协助日军统治。；利用检察权迫害抗日群众；原为警察系统人员，投日后在宁波、鄞州组织伪警察，镇压抗日活动，残害民众。；垄断粮食，造成饥荒。；投敌后任伪司法行政部长，协助日军统治。；推行奴化教育，在杭州各学校强制教授日语，篡改历史教材，宣扬“中日亲善”。；组织伪保安队，在合肥、庐江交界处设卡盘查，杀害新四军交通员。；汪伪政权官员，曾任伪安徽省长，在安徽沦陷区推行亲日政策，滁州、凤阳等地在其伪省政权管辖下，协助日军维持统治。；为日伪迫害抗日人士提供法律辩护，助纣为虐。；以“通匪”罪名判处抗日群众，为日军镇压提供法律借口。；在安徽推行奴化教育，篡改教材，宣传亲日思想。；在静安等区推行奴化教育，强制学校教授日语，篡改历史教材。；垄断芜湖粮食，强制低价收购农民稻米，高价配给日军，造成民众饥荒。；在安徽沦陷区配合日军进行资源开发与交通建设，实质服务于军事侵略与经济掠夺。；在安徽沦陷区协助日军修建军事设施、公路，掠夺资源，配合经济统制。；汪伪政权官员，曾任伪安徽省财政厅厅长，在安徽沦陷区推行伪币、搜刮物资，配合日军经济掠夺。；在江苏审判抗日志士，制造冤狱。；苏州沦陷初期组织维持会，为日军提供物资，协助建立伪政权，后任伪省政府顾问。；日军占领苏州初期，组织维持会，为日军提供粮食、劳役，协助建立伪政权。；为日本宪兵队充当翻译，直接参与抓捕、审讯和拷打抗日志士。；汪伪政权成员，曾任伪安徽省省长，在安徽沦陷区推行伪政，协助日军统治。；在苏州地区协助日军进行经济掠夺，强征粮食，参与汪伪清乡运动。；汪伪政权官员，曾任伪安徽省省长，在安徽沦陷区维持伪政权统治，其辖区覆盖蚌埠、五河等地。；浙江富阳人，在富阳各乡镇推行“联保连坐”，强迫百姓举报抗日分子，造成多起冤案。', '[]', '2026-09-10 09:57:13.978023', '2026-09-10 09:57:13.978023', '上海', '杨浦', '庐江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cccf01f7ed3c4b7292006fb86d0e0593', '崔景岚', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆沙坪坝；内蒙古呼伦贝尔牙克石；大同；张家口', '[]', '[]', '抗日战争时期', '', '伪职：伪张家口市副市长；配合韩广森，管控城市警务，迫害抗日群众，压榨商户百姓。；结局：1945??10??08 公审枪决；伪职：伪大同省省长（末代）；罪行：1943 伪大同省成立后主政，维持伪政权末期统治，配合日军强征物资、抓壮丁。；结局：光复后被捕判刑', '[]', '2026-09-10 09:57:13.989358', '2026-09-10 09:57:13.989358', '内蒙古', '呼伦贝尔', '牙克石', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccd03b7910b544bfa453ec10cda0980e', '张秀峰', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山靖宇', '[]', '[]', '抗日战争时期', '', '原为抗联第一军警卫排排长，1940年2月携带机密文件及枪支叛变投敌，向日军供出杨靖宇的行踪和密营位置，引导伪军警在濛江县三道崴子包围杨靖宇，是杨靖宇牺牲的关键告密者。', '[]', '2026-09-10 09:57:14.000026', '2026-09-10 09:57:14.000026', '吉林', '白山', '靖宇', NULL, NULL, NULL, NULL, '');
