INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccf98f556b094efca301050a4db50d56', '张成义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西忻州岢岚；山西忻州；山西吕梁孝义；山西忻州；山西忻州定襄', '[]', '[]', '抗日战争时期', '', '组织伪警备队，为日军提供情报，参与多次对孝义抗日根据地的“扫荡”，杀害抗日干部和群众数十人。；在定襄县为日军征夫派款，破坏抗日根据地，多次带日伪军偷袭八路军后方。；日军占领原平后出任维持会长，为日军提供情报，组织伪自卫团镇压抗日活动。；组织伪保安队，在忻州、岢岚边界多次袭击八路军游击队，杀害抗日干部，抢劫群众财物。；在平鲁县城组织维持会，为日军征粮派款，提供情报，破坏抗日地下组织。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.020124', '2026-09-10 09:57:14.020124', '山西', '吕梁', '孝义', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ccfb9849ef6a4492ac5fc95bfd2934f4', '郭恩庆', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊寿光；山东潍坊高密；山东_潍坊_潍坊滨海经开区；山东_潍坊_诸城；山东潍坊潍城', '[]', '[]', '抗日战争时期', '', '在潍县沦陷期间依附日军，控制商会为日军经济掠夺服务。；寿光县城士绅，日军占领寿光后组织维持会，为日军服务，后因内部矛盾被撤换。；担任伪潍县县长，推行日军政策，镇压抗日活动。；在潍县地区组建伪警察队伍，配合日军搜捕抗日人员，推行治安强化运动。；在潍县任伪警察头目，搜捕抗日人员，配合日军进行治安强化运动，在潍县及周边地区实施白色恐怖。', '[]', '2026-09-10 09:57:14.016947', '2026-09-10 09:57:14.016947', '山东', '潍坊', '寿光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd07fb47f7dd4b60a9b2fbf6ca96af04', '王兹栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林松原宁江；吉林；辽宁辽阳；辽宁_沈阳_法库；辽宁大连金州；辽宁抚顺；辽宁_沈阳_大东；吉林长春公主岭；辽宁沈阳；辽宁大连旅顺口；辽宁大连；辽宁沈阳苏家屯；辽宁大连；吉林长春；吉林辽源；辽宁沈阳康平；辽宁沈阳铁西；吉林、辽宁；吉林；吉林_长春_农安；辽宁铁岭昌图；辽宁铁岭；吉林通化；吉林永吉', '[]', '[]', '抗日战争时期', '', '任伪吉林市长期间，推行日伪市政管理，镇压反满抗日活动。；任伪永吉县长期间，强征劳工，为日军修建军事设施，镇压当地抗日活动。；原辽源县地方士绅，日军占领后出任伪县长，为日军征粮派款，组织伪自卫团，镇压辽源地区抗日民众运动。；九一八后组织地方维持会，迎接日军进驻公主岭，协助建立伪政权，强征民夫修建军事设施。；指挥伪警察协助日军搜捕抗日分子，破坏地下组织，参与“讨伐”抗联部队。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995841', '2026-09-10 09:57:13.995841', '吉林', '松原', '宁江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd09e5b5ac254506b5c806a225d9c1fd', '黄阿宝', NULL, NULL, NULL, NULL, 'exact', 'exact', '绍兴、上虞、嵊县交界（孙端、谷来）', '[]', '[]', '抗日战争时期', '', '伪职：汪伪独立第一旅旅长，浙东自卫总队司令；罪行：土匪出身投敌，伪军千余人，在绍虞嵊三县烧杀劫掠，配合日军下乡扫荡，残害地方百姓；日寇投降后改换旗号混迹忠义救国军，后卷入荣德生绑架案抖音百科。；结局：1948 年捕获，后处决。', '[]', '2026-09-10 09:57:14.069841', '2026-09-10 09:57:14.069841', '浙江', '绍兴', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd121cfbf7f34931a68b8ab3f6cfc7af', '孙金彪', NULL, NULL, NULL, NULL, 'exact', 'exact', '献县', '[]', '[]', '抗日战争时期', '', '伪职：伪献县警备大队长；多次扫荡献县、交河交界村庄。；结局：献县解放被俘处死', '[]', '2026-09-10 09:57:14.069782', '2026-09-10 09:57:14.069782', '河北', '沧州', NULL, NULL, NULL, NULL, NULL, '');
