INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd2e181c421741be9782c71d1474da27', '张嘉琳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_太原；山西_太原_示范', '[]', '[]', '抗日战争时期', '', '主管伪教育，推行奴化教育，强制学校教授日语，篡改历史教材。；指挥伪保安队配合日军“扫荡”，围剿八路军游击队，残害抗日军民。', '[]', '2026-09-10 09:57:14.021283', '2026-09-10 09:57:14.021283', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd3b8a73efc14e95979b5a919b7f169d', '冯德志', NULL, NULL, NULL, NULL, 'exact', 'exact', '泗水县', '[]', '[]', '抗日战争时期', '', '伪职：泗水县伪警察所特务系长；罪行：泗水人。旧政权巡官，1939年返回泗水投靠日伪警务局，掌管特务系，直接归兖州日本宪兵指挥。建立情报网，收买乡村密探；搜捕地下党组织，抓捕杀害多名抗日干部；策划偷袭抗日人员驻地；结局：泗水解放后被俘，公审后枪毙', '[]', '2026-09-10 09:57:14.074937', '2026-09-10 09:57:14.074937', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd43443fc0df49f9906d2b9dc08212ca', '申传昌', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊寿光；山东潍坊潍坊滨海经开区；江苏盐城滨海', '[]', '[]', '抗日战争时期', '', '在诸城地区组织伪政权，控制潍坊南部与滨海相邻地区，协助日军封锁滨海根据地。；寿光本地人，投日后任伪保安大队长，在寿光南部配合日军扫荡，1945年被八路军俘虏。', '[]', '2026-09-10 09:57:14.016975', '2026-09-10 09:57:14.016975', '山东', '潍坊', '寿光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd441c7382dc465ea466647a7b168665', '赵风山', NULL, NULL, NULL, NULL, 'exact', 'exact', '深县', '[]', '[]', '抗日战争时期', '', '伪职：伪深县警备联队长；伪军主力，反复扫荡深县乡村，破坏地道。；结局：深县解放被俘枪决', '[]', '2026-09-10 09:57:14.068550', '2026-09-10 09:57:14.068550', '河北', '衡水', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd4be7da34f54470836731f30560359a', '毛幼卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '武汉（特务汉奸）', '[]', '[]', '抗日战争时期', '', '伪职：特务汉奸；罪行：特务汉奸；结局：1945年10月被逮捕', '[]', '2026-09-10 09:57:14.069685', '2026-09-10 09:57:14.069685', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd4ee1a334bb44bc90cf7548ccae7a49', '黄镇中', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州兴国；江西赣州；江西赣州定南；江西赣州宁都；江西赣州宁都；江西赣州石城；江西赣州；江西赣州；江西抚州广昌；江西抚州；江西赣州上犹；江西赣州；江西赣州于都；江西赣州章贡；江西赣州；江西赣州全南；江西赣州；江西赣州会昌；江西赣州宁都', '[]', '[]', '抗日战争时期', '', '长期在江西抚州、广昌、南丰一带活动，曾率部配合国民党军清剿红军游击队，抗战时期与日伪势力有勾连，在抚州及广昌周边地区进行反共、扰民活动。；抗战期间投靠日军，在赣州地区组织伪维持会，协助日军维持占领区秩序，推行奴化教育，搜刮民财供给日军。；率部投敌，配合日军扫荡赣州、全南地区抗日游击队，残害百姓。；赣南地方武装头目，抗战后期投靠日军，被委为伪赣南自治军司令，在赣州、兴国一带骚扰抗日根据地、劫掠民众。；在赣州地区长期把持地方军政，抗战期间消极抗日、积极反共，与日伪势力暗中勾结，镇压赣南抗日救亡运动，迫害进步人士。；在赣南地区长期从事反共活动，抗日战争时期消极抗日、积极反共，破坏中共领导的抗日救亡运动，迫害抗日群众。；在赣南宁都、瑞金、石城一带长期掌握地方保安武装，抗日战争时期借抗日名义扩充势力，镇压群众抗日活动，迫害中共地下组织和游击队员，是赣南地区有明确记载的保安团队头目。；抗战期间在赣州地区投靠日军，组织伪维持会，协助日军维持占领区秩序、征发民夫与物资，参与镇压抗日活动。；在赣东及赣州周边地区组织伪维持会，后任伪军大队长，为日军带路扫荡，强征民夫修筑工事，迫害抗日军人家属。；在赣南宁都、瑞金、会昌一带长期进行反共清剿，抗战期间消极抗日、积极反共，纵容部下与日伪势力暗通款曲，迫害抗日人士。；在宁都、瑞金、石城一带长期把持地方武装，镇压革命群众，抗战时期消极抗日、积极反共，与日伪势力暗中勾连，维持其在赣南东部的反动统治。', '[]', '2026-09-10 09:57:14.040102', '2026-09-10 09:57:14.040102', '江西', '抚州', '广昌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd5ede407ea9426ab6fd8f462398bdea', '张良才', NULL, NULL, NULL, NULL, 'exact', 'exact', '兴化水网乡镇', '[]', '[]', '抗日战争时期', '', '伪职：伪 22 师伪团长；罪行：跟随刘湘图驻防兴化水乡，带队下乡清剿，袭扰地方抗日武装，残害乡村百姓。；结局：兴化战役被俘，公审枪决兴化日报。', '[]', '2026-09-10 09:57:14.069944', '2026-09-10 09:57:14.069944', '江苏', '泰州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd6471833bfc47f8a2a52a94900a2e02', '聂三钢', NULL, NULL, NULL, NULL, 'exact', 'exact', '黄梅县', '[]', '[]', '抗日战争时期', '', '伪职：伪侦缉队第三分队副队长；罪行：倚仗日寇势力，巴结任金水，专横跋扈，无恶不作', '[]', '2026-09-10 09:57:14.071350', '2026-09-10 09:57:14.071350', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd73f1c81ed8432fbe4f253c5ca0a6f3', '王孝先', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州淳安', '[]', '[]', '抗日战争时期', '', '任伪淳安县长期间，配合日军“扫荡”，强征民夫修筑碉堡，迫害抗日家属。', '[]', '2026-09-10 09:57:14.051246', '2026-09-10 09:57:14.051246', '浙江', '杭州', '淳安', NULL, NULL, NULL, NULL, '');
