INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cd8a5b4ab84a4603a29b94956de48a4c', '黄则民', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州平阳', '[]', '[]', '抗日战争时期', '', '与日军合作，控制平阳商业，为日军采购军需物资，从中牟利，并强迫商户缴纳“慰劳金”。', '[]', '2026-09-10 09:57:14.051418', '2026-09-10 09:57:14.051418', '浙江', '温州', '平阳', NULL, NULL, NULL, NULL, '');
