INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdcb9bdabde9437f89c3df40fc2f5a27', '张炯', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_郴州_桂东；湖南邵阳大祥；湖南邵阳隆回；湖南邵阳；湖南株洲茶陵；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在湖南沦陷区推行奴化教育，编写亲日教材，影响邵阳等地学校。；在长沙沦陷期间，主办伪报纸，为日军进行宣传，鼓吹“大东亚共荣圈”。；湖南籍人物，日军占领湖南期间任伪省政府秘书长，协助伪政权运作。；在沦陷区推行奴化教育，改编教材，强制学校讲授日伪宣传内容。', '[]', '2026-09-10 09:57:14.058844', '2026-09-10 09:57:14.058844', '湖南', '株洲', '茶陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdcd41e3a2894cd7997bada568fc8bc0', '朋斯克', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '蒙古族，曾在伪兴安北省公署任职，参与伪满地方政权事务，其活动范围包括呼伦贝尔地区。', '[]', '2026-09-10 09:57:13.988235', '2026-09-10 09:57:13.988235', '内蒙古', '呼伦贝尔', '扎兰屯', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdd0896dbe93424e9965ba52bd24adbf', '张澜', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川南充；四川成都青羊', '[]', '[]', '抗日战争时期', '', '南充籍爱国民主人士，抗战期间坚持抗日民主立场，未附逆；此处列出以说明南充地区知名人物中无其汉奸记录。；日伪曾试图拉拢其出任伪职，但张澜拒绝并坚持抗日，此处仅作历史记录说明其被日伪点名。', '[]', '2026-09-10 09:57:14.001068', '2026-09-10 09:57:14.001068', '四川', '南充', '青羊', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdd0913251a4484faa7292f187426683', '邓一平', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州北湖', '[]', '[]', '抗日战争时期', '', '在郴县北湖一带担任伪保甲长，为日军派夫、征粮、传递情报。', '[]', '2026-09-10 09:57:14.059783', '2026-09-10 09:57:14.059783', '湖南', '郴州', '北湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdee13e00cd34a07aa00766f718d096f', '刘冠英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸临漳；河北邯郸；河北石家庄石家庄循环化工园；河北；河北石家庄正定；河北邯郸复兴；河北邯郸肥乡', '[]', '[]', '抗日战争时期', '', '日军占领正定后率先组织维持会，为日军征粮派夫，提供情报。；组织伪警备队，参与对抗日根据地的封锁和扫荡。；在邯郸县城任伪知事，推行日伪法令，强征苛捐杂税，并协助日军建立情报网络。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军。；在邯郸县城推行伪政权，设立‘良民证’制度，协助日军控制交通线，镇压抗日活动，并强迫商户‘捐献’军费……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.043639', '2026-09-10 09:57:14.043639', '河北', '石家庄', '正定', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdfba79c200c41d891190582f88cfbe5', '夏威', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州柳北；广西百色靖西；云南普洱西；广西桂林龙胜各族；云南普洱西；广西桂林恭城；广西柳州鹿寨；云南普洱西', '[]', '[]', '抗日战争时期', '', '桂系将领，坚持抗战，未附逆。；日军曾策动其出任伪职，但其未就任，后率部撤退。；桂系将领，抗战期间在广西活动，但未附逆，不属于汉奸。；新桂系将领，在广西沦陷期间率部投敌，被编入伪军，协助日军进攻抗日根据地，为广西地区重要伪军头目之一。；日军入侵广西期间，参与伪广西绥靖公署活动，协助日军进行地方控制。', '[]', '2026-09-10 09:57:14.031712', '2026-09-10 09:57:14.031712', '广西', '柳州', '柳北', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cdfc619b62e14cc6a2dfb24c52e984ad', '吴镜波', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关新丰；广东韶关翁源；广东肇庆；广东韶关翁源；辽宁沈阳大东；广东阳江', '[]', '[]', '抗日战争时期', '', '翁源县汉奸头目，为日军征派粮食民夫，协助日军控制韶关东部地区。；统率伪军配合日军进攻西江抗日游击队，在肇庆、高要、四会等地烧杀抢掠。；广东教育界汉奸，在日伪政权下推行奴化教育，曾在韶关、翁源等地协助日伪开办学校，宣传“大东亚共荣”。；在阳江某区担任伪区长，负责推行日军政令、征收赋税、登记户口。', '[]', '2026-09-10 09:57:14.030040', '2026-09-10 09:57:14.030040', '广东', '肇庆', '新丰', NULL, NULL, NULL, NULL, '');
