INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cea9cd65455f4782b7a6b9b1fc1248ee', '张承德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西大同广灵', '[]', '[]', '抗日战争时期', '', '作为伪蒙疆政府派驻大同的代表，配合日军实施“以华制华”政策，参与组建伪警察队，镇压抗日活动，并协助日伪军清乡。；原为地方土匪，后投降日军任伪保安队队长，率部多次袭击八路军游击队，杀害抗日干部和军属，并参与日军在广灵县西加斗、南村等地的“清乡”行动。；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，并参与制造多起惨案，如“刘庄惨案”中充当向导。', '[]', '2026-09-10 09:57:14.021030', '2026-09-10 09:57:14.021030', '山西', '大同', '广灵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ceb35a7de2394a34a9d3cf97d8616ee9', '乔振方', NULL, NULL, NULL, NULL, 'exact', 'exact', '驻马店地区', '[]', '[]', '抗日战争时期', '', '伪职：土匪汉奸；罪行：1938年初，遂西舞确一带土匪横行，尤以乔振方为甚。吴赞臣委任乔振方为“遂确西舞抗日义勇军游击司令”', '[]', '2026-09-10 09:57:14.082451', '2026-09-10 09:57:14.082451', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ceb6c7d3e7cc46038607447af1a8c301', '李恺', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州泰州医药高；辽宁沈阳大东；江苏泰州姜堰；江苏泰州', '[]', '[]', '抗日战争时期', '', '在泰州推行奴化教育，篡改教材，宣扬“大东亚共荣”，毒化青少年思想。；日军侵占泰州后出面组织维持会，为日军筹粮筹款、维持地方伪秩序，协助日军统治泰县城乡。', '[]', '2026-09-10 09:57:14.035919', '2026-09-10 09:57:14.035919', '江苏', '泰州', '姜堰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cec59c1b2d1f4e74a9bf3431cfae8ae9', '赵毅', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江双鸭山；黑龙江黑河；黑龙江七台河茄子河；黑龙江哈尔滨；黑龙江佳木斯', '[]', '[]', '抗日战争时期', '', '伪满三江省（辖今双鸭山、宝山部分地区）省长，积极推行日伪殖民政策，强征劳工，配合日军“治安肃正”计划。；原哈尔滨警察头目，投日后任伪滨江省警务厅厅长，管辖包括绥化、北林在内的警务，组织特务网，搜捕抗日地下人员，实施“归屯并户”政策。；曾任伪满黑河省省长，推行日伪殖民政策，协助日军镇压逊克、孙吴等地抗日活动。；伪满三江省（辖佳木斯、富锦等县）省长，推行日伪“治安肃正”政策，组织保甲制度，协助日军屠杀抗联及平民。；在勃利县及茄子河地区残酷镇压抗日地下组织，逮捕并杀害多名抗联交通员和爱国群众。', '[]', '2026-09-10 09:57:14.065177', '2026-09-10 09:57:14.065177', '黑龙江', '七台河', '茄子河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cec9d94ec57a4e9e99bb1a4b3971e60a', '丁敬臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东青岛；山东青岛市南；山东青岛；山东青岛平度；山东青岛', '[]', '[]', '抗日战争时期', '', '青岛沦陷初期参与维持会活动，协助日军接管地方事务并在工商界推行亲日合作。；在伪青岛政权中主管财政，为日军搜刮民财、推行伪币和物资统制，支持殖民统治。；在青岛教育文化领域推行奴化教育，配合日军宣传，毒害青年学生。', '[]', '2026-09-10 09:57:14.018265', '2026-09-10 09:57:14.018265', '山东', '青岛', '市南', NULL, NULL, NULL, NULL, '');
