INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cf3a59ed1f3445c9b4fdfa288af29da2', '徐宝森', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏常州', '[]', '[]', '抗日战争时期', '', '审理抗日案件时，按日军旨意判处抗日志士重刑，镇压民众反抗。', '[]', '2026-09-10 09:57:14.034806', '2026-09-10 09:57:14.034806', '江苏', '常州', NULL, NULL, NULL, NULL, NULL, '');
