INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cf7403fd9bd346c6942edc25d3f4434b', '周良玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '钟祥县', '[]', '[]', '抗日战争时期', '', '伪职：日伪鄂西保安军二团团长→新四军五师特三旅旅长（后叛变）；罪行：钟祥柴湖人，土匪出身。当地沦陷后投靠日军。1943年2月率部投奔新四军五师，被编为特三旅任旅长。同年9月日军大扫荡时叛变投敌，绑架政工干部谢威、杜邦宪等人，将杜邦宪装入麻袋沉水杀害。被称为“钟祥抗战历史上最大的汉奸”；结局：后被自己的警卫员杀死', '[]', '2026-09-10 09:57:14.080790', '2026-09-10 09:57:14.080790', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cf7c1e49cf8f40098387270a395d727c', '陈锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸邯郸经开区；辽宁沈阳大东；河北邯郸魏县；辽宁沈阳新民；山东烟台莱阳；山东烟台；河北；湖南岳阳临湘；湖南岳阳；河北_邯郸_磁县；山东滨州沾化', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，强征棉花、铁矿石等战略物资，中饱私囊，民愤极大。；推行奴化教育，删改教材，强制学校教授日语，灌输“大东亚共荣”思想，迫害爱国教师。；推行奴化教育，组织“新民会”胁迫群众参加日军庆功会，搜集抗日情报。', '[]', '2026-09-10 09:57:14.016504', '2026-09-10 09:57:14.016504', '山东', '滨州', '沾化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cf83988e152347f6b895fd1e15a106b6', '王明贵', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔额尔古纳；河北廊坊三河；黑龙江双鸭山；黑龙江佳木斯向阳；黑龙江佳木斯；黑龙江齐齐哈尔梅里斯；黑龙江齐齐哈尔；黑龙江大庆杜尔伯特；黑龙江大庆；黑龙江佳木斯抚远；黑龙江佳木斯；黑龙江佳木斯', '[]', '[]', '抗日战争时期', '', '汉族，原为地方土匪，投靠日军后任保安队长，在三河、室韦一带抓捕抗联交通员，协助日军建立“防谍网”。', '[]', '2026-09-10 09:57:13.989639', '2026-09-10 09:57:13.989639', '内蒙古', '呼伦贝尔', '阿荣旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cf8f0aed141d49c59b5902da4aa3223a', '张景南', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江哈尔滨宾县；黑龙江哈尔滨；黑龙江哈尔滨；黑龙江哈尔滨南岗；黑龙江哈尔滨', '[]', '[]', '抗日战争时期', '', '原哈尔滨日伪特务，投日后负责协和会特务工作，在宾县发展汉奸线人，破坏抗联地下网络。；原哈尔滨地方武装头目，投日后组织伪保安队，配合日军“讨伐”抗联第三路军。；原土匪头目，投日后组织伪“讨伐队”，在哈尔滨南岗及周边山区多次袭击抗联部队，杀害伤员。', '[]', '2026-09-10 09:57:14.065758', '2026-09-10 09:57:14.065758', '黑龙江', '哈尔滨', '南岗', NULL, NULL, NULL, NULL, '');
