INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cfafe193a6c74df492f0eb3ac570aa8b', '张慕陶', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '合肥城区；山西吕梁柳林；山西临汾永和；云南普洱西；山西晋中平遥；山西晋中祁县；山西晋中；山西太原阳曲；山西临汾洪洞；山西临汾；山西；山西太原小店；山西长治长子；山西长治；云南普洱西；山西阳泉；山西临汾吉县；山西吕梁；山西吕梁孝义；山西临汾侯马；山西临汾', '[\"注：曾在太原活动，后因托派问题被处决，非典型汉奸\"]', '[]', '抗日战争时期', '', '无；伪职：伪安新县县长；白洋淀周边设立大量炮楼，搜捕雁翎队。；结局：战后逮捕判刑；曾任中共早期党员，后叛变投敌，在临汾、乡宁一带为日军搜集情报，策反抗日力量，协助日军扫荡根据地。；在临汾县推行保甲制度，强征民夫修筑公路碉堡，配合日军扫荡，残害抗日军民。；投靠日军后任临汾伪县长，强征民夫修筑碉堡公路，搜捕抗日军民，向日军提供情报。；任伪吉县知事期间，强征民夫修筑日军碉堡，强迫百姓领取“良民证”，并配合日军扫荡抗日根据地。；在吉县组织维持会，为日军征粮派款，出卖抗日志士，导致多名地下党员被捕牺牲。……（共涉及22个地区的犯罪记录）；伪职：伪合肥县财政科长；罪行：经济汉奸，主管伪财政，征收苛捐杂税，统制粮食布匹，为日军搜刮战略物资。；结局：汉奸清算判处有期徒刑。', '[]', '2026-09-10 09:57:14.018548', '2026-09-10 09:57:14.018548', '山西', '临汾', '侯马', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cfc03d6c1aef49e4a6134d44d8e90d89', '魏汉三', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳南乐；河南濮阳清丰', '[]', '[]', '抗日战争时期', '', '清丰县本地士绅，日军占领清丰后投敌，组织维持会并任伪县知事，配合日军在清丰、南乐一带推行伪化统治，征发民夫、粮食，协助日军扫荡抗日根据地。', '[]', '2026-09-10 09:57:14.048776', '2026-09-10 09:57:14.048776', '河南', '濮阳', '南乐', NULL, NULL, NULL, NULL, '');
