INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cfd0be8e77914f0bbafb20f11b9da18e', '鄂日登', NULL, NULL, NULL, NULL, 'exact', 'exact', '莫力达瓦', '[]', '[]', '抗日战争时期', '', '伪职：伪莫力达瓦旗旗长；布特哈地区，推行部落制度，为伪兴安军征集兵员、粮草。；结局：战后判刑管制', '[]', '2026-09-10 09:57:14.082016', '2026-09-10 09:57:14.082016', '内蒙古', '呼伦贝尔', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cfd0c6809ac3447abbdf9f09f34b4bb0', '凌顺棋', NULL, NULL, NULL, NULL, 'exact', 'exact', '芜湖', '[]', '[]', '抗日战争时期', '', '伪职：原国军，投敌伪中队长；罪行：国民党地方武装叛变投伪，扩充伪保安大队兵力，袭击抗日武装。；结局：日军投降后被国民党收编，后被清算。', '[]', '2026-09-10 09:57:14.072833', '2026-09-10 09:57:14.072833', '安徽', '芜湖', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cfd5b165363f4973ab91482742bc0e2d', '张焯堃', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东清远英德；广东清远；广东_韶关；广东韶关始兴；广东韶关；广东广州天河；广东广州；广东韶关新丰；广东韶关曲江；广东韶关；广东广州越秀；山西阳泉城区；广东肇庆怀集；辽宁沈阳大东；广东广州海珠；广东广州；广东广州番禺；广东广州；广东韶关南雄；广东韶关；广西柳州柳南；云南普洱西；广东广州白云；广东广州；广东广州；广东清远连山；广东广州花都；广东湛江；贵州铜仁江口；广东河源东源', '[]', '[]', '抗日战争时期', '', '在南海县推行伪政，配合日军对广州西南地区进行统治和经济掠夺。；在东源地区担任伪保甲长，协助日军征粮、派夫，监视抗日活动。；参与伪广东治安维持会，协助日军在广东占领区建立伪政权基础。；广州商界附逆人物，参与伪商会和物资统制，协助日军掠夺广东经济资源。；掌管汪伪广州警察系统，参与搜捕抗日人士、维持日占区治安。；在伪广东省宣传部门任职，为日军制作亲日宣传品，散布‘大东亚共荣’言论，并到西江肇庆一带进行巡回宣传。；在广州沦陷期间与日伪合作，参与商会与物资统制，为日军经济掠夺提供协助。；广州沦陷初期组织伪维持会，协助日军维持广州城区秩序，筹组伪政权，为日军搜刮物资。；韶关曲江地区伪维持会负责人，协助日军在曲江及周边地区推行保甲、征粮与治安控制。；检索中未见可靠史料明确记载其任职与事迹，仅作为广西范围内可能附逆者线索，需谨慎对待。；任伪广州市警察局长，指挥伪警察配合日军搜捕抗日人员、维持殖民统治。；在汕头及潮梅地区推行日伪统治，配合日军对梅县、兴宁等地的经济封锁和扫荡，诱降地方武装。；日军侵占韶关期间出面组织维持会，为日军筹粮、拉夫，协助维持占领区秩序。；汪伪政权时期曾任伪广州市市长，参与广州沦陷区行政统治。；投靠日军，任伪广东江防舰队司令，配合日军在珠江及北江流域的军事行动，活动范围涉及清远、英德水域。；率伪海军配合日军封锁广东沿海与内河，拦截抗日物资。；率伪军配合日军在广东沿海及珠江口进行封锁与清乡，镇压抗日武装。；广州沦陷后参与组织番禺伪维持会，后任伪番禺县县长，为日军征粮、拉夫、维持治安。；花县沦陷后组织伪维持会，为日军征调粮食、劳工，协助维持地方伪秩序。；汪伪政权后期广东官员，曾任伪广州市长、伪广东建设厅长，参与伪政权地方建设与资源掠夺。；新丰县本地汉奸，组织维持会为日军服务，征派民夫、粮食，协助日军维持对新丰地区的控制。；广州沦陷区商界附逆代表，协助日军进行物资统制与经济掠夺。；日军侵占曲江后出任伪曲江县长，为韶关地区直接附逆者，组织维持会、征发民夫粮秣，协助日军控制粤北交通线。', '[]', '2026-09-10 09:57:14.026723', '2026-09-10 09:57:14.026723', '广东', '广州', '天河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('cff35539a9954bafbdfb3a044736e2d5', '李连祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州齐河', '[]', '[]', '抗日战争时期', '', '在齐河地区率伪保安队协助日军扫荡，镇压抗日群众。', '[]', '2026-09-10 09:57:14.014247', '2026-09-10 09:57:14.014247', '山东', '德州', '齐河', NULL, NULL, NULL, NULL, '');
