INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d028951be8fc4b6d9516fdd684a90628', '申振纲', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州管城；河南郑州；河南郑州；青海黄南河南', '[]', '[]', '抗日战争时期', '', '河南人，投敌后任伪道尹、伪省政府委员，在豫东地区协助日军征粮、派款，推行奴化教育。；日军侵占郑州后出面组织维持会，为日军筹粮筹款、维持治安，协助建立伪政权。；日军占领郑州后出任伪郑州市市长，组织维持会，协助日军管理城市、征发物资，镇压抗日群众。', '[]', '2026-09-10 09:57:14.047272', '2026-09-10 09:57:14.047272', '青海', '黄南', '河南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d02dc5a8f710466db355aa208cf9024a', '林前', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建宁德古田；福建福州闽侯', '[]', '[]', '抗日战争时期', '', '福州及闽侯沦陷期间，任伪闽侯县维持会会长，为日军征集粮食、民夫，维持地方伪秩序。', '[]', '2026-09-10 09:57:14.061217', '2026-09-10 09:57:14.061217', '福建', '宁德', '古田', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d030bac03bcb4edbb0d50874d40591f2', '赵全禄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西运城芮城；山西运城；山西长治沁源；山西阳泉矿区；山西长治黎城；山西长治屯留；山西长治壶关；辽宁沈阳新民；山西；山西运城垣曲；山西忻州河曲；山西长治潞城；山西晋中榆社', '[]', '[]', '抗日战争时期', '', '专门刺探八路军情报，抓捕地下党员，刑讯逼供，导致多名抗日志士牺牲。；积极为日军筹粮派款，强迫村民参加“爱护村”，向日军报告抗日武装动向，导致多处秘密联络点被破坏。；积极推行日军“治安强化运动”，组织汉奸宣传队散布亲日言论，强迫民众参加“新民会”，并收集抗日情报提供给日军，破坏抗日群众组织。；作为日军顾问参与运城地区伪政权决策，协助推行奴化教育和经济掠夺。；为日军宣传奴化思想，组织“新民会”活动，强迫百姓参加“反共”集会，收集抗日情报。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.022072', '2026-09-10 09:57:14.022072', '山西', '忻州', '河曲', NULL, NULL, NULL, NULL, '');
