INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d07008a9d8cc43caa32bc0c8e96c70aa', '段玉昆', NULL, NULL, NULL, NULL, 'exact', 'exact', '清苑', '[]', '[]', '抗日战争时期', '', '伪职：伪保定警察局长；配合保定日本宪兵，大肆搜捕冀中地下党组织，酷刑迫害被捕干部群众。；结局：解放后镇反公审处决', '[]', '2026-09-10 09:57:14.087062', '2026-09-10 09:57:14.087062', '河北', '保定', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d0713fb642e54c7b99d5dddedc099c71', '李海天', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山唐山海港经开区；辽宁沈阳新民；河北唐山滦州；河北唐山乐亭；河北唐山路南；河北唐山；北京、天津、河北；河北秦皇岛北戴河；河北秦皇岛；北京平谷；河北唐山滦南；河北唐山；天津_河北；河北唐山丰南；河北唐山；河北唐山迁西', '[]', '[]', '抗日战争时期', '', '率部驻守平谷地区，配合日军清剿抗日游击队，多次参与“扫荡”行动，抓捕并杀害抗日军民。；原东北军军官，投日后在冀东地区任伪军头目，参与制造“无人区”，屠杀抗日群众。；驻防唐山，协助日军围剿冀东抗日联军，杀害抗日军民。；在丰南、滦县一带活动，协助日军扫荡，破坏抗日组织，强征民夫修筑工事。；长期驻守唐山，协助日军清乡，抓捕抗日志士，镇压开滦煤矿工人罢工，参与“治安强化运动”。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.993769', '2026-09-10 09:57:13.993769', '北京', '平谷', '丰南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d074c39743f54944ac59f6789c1a201f', '陈云涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；山东烟台招远；山东烟台；黑龙江黑河北安；黑龙江哈尔滨宾县；黑龙江哈尔滨；山东烟台牟平；山东烟台；山东威海威海火炬高；山东威海', '[]', '[]', '抗日战争时期', '', '组织协和会青年团，进行军事训练，配合日军进行“思想战”。；在胶东道伪政权中任职，管辖范围包括威海地区，协助日军推行伪化政策、征粮征丁、封锁抗日根据地。；烟台沦陷后参与组织维持会，协助日军维持地方秩序，征发民夫物资。；原哈尔滨市政官员，投日后管理伪市行政，协助日军实施经济统制，在宾县等地强征物资，压迫百姓。；伪政权在胶东地区的行政头目，驻烟台，管辖包括牟平在内的胶东各县伪政权事务。；在胶东包括威海地区开展奴化教育，组织新民会，宣传“中日亲善”，协助日军控制民众思想。', '[]', '2026-09-10 09:57:14.013077', '2026-09-10 09:57:14.013077', '山东', '威海', '威海火炬高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d09342d695014e2ba795cd5b77fea4af', '陈楚材', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁营口站前；辽宁营口；辽宁营口老边；辽宁营口；吉林经开区；浙江台州路桥；浙江台州黄岩', '[]', '[]', '抗日战争时期', '', '协助日伪推行粮谷出荷，强迫农民交粮，压榨农村。；黄岩沦陷后出面组织伪商会，为日军筹办军需物资，强制商户摊派捐款，并协助日伪实行经济统制，盘剥路桥、黄岩一带商民。；营口商界附逆者，为日军筹集物资，协助经济统制，压迫民族工商业。；在营口教育界推行奴化教育，协助日军宣传“日满亲善”，毒害当地青少年，是文化教育领域附逆者。', '[]', '2026-09-10 09:57:14.000191', '2026-09-10 09:57:14.000191', '吉林', '经开区', '路桥', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d09c39aadf284d32bd7a256c9bca98f3', '张冠英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '建昌（凌南）；河北；河北唐山', '[]', '[]', '抗日战争时期', '', '伪职：伪凌南县（建昌前身）县长；罪行：建昌药王庙惨案发生时伪县长；配合日军扫荡，抓捕、杀害大量抗日志士与群众。；结局：光复后汉奸罪判刑。；伪职：伪霸县首任知事；从天津被日军派来，扩充伪保卫团固守霸县城。；结局：城破逃跑，战后抓捕判刑廊坊市纪委...；1938年唐山设市后任伪市长，全面推行日伪统治，控制工商业，强征劳工，为日军提供煤炭等战略物资。', '[]', '2026-09-10 09:57:14.041435', '2026-09-10 09:57:14.041435', '河北', '葫芦岛', NULL, NULL, NULL, NULL, NULL, '');
