INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d0ded732ed664371a8954c4da61a4add', '赵子龙', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵；江苏连云港灌云；河北沧州运河；浙江丽水；江苏镇江扬中；江苏连云港灌南；浙江丽水缙云；浙江金华浦江；安徽_马鞍山_和县', '[]', '[]', '抗日战争时期', '', '带领特务队抓捕抗日志士，严刑逼供，多次破坏地下交通站。；在壶镇区任伪区长，协助日军推行“清乡”政策，强征壮丁，迫害抗日家属。；为日军征收苛捐杂税，勒索商民，中饱私囊，导致民不聊生。；在顺安镇为日军征粮派款，强拉壮丁，迫害抗日家属。；率自卫团协助日军封锁长江渡口，参与抓捕抗日干部，并参与屠杀无辜村民事件。；率自卫团协助日军在灌南地区建立伪化统治，强迫村民“连坐”，镇压反抗者。；组织伪自卫团，配合日军巡逻封锁，参与“扫荡”抗日根据地，杀害抗日群众。；利用商会为日军收购战略物资，提供经济支持，并充当日军与地方势力之间的联络人。；把持运河淮阴段船捐，对过往商船强征重税，为日军运输物资提供便利，并扣留抗日物资船只。', '[]', '2026-09-10 09:57:14.010528', '2026-09-10 09:57:14.010528', '安徽', '铜陵', '灌云', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d0e4ada2ba144bc8939ea8d0aef6f132', '孙玉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江鸡西虎林', '[]', '[]', '抗日战争时期', '', '建立特务情报网，收买汉奸告密，破获多起抗联地下联络站，导致数十名地下党员被捕牺牲。', '[]', '2026-09-10 09:57:14.066671', '2026-09-10 09:57:14.066671', '黑龙江', '鸡西', '虎林', NULL, NULL, NULL, NULL, '');
