INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d158e85f82874ae1bd57283248114d33', '彭孟缉', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳；湖南株洲天元；湖南株洲；湖南_长沙_芙蓉；湖南邵阳洞口；湖南_衡阳_衡南；吉林高；湖南湘潭；湖南郴州', '[]', '[]', '抗日战争时期', '', '在日伪统治下推行奴化教育，修改教材，强制学校教授日语和亲日内容，组织学生参加日伪集会。；湖南湘潭地区部分维持会、保甲长在日军占领期间协助征粮、派夫，但具体姓名多不可考，彭孟缉为台湾高雄人，与湘潭无直接关联，此处仅作示例说明地方维持会现象。；株洲本地士绅，日军占领株洲后出面组织维持会，任副会长，负责为日军筹粮、派夫。；湖南籍，抗战后期在湖南与日伪方面有联络，后率部反正，其活动涉及衡阳地区。；湖南籍，曾在沦陷区与日伪接触，后转向抗日，历史评价复杂。；无可靠史料证明其附逆，故不列入汉奸名录。；湖南人，抗战期间在湘鄂边界地区组织伪军，配合日军对抗日根据地和国军进行骚扰，后所部被日军收编为伪保安部队。', '[]', '2026-09-10 09:57:14.058689', '2026-09-10 09:57:14.058689', '湖南', '株洲', '天元', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d163b6b7799b457fa34d7358dd08c616', '谢文炳', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡南；湖南衡阳；山西阳泉城区；江西赣州瑞金', '[]', '[]', '抗日战争时期', '', '衡阳沦陷后出任伪警察局长，协助日军维持城区治安，搜捕抗日人士，推行伪警察统治。；控制衡阳铁路沿线伪维持组织，为日军运输物资、协助军事行动。；日军侵扰赣南期间，在瑞金出面组织伪维持会，为日军带路、筹粮，协助日军搜捕抗日人士和革命群众，维持日伪在瑞金的短暂统治。', '[]', '2026-09-10 09:57:14.040560', '2026-09-10 09:57:14.040560', '江西', '赣州', '瑞金', NULL, NULL, NULL, NULL, '');
