INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d1711bf79968413e93e147d7bbaa06f9', '陈瑞水', NULL, NULL, NULL, NULL, 'exact', 'exact', '广北', '[]', '[]', '抗日战争时期', '', '伪职：汉奸队头目；罪行：盘踞广北地区的汉奸头目。成建基被消灭后，其残余势力仍与陈瑞水部勾结为害', '[]', '2026-09-10 09:57:14.079327', '2026-09-10 09:57:14.079327', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
