INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d189fd1e08514704990f1a5b2b9da442', '杨绍诚', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南德宏芒市；云南保山腾冲；云南保山腾冲', '[]', '[]', '抗日战争时期', '', '日军占领腾冲后，杨绍诚出任伪维持会会长，为日军征粮派款、维持治安，并协助日军搜捕抗日人员，其活动范围覆盖德宏东部及腾冲一带。；1942年日军占领腾冲后，当地成立维持会以协助日军统治。杨绍诚被记载为参与维持会事务、为日军筹粮派款的地方附逆者之一。', '[]', '2026-09-10 09:57:13.980022', '2026-09-10 09:57:13.980022', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
