INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d1e8e7493a4541c784e68c93a0b525d3', '德穆楚克栋鲁普', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古包头达尔罕茂明安；内蒙古鄂尔多斯；内蒙古锡林郭勒苏尼特右旗；内蒙古乌兰察布化德；内蒙古锡林郭勒太仆寺旗；内蒙古锡林郭勒正镶白旗；云南普洱西；内蒙古赤峰喀喇沁旗；内蒙古锡林郭勒苏尼特右旗；内蒙古赤峰巴林右旗；内蒙古锡林郭勒苏尼特右旗；宁夏石嘴山；山西大同；黑龙江大庆大同；内蒙古乌兰察布；内蒙古包头达尔罕茂明安；内蒙古鄂尔多斯；内蒙古包头；广西桂林资源；内蒙古_呼和浩特；内蒙古巴彦淖尔临河；内蒙古巴彦淖尔五原；内蒙古巴彦淖尔；内蒙古通辽；河北张家口；内蒙古乌兰察布卓资；内蒙古乌兰察布；内蒙古乌海；内蒙古包头；内蒙古包头土默特右旗；内蒙古包头昆都仑；内蒙古呼伦贝尔；内蒙古呼和浩特；内蒙古呼和浩特土默特左旗；内蒙古巴彦淖尔乌拉特前旗；内蒙古通辽奈曼旗；河北张家口；黑龙江大庆大同；河北秦皇岛；内蒙古赤峰松山；内蒙古乌海乌达；内蒙古乌海海南；内蒙古包头；内蒙古呼和浩特武川；河北张家口沽源；苏尼特右旗；内蒙古通辽扎鲁特旗；内蒙古锡林郭勒苏尼特右旗；内蒙古_锡林郭勒_东乌珠穆沁旗；陕西榆林；内蒙古乌兰察布察哈尔右翼前旗；内蒙古巴彦淖尔乌拉特中旗；内蒙古乌兰察布化德；内蒙古乌兰察布；内蒙古乌兰察布察哈尔右翼后旗；内蒙古兴安乌兰浩特；内蒙古呼伦贝尔；内蒙古巴彦淖尔；内蒙古锡林郭勒二连浩特；内蒙古乌兰察布丰镇；内蒙古乌兰察布；内蒙古包头；内蒙古锡林郭勒苏尼特右旗；山东临沂兰山；河北张家口；内蒙古锡林郭勒苏尼特右旗；内蒙古乌兰察布察哈尔右翼中旗；内蒙古兴安科尔沁右翼中旗；内蒙古锡林郭勒苏尼特右旗；内蒙古通辽科尔沁左翼后旗；内蒙古通辽；内蒙古赤峰巴林左旗；内蒙古锡林郭勒苏尼特右旗；内蒙古赤峰阿鲁科尔沁旗；内蒙古锡林郭勒苏尼特左旗；内蒙古锡林郭勒苏尼特右旗；内蒙古苏尼特右旗；内蒙古鄂尔多斯鄂托克前旗；内蒙古鄂尔多斯；内蒙古通辽科尔沁左翼中旗；广西桂林灵川；内蒙古、北京、天津、山西、河北；陕西榆林神木；陕西榆林；云南昆明呈贡；广西_桂林_永福；云南普洱西；陕西宝鸡；陕西_西安；内蒙古锡林郭勒苏尼特右旗；内蒙古兴安科尔沁右翼前旗；甘肃甘南合作；内蒙古呼伦贝尔；河北张家口；天津河北；湖南_怀化_怀化洪江管理；重庆沙坪坝；云南普洱西', '[\"德王\"]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪蒙古联盟自治政府主席，伪蒙疆联合自治政府副主席；以厚和为早期首府，分裂国土，设立巴彦塔拉盟，拆分土默特旗；派遣伪蒙古军反复扫荡大青山抗日根据地，掠夺牲畜矿产，推行日语奴化教育。；结局：1950 引渡回国受审，1963 特赦，1966 呼和浩特病逝光明数字报；蒙古王公，长期与日本关东军勾结，在乌兰察布地区推行“蒙古自治”，建立伪政权，为日军提供兵员和情报，协助统治当地。；蒙古王公，长期策划“蒙古独立”，1936年成立伪蒙古军政府，1939年任伪蒙疆政府主席，其势力覆盖乌兰察布、兴和地区，为日军提供兵员和情报，镇压抗日活动。；蒙古王公，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布盟及凉城一带，配合日军“治安肃正”，征粮抓丁，迫害抗日军民。；在化德（当时称嘉卜寺）建立伪蒙古军政府，后任蒙疆联合自治政府主席，积极投靠日本，组织伪蒙古军配合日军进攻绥远等地。；蒙古族王公，组织伪蒙疆政权，与日军合作，在乌兰察布、卓资一带推行殖民统治，征粮征兵，协助日军清剿抗日武装。……（共涉及85个地区的犯罪记录）；伪任职务：伪蒙疆联合自治政府主席，伪蒙古军政府总裁，伪政权总头目，配合日军扫荡大青山根据地，推行奴化分裂政策。结局：1950 年从蒙古引渡回国关押，1963 年特赦，1966 年呼和浩特病逝人民网', '[]', '2026-09-10 09:57:13.981387', '2026-09-10 09:57:13.981387', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d1e9bd04d55b49e1a70e371692762c10', '汪道源', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽黄山', '[]', '[]', '抗日战争时期', '', '黄山地区地方人物，抗战期间投靠日军，组织伪维持会，协助日军管理黄山周边乡镇，征收赋税，镇压抗日活动。', '[]', '2026-09-10 09:57:14.011344', '2026-09-10 09:57:14.011344', '安徽', '黄山', '屯溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d2030449f51b4ec591c4498c9f3f5566', '乌勒吉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古赤峰克什克腾旗', '[]', '[]', '抗日战争时期', '', '效忠日本特务机关，组织伪警察抓捕抗日志士，参与“治安肃正”行动。', '[]', '2026-09-10 09:57:13.990412', '2026-09-10 09:57:13.990412', '内蒙古', '赤峰', '克什克腾旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d20aebaffd5b4921ade5b21fd002a312', '陈明德', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南五指山；海南临高；海南东方；海南陵水；海南东方；海南乐东；海南昌江；江西景德镇昌江', '[]', '[]', '抗日战争时期', '', '在乐东地区推行奴化教育，强制日语教学，宣传亲日思想。；在临高地区统辖伪军，配合日军扫荡抗日游击队。；在陵水地区推行保甲连坐，协助日军清乡，抓捕抗日人员。；充任伪警察头目，带领伪警配合日军搜捕抗日人员，勒索民众，镇压昌江地区抗日活动。', '[]', '2026-09-10 09:57:14.053733', '2026-09-10 09:57:14.053733', '海南', '东方', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d20ecb0b1f3141afab90b91d9e7a32cd', '薛伟', NULL, NULL, NULL, NULL, 'exact', 'exact', '叶县', '[]', '[]', '抗日战争时期', '', '伪职：叶县维持会副会长；罪行：叶县日伪政权二号人物、大汉奸。长期经商落户叶县，日军占领后任维持会副会长。1944年7月带随从沿许南公路为日军催收粮款，在旧县（今叶邑镇）扣押当地财主故交勒索赎金；结局：1944年7月，地下党陈继尧派段庄村地下党都克祥设局将其击毙于旧县南街油坊院', '[]', '2026-09-10 09:57:14.070336', '2026-09-10 09:57:14.070336', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d2101496f04940e6bbbe2a7983b4003a', '单俊卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '固镇湖沟集', '[]', '[]', '抗日战争时期', '', '伪职：伪湖沟集伪军司令；罪行：青帮头目，盘踞湖沟，拥有千余伪军武装；控制浍河航运，抓捕地下交通人员，策动我方队伍叛变，鱼肉沿淮百姓。；结局：抗战胜利后被国民党收编；解放后镇反公审枪决。', '[]', '2026-09-10 09:57:14.068088', '2026-09-10 09:57:14.068088', '安徽', '蚌埠', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d210b5a4f6214333933bc06c6e13c810', '吴子敬', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北襄阳襄州；湖北襄阳；河南信阳平桥；甘肃甘南合作；湖北荆门京山；湖北荆门；河南信阳罗山；山西晋城阳城；河南许昌；河南驻马店驻马店经开区；河南驻马店；安徽铜陵郊区；安徽淮南大通；河南信阳潢川；河南信阳新县；河南信阳；湖北随州曾都；湖北十堰郧西；重庆云阳；河南信阳信阳高；河南信阳；河南信阳商城；河南信阳息县；河南许昌建安；河南许昌；陕西汉中汉台；湖北荆门；湖北襄阳谷城；湖北襄阳；河南信阳息县；河南信阳；河南许昌魏都；河南许昌', '[]', '[]', '抗日战争时期', '', '协助会长管理信阳维持会，负责与日军联络，提供情报，迫害抗日人员。；统领伪保安大队配合日军扫荡荆门、京山交界地区，捕杀抗日干部和群众，焚烧民房。；任伪襄阳县政府建设科科长，配合日军修筑工事、公路，征用民力，支持日军军事行动。；利用伪法院迫害抗日人士，为日伪统治提供所谓“法律”支持。；湖北郧西人，抗战期间投敌，任伪郧西警察局局长，协助日军维持郧西治安，搜刮物资。；控制伪合作社，低价强购农民粮食棉花，供应日军军需，盘剥当地民众。；在重庆伪政权中任职，协助日军进行经济掠夺和情报收集。；在日伪控制下推行奴化教育，篡改教材，向学生灌输亲日思想，为日军侵略培养顺民。；控制潢川商会，为日军筹款筹粮，强制商户交纳“治安费”，协助日军经济掠夺。；率伪保安大队在随县、曾都周边配合日军扫荡，参与烧毁村庄、抢掠粮食、抓捕抗日人员。；在伪河南省政权中任职，负责许昌道所属各县的伪政事务，推行日军殖民政策。；统率伪军配合日军在豫南信阳、新县、罗山、光山等地进行剿共扫荡，进攻抗日根据地，捕杀抗日军民，是豫南地区重要的伪军头目。；在息县组织伪维持会，协助日军征粮派款，维持沦陷区秩序。；在襄阳基层担任伪保长，负责摊派捐税、抓丁拉夫，监视居民言行，向日军密报抗日人员行踪。；在泌阳及驻马店西部山区为日军搜集情报，诱降地方武装，参与伪化统治。；在平汉铁路信阳段组织伪爱路会，协助日军护路、搜集情报、巡查沿线，防止抗日力量破坏交通。；在大通镇为日军征用民船，控制长江水道，协助日军运输军需，并告密杀害抗日地下工作者。；在信阳城郊担任伪保甲长，负责清查户口、报告抗日人员行踪，为日军征发民夫和粮草。；为日伪政权征收苛捐杂税，压榨许昌民众。；在后港地区为日军征粮征税，组织伪自卫队，配合日军清乡。', '[]', '2026-09-10 09:57:14.010735', '2026-09-10 09:57:14.010735', '安徽', '铜陵', '郊区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d2188827682943c1b8afbb888cb311d4', '陈某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西百色靖西；广西南宁；广东江门恩平；广东江门；安徽黄山；安徽宣城旌德；安徽芜湖芜湖长江大桥经开区；河南郑州中牟', '[\"具体姓名待考\", \"陈伯衡\", \"陈达三\", \"待考\"]', '[]', '抗日战争时期', '', '日军侵占桂南期间曾扶植伪政权，但活动范围主要在南宁、钦州、防城一带，与百色、靖西直接关联的记载有限。；台山沦陷期间组织维持会，为日军征敛物资，维持伪政权，与恩平、江门地区伪政权有联系。；旌德县沦陷期间任维持会会长，协助日军维持地方。；为日伪筹集军饷，强迫商户捐献，垄断物资，从中牟利。', '[]', '2026-09-10 09:57:14.010029', '2026-09-10 09:57:14.010029', '安徽', '芜湖', '芜湖长江大桥经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d21c7fc341a54545b5f78dd29cdd62e6', '杨宝衡', NULL, NULL, NULL, NULL, 'exact', 'exact', '盘山', '[]', '[]', '抗日战争时期', '', '伪职：伪盘山县商会会长，天庆隆商号老板；罪行：巴结日本官吏，把商号房屋献给日本官员；垄断粮食配给与 “出荷粮”，盘剥商民；日本投降后勾结土匪张海峰参加 11??19 反革命叛乱，进攻民主政权。；结局：叛乱失败后被公审处决。', '[]', '2026-09-10 09:57:14.069797', '2026-09-10 09:57:14.069797', '辽宁', '盘锦', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d21f52aa8da54f31886e61c312b87bcb', '纳长麒', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏银川贺兰；宁夏银川', '[]', '[]', '抗日战争时期', '', '在日伪控制区推行奴化教育，在银川、贺兰等地学校强制使用伪满教材，宣传“日满华亲善”，毒害青少年。', '[]', '2026-09-10 09:57:14.004077', '2026-09-10 09:57:14.004077', '宁夏', '银川', '贺兰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d220a322211140ba9291c99eceb5132d', '李逢春', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西晋城高平；江西抚州广昌；山西；江西上饶铅山；偏关；山西运城万荣；山西忻州河曲；肥乡', '[]', '[]', '抗日战争时期', '', '伪职：伪偏关县县长；罪行：建立偏关伪县公署，管控黄河渡口，盘查过往交通人员。；结局：战后汉奸罪判刑；率警备队驻守高平各据点，参与“三光”扫荡，亲手杀害抗日村长数人。；任荣河县伪县长，为日军征收粮款，强抓壮丁，破坏地下抗日组织，曾指使汉奸告密导致多名抗日人员被捕牺牲。；率伪军多次参与对抗日游击队的围剿，杀害多名抗日干部，并强征百姓粮食供应日军。；伪职：伪肥乡警备大队长；多次下乡清乡，抓捕抗日干部。；结局：肥乡解放被俘，判处死刑；伪职：伪肥乡警备大队长；带队多次下乡 “清乡”，抓捕抗日干部。；结局：肥乡解放被俘，判处死刑', '[]', '2026-09-10 09:57:14.022047', '2026-09-10 09:57:14.022047', '山西', '忻州', '河曲', NULL, NULL, NULL, NULL, '');
