INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d393192ac9cd44458fbad34436702a75', '张鸿恩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治屯留；山西；山西临汾安泽；山西临汾；山西晋城陵川；山西运城新绛', '[]', '[]', '抗日战争时期', '', '在临汾及周边地区（含安泽西部）任伪职，为日军提供情报，强征捐税，并参与建立伪自卫团，镇压抗日活动。；率伪保安队配合日军“清乡”，烧杀抢掠，袭击抗日游击队，杀害多名抗日干部。；宣传奴化思想，推行‘中日亲善’，诱骗青年参加伪军，破坏抗日宣传。', '[]', '2026-09-10 09:57:14.018910', '2026-09-10 09:57:14.018910', '山西', '临汾', '安泽', NULL, NULL, NULL, NULL, '');
