INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d3b228f27882441184df9af2b2312ba2', '马鸿宾', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏吴忠；宁夏石嘴山；云南普洱西', '[]', '[]', '抗日战争时期', '', '宁夏地方军阀，抗战期间率部在绥西一带抗日，但同时在宁夏吴忠等地维持军阀统治，与日伪方面有暗中往来，其部属中存在与伪蒙疆政权勾结的情形。；抗战期间在宁夏地区虽曾参与绥西抗战，但立场摇摆，与日伪势力有暧昧关系，对辖区内抗日活动限制较多，其部属在石嘴山一带与伪蒙军有接触。；宁夏地方军阀，抗战期间率部在绥西一带驻防，与日伪军有局部接触，曾参与对日作战，但同时也存在保存实力、与伪蒙疆政权方面人员进行私下联络的行为。；在宁夏及绥西地区与日军作战中态度摇摆，部分部队与伪蒙军有默契，对抗日力量支持有限，其部属在绥西与日伪势力有妥协行为。', '[]', '2026-09-10 09:57:14.003705', '2026-09-10 09:57:14.003705', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d3b5c3d5df354a9fab1dee72615df55e', '张玉琳', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南湘西永顺；湖南怀化辰溪；湖南湘西龙山；云南普洱西', '[]', '[]', '抗日战争时期', '', '湘西地区土匪首领，抗战后期与日伪势力勾结，接受伪军番号，在湘西一带从事破坏抗日后方活动。；在湘西辰溪地区组织伪维持会，为日军征集物资、情报，活动范围接近永顺。', '[]', '2026-09-10 09:57:14.059126', '2026-09-10 09:57:14.059126', '湖南', '湘西', '永顺', NULL, NULL, NULL, NULL, '');
