INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d51824d44cec41869ab7c29ef829aa08', '赵尊岳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京；北京门头沟；江苏常州武进；安徽芜湖镜湖；安徽芜湖芜湖经开区；安徽安庆；辽宁沈阳大东；江西_九江；浙江杭州淳安；江苏南京鼓楼；浙江杭州西湖；贵州贵阳；陕西_西安_长安；江苏镇江', '[]', '[]', '抗日战争时期', '', '在门头沟各学校推行日语教育和“中日亲善”宣传，毒化青少年思想。', '[]', '2026-09-10 09:57:13.995226', '2026-09-10 09:57:13.995226', '北京', '安庆', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d52347f2e301456db02963a3592ecac5', '赵子玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁兖州；山东济宁汶上；山东济宁；山东潍坊临朐；山东济宁任城；山东济宁；山东烟台海阳；山东日照；山东菏泽单县；山东济宁金乡；山东临沂费县；辽宁沈阳大东；安徽淮北杜集；安徽淮北；山东淄博淄川；山东菏泽成武', '[]', '[]', '抗日战争时期', '', '在济宁推行奴化教育，篡改教材，宣传“中日亲善”，毒害青少年。；在海阳地区担任伪警察头目，配合日军抓捕抗日人员，镇压当地民众抗日活动。；在临淄组织伪军，配合日军扫荡，活动范围接近淄川。；成武人，投靠日军后任伪成武县县长，建立伪政权和伪军，在成武、菏泽交界地区配合日军扫荡，强征粮食和劳工。；在费县推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。；出面组织伪商会，为日军筹集物资、摊派款项，协助日军对根据地进行经济封锁。；活动于金乡、单县边境，配合日军扫荡湖西抗日根据地，杀害抗日群众，抢掠财物。；在兖州任伪警察局长，协助日军维持治安，参与抓捕抗日人员，推行保甲制度。；任伪安丘县知事、县长，配合日军扫荡安丘、临朐一带抗日根据地。；在济宁地区开展亲日宣传和奴化教育，组织伪民众团体，配合日军殖民统治。；抗战期间在宿县、淮北一带依附日军，参与伪政权行政事务，为日伪统治服务。', '[]', '2026-09-10 09:57:14.008716', '2026-09-10 09:57:14.008716', '安徽', '淮北', '杜集', NULL, NULL, NULL, NULL, '');
