INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d53487856aba462b821fddf0d60bd165', '乔玉莲', NULL, NULL, NULL, NULL, 'exact', 'exact', '寿阳', '[]', '[]', '抗日战争时期', '', '伪职：“黑军” 伪军头目；罪行：土匪投敌，盘踞白草峪，袭扰盂寿根据地，捕杀区村干部。；结局：1940 武工队奔袭据点击毙', '[]', '2026-09-10 09:57:14.073337', '2026-09-10 09:57:14.073337', '山西', '晋中', NULL, NULL, NULL, NULL, NULL, '');
