INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5930dc8cf144a56a567c64db6186ade', '曹大中', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽芜湖镜湖；河南商丘睢阳；河南商丘；河南商丘；商丘', '[]', '[]', '抗日战争时期', '', '伪职：伪和平救国军第1路司令；罪行：张岚峰部属。1940年6月29日率部反正，脱离伪军；结局：反正', '[]', '2026-09-10 09:57:14.010291', '2026-09-10 09:57:14.010291', '安徽', '芜湖', '镜湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d59f036494fe449d9a09e375df8b6cb6', '杨姓暗探', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁西善桥', '[\"佚名\"]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：西善桥日军密探，长期混迹鸦片烟馆，刺探我方人员行踪。。结局：武工队闯入烟馆抓捕，送交民主政府审判南京雨花台...', '[]', '2026-09-10 09:57:14.077103', '2026-09-10 09:57:14.077103', '江苏', '南京', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5ad09524d604e67814587dba2466b1a', '李德明', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西抚州临川；江西上饶横峰；海南白沙；四川成都邛崃；江西上饶弋阳；江西上饶；山西吕梁石楼；山西吕梁；湖北十堰竹山；河南南阳南阳示范；河南南阳；江西抚州南城；江西抚州资溪；河南商丘宁陵；海南三沙中沙；海南三沙西沙；江西景德镇浮梁；江西景德镇；江西抚州金溪；江西上饶广丰；江西上饶玉山', '[]', '[]', '抗日战争时期', '', '1945年南阳沦陷期间，在伪维持会中担任文书，协助日军登记物资、人口，为日军统治提供情报。；日军侵占临川期间，出面组织地方维持会，为日军征派粮秣、夫役，协助推行伪化统治。；日军侵占南城期间，出面组织维持会，为日军征派粮秣、夫役，协助推行伪化统治。；在地方推行保甲制度，强征粮食、劳工，监视村民言行，向日军密报抗日活动。；湖北竹山人，抗战期间投敌，任伪竹山教育科科长，推行伪化教育，奴化民众。；宁陵沦陷后投靠日军，组织伪维持会并出任伪宁陵县县长，为日军征集物资、拉夫派款，协助维持日伪在宁陵的统治。；任伪邛崃县保甲长，协助日军征粮征丁，监视当地居民，迫害抗日家属。；在江西日占区出任伪县长，协助日军推行伪化政策，其活动范围涉及赣东北包括景德镇周边地区。；日军侵占玉山期间组织维持会，为日军征集物资、招募劳工。；江西横峰人，横峰沦陷期间任伪维持会长，协助日军统治，压迫当地民众。；在汾阳县组织维持会，协助日军统治，征发物资劳工，配合日军对吕梁地区的扫荡。；日军侵占西沙群岛后，协助日军在永兴岛等地建立伪政权，组织渔民为日军服务，搜集南海情报。；在上饶县城及周边乡镇搜捕抗日人员，配合日军扫荡，勒索民众财物。；日军侵占金溪期间出面组织维持会，为日军征派粮秣、拉夫，协助建立伪基层保甲，维持日占区秩序。；抗战后期在资溪县组织维持会，协助日军征粮、派夫，并参与搜捕抗日游击人员。', '[]', '2026-09-10 09:57:14.002187', '2026-09-10 09:57:14.002187', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5b6ab10e3bf42458bb8a2af2680e939', '季刚', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南通南通经开区；江苏南通启东；江苏南通如东；江苏南通如皋；江苏南通海安', '[]', '[]', '抗日战争时期', '', '在如东地区推行“治安强化”运动，设立伪乡保长，强征壮丁和粮食。；率伪军多次袭击新四军游击队，杀害抗日群众，烧毁村庄。；指挥伪警察在如皋城内搜捕抗日分子，协助日军进行大逮捕。；带领伪军多次袭击新四军游击队，杀害地方干部。；率伪保安队多次袭击抗日游击队，杀害无辜百姓，抢劫财物，烧毁村庄，罪孽深重。', '[]', '2026-09-10 09:57:14.034099', '2026-09-10 09:57:14.034099', '江苏', '南通', '南通经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5b95b4e4af14e0990e46854d2177595', '张君实', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆铜梁；安徽淮南寿县；重庆云阳', '[]', '[]', '抗日战争时期', '', '担任伪长寿县警察局长，配合日军搜捕抗日志士，镇压当地民众抗日活动，强征捐税。；抗战期间投靠日伪，在铜梁地区组织维持会，协助日军征粮派款、维持地方治安，镇压抗日活动。；率伪保安团配合日军在重庆周边地区扫荡抗日武装。', '[]', '2026-09-10 09:57:14.064044', '2026-09-10 09:57:14.064044', '重庆', '云阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5bcdfae1e844e67b9ec8eb8d1b7bd99', '张敬浩', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东博山', '[]', '[]', '抗日战争时期', '', '伪职：伪上党道道尹；罪行：主政伪上党道期间推行保甲连坐、强征粮物，为日军搜刮资源；来源：项目数据库；备注：籍贯博山（今属淄博），任职山西上党道，汉奸行为在省外；伪职：首任伪上党道道尹；罪行：搭建伪上党道整套行政体系；推行治安强化、保甲连坐，强征粮食、煤炭、劳工，指挥各县伪政权配合日军扫荡太行根据地，推行新民会奴化教育。；结局：抗战胜利后逮捕，汉奸罪重判', '[]', '2026-09-10 09:57:14.080839', '2026-09-10 09:57:14.080839', '山东', '淄博', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5c64dd645774217b5dd63831ad0b411', '李太平', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北天门；湖北孝感；湖北随州随县；湖北黄冈；湖北天门；湖北孝感应城；湖北_孝感_汉川；湖北武汉蔡甸；湖北武汉黄陂', '[]', '[]', '抗日战争时期', '', '伪军将领，在湖北地区参与日军扫荡行动。；黄陂沦陷后组织维持会，协助日军征粮、拉夫，维持沦陷区基层统治。；黄冈人，任伪黄冈县警察局局长，协助日军维持治安，搜捕抗日人员，镇压群众抗日活动。；负责鄂中地区伪清乡事务，指挥伪军在应城、孝感、天门等地搜捕抗日人员、破坏抗日政权。；在淅河镇组织维持会，为日军提供情报、粮秣，强拉民女供日军淫乐。；在应城、天门交界地区建立伪政权，为日军提供膏盐等战略物资，迫害抗日群众。', '[]', '2026-09-10 09:57:14.055721', '2026-09-10 09:57:14.055721', '湖北', '天门', '应城', NULL, NULL, NULL, NULL, '');
