INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5caed1f4d844df5b661b8ba18ad2483', '王念祖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西_太原；山西_太原_示范', '[]', '[]', '抗日战争时期', '', '负责伪民政，推行保甲制度，协助日军清查户口，抓捕抗日分子。；指挥伪警察协助日军特务机关，破坏地下抗日组织，逮捕爱国志士。', '[]', '2026-09-10 09:57:14.021312', '2026-09-10 09:57:14.021312', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5ce34d12f5d4976b8b17e4f9f7b32df', '李仲章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定唐县；河北保定；河北；河北_保定_容城', '[]', '[]', '抗日战争时期', '', '任伪保定地区行政长官，推行日伪保甲制度，强征粮食，镇压抗日活动。；日军占领唐县后出任维持会长，为日军征粮派夫，出卖抗日积极分子。；组织伪警察配合日军清乡，抓捕地下党员，破坏交通线，参与“治安强化运动”。；任伪保定市市长期间，积极推行日伪政权各项政策，强征民夫，搜刮粮食，协助日军建立保甲制度，镇压抗日活动。', '[]', '2026-09-10 09:57:14.040653', '2026-09-10 09:57:14.040653', '河北', '保定', '唐县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5d626e609d649bd8b1b43aa1a2282d4', '万里浪', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华婺城；浙江杭州；江苏南京；安徽芜湖镜湖；陕西渭南华州；陕西渭南；上海长宁；安徽芜湖镜湖；安徽芜湖；湖南湘西泸溪；江西赣州；安徽滁州天长；浙江杭州；江苏南京浦口；陕西_西安；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '其特工活动涉及湖南沦陷区部分城市。；在长宁区活动，负责情报和暗杀，参与多起针对抗日人士的袭击。；率特务在芜湖街头绑架、枪杀抗日青年，破坏地下交通站。；汪伪特工要员，与陕西渭南地区无直接关联。；绑架枪杀抗日青年。；投敌后任伪政治保卫局副局长，进行特务活动。；抗战期间投敌，任伪特工总部江西区副区长，协助马啸天在江西进行特务活动，镇压赣州周边抗日力量。；汪伪特务，活动于江浙皖一带，捕杀抗日人员。；湖北人，汪伪特工头目，在杭州及浙江沦陷区活动，镇压抗日组织。；率侦缉队搜捕抗日分子；浙江人，抗战期间任汪伪特工总部杭州区区长，在浙江金华、杭州等地镇压抗日活动，1946年以汉奸罪被处决。；在南京执行暗杀任务，杀害多名抗日地下党员。', '[]', '2026-09-10 09:57:13.979585', '2026-09-10 09:57:13.979585', '上海', '长宁', '天长', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d5def027d6ff438c91b23b0cce3da88e', '陈小三', NULL, NULL, NULL, NULL, 'exact', 'exact', '宣城水东', '[]', '[]', '抗日战争时期', '', '伪职：水东便衣特务；罪行：汪伪特工站派遣便衣，混迹茶市，侦查游击队交通线，告密抓捕地下交通员。；结局：武工队捕获正法。', '[]', '2026-09-10 09:57:14.071413', '2026-09-10 09:57:14.071413', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
