INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d70e19b2e00b4aeeb782f0d23f4ff941', '敖门达来', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古通辽；内蒙古呼伦贝尔莫力达瓦；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在呼伦贝尔地区指挥伪军参与“讨伐”抗日游击队，烧毁村庄，掠夺财物。', '[]', '2026-09-10 09:57:13.989600', '2026-09-10 09:57:13.989600', '内蒙古', '呼伦贝尔', '莫力达瓦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d713dd0e9c1a426faacf781c9634823e', '徐更生', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；河南许昌许昌经开区；河南许昌；河南商丘睢阳；河南商丘；河南郑州；陕西西安莲湖；云南普洱西', '[]', '[]', '抗日战争时期', '', '在商丘伪政权中主管教育，推行奴化教育，篡改教材，向学生灌输亲日思想，属文化教育领域附逆者。；协助日军在许昌建立伪政权，参与征粮、派夫等事务。；河南南阳人，抗战期间投敌，任伪南阳合作社理事长，协助日军统制经济，掠夺南阳物资。；郑州沦陷后任伪商会会长，为日军筹措军需物资，协助经济掠夺，并参与奴化宣传。；在华北任伪军职，配合日军扫荡，对陕西周边有威胁。', '[]', '2026-09-10 09:57:14.046863', '2026-09-10 09:57:14.046863', '河南', '南阳', '宛城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d73407ff028644beaad71eb44de7ced7', '张里元', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东临沂；山东日照；山东烟台；四川南充南部；山东临沂平邑；山东临沂；山东济宁梁山；山东济宁；山东临沂郯城；山东临沂；山东临沂罗庄；山东临沂；山东枣庄市中；山东枣庄；山东临沂河东；山东临沂；山东临沂；山东临沂兰陵；山东临沂；山东枣庄薛城；山东枣庄；山东枣庄台儿庄；山东临沂沂南；山西阳泉城区；山东临沂；山东临沂临沭；山西阳泉城区；山东济宁泗水；山东济宁邹城；山东济宁；山东临沂兰山；山东临沂；山东临沂临沂高；山东临沂；山东临沂费县；山东临沂；山东枣庄滕州；山东枣庄；山东济宁；山东菏泽', '[]', '[]', '抗日战争时期', '', '原为国民党地方武装，后率部投敌，在鲁西、济宁一带为日军效力，进攻抗日武装。；伪鲁南道辖泗水等县，其推行治安强化运动，配合日军对鲁南抗日根据地封锁扫荡。；在鲁南地区投敌，组织伪军配合日军行动，活动范围包括枣庄、滕县一带，参与对抗日根据地的扫荡。；原为山东地方武装首领，活动于鲁南、枣庄、临沂一带，抗战中后期与日伪勾结，所部部分投敌，配合日军对付八路军和地方抗日力量。；投敌后控制临沂城区警察与伪警备队，搜捕抗日人员，配合日军对临沭、莒南等根据地进行经济封锁和清乡。；在临沂、沂水一带活动，抗战中后期与日伪勾结，接受伪职，配合日军进攻抗日根据地。；在临沂地区附逆，历任伪职，配合日军进行治安强化运动，参与清乡、征粮和情报搜集。；日军在临沂设立伪沂州道后出任道尹，管辖临沂、郯城、费县等县，推行伪化教育、经济统制，为日军征集物资，其道署驻临沂城，直接影响罗庄地区。；在临沂一带收编土匪、散兵组织伪保安团，配合日军扫荡抗日根据地，袭击八路军和地方抗日武装。；在临沂及鲁南地区反复于抗日与附逆之间，后期部分部属投伪，配合日军维持地方伪秩序。；在菏泽及周边地区为日军效力，组织伪警察与伪军，参与清乡与扫荡。；率部投降日军后编为伪峄县警备队，配合日军扫荡枣庄、峄县一带抗日根据地，捕杀抗日人员。；在鲁南地区包括邹县、济宁一带配合日军剿共，进攻抗日根据地。；在临沂及周边地区参与伪政权事务，协助日军推行治安强化运动，控制交通线和乡村保甲。；原在临沂、费县一带活动，抗战后期动摇投敌，所部部分被伪化，配合日军进攻抗日根据地。；在临沂、沂水一带活动，抗战中后期与日伪保持暧昧关系，其部属有投敌行为，对当地抗日力量造成损害。；在日军占领临沂期间担任伪警察头目，负责维持城区治安，抓捕抗日嫌疑人员，协助日军推行保甲制度。；在临沂沦陷后投敌，任伪警察局长，协助日军搜捕抗日人员，推行治安强化运动。；率部投敌后任伪临沂县警备队队长，配合日军扫荡沂蒙抗日根据地，抓捕抗日人员。；临沂沦陷后出面组织伪维持会，协助日军维持城区秩序、征粮派款，诱迫商户和居民服从伪政权，为日军侵华提供后勤支持。；日军侵占临沂后出面组织维持会，为日军筹粮筹款、拉夫，协助建立伪基层政权。；原国民党山东省保安部队将领，1943年投敌，所部在鲁东南日照、莒县一带配合日军行动。；原为国民党山东省第三区专员，1943年率部投敌，任伪鲁南道尹，辖枣庄、峄县、台儿庄等地，配合日军扫荡鲁南抗日根据地。；在山东南部及胶东部分地区任伪道尹，协助日军推行保甲制度，征发劳工，镇压抗日活动。；原国民党地方武装，后投敌任伪军师长，在济宁周边配合日军进攻抗日根据地。', '[]', '2026-09-10 09:57:14.012139', '2026-09-10 09:57:14.012139', '山东', '临沂', '临沂高', NULL, NULL, NULL, NULL, '');
