INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d776b67881d24934aa794600fe93f8ee', '王文质', NULL, NULL, NULL, NULL, 'exact', 'exact', '包头', '[]', '[]', '抗日战争时期', '', '伪职：伪市公署警务股长、翻译；维持会骨干，懂日语，协助日军审讯抓捕爱国人士。1940 年傅作义攻包之后被日军怀疑通敌逮捕，押往张家口杀害。；结局：1940 张家口秘密枪杀', '[]', '2026-09-10 09:57:14.082892', '2026-09-10 09:57:14.082892', '内蒙古', '包头', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d77717cf958443d0a2330c06b0d7e14e', '王宝庆', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东德州宁津；山东德州', '[]', '[]', '抗日战争时期', '', '日军侵占德州后出任伪德县县知事，推行伪化统治，为日军筹集物资、修筑据点，镇压抗日活动。', '[]', '2026-09-10 09:57:14.013927', '2026-09-10 09:57:14.013927', '山东', '德州', '宁津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d777c9f0815f45eb9f101a2d4ee43702', '张采芹', NULL, NULL, NULL, NULL, 'exact', 'exact', '祁阳县文明铺', '[]', '[]', '抗日战争时期', '', '伪职：日伪祁阳文明铺维持会会长；罪行：1944年日军侵占祁阳后，在文明铺成立维持会，日军指令张采芹担任会长。他为讨好日军，提供村民消息、搜罗村姑供日寇取乐泄欲。在一次宴会中，其三姨太和女儿被日军当着面奸淫，三姨太和女儿后被日军带走充当军妓；结局：1945年春醒悟后与祁东自卫队联系，提供日军驻点布防信息，并亲自带手榴弹炸毁日军碉堡，在战斗中壮烈牺牲', '[]', '2026-09-10 09:57:14.072744', '2026-09-10 09:57:14.072744', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7833e015043486a9d17031b9b8fd59e', '色楞栋鲁布', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古锡林郭勒正蓝旗；内蒙古锡林郭勒锡林浩特；广西桂林资源；内蒙古锡林郭勒东乌珠穆沁旗', '[]', '[]', '抗日战争时期', '', '锡林郭勒盟出身，参与伪蒙疆政权，在锡林郭勒盟一带协助日本推行殖民政策。；锡林郭勒盟王公，附逆日伪，在伪锡林郭勒盟政权中任职，协助日军控制当地牧民和资源。；在东乌珠穆沁旗任伪旗长，投靠日本，协助日军在乌珠穆沁地区推行伪政权的行政、治安与物资征集。', '[]', '2026-09-10 09:57:13.992396', '2026-09-10 09:57:13.992396', '内蒙古', '锡林郭勒', '东乌珠穆沁旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7854dbe7bcc4300a669658dd64c8da8', '吴颂皋', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海虹口；浙江杭州；陕西_西安；江苏南通通州；安徽芜湖镜湖；浙江_杭州_西湖；安徽芜湖镜湖；安徽芜湖；江苏苏州；重庆_大足；上海徐汇；上海静安；上海_黄浦；陕西西安长安；江苏南京浦口；江苏_南京；上海杨浦；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '负责伪上海警察系统，在杨浦地区设立分局，协助日军搜捕抗日人士，残害百姓。；参与伪政府行政事务，在徐汇区协助日伪征收捐税，压迫市民。；长期担任伪市政府秘书长，参与策划对静安等地的“清乡”行动，协助汪伪政权镇压抗日力量。；协助傅筱庵管理伪市政府，参与制定奴化教育政策，迫害爱国师生，为日军征用民房和物资。；浙江杭州人，汪伪外交官，代表伪政权与日本签订卖国条约，承认日本在华特权。；代表汪伪与日本交涉，签署卖国条约。；专门侦缉抗日地下党员，严刑逼供，破坏中共芜湖支部组织。；汪伪政权核心成员，曾任伪上海市府秘书长，参与制定镇压抗日法令，协助日军在虹口及全沪推行保甲制度。；在江苏（含苏州、常熟）推行奴化教育，篡改历史教材，强迫学生效忠汪伪和日本。；在南通、通州建立伪警察网络，搜捕抗日分子，执行日军命令。；在南京参与制定镇压抗日活动的法律条文。；投敌后任伪司法行政部长，配合日军。；严刑逼供抗日志士。；协助伪市长处理日常政务，执行日伪命令；设立伪法院，以“反日”罪名判处抗日志士死刑，镇压正义力量。；在汪伪政权中任外交要职，参与对日妥协。', '[]', '2026-09-10 09:57:13.976423', '2026-09-10 09:57:13.976423', '安徽', '芜湖', '镜湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d79f443c08fb4a7facea5ffbe58e9e24', '王鸿年', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州瑞安；浙江舟山嵊泗；浙江舟山；浙江温州鹿城；浙江温州永嘉；浙江温州龙港；浙江温州永嘉', '[]', '[]', '抗日战争时期', '', '任伪永嘉县知事，推行日伪政令，组织伪警察和保甲制度，强征民夫物资，迫害抗日家属。；在日军占领温州期间出任伪永嘉县知事，为日军提供粮食和劳役，协助日军清乡，逮捕抗日分子。；在舟山定海为日军征粮征税，协助日军控制海岛，镇压渔民抗日活动。；任伪瑞安县知事，推行日伪政令，组织维持会，协助日军清剿抗日游击队。', '[]', '2026-09-10 09:57:14.051473', '2026-09-10 09:57:14.051473', '浙江', '温州', '瑞安', NULL, NULL, NULL, NULL, '');
