INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7df9905348a4f8f8a04ae006083f6d3', '李德山', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；山西阳泉城区；湖北宜昌', '[]', '[]', '抗日战争时期', '', '统率伪保安队，配合日军搜捕抗日人员，镇压民众反抗。；在武昌统率伪保安队，协助日军管理武昌城区。', '[]', '2026-09-10 09:57:14.056112', '2026-09-10 09:57:14.056112', '湖北', '宜昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7e6b9bc62ce40f7ad6b8de19a90cabe', '周化南', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；安徽蚌埠怀远；江苏_宿迁_宿豫；安徽淮南凤台；山西阳泉矿区；安徽淮南；安徽淮南田家庵；安徽_合肥_长丰；江苏_宿迁_宿城；河南三门峡陕州；江苏宿迁宿迁经开区；安徽_蚌埠；河南漯河；河南许昌；河南许昌襄城；河南许昌；河南郑州二七；辽宁沈阳新民；安徽淮北烈山；青海黄南河南；河南南阳；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '强制推行日语教育，篡改历史教材，宣传“中日亲善”，迫害爱国教师。；任伪豫西道尹，管辖陕州、灵宝、渑池等县伪政，推行日军政策，镇压抗日活动。；在许昌推行奴化教育，改编教材，向学生灌输亲日思想，协助日军进行文化侵略。；推行奴化教育，强制学校教授日语，删改历史教材，灌输“中日亲善”思想。；许昌沦陷后任维持会长，为日军筹粮筹款，协助日军管理平汉铁路许昌至漯河段。；率伪军驻扎淮南、潘集一带，参与日军“扫荡”，在潘集地区烧毁村庄，杀害抗日家属，掠夺牲畜粮食。；担任伪淮南保安大队长，率伪军配合日军扫荡田家庵周边抗日武装，残害百姓。；任伪河南教育厅厅长，推行奴化教育，篡改教材，向学生灌输亲日思想。；统管伪河南警务，驻开封，指挥搜捕抗日人员，实施恐怖统治。；任伪淮南县知事，推行日伪保甲制度，强征粮食，协助日军维持矿区治安。；原地方民团头目，投敌后任伪保安大队长，在烈山、蔡里一带多次袭击抗日游击队，杀害抗日军属，并配合日军“清乡”。；为日军征收苛捐杂税，盘剥商民，支持伪政权运转。；任伪警察局长，协助日军搜捕抗日地下党员，破坏中共地下交通站，镇压群众反抗。；在开封控制舆论，进行亲日宣传，粉饰日军侵略。；任伪县知事期间，推行保甲制度，强征壮丁，为日军提供情报，参与“清乡”行动。；河南南阳人，抗战期间投敌，任伪新民会会长，宣传亲日思想，组织亲日团体，奴化民众。；推行奴化教育，篡改教材，向学生灌输亲日思想。；推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，破坏抗日教育，迫害爱国师生。；抗战期间任伪郑州新民会会长，为日军进行奴化宣传，组织亲日团体，协助控制郑州民众思想。', '[]', '2026-09-10 09:57:14.006203', '2026-09-10 09:57:14.006203', '安徽', '淮北', '烈山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7ea5df24b1f4810972a6643f960164e', '唐令欧', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南长沙；长沙', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪长沙市长、伪湖南省设计委员会常务委员、伪复兴会\"主任\"；罪行：湖南最大汉奸。1944年11月任伪长沙市长，并曾署理伪湖南省长。成立伪湖南省设计委员会\"筹备省级傀儡政权。\"；结局：1946年被判处有期徒刑十年。；伪任职务：伪长沙市市长，长沙沦陷时期傀儡首脑，组建伪长沙市自治筹备处。结局：初判十年徒刑，保外后潜逃日本，未归案受重刑新湖南', '[]', '2026-09-10 09:57:14.069393', '2026-09-10 09:57:14.069393', '湖南', '长沙', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7eece3d14c44575bb331782c1d261ca', '麦兆丰', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南儋州', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：儋县海头伪维持分会会长，勾结伪警察姜氏四霸下乡劫掠、刺探情报党史学习教...。结局：1939 年被抗日军民捕获处决', '[]', '2026-09-10 09:57:14.073975', '2026-09-10 09:57:14.073975', '海南', '儋州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d7f917c9538845cc8222178b057bf56c', '陈泰', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳南山；广东深圳；广东深圳龙岗', '[]', '[]', '抗日战争时期', '', '率伪军驻守宝安、深圳一带，协助日军封锁抗日根据地，参与对东江纵队的围剿。；在龙岗组织维持会，为日军提供粮食、劳工，协助维持占领区秩序。', '[]', '2026-09-10 09:57:14.029007', '2026-09-10 09:57:14.029007', '广东', '深圳', '南山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8096a81d8924bd9a8060c16a23b4078', '吴应墀', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江；九江县（今浔阳区）', '[]', '[]', '抗日战争时期', '', '伪职：伪九江治安维持会会长；罪行：1938年冬在日军扶持下成立九江维持会，为日军维持城区治安、征粮征夫、管控百姓；结局：史料未明确记载其最终结局（来源：九江沦陷初期核心汉奸，维持会为伪九江县政府前身）；伪职：伪治安维持会会长；罪行：伪难民整理委员会改组为伪治安维持会，担任会长，协助日军管控城区民众；来源：九江市史志办、江西党史方志网；备注：九江伪维持会首任会长', '[]', '2026-09-10 09:57:14.078893', '2026-09-10 09:57:14.078893', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d819e2e8abe34c65911ff5eaa4649aed', '葛寿山', NULL, NULL, NULL, NULL, 'exact', 'exact', '涿鹿', '[]', '[]', '抗日战争时期', '', '伪职：伪涿鹿警备大队长；驻守涿鹿城、矾山据点，配合桑矾事变，搜捕抗日干部。；结局：涿鹿解放被俘处决', '[]', '2026-09-10 09:57:14.084667', '2026-09-10 09:57:14.084667', '河北', '张家口', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d81ca055924f48f7a1f704745884d32c', '李垣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林长春德惠；吉林；河北唐山；广西桂林资源；河北唐山遵化；北京、吉林、河北；河北廊坊固安；天津河北；河北承德；北京_通州；河北唐山；河北_唐山_路南', '[]', '[]', '抗日战争时期', '', '负责伪政权建设事务，为日军修建军事设施、公路，强征劳工，服务日军侵略。；作为日本关东军顾问的帮凶，在吉林参与制定“治安”政策。；负责伪政权建设事务，在唐山地区强征劳工修建军事设施。；负责伪政府管辖区域（含唐山、丰南）的交通和工矿资源开发，为日军掠夺开滦煤矿等资源服务。；负责伪政权下唐山矿区及交通设施管理，配合日军掠夺开滦煤矿资源。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995000', '2026-09-10 09:57:13.995000', '吉林', '长春', '德惠', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8215e3568004293b539cc3de22a8be3', '梁永燊', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山高明；广东佛山；广东佛山三水；广东佛山；广东肇庆四会；广东肇庆高要', '[]', '[]', '抗日战争时期', '', '在南海县伪警察系统任职，配合日军搜捕抗日人员，控制佛山、南海一带治安，镇压民众抗日活动。；在佛山地区依附日伪，参与伪政权基层统治，协助日军推行保甲、征丁、征粮。；在高要组织伪维持会，为日军筹粮筹款，诱降地方士绅，协助建立伪政权。；在高要县组织伪维持会，协助日军控制西江沿线，征调民夫物资，压制当地抗日活动。；高明沦陷后出面组织伪维持会，为日军征集粮食、民夫，协助日军维持高明地区统治。；汪伪政权委任的顺德伪县长，在顺德及佛山周边地区为日军征粮、征税，破坏抗日根据地。；在佛山及南海一带组建伪警察队伍，配合日军搜捕抗日志士，勒索商户，残害百姓。', '[]', '2026-09-10 09:57:14.026170', '2026-09-10 09:57:14.026170', '广东', '佛山', '三水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8253829d22f48529bbd9ea3a9212971', '王赞亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东临沂平邑；山东临沂', '[]', '[]', '抗日战争时期', '', '在临沂城内为日伪筹款筹物，协助经济统制，压迫商户，为日军侵华提供物资支持。', '[]', '2026-09-10 09:57:14.012782', '2026-09-10 09:57:14.012782', '山东', '临沂', '平邑', NULL, NULL, NULL, NULL, '');
