INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d845fc3bb0a940c4ae71a0e1bfa18d1b', '曹养吾', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南郴州北湖；湖南郴州苏仙；湖南郴州', '[]', '[]', '抗日战争时期', '', '收编地方游杂武装投靠日军，率伪军配合日军扫荡郴县周边乡村。；郴县沦陷期间附逆，参与伪教育组织，推行奴化宣传，为日军占领政策服务。；受日军指使筹组伪郴县县政府，拉拢地方士绅附逆，推行伪化统治。', '[]', '2026-09-10 09:57:14.059702', '2026-09-10 09:57:14.059702', '湖南', '郴州', '北湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d848805d298247af855d0417709dc606', '吴锦堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江湖州安吉；河南郑州中牟；浙江嘉兴南湖；上海杨浦', '[]', '[]', '抗日战争时期', '', '在杨浦地区（杨树浦纺织区）为日军征用棉纱，压榨工人。；为日军和伪政权筹措军饷，垄断粮食和食盐贸易，从中牟利，并强迫商户捐款支持日军。；勾结日军，垄断南湖地区粮食和丝绸贸易，为日军提供军需，从中牟取暴利。', '[]', '2026-09-10 09:57:13.978359', '2026-09-10 09:57:13.978359', '上海', '杨浦', '南湖', NULL, NULL, NULL, NULL, '');
