INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8838ba19f74427397c21aa613e806af', '张福元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权；山西晋中榆社；山西、河北；河北唐山遵化', '[]', '[]', '抗日战争时期', '', '为日军提供榆社抗日政府活动情报，导致多次袭击，损失惨重。；率伪保安队多次袭击遵化境内的抗日游击队，杀害抗日群众，烧毁村庄。；率伪警察配合日军“扫荡”，抓捕抗日军民，破坏地下组织，参与制造多起惨案。', '[]', '2026-09-10 09:57:14.022525', '2026-09-10 09:57:14.022525', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d88509e63ab44daca7efc09132a57c7e', '陈汉光', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南屯昌；海南临高；海南五指山；海南万宁；海南三沙南沙；江西景德镇昌江；海南三沙中沙；海南三沙西沙；海南东方；海南保亭；海南保亭；广西贵港桂平；广西贵港；海南琼中；海南白沙；海南白沙；内蒙古乌海海南', '[]', '[]', '抗日战争时期', '', '在白沙地区为日军征粮、带路，配合日军对白沙抗日根据地进行骚扰。；参与海南伪经济统制，为日军掠夺橡胶、铁矿、盐等战略物资，压榨民众。；在临高地区组织伪政权，协助日军征粮派夫，配合日军扫荡抗日游击队。；在日军扶植的伪广西政权中任职，参与伪警察系统的组建与运作，活动范围覆盖贵港、桂平一带。；在万宁地区为日军筹粮，组织伪自卫军。；组织亲日青年团体，协助日军宣传和情报搜集，诱骗青年加入伪军。；在感恩地区投敌，协助日军维持治安，推行保甲连坐，迫害抗日人员。；在保亭地区推行保甲连坐，协助日军控制山区，征用黎族劳工。；在感恩地区协助日军建立伪政权，征粮征夫，参与对沿海抗日活动的镇压。；昌江沦陷后附逆，任伪昌江县县长，协助日军控制昌江、石碌一带铁矿资源，强征劳工，配合日军掠夺战略物资。', '[]', '2026-09-10 09:57:14.032995', '2026-09-10 09:57:14.032995', '广西', '贵港', '桂平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d888fe812dc346da8028114e8e62df87', '郑鲁岩', NULL, NULL, NULL, NULL, 'exact', 'exact', '宝清、饶河完达山区域；黑龙江鸡西', '[]', '[]', '抗日战争时期', '', '伪职：原抗联七军政治部主任，叛变特务；罪行：被俘投敌，完整出卖东线抗联全部密营坐标、交通网、地下救国会人员名册，致使宝清??饶河抗联根据地遭受毁灭性扫荡。；结局：抗战胜利后被民主政府逮捕处决。', '[]', '2026-09-10 09:57:14.066681', '2026-09-10 09:57:14.066681', '黑龙江', '双鸭山', NULL, NULL, NULL, NULL, NULL, '');
