INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8b2b796570c43caa22164075613d45e', '周道刚', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川成都邛崃；四川成都；四川资阳；四川成都', '[]', '[]', '抗日战争时期', '', '任伪成都市维持会委员，协助日军维持地方秩序，推行奴化教育，为日军征集物资。；四川籍旧官僚，在成都组织伪维持会，后任伪省联合会副会长，协助日伪控制四川地方政权。', '[]', '2026-09-10 09:57:14.002235', '2026-09-10 09:57:14.002235', '四川', '成都', '邛崃', NULL, NULL, NULL, NULL, '');
