INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8c05394c09a4541bceaff4edba0378a', '陈德山', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北宜昌；湖北孝感；汶上县', '[]', '[]', '抗日战争时期', '', '伪职：伪大队长（刘本功部）；罪行：汶上县康驿人。早年在戏班唱戏，1941年以蜀山湖为据点拉帮为匪。1942年投靠刘本功，任伪大队长，活动汶上、济宁、宁阳交界。到处劫掠，捕杀民兵、农会干部；多次随伪军下乡“清乡”。抗战胜利后变本加厉，配合国民党84师疯狂袭击屠杀共产党干部和群众，两三年间杀害干部群众几百人；结局：抗战胜利后投靠国民党。1951年2月在哈尔滨被抓获，押解济宁后处决', '[]', '2026-09-10 09:57:14.056161', '2026-09-10 09:57:14.056161', '湖北', '宜昌', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d8c208ecbce243ddb1e3a335d1e00a2d', '赵福堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '阜新', '[]', '[]', '抗日战争时期', '', '伪职：阜新炭矿翻译兼特务头目；罪行：充当日军翻译，领导 17 名华人特务；在海州、新邱、太平、孙家湾各矿区侦查、抓捕反日矿工，刑讯迫害爱国工人，告密抓人。；结局：解放后矿区公审枪决。', '[]', '2026-09-10 09:57:14.071334', '2026-09-10 09:57:14.071334', '辽宁', '阜新', NULL, NULL, NULL, NULL, NULL, '');
