INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d9351c074ab6468ba6d607c9387cc1bc', '王福堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江伊春嘉荫；黑龙江佳木斯汤原；山东滨州博兴；黑龙江双鸭山；山东滨州无棣；山东滨州；山东淄博淄川；山西阳泉矿区；黑龙江伊春大箐山；山东济南商河；江西宜春；黑龙江鸡西；山东滨州沾化', '[]', '[]', '抗日战争时期', '', '鸡西商界人物，投靠日伪，任伪商会会长，协助日军征购物资、控制经济。；在沾化县城组织维持会，迎接日军入城，后任伪县长，为日军筹粮筹款，协助建立伪保甲制度。；在商河基层推行保甲连坐，协助日军征粮、抓丁。；在鲁中地区组织伪军，协助日军控制淄博矿区。；铁骊县（今铁力市，邻近伊春、大箐山）保甲长，推行保甲连坐，协助日军征粮、抓劳工，镇压当地抗日群众。；在蒲台县组织维持会，后任伪县长，为日军征集物资，建立伪自卫团，配合日伪军清乡。；博兴县经济界汉奸，为日军统制物资，强征商税，低价收购农产品供给日军，配合经济封锁抗日根据地。；负责双鸭山煤矿劳工管理，虐待矿工，强制劳动，导致大量劳工死亡。；为日军筹款筹粮，强制商户缴纳“治安费”，协助日军控制当地物资。；任伪汤原县县长，辖区与伊春、嘉荫相邻，推行归屯并户，配合日军讨伐抗日联军。；日军侵占无棣后出面组织维持会，为日军筹粮筹款、带路清乡，压迫当地民众。', '[]', '2026-09-10 09:57:14.015170', '2026-09-10 09:57:14.015170', '山东', '济南', '商河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d9354c48743544e49d8c8bc86456cd8b', '喇世俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '甘肃天水', '[]', '[]', '抗日战争时期', '', '天水本地人，抗战期间组织伪天水县维持会并任会长，为日军提供物资、情报，协助维持日占区秩序。', '[]', '2026-09-10 09:57:14.060143', '2026-09-10 09:57:14.060143', '甘肃', '天水', '秦州', NULL, NULL, NULL, NULL, '');
