INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d9a440b1ed0848b993ccf75678d3cd65', '凌升', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古呼伦贝尔；北京大兴；黑龙江黑河嫩江；黑龙江_鹤岗_兴安；黑龙江鹤岗兴安；内蒙古呼伦贝尔新巴尔虎右旗；黑龙江鹤岗兴安；内蒙古呼伦贝尔；内蒙古呼伦贝尔新巴尔虎左旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔陈巴尔虎旗；黑龙江鹤岗兴安；内蒙古呼伦贝尔', '[\"蒙古族\"]', '[]', '抗日战争时期', '', '曾任伪兴安北省省长，后因对日本关东军不满被日军以“通苏”罪名处决，但其前期在伪职期间执行了日本殖民统治政策。；曾任伪兴安北省省长，后因与日本关东军产生矛盾，被指控“通苏通蒙”罪名，于1936年被日军处决，但其前期曾协助日伪建立统治。；曾任伪兴安北省省长，后因与日本关东军矛盾被处死，但前期曾协助日军建立伪政权；初期投靠日本，任伪兴安北省省长，后因反对日本移民政策及秘密联络抗日势力，于1936年被日本关东军以“通苏”罪名处决。；初期为日伪效力，后因与日本关东军产生矛盾被处决，但此前在陈巴尔虎旗地区执行过日伪行政命令。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.987775', '2026-09-10 09:57:13.987775', '内蒙古', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d9ac34e0fb434304b47946f50012e65f', '拉木栋鲁布', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古锡林郭勒东乌珠穆沁旗', '[]', '[]', '抗日战争时期', '', '在乌珠穆沁左旗任伪旗长，配合日军和伪蒙疆政权，在锡林郭勒盟东部地区推行殖民统治。', '[]', '2026-09-10 09:57:13.992404', '2026-09-10 09:57:13.992404', '内蒙古', '锡林郭勒', '东乌珠穆沁旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('d9ac9f65d56b450d89faa7646bae9fa6', '孙玺凤', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海威海经开区；山东威海；山东淄博淄川；山东淄博博山；山东威海文登；山东威海；山东威海；山东威海威海临港经开区；山东威海；山东淄博；山东威海荣成；山东淄博桓台；山东淄博临淄；山东威海威海火炬高；山东威海', '[]', '[]', '抗日战争时期', '', '日军侵占威海卫后出面组织伪政权，任伪威海卫特别行政区专员，协助日军维持占领秩序、征发物资。；抗日战争时期投靠日军，出任伪威海卫特别行政区专员，协助日军维持威海卫及环翠一带的殖民统治，推行伪化政策。；日军侵占荣成后出任伪县知事，推行伪政权政策，征粮征夫，协助日军控制荣成地区。；在临淄地区任伪县长，配合日军维持占领区秩序，征粮征夫，镇压抗日群众，活动范围与桓台相邻。；在威海卫组织伪保安队，配合日军维持治安、搜查抗日人员，参与对周边抗日根据地的扫荡和封锁。；抗日战争时期投靠日军，出任伪威海卫专员公署专员，协助日军维持威海卫及周边地区统治，推行伪化政策。；原威海卫管理公署人员，日军占领后留任伪职，协助日军管理威海卫地方事务。；抗战期间附逆，任伪威海卫商会会长，为日军筹集物资、推行经济掠夺，协助维持伪统治秩序。；在博山地区为日军效力，管理伪政权，协助掠夺煤炭资源。；在文登（今威海辖区）推行伪政，组织伪自卫团，配合日军对昆嵛山抗日根据地的扫荡。；在山东沦陷区推行奴化教育，影响包括淄博在内的学校，宣传“中日亲善”。', '[]', '2026-09-10 09:57:14.013021', '2026-09-10 09:57:14.013021', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
