INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('da7c322309ed441aa9255a70f8e41dd1', '朱万金', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西瑞昌；瑞昌县（今瑞昌市）', '[]', '[]', '抗日战争时期', '', '伪职：日军向导、瑞昌知名汉奸；罪行：湖北黄梅人，早年在瑞昌做小生意，抗战时为日军带路，引导日军进攻瑞昌磨山、蛤蟆洞等阵地，导致守军一个团全员牺牲，后长期为日军效力、祸害当地百姓；结局：解放后在群众强烈要求下被政府处决（来源：《瑞昌县志》有明确记载的汉奸，瑞昌沦陷期核心带路党）；伪职：汉奸向导；罪行：带领日军突击队偷袭磨山阵地，致使国军阵地失守、大量官兵牺牲，战后被处决；来源：瑞昌县抗战文史；备注：带路型汉奸', '[]', '2026-09-10 09:57:14.076284', '2026-09-10 09:57:14.076284', '江西', '九江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('da7ec5809e8e48efa92c8c8f91b0121e', '李默庵', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南_岳阳_临湘；湖南长沙；湖南岳阳汨罗；湖南株洲渌口；湖南邵阳邵东；湖南邵阳；福建龙岩；湖南邵阳城步；辽宁沈阳大东', '[\"注：实为抗日将领，误收，已删除\"]', '[]', '抗日战争时期', '', '湖南长沙人，长沙沦陷后任伪维持会教育科长，并出任伪长沙中学校长，推行奴化教育，属于教育领域附逆者。；此人在福建龙岩地区有军事活动，但并非汉奸，若严格按汉奸名录不应列入；此处仅说明龙岩地区相关人物复杂，需谨慎区分。；在邵阳沦陷期间，参与伪教育机构，推行奴化教育，宣传“大东亚共荣圈”。；湖南长沙人，抗战后期在湖南地区活动，曾与日伪方面有接触，后率部反正，其部活动范围涉及湘中、湘南一带。；在汪伪政权中任湖南清乡督办，参与日军对湖南抗日根据地的清乡，后向国民政府投诚。；组织伪保安团配合日军扫荡邵阳周边抗日武装，强征民夫、粮食，为日军提供情报。；日军进攻湖南时，曾被日方胁迫或列入伪政权名单，但实际未履职，历史记载存疑。', '[]', '2026-09-10 09:57:14.057839', '2026-09-10 09:57:14.057839', '湖南', '岳阳', '汨罗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('da8be68d50924fc6975bec05390119f0', '邓祖禹', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江；江西吉安；江西赣州信丰；云南普洱西；江西赣州于都；江西九江；江西南昌青山湖；江西南昌；江西上饶婺源；江西上饶；江西南昌；陕西_西安；江西宜春高安；江西南昌；江西赣州宁都；江西南昌；江西上饶余干；江西南昌；云南普洱西；江西南昌安义；江西宜春；江西吉安永新；云南普洱西；江西赣州；云南普洱西；江西南昌东湖；江西南昌；汪伪江西省政府（省治九江）；云南普洱西；江西南昌；江西赣州全南；江西赣州', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：汪伪高级汉奸；罪行：汪伪政权警政部常务次长、首都警察厅长，1943年出任汪伪江西省省长，在汪伪政权内主管警务、搜刮资源，抗战胜利后被捕审判；来源：近代汪伪史料、人物传记；备注：籍贯宜春，长期在南京、九江汪伪辖区任职，极少回宜春本地活动；伪职：汪伪江西省长兼江西省保安司令部司令；罪行：1943年5月出任汪伪江西省长，管辖九江、南昌等赣北沦陷区，配合日军推行殖民统治、掠夺资源、镇压抗日力量；结局：1943年12月被免职，1947年8月仍被苏州高等检察处通缉在逃，最终结局史料未明确记载（来源：汪伪江西省政府1943年6月在九江成立，为抗战时期江西日伪最高政权）；伪任职务：汪伪首任伪江西省省长、保安司令，省府驻九江，统辖赣北伪政权。结局：抗战胜利被捕，判处徒刑，狱中病逝', '[]', '2026-09-10 09:57:14.037080', '2026-09-10 09:57:14.037080', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('da9512d7972748a7b9c4d01d1a8e5166', '赵炎午', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡东；湖南衡阳', '[]', '[]', '抗日战争时期', '', '湖南湘南地区附逆人物，参与组织伪自治机构，协助日军在衡阳、衡东一带推行伪化统治。', '[]', '2026-09-10 09:57:14.059581', '2026-09-10 09:57:14.059581', '湖南', '衡阳', '衡东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('da9838388a2e44feb5a41e4377fa842d', '郭步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中昔阳；山西；山西朔州；山西大同天镇', '[]', '[]', '抗日战争时期', '', '组织地方伪保安团，配合日军“扫荡”天镇南山抗日游击队，杀害多名抗日群众，烧毁村庄。；率警备队配合日军‘铁壁合围’，在昔阳东部山区烧毁村庄，抢掠物资，杀害抗日军属。；投靠日军，任怀仁县警备大队长，参与“扫荡”朔州西部抗日根据地，杀害多名游击队员。', '[]', '2026-09-10 09:57:14.020983', '2026-09-10 09:57:14.020983', '山西', '大同', '天镇', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('daa6e8ee782a4ea3a47074f9a797d7a9', '李祖龄', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪盂县知事；罪行：盂县早期伪主官，建立完整伪行政体系，推行保甲、苛捐杂税。；结局：战后逮捕判刑阳泉市人大...', '[]', '2026-09-10 09:57:14.085055', '2026-09-10 09:57:14.085055', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('daad91e88b1540d78c5ce7fb573ebc38', '高子明', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店驻马店经开区；河南驻马店正阳；河南驻马店汝南；黑龙江鹤岗南山；河南驻马店；河南开封', '[]', '[]', '抗日战争时期', '', '正阳沦陷后出面维持，为日军筹款筹粮，协助建立伪警察所与保甲组织。；在泌阳县城组织伪维持会，协助日军控制豫南山区边缘地带，为日军提供情报和物资。；泌阳属驻马店地区，任维持会会长，协助日军征粮、清乡，迫害抗日群众。；在开封实施特务统治，抓捕抗日嫌疑人员。', '[]', '2026-09-10 09:57:14.048176', '2026-09-10 09:57:14.048176', '河南', '驻马店', '汝南', NULL, NULL, NULL, NULL, '');
