INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dad4d6ace33a46869b84b9a7c9970499', '赵龙田', NULL, NULL, NULL, NULL, 'exact', 'exact', '郑县', '[]', '[]', '抗日战争时期', '', '伪职：日本特务机关汉奸（山东人）；罪行：1936年被日本特务志贺秀二收买，为日本驻郑州领事馆搜集情报、勾结土匪刘桂堂企图暴动；结局：1937年1月暴露被捕，被处以死刑', '[]', '2026-09-10 09:57:14.083337', '2026-09-10 09:57:14.083337', '山东', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dae3ac4294e14f94ac9ebe1920fb3d6f', '郭子彬', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳邓州；河南南阳新野；河南南阳方城；河南南阳；河南洛阳洛宁', '[]', '[]', '抗日战争时期', '', '1945年日军侵占南阳后，出任伪南阳商会会长，为日军筹款、筹粮，协助日军控制南阳经济。；1945年日军占领新野后，出面组织维持会，协助日军征粮征夫，镇压抗日活动。；洛宁沦陷后出面组织维持会，为日军筹粮、派款、拉夫，并协助建立伪保甲。', '[]', '2026-09-10 09:57:14.047150', '2026-09-10 09:57:14.047150', '河南', '南阳', '方城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dae6eb74d6414b69baf3c29212d42aba', '林光明', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建泉州德化；福建泉州', '[]', '[]', '抗日战争时期', '', '在泉州晋江一带参与日伪维持会活动，协助日军征粮、派款、维持地方秩序，属于基层附逆人员。', '[]', '2026-09-10 09:57:14.061682', '2026-09-10 09:57:14.061682', '福建', '泉州', '德化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dae80fd030aa4dd69e951af317e6258d', '孙景堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽源', '[]', '[]', '抗日战争时期', '', '伪职：伪西安煤矿劳务系华人头目；罪行：协助日本人管理矿工，抓捕管控特殊工人（战俘劳工），迫害反抗矿工。；结局：反奸清算，判处长期徒刑。', '[]', '2026-09-10 09:57:14.085998', '2026-09-10 09:57:14.085998', '吉林', '辽源', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('daf436c4204a44fa8efeab529fafd496', '徐老五', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西抚州金溪；江苏盐城建湖', '[]', '[]', '抗日战争时期', '', '充当日伪耳目，举报抗日人员及家属，带领日军搜捕游击队员，强征当地青年充当伪军。；专门刺探新四军和游击队情报，带领日伪军突袭抗日村庄，逮捕并杀害多名抗日积极分子，民愤极大。', '[]', '2026-09-10 09:57:14.036519', '2026-09-10 09:57:14.036519', '江苏', '盐城', '建湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('daf5957554e24e0b91de4f2436ef9c07', '马继武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城；山西晋城高平；山西晋城陵川；山西晋城；山西晋城阳城；山西晋城；山西；云南曲靖；山西晋中介休', '[]', '[]', '抗日战争时期', '', '在高平县建立伪政权，强征粮食，组织伪保安队，协助日军袭击抗日游击队。；效忠日军，负责县城及周边治安，大肆搜捕抗日分子，严刑逼供，并协助日军建立情报网，破坏地下党活动。；协助日军清乡，围剿游击队，残害抗日家属，民愤极大。；率伪军参与“扫荡”晋城、阳城交界山区，杀害抗日军民，抢夺物资。；在阳城、晋城一带活动，为日军招降纳叛，策反国民党地方武装，并组织“新民会”进行奴化宣传。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.985873', '2026-09-10 09:57:13.985873', '云南', '曲靖', '介休', NULL, NULL, NULL, NULL, '');
