INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dbb282e74d314b55b01ea30242e1bfaf', '邓国庆', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江依兰', '[]', '[]', '抗日战争时期', '', '伪职：伪满国军驻鞍山汤岗子第 10 工兵队上校，鞍山伪驻军头目；罪行：原东北军，先参加义勇军，战败投敌；协助日军维持鞍山周边治安，镇压抗日力量。日本投降后收拢伪满军、残留日军，组建鞍山保安队、军警联合司令部，自任司令，勾结国民党进攻我方。1949 年公审时仍高唱日本国歌，态度极其顽固。；结局：1949??05??30 鞍山二台子公审枪决。', '[]', '2026-09-10 09:57:14.084675', '2026-09-10 09:57:14.084675', '黑龙江', '哈尔滨', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dbb9baa45643457fa4b2afab3180a295', '吴雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华义乌；浙江金华；海南三沙中沙；广西桂林资源；海南海口龙华；海南海口', '[]', '[]', '抗日战争时期', '', '率伪军在琼山、海口一带配合日军作战，参与清乡、扫荡和镇压抗日群众。；率伪保安队多次袭击抗日武装，在金华、义乌交界处设卡盘查，搜捕抗日地下党员，并参与日军“三光”行动。；在儋县地区组织伪政权，配合日军维持治安，搜捕抗日人员，掠夺地方资源。', '[]', '2026-09-10 09:57:14.052477', '2026-09-10 09:57:14.052477', '浙江', '金华', '义乌', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dbbd275324094067bcbdb7965a2e4a1d', '何国涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华；浙江宁波慈溪；浙江宁波海曙；浙江宁波北仑；山西阳泉城区；浙江宁波镇海；浙江绍兴；浙江绍兴诸暨；浙江_宁波', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”。；率伪军驻绍兴、上虞，多次参与“清乡”，杀害抗日军民，掠夺财物。；在镇海各乡镇推行保甲连坐，强征壮丁，为日军修建工事。；在宁波城区及周边实施日伪统治，协助日军建立情报网，逮捕抗日人士。；以伪法院名义审判抗日群众，判处多名爱国人士徒刑或移交日军处置，充当日伪法律工具。；出任伪商会会长，为日军统制物资、摊派捐款，帮助日伪经济掠夺。；在诸暨县建立伪政权，协助日军建立据点，镇压诸暨抗日游击队。；直属日军宪兵队，刺探抗日情报，逮捕并刑讯地下党员，制造多起惨案。；推行奴化教育，强制学校教授日语，删改历史教材，宣扬“中日亲善”，迫害爱国教师。', '[]', '2026-09-10 09:57:14.050829', '2026-09-10 09:57:14.050829', '浙江', '宁波', '北仑', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dbc6602f3758446cba632c29ac7bd2f4', '程斌', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林；吉林白山靖宇；吉林桦甸；吉林白山浑江；吉林通化', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：原抗联一师师长，叛变投敌，伪满警察大队长，熟知抗联山地战术，给抗联造成巨大损失党史学习教...。结局：建国后被逮捕，1951 年镇压反革命中枪决', '[]', '2026-09-10 09:57:13.999922', '2026-09-10 09:57:13.999922', '吉林', '白山', '浑江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dbcd84802d9640cbab5b3082840af954', '刘士毅', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州', '[]', '[]', '抗日战争时期', '', '在赣南地区推行消极抗日政策，与日伪势力保持暧昧关系，纵容部下参与伪政权活动，镇压赣州、会昌等地抗日群众。', '[]', '2026-09-10 09:57:14.040500', '2026-09-10 09:57:14.040500', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
