INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc3a8bab1db549a387b81f9dd584cf16', '林汝珩', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东茂名；广西桂林恭城；云南普洱西；广东广州越秀；广东江门新会；广东江门；广东_广州；广东韶关；吉林高；广东韶关曲江；广东信宜；浙江杭州西湖', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪广东省教育厅厅长，推行华南奴化教育。结局：抗战胜利逮捕，判处徒刑', '[]', '2026-09-10 09:57:14.026638', '2026-09-10 09:57:14.026638', '广东', '广州', '越秀', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc3b4e233c684b1195094e797684f4c0', '张德钦', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海普陀；浙江舟山普陀；山西阳泉城区；浙江杭州建德；上海静安；浙江杭州上城；江苏扬州江都；浙江宁波奉化；江苏苏州苏州工业园；江苏苏州；浙江金华；浙江杭州拱墅；浙江杭州临安；上海杨浦；上海虹口；江苏_南通_海安；江苏南京浦口；江苏_南京；浙江杭州；浙江杭州西湖；浙江杭州；上海金山；浙江舟山', '[]', '[]', '抗日战争时期', '', '继任伪金山县知事，推行保甲制度，协助日军“清乡”，迫害抗日家属。；负责上城区治安，协助日军和宪兵队搜捕抗日地下工作者，参与多起逮捕和刑讯。；指挥伪警在普陀地区抓捕抗日嫌疑犯，协助日军清乡。；控制静安地区水电交通，为日军军事运输和物资调配提供便利。；在舟山定海配合日军“三光”政策，掠夺渔业资源。；协助潘达管理杨浦地区，参与镇压抗日活动，征收苛捐杂税。；率伪军配合日军扫荡金华周边抗日游击区，参与制造多起屠杀事件。；指挥伪军配合日军在金华、兰溪一带“清剿”抗日游击队，杀害多名抗日志士。；浙江临安人，任伪临安县保安大队长，多次率伪军袭击天目山一带的抗日游击队，抓捕并杀害抗日军民。；在扬州城区任伪警察局长，搜捕抗日志士，破坏地下组织，为日军提供情报。；继任伪江都县知事，组织伪警察和自卫团，配合日军“扫荡”邵伯、樊川等地，抓捕抗日干部。；浙江杭州人，任伪浙江省保安司令，率伪军参与“清乡”和扫荡，杀害抗日军民，战后被处决。；在建德推行伪化统治，强征粮食，破坏当地抗日武装。；在浙江地区组织伪保安队，配合日军“扫荡”，在拱墅及周边地区抓捕抗日军民，破坏地下组织。；协助日军在杭州建立秩序，组织“良民证”发放，搜捕抗日分子。；为日军强征各种捐税，盘剥百姓，导致民不聊生。；率领伪保安队协助日军巡逻虹口，镇压民众反抗，强征壮丁。；在浦口码头为日军装卸军需品，强征劳工。；奉化人，组织伪保安队，配合日军扫荡，杀害抗日游击队员。；负责为日军征用苏州地区船只、车辆，破坏交通线，协助日军运输军需。；协助日军强占江苏土地', '[]', '2026-09-10 09:57:13.977063', '2026-09-10 09:57:13.977063', '上海', '普陀', '浦口', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc3bc628749342eb9f4b06e0a1923918', '王狗剩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权', '[]', '[]', '抗日战争时期', '', '随日军“扫荡”左权县泽城村，烧毁民房30间，杀害老人2人。', '[]', '2026-09-10 09:57:14.022742', '2026-09-10 09:57:14.022742', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc41e915234d440e92cd4d661f0bfe87', '郭文林', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古；内蒙古呼伦贝尔阿荣旗；内蒙古呼伦贝尔；吉林白山；吉林通化；内蒙古呼伦贝尔鄂伦春自治旗；内蒙古呼伦贝尔；内蒙古呼伦贝尔；内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔；黑龙江大兴安岭加格达奇；达斡尔族；内蒙古呼伦贝尔海拉尔；黑龙江鹤岗兴安；黑龙江大兴安岭塔河；北京大兴；内蒙古呼伦贝尔新巴尔虎左旗；内蒙古呼伦贝尔；黑龙江大兴安岭松岭；北京大兴；黑龙江鹤岗兴安；黑龙江大兴安岭呼中；北京大兴；内蒙古呼伦贝尔牙克石；内蒙古呼伦贝尔；内蒙古呼伦贝尔额尔古纳；内蒙古呼伦贝尔；黑龙江绥化海伦；黑龙江齐齐哈尔；内蒙古兴安乌兰浩特；内蒙古呼伦贝尔新巴尔虎右旗；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '伪职：伪第九军管区司令官（驻通辽）；强化草原治安，搜缴民间武器，布置讨伐队镇压反满抗日活动，配合日军清剿辽北、热河游击武装抖音百科。；结局：被俘关押，后特赦释放；伪职：伪满第十军管区中将司令官（驻海拉尔）；指挥兴安警备军，在边境镇压反满抗日活动，抓捕爱国群众，配合日军边境警戒；1945 对苏作战率部投诚苏军。；结局：1950 苏联引渡回国，抚顺战犯管理所改造，后特赦释放抖音百科；率伪军在兴安盟、乌兰浩特一带执行“讨伐”任务，制造多起惨案，强征民夫修筑军事工事。；曾任伪兴安军军官，初期效忠日伪，参与镇压抗日武装，1944年率部起义反正，但此前有助纣为虐行为。；驻守呼伦贝尔地区，参与日军对苏作战准备，镇压当地抗日力量；呼伦贝尔籍达斡尔族军官，率伪兴安军驻防额尔古纳地区，参与对苏边境侦察及镇压当地抗联小分队，后于1945年反正。', '[]', '2026-09-10 09:57:13.987520', '2026-09-10 09:57:13.987520', '内蒙古', '呼伦贝尔', '扎兰屯', NULL, NULL, NULL, NULL, '');
