INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc76f3954f9e4d03990cb18e1b04a03f', '张德润', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江西_萍乡_莲花；北京、河北；河北保定雄县；河北_保定_满城；北京房山', '[]', '[]', '抗日战争时期', '', '率伪保安队多次配合日军扫荡房山抗日根据地，杀害抗日干部和群众，抢劫财物。；指挥伪警察搜捕抗日家属，严刑逼供，破坏地下交通站，导致多名抗日干部牺牲。；率伪警备队多次袭击八路军游击队，破坏抗日组织，勒索百姓，民愤极大。；推行日伪奴化教育，组织汉奸宣传队，强迫群众参加“反共”集会，搜集抗日情报提供给日军。', '[]', '2026-09-10 09:57:13.994351', '2026-09-10 09:57:13.994351', '北京', '房山', '雄县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc7f65acd71c48acb95a4813870d2667', '苗占魁', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海威海火炬高；山东烟台牟平；山东威海乳山；山东威海', '[]', '[]', '抗日战争时期', '', '在牟平及威海周边地区附逆，组织伪军和维持会，配合日军进攻昆嵛山抗日根据地，在威海一带参与扫荡、抢粮、抓捕抗日人员。；盘踞胶东地区，收编土匪武装投靠日军，配合日军进攻胶东抗日根据地，活动范围涉及威海、乳山一带。', '[]', '2026-09-10 09:57:14.013170', '2026-09-10 09:57:14.013170', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc90acdcacce49c69a74fa182e0eef99', '郭凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州定襄；山西忻州五寨；山西；山西忻州繁峙；山西临汾浮山', '[]', '[]', '抗日战争时期', '', '为日军征收各种苛捐杂税，强抢民间粮食和物资，导致浮山百姓生活极度困难。；日军占领五寨后出任维持会长，为日军征派民夫、物资，欺压百姓。；日军占领定襄后率先组织维持会，为日军筹粮派款，提供情报，帮助日军建立伪政权。；在砂河镇为日军征粮派款，告密杀害抗日交通员，协助日军建立据点。', '[]', '2026-09-10 09:57:14.019301', '2026-09-10 09:57:14.019301', '山西', '忻州', '五寨', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc91f96a5b2447509d011a8eb2338140', '王永恩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江绥化青冈；吉林；黑龙江大庆林甸；黑龙江大庆大同；吉林昌邑；山东潍坊昌邑', '[]', '[]', '抗日战争时期', '', '率伪保安队多次进攻抗联根据地，烧毁村庄，屠杀百姓。；在昌邑一带残害抗日军民，参与制造多起屠杀事件，协助日军“讨伐”抗联。', '[]', '2026-09-10 09:57:13.996096', '2026-09-10 09:57:13.996096', '吉林', '昌邑', '林甸', NULL, NULL, NULL, NULL, '');
