INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dc9b299012284d869686a9891054279f', '古鼎新', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆大足；重庆万州；湖北黄冈；武汉（伪军）；湖北_咸宁_通山；湖北_孝感_汉川；襄阳（襄北）', '[]', '[]', '抗日战争时期', '', '伪职：伪军头目（原国民党128师旅长）；罪行：武装势力长期活动襄北一带。反复摇摆，时而投靠国军，后投靠日伪充当伪军头目，出卖情报，纵容手下劫掠百姓。1943年与日军签定密约，将128师城防图全部交给日军，致使128师几乎全军覆没，师长王劲哉被俘；结局：抗战结束后被逮捕，得到应有惩处；伪职：伪军师长；罪行：汪伪军头目', '[]', '2026-09-10 09:57:14.055606', '2026-09-10 09:57:14.055606', '重庆', '大足', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dca21e5965f64b3e87c0f7909b562481', '刘绍唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南郑州郑州高；青海黄南河南；福建泉州南安；辽宁沈阳大东；湖南郴州资兴；湖南郴州；湖南郴州宜章；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '组织伪保安团，配合日军对资兴周边抗日游击区进行扫荡，残害抗日军民。；协助日军在宜章设立据点，办理伪政权事务，为日军搜集情报。；在河南伪政权中负责教育，推行奴化教育，篡改教材，宣传“中日亲善”“大东亚共荣”，毒害沦陷区青年，活动范围覆盖开封及郑州周边。；在伪河南省政府中负责教育事务，推行奴化教育，篡改教材，宣传“中日亲善”“大东亚共荣”，毒害河南沦陷区青年。；在河南豫西地区担任伪道尹，负责伪行政事务，配合日军控制豫西沦陷区，推行征粮、派夫等政策。；湖南安仁人，日军占领安仁期间出任伪保安队队长，带领伪军协助日军清乡、搜捕抗日人员，是安仁地区伪军头目之一。；出任伪中牟县县知事，推行奴化教育，征发劳工，配合日军对中牟地区抗日武装进行清剿。', '[]', '2026-09-10 09:57:14.048983', '2026-09-10 09:57:14.048983', '河南', '郑州', '中牟', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dcb48cd4ae5c44048e6031ebe4741200', '高伯勋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北秦皇岛北戴河；河北秦皇岛', '[]', '[]', '抗日战争时期', '', '参与伪冀东道政务，协调秦皇岛、北戴河地区的日伪行政，为日军提供情报。', '[]', '2026-09-10 09:57:14.044056', '2026-09-10 09:57:14.044056', '河北', '秦皇岛', '北戴河', NULL, NULL, NULL, NULL, '');
