INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dcf2352b5ab14cc6aeddfb503832e600', '吕省吾', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建泉州德化；福建厦门；福建泉州永春', '[]', '[]', '抗日战争时期', '', '日军侵占永春期间出面组织维持会，为日军征粮拉夫，协助推行伪化统治。；福建沦陷区伪政权成员，参与日伪在闽南的统治活动，其影响范围涉及泉州、厦门一带。', '[]', '2026-09-10 09:57:14.061674', '2026-09-10 09:57:14.061674', '福建', '泉州', '德化', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dcfed6757c344cde9d41de25446765fe', '马耀南', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博高青；陕西汉中汉台；陕西汉中', '[\"注：此处为误传，马耀南为抗日烈士，非汉奸\"]', '[]', '抗日战争时期', '', '负责日伪在汉中的宣传事务，散布亲日言论，诋毁抗日力量，为日军侵略制造舆论。；经核实，马耀南为山东抗日游击队第三支队司令员，1939年牺牲，是著名抗日烈士，并非汉奸，故不应列入。', '[]', '2026-09-10 09:57:14.016175', '2026-09-10 09:57:14.016175', '山东', '淄博', '高青', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd03ecf790ca4ca5bad795ecec602f75', '李荫春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江黑河；辽宁沈阳；辽宁沈阳于洪；辽宁沈阳康平；辽宁；辽宁辽阳；辽宁铁岭；黑龙江哈尔滨松北；黑龙江哈尔滨呼兰', '[]', '[]', '抗日战争时期', '', '沈阳于洪地区人，任伪于洪区警察署署长，抓捕抗日分子，为日军提供情报。；辽宁康平人，任伪康平县警务科长，抓捕抗日分子，为日军提供情报，参与制造多起屠杀事件。；任伪辽阳警务局长，协助日军搜捕抗日志士，破坏地下抗日组织，残害百姓。；原铁岭县商人，投日后任协和会事务长，组织“青少年团”，灌输军国主义思想，协助日军征兵。', '[]', '2026-09-10 09:57:14.063556', '2026-09-10 09:57:14.063556', '辽宁', '沈阳', '于洪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd07bcced9014fe588f9b3436f202d4e', '阎锡山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '陕西宝鸡；山西吕梁文水；山西大同灵丘；山西吕梁石楼；山西吕梁；山西太原清徐', '[\"注：此处指在灵丘活动的阎系投日人员，非阎本人\", \"注：此条为争议人物，但未公开投日，故不列入\"]', '[]', '抗日战争时期', '', '虽名义抗日，但1940年后与日军达成“默契”，在文水等晋西地区默许伪政权存在，部分部下直接投敌。；组织伪自卫团协助日军守备据点，参与“清乡”行动，抢劫百姓牲畜。', '[]', '2026-09-10 09:57:14.020332', '2026-09-10 09:57:14.020332', '山西', '吕梁', '文水', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd0b85492e8443b3944df7646319d453', '赵登科', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口怀来；辽宁沈阳新民；河北张家口下花园；河北张家口阳原；河北；河北承德平泉；江苏徐州泉山；河北承德滦平；河北_张家口_怀安；河北_张家口_涿鹿；河北张家口', '[]', '[]', '抗日战争时期', '', '负责张家口城区治安，多次组织抓捕地下抗日分子，破坏中共地下组织。；效忠日军，指挥伪警察在下花园地区设卡盘查，破坏地下抗日组织，参与“治安强化运动”。；指挥伪警察抓捕抗日地下党员，破坏抗日组织，参与“清乡”行动。；推行奴化宣传，组织“新民会”胁迫群众参加反共集会，为日军收集抗日情报。；指挥伪警察抓捕抗日地下党员，破坏抗日组织，严刑拷打群众。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.042674', '2026-09-10 09:57:14.042674', '河北', '张家口', '下花园', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd0b85bb3a4249a588aff07428183c69', '高玉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江牡丹江林口；黑龙江伊春嘉荫', '[]', '[]', '抗日战争时期', '', '组织地方汉奸武装，协助日军封锁山区，多次伏击抗联小股部队，并杀害抗联伤病员。；佛山县（今嘉荫县一部分）伪县长，推行日伪政策，协助日军管理边境地区。', '[]', '2026-09-10 09:57:14.065341', '2026-09-10 09:57:14.065341', '黑龙江', '伊春', '嘉荫', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd18858af27b4bed9799f472197ff189', '汪子云', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽铜陵义安', '[]', '[]', '抗日战争时期', '', '在义安乡为日军强征粮食和劳役，强迫村民充当日军向导，并告密导致多名抗日积极分子被捕牺牲。', '[]', '2026-09-10 09:57:14.010569', '2026-09-10 09:57:14.010569', '安徽', '铜陵', '义安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd1ea3197437400baee38aa53bf78a01', '刘某某', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南株洲芦淞；湖南株洲；广西南宁上林；辽宁沈阳大东；湖南永州零陵；黑龙江牡丹江东安；河南洛阳瀍河；河南洛阳；湖南郴州永兴', '[\"刘振南\"]', '[]', '抗日战争时期', '', '永兴县沦陷期间参与伪维持会，负责登记户口、征发物资、传达日军命令；因地方志记载简略，仅存姓氏与职务。；洛阳沦陷后负责伪宣传，散布亲日言论，推行奴化宣传。；在汪伪政权广西宣传机构任职，撰写亲日文章，鼓吹‘大东亚共荣’，影响南宁、上林等地。；日军侵占株洲后，出面组织地方维持会，协助日军维持治安、征发民夫与粮食，具体名字在地方档案中记载不全。；东安沦陷期间附逆，协助日军建立伪政权，征发民夫，镇压抗日活动。', '[]', '2026-09-10 09:57:14.031054', '2026-09-10 09:57:14.031054', '广西', '南宁', '上林', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd1f1ddf02294d809d4e16d49b6eabff', '王庆云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '福建厦门；黑龙江佳木斯；河北', '[]', '[]', '抗日战争时期', '', '主持伪新民会，宣扬‘中日亲善’，奴化教育民众，搜集抗日情报，协助日军建立保甲制度。；充当日军爪牙，负责伪警察机构，搜捕抗日地下人员，破坏抗日组织，勒索百姓。', '[]', '2026-09-10 09:57:14.060686', '2026-09-10 09:57:14.060686', '福建', '厦门', NULL, NULL, NULL, NULL, NULL, '');
