INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd26844381c748bfaad300247d969acd', '于文甲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁；辽宁丹东', '[]', '[]', '抗日战争时期', '', '原安东教育界人士，投日后任伪满安东省教育厅厅长，在丹东、凤城地区推行奴化教育，强制学校教授日语。', '[]', '2026-09-10 09:57:14.062847', '2026-09-10 09:57:14.062847', '辽宁', NULL, NULL, NULL, NULL, NULL, NULL, '');
