INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd6818df138f40dea3a38d52c26447ab', '吕慕陶', NULL, NULL, NULL, NULL, 'exact', 'exact', '邵伯', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪邵伯区区长、伪邵伯镇长，主持邵伯区伪行政，推行保甲、良民证，在运河码头设立检问所，盘查来往船只，为日军征集军粮、木料。。结局：1946 年江苏高等法院判处有期徒刑', '[]', '2026-09-10 09:57:14.082695', '2026-09-10 09:57:14.082695', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd6c71a724804e949de53ffb8143f5fd', '张绍堂', NULL, NULL, NULL, NULL, 'exact', 'exact', '包头；山东德州宁津；黑龙江哈尔滨；黑龙江哈尔滨巴彦；山东德州武城', '[]', '[]', '抗日战争时期', '', '伪职：包头维持会核心头目，漠南公司经理；联合商会士绅出城迎接日军入城，协助接管城市。；结局：战后汉奸罪判刑', '[]', '2026-09-10 09:57:14.013951', '2026-09-10 09:57:14.013951', '山东', '德州', '宁津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd70ee9ffd744032a116587077523e8f', '金寿良', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；山东泰安；辽宁沈阳大东；山东济宁金乡；山东济宁；山东济南；山东济宁', '[]', '[]', '抗日战争时期', '', '金乡人，抗战后期任伪金乡县保安团团长，配合日军对金乡抗日根据地进行扫荡。；济宁商界附逆人物，任伪商会会长，为日军筹集物资，协助经济统制。；掌管山东伪警察系统，驻济南，参与镇压抗日活动。；掌管山东伪警察系统，在济宁等地建立伪警察网络，配合日军扫荡、清乡，抓捕抗日人员。；山东沦陷后投靠日军，出任伪山东省公署省长，统领全省伪政权，在济宁、兖州等地推行伪化政策，协助日军掠夺资源。；在泰安推行奴化教育，篡改教材，宣传“大东亚共荣”。；在济南活动，利用新民会进行亲日宣传、组织民众团体，配合日军殖民统治。', '[]', '2026-09-10 09:57:14.014690', '2026-09-10 09:57:14.014690', '山东', '泰安', '曲阜', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd7b9fffdb4f4294a01deba11af70978', '赵会鹏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林四平', '[]', '[]', '抗日战争时期', '', '在双辽（今属四平）协助日军建立“治安维持会”，参与杀害抗联伤员。', '[]', '2026-09-10 09:57:13.996990', '2026-09-10 09:57:13.996990', '吉林', '四平', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd7f3e84164d483c8a43d311bf60e9c1', '孙柏芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江双鸭山；黑龙江鹤岗；黑龙江双鸭山友谊；黑龙江双鸭山；黑龙江鹤岗工农；黑龙江鹤岗；黑龙江伊春铁力；黑龙江佳木斯', '[]', '[]', '抗日战争时期', '', '伪职：后期伪热河省省长；日本投降后组织承德维持会，妄图维持伪满统治；继续维护日伪旧体系。；结局：承德解放公审，判处死刑', '[]', '2026-09-10 09:57:14.065440', '2026-09-10 09:57:14.065440', '黑龙江', '伊春', '铁力', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd81c317a7bc4f7a91420217d25d2b5e', '杜华梓', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博临淄；山东淄博淄川', '[]', '[]', '抗日战争时期', '', '任伪临淄县知事，协助日军维持临淄地区统治，推行保甲制度。；任伪临淄县知事，配合日军在临淄、淄川交界地区征粮、抓丁。', '[]', '2026-09-10 09:57:14.015856', '2026-09-10 09:57:14.015856', '山东', '淄博', '临淄', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd8225b2211b401ab2fa1261a6cee159', '季步高', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江丽水龙泉', '[]', '[]', '抗日战争时期', '', '日军占领龙泉初期，组织维持会，为日军筹粮派款，提供情报。', '[]', '2026-09-10 09:57:14.049756', '2026-09-10 09:57:14.049756', '浙江', '丽水', '龙泉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd8bb6d175b34a4aa20755cdec362536', '高步瀛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西阳泉城区；山西_朔州_朔州经开区；山西；山西_忻州_静乐；山西朔州山阴；山西阳泉；山西忻州繁峙；河南郑州中牟', '[]', '[]', '抗日战争时期', '', '组织商会为日军筹措军饷和物资，垄断粮食贸易，从中牟利，打压抗日商户。；为日军推行“以战养战”政策，增设苛捐杂税，强征商业税和土地税，导致商户和农民破产，并将所得款项直接供给日军军需。；为日军强征各种苛捐杂税，搜刮民财，导致百姓负担沉重。；为日军推行“以华制华”政策，组织伪自卫团，强征青年充当伪军，并参与日军对狮脑山等根据地的围剿行动。；随日军进行‘宣抚’活动，散布亲日言论，诱骗民众归顺，破坏抗日宣传，并指认抗日家属。', '[]', '2026-09-10 09:57:14.022114', '2026-09-10 09:57:14.022114', '山西', '忻州', '繁峙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dd8cea4201cc4714bc588c88268f194b', '赵振邦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林白城镇赉；吉林白城；黑龙江鹤岗萝北；吉林辽源东辽；黑龙江鸡西鸡冠；黑龙江鸡西；黑龙江绥化望奎；黑龙江佳木斯；黑龙江佳木斯抚远；黑龙江绥化庆安；黑龙江鹤岗兴山；黑龙江鹤岗', '[]', '[]', '抗日战争时期', '', '在伪警务系统任职，多次参与围捕抗联地下交通员，协助日军建立“集团部落”，制造无人区。', '[]', '2026-09-10 09:57:13.999515', '2026-09-10 09:57:13.999515', '吉林', '白城', '镇赉', NULL, NULL, NULL, NULL, '');
