INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddb3f3475c0341aba0c99ed21c662485', '梁振强', NULL, NULL, NULL, NULL, 'exact', 'exact', '四甲坝', '[]', '[]', '抗日战争时期', '', '伪职：伪保甲指导员；罪行：协助朱崇汉推行伪保甲制度，检举地下抗日人员，为日伪搜集情报南通史志网。；结局：同朱崇汉一同被武工队处决。', '[]', '2026-09-10 09:57:14.073517', '2026-09-10 09:57:14.073517', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddbaba7319004c22b2fb06cb38aa1ce4', '马振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄赞皇；山东滨州邹平', '[]', '[]', '抗日战争时期', '', '原为八路军游击队排长，1944年投敌，带领伪军袭击赞皇西沟村，杀害多名村干部。', '[]', '2026-09-10 09:57:14.016515', '2026-09-10 09:57:14.016515', '山东', '滨州', '邹平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddc7895156fd4dcf99f5aa13d855f5b9', '王凤梧', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳；河南安阳龙安；河南安阳；河南濮阳清丰', '[]', '[]', '抗日战争时期', '', '率部驻守安阳近郊据点，配合日军对周边村庄进行清乡、抢粮和抓捕抗日人员。；濮阳本地人，日军占领濮阳后出面组织维持会，后任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。；清丰县本地士绅，日军占领清丰后出面组织维持会，后任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。', '[]', '2026-09-10 09:57:14.047849', '2026-09-10 09:57:14.047849', '河南', '安阳', '龙安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddd41c43e99e4d4a9664760c92fd085e', '王润生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津津南；河北唐山滦南；河北唐山；天津、河北；河北秦皇岛山海关；河北唐山', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军在津南（如咸水沽、葛沽一带）清剿八路军游击队，杀害抗日群众。；指挥伪冀东保安队，在唐山、滦县一带协助日军扫荡，围剿抗日游击队，制造多起惨案。；在唐山、滦州各学校推行奴化教育，删除抗日内容，强迫学生学日语。；原为地方武装头目，投靠殷汝耕后任伪保安队总队长，在唐山、遵化一带配合日军扫荡，围剿抗日游击队。；在山海关任伪警察局长，协助日军抓捕抗日分子，破坏地下组织', '[]', '2026-09-10 09:57:14.003404', '2026-09-10 09:57:14.003404', '天津', '津南', '滦南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddd677e2d4a14b4ea53517ffbaeae43f', '袁道隆', NULL, NULL, NULL, NULL, 'exact', 'exact', '广德县城、誓节渡', '[]', '[]', '抗日战争时期', '', '伪职：广德维持会骨干；罪行：石佐民主要爪牙，办理良民证，搜刮物资，协助管控广德外围据点，迫害抗日家属。；结局：肃奸运动判处死刑。', '[]', '2026-09-10 09:57:14.069913', '2026-09-10 09:57:14.069913', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddd86a95e5464b8bab4cc08f56210c9a', '黄宝忠', NULL, NULL, NULL, NULL, 'exact', 'exact', '遵化', '[]', '[]', '抗日战争时期', '', '伪职：伪遵化县县长，新民会会长；推行治安强化运动，制造遵化多处无人区，强修炮楼封锁沟。；结局：抗战胜利判处无期徒刑', '[]', '2026-09-10 09:57:14.074810', '2026-09-10 09:57:14.074810', '河北', '唐山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dddbce510a75416c97c4ec6f65f6aa77', '曲秉善', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林四平铁东；吉林四平；黑龙江大庆让胡路；黑龙江齐齐哈尔；吉林四平铁西；吉林四平；吉林四平；辽宁沈阳；吉林；辽宁营口；黑龙江佳木斯；辽宁阜新细河；辽宁阜新；吉林白山；吉林', '[]', '[]', '抗日战争时期', '', '伪职：伪四平省末代省长（1943??1945.8）；罪行：疯狂推行粮食 “出荷”，四平省出荷粮占东北很大比重，动用武力搜刮农民粮食；强征劳工，配合治安肃正镇压抗日力量四平市档案...。；结局：苏军逮捕，抚顺战犯管理所关押，后期特赦。；日本关东军指派，实际控制四平省政务，实施经济统制，抓捕抗日分子，强征慰安妇。；原伪满警察，投日后任四平省警务厅厅长，在四平、伊通地区建立情报网，多次破坏抗日地下组织，逮捕爱国人士。', '[]', '2026-09-10 09:57:13.996963', '2026-09-10 09:57:13.996963', '吉林', '四平', '铁东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddddf6167bdd4692b31ecad2140eabe0', '李永翰', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化溆浦；湖南怀化', '[]', '[]', '抗日战争时期', '', '协助李树森组织伪怀化县维持会，为日军提供粮秣、民夫和情报，协助日军控制地方，活动范围包括溆浦。', '[]', '2026-09-10 09:57:14.058648', '2026-09-10 09:57:14.058648', '湖南', '怀化', '溆浦', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dde3ee195f2441728c70d8c3569faaa2', '刀保图', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南芒市（德宏土司）', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：芒市土司，依附日军，出任伪厅厅长，协助日军征粮征壮丁，管控边疆土司武装。结局：滇西光复后被审判，判处徒刑', '[]', '2026-09-10 09:57:14.080664', '2026-09-10 09:57:14.080664', '云南', '德宏', NULL, NULL, NULL, NULL, NULL, '');
