INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ddfd6bac0282432fa6b98fccbab440f4', '顾鸿奎', NULL, NULL, NULL, NULL, 'exact', 'exact', '启东聚阳（利民镇）', '[]', '[]', '抗日战争时期', '', '伪职：伪联防主任、伪保长；罪行：勾结日伪，敲诈勒索乡里，祸害百姓，长期龟缩据点与抗日武装对抗。；结局：被当地民兵锄奸处死。', '[]', '2026-09-10 09:57:14.067288', '2026-09-10 09:57:14.067288', '江苏', '南通', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('de0650d4552e4dd285c0d6203be97abf', '李勉之', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋城', '[]', '[]', '抗日战争时期', '', '投靠日军后任晋城县伪知事，组织伪县公署，为日军提供情报，强征民夫修筑碉堡，镇压抗日群众。', '[]', '2026-09-10 09:57:14.023020', '2026-09-10 09:57:14.023020', '山西', '晋城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('de0c885aad3f41d9ac793370cc177056', '王占牛', NULL, NULL, NULL, NULL, 'exact', 'exact', '峄县', '[]', '[]', '抗日战争时期', '', '伪职：伪军头目；罪行：盘踞临沂卞庄的大汉奸。后逃至峄县与伪县长石振九伙并；结局：1945年9月7日解放峄县时被活捉', '[]', '2026-09-10 09:57:14.074705', '2026-09-10 09:57:14.074705', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('de0deddb67604885957d0e387709e926', '韦云淞', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州岑溪；辽宁沈阳大东；广西河池南丹；广西桂林；广西百色田东；广西百色；广西百色靖西；云南普洱西；广西南宁邕宁；广西桂林恭城；广西南宁青秀；广西桂林；广西玉林容县；广西桂林；广西百色；广西柳州鹿寨；云南普洱西；云南普洱西；广西桂林；广西南宁良庆；广西南宁；广西崇左；广西桂林；山东济宁任城', '[]', '[]', '抗日战争时期', '', '桂林保卫战期间任城防司令，城陷后未坚持抵抗，被日军俘获后变节投敌，参与伪政权组织的活动，为桂林地区重要附逆人员。；协助张君度组织维持会，负责联络日军与地方士绅，征调民力物资，推行奴化宣传。；桂林沦陷期间任维持会副会长，协助会长张君度处理伪务，为日军征集粮食和民夫。；桂系将领，坚持抗战，未附逆。；桂林保卫战失败后被俘，在日方控制下有过妥协性接触，但未正式出任伪职，历史评价存在争议。；日军入侵广西期间，参与伪广西绥靖公署活动，协助日军维持地方治安。；汪伪政权曾委任其为伪广西省保安司令，韦云淞未就任，但日伪曾以其名义进行宣传。；桂系旧军人，日军占领广西期间出任伪职，协助日军在百色周边地区进行清乡。；在日军占领南宁期间，出面组织伪商会，为日军筹款筹粮，协助维持占领区商业秩序，压迫爱国商人。；投日后任伪广西绥靖公署督办，统辖广西伪军，在崇左、龙州地区部署伪军据点，配合日军对抗日根据地进行扫荡。；无可靠史料证明其附逆，不应列为汉奸。；部分地方史料提及其在桂林沦陷期间参与维持会活动，但此说缺乏确证，需谨慎对待。；在日伪控制的广西地区负责文化宣传，鼓吹“大东亚共荣”，为日军侵略辩护，影响梧州等地。；桂系将领，抗战期间在广西活动，但未附逆，不属于汉奸。；桂林失守后，部分守军与地方人员被日军利用组织维持会；韦云淞在部分史料中被提及与沦陷区伪组织有牵连争议。；在日军侵占百色期间，出面组织地方维持会，协助日军维持治安、征调民夫，并参与伪保甲长训练，为日军提供地方情报。', '[]', '2026-09-10 09:57:14.031295', '2026-09-10 09:57:14.031295', '广西', '南宁', '良庆', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('de1aa421a41746c1936e2942b1778223', '王舜卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '安陆县', '[]', '[]', '抗日战争时期', '', '伪职：伪安陆县县长；罪行：安陆伪县长，对抗日态度恶劣。巡店伪区长帅干伯被杀后急得如热锅上的蚂蚁', '[]', '2026-09-10 09:57:14.073750', '2026-09-10 09:57:14.073750', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
