INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('de8b0f2beb24452abf7bbc4913622295', '韩广森', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北张家口崇礼；河北张家口尚义；河北张家口蔚县；张家口；内蒙古、河北；河北张家口桥西；河北张家口；河北张家口沽源；重庆沙坪坝；河北张家口', '[]', '[]', '抗日战争时期', '', '伪职：张家口商会会长，伪张家口市市长；迎接日军入城，横征暴敛，抓捕爱国人士，强征劳工资敌中共张家口...。；结局：1945??10??08 公审枪决；率伪蒙古军第6师驻防兴和、尚义一带，多次袭击八路军游击队，杀害抗日干部和群众。；负责伪察哈尔省（含张家口）警察系统，搜捕抗日人士，配合日军进行“治安肃正”行动。；在崇礼县任伪职期间，推行日伪“治安强化”运动，组织汉奸武装“自卫团”，配合日军扫荡抗日根据地，残害百姓。；在张家口桥西地区指挥伪保安队，多次配合日军扫荡抗日根据地，抓捕抗日军民，参与制造多起屠杀事件。；任伪沽源县知事期间，强征民夫修筑公路和炮楼，为日军提供情报，抓捕抗日人员。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.986760', '2026-09-10 09:57:13.986760', '河北', '张家口', '崇礼', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dea28754cd11437ab1d6f6ecfaadb0c7', '陈伯昂', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波海曙；黑龙江佳木斯郊区；浙江宁波北仑；浙江宁波；浙江_宁波_江北；浙江宁波；安徽安庆', '[]', '[]', '抗日战争时期', '', '率领伪保安队参与“扫荡”，在宁波郊区和海曙周边村庄烧杀抢掠，强征壮丁。；在安庆强征各种杂税，敲诈勒索商户，中饱私囊。；效忠日伪，指挥伪警镇压抗日活动，逮捕爱国人士，并勒索商民，为日军提供情报。；日军占领宁波初期，组织维持会，为日军提供物资和劳役，协助建立伪政权。；效忠日军，指挥伪警察搜捕抗日地下人员，破坏中共宁波地下组织，罪行累累。', '[]', '2026-09-10 09:57:14.006477', '2026-09-10 09:57:14.006477', '安徽', '安庆', '北仑', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dea67ab32bff45478e5248540614d8d9', '黄岩', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江台州玉环；浙江台州椒江', '[\"人名\", \"黄正\"]', '[]', '抗日战争时期', '', '任伪黄岩县知事，配合日军在黄岩、椒江一带清乡，杀害抗日地下党员，强征壮丁。；为日军在玉环沿海设立情报点，破坏抗日武装的物资运输，参与诱降抗日游击队成员。', '[]', '2026-09-10 09:57:14.050008', '2026-09-10 09:57:14.050008', '浙江', '台州', '椒江', NULL, NULL, NULL, NULL, '');
