INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('deda331d4a5a406a88cde9f4708300ae', '张敬忠', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；河南焦作温县；河南许昌；河南焦作焦作示范；山西阳泉矿区；河南焦作山阳；河南焦作', '[]', '[]', '抗日战争时期', '', '在焦作矿区组建伪警备武装，配合日军守备煤矿、镇压抗日群众和矿工反抗。；任伪河南省警务厅厅长，统管全省伪警察系统，在许昌、襄城等地建立伪警察网络，镇压抗日民众。；率伪警备队配合日军扫荡温县及周边抗日根据地，捕杀抗日人员，勒索民众。；率部投敌，在焦作、博爱一带配合日军进攻抗日武装，烧杀抢掠。；在新乡沦陷期间任伪警察局长，负责城区治安与情报，配合日军搜捕抗日人员，维持伪政权统治。', '[]', '2026-09-10 09:57:14.048421', '2026-09-10 09:57:14.048421', '河南', '焦作', '山阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dedc81a133e6412cb9820b2774a64ad0', '周干臣', NULL, NULL, NULL, NULL, 'exact', 'exact', '天长县城；扬州', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：天长伪警察局局长；罪行：执掌伪警侦缉队，管控天长县城及高邮湖沿岸，搜捕地下交通人员，盘查水陆商旅。；结局：肃奸公审枪决。；伪任职务：伪宪兵队翻译、情报组长，专门诱捕爱国学生、地下人员，充当日军耳目。。结局：光复后公审枪决', '[]', '2026-09-10 09:57:14.071021', '2026-09-10 09:57:14.071021', '江苏', '扬州', NULL, NULL, NULL, NULL, NULL, '');
