INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dee05df877fb4e0cb8b2608913fae858', '赵宗鼎', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏徐州铜山', '[]', '[]', '抗日战争时期', '', '任伪铜山县警察局长，负责镇压抗日活动，抓捕地下党员和进步群众，实施“连坐”制度，协助日军进行特务活动。', '[]', '2026-09-10 09:57:14.035320', '2026-09-10 09:57:14.035320', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
