INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('deeebc6dc1a840849b5d7c657a8db193', '张允荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '陕西西安长安；天津东丽；天津_静海；河北廊坊固安；天津河北；天津北辰；湖南常德津；河北承德；天津、河北；河北廊坊广阳；天津河北；河北唐山玉田；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '', '在天津及东丽地区建立特务网络，抓捕抗日志士，协助日军宪兵队进行残酷镇压。；在天津为伪冀东政权服务，协助日军控制天津地区，破坏抗日活动。；为伪政权征收苛捐杂税，搜刮民财，资助日军战争。；控制社会团体，强制推行“治安维持会”制度，迫害进步工人和市民。；参与冀东伪政权决策，在玉田等地推行“保甲连坐”制度。', '[]', '2026-09-10 09:57:14.002540', '2026-09-10 09:57:14.002540', '天津', '北辰', '玉田', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('def1b897e8484d85ae494e19ecc8cdbc', '王墨庄', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封祥符；河南开封；河南漯河临颍；河南开封；河南开封鼓楼；商丘', '[]', '[]', '抗日战争时期', '', '伪职：伪豫东道道尹；罪行：1939年6月1日，日伪在商丘成立伪豫东道公署，王墨庄任道尹，统辖豫东十余县伪政权', '[]', '2026-09-10 09:57:14.048021', '2026-09-10 09:57:14.048021', '河南', '开封', '祥符', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('defdd27ef2894e34a75e29936eafd96d', '陈锡纯', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南通南通经开区；江苏淮安洪泽；江苏徐州新沂；江苏徐州睢宁；江苏徐州；江苏淮安淮阴', '[]', '[]', '抗日战争时期', '', '为日伪征收苛捐杂税，侵吞抗日物资，支持伪政权运作。；盘踞洪泽湖，率伪水警队为日军运输物资，封锁湖面交通，袭击新四军水上交通线，劫掠渔民财物，杀害抗日干部。；其辖区与新沂南部接壤，多次配合日军对新沂地区进行“讨伐”，提供情报和后勤支持。；任伪淮阴县警察局长，协助日军搜捕抗日地下党员，破坏交通线，参与“清乡”行动。；在睢宁、邳县一带发展特务网络，破坏中共地下组织，逮捕并杀害多名抗日志士。；在徐州及邳州地区建立伪警察体系，搜捕抗日分子，执行日军“保甲连坐”制度。', '[]', '2026-09-10 09:57:14.034084', '2026-09-10 09:57:14.034084', '江苏', '南通', '南通经开区', NULL, NULL, NULL, NULL, '');
