INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df16cd50f266428ab702ebbb471f0d7e', '龙云', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明石林；云南昆明；云南昭通；云南昆明晋宁；云南保山；云南昆明安宁；云南昭通；云南普洱西；云南昆明呈贡', '[\"附逆传闻相关者\"]', '[]', '抗日战争时期', '', '作为云南省主席，龙云始终未附逆，但日方曾多次试图拉拢；此条仅作排除性说明，非汉奸。；龙云主政云南期间坚持抗日，未任伪职；此条仅因部分民间传闻涉及昆明地区附逆线索而列，但无可靠史料证明其为汉奸。；云南省政府主席，抗战期间坚持抗日立场，未附逆。此条为排除性说明，非汉奸。；龙云系云南昭通人，主政云南期间积极抗日，组织滇军出滇抗战，修筑滇缅公路，并非汉奸。不应列入。；云南省政府主席，抗战时期组织滇军出滇抗战，支持抗战，无汉奸记载。；主政云南期间坚持抗日，组织滇军出滇抗战，支持滇缅公路修建，未附逆。；云南昭通人，主政云南期间坚持抗日，派滇军出滇抗战，未附逆。此条为排除性说明，非汉奸。；主政云南期间坚持抗战，未附逆；但其所部部分地方势力在滇西沦陷区与日伪有暧昧接触。', '[]', '2026-09-10 09:57:13.979798', '2026-09-10 09:57:13.979798', '云南', '保山', '呈贡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df21b3b8e96b4d0ca66c7330fc4c77bd', '朱幼樵', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽淮南寿县；安徽芜湖', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强制学校使用日伪教材，宣传“中日亲善”，迫害爱国教师，破坏抗日宣传活动。；为日军和伪政权筹措经费，强迫商户捐款，垄断物资，中饱私囊。', '[]', '2026-09-10 09:57:14.008979', '2026-09-10 09:57:14.008979', '安徽', '淮南', '寿县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df2de4dcdf92463aae443a8489906f5e', '奇玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古鄂尔多斯乌审旗；内蒙古鄂尔多斯准格尔旗；内蒙古鄂尔多斯鄂托克旗；内蒙古巴彦淖尔乌拉特后旗', '[]', '[]', '抗日战争时期', '', '在乌拉特后旗为日军效力，协助维持伪政权，镇压当地抗日牧民，征收苛捐杂税。；依附日军，在鄂托克旗设立伪警察所，禁止牧民与抗日武装接触，并参与日军“清边”行动。；投靠日军及伪蒙疆政权，任乌审旗保安团团长，协助日军镇压抗日力量，参与“伊盟事变”中镇压蒙古族人民的反抗，迫害进步人士，强征民夫为日军服务。', '[]', '2026-09-10 09:57:13.990254', '2026-09-10 09:57:13.990254', '内蒙古', '巴彦淖尔', '乌拉特后旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df2f55f1d0764a118b9b4971348fb836', '刘友惠', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉青山；湖北武汉', '[]', '[]', '抗日战争时期', '', '抗战期间在武汉伪政权中任伪检察署检察长，配合日军迫害抗日人士。', '[]', '2026-09-10 09:57:14.056713', '2026-09-10 09:57:14.056713', '湖北', '武汉', '青山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df32895bb44c4e14980fd12462de7b39', '贾景德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西太原示范；云南普洱西；山西太原阳曲；辽宁沈阳大东；江苏无锡锡山；山西晋中；山西太原娄烦；山西；山西太原；云南普洱西；山西_长治_长治高；山西临汾；山西临汾襄汾；山西临汾；山西临汾曲沃；山西晋城；山西_太原_清徐；山西晋城阳城；山西长治；山西太原；山西太原晋源', '[\"附逆争议\"]', '[]', '抗日战争时期', '', '在北平参与伪华北政权活动，为日军在山西的统治提供政策建议。；负责为日军搜刮临汾地区粮食和物资，强征苛捐杂税。；推行保甲制度，强征壮丁，为日军修建据点，镇压反抗。；原为地方士绅，投日后充当日军特务，在临汾、襄汾交界处建立情报网，多次引导日军突袭抗日游击队驻地。；虽名义为顾问，但实际参与伪省府对临汾、襄汾地区的“宣抚”工作，协助日军分化抗日力量，劝降地方武装。；作为山西籍汉奸代表，在北平伪政权中为日军服务，参与协调山西日伪事务。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019024', '2026-09-10 09:57:14.019024', '山西', '临汾', '曲沃', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df36186822814236ac5cac7655413fc6', '伪峡江县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西吉安峡江', '[]', '[]', '抗日战争时期', '', '峡江沦陷后伪维持会协助日军征粮、带路，参与清乡。', '[]', '2026-09-10 09:57:14.038616', '2026-09-10 09:57:14.038616', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
