INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df67fea1fb3d4bf0b987c4f3d692ad2a', '黄仲苏', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江温州洞头；浙江温州；浙江温州乐清；浙江温州；浙江_温州_鹿城；浙江温州', '[]', '[]', '抗日战争时期', '', '以文化人身份投敌，任伪绥靖公署顾问，为日军出谋划策，参与诱降活动。；参与策划对温州沿海的封锁，协助日军掠夺钨砂等战略物资。；推行奴化教育，强制学校教授日语，删改历史教材，宣扬“中日亲善”。；充当汉奸商人，为日军统购物资，控制温州港贸易，从中牟利，资助伪政权。；充当汉奸商人，为日军控制温州经济，垄断粮食和食盐贸易，向日军提供军费，并强迫商户捐款。', '[]', '2026-09-10 09:57:14.051352', '2026-09-10 09:57:14.051352', '浙江', '温州', '乐清', NULL, NULL, NULL, NULL, '');
