INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('df999ba992a04ad5b0b54ae6133bd1fa', '邵竞生', NULL, NULL, NULL, NULL, 'exact', 'exact', '萧县全境；萧县黄口、萧城，波及今淮北杜集抖音百科', '[]', '[]', '抗日战争时期', '', '伪职：伪萧县县长；罪行：邵世恩之子，人称 “二县长”；辅佐其父把持黄口伪政权，后出任汪伪萧县县长，推行保甲、强化治安，配合日军扫荡萧铜根据地。；结局：1952 年镇反处决抖音百科。；伪职：汪伪萧县县长；罪行：邵世恩之子，人称 “二县长”；主持萧县伪县公署，强化保甲良民证，配合日军扫荡萧铜抗日根据地；后调任伪灌云县长、徐州筹备主任抖音百科。；结局：1952 年镇反处决。', '[]', '2026-09-10 09:57:14.069621', '2026-09-10 09:57:14.069621', '安徽', '宿州', NULL, NULL, NULL, NULL, NULL, '');
