INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dfed745b1ead4460892b8a66c05430b0', '郭永清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治黎城；山西忻州神池；山西；山西长治平顺；山西吕梁方山；山西运城垣曲；甘肃甘南合作', '[]', '[]', '抗日战争时期', '', '推行日伪奴化教育，强迫学校使用伪满教材，禁止讲授中国历史，迫害爱国教师。；为日军充当翻译，参与审讯抗日志士，歪曲口供，助纣为虐，并勒索百姓钱财。；垄断食盐、布匹等物资配给，克扣百姓配额，高价转卖，并利用合作社为日军收集战略物资。；带领伪警察搜捕抗日分子，严刑拷打被捕人员，并参与日军“清乡”行动，杀害多名抗日群众。；参与多次“扫荡”，在黎城北部烧毁村庄，抢劫民财。', '[]', '2026-09-10 09:57:14.020415', '2026-09-10 09:57:14.020415', '山西', '吕梁', '方山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dff19842747b4da3828a49b722c59d9a', '孙广庭', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林经开区；吉林；黑龙江绥化望奎；黑龙江绥化；黑龙江绥化绥棱；黑龙江绥化；黑龙江佳木斯向阳；黑龙江佳木斯；辽宁营口老边；辽宁营口', '[]', '[]', '抗日战争时期', '', '历任伪海伦县长、绥化地区协和会会长，积极推行\'王道乐土\'宣传，协助日伪征调劳工、粮食，支持殖民统治。；推行奴化教育，协助日伪控制吉林地区学校。；伪满时期在佳木斯及桦川一带任职，曾任伪桦川县公署参事官、伪佳木斯街长，协助日军推行街村制、保甲制，管理地方行政并配合经济掠夺。；在绥化教育界推行奴化教育，编写亲日教材，组织学生参拜神社，为日军培养顺民，是文化教育领域附逆者。；在营口县任伪县长期间，推行日军殖民政策，征粮征工，镇压抗日活动，对老边一带亦有管辖影响。', '[]', '2026-09-10 09:57:14.000419', '2026-09-10 09:57:14.000419', '吉林', '经开区', '老边', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('dff523fb7e5d4ef59f31ee26198a110c', '丛镜月', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海荣成；山东威海；山东威海乳山；山东威海文登；山东威海威海临港经开区；山东威海；山东威海荣成；山东威海文登；山东威海威海火炬高；山东威海', '[]', '[]', '抗日战争时期', '', '在文登、威海一带组织伪维持会，配合日军统治，为日军提供情报和物资支持。；任伪文登县长期间，配合日军对威海临港经开区一带进行扫荡，推行保甲连坐。；在文登及威海周边地区组织伪维持会，协助日军征粮、征丁、建立伪保甲，参与对胶东抗日根据地的封锁和扫荡。；投敌后任伪文登县保安大队长，率伪军配合日军扫荡文登抗日根据地，捕杀抗日干部和群众。；在荣成组织维持会，为日军登陆和驻防提供便利，协助征发渔船、劳工。；文登伪军头目，率伪军配合日军扫荡文登、乳山地区抗日根据地，残害抗日军民。', '[]', '2026-09-10 09:57:14.013039', '2026-09-10 09:57:14.013039', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
