INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e049321f00ea46f3b9ae6b4ed675e6e7', '周文奎', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_丽水_景宁；浙江_台州_三门；江苏淮安金湖；浙江温州龙湾；辽宁沈阳和平', '[]', '[]', '抗日战争时期', '', '任伪商会会长，为日军统购物资，强制摊派“和平捐款”，从中牟利，压迫商户。；协助日军维持治安，搜捕抗日地下党员，严刑逼供并移交日军处决。；设立关卡盘查行人，搜捕抗日分子，严刑逼供，致死致残多人。；为日军搜捕抗日地下人员，严刑逼供，破坏地下交通站。', '[]', '2026-09-10 09:57:14.036350', '2026-09-10 09:57:14.036350', '江苏', '淮安', '金湖', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e04aa9e9e5df4286828ace9df467aa78', '关俊甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '长葛县', '[]', '[]', '抗日战争时期', '', '伪职：长葛县维持会会长（另一说）；罪行：史料记载长葛县维持会长为袁正卿、关俊甫，可能与袁正卿先后或同时任职', '[]', '2026-09-10 09:57:14.077008', '2026-09-10 09:57:14.077008', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e05845f179c44b7a9fda1d9a50a30154', '周志俊', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江绍兴越城；浙江台州天台；浙江温州永嘉；浙江温州；浙江湖州吴兴；浙江衢州；浙江温州鹿城；浙江绍兴诸暨', '[]', '[]', '抗日战争时期', '', '依附日军，征收苛捐杂税，迫害抗日家属，提供情报给日军。；组织商会为日军筹款、供应粮食和棉布，并强迫商户悬挂日伪旗帜。；组织伪保安团配合日军扫荡，在鹿城及周边乡村烧杀抢掠，抓捕壮丁补充伪军。；直属日军宪兵队，发展密探网，破坏中共地下组织，逮捕并杀害多名抗日群众，罪行累累。；参与组织伪维持会，为日军带路扫荡，强征劳工修筑工事，并出卖抗日志士情报。；在诸暨为日军征购粮食和布匹，协助伪政权经济掠夺。；任伪商会会长，为日军统制物资，强迫商户缴纳“慰劳金”，资助伪军。；率伪保安队配合日军进攻瓯江沿岸抗日据点，杀害多名抗日群众。', '[]', '2026-09-10 09:57:14.049938', '2026-09-10 09:57:14.049938', '浙江', '台州', '天台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e05992821472469188e36b79ad26e8d0', '王安民', NULL, NULL, NULL, NULL, 'exact', 'exact', '东安县芦洪市', '[]', '[]', '抗日战争时期', '', '伪职：日伪东安芦洪市维持会会长；罪行：1944年12月底，日军侵占东安县芦洪市镇后宣布成立维持会，任命王安民为会长，为日军维持殖民统治、征收粮款；结局：1944年12月9日，被王仡“湘南民众联乡自卫纵队”派便衣潜入芦洪市击毙', '[]', '2026-09-10 09:57:14.078947', '2026-09-10 09:57:14.078947', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e06048329eec4754a2236fa7d59bed3a', '李名山', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵州六盘水六枝特', '[]', '[]', '抗日战争时期', '', '在六枝特区担任伪保甲长，协助日军征粮、派夫，监控当地抗日分子，参与伪政权基层统治。', '[]', '2026-09-10 09:57:14.062533', '2026-09-10 09:57:14.062533', '贵州', '六盘水', '六枝特', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e062555b130547ecba627fbab6a03ffc', '孙振东', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台芝罘；山东烟台；河北衡水武邑；辽宁沈阳新民；山东烟台莱阳；山东烟台；山东聊城冠县；山东聊城；山东烟台；山东烟台蓬莱；山东烟台招远；山东烟台；山东烟台牟平；山东德州；山东烟台莱山；山东烟台福山；山东烟台烟台经开区；山东烟台；山东烟台海阳；山东烟台；山东烟台；山东烟台福山；山东烟台；河南开封杞县；山东德州乐陵；山东德州；山东烟台龙口；山东烟台', '[]', '[]', '抗日战争时期', '', '在烟台福山地区出任伪县长，配合日军扫荡抗日根据地，征发劳工。；在烟台地区依附日军，参与伪维持会和商会活动，为日军经济掠夺和统治服务。；在鲁北德州、乐陵一带收编地方武装组成伪保安队，配合日军清乡、扫荡，袭击抗日根据地。；黄县（今烟台龙口）沦陷后出任伪职，组织维持会，协助日军征粮、抓丁，破坏当地抗日组织。；带领伪保安队在聊城周边清乡，抓捕抗日干部，破坏抗日交通线。；在烟台掖县地区出任伪县长，协助日军统治，迫害抗日民众。；在海阳任伪县长，属烟台地区，配合日军进攻抗日根据地，征发物资。；蓬莱沦陷后任伪维持会会长、伪县长，协助日军推行伪化统治，征发劳工，镇压抗日活动。；率领伪保安队配合日军扫荡牟平抗日根据地，抓捕抗日群众。；利用新民会进行奴化宣传，诱降抗日人员，为日军搜集情报。；日伪在胶东设立的道级伪政权头目，管辖烟台、招远等地，推行日伪政策，镇压抗日活动。；在德州任伪警察局长，组织伪警察镇压抗日群众，搜查抗日组织，维持日伪治安。；在烟台地区担任伪警察局长，协助日军统治，镇压抗日活动。；抗战时期在烟台任伪商会会长，为日军筹集军需物资，协助日伪经济统制，涉及烟台、福山地区。；兰封沦陷后组织维持会，为日军提供情报、粮草，协助建立伪政权。；福山（今烟台福山区）伪县长，配合日军统治，在福山、莱山一带推行伪化教育，征粮征兵。', '[]', '2026-09-10 09:57:14.013735', '2026-09-10 09:57:14.013735', '山东', '德州', '乐陵', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e076aaf3220445498d180d351fda401d', '史鹤亭', NULL, NULL, NULL, NULL, 'exact', 'exact', '滕县', '[]', '[]', '抗日战争时期', '', '伪职：伪保二师稽查队长；罪行：滕县恶贯满盈的汉奸恶霸。在敌寇卵翼下任意残害人民，杀害青年17人，强占民女32人。用搜刮得来的民财买地百余顷，建宅四处，民愤极大；结局：1946年3月22日滕县解放后被公审，由滕县公安局宣读罪状后立即执行枪决', '[]', '2026-09-10 09:57:14.080525', '2026-09-10 09:57:14.080525', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e078b64b89464495a22285b7a3e2589e', '陈明斋', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北潜江；湖北_荆州_松滋；湖北宜昌夷陵；湖北宜昌；湖北咸宁赤壁；湖北襄阳；江西鹰潭余江；江西上饶；江西上饶信州；河南许昌；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '在许昌城区推行保甲制度，协助日军清查户口、抓捕抗日嫌疑人员。；蒲圻（今赤壁）伪警察头目，配合日军进行户口清查、搜捕抗日人员。；协助会长筹措物资供应日军，动员商户缴纳所谓“治安费”。；玉山沦陷后组织伪维持会，为日军提供情报、粮草，协助日军控制玉山至信州一线交通。；上饶沦陷期间任维持会副会长，主持征粮派款，为日军提供情报，协助建立伪基层政权。；控制宜昌沦陷区商业，为日军采购军需物资，强制摊派商户捐款，配合经济封锁与物资统制。；在襄阳推行奴化教育，监督学校使用亲日教材。；掌控伪警察力量，协助日军稽查抗日分子，迫害无辜民众，维持日伪统治秩序。', '[]', '2026-09-10 09:57:14.037726', '2026-09-10 09:57:14.037726', '江西', '上饶', '信州', NULL, NULL, NULL, NULL, '');
