INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e0bb2e049c9e4fb0866af99fdbc94f6c', '王铁相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山路南；河北唐山；河北唐山丰润；河北唐山玉田；河北唐山曹妃甸；河北唐山；河北沧州泊头；河北沧州；山西晋中左权；河北沧州沧州渤海；河北沧州；河北沧州沧县；河北唐山唐山海港经开区；山西、河北；山东菏泽菏泽经开区；山东菏泽；山东威海乳山；山东威海；河北_保定_蠡县；天津河北；河北廊坊；山东淄博博山；河北唐山滦南；山东青岛市南；河北唐山；河北唐山滦州；河北秦皇岛昌黎；山东济宁；山东潍坊诸城；河北唐山丰南；河北唐山；河北唐山迁西；河北唐山', '[]', '[]', '抗日战争时期', '', '在晋中地区强抓壮丁，扩充伪军，参与对左权县抗日根据地的进攻。；负责伪警察系统，搜捕抗日地下党员，破坏交通联络站，多次带队突袭村庄。；在丰润县推行日伪统治，强征民夫修筑碉堡，镇压抗日活动。；作为伪冀东道最高行政长官，管理唐山及周边县市，推行保甲制度，强征捐税，配合日军“扫荡”。；驻防唐山周边，参与围剿抗日游击队，残害百姓，掠夺财物。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.013282', '2026-09-10 09:57:14.013282', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e0c0a3f9d7f14d0eb0c0ba7f05989c03', '于景涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑山；岫岩', '[]', '[]', '抗日战争时期', '', '伪职：伪岫岩县县长；罪行：管控岫岩伪政权，配合日伪对辽南三角抗区反复扫荡。；结局：解放后以汉奸罪判刑。；伪职：伪黑山警务科长；罪行：指挥伪警察、特务，抓捕义勇军家属与地下关系，制造多起冤狱。；结局：镇反时期公审处决。；伪职：伪彰武县县长；罪行：彰武伪主官，管控彰武全境，配合日伪讨伐辽西义勇军，强征物资。；结局：解放后逮捕判刑。', '[]', '2026-09-10 09:57:14.080368', '2026-09-10 09:57:14.080368', '辽宁', '锦州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e0c7b87a62294791ab16a957ae4ffb91', '莫国璋', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西贺州钟山；贵州六盘水钟山', '[]', '[]', '抗日战争时期', '', '日军占领钟山后，出任伪警察所所长，搜捕抗日人员，镇压民众反抗。', '[]', '2026-09-10 09:57:14.033063', '2026-09-10 09:57:14.033063', '广西', '贺州', '钟山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e0cb245813044587ad96a80345a7fc16', '吴宝书', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶铅山；江西上饶；江西宜春靖安；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在宜春推行奴化教育，改编教材，强制学校教授日语和‘大东亚共荣’内容，并组织教师参加伪政权培训。；在日军占领上饶期间推行奴化教育，篡改教材，强迫学校师生参加亲日宣传。', '[]', '2026-09-10 09:57:14.038127', '2026-09-10 09:57:14.038127', '江西', '上饶', '铅山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e0cf58216f5848dc837792f2144e264c', '张静舟', NULL, NULL, NULL, NULL, 'exact', 'exact', '鄂城县（今鄂州）', '[]', '[]', '抗日战争时期', '', '伪职：伪鄂城一区区长；罪行：鄂城县城关至黄石一带伪一区区长', '[]', '2026-09-10 09:57:14.067486', '2026-09-10 09:57:14.067486', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
