INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e118dce1e0ff49bdadd891188d38c170', '罗筱元', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳耒阳；湖南衡阳；湖南衡阳', '[]', '[]', '抗日战争时期', '', '衡阳陷落后参与伪政权经济事务，协助日军摊派物资、控制市场，属经济领域附逆者。；衡阳沦陷期间任伪警察局局长，协助日军镇压抗日活动、搜捕抗日人员，直接活动于衡阳地区。', '[]', '2026-09-10 09:57:14.059427', '2026-09-10 09:57:14.059427', '湖南', '衡阳', '耒阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e11bb65ed13d41a297dfc7832cb681b6', '张子丰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治沁源', '[]', '[]', '抗日战争时期', '', '率警备队多次袭击抗日武装，破坏地下党组织，残害抗日家属。', '[]', '2026-09-10 09:57:14.024188', '2026-09-10 09:57:14.024188', '山西', '长治', '沁源', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e11e80dd236f43e5b8c37c2f12e22f35', '金朝文', NULL, NULL, NULL, NULL, 'exact', 'exact', '包头回族', '[]', '[]', '抗日战争时期', '', '伪职：第二任伪包头市长（1939??1945）；强制推行鸦片种植，烟税供给日军；配合宪兵大搜捕，搜刮皮毛、粮食、煤炭输送伪蒙疆总部。；结局：日降后潜逃，被国民政府通缉，抓获判处重刑', '[]', '2026-09-10 09:57:14.080679', '2026-09-10 09:57:14.080679', '内蒙古', '包头', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e133413935dc49be82fa6987c0d51e23', '郭少雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东潮州潮安', '[]', '[]', '抗日战争时期', '', '在浮洋一带为日军收集情报，强征民夫修筑工事，迫害抗日家属。', '[]', '2026-09-10 09:57:14.029875', '2026-09-10 09:57:14.029875', '广东', '潮州', '潮安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e13cb73c1fa44628acad12aed7eaac1d', '沈谱琴', NULL, NULL, NULL, NULL, 'exact', 'exact', '吴兴湖州城；浙江湖州德清；浙江湖州', '[]', '[]', '抗日战争时期', '', '伪职：湖州自治委员会（维持会）挂名会长；罪行：地方士绅，日军胁迫出任维持会会长，出面帮日军维持市面，后避走上海。；结局：1939 年病逝上海，受历史负面评价。', '[]', '2026-09-10 09:57:14.051660', '2026-09-10 09:57:14.051660', '浙江', '湖州', '德清', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e13f9bcd221b46efac0688de7bae9cd8', '张海涛', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北潜江；湖北黄石；湖北黄石黄石港；江苏_宿迁_宿豫；黑龙江黑河北安；河南南阳南阳示范；河南南阳；江西抚州；湖北咸宁通山；湖北咸宁；湖北咸宁赤壁；湖北鄂州鄂城；湖北宜昌；湖北宜昌夷陵；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '统率伪军配合日军在抚州、金溪、东乡一带清乡，袭击抗日游击队，捕杀抗日群众。；1945年日军侵占南阳期间，担任日军翻译，协助日军与当地伪政权沟通，参与审讯抗日人员。；协助推行“配给制”，克扣民众口粮。；鄂城沦陷后投敌，任伪维持会会长、伪县长，协助日军控制鄂城，征粮征夫，破坏抗日根据地。；率伪军在天门、潜江交界地带配合日军扫荡，袭击抗日武装。；掌管伪警察队伍，搜捕抗日人员，勒索百姓，协助日军维持占领区秩序。；监利沦陷后任伪维持会会长，配合日军控制长江航道。；负责黄石港地区治安，协助日军搜捕抗日分子，勒索居民，推行良民证制度。；在宜昌沦陷区推行奴化教育，主持伪学校改用日伪教材，宣传“大东亚共荣”，毒化青年思想。；任伪蒲圻县保安大队大队长，在咸宁地区协助日军维持治安、征发劳役。', '[]', '2026-09-10 09:57:14.034528', '2026-09-10 09:57:14.034528', '河南', '南阳', '南阳示范', NULL, NULL, NULL, NULL, '');
