INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e2411ff43b1144768f7830152029c973', '雄诺敦都布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；内蒙古乌兰察布四子王旗；河北张家口张北；内蒙古乌海；内蒙古锡林郭勒东乌珠穆沁旗；内蒙古锡林郭勒乌拉盖；内蒙古锡林郭勒太仆寺旗；内蒙古锡林郭勒阿巴嘎旗；内蒙古呼和浩特和林格尔；内蒙古_呼和浩特；内蒙古包头；内蒙古；内蒙古巴彦淖尔乌拉特中旗；内蒙古乌兰察布；内蒙古巴彦淖尔乌拉特前旗；内蒙古锡林郭勒苏尼特左旗；内蒙古鄂尔多斯；内蒙古锡林郭勒二连浩特；内蒙古锡林郭勒正镶白旗；内蒙古锡林郭勒正蓝旗；内蒙古_锡林郭勒_锡林浩特', '[\"雄王\", \"雄努敦都布\"]', '[]', '抗日战争时期', '汪伪政权', '伪蒙古军将领，在乌兰察布、兴和地区参与“扫荡”，强征民夫修筑公路和碉堡，配合日军推行“保甲制”。；率部在化德、张北一带协助日军维持治安，镇压抗日民众。；投靠日伪政权，在旗内推行奴化教育，强迫牧民献粮献畜，协助日军维持殖民统治。；在包头、萨拉齐一带活动，协助日军建立伪保甲制度，强征民夫修筑工事，镇压民众反抗。；德王亲信，率伪蒙古军驻守绥东地区，参与多次扫荡行动。……（共涉及10个地区的犯罪记录）；在乌拉特中旗及乌拉特后旗一带活动，为日军提供情报，围剿抗日武装，推行“保甲制度”。；伪任职务：伪蒙古军警卫师师长，伪蒙疆保安负责人。结局：1959 年特赦释放', '[]', '2026-09-10 09:57:13.986242', '2026-09-10 09:57:13.986242', '内蒙古', '乌兰察布', '四子王旗', NULL, NULL, NULL, NULL, '');
