INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e25bc734f2614b7c94f11cb9d01013f9', '王振邦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古赤峰巴林左旗；内蒙古赤峰翁牛特旗；黑龙江黑河北安；天津河北；山西吕梁交城；山西、河北', '[]', '[]', '抗日战争时期', '', '率伪保安队多次配合日军扫荡交城山区抗日根据地，杀害抗日干部和群众，烧毁村庄。；在日占唐山期间任伪市长，推行奴化教育，组织劳工输出，为日军提供物资。；1938年伪冀东政府改为伪河北省后，任伪唐山市长，推行日伪经济统制，强征粮食煤炭，为日军提供战争物资。', '[]', '2026-09-10 09:57:13.991172', '2026-09-10 09:57:13.991172', '内蒙古', '赤峰', '巴林左旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e25d2d48f6224d508608b7d2ddfbffe9', '吴子昂', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽安庆', '[]', '[]', '抗日战争时期', '', '在长江安庆段设卡盘查，拦截抗日物资，勒索船民。', '[]', '2026-09-10 09:57:14.006442', '2026-09-10 09:57:14.006442', '安徽', '安庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e26e0e5d173b4f1cb2a651f314196bda', '王丹侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北鄂州梁子湖；湖北鄂州鄂城；湖北黄冈罗田；湖北黄冈；湖北鄂州；湖北黄冈团风；湖北黄冈', '[]', '[]', '抗日战争时期', '', '抗战期间任伪罗田县县长，在罗田地区推行伪政，协助日军统治。；在黄冈沦陷区推行奴化教育，编写伪教材，强制学校教授日语和亲日内容，毒害青少年。；黄冈地区伪警察头目，负责侦缉抗日人员、维持伪治安，协助日军镇压当地民众。；掌管伪鄂城警察机构，协助日军搜捕抗日人员、控制交通与户籍，为鄂州地区伪政权重要爪牙。；统率伪保安大队配合日军对鄂城周边抗日根据地扫荡，参与清乡与保甲连坐。；主持伪县政，推行日军殖民统治政策，在鄂城及梁子湖地区征粮、征兵、修筑据点，镇压抗日活动。', '[]', '2026-09-10 09:57:14.057270', '2026-09-10 09:57:14.057270', '湖北', '鄂州', '梁子湖', NULL, NULL, NULL, NULL, '');
