INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4201b9a3e7f4734ac2a7dc9cfef8f93', '王露洪', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳新民；山东聊城东昌府；山东聊城；山东济南历城；山东济南；山东菏泽定陶；山东_济南_济阳；山东济南章丘；山东德州禹城；山东济宁嘉祥；山东济宁；山东济南；山东聊城茌平', '[]', '[]', '抗日战争时期', '', '率伪保安队在茌平地区配合日军扫荡，捕杀抗日人员，抢掠民财。；日军侵占济南、历城后组织维持会，为日军带路、筹粮、招募伪警，维持地方伪秩序。；日军侵占济宁后，任伪济宁道公署道尹，管辖济宁及周边嘉祥等县伪政，推行保甲、征粮、抓丁，配合日军清乡扫荡。；掌控定陶伪警察力量，搜捕抗日人员，协助日军维持治安，参与清乡与保甲连坐，迫害当地民众。；掌管伪警察，搜捕抗日人员，镇压市民反抗。；在济南主持伪新民会，进行亲日宣传与奴化教育。；抗日战争时期在禹城地区出任伪县知事，主持伪县政，为日军征粮、派夫、维持治安，是禹城当地直接附逆的伪政权头目。；章丘沦陷初期组织维持会，迎接日军，协助建立伪政权。；莘县沦陷后附逆，任伪莘县知事，配合日军在莘县、聊城交界地区清乡，镇压抗日群众。；掌管伪济南警察系统，参与搜捕抗日人员、推行保甲连坐与治安强化运动。', '[]', '2026-09-10 09:57:14.014147', '2026-09-10 09:57:14.014147', '山东', '德州', '禹城', NULL, NULL, NULL, NULL, '');
