INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e47e24bb1bd84ae2a41c5db702ab66f1', '石宏规', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南怀化溆浦；湖南怀化；湖南湘西吉首；湖南湘西花垣', '[]', '[]', '抗日战争时期', '', '湘西吉首地区人，1944年日军侵入湘西时组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序。；在湘西土家族地区组织伪维持会，为日军筹粮、派夫，协助日军维持占领区秩序，活动范围包括怀化、溆浦。；湘西永绥（今花垣）人，抗战末期出面组织伪维持会，协助日军在湘西边境征粮派夫。', '[]', '2026-09-10 09:57:14.058573', '2026-09-10 09:57:14.058573', '湖南', '怀化', '溆浦', NULL, NULL, NULL, NULL, '');
