INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e48a101e13dd42199151635c7702f687', '何赞', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州；浙江杭州建德；浙江杭州；浙江杭州临安；浙江杭州萧山；浙江杭州；浙江杭州西湖；浙江杭州；浙江杭州富阳；浙江绍兴诸暨；浙江杭州', '[]', '[]', '抗日战争时期', '', '浙江诸暨人，投日后任伪杭州市长，在杭州、滨江地区实施粮食配给，克扣民食，协助日军掠夺丝绸、茶叶等物资。；继任伪杭州市长，在上城地区实施日伪法令，强征劳工，迫害抗日家属。；原国民党杭州地方官员，投日后任伪杭州市长，在桐庐地区组织伪警察，镇压抗日活动。；浙江萧山人，继徐苏中后任伪杭州市长，配合日军“治安强化运动”，实施保甲制度。；投敌后任伪杭州市市长，协助日军维持占领秩序，推行奴化教育，强征物资，压制市民反抗。；浙江富阳本地人，投敌后任伪富阳县知事，为日军提供粮食和民夫，镇压当地抗日游击队。；杭州沦陷初期投敌，组织维持会，为日军提供粮食、情报，协助镇压抗日活动。；杭州沦陷初期组织维持会，协助日军维持秩序，征募劳役。；杭州沦陷后出任伪维持会会长，协助日军维持秩序，征粮派款，为日军服务。；浙江临安人，曾任伪临安县长，在临安地区推行日伪统治，强征壮丁，搜刮民财，镇压抗日武装。', '[]', '2026-09-10 09:57:14.051071', '2026-09-10 09:57:14.051071', '浙江', '杭州', '萧山', NULL, NULL, NULL, NULL, '');
