INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4b74113941141d18362a7404afc3f4a', '张发奎', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西百色靖西；云南普洱西；广西梧州；广西桂林；广西柳州柳北；甘肃甘南合作；广西桂林兴安；云南普洱西', '[]', '[]', '抗日战争时期', '', '抗战期间在华南、广西一带活动，但未附逆，不属于汉奸。；日军曾试图拉拢其合作，但其拒绝，坚持抗日。；在广西等地指挥抗战，无可靠历史记载表明其附逆，此处仅作排除性说明。；有资料提及日军曾试图拉拢其组织伪绥靖机构，但张发奎实际坚持抗日；此条为争议性记录，需谨慎对待。；与广西梧州有军政联系，但坚持抗日，此处仅作背景排除。', '[]', '2026-09-10 09:57:14.031695', '2026-09-10 09:57:14.031695', '广西', '柳州', '柳北', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4c8088b57454700a83865d45704cab4', '李春台', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江苏徐州睢宁；河北石家庄；河北石家庄行唐', '[]', '[]', '抗日战争时期', '', '在行唐县任伪知事，推行“连坐法”，杀害抗日军属，并参与“治安强化”运动。', '[]', '2026-09-10 09:57:14.035220', '2026-09-10 09:57:14.035220', '河北', '石家庄', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4ce341e36124b26bb93d95748d99f85', '王景成', NULL, NULL, NULL, NULL, 'exact', 'exact', '大连', '[]', '[]', '抗日战争时期', '', '伪职：大连伪警察署华人特务系主任；罪行：专门侦查、抓捕大连工人、学生中的地下抗日人员，刑讯迫害被捕爱国分子，搜集民间反日言论。；结局：1946 年逮捕，判处长期徒刑。', '[]', '2026-09-10 09:57:14.076752', '2026-09-10 09:57:14.076752', '辽宁', '大连', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4d1f4f72d09487c81270b929dc182d3', '孙敬之', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口；河南周口沈丘', '[]', '[]', '抗日战争时期', '', '沈丘沦陷区伪政权头目，推行保甲制度，强征壮丁和军粮，配合日军对沈丘、项城交界地区进行清乡扫荡。', '[]', '2026-09-10 09:57:14.047325', '2026-09-10 09:57:14.047325', '河南', '周口', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4dc3b649c0e48eb887d1049a0e3292b', '张子奇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州保德；山西吕梁；山西吕梁石楼；山西；山西运城；山西吕梁；山西太原古交；山西太原清徐', '[]', '[]', '抗日战争时期', '', '在石楼县（今吕梁石楼县）率伪军抢劫百姓，配合日军扫荡。；在吕梁地区推行日军资源掠夺政策，强占煤矿铁矿，强迫劳工开采，并克扣劳工口粮。；为日军收购古交地区煤炭和铁矿，资助伪军，从中牟利。；指挥伪警察抓捕抗日干部，破坏地下交通线，参与“清乡”行动。；组织伪保安队，多次袭击八路军游击队，抓捕抗日群众并送交日军宪兵队，参与杀害抗日干部。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019626', '2026-09-10 09:57:14.019626', '山西', '吕梁', '古交', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4e72d8c84b940158600f46dcc540645', '徐景隆', NULL, NULL, NULL, NULL, 'exact', 'exact', '洮南、白城、江桥前线', '[]', '[]', '抗日战争时期', '', '伪职：张海鹏部伪骑兵团少将团长；罪行：张海鹏核心部下，率伪军作为日军先锋进攻江桥，疯狂进攻马占山抗日部队，在白城周边驻防镇压民众反抗。；结局：江桥作战中被抗日武装击毙。', '[]', '2026-09-10 09:57:14.083686', '2026-09-10 09:57:14.083686', '吉林', '白城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e4f48533a7e74b25bcb7b029c5522aea', '董友梅', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南德宏芒市', '[]', '[]', '抗日战争时期', '', '协助伪维持会工作，负责摊派粮款、登记民户，为日军提供劳工。', '[]', '2026-09-10 09:57:13.980574', '2026-09-10 09:57:13.980574', '云南', '德宏', '芒市', NULL, NULL, NULL, NULL, '');
