INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e502116b666a4a7094a51a206b5114fb', '陈应道', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼和浩特和林格尔；内蒙古呼和浩特；内蒙古包头达尔罕茂明安；内蒙古巴彦淖尔', '[]', '[]', '抗日战争时期', '', '包头地区汉奸，伪政权地方官员，其管辖范围与巴彦淖尔东部接壤，协助日军在绥西推行保甲制度和经济掠夺。；萨拉齐（今属包头）地方士绅，投靠日军后任维持会会长、伪县长，配合日军在绥远中部地区的统治，影响波及呼和浩特周边。；协助日军控制包头经济，为日军筹集物资、资金，参与对达尔罕茂明安等地畜产品的掠夺。', '[]', '2026-09-10 09:57:13.988106', '2026-09-10 09:57:13.988106', '内蒙古', '包头', '达尔罕茂明安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e504c5e197674443ab3456b6f0cfa25b', '刘伯常', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西汉中勉县；陕西汉中洋县', '[]', '[]', '抗日战争时期', '', '在洋县组织伪维持会，协助日军征粮征夫，推行奴化宣传，压制民众抗日情绪。', '[]', '2026-09-10 09:57:14.064777', '2026-09-10 09:57:14.064777', '陕西', '汉中', '勉县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e5184b74a765479e82a5e3241e3cbd2f', '李服膺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原；山西晋中左权；山西太原阳曲；山西忻州五台；山西；山西太原小店；山西临汾；山西晋中；山西吕梁孝义；山西吕梁离石；山西_太原_清徐', '[\"注：因作战不力被处决，非汉奸\"]', '[]', '抗日战争时期', '', '无；原地方士绅，日军占领汾西后出任维持会长，协助日军建立伪政权，提供情报，强征民夫修筑碉堡。；原晋绥军将领，投日后任伪晋南保安司令，驻临汾地区，指挥伪军配合日军进攻隰县、蒲县等抗日根据地。；原晋军将领，投敌后任伪职，在临汾、隰县一带组织伪保安队，配合日军“扫荡”，残害抗日军民。；原为地方士绅，日军占领霍州后出任维持会长，为日军筹集粮食、物资，组织伪自卫团，协助日军镇压当地抗日游击队。；原晋绥军将领，投敌后任伪“剿共”司令，在孝义、中阳、离石一带多次率伪军袭击八路军游击队，烧杀抢掠。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.019414', '2026-09-10 09:57:14.019414', '山西', '吕梁', '孝义', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e5231869bd264eceb014ee174d9ac704', '黄崑山', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁江南；广西南宁；广西南宁；广西南宁武鸣；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '南宁沦陷期间出面组织维持会，为日军筹粮、派夫、维持治安，协助日军控制南宁城区。；日军占领南宁后，出面组织伪商会，为日军筹款筹粮，协助日军控制南宁经济。；组织伪自卫团配合日军扫荡南宁周边乡村，搜捕抗日游击队员。', '[]', '2026-09-10 09:57:14.030786', '2026-09-10 09:57:14.030786', '广西', '南宁', '武鸣', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e526f52faa9d469e9df0e0b53bf491c2', '张楚材', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北武汉黄陂；湖北荆州荆州经开区；湖北荆门；湖北咸宁通山；湖北咸宁嘉鱼；湖北咸宁咸安；湖北咸宁；湖北咸宁通城；湖北咸宁；湖北黄冈黄梅；湖北孝感汉川；湖北孝感；湖北黄石阳新；湖北荆州江陵；湖北咸宁崇阳；湖北咸宁', '[]', '[]', '抗日战争时期', '', '控制咸宁商会，为日军强制征购粮食、物资，协助日军经济掠夺。；在江陵县任职伪警察局长，协助日军维持治安，抓捕抗日人士，迫害无辜百姓。；湖北黄梅人，伪黄梅县地方武装头目，率伪保安大队配合日军在黄梅、广济一带扫荡，捕杀抗日人员，勒索民财。；嘉鱼沦陷后组织维持会，替日军筹粮筹款，协助建立伪政权。；孝感沦陷后组织维持会，后任伪孝感县县长，协助日军统治孝感地区。；蒲圻（今赤壁）沦陷后投敌，任伪维持会会长、伪县长，活动范围邻近崇阳、咸宁。；抗战期间投敌，任伪黄陂县警察局局长，在黄陂地区协助日军维持治安，镇压抗日活动。；在阳新地区组织伪保安大队，为日军守卫据点、搜集情报，参与对抗日根据地的封锁和扫荡。；荆门沦陷后任伪维持会会长，活动范围邻近荆州北部，协助日军控制荆襄通道。；在湖北伪政权中任职，负责咸宁一带的伪化行政，推行保甲连坐，配合日军经济掠夺。', '[]', '2026-09-10 09:57:14.055166', '2026-09-10 09:57:14.055166', '湖北', '咸宁', '咸安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e529de862a194a1594481daccd3a4ef1', '宋子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中介休；山西晋城；山西晋城阳城；山西；山西晋城沁水', '[]', '[]', '抗日战争时期', '', '在阳城宣传“大东亚共荣”，诱骗青年参加伪军，破坏抗日宣传。；在辖区强制推行“良民证”，勒索百姓，向日军报告抗日活动。', '[]', '2026-09-10 09:57:14.022264', '2026-09-10 09:57:14.022264', '山西', '晋中', '介休', NULL, NULL, NULL, NULL, '');
