INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e5f792b58d8c468f85e2b9b65cf7d3dd', '乌古廷', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古赤峰喀喇沁旗；内蒙古乌海乌达；内蒙古、河北；内蒙古乌兰察布化德；内蒙古呼伦贝尔；内蒙古兴安阿尔山；内蒙古呼伦贝尔牙克石；内蒙古_锡林郭勒_锡林浩特；内蒙古巴彦淖尔；内蒙古通辽霍林郭勒；内蒙古赤峰红山；内蒙古乌海乌达；内蒙古通辽扎鲁特旗；内蒙古通辽；内蒙古通辽开鲁；内蒙古通辽；内蒙古包头；内蒙古乌兰察布；内蒙古呼和浩特；内蒙古乌海；内蒙古呼和浩特；内蒙古呼和浩特玉泉；内蒙古锡林郭勒二连浩特；内蒙古通辽；内蒙古赤峰翁牛特旗；内蒙古乌海乌达；内蒙古呼伦贝尔额尔古纳；内蒙古通辽奈曼旗；河北张家口康保；内蒙古通辽科尔沁左翼中旗；内蒙古赤峰巴林左旗；内蒙古乌兰察布；内蒙古通辽库伦旗；内蒙古锡林郭勒镶黄旗；内蒙古兴安乌兰浩特；内蒙古赤峰巴林右旗；内蒙古乌海乌达', '[]', '[]', '抗日战争时期', '', '伪蒙古军高级指挥官，活动于乌兰察布南部及兴和一带，多次率部袭击八路军大青山支队，破坏抗日政权。；在化德及周边地区驻防，配合日军“清乡”，迫害抗日家属。；指挥伪兴安军驻守乌兰浩特，多次配合日军进攻抗联三路军，屠杀抗日军民。；伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长，推行日伪殖民政策，强征劳工，协助日军统治当地蒙汉民众。；蒙古族军官，投靠德王后任伪军参谋长，在包头地区参与军事指挥，协助日军围剿抗日游击队。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.986298', '2026-09-10 09:57:13.986298', '内蒙古', '兴安', '乌兰浩特', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e5f845b97e5c4f8a8522d2d4d866f41c', '王百善', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：后期伪安国县长；五一大扫荡之后强化伪大乡制度，强征粮米。；结局：解放后镇反处决', '[]', '2026-09-10 09:57:14.079646', '2026-09-10 09:57:14.079646', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
