INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e6011ca0c3224e8790219d1d41c926e5', '多英培', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南德宏芒市', '[]', '[]', '抗日战争时期', '', '日军侵占遮放后，多英培出面组织维持会，为日军筹集粮食、修筑工事，并带领伪军配合日军巡逻，搜捕抗日人员。', '[]', '2026-09-10 09:57:13.980459', '2026-09-10 09:57:13.980459', '云南', '德宏', '芒市', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e6042aca95d9458d96851fedd27f3f8d', '孙玉田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林白山长白；山东潍坊；山东潍坊临朐；吉林通化柳河；吉林；吉林白山长白；吉林白山靖宇；山东_潍坊_安丘；山东济南莱芜；吉林磐石；山东济南槐荫；山东济南', '[]', '[]', '抗日战争时期', '', '审判并迫害抗日志士，以“反满抗日”罪名判处多人死刑或长期监禁，并协助日军建立“思想矫正院”。', '[]', '2026-09-10 09:57:13.999907', '2026-09-10 09:57:13.999907', '吉林', '白山', '长白', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e605bdc0757042d988aae44750241ea6', '陈文波', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西钦州浦北；广西钦州；广东茂名；广西贵港；广东江门台山；广西_钦州_钦南；广东阳江阳东；辽宁沈阳大东；广西北海；广西防城港；广西北海合浦；广西梧州；广西梧州苍梧；湖北武汉青山；湖北武汉汉阳；广西贵港港南；广东茂名茂南；广东茂名电白；广东云浮郁南；广东茂名；广东肇庆端州；广东肇庆', '[]', '[]', '抗日战争时期', '', '抗战期间在汉阳伪政权中任职，协助日军管理汉阳地区。；组织亲日宣传，散布“大东亚共荣”言论，为日军侵略行为辩护，麻痹民众抗日意志。；在钦州组织伪维持会，为日军提供情报和物资，协助日军进攻钦州、防城一带抗日武装。；在茂名组织伪维持会，协助日军统治。；在电白县投敌，组织维持会，为日军筹集物资，协助日军控制电白沿海地区，迫害抗日人员。；协助维持会会长办理日常事务，为日军翻译、带路，参与征收苛捐杂税。；组织商人向日军献金献物，协助日军控制钦州物资流通。；在日军控制合浦期间担任伪警察局长，率伪警察配合日军搜捕抗日人员、镇压民众反抗。；任伪台山警察局长期间，带领伪警配合日军搜捕抗日志士，勒索商户，维持沦陷区法西斯统治。；梧州沦陷后任伪苍梧县县长，推行日伪政令，征粮征税。；充任伪警察头目，配合日军搜捕抗日人员，镇压民众抗日活动，维护日伪在钦县的统治秩序。；在日军占领期间把持伪商会，为日军强制摊派物资，压榨商户。；在肇庆、高要推行伪财政政策，为日军征收田赋、捐税，搜刮民财，支持日伪统治。；抗战期间在广东南路伪保安系统任职，组织伪保安队配合日军行动，活动范围涉及茂名、高州及周边地区。', '[]', '2026-09-10 09:57:14.025963', '2026-09-10 09:57:14.025963', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
