INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e6f1ddda94c44dd8a7bc0e0b69259e5d', '陈明山', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江绥化安达；黑龙江绥化望奎；黑龙江绥化；黑龙江大庆杜尔伯特；吉林松原长岭', '[]', '[]', '抗日战争时期', '', '在伪满长岭县组织伪自卫团，配合日军和伪警察搜捕抗日人员，控制地方。；组建伪保安团，配合日军在绥化、望奎、庆安等地讨伐抗日联军，杀害抗日军民，后升任伪滨江省保安总队副。；地方士绅，投敌后任伪泰康县维持会会长，泰康即今杜尔伯特蒙古族自治县前身之一，其直接协助日军在杜尔伯特地区建立殖民统治。；在安达地区警察系统任职，配合日伪军警进行治安肃正与情报活动。', '[]', '2026-09-10 09:57:13.999162', '2026-09-10 09:57:13.999162', '吉林', '松原', '长岭', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e6f2d26d2bba489aaf4e24816029ba66', '刘伯言', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东菏泽菏泽高；山东菏泽成武；山东济南济阳；山东济宁兖州；辽宁沈阳新民；江苏泰州姜堰；江苏泰州；山东济宁汶上；山东济宁；山东临沂平邑；山东临沂；山东济南商河；辽宁沈阳新民；山东济南天桥；山东济南；山东济南钢城；山东济南；山东临沂；山东临沂沂水；山东泰安东平；辽宁沈阳新民；山东济南市中；山东济南；山东泰安泰山；山东泰安；山东济宁任城；山东济宁；山东济宁金乡；山东聊城冠县；山东淄博淄川；辽宁沈阳大东；山东济宁；山东临沂兰陵；辽宁沈阳大东；山东临沂临沭；山东临沂', '[]', '[]', '抗日战争时期', '', '在博山组织新民会活动，宣传“大东亚共荣圈”，配合日伪统治。；在济宁组织伪新民会，进行亲日宣传，配合日军推行奴化教育，协助征粮征丁。；在济南任伪警察头目，搜捕抗日志士，管理保甲与良民证，配合日军特务机关。；通过新民会推行奴化宣传，在济南、商河等地组织亲日团体。；推行奴化教育，在临沂各学校强制使用日伪教材，宣传“大东亚共荣”，毒害青少年。；在泰安道所属各县包括东平推行新民会运动，进行奴化教育。；济阳沦陷后组织维持会，为日军带路、征粮，协助建立伪政权。；在济南道区推行伪政权政令，协助日军征粮、征丁，镇压地方抗日力量。；济南沦陷初期参与组织维持会，为日军筹粮筹款。；沂水沦陷后投敌，组织伪政权，配合日军对沂蒙山区包括临沂北部、平邑周边进行扫荡和封锁。；率伪保安团配合日军扫荡济宁、嘉祥、金乡一带抗日根据地，抢粮抓夫，残害百姓。；抗战期间任伪金乡县知事，配合日军在金乡地区推行保甲制、征粮派款，镇压当地抗日武装。；在成武地区推行伪化统治，征粮征夫，协助日军镇压抗日力量。；率伪保安团配合日军进攻冠县抗日根据地，烧杀抢掠，残害抗日军民。；控制泰州商业，为日军采购军需物资，协助日伪对沦陷区经济掠夺和物资统制。；作为日伪顾问参与泰安地区政务，协助日军控制地方，镇压抗日力量。；主持伪济宁县政，配合日军维持治安，搜捕抗日分子，摊派苛捐杂税。；在济宁县城组织伪政权，协助日军维持治安，迫害抗日家属，强征劳工。；临沂周边沂水县伪政权头目，推行保甲制，协助日军控制山区交通线。；在济南市中区一带充当保甲长，协助日军清查户口、监视居民、摊派捐税。；任伪沂州道道尹期间，管辖临沂、临沭等县伪政权，推行日军政令，征粮征兵，镇压抗日活动。；任伪济宁县警察局长期间，配合日军搜捕抗日人员，镇压民众反抗，维护伪政权治安。', '[]', '2026-09-10 09:57:14.012497', '2026-09-10 09:57:14.012497', '山东', '临沂', '临沭', NULL, NULL, NULL, NULL, '');
