INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7838f999a8e462db6a7e110e72f7807', '王济之', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：原国际情报组织人员，叛变后任安东宪兵特务；罪行：原为共产国际情报员，1935 被捕叛变；出卖安东情报组织，大量地下人员被捕牺牲，充当日伪特务爪牙。；结局：光复后民主政府公审判处死刑。', '[]', '2026-09-10 09:57:14.087351', '2026-09-10 09:57:14.087351', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e790a1d9819a481ea66bc179660b2166', '沈鸿', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏常州；浙江嘉兴桐乡；浙江宁波镇海；浙江宁波', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军“清乡”，在常州周边乡村烧杀抢掠，抓捕壮丁。；投靠日军，出任伪桐乡县知事，协助日军维持占领区秩序，征收捐税，镇压抗日活动。；宁波沦陷初期组织维持会，为日军提供物资和情报，协助建立伪政权。', '[]', '2026-09-10 09:57:14.034798', '2026-09-10 09:57:14.034798', '江苏', '常州', '桐乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7a1c3d872884442a3e140c73372fed9', '黄奕住', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；福建泉州晋江；福建厦门；福建泉州南安；福建厦门；福建泉州德化；福建泉州；福建泉州石狮；福建泉州；福建漳州漳浦；福建漳州芗城；福建漳州；福建宁德福安；福建厦门；福建宁德蕉城；黑龙江牡丹江东宁；福建泉州金门；福建厦门；福建厦门；福建泉州南安；福建泉州；福建泉州鲤城；福建厦门；福建漳州诏安；福建厦门；福建龙岩漳平；福建厦门；福建厦门；福建_厦门_同安；辽宁阜新太平；福建漳州；福建厦门；福建泉州洛江；福建泉州；福建厦门', '[]', '[]', '抗日战争时期', '', '厦门知名人物，抗战期间与日伪政权有经济合作记载，参与维持地方殖民秩序。；厦门沦陷后附逆，出任伪厦门特别市商会会长，协助日军控制闽南经济与物资调配，其商业网络覆盖泉州、晋江一带。；在泉州城郊充当伪保甲长，协助日军清查户口、抓捕抗日人员，向伪警察局密报南安籍抗日家属。；福建南安人，抗战期间在厦门附逆，协助日军控制闽南物资流通，其商业网络覆盖泉州、泉港，为日军采购战略物资。；在日军控制下出面组织伪商会，强制泉州、厦门等地商户向日军缴纳“献金”和物资，协助经济掠夺。；厦门沦陷后与日伪政权有合作记录，参与地方伪自治与筹款征发。；厦门沦陷初期参与维持会，协助日军维持地方秩序并推行伪化统治。；厦门沦陷期间参与伪经济统制机构，协助日军掠夺福建沿海物资，影响闽东宁德等地经济。；虽为商人，但在沦陷区与日伪合作，协助经济统制，其商业网络覆盖泉州。；厦门沦陷后出任伪商会会长，协助日军经济统制，其商业网络覆盖漳州、云霄等地，为伪政权提供物资支持。；在厦门为日军统制物资、征购粮食，协助日伪经济掠夺，间接影响闽东物资流通。；厦门商界人物，与日伪合作，参与物资统制与对日供应，影响厦门及海沧经济。；厦门华侨富商，日军占领厦门后强迫其挂名伪经济顾问，利用其声望向泉州、晋江侨乡诱骗资金与物资。；泉州沦陷前后，部分地方士绅被日伪拉拢参与维持会事务；黄奕住之名在部分地方史料中与泉州伪维持会有关联，但记载有限。；漳浦商人，日军骚扰沿海时出面组织伪商会，为日军采购物资、筹集款项，并协助日军在漳浦建立情报点。；在厦门伪政权中负责物资统制，协助日军掠夺闽南物资，其活动范围覆盖漳州、诏安等地，对当地经济造成严重破坏。；厦门商界人物，沦陷后与日伪合作，组织商会为日军筹款筹粮，属经济附逆者。；厦门商人，抗战期间与日伪合作，控制闽南部分贸易。；闽南知名商人，厦门沦陷后与日军合作，为日军采购战略物资，其商业网络覆盖漳州地区。；厦门知名商人，附逆后参与伪政权咨询机构，为日军统治粉饰门面。；以地方士绅身份参加伪参议会，为日伪统治粉饰门面。；厦门富商，抗战期间附逆，任伪参议员，为日军经济统治效力，与泉州商界有往来。；厦门富商，抗战期间附逆，出任伪参议员，协助日军在闽南推行伪政，其商业网络涉及泉州、惠安。；作为厦门商界人物，在沦陷后参加伪参议会，为日军统治粉饰太平，协助摊派捐税。；泉州沦陷期间任伪商会会长，为日军筹款筹粮。；在漳州地区为日军强制征购粮食、矿产，配合经济封锁，压榨当地民众。', '[]', '2026-09-10 09:57:14.060752', '2026-09-10 09:57:14.060752', '福建', '厦门', '同安', NULL, NULL, NULL, NULL, '');
