INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7ccbeb14fb647a18307a11e03819921', '王体乾', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏宿迁沭阳', '[]', '[]', '抗日战争时期', '', '投靠日军，任沭阳县维持会会长及伪县长，协助日军推行“治安强化”运动，强征粮税，镇压抗日民众。', '[]', '2026-09-10 09:57:14.034665', '2026-09-10 09:57:14.034665', '江苏', '宿迁', '沭阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7d9305bc556438884264d1cf2e84ff8', '周梦熊', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北_石家庄_桥西', '[]', '[]', '抗日战争时期', '', '强征各种苛捐杂税，包括“人头税”“门牌税”，搜刮民财供日军军需。', '[]', '2026-09-10 09:57:14.043622', '2026-09-10 09:57:14.043622', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7df249bc25f470fb0a01096813de76a', '李铭钦', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济南长清；山东济南平阴；山东济南济南高；辽宁沈阳新民；山东济南；山东_济南_钢城；山东济南', '[]', '[]', '抗日战争时期', '', '任伪济南市长期间配合日军统治，推行保甲、征发劳役。；在济南推行伪市政措施，配合日军经济统制与治安强化运动。；长期任伪济南市市长，推行保甲制，配合日军清乡、掠夺物资。；组织商界附逆，为日军筹款筹物，配合经济统制。；在济南为日军筹款筹粮，组织商界附逆，支持日伪经济统制。；协助日军统制济南工商业，强制摊派物资，为伪政权筹款。；任伪济南商会会长，为日军筹款筹粮，控制经济，协助日伪物资统制。；组织商界附逆，为日军筹措物资、摊派款项。；在济南工商界为日军筹款筹物，组织伪新民会活动，进行奴化宣传。；日伪在长清县设立伪政权后任伪县长，配合日军清乡、征粮、修筑据点。；济南商界附逆代表人物，协助日军筹款、征物，控制商会为伪政权服务。；平阴沦陷后任伪县知事，组织伪政权和伪军，协助日军扫荡平阴及周边抗日根据地。；济南商界附逆代表人物，组织商会为日军筹款筹物，协助经济统制与物资掠夺。', '[]', '2026-09-10 09:57:14.014983', '2026-09-10 09:57:14.014983', '山东', '济南', '市中', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7e122f9805141f4aaa49f03365ed8cb', '赵德贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西宜春靖安；山西阳泉城区；湖北恩施鹤峰；山西阳泉城区；江西上饶弋阳', '[]', '[]', '抗日战争时期', '', '控制宜春城区商业，为日军采购军需物资，强制商户‘献金’，并协助日军对食盐、药品等实行统制。；协助伪维持会会长管理恩施城区，登记户口，发放良民证，配合日军清查抗日分子。；率领伪保安队协助日军在弋阳及周边地区清剿抗日武装，欺压百姓。', '[]', '2026-09-10 09:57:14.037965', '2026-09-10 09:57:14.037965', '江西', '上饶', '弋阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7e4c972cf84472b9a0d77de929744cd', '孙文兰', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪便衣特务队长，海启一带作恶，残杀民兵，悬挂人头恐吓群众南通史志网。。结局：被东南行动大队锄奸处决', '[]', '2026-09-10 09:57:14.086908', '2026-09-10 09:57:14.086908', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7e624cfd62642d2be7b77269bcbcbfa', '金泽洙', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林延边延吉', '[]', '[]', '抗日战争时期', '', '朝鲜族亲日分子，在延吉地区组织协和会活动，进行亲日宣传和情报收集。', '[]', '2026-09-10 09:57:13.998391', '2026-09-10 09:57:13.998391', '吉林', '延边', '延吉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7f4e33a063b40228f0f48fcdbf3262b', '赵筱山', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南开封；辽宁沈阳新民；河南开封祥符；辽宁沈阳大东；河南信阳商城；河南新乡卫滨；河南新乡；河南驻马店新蔡；河南驻马店；河南洛阳洛宁；河南郑州管城；河南开封禹王台；河南开封；河南周口；河南周口淮阳；河南开封顺河；河南开封；河南洛阳老城；河南洛阳；河南郑州；河南郑州中牟；河南开封；河南驻马店遂平；辽宁沈阳大东；河南开封鼓楼；河南开封杞县；河南开封；河南开封龙亭；河南商丘虞城；河南商丘', '[]', '[]', '抗日战争时期', '', '作为商会汉奸，为日军筹款筹物，协助控制新乡商业与经济，压榨当地商户民众。；投敌后率保安队配合日军在洛宁境内清乡，抓捕抗日群众。；作为开封商界附逆代表，为日军筹款筹物，协助经济统制与物资征发。；任伪郑州警察局局长，协助日军搜捕抗日人员，维持占领区治安，参与镇压民众反抗。；淮阳地方武装头目投敌后任伪保安团团长，配合日军扫荡淮阳、太康、鹿邑一带，捕杀抗日人员，强征民夫修筑据点。；商城沦陷期间出面组织维持会，为日军筹粮、派夫、带路，协助建立伪基层秩序。；在开封顺河一带参与伪维持会与伪区政，协助日军推行保甲、征发劳工。；协助日军控制开封工商业，摊派捐款，为伪政权提供经济支持。；协助日军控制开封商业，为日军采购军需物资。；协助王旭初组织维持会，为日军征发民夫、物资。；西平县附逆士绅，组织维持会迎降日军，其活动范围与驻马店、新蔡伪政权有联系，协助日军征粮派款。；在遂平推行奴化教育，改编教材，强制学生学习日语，宣传“大东亚共荣圈”。；在洛阳老城推行奴化教育，改编学校课程，强制师生学习日语和亲日内容，为日军培养顺民。；在商丘组织伪保安团，配合日军下乡扫荡，抢粮抓夫，镇压抗日群众，活动范围包括商丘、虞城交界地区。；协助王旭初组织维持会，为日军提供情报与物资，参与建立基层伪组织。；通过新民会进行奴化宣传，组织亲日团体，配合日军思想控制。；在开封主持伪宣传，推行奴化教育，宣传“中日亲善”“大东亚共荣圈”，麻痹民众抗日意识。；在开封等地为日军筹款筹物，控制沦陷区商业，协助日军经济掠夺。；控制沦陷区报刊、广播，为日军进行欺骗宣传，粉饰侵略，诋毁抗日力量。', '[]', '2026-09-10 09:57:14.046345', '2026-09-10 09:57:14.046345', '河南', '信阳', '商城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7f9c9c14e2643b9b8546b59f198ef0e', '钱孙卿', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏无锡锡山', '[]', '[]', '抗日战争时期', '', '在锡山地区组织伪参议会，为日伪政策背书，协助征粮派款。', '[]', '2026-09-10 09:57:14.035899', '2026-09-10 09:57:14.035899', '江苏', '无锡', '锡山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e7fe7cdc620844c1b7c81a5dc5e0e498', '刘长伦', NULL, NULL, NULL, NULL, 'exact', 'exact', '宿县尹集周边', '[]', '[]', '抗日战争时期', '', '伪职：伪连长；罪行：率便衣特务偷袭尹集区公所，图谋杀害区长，四处搜集根据地情报，绑架勒索群众。；结局：时村攻破被俘，镇压处决。', '[]', '2026-09-10 09:57:14.075349', '2026-09-10 09:57:14.075349', '安徽', '宿州', NULL, NULL, NULL, NULL, NULL, '');
