INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e80f1d9ba7c94bd69f8305b3e4ca4aa8', '赵从懿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北唐山；河北；河北唐山唐山海港经开区；河北唐山；河北秦皇岛', '[]', '[]', '抗日战争时期', '', '推行奴化教育，在唐山、乐亭等地学校强制教授日语，删除抗日内容。；指挥伪警察镇压唐山地区抗日民众，协助日军维持占领秩序。；参与冀东伪政权核心决策，对秦皇岛地区实施殖民统治', '[]', '2026-09-10 09:57:14.041534', '2026-09-10 09:57:14.041534', '河北', '唐山', '唐山海港经开区', NULL, NULL, NULL, NULL, '');
