INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e81823b321834909a19a4beac811fd7b', '鲁苏容', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西玉山', '[]', '[]', '抗日战争时期', '', '伪职：附日密探；罪行：与郑和尚一同充当日军眼线，探查游击队动向，被抓获枪决；来源：玉山之窗党史资料；备注：浙赣战役时期', '[]', '2026-09-10 09:57:14.085105', '2026-09-10 09:57:14.085105', '江西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e819160dc2954bf1b620fc52153b6a01', '温世珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；天津；天津_静海；天津_西青；陕西_西安_长安；湖南常德津；江西九江；重庆沙坪坝；天津_武清；河北廊坊；天津南开；天津、河北；湖南常德津；天津_蓟州；天津河北；湖南常德津；天津东丽；湖南常德津；天津红桥；天津河北', '[]', '[]', '抗日战争时期', '汪伪政权', '在任期间强化对廊坊南部伪县署的控制，协助日军“扫荡”冀中十分区。；继任伪市长，继续为日本侵略服务，强化对天津及周边地区（含东丽）的殖民管理，征粮派款，镇压抗日活动。；继任伪天津特别市市长，协助日军实施经济掠夺和殖民统治，参与奴化教育推广。；在伪市府任职，参与日伪行政事务，协助推行保甲制度。；全面推行日伪奴化教育，强征劳工，配合日军“华北新建设运动”，在南开区强拆民房修建军事设施，镇压学生反日运动。；长期担任伪天津市长，积极执行日本占领军命令，强化保甲制度，镇压抗日民众，为日军提供劳役和物资。……（共涉及30个地区的犯罪记录）；伪任职务：伪天津特别市市长（任期最长，1938??1943），推行保甲、强征劳工、物资掠夺。结局：1951 年镇反，判处死刑枪决', '[]', '2026-09-10 09:57:13.983160', '2026-09-10 09:57:13.983160', '湖南', '常德', '津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e81ddf64d3ce4a1b813b5e42bb426159', '刘铁夫', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳；广东阳江；湖南益阳安化；湖南益阳益阳大通湖管理；安徽淮南大通；湖南益阳；湖南岳阳', '[]', '[]', '抗日战争时期', '', '湘阴地区伪保安队头目，投靠日军，在湘阴及洞庭湖周边进行伪化活动，与益阳大通湖地区有接触。；统领伪保安团，配合日军维持治安，参与逮捕抗日分子。；率伪护路队保护日军铁路运输，参与清剿铁路沿线抗日武装，抓捕破坏交通人员。；岳阳沦陷后长期担任伪维持会头目，为日军提供粮秣、情报，参与奴化宣传。；为日军筹款筹粮，强制商户交纳“治安费”，协助日军控制物资流通。', '[]', '2026-09-10 09:57:14.030259', '2026-09-10 09:57:14.030259', '广东', '阳江', '安化', NULL, NULL, NULL, NULL, '');
