INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e8420f0226a44fde962ab7e73f460a94', '佚名南山电台间谍', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详，伪装苦力', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：潜伏重庆南山架设秘密电台，专门向日军发送重庆本地气象情报，解释日军总选晴天轰炸重庆的原因。。结局：军统破获当场抓获，处决', '[]', '2026-09-10 09:57:14.083375', '2026-09-10 09:57:14.083375', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e843257c18f14baba2f670946c8d3800', '张二贵', NULL, NULL, NULL, NULL, 'exact', 'exact', '柳林（临县交界）', '[]', '[]', '抗日战争时期', '', '伪职：据点汉奸特务；罪行：投靠日军，搜集情报，抓捕杀害抗日干部，四处敲诈百姓吕梁新闻网。；结局：解放后公审处决', '[]', '2026-09-10 09:57:14.084143', '2026-09-10 09:57:14.084143', '山西', '吕梁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e84aaab18fde4593a31cdc732d335b21', '林宪祖', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东聊城；山东济南长清；辽宁沈阳新民；辽宁沈阳大东；山东烟台；山东济南', '[]', '[]', '抗日战争时期', '', '在济南道区推行伪政，协助日军征粮征丁、控制地方。；驻济南，通过新民会进行亲日宣传、组织训练、协助日军控制基层。；负责伪山东财政，在聊城、茌平征粮征税，支持日军经济掠夺。；曾任伪山东省省长，在山东全省包括烟台地区推行日军殖民政策，协助征发劳工、物资，镇压抗日力量。；在伪山东省政府任职，参与制定伪化政策，涉及烟台、芝罘地区的基础设施与资源掠夺。；在伪山东省公署任职，参与制定和推行针对鲁西聊城等地的殖民统治措施，协助日军征发劳工、粮食。；在济南推行奴化教育，修改教材，宣传“中日亲善”“大东亚共荣圈”。', '[]', '2026-09-10 09:57:14.015024', '2026-09-10 09:57:14.015024', '山东', '济南', '长清', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e85897429cdb4e34b0b105b3841408f0', '周应湘', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东韶关乐昌；广东韶关；广东佛山；广东茂名；广东_韶关；广西桂林资源；广东广州南沙；广东广州；广东河源；辽宁沈阳大东；广东江门；广东广州；广东湛江赤坎；辽宁沈阳大东；广西柳州鹿寨；云南普洱西；广东广州花都；广东_云浮_郁南；广东揭阳', '[]', '[]', '抗日战争时期', '', '在广东伪政权教育部门任职，推行奴化教育，宣传所谓“大东亚共荣”。；任伪广东财政厅长，为日军筹措军费、搜刮民财。；曾任汪伪广州市长，主持广州沦陷区市政，配合日伪统治。；日军侵占江门、新会期间出面组织维持会，后任伪新会县县长，为日军征发物资、维持治安，镇压抗日群众。；负责汪伪广东财政，在佛山等地强征苛捐杂税，为日军及伪政权搜刮民财。；在广东推行奴化教育，篡改教材，宣传“大东亚共荣”，影响佛山、三水等地学校。；汪伪广东教育厅厅长，推行奴化教育，篡改教材，宣传所谓大东亚共荣。；韶关地区伪维持会负责人，协助日军管理地方，征发民夫物资，镇压抗日活动。；广东财政领域附逆者，协助日军控制华南经济，活动区域与广西邻近。；河源沦陷期间组织维持会，为日军征派粮秣、劳工，协助维持地方伪秩序。；广州商界附逆代表，组织伪商会，配合日军经济统制，为日伪采购物资。；汪伪政权官员，曾任伪广州市长、伪广东省民政厅长等职，负责地方民政与伪化教育。；汪伪政权任命的花县伪县长，在花都地区推行日军政策，征粮征丁，镇压抗日活动。；伪军头目，负责潮汕地区警备，配合日军对揭阳、榕城等地的控制与扫荡。；负责伪广东省财政，为日军筹措军费与物资，对茂名、电白等县实施苛捐杂税与经济掠夺。；负责伪广东财政搜刮，为日军提供物资与经费支持。；负责广东沦陷区经济统制，为日军掠夺粮食、矿产等资源，强制推行伪币，破坏广东经济。；曾任伪广州市长，协助日伪维持广州及周边地区统治。', '[]', '2026-09-10 09:57:14.025356', '2026-09-10 09:57:14.025356', '广东', '广州', '南沙', NULL, NULL, NULL, NULL, '');
