INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e8f808cff0364556baf8a4b82198de79', '王含章', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏石嘴山；宁夏吴忠；宁夏银川灵武；宁夏银川；内蒙古乌兰察布集宁', '[]', '[]', '抗日战争时期', '', '受伪蒙疆政权派遣，潜入宁夏吴忠、金积、灵武等地，联络地方士绅和回教上层，宣传日伪‘回回国’计划，搜集情报并策反地方武装。；受伪蒙疆政权派遣，潜入宁夏银川及周边地区，联络地方士绅和回族上层，策动建立亲日伪组织，收集宁夏驻军情报，并协助日伪进行经济渗透和走私活动。；日军侵占绥远后，在包头、五原一带活动，受日军指使筹组伪宁夏政权，拉拢宁夏地方士绅，企图在石嘴山、银川等地建立伪组织，为日军西侵服务。', '[]', '2026-09-10 09:57:14.003738', '2026-09-10 09:57:14.003738', '宁夏', '吴忠', NULL, NULL, NULL, NULL, NULL, '');
