INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e95caf6eb3ca460cbfaa56d592e6e8fd', '孙鸣岗', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台栖霞；江苏南京栖霞；山东烟台莱阳；山东烟台牟平；山东烟台蓬莱；山东威海文登；山东威海威海经开区；辽宁沈阳大东；山东青岛即墨', '[]', '[]', '抗日战争时期', '', '在文登地区出任伪职，协助日军推行伪化教育，配合日军对胶东抗日根据地的扫荡。；牟平沦陷后组织维持会，任伪县长，配合日军扫荡昆嵛山抗日根据地，残害抗日军民。；组织伪保安团，配合日军对即墨及周边地区进行扫荡，残害抗日军民。；任伪胶东道尹，管辖烟台、栖霞等胶东各县伪政权，推行日军殖民政策，组织伪军配合扫荡，征发劳工和物资。；在威海卫推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青少年。', '[]', '2026-09-10 09:57:14.013510', '2026-09-10 09:57:14.013510', '山东', '威海', '威海经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e960f62b1a2942f1869de3bb59e9d9d9', '张星炳', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏泰州泰州医药高；江苏泰州；江苏南京；江苏扬州；江苏泰州兴化；江苏扬州邗江；江苏扬州；江苏扬州仪征；江苏扬州；江苏泰州；江苏扬州广陵；江苏扬州；江苏泰州海陵；江苏扬州扬州经开区；江苏扬州', '[]', '[]', '抗日战争时期', '', '在扬州（江都）任伪县长期间，推行日伪“清乡”政策，强征粮税，抓捕抗日志士，协助日军维持占领秩序。；扬州沦陷后出任伪维持会会长，后任伪江都县知事，为日军征粮派款，镇压抗日民众，协助建立伪政权。；在扬州广陵地区推行伪政权，协助日军征粮、征税，抓捕抗日志士，参与‘清乡’运动。；扬州沦陷后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权，镇压抗日活动，后任伪江都县知事，管辖邗江一带。；主持兴化地区“清乡”工作，设立封锁线，强迫村民连坐，杀害新四军交通员。；日军侵占泰州后出面组织维持会，后任伪泰县县长，推行保甲制度，为日军征粮派款，协助日军统治泰州城乡。；在苏南地区配合日军作战；在泰县（今海陵区及周边）任伪县长期间，推行日伪统治，强征粮税，镇压抗日活动，协助日军建立伪政权。；在泰州（今海陵区及周边）任伪县长期间，推行日伪统治，强征粮税，镇压抗日活动，协助日军建立伪政权。；任伪泰县知事期间，推行保甲制度，强征粮税，协助日军清乡。；原李长江部旅长，投敌后任伪师长，驻防扬州北乡，协助日军围剿新四军。', '[]', '2026-09-10 09:57:14.033387', '2026-09-10 09:57:14.033387', '江苏', '南京', '仪征', NULL, NULL, NULL, NULL, '');
