INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e9a53ea18ef2413fb89bfe8da8c1a71d', '赵文轩', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南南阳；重庆江北；陕西咸阳秦都', '[]', '[]', '抗日战争时期', '', '为日军筹款筹粮，强制商户交纳“治安费”，协助日军统制物资。；投靠日本，在秦都镇伪警察所任职，镇压抗日民众，对秦都地区有直接影响。；河南南阳宛城人，抗战期间投敌，任伪甲长，协助日军监视民众，报告抗日活动。', '[]', '2026-09-10 09:57:14.046897', '2026-09-10 09:57:14.046897', '河南', '南阳', '宛城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e9b842273d8742b9a6f07219fde3145f', '赵侗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定定州；天津、山西、河北；河北唐山；河北保定；河北石家庄裕华；河北石家庄正定；河北石家庄辛集；河北石家庄深泽；天津河北；陕西渭南华州；云南普洱西；河北保定安国；河北保定唐县；河北保定；河北保定莲池；河北保定；河北沧州沧州渤海；青海海东民和', '[]', '[]', '抗日战争时期', '', '原抗日武装首领，一度被日军收编在河北活动，后反正抗日，但初期有投敌行为。；率伪治安军多次进剿高平、晋城抗日游击队，制造多起惨案。；原抗日武装叛变投日，在保定西部山区袭击八路军游击队。；原抗日武装首领，后叛变投日，在保定、唐县一带组建伪军，协助日军清剿抗日根据地。；投靠日军，任安国县伪县长，协助日军推行‘治安强化运动’，镇压抗日民众，征收苛捐杂税，抓捕抗日家属。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.003303', '2026-09-10 09:57:14.003303', '天津', '河北', '唐县', NULL, NULL, NULL, NULL, '');
