INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('e9e73f467de8430393caa9d119c3591a', '刘子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄；河北石家庄灵寿；山西阳泉城区；山西吕梁兴县；河北石家庄长安；河北保定阜平；河北廊坊广阳；河北廊坊安次；河南信阳固始；河南信阳；北京、山西、河北；河北石家庄井陉矿；河北石家庄井陉；河北邯郸曲周；山西朔州应县；山西大同云冈；黑龙江大庆大同；河北保定高阳；河北秦皇岛卢龙；辽宁沈阳新民；河南南阳；河北保定涞水；河南信阳平桥；河南信阳；河北保定唐县；河北保定涞源；山西大同天镇；黑龙江大庆大同；山西忻州忻府；河北石家庄平山；河南三门峡渑池；河南三门峡卢氏；黑龙江鸡西；山西朔州朔州经开区；山东临沂；山西晋城阳城；河南信阳信阳高；河北张家口蔚县；山西大同广灵；山西忻州定襄；河北石家庄鹿泉；河北邯郸峰峰矿；河北；黑龙江鸡西麻山；河北邯郸邯郸冀南；山西大同灵丘；辽宁沈阳新民；黑龙江双鸭山宝清；山西忻州河曲；北京房山；河北石家庄石家庄高；河南郑州中牟；山西长治黎城；浙江金华东阳；河北衡水衡水高；河北衡水武邑；河北张家口涿鹿；河北张家口怀来；河北邢台；河北邢台清河；河南信阳光山；河北保定满城；山西阳泉盂县；河北邢台新河；河北邢台；山东潍坊临朐；山东潍坊昌乐；山东烟台；山东威海文登；河北保定顺平；河南信阳息县；河南信阳；山西忻州代县；辽宁沈阳新民；河北保定曲阳；山东聊城东阿；河南三门峡；河南三门峡灵宝', '[\"刘锡九\", \"叛徒\", \"刘化南\", \"投敌后改名刘逆\", \"刘凤鸣\", \"叛变前为中共党员，后投敌\", \"一说刘子厚为化名，实为刘景桂\"]', '[]', '抗日战争时期', '', '原为抗日武装人员，后叛变投敌，任伪保安联队副队长，多次带队“扫荡”抗日根据地，杀害抗日干部和群众。；主持房山新民会，推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会。；任伪大同商会会长，为日军筹措军费，强迫商户捐献物资，垄断粮食贸易，从中牟利。；天镇沦陷后率先组织维持会，迎接日军，后升任伪大同省参事，协助日军推行经济掠夺政策，强征民夫。；为日军征收各种苛捐杂税，包括“亩捐”“门牌捐”等，并负责为日军筹办粮秣，曾强行征收民间粮食和牲畜，导致当地百姓生活极度困苦。；宣传奴化思想，组织“新民会”特务网，刺探抗日情报，破坏地下党组织。……（共涉及40个地区的犯罪记录）；组织伪保安队，为日军提供情报，参与“清剿”八路军游击队，残害抗日干部和家属，制造多起惨案。；日军侵占曲阳后率先组织维持会，为日军筹粮派款，提供劳役，帮助日军建立伪政权。；投靠日伪政权，任涞源县伪知事，推行保甲制度，组织维持会，强征粮食和劳役，配合日军“治安强化”运动，镇压抗日群众，破坏地下党组织。；原为抗日游击队干部，1941年被俘后变节，供出多处秘密粮库和交通站，导致多名交通员牺牲。；为日军征收各种苛捐杂税，强征粮款，导致百姓负担沉重，并贪污部分款项，间接支持日军战争机器。；原为地方武装头目，投日后率部驻守峰峰矿区，协助日军“清乡”，杀害抗日家属，掠夺煤炭资源。；日军侵占高阳后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权，并出卖当地抗日积极分子。', '[]', '2026-09-10 09:57:13.994532', '2026-09-10 09:57:13.994532', '北京', '房山', '临朐', NULL, NULL, NULL, NULL, '');
