INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ea223e463418431fb14fe5bc5a63725b', '李先良', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东淄博桓台；山西阳泉矿区；山东烟台；山东青岛；山东青岛；山东_烟台_龙口；山东临沂平邑；山西阳泉城区；山东青岛；山东临沂蒙阴；山东济南平阴；山东临沂费县；山东淄博张店；山西阳泉矿区；山东临沂；山东济南钢城；山东济南；山东德州庆云；山西阳泉城区；山东临沂兰山；山东临沂；山东临沂河东；山东临沂临沂高；山东临沂；山东泰安岱岳；山东济南莱芜；山东泰安泰山；山东泰安；山东青岛；山东潍坊昌邑；山东烟台；山东淄博；山西阳泉矿区；山东临沂莒南；山东青岛青岛高；山东青岛；山东临沂沂南；山东临沂；山东临沂沂水', '[]', '[]', '抗日战争时期', '', '任伪警察局长期间，搜捕抗日人员，维持泰安城区伪治安。；组织伪保安团，协助日军控制平阴交通线，袭击抗日游击队。；抗战期间投敌，任伪青岛市市长，为日军在山东沿海地区推行伪化统治，其管辖范围与威海同属山东沿海，间接影响文登地区。；原国民党青岛市党部委员，投敌后任伪青岛市长，控制胶济铁路东端，与潍坊地区伪政权有行政、经济联系，协助日军掠夺物资。；淄博沦陷初期参与组织地方维持会，为日军筹粮、派夫、搜集情报，协助日军控制淄博矿区及周边桓台等地。；抗战初期在淄博矿区组织维持会，为日军提供煤炭资源情报，后因内部矛盾反正，但其前期附逆行为有明确记载。；蒙阴沦陷后组织维持会，为日军筹粮筹款，维持伪秩序，压迫当地民众。；抗战期间在青岛地区与日伪合作，维持伪政权统治，其势力范围与胶东威海、乳山地区有间接关联。；在青岛及周边沿海地区包括日照岚山一带，组织伪警察力量配合日军进行海上封锁和沿海扫荡。；抗战后期在山东地区组织伪军，配合日军进攻抗日根据地，活动范围涉及泰安周边。；任伪临沂县警察局长期间，带领伪警察配合日军搜捕抗日人员，在罗庄、付庄一带设立检查站，勒索百姓，镇压抗日活动。；在临沂县城充任伪警察头目，带领伪警配合日军抓捕抗日人员，勒索百姓，维持日伪统治秩序。；在临沂城区及河东一带充任伪警察头目，搜捕抗日人员，勒索民众，为日军维持治安。；青岛沦陷初期参与组织维持会，协助日军稳定地方秩序、筹粮筹款。；抗战末期附逆，任伪职，其活动虽在青岛，但与山东伪政权体系相关。；在青岛伪政权警务系统中任职，参与日伪治安强化运动，搜捕抗日人员。；青岛沦陷初期组织维持会，协助日军接管市政，维持地方秩序，为日军侵略服务。；日军第二次侵占青岛后组织维持会，协助日军接管市政。；日军侵占青岛初期组织维持会，协助日军接管市政，维持地方秩序，后由赵琪接任。；抗战期间在青岛及胶东地区附逆，担任伪职，协助日军维持占领区统治，其势力范围与威海地区有联系，参与经济掠夺和治安强化运动。；抗战时期在山东伪政权中任职，参与日伪统治，其活动范围涉及胶济铁路沿线，对潍坊、昌邑等地物资征调和伪化统治有间接影响。；抗战时期在山东伪政权中任职，参与日伪统治，其活动范围覆盖山东东部，与烟台、海阳地区伪政权有联系。；在日军占领青岛后出任伪职，协助日军维持统治，其活动范围覆盖胶东地区，与烟台伪政权有联系。；抗战时期在山东伪政权中任职，后任伪青岛特别市市长，参与日伪统治，其活动范围覆盖山东东部，与烟台地区伪政权有联系。；抗战后期在青岛附逆，任伪青岛市市长，协助日军维持山东东部占领区统治，其影响范围覆盖胶东烟台、莱阳周边区域。；抗战期间在青岛地区附逆，担任伪职，其活动范围涉及胶东地区，与烟台、蓬莱等地伪政权有联系。；抗战期间在山东伪政权任职，活动于青岛及胶东地区，协助日军推行殖民统治。；抗战期间在山东伪政权中任职，参与日伪统治，其活动范围涉及胶东地区。；掌控伪青岛警察系统，在崂山及周边地区实施清乡，逮捕和迫害抗日群众。；在伪青岛警察系统任职，参与搜捕抗日人员、维持日伪治安，配合日军镇压青岛市区抗日力量。；在青岛伪警察系统任职，参与镇压抗日活动、搜捕抗日人员并协助日军维持市区治安。；在伪青岛政权中担任警察头目，参与镇压抗日活动，维护日伪统治秩序。；原国民党青岛市党部负责人，抗战后期在青岛与日伪妥协合作，参与伪政权维持活动。；投靠日军后任伪青岛市市长等职，参与山东伪政权运作，其影响涉及全省包括淄博地区。；沂水沦陷后组织维持会，协助日军维持地方秩序，搜捕抗日人员。；在莒南地区组织维持会，为日军征集粮食、劳工，协助日军建立伪政权，镇压当地抗日活动。；抗战后期在山东泰安、莱芜、新泰一带活动，率伪军配合日军对鲁中抗日根据地进行扫荡。；在淄博矿区协助日军控制煤矿资源，组织维持会，压迫矿工，配合日伪经济掠夺。；在青岛及胶东地区推行伪政，其辖区涵盖威海周边，协助日军征发劳工、物资。；任伪青岛市长期间，配合日军在山东沿海地区的统治，为日军提供物资和情报支持。；抗日战争后期出任伪青岛市长，为日军在山东沿海地区的统治服务，其影响波及胶东包括威海一带。；在青岛任伪市长，其伪政权与山东各地包括淄博有行政联系，协助日军掠夺物资。；抗战期间曾任伪青岛特别市市长，为日军控制青岛提供行政支持。；在青岛及山东地区任伪职，协助日军维持殖民统治，推行伪化政策。；任伪青岛市长期间，推行日伪政策，协助日军控制胶济铁路沿线，影响潍坊地区。；抗日战争时期在山东青岛地区任职伪政权，配合日军统治，其活动范围覆盖胶东地区。；抗战期间投敌，任伪青岛市长，管辖青岛及周边地区，包括烟台部分区域，推行奴化教育，为日军搜刮物资。；抗日战争后期出任伪青岛特别市市长，推行日伪统治政策，协助日军维持青岛及周边即墨等地的治安与物资征调。；抗战期间任伪青岛特别市市长，主持伪政权，推行日军殖民统治政策，镇压青岛地区抗日活动。；在临沂城内充任伪警察头目，协助日军维持城区治安，搜捕抗日人员，勒索商民。；原国民党青岛市党部委员，1943年投敌，任伪青岛市市长，其势力范围涉及潍县、安丘一带的伪化活动。；在伪沂州道公署任职，参与临沂、沂南地区伪政权建设，推行奴化教育，协助日军征发劳工、物资。；在济南周边地区组织伪军，配合日军治安强化运动。；日军侵占德州后出面组织维持会，为日军筹粮筹款、维持地方秩序，协助日军控制德州城区。；抗战期间附逆，在山东伪政权中任职，参与日伪统治，推行奴化教育，协助日军征发劳工和物资，其活动范围覆盖山东多地包括烟台地区。；抗战期间投敌，任伪青岛市市长，在山东沿海地区推行伪政，与烟台、芝罘等地伪政权有联系，协助日军经济掠夺。；任伪鲁南道尹期间，管辖临沂等地伪政权，推行保甲连坐，为日军征集物资、劳工。；费县沦陷后出面组织维持会，为日军筹粮筹款，维持伪秩序，压迫当地民众。；虽主要在青岛，但与鲁南、临沂伪政权系统有联系，协助日军推行伪化统治和经济掠夺。；在青岛及胶东地区为日军效力，组织伪警察力量配合日军扫荡，其活动与威海、荣成地区抗日斗争有间接关联。', '[]', '2026-09-10 09:57:14.012219', '2026-09-10 09:57:14.012219', '山东', '临沂', '临沂高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ea24533de9a840ee94286b75a24c221e', '于学忠部投敌军官张福禄', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东烟台莱山；山东烟台', '[]', '[]', '抗日战争时期', '', '原国民党军军官，投敌后任伪胶东招抚使，在烟台、莱山一带策反抗日武装，收编土匪。', '[]', '2026-09-10 09:57:14.017335', '2026-09-10 09:57:14.017335', '山东', '烟台', '莱山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ea2614d00aad4183a6815c9caf9f0666', '李傻子', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北保定高阳；河北保定安新；河北；河北保定清苑；河北保定雄县；河北保定保定白沟新城；内蒙古呼和浩特新城；河北保定博野', '[\"本名李振声\", \"李振声\", \"李际春\", \"李景和\"]', '[]', '抗日战争时期', '', '组织汉奸武装，配合日军清乡，杀害抗日干部和家属，抢劫民财，民愤极大。；推行奴化教育，组织汉奸情报网，向日军报告抗日活动，导致多名地下党员被捕。；利用新民会进行奴化宣传，诱骗青年参加伪军，配合日军推行“治安强化运动”，在清苑各村建立情报网。；为日军宣传奴化思想，搜集抗日情报，协助日军抓捕抗日家属。；白沟新城本地恶霸，投日后任维持会长，为日军提供抗日情报，勒索商户，多次带日军搜查白沟河两岸村庄，致使数十名群众遇害。；率伪警备队协助日军清剿，抓捕抗日干部和群众，实施“连坐”政策，制造多起惨案。；充当日军爪牙，在高阳境内设卡盘查，搜捕八路军情报员，参与制造多起惨案，如“北辛庄惨案”。', '[]', '2026-09-10 09:57:14.040692', '2026-09-10 09:57:14.040692', '河北', '保定', '保定白沟新城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ea389d8d1efb4f708d56ebe03fc6883e', '刘振群', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶；江西吉安；江西吉安安福', '[]', '[]', '抗日战争时期', '', '江西上饶人，上饶沦陷期间任伪财政科长，为日军征敛钱财、摊派捐款，压迫民众。；任伪安福县警察所所长，带领伪警察配合日军搜查抗日分子，勒索民众，维持伪政权在安福的基层统治。；江西吉安人，投敌后任伪警察局长，协助日军维持治安，抓捕抗日人士。', '[]', '2026-09-10 09:57:14.037423', '2026-09-10 09:57:14.037423', '江西', '上饶', '安福', NULL, NULL, NULL, NULL, '');
