INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ea9afc5190074784ade830f6f16726d7', '赵子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '江苏徐州鼓楼；江苏徐州；河北邢台南宫；河北_邯郸_邯山；河北邯郸邯郸经开区；河北邯郸；河北邢台清河；辽宁沈阳新民；河南南阳；河北邯郸成安；河北邢台信都；河北邯郸鸡泽；河北；河北沧州；河北沧州泊头；安徽安庆；江苏宿迁宿迁经开区；江苏宿迁；河北唐山唐山海港经开区；河北石家庄赞皇；江苏连云港东海；辽宁沈阳新民；河北邢台襄都；河北邢台；河北邯郸邱县', '[]', '[]', '抗日战争时期', '', '在滦县及沿海地区强征粮税，配合日军“扫荡”，镇压当地抗日游击队。；在交河县（今泊头部分）为日军服务，强征壮丁，参与“铁壁合围”扫荡。；在赞皇第一区（城关一带）为日军征粮派夫，告密抗日积极分子，导致多名群众被捕。；日军占领景县初期，出任维持会长，为日军筹粮派款，组织伪政权，协助日军建立统治秩序。；率伪保安队多次袭击抗日根据地，杀害抗日干部和群众，参与“治安强化运动”，搜捕地下党员。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.006526', '2026-09-10 09:57:14.006526', '安徽', '安庆', '宿迁经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eaaaf145cd0d4d398c23dde3d206afbd', '赵寄舟', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东潍坊寿光；山东潍坊昌乐', '[]', '[]', '抗日战争时期', '', '伪山东省昌潍道道尹，驻潍县，管辖潍县、昌乐、寿光等县伪政权，推行保甲制，配合日军经济掠夺。', '[]', '2026-09-10 09:57:14.016965', '2026-09-10 09:57:14.016965', '山东', '潍坊', '寿光', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eab42b1e1f2942d6a311539c79314778', '陈杰', NULL, NULL, NULL, NULL, 'exact', 'exact', '福州城内', '[]', '[]', '抗日战争时期', '', '伪职：伪警察特务；罪行：配合日军大搜捕，欺压城内百姓。；结局：1946??06??10 枪决。', '[]', '2026-09-10 09:57:14.071012', '2026-09-10 09:57:14.071012', '福建', '福州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eac009680f7d49baa7e2e52de135da71', '张星桥', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林经开区；吉林；黑龙江大庆让胡路；内蒙古呼和浩特；黑龙江齐齐哈尔；黑龙江大庆；浙江杭州滨江；黑龙江齐齐哈尔克山；黑龙江齐齐哈尔龙沙；黑龙江齐齐哈尔；黑龙江鸡西', '[]', '[]', '抗日战争时期', '', '伪满时期任齐齐哈尔市商会会长，协助日军进行经济统制与物资征集，为当地经济领域附逆者，活动于齐齐哈尔及龙沙地区。；在伪滨江省警务特务系统任职，参与侦捕抗日人员、破坏地下组织。；协助日伪推行粮谷出荷，压榨吉林农民。；任伪黑龙江省实业厅长，在齐齐哈尔推行经济统制，协助日本掠夺资源。；伪满时期任林甸县县长，林甸为今大庆市辖区，其伪政权活动覆盖大庆北部地区，协助日军征粮、维持治安。；任伪龙江省教育厅厅长，在齐齐哈尔地区推行奴化教育，篡改历史教材，协助日军进行文化侵略。；在伪龙江省警务系统任职，指挥伪警察镇压齐齐哈尔地区抗日活动，搜捕抗日人员，推行法西斯统治。；伪东安省官员，参与对鸡西地区的经济掠夺、劳工征发与殖民管理。；投敌后任伪克山县县长，在克山地区推行保甲制度，协助日军征粮征兵，镇压抗日活动。', '[]', '2026-09-10 09:57:14.000514', '2026-09-10 09:57:14.000514', '吉林', '经开区', '让胡路', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eac3d6c45dc9467b810d970275aca1b1', '熊剑东', NULL, NULL, NULL, NULL, 'exact', 'exact', '常德会战；湖北孝感；湖北襄阳南漳；湖北黄冈团风；湖北黄冈；湖北宜昌；湖北荆州；陕西渭南华州；陕西渭南；浙江新昌；荆州地区；湖北孝感；湖北黄冈；江西南昌；湖北武汉；湖北黄冈龙感湖管理；湖北黄冈；云南普洱西；湖北_咸宁_通山；湖北_黄冈_浠水；陕西西安；湖北武汉黄陂；湖北武汉；湖北宜昌西陵；湖北宜昌；江西宜春；湖北荆州洪湖；湖北荆州', '[]', '[]', '抗日战争时期', '伪军', '伪职：伪黄卫军\"指挥官\"；罪行：曾留学日本士官学校，率黄卫军\"伪军驻扎湖北监利一带，保卫日军白螺机场\"；伪职：“黄卫军”指挥官（汪伪伪军）；罪行：常德会战中，率汪精卫的“皇协军”（黄卫军）参与进攻常德；伪任职务：伪军将领，长期在江苏作战活动。结局：被军统策反，后续战死', '[]', '2026-09-10 09:57:14.037125', '2026-09-10 09:57:14.037125', '江西', '南昌', '兴国', NULL, NULL, NULL, NULL, '');
