INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eafad4778fb546608278bb0f0c180fe3', '王克敏', '叔鲁', NULL, 1873, 1945, 'unknown', 'unknown', '河北；河北廊坊；北京石景山；北京大兴；吉林长春朝阳；广西桂林资源；北京门头沟；天津河北；山东济宁；山东聊城；吉林高；山东青岛；河北张家口；河北秦皇岛；河南南阳；青海黄南河南；湖南衡阳；云南普洱西；陕西榆林；陕西_西安；河北秦皇岛；黑龙江大兴安岭加格达奇；江苏南京；北京延庆；广西玉林；重庆_合川；重庆_大足；浙江_杭州_西湖；河北承德；湖南常德津；河北石家庄石家庄高；广西_桂林_灵川；浙江杭县（今余杭）；黑龙江黑河；北京昌平；天津河北；江苏南京浦口；浙江杭州；云南_昆明_呈贡；北京_西城；四川_广元；四川成都；四川_成都_金牛；安徽_黄山；山东聊城；山东_青岛_城阳；山东青岛；山东_青岛_莱西；广西_柳州；云南普洱西；广西_桂林_永福；广西桂林；江苏南京鼓楼；江西九江；河北廊坊；河北秦皇岛；青海黄南河南；浙江舟山；湖北黄冈；湖南_怀化_怀化洪江管理；湖南株洲；山西太原示范；湖南_衡阳_衡阳高；湖南_郴州；湖南长沙；贵州_贵阳_息烽；重庆万州；甘肃甘南合作；重庆沙坪坝；陕西渭南；吉林高；浙江杭州；北京丰台；北京、天津、河北；北京_东城；江苏南京；天津河北；河北秦皇岛；青海黄南河南；浙江宁波；江苏南京江宁；云南普洱西；河北唐山路北', '[]', '[]', '抗日战争时期', '华北伪临时政府 / 汪伪政权；华北伪临时政府', '王克敏，字叔鲁，浙江杭县人，举人出身。清末留日。民国时期历任中国银行总裁、财政总长、北平政务委员会委员等职。1937年12月在日本扶植下于北平成立「中华民国临时政府」，任行政委员会委员长。1940年并入汪伪政权后，任「华北政务委员会」委员长。1945年8月日本投降后被捕，12月25日在北平狱中畏罪服毒自杀，年72岁。；1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，积极推行日本殖民统治，镇压抗日活动。；原北洋政客，投日后主持伪华北政权，管辖北平及丰台，组织伪军和警察协助日军。；在北平建立伪政权，推行奴化政策，为日军搜刮物资，配合“治安强化运动”。；伪华北最高傀儡头目，在北平设立伪政权，统辖大兴等县，推行“新民会”奴化宣传，配合日军“三光”政策。；原北洋财政官僚，投日后任伪华北政务委员会委员长，在北平及延庆地区全面推行日伪统治，组织“新民会”进行奴化宣传。……（共涉及32个地区的犯罪记录）；伪任职务：伪华北政务委员会委员长，掌控整个华北伪政权，常驻北平（河北境内）。结局：1945 年被捕，狱中服毒自杀光明数字报；华北伪政权首脑，其统治覆盖廊坊全境，推动“新民会”在基层建立汉奸组织。', '[]', '2026-09-10 09:57:13.981529', '2026-09-10 09:57:13.981529', '浙江', '杭州', '浦口', NULL, NULL, NULL, NULL, '');
