INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb64ae8d1d7446a6a21171cf82830b1c', '马廷福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北秦皇岛山海关；河北秦皇岛；河北秦皇岛北戴河；河北秦皇岛', '[]', '[]', '抗日战争时期', '', '在秦皇岛、山海关地区指挥伪保安队，协助日军清乡，抓捕抗日群众，抢掠财物。；在秦皇岛、山海关一带率伪军扫荡抗日游击队，烧杀抢掠', '[]', '2026-09-10 09:57:14.044068', '2026-09-10 09:57:14.044068', '河北', '秦皇岛', '北戴河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb6ec524b8eb474086f0236cb9ce9182', '陈日初', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁良庆；云南普洱西；广西南宁；广西南宁西乡塘；广西南宁；广西南宁马山；广西崇左；广西崇左江州；广西桂林；广西南宁兴宁；广东梅州兴宁；广西南宁武鸣；广西南宁', '[]', '[]', '抗日战争时期', '', '1944年日军侵入马山地区后，出面组织维持会，为日军征粮征夫，协助日军对马山周边乡村进行扫荡。；日军侵占崇善（今崇左市江州区）期间，组织伪维持会，为日军征调民夫、粮食，协助推行伪化统治。；桂林沦陷期间出任伪警察局长，协助日军维持治安，搜捕抗日人员，镇压民众反抗。；日军侵占广西部分地区期间，出面组织伪广西省维持会并任会长，为日军在广西的殖民统治服务，协助征发物资、宣传“东亚共荣”。；日军占领南宁期间，出任伪南宁警察局局长，协助日军搜捕抗日人士、维持占领区治安。；在兴宁地区组织伪维持会，协助日军控制地方，迫害抗日群众。；在日军占领南宁期间，以商会名义为日军筹款筹粮，协助日军对南宁工商业进行控制。；在南宁为日军筹款筹物，组织商户向日军供应物资，属经济领域附逆者。', '[]', '2026-09-10 09:57:14.031087', '2026-09-10 09:57:14.031087', '广西', '南宁', '兴宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb731fec97764bda89371eb0b4746e99', '张海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '[]', '[]', '抗日战争时期', '', '投靠日军，任景县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。；投靠日军，任阜城县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众，抓捕抗日家属。', '[]', '2026-09-10 09:57:14.077221', '2026-09-10 09:57:14.077221', '河北', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb781ba4e29a43b8b7efbd9d37deb63c', '刘景文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁；辽宁鞍山岫岩；辽宁丹东宽甸；黑龙江齐齐哈尔甘南', '[]', '[]', '抗日战争时期', '', '已列，补充其曾亲自拷打抗联女战士。；继任伪宽甸县长，推行“归屯并户”，制造无人区，配合日军围剿杨靖宇领导的抗联部队。；原岫岩警察，投日后任伪警务科长，组织伪警察队，多次参与对抗日武装的“讨伐”，杀害多名抗联侦察员。', '[]', '2026-09-10 09:57:14.062863', '2026-09-10 09:57:14.062863', '辽宁', '丹东', '宽甸', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb85c839b2184649bea6cb8335506486', '李凤藻', NULL, NULL, NULL, NULL, 'exact', 'exact', '宁夏吴忠', '[]', '[]', '抗日战争时期', '', '在日军进犯绥西、威胁宁夏期间，于吴忠堡组织维持会，准备迎接日军，协助日伪征收粮草、拉夫，后因日军未占领宁夏而解散。', '[]', '2026-09-10 09:57:14.003746', '2026-09-10 09:57:14.003746', '宁夏', '吴忠', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb882fd53fe3490497572d3008b85ea1', '杨文清', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明嵩明；云南昆明五华；云南昆明', '[]', '[]', '抗日战争时期', '', '在教育领域附逆，推行奴化教育，篡改教材，向学生灌输亲日思想，协助日伪控制昆明及周边学校。；组织伪保安大队配合日军扫荡嵩明及周边地区，镇压抗日游击队，残害抗日群众。', '[]', '2026-09-10 09:57:13.980900', '2026-09-10 09:57:13.980900', '云南', '昆明', '五华', NULL, NULL, NULL, NULL, '');
