INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb9671e868684e7281bc2c6c85b63e94', '梁国基', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西梧州苍梧；广西梧州；广西梧州；广西南宁兴宁；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '日军占领梧州后，以商会名义为日军筹集物资，协助推行伪币。；协助张君嵩办理维持会事务，为日军征发民夫、物资。；在日军控制下的南宁等地开展亲日宣传，鼓吹“大东亚共荣圈”，为日军侵略辩护。', '[]', '2026-09-10 09:57:14.031125', '2026-09-10 09:57:14.031125', '广西', '南宁', '兴宁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eb9ed1dc16ef4611988154885865ecd5', '王德林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山东威海威海经开区；山东威海；山东威海；江苏连云港海州；江苏连云港；黑龙江黑河北安；河南焦作解放；河南焦作；河北廊坊；河北廊坊固安；河南驻马店驻马店经开区；河南驻马店；山东青岛胶州；安徽铜陵；河南南阳；山东青岛崂山；黑龙江鸡西；黑龙江齐齐哈尔甘南；安徽滁州来安；山东临沂；黑龙江双鸭山尖山；广西桂林资源；江苏镇江扬中；黑龙江鸡西麻山；河南濮阳；山东临沂河东；黑龙江双鸭山宝清；黑龙江双鸭山饶河；河南新乡获嘉；黑龙江鸡西滴道；江苏_连云港_连云港高', '[\"投敌后\"]', '[]', '抗日战争时期', '', '在固安建立伪警察所和情报网，破坏中共固安县委地下活动，协助日军抓捕抗日干部。', '[]', '2026-09-10 09:57:14.009310', '2026-09-10 09:57:14.009310', '安徽', '滁州', '来安', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebbc567741eb43ecacfc8675512f5653', '招桂章', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东南海', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪广州要港司令，汪伪海军华南最高长官，掌控珠江水上武装。结局：日本投降被国民党收编，后因汉奸罪逮捕判刑', '[]', '2026-09-10 09:57:14.087008', '2026-09-10 09:57:14.087008', '广东', '佛山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebbce58882714e1d86bf6db8ab8eb1a8', '凌印清', NULL, NULL, NULL, NULL, 'exact', 'exact', '海城（现鞍山海城）；辽宁海城', '[]', '[]', '抗日战争时期', '伪军', '伪职：九一八后伪 “东北民众自卫军” 总司令；罪行：九一八事变被日军重金收买，招降土匪，策反义勇军，在辽海一带为日军卖命，是辽南最早一批汉奸。；结局：1931 年被抗日义勇军活捉，沙岭镇公审枪决中国·鞍山。；伪职：伪 “东北民众自卫军” 总司令，司令部驻盘山沙岭镇；罪行：九一八被日军重金收买，在沙岭设立伪军总司令部；招降土匪地痞，策反义勇军，企图进攻锦州，充当日军侵辽西先锋，劫掠辽西村镇抖音百科。；结局：1931??11??03 被张海天、项青山义勇军生擒，沙岭公审枪决党史学习教...。；伪任职务：九一八后伪东北民众自卫军总司令，辽西伪军头目，进攻锦州方向抗日武装。结局：1931 年被义勇军擒获就地枪决', '[]', '2026-09-10 09:57:14.067318', '2026-09-10 09:57:14.067318', '辽宁', '鞍山', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebbf1561dd9e4ab5af83013a118b426c', '戚仲侠', NULL, NULL, NULL, NULL, 'exact', 'exact', '宿迁县城', '[]', '[]', '抗日战争时期', '', '伪职：伪宿迁宪兵情报队首任队长；罪行：日军占领初期最早一批汉奸，组建情报队，网罗地痞搜集根据地情报，告密地下抗日人员，制造多起抓捕惨案中共宿迁市...。；结局：抗战胜利后逮捕法办。', '[]', '2026-09-10 09:57:14.071203', '2026-09-10 09:57:14.071203', '江苏', '宿迁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebc4fd74bb6c4f1eb4f7f12e05e9daac', '穆克登宝', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古_乌兰察布_察哈尔右翼中旗；内蒙古乌兰察布察哈尔右翼前旗；重庆沙坪坝；内蒙古呼和浩特托克托；河北_张家口_张家口察北管理；内蒙古、河北；内蒙古锡林郭勒苏尼特左旗；河北张家口沽源；河北张家口张北；内蒙古乌兰察布；内蒙古锡林郭勒多伦；内蒙古包头青山', '[]', '[]', '抗日战争时期', '', '伪蒙古军高级军官，活动于绥远东部（含兴和、商都、化德一带），配合日军进攻大青山抗日游击队，参与“清乡”屠杀。；在乌兰察布地区活动，参与围剿抗日武装，为日军提供情报。；直接管理察哈尔右翼前旗日伪政权，向日军提供当地抗日活动情报，强征壮丁和牲畜，实施保甲连坐制度，镇压反抗民众。；在绥远地区率伪军参与对抗日根据地的围剿，曾在托克托县境内烧杀抢掠，破坏地下抗日组织。；原察哈尔部总管，投日后任伪察哈尔盟盟长，管辖苏尼特左旗等地区，推行日伪保甲制度，搜刮民财。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.986651', '2026-09-10 09:57:13.986651', '内蒙古', '乌兰察布', '察哈尔右翼前旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebd6d12cde844d45b160e1d57bc50c45', '张耀枢', NULL, NULL, NULL, NULL, 'exact', 'exact', '合肥城区及四乡', '[]', '[]', '抗日战争时期', '', '伪职：继任汪伪合肥县县长；罪行：接替方星樵执掌伪县公署，扩充伪自卫团，配合日军对城郊、店埠、上派河扫荡，破坏地下抗日组织。；结局：汉奸审判判处重刑。', '[]', '2026-09-10 09:57:14.069072', '2026-09-10 09:57:14.069072', '安徽', '合肥', NULL, NULL, NULL, NULL, NULL, '');
