INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebe16c32d66f40bea96ce8c5d26d42ae', '胡毓成', NULL, NULL, NULL, NULL, 'exact', 'exact', '湘赣边区（活动于新余、分宜一带）；湖南邵阳', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：附日汉奸；罪行：经营杂货铺，引导日军下乡搜掠粮食，协助日军祸害百姓，抗战胜利后被处决；来源：民国肃奸档案、赣西抗战史料；备注：浙赣战役期间在赣西活动，是新余周边记载较明确汉奸；伪任职务：邵阳伪维持会骨干，被日军称为 “汉奸楷模”，助纣为虐祸害邵阳百姓。结局：抗战胜利公审枪决', '[]', '2026-09-10 09:57:14.067820', '2026-09-10 09:57:14.067820', '湖南', '邵阳', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebf71b8dacd84bccab224732a20f012c', '李仰之', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西运城新绛；山西运城；河南三门峡义马；河南三门峡渑池；河南三门峡陕州；河南_三门峡；河南三门峡湖滨；河南三门峡灵宝；河南三门峡渑池；河南三门峡', '[]', '[]', '抗日战争时期', '', '组建伪警察队伍，协助日军搜捕抗日人员，镇压地方反抗。；任伪陕县县知事期间，推行日伪政令，配合日军清乡、征粮，迫害抗日人员及家属。；在日军占领陕县期间出任伪县长，主持伪县政，配合日军推行保甲、征发物资。；渑池沦陷后投敌，组织伪维持会，配合日军扫荡，迫害抗日人员家属。；在日军扶植下出任伪灵宝县知事，推行伪政令，配合日军对灵宝地区的统治与搜刮。；日军占领陕州（今三门峡陕州区）后，组织伪维持会，为日军筹集物资、拉拢地方士绅附逆。；为日军统制运城物资，强迫商户缴纳“慰劳金”，低价收购粮食棉花供日军军用，从中牟利。', '[]', '2026-09-10 09:57:14.023787', '2026-09-10 09:57:14.023787', '山西', '运城', '新绛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebf81134c10b4a519174576796e56f67', '陈老歪', NULL, NULL, NULL, NULL, 'exact', 'exact', '濉溪??相山一带城乡', '[]', '[]', '抗日战争时期', '', '伪职：濉溪宪兵队便衣；罪行：地痞投靠日军宪兵队，混迹集镇乡村，侦查地下抗日活动，告密抓捕进步群众，敲诈商户。；结局：抗战后期被武工队锄奸击毙。', '[]', '2026-09-10 09:57:14.074140', '2026-09-10 09:57:14.074140', '安徽', '淮北', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ebff7ad8479e453e9e529d63722b39b4', '谢厚香', NULL, NULL, NULL, NULL, 'exact', 'exact', '荆门', '[]', '[]', '抗日战争时期', '', '伪职：土匪汉奸；罪行：荆南土匪，经常聚众在五里铺赵家集一带杀人放火、拦路抢劫、强奸妇女，根据地人民深受其害', '[]', '2026-09-10 09:57:14.078984', '2026-09-10 09:57:14.078984', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec06c493a8c54966a7d1f279f72fd93b', '王梦龄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西忻州；山西忻州河曲；海南五指山；江西赣州石城；江西赣州；江西九江共青城；云南普洱西；江西九江湖口；江西南昌红谷滩；江西南昌；江西吉安万安；江西吉安；江西吉安安福；江西吉安；辽宁沈阳大东；江西赣州大余；江西南昌进贤；江西九江柴桑；江西九江；山西；江西宜春靖安；江西赣州章贡；江西南昌；江西九江彭泽；江西九江；江西南昌；山西忻州保德；江西萍乡上栗；山西阳泉矿区；大同', '[]', '[]', '抗日战争时期', '', '在河曲县率伪军袭击黄河渡口，阻断抗日物资运输，杀害游击队员。；投靠日军后出任伪保德县知事，协助日军建立维持会，强征民夫修筑碉堡，并配合日军扫荡抗日根据地。；伪职：伪大同县警务科长；罪行：指挥便衣特务，在大同城内外抓捕爱国志士，刑讯迫害被捕群众，发展大批乡村密探。；结局：解放后镇反枪决', '[]', '2026-09-10 09:57:14.021653', '2026-09-10 09:57:14.021653', '山西', '忻州', '保德', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec0c779d937246b1b4b6890a9f3a3a0d', '李雨春', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽滁州凤阳', '[]', '[]', '抗日战争时期', '', '汪伪政权委任的凤阳县县长，在凤阳推行保甲制、征粮征丁，配合日军对凤阳山区抗日根据地进行封锁与扫荡。', '[]', '2026-09-10 09:57:14.009159', '2026-09-10 09:57:14.009159', '安徽', '滁州', '凤阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec17c3b9098541179bd4accd946a39de', '高子厚', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东东营东营经开区；山东滨州；山东滨州博兴；河南周口；河南周口商水；河南漯河召陵；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '在信阳城区搜捕抗日分子，推行保甲连坐，配合日军维持殖民统治。；商水沦陷后投敌，参与组建伪商水县政权，为日军征粮征夫，协助日军在商水、周口之间建立封锁线。；在蒲台县及今东营经开区周边率伪军活动，配合日军清乡、扫荡，迫害抗日群众。；在博兴县组织伪政权，任伪县长期间协助日军扫荡博兴、广饶一带，强征民夫修筑据点。；在郾城沦陷期间任伪教育科科长，推行日军奴化教育，篡改教材，宣传“大东亚共荣”，属教育文化领域附逆者，活动范围覆盖漯河、召陵。', '[]', '2026-09-10 09:57:14.011932', '2026-09-10 09:57:14.011932', '山东', '东营', '东营经开区', NULL, NULL, NULL, NULL, '');
