INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec32e638c65e46fc8c0ea1bddeff2e70', '正珠尔扎布', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古；内蒙古赤峰阿鲁科尔沁旗；蒙古族；吉林白城通榆；内蒙古赤峰林西；内蒙古呼伦贝尔扎兰屯；内蒙古呼伦贝尔；内蒙古赤峰红山；内蒙古乌海乌达；内蒙古通辽开鲁；内蒙古通辽；内蒙古兴安阿尔山；黑龙江鹤岗兴安；内蒙古呼伦贝尔海拉尔；内蒙古呼伦贝尔；内蒙古赤峰；内蒙古通辽；内蒙古锡林郭勒锡林浩特；内蒙古通辽奈曼旗；内蒙古通辽科尔沁左翼中旗；内蒙古呼伦贝尔牙克石；内蒙古呼伦贝尔；内蒙古通辽科尔沁左翼中旗；内蒙古通辽科尔沁左翼后旗；黑龙江大兴安岭松岭；内蒙古兴安阿尔山；内蒙古兴安乌兰浩特；内蒙古赤峰巴林右旗；内蒙古乌海乌达；内蒙古呼伦贝尔新巴尔虎右旗；内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '伪职：伪第十军管区少将参谋长（驻海拉尔）；日本士官学校出身，主持伪兴安军参谋业务，训练伪骑兵，参与边境 “治安肃正”，镇压边境各族反抗。；结局：1950 引渡回国，1960 特赦，安置海拉尔，1967 年去世抖音百科；在乌兰浩特地区协助日军进行“特别治安”行动，逮捕并杀害抗联地下工作者。；甘珠尔扎布之弟，任伪兴安军要职，在兴安盟地区协助日军进行军事行动，镇压当地抗日活动。；蒙古族贵族出身，投靠日本后任伪兴安军军官，参与围剿东北抗日联军在呼伦贝尔的游击活动。；在呼伦贝尔地区统领伪兴安军，配合日军进攻苏联边境及抗日武装；甘珠尔扎布之弟，积极推行日满蒙一体化政策，协助日军在通辽地区实施殖民统治。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.987561', '2026-09-10 09:57:13.987561', '内蒙古', '兴安', '阿尔山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec37a619b6654f808583f1b267751dde', '吴发仔', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东深圳盐田；广东深圳；广东深圳；广东广州海珠；广东广州；广东云浮郁南；辽宁大连中山；广东珠海金湾；广东珠海；广东深圳罗湖；广东深圳；广东广州黄埔；黑龙江佳木斯郊区；广东珠海；广东珠海香洲；广东珠海', '[]', '[]', '抗日战争时期', '', '在珠海乡村充任伪保甲长，为日军征粮拉夫，监视村民，举报抗日活动。；在珠海金湾一带充当日伪基层爪牙，负责摊派捐税、监视村民、协助日军抓捕抗日人员，属当地有记载的附逆者。；在广州郊区组织伪自卫队，协助日军控制乡村，镇压抗日群众。；率领伪保安队在珠海沿海地区巡逻，拦截抗日物资，配合日军登陆作战并迫害渔民。；深圳墟沦陷后任伪维持会会长，协助日军在深圳、罗湖地区维持秩序、征收物资、登记户口。；在广州周边及珠三角地区活动，参与伪军武装，协助日军维持占领区秩序。；日军占领宝安（含深圳地区）后出任维持会会长，后任伪县长，为日军征粮拉夫、搜集情报。；在中山地区组织伪军，配合日军进攻抗日根据地。；在深圳、盐田一带为日军搜集情报，带领伪军搜捕抗日人员，协助日军征粮征工。', '[]', '2026-09-10 09:57:14.025735', '2026-09-10 09:57:14.025735', '广东', '云浮', '郁南', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ec38e9e44f704aa59001e5b7d17143a7', '姚天福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西运城临猗；辽宁沈阳新民', '[]', '[]', '抗日战争时期', '', '利用新民会宣传‘中日亲善’，强迫青年参加伪军训练，并密报抗日活动，导致多名地下党员被捕。', '[]', '2026-09-10 09:57:14.023678', '2026-09-10 09:57:14.023678', '山西', '运城', '临猗', NULL, NULL, NULL, NULL, '');
