INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ecb1b0405bb04212be770faa0022d6fb', '吴兆祥', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北黄冈黄梅', '[]', '[]', '抗日战争时期', '', '湖北黄梅人，伪黄梅县商会会长，协助日军征购粮食、棉花，压榨商户，为日军经济侵略服务。', '[]', '2026-09-10 09:57:14.057436', '2026-09-10 09:57:14.057436', '湖北', '黄冈', '黄梅', NULL, NULL, NULL, NULL, '');
