INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ecc7c9d290614229bf39ae3cf1737a7a', '刘达三', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州上犹；江西赣州全南；江西赣州兴国；江西赣州信丰；江西吉安；江西赣州章贡；江西赣州；江西赣州大余；江西赣州赣县；江西_九江_彭泽；江西赣州石城', '[]', '[]', '抗日战争时期', '', '1945年日军窜扰赣县时，出面组织维持会，替日军筹粮、派夫，并协助张贴安民布告、劝诱民众归顺。；日军侵扰赣南时，在上犹县组织伪维持会，为日军带路、征粮、派夫，协助日军镇压当地抗日活动。；协助日军统制物资，强制商户交纳“献金”，为日军采购军需。；日军侵扰赣南期间，在石城组织伪维持会，为日军筹粮、带路，并协助建立伪保甲体系。；兴国县地方人物，在日军侵扰赣南期间组织伪维持会，协助日军征粮、拉夫，后随日军撤退而瓦解。；抗战后期在信丰地区组织伪维持会，为日军征集物资、维持地方秩序，属地方附逆人员。；在赣州沦陷期间依附日军，以商会名义为日军筹款筹粮，动员商户悬挂日伪旗帜，协助日伪推行经济统制，压迫爱国商人。；组建伪警察队伍，配合日军搜捕抗日人员、管制居民。；全南本地汉奸，日军侵扰赣南时组织维持会，胁迫民众服从日军统治，提供情报。', '[]', '2026-09-10 09:57:14.038952', '2026-09-10 09:57:14.038952', '江西', '吉安', '上犹', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ecc90f3415404f36827bf4917f8531bc', '王蕴璞', NULL, NULL, NULL, NULL, 'exact', 'exact', '肇源（三肇惨案）', '[]', '[]', '抗日战争时期', '', '伪职：伪哈尔滨警察厅警尉，特搜班骨干；罪行：随叶永年进驻肇源，主持刑讯，抓捕迫害大量三肇爱国群众，制造多起酷刑冤案。；结局：1951 年镇压反革命被处决。', '[]', '2026-09-10 09:57:14.077323', '2026-09-10 09:57:14.077323', '黑龙江', '大庆', NULL, NULL, NULL, NULL, NULL, '');
