INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed1cf1862eb04587a5e58a40083faeb9', '李择一', NULL, NULL, NULL, NULL, 'exact', 'exact', '福建厦门集美；福建厦门；广西桂林资源；福建宁德福安；福建福州；福建_莆田_城厢；福建厦门；福建厦门思明；福建厦门', '[]', '[]', '抗日战争时期', '', '在厦门及闽南地区为日军筹组伪政权，推行奴化教育，配合日军经济掠夺，影响波及泉州。；福建籍汉奸，抗战期间投靠日军，历任伪厦门特别市市长等职，协助日军在福建沿海推行伪化统治，其活动范围覆盖泉州、惠安等闽南地区。；福建伪政权核心人物，参与筹建伪厦门特别市政府，协助日军在闽南包括泉州、金门周边地区推行保甲连坐与物资统制。；在福建及厦门活动，组织亲日团体，为日军提供情报与地方协助。；在福建伪政权中任职，活动涉及厦门，协助日伪统治。；福州两次沦陷期间参与伪维持会，为日军筹款筹粮，协助推行伪化政策。；控制厦门社会团体和舆论，协助日军进行宣传和思想控制。；掌管伪厦门社会事务，协助日军控制民众团体、推行保甲与物资配给。；福建厦门人，抗战期间投靠日军，出任伪厦门市长，协助日军在闽南地区推行殖民统治，其活动范围覆盖泉州沿海。；福建沦陷区重要伪政权头目，主持厦门伪政，与泉州、漳州一带日伪机构联系密切。；在厦门沦陷区任伪职，配合日军维持治安、征敛物资。；福建厦门人，日军占领厦门后出面组织维持会，后任伪厦门特别市市长，推行伪化统治，配合日军向泉州、晋江沿海渗透，征粮拉夫，镇压抗日分子。；福建人，汪伪政权时期任伪福建省府要职，协助日军在福建沦陷区推行伪化统治，参与征粮、征税及维持会体系的建立。；协助日军在福建沦陷区掠夺经济资源，发行伪币。', '[]', '2026-09-10 09:57:14.060848', '2026-09-10 09:57:14.060848', '福建', '厦门', '思明', NULL, NULL, NULL, NULL, '');
