INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed73d385a4de47b78b0e0e346d6e142c', '张子清', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南新乡辉县；江西鹰潭；吉林白山；吉林白山长白；河南新乡卫辉；河南新乡；江西上饶弋阳；江西南昌；湖南长沙宁乡；湖南长沙；内蒙古锡林郭勒多伦；河南新乡获嘉；河南焦作沁阳；山西阳泉矿区', '[]', '[]', '抗日战争时期', '', '在焦作矿区组织维持会，为日军掠夺煤炭资源服务，强征矿工，迫害抗日矿工家属。；新乡沦陷初期组织维持会，为日军筹粮、派款、维持地方伪秩序。；多伦沦陷初期组织维持会，为日军筹集粮草、物资，协助日军建立伪政权。；获嘉沦陷后，出面组织维持会，为日军提供物资和情报。；长沙本地士绅，日军占领长沙后出面组织维持会，协助日军管理地方、征发物资，与宁乡地区伪政权有联络。；在南昌地区推行日伪政令，配合日军清乡，镇压抗日活动，其势力范围涉及赣东北部分区域。；辉县沦陷后组织维持会，为日军带路扫荡山区抗日根据地，强征民夫修筑公路和炮楼，迫害抗日家属。；充任伪警察头目，配合日军搜捕抗日人员，勒索当地商户与居民。；在长白县任伪职，协助日军控制中朝边境，封锁抗日联军补给线，镇压当地抗日活动。', '[]', '2026-09-10 09:57:13.992443', '2026-09-10 09:57:13.992443', '内蒙古', '锡林郭勒', '多伦', NULL, NULL, NULL, NULL, '');
