INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed78a464c3a04abf98936a394441e0f8', '李耀南', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳耒阳', '[]', '[]', '抗日战争时期', '', '率地方武装投靠日军，编为伪保安团，配合日军扫荡耒阳周边抗日武装，镇压民众反抗。', '[]', '2026-09-10 09:57:14.059540', '2026-09-10 09:57:14.059540', '湖南', '衡阳', '耒阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed79f6dcf73043479d9c55fc5a9b3bad', '张作和', NULL, NULL, NULL, NULL, 'exact', 'exact', '潢川县', '[]', '[]', '抗日战争时期', '', '伪职：日伪情报员→伪乡长；罪行：1941年春至1942年秋季在本村干日伪情报员，每日向日伪报告抗日武装在该地的活动情况。1941年秋季向日军报告侦查连副连长张明堂在该村开展抗日工作。1941年任伪乡长时，日军包围辛寺庄逼问谁是八路军，张作和指认“小穷与八路军有联系”；结局：解放后隐藏历史，后因“信阳事件”被揭发，1962年被清除出党', '[]', '2026-09-10 09:57:14.077068', '2026-09-10 09:57:14.077068', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed7ceda046fc48f9a854e402ff59c114', '吴化文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；安徽六安金寨；安徽六安；安徽宿州；山东_枣庄_峄城；山东_泰安_肥城；山东淄博；山东聊城；辽宁沈阳和平；江苏扬州邗江；江苏扬州；云南_昆明_呈贡；安徽六安；安徽安庆；安徽_宣城_郎溪；安徽阜阳；安徽黄山；江苏_南京_六合；江苏宿迁；江苏徐州；青海黄南河南；湖北_咸宁_通山；湖南_怀化_怀化洪江管理；云南普洱西；陕西_西安_灞桥；江苏连云港；江苏徐州；江苏扬州宝应；江苏南京；江苏盐城；安徽芜湖；安徽阜阳；陕西宝鸡凤县；青海黄南河南；安徽_六安；云南普洱西；山东掖县（今莱州）；山东临沂；安徽亳州；安徽六安；安徽宿州；云南普洱西；安徽阜阳；安徽_阜阳_颍泉；山东济宁；辽宁沈阳和平；河南南阳；河南濮阳；青海黄南河南；河南驻马店；湖南_娄底_新化；湖南_怀化_溆浦；陕西渭南；河北；浙江_宁波_象山；河北廊坊；安徽亳州；江苏南京浦口；山东临沂蒙阴；安徽_亳州；安徽_宣城；安徽_宣城_宁国；安徽_宣城_宣城经开区；安徽宿州；安徽_宿州_埇桥；安徽_宿州_宿州马鞍山现代产业园；安徽_宿州_泗县；安徽池州；安徽滁州；安徽_滁州_天长；安徽阜阳；辽宁沈阳和平；安徽马鞍山；安徽_黄山_屯溪；山东临沂；山东_德州_平原；山东枣庄；山东泰安；山东济南莱芜；山东济南；山东_济宁_嘉祥；山东淄博；山东聊城；山东菏泽；山东青岛；广西玉林；江苏_南京_雨花台；江苏_泰州_泰州医药高；青海黄南河南；河南平顶山；河南洛阳；河南漯河；湖南衡阳；云南普洱西；江苏南京浦口；江苏南京；四川_广元；安徽_芜湖_镜湖；江苏徐州新沂；河北邢台；安徽_宣城_广德', '[]', '[]', '抗日战争时期', '', '其一部曾调至廊坊东部，参与对冀东根据地的“扫荡”。；伪职：伪和平救国军第三方面军上将总司令；罪行：1943年1月公开投日，率部配合日军扫荡鲁中抗日根据地，在临朐一带制造无人区；来源：凤凰网历史等史料综述；备注：掖县人（今属烟台）；1948年9月济南战役阵前起义，任解放军第35军军长，1962年病逝；虽主要活动于山东，但其一部曾调至廊坊地区支援日军扫荡，烧毁村庄。；所部在邢台地区参与“铁壁合围”，制造无人区。', '[]', '2026-09-10 09:57:13.984294', '2026-09-10 09:57:13.984294', '山东', '临沂', '蒙阴', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed8e2cb2db1d4024b98e2b20395270fc', '杨云甫', NULL, NULL, NULL, NULL, 'exact', 'exact', '津市（今属常德）', '[]', '[]', '抗日战争时期', '', '伪职：津市维持会会长；罪行：日伪统治时期成立“津市维持会”，杨云甫任会长', '[]', '2026-09-10 09:57:14.083143', '2026-09-10 09:57:14.083143', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ed99ae57502e4372aaac17b3a58f5f35', '伪大余县维持会头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西九江共青城；江西赣州大余', '[]', '[]', '抗日战争时期', '', '大余沦陷后伪维持会协助日军控制赣粤边界。', '[]', '2026-09-10 09:57:14.038715', '2026-09-10 09:57:14.038715', '江西', '九江', '共青城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edae01c6f94b427999032f305e8364a3', '周玉山', NULL, NULL, NULL, NULL, 'exact', 'exact', '辽宁沈阳和平；江苏宿迁；辽宁沈阳新民；江苏淮安盱眙；江苏淮安；江苏淮安洪泽；江苏徐州鼓楼；江苏南京鼓楼；安徽淮南大通', '[]', '[]', '抗日战争时期', '', '在洪泽湖西岸推行伪化统治，设立税卡盘剥渔民，向日军报告新四军活动情报，组织伪自卫团配合日军“扫荡”。；任伪淮阴绥靖军团长，驻防淮安、盱眙一带，配合日军“蚕食”抗日根据地，抢掠物资，强拉民夫。；率保安队协助日军护矿，多次围剿新四军游击队，在洛河、上窑一带烧杀抢掠，杀害抗日军民数十人。；任伪鼓楼区区长期间，负责该区治安和物资配给，强征民夫修筑工事，并协助日军清查抗日嫌疑人员。；主持新民会宿迁分会，开展“反共”宣传，组织“青少年团”和“妇女会”，诱骗民众参加日伪活动，刺探抗日情报。；为日军征收各种苛捐杂税，强征“和平捐”“慰劳金”，中饱私囊，逼得许多农户破产，并举报抗税群众。', '[]', '2026-09-10 09:57:14.008888', '2026-09-10 09:57:14.008888', '安徽', '淮南', '大通', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edbe1fe0fc3e4cd5a2f9c8479c44216f', '国长有', NULL, NULL, NULL, NULL, 'exact', 'exact', '庆安、绥棱安邦河林区', '[]', '[]', '抗日战争时期', '', '伪职：伪森林警察、伪挺进队队长；罪行：土匪出身投降日军，熟悉山林，带领挺进队进山扫荡；1942 年偷袭抗联三路军总指挥部，造成抗联总参谋长许亨植牺牲，疯狂捕杀抗联小部队人员绥化新闻网。；结局：解放后镇压反革命被处决。', '[]', '2026-09-10 09:57:14.083732', '2026-09-10 09:57:14.083732', '黑龙江', '绥化', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edbe713062fb420c8645494c16a8a203', '陆定一', NULL, NULL, NULL, NULL, 'exact', 'exact', '泰兴县城', '[]', '[]', '抗日战争时期', '', '伪职：伪泰兴县自治会会长、伪县长；罪行：泰兴沦陷初期组建伪自治会，迎接日军，建立伪基层体系，摊派苛捐杂税，拉拢地方士绅附逆。；结局：抗战胜利后清算惩处。', '[]', '2026-09-10 09:57:14.083568', '2026-09-10 09:57:14.083568', '江苏', '泰州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edca3ade5f0f4ec088b65e48fc3dcc82', '德古来', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古；黑龙江大兴安岭加格达奇；北京大兴；内蒙古呼伦贝尔莫力达瓦；达斡尔族；内蒙古呼伦贝尔海拉尔', '[]', '[]', '抗日战争时期', '', '管理伪市公署日常事务，配合日军经济掠夺，强制收缴民间金属和粮食，供日军军需。；在莫力达瓦旗组织伪警察，协助日军清乡，逮捕并杀害抗日地下工作者。；伪职：伪兴安东省公署总务厅长；核心傀儡官员，实际执行日本参事官指令，招降纳叛，控制布特哈各旗。；结局：日本投降潜逃，后抓捕归案劳改', '[]', '2026-09-10 09:57:13.989027', '2026-09-10 09:57:13.989027', '内蒙古', '呼伦贝尔', '海拉尔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edd0116b3f4b4dabb85d5aea7d7924a4', '陈宗莹', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安永丰；江西赣州会昌；江西吉安；江西景德镇乐平；江西景德镇', '[]', '[]', '抗日战争时期', '', '汪伪政权在江西地区的重要附逆者，参与伪江西省政，其伪政权体系延伸影响吉安一带，协助日军推行治安强化与物资统制。；在南昌及江西各地协助日军推行伪化统治，参与组织地方伪政权，其活动影响波及景德镇、乐平地区。；在永丰地区组织维持会，为日军提供情报、粮秣，协助日伪控制永丰一带。；在会昌地区协助日军建立伪政权，征派民夫、粮食，迫害抗日群众。', '[]', '2026-09-10 09:57:14.039817', '2026-09-10 09:57:14.039817', '江西', '吉安', '永丰', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edd31112651140daa3a7a921d3964245', '张万杰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西吕梁汾阳；山西；山西阳泉平定', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军‘扫荡’抗日根据地，多次抓捕抗日军民，烧毁村庄，抢劫财物。；率伪军配合日军‘扫荡’平定抗日根据地，杀害多名村干部和民兵。', '[]', '2026-09-10 09:57:14.020468', '2026-09-10 09:57:14.020468', '山西', '吕梁', '汾阳', NULL, NULL, NULL, NULL, '');
