INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('edded7117ea14da2a3239ed2cb3d2fe7', '张俊杰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁；河北唐山滦州；辽宁丹东凤城', '[\"同名\"]', '[]', '抗日战争时期', '', '在滦州农村进行“宣抚”，欺骗农民归顺日伪。；在滦州组织新民会，推行奴化运动，破坏抗日统一战线。；原凤城商人，投日后任伪满凤城县协和会分会长，在凤城地区组织汉奸宣传队，为日军募集物资和慰劳品。', '[]', '2026-09-10 09:57:14.041877', '2026-09-10 09:57:14.041877', '河北', '唐山', '滦州', NULL, NULL, NULL, NULL, '');
