INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee2a7fd3648544128bb105cc66190305', '张君度', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁；广西柳州融水；广西南宁；广西桂林；广西南宁武鸣；广西南宁邕宁；云南普洱西；广西桂林；广西玉林容县；广西玉林；广西桂林平乐；广西贺州；广西_贺州_钟山；广西桂林全州；广西桂林；广西贵港；云南普洱西；广西桂林临桂；广西南宁良庆；广西南宁；广西柳州柳北；广西柳州；广西梧州；广西贵港桂平；广西贺州昭平；云南普洱西；广西桂林荔浦；广西桂林阳朔；广西玉林；云南普洱西；广西玉林陆川', '[]', '[]', '抗日战争时期', '', '在陆川乡村充任伪保甲长，为日军催征粮食、指派民夫，并监视村民抗日活动。；日军侵占广西部分地区后，参与组织伪警察力量，协助日军维持占领区治安。；在日军占领梧州期间担任伪警察头目，配合日军搜捕抗日人士、镇压民众。；在日军占领梧州期间担任伪警察头目，协助日军搜捕抗日人士、镇压民众反抗。；临桂沦陷期间，出面组织地方维持会，为日军征粮、派夫、维持伪秩序。；在汪伪政权支持下，参与策划广西沦陷区的伪政权组织，试图在广西境内建立维持会体系，配合日军统治。；协助陈日葵组织伪广西省维持会，配合日军在广西占领区的统治。；阳朔沦陷期间组织伪维持会，替日军派款、派粮、拉夫，维持地方伪秩序。；1944年日军侵入荔浦后，出面组织伪荔浦县维持会，为日军征粮征夫，协助日军控制荔浦及周边乡村。；在日军支持下于广西南部地区活动，组织伪维持会，配合日军对南宁及周边地区的控制，进行反共宣传和物资掠夺。；协助日军在广西各地建立伪警察系统，参与搜捕抗日志士，贵县伪警亦受其节制。；武鸣沦陷期间组织维持会，为日军征发民夫、粮食，协助日军镇压地方抗日力量。；日军侵占贵县期间，出面组织伪贵县维持会，协助日军维持地方秩序、征派物资。；日军第一次侵占南宁后，出面组织伪南宁维持会，协助日军维持占领秩序、征发民夫与物资。；日军第二次侵占南宁期间，出面组织伪维持会，协助日军维持地方秩序、征发物资。；1944年日军第二次入侵广西占领南宁期间，出面组织伪南宁维持会，协助日军维持占领区秩序、征调物资。；日军第一次侵占南宁期间，出面组织伪南宁维持会，协助日军征粮、拉夫、维持治安，为日军侵桂提供后勤支持。；日军侵占平乐期间，出面组织伪平乐县维持会，充任会长，为日军征派粮秣、民夫，协助维持占领秩序。；1944年日军侵占贺县期间，出面组织维持会，为日军征粮、派夫、维持地方秩序。；日军侵占贺县期间，出面组织维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。；日军侵占桂林后，出面组织桂林维持会，协助日军推行殖民统治，征发民夫、物资，维持地方秩序以服务日军。；日军侵占桂林后，出面组织桂林维持会，协助日军推行殖民统治，征发民夫、物资，维持地方秩序以供日军驱使。；1944年日军侵占桂林后，出面组织桂林维持会，协助日军维持治安、征发物资、诱降地方士绅，为日军在桂林的统治服务。；日军侵占桂林期间，出面组织桂林维持会，任会长，协助日军征粮、派夫、维持治安，镇压抗日活动，为桂林地区主要附逆者之一。；南宁沦陷后出任伪警察局长，协助日军搜捕抗日分子、镇压民众反抗，维持日占区治安。；日军侵占南宁期间，出面组织伪广西省维持会，协助日军维持占领区秩序、征发物资。；日军入侵广西期间，在桂林组织伪维持会，协助日军维持占领区秩序，征发民夫、物资。；日军侵占桂林后出面组织伪维持会，协助日军维持占领秩序、征派民夫与物资。；日军第二次入侵广西期间，在玉林地区出面组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序。；1944年11月日军侵占柳州后，出面组织伪柳州维持会，协助日军征发民夫、物资，维持占领区秩序。', '[]', '2026-09-10 09:57:14.030660', '2026-09-10 09:57:14.030660', '广西', 