INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee4ccd8485a54d7d82a2d2b0a2ee5c70', '李度梅', NULL, NULL, NULL, NULL, 'exact', 'exact', '不详（潜伏成都）', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：成都潜伏敌特组织头目，架设秘密电台，专门窃取新津、双流美军机场情报，向上海汪伪、日本情报机关密报，活动长达三四年人民网文化...。。结局：1944 年军统破获电台，被捕判处死刑枪决', '[]', '2026-09-10 09:57:14.081013', '2026-09-10 09:57:14.081013', '四川', NULL, NULL, NULL, NULL, NULL, NULL, '');
