INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee655aa6b7864eab8476a004b686c303', '贾宪德', NULL, NULL, NULL, NULL, 'exact', 'exact', '民权', '[]', '[]', '抗日战争时期', '', '伪职：伪保安大队长；罪行：民权县伪保安大队长，盘踞杨城据点。1945年7月八路军发起强攻，经6小时激战全歼守敌，贾宪德被俘虏；结局：被俘虏', '[]', '2026-09-10 09:57:14.086185', '2026-09-10 09:57:14.086185', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee697c4d8e50433cb1518fcea4c70761', '陈哲', NULL, NULL, NULL, NULL, 'exact', 'exact', '海南海口；海南琼中；海南白沙', '[]', '[]', '抗日战争时期', '', '任伪海口警察头目，协助日军搜捕抗日人员、镇压市民反抗，维持殖民统治秩序。；在儋县为日军效力，组织伪政权，配合日军对儋县、白沙一带抗日力量进行清剿。', '[]', '2026-09-10 09:57:14.054413', '2026-09-10 09:57:14.054413', '海南', '琼中', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee886366f9dd47b5ba2d0671b6b8785d', '王仲箎', NULL, NULL, NULL, NULL, 'exact', 'exact', '咸宁县（今咸安区）', '[]', '[]', '抗日战争时期', '', '伪职：伪咸宁县政府秘书科长→全县伪消费合作社长；罪行：咸宁人，原为无业游民。咸宁沦陷时甘心附逆，颇得日军欢心。1940年咸宁成立伪政府时一跃任秘书科长，后任全县伪消费合作社长。与日军共同策划划分乡保、委派伪职、确立税捐、供应军需、倾销鸦片等，贱价或无偿收集地方特产换取鸦片、食盐、布匹自肥，横行霸道，稍有不满即遭杀害；结局：日本投降后逃匿上海、南京；1948年2月来汉口，在肥皂厂当账房被人告密，6月7日被咸宁县政府和汉口警方捕获', '[]', '2026-09-10 09:57:14.084714', '2026-09-10 09:57:14.084714', '上海', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee93702235b248c895efe0088f30535f', '程某', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽黄山；安徽黄山歙县；安徽黄山徽州', '[\"程雪门\"]', '[]', '抗日战争时期', '', '徽州商人，抗战期间附逆，任伪徽州商会会长，为日军筹款筹粮，协助经济掠夺。；歙县沦陷期间任维持会会长，为日军筹款筹粮。', '[]', '2026-09-10 09:57:14.011237', '2026-09-10 09:57:14.011237', '安徽', '黄山', '徽州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ee960ea9304942d2adbeaca361d554a9', '张相周', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：末代伪抚宁县县长，强化物资统制，配合日军制造长城无人区。；结局：战后汉奸罪判处长期徒刑；伪职：末代伪抚宁县县长；强化物资统制，配合日军制造长城无人区。；结局：战后汉奸罪判处长期徒刑', '[]', '2026-09-10 09:57:14.075725', '2026-09-10 09:57:14.075725', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eebbe3bed6d445ac88b62153984b9531', '赵十七', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西晋中左权', '[]', '[]', '抗日战争时期', '', '参与杀害左权县抗日村长，并放火烧毁其房屋。', '[]', '2026-09-10 09:57:14.022866', '2026-09-10 09:57:14.022866', '山西', '晋中', '左权', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eec299f658fe48a5b52385c0c176c3c1', '刘启雄', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏南京；安徽芜湖镜湖；安徽合肥肥西；安徽合肥；安徽芜湖镜湖；安徽芜湖；安徽合肥蜀山；江苏南京浦口；江苏南京浦口；江苏南京', '[]', '[]', '抗日战争时期', '', '组织伪保安队，在肥西地区多次袭击抗日游击队，抓捕并杀害抗日军民。；率伪保安队配合日军在合肥、长丰一带“扫荡”，抓捕抗日军民，抢劫物资，残害百姓。；在南京培养伪军骨干，为日军服务。；率伪宪兵协助日军镇压南京市民；强征民房，强奸妇女。；在芜湖周边强征民房，掠夺财物，强奸妇女，罪行累累。；原国民党警察，投日后任伪警察局长，在蜀山一带抓捕抗日分子，残害百姓，为日军特务机关服务。', '[]', '2026-09-10 09:57:14.006156', '2026-09-10 09:57:14.006156', '安徽', '合肥', '肥西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eed09fa31e0a40e9b717d84003c2983b', '吴维金', NULL, NULL, NULL, NULL, 'exact', 'exact', '外来潜入', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：日伪派遣潜伏特务，混入我模范营当司务长，密谋策反部队武装暴动投敌。。结局：1941 年破获，公审判处死刑', '[]', '2026-09-10 09:57:14.081277', '2026-09-10 09:57:14.081277', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eed10260c74742918b9707cf04dea8ca', '崔子和', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪饶阳县县长；五一大扫荡之后强化保甲制度。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.075927', '2026-09-10 09:57:14.075927', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eed2891113a9438d93d8ac8deb835ed9', '于经武', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东日照日照经开区；山东潍坊诸城；山东日照莒县', '[]', '[]', '抗日战争时期', '', '在胶县、诸城、日照北部一带活动，组织伪军配合日军扫荡，控制交通线。；率伪警备队配合日军扫荡莒县抗日根据地，捕杀抗日军民，抢掠物资。', '[]', '2026-09-10 09:57:14.014441', '2026-09-10 09:57:14.014441', '山东', '日照', '日照经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eef7924f2e9a49c094b182956aa33e00', '韩子犹', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸肥乡', '[]', '[]', '抗日战争时期', '', '推行奴化教育，强迫学校使用日伪教材，告发进步师生。', '[]', '2026-09-10 09:57:14.045358', '2026-09-10 09:57:14.045358', '河北', '邯郸', '肥乡', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eef857accb184457a1e2ef571af3f90d', '周文贵', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁大连金州；河北、辽宁；河北唐山唐山汉沽管理；河北唐山；辽宁阜新；辽宁大连沙河口；辽宁本溪明山；辽宁铁岭；河北秦皇岛', '[]', '[]', '抗日战争时期', '', '为日军筹措军费，强迫商户捐献，控制唐山粮食和煤炭贸易，从中牟利并资助伪军。；协助日军控制秦皇岛港口，管理港口运输，为日军运送兵员和物资，出卖港口权益。；率保安队配合日军扫荡，围捕抗日武装，参与杀害沙河口地区抗日群众，罪行累累。；九一八后组织维持会，协助日军接管金州，后任伪职。；原铁岭县教育界人士，投日后任伪教育局长，强制推行日语教育，篡改历史教材，毒化青少年思想。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.041616', '2026-09-10 09:57:14.041616', '河北', '唐山', '唐山汉沽管理', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eefbee905ab34ebaa5ec758897e2a943', '黄仲瑜', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕头；广东汕头金平；辽宁沈阳大东；广东汕头濠江；广东广州；广东潮州湘桥；广东潮州潮安；广东揭阳揭西；广东揭阳', '[]', '[]', '抗日战争时期', '', '汪伪政权委任的揭阳县伪县长，在揭阳地区推行日伪政令，配合日军清乡，镇压抗日民众。；在揭阳部分沦陷区出任伪县长，配合日军维持占领区统治。；在汕头及潮汕地区推行伪政，配合日军经济掠夺，强征粮食和劳工，镇压抗日力量。；在潮安沦陷初期参与伪维持会，协助日军安民、征粮、建立伪基层政权。；汕头沦陷初期组织维持会，为日军筹粮筹款、招募伪职人员，协助建立殖民秩序。；汪伪广州政权科室人员，协助日伪行政。；在潮阳及濠江一带推行伪政，配合日军征粮征税，组织伪保安队，压制当地抗日活动。；在汕头沦陷区推行奴化教育，篡改教材，宣传所谓‘大东亚共荣圈’。', '[]', '2026-09-10 09:57:14.027124', '2026-09-10 09:57:14.027124', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('eefef66b353d4eb093393b8b7b6253e2', '许梅村', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东揭阳榕城；广东潮州湘桥；广东潮州潮安', '[]', '[]', '抗日战争时期', '', '榕城沦陷后，出面组织伪维持会，为日军筹粮、拉夫，维持地方治安，直接服务于日军占领当局。；在潮安沦陷期间依附日伪，控制商会为日军筹款筹物，协助实行经济统制，盘剥商户与民众。；控制潮安商业，为日军筹款筹粮，强制商户缴纳“治安费”，协助日军经济统制。', '[]', '2026-09-10 09:57:14.027828', '2026-09-10 09:57:14.027828', '广东', '揭阳', '榕城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ef17df7766ac4116aa6a203b533eb73a', '巫孔玺', NULL, NULL, NULL, NULL, 'exact', 'exact', '镇江', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：原抗日干部，跟随包建华叛变；任伪清乡公署特别行动总队副队长，出卖根据地情报，杀害多名抗日干部，拆民房修碉堡、搜刮钱粮抖音百科。。结局：战后逮捕，判处死刑执行枪决', '[]', '2026-09-10 09:57:14.086730', '2026-09-10 09:57:14.086730', '江苏', '镇江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('ef19d0700b6c48da96786a74901318d6', '王宾章', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江齐齐哈尔；黑龙江齐齐哈尔龙沙；黑龙江齐齐哈尔', '[]', '[]', '抗日战争时期', '', '齐齐哈尔商界人物，投敌后任伪齐齐哈尔市商会会长，协助日军经济掠夺，为伪政权筹款筹物。；九一八事变后，在齐齐哈尔组织维持会，协助日军维持地方秩序，为日军侵占齐齐哈尔提供地方支持，直接活动于齐齐哈尔及龙沙地区。', '[]', '2026-09-10 09:57:14.066921', '2026-09-10 09:57:14.066921', '黑龙江', '齐齐哈尔', '克山', NULL, NULL, NULL, NULL, '');
