INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efc7aadc32f345a7a42994f7a24ba68e', '李国清', NULL, NULL, NULL, NULL, 'exact', 'exact', '云南昆明安宁；云南普洱西；湖南湘西古丈；云南保山；云南德宏芒市；云南德宏梁河；云南德宏梁河；云南保山腾冲；云南昆明盘龙；云南昆明；云南德宏陇川；云南保山隆阳；云南保山', '[]', '[]', '抗日战争时期', '', '日军占领腾冲后，出面组织维持会，协助日军维持地方秩序、征派粮秣，活动范围属保山地区。；保山及滇西沦陷区边缘地带，部分保甲长在日军压力下协助征粮、派款、传递情报。李国清被地方史料提及为保山一带附逆基层人员。；在云南日占区参与伪政权工作，协助日军进行经济掠夺和物资征调，活动范围涉及德宏地区。；日军侵占腾冲后，当地曾成立维持会。但腾冲属保山地区，与昆明盘龙无直接关联，且具体人员记载模糊。；日军占领腾冲后，李国清出面组织伪腾冲县维持会，协助日军征粮、派夫、维持治安，并参与建立伪政权。；在湘西伪政权中负责教育，推行奴化教育，编写亲日教材，在古丈等地学校强制使用。；在梁河地区组织伪维持会，为日军筹集物资、提供民夫，并配合日军对当地抗日武装进行清剿。；组织滇西抗日游击队，坚持敌后抗战，未附逆。', '[]', '2026-09-10 09:57:13.980110', '2026-09-10 09:57:13.980110', '云南', '保山', '腾冲', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efc96fb0fbfb41f281ffd6613c737aed', '田金锡', NULL, NULL, NULL, NULL, 'exact', 'exact', '长葛县', '[]', '[]', '抗日战争时期', '', '伪职：日伪汉奸组织头目；罪行：在陉山设有庙堂、赌场，勾结汉奸，收买流氓，为日军效力；结局：1938年11月，被中共长葛县委组织武装力量摧毁', '[]', '2026-09-10 09:57:14.085022', '2026-09-10 09:57:14.085022', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efd239b10b0b421b9afe5844ec84a543', '李海泉', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济南市中；山东济南；山东济南历城；辽宁沈阳新民；山东济南历下；山东济南历城；山东济南', '[]', '[]', '抗日战争时期', '', '在济南组织新民会，协助日军进行民众训练、情报收集与反共宣传。；在济南基层推行保甲制度，协助日军清查户口、抓捕抗日人员。；率伪保安队在济南及周边地区协助日军进攻抗日根据地。；在历城地区推行伪政，征粮征丁，配合日军扫荡。', '[]', '2026-09-10 09:57:14.015062', '2026-09-10 09:57:14.015062', '山东', '济南', '历下', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efd9b7d6d67842e6afac6301dc2ccb36', '吴廷芳', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏无锡', '[]', '[]', '抗日战争时期', '', '无锡商人，投靠日军后控制商会，为日军筹措军费，垄断粮食和棉纱贸易，从中牟利。', '[]', '2026-09-10 09:57:14.035783', '2026-09-10 09:57:14.035783', '江苏', '无锡', '梁溪', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efe6f7e4a16c42c6b21e12e79fdb914b', '荣茂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古呼伦贝尔', '[]', '[]', '抗日战争时期', '', '在呼伦贝尔布特哈旗推行日伪“保甲制度”，组织伪自卫团，协助日军围剿抗联小分队，迫害达斡尔族抗日群众。', '[]', '2026-09-10 09:57:13.988157', '2026-09-10 09:57:13.988157', '内蒙古', '呼伦贝尔', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efeaba2501174059b165168adf60fd56', '刘冠三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；河北邯郸永年；河北邯郸；山西阳泉；河北邯郸馆陶；河南郑州中牟；河北邯郸邯郸冀南；河北邯郸；河北石家庄桥西；辽宁沈阳新民；河北邯郸魏县', '[]', '[]', '抗日战争时期', '', '直属日军宪兵队指挥，专门搜捕八路军地下工作者，曾破获阳泉地下党联络站，致使多名党员牺牲。；宣传奴化思想，组织“新民会”青年团，协助日军进行文化侵略和特务活动。；为日军统制邯郸商业，强制商户缴纳‘慰劳金’，为日军收购粮食、棉花等战略物资。；日军占领永年后，率先组织维持会，为日军筹粮派款，提供情报，帮助日军建立伪政权。；组建伪剿共军，在邯郸、磁县、成安等地频繁袭击抗日武装，杀害抗日家属，烧毁村庄。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.024560', '2026-09-10 09:57:14.024560', '山西', '阳泉', '桥西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('efebff59c78d4770b1d85bc29bc02c40', '朱德明', NULL, NULL, NULL, NULL, 'exact', 'exact', '贵池观前、茅坦', '[]', '[]', '抗日战争时期', '', '伪职：伪区特务头目；罪行：铁杆特务，因索贿未遂，随意抓捕杜祖汉等 42 名无辜百姓，押至贵池三阳墩集体屠杀，制造四十二人惨案。；结局：1950 年捉拿归案公审枪决。', '[]', '2026-09-10 09:57:14.080829', '2026-09-10 09:57:14.080829', '安徽', '池州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('effbbd450cfa49519373a20afee072b1', '刘老三', NULL, NULL, NULL, NULL, 'exact', 'exact', '江宁秣陵关', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：伪警察局侦缉队长，在秣陵关盘查行人，抓捕地下交通员，严刑逼供。。结局：抗战胜利公审枪决', '[]', '2026-09-10 09:57:14.075133', '2026-09-10 09:57:14.075133', '江苏', '南京', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('effc88487d314984a9d945ff8b6e8d68', '张老八', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邯郸临漳；河北邯郸邱县；辽宁沈阳新民；河北；河北邢台；河北邢台广宗；河北石家庄高邑；河北石家庄无极；河北保定安国；河北邯郸肥乡；河北石家庄藁城；河北邯郸曲周；河北邯郸鸡泽；河北石家庄；河北石家庄赞皇', '[\"张占元\", \"张洛八\", \"张洪义\", \"张鸣岐\", \"张振海\", \"张景和\"]', '[]', '抗日战争时期', '', '率警备队驻守安国县城，多次参与‘清乡’行动，烧毁村庄，抢掠物资，并亲手杀害多名抗日积极分子。；担任新民会曲周县分会会长，推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，并收集抗日情报提供给日军。；组织伪保安队，配合日军扫荡无极抗日根据地，多次带队袭击抗日村庄，杀害抗日干部和军属，烧毁民房，抢夺财物。；投靠日军后组织土匪武装，在高邑、元氏交界地带抢劫商旅，袭击抗日游击队，为日军充当耳目，残害百姓。；原国民党地方武装人员，后投降日军，组织伪保安队，多次配合日军扫荡肥乡抗日根据地，杀害抗日干部。；赞皇县汉奸武装头目，多次带队突袭抗日县政府，烧杀抢掠。；带领便衣队突袭抗日村庄，抢劫财物，杀害抗日军属。；率自卫团配合日军袭击广宗抗日根据地，烧杀抢掠。；组织伪自卫团，为日军提供情报，参与“清乡”行动，残害抗日家属。；组织伪自卫团，为日军把守据点、修筑炮楼，协助日军封锁抗日根据地，抢劫百姓财物。；任伪新民会会长，宣传奴化思想，组织‘反共自卫团’，为日军提供情报。；组织伪自卫团，配合日军封锁抗日根据地，参与“清乡”行动，抢劫村庄，杀害无辜百姓。；为日军控制煤矿，残酷压榨矿工，向日军提供抗日分子情报，参与杀害矿工代表。', '[]', '2026-09-10 09:57:14.040825', '2026-09-10 09:57:14.040825', '河北', '保定', '安国', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f00044b9fa1a41518420a95684f1f763', '石佐民', NULL, NULL, NULL, NULL, 'exact', 'exact', '广德城关', '[]', '[]', '抗日战争时期', '', '伪职：广德维持会会长；罪行：广德沦陷头号汉奸，1943 年广德第四次沦陷牵头成立维持会；征集粮草、民夫，协助设立北门慰安所，残害妇女，带路扫荡乡村。；结局：抗战胜利公审枪决。', '[]', '2026-09-10 09:57:14.074208', '2026-09-10 09:57:14.074208', '安徽', '宣城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f001bfe35e5e424e9efb67802d1de802', '范月三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西晋中祁县', '[]', '[]', '抗日战争时期', '', '在祁县推行保甲制度，搜捕抗日军民，刑讯逼供，直接参与多起屠杀事件。', '[]', '2026-09-10 09:57:14.023003', '2026-09-10 09:57:14.023003', '山西', NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f015e8e6b64d42feacb3d9605e9912e8', '刘迈', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽合肥庐江；安徽安庆岳西；安徽安庆；安庆、怀宁、桐城沿江；安徽安庆；安徽安庆宜秀；安徽安庆怀宁', '[]', '[]', '抗日战争时期', '', '伪职：伪第一方面军独立团团长；罪行：原地方游击武装叛变投敌，在安庆组建伪军独立团；驻防安庆外围据点，多次配合日军进攻皖江抗日根据地，劫掠沿江村镇百姓。；结局：抗战胜利伪军解体，汉奸审判处决。', '[]', '2026-09-10 09:57:14.005942', '2026-09-10 09:57:14.005942', '安徽', '合肥', '庐江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f01a5994d22641dc9af8e10045b64444', '王福山', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁赤壁', '[]', '[]', '抗日战争时期', '', '蒲圻（今赤壁）地区伪军头目，率伪保安大队协助日军清乡，镇压抗日武装。', '[]', '2026-09-10 09:57:14.055268', '2026-09-10 09:57:14.055268', '湖北', '咸宁', '赤壁', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f023f39d83544ee0b62f50b5ee891e08', '刘夷', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西吉安青原；江西吉安；江西吉安（吉州长塘）；江西宜春；安徽安庆；江西南昌东湖；江西南昌；云南普洱西；江西九江浔阳；江西九江；云南普洱西；江西赣州', '[]', '[]', '抗日战争时期', '', '伪职：汪伪军官汉奸；罪行：黄埔二期毕业生，抗战期间投汪伪，担任伪军旅长等职务；抗战胜利后被捕，以“奉命投敌”为由获减刑；来源：近代黄埔投敌人物史料、赣西文史资料；备注：籍贯吉安，主要活动不在吉安本地', '[]', '2026-09-10 09:57:14.007375', '2026-09-10 09:57:14.007375', '云南', '普洱', '西', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f0292127eadf405393c803eb74906cc8', '李润芝', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治潞州；山西长治；山西；山西长治；山西长治上党；山西_长治_长治高', '[]', '[]', '抗日战争时期', '', '率伪保安队配合日军多次袭击抗日根据地，杀害抗日干部和群众，参与“治安强化”运动。；率伪保安队配合日军扫荡长治周边抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。；率伪保安队配合日军扫荡上党地区，抓捕抗日干部，抢劫百姓财物。；日军侵占潞安（今长治）后，主动投靠，任维持会长，为日军筹集物资，指认抗日分子，导致多名地下党员被捕。；率伪保安队多次袭击抗日游击队，抓捕抗日军民，烧毁村庄，为日军提供情报。', '[]', '2026-09-10 09:57:14.023989', '2026-09-10 09:57:14.023989', '山西', '长治', '上党', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f0413170dd44470e87e1b13864db4958', '张经武', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南株洲芦淞；湖南株洲；湖南邵阳武冈；湖南株洲荷塘；湖南长沙', '[]', '[]', '抗日战争时期', '', '日军占领武冈期间，出任伪警察局长，带领伪警察搜捕抗日分子，镇压民众反抗。；日军占领湘潭后，出面组织维持会，为日军筹集物资、拉夫，协助伪化统治，影响波及株洲一带。；日军第四次长沙会战期间组织伪维持会，其势力范围波及株洲北部地区，协助日军维持占领秩序。', '[]', '2026-09-10 09:57:14.058770', '2026-09-10 09:57:14.058770', '湖南', '株洲', '芦淞', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f04c077c658b4fe194d17de415493484', '赵廷璧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西_忻州_忻府；辽宁葫芦岛绥中；山西长治长治高；山西晋城高平；山西长治沁县；黑龙江黑河北安；河北秦皇岛山海关；河北秦皇岛；河北唐山；山西、河北、辽宁', '[]', '[]', '抗日战争时期', '', '作为日伪大同省与广灵之间的联络人，参与策划“铁壁合围”扫荡，并协助日伪军建立保甲制度，实行连坐。；指挥伪警察搜捕抗日情报员，严刑逼供，杀害多名八路军侦察员，并协助日军建立“爱护村”保甲制度。；率伪保安队多次袭击抗日游击队，抓捕并杀害抗日干部及家属，参与日军‘三光’政策行动，烧毁村庄多处，并强迫青壮年加入伪军。；效忠日军，组织伪警察搜捕抗日地下人员，破坏抗日组织。；日军占领忻县后率先组织维持会，为日军筹集物资，提供情报，协助建立伪政权。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.021991', '2026-09-10 09:57:14.021991', '山西', '长治', '沁县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f05916e1e73e4f63887518743843c601', '李某某', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西南宁上林；广西南宁；安徽芜湖芜湖长江大桥经开区', '[\"具体姓名待考\", \"李亚福\"]', '[]', '抗日战争时期', '', '在日军占领南宁期间，充任伪警察头目，协助日军维持治安，抓捕抗日分子。；指挥伪保安队配合日军扫荡，捕杀抗日军民，破坏地下组织。', '[]', '2026-09-10 09:57:14.010007', '2026-09-10 09:57:14.010007', '安徽', '芜湖', '芜湖长江大桥经开区', NULL, NULL, NULL, NULL, '');
