INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f1099dd35e854de0bcb24fee60a8f64c', '蔡洪田', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏镇江京口；江苏南通通州', '[]', '[]', '抗日战争时期', '', '在南通、通州发展伪党组织，策反地方人士，协助日军维持治安。；在镇江县城（今京口区）组织伪县署，为日军提供情报，强征民夫，搜刮物资，迫害抗日家属。', '[]', '2026-09-10 09:57:14.034289', '2026-09-10 09:57:14.034289', '江苏', '南通', '通州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f110341f54c14253b7c7f226d7e37d80', '李昌洙', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林_延边_龙井', '[]', '[]', '抗日战争时期', '', '组织青年团进行“思想矫正”，强迫青年参加日军“挺身队”，为日本侵略战争输送炮灰。', '[]', '2026-09-10 09:57:13.998797', '2026-09-10 09:57:13.998797', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f114c39b1a294d3594a87ccaf5161119', '吴国桢', NULL, NULL, NULL, NULL, 'exact', 'exact', '重庆丰都；浙江金华浦江；浙江金华；浙江温州洞头；浙江丽水莲都；广西桂林资源；浙江_温州_永嘉；江苏镇江扬中；浙江台州黄岩；浙江宁波象山；浙江宁波；浙江温州泰顺；重庆江津；江苏盐城射阳；江苏盐城；湖北武汉汉南；重庆璧山；江苏常州金坛；湖北_武汉_汉阳', '[]', '[]', '抗日战争时期', '', '管辖宁波、象山等地伪政权，推行“保甲连坐”，镇压抗日武装。；推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”。；主办伪报纸和广播，散布亲日言论，诋毁抗日力量，为日军侵略辩护。；控制瓯江及洞头海域水上交通，为日军护航，截击抗日武装运输船。；在盐城、射阳一带活动，协助日军推行“治安强化运动”，组织伪宣传，污蔑抗日力量。；任伪汉口特别市市长，协助日军实施经济统制，推行奴化教育，镇压抗日活动。；作为商会头目附逆，为日军统制物资、摊派捐款，协助经济掠夺。；为伪政府征收苛捐杂税，中饱私囊，协助日军掠夺当地资源。；组织商会为日军筹集军饷，强迫商户捐献，并暗中向日军出售粮食、棉花等战略物资。；设立苛捐杂税，为日伪政权筹集军费，贪污勒索百姓。；日军占领泰顺期间组织维持会，为日军提供粮秣、向导，强迫百姓悬挂日旗，并告密导致多名抗日群众被捕。；任伪商会会长，强迫商户向日军捐献物资，垄断粮食贸易，牟取暴利。；负责日伪宣传工作，散布亲日言论，诋毁抗日力量。；日军占领金华后任维持会长，组织汉奸队伍，为日军筹措军需物资，破坏抗日组织。；在重庆及周边地区参与搜捕抗日志士，破坏地下抗日组织。', '[]', '2026-09-10 09:57:14.034970', '2026-09-10 09:57:14.034970', '江苏', '常州', '金坛', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f125655d59a740fdb89d2b2820eb1934', '毕星垣', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：伪滦平县县长；制造滦平南部无人区，推行集家并村，管控古北口周边。；结局：战后逮捕判刑', '[]', '2026-09-10 09:57:14.087039', '2026-09-10 09:57:14.087039', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f126b18e10f34a4fa58d218bdf6c8de6', '张阿六', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海奉贤；上海宝山；黑龙江双鸭山宝山；上海浦东', '[\"张惠芳\"]', '[]', '抗日战争时期', '', '日军占领初期出任维持会长，协助日军建立伪政权，强迫百姓“欢迎皇军”，提供劳役。；原为地方流氓，投日后组织伪保安队，在浦东川沙、南汇一带为日军充当鹰犬，欺压百姓，袭击抗日游击队。；日军占领宝山后，出任伪保长，协助日军征粮、拉夫，迫害抗日群众，多次向日军报告抗日武装动向。', '[]', '2026-09-10 09:57:13.975686', '2026-09-10 09:57:13.975686', '上海', '奉贤', NULL, NULL, NULL, NULL, NULL, '');
