INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f35532a002a44128b437cc31e65fcd96', '郑洸薰', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东佛山；广东广州；广东广州番禺；广东佛山；江西九江', '[]', '[]', '抗日战争时期', '', '广州伪警察头目，协助日军维持殖民统治，镇压抗日活动，搜捕抗日人员。；接替陈耀任伪南海县长，推行保甲制，强征粮食，配合日军清乡，镇压西樵、九江一带抗日武装。；佛山沦陷后投敌，任伪南海县警察局局长，协助日军维持治安、搜捕抗日人士，推行保甲制度。；在广东沦陷区主持伪司法机构，以法律手段镇压抗日人士，维护日伪统治秩序。', '[]', '2026-09-10 09:57:14.026152', '2026-09-10 09:57:14.026152', '广东', '佛山', '番禺', NULL, NULL, NULL, NULL, '');
