INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3d3b85c18a548b2b2543fba9c4cc2b8', '田子明', NULL, NULL, NULL, NULL, 'exact', 'exact', '阜新太平矿', '[]', '[]', '抗日战争时期', '', '伪职：太平采炭所大把头；罪行：依附日伪，压榨矿工；日本投降后收拢 700 余人，组建冒充八路军的 “黑八路”，抢夺维持会权力，妄图投靠国民党，残害群众新华网。；结局：败露后潜逃，后抓捕归案惩处。', '[]', '2026-09-10 09:57:14.070033', '2026-09-10 09:57:14.070033', '辽宁', '阜新', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3d92933ccee49a1b078f8a507b1ccdd', '达木林', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古呼伦贝尔扎赉诺尔；内蒙古呼伦贝尔；鄂托克旗', '[]', '[]', '抗日战争时期', '', '伪职：草原告密分子；给包头日伪传递牧民动向，告发暗中支援游击队的牧户。；结局：解放后斗争镇压', '[]', '2026-09-10 09:57:13.988686', '2026-09-10 09:57:13.988686', '内蒙古', '呼伦贝尔', '扎赉诺尔', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3da83554d0045ebbfb715eba1fce745', '王廷扬', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波象山；浙江丽水云和；浙江丽水；浙江温州；浙江温州乐清；浙江湖州德清；浙江金华兰溪；浙江金华东阳；浙江宁波奉化；浙江台州仙居；浙江台州天台；浙江台州临海', '[]', '[]', '抗日战争时期', '', '德清本地人，抗战期间组织伪维持会，为日军征集粮食、劳工，协助维持德清地区伪统治。；在临海推行日伪奴化教育，强征壮丁补充伪军，破坏地下抗日组织。；在丽水沦陷期间组织伪政权，强征民夫为日军修路筑堡，强派粮食，迫害抗日家属。；任伪东阳县知事，配合日军扫荡，强征民夫修筑工事，搜刮民间物资供给日军。；日军占领仙居期间组织维持会，为日军提供物资和情报，协助建立伪政权。；在象山推行伪政权，强迫渔民为日军提供情报，参与掠夺海产资源。；任伪乐清县知事，为日军提供情报，参与组建伪保安队，镇压当地抗日游击队。；在兰溪推行日伪“治安强化”运动，组织汉奸武装，协助日军扫荡周边抗日游击区。；奉化士绅，投靠日军，参与组织维持会，为日军提供情报。', '[]', '2026-09-10 09:57:14.049333', '2026-09-10 09:57:14.049333', '浙江', '丽水', '云和', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3e491f120ad4bcfa23140483a1b6a0e', '刘化南', NULL, NULL, NULL, NULL, 'exact', 'exact', '河北唐山路南；河北保定涿州；河北保定；河北保定保定高；河北保定高阳；河北邢台南宫；辽宁沈阳新民；河北廊坊安次；河北唐山玉田；河北保定容城；河北石家庄石家庄高；河北石家庄栾城；河北保定定州；河北廊坊廊坊经开区；河北保定蠡县；河北保定；河北保定望都；河北邢台柏乡；河北邢台；河北保定莲池；河北保定；吉林经开区；河北保定定兴；河北保定竞秀；河北；河北衡水阜城；河北保定；河北保定安新；河北衡水深州；河北衡水桃城；河北衡水；河北保定雄县；河北保定保定白沟新城；河北保定；河北邢台南和；河北邢台', '[]', '[]', '抗日战争时期', '华北伪临时政府', '伪任职务：伪华北治安军集团军司令，驻防保定、石家庄。结局：1945 年被俘，公审枪决；伪职：伪石门保安军总指挥，统辖两万伪军，驻守石门城郊铁路沿线，多次配合日军扫荡周边根据地。；结局：1947 石家庄解放被俘，判处监禁；日军占领保定后率先组织维持会，为日军征粮派夫，提供情报。；在保定及白沟新城推行“保甲连坐”制度，组织汉奸特务队，多次突袭抗日村庄，逮捕并杀害抗日干部及家属。；在白沟新城（今白沟镇）一带为日军征收粮饷，出卖抗日干部，协助日军建立伪政权。；在高阳地区组织伪保安团，为日军提供情报，参与屠杀抗日群众。；在博野、蠡县一带收编散匪组建伪军，为日军提供情报，参与‘清剿’八路军游击队，残害抗日家属。……（共涉及35个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.000478', '2026-09-10 09:57:14.000478', '吉林', '经开区', '保定白沟新城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3e4d06dbbd74b7ca905378b8d6c03dc', '陈升儒', NULL, NULL, NULL, NULL, 'exact', 'exact', '泗阳众兴', '[]', '[]', '抗日战争时期', '', '伪职：伪泗阳县县长、苏淮特区教育处长；罪行：教育出身投敌，两度出任伪泗阳县长；建立伪保甲体系，奴化教育，征粮抓丁，配合日伪扫荡泗阳根据地。；结局：1945 年两淮战役被俘，1946 年两万群众公审处决。', '[]', '2026-09-10 09:57:14.075471', '2026-09-10 09:57:14.075471', '江苏', '宿迁', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f3eb2ede778c4ec09fdb88538c77b5cf', '赵震', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江杭州滨江', '[]', '[]', '抗日战争时期', '', '在伪滨江省经济部门任职，配合日本推行产业统制与资源掠夺。；投敌后任伪滨江省警务厅厅长，指挥伪警察在滨江省各地搜捕抗日人员，推行治安肃正。', '[]', '2026-09-10 09:57:14.066173', '2026-09-10 09:57:14.066173', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
