INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f4f6914d57df400b88a4f953f66e8945', '卜兆瑞', NULL, NULL, NULL, NULL, 'exact', 'exact', '萨拉齐', '[]', '[]', '抗日战争时期', '', '伪职：伪萨拉齐县县长；修筑大量炮楼，管控平绥铁路西段，扫荡大青山南麓村庄。；结局：战后汉奸罪判处徒刑；伪职：伪萨拉齐县县长；管控平绥铁路西段，修筑炮楼，频繁配合日军扫荡大青山南麓村庄。；结局：战后汉奸罪判处徒刑', '[]', '2026-09-10 09:57:14.067343', '2026-09-10 09:57:14.067343', '内蒙古', '包头', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f503cd32323b494e86cf192154027b57', '贾文郁', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江哈尔滨宾县；黑龙江大庆肇州；黑龙江牡丹江', '[]', '[]', '抗日战争时期', '', '原宾县警察，投日后任警务科长，亲自带队抓捕抗联交通员，在宾县县城设立监狱，酷刑折磨抗日志士。；原地方土匪头目，投日后组织伪保安队，在牡丹江林口、宁安等地袭击抗联小分队。；在肇州、肇东交界地区抓捕抗联交通员，破坏地下组织。', '[]', '2026-09-10 09:57:14.065876', '2026-09-10 09:57:14.065876', '黑龙江', '哈尔滨', '宾县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f5079ce249d44a3da767a06fceee007c', '黄少谷', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南衡阳衡南；湖南岳阳汨罗；湖南长沙；湖南怀化溆浦；湖南湘潭湘乡；湖南岳阳君山；湖南_岳阳_岳阳楼；湖南湘潭；河南郑州中牟', '[\"注：实为抗日人士，误收，已删除\"]', '[]', '抗日战争时期', '', '湖南长沙人，沦陷后任伪长沙维持会宣传科长，并主办伪《湖南日报》，进行亲日宣传，属于文化教育领域附逆者。；湖南沦陷区投敌分子，参与伪湖南省政权筹备与地方维持活动。；控制湘潭商业，为日军采购军需物资，从中牟利并协助经济掠夺。；在湘乡组织伪维持会，为日军提供粮食、民夫和情报，协助日军维持占领区秩序。；在伪湖南省政权中任职，参与制定伪政策，协助日军对湖南沦陷区进行政治控制与经济掠夺。；在伪湖南省政府中任职，参与推行日伪政策，为日军在湖南的统治提供行政支持。', '[]', '2026-09-10 09:57:14.057959', '2026-09-10 09:57:14.057959', '湖南', '岳阳', '君山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f51950d466b94819a89422b138781f2b', '赵志尧', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西上饶；上海浦东', '[]', '[]', '抗日战争时期', '', '江西上饶人，上饶沦陷期间任伪合作社理事长，利用合作社体系为日军征购粮食、棉花等战略物资。；在南汇地区协助日军清乡，强征粮食，迫害百姓。', '[]', '2026-09-10 09:57:13.979238', '2026-09-10 09:57:13.979238', '上海', '浦东', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f51eb757f0094a809841c16c805ece0b', '刘芳圃', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北沧州海兴；河北沧州；河北；河北沧州泊头；河北沧州；河北沧州任丘', '[]', '[]', '抗日战争时期', '', '在任丘地区为日军征粮征税，组织伪自卫团，参与围剿八路军游击队。；日军占领泊头后出任维持会长，为日军筹集粮款，出卖抗日志士，导致多人被捕牺牲。；作为日方顾问参与沧州地区伪政权管理，协助日军征粮、抓夫，破坏抗日组织。；充当日军走狗，率伪警备队多次围剿八路军游击队，抓捕抗日干部，制造多起惨案。', '[]', '2026-09-10 09:57:14.042956', '2026-09-10 09:57:14.042956', '河北', '沧州', '泊头', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f52557e736b04d90ae6ff842c28ae9af', '刘歪嘴', NULL, NULL, NULL, NULL, 'exact', 'exact', '莆田忠门、东埔', '[]', '[]', '抗日战争时期', '', '伪职：沿海潜入密探；罪行：受厦门日伪派遣，伪装商贩登陆大陆，刺探国军布防，散布失败谣言，引诱沿海土匪下海投伪。；结局：被闽中武工队锄奸处决。', '[]', '2026-09-10 09:57:14.083159', '2026-09-10 09:57:14.083159', '福建', '莆田', NULL, NULL, NULL, NULL, NULL, '');
