INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f55e12717e8341518e9edac74b828cb2', '赵海清', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北荆门掇刀；湖北荆门钟祥；湖北荆门；湖北襄阳；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '在鄂中伪政权中任职，配合日军对荆门、钟祥一带抗日武装进行扫荡，推行物资统制与奴化教育。；在襄阳城区执行伪警察职务，监视居民，抓捕抗日嫌疑人员。；任伪乡长期间强征捐税、抓丁拉夫，为日军提供情报，迫害抗日家属。', '[]', '2026-09-10 09:57:14.057024', '2026-09-10 09:57:14.057024', '湖北', '荆门', '掇刀', NULL, NULL, NULL, NULL, '');
