INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f56e001886d44d2f9ac9718b5b0dd593', '吴伯康', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东湛江', '[]', '[]', '抗日战争时期', '', '协助符永茂管理伪警察，参与搜捕抗日人士与镇压民众反抗。', '[]', '2026-09-10 09:57:14.029515', '2026-09-10 09:57:14.029515', '广东', '湛江', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f5702ac9e36147549ead5c2e7bb38ca5', '冷开泰', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川南充；四川成都', '[]', '[]', '抗日战争时期', '', '四川地方帮会势力头目，抗战期间有与日伪、伪军勾结的传闻，活动范围涉及川北南充一带，但可靠史料不足。；抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行奴化教育、征敛物资。；成都沦陷后（注：成都实际未被日军占领，此处指其附逆筹备活动）参与组织伪政权，协助日军维持地方秩序，推行奴化教育，为日军征集物资。；成都本地帮会头目，抗战期间投靠日伪，参与组织伪成都维持会并出任伪市长，协助日军维持成都地区治安、征发物资，镇压抗日活动。；抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行伪化统治。；抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行奴化教育、征发物资。；四川成都人，抗战期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、征敛物资。', '[]', '2026-09-10 09:57:14.001135', '2026-09-10 09:57:14.001135', '四川', '南充', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f574c890a52b494999044443fb21c6da', '赵廷英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西；山西运城；山西长治上党；山西长治', '[]', '[]', '抗日战争时期', '', '出任伪阳曲县知事，为日军征收粮款，组织伪自卫团，破坏抗日根据地。；投靠日军任伪长治县知事，组织维持会，协助日军清乡，残害抗日军民。；任伪长治县知事，推行保甲制度，建立伪乡村政权，协助日军抓捕抗日军民，征收苛捐杂税。', '[]', '2026-09-10 09:57:14.023851', '2026-09-10 09:57:14.023851', '山西', '运城', '稷山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f57b17ee5e974b95910d80d86d03a231', '赵质宸', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南驻马店；河南安阳北关；河南安阳；山西阳泉城区；河南鹤壁鹤壁经开区；青海黄南河南；河南安阳林州；辽宁沈阳大东；河南安阳内黄；河南安阳；河南鹤壁浚县；河南鹤壁；河南信阳光山；河南信阳；青海黄南河南；河南安阳；河南南阳邓州；河南南阳方城；河南鹤壁山城；河南安阳', '[]', '[]', '抗日战争时期', '', '河南人，投日后任伪河南省教育厅长，推行奴化教育，安阳、汤阴等地学校受其政策影响。；在伪河南省政权中负责教育事务，推行奴化教育，编写亲日教材，毒害青年学生。；在林县推行奴化教育，宣传“大东亚共荣”，配合日军进行思想控制。；在安阳为日军筹款、征粮、摊派物资，协助日伪经济统制。；协助日军控制安阳工商业，为日军筹集物资、资金，压榨商户。；控制安阳城区商业，为日军征购物资、摊派捐款，协助日伪实行经济统制。；代表伪河南省政府联络豫南各县伪政权，督导信阳、光山等地征粮征兵，配合日军对豫南抗日根据地实行封锁与扫荡。；投敌后任伪河南省教育厅厅长，在河南沦陷区包括驻马店、泌阳推行奴化教育，篡改教材，宣传“大东亚共荣”。；1945年日军侵入方城期间，组织维持会，为日军提供情报和物资，协助日军控制方城地区。；在淇县（今属鹤壁市）任伪县长，组织伪保安队，协助日军清乡，镇压当地抗日活动。；在豫北道和安阳地区充任伪职，协助日军控制地方，推行伪教育、伪宣传和物资统制。；在豫北沦陷区推行奴化教育，编写亲日教材，培训伪师资，活动涉及鹤壁、安阳等地学校。', '[]', '2026-09-10 09:57:14.046285', '2026-09-10 09:57:14.046285', '河南', '信阳', '光山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f58cb0f6be0c4366ba6394606ace7577', '王信符', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东威海；山东威海威海火炬高；辽宁沈阳大东；山东威海乳山；山东烟台牟平；山东威海荣成；辽宁沈阳大东', '[]', '[]', '抗日战争时期', '', '担任伪威海卫警察头目，协助日军搜捕抗日人员，镇压民众抗日活动。；在荣成推行奴化教育，篡改教材，宣传“大东亚共荣圈”，为日军文化侵略服务。；牟平伪政权头目，牟平与乳山相邻，其伪政权活动覆盖乳山北部地区，配合日军扫荡抗日根据地。；在威海卫组织伪新民会，宣传“大东亚共荣圈”，配合日军进行思想控制和奴化宣传，拉拢地方士绅附逆。', '[]', '2026-09-10 09:57:14.013148', '2026-09-10 09:57:14.013148', '山东', '威海', '乳山', NULL, NULL, NULL, NULL, '');
