INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f5d4d26969f44a1b84b9a220bc9e7c9a', '王占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津静海；辽宁沈阳新民；河北邯郸馆陶；河北唐山滦州；河北唐山；天津、河北', '[\"同名\"]', '[]', '抗日战争时期', '', '组织新民会宣传“中日亲善”，诱骗青年参加伪军，收集抗日情报。；在唐山市区跟踪暗杀抗日人士，破坏地下交通站。；率伪军多次扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，抢夺物资。；组建并指挥伪保安武装，多次配合日军对馆陶及周边（含邯郸东部）抗日根据地进行“清剿”，烧毁村庄、掠夺粮食，并参与杀害八路军地方干部和民兵。；在唐山侦缉地下党，破坏抗日组织。', '[]', '2026-09-10 09:57:14.003620', '2026-09-10 09:57:14.003620', '天津', '静海', '滦州', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f5e046fb829947dca3601b453bf2ba73', '达理札雅', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古阿拉善阿拉善右旗', '[]', '[]', '抗日战争时期', '', '在抗日战争期间，虽名义上隶属国民政府，但为保全自身利益，与日本特务机关及伪蒙疆政权保持暧昧关系，曾接待日本特务人员，并默许日伪势力在旗内活动，未积极抗日。', '[]', '2026-09-10 09:57:13.992574', '2026-09-10 09:57:13.992574', '内蒙古', '阿拉善', '阿拉善右旗', NULL, NULL, NULL, NULL, '');
