INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f65569c7814a47d099ad2fc03a4c32a5', '沁布多尔济', NULL, NULL, NULL, NULL, 'exact', 'exact', '喀喇沁左旗', '[]', '[]', '抗日战争时期', '', '伪职：伪喀喇沁左旗旗长（蒙奸）；罪行：喀左伪最高长官；协助日军镇压热东抗日武装，掠夺蒙汉百姓牲畜土地；八一五后勾结国民党，收拢伪旗警，继续与人民为敌。；结局：被俘后公审处决。', '[]', '2026-09-10 09:57:14.086530', '2026-09-10 09:57:14.086530', '辽宁', '赤峰', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f667679ce52f48ae97f761e9da94df0b', '李润发', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西临汾吉县；山西临汾；山西太原尖草坪；山西临汾永和；山西临汾侯马；山西太原示范；山西太原；山西；山西临汾翼城；山西临汾霍州；山西临汾；山西_晋中_榆次；山西临汾洪洞；山西运城河津；山西太原万柏林；山西临汾襄汾；山西太原杏花岭', '[]', '[]', '抗日战争时期', '', '组织伪保安队，多次配合日军扫荡临汾周边村庄，抓捕抗日干部，抢劫民财，杀害无辜百姓。；担任伪临汾保安队队长，率伪军协助日军驻守临汾，参与清乡和搜捕抗日人员，残害当地百姓。；在侯马镇为日军提供情报，组织汉奸武装，协助日军控制同蒲铁路沿线，欺压百姓。；率伪保安队多次袭击抗日游击队，杀害抗日干部，并参与日军在临汾的“清乡”行动。；率伪军配合日军在临汾、吉县一带“清乡”，烧杀抢掠，残害百姓，破坏抗日组织。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.018389', '2026-09-10 09:57:14.018389', '山西', '临汾', '侯马', NULL, NULL, NULL, NULL, '');
