INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f81f0db6b7aa4a7697544f877f5ca569', '何成濬', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北随州随县；湖北襄阳', '[]', '[]', '抗日战争时期', '', '虽未实际就任，但曾被日伪列入伪湖北省政府委员名单，与日伪有联系。；湖北随县人，原国民党元老，抗战期间投敌，任伪湖北省政府委员，协助日军推行殖民政策。', '[]', '2026-09-10 09:57:14.056462', '2026-09-10 09:57:14.056462', '湖北', '随州', '随县', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f825bfec324145a0b75f6bed5efb935e', '徐家桓', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁鞍山铁东；浙江杭州滨江；吉林；吉林；吉林丰满；吉林高；吉林永吉；吉林白城白城经开区；吉林白城', '[]', '[]', '抗日战争时期', '', '伪职：伪四平省首任省长，后伪吉林省省长；罪行：伪四平省第一任华人最高长官；推行保甲、粮食出荷，强征国兵、劳工；后调吉林，八一五组织吉林维持会，企图保留伪政权等待国民党接收。；结局：苏军逮捕，关押抚顺战犯管理所，后特赦释放。；在丰满地区设立警察分所，抓捕抗日地下工作者，参与“归屯并户”行动，迫害百姓，为日军提供情报。；伪职：伪吉林省末代省长（永吉本地人）；罪行：伪满末期吉林省华人最高长官；执行战时物资搜刮，强征劳工粮食；八一五后组建吉林治安维持会，妄图完整保留伪政权等待国民党接收。；结局：被苏军逮捕，关押抚顺战犯管理所，后特赦。', '[]', '2026-09-10 09:57:13.996509', '2026-09-10 09:57:13.996509', '吉林', '白城', '白城经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f8272a7419114d3aa68ca68cd5039cec', '李旭东', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南濮阳华龙；河南新乡长垣', '[]', '[]', '抗日战争时期', '', '抗战期间任伪长垣县县长，长垣与濮阳接壤，其伪政权为日军征集物资，协助日军封锁抗日根据地。', '[]', '2026-09-10 09:57:14.048756', '2026-09-10 09:57:14.048756', '河南', '濮阳', '华龙', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f834d36ce02746bcb859492204a3deb3', '潘芸生', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东肇庆高要；广东肇庆；广西桂林资源；广东广州荔湾；广东广州', '[]', '[]', '抗日战争时期', '', '负责伪广东粮食征购与配给，协助日军掠夺广东粮食资源。；广州沦陷初期伪维持会成员，参与附逆统治。；负责沦陷区舆论宣传，在肇庆、高要等地散发亲日宣传品，为日军侵略辩护。', '[]', '2026-09-10 09:57:14.026889', '2026-09-10 09:57:14.026889', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f834e08385f44888ada3e6041baa3f68', '王效曾', NULL, NULL, NULL, NULL, 'exact', 'exact', '山西阳泉城区；山东济宁任城；江苏南通启东；江苏_泰州_泰兴；江苏泰州靖江；江苏泰州；江苏泰州海陵；江苏泰州；安徽宿州宿州马鞍山现代产业园；安徽宿州；安徽宿州砀山；山东济宁泗水；山东济宁', '[]', '[]', '抗日战争时期', '', '参与策划“清乡”行动，带队搜查村庄，逮捕抗日群众，并参与集体屠杀事件。；效忠日寇，指挥伪警搜捕新四军情报人员，破坏地下组织，在黄桥、曲霞等地制造多起血案。；参与日军“清乡”计划，在泰州地区设立封锁线，迫害百姓。；任伪砀山县县长期间，配合日军清乡，镇压抗日活动，为日军提供情报和物资。；伪兖州道辖济宁、泗水等县，其推行伪化教育、征发劳工，配合日军军事行动。；日军占领泰州初期，组织维持会，为日军征粮派夫，提供情报，帮助建立伪政权。；宿州灵璧地区伪政权头目，推行伪化教育、征粮征丁，协助日军维持占领区统治。；为日伪征收苛捐杂税，搜刮民财，供给日军军费，协助经济掠夺。；在泰州地区充任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗，维护伪政权治安。；在泰州城区及高港沿江地区搜捕抗日分子，破坏地下交通站，参与“清乡”行动。；组织伪自卫团，配合日军守备队清乡，搜捕抗日军民，焚烧村庄。', '[]', '2026-09-10 09:57:14.008310', '2026-09-10 09:57:14.008310', '安徽', '宿州', '宿州马鞍山现代产业园', NULL, NULL, NULL, NULL, '');
