INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9282514c63343f0b4da7e8e122511fc', '梁禹廷', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江哈尔滨方正；黑龙江大兴安岭漠河', '[]', '[]', '抗日战争时期', '', '投日后任伪方正县参事官，协助日本参事官管理县政，强征民夫修筑警备道路，迫害抗联家属。；在漠河、呼玛等边境县组织警察队，协助日军封锁边境，杀害越境抗联战士。', '[]', '2026-09-10 09:57:14.065965', '2026-09-10 09:57:14.065965', '黑龙江', '哈尔滨', '方正', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f92cc669ae2a409999e14143fd52262a', '陈济桓', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西玉林容县；云南普洱西；广西桂林恭城；广西梧州万秀；广西梧州；贵州贵阳息烽；贵州贵阳；广西崇左龙州；广西玉林；广西桂林荔浦；广西桂林；贵州贵阳；广西玉林陆川；广西桂林龙胜各族；广西桂林', '[]', '[]', '抗日战争时期', '', '桂系将领，坚持抗战，未附逆。；抗战期间在贵阳出面组织伪维持会，协助日军宣传与地方控制，后因内部矛盾被日方弃用。；日军侵占玉林期间出面组织维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。；桂林沦陷后与张君度共同组织维持会，任副会长，协助日军管理桂林市区，征调民夫物资，迫害抗日群众。；日军侵占梧州期间，出面组织伪维持会，协助日军维持地方秩序、征派物资与民夫，为日军侵略服务。；日军侵占梧州期间，出面组织伪维持会，协助日军维持占领秩序、征调物资与民夫，为日军统治服务。；日军侵占梧州期间，出面组织伪梧州维持会，协助日军维持占领秩序、征派物资与民夫。；日军侵占梧州期间，出面组织伪维持会，协助日军维持占领秩序、征派物资与民夫。；梧州沦陷后出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军占领梧州提供行政支持。；桂林沦陷后投敌，以商会会长身份为日军筹款筹粮，协助日伪维持桂林商业秩序，压迫商户。；日军入侵陆川期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵扰地方提供便利。；日军入侵黔南期间，出面组织伪贵阳维持会，协助日军征发民夫、粮食，维持占领区秩序。；日军入侵贵州期间，出面组织伪贵阳维持会，协助日军维持占领区秩序、征发民夫与物资。；据部分地方文史资料提及，日军入侵广西期间曾拟拉拢其出面组织伪维持会，但其未实际就任，相关记载存疑，需谨慎使用。；龙州本地士绅，日军侵占龙州后出面组织维持会，为日军征粮征夫，协助建立伪基层政权，压迫当地民众。', '[]', '2026-09-10 09:57:14.031530', '2026-09-10 09:57:14.031530', '广西', '崇左', '龙州', NULL, NULL, NULL, NULL, '');
