INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9977c8ab310437f8fa06da6243d5b49', '陈耀堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北；河北邯郸邯山', '[]', '[]', '抗日战争时期', '', '原国民党军官，后率部投敌，改编为伪军独立旅，驻防平陆、运城一带，参与日军“扫荡”中条山抗日游击队，烧杀抢掠。；主持修建日军军用公路和碉堡，强拆民房，征用大量土地，致使邯山农民流离失所。', '[]', '2026-09-10 09:57:14.045385', '2026-09-10 09:57:14.045385', '河北', '邯郸', '邯山', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9a76c9205434439b8160673109cb419', '李台', NULL, NULL, NULL, NULL, 'exact', 'exact', '安阳', '[]', '[]', '抗日战争时期', '', '伪职：伪豫北剿共支队司令；罪行：安阳东部老牌地方武装首领，1938年主动投靠日军，驻防辛村、窦公一线；多次进攻内黄、安阳东部沙区抗日武装；胁迫周边村庄建立维持会；结局：1944年武装遭冀鲁豫军区重创，势力瓦解；抗战胜利后溃散', '[]', '2026-09-10 09:57:14.084220', '2026-09-10 09:57:14.084220', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9b2f4293e2f40fdb3d9149832981833', '邹泉荪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北；河北廊坊；北京、河北；河北廊坊；北京东城；北京昌平；北京_西城；湖南怀化怀化洪江管理', '[]', '[]', '抗日战争时期', '', '在廊坊地区推行“经济封锁”，禁止粮食、药品流入抗日根据地。；在北平主管伪实业部门，推动华北资源对日输出，参与对东城工商业的统制。；在北平主管实业，控制昌平矿产和农产品，为日军提供战略物资。；推行日伪社会政策，镇压民众反抗。；在廊坊地区推行“经济封锁”，禁止粮食、药品流入抗日根据地。', '[]', '2026-09-10 09:57:13.993021', '2026-09-10 09:57:13.993021', '河北', '怀化', '怀化洪江管理', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9b488aa9f834f94935adba7e0292df4', '张登云', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南新乡原阳；河南新乡；青海黄南河南', '[]', '[]', '抗日战争时期', '', '伪河南省政府末任主席之一，日军投降前继续维持伪政权，其辖区包括豫北新乡地区。；抗战末期任伪河南省长，继续为日军服务，直至日本投降。', '[]', '2026-09-10 09:57:14.048295', '2026-09-10 09:57:14.048295', '河南', '新乡', '原阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9c0e8707cd54b8583c955e27c3717fc', '冯焯勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西钦州浦北；广西钦州；广东肇庆；广西钦州钦南；广西梧州；广东肇庆广宁；广西北海合浦；广西北海；广东广州荔湾；山西阳泉城区；广东江门蓬江；广东江门；广东江门鹤山；河南鹤壁鹤山；广东韶关', '[]', '[]', '抗日战争时期', '', '在钦州、合浦、北海一带活动，联络各地伪维持会，为日军提供情报与物资。；汪伪政权在江门地区的基层行政头目，推行保甲、征粮、拉夫等伪政。；汪伪政权委任的鹤山县伪县长，推行日军政策，组织伪警察和保甲，配合日军扫荡鹤山及周边抗日力量。；在钦州乡村推行保甲连坐，协助日军征丁征粮，举报抗日分子。；在广州荔湾等城区担任伪保甲长，协助日伪推行保甲制度与人口控制。；出任伪广宁县县长，推行日伪政令，配合日军清乡扫荡，搜捕抗日人士。；统领伪自卫团配合日军进攻钦县抗日根据地，烧杀抢掠，强迫民众修筑工事。；担任伪梧州警察头目，协助日军维持占领区治安，镇压抗日活动。；参与组建肇庆伪维持分会，为日军筹办物资，诱降地方武装。；韶关伪商会负责人，为日军筹集物资，协助维持占领区经济秩序。', '[]', '2026-09-10 09:57:14.026966', '2026-09-10 09:57:14.026966', '广东', '广州', '荔湾', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9c4c93396a94825ab263aee69c5bad1', '林迈可', NULL, NULL, NULL, NULL, 'exact', 'exact', '安徽合肥合肥经开区；安徽_合肥_庐阳；安徽合肥蜀山；安徽合肥；安徽合肥合肥新站高；安徽合肥肥西；安徽合肥瑶海', '[\"注：非汉奸，但需澄清\"]', '[]', '抗日战争时期', '', '投靠日军，任伪合肥县知事，协助日军推行‘治安强化运动’，强征粮税，镇压抗日民众。；投靠汪伪政权，任肥西县伪县长，协助日军推行“清乡”政策，强征粮税，镇压抗日民众。；该人物为英国学者，曾支持中国抗战，非汉奸。此条目为误植，实际瑶海地区无明确汉奸记录。；投靠日军，出任伪安徽省省长，协助日军推行殖民统治，征粮征税，镇压抗日活动。；协助日军维持治安，强征粮税，镇压抗日活动；此条目为误录，林迈可是英国学者，支持中国抗战，并非汉奸。', '[]', '2026-09-10 09:57:14.005855', '2026-09-10 09:57:14.005855', '安徽', '合肥', '合肥新站高', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9c6f9bbeda44138a5f25689fc6281b2', '王槐三', NULL, NULL, NULL, NULL, 'exact', 'exact', '', '[]', '[]', '抗日战争时期', '', '伪职：凌印清伪部参谋长；罪行：辅佐凌印清招匪扩军，拉拢地方武装，替日军策反义勇军头目。；结局：同案沙岭公审枪决。', '[]', '2026-09-10 09:57:14.082108', '2026-09-10 09:57:14.082108', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9d4af35ded84f29b2dde7b5e1655807', '陈焕章', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林白山长白；广东汕头；广东潮州潮安；山西阳泉城区；广东汕头澄海；辽宁沈阳和平；广东潮州饶平；辽宁沈阳大东；广东潮州湘桥；广东潮州潮安；湖南郴州嘉禾；湖南常德安乡；湖南岳阳', '[]', '[]', '抗日战争时期', '', '汕头沦陷后组织伪维持会，后任伪汕头市长，配合日军在潮汕地区的殖民统治。；主办伪报纸，进行亲日宣传，散布‘和平救国’谬论，为日军侵略辩护。；协助日军在潮州城区建立伪秩序，诱迫居民登记良民证，为日军提供情报。；1944年日军侵占郴县后，出面组织伪维持会，为日军筹集粮秣、拉夫，协助日军维持地方秩序。；在潮安基层推行保甲制度，监视民众言行，向日军密报抗日人员及活动。；在长白地区控制边境通道，协助日军切断抗日联军与朝鲜方面的联系，镇压当地抗日活动。；岳阳沦陷后组织维持会，控制洞庭湖区域物资运输，为日军提供船只和情报，影响波及常德、安乡水路。；在潮安沦陷区推行奴化教育，编写伪教材，宣传“大东亚共荣圈”，毒害青少年。；在汕头推行奴化教育，篡改教材，向学生灌输亲日思想，为伪政权培养顺民。', '[]', '2026-09-10 09:57:13.999636', '2026-09-10 09:57:13.999636', '广东', '汕头', '澄海', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9d8031ebc8e478999f4ad5001713900', '包启文', NULL, NULL, NULL, NULL, 'exact', 'exact', '黑龙江大庆；黑龙江大庆杜尔伯特', '[]', '[]', '抗日战争时期', '', '在杜尔伯特旗（今大庆杜尔伯特蒙古族自治县）任伪旗长，协助日伪推行旗政、保甲与物资掠夺。', '[]', '2026-09-10 09:57:14.066141', '2026-09-10 09:57:14.066141', '黑龙江', '大庆', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9e698cccc40429e9e5f7d7070ffba34', '刘作人', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林长春长春经开区；吉林经开区', '[]', '[]', '抗日战争时期', '', '原长春县警察，投日后在长春县（含今经开区）镇压抗日活动，抓捕地下党。', '[]', '2026-09-10 09:57:14.000979', '2026-09-10 09:57:14.000979', '吉林', '长春', '长春经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9ec48329e74418695105f2c475e33fb', '王懋德', NULL, NULL, NULL, NULL, 'exact', 'exact', '江西赣州于都；云南普洱西', '[]', '[]', '抗日战争时期', '', '汪伪政权在江西地区安插的伪职官员，参与伪政权对江西部分沦陷区的控制与宣传，协助日军推行治安强化运动。', '[]', '2026-09-10 09:57:14.040470', '2026-09-10 09:57:14.040470', '江西', '赣州', '于都', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9ec7b05b18f4a138bb4874419a817d3', '张振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北邢台临城；贵州铜仁沿河；河北', '[]', '[]', '抗日战争时期', '', '投靠日军，任临城县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日群众。；负责漳河、滏阳河河务，为日军运输物资提供水路保障，同时向沿河村庄强征船工和物资。', '[]', '2026-09-10 09:57:14.044600', '2026-09-10 09:57:14.044600', '河北', '邢台', '临城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('f9f0e23972124ed0a413234dcf29574c', '张百奎', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州三江；广西柳州；河北巨鹿；巨鹿张庄', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：巨鹿伪警备大队长，双手沾满根据地军民鲜血，制造多起惨案。结局：1951 年公审枪决；伪职：伪巨鹿保安联队长，冀南著名铁杆汉奸；设立杀人场 “鬼王台”，残害大量干部、战士、群众，手段极其残暴；投降后混入国民党，潜逃上海。；结局：1951 年抓捕押回巨鹿，万人公审处决', '[]', '2026-09-10 09:57:14.031606', '2026-09-10 09:57:14.031606', '广西', '柳州', '三江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa0ef38965a249a1bed64741949a2c24', '孙振海', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东滨州；山东滨州无棣；山东滨州博兴；山东东营利津；山东滨州滨城；辽宁铁岭清河；山东东营广饶；山东东营；山东德州平原；山东德州；山东滨州阳信；辽宁铁岭清河；山东滨州沾化', '[]', '[]', '抗日战争时期', '', '在东营、广饶交界一带担任伪保甲长，为日军搜集抗日武装情报，带领日伪军抓捕抗日干部和群众，催缴捐税。；沾化与利津北部接壤，率伪军配合日军在利津、沾化沿海地区进行扫荡，封锁抗日根据地，残害百姓。；控制沾化经济，为日军掠夺棉花、粮食等物资，配合经济封锁，压榨当地百姓。；在博兴、蒲台一带组织伪军，配合日军对清河区抗日根据地进行扫荡，强征民夫修筑封锁沟墙，残害抗日群众。；无棣沦陷后出面维持，后任伪县长，配合日军封锁渤海抗日根据地，征粮抓丁，残害百姓。；博兴县伪警备队骨干，驻守博兴城关据点，多次随日军下乡扫荡，烧毁民房，杀害抗日干部家属。；在利津、滨县、阳信一带活动，控制黄河渡口，为日军运输物资，参与对清河区的多次扫荡。；禹城属德州地区，任伪县长期间推行日伪政令，配合日军控制铁路沿线，镇压抗日人员。', '[]', '2026-09-10 09:57:14.011972', '2026-09-10 09:57:14.011972', '山东', '东营', '利津', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa10c08983c843228616a46f809f2abb', '罗觉庵', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东汕尾陆河；广东汕尾', '[]', '[]', '抗日战争时期', '', '在伪广东省政府任职，参与推行日伪政策，其活动涉及汕尾地区，协助日军在广东沿海的统治。', '[]', '2026-09-10 09:57:14.028478', '2026-09-10 09:57:14.028478', '广东', '汕尾', '陆河', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa12777df852490e87a08e225642979c', '李仰荣', NULL, NULL, NULL, NULL, 'exact', 'exact', '睢县', '[]', '[]', '抗日战争时期', '', '伪职：伪乡长；罪行：睢县皇台东北赵楼村人，其父李国吉是地方上有名的劣绅。父子俩为敌伪效忠', '[]', '2026-09-10 09:57:14.087933', '2026-09-10 09:57:14.087933', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa1942e9e0374d2fb6a5ae50870ee2c7', '李辅唐', NULL, NULL, NULL, NULL, 'exact', 'exact', '五台', '[]', '[]', '抗日战争时期', '', '伪职：伪五台县县长；罪行：建立伪公署，修筑炮楼，管控台怀、豆村据点，配合日军扫荡五台山区。；结局：战后汉奸罪判刑', '[]', '2026-09-10 09:57:14.081285', '2026-09-10 09:57:14.081285', '山西', '忻州', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa238aafbb22401782b52de77342c4da', '杜孝先', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东滨州；山东_滨州_滨城；山东_滨州_邹平；山东潍坊安丘；山东淄博；山东滨州惠民；山东滨州；山东滨州沾化；山东_滨州_阳信；辽宁铁岭清河；山东淄博桓台；山东淄博；山东滨州惠民；山东济南济阳；山东东营', '[]', '[]', '抗日战争时期', '', '潍县沦陷后组织维持会，任伪县长，为日军征粮征夫，推行伪化教育，镇压抗日活动。；参与淄博地方维持会，为日军筹粮、派款、维持治安，协助日伪统治。；在蒲台、东营地区推行伪化教育，配合日军经济掠夺。；在滨县及沾化边境地区建立伪政权，推行保甲连坐，为日军征粮派款，镇压抗日活动。；在滨县县城及周边乡镇建立伪政权，推行保甲连坐，强征民夫修筑据点，协助日军掠夺粮食棉花。；在广饶、寿光一带依附张景月部，后任伪职，配合日军进攻清河区抗日根据地，活动区域邻近今东营市河口区。；在惠民、阳信、商河、济阳一带活动，率伪军配合日军进攻冀鲁边抗日根据地，杀害抗日干部和群众。；日军侵占滨县后出面组织维持会，后任伪县长，协助日军推行保甲连坐，强征民夫、粮食，镇压抗日活动。；日军侵占滨县后出面组织维持会，后任伪县长，推行保甲连坐，强征民夫修筑碉堡公路，为日军掠夺粮食棉花等物资。；日军侵占滨县后出面组织维持会，后任伪县长，为日军征粮派款、搜集情报，镇压抗日活动。；在长山、淄博北部地区任伪职，组织伪军配合日军扫荡，控制周村、桓台周边交通线。；惠民伪政权核心人物，管辖范围涉及滨州各县，包括博兴，推行奴化教育，强征劳工，为日军提供物资。', '[]', '2026-09-10 09:57:14.011738', '2026-09-10 09:57:14.011738', '山东', '东营', '桓台', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa262d582fc54e32b1a04ff848cb3d19', '周绍良', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江_衢州_常山', '[]', '[]', '抗日战争时期', '', '指挥伪警察搜捕抗日分子，严刑逼供，破坏地下交通站，协助日军实行“治安强化”', '[]', '2026-09-10 09:57:14.052218', '2026-09-10 09:57:14.052218', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa35642d46dc4b77930f653287bb2858', '丁今吾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北承德宽城；河北秦皇岛青龙；河北承德围场；河北；河北_承德_平泉', '[]', '[]', '抗日战争时期', '', '日军侵占围场后首任伪县长，协助日军建立保甲制度，组织清乡队搜捕抗日人员，强征粮食支援日军；在宽城、青龙一带为日军效命，组织伪警察和保甲制度，参与“治安肃正”，围剿抗日游击队，强征民夫修建警备道路和碉堡。；负责热河地区伪警察体系，抓捕抗日志士，配合日军“治安肃正”行动。；1933年日军侵占平泉后出任伪县长，推行保甲制度，强征劳工，为日军提供粮秣，镇压当地反满抗日活动。；任伪承德县县长期间，在鹰手营子矿区及周边强征劳工开采矿产，为日军提供战略资源，并配合日伪军清剿抗日游击队。', '[]', '2026-09-10 09:57:14.042813', '2026-09-10 09:57:14.042813', '河北', '承德', '围场', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa449bf50af24260a43377650926163d', '吴望伋', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江金华；河南郑州中牟；江西', '[]', '[]', '抗日战争时期', '汪伪政权', '伪任职务：汪伪国民党中央委员，赣籍在南京汪伪中央任职，鼓吹投降理论。结局：抗战胜利逮捕，判处无期徒刑', '[]', '2026-09-10 09:57:14.052406', '2026-09-10 09:57:14.052406', '浙江', '金华', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa4a48e91ef64c839c65006f65226a4b', '曾扩情', NULL, NULL, NULL, NULL, 'exact', 'exact', '四川资阳；四川成都', '[]', '[]', '抗日战争时期', '', '在成都负责伪特务活动，破坏抗日组织，暗杀抗日人士，为日军搜集情报。；原国民党四川省党部委员，1940年投敌，任伪省政府委员，参与伪政权决策，出卖抗日情报。', '[]', '2026-09-10 09:57:14.001861', '2026-09-10 09:57:14.001861', '四川', '成都', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa4d2269ff9b48d28ed04f8e1df4cbfd', '郑梅魁', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江衢州龙游；浙江衢州', '[]', '[]', '抗日战争时期', '', '隶属汪伪特工总部，在衢州、龙游一带发展情报网，破坏地下抗日组织，逮捕并酷刑审讯抗日志士。', '[]', '2026-09-10 09:57:14.052388', '2026-09-10 09:57:14.052388', '浙江', '衢州', '龙游', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa4e90ea2fba4c7780c0710b0a347a44', '王梦久', NULL, NULL, NULL, NULL, 'exact', 'exact', '鹤岗全矿区', '[]', '[]', '抗日战争时期', '', '伪职：伪鹤岗煤矿矿警队队长；罪行：执掌矿警武装，镇压矿工反抗，保护日军煤炭掠夺；光复后投奔国民党，企图阻挠矿山接收东北网。；结局：随国民党势力逃窜，后被清算。', '[]', '2026-09-10 09:57:14.087210', '2026-09-10 09:57:14.087210', '黑龙江', '鹤岗', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa51b7c6f41e41c6b90bb955f0cd515b', '崔培成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治长治高；山西晋城高平；山西长治上党；山西晋城阳城；山西晋城；山西；山西长治潞州；山西长治；山西长治；山西晋城；山西晋城高平', '[]', '[]', '抗日战争时期', '', '在高平组织“新民会”分会，煽动民众脱离抗日阵营，为日军提供劳役。；参与制造“晋城大屠杀”事件，率伪军烧毁村庄，杀害无辜百姓。；组织维持会为日军筹粮派款，强迫百姓领取“良民证”，告密导致多名抗日群众被捕牺牲。；组织伪军专门围剿八路军游击队，制造多起惨案，杀害抗日群众。；率部投敌，担任伪保安队长，多次配合日军袭击八路军游击队，在潞城、长治一带烧杀抢掠，民愤极大。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-10 09:57:14.023057', '2026-09-10 09:57:14.023057', '山西', '晋城', '阳城', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa545ec1074a4de4a8ea603acdfee50b', '阎传绂', NULL, NULL, NULL, NULL, 'exact', 'exact', '吉林_经开区；吉林松原宁江；吉林；辽宁金县；吉林；山东潍坊昌邑；辽宁_大连_金州；内蒙古赤峰林西；黑龙江_牡丹江；黑龙江哈尔滨；黑龙江鹤岗；黑龙江绥化兰西；黑龙江绥化；黑龙江齐齐哈尔；吉林四平；辽宁海城；吉林船营；吉林_长春_榆树；黑龙江大兴安岭漠河；黑龙江齐齐哈尔；吉林_长春_农安；吉林_长春_德惠；黑龙江牡丹江东宁；辽宁本溪；辽宁沈阳；吉林_永吉；吉林白城；吉林长春；吉林_高；大连（旅大派）；吉林、辽宁；吉林；黑龙江佳木斯桦南；黑龙江鹤岗南山；黑龙江佳木斯；黑龙江牡丹江阳明；黑龙江牡丹江；黑龙江哈尔滨香坊；黑龙江哈尔滨', '[]', '[]', '抗日战争时期', '汪伪政权', '伪职：伪吉林省第三任省长、伪司法部大臣；罪行：主持吉林殖民统治；后调伪满中央，执掌伪司法，大量判处 “国事犯”，迫害爱国志士。；结局：苏军逮捕，抚顺战犯管理所，后期特赦释放。；伪任职务：伪滨江省省长，后期伪满司法部大臣，驻哈尔滨。结局：苏军俘虏，抚顺关押，1964 年特赦释放；伪职：伪满司法部大臣、伪吉林省长；罪行：大连出身，长期在伪满高层，配合日本殖民统治。；结局：抚顺战犯管理所关押，后特赦。；伪职：伪满司法部大臣；罪行：伪满司法头目，大量判处 “国事犯”，迫害爱国志士。；结局：苏军逮捕，抚顺战犯管理所，后期特赦释放。；利用司法系统迫害抗日人士，判处大量爱国者死刑或长期监禁。；推行奴化教育，在丰满及吉林地区学校强制灌输“日满亲善”，禁止使用中文教材，迫害爱国教师。；伪满四平省（辖四平、梨树等县）省长，配合日军“讨伐”抗联，强征民夫修筑战备工事。；在昌邑地区推行日语教育，篡改历史教材，强迫学生效忠日本天皇。；投敌后任伪省民政厅长，推行保甲制度，协助日军清乡，迫害抗日家属。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-10 09:57:13.995940', '2026-09-10 09:57:13.995940', '吉林', '松原', '宁江', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa549663822d4803bc1aef62272138a6', '王谟', NULL, NULL, NULL, NULL, 'exact', 'exact', '陕西西安；云南普洱西', '[]', '[]', '抗日战争时期', '', '投敌后任伪山西省省长，统治山西沦陷区，与陕西隔河相望，配合日军封锁陕甘宁边区，推行奴化教育。；投敌后任伪军事委员会调查统计部次长，进行特务活动。；投靠日本，在华北伪政权中任职，参与奴化教育，对陕西有间接影响。', '[]', '2026-09-10 09:57:14.064538', '2026-09-10 09:57:14.064538', '陕西', '西安', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fa58d600aa91424296d7969672ecd400', '杨玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西长治黎城；大厂夏垫', '[]', '[]', '抗日战争时期', '', '伪职：夏垫据点伪警备中队长；为日军搜集情报，祸害周边村庄。；结局：1944 年被县大队锄奸击毙；专门刺探八路军情报，导致黎城抗日政府多次转移，多名干部被捕。', '[]', '2026-09-10 09:57:14.024476', '2026-09-10 09:57:14.024476', '山西', '长治', '黎城', NULL, NULL, NULL, NULL, '');
