INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('faafd3fe1cac445580067d4bc2f0ef06', '赵殿忱', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁；辽宁本溪；辽宁本溪溪湖；辽宁本溪', '[]', '[]', '抗日战争时期', '', '任伪本溪湖市市长期间，积极为日军提供铁矿资源，强征中国劳工，镇压本溪湖煤矿工人罢工，并协助日军围剿本溪周边抗联部队。；任伪本溪县县长期间，推行日伪“保甲连坐”制度，强征劳工用于本溪湖铁矿和煤矿，配合日军“讨伐”溪湖山区抗联部队。', '[]', '2026-09-10 09:57:14.063469', '2026-09-10 09:57:14.063469', '辽宁', '本溪', '溪湖', NULL, NULL, NULL, NULL, '');
