INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fabe93273fa1464b8fa142bb1b66ac08', '杨香坡', NULL, NULL, NULL, NULL, 'exact', 'exact', '寿光', '[]', '[]', '抗日战争时期', '', '伪职：伪寿光八区区长兼日军翻译；罪行：寿光孙家庄人，青年时闯朝鲜学会日语。七七事变后投靠日军，任侯镇据点翻译，后任南河据点八区伪区长兼翻译。向群众三日催粮五日要款，以组织“新民队”为名勒索百姓。1940年9月用旗语指挥日军绕过八路军伏击圈；结局：1940年11月被八区除奸小组用斧头劈死', '[]', '2026-09-10 09:57:14.072903', '2026-09-10 09:57:14.072903', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
