INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fb7d3c3720bf4e949fa434ad6783bd88', '淄博矿区伪警察头目', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东淄博高青；山西阳泉矿区', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '日军侵占淄博矿区后，设立伪警察机构，由汉奸担任头目，配合日军镇压矿工反抗、维持矿区治安、抓捕抗日人员，具体姓名史料记载较少。', '[]', '2026-09-10 09:57:14.016160', '2026-09-10 09:57:14.016160', '山东', '淄博', '高青', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fb8e84c16c1b4e5a97c8a11fb1050f59', '突泉县维持会会长', NULL, NULL, NULL, NULL, 'exact', 'exact', '内蒙古兴安突泉', '[\"姓名待考\"]', '[]', '抗日战争时期', '', '九一八事变后，突泉县地方士绅组织维持会，迎接日军占领，协助建立伪政权，维持地方治安并征发物资。', '[]', '2026-09-10 09:57:13.987915', '2026-09-10 09:57:13.987915', '内蒙古', '兴安', '突泉', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fb94c90ee00e4787aa111b279b88920b', '王天木', NULL, NULL, NULL, NULL, 'exact', 'exact', '上海虹口；陕西西安；安徽马鞍山雨山；安徽马鞍山；上海静安；浙江宁波余姚；浙江宁波；安徽芜湖芜湖经开区；安徽芜湖；山东青岛黄岛；江苏_南京；上海杨浦', '[]', '[]', '抗日战争时期', '', '汪伪特工系统成员，活动于南京、安徽沿江地区，马鞍山、当涂一带有其特务活动痕迹。；原军统叛徒，在虹口地区执行多次暗杀和绑架，杀害多名抗日志士。；在静安地区指挥暗杀、绑架活动，杀害多名抗日爱国人士，后投靠日军。；在宁波、余姚组织特工暗杀抗日人士，破坏地下党组织。；参与策划在杨浦地区袭击抗日组织，后投靠日军。；协助日军情报机构，镇压抗日地下活动。；投敌后任伪特工总部处长，进行特务活动。；参与策划清乡军事行动；为汪伪特务出谋划策，在芜湖策划多起暗杀事件，破坏抗日统一战线。', '[]', '2026-09-10 09:57:13.978268', '2026-09-10 09:57:13.978268', '上海', '杨浦', '芜湖经开区', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fb961dca0a8b4edca7be5e134da9f88f', '甄洛黑', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北石家庄无极', '[]', '[]', '抗日战争时期', '', '为日军催粮逼款，强抓壮丁补充伪军，多次带领日军包围村庄搜捕八路军伤员，致使伤员被俘遇害。', '[]', '2026-09-10 09:57:14.043530', '2026-09-10 09:57:14.043530', '河北', '石家庄', '无极', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fb995f6f58054e0c89badefee80d4042', '刘文藻', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖北咸宁崇阳；湖北咸宁嘉鱼；湖北宜昌；湖北武汉黄陂；湖北咸宁赤壁；湖北咸宁崇阳；湖北十堰；湖北黄冈；湖北孝感应城；湖北孝感；湖北黄石铁山；湖北黄石黄石港；湖北咸宁通城', '[]', '[]', '抗日战争时期', '', '蒲圻沦陷后任伪维持会会长，为日军筹粮、带路，并协助建立伪基层保甲。；湖北十堰人，抗战期间投敌，任伪十堰地区教育科科长，推行伪化教育，奴化民众。；崇阳沦陷后投敌，任伪维持会会长、伪县长，协助日军维持占领区秩序，镇压抗日群众。；湖北人，抗战期间投敌，任伪湖北省政府委员并兼任伪黄石港特区署长，协助日军管理黄石港及铁山矿区行政事务。；黄冈本地人，协助日军建立维持会，征发民夫，修筑据点。；嘉鱼沦陷后组织伪维持会并任伪县长，协助日军控制嘉鱼及周边地区。；黄陂沦陷后组织维持会，为日军征粮征丁，推行奴化教育。；孝感县城沦陷后组织维持会，为日军筹粮筹款，维持地方伪秩序。', '[]', '2026-09-10 09:57:14.054712', '2026-09-10 09:57:14.054712', '湖北', '十堰', '崇阳', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fba1bec77e8441d7be7a1a78e3de4392', '陈中柱', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏宿迁宿豫', '[]', '[]', '抗日战争时期', '', '主办伪报刊，进行亲日宣传，诋毁抗日力量。', '[]', '2026-09-10 09:57:14.034582', '2026-09-10 09:57:14.034582', '江苏', '宿迁', '宿豫', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fbb4513f6d76475181e90eb463556578', '刘桂棠', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东平邑；辽宁沈阳和平', '[\"刘黑七\"]', '[]', '抗日战争时期', '伪军', '伪任职务：皇协军前进总司令，反复投敌叛变，鲁南巨匪汉奸抖音百科。结局：1943 年被八路军击毙；伪职：伪和平救国军第十军第三师师长；罪行：惯匪出身反复投敌，在沂蒙山区烧杀掳掠、残害百姓；来源：项目数据库、网络史料；备注：1943年11月15日在费县柱子山一带被八路军击毙', '[]', '2026-09-10 09:57:14.017098', '2026-09-10 09:57:14.017098', '山东', '临沂', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fbb996d06c9b43b38a611f3e5f21a3e1', '马元凯', NULL, NULL, NULL, NULL, 'exact', 'exact', '河南周口；河南洛阳新安；河南洛阳；河南平顶山鲁山；河南平顶山；河南驻马店汝南；河南驻马店；河北邢台沙河', '[]', '[]', '抗日战争时期', '', '在周口任伪警察局长，为日军搜集情报、抓捕抗日嫌疑人员，控制沙河码头物资运输。；在洛阳推行奴化教育，改编教材、组织亲日宣传，影响洛阳及新安周边学校。；项城沦陷后投敌，组织维持会，后任伪县知事，在项城、周口一带为日军征粮征夫，镇压抗日群众，协助建立伪军据点。；在新蔡县城组织伪维持会，配合日军征粮征丁，其活动区域与汝南同属驻马店地区。；郏县（今属平顶山市）人，日军侵占郏县后出面组织维持会，为日军服务，协助维持占领区秩序，抗战胜利后被捕。；鲁山本地商人，投靠日军后任伪商会会长，为日军筹款筹物，控制沦陷区商业。', '[]', '2026-09-10 09:57:14.047342', '2026-09-10 09:57:14.047342', '河南', '周口', '石龙', NULL, NULL, NULL, NULL, '');
