INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fcf2910dda014ca3affea24ed6f7b13b', '赵某', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '广东江门恩平；云南曲靖；辽宁沈阳大东；安徽芜湖；山西吕梁兴县；湖南郴州永兴；湖南永州零陵；舒城城关；江苏镇江丹徒；吉林蛟河', '[\"佚名\", \"名不详，绰号“赵大马棒”\", \"名不详\", \"赵其休\", \"名不详，绰号“赵麻子”\"]', '[]', '抗日战争时期', '', '组织伪自卫团协助日军巡逻，多次袭击抗联小分队，杀害无辜百姓，霸占民财。；伪职：舒城维持会头目；罪行：本地商人，公开投敌，主持城关维持会，摊派商税物资资敌。；结局：战后肃奸判刑。', '[]', '2026-09-10 09:57:13.985935', '2026-09-10 09:57:13.985935', '云南', '曲靖', '恩平', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fcfc06b3db4a4a4bababe5aec6c5cec5', '杨法贤', NULL, NULL, NULL, NULL, 'exact', 'exact', '南乐县；河南濮阳南乐；河南濮阳濮阳经开区；河南濮阳；河南濮阳华龙；河南濮阳南乐；河南濮阳濮阳工业园；河南濮阳范县；河南濮阳；河南濮阳；南乐；安阳周边（豫北）', '[]', '[]', '抗日战争时期', '', '伪职：伪南乐警备大队长；率伪军袭扰卫河两岸游击区。；结局：南乐解放被俘处死；伪职：伪东亚同盟自治军第二旅旅长；罪行：冀鲁豫边区有名的汉奸头子之一，拥有3000多人的反动武装；伪职：南乐元村伪自卫大队长→伪东亚同盟自治军第二旅旅长；罪行：南乐县元村镇人。1905年生，早年当兵，返乡后收拢地痞流氓。日军占领南乐后抢夺民间枪支投靠日军，盘踞元村渡口。把持卫河渡口盘查勒索来往百姓，配合日军扫荡南乐西部乡村，搜捕地下交通员。后任伪东亚同盟自治军第二旅旅长，拥有3000多人武装，多次大规模扫荡我抗日根据地，残杀抗日军政干部及亲属和无辜群众；结局：1944年南乐战役中被俘，公审后枪决', '[]', '2026-09-10 09:57:14.048738', '2026-09-10 09:57:14.048738', '河南', '濮阳', '华龙', NULL, NULL, NULL, NULL, '');
