INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fd6c2016ce2c483bacbc6c1654c12660', '阿拉腾敖其尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古鄂尔多斯乌审旗', '[]', '[]', '抗日战争时期', '', '效忠伪蒙疆政权，在乌审旗建立伪警察体系，搜捕抗日地下工作者，向日军提供情报，参与镇压“独贵龙”运动余部。', '[]', '2026-09-10 09:57:13.992115', '2026-09-10 09:57:13.992115', '内蒙古', '鄂尔多斯', '乌审旗', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fd796b0418554a67a66da8c77b6ddd88', '刘存善', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西太原清徐；山西太原', '[]', '[]', '抗日战争时期', '', '太原沦陷后组织清徐维持会，为日军带路、提供情报，协助建立伪政权。', '[]', '2026-09-10 09:57:14.021497', '2026-09-10 09:57:14.021497', '山西', '太原', '清徐', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fd7a9021b68e4e42ba78edddc5c6a6ca', '陈以燊', NULL, NULL, NULL, NULL, 'exact', 'exact', '山东济宁邹城；山东济宁；山东临沂；辽宁沈阳新民；山东济宁鱼台；山东济宁；山东临沂河东；山东临沂', '[]', '[]', '抗日战争时期', '', '在滋阳（今兖州）及济宁北部推行伪政，为日军提供物资，镇压抗日活动。；在临沂推行新民会奴化教育，组织宣传亲日思想，配合日军进行文化侵略。；在济宁工商界为日军筹款筹物，协助统制经济，压迫商户。；任伪临沂道尹期间，推行日军殖民统治政策，督饬各县伪政权征粮、抓丁、修路，镇压抗日力量。', '[]', '2026-09-10 09:57:14.012406', '2026-09-10 09:57:14.012406', '山东', '临沂', '河东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fd83962ad51b47dcb215b09757849665', '刘志陆', NULL, NULL, NULL, NULL, 'exact', 'exact', '广东河源；广东河源和平；广东潮州饶平；广东梅州梅县；广东惠州惠东；广东惠州；广东梅州梅县；广东梅州；广东揭阳惠来；广东揭阳；广东梅州梅县；广东惠州惠阳；广东梅州丰顺；广东广州；广东_汕头_南澳；广东汕头金平；广东潮州湘桥；广东潮州；广东揭阳', '[]', '[]', '抗日战争时期', '', '率伪军配合日军进攻粤东，曾在大埔、梅县边境地区进行清乡，镇压抗日游击队。；刘志陆在广东东部地区组织伪军，配合日军对潮汕抗日根据地实行封锁和扫荡，其部队活动范围包括揭阳、惠来一带。；在广东东部包括揭阳一带活动，收编土匪、伪军，配合日军作战。；广东梅县籍，抗战初期投靠日军，在广东沦陷区收编土匪、组织伪军，配合日军进攻抗日游击区。；在广东收编土匪、散兵组成伪军，活动于潮梅、惠阳一带，配合日军扫荡抗日根据地，残害百姓。；协助日军统制惠州、惠东地区粮食与物资，压榨民众，供应日军军需。；广东沦陷后投敌，任伪广东治安维持会副会长，协助日军在广东各地建立伪政权，其活动范围覆盖潮汕地区。；在广州参与伪广东治安维持会，后其影响扩展至潮梅地区，协助日军推行伪化统治，与丰顺等地伪组织有联系。；在广东伪政权中任职，参与推动潮汕地区伪化。；在伪广东省政权中负责潮汕地区行政，协助日军推行殖民统治、经济掠夺。；在广东收编伪军，其势力范围涉及潮汕地区，与揭阳伪军有联系，配合日军进攻抗日根据地。；广东梅县人，早年军阀，抗战期间投敌，任伪广东治安维持会会长、伪省政府委员，在广东沦陷区推行伪化统治，对梅州籍人士有号召性负面影响。；广东梅县人，汪伪政权在广东的军事头目之一，统率伪军配合日军在潮汕地区扫荡，活动范围覆盖揭阳、揭西。；广东沦陷区伪政权头目之一，组织伪军配合日军，其势力范围涉及潮汕地区。；在河源周边和平县组织维持会，为日军提供情报与物资，协助建立伪基层政权。；在广东沦陷区组织伪军，配合日军在潮汕等地进行清乡、扫荡，镇压抗日武装。', '[]', '2026-09-10 09:57:14.027510', '2026-09-10 09:57:14.027510', '广东', '惠州', '惠东', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fda0f3b3c02845828b256fef6ee0fe4b', '刘乙青', NULL, NULL, NULL, NULL, 'exact', 'exact', '浙江宁波；山西阳泉城区', '[]', '[]', '抗日战争时期', '', '原为旧警察，投日后任伪警察局长，在鄞州城区设卡盘查，搜捕抗日地下工作者。；参与策划“清乡”行动，提供宁波地形和抗日武装情报，导致游击队多次受挫。', '[]', '2026-09-10 09:57:14.050841', '2026-09-10 09:57:14.050841', '浙江', '宁波', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fda2aa68fbc44eb590f74cb2c0a83446', '常景晟', NULL, NULL, NULL, NULL, 'exact', 'exact', '陵川梧桐村', '[]', '[]', '抗日战争时期', '', '伪职：原国民党教育局长，日伪咨议员；罪行：跟随韩维屏投敌，搜集陵高抗日政府情报，参与策划偷袭根据地。；结局：同案公审枪毙', '[]', '2026-09-10 09:57:14.076498', '2026-09-10 09:57:14.076498', '山西', '晋城', NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fda8527892d442389ed73dc4da368b65', '陈伯勋', NULL, NULL, NULL, NULL, 'exact', 'exact', '湖南岳阳岳阳屈原管理；湖南岳阳湘阴；福建泉州南安；湖南郴州安仁；湖南岳阳；湖南_郴州_资兴', '[]', '[]', '抗日战争时期', '', '湖南安仁人，1944年日军侵入安仁后，出面组织伪安仁县维持会，为日军征粮、派款、拉夫，协助日军维持安仁地区统治，是安仁县有明确记载的附逆者。；统率伪警察配合日军搜捕抗日人员，镇压民众反抗，维护日伪在岳阳的治安统治。；在湘阴一带组织伪维持会，为日军筹粮筹款、拉拢地方士绅附逆。；任伪郴县警察局长，为日军搜集情报、抓捕抗日人员，配合日军维持占领区治安。', '[]', '2026-09-10 09:57:14.057931', '2026-09-10 09:57:14.057931', '湖南', '岳阳', '岳阳屈原管理', NULL, NULL, NULL, NULL, '');
