INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fe32ac8ba07d4c0395efe5c133a2ddab', '高云昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '黑龙江哈尔滨阿城；黑龙江哈尔滨；天津、辽宁；黑龙江牡丹江绥芬河；黑龙江牡丹江；辽宁鞍山岫岩；天津津南；辽宁；辽宁_鞍山_岫岩；黑龙江哈尔滨', '[]', '[]', '抗日战争时期', '', '已列，补充其曾强迫学生唱日本国歌。；在咸水沽一带为日军征粮、抓夫，报告八路军活动，导致多名抗日群众被捕。；原岫岩教育界人士，投日后任伪教育局长，强制推行奴化教育，删除中国历史教材，灌输亲日思想。', '[]', '2026-09-10 09:57:14.003449', '2026-09-10 09:57:14.003449', '天津', '津南', '岫岩', NULL, NULL, NULL, NULL, '');
INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fe3580d9dd2c4fd7aede50499046f6c4', '罗振玉', NULL, NULL, NULL, NULL, 'exact', 'exact', '江苏淮安；吉林长春长春高；吉林长春；吉林长春农安；吉林长春；吉林四平；吉林、辽宁；云南昆明呈贡；吉林长春绿园；吉林长春；辽宁大连；辽宁_营口_大石桥；吉林长春德惠；吉林长春', '[]', '[]', '抗日战争时期', '', '原清朝遗老，积极参与伪满建国，在四平地区活动，为日本侵略提供“历史依据”和意识形态支持。；积极鼓吹复辟，协助溥仪建立伪满，在长春参与伪满政治活动。；在长春（新京）任职，积极鼓吹“王道乐土”，为日本侵略辩护。；清朝遗老，积极推动溥仪出任伪满皇帝，在长春参与伪满政治活动，为日本侵略张目。；原清朝遗老，投靠日本后任伪满监察院院长，在长春积极鼓吹“王道乐土”，协助日本进行文化奴役。……（共涉及7个地区的犯罪记录）；伪职：伪满监察院副院长，祭祀府副总裁；罪行：晚清学者，赴东北投靠溥仪，参与伪满建国，为日伪制造舆论。；结局：1940 年病死长春。', '[]', '2026-09-10 09:57:13.982702', '2026-09-10 09:57:13.982702', '云南', '昆明', '呈贡', NULL, NULL, NULL, NULL, '');
