INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fe79166f57ab440f8ee10214c6351cc4', '黄启汉', NULL, NULL, NULL, NULL, 'exact', 'exact', '广西柳州柳江；广西柳州', '[]', '[]', '抗日战争时期', '', '日军侵占柳州期间，出面组织维持会，为日军筹粮、派夫、维持地方秩序。', '[]', '2026-09-10 09:57:14.031776', '2026-09-10 09:57:14.031776', '广西', '柳州', '柳江', NULL, NULL, NULL, NULL, '');
