INSERT INTO `traitors`(`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`, `Province`, `City`, `Country`, `Town`, `Village`, `MergedIntoId`, `MergedAt`, `BirthPlace`) VALUES ('fea53df17e6241adb2e89ce39f91136f', '史聘侯', NULL, NULL, NULL, NULL, 'exact', 'exact', '舞阳县', '[]', '[]', '抗日战争时期', '', '伪职：国民党舞阳县保安大队大队长→河南皇协军独立游击大队大队长；罪行：1944年舞阳沦陷后，盘踞母猪峡一带占山为王，打家劫舍，祸害百姓。日军打通平汉线后投靠日军当汉奸，被委任为河南皇协军独立游击大队大队长，手下约800人。这支伪军同时接受日、蒋两方面给养，横行无忌；结局：1945年2月，新四军五师河南挺进兵团在母猪峡组织战斗，一举扫除史聘侯部', '[]', '2026-09-10 09:57:14.069677', '2026-09-10 09:57:14.069677', '河南', NULL, NULL, NULL, NULL, NULL, NULL, '');
